CREATE OR REPLACE FUNCTION "tongs"."_activate_owner_paid_execution_test_canary"("p_activation_id" "uuid", "p_budget_id" "uuid", "p_scope_id" "uuid", "p_actor_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  scope_auth tongs.customer_paid_execution_scope_authorizations%rowtype;
  existing tongs.owner_paid_execution_canary_activation_revisions%rowtype;
  model record;
  pricing tongs.private_pricing_revisions%rowtype;
  rollout tongs.openai_text_rollout_revisions%rowtype;
  sku text;
  prior_sub text:=current_setting('request.jwt.claim.sub',true);
begin
  if p_activation_id is null or p_budget_id is null or p_scope_id is null
     or p_actor_id is null or not tongs.is_platform_operator(p_actor_id)
     or length(btrim(coalesce(p_reason,''))) not between 8 and 500 then
    raise exception 'invalid owner Test canary activation' using errcode='22023';
  end if;
  select * into existing from tongs.owner_paid_execution_canary_activation_revisions
    where id=p_activation_id;
  if found then
    if existing.execution_scope_authorization_id<>p_scope_id
       or existing.owner_budget_id<>p_budget_id then
      raise exception 'owner Test canary activation replay conflict' using errcode='23505';
    end if;
    return to_jsonb(existing)||jsonb_build_object('replay',true);
  end if;
  select * into scope_auth from tongs.customer_paid_execution_scope_authorizations where id=p_scope_id;
  if not found or scope_auth.authorization_kind<>'owner_only'
     or scope_auth.financial_environment<>'test' or scope_auth.status<>'active'
     or scope_auth.valid_from>now() or scope_auth.valid_until<=now()
     or scope_auth.maximum_operation_count<>1 or scope_auth.maximum_concurrency<>1
     or scope_auth.maximum_wholesale_exposure_micros<=0
     or not tongs._transition_owner_authority_agrees(scope_auth.user_id) then
    raise exception 'exact active one-operation owner-only Test scope required' using errcode='42501';
  end if;
  select * into model from tongs._eligible_ai_models_for_operation(scope_auth.route_code) eligible
    where eligible.runtime_model_id=scope_auth.model_or_sku
      and eligible.cost_policy_revision_id=scope_auth.cost_policy_revision_id;
  if not found then raise exception 'exact operation/model eligibility required' using errcode='42501'; end if;
  select * into pricing from tongs.private_pricing_revisions where id=scope_auth.pricing_revision_id;
  if not found or pricing.full_cost_ceiling_micros<>scope_auth.maximum_wholesale_exposure_micros
     or pricing.customer_credit_units<>model.customer_credit_units
     or pricing.markup_basis_points<>3300 then
    raise exception 'exact pricing and common markup authority required' using errcode='42501';
  end if;
  select * into rollout from tongs._current_openai_text_rollout(scope_auth.route_code);
  if not found or rollout.mode<>'halt_new' then
    raise exception 'general route must remain halt_new for owner canary' using errcode='42501';
  end if;
  if not exists(
    select 1 from tongs.paid_execution_aggregate_assignments assignment
    join tongs.restricted_beta_policy_revisions policy on policy.id=assignment.policy_revision_id
    join tongs.restricted_beta_policy_capabilities capability on capability.policy_revision_id=policy.id
    where assignment.user_id=scope_auth.user_id and assignment.workspace_id=scope_auth.workspace_id
      and assignment.state='active' and assignment.valid_from<=now() and assignment.valid_until>now()
      and policy.environment='test' and policy.lifecycle_state='active'
      and capability.capability_code='openai.text.hammer_cleanup'
      and capability.admission_mode='covered'
      and capability.exact_model_or_sku=scope_auth.model_or_sku
      and capability.maximum_attempts=1
      and capability.per_operation_supplier_ceiling_micros>=scope_auth.maximum_wholesale_exposure_micros
  ) then raise exception 'exact active Test aggregate assignment required' using errcode='42501'; end if;
  if exists(select 1 from tongs.owner_operating_budgets where id=p_budget_id) then
    raise exception 'owner Test canary budget id already exists' using errcode='23505';
  end if;
  sku:=lower('openai-text:'||scope_auth.route_code||':'||scope_auth.model_or_sku||':'||scope_auth.cost_policy_revision_id::text);
  perform set_config('request.jwt.claim.sub',p_actor_id::text,true);
  perform tongs.create_owner_testing_budget_draft(
    p_budget_id,scope_auth.user_id,p_actor_id,'test',scope_auth.workspace_id,
    'openai',scope_auth.route_code,sku,'USD',greatest(now(),scope_auth.valid_from),
    scope_auth.valid_until,btrim(p_reason));
  perform tongs.revise_owner_operating_budget(
    p_budget_id,'active',scope_auth.maximum_wholesale_exposure_micros,btrim(p_reason));
  perform set_config('request.jwt.claim.sub',coalesce(prior_sub,''),true);
  insert into tongs.owner_paid_execution_canary_activation_revisions(
    id,execution_scope_authorization_id,owner_budget_id,revision,previous_revision_id,state,
    maximum_operation_count,valid_from,valid_until,reason,actor_id
  ) values(p_activation_id,p_scope_id,p_budget_id,1,null,'active',1,
    greatest(now(),scope_auth.valid_from),scope_auth.valid_until,btrim(p_reason),p_actor_id)
  returning * into existing;
  return to_jsonb(existing)||jsonb_build_object(
    'replay',false,'budget_amount_micros',scope_auth.maximum_wholesale_exposure_micros);
exception when others then
  perform set_config('request.jwt.claim.sub',coalesce(prior_sub,''),true);
  raise;
end $$;


ALTER FUNCTION "tongs"."_activate_owner_paid_execution_test_canary"("p_activation_id" "uuid", "p_budget_id" "uuid", "p_scope_id" "uuid", "p_actor_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "tongs"."customer_paid_execution_test_authorizations" (
    "id" "uuid" NOT NULL,
    "user_id" "uuid" NOT NULL,
    "workspace_id" "uuid" NOT NULL,
    "route_code" "text" NOT NULL,
    "provider" "text" NOT NULL,
    "model" "text" NOT NULL,
    "pricing_revision_id" "uuid" NOT NULL,
    "cost_policy_revision_id" "uuid" NOT NULL,
    "maximum_operation_count" integer NOT NULL,
    "maximum_customer_charge_micros" bigint NOT NULL,
    "authorization_expires_at" timestamp with time zone NOT NULL,
    "reason" "text" NOT NULL,
    "created_by" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "customer_paid_execution_test_auth_maximum_operation_count_check" CHECK (("maximum_operation_count" = 1)),
    CONSTRAINT "customer_paid_execution_test_authorizations_check" CHECK (("authorization_expires_at" > "created_at")),
    CONSTRAINT "customer_paid_execution_test_authorizations_model_check" CHECK (("model" = 'gpt-5.6-luna'::"text")),
    CONSTRAINT "customer_paid_execution_test_authorizations_provider_check" CHECK (("provider" = 'openai'::"text")),
    CONSTRAINT "customer_paid_execution_test_authorizations_reason_check" CHECK ((NULLIF("btrim"("reason"), ''::"text") IS NOT NULL)),
    CONSTRAINT "customer_paid_execution_test_authorizations_route_code_check" CHECK (("route_code" = 'hearth.chat_completion'::"text")),
    CONSTRAINT "customer_paid_execution_test_maximum_customer_charge_micr_check" CHECK (("maximum_customer_charge_micros" = 20000))
);

ALTER TABLE ONLY "tongs"."customer_paid_execution_test_authorizations" FORCE ROW LEVEL SECURITY;


ALTER TABLE "tongs"."customer_paid_execution_test_authorizations" OWNER TO "postgres";


COMMENT ON TABLE "tongs"."customer_paid_execution_test_authorizations" IS 'Server-owned, single-operation customer canary scopes. They never grant owner-budget access or general route activation.';



CREATE OR REPLACE FUNCTION "tongs"."_active_customer_paid_execution_test_authorization_for_quote"("p_quote_id" "uuid") RETURNS "tongs"."customer_paid_execution_test_authorizations"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
  select a.*
  from tongs.customer_paid_execution_test_authorization_quotes binding
  join tongs.customer_paid_execution_test_authorizations a
    on a.id=binding.authorization_id
  join lateral (
    select revision.status
    from tongs.customer_paid_execution_test_authorization_revisions revision
    where revision.authorization_id=a.id
    order by revision.revision desc limit 1
  ) latest on true
  where binding.quote_id=p_quote_id
    and latest.status='active'
    and clock_timestamp()<a.authorization_expires_at;
$$;


ALTER FUNCTION "tongs"."_active_customer_paid_execution_test_authorization_for_quote"("p_quote_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."_active_funding_hold"("p_source_type" "text", "p_source_id" "uuid") RETURNS TABLE("customer_charge_micros" bigint, "credit_units" bigint, "wholesale_spend_micros" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
  select
    coalesce(sum(reservation.reserved_customer_charge_micros), 0)::bigint,
    coalesce(sum(reservation.reserved_credit_units), 0)::bigint,
    coalesce(sum(reservation.reserved_wholesale_spend_micros), 0)::bigint
  from tongs.funding_reservations reservation
  where reservation.funding_source_type = p_source_type
    and reservation.funding_source_id = p_source_id
    and tongs._funding_reservation_state(reservation.id) not in ('settled', 'released');
$$;


ALTER FUNCTION "tongs"."_active_funding_hold"("p_source_type" "text", "p_source_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "tongs"."customer_paid_execution_scope_authorizations" (
    "id" "uuid" NOT NULL,
    "user_id" "uuid" NOT NULL,
    "workspace_id" "uuid" NOT NULL,
    "financial_environment" "text" NOT NULL,
    "route_code" "text" NOT NULL,
    "provider" "text" NOT NULL,
    "model_or_sku" "text" NOT NULL,
    "pricing_revision_id" "uuid" NOT NULL,
    "cost_policy_revision_id" "uuid",
    "maximum_operation_count" integer,
    "maximum_customer_charge_micros" bigint NOT NULL,
    "maximum_wholesale_exposure_micros" bigint NOT NULL,
    "maximum_concurrency" integer NOT NULL,
    "rolling_window_seconds" integer,
    "valid_from" timestamp with time zone NOT NULL,
    "valid_until" timestamp with time zone,
    "status" "text" NOT NULL,
    "reason" "text" NOT NULL,
    "created_by" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "authorization_kind" "text" DEFAULT 'certification'::"text" NOT NULL,
    CONSTRAINT "customer_paid_execution_scop_maximum_customer_charge_micr_check" CHECK (("maximum_customer_charge_micros" >= 0)),
    CONSTRAINT "customer_paid_execution_scop_maximum_wholesale_exposure_m_check" CHECK (("maximum_wholesale_exposure_micros" > 0)),
    CONSTRAINT "customer_paid_execution_scope_aut_maximum_operation_count_check" CHECK (((("authorization_kind" = ANY (ARRAY['certification'::"text", 'owner_only'::"text"])) AND ("maximum_operation_count" > 0)) OR (("authorization_kind" = 'normal_customer'::"text") AND (("maximum_operation_count" IS NULL) OR ("maximum_operation_count" > 0))))),
    CONSTRAINT "customer_paid_execution_scope_auth_rolling_window_seconds_check" CHECK (((("authorization_kind" = ANY (ARRAY['certification'::"text", 'owner_only'::"text"])) AND ("rolling_window_seconds" > 0)) OR (("authorization_kind" = 'normal_customer'::"text") AND (("rolling_window_seconds" IS NULL) OR ("rolling_window_seconds" > 0))))),
    CONSTRAINT "customer_paid_execution_scope_autho_financial_environment_check" CHECK (("financial_environment" = ANY (ARRAY['test'::"text", 'live'::"text"]))),
    CONSTRAINT "customer_paid_execution_scope_authori_maximum_concurrency_check" CHECK (("maximum_concurrency" > 0)),
    CONSTRAINT "customer_paid_execution_scope_authorizations_authorization_kind" CHECK (("authorization_kind" = ANY (ARRAY['certification'::"text", 'normal_customer'::"text", 'owner_only'::"text"]))),
    CONSTRAINT "customer_paid_execution_scope_authorizations_check" CHECK (((("authorization_kind" = ANY (ARRAY['certification'::"text", 'owner_only'::"text"])) AND ("valid_until" > "valid_from")) OR (("authorization_kind" = 'normal_customer'::"text") AND (("valid_until" IS NULL) OR ("valid_until" > "valid_from"))))),
    CONSTRAINT "customer_paid_execution_scope_authorizations_provider_check" CHECK (("provider" = ANY (ARRAY['openai'::"text", 'runway'::"text"]))),
    CONSTRAINT "customer_paid_execution_scope_authorizations_reason_check" CHECK ((NULLIF("btrim"("reason"), ''::"text") IS NOT NULL)),
    CONSTRAINT "customer_paid_execution_scope_authorizations_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'closed'::"text"])))
);

ALTER TABLE ONLY "tongs"."customer_paid_execution_scope_authorizations" FORCE ROW LEVEL SECURITY;


ALTER TABLE "tongs"."customer_paid_execution_scope_authorizations" OWNER TO "postgres";


COMMENT ON COLUMN "tongs"."customer_paid_execution_scope_authorizations"."authorization_kind" IS 'Separates immutable certification evidence from ongoing customer rollout authority.';



CREATE OR REPLACE FUNCTION "tongs"."_active_owner_only_paid_execution_scope"("p_owner_user_id" "uuid", "p_workspace_id" "uuid", "p_financial_environment" "text", "p_route_code" "text", "p_model_or_sku" "text", "p_pricing_revision_id" "uuid", "p_cost_policy_revision_id" "uuid") RETURNS "tongs"."customer_paid_execution_scope_authorizations"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_scope tongs.customer_paid_execution_scope_authorizations%rowtype;
  v_owner_count bigint;
begin
  perform tongs._require_pricing_service_role();
  select count(*) into v_owner_count
  from tongs.account_authority_classifications
  where account_class = 'owner';
  if v_owner_count <> 1 or not tongs._transition_owner_authority_agrees(p_owner_user_id) then
    return null;
  end if;
  select * into v_scope
  from tongs.customer_paid_execution_scope_authorizations
  where authorization_kind = 'owner_only'
    and user_id = p_owner_user_id
    and workspace_id = p_workspace_id
    and financial_environment = p_financial_environment
    and route_code = p_route_code
    and provider = 'openai'
    and model_or_sku = p_model_or_sku
    and pricing_revision_id = p_pricing_revision_id
    and cost_policy_revision_id = p_cost_policy_revision_id
    and status = 'active'
    and valid_from <= now() and valid_until > now()
  order by created_at desc limit 1;
  return v_scope;
end
$$;


ALTER FUNCTION "tongs"."_active_owner_only_paid_execution_scope"("p_owner_user_id" "uuid", "p_workspace_id" "uuid", "p_financial_environment" "text", "p_route_code" "text", "p_model_or_sku" "text", "p_pricing_revision_id" "uuid", "p_cost_policy_revision_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "tongs"."owner_paid_execution_canary_activation_revisions" (
    "id" "uuid" NOT NULL,
    "execution_scope_authorization_id" "uuid" NOT NULL,
    "owner_budget_id" "uuid" NOT NULL,
    "revision" integer NOT NULL,
    "previous_revision_id" "uuid",
    "state" "text" NOT NULL,
    "maximum_operation_count" integer NOT NULL,
    "valid_from" timestamp with time zone NOT NULL,
    "valid_until" timestamp with time zone NOT NULL,
    "reason" "text" NOT NULL,
    "actor_id" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "owner_paid_execution_canary_activ_maximum_operation_count_check" CHECK (("maximum_operation_count" = 1)),
    CONSTRAINT "owner_paid_execution_canary_activation_revisions_check" CHECK (("valid_until" > "valid_from")),
    CONSTRAINT "owner_paid_execution_canary_activation_revisions_check1" CHECK (((("revision" = 1) AND ("previous_revision_id" IS NULL)) OR (("revision" > 1) AND ("previous_revision_id" IS NOT NULL)))),
    CONSTRAINT "owner_paid_execution_canary_activation_revisions_reason_check" CHECK ((("length"("btrim"("reason")) >= 8) AND ("length"("btrim"("reason")) <= 500))),
    CONSTRAINT "owner_paid_execution_canary_activation_revisions_revision_check" CHECK (("revision" > 0)),
    CONSTRAINT "owner_paid_execution_canary_activation_revisions_state_check" CHECK (("state" = ANY (ARRAY['active'::"text", 'revoked'::"text"])))
);

ALTER TABLE ONLY "tongs"."owner_paid_execution_canary_activation_revisions" FORCE ROW LEVEL SECURITY;


ALTER TABLE "tongs"."owner_paid_execution_canary_activation_revisions" OWNER TO "postgres";


COMMENT ON TABLE "tongs"."owner_paid_execution_canary_activation_revisions" IS 'Private append-only authority binding one owner_only scope to one exact owner budget. It grants no route-wide or customer execution authority.';



CREATE OR REPLACE FUNCTION "tongs"."_active_owner_paid_execution_canary_for_scope"("p_scope_id" "uuid", "p_budget_id" "uuid" DEFAULT NULL::"uuid") RETURNS "tongs"."owner_paid_execution_canary_activation_revisions"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
  select activation.*
  from tongs.owner_paid_execution_canary_activation_revisions activation
  join tongs.customer_paid_execution_scope_authorizations scope_auth
    on scope_auth.id=activation.execution_scope_authorization_id
  join tongs.owner_operating_budgets budget on budget.id=activation.owner_budget_id
  join lateral (
    select revision.* from tongs.owner_operating_budget_revisions revision
    where revision.budget_id=budget.id order by revision.revision desc limit 1
  ) budget_revision on true
  where activation.execution_scope_authorization_id=p_scope_id
    and (p_budget_id is null or activation.owner_budget_id=p_budget_id)
    and activation.state='active'
    and activation.valid_from<=now() and activation.valid_until>now()
    and scope_auth.authorization_kind='owner_only'
    and scope_auth.financial_environment='test'
    and scope_auth.status='active'
    and scope_auth.valid_from<=now() and scope_auth.valid_until>now()
    and scope_auth.maximum_operation_count=1 and scope_auth.maximum_concurrency=1
    and budget.environment='test'
    and budget.owner_testing_user_id=scope_auth.user_id
    and budget.workspace_id=scope_auth.workspace_id
    and lower(budget.provider)='openai'
    and budget.route=scope_auth.route_code
    and budget_revision.status='active'
    and budget_revision.maximum_amount_micros=scope_auth.maximum_wholesale_exposure_micros
    and now()>=budget.period_start and now()<budget.period_end
  order by activation.revision desc limit 1
$$;


ALTER FUNCTION "tongs"."_active_owner_paid_execution_canary_for_scope"("p_scope_id" "uuid", "p_budget_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "tongs"."paid_execution_aggregate_assignments" (
    "id" "uuid" NOT NULL,
    "policy_revision_id" "uuid" NOT NULL,
    "user_id" "uuid" NOT NULL,
    "workspace_id" "uuid" NOT NULL,
    "state" "text" NOT NULL,
    "valid_from" timestamp with time zone NOT NULL,
    "valid_until" timestamp with time zone NOT NULL,
    "reason" "text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "paid_execution_aggregate_assignments_check" CHECK (("valid_until" > "valid_from")),
    CONSTRAINT "paid_execution_aggregate_assignments_reason_check" CHECK ((NULLIF("btrim"("reason"), ''::"text") IS NOT NULL)),
    CONSTRAINT "paid_execution_aggregate_assignments_state_check" CHECK (("state" = ANY (ARRAY['active'::"text", 'closed'::"text"])))
);

ALTER TABLE ONLY "tongs"."paid_execution_aggregate_assignments" FORCE ROW LEVEL SECURITY;


ALTER TABLE "tongs"."paid_execution_aggregate_assignments" OWNER TO "postgres";


COMMENT ON TABLE "tongs"."paid_execution_aggregate_assignments" IS 'Empty-by-default scoped activation authority. This migration does not enroll or activate anyone.';



CREATE OR REPLACE FUNCTION "tongs"."_active_paid_execution_aggregate_assignment"("p_user_id" "uuid", "p_workspace_id" "uuid", "p_environment" "text") RETURNS "tongs"."paid_execution_aggregate_assignments"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
 select assignment.* from tongs.paid_execution_aggregate_assignments assignment
 join tongs.restricted_beta_policy_revisions policy on policy.id=assignment.policy_revision_id
 where assignment.user_id=p_user_id and assignment.workspace_id=p_workspace_id and assignment.state='active'
   and assignment.valid_from<=now() and assignment.valid_until>now() and policy.environment=p_environment
 order by assignment.created_at desc limit 1
$$;


ALTER FUNCTION "tongs"."_active_paid_execution_aggregate_assignment"("p_user_id" "uuid", "p_workspace_id" "uuid", "p_environment" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "tongs"."funding_reservations" (
    "id" "uuid" NOT NULL,
    "quote_id" "uuid" NOT NULL,
    "user_id" "uuid" NOT NULL,
    "operation_id" "text" NOT NULL,
    "funding_source_type" "text" NOT NULL,
    "funding_source_id" "uuid",
    "currency" "text" NOT NULL,
    "reserved_customer_charge_micros" bigint NOT NULL,
    "reserved_credit_units" bigint NOT NULL,
    "reserved_wholesale_spend_micros" bigint NOT NULL,
    "idempotency_key" "text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "funding_environment" "text" DEFAULT 'legacy_unverified'::"text" NOT NULL,
    "rollout_authorization_id" "uuid",
    "runway_test_authorization_id" "uuid",
    CONSTRAINT "funding_reservations_check" CHECK (((("funding_source_type" = 'none'::"text") AND ("funding_source_id" IS NULL) AND ("reserved_customer_charge_micros" = 0) AND ("reserved_credit_units" = 0) AND ("reserved_wholesale_spend_micros" = 0)) OR (("funding_source_type" <> 'none'::"text") AND ("funding_source_id" IS NOT NULL)))),
    CONSTRAINT "funding_reservations_currency_check" CHECK (("currency" ~ '^[A-Z]{3}$'::"text")),
    CONSTRAINT "funding_reservations_funding_environment_check" CHECK (("funding_environment" = ANY (ARRAY['test'::"text", 'live'::"text", 'owner_internal'::"text", 'legacy_unverified'::"text"]))),
    CONSTRAINT "funding_reservations_funding_source_type_check" CHECK (("funding_source_type" = ANY (ARRAY['customer_deposit'::"text", 'paid_allowance'::"text", 'beta_grant'::"text", 'owner_budget'::"text", 'none'::"text"]))),
    CONSTRAINT "funding_reservations_idempotency_key_check" CHECK ((("length"("btrim"("idempotency_key")) >= 8) AND ("length"("btrim"("idempotency_key")) <= 300))),
    CONSTRAINT "funding_reservations_reserved_credit_units_check" CHECK (("reserved_credit_units" >= 0)),
    CONSTRAINT "funding_reservations_reserved_customer_charge_micros_check" CHECK (("reserved_customer_charge_micros" >= 0)),
    CONSTRAINT "funding_reservations_reserved_wholesale_spend_micros_check" CHECK (("reserved_wholesale_spend_micros" >= 0))
);


ALTER TABLE "tongs"."funding_reservations" OWNER TO "postgres";


COMMENT ON TABLE "tongs"."funding_reservations" IS 'Verified-funding holds. Test deposits and legacy credits are not valid source types.';



CREATE OR REPLACE FUNCTION "tongs"."_aggregate_funding_class"("p_reservation" "tongs"."funding_reservations") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
begin
  if p_reservation.funding_source_type = 'customer_deposit' then return 'verified_customer_deposit';
  elsif p_reservation.funding_source_type = 'paid_allowance' then return 'economically_backed_allowance';
  elsif p_reservation.funding_source_type = 'beta_grant' then return 'operator_provisioned_beta_credit';
  elsif p_reservation.funding_source_type = 'owner_budget' then return 'owner_operating_budget';
  elsif p_reservation.funding_source_type = 'none' then return 'byo';
  end if;
  raise exception 'unsupported aggregate funding source' using errcode = '22023';
end $$;


ALTER FUNCTION "tongs"."_aggregate_funding_class"("p_reservation" "tongs"."funding_reservations") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."_ai_credit_active_holds"("p_user_id" "uuid") RETURNS bigint
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
  select coalesce(sum(greatest(0, r.amount - coalesce(e.settled, 0) - coalesce(e.released, 0))), 0)::bigint
  from tongs.ai_credit_reservations r
  left join lateral (
    select
      coalesce(sum(ev.amount) filter (where ev.event_type = 'settled'), 0)::bigint as settled,
      coalesce(sum(ev.amount) filter (where ev.event_type = 'released'), 0)::bigint as released
    from tongs.ai_credit_reservation_events ev
    where ev.reservation_id = r.id
  ) e on true
  where r.user_id = p_user_id;
$$;


ALTER FUNCTION "tongs"."_ai_credit_active_holds"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."_ai_pricing_ceil_fraction"("p_numerator" numeric, "p_denominator" numeric) RETURNS bigint
    LANGUAGE "sql" IMMUTABLE STRICT
    SET "search_path" TO 'pg_catalog'
    AS $$
  select ceil(p_numerator / p_denominator)::bigint;
$$;


ALTER FUNCTION "tongs"."_ai_pricing_ceil_fraction"("p_numerator" numeric, "p_denominator" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."_ai_pricing_gcd"("p_left" numeric, "p_right" numeric) RETURNS numeric
    LANGUAGE "plpgsql" IMMUTABLE STRICT
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_left numeric := abs(p_left);
  v_right numeric := abs(p_right);
  v_remainder numeric;
begin
  while v_right <> 0 loop
    v_remainder := v_left % v_right;
    v_left := v_right;
    v_right := v_remainder;
  end loop;
  return greatest(v_left, 1);
end;
$$;


ALTER FUNCTION "tongs"."_ai_pricing_gcd"("p_left" numeric, "p_right" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."_assert_accounting_event_balanced"("p_event_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
begin
  if exists (
    select 1 from tongs.accounting_journal_entries entry
    where entry.event_id = p_event_id and entry.amount_micros <> 0
    group by entry.currency having sum(entry.amount_micros) <> 0
  ) then
    raise exception 'accounting event is not balanced' using errcode = '23514';
  end if;
end;
$$;


ALTER FUNCTION "tongs"."_assert_accounting_event_balanced"("p_event_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."_assert_openai_text_domain_result_context"("p_route_code" "text", "p_operation_id" "text", "p_reservation_id" "uuid", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_request_fingerprint" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
begin
  perform tongs._require_pricing_service_role();
  if not exists(select 1 from tongs.episodes e where e.id=p_workpiece_id and e.workspace_id=p_workspace_id)
    or not exists(select 1 from tongs.workspace_members m where m.workspace_id=p_workspace_id and m.user_id=p_user_id)
    or not (
      exists(select 1 from tongs.openai_text_funding_bindings b join tongs.funding_reservations r on r.id=b.reservation_id
        join tongs.customer_spending_quotes q on q.id=r.quote_id where b.route_code=p_route_code and b.operation_id=p_operation_id
          and b.reservation_id=p_reservation_id and r.user_id=p_user_id and q.workspace_id=p_workspace_id and q.request_fingerprint=p_request_fingerprint)
      or exists(select 1 from tongs.openai_text_test_certification_operations o
        join tongs.openai_text_test_certification_reservations r on r.operation_record_id=o.id
        join tongs.openai_text_test_certification_batches b on b.id=o.batch_id
        where o.route_code=p_route_code and o.operation_id=p_operation_id and r.id=p_reservation_id
          and b.user_id=p_user_id and b.workspace_id=p_workspace_id and o.request_fingerprint=p_request_fingerprint)
    ) then raise exception 'exact paid route domain-result context required' using errcode='42501'; end if;
end $$;


ALTER FUNCTION "tongs"."_assert_openai_text_domain_result_context"("p_route_code" "text", "p_operation_id" "text", "p_reservation_id" "uuid", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_request_fingerprint" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."_assert_owner_hearth_image_result_authority"("p_owner_cost_attempt_id" "uuid", "p_route_code" "text", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_operation_fingerprint" "text", "p_financial_environment" "text", "p_runtime_environment" "text", "p_provider_request_id" "text", "p_model" "text", "p_service" "text", "p_sku" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_authority jsonb;
  v_attempt tongs.owner_cost_provider_attempts%rowtype;
  v_provider_reference text;
  v_route text:=lower(btrim(coalesce(p_route_code,'')));
  v_expected_sku text;
begin
  perform tongs._require_accounting_service_role();
  v_expected_sku:=case v_route
    when 'hearth.thumbnail_base_generation'
      then 'gpt-image-2-2026-04-21:1536x1024:high:n1'
    when 'hearth.timeline_image_generation'
      then 'gpt-image-2-2026-04-21:1536x1024:high:n2'
    else null end;
  if v_expected_sku is null
     or p_model<>'gpt-image-2-2026-04-21'
     or p_service<>'image_generation'
     or p_sku<>v_expected_sku
     or nullif(btrim(coalesce(p_provider_request_id,'')),'') is null then
    raise exception 'invalid owner Hearth image provider contract' using errcode='22023';
  end if;

  v_authority:=tongs._assert_owner_hearth_result_authority(
    p_owner_cost_attempt_id,v_route,p_user_id,p_workspace_id,p_workpiece_id,
    p_operation_fingerprint,p_financial_environment,p_runtime_environment,
    p_provider_request_id,p_model
  );
  select * into v_attempt from tongs.owner_cost_provider_attempts
    where attempt_id=p_owner_cost_attempt_id;
  select event.provider_reference_id into v_provider_reference
    from tongs.owner_cost_attempt_events event
    where event.attempt_id=p_owner_cost_attempt_id
      and event.lifecycle_state in('response_captured','succeeded')
      and event.provider_reference_id is not null
    order by event.event_sequence desc limit 1;
  if v_attempt.provider<>'openai'
     or v_attempt.service<>p_service
     or v_attempt.model is distinct from p_model
     or v_attempt.sku is distinct from p_sku
     or v_provider_reference is distinct from btrim(p_provider_request_id) then
    raise exception 'owner Hearth image provider authority mismatch' using errcode='42501';
  end if;
  return v_authority||jsonb_build_object('service',p_service,'sku',p_sku);
end $$;


ALTER FUNCTION "tongs"."_assert_owner_hearth_image_result_authority"("p_owner_cost_attempt_id" "uuid", "p_route_code" "text", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_operation_fingerprint" "text", "p_financial_environment" "text", "p_runtime_environment" "text", "p_provider_request_id" "text", "p_model" "text", "p_service" "text", "p_sku" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."_assert_owner_hearth_operation_attempt"("p_owner_cost_attempt_id" "uuid", "p_route_code" "text", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_operation_fingerprint" "text", "p_financial_environment" "text", "p_runtime_environment" "text", "p_provider" "text", "p_model" "text", "p_allowed_states" "text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_attempt tongs.owner_cost_provider_attempts%rowtype;
  v_operation tongs.owner_cost_operations%rowtype;
  v_latest_state text;
begin
  perform tongs._require_accounting_service_role();
  select * into v_attempt from tongs.owner_cost_provider_attempts
    where attempt_id=p_owner_cost_attempt_id;
  if not found then raise exception 'owner-cost attempt not found' using errcode='23503'; end if;
  select * into v_operation from tongs.owner_cost_operations
    where operation_id=v_attempt.operation_id;
  if not found then raise exception 'owner-cost operation not found' using errcode='23503'; end if;
  select lifecycle_state into v_latest_state from tongs.owner_cost_attempt_events
    where attempt_id=p_owner_cost_attempt_id order by event_sequence desc limit 1;
  if v_operation.payer<>'forge'
    or v_operation.originating_tool<>'hearth'
    or v_operation.operation_type<>lower(btrim(p_route_code))
    or v_operation.workspace_id is distinct from p_workspace_id
    or v_operation.workpiece_id is distinct from p_workpiece_id
    or v_operation.request_fingerprint<>lower(btrim(p_operation_fingerprint))
    or v_operation.financial_environment<>lower(btrim(p_financial_environment))
    or v_operation.runtime_environment<>lower(btrim(p_runtime_environment))
    or v_attempt.provider<>lower(btrim(p_provider))
    or v_attempt.model is distinct from nullif(btrim(p_model),'')
    or v_latest_state is null or v_latest_state<>all(p_allowed_states)
  then raise exception 'owner Hearth operation authority mismatch' using errcode='42501'; end if;
  if not exists (
    select 1 from tongs.workspaces workspace
    where workspace.id=p_workspace_id and (
      workspace.created_by=p_user_id
      or exists(select 1 from tongs.workspace_members member
        where member.workspace_id=workspace.id and member.user_id=p_user_id)
      or tongs.is_platform_operator(p_user_id)))
  then raise exception 'owner Hearth operation user cannot access workspace' using errcode='42501'; end if;
  return jsonb_build_object(
    'operation_id',v_operation.operation_id,'operation_key',v_operation.operation_key,
    'attempt_id',v_attempt.attempt_id,'latest_state',v_latest_state,
    'financial_environment',v_operation.financial_environment,
    'runtime_environment',v_operation.runtime_environment);
end $$;


ALTER FUNCTION "tongs"."_assert_owner_hearth_operation_attempt"("p_owner_cost_attempt_id" "uuid", "p_route_code" "text", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_operation_fingerprint" "text", "p_financial_environment" "text", "p_runtime_environment" "text", "p_provider" "text", "p_model" "text", "p_allowed_states" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."_assert_owner_hearth_result_authority"("p_owner_cost_attempt_id" "uuid", "p_route_code" "text", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_request_fingerprint" "text", "p_financial_environment" "text", "p_runtime_environment" "text", "p_provider_request_id" "text", "p_model" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $_$
declare
  v_attempt tongs.owner_cost_provider_attempts%rowtype;
  v_operation tongs.owner_cost_operations%rowtype;
  v_latest_state text;
  v_provider_reference text;
  v_route text := lower(btrim(coalesce(p_route_code,'')));
  v_fingerprint text := lower(btrim(coalesce(p_request_fingerprint,'')));
  v_financial text := lower(btrim(coalesce(p_financial_environment,'')));
  v_runtime text := lower(btrim(coalesce(p_runtime_environment,'')));
begin
  perform tongs._require_accounting_service_role();
  if p_owner_cost_attempt_id is null or p_user_id is null or p_workspace_id is null
     or p_workpiece_id is null or v_fingerprint !~ '^[0-9a-f]{64}$'
     or v_financial not in ('live','test')
     or v_runtime not in ('production','preview','development') then
    raise exception 'invalid owner Hearth result authority request' using errcode='22023';
  end if;
  select * into v_attempt from tongs.owner_cost_provider_attempts
    where attempt_id=p_owner_cost_attempt_id;
  if not found then raise exception 'owner-cost attempt not found' using errcode='23503'; end if;
  select * into v_operation from tongs.owner_cost_operations
    where operation_id=v_attempt.operation_id;
  if not found then raise exception 'owner-cost operation not found' using errcode='23503'; end if;
  select e.lifecycle_state into v_latest_state
    from tongs.owner_cost_attempt_events e
    where e.attempt_id=v_attempt.attempt_id order by e.event_sequence desc limit 1;
  select e.provider_reference_id into v_provider_reference
    from tongs.owner_cost_attempt_events e
    where e.attempt_id=v_attempt.attempt_id and e.provider_reference_id is not null
    order by e.event_sequence desc limit 1;
  if v_operation.payer<>'forge' or v_operation.originating_tool<>'hearth'
     or v_operation.operation_type<>v_route
     or v_operation.financial_environment<>v_financial
     or v_operation.runtime_environment<>v_runtime
     or v_operation.workspace_id is distinct from p_workspace_id
     or v_operation.workpiece_id is distinct from p_workpiece_id
     or v_operation.request_fingerprint<>v_fingerprint
     or v_attempt.provider<>'openai'
     or v_latest_state not in ('response_captured','succeeded')
     or (nullif(btrim(coalesce(p_model,'')),'') is not null
       and v_attempt.model is distinct from nullif(btrim(p_model),''))
     or (nullif(btrim(coalesce(p_provider_request_id,'')),'') is not null
       and v_provider_reference is not null
       and v_provider_reference is distinct from nullif(btrim(p_provider_request_id),''))
  then raise exception 'owner Hearth result authority mismatch' using errcode='42501'; end if;
  if not exists (
    select 1 from tongs.workspaces w
    where w.id=p_workspace_id and (
      w.created_by=p_user_id
      or exists(select 1 from tongs.workspace_members m where m.workspace_id=w.id and m.user_id=p_user_id)
      or tongs.is_platform_operator(p_user_id)
    )
  ) then raise exception 'owner Hearth result user cannot access workspace' using errcode='42501'; end if;
  return jsonb_build_object(
    'operation_id',v_operation.operation_id,
    'operation_key',v_operation.operation_key,
    'attempt_id',v_attempt.attempt_id,
    'route_code',v_route
  );
end $_$;


ALTER FUNCTION "tongs"."_assert_owner_hearth_result_authority"("p_owner_cost_attempt_id" "uuid", "p_route_code" "text", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_request_fingerprint" "text", "p_financial_environment" "text", "p_runtime_environment" "text", "p_provider_request_id" "text", "p_model" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."_assert_owner_hearth_script_approval"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_approval_id" "uuid", "p_approval_revision" integer, "p_script_content_hash" "text") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_approval tongs.script_approval_revisions%rowtype;
  v_sequence tongs.workpiece_script_approval_sequences%rowtype;
begin
  perform tongs._require_accounting_service_role();
  select * into v_approval from tongs.script_approval_revisions
    where id=p_approval_id and workspace_id=p_workspace_id and workpiece_id=p_workpiece_id;
  select * into v_sequence from tongs.workpiece_script_approval_sequences
    where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id;
  if v_approval.id is null or v_approval.approval_revision<>p_approval_revision
     or v_approval.script_content_hash<>lower(btrim(coalesce(p_script_content_hash,'')))
     or encode(extensions.digest(convert_to(v_approval.script_text,'utf8'),'sha256'),'hex')<>v_approval.script_content_hash
     or v_sequence.current_approval_id is distinct from p_approval_id
     or v_sequence.current_revision is distinct from p_approval_revision
  then raise exception 'owner Hearth result script authority mismatch' using errcode='42501'; end if;
end $$;


ALTER FUNCTION "tongs"."_assert_owner_hearth_script_approval"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_approval_id" "uuid", "p_approval_revision" integer, "p_script_content_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."_assert_owner_unified_visual_plan_persistence_authority"("p_owner_cost_attempt_id" "uuid", "p_operation_id" "text", "p_operation_fingerprint" "text", "p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_created_by" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
begin
  perform tongs._require_accounting_service_role();

  if p_owner_cost_attempt_id is null or not exists (
    select 1
    from tongs.owner_cost_provider_attempts attempt
    join tongs.owner_cost_operations owner_operation
      on owner_operation.operation_id = attempt.operation_id
    join tongs.workspaces workspace
      on workspace.id = p_workspace_id
    where attempt.attempt_id = p_owner_cost_attempt_id
      and attempt.provider = 'openai'
      and owner_operation.payer = 'forge'
      and owner_operation.originating_tool = 'hearth'
      and owner_operation.operation_type = 'visual.unified_plan'
      and owner_operation.operation_key = p_operation_id
      and owner_operation.request_fingerprint = p_operation_fingerprint
      and owner_operation.workspace_id is not distinct from p_workspace_id
      and owner_operation.workpiece_id is not distinct from p_workpiece_id
      and (
        workspace.created_by = p_created_by
        or exists (
          select 1
          from tongs.workspace_members member
          where member.workspace_id = workspace.id
            and member.user_id = p_created_by
        )
        or tongs.is_platform_operator(p_created_by)
      )
      and exists (
        select 1
        from tongs.owner_cost_attempt_events event
        where event.attempt_id = attempt.attempt_id
          and event.lifecycle_state = 'response_captured'
          and event.provider_reference_id is not null
      )
  ) then
    raise exception 'owner Unified Visual Plan persistence authority mismatch'
      using errcode = '42501';
  end if;
end;
$$;


ALTER FUNCTION "tongs"."_assert_owner_unified_visual_plan_persistence_authority"("p_owner_cost_attempt_id" "uuid", "p_operation_id" "text", "p_operation_fingerprint" "text", "p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_created_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."_authorize_openai_text_provider_attempt_before_customer_test_sc"("p_reservation_id" "uuid", "p_attempt_key" "text", "p_attempt_number" smallint, "p_failure_exposure_micros" bigint, "p_lease_seconds" integer, "p_evidence_json" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  binding tongs.openai_text_funding_bindings%rowtype;
  reservation tongs.funding_reservations%rowtype;
  route_rollout tongs.openai_text_rollout_revisions%rowtype;
  risk_rollout tongs.openai_text_failure_loss_rollout_revisions%rowtype;
  risk_decision tongs.openai_text_failure_loss_operator_decisions%rowtype;
  policy tongs.openai_text_failure_loss_policy_revisions%rowtype;
  hold tongs.openai_text_failure_exposure_holds%rowtype;
  begin_result jsonb;
  canonical_environment text;
  committed_micros bigint:=0;
  concurrency_count integer:=0;
  effective_aggregate_limit_micros bigint;
  next_risk_revision integer;
  limit_event_id uuid;
begin
  perform tongs._require_pricing_service_role();
  if length(btrim(coalesce(p_attempt_key,'')))<8 or p_attempt_number not between 1 and 4
    or p_failure_exposure_micros<0 or p_lease_seconds not between 5 and 900
    or jsonb_typeof(coalesce(p_evidence_json,'null'::jsonb))<>'object' then
    raise exception 'invalid OpenAI text provider attempt' using errcode='22023';
  end if;
  select * into binding from tongs.openai_text_funding_bindings
  where reservation_id=p_reservation_id;
  select * into reservation from tongs.funding_reservations where id=p_reservation_id;
  if binding.operation_id is null or reservation.id is null or binding.cost_policy_revision_id is null
    or p_attempt_number>binding.maximum_attempts then
    raise exception 'funded OpenAI text binding required' using errcode='P0002';
  end if;

  select * into hold from tongs.openai_text_failure_exposure_holds
  where attempt_key=btrim(p_attempt_key);
  if found then
    return jsonb_build_object('reservation_id',p_reservation_id,'attempt_key',hold.attempt_key,
      'replay',true,'provider_execution_authorized',false,'reason','duplicate_attempt_blocked');
  end if;

  select * into route_rollout from tongs._current_openai_text_rollout(binding.route_code);
  if (route_rollout.mode<>'enforce' and not exists(select 1 from tongs._owner_paid_execution_canary_for_reservation(p_reservation_id)))
    or (route_rollout.mode='enforce' and route_rollout.cost_policy_revision_id is distinct from binding.cost_policy_revision_id) then
    raise exception 'OpenAI text route is not activated for this exact cost revision' using errcode='42501';
  end if;

  if binding.credential_funding='forge' then
    canonical_environment:=reservation.funding_environment;
    if canonical_environment not in('test','live') then
      raise exception 'canonical reservation financial environment required' using errcode='42501';
    end if;
    perform pg_advisory_xact_lock(hashtextextended(
      'openai-text-loss:'||binding.route_code||':'||canonical_environment,0));
    select * into policy
    from tongs.openai_text_failure_loss_policy_revisions policy_row
    where policy_row.route_code=binding.route_code
      and policy_row.environment=canonical_environment
      and policy_row.lifecycle_state='active'
    order by policy_row.revision desc limit 1;
    select * into risk_rollout
    from tongs._current_openai_text_failure_loss_rollout(binding.route_code,canonical_environment);
    if policy.id is null or risk_rollout.route_code is null
      or risk_rollout.loss_policy_revision_id is distinct from policy.id then
      raise exception 'environment-scoped OpenAI failure-loss policy is not active' using errcode='42501';
    end if;
    if risk_rollout.mode='halt_new' and exists(select 1 from tongs._owner_paid_execution_canary_for_reservation(p_reservation_id)) then
      effective_aggregate_limit_micros:=policy.aggregate_limit_micros;
    elsif risk_rollout.mode='halt_new' then
      return jsonb_build_object(
        'provider_execution_authorized',false,'reason','failure_loss_environment_halted',
        'denial_class','platform_risk','preprovider_release_required',true,
        'financial_environment',canonical_environment,'rollout_mode','halt_new');
    elsif risk_rollout.mode='operator_authorized' then
      select * into risk_decision
      from tongs.openai_text_failure_loss_operator_decisions decision
      where decision.id=risk_rollout.operator_decision_id;
      if canonical_environment<>'test' or risk_decision.id is null
        or risk_decision.decision_type<>'bounded_test_risk_acceptance'
        or risk_decision.loss_policy_revision_id is distinct from policy.id
        or risk_decision.resulting_rollout_revision<>risk_rollout.revision then
        raise exception 'invalid bounded Test risk authorization' using errcode='42501';
      end if;
      effective_aggregate_limit_micros:=risk_decision.effective_aggregate_limit_micros;
    elsif risk_rollout.mode='enforce' then
      effective_aggregate_limit_micros:=policy.aggregate_limit_micros;
    else
      raise exception 'unsupported failure-loss rollout mode' using errcode='42501';
    end if;

    select exposure.committed_micros,exposure.concurrency_count
    into committed_micros,concurrency_count
    from tongs._openai_text_failure_loss_exposure(
      binding.route_code,canonical_environment,policy.rolling_window_seconds) exposure;

    if p_failure_exposure_micros>policy.per_operation_limit_micros then
      insert into tongs.openai_text_failure_limit_events(
        id,route_code,reservation_id,event_key,event_type,requested_micros,committed_micros,
        configured_limit_micros,evidence_json,financial_environment,environment_authority
      ) values(
        gen_random_uuid(),binding.route_code,p_reservation_id,btrim(p_attempt_key)||':operation-limit',
        'operation_limit_blocked',p_failure_exposure_micros,committed_micros,
        policy.per_operation_limit_micros,p_evidence_json,canonical_environment,'canonical_reservation');
      return jsonb_build_object(
        'provider_execution_authorized',false,'reason','operation_failure_limit',
        'denial_class','platform_risk','preprovider_release_required',true,
        'financial_environment',canonical_environment,'rollout_mode',risk_rollout.mode);
    elsif concurrency_count>=policy.maximum_concurrency then
      insert into tongs.openai_text_failure_limit_events(
        id,route_code,reservation_id,event_key,event_type,requested_micros,committed_micros,
        configured_limit_micros,evidence_json,financial_environment,environment_authority
      ) values(
        gen_random_uuid(),binding.route_code,p_reservation_id,btrim(p_attempt_key)||':concurrency-limit',
        'concurrency_blocked',p_failure_exposure_micros,committed_micros,
        effective_aggregate_limit_micros,p_evidence_json,canonical_environment,'canonical_reservation');
      return jsonb_build_object(
        'provider_execution_authorized',false,'reason','failure_loss_concurrency_limit',
        'denial_class','platform_risk','preprovider_release_required',true,
        'financial_environment',canonical_environment,'rollout_mode',risk_rollout.mode);
    elsif committed_micros+p_failure_exposure_micros>effective_aggregate_limit_micros then
      insert into tongs.openai_text_failure_limit_events(
        id,route_code,reservation_id,event_key,event_type,requested_micros,committed_micros,
        configured_limit_micros,evidence_json,financial_environment,environment_authority
      ) values(
        gen_random_uuid(),binding.route_code,p_reservation_id,btrim(p_attempt_key)||':aggregate-limit',
        'aggregate_limit_blocked',p_failure_exposure_micros,committed_micros,
        effective_aggregate_limit_micros,p_evidence_json||jsonb_build_object(
          'base_aggregate_limit_micros',policy.aggregate_limit_micros,
          'operator_decision_id',risk_rollout.operator_decision_id
        ),canonical_environment,'canonical_reservation')
      returning id into limit_event_id;
      select coalesce(max(revision),0)+1 into next_risk_revision
      from tongs.openai_text_failure_loss_rollout_revisions risk_revision
      where risk_revision.route_code=binding.route_code
        and risk_revision.financial_environment=canonical_environment;
      insert into tongs.openai_text_failure_loss_rollout_revisions(
        route_code,financial_environment,revision,mode,loss_policy_revision_id,
        source_limit_event_id,reason
      ) values(
        binding.route_code,canonical_environment,next_risk_revision,'halt_new',policy.id,
        limit_event_id,'Automatic halt: effective aggregate Forge failure-loss ceiling reached.');
      return jsonb_build_object(
        'provider_execution_authorized',false,'reason','aggregate_failure_limit',
        'denial_class','platform_risk','preprovider_release_required',true,
        'financial_environment',canonical_environment,'rollout_mode','halt_new');
    end if;

    if risk_rollout.mode='operator_authorized'
      and committed_micros+p_failure_exposure_micros>policy.aggregate_limit_micros then
      insert into tongs.openai_text_failure_limit_events(
        id,route_code,reservation_id,event_key,event_type,requested_micros,committed_micros,
        configured_limit_micros,evidence_json,financial_environment,environment_authority
      ) values(
        gen_random_uuid(),binding.route_code,p_reservation_id,
        btrim(p_attempt_key)||':aggregate-risk-accepted','aggregate_risk_accepted',
        p_failure_exposure_micros,committed_micros,effective_aggregate_limit_micros,
        p_evidence_json||jsonb_build_object(
          'base_aggregate_limit_micros',policy.aggregate_limit_micros,
          'operator_decision_id',risk_rollout.operator_decision_id,
          'accepted_total_exposure_micros',committed_micros+p_failure_exposure_micros
        ),canonical_environment,'canonical_reservation');
    end if;
  elsif p_failure_exposure_micros<>0 then
    raise exception 'BYO OpenAI attempt cannot reserve Forge provider failure exposure' using errcode='22023';
  end if;

  insert into tongs.openai_text_failure_exposure_holds(
    id,reservation_id,route_code,attempt_key,attempt_number,loss_policy_revision_id,
    authorized_exposure_micros,lease_expires_at,financial_environment,environment_authority
  ) values(
    gen_random_uuid(),p_reservation_id,binding.route_code,btrim(p_attempt_key),p_attempt_number,
    policy.id,p_failure_exposure_micros,now()+make_interval(secs=>p_lease_seconds),
    canonical_environment,case when canonical_environment is null then null else 'canonical_reservation' end
  ) returning * into hold;
  if reservation.funding_source_type='owner_budget' then
    begin_result:=tongs.begin_owner_provider_attempt(
      p_reservation_id,btrim(p_attempt_key),p_lease_seconds,p_evidence_json);
  else
    begin_result:=tongs.begin_provider_attempt(
      p_reservation_id,btrim(p_attempt_key),p_lease_seconds,p_evidence_json);
  end if;
  if coalesce((begin_result->>'provider_execution_authorized')::boolean,false) is not true then
    raise exception 'shared spending gate denied OpenAI execution' using errcode='42501';
  end if;
  return begin_result||jsonb_build_object(
    'failure_exposure_hold_id',hold.id,'failure_exposure_micros',p_failure_exposure_micros,
    'financial_environment',canonical_environment,
    'failure_loss_rollout_mode',case when binding.credential_funding='forge' then risk_rollout.mode else null end,
    'failure_loss_aggregate_limit_micros',effective_aggregate_limit_micros
  );
end $$;


ALTER FUNCTION "tongs"."_authorize_openai_text_provider_attempt_before_customer_test_sc"("p_reservation_id" "uuid", "p_attempt_key" "text", "p_attempt_number" smallint, "p_failure_exposure_micros" bigint, "p_lease_seconds" integer, "p_evidence_json" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."_authorize_openai_text_provider_attempt_before_customer_test_sc"("p_reservation_id" "uuid", "p_attempt_key" "text", "p_attempt_number" smallint, "p_failure_exposure_micros" bigint, "p_lease_seconds" integer, "p_evidence_json" "jsonb") IS 'Authorizes the shared provider boundary with hard per-operation/concurrency limits and optional finite operator-accepted Test aggregate exposure.';



CREATE OR REPLACE FUNCTION "tongs"."_available_deposit_credit_units"("p_deposit_id" "uuid") RETURNS bigint
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
  select greatest(coalesce(tongs._unconsumed_deposit_credit_units(p_deposit_id),0)
    - coalesce((select held.credit_units from tongs._active_funding_hold('customer_deposit',p_deposit_id) held),0),0)::bigint
$$;


ALTER FUNCTION "tongs"."_available_deposit_credit_units"("p_deposit_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."_available_deposit_value_micros"("p_deposit_id" "uuid") RETURNS bigint
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
  select greatest(
    coalesce(tongs._unconsumed_deposit_value_micros(p_deposit_id),0)
      - coalesce((select held.customer_charge_micros
          from tongs._active_funding_hold('customer_deposit',p_deposit_id) held),0),
    0
  )::bigint
$$;


ALTER FUNCTION "tongs"."_available_deposit_value_micros"("p_deposit_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."_bind_broll_prompt_owner_authority"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog'
    AS $$
declare v_receipt tongs.broll_operation_receipts%rowtype;
begin
  if new.prompt_source<>'ai_derived' then
    if new.owner_cost_attempt_id is not null then
      raise exception 'creator prompt edits cannot claim owner provider authority' using errcode='23514';
    end if;
    return new;
  end if;
  select * into v_receipt from tongs.broll_operation_receipts
    where operation_id=new.origin_operation_id and operation_type='prompt_interpretation';
  if not found then raise exception 'AI-derived B-roll prompt requires its canonical receipt' using errcode='23503'; end if;
  if new.owner_cost_attempt_id is not null
    and new.owner_cost_attempt_id is distinct from v_receipt.owner_cost_attempt_id
  then raise exception 'B-roll prompt owner authority conflicts with its receipt' using errcode='23514'; end if;
  new.owner_cost_attempt_id:=v_receipt.owner_cost_attempt_id;
  return new;
end $$;


ALTER FUNCTION "tongs"."_bind_broll_prompt_owner_authority"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."_bind_hearth_script_generation_proposal"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $_$
declare draft_file tongs.workpiece_files%rowtype;
begin
  select * into draft_file from tongs.workpiece_files
  where workpiece_id=new.workpiece_id and path='hearth/drafts.v1.json'
  for share;
  if draft_file.workpiece_id is null or draft_file.revision<1
    or lower(coalesce(draft_file.hash_value,''))!~'^[0-9a-f]{64}$' then
    raise exception 'canonical Hearth draft authority is required before proposal persistence'
      using errcode='55000';
  end if;
  insert into tongs.hearth_script_generation_proposal_draft_bindings(
    proposal_id,workspace_id,workpiece_id,expected_draft_revision,expected_draft_hash,bound_at
  ) values(
    new.id,new.workspace_id,new.workpiece_id,draft_file.revision,
    lower(draft_file.hash_value),new.created_at
  );
  insert into tongs.hearth_script_generation_proposal_events(
    proposal_id,event_type,idempotency_key,actor_id,
    expected_draft_revision,expected_draft_hash,details,created_at
  )
  select older.id,'superseded','hearth-script-proposal:superseded:'||older.id::text,
    new.user_id,older_binding.expected_draft_revision,older_binding.expected_draft_hash,
    jsonb_build_object('superseded_by',new.id),new.created_at
  from tongs.hearth_script_generation_proposals older
  join tongs.hearth_script_generation_proposal_draft_bindings older_binding
    on older_binding.proposal_id=older.id
  where older.user_id=new.user_id and older.workspace_id=new.workspace_id
    and older.workpiece_id=new.workpiece_id and older.id<>new.id
    and not exists(
      select 1 from tongs.hearth_script_generation_proposal_events terminal
      where terminal.proposal_id=older.id
        and terminal.event_type in ('applied','rejected','superseded')
    )
  on conflict do nothing;
  return new;
end $_$;


ALTER FUNCTION "tongs"."_bind_hearth_script_generation_proposal"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."_create_accounting_event"("p_event_id" "uuid", "p_idempotency_key" "text", "p_event_type" "text", "p_environment" "text", "p_source_type" "text", "p_source_id" "text", "p_currency" "text", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_actor_id" "uuid", "p_payload" "jsonb", "p_occurred_at" timestamp with time zone) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_hash text := tongs._accounting_payload_hash(p_payload);
  v_existing tongs.accounting_journal_events%rowtype;
begin
  perform pg_advisory_xact_lock(hashtextextended(p_idempotency_key, 0));
  select * into v_existing from tongs.accounting_journal_events where idempotency_key = p_idempotency_key;
  if found then
    if v_existing.id <> p_event_id or v_existing.payload_hash <> v_hash then
      raise exception 'accounting event replay conflict' using errcode = '23505';
    end if;
    return false;
  end if;
  insert into tongs.accounting_journal_events(
    id, idempotency_key, event_type, environment, source_type, source_id, currency,
    user_id, workspace_id, actor_id, payload_hash, metadata_json, occurred_at
  ) values (
    p_event_id, btrim(p_idempotency_key), btrim(p_event_type), p_environment,
    btrim(p_source_type), btrim(p_source_id), p_currency, p_user_id, p_workspace_id,
    p_actor_id, v_hash, coalesce(p_payload, '{}'::jsonb), coalesce(p_occurred_at, now())
  );
  return true;
end;
$$;


ALTER FUNCTION "tongs"."_create_accounting_event"("p_event_id" "uuid", "p_idempotency_key" "text", "p_event_type" "text", "p_environment" "text", "p_source_type" "text", "p_source_id" "text", "p_currency" "text", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_actor_id" "uuid", "p_payload" "jsonb", "p_occurred_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."_create_customer_runway_quote_before_customer_test_scope"("p_quote_id" "uuid", "p_user_id" "uuid", "p_operation_id" "text", "p_workspace_id" "uuid", "p_operation_fingerprint" "text", "p_model" "text", "p_duration_seconds" integer, "p_ratio" "text", "p_expires_at" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare v_pricing tongs.private_pricing_revisions%rowtype; v_policy tongs.private_pricing_policies%rowtype;
  v_quote tongs.customer_spending_quotes%rowtype; v_control tongs.paid_execution_control_revisions%rowtype;
  v_create jsonb; v_funding jsonb; v_sku text; v_price bigint;
begin
  perform tongs._require_pricing_service_role();
  select * into v_control from tongs._current_paid_execution_control();
  if p_model <> 'gen4.5' or p_duration_seconds not between 2 and 10 or p_ratio not in ('1280:720','720:1280') then
    raise exception 'unsupported Runway customer SKU' using errcode = '22023'; end if;
  v_sku := lower(p_model || ':' || p_duration_seconds::text || 's:' || p_ratio);
  select * into v_pricing from tongs._published_pricing_revision('runway',v_sku);
  if not found then raise exception 'pricing_not_configured' using errcode = 'P0001'; end if;
  select * into v_policy from tongs.private_pricing_policies where id=v_pricing.policy_id;
  if v_policy.scope_kind <> 'sku' or lower(coalesce(v_policy.provider,'')) <> 'runway' or lower(coalesce(v_policy.sku,'')) <> v_sku then
    raise exception 'pricing_not_configured' using errcode = 'P0001'; end if;
  v_price := tongs.round_customer_price_micros(
    v_pricing.full_cost_ceiling_micros::numeric * (10000::numeric + v_pricing.markup_basis_points)/10000::numeric,
    v_pricing.currency);
  v_create := tongs.create_shadow_spending_quote(p_quote_id,p_user_id,p_operation_id,'tongs_broll_v2',p_workspace_id,
    v_pricing.id,p_operation_fingerprint,jsonb_build_array(jsonb_build_object('component','video_generation','provider_label','Runway','credential_source','forge')),
    p_expires_at);
  select * into v_quote from tongs.customer_spending_quotes where id=p_quote_id;
  v_funding := tongs._select_customer_funding_for_quote(p_quote_id);
  return jsonb_build_object('quote_id',v_quote.id,'operation_id',v_quote.operation_id,'currency',v_quote.currency,
    'customer_price_micros',v_quote.normal_maximum_charge_micros,'maximum_charge_micros',v_quote.normal_maximum_charge_micros,
    'billable_failure_maximum_charge_micros',0,'billable_failure_classes','[]'::jsonb,
    'free_failure_classes',v_quote.free_failure_classes,'funding',v_funding,'expires_at',v_quote.expires_at,
    'retry_terms',jsonb_build_object('duplicate_operation_reuses_state',true,'automatic_resubmission_after_unknown',false),
    'execution_authorized',false,'customer_spending_enabled',v_control.customer_settlement_enabled,
    'rounding_rule','cost-plus rounded upward to the next USD cent');
end $$;


