CREATE OR REPLACE FUNCTION "tongs"."_eligible_ai_models_for_operation"("p_operation_code" "text") RETURNS TABLE("model_identity_id" "uuid", "customer_selection_key" "uuid", "display_name" "text", "relative_cost_class" "text", "catalog_revision_id" "uuid", "catalog_revision" integer, "model_catalog_entry_id" "uuid", "runtime_model_id" "text", "provider_model_id" "text", "cost_policy_revision_id" "uuid", "customer_credit_units" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
 select identity.id,identity.customer_selection_key,revision.display_name,revision.relative_cost_class,catalog.id,catalog.revision,entry.id,entry.runtime_model_id,entry.provider_model_id,compat.cost_policy_revision_id,pricing.customer_credit_units
 from tongs.ai_model_identities identity
 join lateral (select r.* from tongs.ai_model_identity_revisions r where r.model_identity_id=identity.id order by r.revision desc limit 1) revision on revision.lifecycle_state='active'
 join tongs.openai_text_catalog_ai_model_bindings binding on binding.model_identity_id=identity.id
 join tongs.openai_text_model_catalog_entries entry on entry.id=binding.catalog_entry_id
 join tongs.openai_text_model_catalog_revisions catalog on catalog.id=entry.catalog_revision_id and catalog.lifecycle_state='active'
 join tongs.openai_text_model_route_compatibility compat on compat.catalog_entry_id=entry.id and compat.route_code=p_operation_code and compat.compatibility_status='generation_verified' and compat.supporting_cost_coverage='complete'
 join tongs.openai_text_cost_policy_revisions cost on cost.id=compat.cost_policy_revision_id and cost.cost_coverage='complete' and cost.lifecycle_state in ('pilot_candidate','active')
 join lateral tongs._published_pricing_revision('openai',lower('openai-text:'||p_operation_code||':'||entry.runtime_model_id||':'||cost.id::text)) pricing on pricing.full_cost_ceiling_micros=cost.full_cost_ceiling_micros
 where catalog.id=(select id from tongs.openai_text_model_catalog_revisions where lifecycle_state='active' order by revision desc limit 1)
   and entry.lifecycle_state='active' and entry.availability_status='generation_compatible';
$$;


ALTER FUNCTION "tongs"."_eligible_ai_models_for_operation"("p_operation_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."_enforce_hearth_remaining_execution_authority"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_route text;
  v_customer boolean;
  v_historical boolean;
  v_owner tongs.owner_cost_operations%rowtype;
  v_attempt tongs.owner_cost_provider_attempts%rowtype;
  v_latest_state text;
  v_captured_response boolean := false;
begin
  if tg_table_name='unified_visual_plan_operations' then
    v_route:='visual.unified_plan';
    select exists(select 1 from tongs.unified_visual_plan_historical_authorities historical
      where historical.operation_id=new.operation_id) into v_historical;
  elsif tg_table_name='broll_operation_receipts' and new.operation_type='prompt_interpretation' then
    v_route:='motion.broll_interpretation';
    select exists(select 1 from tongs.broll_interpretation_historical_authorities historical
      where historical.operation_id=new.operation_id) into v_historical;
  else
    if new.owner_cost_attempt_id is not null then
      raise exception 'owner authority is restricted to B-roll prompt interpretation' using errcode='23514';
    end if;
    return new;
  end if;

  select exists(select 1 from tongs.openai_text_funding_bindings binding
    where binding.operation_id=new.operation_id and binding.route_code=v_route) into v_customer;
  if ((v_customer::integer)+(v_historical::integer)+
      ((new.owner_cost_attempt_id is not null)::integer)) <> 1 then
    raise exception '% requires exactly one customer, owner, or sealed historical authority', v_route
      using errcode='23514';
  end if;
  if tg_op='UPDATE' and new.owner_cost_attempt_id is distinct from old.owner_cost_attempt_id then
    raise exception 'execution authority is immutable' using errcode='55000';
  end if;
  if v_historical then
    if tg_op='INSERT' or new.owner_cost_attempt_id is not null then
      raise exception 'historical authority is migration-only' using errcode='42501';
    end if;
    return new;
  end if;
  if new.owner_cost_attempt_id is null then return new; end if;

  select * into v_attempt from tongs.owner_cost_provider_attempts
    where attempt_id=new.owner_cost_attempt_id;
  select * into v_owner from tongs.owner_cost_operations
    where operation_id=v_attempt.operation_id;
  select lifecycle_state into v_latest_state from tongs.owner_cost_attempt_events
    where attempt_id=new.owner_cost_attempt_id order by event_sequence desc limit 1;
  if v_route='visual.unified_plan' then
    select exists (
      select 1
      from tongs.owner_cost_attempt_events event
      where event.attempt_id=new.owner_cost_attempt_id
        and event.lifecycle_state='response_captured'
        and event.provider_reference_id is not null
    ) into v_captured_response;
  end if;

  if v_attempt.attempt_id is null or v_owner.operation_id is null
    or v_owner.payer<>'forge' or v_owner.originating_tool<>'hearth'
    or v_owner.operation_type<>v_route or v_owner.operation_key<>new.operation_id
    or v_owner.workspace_id is distinct from new.workspace_id
    or v_owner.workpiece_id is distinct from new.workpiece_id
    or v_owner.request_fingerprint<>new.operation_fingerprint
    or v_attempt.provider<>'openai'
    or (
      v_latest_state not in ('authorized','submitted','response_captured','succeeded')
      and not (v_latest_state='failed' and v_captured_response)
    )
    or (
      new.provider_response_json is not null
      and v_latest_state not in ('response_captured','succeeded')
      and not (v_latest_state='failed' and v_captured_response)
    )
  then raise exception 'owner execution authority does not match canonical operation'
    using errcode='42501'; end if;
  return new;
end
$$;


ALTER FUNCTION "tongs"."_enforce_hearth_remaining_execution_authority"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."_enforce_scoped_customer_paid_reservation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_quote tongs.customer_spending_quotes%rowtype;
  v_authorization tongs.customer_paid_execution_test_authorizations%rowtype;
begin
  if new.funding_source_type not in ('customer_deposit','paid_allowance') then
    return new;
  end if;
  select * into v_quote from tongs.customer_spending_quotes where id=new.quote_id;
  select * into v_authorization
    from tongs._active_customer_paid_execution_test_authorization_for_quote(new.quote_id);
  if not found
     or v_authorization.user_id<>new.user_id
     or v_authorization.user_id<>v_quote.user_id
     or v_authorization.workspace_id is distinct from v_quote.workspace_id
     or v_authorization.route_code<>v_quote.tool
     or v_authorization.pricing_revision_id<>v_quote.pricing_revision_id
     or v_quote.normal_maximum_charge_micros>v_authorization.maximum_customer_charge_micros then
    raise exception 'customer paid execution is not authorized for this test scope' using errcode='42501';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('customer-paid-test-authorization:'||v_authorization.id::text,0));
  if exists (
    select 1
    from tongs.customer_paid_execution_test_authorization_quotes authorization_quote
    join tongs.funding_reservations reservation on reservation.quote_id=authorization_quote.quote_id
    where authorization_quote.authorization_id=v_authorization.id
      and reservation.id<>new.id
  ) then
    raise exception 'customer paid test operation limit reached' using errcode='P0001';
  end if;
  return new;
end $$;


ALTER FUNCTION "tongs"."_enforce_scoped_customer_paid_reservation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."_finish_customer_hearth_research_stage"("p_reservation_id" "uuid", "p_stage_key" "text", "p_event_type" "text", "p_actual" bigint, "p_capture" "jsonb", "p_evidence" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  first_event tongs.customer_hearth_research_stage_events%rowtype;
  latest tongs.customer_hearth_research_stage_events%rowtype;
  total bigint;
begin
  perform tongs._require_pricing_service_role();
  perform pg_advisory_xact_lock(hashtextextended('customer-hearth-research-stage:'||p_reservation_id::text,0));
  select * into first_event from tongs.customer_hearth_research_stage_events
    where reservation_id=p_reservation_id and stage_key=btrim(p_stage_key) and sequence=1;
  select * into latest from tongs.customer_hearth_research_stage_events
    where reservation_id=p_reservation_id and stage_key=btrim(p_stage_key) order by sequence desc limit 1;
  if first_event.id is null then raise exception 'research stage authorization missing' using errcode='42501'; end if;
  if latest.sequence>1 then return jsonb_build_object('replay',true,'event_type',latest.event_type,'capture',latest.capture_json); end if;
  if p_event_type not in ('captured','failed','submission_unknown') or p_actual<0
     or p_actual>first_event.maximum_supplier_cost_micros
  then raise exception 'invalid research stage result' using errcode='22023'; end if;
  if p_event_type='captured' then
    select coalesce(sum((capture_json->>'response_bytes')::bigint),0)+coalesce((p_capture->>'response_bytes')::bigint,0)
      into total from tongs.customer_hearth_research_stage_events
      where reservation_id=p_reservation_id and event_type='captured';
    if total>1048576 then raise exception 'research capture package cap exceeded' using errcode='22023'; end if;
  end if;
  insert into tongs.customer_hearth_research_stage_events values(
    gen_random_uuid(),p_reservation_id,btrim(p_stage_key),2,first_event.stage_type,
    first_event.stage_ordinal,p_event_type,first_event.request_fingerprint,
    first_event.maximum_supplier_cost_micros,p_actual,'estimated',first_event.request_json,
    p_capture,coalesce(p_evidence,'{}'),now()
  ) returning * into latest;
  insert into tongs.customer_hearth_research_component_expenses values(
    gen_random_uuid(),p_reservation_id,'stage:'||btrim(p_stage_key),first_event.stage_type,p_actual,
    'estimated',case when first_event.stage_type='search' then 'Brave Search' else 'retrieval origin' end,
    coalesce(p_evidence,'{}')||jsonb_build_object('event_type',p_event_type),now()
  ) on conflict(expense_key) do nothing;
  return jsonb_build_object('replay',false,'event_type',latest.event_type,'capture',latest.capture_json);
end $$;


ALTER FUNCTION "tongs"."_finish_customer_hearth_research_stage"("p_reservation_id" "uuid", "p_stage_key" "text", "p_event_type" "text", "p_actual" bigint, "p_capture" "jsonb", "p_evidence" "jsonb") OWNER TO "postgres";


