CREATE OR REPLACE FUNCTION "tongs"."_gpt_image_2_output_tokens"("p_width" integer, "p_height" integer, "p_quality" "text") RETURNS bigint
    LANGUAGE "plpgsql" IMMUTABLE STRICT
    SET "search_path" TO 'pg_catalog'
    AS $$
declare v_grid integer; v_minor integer;
begin
  if p_width%16<>0 or p_height%16<>0 or p_width*p_height not between 655360 and 8294400
     or greatest(p_width,p_height)>3840 or greatest(p_width,p_height)::numeric/least(p_width,p_height)>3 then
    raise exception 'unsupported GPT Image 2 dimensions' using errcode='22023';
  end if;
  v_grid:=case p_quality when 'low' then 16 when 'medium' then 48 when 'high' then 96 else null end;
  if v_grid is null then raise exception 'unsupported GPT Image 2 quality' using errcode='22023'; end if;
  v_minor:=round(v_grid::numeric*least(p_width,p_height)/greatest(p_width,p_height));
  return ceil((v_grid*v_minor)::numeric*(2000000::numeric+p_width::numeric*p_height)/4000000::numeric)::bigint;
end $$;


ALTER FUNCTION "tongs"."_gpt_image_2_output_tokens"("p_width" integer, "p_height" integer, "p_quality" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."_guard_openai_job_cutover"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare route text; mode text;
begin
 if new.job_type not in ('hammer_transcript_prep','hammer_transcript_regeneration') then return new; end if;
 route:=case new.job_type when 'hammer_transcript_prep' then 'hammer.transcript_prep' else 'hammer.transcript_regeneration' end;
 select r.mode into mode from tongs._current_openai_text_rollout(route) r;
 if mode='halt_new' and (tg_op='INSERT' or (new.status in ('queued','running') and new.status is distinct from old.status)) then
   raise exception 'paid_submissions_halted: existing evidence can reconcile; no transcription job may start' using errcode='42501';
 end if;
 return new;
end $$;


ALTER FUNCTION "tongs"."_guard_openai_job_cutover"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."_hammer_scope_has_remaining_authority"("p_authorization_id" "uuid", "p_at" timestamp with time zone DEFAULT "clock_timestamp"()) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
  select exists (
    select 1
    from tongs.customer_paid_execution_scope_authorizations scope_auth
    where scope_auth.id = p_authorization_id
      and scope_auth.route_code = 'hammer.transcript_cleanup'
      and scope_auth.financial_environment = 'test'
      and scope_auth.status = 'active'
      and scope_auth.valid_from <= p_at
      and (scope_auth.valid_until is null or scope_auth.valid_until > p_at)
      and (
        scope_auth.maximum_operation_count is null
        or (select count(*)
            from tongs.funding_reservations reservation
            where reservation.rollout_authorization_id = scope_auth.id)
          < scope_auth.maximum_operation_count
      )
      and (
        select count(*)
        from tongs.funding_reservations reservation
        where reservation.rollout_authorization_id = scope_auth.id
          and tongs._funding_reservation_counts_paid_scope_concurrency(
            reservation.id
          )
      ) < scope_auth.maximum_concurrency
  );
$$;


ALTER FUNCTION "tongs"."_hammer_scope_has_remaining_authority"("p_authorization_id" "uuid", "p_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."_hammer_scope_is_effective"("p_authorization_id" "uuid", "p_at" timestamp with time zone DEFAULT "clock_timestamp"()) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
  select tongs._hammer_scope_has_remaining_authority(p_authorization_id, p_at)
    and exists (
      select 1
      from tongs.customer_paid_execution_scope_authorizations scope_auth
      where scope_auth.id = p_authorization_id
        and scope_auth.authorization_kind = 'normal_customer'
        and scope_auth.provider = 'openai'
        and scope_auth.model_or_sku = 'gpt-5.4-mini'
        and scope_auth.pricing_revision_id =
          '40010000-0000-4000-8000-000000000402'::uuid
        and scope_auth.cost_policy_revision_id =
          '40010000-0000-4000-8000-000000000301'::uuid
    )
    and (
      select rollout.mode = 'enforce'
        and rollout.cost_policy_revision_id =
          '40010000-0000-4000-8000-000000000301'::uuid
      from tongs.openai_text_rollout_revisions rollout
      where rollout.route_code = 'hammer.transcript_cleanup'
      order by rollout.revision desc limit 1
    )
    and (
      select loss.mode = 'enforce'
        and loss.loss_policy_revision_id =
          '40010000-0000-4000-8000-000000000601'::uuid
      from tongs.openai_text_failure_loss_rollout_revisions loss
      where loss.route_code = 'hammer.transcript_cleanup'
        and loss.financial_environment = 'test'
      order by loss.revision desc limit 1
    );
$$;


