CREATE OR REPLACE FUNCTION "tongs"."_insert_missing_org_members_from_teams"("p_org_id" "uuid" DEFAULT NULL::"uuid") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare
  v_inserted integer := 0;
begin
  with missing as (
    select
      t.org_id,
      tm.user_id,
      coalesce(tm.created_at, now()) as created_at,
      coalesce(
        tm.created_by,
        (
          select owner_row.user_id
          from tongs.org_members owner_row
          where owner_row.org_id = t.org_id
            and owner_row.org_role = 'owner'
          order by owner_row.created_at asc nulls last
          limit 1
        )
      ) as created_by
    from tongs.team_members tm
    join tongs.teams t
      on t.id = tm.team_id
    left join tongs.org_members om
      on om.org_id = t.org_id
     and om.user_id = tm.user_id
    where om.user_id is null
      and (p_org_id is null or t.org_id = p_org_id)
  ),
  inserted as (
    insert into tongs.org_members (
      org_id,
      user_id,
      org_role,
      created_at,
      created_by
    )
    select
      m.org_id,
      m.user_id,
      'member',
      m.created_at,
      m.created_by
    from missing m
    on conflict (org_id, user_id) do nothing
    returning 1
  )
  select count(*)
  into v_inserted
  from inserted;

  return v_inserted;
end;
$$;


