CREATE OR REPLACE FUNCTION "tongs"."_openai_reconciliation_runtime_model_matches_snapshot"("p_runtime_model" "text", "p_provider_snapshot" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
  with current_catalog_revision as (
    select revision.id
    from tongs.openai_text_model_catalog_revisions revision
    where revision.lifecycle_state='active'
    order by revision.revision desc
    limit 1
  ), active_entries as (
    select entry.runtime_model_id,entry.provider_model_id
    from tongs.openai_text_model_catalog_entries entry
    join current_catalog_revision catalog on catalog.id=entry.catalog_revision_id
    where entry.lifecycle_state='active'
  )
  select
    (select count(*) from active_entries
      where runtime_model_id=btrim(p_runtime_model)
        and provider_model_id=btrim(p_provider_snapshot))=1
    and (select count(*) from active_entries
      where runtime_model_id=btrim(p_runtime_model))=1
    and (select count(*) from active_entries
      where provider_model_id=btrim(p_provider_snapshot))=1
$$;


ALTER FUNCTION "tongs"."_openai_reconciliation_runtime_model_matches_snapshot"("p_runtime_model" "text", "p_provider_snapshot" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."_openai_reconciliation_runtime_model_matches_snapshot"("p_runtime_model" "text", "p_provider_snapshot" "text") IS 'Fail-closed exact active catalog mapping from a funding-bound runtime model to a supplier-reported provider snapshot.';



CREATE OR REPLACE FUNCTION "tongs"."_openai_reconciliation_scope_key"("p_source_kind" "text", "p_currency" "text", "p_raw" "jsonb") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
  select encode(extensions.digest(convert_to(
    coalesce(p_source_kind,'')||':'||upper(coalesce(p_currency,''))||':'||
    coalesce((select string_agg(value,',' order by value) from jsonb_array_elements_text(coalesce(p_raw->'project_scope','[]'::jsonb))),''),
    'utf8'),'sha256'),'hex');
$$;


