CREATE OR REPLACE FUNCTION "tongs"."_openai_text_verified_zero_supporting_cost"("p_reservation_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
  select exists(
    select 1
    from tongs.funding_reservations reservation
    join tongs.openai_text_funding_bindings binding
      on binding.reservation_id=reservation.id
    join tongs.openai_text_customer_quote_bindings quote_binding
      on quote_binding.quote_id=reservation.quote_id
    join tongs.openai_text_cost_policy_revisions cost
      on cost.id=binding.cost_policy_revision_id
    where reservation.id=p_reservation_id
      and binding.credential_funding='forge'
      and binding.route_code='hammer.transcript_cleanup'
      and quote_binding.route_code=binding.route_code
      and quote_binding.canonical_operation_id=binding.operation_id
      and quote_binding.runtime_model=binding.model
      and quote_binding.pricing_revision_id=binding.pricing_revision_id
      and quote_binding.cost_policy_revision_id=binding.cost_policy_revision_id
      and cost.route_code=binding.route_code
      and cost.lifecycle_state='active'
      and cost.cost_coverage='complete'
      and cost.supporting_cost_ceiling_micros=0
      and cost.full_cost_ceiling_micros=cost.direct_provider_ceiling_micros
      and (
        select count(*)=3
          and count(*) filter(where inventory.evidence_status='verified')=3
          and count(*) filter(where
            (inventory.component_code='provider_attempt' and inventory.disposition='attributable_metered')
            or (inventory.component_code='validation_persistence' and inventory.disposition='platform_overhead')
            or (inventory.component_code='hosting_storage_egress' and inventory.disposition='platform_overhead')
          )=3
        from tongs.openai_text_supporting_cost_inventory inventory
        where inventory.cost_policy_revision_id=cost.id
          and inventory.route_code=cost.route_code
      )
  )
$$;


ALTER FUNCTION "tongs"."_openai_text_verified_zero_supporting_cost"("p_reservation_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "tongs"."owner_hearth_research_authorizations" (
    "id" "uuid" NOT NULL,
    "proposal_id" "uuid" NOT NULL,
    "authorization_kind" "text" NOT NULL,
    "limit_profile" "text" NOT NULL,
    "owner_user_id" "uuid" NOT NULL,
    "workspace_id" "uuid" NOT NULL,
    "budget_id" "uuid" NOT NULL,
    "maximum_amount_micros" bigint NOT NULL,
    "maximum_operations" integer NOT NULL,
    "maximum_concurrency" integer NOT NULL,
    "maximum_attempts" smallint NOT NULL,
    "maximum_searches" integer NOT NULL,
    "maximum_sources" integer NOT NULL,
    "maximum_http_attempts" integer NOT NULL,
    "maximum_input_tokens" bigint NOT NULL,
    "maximum_output_tokens" bigint NOT NULL,
    "failure_loss_limit_micros" bigint NOT NULL,
    "duration_seconds" integer NOT NULL,
    "created_by" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "owner_hearth_research_authoriza_failure_loss_limit_micros_check" CHECK (("failure_loss_limit_micros" >= 0)),
    CONSTRAINT "owner_hearth_research_authorization_maximum_amount_micros_check" CHECK (("maximum_amount_micros" > 0)),
    CONSTRAINT "owner_hearth_research_authorization_maximum_http_attempts_check" CHECK (("maximum_http_attempts" = 24)),
    CONSTRAINT "owner_hearth_research_authorizations_authorization_kind_check" CHECK (("authorization_kind" = ANY (ARRAY['canary'::"text", 'creator_session'::"text"]))),
    CONSTRAINT "owner_hearth_research_authorizations_check" CHECK (("limit_profile" = "authorization_kind")),
    CONSTRAINT "owner_hearth_research_authorizations_check1" CHECK (((("authorization_kind" = 'canary'::"text") AND ("failure_loss_limit_micros" = 144072)) OR (("authorization_kind" = 'creator_session'::"text") AND ("failure_loss_limit_micros" = 4276544)))),
    CONSTRAINT "owner_hearth_research_authorizations_check2" CHECK (((("authorization_kind" = 'canary'::"text") AND ("maximum_searches" = 1) AND ("maximum_sources" = 2) AND ("maximum_input_tokens" = 8000) AND ("maximum_output_tokens" = 1000)) OR (("authorization_kind" = 'creator_session'::"text") AND ("maximum_searches" = 6) AND ("maximum_sources" = 6) AND ("maximum_input_tokens" = 128000) AND ("maximum_output_tokens" = 16384)))),
    CONSTRAINT "owner_hearth_research_authorizations_duration_seconds_check" CHECK (("duration_seconds" = 86400)),
    CONSTRAINT "owner_hearth_research_authorizations_limit_profile_check" CHECK (("limit_profile" = ANY (ARRAY['canary'::"text", 'creator_session'::"text"]))),
    CONSTRAINT "owner_hearth_research_authorizations_maximum_attempts_check" CHECK (("maximum_attempts" = 1)),
    CONSTRAINT "owner_hearth_research_authorizations_maximum_concurrency_check" CHECK (("maximum_concurrency" = 1)),
    CONSTRAINT "owner_hearth_research_authorizations_maximum_operations_check" CHECK (("maximum_operations" > 0))
);

