CREATE OR REPLACE FUNCTION "tongs"."_paid_media_usage_contract_is_video"("p_usage_components" "jsonb") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'pg_catalog', 'tongs', 'extensions'
    AS $$
  select coalesce(
    jsonb_typeof(p_usage_components) = 'array'
    and jsonb_array_length(p_usage_components) = 1
    and (p_usage_components->0->>'component_kind') = 'video_output'
    and (p_usage_components->0->>'unit_kind') = 'second',
    false
  );
$$;


