CREATE OR REPLACE FUNCTION "tongs"."_preview_private_price_before_rounded_customer_ceiling"("p_pricing_revision_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_revision tongs.private_pricing_revisions%rowtype;
  v_policy tongs.private_pricing_policies%rowtype;
  v_components jsonb;
begin
  if coalesce(auth.role(), '') <> 'service_role'
     and (v_actor is null or not tongs.is_platform_operator(v_actor)) then
    raise exception 'platform operator required' using errcode = '42501';
  end if;
  select * into v_revision from tongs.private_pricing_revisions where id = p_pricing_revision_id;
  if not found then raise exception 'private pricing revision not found' using errcode = 'P0002'; end if;
  select * into v_policy from tongs.private_pricing_policies where id = v_revision.policy_id;
  select coalesce(jsonb_agg(jsonb_build_object(
    'component_code', component.component_code,
    'component_kind', component.component_kind,
    'credential_funding', component.credential_funding,
    'provider_label', component.provider_label,
    'success_ceiling_micros', component.success_ceiling_micros,
    'failure_ceiling_micros', component.failure_ceiling_micros,
    'cost_policy_revision', component.cost_policy_revision,
    'tail_policy', component.tail_policy,
    'tail_policy_details', component.tail_policy_details
  ) order by component.ordinal), '[]'::jsonb) into v_components
  from tongs.private_pricing_cost_components component
  where component.pricing_revision_id = v_revision.id;
  return jsonb_build_object(
    'policy', jsonb_build_object('policy_code', v_policy.policy_code, 'scope_kind', v_policy.scope_kind,
      'provider', v_policy.provider, 'sku', v_policy.sku),
    'revision_id', v_revision.id, 'revision', v_revision.revision,
    'state', v_revision.lifecycle_state, 'currency', v_revision.currency,
    'cost_components', v_components,
    'full_cost_ceiling_micros', v_revision.full_cost_ceiling_micros,
    'failure_cost_ceiling_micros', v_revision.failure_cost_ceiling_micros,
    'markup_basis_points', v_revision.markup_basis_points,
    'customer_price_ceiling_micros', v_revision.customer_price_ceiling_micros,
    'billable_failure_ceiling_micros', v_revision.billable_failure_ceiling_micros,
    'customer_credit_units', v_revision.customer_credit_units,
    'expected_margin_micros', case when v_revision.customer_price_ceiling_micros is null then null
      else v_revision.customer_price_ceiling_micros - v_revision.full_cost_ceiling_micros end,
    'expected_margin_percentage', case
      when coalesce(v_revision.customer_price_ceiling_micros, 0) = 0 then null
      else round(100::numeric * (v_revision.customer_price_ceiling_micros - v_revision.full_cost_ceiling_micros)::numeric
        / v_revision.customer_price_ceiling_micros::numeric, 4) end,
    'funding_behavior', jsonb_build_object(
      'customer_deposit', 'requires verified live deposit and finalized processor fee',
      'paid_allowance', 'requires funded-cycle entitlement, revenue backing, and wholesale capacity',
      'byo', 'reserves only Forge-funded supporting components',
      'owner_testing', 'disabled until a later approved control revision and an active capped budget'),
    'activation_enabled', false,
    'missing_decisions', case when v_revision.markup_basis_points is null
      then jsonb_build_array('markup_basis_points', 'customer_credit_units') else '[]'::jsonb end
  );
end;
$$;


ALTER FUNCTION "tongs"."_preview_private_price_before_rounded_customer_ceiling"("p_pricing_revision_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."_process_openai_organization_reconciliation"("p_batch_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $_$
declare ub record; candidate record; candidate_count bigint; candidate_input bigint; candidate_cached bigint;
 provider_bucket_count bigint; candidate_output bigint; distinct_refs bigint; cost_total bigint; cost_bucket_count bigint;
 allocation_count bigint:=0; adjustment_total bigint:=0; direct_count bigint; reconciled_direct_count bigint;
 direct_actual bigint; other_incomplete bigint; other_confirmed bigint; aggregate_result jsonb;
begin
 perform tongs._require_pricing_service_role();
 if tongs._openai_reconciliation_batch_state(p_batch_id)<>'accepted' then
  return jsonb_build_object('batch_id',p_batch_id,'effective',false,'allocation_status','overlap_quarantined','automatic_allocations',0);
 end if;
 for ub in select * from tongs.openai_organization_usage_buckets where batch_id=p_batch_id loop
  select count(*) into provider_bucket_count from tongs.openai_organization_usage_buckets x
   where x.batch_id=p_batch_id and x.model is not distinct from ub.model
    and (x.evidence_json->>'start_time')=(ub.evidence_json->>'start_time')
    and (x.evidence_json->>'end_time')=(ub.evidence_json->>'end_time')
    and x.project_id is not distinct from ub.project_id;
  if provider_bucket_count<>1 or ub.model is null or ub.api_key_id is null then continue; end if;
  select count(*),coalesce(sum(c.amount_micros),0) into cost_bucket_count,cost_total
  from tongs.openai_organization_cost_buckets c
  where c.batch_id=p_batch_id and c.project_id is not distinct from ub.project_id
    and c.api_key_id is not distinct from ub.api_key_id
    and (c.evidence_json->>'start_time')=(ub.evidence_json->>'start_time')
    and (c.evidence_json->>'end_time')=(ub.evidence_json->>'end_time')
    and btrim(split_part(coalesce(c.line_item,''),',',1))=ub.model;
  if cost_bucket_count=0 then continue; end if;
  select count(*),coalesce(sum(u.input_units),0),
    coalesce(sum(case when (u.evidence_json->>'cached_input_units')~'^[0-9]+$' then (u.evidence_json->>'cached_input_units')::bigint else 0 end),0),
    coalesce(sum(u.output_units),0),count(distinct u.provider_request_id)
  into candidate_count,candidate_input,candidate_cached,candidate_output,distinct_refs
  from tongs.supplier_expenses e
  join tongs.openai_text_funding_bindings b on b.reservation_id=e.reservation_id
    and b.credential_funding='forge'
    and tongs._openai_reconciliation_runtime_model_matches_snapshot(b.model,ub.model)
  join tongs.openai_text_usage_evidence u on u.reservation_id=e.reservation_id
    and u.attempt_number=coalesce((e.evidence_json->>'attempt_number')::smallint,1) and u.provider_reported
  join tongs.funding_reservations r on r.id=e.reservation_id
  where e.provider='openai' and e.provider_reference is not null and u.provider_request_id=e.provider_reference
    and tongs._aggregate_funding_class(r)<>'test_customer'
    and u.recorded_at>=to_timestamp((ub.evidence_json->>'start_time')::double precision)
    and u.recorded_at<to_timestamp((ub.evidence_json->>'end_time')::double precision);
  if candidate_count=0 or candidate_count<>ub.request_count or distinct_refs<>candidate_count
     or candidate_input<>ub.input_tokens or candidate_cached<>ub.cached_input_tokens or candidate_output<>ub.output_tokens then continue; end if;
  for candidate in
   with candidates as (
    select e.id expense_id,e.reservation_id,e.amount_micros,u.provider_request_id,
      greatest(coalesce(e.amount_micros,0),u.input_units+u.output_units,1)::numeric weight
    from tongs.supplier_expenses e
    join tongs.openai_text_funding_bindings b on b.reservation_id=e.reservation_id
      and b.credential_funding='forge'
      and tongs._openai_reconciliation_runtime_model_matches_snapshot(b.model,ub.model)
    join tongs.openai_text_usage_evidence u on u.reservation_id=e.reservation_id
      and u.attempt_number=coalesce((e.evidence_json->>'attempt_number')::smallint,1) and u.provider_reported
    join tongs.funding_reservations r on r.id=e.reservation_id
    where e.provider='openai' and e.provider_reference is not null and u.provider_request_id=e.provider_reference
      and tongs._aggregate_funding_class(r)<>'test_customer'
      and u.recorded_at>=to_timestamp((ub.evidence_json->>'start_time')::double precision)
      and u.recorded_at<to_timestamp((ub.evidence_json->>'end_time')::double precision)
   ), weighted as (
    select c.*,sum(weight) over() total_weight,
      sum(weight) over(order by reservation_id rows between unbounded preceding and current row) cumulative_weight,
      coalesce(sum(weight) over(order by reservation_id rows between unbounded preceding and 1 preceding),0) prior_weight
    from candidates c
   )
   select w.*,case when cost_total=0 then 0 else
     floor(cost_total::numeric*cumulative_weight/total_weight)::bigint-floor(cost_total::numeric*prior_weight/total_weight)::bigint end allocated
   from weighted w order by reservation_id
  loop
   insert into tongs.openai_text_operation_cost_allocations(
     id,reservation_id,batch_id,allocation_key,allocated_cost_micros,allocation_status,allocation_method,evidence_json)
   values(extensions.uuid_generate_v5(p_batch_id,candidate.reservation_id::text),candidate.reservation_id,p_batch_id,
    'openai-allocation:'||p_batch_id::text||':'||candidate.reservation_id::text,candidate.allocated,'confirmed','token_weighted',
    jsonb_build_object('evidence_class','defensible_aggregate_allocation','request_level_cost_match',false,
      'provider_request_id_used_for_completeness',candidate.provider_request_id,'project_id',ub.project_id,
      'api_key_id',ub.api_key_id,'provider_snapshot_model',ub.model,'provider_request_count',ub.request_count,
      'provider_usage_totals_exactly_accounted_for',true,
      'allocation_rule','estimated-cost weight, token fallback, deterministic remainder'))
   on conflict(allocation_key) do nothing;
   perform tongs.record_openai_supplier_expense_reconciliation_adjustment(
    extensions.uuid_generate_v5(p_batch_id,'adjustment:'||candidate.expense_id::text),candidate.expense_id,p_batch_id,
    extensions.uuid_generate_v5(p_batch_id,candidate.reservation_id::text),
    'openai-adjustment:'||p_batch_id::text||':'||candidate.expense_id::text,candidate.allocated,'documented_allocation',
    jsonb_build_object('provider_total_authoritative',true,'operation_amount_is_allocated',true,'request_level_cost_match',false));
   perform tongs.record_openai_supplier_expense_obligation_settlement(
    extensions.uuid_generate_v5(p_batch_id,'obligation-settlement:'||candidate.expense_id::text),candidate.expense_id,p_batch_id,
    extensions.uuid_generate_v5(p_batch_id,candidate.reservation_id::text),
    'openai-obligation:'||p_batch_id::text||':'||candidate.expense_id::text,
    jsonb_build_object('provider_total_authoritative',true,'provider_snapshot_model',ub.model));
   allocation_count:=allocation_count+1;
   adjustment_total:=adjustment_total+(candidate.allocated-coalesce(candidate.amount_micros,0));

   if exists(select 1 from tongs.paid_operation_aggregate_bindings b where b.reservation_id=candidate.reservation_id) then
    select count(*),count(*) filter(where effective.confirmed_amount is not null),coalesce(sum(effective.confirmed_amount),0)
    into direct_count,reconciled_direct_count,direct_actual
    from tongs.supplier_expenses e
    left join lateral(
      select settlement.confirmed_amount_micros confirmed_amount
      from tongs.openai_supplier_expense_obligation_settlement_events settlement
      where settlement.supplier_expense_id=e.id
      order by settlement.sequence desc limit 1
    ) effective on true
    where e.reservation_id=candidate.reservation_id and e.provider='openai';
    if direct_count>0 and direct_count=reconciled_direct_count then
     select summary.incomplete_count
       + case when authority.verified_zero and summary.verified_zero_expense_count<>1 then 1 else 0 end,
       summary.confirmed_amount
     into other_incomplete,other_confirmed
     from (select tongs._openai_text_verified_zero_supporting_cost(candidate.reservation_id) verified_zero) authority
     cross join lateral(
       select
        count(*) filter(where (e.evidence_status<>'confirmed' or e.amount_micros is null)
          and not (authority.verified_zero and e.provider='forge'
            and e.component_code='openai.text.hammer.transcript_cleanup.supporting'
            and e.amount_micros=0 and e.obligation_status='closed'
            and e.evidence_status in ('estimated','confirmed'))) incomplete_count,
        coalesce(sum(e.amount_micros) filter(where e.evidence_status='confirmed'),0) confirmed_amount,
        count(*) filter(where e.provider='forge'
          and e.component_code='openai.text.hammer.transcript_cleanup.supporting'
          and e.amount_micros=0 and e.obligation_status='closed'
          and e.evidence_status in ('estimated','confirmed')) verified_zero_expense_count
       from tongs.supplier_expenses e
       where e.reservation_id=candidate.reservation_id and e.provider<>'openai'
     ) summary;
     if other_incomplete=0 then
      perform tongs.record_owner_operating_budget_reconciliation_adjustment(
       extensions.uuid_generate_v5(p_batch_id,'owner-budget-adjustment:'||candidate.reservation_id::text),
       candidate.reservation_id,candidate.expense_id,p_batch_id,
       extensions.uuid_generate_v5(p_batch_id,candidate.reservation_id::text),
       'owner-budget-adjustment:'||p_batch_id::text||':'||candidate.reservation_id::text,
       direct_actual+other_confirmed,
       jsonb_build_object('authoritative',true,'provider','openai','provider_snapshot_model',ub.model,
         'direct_provider_allocated',true,'supporting_costs_confirmed',true));
      aggregate_result:=tongs.record_paid_operation_aggregate_outcome(candidate.reservation_id,
       'openai-reconciliation:'||p_batch_id::text||':'||candidate.reservation_id::text||':complete','reconciled',direct_actual+other_confirmed,null,
       jsonb_build_object('authoritative',true,'provider','openai','batch_id',p_batch_id,
         'direct_provider_allocated',true,'supporting_costs_confirmed',true,
         'verified_zero_supporting_cost_authority',tongs._openai_text_verified_zero_supporting_cost(candidate.reservation_id)));
       perform tongs.record_restricted_beta_exposure_adjustment(
         binding.hold_id,
         'openai-reconciliation:'||p_batch_id::text||':'||candidate.reservation_id::text||':effective-exposure',
         'authoritative_adjustment',direct_actual+other_confirmed,
         (direct_actual+other_confirmed)-coalesce(prior.remaining_exposure,
           binding.supplier_exposure_ceiling_micros+binding.supporting_exposure_ceiling_micros),
         direct_actual+other_confirmed,
         jsonb_build_object('authoritative',true,'provider','openai','batch_id',p_batch_id,
           'effective_supplier_obligations_closed',true,'supporting_costs_confirmed',true))
       from tongs.paid_operation_aggregate_bindings binding
       left join lateral(
         select event.remaining_exposure_micros remaining_exposure
         from tongs.restricted_beta_exposure_events event
         where event.hold_id=binding.hold_id and event.remaining_exposure_micros is not null
         order by event.sequence desc limit 1
       ) prior on true
       where binding.reservation_id=candidate.reservation_id;
     else
      aggregate_result:=tongs.record_paid_operation_aggregate_outcome(candidate.reservation_id,
       'openai-reconciliation:'||p_batch_id::text||':'||candidate.reservation_id::text||':partial','reconciled_partial',direct_actual,null,
       jsonb_build_object('authoritative',true,'provider','openai','batch_id',p_batch_id,
         'direct_provider_allocated',true,'supporting_costs_confirmed',false));
     end if;
    end if;
   end if;
  end loop;
 end loop;
 return jsonb_build_object('batch_id',p_batch_id,'effective',true,
  'allocation_status',case when allocation_count>0 then 'defensibly_allocated' else 'unresolved' end,
  'automatic_allocations',allocation_count,'estimate_replacement_adjustment_micros',adjustment_total);
end $_$;


ALTER FUNCTION "tongs"."_process_openai_organization_reconciliation"("p_batch_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."_process_openai_organization_reconciliation"("p_batch_id" "uuid") IS 'Atomically allocates exact aggregate supplier evidence, closes effective supplier obligations, reconciles aggregate exposure, and appends owner-budget corrections without mutating historical rows.';



CREATE TABLE IF NOT EXISTS "tongs"."private_pricing_revisions" (
    "id" "uuid" NOT NULL,
    "policy_id" "uuid" NOT NULL,
    "revision" integer NOT NULL,
    "previous_revision_id" "uuid",
    "lifecycle_state" "text" NOT NULL,
    "currency" "text" NOT NULL,
    "markup_basis_points" integer,
    "full_cost_ceiling_micros" bigint NOT NULL,
    "failure_cost_ceiling_micros" bigint NOT NULL,
    "customer_price_ceiling_micros" bigint,
    "billable_failure_ceiling_micros" bigint,
    "customer_credit_units" bigint,
    "billable_failure_classes" "jsonb" NOT NULL,
    "free_failure_classes" "jsonb" NOT NULL,
    "included_quantity" "jsonb" NOT NULL,
    "retention_policy" "jsonb" NOT NULL,
    "change_reason" "text" NOT NULL,
    "content_hash" "text" NOT NULL,
    "actor_id" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "unrounded_customer_price_micros" bigint,
    "rounding_adjustment_micros" bigint,
    "settled_customer_price_micros" bigint,
    CONSTRAINT "private_pricing_revisions_billable_failure_classes_check" CHECK (("jsonb_typeof"("billable_failure_classes") = 'array'::"text")),
    CONSTRAINT "private_pricing_revisions_change_reason_check" CHECK ((NULLIF("btrim"("change_reason"), ''::"text") IS NOT NULL)),
    CONSTRAINT "private_pricing_revisions_check" CHECK ((("failure_cost_ceiling_micros" >= 0) AND ("failure_cost_ceiling_micros" <= "full_cost_ceiling_micros"))),
    CONSTRAINT "private_pricing_revisions_check1" CHECK (((("lifecycle_state" = 'draft'::"text") AND ("markup_basis_points" IS NULL) AND ("customer_price_ceiling_micros" IS NULL) AND ("billable_failure_ceiling_micros" IS NULL) AND ("customer_credit_units" IS NULL)) OR (("lifecycle_state" = 'review_ready'::"text") AND ("markup_basis_points" IS NOT NULL) AND ("customer_price_ceiling_micros" IS NOT NULL) AND ("billable_failure_ceiling_micros" IS NOT NULL) AND ("customer_credit_units" IS NOT NULL) AND ("customer_credit_units" >= 0)))),
    CONSTRAINT "private_pricing_revisions_content_hash_check" CHECK (("content_hash" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "private_pricing_revisions_currency_check" CHECK (("currency" ~ '^[A-Z]{3}$'::"text")),
    CONSTRAINT "private_pricing_revisions_free_failure_classes_check" CHECK (("jsonb_typeof"("free_failure_classes") = 'array'::"text")),
    CONSTRAINT "private_pricing_revisions_full_cost_ceiling_micros_check" CHECK (("full_cost_ceiling_micros" >= 0)),
    CONSTRAINT "private_pricing_revisions_included_quantity_check" CHECK (("jsonb_typeof"("included_quantity") = 'object'::"text")),
    CONSTRAINT "private_pricing_revisions_lifecycle_state_check" CHECK (("lifecycle_state" = ANY (ARRAY['draft'::"text", 'review_ready'::"text"]))),
    CONSTRAINT "private_pricing_revisions_markup_basis_points_check" CHECK ((("markup_basis_points" IS NULL) OR ("markup_basis_points" >= 0))),
    CONSTRAINT "private_pricing_revisions_retention_policy_check" CHECK (("jsonb_typeof"("retention_policy") = 'object'::"text")),
    CONSTRAINT "private_pricing_revisions_revision_check" CHECK (("revision" > 0)),
    CONSTRAINT "private_pricing_rounding_consistency" CHECK ((("settled_customer_price_micros" IS NULL) OR (("unrounded_customer_price_micros" IS NOT NULL) AND ("rounding_adjustment_micros" IS NOT NULL) AND ("settled_customer_price_micros" = ("unrounded_customer_price_micros" + "rounding_adjustment_micros")) AND ("settled_customer_price_micros" = "customer_price_ceiling_micros"))))
);


ALTER TABLE "tongs"."private_pricing_revisions" OWNER TO "postgres";


COMMENT ON TABLE "tongs"."private_pricing_revisions" IS 'Owner-only immutable cost-plus revisions. This release seeds no markup and supports no active lifecycle state.';



CREATE OR REPLACE FUNCTION "tongs"."_published_pricing_revision"("p_provider" "text", "p_sku" "text") RETURNS "tongs"."private_pricing_revisions"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
  with candidates as (
    select policy.id as policy_id,
      case policy.scope_kind when 'sku' then 3 when 'provider' then 2 else 1 end as priority
    from tongs.private_pricing_policies policy
    where (policy.scope_kind = 'sku' and lower(policy.provider) = lower(btrim(p_provider))
      and lower(policy.sku) = lower(btrim(p_sku)))
      or (policy.scope_kind = 'provider' and lower(policy.provider) = lower(btrim(p_provider)))
      or policy.scope_kind = 'default'
  ), current_publication as (
    select distinct on (publication.policy_id) publication.*
    from tongs.private_pricing_publications publication
    join candidates candidate on candidate.policy_id = publication.policy_id
    order by publication.policy_id, publication.publication_revision desc
  )
  select revision.*
  from candidates candidate
  join current_publication publication on publication.policy_id = candidate.policy_id
    and publication.action = 'published'
  join tongs.private_pricing_revisions revision on revision.id = publication.pricing_revision_id
  where revision.lifecycle_state = 'review_ready'
  order by candidate.priority desc
  limit 1;
$$;


ALTER FUNCTION "tongs"."_published_pricing_revision"("p_provider" "text", "p_sku" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."_quote_owner_budget_allows"("p_quote_id" "uuid", "p_budget_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
  select exists(
    select 1 from tongs.spending_quote_authority_bindings binding
    join tongs.owner_testing_principals principal on principal.user_id=binding.acting_user_id
      and principal.status='enabled' and principal.revision=binding.owner_principal_revision
    join tongs.owner_operating_budgets budget on budget.id=p_budget_id
      and budget.owner_testing_user_id=binding.acting_user_id
    where binding.quote_id=p_quote_id and binding.payer_kind='owner_testing'
      and tongs._transition_owner_authority_agrees(binding.acting_user_id)
  );
$$;


ALTER FUNCTION "tongs"."_quote_owner_budget_allows"("p_quote_id" "uuid", "p_budget_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."_quote_payer_allows_user"("p_quote_id" "uuid", "p_source_user_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
  select coalesce((select binding.payer_user_id=p_source_user_id
    from tongs.spending_quote_authority_bindings binding where binding.quote_id=p_quote_id),
    (select quote.user_id=p_source_user_id from tongs.customer_spending_quotes quote where quote.id=p_quote_id));
$$;


ALTER FUNCTION "tongs"."_quote_payer_allows_user"("p_quote_id" "uuid", "p_source_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."_read_customer_test_billing_before_openai_text_certification"("p_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare v_user uuid; v_balance bigint;
begin
  if coalesce(auth.role(),'')='service_role' then v_user:=p_user_id; else v_user:=auth.uid(); end if;
  if v_user is null or (coalesce(auth.role(),'')<>'service_role' and p_user_id is not null and p_user_id<>v_user) then raise exception 'customer required' using errcode='42501'; end if;
  select coalesce(sum(quantity_delta),0) into v_balance from tongs.accounting_journal_entries where user_id=v_user and account_code='test_customer_credits';
  return jsonb_build_object('contract_version','forge.customer-test-billing.v1','stripe_mode','test','test_credit_balance',v_balance,
    'live_provider_eligible',false,'live_revenue',false,
    'deposits',(select coalesce(jsonb_agg(jsonb_build_object('deposit_id',d.id,'pack_id',d.pack_id,'currency',d.currency,'gross_amount_micros',d.gross_amount_micros,'credit_units',d.credit_units,'received_at',d.received_at,'label','Stripe Test') order by d.received_at desc),'[]'::jsonb) from tongs.customer_deposits d where d.user_id=v_user and d.stripe_mode='test'),
    'receipts',(select coalesce(jsonb_agg(jsonb_build_object('operation_id',r.operation_id,'customer_charge_micros',s.customer_charge_micros,'outcome',s.outcome,'settled_at',s.settled_at,'execution_kind','simulated_test') order by s.settled_at desc),'[]'::jsonb) from tongs.test_funding_reservations r join tongs.test_paid_execution_settlements s on s.reservation_id=r.id where r.user_id=v_user));
end $$;


ALTER FUNCTION "tongs"."_read_customer_test_billing_before_openai_text_certification"("p_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."_read_customer_test_billing_before_openai_text_certification"("p_user_id" "uuid") IS 'Customer-safe Stripe Test funding and simulated receipt view. Never authorizes a live provider or reports Live revenue.';



CREATE OR REPLACE FUNCTION "tongs"."_read_owner_billing_console_before_rounded_customer_ceiling"("p_limit" integer DEFAULT 250) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_limit integer := least(greatest(coalesce(p_limit, 250), 1), 2000);
  v_control tongs.paid_execution_control_revisions%rowtype;
  v_rollout tongs.runway_execution_rollout_revisions%rowtype;
  v_rules jsonb;
  v_pricing jsonb;
  v_operations jsonb;
  v_funding jsonb;
begin
  if coalesce(auth.role(), '') <> 'service_role'
     and (v_actor is null or not tongs.is_platform_operator(v_actor)) then
    raise exception 'platform operator required' using errcode = '42501';
  end if;
  select * into v_control from tongs._current_paid_execution_control();
  select * into v_rollout from tongs._current_runway_execution_rollout();
  select coalesce(jsonb_agg(to_jsonb(rule_row) order by rule_row.revision desc), '[]'::jsonb)
  into v_rules from (
    select id, revision, default_markup_basis_points, overrides_json,
      change_reason, content_hash, created_at
    from tongs.private_markup_rule_revisions order by revision desc limit v_limit
  ) rule_row;
  select coalesce(jsonb_agg(to_jsonb(price_row) order by price_row.created_at desc), '[]'::jsonb)
  into v_pricing from (
    select policy.id as policy_id, policy.policy_code, policy.scope_kind,
      policy.provider, policy.sku, revision.id as pricing_revision_id,
      revision.revision, revision.lifecycle_state, revision.currency,
      revision.markup_basis_points,
      revision.full_cost_ceiling_micros, revision.failure_cost_ceiling_micros,
      revision.customer_price_ceiling_micros, revision.billable_failure_ceiling_micros,
      revision.customer_credit_units, revision.billable_failure_classes,
      revision.free_failure_classes, revision.included_quantity, revision.retention_policy,
      revision.change_reason, revision.created_at,
      source.markup_rule_revision_id,
      coalesce((select publication.action from tongs.private_pricing_publications publication
        where publication.policy_id = policy.id order by publication.publication_revision desc limit 1),
        'unpublished') as publication_state,
      coalesce((select jsonb_agg(to_jsonb(component) order by component.ordinal)
        from tongs.private_pricing_cost_components component
        where component.pricing_revision_id = revision.id), '[]'::jsonb) as cost_components,
      revision.customer_price_ceiling_micros - revision.full_cost_ceiling_micros
        as expected_contribution_profit_micros,
      case when coalesce(revision.customer_price_ceiling_micros, 0) = 0 then null
        else round(100::numeric *
          (revision.customer_price_ceiling_micros - revision.full_cost_ceiling_micros)::numeric /
          revision.customer_price_ceiling_micros::numeric, 4) end as expected_contribution_margin_percentage
    from tongs.private_pricing_revisions revision
    join tongs.private_pricing_policies policy on policy.id = revision.policy_id
    left join tongs.private_pricing_revision_markup_sources source
      on source.pricing_revision_id = revision.id
    order by revision.created_at desc limit v_limit
  ) price_row;
  select coalesce(jsonb_agg(to_jsonb(operation_row) order by operation_row.created_at desc), '[]'::jsonb)
  into v_operations from (
    select reservation.id as reservation_id, reservation.operation_id, reservation.user_id,
      reservation.funding_source_type, reservation.currency,
      reservation.reserved_customer_charge_micros,
      reservation.reserved_credit_units, reservation.reserved_wholesale_spend_micros,
      tongs._funding_reservation_state(reservation.id) as reservation_state,
      quote.normal_maximum_charge_micros, quote.billable_failure_maximum_charge_micros,
      settlement.customer_charge_micros as recognized_revenue_micros,
      case when reservation.funding_source_type = 'customer_deposit'
        then consumption.allocated_processor_fee_micros else 0 end as allocated_processor_fee_micros,
      receipt.direct_provider_estimated_micros,
      receipt.direct_provider_actual_micros,
      receipt.supporting_actual_micros,
      receipt.supporting_cost_status,
      case
        when receipt.supporting_cost_status = 'finalized'
          and receipt.direct_provider_actual_micros is not null
          and receipt.supporting_actual_micros is not null then 'confirmed'
        when receipt.direct_provider_estimated_micros is not null then 'estimated_unresolved'
        else 'unresolved' end as expense_coverage,
      case when settlement.customer_charge_micros is not null
          and receipt.supporting_cost_status = 'finalized'
          and receipt.direct_provider_actual_micros is not null
          and receipt.supporting_actual_micros is not null
        then settlement.customer_charge_micros - receipt.direct_provider_actual_micros
          - receipt.supporting_actual_micros
          - case when reservation.funding_source_type = 'customer_deposit'
            then coalesce(consumption.allocated_processor_fee_micros, 0) else 0 end
        else null end as contribution_profit_micros,
      receipt.provider_task_id, receipt.reconciled_at,
      binding.model, binding.duration_seconds, binding.ratio,
      reservation.created_at
    from tongs.funding_reservations reservation
    join tongs.customer_spending_quotes quote on quote.id = reservation.quote_id
    left join lateral (
      select event.* from tongs.funding_reservation_events event
      where event.reservation_id = reservation.id and event.event_type = 'settled'
      order by event.sequence desc limit 1
    ) settlement on true
    left join tongs.customer_deposit_consumptions consumption
      on consumption.deposit_id = reservation.funding_source_id
      and consumption.operation_id = reservation.operation_id
      and reservation.funding_source_type = 'customer_deposit'
    left join tongs.runway_funding_bindings binding on binding.reservation_id = reservation.id
    left join tongs.runway_execution_reconciliation_receipts receipt
      on receipt.reservation_id = reservation.id
    order by reservation.created_at desc limit v_limit
  ) operation_row;
  v_funding := jsonb_build_object(
    'customer_deposits', (select coalesce(jsonb_agg(to_jsonb(row_data) order by row_data.received_at desc), '[]'::jsonb)
      from (select id, user_id, stripe_mode, stripe_session_id, stripe_payment_intent_id,
        pack_id, currency, gross_amount_micros, credit_units, received_at
        from tongs.customer_deposits order by received_at desc limit v_limit) row_data),
    'subscription_receipts', (select coalesce(jsonb_agg(to_jsonb(row_data) order by row_data.received_at desc), '[]'::jsonb)
      from (select id, user_id, stripe_mode, stripe_invoice_id, stripe_subscription_id,
        purchase_type, plan_item_id, currency, gross_amount_micros, period_start, period_end, received_at
        from tongs.subscription_cycle_receipts order by received_at desc limit v_limit) row_data),
    'deposit_consumptions', (select coalesce(jsonb_agg(to_jsonb(row_data) order by row_data.consumed_at desc), '[]'::jsonb)
      from (select id, deposit_id, user_id, operation_id, recognized_revenue_micros,
        credit_units_consumed, allocated_processor_fee_micros, consumed_at
        from tongs.customer_deposit_consumptions order by consumed_at desc limit v_limit) row_data),
    'allowance_consumptions', (select coalesce(jsonb_agg(to_jsonb(row_data) order by row_data.consumed_at desc), '[]'::jsonb)
      from (select id, allowance_grant_id, user_id, operation_id, recognized_revenue_micros,
        entitlement_units_consumed, wholesale_spend_micros, consumed_at
        from tongs.paid_allowance_consumptions order by consumed_at desc limit v_limit) row_data),
    'owner_expenses', (select coalesce(jsonb_agg(to_jsonb(row_data) order by row_data.consumed_at desc), '[]'::jsonb)
      from (select consumption.id, consumption.budget_id, consumption.operation_id,
        budget.provider, budget.route, budget.sku, consumption.expense_amount_micros,
        consumption.currency, 'not_applicable'::text as margin_classification,
        consumption.consumed_at
        from tongs.owner_operating_budget_consumptions consumption
        join tongs.owner_operating_budgets budget on budget.id = consumption.budget_id
        order by consumption.consumed_at desc limit v_limit) row_data)
  );
  return jsonb_build_object(
    'control', to_jsonb(v_control),
    'runway_rollout', to_jsonb(v_rollout),
    'markup_rule_revisions', v_rules,
    'pricing_revisions', v_pricing,
    'operations', v_operations,
    'funding_activity', v_funding,
    'pricing_discrepancies', (select coalesce(jsonb_agg(to_jsonb(discrepancy)
      order by discrepancy.created_at desc), '[]'::jsonb)
      from (select * from tongs.pricing_discrepancies order by created_at desc limit v_limit) discrepancy)
  );
end;
$$;


ALTER FUNCTION "tongs"."_read_owner_billing_console_before_rounded_customer_ceiling"("p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."_read_owner_billing_console_before_rounded_customer_ceiling"("p_limit" integer) IS 'Platform-operator financial read. Contribution profit is null until fulfillment cost coverage is confirmed.';



CREATE OR REPLACE FUNCTION "tongs"."_read_owner_purchase_activity_before_test_ai_deposits"("p_stripe_mode" "text" DEFAULT 'test'::"text", "p_limit" integer DEFAULT 100) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_mode text := lower(btrim(coalesce(p_stripe_mode, '')));
  v_limit integer := least(greatest(coalesce(p_limit, 100), 1), 500);
  v_purchases jsonb;
begin
  if coalesce(auth.role(), '') <> 'service_role'
     and (v_actor is null or not tongs.is_platform_operator(v_actor)) then
    raise exception 'platform operator required' using errcode = '42501';
  end if;
  if v_mode not in ('test', 'live') then
    raise exception 'stripe mode must be test or live' using errcode = '22023';
  end if;

  select coalesce(jsonb_agg(to_jsonb(purchase_row) order by purchase_row.observed_at desc), '[]'::jsonb)
  into v_purchases
  from (
    select
      subscription.stripe_subscription_id as purchase_id,
      subscription.user_id,
      customer.email as customer_email,
      customer.customer_name,
      v_mode as stripe_mode,
      subscription.purchase_type,
      subscription.item_id,
      subscription.interval,
      subscription.status,
      subscription.current_period_start,
      subscription.current_period_end,
      subscription.cancel_at_period_end,
      checkout.stripe_event_id as checkout_event_id,
      nullif(checkout.payload_json #>> '{data,object,id}', '') as checkout_session_id,
      nullif(checkout.payload_json #>> '{data,object,invoice}', '') as stripe_invoice_id,
      nullif(lower(checkout.payload_json #>> '{data,object,payment_status}'), '') as payment_status,
      nullif(lower(checkout.payload_json #>> '{data,object,currency}'), '') as checkout_currency,
      case
        when checkout.payload_json #>> '{data,object,amount_total}' ~ '^[0-9]+$'
          then (checkout.payload_json #>> '{data,object,amount_total}')::bigint
        else null
      end as checkout_amount_minor,
      checkout.processed_at as checkout_processed_at,
      receipt.id as accounting_receipt_id,
      receipt.stripe_event_id as accounting_event_id,
      receipt.gross_amount_micros as accounted_cash_micros,
      receipt.currency as accounting_currency,
      receipt.received_at as accounting_received_at,
      coalesce(allowance.allowance_grant_count, 0) as allowance_grant_count,
      coalesce(allowance.allocated_revenue_micros, 0) as allocated_revenue_micros,
      coalesce(allowance.maximum_wholesale_spend_micros, 0) as maximum_wholesale_spend_micros,
      coalesce(recognized.recognized_revenue_micros, 0) as recognized_revenue_micros,
      case
        when receipt.id is not null then 'cycle_receipt_recorded'
        when checkout.stripe_event_id is not null
          and nullif(checkout.payload_json #>> '{data,object,invoice}', '') is not null
          then 'invoice_receipt_pending'
        when checkout.stripe_event_id is not null then 'checkout_recorded'
        else 'subscription_recorded'
      end as accounting_state,
      case
        when v_mode = 'test' then false
        when receipt.id is null then false
        else coalesce(allowance.allowance_grant_count, 0) > 0
      end as live_funding_eligible,
      event_summary.signed_webhook_events,
      coalesce(checkout.processed_at, mode_event.processed_at, subscription.updated_at) as observed_at
    from tongs.billing_subscriptions subscription
    join tongs.billing_customers customer on customer.user_id = subscription.user_id
    join lateral (
      select event.processed_at
      from tongs.billing_events event
      where event.stripe_subscription_id = subscription.stripe_subscription_id
        and event.livemode = (v_mode = 'live')
      order by event.processed_at desc
      limit 1
    ) mode_event on true
    left join lateral (
      select event.stripe_event_id, event.payload_json, event.processed_at
      from tongs.billing_events event
      where event.stripe_subscription_id = subscription.stripe_subscription_id
        and event.livemode = (v_mode = 'live')
        and event.event_type = 'checkout.session.completed'
      order by event.processed_at desc
      limit 1
    ) checkout on true
    left join lateral (
      select cycle.*
      from tongs.subscription_cycle_receipts cycle
      where cycle.stripe_subscription_id = subscription.stripe_subscription_id
        and cycle.stripe_mode = v_mode
      order by cycle.received_at desc
      limit 1
    ) receipt on true
    left join lateral (
      select count(*)::integer as allowance_grant_count,
        coalesce(sum(grant_row.allocated_revenue_micros), 0)::bigint as allocated_revenue_micros,
        coalesce(sum(grant_row.maximum_wholesale_spend_micros), 0)::bigint as maximum_wholesale_spend_micros
      from tongs.paid_allowance_grants grant_row
      where grant_row.receipt_id = receipt.id
    ) allowance on true
    left join lateral (
      select coalesce(sum(consumption.recognized_revenue_micros), 0)::bigint as recognized_revenue_micros
      from tongs.paid_allowance_consumptions consumption
      join tongs.paid_allowance_grants grant_row on grant_row.id = consumption.allowance_grant_id
      where grant_row.receipt_id = receipt.id
    ) recognized on true
    join lateral (
      select coalesce(jsonb_agg(jsonb_build_object(
        'event_id', event.stripe_event_id,
        'event_type', event.event_type,
        'processed_at', event.processed_at
      ) order by event.processed_at), '[]'::jsonb) as signed_webhook_events
      from tongs.billing_events event
      where event.stripe_subscription_id = subscription.stripe_subscription_id
        and event.livemode = (v_mode = 'live')
    ) event_summary on true
    order by coalesce(checkout.processed_at, mode_event.processed_at, subscription.updated_at) desc
    limit v_limit
  ) purchase_row;

  return jsonb_build_object(
    'contract_version', 'forge.owner-purchase-activity.v1',
    'stripe_mode', v_mode,
    'purchases', v_purchases,
    'contains_wholesale_costs', false,
    'creates_accounting_entries', false,
    'spending_activation_changed', false
  );
end;
$_$;


ALTER FUNCTION "tongs"."_read_owner_purchase_activity_before_test_ai_deposits"("p_stripe_mode" "text", "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."_read_owner_purchase_activity_before_test_ai_deposits"("p_stripe_mode" "text", "p_limit" integer) IS 'Platform-operator-only sanitized Test/Live purchase read model. Never creates funding, allowance, revenue, or expense entries.';



CREATE OR REPLACE FUNCTION "tongs"."_reconcile_runway_execution_before_success_finalization"("p_operation_id" "text", "p_direct_provider_actual_micros" bigint, "p_supporting_actual_micros" bigint, "p_settlement_id" "uuid", "p_settlement_key" "text", "p_evidence_json" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_binding tongs.runway_funding_bindings%rowtype;
  v_receipt tongs.runway_execution_reconciliation_receipts%rowtype;
  v_reservation tongs.funding_reservations%rowtype;
  v_total bigint;
  v_result jsonb;
begin
  perform tongs._require_pricing_service_role();
  if nullif(btrim(coalesce(p_operation_id, '')), '') is null
     or p_direct_provider_actual_micros < 0 or p_supporting_actual_micros < 0 or p_settlement_id is null
     or length(btrim(coalesce(p_settlement_key, ''))) < 8
     or jsonb_typeof(coalesce(p_evidence_json, 'null'::jsonb)) <> 'object' then
    raise exception 'invalid Runway reconciliation' using errcode = '22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('runway-reconcile:' || btrim(p_operation_id), 0));
  select * into v_binding from tongs.runway_funding_bindings where operation_id = btrim(p_operation_id);
  select * into v_receipt from tongs.runway_execution_reconciliation_receipts
    where operation_id = btrim(p_operation_id) for update;
  if v_binding.operation_id is null or v_receipt.operation_id is null then
    raise exception 'completed funded Runway operation not found' using errcode = 'P0002';
  end if;
  if v_receipt.supporting_cost_status = 'finalized' then
    if v_receipt.supporting_actual_micros <> p_supporting_actual_micros then
      raise exception 'Runway reconciliation replay conflict' using errcode = '23505';
    end if;
    return coalesce(v_receipt.settlement_result_json, '{}'::jsonb) || jsonb_build_object('replay', true);
  end if;
  v_total := p_direct_provider_actual_micros + p_supporting_actual_micros;
  if p_direct_provider_actual_micros > v_binding.direct_provider_ceiling_micros
     or p_supporting_actual_micros > v_binding.supporting_cost_ceiling_micros
     or v_total > v_binding.total_cost_ceiling_micros then
    insert into tongs.pricing_discrepancies(
      id, reservation_id, discrepancy_key, discrepancy_type,
      quoted_ceiling_micros, observed_amount_micros, evidence_json
    ) values (
      gen_random_uuid(), v_binding.reservation_id,
      btrim(p_settlement_key) || ':runway-reconciliation-overrun',
      'wholesale_ceiling_overrun', v_binding.total_cost_ceiling_micros, v_total,
      coalesce(p_evidence_json, '{}'::jsonb)
    ) on conflict (discrepancy_key) do nothing;
    return jsonb_build_object('settled', false, 'pricing_discrepancy', true,
      'reservation_retained', true, 'customer_overcharge_allowed', false,
      'quoted_ceiling_micros', v_binding.total_cost_ceiling_micros,
      'observed_amount_micros', v_total);
  end if;
  select * into v_reservation from tongs.funding_reservations where id = v_binding.reservation_id;
  if v_reservation.funding_source_type = 'owner_budget' then
    v_result := tongs.settle_owner_operation(
      v_binding.reservation_id, p_settlement_id, btrim(p_settlement_key),
      'success', null, v_total,
      coalesce(p_evidence_json, '{}'::jsonb) || jsonb_build_object(
        'provider', 'runway', 'direct_provider_actual_micros', p_direct_provider_actual_micros,
        'supporting_actual_micros', p_supporting_actual_micros)
    );
  else
    v_result := tongs.settle_operation(
      v_binding.reservation_id, p_settlement_id, btrim(p_settlement_key),
      'success', null, v_total,
      coalesce(p_evidence_json, '{}'::jsonb) || jsonb_build_object(
        'provider', 'runway', 'direct_provider_actual_micros', p_direct_provider_actual_micros,
        'supporting_actual_micros', p_supporting_actual_micros)
    );
  end if;
  update tongs.runway_execution_reconciliation_receipts
  set supporting_cost_status = 'finalized', direct_provider_actual_micros = p_direct_provider_actual_micros,
      supporting_actual_micros = p_supporting_actual_micros,
      settlement_result_json = v_result, reconciled_at = now()
  where operation_id = v_binding.operation_id;
  return v_result || jsonb_build_object('replay', false,
    'direct_provider_actual_micros', p_direct_provider_actual_micros,
    'supporting_actual_micros', p_supporting_actual_micros,
    'actual_fulfillment_cost_micros', v_total);
end;
$$;


ALTER FUNCTION "tongs"."_reconcile_runway_execution_before_success_finalization"("p_operation_id" "text", "p_direct_provider_actual_micros" bigint, "p_supporting_actual_micros" bigint, "p_settlement_id" "uuid", "p_settlement_key" "text", "p_evidence_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."_record_runway_aggregate_reconciliation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
begin
 if old.supporting_cost_status='pending' and new.supporting_cost_status='finalized' then
  perform tongs.record_paid_operation_aggregate_outcome(
    new.reservation_id,new.operation_id||':aggregate-authoritative-reconciliation','reconciled',
    new.direct_provider_actual_micros+new.supporting_actual_micros,null,
    coalesce(new.evidence_json,'{}'::jsonb)||jsonb_build_object('authoritative',true,'provider','runway','provider_task_id',new.provider_task_id));
 end if;
 return new;
end $$;


