CREATE OR REPLACE FUNCTION "tongs"."_reserve_customer_runway_quote_before_gen45_customer_test"("p_quote_id" "uuid", "p_reservation_id" "uuid", "p_idempotency_key" "text", "p_operation_fingerprint" "text", "p_model" "text", "p_duration_seconds" integer, "p_ratio" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_control tongs.paid_execution_control_revisions%rowtype;
  v_quote tongs.customer_spending_quotes%rowtype;
  v_existing tongs.funding_reservations%rowtype;
  v_funding jsonb;
  v_result jsonb;
  v_binding jsonb;
begin
  perform tongs._require_pricing_service_role();
  select * into v_control from tongs._current_paid_execution_control();
  if not v_control.pricing_activation_enabled or not v_control.customer_settlement_enabled
     or not v_control.provider_execution_enabled then
    raise exception 'customer spending is not activated' using errcode = '42501';
  end if;
  select * into v_quote from tongs.customer_spending_quotes where id = p_quote_id;
  if not found then raise exception 'spending quote not found' using errcode = 'P0002'; end if;
  if v_quote.request_fingerprint <> p_operation_fingerprint then
    raise exception 'Runway quote fingerprint mismatch' using errcode = '42501';
  end if;
  select * into v_existing from tongs.funding_reservations where quote_id = p_quote_id;
  if found then
    if v_existing.id <> p_reservation_id or v_existing.idempotency_key <> btrim(p_idempotency_key) then
      raise exception 'operation reservation replay conflict' using errcode = '23505';
    end if;
    v_funding := jsonb_build_object('eligible', true,
      'funding_source', v_existing.funding_source_type,
      'funding_source_id', v_existing.funding_source_id,
      'customer_label', case v_existing.funding_source_type
        when 'customer_deposit' then 'Verified AI credit purchase'
        when 'paid_allowance' then 'Paid-plan allowance'
        else 'Verified funding' end);
  else
    v_funding := tongs._select_customer_funding_for_quote(p_quote_id);
    if not coalesce((v_funding->>'eligible')::boolean, false) then
      raise exception 'insufficient verified funding' using errcode = 'P0001';
    end if;
  end if;
  v_result := tongs.reserve_operation(
    p_reservation_id, p_quote_id, v_funding->>'funding_source',
    (v_funding->>'funding_source_id')::uuid, p_idempotency_key
  );
  v_binding := tongs.bind_runway_funding_reservation(
    v_quote.operation_id, p_operation_fingerprint, p_reservation_id, v_quote.user_id,
    v_quote.workspace_id, p_model, p_duration_seconds, p_ratio
  );
  return jsonb_build_object(
    'reservation_id', p_reservation_id,
    'state', v_result->>'state',
    'replay', coalesce((v_result->>'replay')::boolean, false),
    'funding_source', v_funding->>'funding_source',
    'funding_label', v_funding->>'customer_label',
    'provider_execution_authorized', false,
    'binding_replay', coalesce((v_binding->>'replay')::boolean, false)
  );
end;
$$;


ALTER FUNCTION "tongs"."_reserve_customer_runway_quote_before_gen45_customer_test"("p_quote_id" "uuid", "p_reservation_id" "uuid", "p_idempotency_key" "text", "p_operation_fingerprint" "text", "p_model" "text", "p_duration_seconds" integer, "p_ratio" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."_resolve_spending_authority"("p_user_id" "uuid", "p_workspace_id" "uuid", "p_route_code" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_workspace tongs.workspaces%rowtype;
  v_pref tongs.ai_funding_preference_revisions%rowtype;
  v_account tongs.organization_funding_account_revisions%rowtype;
  v_permission tongs.organization_shared_spend_permission_revisions%rowtype;
  v_owner_authority jsonb;
begin
  perform tongs._require_pricing_service_role();
  select * into v_workspace from tongs.workspaces where id=p_workspace_id;
  if not found or not exists(select 1 from tongs.workspace_members wm where wm.workspace_id=p_workspace_id and wm.user_id=p_user_id) then
    raise exception 'workspace membership required' using errcode='42501'; end if;
  select * into v_pref from tongs.ai_funding_preference_revisions where user_id=p_user_id and workspace_id=p_workspace_id order by revision desc limit 1;
  if not found or v_pref.payer_kind='personal' then
    return jsonb_build_object('payer_kind','personal','payer_user_id',p_user_id,'preference_revision_id',v_pref.id);
  end if;
  if v_pref.payer_kind='owner_testing' then
    v_owner_authority := tongs.resolve_transition_owner_authority(p_user_id);
    if not coalesce((v_owner_authority->>'eligible')::boolean,false) then
      raise exception 'owner-testing authority is no longer available' using errcode='42501'; end if;
    return jsonb_build_object('payer_kind','owner_testing','payer_user_id',p_user_id,
      'preference_revision_id',v_pref.id,
      'account_authority_revision',(v_owner_authority->>'account_authority_revision')::integer,
      'owner_principal_revision',(v_owner_authority->>'legacy_principal_revision')::integer,
      'owner_authority_mode','canonical_legacy_dual_read');
  end if;
  if v_workspace.org_id is distinct from v_pref.org_id or not exists(select 1 from tongs.org_members om where om.org_id=v_pref.org_id and om.user_id=p_user_id) then
    raise exception 'organization funding membership required' using errcode='42501'; end if;
  select * into v_account from tongs.organization_funding_account_revisions where org_id=v_pref.org_id order by revision desc limit 1;
  select * into v_permission from tongs.organization_shared_spend_permission_revisions where org_id=v_pref.org_id and member_user_id=p_user_id order by revision desc limit 1;
  if v_account.status<>'active' or v_permission.status<>'allowed'
     or (cardinality(v_permission.route_codes)>0 and not p_route_code=any(v_permission.route_codes)) then
    raise exception 'organization shared funding is not authorized for this operation' using errcode='42501'; end if;
  return jsonb_build_object('payer_kind','organization_shared','payer_user_id',v_account.payer_user_id,'org_id',v_pref.org_id,
    'preference_revision_id',v_pref.id,'organization_account_revision_id',v_account.id,
    'organization_permission_revision_id',v_permission.id,'currency',v_account.currency);
end $$;


ALTER FUNCTION "tongs"."_resolve_spending_authority"("p_user_id" "uuid", "p_workspace_id" "uuid", "p_route_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."_restricted_beta_policy_commitment"("p_policy_revision_id" "uuid") RETURNS TABLE("committed_micros" bigint, "outstanding_count" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
 with selected_policy as (
  select * from tongs.restricted_beta_policy_revisions where id=p_policy_revision_id
 ), facts as (
  select h.*,
   (select e.event_type from tongs.restricted_beta_exposure_events e where e.hold_id=h.id order by e.sequence desc limit 1) last_type,
   (select e.remaining_exposure_micros from tongs.restricted_beta_exposure_events e where e.hold_id=h.id and e.remaining_exposure_micros is not null order by e.sequence desc limit 1) remaining_exposure,
   (select e.supplier_obligation_micros from tongs.restricted_beta_exposure_events e where e.hold_id=h.id and e.event_type='reconciled' order by e.sequence desc limit 1) reconciled_supplier,
   (select e.supplier_obligation_micros from tongs.restricted_beta_exposure_events e where e.hold_id=h.id and e.event_type='reconciliation_partial' order by e.sequence desc limit 1) partial_supplier,
   (select e.created_at from tongs.restricted_beta_exposure_events e where e.hold_id=h.id and e.event_type='attempt_started' order by e.sequence limit 1) incurred_at,
   (select coalesce(sum(e.supplier_recovery_micros),0) from tongs.restricted_beta_exposure_events e where e.hold_id=h.id and e.event_type='supplier_recovery') recovered
  from tongs.restricted_beta_exposure_holds h
  join tongs.restricted_beta_policy_revisions old_policy on old_policy.id=h.policy_revision_id
  where old_policy.environment=(select environment from selected_policy)
 ), amounts as (
  select f.*,
   case
    when f.last_type='released' then 0
    when f.remaining_exposure is not null then greatest(f.remaining_exposure-f.recovered,0)
    when f.reconciled_supplier is not null then case
      when coalesce(f.incurred_at,f.created_at)>=now()-make_interval(secs=>(select rolling_window_seconds from selected_policy))
      then greatest(f.reconciled_supplier-f.recovered,0) else 0 end
    when f.partial_supplier is not null then greatest(f.partial_supplier-f.recovered,0)+
      f.supporting_exposure_ceiling_micros+f.tail_exposure_ceiling_micros+
      f.unreconciled_exposure_ceiling_micros+f.retry_exposure_ceiling_micros
    else f.supplier_exposure_ceiling_micros+f.supporting_exposure_ceiling_micros+
      f.tail_exposure_ceiling_micros+f.unreconciled_exposure_ceiling_micros+
      f.retry_exposure_ceiling_micros
   end amount
  from facts f
 ), opening as (
  select coalesce(sum(amount_micros),0)::bigint amount
  from tongs.legacy_supplier_opening_commitments
  where environment=(select environment from selected_policy) and status='unresolved'
 )
 select (coalesce(sum(amount),0)+(select amount from opening))::bigint,
   coalesce(count(*) filter(where amount>0 and last_type<>'reconciled'),0)::bigint
 from amounts;
$$;


ALTER FUNCTION "tongs"."_restricted_beta_policy_commitment"("p_policy_revision_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."_restricted_beta_policy_commitment"("p_policy_revision_id" "uuid") IS 'Environment-wide commitment across revisions: unresolved supplier obligations survive lease expiry and window rollover; reconciled realized spend ages out only after the configured window.';



CREATE OR REPLACE FUNCTION "tongs"."_restricted_beta_policy_execution_concurrency"("p_policy_revision_id" "uuid") RETURNS bigint
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
  with selected_policy as (
    select environment
    from tongs.restricted_beta_policy_revisions
    where id=p_policy_revision_id
  ), latest as (
    select (
      select e.event_type
      from tongs.restricted_beta_exposure_events e
      where e.hold_id=h.id
      order by e.sequence desc
      limit 1
    ) as event_type
    from tongs.restricted_beta_exposure_holds h
    join tongs.restricted_beta_policy_revisions p on p.id=h.policy_revision_id
    where p.environment=(select environment from selected_policy)
  )
  select coalesce(count(*) filter (
    where event_type in ('reserved','attempt_started','ambiguous')
  ),0)::bigint
  from latest;
$$;


ALTER FUNCTION "tongs"."_restricted_beta_policy_execution_concurrency"("p_policy_revision_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."_restricted_beta_policy_execution_concurrency"("p_policy_revision_id" "uuid") IS 'Counts active provider execution holds only. Retained terminal supplier exposure remains committed financially without consuming an execution concurrency slot.';



CREATE OR REPLACE FUNCTION "tongs"."_sanitize_keyword"("raw" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'tongs', 'pg_temp'
    AS $$
  select
    case
      when raw is null then ''
      else
        -- lowercase, keep a-z0-9 and hyphen/underscore, collapse spaces to hyphen
        regexp_replace(
          regexp_replace(lower(raw), '[^a-z0-9 _-]+', '', 'g'),
          '\s+', '-', 'g'
        )
    end
$$;


ALTER FUNCTION "tongs"."_sanitize_keyword"("raw" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."_schedule_owner_hearth_tail"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare op tongs.owner_hearth_operation_authorizations%rowtype; tail tongs.owner_hearth_tail_authorizations%rowtype; class text; start_at timestamptz; seq integer;
begin
 if new.event_type<>'settled' then return new; end if;
 select * into op from tongs.owner_hearth_operation_authorizations where reservation_id=new.reservation_id;
 if not found then return new; end if;
 select * into tail from tongs.owner_hearth_tail_authorizations where owner_user_id=op.owner_user_id and workspace_id=op.workspace_id order by created_at desc limit 1;
 if not found then return new; end if;
 start_at:=new.created_at+interval '30 days';
 foreach class in array case when new.evidence_json->>'operation_outcome'='success'
   then array['canonical_content','provider_evidence'] else array['provider_evidence'] end loop
  insert into tongs.owner_hearth_tail_periods(id,tail_authorization_id,reservation_id,artifact_class,coverage_start,coverage_end,monthly_limit_micros,cost_status,evidence_json)
  values(extensions.uuid_generate_v5(new.reservation_id,'owner-tail:'||class),tail.id,new.reservation_id,class,start_at,start_at+interval '12 months',
   tail.monthly_limit_micros,'allocated_estimate',jsonb_build_object('first_period_ends_at',start_at,'no_overlap',true,'replacement_rate_micros_per_mib_month',123))
  on conflict(reservation_id,artifact_class,coverage_start) do nothing;
 end loop;
 select coalesce(max(sequence),0)+1 into seq from tongs.owner_hearth_tail_events where tail_authorization_id=tail.id;
 insert into tongs.owner_hearth_tail_events(id,tail_authorization_id,sequence,event_key,event_type,evidence_json)
 values(gen_random_uuid(),tail.id,seq,'owner-hearth-tail:'||tail.id::text||':artifact:'||new.reservation_id::text,'artifact_covered',
  jsonb_build_object('reservation_id',new.reservation_id,'coverage_start',start_at,'coverage_end',start_at+interval '12 months','first_30_days_excluded',true))
 on conflict(event_key) do nothing;
 return new;
end $$;


ALTER FUNCTION "tongs"."_schedule_owner_hearth_tail"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."_select_customer_funding_for_quote"("p_quote_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_quote tongs.customer_spending_quotes%rowtype;
  v_authority tongs.spending_quote_authority_bindings%rowtype;
  v_source record;
  v_control tongs.paid_execution_control_revisions%rowtype;
begin
  perform tongs._require_pricing_service_role();
  select * into v_quote from tongs.customer_spending_quotes where id = p_quote_id;
  if not found then raise exception 'spending quote not found' using errcode = 'P0002'; end if;
  if v_quote.financial_environment not in ('test', 'live') then
    return jsonb_build_object('eligible', false, 'funding_source', 'none',
      'funding_environment', v_quote.financial_environment,
      'customer_label', 'Historical quote has no spendable financial environment');
  end if;
  select * into v_authority from tongs.spending_quote_authority_bindings where quote_id = p_quote_id;
  if not found then
    v_authority.acting_user_id := v_quote.user_id;
    v_authority.payer_kind := 'personal';
    v_authority.payer_user_id := v_quote.user_id;
  end if;

  if v_authority.payer_kind = 'owner_testing' then
    select * into v_control from tongs._current_paid_execution_control();
    select 'owner_budget'::text source_type, budget.id source_id,
      'owner_internal'::text funding_environment,
      'Private owner testing (no customer charge)'::text customer_label,
      budget.period_end sort_time
    into v_source
    from tongs.owner_operating_budgets budget
    join lateral (
      select revision.* from tongs.owner_operating_budget_revisions revision
      where revision.budget_id = budget.id order by revision.revision desc limit 1
    ) latest on true
    left join lateral tongs._active_funding_hold('owner_budget', budget.id) held on true
    where v_control.owner_budget_spending_enabled
      and budget.owner_testing_user_id = v_authority.acting_user_id
      and latest.status = 'active' and latest.maximum_amount_micros is not null
      and now() >= budget.period_start and now() < budget.period_end
      and budget.currency = v_quote.currency
      and (budget.workspace_id is null or budget.workspace_id = v_quote.workspace_id)
      and (budget.provider is null or lower(budget.provider) = 'openai')
      and (budget.route is null or budget.route = v_quote.tool)
      and latest.maximum_amount_micros - held.wholesale_spend_micros >= v_quote.full_cost_ceiling_micros
    order by budget.period_end asc limit 1;
  else
    select candidate.* into v_source from (
      select 'customer_deposit'::text source_type, deposit.id source_id,
        deposit.stripe_mode funding_environment,
        case when v_authority.payer_kind = 'organization_shared'
          then 'Organization shared purchased credits'
          else 'Verified Forge Credit purchase' end customer_label,
        deposit.received_at sort_time
      from tongs.customer_deposits deposit
      join tongs.customer_deposit_processor_fees fee on fee.deposit_id = deposit.id
      left join lateral (
        select coalesce(sum(c.recognized_revenue_micros), 0)::bigint used_charge,
          coalesce(sum(c.credit_units_consumed), 0)::bigint used_units
        from tongs.customer_deposit_consumptions c where c.deposit_id = deposit.id
      ) used on true
      left join lateral (
        select coalesce(sum(r.liability_release_micros), 0)::bigint refunded_charge,
          coalesce(sum(r.refunded_credit_units), 0)::bigint refunded_units
        from tongs.customer_deposit_refunds r where r.deposit_id = deposit.id
      ) refunded on true
      left join lateral tongs._active_funding_hold('customer_deposit', deposit.id) held on true
      where deposit.user_id = v_authority.payer_user_id
        and deposit.stripe_mode = v_quote.financial_environment
        and deposit.currency = v_quote.currency
        and tongs._available_deposit_value_micros(deposit.id) >= v_quote.normal_maximum_charge_micros
        and tongs._available_deposit_credit_units(deposit.id) >= v_quote.customer_credit_units
      union all
      select 'paid_allowance', allowance.id, allowance.financial_environment,
        case when v_authority.payer_kind = 'organization_shared'
          then 'Organization shared paid allowance' else 'Paid-plan allowance' end,
        allowance.period_end
      from tongs.paid_allowance_grants allowance
      left join lateral (
        select coalesce(sum(c.recognized_revenue_micros), 0)::bigint used_charge,
          coalesce(sum(c.entitlement_units_consumed), 0)::bigint used_units,
          coalesce(sum(c.wholesale_spend_micros), 0)::bigint used_wholesale
        from tongs.paid_allowance_consumptions c where c.allowance_grant_id = allowance.id
      ) used on true
      left join lateral tongs._active_funding_hold('paid_allowance', allowance.id) held on true
      where allowance.user_id = v_authority.payer_user_id
        and allowance.financial_environment = v_quote.financial_environment
        and allowance.currency = v_quote.currency
        and now() >= allowance.period_start and now() < allowance.period_end
        and not exists (
          select 1 from tongs.subscription_cycle_adjustments adjustment
          where adjustment.receipt_id = allowance.receipt_id
        )
        and allowance.allocated_revenue_micros - used.used_charge
          - held.customer_charge_micros >= v_quote.normal_maximum_charge_micros
        and allowance.entitlement_units - used.used_units
          - held.credit_units >= v_quote.customer_credit_units
        and allowance.maximum_wholesale_spend_micros - used.used_wholesale
          - held.wholesale_spend_micros >= v_quote.full_cost_ceiling_micros
      union all
      select 'beta_grant', beta.id, beta.financial_environment,
        'Forge Credits', beta.granted_at
      from tongs.beta_credit_grants beta
      left join lateral (
        select coalesce(sum(c.customer_value_micros), 0)::bigint used_charge,
          coalesce(sum(c.credit_units_consumed), 0)::bigint used_units,
          coalesce(sum(c.wholesale_spend_micros), 0)::bigint used_wholesale
        from tongs.beta_credit_consumptions c where c.grant_id = beta.id
      ) used on true
      left join lateral tongs._active_funding_hold('beta_grant', beta.id) held on true
      where beta.user_id = v_authority.payer_user_id
        and beta.workspace_id = v_quote.workspace_id
        and beta.financial_environment = v_quote.financial_environment
        and beta.customer_value_micros - used.used_charge
          - held.customer_charge_micros >= v_quote.normal_maximum_charge_micros
        and beta.credit_units - used.used_units
          - held.credit_units >= v_quote.customer_credit_units
        and beta.maximum_wholesale_capacity_micros - used.used_wholesale
          - held.wholesale_spend_micros >= v_quote.full_cost_ceiling_micros
    ) candidate
    order by case candidate.source_type
      when 'customer_deposit' then 1 when 'paid_allowance' then 2 else 3 end,
      candidate.sort_time asc limit 1;
  end if;
  if not found then
    return jsonb_build_object(
      'eligible', false,
      'funding_source', 'none',
      'funding_environment', v_quote.financial_environment,
      'payer_kind', v_authority.payer_kind,
      'customer_label', case when v_authority.payer_kind = 'owner_testing'
        then 'Owner testing selected; an active explicit budget is still required'
        else 'No verified eligible funds for the active environment' end
    );
  end if;
  return jsonb_build_object(
    'eligible', true,
    'funding_source', v_source.source_type,
    'funding_source_id', v_source.source_id,
    'funding_environment', v_source.funding_environment,
    'payer_kind', v_authority.payer_kind,
    'payer_user_id', v_authority.payer_user_id,
    'customer_label', v_source.customer_label
  );
end $$;


ALTER FUNCTION "tongs"."_select_customer_funding_for_quote"("p_quote_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."_selectable_openai_text_models"("p_route_code" "text") RETURNS TABLE("catalog_revision_id" "uuid", "catalog_revision" integer, "model_catalog_entry_id" "uuid", "customer_selection_key" "uuid", "customer_selection_state" "text", "runtime_model_id" "text", "provider_model_id" "text", "display_name" "text", "tradeoff_summary" "text", "quality_rank" integer, "rate_revision" integer, "cost_policy_revision_id" "uuid", "customer_credit_units" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
  select catalog.id,
    catalog.revision,
    entry.id,
    entry.customer_selection_key,
    coalesce(entry.customer_selection_state,case entry.lifecycle_state
      when 'active' then 'selectable'
      when 'deprecated' then 'historical'
      when 'retired' then 'historical'
      else 'unavailable' end),
    entry.runtime_model_id,
    entry.provider_model_id,
    entry.display_name,
    entry.tradeoff_summary,
    entry.quality_rank,
    rate.revision,
    compatibility.cost_policy_revision_id,
    pricing.customer_credit_units
  from tongs.openai_text_model_catalog_revisions catalog
  join tongs.openai_text_model_catalog_entries entry
    on entry.catalog_revision_id=catalog.id
  join tongs.openai_text_model_route_compatibility compatibility
    on compatibility.catalog_entry_id=entry.id
   and compatibility.route_code=p_route_code
  join tongs.openai_text_cost_policy_revisions cost
    on cost.id=compatibility.cost_policy_revision_id
   and cost.cost_coverage='complete'
   and cost.lifecycle_state in ('pilot_candidate','active')
  join tongs.openai_text_provider_rate_revisions rate
    on rate.id=entry.rate_revision_id
  join lateral tongs._published_pricing_revision(
    'openai',
    lower(
      (case when compatibility.route_code='hearth.thumbnail_base_generation'
        then 'openai-image:' else 'openai-text:' end)
      ||compatibility.route_code||':'||entry.runtime_model_id||':'||cost.id::text
    )
  ) pricing on pricing.full_cost_ceiling_micros=cost.full_cost_ceiling_micros
  where catalog.lifecycle_state='active'
    and catalog.id=(select latest.id from tongs.openai_text_model_catalog_revisions latest
      where latest.lifecycle_state='active' order by latest.revision desc limit 1)
    and entry.lifecycle_state='active'
    and coalesce(entry.customer_selection_state,'selectable') in ('selectable','recommended','retiring')
    and entry.availability_status='generation_compatible'
    and compatibility.compatibility_status='generation_verified'
    and compatibility.supporting_cost_coverage='complete';
$$;


ALTER FUNCTION "tongs"."_selectable_openai_text_models"("p_route_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."_settle_operation_before_zero_failure_policy"("p_reservation_id" "uuid", "p_settlement_id" "uuid", "p_settlement_key" "text", "p_outcome" "text", "p_failure_class" "text", "p_actual_fulfillment_cost_micros" bigint, "p_evidence_json" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_control tongs.paid_execution_control_revisions%rowtype;
  v_reservation tongs.funding_reservations%rowtype;
  v_quote tongs.customer_spending_quotes%rowtype;
  v_pricing tongs.private_pricing_revisions%rowtype;
  v_existing tongs.funding_reservation_events%rowtype;
  v_state text;
  v_sequence integer;
  v_ceiling bigint;
  v_charge bigint;
  v_units bigint;
  v_calculated_charge numeric;
  v_observed_charge bigint;
  v_consumption jsonb;
begin
  perform tongs._require_pricing_service_role();
  if p_settlement_id is null or length(btrim(coalesce(p_settlement_key, ''))) < 8
     or p_outcome not in ('success', 'billable_failure', 'nonbillable_failure')
     or p_actual_fulfillment_cost_micros < 0
     or jsonb_typeof(coalesce(p_evidence_json, 'null'::jsonb)) <> 'object' then
    raise exception 'invalid operation settlement' using errcode = '22023';
  end if;
  select * into v_control from tongs._current_paid_execution_control();
  if not v_control.pricing_activation_enabled or not v_control.customer_settlement_enabled then
    raise exception 'customer settlement is not activated' using errcode = '42501';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('provider-attempt:' || p_reservation_id::text, 0));
  select * into v_reservation from tongs.funding_reservations where id = p_reservation_id for update;
  if not found then raise exception 'funding reservation not found' using errcode = 'P0002'; end if;
  select * into v_quote from tongs.customer_spending_quotes where id = v_reservation.quote_id;
  select * into v_pricing from tongs.private_pricing_revisions where id = v_quote.pricing_revision_id;
  select * into v_existing from tongs.funding_reservation_events where event_key = btrim(p_settlement_key);
  if found then
    return jsonb_build_object('reservation_id', p_reservation_id, 'state', 'settled', 'replay', true,
      'customer_charge_micros', v_existing.customer_charge_micros,
      'wholesale_spend_micros', v_existing.wholesale_spend_micros);
  end if;
  v_state := tongs._funding_reservation_state(p_reservation_id);
  if v_state = 'settled' then raise exception 'settlement replay key conflict' using errcode = '23505'; end if;
  if v_state = 'released' then raise exception 'released reservation cannot settle' using errcode = 'P0001'; end if;
  if p_outcome = 'nonbillable_failure' then
    v_ceiling := 0;
    v_calculated_charge := 0;
  elsif p_outcome = 'billable_failure' then
    if nullif(btrim(coalesce(p_failure_class, '')), '') is null
       or not exists (select 1 from jsonb_array_elements_text(v_quote.billable_failure_classes) value
         where value = btrim(p_failure_class)) then
      raise exception 'failure class is not billable under accepted quote' using errcode = 'P0001';
    end if;
    v_ceiling := v_quote.billable_failure_maximum_charge_micros;
    v_calculated_charge := ceil(
      p_actual_fulfillment_cost_micros::numeric
      * (10000::numeric + v_pricing.markup_basis_points::numeric) / 10000::numeric
    );
  else
    v_ceiling := v_quote.normal_maximum_charge_micros;
    v_calculated_charge := v_quote.normal_maximum_charge_micros;
  end if;
  if v_calculated_charge > 9223372036854775807::numeric then
    v_observed_charge := 9223372036854775807;
  else
    v_observed_charge := v_calculated_charge::bigint;
  end if;
  v_charge := least(v_observed_charge, v_ceiling, v_reservation.reserved_customer_charge_micros);
  v_units := case
    when v_charge = 0 or v_reservation.reserved_customer_charge_micros = 0 then 0
    else ceil(v_reservation.reserved_credit_units::numeric * v_charge::numeric
      / v_reservation.reserved_customer_charge_micros::numeric)::bigint end;
  if p_outcome = 'nonbillable_failure' and (v_charge <> 0 or v_units <> 0) then
    raise exception 'nonbillable failure must settle at zero' using errcode = 'P0001';
  end if;
  if v_observed_charge > v_ceiling then
    insert into tongs.pricing_discrepancies(
      id, reservation_id, discrepancy_key, discrepancy_type,
      quoted_ceiling_micros, observed_amount_micros, evidence_json
    ) values (gen_random_uuid(), p_reservation_id, btrim(p_settlement_key) || ':customer-overrun',
      'customer_ceiling_overrun', v_ceiling, v_observed_charge,
      coalesce(p_evidence_json, '{}'::jsonb)) on conflict (discrepancy_key) do nothing;
  end if;
  if p_actual_fulfillment_cost_micros > v_reservation.reserved_wholesale_spend_micros then
    insert into tongs.pricing_discrepancies(
      id, reservation_id, discrepancy_key, discrepancy_type,
      quoted_ceiling_micros, observed_amount_micros, evidence_json
    ) values (gen_random_uuid(), p_reservation_id, btrim(p_settlement_key) || ':wholesale-overrun',
      'wholesale_ceiling_overrun', v_reservation.reserved_wholesale_spend_micros,
      p_actual_fulfillment_cost_micros, coalesce(p_evidence_json, '{}'::jsonb))
    on conflict (discrepancy_key) do nothing;
  end if;
  if v_reservation.funding_source_type = 'customer_deposit' and v_charge > 0 then
    v_consumption := tongs.consume_customer_deposit(
      p_settlement_id, v_reservation.funding_source_id,
      'reservation-settlement:' || p_reservation_id::text, v_reservation.operation_id,
      v_charge, v_units, now(), jsonb_build_object('reservation_id', p_reservation_id,
        'quote_id', v_quote.id, 'outcome', p_outcome)
    );
  elsif v_reservation.funding_source_type = 'paid_allowance' and v_charge > 0 then
    v_consumption := tongs.consume_paid_allowance(
      p_settlement_id, v_reservation.funding_source_id,
      'reservation-settlement:' || p_reservation_id::text, v_reservation.operation_id,
      v_units, v_charge, least(p_actual_fulfillment_cost_micros, v_reservation.reserved_wholesale_spend_micros),
      now(), jsonb_build_object('reservation_id', p_reservation_id,
        'quote_id', v_quote.id, 'outcome', p_outcome)
    );
  elsif v_reservation.funding_source_type = 'beta_grant' and v_charge > 0 then
    v_consumption := tongs.consume_beta_test_credits(
      p_settlement_id, v_reservation.funding_source_id,
      'reservation-settlement:' || p_reservation_id::text, v_reservation.operation_id,
      v_units, v_charge, least(p_actual_fulfillment_cost_micros, v_reservation.reserved_wholesale_spend_micros),
      jsonb_build_object('reservation_id', p_reservation_id, 'quote_id', v_quote.id, 'outcome', p_outcome)
    );
  elsif v_reservation.funding_source_type = 'owner_budget' then
    raise exception 'owner-budget settlement is not available in this release' using errcode = '42501';
  elsif v_reservation.funding_source_type <> 'none' and v_charge = 0 and v_units <> 0 then
    raise exception 'zero-charge settlement cannot consume credits' using errcode = '22023';
  end if;
  select coalesce(max(sequence),0)+1 into v_sequence from tongs.funding_reservation_events
    where reservation_id = p_reservation_id;
  insert into tongs.funding_reservation_events(
    id, reservation_id, sequence, event_type, event_key, customer_charge_micros,
    credit_units, wholesale_spend_micros, failure_class, evidence_json
  ) values (
    gen_random_uuid(), p_reservation_id, v_sequence, 'settled', btrim(p_settlement_key),
    v_charge, v_units, p_actual_fulfillment_cost_micros, nullif(btrim(coalesce(p_failure_class, '')), ''),
    coalesce(p_evidence_json, '{}'::jsonb)
  );
  return jsonb_build_object('reservation_id', p_reservation_id, 'state', 'settled',
    'replay', false, 'customer_charge_micros', v_charge, 'credit_units', v_units,
    'fulfillment_cost_micros', p_actual_fulfillment_cost_micros,
    'customer_ceiling_applied', v_observed_charge > v_ceiling,
    'wholesale_discrepancy_recorded', p_actual_fulfillment_cost_micros > v_reservation.reserved_wholesale_spend_micros,
    'accounting_consumption', v_consumption);
end;
$$;


ALTER FUNCTION "tongs"."_settle_operation_before_zero_failure_policy"("p_reservation_id" "uuid", "p_settlement_id" "uuid", "p_settlement_key" "text", "p_outcome" "text", "p_failure_class" "text", "p_actual_fulfillment_cost_micros" bigint, "p_evidence_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."_stamp_and_authorize_funding_reservation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  quote_row tongs.customer_spending_quotes%rowtype;
  source_environment text;
  quote_binding tongs.openai_text_customer_quote_bindings%rowtype;
  scope_auth tongs.customer_paid_execution_scope_authorizations%rowtype;
  activation tongs.owner_paid_execution_canary_activation_revisions%rowtype;
  prior_count bigint; active_count bigint;
begin
  select * into quote_row from tongs.customer_spending_quotes where id=new.quote_id;
  if not found then raise exception 'spending quote not found' using errcode='P0002'; end if;
  if new.funding_source_type='customer_deposit' then
    select stripe_mode into source_environment from tongs.customer_deposits where id=new.funding_source_id;
  elsif new.funding_source_type='paid_allowance' then
    select financial_environment into source_environment from tongs.paid_allowance_grants where id=new.funding_source_id;
  elsif new.funding_source_type='beta_grant' then
    select financial_environment into source_environment from tongs.beta_credit_grants where id=new.funding_source_id;
  elsif new.funding_source_type='owner_budget' then
    select * into quote_binding from tongs.openai_text_customer_quote_bindings where quote_id=new.quote_id;
    select scope.* into scope_auth
    from tongs.customer_paid_execution_scope_authorizations scope
    join lateral tongs._active_owner_paid_execution_canary_for_scope(scope.id,new.funding_source_id) canary on canary.id is not null
    where scope.user_id=new.user_id and scope.workspace_id=quote_binding.workspace_id
      and scope.route_code=quote_binding.route_code and scope.model_or_sku=quote_binding.runtime_model
      and scope.pricing_revision_id=quote_binding.pricing_revision_id
      and scope.cost_policy_revision_id=quote_binding.cost_policy_revision_id
    order by scope.created_at desc limit 1;
    if found then source_environment:='test'; else source_environment:='owner_internal'; end if;
  else source_environment:=quote_row.financial_environment;
  end if;
  if source_environment is null then raise exception 'funding source environment is unavailable' using errcode='P0002'; end if;
  if new.funding_source_type in('customer_deposit','paid_allowance','beta_grant')
     and source_environment<>quote_row.financial_environment then
    raise exception 'cross-environment customer funding is forbidden' using errcode='42501';
  end if;
  new.funding_environment:=source_environment;
  if new.funding_source_type='owner_budget' and source_environment='test' then
    select * into activation from tongs._active_owner_paid_execution_canary_for_scope(scope_auth.id,new.funding_source_id);
    if activation.id is null
       or new.reserved_wholesale_spend_micros>scope_auth.maximum_wholesale_exposure_micros
       or new.reserved_customer_charge_micros<>0 or new.reserved_credit_units<>0 then
      raise exception 'exact owner canary funding authority required' using errcode='42501';
    end if;
    perform pg_advisory_xact_lock(hashtextextended('paid-scope:'||scope_auth.id::text,0));
    select count(*) into prior_count from tongs.funding_reservations
      where rollout_authorization_id=scope_auth.id;
    if prior_count>=1 then raise exception 'owner canary operation limit reached' using errcode='P0001'; end if;
    select count(*) into active_count from tongs.funding_reservations reservation
      where reservation.rollout_authorization_id=scope_auth.id
        and tongs._funding_reservation_counts_paid_scope_concurrency(reservation.id);
    if active_count>=1 then raise exception 'owner canary concurrency limit reached' using errcode='P0001'; end if;
    new.rollout_authorization_id:=scope_auth.id;
    return new;
  end if;
  if new.funding_source_type not in('customer_deposit','paid_allowance','beta_grant') then return new; end if;
  select * into quote_binding from tongs.openai_text_customer_quote_bindings where quote_id=new.quote_id;
  if not found then raise exception 'generic paid execution authorization requires an immutable provider quote binding' using errcode='42501'; end if;
  select scope.* into scope_auth from tongs.customer_paid_execution_scope_authorizations scope
  where scope.user_id=new.user_id and scope.workspace_id=quote_binding.workspace_id
    and scope.financial_environment=source_environment and scope.route_code=quote_binding.route_code
    and scope.provider='openai' and scope.model_or_sku=quote_binding.runtime_model
    and scope.pricing_revision_id=quote_binding.pricing_revision_id
    and scope.cost_policy_revision_id=quote_binding.cost_policy_revision_id
    and scope.authorization_kind in('certification','normal_customer')
    and scope.status='active' and scope.valid_from<=now() and(scope.valid_until is null or scope.valid_until>now())
  order by(scope.authorization_kind='normal_customer') desc,scope.created_at desc limit 1;
  if not found or new.reserved_customer_charge_micros>scope_auth.maximum_customer_charge_micros
     or new.reserved_wholesale_spend_micros>scope_auth.maximum_wholesale_exposure_micros then
    raise exception 'customer paid execution is not authorized for this scope' using errcode='42501';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('paid-scope:'||scope_auth.id::text,0));
  if scope_auth.maximum_operation_count is not null then
    select count(*) into prior_count from tongs.funding_reservations where rollout_authorization_id=scope_auth.id;
    if prior_count>=scope_auth.maximum_operation_count then raise exception 'customer paid execution operation limit reached' using errcode='P0001'; end if;
  end if;
  select count(*) into active_count from tongs.funding_reservations reservation
    where reservation.rollout_authorization_id=scope_auth.id
      and tongs._funding_reservation_counts_paid_scope_concurrency(reservation.id);
  if active_count>=scope_auth.maximum_concurrency then raise exception 'customer paid execution concurrency limit reached' using errcode='P0001'; end if;
  new.rollout_authorization_id:=scope_auth.id;
  return new;
end $$;


ALTER FUNCTION "tongs"."_stamp_and_authorize_funding_reservation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."_stamp_paid_allowance_environment"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
begin
  select receipt.stripe_mode into new.financial_environment
  from tongs.subscription_cycle_receipts receipt
  where receipt.id = new.receipt_id;
  if new.financial_environment not in ('test', 'live') then
    raise exception 'allowance receipt environment is unavailable' using errcode = 'P0002';
  end if;
  return new;
end $$;


ALTER FUNCTION "tongs"."_stamp_paid_allowance_environment"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."_stamp_restricted_beta_funding_environment"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare v_reservation_id uuid;
begin
  begin
    v_reservation_id := nullif(current_setting('forge.funding_reservation_id', true), '')::uuid;
  exception when others then
    v_reservation_id := null;
  end;
  if v_reservation_id is not null then
    select funding_environment into new.funding_environment
    from tongs.funding_reservations where id = v_reservation_id;
  end if;
  if new.funding_environment = 'legacy_unverified' then
    new.funding_environment := case new.funding_class
      when 'owner_operating_budget' then 'owner_internal'
      else tongs._current_financial_environment()
    end;
  end if;
  return new;
end $$;


ALTER FUNCTION "tongs"."_stamp_restricted_beta_funding_environment"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."_stamp_spending_quote_environment"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare v_environment text;
begin
  v_environment := tongs._current_financial_environment();
  if v_environment not in ('test', 'live') then
    raise exception 'trusted financial runtime environment is unavailable' using errcode = '42501';
  end if;
  new.financial_environment := v_environment;
  return new;
end $$;


