CREATE OR REPLACE FUNCTION "tongs"."_transition_owner_authority_agrees"("p_user_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
  select p_user_id is not null
    and exists(
      select 1
      from tongs.account_authority_classifications c
      where c.user_id = p_user_id
        and c.account_class = 'owner'
    )
    and exists(
      select 1
      from tongs.owner_testing_principals p
      where p.user_id = p_user_id
        and p.status = 'enabled'
    );
$$;


