CREATE OR REPLACE FUNCTION "tongs"."_unconsumed_deposit_credit_units"("p_deposit_id" "uuid") RETURNS bigint
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
  select greatest(case when conversion.deposit_id is not null then
    conversion.canonical_available_credit_units
      - coalesce((select sum(c.credit_units_consumed)
          from tongs.customer_deposit_consumptions c
          where c.deposit_id=deposit.id and not exists (
            select 1 from tongs.legacy_deposit_conversion_consumptions mapped
            where mapped.consumption_id=c.id)),0)
      - coalesce((select sum(r.refunded_credit_units)
          from tongs.customer_deposit_refunds r
          where r.deposit_id=deposit.id and not exists (
            select 1 from tongs.legacy_deposit_conversion_refunds mapped
            where mapped.refund_id=r.id)),0)
      + coalesce((select sum(relief.restored_units)
          from tongs.customer_operation_reliefs relief
          where relief.funding_source_type='customer_deposit'
            and relief.funding_source_id=deposit.id),0)
      - coalesce((select sum(correction.corrected_credit_units)
          from tongs.customer_operation_relief_corrections correction
          join tongs.customer_operation_reliefs relief on relief.id=correction.relief_id
          where relief.funding_source_type='customer_deposit'
            and relief.funding_source_id=deposit.id),0)
    else deposit.credit_units
      - coalesce((select sum(c.credit_units_consumed)
          from tongs.customer_deposit_consumptions c where c.deposit_id=deposit.id),0)
      - coalesce((select sum(r.refunded_credit_units)
          from tongs.customer_deposit_refunds r where r.deposit_id=deposit.id),0)
      + coalesce((select sum(relief.restored_units)
          from tongs.customer_operation_reliefs relief
          where relief.funding_source_type='customer_deposit'
            and relief.funding_source_id=deposit.id),0)
      - coalesce((select sum(correction.corrected_credit_units)
          from tongs.customer_operation_relief_corrections correction
          join tongs.customer_operation_reliefs relief on relief.id=correction.relief_id
          where relief.funding_source_type='customer_deposit'
            and relief.funding_source_id=deposit.id),0)
    end,0)::bigint
  from tongs.customer_deposits deposit
  left join tongs.legacy_deposit_credit_conversions conversion
    on conversion.deposit_id=deposit.id
  where deposit.id=p_deposit_id
$$;


ALTER FUNCTION "tongs"."_unconsumed_deposit_credit_units"("p_deposit_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."_unconsumed_deposit_credit_units"("p_deposit_id" "uuid") IS 'Canonical purchased Forge Credit balance after consumption, Stripe refunds, relief restoration, and append-only relief correction.';



CREATE OR REPLACE FUNCTION "tongs"."_unconsumed_deposit_value_micros"("p_deposit_id" "uuid") RETURNS bigint
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
  select greatest(
    deposit.gross_amount_micros
      - coalesce((select sum(c.recognized_revenue_micros)
          from tongs.customer_deposit_consumptions c where c.deposit_id=deposit.id),0)
      - coalesce((select sum(r.liability_release_micros)
          from tongs.customer_deposit_refunds r where r.deposit_id=deposit.id),0)
      + coalesce((select sum(relief.revenue_reversal_micros)
          from tongs.customer_operation_reliefs relief
          where relief.funding_source_type='customer_deposit'
            and relief.funding_source_id=deposit.id),0)
      - coalesce((select sum(correction.corrected_revenue_micros)
          from tongs.customer_operation_relief_corrections correction
          join tongs.customer_operation_reliefs relief on relief.id=correction.relief_id
          where relief.funding_source_type='customer_deposit'
            and relief.funding_source_id=deposit.id),0),
    0
  )::bigint
  from tongs.customer_deposits deposit where deposit.id=p_deposit_id
$$;


ALTER FUNCTION "tongs"."_unconsumed_deposit_value_micros"("p_deposit_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."_unconsumed_deposit_value_micros"("p_deposit_id" "uuid") IS 'Canonical purchased-credit liability after consumption, Stripe refunds, relief restoration, and append-only relief correction.';



CREATE OR REPLACE FUNCTION "tongs"."_valid_paid_media_usage_components"("p_usage_components" "jsonb") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'pg_catalog', 'tongs', 'extensions'
    AS $$
  select (
    jsonb_typeof(p_usage_components) = 'array'
    and jsonb_array_length(p_usage_components) > 0
    and not exists (
      select 1
      from jsonb_array_elements(p_usage_components) as c
      where nullif(btrim(c->>'component_kind'), '') is null
        or nullif(btrim(c->>'unit_kind'), '') is null
        or coalesce((c->>'quantity')::bigint, -1) < 0
    )
    and (
      tongs._paid_media_usage_contract_is_image(p_usage_components)
      or tongs._paid_media_usage_contract_is_video(p_usage_components)
    )
  );
$$;


ALTER FUNCTION "tongs"."_valid_paid_media_usage_components"("p_usage_components" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."_validate_customer_deposit_credit_term"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare v_offer text := nullif(btrim(coalesce(new.metadata_json->>'forge_offer_id','')), '');
begin
  if v_offer is null or not exists (
    select 1 from tongs.forge_credit_pack_terms term
    join tongs.forge_credit_contract_revisions contract on contract.id=term.contract_revision_id
    where contract.lifecycle_state='active'
      and term.financial_environment=new.stripe_mode and term.pack_id=new.pack_id
      and term.offer_id=v_offer and term.gross_amount_micros=new.gross_amount_micros
      and term.credit_units=new.credit_units
  ) then
    raise exception 'customer deposit does not match a versioned Forge Credit term' using errcode='23514';
  end if;
  return new;
end $$;


ALTER FUNCTION "tongs"."_validate_customer_deposit_credit_term"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."_validate_markup_overrides"("p_overrides" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_item jsonb;
begin
  if jsonb_typeof(coalesce(p_overrides, 'null'::jsonb)) <> 'array' then
    raise exception 'markup overrides must be an array' using errcode = '22023';
  end if;
  for v_item in select value from jsonb_array_elements(p_overrides) loop
    if jsonb_typeof(v_item) <> 'object'
       or v_item->>'scope_kind' not in ('provider', 'sku')
       or nullif(lower(btrim(coalesce(v_item->>'provider', ''))), '') is null
       or not (v_item ? 'markup_basis_points')
       or (v_item->>'markup_basis_points')::numeric < 0
       or (v_item->>'markup_basis_points')::numeric > 2147483647
       or (v_item->>'scope_kind' = 'provider'
         and nullif(btrim(coalesce(v_item->>'sku', '')), '') is not null)
       or (v_item->>'scope_kind' = 'sku'
         and nullif(btrim(coalesce(v_item->>'sku', '')), '') is null) then
      raise exception 'invalid markup override' using errcode = '22023';
    end if;
  end loop;
  if exists (
    select 1 from (
      select lower(value->>'scope_kind') as scope_kind,
        lower(btrim(value->>'provider')) as provider,
        lower(btrim(coalesce(value->>'sku', ''))) as sku,
        count(*)
      from jsonb_array_elements(p_overrides)
      group by 1,2,3 having count(*) > 1
    ) duplicate
  ) then
    raise exception 'duplicate markup override scope' using errcode = '22023';
  end if;
end;
$$;


ALTER FUNCTION "tongs"."_validate_markup_overrides"("p_overrides" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."_validate_owner_budget_reservation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_budget tongs.owner_operating_budgets%rowtype;
  v_revision tongs.owner_operating_budget_revisions%rowtype;
  v_quote tongs.customer_spending_quotes%rowtype;
  v_pricing tongs.private_pricing_revisions%rowtype;
  v_policy tongs.private_pricing_policies%rowtype;
  v_consumed bigint;
  v_held bigint;
begin
  if new.funding_source_type <> 'owner_budget' then return new; end if;
  select * into v_budget from tongs.owner_operating_budgets where id = new.funding_source_id for update;
  select * into v_revision from tongs.owner_operating_budget_revisions
    where budget_id = new.funding_source_id order by revision desc limit 1;
  select * into v_quote from tongs.customer_spending_quotes where id = new.quote_id;
  select * into v_pricing from tongs.private_pricing_revisions where id = v_quote.pricing_revision_id;
  select * into v_policy from tongs.private_pricing_policies where id = v_pricing.policy_id;
  if v_budget.id is null or v_revision.status <> 'active' or v_revision.maximum_amount_micros is null
     or now() < v_budget.period_start or now() >= v_budget.period_end then
    raise exception 'active capped owner operating budget required' using errcode = 'P0001';
  end if;
  if not tongs.is_platform_operator(v_quote.user_id) then
    raise exception 'owner budget requires platform-operator operation identity' using errcode = '42501';
  end if;
  if v_budget.currency <> new.currency
     or (v_budget.workspace_id is not null and v_budget.workspace_id is distinct from v_quote.workspace_id)
     or (v_budget.provider is not null and lower(v_budget.provider) is distinct from lower(v_policy.provider))
     or (v_budget.route is not null and lower(v_budget.route) is distinct from lower(v_quote.tool))
     or (v_budget.sku is not null and lower(v_budget.sku) is distinct from lower(v_policy.sku)) then
    raise exception 'owner budget scope does not cover operation' using errcode = '42501';
  end if;
  select tongs._owner_operating_budget_effective_consumed(v_budget.id) into v_consumed;
  select coalesce(sum(reservation.reserved_wholesale_spend_micros),0) into v_held
    from tongs.funding_reservations reservation
    where reservation.funding_source_type = 'owner_budget'
      and reservation.funding_source_id = v_budget.id
      and tongs._funding_reservation_state(reservation.id) not in ('settled','released');
  if v_consumed + v_held + new.reserved_wholesale_spend_micros > v_revision.maximum_amount_micros then
    raise exception 'insufficient owner operating budget' using errcode = 'P0001';
  end if;
  if new.reserved_customer_charge_micros <> 0 or new.reserved_credit_units <> 0 then
    raise exception 'owner-funded reservation cannot debit a customer' using errcode = '23514';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "tongs"."_validate_owner_budget_reservation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."_validate_owner_cost_attribution"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_recording_session_id" "uuid", "p_recording_capture_authority_id" "uuid", "p_anvil_capture_execution_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_authority tongs.recording_capture_authorities%rowtype;
  v_execution tongs.anvil_capture_executions%rowtype;
begin
  if p_workpiece_id is not null and not exists (
    select 1 from tongs.episodes e
    where e.id = p_workpiece_id and (p_workspace_id is null or e.workspace_id = p_workspace_id)
  ) then raise exception 'owner-cost workpiece attribution mismatch' using errcode = '23514'; end if;

  if p_recording_session_id is not null and not exists (
    select 1 from tongs.recording_sessions s
    where s.id = p_recording_session_id and (p_workspace_id is null or s.workspace_id = p_workspace_id)
  ) then raise exception 'owner-cost recording session attribution mismatch' using errcode = '23514'; end if;

  if p_recording_capture_authority_id is not null then
    select * into v_authority from tongs.recording_capture_authorities a
      where a.id = p_recording_capture_authority_id;
    if not found
       or (p_workspace_id is not null and v_authority.workspace_id <> p_workspace_id)
       or (p_workpiece_id is not null and v_authority.workpiece_id <> p_workpiece_id)
       or (p_recording_session_id is not null and v_authority.recording_session_id is distinct from p_recording_session_id) then
      raise exception 'owner-cost capture authority attribution mismatch' using errcode = '23514';
    end if;
  end if;

  if p_anvil_capture_execution_id is not null then
    select * into v_execution from tongs.anvil_capture_executions e
      where e.execution_id = p_anvil_capture_execution_id;
    if not found
       or (p_recording_capture_authority_id is not null and v_execution.recording_capture_authority_id <> p_recording_capture_authority_id) then
      raise exception 'owner-cost Anvil execution attribution mismatch' using errcode = '23514';
    end if;
    if p_recording_capture_authority_id is null then
      perform tongs._validate_owner_cost_attribution(
        p_workspace_id, p_workpiece_id, p_recording_session_id,
        v_execution.recording_capture_authority_id, null
      );
    end if;
  end if;
end;
$$;


ALTER FUNCTION "tongs"."_validate_owner_cost_attribution"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_recording_session_id" "uuid", "p_recording_capture_authority_id" "uuid", "p_anvil_capture_execution_id" "uuid") OWNER TO "postgres";


