CREATE OR REPLACE FUNCTION "tongs"."_validate_quote_authority_before_provider"("p_quote_id" "uuid", "p_route_code" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_binding tongs.spending_quote_authority_bindings%rowtype;
  v_workspace_id uuid;
  v_pref tongs.ai_funding_preference_revisions%rowtype;
  v_account tongs.organization_funding_account_revisions%rowtype;
  v_permission tongs.organization_shared_spend_permission_revisions%rowtype;
begin
  select * into v_binding from tongs.spending_quote_authority_bindings where quote_id=p_quote_id;
  if not found then return true; end if;
  select workspace_id into v_workspace_id from tongs.customer_spending_quotes where id=p_quote_id;
  if v_binding.preference_revision_id is not null then
    select * into v_pref from tongs.ai_funding_preference_revisions
      where user_id=v_binding.acting_user_id and workspace_id=v_workspace_id order by revision desc limit 1;
    if not found or v_pref.id<>v_binding.preference_revision_id then return false; end if;
  end if;
  if v_binding.payer_kind='owner_testing' then
    return tongs._transition_owner_authority_agrees(v_binding.acting_user_id)
      and exists(select 1 from tongs.owner_testing_principals p
        where p.user_id=v_binding.acting_user_id and p.status='enabled' and p.revision=v_binding.owner_principal_revision);
  end if;
  if v_binding.payer_kind='organization_shared' then
    if not exists(select 1 from tongs.org_members om where om.org_id=v_binding.org_id and om.user_id=v_binding.acting_user_id) then return false; end if;
    select * into v_account from tongs.organization_funding_account_revisions where org_id=v_binding.org_id order by revision desc limit 1;
    select * into v_permission from tongs.organization_shared_spend_permission_revisions where org_id=v_binding.org_id and member_user_id=v_binding.acting_user_id order by revision desc limit 1;
    return v_account.id=v_binding.organization_account_revision_id and v_account.status='active'
      and v_permission.id=v_binding.organization_permission_revision_id and v_permission.status='allowed'
      and (cardinality(v_permission.route_codes)=0 or p_route_code=any(v_permission.route_codes));
  end if;
  return true;
end $$;


ALTER FUNCTION "tongs"."_validate_quote_authority_before_provider"("p_quote_id" "uuid", "p_route_code" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "tongs"."bellows_capture_packages" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "session_id" "text" NOT NULL,
    "workspace_id" "uuid" NOT NULL,
    "workpiece_id" "uuid" NOT NULL,
    "contract_version" integer DEFAULT 1 NOT NULL,
    "outcome" "text" NOT NULL,
    "manifest" "jsonb" NOT NULL,
    "manifest_sha256" "text" NOT NULL,
    "incomplete_acceptance_id" "uuid",
    "sealed_by_engine_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "hammer_handoff_id" "text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "bellows_capture_packages_check" CHECK ((("outcome" = 'incomplete_capture'::"text") = ("incomplete_acceptance_id" IS NOT NULL))),
    CONSTRAINT "bellows_capture_packages_contract_version_check" CHECK (("contract_version" = 1)),
    CONSTRAINT "bellows_capture_packages_manifest_check" CHECK (("jsonb_typeof"("manifest") = 'object'::"text")),
    CONSTRAINT "bellows_capture_packages_manifest_sha256_check" CHECK (("length"("manifest_sha256") = 64)),
    CONSTRAINT "bellows_capture_packages_outcome_check" CHECK (("outcome" = ANY (ARRAY['sealed'::"text", 'incomplete_capture'::"text"])))
);


ALTER TABLE "tongs"."bellows_capture_packages" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."accept_and_seal_incomplete_bellows_capture"("p_session_id" "text", "p_authority_generation" bigint, "p_finding_ids" "uuid"[], "p_workpiece_id" "uuid", "p_manifest" "jsonb", "p_manifest_sha256" "text") RETURNS "tongs"."bellows_capture_packages"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public', 'auth'
    AS $$
declare v_session tongs.bellows_sessions; v_acceptance uuid; v_package tongs.bellows_capture_packages;
begin
  select * into v_session from tongs.bellows_sessions where id=p_session_id for update;
  if not found then raise exception 'bellows_session_not_found'; end if;
  if v_session.authority_generation<>p_authority_generation then raise exception 'bellows_stale_authority_generation'; end if;
  if not exists(select 1 from tongs.bellows_session_participants p where p.session_id=p_session_id and p.id=v_session.acting_host_participant_id and p.user_id=auth.uid()) then raise exception 'bellows_incomplete_acceptance_forbidden'; end if;
  if not exists(select 1 from tongs.bellows_integrity_findings where session_id=p_session_id and id=any(p_finding_ids)) then raise exception 'bellows_findings_required'; end if;
  insert into tongs.bellows_incomplete_acceptances(session_id,workspace_id,accepted_by_user_id,authority_generation,finding_ids)
    values(p_session_id,v_session.workspace_id,auth.uid(),p_authority_generation,p_finding_ids) returning id into v_acceptance;
  insert into tongs.bellows_capture_packages(session_id,workspace_id,workpiece_id,outcome,manifest,manifest_sha256,incomplete_acceptance_id,hammer_handoff_id)
    values(p_session_id,v_session.workspace_id,p_workpiece_id,'incomplete_capture',p_manifest,lower(p_manifest_sha256),v_acceptance,'bellows:'||p_session_id)
    returning * into v_package;
  update tongs.bellows_sessions set lifecycle_state='incomplete_capture',outcome='incomplete_capture',seal_state='sealed',sealed_at=now(),workpiece_id=p_workpiece_id where id=p_session_id;
  return v_package;
end $$;


ALTER FUNCTION "tongs"."accept_and_seal_incomplete_bellows_capture"("p_session_id" "text", "p_authority_generation" bigint, "p_finding_ids" "uuid"[], "p_workpiece_id" "uuid", "p_manifest" "jsonb", "p_manifest_sha256" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."accept_barstock_discovery_story"("p_workspace_id" "uuid", "p_story_revision_id" "uuid", "p_operation_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs', 'extensions'
    AS $$
declare u uuid:=auth.uid(); v tongs.barstock_discovery_story_revisions%rowtype; a tongs.barstock_discovery_acceptances%rowtype; spark uuid:=gen_random_uuid(); workpiece uuid; src tongs.barstock_discovery_sources%rowtype; sr jsonb; lr jsonb; srid uuid; srrev bigint; stable text;
begin
 if u is null or not tongs.has_workspace_role(p_workspace_id,'editor') then return jsonb_build_object('outcome','denied');end if;
 perform pg_advisory_xact_lock(hashtextextended(p_workspace_id::text||':'||u::text||':'||p_operation_key,0));
 select * into a from tongs.barstock_discovery_acceptances where workspace_id=p_workspace_id and user_id=u and operation_key=p_operation_key;
 if a.id is not null then return jsonb_build_object('outcome','existing','spark_id',a.spark_id,'workpiece_id',a.workpiece_id,'story_revision_id',a.story_revision_id);end if;
 select * into v from tongs.barstock_discovery_story_revisions where id=p_story_revision_id and workspace_id=p_workspace_id and user_id=u;
 if v.id is null then return jsonb_build_object('outcome','not_found');end if;
 select * into a from tongs.barstock_discovery_acceptances where workspace_id=p_workspace_id and user_id=u and story_id=v.story_id;
 if a.id is not null then return jsonb_build_object('outcome','existing','spark_id',a.spark_id,'workpiece_id',a.workpiece_id,'story_revision_id',a.story_revision_id);end if;
 insert into tongs.barstock_sparks(id,workspace_id,created_by,title,body,tags,status,source,pinned,revision) values(spark,p_workspace_id,u,v.headline,v.summary,array['timely-topic'],'raw','link',false,1);
 workpiece:=tongs.create_episode_identity_internal(p_workspace_id,v.headline,u,'hearth_spark');
 update tongs.barstock_sparks set linked_workpiece_id=workpiece,status='forged',updated_at=now() where id=spark and workspace_id=p_workspace_id;
 for src in select * from tongs.barstock_discovery_sources where story_revision_id=v.id order by ordinal loop
  stable:='discovery-revision:'||v.id::text||':'||src.ordinal::text;
  sr:=tongs.commit_source_revision(p_workspace_id,null,stable,0,'webpage',src.title,src.author,src.publisher,src.published_at,src.canonical_url,null,null,null,jsonb_build_object('event_at',src.event_at),jsonb_build_object('origin','barstock_discovery','story_revision_id',v.id,'retrieved_at',src.retrieved_at,'supporting_excerpt',src.supporting_excerpt),'forge.source.metadata.v1','forge.source.provenance.v1','forge:source:discovery:'||v.id::text||':'||src.ordinal,encode(digest(convert_to(src.canonical_url,'UTF8'),'sha256'),'hex'),u);
  srid:=(sr#>>'{source_revision,id}')::uuid; srrev:=(sr#>>'{source_revision,revision}')::bigint;
  lr:=tongs.commit_workpiece_source_link_revision(p_workspace_id,workpiece,null,0,srid,srrev,'supports',null,null,'{}','{}','{}',src.excerpt_hash,v.suggested_angle,jsonb_build_object('origin','barstock_discovery','story_revision_id',v.id),'forge:source:discovery-link:'||v.id::text||':'||src.ordinal,encode(digest(convert_to(workpiece::text||src.canonical_url,'UTF8'),'sha256'),'hex'),u);
  if coalesce(lr->>'disposition','')<>'committed' then raise exception 'discovery source link failed';end if;
 end loop;
 insert into tongs.barstock_discovery_acceptances(workspace_id,user_id,story_id,story_revision_id,operation_key,spark_id,workpiece_id,selected_angle) values(p_workspace_id,u,v.story_id,v.id,p_operation_key,spark,workpiece,v.suggested_angle) returning * into a;
 return jsonb_build_object('outcome','created','spark_id',spark,'workpiece_id',workpiece,'story_revision_id',v.id);
end$$;


ALTER FUNCTION "tongs"."accept_barstock_discovery_story"("p_workspace_id" "uuid", "p_story_revision_id" "uuid", "p_operation_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."accept_hearth_chat_test_quote"("p_acceptance_id" "uuid", "p_quote_id" "uuid", "p_acceptance_key" "text", "p_quote_hash" "text", "p_actor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare v_quote tongs.test_customer_spending_quotes%rowtype; v_existing tongs.test_customer_spending_quote_acceptances%rowtype; v_kind text;
begin
  select * into v_quote from tongs.test_customer_spending_quotes where id=p_quote_id;
  if not found or v_quote.expires_at<=now() or v_quote.quote_hash<>p_quote_hash then raise exception 'invalid or expired Test quote' using errcode='P0001'; end if;
  if coalesce(auth.role(),'')='service_role' then
    if not tongs.is_platform_operator(p_actor_id) then raise exception 'platform operator required' using errcode='42501'; end if;
    v_kind:='platform_operator_test';
  else
    if auth.uid() is distinct from v_quote.user_id or p_actor_id is distinct from auth.uid() then raise exception 'customer required' using errcode='42501'; end if;
    v_kind:='customer';
  end if;
  select * into v_existing from tongs.test_customer_spending_quote_acceptances where quote_id=p_quote_id;
  if found then return jsonb_build_object('acceptance_id',v_existing.id,'replay',true); end if;
  insert into tongs.test_customer_spending_quote_acceptances(id,quote_id,acceptance_key,quote_hash,accepted_by,acceptance_kind)
  values(p_acceptance_id,p_quote_id,btrim(p_acceptance_key),p_quote_hash,p_actor_id,v_kind);
  return jsonb_build_object('acceptance_id',p_acceptance_id,'replay',false,'acceptance_kind',v_kind);
end $$;


ALTER FUNCTION "tongs"."accept_hearth_chat_test_quote"("p_acceptance_id" "uuid", "p_quote_id" "uuid", "p_acceptance_key" "text", "p_quote_hash" "text", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."accept_owner_hearth_research_operation"("p_owner_user_id" "uuid", "p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_operation_id" "text", "p_quote_id" "uuid", "p_quote_hash" "text", "p_request_fingerprint" "text", "p_plan_json" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare q tongs.owner_hearth_research_quotes%rowtype; a tongs.owner_hearth_research_authorizations%rowtype; ev tongs.owner_hearth_research_authorization_events%rowtype;
 term tongs.owner_hearth_research_model_terms%rowtype; existing tongs.owner_hearth_research_operations%rowtype; rid uuid; count_ops bigint; active_ops bigint;
 consumed bigint; held bigint; seq int; rollout tongs.openai_text_rollout_revisions%rowtype;
begin
 perform tongs._require_pricing_service_role(); perform pg_advisory_xact_lock(hashtextextended('owner-research-accept:'||p_quote_id::text,0));
 select * into existing from tongs.owner_hearth_research_operations where quote_id=p_quote_id;
 if found then return jsonb_build_object('operation_id',existing.operation_id,'reservation_id',existing.reservation_id,'request_fingerprint',existing.request_fingerprint,
  'provider_model_id',existing.provider_model_id,'maximum_output_tokens',existing.maximum_output_tokens,'limit_profile',existing.limit_profile,'replay',true); end if;
 select * into q from tongs.owner_hearth_research_quotes where quote_id=p_quote_id;
 select * into a from tongs.owner_hearth_research_authorizations where id=q.authorization_id for update;
 select * into ev from tongs.owner_hearth_research_authorization_events where authorization_id=a.id order by sequence desc limit 1;
 if q.quote_id is null or q.owner_user_id<>p_owner_user_id or q.workspace_id<>p_workspace_id or q.workpiece_id<>p_workpiece_id
  or q.operation_id<>btrim(p_operation_id) or q.quote_hash<>p_quote_hash or q.request_fingerprint<>p_request_fingerprint or q.plan_json<>p_plan_json
  or q.expires_at<=now() then raise exception 'accepted research quote mismatch or expiry' using errcode='42501'; end if;
 if ev.state='dormant' then
  select coalesce(max(sequence),0)+1 into seq from tongs.owner_hearth_research_authorization_events where authorization_id=a.id;
  insert into tongs.owner_hearth_research_authorization_events values(gen_random_uuid(),a.id,seq,'owner-research:'||a.id::text||':active','active',now(),now()+make_interval(secs=>a.duration_seconds),
   'First accepted operation started the separately approved session.','{"automatic_renewal":false}',now());
  select * into ev from tongs.owner_hearth_research_authorization_events where authorization_id=a.id order by sequence desc limit 1;
 end if;
 if ev.state<>'active' or ev.expires_at<=now() then raise exception 'owner research authorization is not active' using errcode='42501'; end if;
 select * into term from tongs.owner_hearth_research_model_terms where authorization_id=a.id and provider_model_id=q.provider_model_id;
 select count(*) into count_ops from tongs.owner_hearth_research_operations where authorization_id=a.id;
 select count(*) into active_ops from tongs.owner_hearth_research_operations o where o.authorization_id=a.id and tongs._funding_reservation_state(o.reservation_id) in('reserved','provider_attempt_shadowed','submission_unknown');
 if count_ops>=a.maximum_operations or active_ops>=a.maximum_concurrency then raise exception 'owner research operation or concurrency cap reached' using errcode='42501'; end if;
 select coalesce(sum(c.expense_amount_micros),0) into consumed from tongs.owner_operating_budget_consumptions c where c.budget_id=a.budget_id;
 select coalesce(sum(r.reserved_wholesale_spend_micros),0) into held from tongs.funding_reservations r where r.funding_source_type='owner_budget' and r.funding_source_id=a.budget_id
  and tongs._funding_reservation_state(r.id) not in('settled','released');
 if consumed+held+q.maximum_owner_commitment_micros>a.maximum_amount_micros then raise exception 'owner research budget cap exhausted' using errcode='42501'; end if;
 rid:=extensions.uuid_generate_v5(p_quote_id,'owner-research-reservation');
 insert into tongs.customer_spending_quote_acceptances values(gen_random_uuid(),p_quote_id,p_owner_user_id,'owner-research:'||p_quote_id::text,p_quote_hash,now());
 insert into tongs.funding_reservations values(rid,p_quote_id,p_owner_user_id,q.operation_id,'owner_budget',a.budget_id,'USD',0,0,q.maximum_owner_commitment_micros,
  'owner-research:'||rid::text,now());
 insert into tongs.funding_reservation_events(id,reservation_id,sequence,event_type,event_key,evidence_json)
  values(gen_random_uuid(),rid,1,'reserved','owner-research:'||rid::text||':reserved',jsonb_build_object('customer_charge_micros',0,'paid_supporting_work_authorized',false));
 select * into rollout from tongs._current_openai_text_rollout('hearth.research_synthesis');
 insert into tongs.openai_text_funding_bindings(operation_id,route_code,reservation_id,credential_funding,model,pricing_revision_id,maximum_input_units,
  maximum_output_units,maximum_attempts,cost_policy_revision_id,rollout_revision)
 values(q.operation_id,'hearth.research_synthesis',rid,'forge',q.provider_model_id,term.pricing_revision_id,a.maximum_input_tokens,a.maximum_output_tokens,1,term.cost_policy_revision_id,rollout.revision);
 insert into tongs.owner_hearth_research_operations(
  id,authorization_id,quote_id,reservation_id,operation_id,owner_user_id,workspace_id,workpiece_id,request_fingerprint,provider_model_id,
  cost_policy_revision_id,pricing_revision_id,aggregate_policy_revision_id,direct_provider_ceiling_micros,storage_ceiling_micros,full_cost_ceiling_micros,
  limit_profile,maximum_searches,maximum_sources,maximum_http_attempts,maximum_input_tokens,maximum_output_tokens,execution_deadline_at,created_at
 ) values(gen_random_uuid(),a.id,p_quote_id,rid,q.operation_id,p_owner_user_id,p_workspace_id,p_workpiece_id,
  p_request_fingerprint,q.provider_model_id,term.cost_policy_revision_id,term.pricing_revision_id,term.aggregate_policy_revision_id,
  q.direct_provider_ceiling_micros,q.storage_ceiling_micros,q.maximum_owner_commitment_micros,a.limit_profile,a.maximum_searches,a.maximum_sources,
  a.maximum_http_attempts,a.maximum_input_tokens,a.maximum_output_tokens,now()+interval '60 seconds',now());
 return jsonb_build_object('operation_id',q.operation_id,'reservation_id',rid,'request_fingerprint',p_request_fingerprint,'provider_model_id',q.provider_model_id,
  'maximum_output_tokens',a.maximum_output_tokens,'limit_profile',a.limit_profile,'replay',false);
end $$;


ALTER FUNCTION "tongs"."accept_owner_hearth_research_operation"("p_owner_user_id" "uuid", "p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_operation_id" "text", "p_quote_id" "uuid", "p_quote_hash" "text", "p_request_fingerprint" "text", "p_plan_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."accept_quote"("p_quote_id" "uuid", "p_acceptance_id" "uuid", "p_acceptance_key" "text", "p_quote_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $_$
declare
  v_user uuid := auth.uid();
  v_quote tongs.customer_spending_quotes%rowtype;
  v_existing tongs.customer_spending_quote_acceptances%rowtype;
begin
  if v_user is null then raise exception 'authentication required' using errcode = '42501'; end if;
  if p_acceptance_id is null or length(btrim(coalesce(p_acceptance_key, ''))) < 8
     or p_quote_hash !~ '^[0-9a-f]{64}$' then
    raise exception 'invalid quote acceptance' using errcode = '22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('quote-acceptance:' || p_quote_id::text, 0));
  select * into v_quote from tongs.customer_spending_quotes
  where id = p_quote_id and user_id = v_user;
  if not found then raise exception 'spending quote not found' using errcode = 'P0002'; end if;
  if v_quote.expires_at <= now() then raise exception 'spending quote expired' using errcode = 'P0001'; end if;
  if v_quote.quote_hash <> p_quote_hash then raise exception 'accepted quote hash mismatch' using errcode = '22023'; end if;
  select * into v_existing from tongs.customer_spending_quote_acceptances where quote_id = p_quote_id;
  if found then
    if v_existing.user_id <> v_user or v_existing.acceptance_key <> btrim(p_acceptance_key)
       or v_existing.accepted_quote_hash <> p_quote_hash then
      raise exception 'quote acceptance replay conflict' using errcode = '23505';
    end if;
    return jsonb_build_object('acceptance_id', v_existing.id, 'replay', true,
      'execution_authorized', false);
  end if;
  insert into tongs.customer_spending_quote_acceptances(
    id, quote_id, user_id, acceptance_key, accepted_quote_hash
  ) values (p_acceptance_id, p_quote_id, v_user, btrim(p_acceptance_key), p_quote_hash);
  return jsonb_build_object('acceptance_id', p_acceptance_id, 'replay', false,
    'execution_authorized', false);
end;
$_$;


ALTER FUNCTION "tongs"."accept_quote"("p_quote_id" "uuid", "p_acceptance_id" "uuid", "p_acceptance_key" "text", "p_quote_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."accept_workspace_invite"("p_token" "text") RETURNS TABLE("workspace_id" "uuid", "role" "text", "membership_created" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare
  v_user uuid;
  v_user_email text;
  v_token text;
  v_invite tongs.workspace_invites%rowtype;
  v_existing_member boolean;
begin
  v_user := auth.uid();
  if v_user is null then
    raise exception 'not_authenticated'
      using errcode = '42501';
  end if;

  v_token := btrim(coalesce(p_token, ''));
  if v_token = '' then
    raise exception 'invalid_token'
      using errcode = '22023';
  end if;

  select lower(coalesce(u.email, ''))
  into v_user_email
  from auth.users u
  where u.id = v_user;

  if v_user_email is null or v_user_email = '' then
    raise exception 'invite_user_email_missing'
      using errcode = '22023';
  end if;

  select wi.*
  into v_invite
  from tongs.workspace_invites wi
  where wi.token = v_token
  order by wi.created_at desc
  limit 1
  for update;

  if not found then
    raise exception 'invalid_token'
      using errcode = '22023';
  end if;

  if v_invite.revoked_at is not null then
    raise exception 'invite_revoked'
      using errcode = '22023';
  end if;

  if v_invite.accepted_at is not null then
    raise exception 'invite_already_accepted'
      using errcode = '22023';
  end if;

  if v_invite.expires_at <= now() then
    raise exception 'invite_expired'
      using errcode = '22023';
  end if;

  if v_invite.email <> v_user_email then
    raise exception 'invite_email_mismatch'
      using errcode = '42501';
  end if;

  select exists (
    select 1
    from tongs.workspace_members wm
    where wm.workspace_id = v_invite.workspace_id
      and wm.user_id = v_user
  )
  into v_existing_member;

  insert into tongs.workspace_members (
    workspace_id,
    user_id,
    role,
    created_at,
    created_by
  )
  values (
    v_invite.workspace_id,
    v_user,
    v_invite.role,
    now(),
    coalesce(v_invite.created_by, v_user)
  )
  on conflict on constraint workspace_members_pkey do update
    set role = case
      when tongs.workspace_role_rank(workspace_members.role)
         >= tongs.workspace_role_rank(excluded.role)
      then workspace_members.role
      else excluded.role
    end,
    created_by = coalesce(workspace_members.created_by, excluded.created_by);

  update tongs.workspace_invites wi
  set accepted_by = v_user,
      accepted_at = now(),
      updated_at = now()
  where wi.id = v_invite.id;

  return query
  select
    v_invite.workspace_id,
    v_invite.role,
    not v_existing_member;
end;
$$;


ALTER FUNCTION "tongs"."accept_workspace_invite"("p_token" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."acknowledge_hammer_editorial_authority"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_canonical_recording_id" "uuid", "p_revision_id" "uuid", "p_path" "text", "p_fingerprint" "text", "p_expected_revision_updated_at" timestamp with time zone, "p_expected_authority_revision" bigint, "p_expected_authority_path" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $_$
declare
  v_row tongs.recording_revisions%rowtype;
begin
  if not tongs.has_workspace_role(p_workspace_id, 'editor') then
    raise exception using errcode = '42501', message = 'editorial_authority_forbidden';
  end if;
  if p_path is null or btrim(p_path) = '' or p_fingerprint !~ '^[0-9a-f]{64}$' then
    raise exception using errcode = '22023', message = 'editorial_authority_ack_invalid';
  end if;
  if p_path <> format('hammer/revisions/%s/editorial-authority.v1.json', p_revision_id) then
    raise exception using errcode = '22023', message = 'editorial_authority_path_invalid';
  end if;

  update tongs.recording_revisions
     set editorial_authority_path = p_path,
         editorial_authority_fingerprint = p_fingerprint,
         editorial_authority_revision = editorial_authority_revision + 1,
         updated_at = now(),
         updated_by = auth.uid()
   where id = p_revision_id
     and workspace_id = p_workspace_id
     and workpiece_id = p_workpiece_id
     and canonical_recording_id = p_canonical_recording_id
     and status = 'active'
     and updated_at = p_expected_revision_updated_at
     and editorial_authority_revision = p_expected_authority_revision
     and editorial_authority_path is not distinct from p_expected_authority_path
  returning * into v_row;

  if v_row.id is null then
    raise exception using errcode = 'PT409', message = 'editorial_authority_conflict';
  end if;

  return jsonb_build_object(
    'revision_id', v_row.id,
    'canonical_recording_id', v_row.canonical_recording_id,
    'path', v_row.editorial_authority_path,
    'fingerprint', v_row.editorial_authority_fingerprint,
    'authority_revision', v_row.editorial_authority_revision,
    'revision_updated_at', v_row.updated_at
  );
end;
$_$;


ALTER FUNCTION "tongs"."acknowledge_hammer_editorial_authority"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_canonical_recording_id" "uuid", "p_revision_id" "uuid", "p_path" "text", "p_fingerprint" "text", "p_expected_revision_updated_at" timestamp with time zone, "p_expected_authority_revision" bigint, "p_expected_authority_path" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."acknowledge_hearth_preflight_finding_v1"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_report_id" "uuid", "p_finding_key" "text", "p_action" "text", "p_note" "text", "p_operation_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare
  v_user uuid:=auth.uid();
  v_finding tongs.hearth_editorial_preflight_findings%rowtype;
  v_report tongs.hearth_editorial_preflight_reports%rowtype;
  v_ack tongs.hearth_preflight_finding_acknowledgements%rowtype;
begin
  if v_user is null or not tongs.has_workspace_role(p_workspace_id,'editor') then
    return jsonb_build_object('disposition','denied');
  end if;
  select * into v_ack
  from tongs.hearth_preflight_finding_acknowledgements
  where operation_id=p_operation_id;
  if found then
    return jsonb_build_object('disposition','duplicate','acknowledgement',to_jsonb(v_ack));
  end if;
  select r.* into v_report
  from tongs.hearth_editorial_preflight_reports r
  join tongs.workpiece_hearth_preflight_sequences s
    on s.current_report_id=r.id and s.current_revision=r.revision
  join tongs.workpiece_files wf
    on wf.workpiece_id=r.workpiece_id
    and wf.path=r.source_file_path
    and lower(wf.hash_value)=r.script_content_hash
  where r.id=p_report_id
    and r.workspace_id=p_workspace_id
    and r.workpiece_id=p_workpiece_id
    and (
      r.research_artifact_id is null
      or exists(
        select 1
        from tongs.workpiece_hearth_research_sequences rs
        join tongs.hearth_research_artifact_revisions ra on ra.id=rs.current_artifact_id
        where rs.workspace_id=r.workspace_id
          and rs.workpiece_id=r.workpiece_id
          and ra.id=r.research_artifact_id
          and ra.artifact_content_hash=r.research_artifact_hash
      )
    );
  if not found then
    return jsonb_build_object('disposition','stale','reason','preflight_not_current');
  end if;
  select * into v_finding
  from tongs.hearth_editorial_preflight_findings
  where report_id=p_report_id
    and finding_key=p_finding_key
    and workspace_id=p_workspace_id
    and workpiece_id=p_workpiece_id;
  if not found then
    return jsonb_build_object('disposition','not_found','reason','finding_not_found');
  end if;
  if p_action not in ('acknowledge','resolve')
    or (v_finding.severity='blocker' and p_action<>'resolve') then
    return jsonb_build_object('disposition','invalid','reason','blocking_findings_require_resolution');
  end if;

  -- An identical advisory decision already made for the same script bytes and
  -- checker contract is the durable decision. A prior resolve also dominates
  -- a later acknowledge request. Do not manufacture a report-local duplicate.
  select a.* into v_ack
  from tongs.hearth_preflight_finding_acknowledgements a
  join tongs.hearth_editorial_preflight_findings prior_finding
    on prior_finding.report_id=a.report_id
    and prior_finding.ordinal=a.finding_ordinal
  join tongs.hearth_editorial_preflight_reports prior_report
    on prior_report.id=prior_finding.report_id
  where prior_report.workspace_id=p_workspace_id
    and prior_report.workpiece_id=p_workpiece_id
    and prior_report.script_content_hash=v_report.script_content_hash
    and prior_report.checker_contract_version=v_report.checker_contract_version
    and prior_finding.finding_basis_hash=v_finding.finding_basis_hash
    and (a.action=p_action or a.action='resolve')
  order by case when a.action='resolve' then 1 else 0 end desc, a.acted_at desc
  limit 1;
  if found then
    return jsonb_build_object('disposition','duplicate','acknowledgement',to_jsonb(v_ack));
  end if;

  insert into tongs.hearth_preflight_finding_acknowledgements(
    workspace_id,workpiece_id,report_id,report_revision,finding_ordinal,
    action,note,operation_id,acted_by
  ) values(
    p_workspace_id,p_workpiece_id,p_report_id,v_finding.report_revision,
    v_finding.ordinal,p_action,nullif(btrim(coalesce(p_note,'')),''),p_operation_id,v_user
  ) returning * into v_ack;
  return jsonb_build_object('disposition','saved','acknowledgement',to_jsonb(v_ack));
end;
$$;


ALTER FUNCTION "tongs"."acknowledge_hearth_preflight_finding_v1"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_report_id" "uuid", "p_finding_key" "text", "p_action" "text", "p_note" "text", "p_operation_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."acquire_openai_text_aggregate_admission"("p_reservation_id" "uuid", "p_caller_class" "text", "p_provider_mode" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare b tongs.openai_text_funding_bindings%rowtype; r tongs.funding_reservations%rowtype;
 q tongs.customer_spending_quotes%rowtype; qb tongs.openai_text_customer_quote_bindings%rowtype;
 c tongs.openai_text_cost_policy_revisions%rowtype; a tongs.paid_execution_aggregate_assignments%rowtype;
 existing tongs.paid_operation_aggregate_bindings%rowtype; capability text; funding_class text;
 environment text; hold_id uuid; admitted jsonb; workspace uuid; supplier bigint;
 rollout tongs.openai_text_rollout_revisions%rowtype;
begin
 perform tongs._require_pricing_service_role();
 if p_caller_class not in ('interactive','background','retry','recovery') or p_provider_mode not in ('real','simulated','byo') then raise exception 'invalid aggregate caller context' using errcode='22023'; end if;
 select * into existing from tongs.paid_operation_aggregate_bindings where reservation_id=p_reservation_id;
 if found then return jsonb_build_object('enforcement_enabled',true,'authorized',true,'replay',true,'hold_id',existing.hold_id,'reason','existing_authoritative_admission'); end if;
 select * into b from tongs.openai_text_funding_bindings where reservation_id=p_reservation_id;
 select * into r from tongs.funding_reservations where id=p_reservation_id;
 select * into q from tongs.customer_spending_quotes where id=r.quote_id;
 select * into rollout from tongs._openai_rollout_for_funding(b.route_code,b.credential_funding);
 if rollout.mode<>'enforce' and not exists(select 1 from tongs._owner_paid_execution_canary_for_reservation(p_reservation_id)) then
  return jsonb_build_object('enforcement_enabled',false,'authorized',false,'replay',false,'reason','rollout_halt_new');
 end if;
 if exists (
   select 1 from tongs.customer_paid_execution_scope_authorizations scope_auth
   where scope_auth.id = r.rollout_authorization_id
     and scope_auth.authorization_kind = 'normal_customer'
     and scope_auth.status = 'active'
 ) then
   return jsonb_build_object('enforcement_enabled',false,'authorized',true,'replay',false,'reason','normal_customer_credit_bounded');
 end if;
 select * into qb from tongs.openai_text_customer_quote_bindings where quote_id=q.id;
 select * into c from tongs.openai_text_cost_policy_revisions where id=b.cost_policy_revision_id;
 if b.operation_id is null or r.id is null or q.id is null or qb.quote_id is null or c.id is null or q.workspace_id is null
    or not exists(select 1 from tongs.customer_spending_quote_acceptances accepted where accepted.quote_id=q.id and accepted.user_id=r.user_id)
    or q.operation_id<>r.operation_id or qb.canonical_operation_id<>b.operation_id
    or qb.user_id<>r.user_id or qb.workspace_id<>q.workspace_id or qb.request_fingerprint<>q.request_fingerprint
    or qb.runtime_model<>b.model or qb.cost_policy_revision_id<>b.cost_policy_revision_id
    or qb.pricing_revision_id<>q.pricing_revision_id or q.request_fingerprint is null
    or c.cost_coverage<>'complete' or c.full_cost_ceiling_micros<>r.reserved_wholesale_spend_micros then
  raise exception 'exact accepted funding and complete cost policy required' using errcode='42501';
 end if;
 workspace:=q.workspace_id; funding_class:=tongs._aggregate_funding_class(r);
 environment:=case when r.funding_environment='test' then 'test' else 'production' end;
 select * into a from tongs._active_paid_execution_aggregate_assignment(r.user_id,workspace,environment);
 if not found then return jsonb_build_object('enforcement_enabled',false,'authorized',true,'replay',false,'reason','aggregate_assignment_inactive'); end if;
 capability:=case b.route_code
  when 'hearth.chat_completion' then 'openai.text.hearth_chat'
  when 'hearth.research_synthesis' then 'openai.text.hearth_research'
  when 'visual.unified_plan' then 'openai.text.visual_unified_plan'
  when 'visual.narrative_interpretation' then 'openai.text.visual_narrative'
  when 'motion.broll_interpretation' then 'openai.text.motion_broll'
  when 'hammer.transcript_cleanup' then 'openai.text.hammer_cleanup'
  when 'shorts.discovery' then 'openai.text.shorts_discovery'
  when 'quench.metadata' then 'openai.text.quench_metadata' else null end;
 if capability is null then raise exception 'unmapped paid OpenAI route' using errcode='P0001'; end if;
 if b.credential_funding='byo_customer' and p_provider_mode<>'byo' then raise exception 'BYO provider mode required' using errcode='42501'; end if;
 if b.credential_funding='forge' and p_provider_mode='byo' then raise exception 'Forge provider mode required' using errcode='42501'; end if;
 if funding_class='test_customer' and b.credential_funding='byo_customer' and c.supporting_cost_ceiling_micros>0 then
  return jsonb_build_object('enforcement_enabled',true,'authorized',false,'reason','test_supporting_real_provider_forbidden'); end if;
 supplier:=case when b.credential_funding='forge' then c.direct_provider_ceiling_micros else 0 end;
 hold_id:=extensions.uuid_generate_v5(p_reservation_id,'aggregate-exposure');
 admitted:=tongs.reserve_restricted_beta_exposure(hold_id,a.policy_revision_id,capability,b.operation_id,r.user_id,workspace,q.request_fingerprint,
  b.model,funding_class,p_reservation_id::text,p_provider_mode,p_caller_class,r.reserved_customer_charge_micros,supplier,
  c.supporting_cost_ceiling_micros,0,0,0,180,p_reservation_id::text||':aggregate-reserved');
 if coalesce((admitted->>'authorized')::boolean,false) then
  insert into tongs.paid_operation_aggregate_bindings(
   reservation_id,hold_id,policy_revision_id,capability_code,provider,operation_id,user_id,workspace_id,
   request_fingerprint,model_or_sku,funding_source_type,credential_funding,provider_mode,pricing_revision_id,
   cost_policy_revision_id,customer_funding_ceiling_micros,supplier_exposure_ceiling_micros,supporting_exposure_ceiling_micros)
  values(r.id,hold_id,a.policy_revision_id,capability,'openai',b.operation_id,r.user_id,workspace,q.request_fingerprint,
   b.model,r.funding_source_type,b.credential_funding,p_provider_mode,q.pricing_revision_id,c.id,
   r.reserved_customer_charge_micros,supplier,c.supporting_cost_ceiling_micros);
 end if;
 return jsonb_build_object('enforcement_enabled',true)||admitted;
end
$$;


ALTER FUNCTION "tongs"."acquire_openai_text_aggregate_admission"("p_reservation_id" "uuid", "p_caller_class" "text", "p_provider_mode" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."acquire_owner_hearth_aggregate_admission"("p_reservation_id" "uuid", "p_caller_class" "text", "p_provider_mode" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare op tongs.owner_hearth_operation_authorizations%rowtype; authz tongs.owner_hearth_authorizations%rowtype; res tongs.funding_reservations%rowtype;
 cost tongs.openai_text_cost_policy_revisions%rowtype; existing tongs.paid_operation_aggregate_bindings%rowtype; hold_id uuid; admitted jsonb;
begin
 perform tongs._require_pricing_service_role();
 if p_provider_mode<>'real' or p_caller_class not in ('interactive','recovery') then raise exception 'owner Hearth provider context denied' using errcode='42501'; end if;
 select * into existing from tongs.paid_operation_aggregate_bindings where reservation_id=p_reservation_id;
 if found then return jsonb_build_object('enforcement_enabled',true,'authorized',true,'replay',true,'hold_id',existing.hold_id,'reason','existing_authoritative_admission'); end if;
 select * into op from tongs.owner_hearth_operation_authorizations where reservation_id=p_reservation_id;
 select * into authz from tongs.owner_hearth_authorizations where id=op.authorization_id;
 select * into res from tongs.funding_reservations where id=p_reservation_id;
 select * into cost from tongs.openai_text_cost_policy_revisions where id=op.cost_policy_revision_id;
 if op.id is null or authz.id is null or res.id is null or cost.id is null or res.funding_source_id<>authz.budget_id then
  raise exception 'owner Hearth aggregate authority missing' using errcode='42501'; end if;
 hold_id:=extensions.uuid_generate_v5(p_reservation_id,'aggregate-exposure');
 admitted:=tongs.reserve_restricted_beta_exposure(hold_id,op.aggregate_policy_revision_id,'openai.text.hearth_chat',op.operation_id,
  op.owner_user_id,op.workspace_id,op.request_fingerprint,op.provider_model_id,'owner_operating_budget',p_reservation_id::text,
  'real',p_caller_class,0,cost.direct_provider_ceiling_micros,cost.supporting_cost_ceiling_micros,0,3,0,180,
  p_reservation_id::text||':aggregate-reserved');
 if coalesce((admitted->>'authorized')::boolean,false) then
  insert into tongs.paid_operation_aggregate_bindings(reservation_id,hold_id,policy_revision_id,capability_code,provider,operation_id,user_id,
   workspace_id,request_fingerprint,model_or_sku,funding_source_type,credential_funding,provider_mode,pricing_revision_id,cost_policy_revision_id,
   customer_funding_ceiling_micros,supplier_exposure_ceiling_micros,supporting_exposure_ceiling_micros)
  values(res.id,hold_id,op.aggregate_policy_revision_id,'openai.text.hearth_chat','openai',op.operation_id,op.owner_user_id,op.workspace_id,
   op.request_fingerprint,op.provider_model_id,'owner_budget','forge','real',op.pricing_revision_id,cost.id,0,cost.direct_provider_ceiling_micros,cost.supporting_cost_ceiling_micros);
 end if;
 return jsonb_build_object('enforcement_enabled',true)||admitted;
end $$;


