CREATE OR REPLACE FUNCTION "tongs"."acquire_owner_hearth_research_aggregate_admission"("p_reservation_id" "uuid", "p_caller_class" "text", "p_provider_mode" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare o tongs.owner_hearth_research_operations%rowtype; a tongs.owner_hearth_research_authorizations%rowtype; existing tongs.paid_operation_aggregate_bindings%rowtype;
 hold_id uuid; admitted jsonb;
begin
 perform tongs._require_pricing_service_role();
 select * into existing from tongs.paid_operation_aggregate_bindings where reservation_id=p_reservation_id;
 if found then return jsonb_build_object('enforcement_enabled',true,'authorized',true,'replay',true,'hold_id',existing.hold_id); end if;
 select * into o from tongs.owner_hearth_research_operations where reservation_id=p_reservation_id;
 select * into a from tongs.owner_hearth_research_authorizations where id=o.authorization_id;
 if o.id is null or p_provider_mode<>'real' or p_caller_class not in('interactive','recovery') then raise exception 'research aggregate context denied' using errcode='42501'; end if;
 hold_id:=extensions.uuid_generate_v5(p_reservation_id,'owner-research-aggregate');
 admitted:=tongs.reserve_restricted_beta_exposure(hold_id,o.aggregate_policy_revision_id,'openai.text.hearth_research',o.operation_id,o.owner_user_id,o.workspace_id,
  o.request_fingerprint,o.provider_model_id,'owner_operating_budget',p_reservation_id::text,'real',p_caller_class,0,o.direct_provider_ceiling_micros,
  o.maximum_searches*5000+1456,o.storage_ceiling_micros,3,0,180,
  'owner-research:'||p_reservation_id::text||':aggregate');
 if coalesce((admitted->>'authorized')::boolean,false) then
  insert into tongs.paid_operation_aggregate_bindings values(p_reservation_id,hold_id,o.aggregate_policy_revision_id,'openai.text.hearth_research','openai',o.operation_id,
   o.owner_user_id,o.workspace_id,o.request_fingerprint,o.provider_model_id,'owner_budget','forge','real',o.pricing_revision_id,o.cost_policy_revision_id,0,
   o.direct_provider_ceiling_micros,o.maximum_searches*5000+1456+o.storage_ceiling_micros,now());
 end if;
 return jsonb_build_object('enforcement_enabled',true)||admitted;
end $$;


ALTER FUNCTION "tongs"."acquire_owner_hearth_research_aggregate_admission"("p_reservation_id" "uuid", "p_caller_class" "text", "p_provider_mode" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."acquire_runway_aggregate_admission"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_caller_class" "text", "p_provider_mode" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare b tongs.runway_funding_bindings%rowtype; r tongs.funding_reservations%rowtype; a tongs.paid_execution_aggregate_assignments%rowtype;
 existing tongs.paid_operation_aggregate_bindings%rowtype; funding_class text; environment text; hold_id uuid; admitted jsonb;
 rollout tongs.runway_execution_rollout_revisions%rowtype;
begin
 perform tongs._require_pricing_service_role();
 select * into b from tongs.runway_funding_bindings where operation_id=btrim(p_operation_id);
 if not found or b.operation_fingerprint<>p_operation_fingerprint or b.user_id<>p_user_id or b.workspace_id<>p_workspace_id then raise exception 'exact Runway funding binding required' using errcode='42501'; end if;
 select * into existing from tongs.paid_operation_aggregate_bindings where reservation_id=b.reservation_id;
 if found then return jsonb_build_object('enforcement_enabled',true,'authorized',true,'replay',true,'hold_id',existing.hold_id,'reason','existing_authoritative_admission'); end if;
 select * into r from tongs.funding_reservations where id=b.reservation_id;
 select * into rollout from tongs._current_runway_execution_rollout();
 if rollout.mode<>'enforce' then return jsonb_build_object('enforcement_enabled',false,'authorized',false,'replay',false,'reason','rollout_halt_new'); end if;
 funding_class:=tongs._aggregate_funding_class(r); environment:=case when funding_class='test_customer' then 'test' else 'production' end;
 select * into a from tongs._active_paid_execution_aggregate_assignment(p_user_id,p_workspace_id,environment);
 if not found then return jsonb_build_object('enforcement_enabled',false,'authorized',true,'replay',false,'reason','aggregate_assignment_inactive'); end if;
 if p_provider_mode<>'real' then raise exception 'Runway Forge credential requires real provider mode' using errcode='42501'; end if;
 hold_id:=extensions.uuid_generate_v5(b.reservation_id,'aggregate-exposure');
 admitted:=tongs.reserve_restricted_beta_exposure(hold_id,a.policy_revision_id,'runway.video',b.operation_id,b.user_id,b.workspace_id,b.operation_fingerprint,b.model||':'||b.duration_seconds::text||'s:'||b.ratio,funding_class,b.reservation_id::text,p_provider_mode,p_caller_class,r.reserved_customer_charge_micros,b.direct_provider_ceiling_micros,b.supporting_cost_ceiling_micros,0,0,0,300,b.reservation_id::text||':aggregate-reserved');
 if coalesce((admitted->>'authorized')::boolean,false) then
  insert into tongs.paid_operation_aggregate_bindings(reservation_id,hold_id,policy_revision_id,capability_code,provider,operation_id,user_id,workspace_id,request_fingerprint,model_or_sku,funding_source_type,credential_funding,provider_mode,pricing_revision_id,cost_policy_revision_id,customer_funding_ceiling_micros,supplier_exposure_ceiling_micros,supporting_exposure_ceiling_micros)
  values(r.id,hold_id,a.policy_revision_id,'runway.video','runway',b.operation_id,b.user_id,b.workspace_id,b.operation_fingerprint,b.model||':'||b.duration_seconds::text||'s:'||b.ratio,r.funding_source_type,'forge',p_provider_mode,b.pricing_revision_id,null,r.reserved_customer_charge_micros,b.direct_provider_ceiling_micros,b.supporting_cost_ceiling_micros);
 end if;
 return jsonb_build_object('enforcement_enabled',true)||admitted;
end
$$;


ALTER FUNCTION "tongs"."acquire_runway_aggregate_admission"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_caller_class" "text", "p_provider_mode" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."activate_customer_hearth_chat_luna_test"("p_authorization_id" "uuid", "p_operator_user_id" "uuid", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_pricing_revision_id" "uuid", "p_cost_policy_revision_id" "uuid", "p_publication_id" "uuid", "p_authorization_expires_at" timestamp with time zone, "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_now timestamptz:=clock_timestamp();
  v_reason text:=nullif(btrim(coalesce(p_reason,'')),'');
  v_pricing tongs.private_pricing_revisions%rowtype;
  v_policy tongs.private_pricing_policies%rowtype;
  v_cost tongs.openai_text_cost_policy_revisions%rowtype;
  v_existing tongs.customer_paid_execution_test_authorizations%rowtype;
  v_current_publication tongs.private_pricing_publications%rowtype;
  v_control tongs.paid_execution_control_revisions%rowtype;
  v_rollout tongs.openai_text_rollout_revisions%rowtype;
  v_control_revision integer;
  v_rollout_revision integer;
  v_publication jsonb;
begin
  perform tongs._require_pricing_service_role();
  if p_authorization_id is null or p_publication_id is null or p_operator_user_id is null
     or not tongs.is_platform_operator(p_operator_user_id) or p_user_id is null
     or p_workspace_id is null or p_pricing_revision_id is null or p_cost_policy_revision_id is null
     or v_reason is null or p_authorization_expires_at<=v_now
     or p_authorization_expires_at>v_now+interval '24 hours' then
    raise exception 'invalid bounded customer Hearth Luna activation' using errcode='22023';
  end if;
  if not exists (
    select 1 from tongs.workspaces workspace
    where workspace.id=p_workspace_id and (
      workspace.created_by=p_user_id or exists (
        select 1 from tongs.workspace_members member
        where member.workspace_id=workspace.id and member.user_id=p_user_id
      )
    )
  ) then
    raise exception 'test customer cannot access designated workspace' using errcode='42501';
  end if;
  select * into v_existing from tongs.customer_paid_execution_test_authorizations
    where id=p_authorization_id;
  if found then
    if v_existing.user_id<>p_user_id or v_existing.workspace_id<>p_workspace_id
       or v_existing.pricing_revision_id<>p_pricing_revision_id
       or v_existing.cost_policy_revision_id<>p_cost_policy_revision_id
       or v_existing.authorization_expires_at<>p_authorization_expires_at then
      raise exception 'customer Hearth Luna activation replay conflict' using errcode='23505';
    end if;
    return jsonb_build_object('authorization_id',v_existing.id,'replay',true,
      'status',(select revision.status from tongs.customer_paid_execution_test_authorization_revisions revision
        where revision.authorization_id=v_existing.id order by revision.revision desc limit 1),
      'maximum_operation_count',1,'maximum_customer_charge_micros',20000);
  end if;
  select * into v_pricing from tongs.private_pricing_revisions where id=p_pricing_revision_id;
  select * into v_policy from tongs.private_pricing_policies where id=v_pricing.policy_id;
  select * into v_cost from tongs.openai_text_cost_policy_revisions where id=p_cost_policy_revision_id;
  if v_pricing.id is null or v_policy.id is null or v_cost.id is null
     or v_pricing.lifecycle_state<>'review_ready' or v_pricing.currency<>'USD'
     or v_pricing.markup_basis_points<>3300 or v_pricing.full_cost_ceiling_micros<>11015
     or v_pricing.failure_cost_ceiling_micros<>0
     or tongs.round_customer_price_micros(
       v_pricing.full_cost_ceiling_micros::numeric*(10000+v_pricing.markup_basis_points)/10000,
       v_pricing.currency
     )<>20000
     or v_policy.scope_kind<>'sku' or lower(v_policy.provider)<>'openai'
     or lower(v_policy.sku)<>'gpt-5.6-luna'
     or v_cost.route_code<>'hearth.chat_completion' or v_cost.full_cost_ceiling_micros<>11015
     or v_cost.maximum_input_units<>2000 or v_cost.maximum_output_units<>512
     or v_cost.maximum_attempts<>1 or v_cost.cost_coverage<>'complete'
     or v_cost.lifecycle_state not in ('pilot_candidate','active') then
    raise exception 'exact approved Hearth Luna customer pricing and cost revisions required' using errcode='P0001';
  end if;
  if not exists (
    select 1 from tongs.openai_text_failure_loss_policy_revisions failure_policy
    where failure_policy.route_code='hearth.chat_completion'
      and failure_policy.environment='production' and failure_policy.lifecycle_state='active'
      and failure_policy.per_operation_limit_micros>=11015
      and failure_policy.aggregate_limit_micros>=11015
      and failure_policy.maximum_concurrency=1
  ) then
    raise exception 'bounded Forge failure-loss policy is not active' using errcode='P0001';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('customer-hearth-luna-test-activation',0));
  if exists (
    select 1 from tongs.customer_paid_execution_test_authorizations a
    join lateral (
      select revision.status from tongs.customer_paid_execution_test_authorization_revisions revision
      where revision.authorization_id=a.id order by revision.revision desc limit 1
    ) latest on true
    where a.route_code='hearth.chat_completion' and latest.status='active'
      and clock_timestamp()<a.authorization_expires_at
  ) then
    raise exception 'another customer Hearth paid test authorization is active' using errcode='P0001';
  end if;
  select distinct on (publication.policy_id) publication.* into v_current_publication
  from tongs.private_pricing_publications publication
  where publication.policy_id=v_policy.id
  order by publication.policy_id,publication.publication_revision desc;
  if v_current_publication.action is distinct from 'published'
     or v_current_publication.pricing_revision_id is distinct from v_pricing.id then
    perform set_config('request.jwt.claim.sub',p_operator_user_id::text,true);
    v_publication:=tongs.publish_private_pricing_revision(
      p_publication_id,p_pricing_revision_id,v_reason
    );
  else
    v_publication:=jsonb_build_object('publication_id',v_current_publication.id,
      'pricing_revision_id',v_current_publication.pricing_revision_id,'replay',true);
  end if;
  select * into v_control from tongs._current_paid_execution_control();
  if not v_control.pricing_activation_enabled or not v_control.provider_execution_enabled then
    raise exception 'provider execution controls are not active' using errcode='42501';
  end if;
  if not v_control.customer_settlement_enabled then
    select coalesce(max(revision),0)+1 into v_control_revision
      from tongs.paid_execution_control_revisions;
    insert into tongs.paid_execution_control_revisions(
      revision,pricing_activation_enabled,reservation_shadow_enabled,customer_settlement_enabled,
      owner_budget_spending_enabled,provider_execution_enabled,reason,actor_id
    ) values (
      v_control_revision,true,true,true,v_control.owner_budget_spending_enabled,true,v_reason,p_operator_user_id
    );
  else
    v_control_revision:=v_control.revision;
  end if;
  select * into v_rollout from tongs._current_openai_text_rollout('hearth.chat_completion');
  if v_rollout.mode<>'enforce' or v_rollout.cost_policy_revision_id is distinct from v_cost.id then
    select coalesce(max(revision),0)+1 into v_rollout_revision
      from tongs.openai_text_rollout_revisions where route_code='hearth.chat_completion';
    insert into tongs.openai_text_rollout_revisions(
      route_code,revision,mode,cost_policy_revision_id,reason,actor_id
    ) values ('hearth.chat_completion',v_rollout_revision,'enforce',v_cost.id,v_reason,p_operator_user_id);
  else
    v_rollout_revision:=v_rollout.revision;
  end if;
  insert into tongs.customer_paid_execution_test_authorizations(
    id,user_id,workspace_id,route_code,provider,model,pricing_revision_id,
    cost_policy_revision_id,maximum_operation_count,maximum_customer_charge_micros,
    authorization_expires_at,reason,created_by
  ) values (
    p_authorization_id,p_user_id,p_workspace_id,'hearth.chat_completion','openai','gpt-5.6-luna',
    p_pricing_revision_id,p_cost_policy_revision_id,1,20000,p_authorization_expires_at,v_reason,p_operator_user_id
  );
  insert into tongs.customer_paid_execution_test_authorization_revisions(
    authorization_id,revision,status,reason,actor_id
  ) values (p_authorization_id,1,'active',v_reason,p_operator_user_id);
  return jsonb_build_object('authorization_id',p_authorization_id,'replay',false,'status','active',
    'publication',v_publication,'pricing_revision_id',p_pricing_revision_id,
    'cost_policy_revision_id',p_cost_policy_revision_id,'control_revision',v_control_revision,
    'rollout_revision',v_rollout_revision,'maximum_operation_count',1,
    'maximum_customer_charge_micros',20000,'authorization_expires_at',p_authorization_expires_at);
end $$;


ALTER FUNCTION "tongs"."activate_customer_hearth_chat_luna_test"("p_authorization_id" "uuid", "p_operator_user_id" "uuid", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_pricing_revision_id" "uuid", "p_cost_policy_revision_id" "uuid", "p_publication_id" "uuid", "p_authorization_expires_at" timestamp with time zone, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."activate_financial_runtime_environment"("p_environment" "text", "p_actor_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_configuration tongs.financial_environment_configuration_revisions%rowtype;
  v_revision integer;
begin
  perform tongs._require_pricing_service_role();
  if p_actor_id is null or not tongs.is_platform_operator(p_actor_id)
     or p_environment not in ('test', 'live')
     or nullif(btrim(coalesce(p_reason, '')), '') is null then
    raise exception 'platform operator and activation reason required' using errcode = '42501';
  end if;
  select * into v_configuration
  from tongs.financial_environment_configuration_revisions
  where environment = p_environment
  order by revision desc limit 1;
  if not found or v_configuration.lifecycle_state not in ('certification_ready', 'inactive_ready')
     or v_configuration.cost_policy_revision_id is null
     or v_configuration.pricing_revision_id is null then
    raise exception 'financial environment is not activation-ready' using errcode = 'P0001';
  end if;
  perform pg_advisory_xact_lock(hashtext('financial-runtime-environment'));
  select coalesce(max(revision), 0) + 1 into v_revision
  from tongs.financial_runtime_environment_revisions;
  insert into tongs.financial_runtime_environment_revisions(
    revision, financial_environment, reason, actor_id
  ) values (v_revision, p_environment, btrim(p_reason), p_actor_id);
  return jsonb_build_object(
    'financial_environment', p_environment,
    'runtime_revision', v_revision,
    'configuration_revision', v_configuration.revision
  );
end $$;


ALTER FUNCTION "tongs"."activate_financial_runtime_environment"("p_environment" "text", "p_actor_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."activate_hammer_customer_test_acceptance"("p_authorization_id" "uuid", "p_actor_id" "uuid", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_valid_until" timestamp with time zone, "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_now timestamptz := clock_timestamp();
  v_existing tongs.customer_paid_execution_scope_authorizations%rowtype;
  v_rollout tongs.openai_text_rollout_revisions%rowtype;
  v_test_loss tongs.openai_text_failure_loss_rollout_revisions%rowtype;
  v_live_loss tongs.openai_text_failure_loss_rollout_revisions%rowtype;
  v_cost tongs.openai_text_cost_policy_revisions%rowtype;
  v_price tongs.private_pricing_revisions%rowtype;
  v_eligible record;
  v_eligible_credits jsonb;
begin
  perform tongs._require_pricing_service_role();
  if p_authorization_id is null or p_actor_id is null
     or not tongs.is_platform_operator(p_actor_id)
     or p_user_id is null or p_user_id = p_actor_id or p_workspace_id is null
     or p_valid_until is null or p_valid_until <= v_now
     or p_valid_until > v_now + interval '24 hours'
     or length(btrim(coalesce(p_reason, ''))) not between 8 and 500 then
    raise exception 'invalid bounded Hammer customer Test activation'
      using errcode = '22023';
  end if;
  if not exists (select 1 from auth.users where id = p_user_id)
     or tongs.is_platform_operator(p_user_id)
     or exists (
       select 1 from tongs.account_authority_classifications
       where user_id = p_user_id and account_class = 'owner'
     )
     or not exists (
       select 1 from tongs.workspace_members
       where user_id = p_user_id and workspace_id = p_workspace_id
     ) then
    raise exception 'canonical customer and workspace membership required'
      using errcode = '42501';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended('hammer-customer-test-acceptance', 0)
  );

  select * into v_existing
  from tongs.customer_paid_execution_scope_authorizations
  where id = p_authorization_id;
  if found then
    if v_existing.authorization_kind <> 'normal_customer'
       or v_existing.user_id <> p_user_id
       or v_existing.workspace_id <> p_workspace_id
       or v_existing.financial_environment <> 'test'
       or v_existing.route_code <> 'hammer.transcript_cleanup'
       or v_existing.provider <> 'openai'
       or v_existing.model_or_sku <> 'gpt-5.4-mini'
       or v_existing.pricing_revision_id <> '40010000-0000-4000-8000-000000000402'::uuid
       or v_existing.cost_policy_revision_id <> '40010000-0000-4000-8000-000000000301'::uuid
       or v_existing.maximum_operation_count <> 1
       or v_existing.maximum_customer_charge_micros <> 230000
       or v_existing.maximum_wholesale_exposure_micros <> 169728
       or v_existing.maximum_concurrency <> 1
       or v_existing.valid_until <> p_valid_until
       or v_existing.reason <> btrim(p_reason)
       or (select revision from tongs.openai_text_rollout_revisions
           where route_code = 'hammer.transcript_cleanup'
           order by revision desc limit 1) <> 4
       or (select mode from tongs.openai_text_rollout_revisions
           where route_code = 'hammer.transcript_cleanup'
           order by revision desc limit 1) <> 'enforce'
       or (select revision from tongs.openai_text_failure_loss_rollout_revisions
           where route_code = 'hammer.transcript_cleanup'
             and financial_environment = 'test'
           order by revision desc limit 1) <> 2
       or (select mode from tongs.openai_text_failure_loss_rollout_revisions
           where route_code = 'hammer.transcript_cleanup'
             and financial_environment = 'test'
           order by revision desc limit 1) <> 'enforce'
       or (select mode from tongs.openai_text_failure_loss_rollout_revisions
           where route_code = 'hammer.transcript_cleanup'
             and financial_environment = 'live'
           order by revision desc limit 1) <> 'halt_new'
       or exists (
         select 1 from tongs.customer_paid_execution_scope_authorizations
         where route_code = 'hammer.transcript_cleanup'
           and financial_environment = 'live'
       ) then
      raise exception 'Hammer customer Test activation replay conflict'
        using errcode = '23505';
    end if;
    return jsonb_build_object(
      'authorization_id', v_existing.id,
      'financial_environment', 'test',
      'route_code', 'hammer.transcript_cleanup',
      'model', 'gpt-5.4-mini',
      'customer_credit_units', 46,
      'maximum_customer_charge_micros', 230000,
      'maximum_wholesale_exposure_micros', 169728,
      'maximum_operation_count', 1,
      'valid_until', v_existing.valid_until,
      'live_authority_count', 0,
      'replay', true
    );
  end if;

  if exists (
    select 1 from tongs.customer_paid_execution_scope_authorizations
    where route_code = 'hammer.transcript_cleanup'
      and authorization_kind = 'normal_customer'
  )
  or exists (
    select 1 from tongs.customer_paid_execution_scope_authorizations
    where route_code = 'hammer.transcript_cleanup'
      and financial_environment = 'live'
  )
  or exists (
    select 1
    from tongs.customer_paid_execution_scope_authorizations scope_auth
    where scope_auth.route_code = 'hammer.transcript_cleanup'
      and scope_auth.authorization_kind in ('certification', 'owner_only')
      and tongs._hammer_scope_has_remaining_authority(
        scope_auth.id, v_now
      )
  )
  or exists (
    select 1
    from tongs.customer_paid_execution_scope_authorizations scope_auth
    where scope_auth.route_code = 'hammer.transcript_cleanup'
      and tongs._hammer_scope_is_effective(scope_auth.id, v_now)
  ) then
    raise exception 'Hammer customer Test activation already exists'
      using errcode = '23505';
  end if;

  select * into v_rollout
  from tongs.openai_text_rollout_revisions
  where route_code = 'hammer.transcript_cleanup'
  order by revision desc limit 1;
  select * into v_test_loss
  from tongs.openai_text_failure_loss_rollout_revisions
  where route_code = 'hammer.transcript_cleanup' and financial_environment = 'test'
  order by revision desc limit 1;
  select * into v_live_loss
  from tongs.openai_text_failure_loss_rollout_revisions
  where route_code = 'hammer.transcript_cleanup' and financial_environment = 'live'
  order by revision desc limit 1;
  if v_rollout.revision <> 3 or v_rollout.mode <> 'halt_new'
     or v_rollout.funding_scope <> 'forge'
     or v_test_loss.revision <> 1 or v_test_loss.mode <> 'halt_new'
     or v_live_loss.revision <> 1 or v_live_loss.mode <> 'halt_new'
     or exists (
       select 1 from tongs.customer_paid_execution_scope_authorizations
       where route_code = 'hammer.transcript_cleanup'
         and financial_environment = 'live'
     ) then
    raise exception 'exact Hammer halt-new baseline required for activation'
      using errcode = '42501';
  end if;

  select * into v_eligible
  from tongs._eligible_ai_models_for_operation('hammer.transcript_cleanup') eligible
  where eligible.runtime_model_id = 'gpt-5.4-mini'
    and eligible.cost_policy_revision_id = '40010000-0000-4000-8000-000000000301'::uuid
    and eligible.customer_credit_units = 46;
  select jsonb_agg(customer_credit_units order by customer_credit_units)
    into v_eligible_credits
  from tongs._eligible_ai_models_for_operation('hammer.transcript_cleanup');
  select * into v_cost from tongs.openai_text_cost_policy_revisions
  where id = '40010000-0000-4000-8000-000000000301'::uuid;
  select * into v_price from tongs.private_pricing_revisions
  where id = '40010000-0000-4000-8000-000000000402'::uuid;

  if v_eligible.runtime_model_id is null
     or v_eligible_credits <> '[46,129,258]'::jsonb
     or v_cost.route_code <> 'hammer.transcript_cleanup'
     or v_cost.maximum_attempts <> 1
     or v_cost.full_cost_ceiling_micros <> 169728
     or v_cost.cost_coverage <> 'complete'
     or v_cost.lifecycle_state <> 'active'
     or v_price.lifecycle_state <> 'review_ready'
     or v_price.currency <> 'USD'
     or v_price.customer_credit_units <> 46
     or v_price.customer_price_ceiling_micros <> 230000
     or v_price.full_cost_ceiling_micros <> 169728
     or v_price.failure_cost_ceiling_micros <> 0
     or not exists (
       select 1
       from tongs.private_pricing_publications publication
       where publication.pricing_revision_id = v_price.id
         and publication.action = 'published'
         and publication.publication_revision = 1
     )
     or v_test_loss.loss_policy_revision_id <> '40010000-0000-4000-8000-000000000601'::uuid
     or not exists (
       select 1 from tongs.openai_text_failure_loss_policy_revisions
       where id = v_test_loss.loss_policy_revision_id
         and route_code = 'hammer.transcript_cleanup'
         and environment = 'test' and revision = 1
         and per_operation_limit_micros = 967680
         and aggregate_limit_micros = 967680
         and rolling_window_seconds = 86400
         and maximum_concurrency = 1
         and lifecycle_state = 'active'
     ) then
    raise exception 'approved Hammer Mini price, cost, and loss authority required'
      using errcode = '42501';
  end if;

  insert into tongs.openai_text_rollout_revisions(
    route_code, revision, mode, cost_policy_revision_id,
    reason, actor_id, funding_scope
  ) values (
    'hammer.transcript_cleanup', 4, 'enforce',
    '40010000-0000-4000-8000-000000000301',
    btrim(p_reason), p_actor_id, 'forge'
  );
  insert into tongs.openai_text_failure_loss_rollout_revisions(
    route_code, financial_environment, revision, mode,
    loss_policy_revision_id, source_limit_event_id, reason, actor_id
  ) values (
    'hammer.transcript_cleanup', 'test', 2, 'enforce',
    '40010000-0000-4000-8000-000000000601', null,
    btrim(p_reason), p_actor_id
  );
  insert into tongs.customer_paid_execution_scope_authorizations(
    id, user_id, workspace_id, financial_environment, route_code, provider,
    model_or_sku, pricing_revision_id, cost_policy_revision_id,
    maximum_operation_count, maximum_customer_charge_micros,
    maximum_wholesale_exposure_micros, maximum_concurrency,
    rolling_window_seconds, valid_from, valid_until, status, reason,
    created_by, authorization_kind
  ) values (
    p_authorization_id, p_user_id, p_workspace_id, 'test',
    'hammer.transcript_cleanup', 'openai', 'gpt-5.4-mini',
    '40010000-0000-4000-8000-000000000402',
    '40010000-0000-4000-8000-000000000301',
    1, 230000, 169728, 1, null,
    v_now, p_valid_until, 'active', btrim(p_reason),
    p_actor_id, 'normal_customer'
  ) returning * into v_existing;

  if (select count(*) from tongs.customer_paid_execution_scope_authorizations
      where route_code = 'hammer.transcript_cleanup'
        and financial_environment = 'test'
        and authorization_kind = 'normal_customer') <> 1
     or (select count(*)
         from tongs.customer_paid_execution_scope_authorizations scope_auth
         where scope_auth.route_code = 'hammer.transcript_cleanup'
           and tongs._hammer_scope_is_effective(scope_auth.id, v_now)) <> 1
     or not tongs._hammer_scope_is_effective(v_existing.id, v_now)
     or exists (
       select 1 from tongs.customer_paid_execution_scope_authorizations
       where route_code = 'hammer.transcript_cleanup'
         and financial_environment = 'live'
     )
     or (select mode from tongs.openai_text_failure_loss_rollout_revisions
         where route_code = 'hammer.transcript_cleanup'
           and financial_environment = 'live'
         order by revision desc limit 1) <> 'halt_new' then
    raise exception 'Hammer activation escaped its single Test-only boundary'
      using errcode = '42501';
  end if;

  return jsonb_build_object(
    'authorization_id', v_existing.id,
    'financial_environment', 'test',
    'route_code', 'hammer.transcript_cleanup',
    'model', 'gpt-5.4-mini',
    'customer_credit_units', 46,
    'maximum_customer_charge_micros', 230000,
    'maximum_wholesale_exposure_micros', 169728,
    'maximum_operation_count', 1,
    'valid_until', v_existing.valid_until,
    'live_authority_count', 0,
    'replay', false
  );
end
$$;


ALTER FUNCTION "tongs"."activate_hammer_customer_test_acceptance"("p_authorization_id" "uuid", "p_actor_id" "uuid", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_valid_until" timestamp with time zone, "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."activate_hammer_customer_test_acceptance"("p_authorization_id" "uuid", "p_actor_id" "uuid", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_valid_until" timestamp with time zone, "p_reason" "text") IS 'Explicit service-role activation for one customer-funded Hammer transcript-cleanup Test operation. Applying the migration alone grants no execution authority.';



CREATE OR REPLACE FUNCTION "tongs"."activate_owner_hearth_chat_luna_pilot"("p_operator_user_id" "uuid", "p_workspace_id" "uuid", "p_budget_id" "uuid", "p_pricing_policy_id" "uuid", "p_pricing_revision_id" "uuid", "p_markup_rule_revision_id" "uuid", "p_failure_loss_policy_revision_id" "uuid", "p_decision_id" "uuid", "p_authorization_expires_at" timestamp with time zone, "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_now timestamptz:=clock_timestamp();
  v_reason text:=nullif(btrim(coalesce(p_reason,'')),'');
  v_rules tongs.private_markup_rule_revisions%rowtype;
  v_rollout tongs.openai_text_rollout_revisions%rowtype;
  v_control tongs.paid_execution_control_revisions%rowtype;
  v_budget tongs.owner_operating_budgets%rowtype;
  v_budget_revision tongs.owner_operating_budget_revisions%rowtype;
  v_pricing jsonb;
  v_budget_active jsonb;
  v_rollout_revision integer;
  v_loss_revision integer;
begin
  perform tongs._require_pricing_service_role();
  if p_operator_user_id is null or not tongs.is_platform_operator(p_operator_user_id)
     or p_workspace_id is null or p_budget_id is null or p_pricing_policy_id is null
     or p_pricing_revision_id is null or p_markup_rule_revision_id is null
     or p_failure_loss_policy_revision_id is null or p_decision_id is null
     or v_reason is null or p_authorization_expires_at<=v_now
     or p_authorization_expires_at>v_now+interval '24 hours' then
    raise exception 'invalid bounded Luna owner pilot activation' using errcode='22023';
  end if;
  if not exists(select 1 from tongs.workspaces w where w.id=p_workspace_id and
    (w.created_by=p_operator_user_id or exists(select 1 from tongs.workspace_members m
      where m.workspace_id=w.id and m.user_id=p_operator_user_id))) then
    raise exception 'operator cannot access pilot workspace' using errcode='42501';
  end if;
  if not exists(select 1 from tongs.openai_text_model_availability_checks
    where id='56560000-0000-4000-8000-000000000002'::uuid
      and provider_model_id='gpt-5.6-luna' and credential_class='forge_project_scoped'
      and check_kind='model_metadata_read' and accessible and http_status=200) then
    raise exception 'approved model availability check missing' using errcode='P0002';
  end if;
  select * into v_rules from tongs.private_markup_rule_revisions where id=p_markup_rule_revision_id;
  if not found or v_rules.default_markup_basis_points<>3300
     or tongs._effective_markup_basis_points(v_rules.id,'openai','gpt-5.6-luna')<>3300 then
    raise exception 'approved 33 percent markup revision required' using errcode='P0001';
  end if;
  if not exists(select 1 from tongs.openai_text_activation_proposals p
    where p.id='30000000-0000-4000-8000-000000000002'::uuid
      and p.cost_policy_revision_id='10000000-0000-4000-8000-000000000010'::uuid
      and p.model='gpt-5.6-luna' and p.maximum_input_units=2000
      and p.maximum_output_units=512 and p.maximum_attempts=1
      and p.direct_provider_ceiling_micros=1015
      and p.supporting_cost_ceiling_micros=10000
      and p.total_cost_ceiling_micros=11015
      and p.proposed_owner_budget_micros=11015
      and p.authorization_window_seconds=86400
      and p.status='awaiting_owner_approval') then
    raise exception 'exact bounded Luna activation proposal missing' using errcode='P0002';
  end if;
  select * into v_control from tongs._current_paid_execution_control();
  if not v_control.pricing_activation_enabled or not v_control.owner_budget_spending_enabled
     or not v_control.provider_execution_enabled or v_control.customer_settlement_enabled then
    raise exception 'owner-only provider controls are not safely configured' using errcode='42501';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('owner-hearth-openai-luna-pilot',0));
  select * into v_budget from tongs.owner_operating_budgets where id=p_budget_id;
  if found then
    select * into v_budget_revision from tongs.owner_operating_budget_revisions
      where budget_id=p_budget_id order by revision desc limit 1;
    if v_budget.environment<>'production' or v_budget.workspace_id is distinct from p_workspace_id
       or lower(coalesce(v_budget.provider,''))<>'openai'
       or lower(coalesce(v_budget.route,''))<>'hearth.chat_completion'
       or lower(coalesce(v_budget.sku,''))<>'gpt-5.6-luna'
       or v_budget.currency<>'USD' or v_budget_revision.status not in ('active','closed')
       or v_budget_revision.maximum_amount_micros<>11015 then
      raise exception 'owner Luna pilot activation replay conflict' using errcode='23505';
    end if;
    return jsonb_build_object('replay',true,'budget_id',p_budget_id,
      'budget_status',v_budget_revision.status,'maximum_amount_micros',11015,
      'customer_settlement_enabled',false);
  end if;
  if exists(select 1 from tongs.owner_operating_budgets b
    join lateral(select r.status from tongs.owner_operating_budget_revisions r
      where r.budget_id=b.id order by r.revision desc limit 1) latest on true
    where b.environment='production' and lower(coalesce(b.provider,''))='openai'
      and lower(coalesce(b.route,''))='hearth.chat_completion' and latest.status='active') then
    raise exception 'another active owner Hearth OpenAI budget exists' using errcode='P0001';
  end if;

  perform set_config('request.jwt.claim.sub',p_operator_user_id::text,true);
  v_pricing:=tongs.commit_operator_pricing_revision(
    p_markup_rule_revision_id,p_pricing_policy_id,
    'owner-openai-hearth-chat-luna-bounded-pilot','sku','openai','gpt-5.6-luna',0,
    p_pricing_revision_id,2,'USD',
    jsonb_build_array(
      jsonb_build_object('component_code','openai_text','component_kind','direct_provider',
        'credential_funding','forge','provider_label','OpenAI','success_ceiling_micros',1015,
        'failure_ceiling_micros',0,'cost_policy_revision','openai-text:hearth-chat:luna-bounded-pilot-v1',
        'tail_policy','none'),
      jsonb_build_object('component_code','bounded_support','component_kind','compute',
        'credential_funding','forge','provider_label','Forge validation and persistence',
        'success_ceiling_micros',10000,'failure_ceiling_micros',0,
        'cost_policy_revision','openai-text:hearth-chat:luna-bounded-pilot-v1','tail_policy','none')
    ),
    '[]'::jsonb,'["provider_failure","forge_failure","unknown_fault"]'::jsonb,
    '{"input_tokens":2000,"output_tokens":512,"attempts":1,"concurrency":1}'::jsonb,
    '{"kind":"none"}'::jsonb,v_reason
  );
  perform tongs.create_owner_operating_budget_draft(
    p_budget_id,'production',p_workspace_id,'openai','hearth.chat_completion',
    'gpt-5.6-luna','USD',v_now-interval '1 second',p_authorization_expires_at,v_reason
  );
  v_budget_active:=tongs.revise_owner_operating_budget(p_budget_id,'active',11015,v_reason);

  select coalesce(max(revision),0)+1 into v_loss_revision
    from tongs.openai_text_failure_loss_policy_revisions
    where route_code='hearth.chat_completion' and environment='production';
  insert into tongs.openai_text_failure_loss_policy_revisions(
    id,route_code,environment,revision,per_operation_limit_micros,aggregate_limit_micros,
    rolling_window_seconds,maximum_concurrency,lifecycle_state,reason,actor_id
  ) values (
    p_failure_loss_policy_revision_id,'hearth.chat_completion','production',v_loss_revision,
    11015,11015,86400,1,'active',v_reason,p_operator_user_id
  );
  select * into v_rollout from tongs._current_openai_text_rollout('hearth.chat_completion');
  if v_rollout.mode not in ('inactive','halt_new') then
    raise exception 'Hearth OpenAI rollout is already active' using errcode='P0001';
  end if;
  select coalesce(max(revision),0)+1 into v_rollout_revision
    from tongs.openai_text_rollout_revisions where route_code='hearth.chat_completion';
  insert into tongs.openai_text_rollout_revisions(
    route_code,revision,mode,cost_policy_revision_id,reason,actor_id
  ) values (
    'hearth.chat_completion',v_rollout_revision,'enforce',
    '10000000-0000-4000-8000-000000000010',v_reason,p_operator_user_id
  );
  insert into tongs.openai_text_activation_decisions(
    id,proposal_id,decision,operator_user_id,reason
  ) values (
    p_decision_id,'30000000-0000-4000-8000-000000000002','approved',p_operator_user_id,v_reason
  );
  return jsonb_build_object(
    'replay',false,'budget',v_budget_active,'pricing',v_pricing,
    'rollout_revision',v_rollout_revision,'rollout_mode','enforce',
    'failure_loss_policy_revision',v_loss_revision,'maximum_amount_micros',11015,
    'customer_settlement_enabled',false,'pricing_published',false
  );
end $$;


ALTER FUNCTION "tongs"."activate_owner_hearth_chat_luna_pilot"("p_operator_user_id" "uuid", "p_workspace_id" "uuid", "p_budget_id" "uuid", "p_pricing_policy_id" "uuid", "p_pricing_revision_id" "uuid", "p_markup_rule_revision_id" "uuid", "p_failure_loss_policy_revision_id" "uuid", "p_decision_id" "uuid", "p_authorization_expires_at" timestamp with time zone, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."activate_owner_hearth_chat_luna_retest"("p_operator_user_id" "uuid", "p_workspace_id" "uuid", "p_budget_id" "uuid", "p_pricing_revision_id" "uuid", "p_failure_loss_policy_revision_id" "uuid", "p_authorization_expires_at" timestamp with time zone, "p_corrected_reservation_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare v_now timestamptz:=clock_timestamp(); v_reason text:=nullif(btrim(coalesce(p_reason,'')),'');
  v_control tongs.paid_execution_control_revisions%rowtype;
  v_rollout tongs.openai_text_rollout_revisions%rowtype;
  v_budget tongs.owner_operating_budgets%rowtype;
  v_budget_revision tongs.owner_operating_budget_revisions%rowtype;
  v_budget_active jsonb; v_rollout_revision integer; v_loss_revision integer;
begin
  perform tongs._require_pricing_service_role();
  if p_operator_user_id is null or not tongs.is_platform_operator(p_operator_user_id)
     or p_workspace_id is null or p_budget_id is null or p_pricing_revision_id is null
     or p_failure_loss_policy_revision_id is null
     or p_corrected_reservation_id is null or v_reason is null
     or p_authorization_expires_at<=v_now or p_authorization_expires_at>v_now+interval '24 hours' then
    raise exception 'invalid bounded Luna owner retest activation' using errcode='22023';
  end if;
  if not exists(select 1 from tongs.workspaces w where w.id=p_workspace_id and
    (w.created_by=p_operator_user_id or exists(select 1 from tongs.workspace_members m
      where m.workspace_id=w.id and m.user_id=p_operator_user_id))) then
    raise exception 'operator cannot access retest workspace' using errcode='42501';
  end if;
  if not exists(select 1 from tongs.funding_failure_class_corrections c
    where c.reservation_id=p_corrected_reservation_id
      and c.original_failure_class='provider_failure'
      and c.corrected_failure_class='forge_validation_failure') then
    raise exception 'audited pilot failure correction required' using errcode='P0002';
  end if;
  if not exists(select 1 from tongs.openai_text_model_availability_checks
    where provider_model_id='gpt-5.6-luna' and credential_class='forge_project_scoped'
      and check_kind='model_metadata_read' and accessible and http_status=200) then
    raise exception 'Luna availability check missing' using errcode='P0002';
  end if;
  if not exists(select 1 from tongs.private_pricing_revisions p
    join tongs.private_pricing_policies policy on policy.id=p.policy_id
    where p.id=p_pricing_revision_id
      and p.lifecycle_state='review_ready' and p.full_cost_ceiling_micros=11015
      and p.markup_basis_points=3300 and lower(policy.provider)='openai'
      and lower(policy.sku)='gpt-5.6-luna') then
    raise exception 'exact reviewed Luna pricing revision missing' using errcode='P0002';
  end if;
  select * into v_control from tongs._current_paid_execution_control();
  if not v_control.pricing_activation_enabled or not v_control.owner_budget_spending_enabled
     or not v_control.provider_execution_enabled or v_control.customer_settlement_enabled then
    raise exception 'owner-only provider controls are not safely configured' using errcode='42501';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('owner-hearth-openai-luna-pilot',0));
  select * into v_budget from tongs.owner_operating_budgets where id=p_budget_id;
  if found then
    select * into v_budget_revision from tongs.owner_operating_budget_revisions
      where budget_id=p_budget_id order by revision desc limit 1;
    if v_budget.created_by<>p_operator_user_id or v_budget.workspace_id is distinct from p_workspace_id
       or v_budget.environment<>'production' or lower(coalesce(v_budget.provider,''))<>'openai'
       or lower(coalesce(v_budget.route,''))<>'hearth.chat_completion'
       or lower(coalesce(v_budget.sku,''))<>'gpt-5.6-luna'
       or v_budget_revision.maximum_amount_micros<>11015 then
      raise exception 'owner Luna retest replay conflict' using errcode='23505'; end if;
    return jsonb_build_object('replay',true,'budget_id',p_budget_id,
      'budget_status',v_budget_revision.status,'maximum_amount_micros',11015);
  end if;
  if exists(select 1 from tongs.owner_operating_budgets b
    join lateral(select r.status from tongs.owner_operating_budget_revisions r
      where r.budget_id=b.id order by r.revision desc limit 1) latest on true
    where b.environment='production' and lower(coalesce(b.provider,''))='openai'
      and lower(coalesce(b.route,''))='hearth.chat_completion' and latest.status='active') then
    raise exception 'another active owner Hearth OpenAI budget exists' using errcode='P0001';
  end if;
  perform set_config('request.jwt.claim.sub',p_operator_user_id::text,true);
  perform tongs.create_owner_operating_budget_draft(
    p_budget_id,'production',p_workspace_id,'openai','hearth.chat_completion','gpt-5.6-luna',
    'USD',v_now-interval '1 second',p_authorization_expires_at,v_reason
  );
  v_budget_active:=tongs.revise_owner_operating_budget(p_budget_id,'active',11015,v_reason);
  select coalesce(max(revision),0)+1 into v_loss_revision from tongs.openai_text_failure_loss_policy_revisions
    where route_code='hearth.chat_completion' and environment='production';
  insert into tongs.openai_text_failure_loss_policy_revisions(
    id,route_code,environment,revision,per_operation_limit_micros,aggregate_limit_micros,
    rolling_window_seconds,maximum_concurrency,lifecycle_state,reason,actor_id
  ) values (p_failure_loss_policy_revision_id,'hearth.chat_completion','production',v_loss_revision,
    11015,11015,86400,1,'active',v_reason,p_operator_user_id);
  select * into v_rollout from tongs._current_openai_text_rollout('hearth.chat_completion');
  if v_rollout.mode not in ('inactive','halt_new') then
    raise exception 'Hearth OpenAI rollout is already active' using errcode='P0001'; end if;
  select coalesce(max(revision),0)+1 into v_rollout_revision from tongs.openai_text_rollout_revisions
    where route_code='hearth.chat_completion';
  insert into tongs.openai_text_rollout_revisions(route_code,revision,mode,cost_policy_revision_id,reason,actor_id)
  values('hearth.chat_completion',v_rollout_revision,'enforce',
    '10000000-0000-4000-8000-000000000010'::uuid,v_reason,p_operator_user_id);
  return jsonb_build_object('replay',false,'budget',v_budget_active,'budget_id',p_budget_id,
    'maximum_amount_micros',11015,'rollout_mode','enforce','rollout_revision',v_rollout_revision,
    'failure_loss_policy_revision',v_loss_revision,'customer_settlement_enabled',false,
    'pricing_published',false,'maximum_attempts',1,'maximum_concurrency',1);
end $$;


ALTER FUNCTION "tongs"."activate_owner_hearth_chat_luna_retest"("p_operator_user_id" "uuid", "p_workspace_id" "uuid", "p_budget_id" "uuid", "p_pricing_revision_id" "uuid", "p_failure_loss_policy_revision_id" "uuid", "p_authorization_expires_at" timestamp with time zone, "p_corrected_reservation_id" "uuid", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."activate_owner_hearth_chat_luna_retest"("p_operator_user_id" "uuid", "p_workspace_id" "uuid", "p_budget_id" "uuid", "p_pricing_revision_id" "uuid", "p_failure_loss_policy_revision_id" "uuid", "p_authorization_expires_at" timestamp with time zone, "p_corrected_reservation_id" "uuid", "p_reason" "text") IS 'Creates one fresh $0.011015 owner-only Luna retest budget after the original provider-blame event has an audited Forge-validation correction.';



CREATE OR REPLACE FUNCTION "tongs"."activate_owner_hearth_chat_pilot"("p_operator_user_id" "uuid", "p_workspace_id" "uuid", "p_budget_id" "uuid", "p_pricing_policy_id" "uuid", "p_pricing_revision_id" "uuid", "p_markup_rule_revision_id" "uuid", "p_failure_loss_policy_revision_id" "uuid", "p_decision_id" "uuid", "p_authorization_expires_at" timestamp with time zone, "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_now timestamptz:=clock_timestamp();
  v_reason text:=nullif(btrim(coalesce(p_reason,'')),'');
  v_rules tongs.private_markup_rule_revisions%rowtype;
  v_current_rollout tongs.openai_text_rollout_revisions%rowtype;
  v_control tongs.paid_execution_control_revisions%rowtype;
  v_budget tongs.owner_operating_budgets%rowtype;
  v_budget_revision tongs.owner_operating_budget_revisions%rowtype;
  v_pricing jsonb;
  v_budget_draft jsonb;
  v_budget_active jsonb;
  v_rollout_revision integer;
  v_loss_revision integer;
begin
  perform tongs._require_pricing_service_role();
  if p_operator_user_id is null or not tongs.is_platform_operator(p_operator_user_id)
     or p_workspace_id is null or p_budget_id is null or p_pricing_policy_id is null
     or p_pricing_revision_id is null or p_markup_rule_revision_id is null
     or p_failure_loss_policy_revision_id is null or p_decision_id is null
     or v_reason is null or p_authorization_expires_at<=v_now
     or p_authorization_expires_at>v_now+interval '24 hours' then
    raise exception 'invalid bounded owner Hearth pilot activation' using errcode='22023';
  end if;
  if not exists(select 1 from tongs.workspaces w where w.id=p_workspace_id and
    (w.created_by=p_operator_user_id or exists(select 1 from tongs.workspace_members m
      where m.workspace_id=w.id and m.user_id=p_operator_user_id))) then
    raise exception 'operator cannot access pilot workspace' using errcode='42501';
  end if;
  select * into v_rules from tongs.private_markup_rule_revisions where id=p_markup_rule_revision_id;
  if not found or v_rules.default_markup_basis_points<>3300
     or tongs._effective_markup_basis_points(v_rules.id,'openai','gpt-5.3-chat-latest')<>3300 then
    raise exception 'approved 33 percent markup revision required' using errcode='P0001';
  end if;
  if not exists(select 1 from tongs.openai_text_activation_proposals p
    where p.id='30000000-0000-4000-8000-000000000001'::uuid
      and p.route_code='hearth.chat_completion'
      and p.cost_policy_revision_id='10000000-0000-4000-8000-000000000009'::uuid
      and p.model='gpt-5.3-chat-latest' and p.maximum_input_units=2000
      and p.maximum_output_units=512 and p.maximum_attempts=1
      and p.direct_provider_ceiling_micros=10668
      and p.supporting_cost_ceiling_micros=10000
      and p.total_cost_ceiling_micros=20668
      and p.proposed_owner_budget_micros=30000
      and p.authorization_window_seconds=86400) then
    raise exception 'exact bounded Hearth activation proposal missing' using errcode='P0002';
  end if;
  select * into v_control from tongs._current_paid_execution_control();
  if not v_control.pricing_activation_enabled or not v_control.owner_budget_spending_enabled
     or not v_control.provider_execution_enabled or v_control.customer_settlement_enabled then
    raise exception 'owner-only provider controls are not safely configured' using errcode='42501';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('owner-hearth-openai-pilot',0));
  select * into v_budget from tongs.owner_operating_budgets where id=p_budget_id;
  if found then
    select * into v_budget_revision from tongs.owner_operating_budget_revisions
      where budget_id=p_budget_id order by revision desc limit 1;
    if v_budget.environment<>'production' or v_budget.workspace_id is distinct from p_workspace_id
       or lower(coalesce(v_budget.provider,''))<>'openai'
       or lower(coalesce(v_budget.route,''))<>'hearth.chat_completion'
       or lower(coalesce(v_budget.sku,''))<>'gpt-5.3-chat-latest'
       or v_budget.currency<>'USD' or v_budget_revision.status not in ('active','closed')
       or v_budget_revision.maximum_amount_micros<>30000 then
      raise exception 'owner Hearth pilot activation replay conflict' using errcode='23505';
    end if;
    return jsonb_build_object('replay',true,'budget_id',p_budget_id,
      'budget_status',v_budget_revision.status,'maximum_amount_micros',30000,
      'customer_settlement_enabled',false);
  end if;
  if exists(select 1 from tongs.owner_operating_budgets b
    join lateral(select r.status from tongs.owner_operating_budget_revisions r
      where r.budget_id=b.id order by r.revision desc limit 1) latest on true
    where b.environment='production' and lower(coalesce(b.provider,''))='openai'
      and lower(coalesce(b.route,''))='hearth.chat_completion' and latest.status='active') then
    raise exception 'another active owner Hearth OpenAI budget exists' using errcode='P0001';
  end if;

  perform set_config('request.jwt.claim.sub',p_operator_user_id::text,true);
  v_pricing:=tongs.commit_operator_pricing_revision(
    p_markup_rule_revision_id,p_pricing_policy_id,
    'owner-openai-hearth-chat-bounded-pilot','sku','openai','gpt-5.3-chat-latest',0,
    p_pricing_revision_id,3,'USD',
    jsonb_build_array(
      jsonb_build_object('component_code','openai_text','component_kind','direct_provider',
        'credential_funding','forge','provider_label','OpenAI','success_ceiling_micros',10668,
        'failure_ceiling_micros',0,'cost_policy_revision','openai-text:hearth-chat:bounded-pilot-v1',
        'tail_policy','none'),
      jsonb_build_object('component_code','bounded_support','component_kind','compute',
        'credential_funding','forge','provider_label','Forge validation and persistence',
        'success_ceiling_micros',10000,'failure_ceiling_micros',0,
        'cost_policy_revision','openai-text:hearth-chat:bounded-pilot-v1','tail_policy','none')
    ),
    '[]'::jsonb,'["provider_failure","forge_failure","unknown_fault"]'::jsonb,
    '{"input_tokens":2000,"output_tokens":512,"attempts":1,"concurrency":1}'::jsonb,
    '{"kind":"none"}'::jsonb,v_reason
  );
  v_budget_draft:=tongs.create_owner_operating_budget_draft(
    p_budget_id,'production',p_workspace_id,'openai','hearth.chat_completion',
    'gpt-5.3-chat-latest','USD',v_now,p_authorization_expires_at,v_reason
  );
  v_budget_active:=tongs.revise_owner_operating_budget(p_budget_id,'active',30000,v_reason);

  select coalesce(max(revision),0)+1 into v_loss_revision
    from tongs.openai_text_failure_loss_policy_revisions
    where route_code='hearth.chat_completion' and environment='production';
  insert into tongs.openai_text_failure_loss_policy_revisions(
    id,route_code,environment,revision,per_operation_limit_micros,aggregate_limit_micros,
    rolling_window_seconds,maximum_concurrency,lifecycle_state,reason,actor_id
  ) values (
    p_failure_loss_policy_revision_id,'hearth.chat_completion','production',v_loss_revision,
    20668,20668,86400,1,'active',v_reason,p_operator_user_id
  );
  select * into v_current_rollout from tongs._current_openai_text_rollout('hearth.chat_completion');
  if v_current_rollout.mode not in ('inactive','halt_new') then
    raise exception 'Hearth OpenAI rollout is already active' using errcode='P0001';
  end if;
  select coalesce(max(revision),0)+1 into v_rollout_revision
    from tongs.openai_text_rollout_revisions where route_code='hearth.chat_completion';
  insert into tongs.openai_text_rollout_revisions(
    route_code,revision,mode,cost_policy_revision_id,reason,actor_id
  ) values (
    'hearth.chat_completion',v_rollout_revision,'enforce',
    '10000000-0000-4000-8000-000000000009',v_reason,p_operator_user_id
  );
  insert into tongs.openai_text_activation_decisions(
    id,proposal_id,decision,operator_user_id,reason
  ) values (
    p_decision_id,'30000000-0000-4000-8000-000000000001','approved',p_operator_user_id,v_reason
  );
  return jsonb_build_object(
    'replay',false,'budget',v_budget_active,'pricing',v_pricing,
    'rollout_revision',v_rollout_revision,'rollout_mode','enforce',
    'failure_loss_policy_revision',v_loss_revision,'maximum_amount_micros',30000,
    'customer_settlement_enabled',false,'pricing_published',false
  );
end $$;


ALTER FUNCTION "tongs"."activate_owner_hearth_chat_pilot"("p_operator_user_id" "uuid", "p_workspace_id" "uuid", "p_budget_id" "uuid", "p_pricing_policy_id" "uuid", "p_pricing_revision_id" "uuid", "p_markup_rule_revision_id" "uuid", "p_failure_loss_policy_revision_id" "uuid", "p_decision_id" "uuid", "p_authorization_expires_at" timestamp with time zone, "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."activate_owner_hearth_chat_pilot"("p_operator_user_id" "uuid", "p_workspace_id" "uuid", "p_budget_id" "uuid", "p_pricing_policy_id" "uuid", "p_pricing_revision_id" "uuid", "p_markup_rule_revision_id" "uuid", "p_failure_loss_policy_revision_id" "uuid", "p_decision_id" "uuid", "p_authorization_expires_at" timestamp with time zone, "p_reason" "text") IS 'Service-role-only exact activation for the approved 0.03 USD owner Hearth/OpenAI pilot; customer settlement and pricing publication remain disabled.';



CREATE OR REPLACE FUNCTION "tongs"."activate_owner_hearth_compatibility_package"("p_owner_user_id" "uuid", "p_workspace_id" "uuid", "p_operator_user_id" "uuid", "p_authorization_id" "uuid", "p_budget_id" "uuid", "p_tail_authorization_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare actor uuid:=p_operator_user_id; event_id uuid; pref_revision integer; authrow tongs.owner_hearth_authorizations%rowtype;
  markup_rules tongs.private_markup_rule_revisions%rowtype; spec record; price_id uuid; policy_id uuid; auth_event uuid;
begin
 if coalesce(auth.role(),'')<>'service_role' or actor is null or not tongs.is_platform_operator(actor)
    or p_owner_user_id is null or p_workspace_id is null or p_authorization_id is null or p_budget_id is null
    or p_tail_authorization_id is null or length(btrim(coalesce(p_reason,'')))<3 then
  raise exception 'service-role platform operator activation required' using errcode='42501'; end if;
 if not tongs._transition_owner_authority_agrees(p_owner_user_id)
    or not exists(select 1 from tongs.workspace_members where user_id=p_owner_user_id and workspace_id=p_workspace_id) then
  raise exception 'explicit owner principal and workspace membership required' using errcode='42501'; end if;
 perform pg_advisory_xact_lock(hashtextextended('owner-hearth-activation:'||p_owner_user_id::text,0));
 select * into authrow from tongs.owner_hearth_authorizations where id=p_authorization_id;
 if found then return jsonb_build_object('authorization_id',authrow.id,'replay',true); end if;
 select * into markup_rules from tongs.private_markup_rule_revisions order by revision desc limit 1;
 if markup_rules.id is null or markup_rules.default_markup_basis_points<>3300 then
  raise exception 'private 33 percent default markup revision required' using errcode='P0001'; end if;

 select coalesce(max(revision),0)+1 into pref_revision from tongs.ai_funding_preference_revisions where user_id=p_owner_user_id and workspace_id=p_workspace_id;
 insert into tongs.ai_funding_preference_revisions(id,user_id,workspace_id,revision,payer_kind,actor_id)
 values(gen_random_uuid(),p_owner_user_id,p_workspace_id,pref_revision,'owner_testing',actor);

 event_id:=gen_random_uuid();
 perform tongs._create_accounting_event(event_id,'owner-hearth-compat-budget:'||p_budget_id::text,
  'owner_operating_budget_created','owner_internal','owner_operating_budget',p_budget_id::text,'USD',
  p_owner_user_id,p_workspace_id,actor,jsonb_build_object('maximum_amount_micros',90000,'customer_revenue_micros',0,'reason',p_reason),now());
 insert into tongs.owner_operating_budgets(id,environment,workspace_id,provider,route,sku,currency,period_start,period_end,created_by,owner_testing_user_id)
 values(p_budget_id,'production',p_workspace_id,'openai','hearth.chat_completion',null,'USD',now(),now()+interval '24 hours',actor,p_owner_user_id);
 insert into tongs.owner_operating_budget_revisions(budget_id,revision,status,maximum_amount_micros,reason,actor_id,journal_event_id)
 values(p_budget_id,1,'active',90000,p_reason,actor,event_id);
 insert into tongs.owner_hearth_authorizations(id,authorization_kind,owner_user_id,workspace_id,budget_id,maximum_amount_micros,
  maximum_operations,maximum_concurrency,maximum_attempts,failure_loss_limit_micros,duration_seconds,created_by)
 values(p_authorization_id,'compatibility_batch',p_owner_user_id,p_workspace_id,p_budget_id,90000,5,1,1,90000,86400,actor);
 auth_event:=gen_random_uuid();
 insert into tongs.owner_hearth_authorization_events(id,authorization_id,sequence,event_key,state,started_at,expires_at,reason,evidence_json)
 values(auth_event,p_authorization_id,1,'owner-hearth-compat:'||p_authorization_id::text||':active','active',now(),now()+interval '24 hours',p_reason,
  jsonb_build_object('maximum_provider_calls',5,'aggregate_cap_micros',90000,'prompt','Reply with exactly: Ready.','concurrency',1));
 insert into tongs.owner_hearth_tail_authorizations(id,owner_user_id,workspace_id,currency,monthly_limit_micros,aggregate_limit_micros,
  canonical_capacity_bytes,evidence_capacity_bytes,replacement_rate_micros_per_mib_month,coverage_months,created_by)
 values(p_tail_authorization_id,p_owner_user_id,p_workspace_id,'USD',20000,240000,134217728,33554432,123,12,actor);
 insert into tongs.owner_hearth_tail_events(id,tail_authorization_id,sequence,event_key,event_type,amount_micros,evidence_json)
 values(gen_random_uuid(),p_tail_authorization_id,1,'owner-hearth-tail:'||p_tail_authorization_id::text||':authorized','authorized',240000,
  jsonb_build_object('first_30_days_excluded',true,'coverage_begins_at_each_artifact_day_30',true,'automatic_renewal',false));

 for spec in select * from (values
  (1,'gpt-6-astra','GPT-6 Astra','81000000-0000-4000-8000-000000000001'::uuid,30919::bigint,'compatibility'),
  (2,'gpt-5.6-sol','GPT-5.6 Sol','81000000-0000-4000-8000-000000000002'::uuid,13243::bigint,'compatibility'),
  (3,'gpt-5.6-terra','GPT-5.6 Terra','81000000-0000-4000-8000-000000000003'::uuid,8379::bigint,'compatibility'),
  (4,'gpt-5.4-mini-2026-03-17','GPT-5.4 Mini','81000000-0000-4000-8000-000000000004'::uuid,4062::bigint,'compatibility'),
  (5,'gpt-5.6-luna','GPT-5.6 Luna','81000000-0000-4000-8000-000000000005'::uuid,2151::bigint,'compatibility')
 ) v(ordinal,model_id,display_name,cost_id,max_exposure,kind)
 loop
  policy_id:=extensions.uuid_generate_v5(p_authorization_id,'pricing-policy:'||spec.model_id);
  price_id:=extensions.uuid_generate_v5(p_authorization_id,'pricing-revision:'||spec.model_id);
  insert into tongs.private_pricing_policies(id,policy_code,scope_kind,provider,sku,created_by)
  values(policy_id,'owner-hearth-compat-'||spec.ordinal,'sku','openai','owner-hearth-compat:'||spec.model_id,actor);
  insert into tongs.private_pricing_revisions(id,policy_id,revision,lifecycle_state,currency,markup_basis_points,
   full_cost_ceiling_micros,failure_cost_ceiling_micros,customer_price_ceiling_micros,billable_failure_ceiling_micros,
   customer_credit_units,billable_failure_classes,free_failure_classes,included_quantity,retention_policy,change_reason,content_hash,actor_id)
  select price_id,policy_id,1,'review_ready','USD',3300,c.full_cost_ceiling_micros,c.full_cost_ceiling_micros,
   ((c.full_cost_ceiling_micros*133+999999)/1000000)*10000,0,0,'[]'::jsonb,
   '["provider_failure","forge_failure","forge_validation_failure","persistence_failure","unknown_fault"]'::jsonb,
   jsonb_build_object('input_tokens',c.maximum_input_units,'output_tokens',c.maximum_output_units,'attempts',1),
   jsonb_build_object('first_30_days','included_in_supporting_allocation','post_day_30','separate_owner_tail_authorization'),
   'Private owner compatibility basis; no customer price publication.',
   encode(extensions.digest(convert_to(p_authorization_id::text||':'||spec.model_id||':3300:'||c.full_cost_ceiling_micros::text,'utf8'),'sha256'),'hex'),actor
  from tongs.openai_text_cost_policy_revisions c where c.id=spec.cost_id;
  insert into tongs.owner_hearth_model_terms(authorization_id,ordinal,provider_model_id,display_name,cost_policy_revision_id,
   pricing_revision_id,aggregate_policy_revision_id,maximum_exposure_micros)
  values(p_authorization_id,spec.ordinal,spec.model_id,spec.display_name,spec.cost_id,price_id,
   extensions.uuid_generate_v5('83000000-0000-4000-8000-000000000000'::uuid,'compatibility:'||spec.model_id),spec.max_exposure);
 end loop;
 return jsonb_build_object('authorization_id',p_authorization_id,'budget_id',p_budget_id,'tail_authorization_id',p_tail_authorization_id,
  'maximum_amount_micros',90000,'admitted_total_micros',58754,'replay',false);
end $$;


ALTER FUNCTION "tongs"."activate_owner_hearth_compatibility_package"("p_owner_user_id" "uuid", "p_workspace_id" "uuid", "p_operator_user_id" "uuid", "p_authorization_id" "uuid", "p_budget_id" "uuid", "p_tail_authorization_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."activate_owner_hearth_compatibility_retry"("p_owner_user_id" "uuid", "p_workspace_id" "uuid", "p_operator_user_id" "uuid", "p_prior_authorization_id" "uuid", "p_authorization_id" "uuid", "p_budget_id" "uuid", "p_tail_authorization_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare actor uuid:=p_operator_user_id; prior_auth tongs.owner_hearth_authorizations%rowtype;
 prior_event tongs.owner_hearth_authorization_events%rowtype; authrow tongs.owner_hearth_authorizations%rowtype;
 tail tongs.owner_hearth_tail_authorizations%rowtype; event_id uuid; auth_event uuid;
 markup_rules tongs.private_markup_rule_revisions%rowtype; spec record; price_id uuid; policy_id uuid;
begin
 if coalesce(auth.role(),'')<>'service_role' or actor is null or not tongs.is_platform_operator(actor)
    or p_owner_user_id is null or p_workspace_id is null or p_prior_authorization_id is null
    or p_authorization_id is null or p_budget_id is null or p_tail_authorization_id is null
    or length(btrim(coalesce(p_reason,'')))<3 then
  raise exception 'service-role platform operator retry activation required' using errcode='42501'; end if;
 if not tongs._transition_owner_authority_agrees(p_owner_user_id)
    or not exists(select 1 from tongs.workspace_members where user_id=p_owner_user_id and workspace_id=p_workspace_id) then
  raise exception 'explicit owner principal and workspace membership required' using errcode='42501'; end if;

 perform pg_advisory_xact_lock(hashtextextended('owner-hearth-activation:'||p_owner_user_id::text,0));
 select * into authrow from tongs.owner_hearth_authorizations where id=p_authorization_id;
 if found then
  if authrow.authorization_kind<>'compatibility_batch' or authrow.owner_user_id<>p_owner_user_id
     or authrow.workspace_id<>p_workspace_id or authrow.budget_id<>p_budget_id then
   raise exception 'owner Hearth retry replay conflict' using errcode='23505'; end if;
  return jsonb_build_object('authorization_id',authrow.id,'budget_id',authrow.budget_id,
   'tail_authorization_id',p_tail_authorization_id,'tail_allocation_reused',true,'replay',true);
 end if;

 select * into prior_auth from tongs.owner_hearth_authorizations where id=p_prior_authorization_id;
 select * into prior_event from tongs.owner_hearth_authorization_events
  where authorization_id=p_prior_authorization_id order by sequence desc limit 1;
 if prior_auth.authorization_kind<>'compatibility_batch' or prior_auth.owner_user_id<>p_owner_user_id
    or prior_auth.workspace_id<>p_workspace_id or prior_event.state<>'closed' then
  raise exception 'closed prior compatibility authorization required' using errcode='P0001'; end if;
 if exists(
  select 1 from tongs.owner_hearth_authorizations a
  join lateral(select e.state,e.expires_at from tongs.owner_hearth_authorization_events e
    where e.authorization_id=a.id order by e.sequence desc limit 1) latest on true
  where a.owner_user_id=p_owner_user_id and a.workspace_id=p_workspace_id
    and latest.state in ('active','dormant') and (latest.expires_at is null or latest.expires_at>now())
 ) then raise exception 'another owner Hearth authorization is already eligible' using errcode='P0001'; end if;

 select * into tail from tongs.owner_hearth_tail_authorizations where id=p_tail_authorization_id;
 if tail.id is null or tail.owner_user_id<>p_owner_user_id or tail.workspace_id<>p_workspace_id
    or tail.monthly_limit_micros<>20000 or tail.aggregate_limit_micros<>240000
    or tail.canonical_capacity_bytes<>134217728 or tail.evidence_capacity_bytes<>33554432
    or tail.replacement_rate_micros_per_mib_month<>123 or tail.coverage_months<>12 or not tail.no_renewal then
  raise exception 'exact existing owner Hearth tail authorization required' using errcode='P0001'; end if;
 if not exists(select 1 from tongs.owner_hearth_tail_events e where e.tail_authorization_id=tail.id
   and e.event_type='authorized' and e.amount_micros=240000
   and coalesce((e.evidence_json->>'first_30_days_excluded')::boolean,false)) then
  raise exception 'non-overlapping existing tail allocation evidence required' using errcode='P0001'; end if;

 select * into markup_rules from tongs.private_markup_rule_revisions order by revision desc limit 1;
 if markup_rules.id is null or markup_rules.default_markup_basis_points<>3300 then
  raise exception 'private 33 percent default markup revision required' using errcode='P0001'; end if;

 event_id:=gen_random_uuid();
 perform tongs._create_accounting_event(event_id,'owner-hearth-compat-retry-budget:'||p_budget_id::text,
  'owner_operating_budget_created','owner_internal','owner_operating_budget',p_budget_id::text,'USD',
  p_owner_user_id,p_workspace_id,actor,jsonb_build_object('maximum_amount_micros',90000,'customer_revenue_micros',0,
   'prior_authorization_id',p_prior_authorization_id,'tail_authorization_id',tail.id,'tail_allocation_reused',true,'reason',p_reason),now());
 insert into tongs.owner_operating_budgets(id,environment,workspace_id,provider,route,sku,currency,period_start,period_end,created_by,owner_testing_user_id)
 values(p_budget_id,'production',p_workspace_id,'openai','hearth.chat_completion',null,'USD',now(),now()+interval '24 hours',actor,p_owner_user_id);
 insert into tongs.owner_operating_budget_revisions(budget_id,revision,status,maximum_amount_micros,reason,actor_id,journal_event_id)
 values(p_budget_id,1,'active',90000,p_reason,actor,event_id);
 insert into tongs.owner_hearth_authorizations(id,authorization_kind,owner_user_id,workspace_id,budget_id,maximum_amount_micros,
  maximum_operations,maximum_concurrency,maximum_attempts,failure_loss_limit_micros,duration_seconds,created_by,created_at)
 values(p_authorization_id,'compatibility_batch',p_owner_user_id,p_workspace_id,p_budget_id,90000,5,1,1,90000,86400,actor,clock_timestamp());
 auth_event:=gen_random_uuid();
 insert into tongs.owner_hearth_authorization_events(id,authorization_id,sequence,event_key,state,started_at,expires_at,reason,evidence_json)
 values(auth_event,p_authorization_id,1,'owner-hearth-compat-retry:'||p_authorization_id::text||':active','active',now(),now()+interval '24 hours',p_reason,
  jsonb_build_object('maximum_provider_calls',5,'aggregate_cap_micros',90000,'prompt','Reply with exactly: Ready.',
   'concurrency',1,'prior_authorization_id',p_prior_authorization_id,'tail_authorization_id',tail.id,'tail_allocation_reused',true));

 for spec in select * from (values
  (1,'gpt-6-astra','GPT-6 Astra','81000000-0000-4000-8000-000000000001'::uuid,30919::bigint),
  (2,'gpt-5.6-sol','GPT-5.6 Sol','81000000-0000-4000-8000-000000000002'::uuid,13243::bigint),
  (3,'gpt-5.6-terra','GPT-5.6 Terra','81000000-0000-4000-8000-000000000003'::uuid,8379::bigint),
  (4,'gpt-5.4-mini-2026-03-17','GPT-5.4 Mini','81000000-0000-4000-8000-000000000004'::uuid,4062::bigint),
  (5,'gpt-5.6-luna','GPT-5.6 Luna','81000000-0000-4000-8000-000000000005'::uuid,2151::bigint)
 ) v(ordinal,model_id,display_name,cost_id,max_exposure)
 loop
  policy_id:=extensions.uuid_generate_v5(p_authorization_id,'pricing-policy:'||spec.model_id);
  price_id:=extensions.uuid_generate_v5(p_authorization_id,'pricing-revision:'||spec.model_id);
  insert into tongs.private_pricing_policies(id,policy_code,scope_kind,provider,sku,created_by)
  values(policy_id,'owner-hearth-compat-retry-'||left(replace(p_authorization_id::text,'-',''),12)||'-'||spec.ordinal,
   'sku','openai','owner-hearth-compat-retry:'||p_authorization_id::text||':'||spec.model_id,actor);
  insert into tongs.private_pricing_revisions(id,policy_id,revision,lifecycle_state,currency,markup_basis_points,
   full_cost_ceiling_micros,failure_cost_ceiling_micros,customer_price_ceiling_micros,billable_failure_ceiling_micros,
   customer_credit_units,billable_failure_classes,free_failure_classes,included_quantity,retention_policy,change_reason,content_hash,actor_id)
  select price_id,policy_id,1,'review_ready','USD',3300,c.full_cost_ceiling_micros,c.full_cost_ceiling_micros,
   ((c.full_cost_ceiling_micros*133+999999)/1000000)*10000,0,0,'[]'::jsonb,
   '["provider_failure","forge_failure","forge_validation_failure","persistence_failure","unknown_fault"]'::jsonb,
   jsonb_build_object('input_tokens',c.maximum_input_units,'output_tokens',c.maximum_output_units,'attempts',1),
   jsonb_build_object('first_30_days','included_in_supporting_allocation','post_day_30','existing_owner_tail_authorization',
    'tail_authorization_id',tail.id),
   'Private owner compatibility retry basis; no customer price publication and no duplicate tail allocation.',
   encode(extensions.digest(convert_to(p_authorization_id::text||':'||spec.model_id||':3300:'||c.full_cost_ceiling_micros::text,'utf8'),'sha256'),'hex'),actor
  from tongs.openai_text_cost_policy_revisions c where c.id=spec.cost_id;
  insert into tongs.owner_hearth_model_terms(authorization_id,ordinal,provider_model_id,display_name,cost_policy_revision_id,
   pricing_revision_id,aggregate_policy_revision_id,maximum_exposure_micros)
  values(p_authorization_id,spec.ordinal,spec.model_id,spec.display_name,spec.cost_id,price_id,
   extensions.uuid_generate_v5('83000000-0000-4000-8000-000000000000'::uuid,'compatibility:'||spec.model_id),spec.max_exposure);
 end loop;
 return jsonb_build_object('authorization_id',p_authorization_id,'prior_authorization_id',p_prior_authorization_id,
  'budget_id',p_budget_id,'tail_authorization_id',tail.id,'tail_allocation_reused',true,
  'maximum_amount_micros',90000,'admitted_total_micros',58754,'replay',false);
end $$;


ALTER FUNCTION "tongs"."activate_owner_hearth_compatibility_retry"("p_owner_user_id" "uuid", "p_workspace_id" "uuid", "p_operator_user_id" "uuid", "p_prior_authorization_id" "uuid", "p_authorization_id" "uuid", "p_budget_id" "uuid", "p_tail_authorization_id" "uuid", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."activate_owner_hearth_compatibility_retry"("p_owner_user_id" "uuid", "p_workspace_id" "uuid", "p_operator_user_id" "uuid", "p_prior_authorization_id" "uuid", "p_authorization_id" "uuid", "p_budget_id" "uuid", "p_tail_authorization_id" "uuid", "p_reason" "text") IS 'Creates a fresh five-call/$0.09 owner compatibility authorization after a closed batch while reusing the exact existing $0.24 non-overlapping tail authorization.';



CREATE OR REPLACE FUNCTION "tongs"."activate_owner_hearth_research_package"("p_proposal_id" "uuid", "p_owner_user_id" "uuid", "p_workspace_id" "uuid", "p_budget_id" "uuid", "p_canary_authorization_id" "uuid", "p_session_authorization_id" "uuid", "p_storage_allowance_id" "uuid", "p_verified_model_terms" "jsonb", "p_storage_evidence_json" "jsonb", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
begin
 perform tongs._require_pricing_service_role();
 if p_proposal_id<>'91000000-0000-4000-8000-000000000001' or not exists(select 1 from tongs.owner_hearth_research_proposal_events e where e.proposal_id=p_proposal_id and e.event_type='approved')
  or jsonb_typeof(p_verified_model_terms)<>'array' or jsonb_array_length(p_verified_model_terms)<>5
  or coalesce(p_storage_evidence_json->>'status','')<>'verified' then raise exception 'separate owner approval and verified rate/storage evidence required' using errcode='42501'; end if;
 raise exception 'activation handoff requires the separately approved deployment transaction' using errcode='42501';
end $$;


ALTER FUNCTION "tongs"."activate_owner_hearth_research_package"("p_proposal_id" "uuid", "p_owner_user_id" "uuid", "p_workspace_id" "uuid", "p_budget_id" "uuid", "p_canary_authorization_id" "uuid", "p_session_authorization_id" "uuid", "p_storage_allowance_id" "uuid", "p_verified_model_terms" "jsonb", "p_storage_evidence_json" "jsonb", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."activate_owner_hearth_research_package"("p_proposal_id" "uuid", "p_owner_user_id" "uuid", "p_workspace_id" "uuid", "p_budget_id" "uuid", "p_canary_authorization_id" "uuid", "p_session_authorization_id" "uuid", "p_storage_allowance_id" "uuid", "p_verified_model_terms" "jsonb", "p_storage_evidence_json" "jsonb", "p_reason" "text") IS 'Intentional approval boundary: remains fail-closed until a separately approved activation migration implements the verified deployment transaction.';



CREATE OR REPLACE FUNCTION "tongs"."activate_owner_paid_execution_test_canary"("p_activation_id" "uuid", "p_budget_id" "uuid", "p_scope_id" "uuid", "p_actor_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
begin
  perform tongs._require_pricing_service_role();
  return tongs._activate_owner_paid_execution_test_canary(
    p_activation_id,p_budget_id,p_scope_id,p_actor_id,p_reason);
end $$;


ALTER FUNCTION "tongs"."activate_owner_paid_execution_test_canary"("p_activation_id" "uuid", "p_budget_id" "uuid", "p_scope_id" "uuid", "p_actor_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."activate_owner_runway_pilot_controls"("p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_actor uuid:=auth.uid();
  v_reason text:=nullif(btrim(coalesce(p_reason,'')),'');
  v_current tongs.paid_execution_control_revisions%rowtype;
  v_revision integer;
begin
  if v_actor is null or not tongs.is_platform_operator(v_actor) then
    raise exception 'platform operator required' using errcode='42501';
  end if;
  if v_reason is null then raise exception 'activation reason required' using errcode='22023'; end if;
  select * into v_current from tongs._current_paid_execution_control();
  if v_current.customer_settlement_enabled then
    raise exception 'owner pilot cannot activate while customer settlement is enabled' using errcode='42501';
  end if;
  if exists(
    select 1 from tongs.owner_operating_budgets b
    join lateral(select r.status,r.maximum_amount_micros from tongs.owner_operating_budget_revisions r
      where r.budget_id=b.id order by r.revision desc limit 1) latest on true
    where latest.status='active' and now()>=b.period_start and now()<b.period_end
      and (b.environment<>'production' or lower(coalesce(b.provider,''))<>'runway'
        or lower(coalesce(b.route,''))<>'tongs_broll_v2'
        or lower(coalesce(b.sku,''))<>'gen4.5:5s:1280:720'
        or latest.maximum_amount_micros<>750000)
  ) then raise exception 'broader active owner budget prevents bounded pilot activation' using errcode='42501'; end if;
  if not exists(
    select 1 from tongs.runway_funding_bindings binding
    join tongs.funding_reservations reservation on reservation.id=binding.reservation_id
    join tongs.owner_operating_budgets budget on budget.id=reservation.funding_source_id
    join lateral(select r.status,r.maximum_amount_micros from tongs.owner_operating_budget_revisions r
      where r.budget_id=budget.id order by r.revision desc limit 1) latest on true
    where binding.user_id=v_actor and binding.model='gen4.5' and binding.duration_seconds=5
      and binding.ratio='1280:720' and binding.total_cost_ceiling_micros=750000
      and reservation.funding_source_type='owner_budget'
      and tongs._funding_reservation_state(reservation.id)='reserved'
      and latest.status='active' and latest.maximum_amount_micros=750000
      and budget.environment='production' and now()>=budget.period_start and now()<budget.period_end
  ) then raise exception 'approved bounded owner Runway reservation required before activation' using errcode='P0001'; end if;
  select coalesce(max(revision),0)+1 into v_revision from tongs.paid_execution_control_revisions;
  insert into tongs.paid_execution_control_revisions(
    revision,pricing_activation_enabled,reservation_shadow_enabled,customer_settlement_enabled,
    owner_budget_spending_enabled,provider_execution_enabled,reason,actor_id
  ) values (v_revision,true,true,false,true,true,v_reason,v_actor);
  return jsonb_build_object('revision',v_revision,'pricing_activation_enabled',true,
    'reservation_shadow_enabled',true,'customer_settlement_enabled',false,
    'owner_budget_spending_enabled',true,'provider_execution_enabled',true);
end;
$$;


ALTER FUNCTION "tongs"."activate_owner_runway_pilot_controls"("p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."activate_reference_visual_evidence_claim_after_commit"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare
  claim tongs.reference_visual_evidence_claims%rowtype;
  latest_reset_at timestamptz;
begin
  if new.operation_type<>'evidence_commit' or new.state<>'committed' then
    return new;
  end if;
  select c.* into claim
  from tongs.reference_visual_evidence_claims c
  where c.claim_id=nullif(new.receipt_json->>'canonical_claim_id','')::uuid;
  if claim.claim_id is null then return new; end if;
  select max(r.reset_at) into latest_reset_at
  from tongs.reference_visual_evidence_resets r
  where r.workspace_id=claim.workspace_id and r.workpiece_id=claim.workpiece_id
    and r.opportunity_id=claim.opportunity_id;
  if latest_reset_at is not null and claim.created_at<=latest_reset_at
    and not exists(
      select 1 from tongs.reference_visual_evidence_claim_activations a
      where a.canonical_claim_id=claim.claim_id and a.activated_at>latest_reset_at
    ) then
    insert into tongs.reference_visual_evidence_claim_activations(
      workspace_id,workpiece_id,opportunity_id,canonical_claim_id,canonical_evidence_id,
      operation_id,operation_fingerprint,activated_by,activated_at
    ) values(
      claim.workspace_id,claim.workpiece_id,claim.opportunity_id,claim.claim_id,
      claim.canonical_evidence_id,new.operation_id,new.operation_fingerprint,new.created_by,
      clock_timestamp()
    ) on conflict(operation_id) do nothing;
  end if;
  return new;
end$$;


ALTER FUNCTION "tongs"."activate_reference_visual_evidence_claim_after_commit"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."activate_runway_gen45_customer_test"("p_authorization_id" "uuid", "p_actor_id" "uuid", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_operation_id" "text", "p_operation_fingerprint" "text", "p_valid_until" timestamp with time zone, "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $_$
declare
  op tongs.broll_operation_receipts%rowtype;
  existing tongs.runway_customer_test_authorizations%rowtype;
  assignment tongs.paid_execution_aggregate_assignments%rowtype;
begin
  perform tongs._require_pricing_service_role();
  if p_actor_id is null or not tongs.is_platform_operator(p_actor_id)
     or p_authorization_id is null or p_user_id is null or p_workspace_id is null
     or nullif(btrim(coalesce(p_operation_id,'')),'') is null
     or p_operation_fingerprint!~'^[0-9a-f]{64}$'
     or p_valid_until<=clock_timestamp()
     or p_valid_until>clock_timestamp()+interval '24 hours'
     or nullif(btrim(coalesce(p_reason,'')),'') is null then
    raise exception 'invalid bounded Runway customer Test activation' using errcode='22023';
  end if;
  select * into existing from tongs.runway_customer_test_authorizations where id=p_authorization_id;
  if found then
    if existing.user_id<>p_user_id or existing.workspace_id<>p_workspace_id
       or existing.operation_id<>btrim(p_operation_id)
       or existing.operation_fingerprint<>lower(p_operation_fingerprint)
       or existing.valid_until<>p_valid_until then
      raise exception 'Runway customer Test activation replay conflict' using errcode='23505';
    end if;
    return to_jsonb(existing)||jsonb_build_object('replay',true);
  end if;
  select * into op from tongs.broll_operation_receipts
  where operation_id=btrim(p_operation_id) for update;
  if op.operation_id is null
     or op.operation_fingerprint<>lower(p_operation_fingerprint)
     or op.workspace_id<>p_workspace_id or op.created_by<>p_user_id
     or op.operation_type<>'candidate_acquire' or op.state<>'pending'
     or op.provider_task_id is not null or op.submission_attempt_id is not null
     or op.normalized_inputs_json->>'source_kind'<>'generated'
     or op.normalized_inputs_json->>'runway_model'<>'gen4.5'
     or (op.normalized_inputs_json->>'duration_seconds')::integer<>5
     or op.normalized_inputs_json->>'ratio'<>'1280:720'
     or jsonb_typeof(op.normalized_inputs_json->'reference_images')<>'array'
     or jsonb_array_length(op.normalized_inputs_json->'reference_images')<>0
     or length(coalesce(op.normalized_inputs_json->>'final_prompt','')) not between 1 and 1000 then
    raise exception 'exact pending zero-reference Runway operation required' using errcode='42501';
  end if;
  if not exists(select 1 from tongs.workspace_members
    where workspace_id=p_workspace_id and user_id=p_user_id) and not exists(
    select 1 from tongs.workspaces where id=p_workspace_id and created_by=p_user_id
  ) then raise exception 'customer cannot access designated workspace' using errcode='42501'; end if;

  insert into tongs.runway_customer_test_authorizations(
    id,user_id,workspace_id,financial_environment,route_code,provider,model,
    generation_mode,duration_seconds,ratio,output_count,reference_image_count,
    maximum_provider_attempts,pricing_revision_id,operation_id,
    operation_fingerprint,maximum_operation_count,
    maximum_customer_charge_micros,maximum_wholesale_exposure_micros,
    maximum_concurrency,valid_from,valid_until,status,reason,created_by
  ) values(
    p_authorization_id,p_user_id,p_workspace_id,'test','tongs_broll_v2','runway','gen4.5',
    'text_to_video',5,'1280:720',1,0,1,
    '19730000-0000-4000-8000-000000000002',btrim(p_operation_id),
    lower(p_operation_fingerprint),1,800000,600000,1,clock_timestamp(),
    p_valid_until,'active',btrim(p_reason),p_actor_id
  ) returning * into existing;
  insert into tongs.paid_execution_aggregate_assignments(
    id,policy_revision_id,user_id,workspace_id,state,valid_from,valid_until,reason
  ) values(
    extensions.uuid_generate_v5(p_authorization_id,'aggregate-assignment'),
    '19730000-0000-4000-8000-000000000005',p_user_id,p_workspace_id,
    'active',existing.valid_from,existing.valid_until,
    'Exact one-operation normal-customer Test Runway Gen-4.5 exposure assignment.'
  ) returning * into assignment;
  return to_jsonb(existing)||jsonb_build_object('replay',false,'aggregate_assignment_id',assignment.id);
end $_$;


