CREATE OR REPLACE FUNCTION "tongs"."add_my_style_sample"("p_workspace_id" "uuid", "p_source_kind" "text" DEFAULT 'paste'::"text", "p_source_label" "text" DEFAULT NULL::"text", "p_source_workpiece_id" "uuid" DEFAULT NULL::"uuid", "p_source_path" "text" DEFAULT NULL::"text", "p_content" "text" DEFAULT NULL::"text") RETURNS TABLE("sample_id" "uuid", "workspace_id" "uuid", "user_id" "uuid", "source_kind" "text", "source_label" "text", "source_workpiece_id" "uuid", "source_path" "text", "content" "text", "content_chars" integer, "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare
  v_user uuid;
  v_source_kind text := lower(nullif(btrim(coalesce(p_source_kind, '')), ''));
  v_source_label text := nullif(btrim(coalesce(p_source_label, '')), '');
  v_source_path text := nullif(btrim(coalesce(p_source_path, '')), '');
  v_content text := nullif(btrim(coalesce(p_content, '')), '');
  v_content_chars integer;
  v_digest text;
begin
  v_user := auth.uid();
  if v_user is null then
    raise exception 'Not authenticated'
      using errcode = '42501';
  end if;

  if p_workspace_id is null then
    raise exception 'workspace_id is required'
      using errcode = '22023';
  end if;

  perform tongs.assert_workspace_role(p_workspace_id, 'viewer');

  if v_source_kind is null then
    v_source_kind := 'paste';
  end if;
  if v_source_kind not in ('upload', 'paste', 'forge_script', 'forge_transcript', 'other') then
    raise exception 'Unsupported source_kind: %', v_source_kind
      using errcode = '22023';
  end if;

  if v_source_path is not null then
    if left(v_source_path, 1) = '/'
      or position('..' in v_source_path) > 0
      or position(chr(92) in v_source_path) > 0
    then
      raise exception 'source_path must be relative and safe'
        using errcode = '22023';
    end if;
  end if;

  if p_source_workpiece_id is not null then
    perform 1
    from tongs.episodes e
    where e.id = p_source_workpiece_id
      and e.workspace_id = p_workspace_id;
    if not found then
      raise exception 'source_workpiece_id does not belong to workspace'
        using errcode = '22023';
    end if;
  end if;

  if v_content is null then
    raise exception 'content is required'
      using errcode = '22023';
  end if;

  v_content_chars := char_length(v_content);
  if v_content_chars > 150000 then
    raise exception 'style sample content exceeds 150000 characters'
      using errcode = '22023';
  end if;
  v_digest := md5(v_content);

  insert into tongs.workspace_style_samples (
    workspace_id,
    user_id,
    source_kind,
    source_label,
    source_workpiece_id,
    source_path,
    content,
    content_chars,
    content_digest,
    created_at,
    updated_at
  )
  values (
    p_workspace_id,
    v_user,
    v_source_kind,
    v_source_label,
    p_source_workpiece_id,
    v_source_path,
    v_content,
    v_content_chars,
    v_digest,
    now(),
    now()
  )
  on conflict (workspace_id, user_id, content_digest) do update
    set source_kind = excluded.source_kind,
        source_label = coalesce(excluded.source_label, tongs.workspace_style_samples.source_label),
        source_workpiece_id = coalesce(excluded.source_workpiece_id, tongs.workspace_style_samples.source_workpiece_id),
        source_path = coalesce(excluded.source_path, tongs.workspace_style_samples.source_path),
        content = excluded.content,
        content_chars = excluded.content_chars,
        updated_at = now();

  return query
  select
    s.id,
    s.workspace_id,
    s.user_id,
    s.source_kind,
    s.source_label,
    s.source_workpiece_id,
    s.source_path,
    s.content,
    s.content_chars,
    s.created_at,
    s.updated_at
  from tongs.workspace_style_samples s
  where s.workspace_id = p_workspace_id
    and s.user_id = v_user
    and s.content_digest = v_digest
  limit 1;
end;
$$;


ALTER FUNCTION "tongs"."add_my_style_sample"("p_workspace_id" "uuid", "p_source_kind" "text", "p_source_label" "text", "p_source_workpiece_id" "uuid", "p_source_path" "text", "p_content" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."add_team_member"("p_team_id" "uuid", "p_user_id" "uuid", "p_team_role" "text" DEFAULT 'member'::"text") RETURNS TABLE("team_id" "uuid", "user_id" "uuid", "user_email" "text", "team_role" "text", "created_at" timestamp with time zone, "created_by" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare
  v_user uuid;
  v_org_id uuid;
  v_team_role text;
  v_existing_role text;
  v_event_timestamp timestamptz := now();
  v_row record;
begin
  v_user := auth.uid();
  if v_user is null then
    raise exception 'Not authenticated'
      using errcode = '42501';
  end if;

  if p_team_id is null then
    raise exception 'team_id is required'
      using errcode = '22023';
  end if;

  if p_user_id is null then
    raise exception 'user_id is required'
      using errcode = '22023';
  end if;

  v_team_role := lower(trim(coalesce(p_team_role, 'member')));
  if v_team_role not in ('lead', 'member') then
    raise exception 'invalid team role: %', p_team_role
      using errcode = '22023';
  end if;

  select t.org_id
  into v_org_id
  from tongs.teams t
  where t.id = p_team_id;

  if v_org_id is null then
    raise exception 'Team not found'
      using errcode = 'P0002';
  end if;

  perform tongs.assert_org_role(v_org_id, 'admin');

  select tm.team_role
  into v_existing_role
  from tongs.team_members tm
  where tm.team_id = p_team_id
    and tm.user_id = p_user_id;

  insert into tongs.team_members (
    team_id,
    user_id,
    team_role,
    created_at,
    created_by
  )
  values (
    p_team_id,
    p_user_id,
    v_team_role,
    now(),
    v_user
  )
  on conflict on constraint team_members_pkey do update
    set team_role = excluded.team_role;

  if v_existing_role is null and to_regclass('tongs.hearth_interaction_events') is not null then
    insert into tongs.hearth_interaction_events (
      user_id,
      workspace_id,
      episode_id,
      event_type,
      payload
    )
    values (
      v_user,
      null,
      null,
      'team.member.add',
      jsonb_build_object(
        'org_id', v_org_id,
        'team_id', p_team_id,
        'actor_user_id', v_user,
        'target_user_id', p_user_id,
        'new_role', v_team_role,
        'timestamp', v_event_timestamp
      )
    );
  end if;

  select
    tm.team_id,
    tm.user_id,
    coalesce(lower(u.email), '') as user_email,
    tm.team_role,
    tm.created_at,
    tm.created_by
  into v_row
  from tongs.team_members tm
  left join auth.users u
    on u.id = tm.user_id
  where tm.team_id = p_team_id
    and tm.user_id = p_user_id;

  return query
  select
    v_row.team_id,
    v_row.user_id,
    v_row.user_email,
    v_row.team_role,
    v_row.created_at,
    v_row.created_by;
end;
$$;


ALTER FUNCTION "tongs"."add_team_member"("p_team_id" "uuid", "p_user_id" "uuid", "p_team_role" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."add_team_member_by_email"("p_team_id" "uuid", "p_email" "text", "p_team_role" "text" DEFAULT 'member'::"text") RETURNS TABLE("team_id" "uuid", "user_id" "uuid", "user_email" "text", "team_role" "text", "created_at" timestamp with time zone, "created_by" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare
  v_org_id uuid;
  v_user_id uuid;
begin
  if p_team_id is null then
    raise exception 'team_id is required'
      using errcode = '22023';
  end if;

  select t.org_id
  into v_org_id
  from tongs.teams t
  where t.id = p_team_id;

  if v_org_id is null then
    raise exception 'Team not found'
      using errcode = 'P0002';
  end if;

  perform tongs.assert_org_role(v_org_id, 'admin');

  select r.user_id
  into v_user_id
  from tongs.resolve_org_user_by_email(v_org_id, p_email) r
  limit 1;

  if v_user_id is null then
    return;
  end if;

  return query
  select
    atm.team_id,
    atm.user_id,
    atm.user_email,
    atm.team_role,
    atm.created_at,
    atm.created_by
  from tongs.add_team_member(p_team_id, v_user_id, p_team_role) atm;
end;
$$;


