    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare
  v_limit integer := least(greatest(coalesce(p_limit, 40), 1), 200);
begin
  perform tongs.assert_org_role(p_org_id, 'admin');

  return query
  select
