CREATE OR REPLACE FUNCTION "tongs"."admin_set_org_shared_ai_enabled"("p_org_id" "uuid", "p_enabled" boolean) RETURNS TABLE("org_id" "uuid", "shared_org_ai_enabled" boolean, "default_mode" "tongs"."ai_mode", "member_byo_allowed" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
begin
  perform tongs.assert_org_role(p_org_id, 'admin');

  if p_enabled is null then
    raise exception 'p_enabled is required'
      using errcode = '22023';
  end if;

  insert into tongs.organization_ai_policy (
    org_id,
    shared_org_ai_enabled
  )
  values (
    p_org_id,
    p_enabled
  )
  on conflict (org_id)
  do update set
    shared_org_ai_enabled = excluded.shared_org_ai_enabled,
    updated_at = now();

  return query
  select
    op.org_id,
    op.shared_org_ai_enabled,
    op.default_mode,
    op.member_byo_allowed
  from tongs.organization_ai_policy op
  where op.org_id = p_org_id;
end;
$$;


