CREATE OR REPLACE FUNCTION "tongs"."adopt_creator_amended_reference_visual_plan"("p_operation_id" "text", "p_operation_fingerprint" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare
  op tongs.unified_visual_plan_operations%rowtype;
  seq tongs.reference_visual_plan_sequences%rowtype;
  current_plan tongs.reference_visual_plan_revisions%rowtype;
  creator_added jsonb;
  retained_members jsonb;
  evidence jsonb;
begin
  select * into op
  from tongs.unified_visual_plan_operations
  where operation_id = p_operation_id
  for update;
  if not found or op.operation_fingerprint <> p_operation_fingerprint then
    return jsonb_build_object('disposition', 'operation_identity_conflict');
  end if;
  
if op.owner_cost_attempt_id is not null then
    perform tongs._assert_owner_unified_visual_plan_persistence_authority(
      op.owner_cost_attempt_id,
      op.operation_id,
      op.operation_fingerprint,
      op.workspace_id,
      op.workpiece_id,
      op.created_by
    );
  elsif coalesce(auth.role(), '') = 'service_role' then
    raise exception 'owner-bound Unified Visual Plan operation required for service continuation'
      using errcode = '42501';
  elsif not tongs.has_workspace_role(op.workspace_id, 'editor') then
    raise exception 'workspace editor authority required' using errcode = '42501';
  end if;
  if op.state <> 'reference_plan_committed' then
    return jsonb_build_object('disposition', 'stage_conflict', 'state', op.state);
  end if;
  if op.child_membership_evidence_json ? 'reference_visual' then
    return jsonb_build_object(
      'disposition', 'replay',
      'revision_id', op.child_membership_evidence_json->'reference_visual'->>'final_plan_revision_id',
      'membership_evidence', op.child_membership_evidence_json
    );
  end if;

  select * into seq
  from tongs.reference_visual_plan_sequences
  where workspace_id = op.workspace_id and workpiece_id = op.workpiece_id
  for update;
  select * into current_plan
  from tongs.reference_visual_plan_revisions
  where id = seq.current_plan_revision_id;

  if current_plan.previous_revision_id is distinct from op.expected_reference_visual_revision_id
    or current_plan.previous_revision is distinct from op.expected_reference_visual_revision
    or current_plan.contract_version <> 'forge.reference-visual.creator-amendment.v1'
    or current_plan.script_approval_id <> op.script_approval_id
    or current_plan.script_approval_revision <> op.script_approval_revision
    or current_plan.script_content_hash <> op.script_content_hash then
    return jsonb_build_object(
      'disposition', 'creator_amendment_not_adoptable',
      'current_revision_id', current_plan.id,
      'current_revision', current_plan.revision
    );
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
      'ordinal', m.ordinal,
      'opportunity_id', m.opportunity_id,
      'opportunity_revision_id', m.opportunity_revision_id,
      'origin', o.opportunity_origin
    ) order by m.ordinal, m.opportunity_id), '[]'::jsonb)
  into retained_members
  from tongs.reference_visual_plan_membership m
  join tongs.reference_visual_opportunity_revisions o on o.id = m.opportunity_revision_id
  where m.plan_revision_id = current_plan.id;

  select coalesce(jsonb_agg(jsonb_build_object(
      'ordinal', m.ordinal,
      'opportunity_id', m.opportunity_id,
      'opportunity_revision_id', m.opportunity_revision_id,
      'derived_from_opportunity_revision_id', o.derived_from_opportunity_revision_id
    ) order by m.ordinal, m.opportunity_id), '[]'::jsonb)
  into creator_added
  from tongs.reference_visual_plan_membership m
  join tongs.reference_visual_opportunity_revisions o on o.id = m.opportunity_revision_id
  where m.plan_revision_id = current_plan.id and o.opportunity_origin = 'creator_added';

  evidence := jsonb_build_object(
    'provider_plan_revision_id', null,
    'provider_output_applied', false,
    'superseded_by_creator_plan', true,
    'frozen_expected_plan_revision_id', op.expected_reference_visual_revision_id,
    'final_plan_revision_id', current_plan.id,
    'provider_proposed', '[]'::jsonb,
    'creator_retained', retained_members,
    'creator_added', creator_added
  );
  update tongs.unified_visual_plan_operations
  set child_membership_evidence_json = child_membership_evidence_json || jsonb_build_object('reference_visual', evidence),
      updated_at = now()
  where operation_id = op.operation_id
  returning child_membership_evidence_json into evidence;

  return jsonb_build_object(
    'disposition', 'creator_amendment_adopted',
    'revision_id', current_plan.id,
    'revision', current_plan.revision,
    'membership_evidence', evidence
  );
end
$$;


ALTER FUNCTION "tongs"."adopt_creator_amended_reference_visual_plan"("p_operation_id" "text", "p_operation_fingerprint" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."adopt_latest_kept_take_for_hammer"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_operation_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare
  v_result jsonb; v_outcome text; v_canonical_id uuid; v_actor uuid:=auth.uid();
  v_episode tongs.episodes%rowtype; v_revision tongs.recording_revisions%rowtype;
begin
  v_result:=tongs.adopt_latest_kept_take_for_hammer_pre_lineage(p_workspace_id,p_workpiece_id,p_operation_key);
  v_outcome:=v_result->>'outcome';
  if v_outcome not in ('adopted','duplicate') then return v_result; end if;
  v_canonical_id:=nullif(v_result->'canonical_recording'->>'id','')::uuid;
  if v_actor is null or v_canonical_id is null then
    raise exception 'Take adoption returned incomplete lineage authority' using errcode='55000';
  end if;

  select * into v_episode from tongs.episodes
  where id=p_workpiece_id and workspace_id=p_workspace_id for update;
  if not found or v_episode.canonical_recording_id is distinct from v_canonical_id then
    raise exception 'Take adoption lineage relationship mismatch' using errcode='55000';
  end if;

  if v_episode.active_revision_id is not null then
    select * into v_revision from tongs.recording_revisions
    where id=v_episode.active_revision_id and workspace_id=p_workspace_id
      and workpiece_id=p_workpiece_id and canonical_recording_id=v_canonical_id and status='active';
  end if;
  if v_revision.id is not null then
    return v_result||jsonb_build_object('recording_revision',to_jsonb(v_revision));
  end if;

  update tongs.recording_revisions set status='superseded',updated_by=v_actor,updated_at=now()
  where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and status='active';
  insert into tongs.recording_revisions(
    workspace_id,workpiece_id,canonical_recording_id,status,label,created_by,updated_by
  ) values (
    p_workspace_id,p_workpiece_id,v_canonical_id,'active','Fresh lineage for adopted take',v_actor,v_actor
  ) returning * into v_revision;
  update tongs.episodes set active_revision_id=v_revision.id,updated_at=now()
  where id=p_workpiece_id and workspace_id=p_workspace_id;

  -- Reset only columns actually owned by the mutable current-workpiece
  -- compatibility projection. The newly inserted revision starts with empty
  -- revision-owned editorial authority by construction.
  update tongs.hammer_workpiece_state set
    active_session_id=null,prep_status='idle',alignment_status='not_started',
    current_pass='transcript_cleanup',pass_status='{}'::jsonb,
    editor_session_path=null,transcript_artifact_path=null,speaker_map_artifact_path=null,
    visual_placement_artifact_path=null,audio_polish_artifact_path=null,
    edit_plan_artifact_path=null,transcript_versions_artifact_path=null,
    edit_plan_signature=null,macro_recipe_ref=null,last_macro_run_ref=null,
    updated_at=now(),updated_by=v_actor
  where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id;

  return v_result||jsonb_build_object('recording_revision',to_jsonb(v_revision));
end $$;


ALTER FUNCTION "tongs"."adopt_latest_kept_take_for_hammer"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_operation_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."adopt_latest_kept_take_for_hammer_pre_lineage"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_operation_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare
  v_user uuid := auth.uid();
  v_key text := btrim(coalesce(p_operation_key, ''));
  v_fingerprint text;
  v_episode tongs.episodes%rowtype;
  v_prior tongs.canonical_recordings%rowtype;
  v_adopted tongs.canonical_recordings%rowtype;
  v_take record;
  v_receipt tongs.hammer_take_adoption_receipts%rowtype;
  v_capture uuid;
  v_media_id text;
begin
  if v_user is null or not tongs.has_workspace_role(p_workspace_id, 'editor') then
    return jsonb_build_object('outcome','denied','reason','editor_required');
  end if;
  if length(v_key) not between 8 and 200 then
    return jsonb_build_object('outcome','conflict','reason','invalid_adoption_request');
  end if;

  select * into v_episode from tongs.episodes
    where id=p_workpiece_id and workspace_id=p_workspace_id for update;
  if not found then
    return jsonb_build_object('outcome','not_found','reason','workpiece_membership_mismatch');
  end if;

  v_fingerprint := md5(concat_ws('|', p_workspace_id, p_workpiece_id, 'latest_kept_take'));
  select * into v_receipt from tongs.hammer_take_adoption_receipts
    where workspace_id=p_workspace_id and operation_key=v_key;
  if found then
    if v_receipt.request_fingerprint <> v_fingerprint then
      return jsonb_build_object('outcome','conflict','reason','hammer_take_adoption_idempotency_conflict');
    end if;
    select * into v_adopted from tongs.canonical_recordings where id=v_receipt.adopted_canonical_recording_id;
    return jsonb_build_object('outcome','duplicate','canonical_recording',to_jsonb(v_adopted),'receipt',to_jsonb(v_receipt));
  end if;

  if v_episode.canonical_recording_id is not null then
    select * into v_prior from tongs.canonical_recordings
      where id=v_episode.canonical_recording_id and workspace_id=p_workspace_id and workpiece_id=p_workpiece_id;
    if not found then
      return jsonb_build_object('outcome','blocked','reason','canonical_recording_pointer_invalid');
    end if;
  end if;

  select r.*, c.capture_authority_id into v_take
    from tongs.current_workpiece_recorded_takes r
    left join tongs.anvil_recording_completion_requests c on c.id=r.completion_id
    where r.workspace_id=p_workspace_id and r.workpiece_id=p_workpiece_id and r.keep_id is not null
    order by r.kept_at desc nulls last, r.completed_at desc, r.source_authority_id desc limit 1;
  if not found then
    return jsonb_build_object('outcome','blocked','reason','canonical_recording_missing_take');
  end if;

  v_capture := v_take.capture_authority_id;
  v_media_id := case when v_take.source_kind='anvil_capture'
    then 'anvil-completion:'||v_take.source_authority_id::text
    else 'hammer-import:'||v_take.source_authority_id::text end;

  if v_prior.id is not null
    and v_prior.source_kind=v_take.source_kind
    and v_prior.source_authority_id=v_take.source_authority_id then
    insert into tongs.hammer_take_adoption_receipts(
      workspace_id,workpiece_id,operation_key,request_fingerprint,prior_canonical_recording_id,
      adopted_canonical_recording_id,source_kind,source_authority_id,adopted_by
    ) values (
      p_workspace_id,p_workpiece_id,v_key,v_fingerprint,v_prior.id,v_prior.id,
      v_take.source_kind,v_take.source_authority_id,v_user
    ) returning * into v_receipt;
    return jsonb_build_object('outcome','already_current','canonical_recording',to_jsonb(v_prior),'receipt',to_jsonb(v_receipt));
  end if;

  update tongs.recording_revisions set status='superseded',updated_by=v_user,updated_at=now()
    where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and status='active';
  update tongs.hammer_preparation_attempts set state='superseded'
    where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id
      and state not in ('ready','blocked','superseded');

  insert into tongs.canonical_recordings(
    workspace_id,workpiece_id,status,kept_take_event_id,media_path,media_content_type,media_bytes,
    recording_session_id,anvil_capture_session_id,media_id,media_signature,source_kind,
    source_authority_id,source_capture_authority_id,created_by,updated_by
  ) values (
    p_workspace_id,p_workpiece_id,'draft',null,v_take.media_path,v_take.media_content_type,v_take.media_bytes,
    v_take.recording_session_id,v_take.capture_session_id::text,v_media_id,lower(v_take.media_hash),v_take.source_kind,
    v_take.source_authority_id,v_capture,v_user,v_user
  ) returning * into v_adopted;

  update tongs.episodes set canonical_recording_id=v_adopted.id,active_revision_id=null,updated_at=now()
    where id=p_workpiece_id and workspace_id=p_workspace_id;

  insert into tongs.hammer_take_adoption_receipts(
    workspace_id,workpiece_id,operation_key,request_fingerprint,prior_canonical_recording_id,
    adopted_canonical_recording_id,source_kind,source_authority_id,adopted_by
  ) values (
    p_workspace_id,p_workpiece_id,v_key,v_fingerprint,v_prior.id,v_adopted.id,
    v_take.source_kind,v_take.source_authority_id,v_user
  ) returning * into v_receipt;

  return jsonb_build_object('outcome','adopted','canonical_recording',to_jsonb(v_adopted),'receipt',to_jsonb(v_receipt));
exception when unique_violation then
  select * into v_receipt from tongs.hammer_take_adoption_receipts
    where workspace_id=p_workspace_id and operation_key=v_key;
  if found and v_receipt.request_fingerprint=v_fingerprint then
    select * into v_adopted from tongs.canonical_recordings where id=v_receipt.adopted_canonical_recording_id;
    return jsonb_build_object('outcome','duplicate','canonical_recording',to_jsonb(v_adopted),'receipt',to_jsonb(v_receipt));
  end if;
  raise;
end $$;


ALTER FUNCTION "tongs"."adopt_latest_kept_take_for_hammer_pre_lineage"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_operation_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."adopt_legacy_source"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_legacy_source_id" "text", "p_legacy_source_path" "text", "p_legacy_source_revision" bigint, "p_legacy_source_hash" "text", "p_legacy_links_path" "text", "p_legacy_links_revision" bigint, "p_legacy_links_hash" "text", "p_source_type" "text", "p_title" "text", "p_author_creator" "text", "p_publisher" "text", "p_published_at" timestamp with time zone, "p_canonical_url" "text", "p_document_identity" "text", "p_relationship_type" "text", "p_script_approval_id" "uuid", "p_script_approval_revision" bigint, "p_citation_anchor_json" "jsonb", "p_document_locator_json" "jsonb", "p_media_range_json" "jsonb", "p_quotation_excerpt_hash" "text", "p_relationship_note" "text", "p_operation_id" "text", "p_operation_fingerprint" "text", "p_actor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $_$
declare v_op tongs.source_operation_receipts%rowtype; v_source tongs.sources%rowtype; v_rev tongs.source_revisions%rowtype;
 v_link tongs.workpiece_source_link_revisions%rowtype; v_source_hash text; v_source_immutable text; v_link_hash text; v_link_immutable text; v_link_id uuid; v_result jsonb;
begin
 if not tongs.has_workspace_role(p_workspace_id,'editor') then raise exception 'workspace editor authority required' using errcode='42501'; end if;
 if auth.uid() is distinct from p_actor_id then raise exception 'Legacy-adoption actor must match authenticated creator' using errcode='42501'; end if;
 if p_legacy_source_hash!~'^[0-9a-f]{64}$' or p_legacy_links_hash!~'^[0-9a-f]{64}$' or p_legacy_source_revision<1 or p_legacy_links_revision<1 then return jsonb_build_object('disposition','legacy_evidence_invalid'); end if;
 perform pg_advisory_xact_lock(hashtextextended(p_operation_id,0));
 select * into v_op from tongs.source_operation_receipts where operation_id=p_operation_id for update;
 if found then
  if v_op.operation_fingerprint<>p_operation_fingerprint or v_op.workspace_id<>p_workspace_id or v_op.workpiece_id is distinct from p_workpiece_id or v_op.operation_type<>'legacy_adoption' then return jsonb_build_object('disposition','operation_identity_conflict'); end if;
  return v_op.receipt_json;
 end if;
 insert into tongs.sources(workspace_id,stable_key,created_by) values(p_workspace_id,'legacy:'||btrim(p_legacy_source_id),p_actor_id)
 on conflict(workspace_id,stable_key) do nothing;
 select * into v_source from tongs.sources where workspace_id=p_workspace_id and stable_key='legacy:'||btrim(p_legacy_source_id) for update;
 if exists(select 1 from tongs.source_sequences where workspace_id=p_workspace_id and source_id=v_source.id) then return jsonb_build_object('disposition','legacy_source_already_adopted'); end if;
 v_source_hash:=encode(extensions.digest(convert_to(jsonb_strip_nulls(jsonb_build_object('source_type',p_source_type,'title',p_title,'author_creator',p_author_creator,'publisher',p_publisher,'published_at',p_published_at,'canonical_url',p_canonical_url,'document_identity',p_document_identity,'legacy_path',p_legacy_source_path,'legacy_revision',p_legacy_source_revision,'legacy_hash',lower(p_legacy_source_hash)))::text,'UTF8'),'sha256'),'hex');
 v_source_immutable:=encode(extensions.digest(convert_to(jsonb_build_object('source_id',v_source.id,'revision',1,'content_hash',v_source_hash)::text,'UTF8'),'sha256'),'hex');
 insert into tongs.source_revisions(source_id,workspace_id,revision,source_type,title,author_creator,publisher,published_at,canonical_url,document_identity,metadata_json,provenance_json,metadata_contract_version,provenance_contract_version,content_hash,immutable_revision_hash,created_by)
 values(v_source.id,p_workspace_id,1,btrim(p_source_type),btrim(p_title),nullif(btrim(p_author_creator),''),nullif(btrim(p_publisher),''),p_published_at,nullif(btrim(p_canonical_url),''),nullif(btrim(p_document_identity),''),'{}'::jsonb,jsonb_build_object('source','legacy_current_state','legacy_source_path',p_legacy_source_path,'legacy_source_revision',p_legacy_source_revision,'legacy_source_hash',lower(p_legacy_source_hash)),'forge.source.metadata.v1','forge.source.provenance.v1',v_source_hash,v_source_immutable,p_actor_id) returning * into v_rev;
 insert into tongs.source_sequences values(p_workspace_id,v_source.id,v_rev.id,1,now());
 v_link_id:=gen_random_uuid();
 v_link_hash:=encode(extensions.digest(convert_to(jsonb_strip_nulls(jsonb_build_object('source_revision_id',v_rev.id,'relationship_type',p_relationship_type,'script_approval_id',p_script_approval_id,'script_approval_revision',p_script_approval_revision,'citation_anchor',coalesce(p_citation_anchor_json,'{}'::jsonb),'document_locator',coalesce(p_document_locator_json,'{}'::jsonb),'media_range',coalesce(p_media_range_json,'{}'::jsonb),'quotation_excerpt_hash',lower(p_quotation_excerpt_hash),'relationship_note',p_relationship_note,'legacy_links_path',p_legacy_links_path,'legacy_links_revision',p_legacy_links_revision,'legacy_links_hash',lower(p_legacy_links_hash)))::text,'UTF8'),'sha256'),'hex');
 v_link_immutable:=encode(extensions.digest(convert_to(jsonb_build_object('link_id',v_link_id,'revision',1,'content_hash',v_link_hash)::text,'UTF8'),'sha256'),'hex');
 insert into tongs.workpiece_source_link_revisions(link_id,workspace_id,workpiece_id,revision,source_id,source_revision_id,source_revision,relationship_type,script_approval_id,script_approval_revision,citation_anchor_json,document_locator_json,media_range_json,quotation_excerpt_hash,relationship_note,provenance_json,content_hash,immutable_revision_hash,created_by)
 values(v_link_id,p_workspace_id,p_workpiece_id,1,v_source.id,v_rev.id,1,btrim(p_relationship_type),p_script_approval_id,p_script_approval_revision,coalesce(p_citation_anchor_json,'{}'::jsonb),coalesce(p_document_locator_json,'{}'::jsonb),coalesce(p_media_range_json,'{}'::jsonb),lower(p_quotation_excerpt_hash),nullif(btrim(p_relationship_note),''),jsonb_build_object('source','legacy_current_state','legacy_links_path',p_legacy_links_path,'legacy_links_revision',p_legacy_links_revision,'legacy_links_hash',lower(p_legacy_links_hash)),v_link_hash,v_link_immutable,p_actor_id) returning * into v_link;
 insert into tongs.workpiece_source_link_sequences values(p_workspace_id,p_workpiece_id,v_link_id,v_link.id,1,now());
 v_result:=jsonb_build_object('disposition','committed','adoption','legacy_current_state','source',to_jsonb(v_source),'source_revision',to_jsonb(v_rev),'link_revision',to_jsonb(v_link));
 insert into tongs.source_operation_receipts(operation_id,operation_fingerprint,operation_type,workspace_id,workpiece_id,source_id,link_id,normalized_inputs_json,state,result_source_revision_id,result_link_revision_id,receipt_json,created_by)
 values(p_operation_id,p_operation_fingerprint,'legacy_adoption',p_workspace_id,p_workpiece_id,v_source.id,v_link_id,jsonb_build_object('legacy_source_path',p_legacy_source_path,'legacy_source_revision',p_legacy_source_revision,'legacy_source_hash',lower(p_legacy_source_hash),'legacy_links_path',p_legacy_links_path,'legacy_links_revision',p_legacy_links_revision,'legacy_links_hash',lower(p_legacy_links_hash)),'committed',v_rev.id,v_link.id,v_result,p_actor_id);
 return v_result;
end $_$;


ALTER FUNCTION "tongs"."adopt_legacy_source"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_legacy_source_id" "text", "p_legacy_source_path" "text", "p_legacy_source_revision" bigint, "p_legacy_source_hash" "text", "p_legacy_links_path" "text", "p_legacy_links_revision" bigint, "p_legacy_links_hash" "text", "p_source_type" "text", "p_title" "text", "p_author_creator" "text", "p_publisher" "text", "p_published_at" timestamp with time zone, "p_canonical_url" "text", "p_document_identity" "text", "p_relationship_type" "text", "p_script_approval_id" "uuid", "p_script_approval_revision" bigint, "p_citation_anchor_json" "jsonb", "p_document_locator_json" "jsonb", "p_media_range_json" "jsonb", "p_quotation_excerpt_hash" "text", "p_relationship_note" "text", "p_operation_id" "text", "p_operation_fingerprint" "text", "p_actor_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."adopt_legacy_source"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_legacy_source_id" "text", "p_legacy_source_path" "text", "p_legacy_source_revision" bigint, "p_legacy_source_hash" "text", "p_legacy_links_path" "text", "p_legacy_links_revision" bigint, "p_legacy_links_hash" "text", "p_source_type" "text", "p_title" "text", "p_author_creator" "text", "p_publisher" "text", "p_published_at" timestamp with time zone, "p_canonical_url" "text", "p_document_identity" "text", "p_relationship_type" "text", "p_script_approval_id" "uuid", "p_script_approval_revision" bigint, "p_citation_anchor_json" "jsonb", "p_document_locator_json" "jsonb", "p_media_range_json" "jsonb", "p_quotation_excerpt_hash" "text", "p_relationship_note" "text", "p_operation_id" "text", "p_operation_fingerprint" "text", "p_actor_id" "uuid") IS 'Explicit replay-safe adoption of one current legacy Source and workpiece link. It never invents historical revisions.';



CREATE OR REPLACE FUNCTION "tongs"."adopt_repaired_image_map_for_unified_operation"("p_operation_id" "text", "p_operation_fingerprint" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare
  op tongs.unified_visual_plan_operations%rowtype;
  seq tongs.workpiece_image_map_sequences%rowtype;
  current_map tongs.image_map_revisions%rowtype;
  evidence jsonb;
begin
  select * into op from tongs.unified_visual_plan_operations where operation_id = p_operation_id for update;
  if not found or op.operation_fingerprint <> p_operation_fingerprint then
    return jsonb_build_object('disposition', 'operation_identity_conflict');
  end if;
  
if op.owner_cost_attempt_id is not null then
    perform tongs._assert_owner_unified_visual_plan_persistence_authority(
      op.owner_cost_attempt_id,
      op.operation_id,
      op.operation_fingerprint,
      op.workspace_id,
      op.workpiece_id,
      op.created_by
    );
  elsif coalesce(auth.role(), '') = 'service_role' then
    raise exception 'owner-bound Unified Visual Plan operation required for service continuation'
      using errcode = '42501';
  elsif not tongs.has_workspace_role(op.workspace_id, 'editor') then
    raise exception 'workspace editor authority required' using errcode = '42501';
  end if;
  if op.state <> 'reference_visual_plan_committed' then
    return jsonb_build_object('disposition', 'stage_conflict', 'state', op.state);
  end if;

  select * into seq
  from tongs.workpiece_image_map_sequences
  where workspace_id = op.workspace_id and workpiece_id = op.workpiece_id
  for update;
  if seq.current_revision_id = op.image_map_revision_id then
    return jsonb_build_object('disposition', 'current', 'revision_id', op.image_map_revision_id, 'revision', op.image_map_revision);
  end if;

  select * into current_map from tongs.image_map_revisions where id = seq.current_revision_id;
  if current_map.previous_revision_id is distinct from op.image_map_revision_id
    or current_map.previous_revision is distinct from op.image_map_revision
    or current_map.source_script_approval_id <> op.script_approval_id
    or current_map.source_script_approval_revision <> op.script_approval_revision
    or current_map.source_script_content_hash <> op.script_content_hash
    or current_map.anchor_contract_version <> 'forge.image-map-anchor.v1'
    or current_map.provenance_state <> 'current' then
    return jsonb_build_object(
      'disposition', 'image_repair_not_adoptable',
      'current_revision_id', current_map.id,
      'current_revision', current_map.revision
    );
  end if;

  evidence := coalesce(op.child_membership_evidence_json->'image', '{}'::jsonb)
    || jsonb_build_object(
      'authority_repair_successor', true,
      'repaired_from_revision_id', op.image_map_revision_id,
      'final_plan_revision_id', current_map.id
    );
  update tongs.unified_visual_plan_operations
  set image_map_revision_id = current_map.id,
      image_map_revision = current_map.revision,
      image_plan_content_hash = current_map.document_content_hash,
      image_plan_empty = jsonb_array_length(coalesce(current_map.document_json->'entries', '[]'::jsonb)) = 0,
      child_membership_evidence_json = child_membership_evidence_json || jsonb_build_object('image', evidence),
      failed_stage = null,
      failure_code = null,
      failure_message = null,
      updated_at = now()
  where operation_id = op.operation_id
  returning child_membership_evidence_json into evidence;

  return jsonb_build_object(
    'disposition', 'image_repair_adopted',
    'revision_id', current_map.id,
    'revision', current_map.revision,
    'membership_evidence', evidence
  );
end
$$;


ALTER FUNCTION "tongs"."adopt_repaired_image_map_for_unified_operation"("p_operation_id" "text", "p_operation_fingerprint" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."advance_hammer_preparation"("p_preparation_attempt_id" "uuid", "p_expected_state_version" bigint, "p_action" "text", "p_transcript_job_id" "uuid" DEFAULT NULL::"uuid", "p_transcript_artifact_path" "text" DEFAULT NULL::"text", "p_failure_code" "text" DEFAULT NULL::"text", "p_failure_detail" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare v_user uuid:=auth.uid();v_attempt tongs.hammer_preparation_attempts%rowtype;v_next text;
begin
  select * into v_attempt from tongs.hammer_preparation_attempts where id=p_preparation_attempt_id for update;
  if not found then return jsonb_build_object('outcome','not_found','reason','preparation_attempt_not_found'); end if;
  if v_user is null or not tongs.has_workspace_role(v_attempt.workspace_id,'editor') then return jsonb_build_object('outcome','denied','reason','editor_required'); end if;
  if v_attempt.state_version<>p_expected_state_version then return jsonb_build_object('outcome','conflict','reason','preparation_state_changed','preparation_attempt',to_jsonb(v_attempt)); end if;
  v_next:=case p_action
    when 'await_transcript_choice' then 'awaiting_transcript_choice'
    when 'authorize_ai' then 'transcribing'
    when 'begin_hydration' then 'hydrating'
    when 'mark_ready' then 'ready'
    when 'retry' then 'resolving_transcript'
    when 'fail_recoverable' then 'recoverable_failure'
    when 'block' then 'blocked' else null end;
  if v_next is null then return jsonb_build_object('outcome','conflict','reason','preparation_action_invalid'); end if;
  if p_action='authorize_ai' and p_transcript_job_id is null then return jsonb_build_object('outcome','conflict','reason','transcript_job_required'); end if;
  update tongs.hammer_preparation_attempts set state=v_next,
    transcript_policy=case when p_action='authorize_ai' then 'allow_ai_fallback' else transcript_policy end,
    transcript_job_id=coalesce(p_transcript_job_id,transcript_job_id),
    transcript_artifact_path=coalesce(p_transcript_artifact_path,transcript_artifact_path),
    failure_code=case when p_action in ('fail_recoverable','block') then p_failure_code else null end,
    failure_detail=case when p_action in ('fail_recoverable','block') then p_failure_detail else null end,
    retry_count=retry_count+case when p_action='retry' then 1 else 0 end,
    completed_at=case when v_next='ready' then now() else completed_at end,
    failed_at=case when v_next in ('recoverable_failure','blocked') then now() else null end
  where id=p_preparation_attempt_id returning * into v_attempt;
  return jsonb_build_object('outcome','advanced','preparation_attempt',to_jsonb(v_attempt));
end $$;


ALTER FUNCTION "tongs"."advance_hammer_preparation"("p_preparation_attempt_id" "uuid", "p_expected_state_version" bigint, "p_action" "text", "p_transcript_job_id" "uuid", "p_transcript_artifact_path" "text", "p_failure_code" "text", "p_failure_detail" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."anvil_transition_take_completed"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_capture_session_id" "uuid", "p_ready_transition_id" "uuid", "p_expected_script_revision" bigint, "p_expected_script_hash" "text", "p_media_path" "text", "p_expected_media_revision" bigint, "p_expected_media_hash" "text", "p_idempotency_key" "text", "p_completion_evidence" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_key text := btrim(coalesce(p_idempotency_key, ''));
  v_script_hash text := lower(btrim(coalesce(p_expected_script_hash, '')));
  v_media_hash text := lower(btrim(coalesce(p_expected_media_hash, '')));
  v_media_path text := btrim(coalesce(p_media_path, ''));
  v_fingerprint text;
  v_existing tongs.anvil_recording_completion_requests%rowtype;
  v_ready record;
  v_media record;
  v_saved tongs.anvil_recording_completion_requests%rowtype;
begin
  perform pg_advisory_xact_lock(hashtextextended(p_workspace_id::text || ':' || v_key, 0));
  if v_user_id is null or not tongs.has_workspace_role(p_workspace_id, 'editor') then
    return jsonb_build_object('outcome', 'denied', 'completion', null);
  end if;
  if not exists (select 1 from tongs.episodes where id = p_workpiece_id and workspace_id = p_workspace_id) then
    return jsonb_build_object('outcome', 'not_found', 'completion', null);
  end if;
  if length(v_key) not between 8 and 200 then
    return jsonb_build_object('outcome', 'conflict', 'completion', null, 'reason', 'invalid_idempotency_key');
  end if;
  if p_completion_evidence is null or jsonb_typeof(p_completion_evidence) <> 'object'
     or p_completion_evidence->>'schema' <> 'anvil.recording-completion.v1'
     or p_completion_evidence->'completed' is distinct from 'true'::jsonb
     or p_completion_evidence->>'capture_session_id' is distinct from p_capture_session_id::text
     or p_completion_evidence#>'{coverage,terminal_line_completed}' is distinct from 'true'::jsonb
     or p_completion_evidence#>'{coverage,unresolved_skipped_line_count}' is distinct from '0'::jsonb
     or jsonb_typeof(p_completion_evidence#>'{coverage,unresolved_skipped_lines}') <> 'array'
     or jsonb_array_length(p_completion_evidence#>'{coverage,unresolved_skipped_lines}') <> 0
     or coalesce((p_completion_evidence#>>'{artifact_validation,ok}')::boolean, false) is not true
     or lower(coalesce(p_completion_evidence#>>'{artifact_validation,sha256}', '')) <> v_media_hash then
    return jsonb_build_object('outcome', 'conflict', 'completion', null, 'reason', 'invalid_completion_evidence');
  end if;
  select * into v_ready from tongs.current_workpiece_ready_scripts
    where workspace_id = p_workspace_id and workpiece_id = p_workpiece_id
      and transition_id = p_ready_transition_id and script_revision = p_expected_script_revision
      and script_hash = v_script_hash;
  if not found then
    return jsonb_build_object('outcome', 'stale', 'completion', null, 'reason', 'ready_contract_mismatch');
  end if;
  select revision, lower(hash_value) as hash_value, bytes into v_media
    from tongs.workpiece_files where workpiece_id = p_workpiece_id and path = v_media_path;
  if not found then
    return jsonb_build_object('outcome', 'not_found', 'completion', null, 'reason', 'media_not_found');
  end if;
  if v_media.revision <> p_expected_media_revision or v_media.hash_value <> v_media_hash then
    return jsonb_build_object('outcome', 'stale', 'completion', null, 'reason', 'media_contract_mismatch',
      'current_media_revision', v_media.revision, 'current_media_hash', v_media.hash_value);
  end if;
  v_fingerprint := md5(concat_ws('|', p_workspace_id, p_workpiece_id, p_capture_session_id,
    p_ready_transition_id, p_expected_script_revision, v_script_hash, v_media_path,
    p_expected_media_revision, v_media_hash, p_completion_evidence::text));
  select * into v_existing from tongs.anvil_recording_completion_requests
    where workspace_id = p_workspace_id and idempotency_key = v_key;
  if found then
    if v_existing.request_fingerprint = v_fingerprint then
      return jsonb_build_object('outcome', 'duplicate', 'completion', to_jsonb(v_existing));
    end if;
    return jsonb_build_object('outcome', 'conflict', 'completion', null, 'reason', 'idempotency_key_reused');
  end if;
  select * into v_existing from tongs.anvil_recording_completion_requests
    where workspace_id = p_workspace_id and workpiece_id = p_workpiece_id
      and capture_session_id = p_capture_session_id;
  if found then
    if v_existing.request_fingerprint = v_fingerprint then
      return jsonb_build_object('outcome', 'duplicate', 'completion', to_jsonb(v_existing));
    end if;
    return jsonb_build_object('outcome', 'conflict', 'completion', null, 'reason', 'capture_session_reused');
  end if;
  insert into tongs.anvil_recording_completion_requests(
    workspace_id, workpiece_id, capture_session_id, ready_transition_id,
    script_revision, script_hash, media_path, media_revision, media_hash,
    idempotency_key, request_fingerprint, completion_evidence, completed_by
  ) values (
    p_workspace_id, p_workpiece_id, p_capture_session_id, p_ready_transition_id,
    p_expected_script_revision, v_script_hash, v_media_path, p_expected_media_revision, v_media_hash,
    v_key, v_fingerprint, p_completion_evidence, v_user_id
  ) returning * into v_saved;
  perform set_config('tongs.recording_authority_rpc', 'on', true);
  insert into tongs.workpiece_events(workpiece_id, event_name, payload, correlation_id,
    written_by_tool, written_by_tool_version, written_by_lane)
  values (p_workpiece_id, 'take_completed', jsonb_build_object(
    'authority_schema', 'anvil.recording-completion.v1', 'completion_id', v_saved.id,
    'workspace_id', p_workspace_id, 'capture_session_id', p_capture_session_id,
    'ready_transition_id', p_ready_transition_id, 'script_revision', p_expected_script_revision,
    'script_hash', v_script_hash, 'file_path', v_media_path, 'media_revision', p_expected_media_revision,
    'media_hash', v_media_hash), v_key, 'anvil', '0.0.0', 'forge-managed');
  return jsonb_build_object('outcome', 'saved', 'completion', to_jsonb(v_saved));
end;
$$;


ALTER FUNCTION "tongs"."anvil_transition_take_completed"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_capture_session_id" "uuid", "p_ready_transition_id" "uuid", "p_expected_script_revision" bigint, "p_expected_script_hash" "text", "p_media_path" "text", "p_expected_media_revision" bigint, "p_expected_media_hash" "text", "p_idempotency_key" "text", "p_completion_evidence" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."anvil_transition_take_completed_v2"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_capture_session_id" "uuid", "p_recording_session_id" "uuid", "p_script_path" "text", "p_expected_script_revision" bigint, "p_expected_script_hash" "text", "p_media_path" "text", "p_expected_media_revision" bigint, "p_expected_media_hash" "text", "p_expected_media_bytes" bigint, "p_expected_media_content_type" "text", "p_storage_bucket" "text", "p_storage_key" "text", "p_idempotency_key" "text", "p_completion_evidence" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $_$
declare
  v_user uuid := auth.uid(); v_key text := btrim(coalesce(p_idempotency_key,''));
  v_script_path text := btrim(coalesce(p_script_path,'')); v_media_path text := btrim(coalesce(p_media_path,''));
  v_script_hash text := lower(btrim(coalesce(p_expected_script_hash,'')));
  v_media_hash text := lower(btrim(coalesce(p_expected_media_hash,'')));
  v_content_type text := lower(btrim(coalesce(p_expected_media_content_type,'')));
  v_fingerprint text; v_existing tongs.anvil_recording_completion_requests%rowtype;
  v_media record; v_script record; v_saved tongs.anvil_recording_completion_requests%rowtype;
begin
  perform pg_advisory_xact_lock(hashtextextended(p_workspace_id::text || ':' || v_key, 0));
  if v_user is null or not tongs.has_workspace_role(p_workspace_id, 'editor') then
    return jsonb_build_object('outcome','denied','completion',null);
  end if;
  if not exists(select 1 from tongs.episodes where id=p_workpiece_id and workspace_id=p_workspace_id) then
    return jsonb_build_object('outcome','not_found','completion',null);
  end if;
  if length(v_key) not between 8 and 200 or v_script_path = '' or v_media_path = ''
     or v_script_hash !~ '^[0-9a-f]{64}$' or v_media_hash !~ '^[0-9a-f]{64}$'
     or p_expected_media_bytes <= 0 or v_content_type = ''
     or p_completion_evidence is null or jsonb_typeof(p_completion_evidence) <> 'object'
     or p_completion_evidence->>'schema' <> 'anvil.recording-completion.v2'
     or p_completion_evidence->>'capture_session_id' is distinct from p_capture_session_id::text
     or coalesce((p_completion_evidence#>>'{artifact_validation,ok}')::boolean,false) is not true
     or lower(coalesce(p_completion_evidence#>>'{artifact_validation,sha256}','')) <> v_media_hash then
    return jsonb_build_object('outcome','conflict','completion',null,'reason','invalid_completion_evidence');
  end if;
  select revision, lower(hash_value) hash_value into v_script from tongs.workpiece_files
    where workpiece_id=p_workpiece_id and path=v_script_path;
  if not found then return jsonb_build_object('outcome','not_found','completion',null,'reason','script_not_found'); end if;
  if v_script.revision <> p_expected_script_revision or v_script.hash_value <> v_script_hash then
    return jsonb_build_object('outcome','stale','completion',null,'reason','script_contract_mismatch');
  end if;
  select revision, lower(hash_value) hash_value, bytes, lower(content_type) content_type, storage_bucket, storage_key
    into v_media from tongs.workpiece_files where workpiece_id=p_workpiece_id and path=v_media_path;
  if not found then return jsonb_build_object('outcome','not_found','completion',null,'reason','media_not_found'); end if;
  if v_media.revision <> p_expected_media_revision or v_media.hash_value <> v_media_hash
     or v_media.bytes <> p_expected_media_bytes or v_media.content_type <> v_content_type
     or v_media.storage_bucket <> p_storage_bucket or v_media.storage_key <> p_storage_key then
    return jsonb_build_object('outcome','stale','completion',null,'reason','media_contract_mismatch');
  end if;
  v_fingerprint := md5(concat_ws('|',p_workspace_id,p_workpiece_id,p_capture_session_id,p_recording_session_id,
    v_script_path,p_expected_script_revision,v_script_hash,v_media_path,p_expected_media_revision,v_media_hash,
    p_expected_media_bytes,v_content_type,p_storage_bucket,p_storage_key,p_completion_evidence::text));
  select * into v_existing from tongs.anvil_recording_completion_requests
    where workspace_id=p_workspace_id and idempotency_key=v_key;
  if found then
    if v_existing.request_fingerprint=v_fingerprint then return jsonb_build_object('outcome','duplicate','completion',to_jsonb(v_existing)); end if;
    return jsonb_build_object('outcome','conflict','completion',null,'reason','idempotency_key_reused');
  end if;
  select * into v_existing from tongs.anvil_recording_completion_requests
    where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and capture_session_id=p_capture_session_id;
  if found then
    if v_existing.request_fingerprint=v_fingerprint then return jsonb_build_object('outcome','duplicate','completion',to_jsonb(v_existing)); end if;
    return jsonb_build_object('outcome','conflict','completion',null,'reason','capture_session_reused');
  end if;
  insert into tongs.anvil_recording_completion_requests(workspace_id,workpiece_id,capture_session_id,
    ready_transition_id,script_path,script_revision,script_hash,media_path,media_revision,media_hash,media_bytes,
    media_content_type,storage_bucket,storage_key,recording_session_id,idempotency_key,request_fingerprint,
    completion_evidence,completed_by)
  values(p_workspace_id,p_workpiece_id,p_capture_session_id,null,v_script_path,p_expected_script_revision,v_script_hash,
    v_media_path,p_expected_media_revision,v_media_hash,p_expected_media_bytes,v_content_type,p_storage_bucket,p_storage_key,
    p_recording_session_id,v_key,v_fingerprint,p_completion_evidence,v_user) returning * into v_saved;
  perform set_config('tongs.recording_authority_rpc','on',true);
  insert into tongs.workpiece_events(workpiece_id,event_name,payload,correlation_id,written_by_tool,written_by_tool_version,written_by_lane)
  values(p_workpiece_id,'take_completed',jsonb_build_object('authority_schema','anvil.recording-completion.v2',
    'completion_id',v_saved.id,'workspace_id',p_workspace_id,'capture_session_id',p_capture_session_id,
    'script_path',v_script_path,'script_revision',p_expected_script_revision,'script_hash',v_script_hash,
    'file_path',v_media_path,'media_revision',p_expected_media_revision,'media_hash',v_media_hash),
    v_key,'anvil',coalesce(p_completion_evidence->>'anvil_version','unknown'),'forge-managed');
  return jsonb_build_object('outcome','saved','completion',to_jsonb(v_saved));
end; $_$;


ALTER FUNCTION "tongs"."anvil_transition_take_completed_v2"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_capture_session_id" "uuid", "p_recording_session_id" "uuid", "p_script_path" "text", "p_expected_script_revision" bigint, "p_expected_script_hash" "text", "p_media_path" "text", "p_expected_media_revision" bigint, "p_expected_media_hash" "text", "p_expected_media_bytes" bigint, "p_expected_media_content_type" "text", "p_storage_bucket" "text", "p_storage_key" "text", "p_idempotency_key" "text", "p_completion_evidence" "jsonb") OWNER TO "postgres";


