    or p_decision_evidence->>'schema'<>'anvil.take-decision.v1' or p_decision_evidence->>'decision'<>'keep'
    or p_decision_evidence->>'completion_id' is distinct from p_completion_id::text
    or p_decision_evidence->>'capture_session_id' is distinct from p_capture_session_id::text then
    return jsonb_build_object('outcome','conflict','keep',null,'reason','invalid_keep_evidence');
  end if;
  v_fingerprint:=md5(concat_ws('|',p_workspace_id,p_workpiece_id,p_capture_session_id,p_completion_id,p_decision_evidence::text));
  select * into v_existing from tongs.anvil_recording_keep_requests where workspace_id=p_workspace_id and idempotency_key=v_key;
  if found then
    if v_existing.request_fingerprint=v_fingerprint then return jsonb_build_object('outcome','duplicate','keep',to_jsonb(v_existing)); end if;
    return jsonb_build_object('outcome','conflict','keep',null,'reason','idempotency_key_reused');
  end if;
  select * into v_existing from tongs.anvil_recording_keep_requests where completion_id=p_completion_id;
  if found then return jsonb_build_object('outcome','duplicate','keep',to_jsonb(v_existing)); end if;
  insert into tongs.anvil_recording_keep_requests(workspace_id,workpiece_id,capture_session_id,completion_id,idempotency_key,request_fingerprint,decision_evidence,kept_by)
  values(p_workspace_id,p_workpiece_id,p_capture_session_id,p_completion_id,v_key,v_fingerprint,p_decision_evidence,v_user) returning * into v_saved;
  perform set_config('tongs.recording_authority_rpc','on',true);
  insert into tongs.workpiece_events(workpiece_id,event_name,payload,correlation_id,written_by_tool,written_by_tool_version,written_by_lane)
  values(p_workpiece_id,'take_kept',jsonb_build_object('authority_schema','anvil.take-decision.v1','keep_id',v_saved.id,'completion_id',p_completion_id,'workspace_id',p_workspace_id,'capture_session_id',p_capture_session_id,'file_path',v_completion.media_path,'media_revision',v_completion.media_revision,'media_hash',v_completion.media_hash),v_key,'anvil','0.0.0','forge-managed');
  return jsonb_build_object('outcome','saved','keep',to_jsonb(v_saved));
end; $$;


ALTER FUNCTION "tongs"."anvil_transition_take_kept"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_capture_session_id" "uuid", "p_completion_id" "uuid", "p_idempotency_key" "text", "p_decision_evidence" "jsonb") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "tongs"."bellows_session_checkpoints" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "session_id" "text" NOT NULL,
    "sequence_no" bigint NOT NULL,
    "checkpoint_kind" "text" NOT NULL,
    "trigger_action_source" "text" NOT NULL,
    "trigger_action_type" "text" NOT NULL,
    "actor_type" "text",
    "actor_id" "text",
    "effect_type" "text",
    "follow_up_action_source" "text",
    "follow_up_action_type" "text",
    "offset_ms" bigint,
    "occurred_at" timestamp with time zone,
    "lifecycle_state" "text" NOT NULL,
    "recording_state" "text" NOT NULL,
    "broadcast_state" "text" NOT NULL,
    "upload_state" "text" NOT NULL,
    "seal_state" "text" NOT NULL,
    "outcome" "text",
    "acting_authority_state" "text" NOT NULL,
    "host_participant_id" "text",
    "acting_host_participant_id" "text",
    "co_host_participant_ids" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "integrity_flags" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "event_count" integer DEFAULT 0 NOT NULL,
    "snapshot_schema_version" integer DEFAULT 1 NOT NULL,
    "session_snapshot" "jsonb" NOT NULL,
    "delta" "jsonb",
    "recorded_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "bellows_session_checkpoints_acting_authority_state_check" CHECK (("acting_authority_state" = ANY (ARRAY['host_present'::"text", 'co_host_promoted'::"text", 'engine_stewardship'::"text"]))),
    CONSTRAINT "bellows_session_checkpoints_actor_type_check" CHECK ((("actor_type" IS NULL) OR ("actor_type" = ANY (ARRAY['host'::"text", 'co_host'::"text", 'participant'::"text", 'engine'::"text", 'system'::"text"])))),
    CONSTRAINT "bellows_session_checkpoints_broadcast_state_check" CHECK (("broadcast_state" = ANY (ARRAY['not_broadcasting'::"text", 'starting'::"text", 'live'::"text", 'degraded'::"text", 'disconnected'::"text", 'ended'::"text"]))),
    CONSTRAINT "bellows_session_checkpoints_delta_check" CHECK ((("delta" IS NULL) OR ("jsonb_typeof"("delta") = 'object'::"text"))),
    CONSTRAINT "bellows_session_checkpoints_effect_type_check" CHECK ((("effect_type" IS NULL) OR ("effect_type" = ANY (ARRAY['run_preflight_checks'::"text", 'generate_invite_links'::"text", 'start_countdown'::"text", 'establish_t0'::"text", 'emit_sync_marker'::"text", 'start_local_recording'::"text", 'start_broadcast'::"text", 'stop_broadcast'::"text", 'finalize_local_segments'::"text", 'resume_pending_uploads'::"text", 'verify_integrity'::"text", 'assemble_manifest'::"text", 'seal_session_record'::"text", 'promote_co_host'::"text", 'enter_engine_stewardship'::"text"])))),
    CONSTRAINT "bellows_session_checkpoints_event_count_check" CHECK (("event_count" >= 0)),
    CONSTRAINT "bellows_session_checkpoints_follow_up_action_pair_check" CHECK (((("follow_up_action_source" IS NULL) AND ("follow_up_action_type" IS NULL)) OR (("follow_up_action_source" IS NOT NULL) AND ("follow_up_action_type" IS NOT NULL) AND ("length"("btrim"("follow_up_action_type")) > 0)))),
    CONSTRAINT "bellows_session_checkpoints_follow_up_action_source_check" CHECK ((("follow_up_action_source" IS NULL) OR ("follow_up_action_source" = ANY (ARRAY['host'::"text", 'co_host'::"text", 'participant'::"text", 'capture'::"text", 'connectivity'::"text", 'broadcast'::"text", 'upload'::"text", 'recovery'::"text", 'engine'::"text"])))),
    CONSTRAINT "bellows_session_checkpoints_integrity_flags_check" CHECK (("integrity_flags" <@ ARRAY['missing_track'::"text", 'degraded_quality'::"text", 'participant_dropout'::"text", 'upload_interrupted'::"text", 'resync_required'::"text", 'corrupted_capture'::"text"])),
    CONSTRAINT "bellows_session_checkpoints_kind_check" CHECK (("checkpoint_kind" = ANY (ARRAY['session_created'::"text", 'draft_updated'::"text", 'runtime_transition'::"text", 'effect_checkpoint'::"text", 'recovery_checkpoint'::"text", 'integrity_checkpoint'::"text", 'seal_checkpoint'::"text", 'archive_checkpoint'::"text"]))),
    CONSTRAINT "bellows_session_checkpoints_lifecycle_state_check" CHECK (("lifecycle_state" = ANY (ARRAY['idle'::"text", 'configuring'::"text", 'linking_accounts'::"text", 'inviting'::"text", 'waiting_for_participants'::"text", 'preflight_ready'::"text", 'preflight_checks'::"text", 'ready_to_start'::"text", 'countdown'::"text", 'sync_initializing'::"text", 'recording_active'::"text", 'recording_degraded'::"text", 'recording_offline_local'::"text", 'recording_rejoining'::"text", 'finalizing_local'::"text", 'uploading'::"text", 'upload_degraded'::"text", 'upload_paused'::"text", 'upload_resuming'::"text", 'upload_complete_pending_verification'::"text", 'verifying_integrity'::"text", 'assembling_manifest'::"text", 'sealing_session'::"text", 'sealed'::"text", 'incomplete_capture'::"text", 'failed_capture'::"text", 'archived'::"text"]))),
    CONSTRAINT "bellows_session_checkpoints_outcome_check" CHECK ((("outcome" IS NULL) OR ("outcome" = ANY (ARRAY['sealed'::"text", 'incomplete_capture'::"text", 'failed_capture'::"text", 'archived'::"text"])))),
    CONSTRAINT "bellows_session_checkpoints_recording_state_check" CHECK (("recording_state" = ANY (ARRAY['idle'::"text", 'countdown'::"text", 'sync_initializing'::"text", 'active'::"text", 'degraded'::"text", 'offline_local'::"text", 'rejoining'::"text", 'stopping'::"text", 'stopped'::"text"]))),
    CONSTRAINT "bellows_session_checkpoints_seal_state_check" CHECK (("seal_state" = ANY (ARRAY['not_started'::"text", 'verifying_integrity'::"text", 'assembling_manifest'::"text", 'sealing_session'::"text", 'sealed'::"text"]))),
    CONSTRAINT "bellows_session_checkpoints_sequence_check" CHECK (("sequence_no" > 0)),
    CONSTRAINT "bellows_session_checkpoints_session_snapshot_check" CHECK (("jsonb_typeof"("session_snapshot") = 'object'::"text")),
    CONSTRAINT "bellows_session_checkpoints_snapshot_schema_version_check" CHECK (("snapshot_schema_version" > 0)),
    CONSTRAINT "bellows_session_checkpoints_trigger_action_source_check" CHECK (("trigger_action_source" = ANY (ARRAY['host'::"text", 'co_host'::"text", 'participant'::"text", 'capture'::"text", 'connectivity'::"text", 'broadcast'::"text", 'upload'::"text", 'recovery'::"text", 'engine'::"text"]))),
    CONSTRAINT "bellows_session_checkpoints_trigger_action_type_check" CHECK (("length"("btrim"("trigger_action_type")) > 0)),
    CONSTRAINT "bellows_session_checkpoints_upload_state_check" CHECK (("upload_state" = ANY (ARRAY['not_started'::"text", 'finalizing_local'::"text", 'uploading'::"text", 'degraded'::"text", 'paused'::"text", 'resuming'::"text", 'complete_pending_verification'::"text"])))
);


ALTER TABLE "tongs"."bellows_session_checkpoints" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."append_bellows_session_checkpoint"("p_session_id" "text", "p_checkpoint_kind" "text", "p_trigger_action_source" "text", "p_trigger_action_type" "text", "p_actor_type" "text" DEFAULT NULL::"text", "p_actor_id" "text" DEFAULT NULL::"text", "p_effect_type" "text" DEFAULT NULL::"text", "p_follow_up_action_source" "text" DEFAULT NULL::"text", "p_follow_up_action_type" "text" DEFAULT NULL::"text", "p_offset_ms" bigint DEFAULT NULL::bigint, "p_occurred_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_lifecycle_state" "text" DEFAULT NULL::"text", "p_recording_state" "text" DEFAULT NULL::"text", "p_broadcast_state" "text" DEFAULT NULL::"text", "p_upload_state" "text" DEFAULT NULL::"text", "p_seal_state" "text" DEFAULT NULL::"text", "p_outcome" "text" DEFAULT NULL::"text", "p_acting_authority_state" "text" DEFAULT NULL::"text", "p_host_participant_id" "text" DEFAULT NULL::"text", "p_acting_host_participant_id" "text" DEFAULT NULL::"text", "p_co_host_participant_ids" "text"[] DEFAULT NULL::"text"[], "p_integrity_flags" "text"[] DEFAULT NULL::"text"[], "p_event_count" integer DEFAULT 0, "p_session_snapshot" "jsonb" DEFAULT NULL::"jsonb", "p_delta" "jsonb" DEFAULT NULL::"jsonb", "p_started_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_ended_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_sealed_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_archived_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_snapshot_schema_version" integer DEFAULT 1) RETURNS "tongs"."bellows_session_checkpoints"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare
  v_session tongs.bellows_sessions;
  v_next_sequence bigint;
  v_checkpoint tongs.bellows_session_checkpoints;
begin
  if p_session_snapshot is null or jsonb_typeof(p_session_snapshot) <> 'object' then
    raise exception 'session_snapshot must be a JSON object'
      using errcode = '22023';
  end if;

  select *
  into v_session
  from tongs.bellows_sessions
  where id = p_session_id
  for update;

  if not found then
    raise exception 'bellows_session_not_found'
      using errcode = 'P0002';
  end if;

  if coalesce(auth.role(), '') <> 'service_role' then
    perform tongs.assert_workspace_role(v_session.workspace_id, 'editor');
  end if;

  select coalesce(max(sequence_no), 0) + 1
  into v_next_sequence
  from tongs.bellows_session_checkpoints
  where session_id = p_session_id;

  insert into tongs.bellows_session_checkpoints (
    session_id,
    sequence_no,
    checkpoint_kind,
    trigger_action_source,
    trigger_action_type,
    actor_type,
    actor_id,
    effect_type,
    follow_up_action_source,
    follow_up_action_type,
    offset_ms,
    occurred_at,
    lifecycle_state,
    recording_state,
    broadcast_state,
    upload_state,
    seal_state,
    outcome,
    acting_authority_state,
    host_participant_id,
    acting_host_participant_id,
    co_host_participant_ids,
    integrity_flags,
    event_count,
    snapshot_schema_version,
    session_snapshot,
    delta
  )
  values (
    p_session_id,
    v_next_sequence,
    p_checkpoint_kind,
    p_trigger_action_source,
    p_trigger_action_type,
    p_actor_type,
    nullif(btrim(coalesce(p_actor_id, '')), ''),
    p_effect_type,
    p_follow_up_action_source,
    p_follow_up_action_type,
    p_offset_ms,
    p_occurred_at,
    coalesce(p_lifecycle_state, v_session.lifecycle_state),
    coalesce(p_recording_state, v_session.recording_state),
    coalesce(p_broadcast_state, v_session.broadcast_state),
    coalesce(p_upload_state, v_session.upload_state),
    coalesce(p_seal_state, v_session.seal_state),
    coalesce(p_outcome, v_session.outcome),
    coalesce(p_acting_authority_state, v_session.acting_authority_state),
    coalesce(nullif(btrim(coalesce(p_host_participant_id, '')), ''), v_session.host_participant_id),
    coalesce(nullif(btrim(coalesce(p_acting_host_participant_id, '')), ''), v_session.acting_host_participant_id),
    coalesce(p_co_host_participant_ids, v_session.co_host_participant_ids),
    coalesce(p_integrity_flags, v_session.integrity_flags),
    coalesce(p_event_count, 0),
    p_snapshot_schema_version,
    p_session_snapshot,
    p_delta
  )
  returning *
  into v_checkpoint;

  update tongs.bellows_sessions
  set
    latest_checkpoint_id = v_checkpoint.id,
    acting_authority_state = v_checkpoint.acting_authority_state,
    host_participant_id = v_checkpoint.host_participant_id,
    acting_host_participant_id = v_checkpoint.acting_host_participant_id,
    co_host_participant_ids = v_checkpoint.co_host_participant_ids,
    lifecycle_state = v_checkpoint.lifecycle_state,
    recording_state = v_checkpoint.recording_state,
    broadcast_state = v_checkpoint.broadcast_state,
    upload_state = v_checkpoint.upload_state,
    seal_state = v_checkpoint.seal_state,
    outcome = v_checkpoint.outcome,
    integrity_flags = v_checkpoint.integrity_flags,
    snapshot_schema_version = v_checkpoint.snapshot_schema_version,
    started_at = coalesce(tongs.bellows_sessions.started_at, p_started_at),
    ended_at = coalesce(tongs.bellows_sessions.ended_at, p_ended_at),
    sealed_at = coalesce(tongs.bellows_sessions.sealed_at, p_sealed_at),
    archived_at = coalesce(tongs.bellows_sessions.archived_at, p_archived_at)
  where id = p_session_id;

  return v_checkpoint;
end;
$$;


ALTER FUNCTION "tongs"."append_bellows_session_checkpoint"("p_session_id" "text", "p_checkpoint_kind" "text", "p_trigger_action_source" "text", "p_trigger_action_type" "text", "p_actor_type" "text", "p_actor_id" "text", "p_effect_type" "text", "p_follow_up_action_source" "text", "p_follow_up_action_type" "text", "p_offset_ms" bigint, "p_occurred_at" timestamp with time zone, "p_lifecycle_state" "text", "p_recording_state" "text", "p_broadcast_state" "text", "p_upload_state" "text", "p_seal_state" "text", "p_outcome" "text", "p_acting_authority_state" "text", "p_host_participant_id" "text", "p_acting_host_participant_id" "text", "p_co_host_participant_ids" "text"[], "p_integrity_flags" "text"[], "p_event_count" integer, "p_session_snapshot" "jsonb", "p_delta" "jsonb", "p_started_at" timestamp with time zone, "p_ended_at" timestamp with time zone, "p_sealed_at" timestamp with time zone, "p_archived_at" timestamp with time zone, "p_snapshot_schema_version" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."append_brand_profile_revision"("p_workspace_id" "uuid", "p_profile_id" "uuid", "p_rules" "jsonb", "p_operation_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare v_user uuid:=auth.uid();v_revision int;v_id uuid;v_hash text;v_asset_ids uuid[];v_errors text[];v_validation jsonb;
begin if v_user is null then raise exception 'Not authenticated' using errcode='42501';end if;perform tongs.assert_workspace_role(p_workspace_id,'editor');perform pg_advisory_xact_lock(hashtextextended(p_workspace_id::text||':'||p_profile_id::text,0));
 if not exists(select 1 from tongs.brand_profiles where id=p_profile_id and workspace_id=p_workspace_id and archived_at is null)then raise exception 'profile unavailable' using errcode='22023';end if;
 v_errors:=tongs.brand_rule_errors(p_rules);select coalesce(array_agg(value::uuid),'{}')into v_asset_ids from jsonb_each_text(coalesce(p_rules->'asset_revision_ids','{}'::jsonb));
 if exists(select 1 from unnest(v_asset_ids)x left join tongs.brand_asset_revisions ar on ar.id=x where ar.id is null or ar.workspace_id<>p_workspace_id or ar.state<>'ready')then v_errors:=array_append(v_errors,'All referenced asset revisions must be ready and workspace-owned.');end if;
 v_hash:=tongs.brand_rules_hash(p_rules);select id,revision into v_id,v_revision from tongs.brand_profile_revisions where profile_id=p_profile_id and content_hash=v_hash;if v_id is not null then return jsonb_build_object('disposition','existing_revision','profile_revision_id',v_id,'revision',v_revision);end if;
 select coalesce(max(revision),0)+1 into v_revision from tongs.brand_profile_revisions where profile_id=p_profile_id;v_id:=gen_random_uuid();v_validation:=jsonb_build_object('valid',cardinality(v_errors)=0,'bindable',cardinality(v_errors)=0,'errors',to_jsonb(v_errors),'asset_revision_ids',to_jsonb(v_asset_ids));
 insert into tongs.brand_profile_revisions(id,workspace_id,profile_id,revision,rules_json,content_hash,state,eligible_for_new_use,validation_json,verified_at,created_by)values(v_id,p_workspace_id,p_profile_id,v_revision,jsonb_strip_nulls(p_rules),v_hash,case when cardinality(v_errors)=0 then 'committed' else 'ineligible' end,cardinality(v_errors)=0,v_validation,now(),v_user);
 return jsonb_build_object('disposition','created_revision','profile_revision_id',v_id,'revision',v_revision,'bindable',cardinality(v_errors)=0,'errors',to_jsonb(v_errors));end $$;


ALTER FUNCTION "tongs"."append_brand_profile_revision"("p_workspace_id" "uuid", "p_profile_id" "uuid", "p_rules" "jsonb", "p_operation_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."append_funding_failure_class_correction"("p_correction_id" "uuid", "p_reservation_id" "uuid", "p_original_event_id" "uuid", "p_correction_key" "text", "p_corrected_failure_class" "text", "p_correction_reason" "text", "p_operator_user_id" "uuid", "p_evidence_json" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare v_original tongs.funding_reservation_events%rowtype;
  v_existing tongs.funding_failure_class_corrections%rowtype;
begin
  perform tongs._require_pricing_service_role();
  if p_correction_id is null or p_reservation_id is null or p_original_event_id is null
     or length(btrim(coalesce(p_correction_key,'')))<8
     or p_corrected_failure_class not in ('forge_validation_failure','persistence_failure','forge_failure','provider_failure')
     or length(btrim(coalesce(p_correction_reason,'')))<8
     or p_operator_user_id is null or not tongs.is_platform_operator(p_operator_user_id)
     or jsonb_typeof(coalesce(p_evidence_json,'null'::jsonb))<>'object' then
    raise exception 'invalid failure attribution correction' using errcode='22023';
  end if;
  select * into v_original from tongs.funding_reservation_events
    where id=p_original_event_id and reservation_id=p_reservation_id;
  if not found or v_original.event_type<>'provider_failure_recorded' then
    raise exception 'original failure event not found' using errcode='P0002';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('failure-correction:'||p_original_event_id::text,0));
  select * into v_existing from tongs.funding_failure_class_corrections where original_event_id=p_original_event_id;
  if found then
    if v_existing.correction_key<>btrim(p_correction_key)
       or v_existing.corrected_failure_class<>p_corrected_failure_class then
      raise exception 'failure correction replay conflict' using errcode='23505';
    end if;
    return jsonb_build_object('correction_id',v_existing.id,'replay',true,
      'original_failure_class',v_existing.original_failure_class,
      'effective_failure_class',v_existing.corrected_failure_class);
  end if;
  insert into tongs.funding_failure_class_corrections(
    id,reservation_id,original_event_id,correction_key,original_failure_class,
    corrected_failure_class,correction_reason,evidence_json,corrected_by
  ) values (
    p_correction_id,p_reservation_id,p_original_event_id,btrim(p_correction_key),
    coalesce(v_original.failure_class,'unknown'),p_corrected_failure_class,
    btrim(p_correction_reason),coalesce(p_evidence_json,'{}'::jsonb),p_operator_user_id
  ) returning * into v_existing;
  return jsonb_build_object('correction_id',v_existing.id,'replay',false,
    'original_failure_class',v_existing.original_failure_class,
    'effective_failure_class',v_existing.corrected_failure_class,
    'original_event_preserved',true,'supplier_expense_mutated',false);
end $$;


ALTER FUNCTION "tongs"."append_funding_failure_class_correction"("p_correction_id" "uuid", "p_reservation_id" "uuid", "p_original_event_id" "uuid", "p_correction_key" "text", "p_corrected_failure_class" "text", "p_correction_reason" "text", "p_operator_user_id" "uuid", "p_evidence_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."append_my_hearth_conversation_messages"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_generation" bigint, "p_messages" "jsonb", "p_import_completeness" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare
  v_thread tongs.hearth_conversation_threads%rowtype;
  v_item jsonb;
  v_key text;
  v_role text;
  v_content text;
  v_inserted integer := 0;
begin
  perform tongs.assert_workspace_role(p_workspace_id, 'editor');
  if not exists(select 1 from tongs.episodes e where e.id=p_workpiece_id and e.workspace_id=p_workspace_id) then
    raise exception 'workpiece does not belong to workspace' using errcode='22023';
  end if;
  if jsonb_typeof(coalesce(p_messages,'[]'::jsonb)) <> 'array' then
    raise exception 'messages must be an array' using errcode='22023';
  end if;
  if p_import_completeness is not null and p_import_completeness not in ('legacy_completeness_unknown','known_truncated') then
    raise exception 'invalid import completeness' using errcode='22023';
  end if;

  insert into tongs.hearth_conversation_threads(workspace_id,workpiece_id,generation,completeness)
    values(p_workspace_id,p_workpiece_id,1,coalesce(p_import_completeness,'complete'))
    on conflict(workpiece_id) do nothing;
  select * into v_thread from tongs.hearth_conversation_threads t
    where t.workspace_id=p_workspace_id and t.workpiece_id=p_workpiece_id for update;
  if not found then raise exception 'conversation thread workspace mismatch' using errcode='42501'; end if;
  if v_thread.generation<>p_generation then
    return jsonb_build_object('status','generation_conflict','generation',v_thread.generation,'inserted',0);
  end if;

  for v_item in select value from jsonb_array_elements(coalesce(p_messages,'[]'::jsonb)) loop
    v_key:=nullif(btrim(v_item->>'client_message_key'),'');
    v_role:=v_item->>'role';
    v_content:=v_item->>'content';
    if v_key is null or length(v_key)>200 or v_role not in ('user','assistant') or nullif(v_content,'') is null then
      raise exception 'invalid conversation message' using errcode='22023';
    end if;
    if not exists(select 1 from tongs.hearth_conversation_messages m where m.workpiece_id=p_workpiece_id and m.generation=v_thread.generation and m.client_message_key=v_key) then
      insert into tongs.hearth_conversation_messages(workspace_id,workpiece_id,generation,sequence,client_message_key,role,content)
        values(p_workspace_id,p_workpiece_id,v_thread.generation,v_thread.next_sequence,v_key,v_role,v_content);
      v_thread.next_sequence:=v_thread.next_sequence+1;
      v_inserted:=v_inserted+1;
    end if;
  end loop;
  update tongs.hearth_conversation_threads set next_sequence=v_thread.next_sequence,updated_at=now() where workpiece_id=p_workpiece_id;
  return jsonb_build_object('status','committed','generation',v_thread.generation,'inserted',v_inserted);
end $$;


ALTER FUNCTION "tongs"."append_my_hearth_conversation_messages"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_generation" bigint, "p_messages" "jsonb", "p_import_completeness" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."append_owner_cost_attempt_event"("p_attempt_event_id" "uuid", "p_attempt_id" "uuid", "p_event_sequence" integer, "p_lifecycle_state" "text", "p_provider_reference_id" "text", "p_normalized_usage_evidence" "jsonb", "p_private_provider_evidence" "jsonb", "p_occurred_at" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_state text := lower(btrim(coalesce(p_lifecycle_state, '')));
  v_previous text;
  v_existing tongs.owner_cost_attempt_events%rowtype;
begin
  perform tongs._require_accounting_service_role();
  if p_attempt_event_id is null or p_attempt_id is null or p_event_sequence <= 1
     or v_state not in ('submitted', 'response_captured', 'succeeded', 'definitively_rejected', 'failed', 'submission_unknown')
     or p_occurred_at is null
     or jsonb_typeof(coalesce(p_normalized_usage_evidence, '{}'::jsonb)) <> 'object'
     or jsonb_typeof(coalesce(p_private_provider_evidence, '{}'::jsonb)) <> 'object' then
    raise exception 'invalid owner-cost attempt event' using errcode = '22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('owner-cost-attempt-events:' || p_attempt_id::text, 0));
  select * into v_existing from tongs.owner_cost_attempt_events e
    where e.attempt_event_id = p_attempt_event_id
       or (e.attempt_id = p_attempt_id and e.event_sequence = p_event_sequence)
    limit 1;
  if found then
    if v_existing.attempt_event_id <> p_attempt_event_id or v_existing.lifecycle_state <> v_state
       or v_existing.provider_reference_id is distinct from nullif(btrim(coalesce(p_provider_reference_id, '')), '')
       or v_existing.normalized_usage_evidence <> coalesce(p_normalized_usage_evidence, '{}'::jsonb)
       or v_existing.private_provider_evidence <> coalesce(p_private_provider_evidence, '{}'::jsonb)
       or v_existing.occurred_at <> coalesce(p_occurred_at, v_existing.occurred_at) then
      raise exception 'owner-cost attempt event replay conflict' using errcode = '23505';
    end if;
    return jsonb_build_object('attempt_event_id', v_existing.attempt_event_id, 'replay', true, 'provider_submission_created', false);
  end if;
  select e.lifecycle_state into v_previous from tongs.owner_cost_attempt_events e
    where e.attempt_id = p_attempt_id order by e.event_sequence desc limit 1;
  if not found then raise exception 'owner-cost attempt not found' using errcode = '23503'; end if;
  if p_event_sequence <> (select max(e.event_sequence) + 1 from tongs.owner_cost_attempt_events e where e.attempt_id = p_attempt_id) then
    raise exception 'owner-cost attempt event sequence gap' using errcode = '23514';
  end if;
  if not (
    (v_previous = 'authorized' and v_state in ('submitted', 'failed')) or
    (v_previous = 'submitted' and v_state in ('response_captured', 'succeeded', 'definitively_rejected', 'failed', 'submission_unknown')) or
    (v_previous = 'submission_unknown' and v_state in ('response_captured', 'succeeded', 'failed')) or
    (v_previous = 'response_captured' and v_state in ('succeeded', 'failed'))
  ) then raise exception 'invalid owner-cost attempt lifecycle transition' using errcode = '23514'; end if;
  insert into tongs.owner_cost_attempt_events(
    attempt_event_id, attempt_id, event_sequence, lifecycle_state, provider_reference_id,
    normalized_usage_evidence, private_provider_evidence, occurred_at
  ) values (
    p_attempt_event_id, p_attempt_id, p_event_sequence, v_state,
    nullif(btrim(coalesce(p_provider_reference_id, '')), ''),
    coalesce(p_normalized_usage_evidence, '{}'::jsonb),
    coalesce(p_private_provider_evidence, '{}'::jsonb), p_occurred_at
  );
  return jsonb_build_object(
    'attempt_event_id', p_attempt_event_id, 'replay', false,
    'provider_submission_created', v_state = 'submitted'
  );
end;
$$;


ALTER FUNCTION "tongs"."append_owner_cost_attempt_event"("p_attempt_event_id" "uuid", "p_attempt_id" "uuid", "p_event_sequence" integer, "p_lifecycle_state" "text", "p_provider_reference_id" "text", "p_normalized_usage_evidence" "jsonb", "p_private_provider_evidence" "jsonb", "p_occurred_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."append_reference_visual_opportunity"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_expected_plan_revision_id" "uuid", "p_expected_plan_revision" bigint, "p_script_approval_id" "uuid", "p_script_approval_revision" bigint, "p_script_content_hash" "text", "p_visual_subtype" "text", "p_context_before" "text", "p_context_focus" "text", "p_context_after" "text", "p_citation_anchor_json" "jsonb", "p_editorial_reason" "text", "p_desired_material" "text", "p_search_terms" "jsonb", "p_placement_hint" "text", "p_duration_target_ms" bigint, "p_creator_direction" "text", "p_derived_from_opportunity_revision_id" "uuid", "p_creator_request_json" "jsonb", "p_operation_id" "text", "p_operation_fingerprint" "text", "p_actor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $_$
declare
  receipt tongs.reference_visual_operation_receipts%rowtype;
  seq tongs.reference_visual_plan_sequences%rowtype;
  current_plan tongs.reference_visual_plan_revisions%rowtype;
  approval tongs.script_approval_revisions%rowtype;
  next_plan tongs.reference_visual_plan_revisions%rowtype;
  opportunity tongs.reference_visual_opportunity_revisions%rowtype;
  member tongs.reference_visual_plan_membership%rowtype;
  next_ordinal integer;
  opportunity_id_value uuid:=gen_random_uuid();
  plan_content_hash text;
  plan_immutable_hash text;
  opportunity_content_hash text;
  opportunity_immutable_hash text;
  result jsonb;
begin
  if not tongs.has_workspace_role(p_workspace_id,'editor') or auth.uid() is distinct from p_actor_id then
    raise exception 'workspace editor authority required' using errcode='42501';
  end if;
  if p_operation_fingerprint !~ '^[0-9a-f]{64}$' then
    return jsonb_build_object('disposition','invalid_operation_fingerprint');
  end if;
  if p_visual_subtype not in ('archival_still','archival_sequence','timeline','document_excerpt','quote_card','stat_card','comparison','chart')
    or btrim(coalesce(p_context_focus,''))=''
    or btrim(coalesce(p_editorial_reason,''))=''
    or btrim(coalesce(p_desired_material,''))=''
    or btrim(coalesce(p_placement_hint,''))=''
    or p_duration_target_ms<=0
    or jsonb_typeof(coalesce(p_search_terms,'[]'::jsonb))<>'array'
    or jsonb_typeof(coalesce(p_citation_anchor_json,'{}'::jsonb))<>'object'
    or jsonb_typeof(coalesce(p_creator_request_json,'{}'::jsonb))<>'object' then
    return jsonb_build_object('disposition','invalid_creator_opportunity');
  end if;

  perform pg_advisory_xact_lock(hashtextextended(p_operation_id,0));
  select * into receipt from tongs.reference_visual_operation_receipts where operation_id=p_operation_id;
  if found then
    if receipt.operation_fingerprint<>p_operation_fingerprint then
      return jsonb_build_object('disposition','operation_identity_conflict');
    end if;
    return receipt.receipt_json;
  end if;

  select * into seq from tongs.reference_visual_plan_sequences
    where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id for update;
  if not found or seq.current_plan_revision_id is distinct from p_expected_plan_revision_id
    or seq.current_plan_revision<>p_expected_plan_revision then
    return jsonb_build_object('disposition','plan_revision_conflict',
      'current_revision_id',seq.current_plan_revision_id,'current_revision',coalesce(seq.current_plan_revision,0));
  end if;
  select * into current_plan from tongs.reference_visual_plan_revisions where id=seq.current_plan_revision_id;
  select * into approval from tongs.script_approval_revisions
    where id=p_script_approval_id and workspace_id=p_workspace_id and workpiece_id=p_workpiece_id;
  if not found or approval.approval_revision<>p_script_approval_revision
    or approval.script_content_hash<>p_script_content_hash
    or current_plan.script_approval_id<>approval.id
    or current_plan.script_approval_revision<>approval.approval_revision
    or current_plan.script_content_hash<>approval.script_content_hash
    or not exists (
      select 1 from tongs.workpiece_script_approval_sequences s
      where s.workspace_id=p_workspace_id and s.workpiece_id=p_workpiece_id and s.current_approval_id=approval.id
    ) then
    return jsonb_build_object('disposition','script_revision_conflict');
  end if;
  if strpos(approval.script_text,p_context_focus)=0 then
    return jsonb_build_object('disposition','script_anchor_unresolved');
  end if;
  if p_derived_from_opportunity_revision_id is not null then
    perform 1 from tongs.reference_visual_opportunity_revisions
      where id=p_derived_from_opportunity_revision_id
        and workspace_id=p_workspace_id and workpiece_id=p_workpiece_id
        and script_approval_id=approval.id and script_approval_revision=approval.approval_revision;
    if not found then return jsonb_build_object('disposition','historical_opportunity_not_found'); end if;
  end if;

  opportunity_content_hash:=encode(extensions.digest(convert_to(jsonb_strip_nulls(jsonb_build_object(
    'origin','creator_added','derived_from',p_derived_from_opportunity_revision_id,
    'script_approval_id',approval.id,'script_approval_revision',approval.approval_revision,
    'script_content_hash',approval.script_content_hash,'visual_subtype',p_visual_subtype,
    'context_before',coalesce(p_context_before,''),'context_focus',p_context_focus,
    'context_after',coalesce(p_context_after,''),'citation_anchor',coalesce(p_citation_anchor_json,'{}'::jsonb),
    'editorial_reason',p_editorial_reason,'desired_material',p_desired_material,
    'search_terms',coalesce(p_search_terms,'[]'::jsonb),'placement_hint',p_placement_hint,
    'duration_target_ms',p_duration_target_ms,'creator_direction',p_creator_direction,
    'creator_request',coalesce(p_creator_request_json,'{}'::jsonb)
  ))::text,'UTF8'),'sha256'),'hex');
  plan_content_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'previous_plan_content_hash',current_plan.content_hash,
    'creator_added_opportunity_content_hash',opportunity_content_hash
  )::text,'UTF8'),'sha256'),'hex');
  plan_immutable_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'content_hash',plan_content_hash,'revision',current_plan.revision+1,'previous_revision_id',current_plan.id
  )::text,'UTF8'),'sha256'),'hex');

  insert into tongs.reference_visual_plan_revisions(
    workspace_id,workpiece_id,revision,previous_revision_id,previous_revision,
    script_approval_id,script_approval_revision,script_content_hash,contract_version,
    content_hash,immutable_revision_hash,created_by
  ) values(
    p_workspace_id,p_workpiece_id,current_plan.revision+1,current_plan.id,current_plan.revision,
    approval.id,approval.approval_revision,approval.script_content_hash,'forge.reference-visual.creator-amendment.v1',
    plan_content_hash,plan_immutable_hash,p_actor_id
  ) returning * into next_plan;

  opportunity_immutable_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'content_hash',opportunity_content_hash,'opportunity_id',opportunity_id_value,'revision',1,
    'source_plan_revision_id',next_plan.id
  )::text,'UTF8'),'sha256'),'hex');
  insert into tongs.reference_visual_opportunity_revisions(
    opportunity_id,workspace_id,workpiece_id,revision,source_plan_revision_id,source_plan_revision,
    script_approval_id,script_approval_revision,source_status,visual_subtype,
    context_before,context_focus,context_after,citation_anchor_json,document_locator_json,media_range_json,
    editorial_reason,desired_material,search_terms,placement_hint,duration_target_ms,creator_direction,
    content_hash,immutable_revision_hash,created_by,opportunity_origin,
    derived_from_opportunity_revision_id,creator_request_json
  ) values(
    opportunity_id_value,p_workspace_id,p_workpiece_id,1,next_plan.id,next_plan.revision,
    approval.id,approval.approval_revision,'unresolved',p_visual_subtype,
    coalesce(p_context_before,''),p_context_focus,coalesce(p_context_after,''),coalesce(p_citation_anchor_json,'{}'::jsonb),'{}'::jsonb,'{}'::jsonb,
    p_editorial_reason,p_desired_material,coalesce(p_search_terms,'[]'::jsonb),p_placement_hint,p_duration_target_ms,p_creator_direction,
    opportunity_content_hash,opportunity_immutable_hash,p_actor_id,'creator_added',
    p_derived_from_opportunity_revision_id,coalesce(p_creator_request_json,'{}'::jsonb)
  ) returning * into opportunity;

  next_ordinal:=0;
  for member in select * from tongs.reference_visual_plan_membership
    where plan_revision_id=current_plan.id order by ordinal loop
    insert into tongs.reference_visual_plan_membership
      values(next_plan.id,p_workspace_id,p_workpiece_id,next_plan.revision,next_ordinal,
        member.opportunity_id,member.opportunity_revision_id,member.opportunity_revision);
    next_ordinal:=next_ordinal+1;
  end loop;
  insert into tongs.reference_visual_plan_membership
    values(next_plan.id,p_workspace_id,p_workpiece_id,next_plan.revision,next_ordinal,
      opportunity.opportunity_id,opportunity.id,opportunity.revision);
  update tongs.reference_visual_plan_sequences set
    current_plan_revision_id=next_plan.id,current_plan_revision=next_plan.revision,updated_at=now()
    where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id;

  result:=jsonb_build_object(
    'disposition','committed','operation_id',p_operation_id,'operation_fingerprint',p_operation_fingerprint,
    'plan_revision',to_jsonb(next_plan),'opportunity_revision',to_jsonb(opportunity),
    'preserved_opportunity_count',next_ordinal,'provider_request_performed',false
  );
  insert into tongs.reference_visual_operation_receipts(
    operation_id,operation_fingerprint,operation_type,workspace_id,workpiece_id,state,result_revision_id,receipt_json,created_by,created_at
  ) values(
    p_operation_id,p_operation_fingerprint,'creator_amendment',p_workspace_id,p_workpiece_id,
    'committed',opportunity.id,result,p_actor_id,now()
  );
  return result;
end$_$;


ALTER FUNCTION "tongs"."append_reference_visual_opportunity"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_expected_plan_revision_id" "uuid", "p_expected_plan_revision" bigint, "p_script_approval_id" "uuid", "p_script_approval_revision" bigint, "p_script_content_hash" "text", "p_visual_subtype" "text", "p_context_before" "text", "p_context_focus" "text", "p_context_after" "text", "p_citation_anchor_json" "jsonb", "p_editorial_reason" "text", "p_desired_material" "text", "p_search_terms" "jsonb", "p_placement_hint" "text", "p_duration_target_ms" bigint, "p_creator_direction" "text", "p_derived_from_opportunity_revision_id" "uuid", "p_creator_request_json" "jsonb", "p_operation_id" "text", "p_operation_fingerprint" "text", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."append_thumbnail_launch_experiment"("p_workspace_id" "uuid", "p_publication_id" "text", "p_experiment_identity" "text", "p_launch_snapshot_hashes" "text"[], "p_hypothesis" "text", "p_primary_metric" "text", "p_guardrail_metrics" "text"[], "p_window_kind" "text", "p_stopping_conditions" "text"[], "p_state" "text", "p_experiment_json" "jsonb", "p_content_hash" "text") RETURNS TABLE("experiment_id" "uuid", "revision" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare v_user uuid:=auth.uid(); v_revision int; v_id uuid;
begin if v_user is null then raise exception 'Not authenticated' using errcode='42501'; end if; perform tongs.assert_workspace_role(p_workspace_id,'editor');
  perform pg_advisory_xact_lock(hashtextextended(p_workspace_id::text||':'||p_experiment_identity,0));
  select coalesce(max(revision),0)+1 into v_revision from tongs.thumbnail_launch_experiments where workspace_id=p_workspace_id and experiment_identity=p_experiment_identity;
  insert into tongs.thumbnail_launch_experiments(workspace_id,publication_id,experiment_identity,revision,launch_snapshot_hashes,hypothesis,primary_metric,guardrail_metrics,window_kind,stopping_conditions,state,experiment_json,content_hash,created_by)
  values(p_workspace_id,p_publication_id,p_experiment_identity,v_revision,p_launch_snapshot_hashes,p_hypothesis,p_primary_metric,p_guardrail_metrics,p_window_kind,p_stopping_conditions,p_state,p_experiment_json,p_content_hash,v_user) returning id into v_id;
  return query select v_id,v_revision; end $$;


ALTER FUNCTION "tongs"."append_thumbnail_launch_experiment"("p_workspace_id" "uuid", "p_publication_id" "text", "p_experiment_identity" "text", "p_launch_snapshot_hashes" "text"[], "p_hypothesis" "text", "p_primary_metric" "text", "p_guardrail_metrics" "text"[], "p_window_kind" "text", "p_stopping_conditions" "text"[], "p_state" "text", "p_experiment_json" "jsonb", "p_content_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."append_thumbnail_launch_fact"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_launch_identity" "text", "p_launch_snapshot_hash" "text", "p_published_at" timestamp with time zone, "p_destination" "text", "p_fact_json" "jsonb") RETURNS TABLE("fact_id" "uuid", "disposition" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare v_user uuid := auth.uid(); v_id uuid;
begin
  if v_user is null then raise exception 'Not authenticated' using errcode = '42501'; end if;
  perform tongs.assert_workspace_role(p_workspace_id, 'editor');
  if not exists (select 1 from tongs.episodes e where e.id = p_workpiece_id and e.workspace_id = p_workspace_id) then
    raise exception 'workpiece does not belong to workspace' using errcode = '22023';
  end if;
  select f.id into v_id from tongs.thumbnail_launch_facts f
    where f.workspace_id = p_workspace_id and f.launch_identity = btrim(p_launch_identity);
  if v_id is not null then return query select v_id, 'existing'::text; return; end if;
  insert into tongs.thumbnail_launch_facts
    (workspace_id, workpiece_id, launch_identity, launch_snapshot_hash, published_at, destination, fact_json, recorded_by)
  values (p_workspace_id, p_workpiece_id, btrim(p_launch_identity), p_launch_snapshot_hash,
    p_published_at, nullif(btrim(coalesce(p_destination, '')), ''), jsonb_strip_nulls(p_fact_json), v_user)
  returning id into v_id;
  return query select v_id, 'created'::text;
end;
$$;


ALTER FUNCTION "tongs"."append_thumbnail_launch_fact"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_launch_identity" "text", "p_launch_snapshot_hash" "text", "p_published_at" timestamp with time zone, "p_destination" "text", "p_fact_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."append_thumbnail_launch_interval"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_publication_id" "text", "p_launch_identity" "text", "p_launch_snapshot_hash" "text", "p_platform" "text", "p_state" "text", "p_started_at" timestamp with time zone, "p_attribution_json" "jsonb", "p_content_hash" "text") RETURNS TABLE("interval_id" "uuid", "disposition" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare v_user uuid:=auth.uid(); v_existing uuid; v_prior uuid;
begin
  if v_user is null then raise exception 'Not authenticated' using errcode='42501'; end if;
  perform tongs.assert_workspace_role(p_workspace_id,'editor');
  if not exists(select 1 from tongs.episodes where id=p_workpiece_id and workspace_id=p_workspace_id) then raise exception 'workpiece does not belong to workspace' using errcode='22023'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_workspace_id::text||':'||btrim(p_publication_id),0));
  select id into v_existing from tongs.thumbnail_launch_intervals where workspace_id=p_workspace_id and publication_id=btrim(p_publication_id) and launch_identity=btrim(p_launch_identity) and started_at=p_started_at;
  if v_existing is not null then return query select v_existing,'existing'::text; return; end if;
  select id into v_prior from tongs.thumbnail_launch_intervals where workspace_id=p_workspace_id and publication_id=btrim(p_publication_id) and ended_at is null for update;
  if v_prior is not null then perform set_config('tongs.thumbnail_ledger_controlled_update','on',true); update tongs.thumbnail_launch_intervals set ended_at=p_started_at,state='replaced' where id=v_prior; perform set_config('tongs.thumbnail_ledger_controlled_update','off',true); end if;
  insert into tongs.thumbnail_launch_intervals(workspace_id,workpiece_id,publication_id,launch_identity,launch_snapshot_hash,platform,state,started_at,predecessor_interval_id,attribution_json,content_hash,created_by)
  values(p_workspace_id,p_workpiece_id,btrim(p_publication_id),btrim(p_launch_identity),p_launch_snapshot_hash,btrim(p_platform),p_state,p_started_at,v_prior,p_attribution_json,p_content_hash,v_user) returning id into v_existing;
  return query select v_existing,'created'::text;
end $$;


ALTER FUNCTION "tongs"."append_thumbnail_launch_interval"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_publication_id" "text", "p_launch_identity" "text", "p_launch_snapshot_hash" "text", "p_platform" "text", "p_state" "text", "p_started_at" timestamp with time zone, "p_attribution_json" "jsonb", "p_content_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."append_thumbnail_ledger_analysis"("p_workspace_id" "uuid", "p_analysis_identity" "text", "p_analysis_type" "text", "p_launch_identities" "text"[], "p_observation_ids" "uuid"[], "p_analysis_version" "text", "p_evidence_class" "text", "p_confidence" "text", "p_analysis_json" "jsonb", "p_content_hash" "text") RETURNS TABLE("analysis_id" "uuid", "disposition" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare v_user uuid:=auth.uid(); v_id uuid;
begin if v_user is null then raise exception 'Not authenticated' using errcode='42501'; end if; perform tongs.assert_workspace_role(p_workspace_id,'editor');
  select id into v_id from tongs.thumbnail_ledger_analyses where workspace_id=p_workspace_id and analysis_identity=p_analysis_identity and content_hash=p_content_hash;
  if v_id is not null then return query select v_id,'existing'::text; return; end if;
  insert into tongs.thumbnail_ledger_analyses(workspace_id,analysis_identity,analysis_type,launch_identities,observation_ids,analysis_version,evidence_class,confidence,analysis_json,content_hash,created_by)
  values(p_workspace_id,p_analysis_identity,p_analysis_type,coalesce(p_launch_identities,'{}'),coalesce(p_observation_ids,'{}'),p_analysis_version,p_evidence_class,p_confidence,p_analysis_json,p_content_hash,v_user) returning id into v_id;
  return query select v_id,'created'::text; end $$;


