CREATE OR REPLACE FUNCTION "tongs"."append_thumbnail_ledger_ingestion_cursor"("p_workspace_id" "uuid", "p_provider" "text", "p_publication_id" "text", "p_cursor_identity" "text", "p_cursor_json" "jsonb", "p_status" "text", "p_last_success_at" timestamp with time zone, "p_last_error" "text") RETURNS TABLE("cursor_id" "uuid", "disposition" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare v_user uuid:=auth.uid(); v_id uuid;
begin
  if v_user is null then raise exception 'Not authenticated' using errcode='42501'; end if;
  perform tongs.assert_workspace_role(p_workspace_id,'editor');
  select id into v_id from tongs.thumbnail_ledger_ingestion_cursors where workspace_id=p_workspace_id and provider=p_provider
    and publication_id=p_publication_id and cursor_identity=p_cursor_identity order by recorded_at desc limit 1;
  if v_id is not null then return query select v_id,'existing'::text; return; end if;
  insert into tongs.thumbnail_ledger_ingestion_cursors(workspace_id,provider,publication_id,cursor_identity,cursor_json,status,last_success_at,last_error,created_by)
  values(p_workspace_id,p_provider,p_publication_id,p_cursor_identity,p_cursor_json,p_status,p_last_success_at,p_last_error,v_user) returning id into v_id;
  return query select v_id,'created'::text;
end $$;


ALTER FUNCTION "tongs"."append_thumbnail_ledger_ingestion_cursor"("p_workspace_id" "uuid", "p_provider" "text", "p_publication_id" "text", "p_cursor_identity" "text", "p_cursor_json" "jsonb", "p_status" "text", "p_last_success_at" timestamp with time zone, "p_last_error" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."append_thumbnail_memory_interpretation"("p_workspace_id" "uuid", "p_interpretation_key" "text", "p_observation_type" "text", "p_evidence_launch_identities" "text"[], "p_interpretation_json" "jsonb") RETURNS TABLE("interpretation_id" "uuid", "revision" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare v_user uuid := auth.uid(); v_prior_id uuid; v_revision integer; v_id uuid;
begin
  if v_user is null then raise exception 'Not authenticated' using errcode = '42501'; end if;
  perform tongs.assert_workspace_role(p_workspace_id, 'editor');
  perform pg_advisory_xact_lock(hashtextextended(p_workspace_id::text || ':' || btrim(p_interpretation_key), 0));
  select i.id, i.revision into v_prior_id, v_revision from tongs.thumbnail_memory_interpretations i
    where i.workspace_id = p_workspace_id and i.interpretation_key = btrim(p_interpretation_key)
    order by i.revision desc limit 1;
  v_revision := coalesce(v_revision, 0) + 1;
  insert into tongs.thumbnail_memory_interpretations
    (workspace_id, interpretation_key, revision, supersedes_id, observation_type,
      evidence_launch_identities, interpretation_json, created_by)
  values (p_workspace_id, btrim(p_interpretation_key), v_revision, v_prior_id, p_observation_type,
    coalesce(p_evidence_launch_identities, '{}'), jsonb_strip_nulls(p_interpretation_json), v_user)
  returning id into v_id;
  return query select v_id, v_revision;
end;
$$;


ALTER FUNCTION "tongs"."append_thumbnail_memory_interpretation"("p_workspace_id" "uuid", "p_interpretation_key" "text", "p_observation_type" "text", "p_evidence_launch_identities" "text"[], "p_interpretation_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."apply_ai_credit_correction"("p_user_id" "uuid", "p_correction_id" "uuid", "p_settlement_event_id" bigint, "p_correction_type" "text", "p_amount" bigint, "p_reason_code" "text", "p_actor_id" "uuid", "p_metadata_json" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_account tongs.ai_credits%rowtype;
  v_existing tongs.ai_credit_corrections%rowtype;
  v_delta bigint;
  v_available bigint;
begin
  select * into v_account from tongs.ai_credits where user_id = p_user_id for update;
  if not found then raise exception 'AI-credit account not found' using errcode = 'P0002'; end if;
  select * into v_existing from tongs.ai_credit_corrections where id = p_correction_id;
  if found then
    if v_existing.user_id <> p_user_id or v_existing.amount <> p_amount or v_existing.correction_type <> p_correction_type
       or v_existing.settlement_event_id is distinct from p_settlement_event_id or v_existing.reason_code <> p_reason_code then
      raise exception 'correction replay conflict' using errcode = '23505';
    end if;
    return jsonb_build_object('correction', to_jsonb(v_existing), 'replay', true);
  end if;
  if p_amount <= 0 or p_correction_type not in ('refund', 'credit_adjustment', 'debit_adjustment') then
    raise exception 'invalid correction' using errcode = '22023';
  end if;
  if p_correction_type = 'refund' and not exists (
    select 1 from tongs.ai_credit_reservation_events e
    where e.id = p_settlement_event_id and e.user_id = p_user_id and e.event_type = 'settled'
  ) then raise exception 'refund requires an owned settlement' using errcode = '22023'; end if;
  v_delta := case when p_correction_type = 'debit_adjustment' then -p_amount else p_amount end;
  v_available := v_account.token_balance - tongs._ai_credit_active_holds(p_user_id);
  if v_delta < 0 and -v_delta > v_available then raise exception 'insufficient available AI credits' using errcode = 'P0001'; end if;
  insert into tongs.ai_credit_corrections values (
    p_correction_id, p_user_id, p_settlement_event_id, p_correction_type, p_amount,
    p_reason_code, p_actor_id, coalesce(p_metadata_json, '{}'::jsonb), now()
  ) returning * into v_existing;
  insert into tongs.ai_credit_ledger (request_id, user_id, delta, reason)
    values (p_correction_id, p_user_id, v_delta, 'correction:' || p_reason_code);
  update tongs.ai_credits set token_balance = token_balance + v_delta, updated_at = now() where user_id = p_user_id;
  return jsonb_build_object('correction', to_jsonb(v_existing), 'replay', false,
    'settled_balance', v_account.token_balance + v_delta);
end;
$$;


ALTER FUNCTION "tongs"."apply_ai_credit_correction"("p_user_id" "uuid", "p_correction_id" "uuid", "p_settlement_event_id" bigint, "p_correction_type" "text", "p_amount" bigint, "p_reason_code" "text", "p_actor_id" "uuid", "p_metadata_json" "jsonb") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "tongs"."ai_credits" (
    "user_id" "uuid" NOT NULL,
    "billing_mode" "text" DEFAULT 'forge'::"text" NOT NULL,
    "token_balance" bigint DEFAULT 0 NOT NULL,
    "token_monthly_limit" bigint,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "ai_credits_billing_mode_check" CHECK (("billing_mode" = ANY (ARRAY['forge'::"text", 'byo'::"text", 'off'::"text"]))),
    CONSTRAINT "ai_credits_token_balance_check" CHECK (("token_balance" >= 0)),
    CONSTRAINT "ai_credits_token_monthly_limit_check" CHECK ((("token_monthly_limit" IS NULL) OR ("token_monthly_limit" >= 0)))
);


ALTER TABLE "tongs"."ai_credits" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."apply_ai_token_delta"("p_user_id" "uuid", "p_delta" bigint, "p_reason" "text" DEFAULT ''::"text", "p_request_id" "uuid" DEFAULT NULL::"uuid") RETURNS "tongs"."ai_credits"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare
  v_row tongs.ai_credits;
begin
  if p_user_id is null then
    raise exception 'p_user_id cannot be null';
  end if;

  insert into tongs.ai_credits (user_id)
  values (p_user_id)
  on conflict (user_id) do nothing;

  update tongs.ai_credits
    set token_balance = token_balance + p_delta
  where user_id = p_user_id
    and (token_balance + p_delta) >= 0
  returning * into v_row;

  if not found then
    raise exception 'Insufficient tokens for user % (delta=%)', p_user_id, p_delta
      using errcode = '22000';
  end if;

  insert into tongs.ai_token_ledger (user_id, delta, reason, request_id)
  values (p_user_id, p_delta, coalesce(p_reason,''), p_request_id);

  return v_row;
end;
$$;


ALTER FUNCTION "tongs"."apply_ai_token_delta"("p_user_id" "uuid", "p_delta" bigint, "p_reason" "text", "p_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."apply_ai_token_delta"("p_user_id" "uuid", "p_delta" integer, "p_reason" "text", "p_request_id" "uuid", "p_provider_request_id" "text" DEFAULT NULL::"text") RETURNS TABLE("token_balance" bigint, "billing_mode" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_account tongs.ai_credits%rowtype;
  v_available bigint;
begin
  if p_user_id is null or p_request_id is null then raise exception 'user and request required' using errcode = '22023'; end if;
  insert into tongs.ai_credits (user_id) values (p_user_id) on conflict do nothing;
  select * into v_account from tongs.ai_credits where user_id = p_user_id for update;
  if exists (select 1 from tongs.ai_credit_ledger where request_id = p_request_id and user_id = p_user_id) then
    return query select c.token_balance, c.billing_mode from tongs.ai_credits c where c.user_id = p_user_id;
    return;
  end if;
  if p_delta < 0 then
    v_available := v_account.token_balance - tongs._ai_credit_active_holds(p_user_id);
    if -p_delta::bigint > v_available then
      raise exception 'insufficient available AI credits' using errcode = 'P0001',
        detail = jsonb_build_object('required', -p_delta::bigint, 'available', v_available)::text;
    end if;
  end if;
  insert into tongs.ai_credit_ledger (request_id, user_id, delta, reason, provider_request_id)
    values (p_request_id, p_user_id, p_delta, coalesce(nullif(btrim(p_reason), ''), 'legacy_ai_credit_delta'), p_provider_request_id);
  update tongs.ai_credits c set token_balance = c.token_balance + p_delta, updated_at = now() where c.user_id = p_user_id;
  return query select c.token_balance, c.billing_mode from tongs.ai_credits c where c.user_id = p_user_id;
end;
$$;


ALTER FUNCTION "tongs"."apply_ai_token_delta"("p_user_id" "uuid", "p_delta" integer, "p_reason" "text", "p_request_id" "uuid", "p_provider_request_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."apply_episode_split_recovery"("p_manifest" "jsonb", "p_manifest_hash" "text", "p_operation_key" "text", "p_actor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $_$
declare
  w uuid := (p_manifest->>'workspace_id')::uuid;
  project uuid := (p_manifest->>'project_id')::uuid;
  source_wp uuid := (p_manifest->>'source_workpiece_id')::uuid;
  destination_wp uuid := (p_manifest->>'destination_workpiece_id')::uuid;
  source_approval uuid := (p_manifest->>'source_restore_approval_id')::uuid;
  destination_source_approval uuid := (p_manifest->>'destination_source_approval_id')::uuid;
  destination_approval uuid := (p_manifest->>'destination_approval_id')::uuid;
  destination_link uuid := (p_manifest->>'destination_link_id')::uuid;
  source_script jsonb := p_manifest->'staged_files'->'source_script';
  source_chat jsonb := p_manifest->'staged_files'->'source_chat';
  destination_script jsonb := p_manifest->'staged_files'->'destination_script';
  destination_chat jsonb := p_manifest->'staged_files'->'destination_chat';
  expected_hash text;
  prior tongs.episode_split_recovery_receipts%rowtype;
  src tongs.script_approval_revisions%rowtype;
  dst_src tongs.script_approval_revisions%rowtype;
  receipt jsonb;
begin
  if p_actor_id is null or (auth.role()<>'service_role' and (auth.uid() is distinct from p_actor_id or not tongs.has_workspace_role(w,'owner'))) then
    raise exception 'workspace owner authority required' using errcode='42501';
  end if;
  expected_hash := tongs.episode_split_recovery_manifest_hash(p_manifest);
  if p_manifest_hash !~ '^[0-9a-f]{64}$' or expected_hash <> p_manifest_hash then
    return jsonb_build_object('outcome','manifest_hash_mismatch','expected_manifest_hash',expected_hash);
  end if;
  if length(btrim(coalesce(p_operation_key,''))) not between 16 and 200 then
    return jsonb_build_object('outcome','invalid_operation_key');
  end if;
  perform pg_advisory_xact_lock(hashtextextended(w::text||':'||project::text||':'||p_operation_key,0));
  select * into prior from tongs.episode_split_recovery_receipts
    where workspace_id=w and project_id=project and operation_key=p_operation_key;
  if found then
    if prior.manifest_hash <> p_manifest_hash then return jsonb_build_object('outcome','operation_identity_conflict'); end if;
    return prior.receipt_json;
  end if;
  if not exists(select 1 from tongs.barstock_project_episode_links where workspace_id=w and project_id=project and workpiece_id=source_wp)
    or exists(select 1 from tongs.episodes where id=destination_wp) then
    return jsonb_build_object('outcome','identity_precondition_failed');
  end if;
  select * into src from tongs.script_approval_revisions where id=source_approval and workspace_id=w and workpiece_id=source_wp;
  select * into dst_src from tongs.script_approval_revisions where id=destination_source_approval and workspace_id=w and workpiece_id=source_wp;
  if src.id is null or dst_src.id is null
    or src.script_content_hash <> p_manifest->>'source_restore_script_hash'
    or dst_src.script_content_hash <> p_manifest->>'destination_script_hash' then
    return jsonb_build_object('outcome','script_precondition_failed');
  end if;
  if not exists(select 1 from tongs.workpiece_script_approval_sequences where workspace_id=w and workpiece_id=source_wp and current_approval_id=destination_source_approval and current_revision=(p_manifest->>'expected_source_approval_revision')::bigint)
    or not exists(select 1 from tongs.workpiece_image_map_sequences where workspace_id=w and workpiece_id=source_wp and current_revision_id=(p_manifest->>'expected_image_revision_id')::uuid)
    or not exists(select 1 from tongs.broll_plan_sequences where workspace_id=w and workpiece_id=source_wp and current_plan_revision_id=(p_manifest->>'expected_broll_revision_id')::uuid)
    or not exists(select 1 from tongs.reference_clip_plan_sequences where workspace_id=w and workpiece_id=source_wp and current_plan_revision_id=(p_manifest->>'expected_reference_clip_revision_id')::uuid)
    or not exists(select 1 from tongs.reference_visual_plan_sequences where workspace_id=w and workpiece_id=source_wp and current_plan_revision_id=(p_manifest->>'expected_reference_visual_revision_id')::uuid)
    or not exists(select 1 from tongs.workpiece_files where workpiece_id=source_wp and path='hearth/chat.v1.json' and revision=(p_manifest->>'expected_chat_revision')::bigint and hash_value=p_manifest->>'expected_chat_hash') then
    return jsonb_build_object('outcome','authority_precondition_failed');
  end if;
  if exists(select 1 from jsonb_each(p_manifest->'staged_files') f where f.value->>'hash_value' !~ '^[0-9a-f]{64}$' or (f.value->>'bytes')::bigint < 0) then
    return jsonb_build_object('outcome','staged_file_evidence_invalid');
  end if;

  insert into tongs.episodes(id,workspace_id,label) values(destination_wp,w,p_manifest->>'destination_label');
  insert into tongs.barstock_project_episode_links(id,workspace_id,project_id,workpiece_id,creation_operation_key,created_by)
    values(destination_link,w,project,destination_wp,p_operation_key,p_actor_id);
  insert into tongs.script_approval_revisions(id,workspace_id,workpiece_id,approval_revision,source_file_path,source_file_revision,script_content_hash,semantic_state_hash,immutable_revision_hash,script_text,approval_contract_version,creator_version_label,created_by)
    values(destination_approval,w,destination_wp,1,'script/script.md',1,dst_src.script_content_hash,dst_src.semantic_state_hash,
      encode(extensions.digest(convert_to(jsonb_build_object('source_approval_id',dst_src.id,'destination_workpiece_id',destination_wp,'manifest_hash',p_manifest_hash)::text,'UTF8'),'sha256'),'hex'),
      dst_src.script_text,dst_src.approval_contract_version,dst_src.creator_version_label,p_actor_id);
  insert into tongs.workpiece_script_approval_sequences(workspace_id,workpiece_id,current_approval_id,current_revision) values(w,destination_wp,destination_approval,1);

  update tongs.workpiece_script_approval_sequences set current_approval_id=source_approval,current_revision=src.approval_revision,updated_at=now() where workspace_id=w and workpiece_id=source_wp;
  update tongs.workpiece_image_map_sequences set current_revision_id=(p_manifest->>'restore_image_revision_id')::uuid,current_revision=(p_manifest->>'restore_image_revision')::bigint,updated_at=now() where workspace_id=w and workpiece_id=source_wp;
  update tongs.broll_plan_sequences set current_plan_revision_id=(p_manifest->>'restore_broll_revision_id')::uuid,current_plan_revision=(p_manifest->>'restore_broll_revision')::bigint,updated_at=now() where workspace_id=w and workpiece_id=source_wp;
  update tongs.reference_clip_plan_sequences set current_plan_revision_id=(p_manifest->>'restore_reference_clip_revision_id')::uuid,current_plan_revision=(p_manifest->>'restore_reference_clip_revision')::bigint,updated_at=now() where workspace_id=w and workpiece_id=source_wp;
  update tongs.reference_visual_plan_sequences set current_plan_revision_id=(p_manifest->>'restore_reference_visual_revision_id')::uuid,current_plan_revision=(p_manifest->>'restore_reference_visual_revision')::bigint,updated_at=now() where workspace_id=w and workpiece_id=source_wp;

  update tongs.workpiece_files set bytes=(source_script->>'bytes')::bigint,hash_value=source_script->>'hash_value',storage_bucket=source_script->>'storage_bucket',storage_key=source_script->>'storage_key',revision=revision+1,updated_at=now() where workpiece_id=source_wp and path='script/script.md';
  update tongs.workpiece_files set bytes=(source_chat->>'bytes')::bigint,hash_value=source_chat->>'hash_value',storage_bucket=source_chat->>'storage_bucket',storage_key=source_chat->>'storage_key',revision=revision+1,updated_at=now() where workpiece_id=source_wp and path='hearth/chat.v1.json';
  insert into tongs.workpiece_files(workpiece_id,path,file_type,content_type,bytes,hash_algo,hash_value,storage_bucket,storage_key,written_by_tool,written_by_tool_version,written_by_lane,revision)
    values(destination_wp,'script/script.md','script','text/markdown; charset=utf-8',(destination_script->>'bytes')::bigint,'sha256',destination_script->>'hash_value',destination_script->>'storage_bucket',destination_script->>'storage_key','tongs-recovery','forge-v1.2.0','incident-recovery',1),
          (destination_wp,'hearth/chat.v1.json','json','application/json',(destination_chat->>'bytes')::bigint,'sha256',destination_chat->>'hash_value',destination_chat->>'storage_bucket',destination_chat->>'storage_key','tongs-recovery','forge-v1.2.0','incident-recovery',1);

  receipt := jsonb_build_object('outcome','applied','manifest_hash',p_manifest_hash,'operation_key',p_operation_key,'source_workpiece_id',source_wp,'destination_workpiece_id',destination_wp,'destination_approval_id',destination_approval,'applied_at',now());
  insert into tongs.episode_split_recovery_receipts(workspace_id,project_id,source_workpiece_id,destination_workpiece_id,operation_key,manifest_hash,manifest_json,receipt_json,created_by)
    values(w,project,source_wp,destination_wp,p_operation_key,p_manifest_hash,p_manifest,receipt,p_actor_id);
  return receipt;
end$_$;


ALTER FUNCTION "tongs"."apply_episode_split_recovery"("p_manifest" "jsonb", "p_manifest_hash" "text", "p_operation_key" "text", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."approve_and_reserve_paid_media_operation"("p_paid_media_operation_id" "uuid", "p_operation_id" "text", "p_operation_fingerprint" "text", "p_quote_id" "uuid", "p_reservation_id" "uuid", "p_actor_id" "uuid", "p_creator_approval_json" "jsonb", "p_contract_version" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare v_quote tongs.ai_credit_quotes%rowtype; v_existing tongs.paid_media_operations%rowtype; v_reservation jsonb; v_purpose text;
begin
  select * into v_quote from tongs.ai_credit_quotes where id=p_quote_id and user_id=p_actor_id for update;
  if not found then raise exception 'owned paid media quote not found' using errcode='P0002'; end if;
  if v_quote.expires_at is not null and v_quote.expires_at<=now() then raise exception 'paid media quote expired' using errcode='22023'; end if;
  if v_quote.request_fingerprint<>p_operation_fingerprint then raise exception 'paid operation fingerprint mismatch' using errcode='22023'; end if;
  select * into v_existing from tongs.paid_media_operations where user_id=p_actor_id and operation_id=p_operation_id for update;
  if found then
    if v_existing.id<>p_paid_media_operation_id or v_existing.operation_fingerprint<>p_operation_fingerprint or v_existing.quote_id<>p_quote_id then
      raise exception 'paid media operation replay conflict' using errcode='23505'; end if;
    return jsonb_build_object('operation',to_jsonb(v_existing),'replay',true);
  end if;
  v_purpose:=case when v_quote.media_kind='video' then 'paid_video_generation' else 'paid_image_generation' end;
  v_reservation:=tongs.reserve_ai_credits(p_actor_id,p_operation_id,v_quote.tool,v_purpose,v_quote.media_kind,
    v_quote.authorized_customer_ceiling,p_operation_fingerprint,
    jsonb_build_object('quote_id',p_quote_id,'ceiling',v_quote.authorized_customer_ceiling),p_reservation_id);
  insert into tongs.paid_media_operations(id,operation_id,operation_fingerprint,user_id,actor_id,workspace_id,workpiece_id,
    originating_tool,originating_entity_id,media_kind,provider,model_snapshot,quote_id,authorization_policy_revision_id,
    pricing_policy_revision_id,authorized_customer_ceiling,reservation_id,prompt_revision_id,prompt_content_hash,request_parameters,
    creator_approval_json,contract_version,state)
  values(p_paid_media_operation_id,p_operation_id,p_operation_fingerprint,p_actor_id,p_actor_id,v_quote.workspace_id,v_quote.workpiece_id,
    v_quote.tool,v_quote.request_parameters#>>'{metadata,originating_entity_id}',v_quote.media_kind,v_quote.provider,v_quote.model,v_quote.id,
    v_quote.authorization_policy_revision_id,v_quote.pricing_policy_revision_id,v_quote.authorized_customer_ceiling,p_reservation_id,
    v_quote.prompt_revision_id,v_quote.prompt_content_hash,v_quote.request_parameters,p_creator_approval_json,p_contract_version,'approved')
  returning * into v_existing;
  insert into tongs.paid_media_operation_events values(gen_random_uuid(),v_existing.id,p_actor_id,'creator_approved',1,p_creator_approval_json,p_actor_id,now());
  update tongs.paid_media_operations set state='reserved',updated_at=now() where id=v_existing.id returning * into v_existing;
  insert into tongs.paid_media_operation_events values(gen_random_uuid(),v_existing.id,p_actor_id,'credits_reserved',2,
    jsonb_build_object('reservation_id',p_reservation_id,'amount',v_quote.authorized_customer_ceiling),p_actor_id,now());
  return jsonb_build_object('operation',to_jsonb(v_existing),'reservation',v_reservation,'replay',false);
end $$;


ALTER FUNCTION "tongs"."approve_and_reserve_paid_media_operation"("p_paid_media_operation_id" "uuid", "p_operation_id" "text", "p_operation_fingerprint" "text", "p_quote_id" "uuid", "p_reservation_id" "uuid", "p_actor_id" "uuid", "p_creator_approval_json" "jsonb", "p_contract_version" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."approve_canonical_script_v2"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_expected_current_approval_revision" bigint, "p_expected_source_file_revision" bigint, "p_expected_source_content_hash" "text", "p_script_text" "text", "p_creator_version_label" "text", "p_operation_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare
  v_user uuid := auth.uid();
  v_file tongs.workpiece_files%rowtype;
  v_text text;
  v_hash text;
  v_result jsonb;
  v_receipt tongs.hearth_authority_operation_receipts%rowtype;
  v_prior tongs.script_approval_revisions%rowtype;
begin
  if v_user is null or not tongs.has_workspace_role(p_workspace_id, 'editor') then
    return jsonb_build_object('disposition','denied','reason','editor_required');
  end if;
  if not exists(select 1 from tongs.episodes where id=p_workpiece_id and workspace_id=p_workspace_id) then
    return jsonb_build_object('disposition','not_found','reason','episode_membership_invalid');
  end if;
  select * into v_receipt from tongs.hearth_authority_operation_receipts where operation_id=p_operation_id;
  if found then
    select * into v_prior from tongs.script_approval_revisions where id=v_receipt.result_script_approval_id;
    if found and v_receipt.workspace_id=p_workspace_id and v_receipt.workpiece_id=p_workpiece_id
      and v_prior.source_file_revision=p_expected_source_file_revision
      and v_prior.script_content_hash=lower(p_expected_source_content_hash) then
      return v_receipt.immutable_result_json;
    end if;
    return jsonb_build_object('disposition','operation_identity_conflict');
  end if;
  select * into v_file from tongs.workpiece_files
    where workpiece_id=p_workpiece_id and path='script/script.md' for update;
  if not found then return jsonb_build_object('disposition','not_found','reason','script_not_found'); end if;
  if v_file.revision <> p_expected_source_file_revision then
    return jsonb_build_object('disposition','stale_source','reason','source_revision_changed','current_source_revision',v_file.revision);
  end if;
  v_hash := lower(coalesce(v_file.hash_value,''));
  if v_hash <> lower(btrim(coalesce(p_expected_source_content_hash,''))) then
    return jsonb_build_object('disposition','stale_source','reason','source_hash_changed','current_source_hash',v_hash);
  end if;
  v_text := tongs.normalize_script_approval_text(p_script_text);
  if encode(extensions.digest(convert_to(v_text,'UTF8'),'sha256'),'hex') <> v_hash then
    return jsonb_build_object('disposition','stale_source','reason','source_bytes_changed');
  end if;
  select tongs.commit_script_approval_snapshot(
    p_workspace_id,p_workpiece_id,p_expected_current_approval_revision,
    'script/script.md',v_file.revision,v_text,'forge.script-approval.v2',
    p_creator_version_label,p_operation_id,v_user
  ) into v_result;
  return v_result;
end;
$$;


ALTER FUNCTION "tongs"."approve_canonical_script_v2"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_expected_current_approval_revision" bigint, "p_expected_source_file_revision" bigint, "p_expected_source_content_hash" "text", "p_script_text" "text", "p_creator_version_label" "text", "p_operation_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."approve_canonical_script_v3"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_expected_current_approval_revision" bigint, "p_expected_source_file_revision" bigint, "p_expected_source_content_hash" "text", "p_script_text" "text", "p_creator_version_label" "text", "p_preflight_report_id" "uuid", "p_operation_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare
  v_user uuid:=auth.uid();v_report tongs.hearth_editorial_preflight_reports%rowtype;v_review tongs.hearth_preflight_review_receipts%rowtype;
  v_research tongs.hearth_research_artifact_revisions%rowtype;v_result jsonb;v_approval_id uuid;v_approval_revision bigint;
  v_binding tongs.script_approval_preflight_bindings%rowtype;
begin
  if v_user is null or not tongs.has_workspace_role(p_workspace_id,'editor') then return jsonb_build_object('disposition','denied','reason','editor_required');end if;
  select r.* into v_report from tongs.hearth_editorial_preflight_reports r join tongs.workpiece_hearth_preflight_sequences s on s.current_report_id=r.id where r.id=p_preflight_report_id and r.workspace_id=p_workspace_id and r.workpiece_id=p_workpiece_id;
  if not found or v_report.source_file_revision<>p_expected_source_file_revision or v_report.script_content_hash<>lower(p_expected_source_content_hash) then return jsonb_build_object('disposition','stale_preflight','reason','script_preflight_mismatch');end if;
  select * into v_review from tongs.hearth_preflight_review_receipts where report_id=v_report.id;
  if not found then return jsonb_build_object('disposition','preflight_unreviewed');end if;
  if v_report.research_artifact_id is not null then
    select r.* into v_research from tongs.hearth_research_artifact_revisions r join tongs.workpiece_hearth_research_sequences s on s.current_artifact_id=r.id where r.id=v_report.research_artifact_id and r.artifact_content_hash=v_report.research_artifact_hash;
    if not found then return jsonb_build_object('disposition','stale_preflight','reason','research_changed');end if;
  end if;
  select tongs.commit_script_approval_snapshot(p_workspace_id,p_workpiece_id,p_expected_current_approval_revision,'script/script.md',p_expected_source_file_revision,tongs.normalize_script_approval_text(p_script_text),'forge.script-approval.v3',p_creator_version_label,p_operation_id,v_user) into v_result;
  if v_result->>'disposition' not in ('committed','no_change') then return v_result;end if;
  v_approval_id:=(v_result#>>'{approval,id}')::uuid;v_approval_revision:=(v_result#>>'{approval,approval_revision}')::bigint;
  select * into v_binding from tongs.script_approval_preflight_bindings where script_approval_id=v_approval_id and preflight_report_id=v_report.id;
  if found then
    if v_binding.preflight_script_hash<>v_report.script_content_hash or v_binding.research_artifact_id is distinct from v_report.research_artifact_id or v_binding.research_artifact_hash is distinct from v_report.research_artifact_hash then
      return jsonb_build_object('disposition','integrity_error','reason','approval_preflight_binding_mismatch');
    end if;
  else
    insert into tongs.script_approval_preflight_bindings(script_approval_id,workspace_id,workpiece_id,script_approval_revision,preflight_report_id,preflight_report_revision,preflight_script_hash,research_artifact_id,research_artifact_hash,bound_by)
    values(v_approval_id,p_workspace_id,p_workpiece_id,v_approval_revision,v_report.id,v_report.revision,v_report.script_content_hash,v_report.research_artifact_id,v_report.research_artifact_hash,v_user);
  end if;
  return v_result||jsonb_build_object('preflight_report_id',v_report.id,'preflight_report_revision',v_report.revision);
end;$$;


ALTER FUNCTION "tongs"."approve_canonical_script_v3"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_expected_current_approval_revision" bigint, "p_expected_source_file_revision" bigint, "p_expected_source_content_hash" "text", "p_script_text" "text", "p_creator_version_label" "text", "p_preflight_report_id" "uuid", "p_operation_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."approve_canonical_script_v4"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_expected_current_approval_revision" bigint, "p_expected_source_file_revision" bigint, "p_expected_source_content_hash" "text", "p_script_text" "text", "p_creator_version_label" "text", "p_operation_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_result jsonb;
  v_approval jsonb;
  v_approval_id uuid;
  v_approval_revision bigint;
  v_approval_hash text;
  v_ready_result jsonb;
begin
  -- The commit-only implementation retains all existing role, membership,
  -- source-revision, source-hash, and operation-id checks.
  select tongs.approve_canonical_script_v4_commit_only(
    p_workspace_id,
    p_workpiece_id,
    p_expected_current_approval_revision,
    p_expected_source_file_revision,
    p_expected_source_content_hash,
    p_script_text,
    p_creator_version_label,
    p_operation_id
  ) into v_result;

  if coalesce(v_result->>'disposition','') not in ('committed','no_change') then
    return v_result;
  end if;

  v_approval := v_result->'approval';
  begin
    v_approval_id := (v_approval->>'id')::uuid;
    v_approval_revision := (v_approval->>'approval_revision')::bigint;
    v_approval_hash := lower(coalesce(v_approval->>'script_content_hash',''));
  exception
    when invalid_text_representation or numeric_value_out_of_range then
      raise exception using
        errcode = '23514',
        message = 'canonical script approval returned malformed recording-readiness evidence';
  end;

  if v_approval_id is null
    or v_approval_revision < 1
    or v_approval_hash !~ '^[0-9a-f]{64}$' then
    raise exception using
      errcode = '23514',
      message = 'canonical script approval returned incomplete recording-readiness evidence';
  end if;

  select tongs.hearth_transition_approved_script_ready_v4(
    p_workspace_id,
    p_workpiece_id,
    v_approval_id,
    'hearth-approved-ready-v4:' || p_workpiece_id::text || ':' || v_approval_id::text,
    jsonb_build_object(
      'transition','hearth.approved-script.ready.v4',
      'script_approval_id',v_approval_id,
      'script_approval_revision',v_approval_revision,
      'script_approval_hash',v_approval_hash
    )
  ) into v_ready_result;

  if coalesce(v_ready_result->>'outcome','') not in ('saved','duplicate') then
    raise exception using
      errcode = '23514',
      message = 'approved script could not become recording-ready',
      detail = coalesce(v_ready_result::text,'null');
  end if;

  return v_result || jsonb_build_object(
    'recording_readiness', jsonb_build_object(
      'state','ready',
      'basis','current_script_approval',
      'ready',v_ready_result->'ready'
    )
  );
end;
$_$;


ALTER FUNCTION "tongs"."approve_canonical_script_v4"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_expected_current_approval_revision" bigint, "p_expected_source_file_revision" bigint, "p_expected_source_content_hash" "text", "p_script_text" "text", "p_creator_version_label" "text", "p_operation_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."approve_canonical_script_v4"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_expected_current_approval_revision" bigint, "p_expected_source_file_revision" bigint, "p_expected_source_content_hash" "text", "p_script_text" "text", "p_creator_version_label" "text", "p_operation_id" "text") IS 'Commits canonical script approval and atomically derives Anvil recording readiness. Optional review, thumbnails, images, reference material, and B-roll are non-blocking.';



CREATE OR REPLACE FUNCTION "tongs"."approve_canonical_script_v4_commit_only"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_expected_current_approval_revision" bigint, "p_expected_source_file_revision" bigint, "p_expected_source_content_hash" "text", "p_script_text" "text", "p_creator_version_label" "text", "p_operation_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare
  v_user uuid := auth.uid();
  v_file tongs.workpiece_files%rowtype;
  v_text text;
  v_hash text;
  v_result jsonb;
  v_receipt tongs.hearth_authority_operation_receipts%rowtype;
  v_prior tongs.script_approval_revisions%rowtype;
begin
  if v_user is null or not tongs.has_workspace_role(p_workspace_id, 'editor') then
    return jsonb_build_object('disposition','denied','reason','editor_required');
  end if;
  if not exists(
    select 1 from tongs.episodes
    where id=p_workpiece_id and workspace_id=p_workspace_id
  ) then
    return jsonb_build_object('disposition','not_found','reason','episode_membership_invalid');
  end if;
  select * into v_receipt
  from tongs.hearth_authority_operation_receipts
  where operation_id=p_operation_id;
  if found then
    select * into v_prior
    from tongs.script_approval_revisions
    where id=v_receipt.result_script_approval_id;
    if found
      and v_receipt.workspace_id=p_workspace_id
      and v_receipt.workpiece_id=p_workpiece_id
      and v_prior.source_file_revision=p_expected_source_file_revision
      and v_prior.script_content_hash=lower(p_expected_source_content_hash) then
      return v_receipt.immutable_result_json;
    end if;
    return jsonb_build_object('disposition','operation_identity_conflict');
  end if;
  select * into v_file
  from tongs.workpiece_files
  where workpiece_id=p_workpiece_id and path='script/script.md'
  for update;
  if not found then
    return jsonb_build_object('disposition','not_found','reason','script_not_found');
  end if;
  if v_file.revision<>p_expected_source_file_revision then
    return jsonb_build_object(
      'disposition','stale_source','reason','source_revision_changed',
      'current_source_revision',v_file.revision
    );
  end if;
  v_hash:=lower(coalesce(v_file.hash_value,''));
  if v_hash<>lower(btrim(coalesce(p_expected_source_content_hash,''))) then
    return jsonb_build_object(
      'disposition','stale_source','reason','source_hash_changed',
      'current_source_hash',v_hash
    );
  end if;
  v_text:=tongs.normalize_script_approval_text(p_script_text);
  if nullif(btrim(coalesce(v_text,'')),'') is null then
    return jsonb_build_object('disposition','invalid_script','reason','script_empty');
  end if;
  if encode(extensions.digest(convert_to(v_text,'UTF8'),'sha256'),'hex')<>v_hash then
    return jsonb_build_object('disposition','stale_source','reason','source_bytes_changed');
  end if;
  select tongs.commit_script_approval_snapshot(
    p_workspace_id,p_workpiece_id,p_expected_current_approval_revision,
    'script/script.md',v_file.revision,v_text,'forge.script-approval.v4',
    p_creator_version_label,p_operation_id,v_user
  ) into v_result;
  return v_result;
end;
$$;


ALTER FUNCTION "tongs"."approve_canonical_script_v4_commit_only"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_expected_current_approval_revision" bigint, "p_expected_source_file_revision" bigint, "p_expected_source_content_hash" "text", "p_script_text" "text", "p_creator_version_label" "text", "p_operation_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."archive_my_thumbnail_brand_template"("p_workspace_id" "uuid", "p_template_id" "uuid") RETURNS TABLE("template_id" "uuid", "workspace_id" "uuid", "slug" "text", "name" "text", "template_json" "jsonb", "is_default" boolean, "archived_at" timestamp with time zone, "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "updated_by" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare
  v_user uuid;
  v_was_default boolean := false;
  v_fallback_id uuid := null;
begin
  v_user := auth.uid();
  if v_user is null then
    raise exception 'Not authenticated'
      using errcode = '42501';
  end if;

  if p_workspace_id is null or p_template_id is null then
    raise exception 'workspace_id and template_id are required'
      using errcode = '22023';
  end if;

  perform tongs.assert_workspace_role(p_workspace_id, 'editor');

  select is_default
  into v_was_default
  from tongs.workspace_thumbnail_brand_templates t
  where t.workspace_id = p_workspace_id
    and t.id = p_template_id
    and t.archived_at is null
  limit 1;

  if not found then
    raise exception 'template not found'
      using errcode = 'P0002';
  end if;

  update tongs.workspace_thumbnail_brand_templates t
  set archived_at = now(),
      is_default = false,
      updated_at = now(),
      updated_by = v_user
  where t.workspace_id = p_workspace_id
    and t.id = p_template_id;

  if v_was_default then
    select t.id
    into v_fallback_id
    from tongs.workspace_thumbnail_brand_templates t
    where t.workspace_id = p_workspace_id
      and t.archived_at is null
    order by t.created_at asc, t.id asc
    limit 1;

    if v_fallback_id is not null then
      update tongs.workspace_thumbnail_brand_templates t
      set is_default = true,
          updated_at = now(),
          updated_by = v_user
      where t.id = v_fallback_id;
    end if;
  end if;

  return query
  select
    t.id,
    t.workspace_id,
    t.slug,
    t.name,
    t.template_json,
    t.is_default,
    t.archived_at,
    t.created_at,
    t.updated_at,
    t.updated_by
  from tongs.workspace_thumbnail_brand_templates t
  where t.id = p_template_id;
end;
$$;


ALTER FUNCTION "tongs"."archive_my_thumbnail_brand_template"("p_workspace_id" "uuid", "p_template_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."assert_current_broll_prompt"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_beat_id" "uuid", "p_prompt_revision_id" "uuid", "p_prompt_revision" bigint, "p_prompt_content_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare v_status jsonb; v_prompt jsonb;
begin
 if not tongs.has_workspace_role(p_workspace_id,'viewer') then raise exception 'workspace viewer authority required' using errcode='42501'; end if;
 v_status:=tongs.read_broll_prompt_status(p_workspace_id,p_workpiece_id,p_beat_id); v_prompt:=v_status->'prompt_revision';
 if v_status->>'status' not in('current','creator_edited') then return jsonb_build_object('disposition','prompt_authority_invalid','prompt_status',v_status); end if;
 if v_prompt->>'id' is distinct from p_prompt_revision_id::text or (v_prompt->>'revision')::bigint is distinct from p_prompt_revision or v_prompt->>'content_hash' is distinct from p_prompt_content_hash then return jsonb_build_object('disposition','prompt_revision_conflict','prompt_status',v_status); end if;
 return jsonb_build_object('disposition','verified','prompt_revision',v_prompt);
end $$;


ALTER FUNCTION "tongs"."assert_current_broll_prompt"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_beat_id" "uuid", "p_prompt_revision_id" "uuid", "p_prompt_revision" bigint, "p_prompt_content_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."assert_openai_result_delivery_access"("p_user_id" "uuid", "p_workspace_id" "uuid", "p_workpiece_id" "text") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
begin
 perform tongs._require_pricing_service_role();
 if p_user_id is null or not exists(select 1 from tongs.workspace_members
   where user_id=p_user_id and workspace_id=p_workspace_id) then
   raise exception 'current workspace access required for result delivery' using errcode='42501';
 end if;
 return true;
end $$;


ALTER FUNCTION "tongs"."assert_openai_result_delivery_access"("p_user_id" "uuid", "p_workspace_id" "uuid", "p_workpiece_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."assert_org_role"("p_org_id" "uuid", "p_min_role" "text" DEFAULT 'member'::"text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare
  v_user uuid;
  v_role text;
  v_needed text;
begin
  v_user := auth.uid();
  if v_user is null then
    raise exception 'Not authenticated'
      using errcode = '42501';
  end if;

  if p_org_id is null then
    raise exception 'org_id is required'
      using errcode = '22023';
  end if;

  v_needed := lower(trim(coalesce(p_min_role, 'member')));
  if v_needed not in ('owner', 'admin', 'member') then
    raise exception 'invalid minimum org role: %', p_min_role
      using errcode = '22023';
  end if;

  select om.org_role
  into v_role
  from tongs.org_members om
  where om.org_id = p_org_id
    and om.user_id = v_user;

  if v_role is null then
    raise exception 'Insufficient org role (requires %)', v_needed
      using errcode = '42501';
  end if;

  if tongs.org_role_rank(v_role) < tongs.org_role_rank(v_needed) then
    raise exception 'Insufficient org role (requires %)', v_needed
      using errcode = '42501';
  end if;

  return v_role;
end;
$$;


ALTER FUNCTION "tongs"."assert_org_role"("p_org_id" "uuid", "p_min_role" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."assert_unified_visual_plan_coverage_exclusive"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_plan" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare
  duplicate_focus text;
begin
  if not tongs.has_workspace_role(p_workspace_id, 'editor') then
    raise exception 'workspace editor role required' using errcode = '42501';
  end if;

  if not exists (
    select 1 from tongs.episodes
    where id = p_workpiece_id and workspace_id = p_workspace_id
  ) then
    raise exception 'workpiece not found in workspace' using errcode = 'P0002';
  end if;

  with coverage as (
    select family, nullif(btrim(item->>'context_focus'), '') as focus
    from (values
      ('image', coalesce(p_plan->'images', '[]'::jsonb)),
      ('broll', coalesce(p_plan->'broll', '[]'::jsonb)),
      ('reference_clip', coalesce(p_plan->'reference_clips', '[]'::jsonb)),
      ('reference_visual', coalesce(p_plan->'reference_visuals', '[]'::jsonb))
    ) as families(family, items)
    cross join lateral jsonb_array_elements(families.items) as item
  )
  select focus into duplicate_focus
  from coverage
  where focus is not null
  group by focus
  having count(*) > 1
  limit 1;

  if duplicate_focus is not null then
    raise exception 'visual coverage overlap remains for script focus: %', duplicate_focus
      using errcode = '23514';
  end if;

  return jsonb_build_object('disposition', 'verified', 'exclusive', true);
end;
$$;


ALTER FUNCTION "tongs"."assert_unified_visual_plan_coverage_exclusive"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_plan" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."assert_workspace_role"("_workspace_id" "uuid", "_min_role" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
begin
  if _workspace_id is null then
    raise exception 'workspace_id is required'
      using errcode = '22023';
  end if;

  if tongs.workspace_role_rank(_min_role) = 0 then
    raise exception 'Unsupported workspace role: %', _min_role
      using errcode = '22023';
  end if;

  if not tongs.has_workspace_role(_workspace_id, _min_role) then
    raise exception 'Insufficient workspace role (requires %)', lower(btrim(_min_role))
      using errcode = '42501';
  end if;
end;
$$;


ALTER FUNCTION "tongs"."assert_workspace_role"("_workspace_id" "uuid", "_min_role" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."authorize_hammer_short_derivative_preparation"("p_derivative_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare v_actor uuid:=auth.uid(); v_row tongs.hammer_short_derivatives%rowtype;
begin
  select * into v_row from tongs.hammer_short_derivatives where id=p_derivative_id;
  if v_actor is null or v_row.id is null or not tongs.has_workspace_role(v_row.workspace_id,'editor') then raise exception 'hammer_shorts_editor_required' using errcode='42501'; end if;
  if v_row.state not in('preparing','failed') then raise exception 'hammer_short_derivative_not_preparing' using errcode='40001'; end if;
  return to_jsonb(v_row);
end $$;


ALTER FUNCTION "tongs"."authorize_hammer_short_derivative_preparation"("p_derivative_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."authorize_hearth_chat_test_attempt"("p_reservation_id" "uuid", "p_attempt_key" "text", "p_evidence_json" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare v_state text; v_seq integer;
begin
  perform tongs._require_pricing_service_role();
  perform pg_advisory_xact_lock(hashtextextended('test-attempt:'||p_reservation_id::text,0));
  if exists(select 1 from tongs.test_funding_reservation_events where event_key=btrim(p_attempt_key)) then return jsonb_build_object('provider_execution_authorized',true,'execution_kind','simulated_test','real_provider_authorized',false,'replay',true); end if;
  v_state:=tongs._test_reservation_state(p_reservation_id);
  if v_state<>'reserved' then raise exception 'Test reservation not attemptable' using errcode='P0001'; end if;
  select coalesce(max(sequence),0)+1 into v_seq from tongs.test_funding_reservation_events where reservation_id=p_reservation_id;
  insert into tongs.test_funding_reservation_events(id,reservation_id,sequence,event_type,event_key,evidence_json)
  values(gen_random_uuid(),p_reservation_id,v_seq,'attempt_started',btrim(p_attempt_key),coalesce(p_evidence_json,'{}'::jsonb)||jsonb_build_object('execution_kind','simulated_test','real_provider_authorized',false));
  return jsonb_build_object('provider_execution_authorized',true,'execution_kind','simulated_test','real_provider_authorized',false,'replay',false);
end $$;


ALTER FUNCTION "tongs"."authorize_hearth_chat_test_attempt"("p_reservation_id" "uuid", "p_attempt_key" "text", "p_evidence_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."authorize_openai_text_provider_attempt"("p_reservation_id" "uuid", "p_attempt_key" "text", "p_attempt_number" smallint, "p_failure_exposure_micros" bigint, "p_lease_seconds" integer, "p_evidence_json" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  reservation tongs.funding_reservations%rowtype;
  legacy_authorization tongs.customer_paid_execution_test_authorizations%rowtype;
  normal_authorized boolean := false;
begin
  perform tongs._require_pricing_service_role();
  select * into reservation
  from tongs.funding_reservations
  where id = p_reservation_id;
  if not found then
    raise exception 'funding reservation not found' using errcode = 'P0002';
  end if;

  if reservation.funding_source_type in ('customer_deposit', 'paid_allowance', 'beta_grant') then
    select exists (
      select 1
      from tongs.customer_paid_execution_scope_authorizations scope_auth
      where scope_auth.id = reservation.rollout_authorization_id
        and scope_auth.authorization_kind = 'normal_customer'
        and scope_auth.user_id = reservation.user_id
        and scope_auth.financial_environment = reservation.funding_environment
        and scope_auth.status = 'active'
        and scope_auth.valid_from <= now()
        and (scope_auth.valid_until is null or scope_auth.valid_until > now())
    ) into normal_authorized;

    if not normal_authorized then
      if reservation.funding_source_type = 'beta_grant' then
        raise exception 'normal customer paid execution authorization is required for beta credits'
          using errcode = '42501';
      end if;
      select * into legacy_authorization
      from tongs._active_customer_paid_execution_test_authorization_for_quote(reservation.quote_id);
      if not found then
        raise exception 'customer paid execution authorization is closed or expired'
          using errcode = '42501';
      end if;
    end if;
  end if;

  return tongs._authorize_openai_text_provider_attempt_before_customer_test_scope(
    p_reservation_id,
    p_attempt_key,
    p_attempt_number,
    p_failure_exposure_micros,
    p_lease_seconds,
    p_evidence_json
  );
end $$;


ALTER FUNCTION "tongs"."authorize_openai_text_provider_attempt"("p_reservation_id" "uuid", "p_attempt_key" "text", "p_attempt_number" smallint, "p_failure_exposure_micros" bigint, "p_lease_seconds" integer, "p_evidence_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."authorize_openai_text_provider_attempt_with_aggregate"("p_reservation_id" "uuid", "p_attempt_key" "text", "p_attempt_number" smallint, "p_caller_class" "text", "p_failure_exposure_micros" bigint, "p_lease_seconds" integer, "p_evidence_json" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  aggregate_result jsonb;
  funding_result jsonb;
  normal_customer_credit_bounded boolean := false;
begin
  perform tongs._require_pricing_service_role();

  select exists (
    select 1
    from tongs.funding_reservations reservation
    join tongs.customer_paid_execution_scope_authorizations scope_auth
      on scope_auth.id = reservation.rollout_authorization_id
    where reservation.id = p_reservation_id
      and scope_auth.authorization_kind = 'normal_customer'
      and scope_auth.user_id = reservation.user_id
      and scope_auth.financial_environment = reservation.funding_environment
      and scope_auth.status = 'active'
      and scope_auth.valid_from <= now()
      and (scope_auth.valid_until is null or scope_auth.valid_until > now())
  ) into normal_customer_credit_bounded;

  if normal_customer_credit_bounded then
    aggregate_result := jsonb_build_object(
      'enforcement_enabled', false,
      'authorized', true,
      'reason', 'normal_customer_credit_bounded'
    );
  else
    if exists (
      select 1
      from tongs.openai_text_funding_bindings binding
      join tongs.openai_text_cost_policy_revisions cost_policy
        on cost_policy.id = binding.cost_policy_revision_id
      where binding.reservation_id = p_reservation_id
        and (binding.credential_funding = 'forge' or cost_policy.supporting_cost_ceiling_micros > 0)
    ) and not exists (
      select 1 from tongs.paid_operation_aggregate_bindings
      where reservation_id = p_reservation_id
    ) then
      return jsonb_build_object(
        'provider_execution_authorized', false,
        'reason', 'aggregate_admission_required'
      );
    end if;
    aggregate_result := tongs.begin_paid_operation_aggregate_attempt(
      p_reservation_id,
      p_attempt_key || ':aggregate',
      p_attempt_number,
      p_caller_class
    );
  end if;

  if coalesce((aggregate_result->>'enforcement_enabled')::boolean, false)
     and not coalesce((aggregate_result->>'authorized')::boolean, false) then
    return jsonb_build_object(
      'provider_execution_authorized', false,
      'reason', coalesce(aggregate_result->>'reason', 'aggregate_admission_denied'),
      'aggregate_enforcement_enabled', true
    );
  end if;

  funding_result := tongs.authorize_openai_text_provider_attempt(
    p_reservation_id,
    p_attempt_key,
    p_attempt_number,
    p_failure_exposure_micros,
    p_lease_seconds,
    p_evidence_json
  );

  if coalesce((aggregate_result->>'enforcement_enabled')::boolean, false)
     and not coalesce((funding_result->>'provider_execution_authorized')::boolean, false) then
    perform tongs.record_paid_operation_aggregate_outcome(
      p_reservation_id,
      p_attempt_key || ':aggregate-preprovider-release',
      'preprovider_release',
      null,
      null,
      jsonb_build_object(
        'reason', coalesce(funding_result->>'reason', 'funding_authority_denied'),
        'transmitted', false
      )
    );
  end if;

  return funding_result || jsonb_build_object(
    'aggregate_enforcement_enabled',
      coalesce((aggregate_result->>'enforcement_enabled')::boolean, false),
    'aggregate_hold_id', aggregate_result->>'hold_id',
    'aggregate_reason', aggregate_result->>'reason'
  );
end $$;


ALTER FUNCTION "tongs"."authorize_openai_text_provider_attempt_with_aggregate"("p_reservation_id" "uuid", "p_attempt_key" "text", "p_attempt_number" smallint, "p_caller_class" "text", "p_failure_exposure_micros" bigint, "p_lease_seconds" integer, "p_evidence_json" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."authorize_openai_text_provider_attempt_with_aggregate"("p_reservation_id" "uuid", "p_attempt_key" "text", "p_attempt_number" smallint, "p_caller_class" "text", "p_failure_exposure_micros" bigint, "p_lease_seconds" integer, "p_evidence_json" "jsonb") IS 'Uses the certification aggregate for certification scopes and the explicit canonical-credit authority for ongoing normal-customer scopes; the separate provider failure-loss boundary remains mandatory.';



CREATE OR REPLACE FUNCTION "tongs"."authorize_openai_text_test_certification_attempt"("p_reservation_id" "uuid", "p_attempt_key" "text", "p_attempt_number" smallint, "p_failure_exposure_micros" bigint, "p_evidence_json" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare v_res tongs.openai_text_test_certification_reservations%rowtype; v_term tongs.openai_text_test_certification_terms%rowtype; v_seq integer;
begin
  perform tongs._require_pricing_service_role(); perform pg_advisory_xact_lock(hashtextextended('openai-text-test-attempt:'||p_reservation_id::text,0));
  if exists(select 1 from tongs.openai_text_test_certification_reservation_events where event_key=p_attempt_key) then return jsonb_build_object('provider_execution_authorized',true,'real_provider_authorized',false,'replay',true); end if;
  select * into v_res from tongs.openai_text_test_certification_reservations where id=p_reservation_id; select t.* into v_term from tongs.openai_text_test_certification_terms t join tongs.openai_text_test_certification_operations o on o.term_id=t.id where o.id=v_res.operation_record_id;
  if tongs._openai_text_test_certification_reservation_state(p_reservation_id)<>'reserved' or p_attempt_number<>1 or p_failure_exposure_micros>v_term.failure_exposure_ceiling_micros then raise exception 'Test attempt denied' using errcode='42501'; end if;
  insert into tongs.openai_text_test_certification_reservation_events(id,reservation_id,sequence,event_type,event_key,evidence_json)
  values(gen_random_uuid(),p_reservation_id,2,'attempt_started',p_attempt_key,coalesce(p_evidence_json,'{}')||jsonb_build_object('real_provider_authorized',false));
  return jsonb_build_object('provider_execution_authorized',true,'real_provider_authorized',false,'replay',false);
end $$;


ALTER FUNCTION "tongs"."authorize_openai_text_test_certification_attempt"("p_reservation_id" "uuid", "p_attempt_key" "text", "p_attempt_number" smallint, "p_failure_exposure_micros" bigint, "p_evidence_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."authorize_owner_cost_provider_attempt"("p_attempt_id" "uuid", "p_operation_id" "uuid", "p_attempt_number" integer, "p_attempt_key" "text", "p_request_fingerprint" "text", "p_provider" "text", "p_service" "text", "p_model" "text", "p_sku" "text", "p_credential_identity_hash" "text", "p_private_authorization_evidence" "jsonb", "p_authorized_at" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $_$
declare
  v_key text := btrim(coalesce(p_attempt_key, ''));
  v_fingerprint text := lower(btrim(coalesce(p_request_fingerprint, '')));
  v_provider text := lower(btrim(coalesce(p_provider, '')));
  v_service text := lower(btrim(coalesce(p_service, '')));
  v_credential text := nullif(lower(btrim(coalesce(p_credential_identity_hash, ''))), '');
  v_payload jsonb;
  v_hash text;
  v_existing tongs.owner_cost_provider_attempts%rowtype;
begin
  perform tongs._require_accounting_service_role();
  if p_attempt_id is null or p_operation_id is null or p_attempt_number <= 0
     or length(v_key) not between 8 and 300 or v_fingerprint !~ '^[0-9a-f]{64}$'
     or length(v_provider) not between 2 and 80 or length(v_service) not between 2 and 100
     or (v_credential is not null and v_credential !~ '^[0-9a-f]{64}$')
     or p_authorized_at is null
     or jsonb_typeof(coalesce(p_private_authorization_evidence, '{}'::jsonb)) <> 'object' then
    raise exception 'invalid owner-cost provider attempt' using errcode = '22023';
  end if;
  if not exists (select 1 from tongs.owner_cost_operations o where o.operation_id = p_operation_id) then
    raise exception 'owner-cost operation not found' using errcode = '23503';
  end if;
  v_payload := jsonb_build_object(
    'attempt_id', p_attempt_id, 'operation_id', p_operation_id, 'attempt_number', p_attempt_number,
    'attempt_key', v_key, 'request_fingerprint', v_fingerprint, 'provider', v_provider,
    'service', v_service, 'model', nullif(btrim(coalesce(p_model, '')), ''),
    'sku', nullif(btrim(coalesce(p_sku, '')), ''), 'credential_identity_hash', v_credential,
    'private_authorization_evidence', coalesce(p_private_authorization_evidence, '{}'::jsonb),
    'authorized_at', p_authorized_at
  );
  v_hash := tongs._accounting_payload_hash(v_payload);
  perform pg_advisory_xact_lock(hashtextextended('owner-cost-attempt:' || p_operation_id::text || ':' || p_attempt_number::text, 0));
  select * into v_existing from tongs.owner_cost_provider_attempts a
    where a.attempt_id = p_attempt_id or (a.operation_id = p_operation_id and (a.attempt_number = p_attempt_number or a.attempt_key = v_key))
    limit 1;
  if found then
    if v_existing.attempt_id <> p_attempt_id or v_existing.payload_hash <> v_hash then
      raise exception 'owner-cost provider attempt replay conflict' using errcode = '23505';
    end if;
    return jsonb_build_object('attempt_id', v_existing.attempt_id, 'authorized', false, 'replay', true);
  end if;
  insert into tongs.owner_cost_provider_attempts(
    attempt_id, operation_id, attempt_number, attempt_key, request_fingerprint, payload_hash,
    provider, service, model, sku, credential_identity_hash, authorized_at
  ) values (
    p_attempt_id, p_operation_id, p_attempt_number, v_key, v_fingerprint, v_hash,
    v_provider, v_service, nullif(btrim(coalesce(p_model, '')), ''),
    nullif(btrim(coalesce(p_sku, '')), ''), v_credential, p_authorized_at
  );
  insert into tongs.owner_cost_attempt_events(
    attempt_event_id, attempt_id, event_sequence, lifecycle_state,
    private_provider_evidence, occurred_at
  ) values (
    p_attempt_id, p_attempt_id, 1, 'authorized',
    coalesce(p_private_authorization_evidence, '{}'::jsonb), p_authorized_at
  );
  return jsonb_build_object('attempt_id', p_attempt_id, 'authorized', true, 'replay', false);
end;
$_$;


ALTER FUNCTION "tongs"."authorize_owner_cost_provider_attempt"("p_attempt_id" "uuid", "p_operation_id" "uuid", "p_attempt_number" integer, "p_attempt_key" "text", "p_request_fingerprint" "text", "p_provider" "text", "p_service" "text", "p_model" "text", "p_sku" "text", "p_credential_identity_hash" "text", "p_private_authorization_evidence" "jsonb", "p_authorized_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."authorize_owner_hearth_provider_attempt_with_aggregate"("p_reservation_id" "uuid", "p_attempt_key" "text", "p_attempt_number" smallint, "p_caller_class" "text", "p_failure_exposure_micros" bigint, "p_lease_seconds" integer, "p_evidence_json" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare op tongs.owner_hearth_operation_authorizations%rowtype; authz tongs.owner_hearth_authorizations%rowtype; latest tongs.owner_hearth_authorization_events%rowtype;
 hold tongs.openai_text_failure_exposure_holds%rowtype; res tongs.funding_reservations%rowtype; aggregate_result jsonb;
 current_failure bigint; current_concurrency bigint; seq integer; lease timestamptz;
begin
 perform tongs._require_pricing_service_role();
 if p_attempt_number<>1 or p_caller_class not in ('interactive','recovery') or p_lease_seconds not between 5 and 900 then
  raise exception 'owner Hearth attempt outside authorization' using errcode='42501'; end if;
 perform pg_advisory_xact_lock(hashtextextended('owner-hearth-attempt:'||p_reservation_id::text,0));
 select * into op from tongs.owner_hearth_operation_authorizations where reservation_id=p_reservation_id;
 select * into authz from tongs.owner_hearth_authorizations where id=op.authorization_id;
 select * into latest from tongs.owner_hearth_authorization_events where authorization_id=authz.id order by sequence desc limit 1;
 select * into res from tongs.funding_reservations where id=p_reservation_id for update;
 if op.id is null or authz.id is null or latest.state<>'active' or latest.expires_at<=now() or res.id is null
   or p_failure_exposure_micros>authz.maximum_amount_micros then raise exception 'owner Hearth authorization unavailable' using errcode='42501'; end if;
 select * into hold from tongs.openai_text_failure_exposure_holds where attempt_key=btrim(p_attempt_key);
 if found then return jsonb_build_object('provider_execution_authorized',false,'replay',true,'reason','duplicate_attempt_blocked'); end if;
 select coalesce(sum(coalesce(e.actual_supplier_cost_micros,h.authorized_exposure_micros)),0) into current_failure
 from tongs.openai_text_failure_exposure_holds h join lateral(select * from tongs.openai_text_failure_exposure_events x where x.hold_id=h.id order by sequence desc limit 1)e on true
 join tongs.owner_hearth_operation_authorizations o on o.reservation_id=h.reservation_id
 where o.authorization_id=authz.id and e.event_type in ('failure_realized','unresolved');
 if current_failure+p_failure_exposure_micros>authz.failure_loss_limit_micros then raise exception 'owner Hearth failure-loss cap exhausted' using errcode='42501'; end if;
 select count(*) into current_concurrency from tongs.owner_hearth_operation_authorizations o where o.authorization_id=authz.id
   and o.reservation_id<>p_reservation_id and tongs._funding_reservation_state(o.reservation_id) in ('provider_attempt_shadowed','submission_unknown');
 if current_concurrency>=authz.maximum_concurrency then raise exception 'owner Hearth concurrency cap exhausted' using errcode='42501'; end if;
 aggregate_result:=tongs.begin_paid_operation_aggregate_attempt(p_reservation_id,p_attempt_key||':aggregate',1::smallint,p_caller_class);
 if coalesce((aggregate_result->>'enforcement_enabled')::boolean,false) and not coalesce((aggregate_result->>'authorized')::boolean,false) then
  return jsonb_build_object('provider_execution_authorized',false,'reason',aggregate_result->>'reason','aggregate_enforcement_enabled',true); end if;
 insert into tongs.openai_text_failure_exposure_holds(id,reservation_id,route_code,attempt_key,attempt_number,loss_policy_revision_id,
  authorized_exposure_micros,lease_expires_at)
 values(gen_random_uuid(),p_reservation_id,'hearth.chat_completion',btrim(p_attempt_key),1,null,p_failure_exposure_micros,now()+make_interval(secs=>p_lease_seconds)) returning * into hold;
 insert into tongs.openai_text_failure_exposure_events(id,hold_id,sequence,event_key,event_type,evidence_json)
 values(gen_random_uuid(),hold.id,1,btrim(p_attempt_key)||':loss-authorized','authorized',coalesce(p_evidence_json,'{}'::jsonb));
 if tongs._funding_reservation_state(res.id)<>'reserved' then raise exception 'owner Hearth reservation is not attemptable' using errcode='42501'; end if;
 select coalesce(max(sequence),0)+1 into seq from tongs.funding_reservation_events where reservation_id=res.id;
 lease:=now()+make_interval(secs=>p_lease_seconds);
 insert into tongs.funding_reservation_events(id,reservation_id,sequence,event_type,event_key,provider_attempt_key,lease_expires_at,evidence_json)
 values(gen_random_uuid(),res.id,seq,'provider_attempt_shadowed','reservation:'||res.id::text||':attempt:'||btrim(p_attempt_key),btrim(p_attempt_key),lease,
  coalesce(p_evidence_json,'{}'::jsonb)||jsonb_build_object('owner_hearth_authorization_id',authz.id,'isolated_credential_required',true));
 return jsonb_build_object('provider_execution_authorized',true,'reason','owner_hearth_authorized','replay',false,
  'failure_exposure_hold_id',hold.id,'aggregate_hold_id',aggregate_result->>'hold_id','lease_expires_at',lease);
end $$;


ALTER FUNCTION "tongs"."authorize_owner_hearth_provider_attempt_with_aggregate"("p_reservation_id" "uuid", "p_attempt_key" "text", "p_attempt_number" smallint, "p_caller_class" "text", "p_failure_exposure_micros" bigint, "p_lease_seconds" integer, "p_evidence_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."authorize_owner_hearth_research_openai_attempt"("p_reservation_id" "uuid", "p_attempt_key" "text", "p_attempt_number" smallint, "p_caller_class" "text", "p_failure_exposure_micros" bigint, "p_lease_seconds" integer, "p_evidence_json" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare o tongs.owner_hearth_research_operations%rowtype; hold tongs.openai_text_failure_exposure_holds%rowtype; aggregate_result jsonb; seq int; lease timestamptz;
begin
 perform tongs._require_pricing_service_role(); perform pg_advisory_xact_lock(hashtextextended('owner-research-openai:'||p_reservation_id::text,0));
 select * into o from tongs.owner_hearth_research_operations where reservation_id=p_reservation_id;
 select * into hold from tongs.openai_text_failure_exposure_holds where attempt_key=btrim(p_attempt_key);
 if found then return jsonb_build_object('provider_execution_authorized',false,'replay',true,'reason','duplicate_attempt_blocked'); end if;
 if o.id is null or p_attempt_number<>1 or p_failure_exposure_micros>o.full_cost_ceiling_micros+3 or now()>=o.execution_deadline_at
  or not exists(select 1 from tongs.owner_hearth_research_frozen_requests where reservation_id=p_reservation_id) then raise exception 'research OpenAI attempt not authorized' using errcode='42501'; end if;
 aggregate_result:=tongs.begin_paid_operation_aggregate_attempt(p_reservation_id,p_attempt_key||':aggregate',1,p_caller_class);
 if coalesce((aggregate_result->>'enforcement_enabled')::boolean,false) and not coalesce((aggregate_result->>'authorized')::boolean,false) then
  return jsonb_build_object('provider_execution_authorized',false,'reason',aggregate_result->>'reason'); end if;
 insert into tongs.openai_text_failure_exposure_holds(id,reservation_id,route_code,attempt_key,attempt_number,loss_policy_revision_id,authorized_exposure_micros,lease_expires_at)
 values(gen_random_uuid(),p_reservation_id,'hearth.research_synthesis',btrim(p_attempt_key),1,null,p_failure_exposure_micros,now()+make_interval(secs=>p_lease_seconds)) returning * into hold;
 insert into tongs.openai_text_failure_exposure_events(id,hold_id,sequence,event_key,event_type,actual_supplier_cost_micros,evidence_json)
 values(gen_random_uuid(),hold.id,1,btrim(p_attempt_key)||':loss-authorized','authorized',null,coalesce(p_evidence_json,'{}'));
 select coalesce(max(sequence),0)+1 into seq from tongs.funding_reservation_events where reservation_id=p_reservation_id; lease:=now()+make_interval(secs=>p_lease_seconds);
 insert into tongs.funding_reservation_events(id,reservation_id,sequence,event_type,event_key,provider_attempt_key,lease_expires_at,evidence_json)
 values(gen_random_uuid(),p_reservation_id,seq,'provider_attempt_shadowed','owner-research:'||p_reservation_id::text||':openai',btrim(p_attempt_key),lease,
  coalesce(p_evidence_json,'{}')||'{"customer_charge_micros":0,"duplicate_submission_prohibited":true}');
 return jsonb_build_object('provider_execution_authorized',true,'replay',false,'failure_exposure_hold_id',hold.id,'lease_expires_at',lease);
end $$;


ALTER FUNCTION "tongs"."authorize_owner_hearth_research_openai_attempt"("p_reservation_id" "uuid", "p_attempt_key" "text", "p_attempt_number" smallint, "p_caller_class" "text", "p_failure_exposure_micros" bigint, "p_lease_seconds" integer, "p_evidence_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."authorize_runway_submission"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_submission_attempt_id" "text", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_model" "text", "p_duration_seconds" integer, "p_ratio" "text", "p_evidence_json" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $_$
declare
  v_operation text := nullif(btrim(coalesce(p_operation_id, '')), '');
  v_attempt text := nullif(btrim(coalesce(p_submission_attempt_id, '')), '');
  v_rollout tongs.runway_execution_rollout_revisions%rowtype;
  v_binding tongs.runway_funding_bindings%rowtype;
  v_reservation tongs.funding_reservations%rowtype;
  v_existing tongs.runway_submission_boundary_events%rowtype;
  v_attempt_result jsonb;
  v_decision text;
  v_reason text;
  v_authorized boolean := false;
  v_legacy_allowed boolean := false;
begin
  perform tongs._require_pricing_service_role();
  if v_operation is null or p_operation_fingerprint !~ '^[0-9a-f]{64}$'
     or v_attempt is null or p_user_id is null or p_workspace_id is null
     or p_model <> 'gen4.5' or p_duration_seconds not between 2 and 10
     or p_ratio not in ('1280:720', '720:1280')
     or jsonb_typeof(coalesce(p_evidence_json, 'null'::jsonb)) <> 'object' then
    raise exception 'invalid Runway submission authorization' using errcode = '22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('runway-submit:' || v_operation, 0));
  select * into v_rollout from tongs._current_runway_execution_rollout();
  select * into v_existing from tongs.runway_submission_boundary_events
  where (operation_id = v_operation or submission_attempt_id = v_attempt)
    and decision in ('legacy_observed', 'funded_authorized')
  order by created_at desc limit 1;
  if found then
    insert into tongs.runway_submission_boundary_events(
      id, operation_id, operation_fingerprint, submission_attempt_id, rollout_revision,
      reservation_id, decision, reason, evidence_json
    ) values (
      gen_random_uuid(), v_operation, p_operation_fingerprint, v_attempt, v_rollout.revision,
      v_existing.reservation_id, 'duplicate_blocked', 'duplicate paid submission boundary attempt',
      coalesce(p_evidence_json, '{}'::jsonb)
    );
    return jsonb_build_object('mode', v_rollout.mode, 'rollout_revision', v_rollout.revision,
      'provider_execution_authorized', false, 'legacy_execution_allowed', false,
      'reason', 'duplicate_attempt', 'replay', true,
      'reservation_id', v_existing.reservation_id);
  end if;
  if v_rollout.mode = 'halt_new' then
    v_decision := 'halted';
    v_reason := 'new Runway submissions are halted; polling and reconciliation remain available';
  elsif v_rollout.mode = 'observe' then
    v_decision := 'legacy_observed';
    v_reason := 'legacy Runway execution observed before approved cutover';
    v_legacy_allowed := true;
  else
    select * into v_binding from tongs.runway_funding_bindings where operation_id = v_operation;
    if not found or v_binding.operation_fingerprint <> p_operation_fingerprint
       or v_binding.user_id <> p_user_id or v_binding.workspace_id <> p_workspace_id
       or v_binding.model <> p_model or v_binding.duration_seconds <> p_duration_seconds
       or v_binding.ratio <> p_ratio then
      v_decision := 'unfunded_blocked';
      v_reason := 'matching full-cost funding reservation required';
    else
      select * into v_reservation from tongs.funding_reservations where id = v_binding.reservation_id;
      if v_reservation.funding_source_type = 'owner_budget' then
        v_attempt_result := tongs.begin_owner_provider_attempt(
          v_binding.reservation_id, v_attempt, 120,
          coalesce(p_evidence_json, '{}'::jsonb) || jsonb_build_object(
            'provider', 'runway', 'model', p_model, 'operation_id', v_operation)
        );
      else
        v_attempt_result := tongs.begin_provider_attempt(
          v_binding.reservation_id, v_attempt, 120,
          coalesce(p_evidence_json, '{}'::jsonb) || jsonb_build_object(
            'provider', 'runway', 'model', p_model, 'operation_id', v_operation)
        );
      end if;
      v_authorized := coalesce((v_attempt_result->>'provider_execution_authorized')::boolean, false);
      v_decision := case when v_authorized then 'funded_authorized' else 'duplicate_blocked' end;
      v_reason := coalesce(v_attempt_result->>'reason', 'funding gate denied provider attempt');
    end if;
  end if;
  insert into tongs.runway_submission_boundary_events(
    id, operation_id, operation_fingerprint, submission_attempt_id, rollout_revision,
    reservation_id, decision, reason, lease_expires_at, evidence_json
  ) values (
    gen_random_uuid(), v_operation, p_operation_fingerprint, v_attempt, v_rollout.revision,
    v_binding.reservation_id, v_decision, v_reason,
    case when v_attempt_result ? 'lease_expires_at' then (v_attempt_result->>'lease_expires_at')::timestamptz else null end,
    coalesce(p_evidence_json, '{}'::jsonb)
  );
  return jsonb_build_object('mode', v_rollout.mode, 'rollout_revision', v_rollout.revision,
    'provider_execution_authorized', v_authorized,
    'legacy_execution_allowed', v_legacy_allowed,
    'reason', v_reason, 'replay', false,
    'reservation_id', v_binding.reservation_id,
    'funding_source_type', v_reservation.funding_source_type);
end;
$_$;


ALTER FUNCTION "tongs"."authorize_runway_submission"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_submission_attempt_id" "text", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_model" "text", "p_duration_seconds" integer, "p_ratio" "text", "p_evidence_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."authorize_runway_submission_with_aggregate"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_submission_attempt_id" "text", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_model" "text", "p_duration_seconds" integer, "p_ratio" "text", "p_caller_class" "text", "p_evidence_json" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  rollout tongs.runway_execution_rollout_revisions%rowtype;
  admission jsonb;
  aggregate_attempt jsonb;
  result jsonb;
  reservation uuid;
begin
  perform tongs._require_pricing_service_role();
  select * into rollout from tongs._current_runway_execution_rollout();
  if rollout.mode<>'enforce' then
    return tongs.authorize_runway_submission(
      p_operation_id,p_operation_fingerprint,p_submission_attempt_id,
      p_user_id,p_workspace_id,p_model,p_duration_seconds,p_ratio,p_evidence_json);
  end if;

  admission:=tongs.acquire_runway_aggregate_admission(
    p_operation_id,p_operation_fingerprint,p_user_id,p_workspace_id,
    p_caller_class,'real');
  if coalesce((admission->>'enforcement_enabled')::boolean,false)
     and not coalesce((admission->>'authorized')::boolean,false) then
    select reservation_id into reservation
    from tongs.runway_funding_bindings where operation_id=btrim(p_operation_id);
    if reservation is not null then
      perform tongs.release_operation(
        reservation,
        p_submission_attempt_id||':aggregate-admission-denied-release',
        coalesce(admission->>'reason','aggregate_admission_denied'),
        jsonb_build_object('transmitted',false,'aggregate_admission_denied',true));
    end if;
    return jsonb_build_object(
      'mode',rollout.mode,
      'rollout_revision',rollout.revision,
      'provider_execution_authorized',false,
      'legacy_execution_allowed',false,
      'reason',admission->>'reason',
      'replay',false,
      'reservation_id',null,
      'aggregate_enforcement_enabled',true);
  end if;

  select reservation_id into reservation
  from tongs.runway_funding_bindings where operation_id=btrim(p_operation_id);
  aggregate_attempt:=tongs.begin_paid_operation_aggregate_attempt(
    reservation,p_submission_attempt_id||':aggregate',1::smallint,p_caller_class);
  if coalesce((aggregate_attempt->>'enforcement_enabled')::boolean,false)
     and not coalesce((aggregate_attempt->>'authorized')::boolean,false) then
    return jsonb_build_object(
      'mode',rollout.mode,
      'rollout_revision',rollout.revision,
      'provider_execution_authorized',false,
      'legacy_execution_allowed',false,
      'reason',aggregate_attempt->>'reason',
      'replay',coalesce((aggregate_attempt->>'replay')::boolean,false),
      'reservation_id',reservation,
      'aggregate_enforcement_enabled',true);
  end if;

  result:=tongs.authorize_runway_submission(
    p_operation_id,p_operation_fingerprint,p_submission_attempt_id,
    p_user_id,p_workspace_id,p_model,p_duration_seconds,p_ratio,p_evidence_json);
  if coalesce((aggregate_attempt->>'enforcement_enabled')::boolean,false)
     and not coalesce((result->>'provider_execution_authorized')::boolean,false) then
    perform tongs.record_paid_operation_aggregate_outcome(
      reservation,
      p_submission_attempt_id||':aggregate-preprovider-release',
      'preprovider_release',null,null,
      jsonb_build_object(
        'reason',coalesce(result->>'reason','funding_authority_denied'),
        'transmitted',false));
  end if;
  return result||jsonb_build_object(
    'aggregate_enforcement_enabled',
      coalesce((aggregate_attempt->>'enforcement_enabled')::boolean,false),
    'aggregate_hold_id',aggregate_attempt->>'hold_id');
end $$;


ALTER FUNCTION "tongs"."authorize_runway_submission_with_aggregate"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_submission_attempt_id" "text", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_model" "text", "p_duration_seconds" integer, "p_ratio" "text", "p_caller_class" "text", "p_evidence_json" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."authorize_runway_submission_with_aggregate"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_submission_attempt_id" "text", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_model" "text", "p_duration_seconds" integer, "p_ratio" "text", "p_caller_class" "text", "p_evidence_json" "jsonb") IS 'Service-only transactional Runway funding and aggregate boundary. The aggregate attempt ordinal is explicitly smallint; no provider call occurs inside this database function.';



CREATE OR REPLACE FUNCTION "tongs"."barstock_advance_revision"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
begin
  new.revision := old.revision + 1;
  return new;
end;
$$;


ALTER FUNCTION "tongs"."barstock_advance_revision"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."barstock_apply_assignment"("p_row" "jsonb", "p_expected_revision" bigint DEFAULT NULL::bigint, "p_import_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare
  v_workspace_id uuid := nullif(p_row->>'workspace_id', '')::uuid;
  v_id uuid := nullif(p_row->>'id', '')::uuid;
  v_existing tongs.barstock_assignments%rowtype;
begin
  if auth.uid() is null or v_workspace_id is null
    or not tongs.has_workspace_role(v_workspace_id, 'editor') then
    return jsonb_build_object('outcome', 'denied', 'row', null);
  end if;
  if v_id is null or nullif(btrim(p_row->>'title'), '') is null then
    raise invalid_parameter_value using message = 'Assignment id and title are required.';
  end if;

  if p_expected_revision is null then
    insert into tongs.barstock_assignments (
      id, workspace_id, created_by, title, status, import_key
    ) values (
      v_id, v_workspace_id, auth.uid(), btrim(p_row->>'title'),
      coalesce(nullif(p_row->>'status', ''), 'open'), nullif(p_import_key, '')
    )
    on conflict do nothing
    returning * into v_existing;

    if found then
      return jsonb_build_object('outcome', 'saved', 'row', to_jsonb(v_existing));
    end if;

    select * into v_existing from tongs.barstock_assignments
    where workspace_id = v_workspace_id and id = v_id;
    if found and (p_import_key is null or v_existing.import_key is not distinct from nullif(p_import_key, '')) then
      return jsonb_build_object('outcome', 'duplicate', 'row', to_jsonb(v_existing));
    end if;

    if p_import_key is not null and exists (
      select 1 from tongs.barstock_assignments
      where workspace_id = v_workspace_id and import_key = nullif(p_import_key, '')
    ) then
      return jsonb_build_object('outcome', 'conflict', 'row', null);
    end if;
    return jsonb_build_object('outcome', 'conflict', 'row', null);
  end if;

  update tongs.barstock_assignments
  set title = coalesce(nullif(btrim(p_row->>'title'), ''), title),
      status = coalesce(nullif(p_row->>'status', ''), status)
  where workspace_id = v_workspace_id
    and id = v_id
    and revision = p_expected_revision
  returning * into v_existing;

  if found then
    return jsonb_build_object('outcome', 'saved', 'row', to_jsonb(v_existing));
  end if;

  select * into v_existing from tongs.barstock_assignments
  where workspace_id = v_workspace_id and id = v_id;
  return case when found
    then jsonb_build_object('outcome', 'stale', 'row', to_jsonb(v_existing))
    else jsonb_build_object('outcome', 'not_found', 'row', null)
  end;
end;
$$;


ALTER FUNCTION "tongs"."barstock_apply_assignment"("p_row" "jsonb", "p_expected_revision" bigint, "p_import_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."barstock_apply_spark"("p_row" "jsonb", "p_expected_revision" bigint DEFAULT NULL::bigint, "p_import_key" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare
  v_workspace_id uuid := nullif(p_row->>'workspace_id', '')::uuid;
  v_id uuid := nullif(p_row->>'id', '')::uuid;
  v_existing tongs.barstock_sparks%rowtype;
begin
  if auth.uid() is null or v_workspace_id is null
    or not tongs.has_workspace_role(v_workspace_id, 'editor') then
    return jsonb_build_object('outcome', 'denied', 'row', null);
  end if;
  if v_id is null or nullif(btrim(p_row->>'body'), '') is null then
    raise invalid_parameter_value using message = 'Spark id and body are required.';
  end if;

  if p_expected_revision is null then
    insert into tongs.barstock_sparks (
      id, workspace_id, created_by, assignment_id, title, body, tags,
      status, source, pinned, import_key
    ) values (
      v_id, v_workspace_id, auth.uid(), nullif(p_row->>'assignment_id', '')::uuid,
      nullif(p_row->>'title', ''), p_row->>'body',
      coalesce(array(select jsonb_array_elements_text(coalesce(p_row->'tags', '[]'::jsonb))), '{}'::text[]),
      coalesce(nullif(p_row->>'status', ''), 'raw'),
      coalesce(nullif(p_row->>'source', ''), 'typed'),
      coalesce((p_row->>'pinned')::boolean, false), nullif(p_import_key, '')
    )
    on conflict do nothing
    returning * into v_existing;

    if found then
      return jsonb_build_object('outcome', 'saved', 'row', to_jsonb(v_existing));
    end if;

    select * into v_existing from tongs.barstock_sparks
    where workspace_id = v_workspace_id and id = v_id;
    if found and (p_import_key is null or v_existing.import_key is not distinct from nullif(p_import_key, '')) then
      return jsonb_build_object('outcome', 'duplicate', 'row', to_jsonb(v_existing));
    end if;

    if p_import_key is not null and exists (
      select 1 from tongs.barstock_sparks
      where workspace_id = v_workspace_id and import_key = nullif(p_import_key, '')
    ) then
      return jsonb_build_object('outcome', 'conflict', 'row', null);
    end if;
    return jsonb_build_object('outcome', 'conflict', 'row', null);
  end if;

  update tongs.barstock_sparks
  set assignment_id = case when p_row ? 'assignment_id' then nullif(p_row->>'assignment_id', '')::uuid else assignment_id end,
      title = case when p_row ? 'title' then nullif(p_row->>'title', '') else title end,
      body = coalesce(nullif(p_row->>'body', ''), body),
      tags = case when p_row ? 'tags' then array(select jsonb_array_elements_text(p_row->'tags')) else tags end,
      status = coalesce(nullif(p_row->>'status', ''), status),
      source = coalesce(nullif(p_row->>'source', ''), source),
      pinned = case when p_row ? 'pinned' then (p_row->>'pinned')::boolean else pinned end
  where workspace_id = v_workspace_id and id = v_id and revision = p_expected_revision
  returning * into v_existing;

  if found then
    return jsonb_build_object('outcome', 'saved', 'row', to_jsonb(v_existing));
  end if;
  select * into v_existing from tongs.barstock_sparks
  where workspace_id = v_workspace_id and id = v_id;
  return case when found
    then jsonb_build_object('outcome', 'stale', 'row', to_jsonb(v_existing))
    else jsonb_build_object('outcome', 'not_found', 'row', null)
  end;
end;
$$;


