CREATE OR REPLACE FUNCTION "tongs"."barstock_archive_assignment"("p_workspace_id" "uuid", "p_id" "uuid", "p_expected_revision" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare v_existing tongs.barstock_assignments%rowtype;
begin
  if auth.uid() is null or not tongs.has_workspace_role(p_workspace_id, 'editor') then
    return jsonb_build_object('outcome', 'denied', 'row', null);
  end if;
  update tongs.barstock_assignments set status = 'archived'
  where workspace_id = p_workspace_id and id = p_id and revision = p_expected_revision
  returning * into v_existing;
  if found then return jsonb_build_object('outcome', 'saved', 'row', to_jsonb(v_existing)); end if;
  select * into v_existing from tongs.barstock_assignments where workspace_id = p_workspace_id and id = p_id;
  return case when found then jsonb_build_object('outcome', 'stale', 'row', to_jsonb(v_existing))
    else jsonb_build_object('outcome', 'not_found', 'row', null) end;
end;
$$;


ALTER FUNCTION "tongs"."barstock_archive_assignment"("p_workspace_id" "uuid", "p_id" "uuid", "p_expected_revision" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."barstock_archive_project_graduates_sparks"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'tongs', 'pg_temp'
    AS $$
begin
  -- Only when transitioning to archived
  if (tg_op = 'UPDATE')
     and (old.status is distinct from new.status)
     and (new.status = 'archived') then

    update tongs.barstock_sparks s
       set status = 'graduated',
           updated_at = now()
     where s.assignment_id = new.id
       and coalesce(s.status, 'active') <> 'graduated';

  end if;

  -- One-way door: prevent un-archiving
  if (tg_op = 'UPDATE')
     and (old.status is distinct from new.status)
     and (old.status = 'archived')
     and (new.status <> 'archived') then
    raise exception using
      errcode = '23514',
      message = 'Cannot un-archive (un-graduate) a Project once archived.';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "tongs"."barstock_archive_project_graduates_sparks"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."barstock_archive_spark"("p_workspace_id" "uuid", "p_id" "uuid", "p_expected_revision" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare v_existing tongs.barstock_sparks%rowtype;
begin
  if auth.uid() is null or not tongs.has_workspace_role(p_workspace_id, 'editor') then
    return jsonb_build_object('outcome', 'denied', 'row', null);
  end if;
  update tongs.barstock_sparks set status = 'archived', deleted_at = now()
  where workspace_id = p_workspace_id and id = p_id and revision = p_expected_revision
  returning * into v_existing;
  if found then return jsonb_build_object('outcome', 'saved', 'row', to_jsonb(v_existing)); end if;
  select * into v_existing from tongs.barstock_sparks where workspace_id = p_workspace_id and id = p_id;
  return case when found then jsonb_build_object('outcome', 'stale', 'row', to_jsonb(v_existing))
    else jsonb_build_object('outcome', 'not_found', 'row', null) end;
end;
$$;


ALTER FUNCTION "tongs"."barstock_archive_spark"("p_workspace_id" "uuid", "p_id" "uuid", "p_expected_revision" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."barstock_delete_assignment"("p_workspace_id" "uuid", "p_id" "uuid", "p_expected_revision" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare v_existing tongs.barstock_assignments%rowtype;
begin
  if auth.uid() is null or not tongs.has_workspace_role(p_workspace_id, 'admin') then
    return jsonb_build_object('outcome', 'denied', 'row', null);
  end if;
  if exists (select 1 from tongs.barstock_project_episode_links where workspace_id = p_workspace_id and project_id = p_id) then
    return jsonb_build_object('outcome', 'linked', 'row', null);
  end if;
  delete from tongs.barstock_assignments
  where workspace_id = p_workspace_id and id = p_id and revision = p_expected_revision
  returning * into v_existing;
  if found then return jsonb_build_object('outcome', 'deleted', 'row', to_jsonb(v_existing)); end if;
  select * into v_existing from tongs.barstock_assignments where workspace_id = p_workspace_id and id = p_id;
  return case when found then jsonb_build_object('outcome', 'stale', 'row', to_jsonb(v_existing))
    else jsonb_build_object('outcome', 'not_found', 'row', null) end;
end;
$$;


ALTER FUNCTION "tongs"."barstock_delete_assignment"("p_workspace_id" "uuid", "p_id" "uuid", "p_expected_revision" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."barstock_discovery_next_eligible_at"("p_workspace_id" "uuid", "p_user_id" "uuid") RETURNS timestamp with time zone
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
  with recent as (
    select first_provider_call_at
    from tongs.barstock_discovery_runs
    where workspace_id = p_workspace_id
      and user_id = p_user_id
      and first_provider_call_at > now() - interval '24 hours'
  ),
  boundaries as (
    select
      case
        when count(*) filter (
          where first_provider_call_at > now() - interval '6 hours'
        ) >= 1
          then max(first_provider_call_at) filter (
            where first_provider_call_at > now() - interval '6 hours'
          ) + interval '6 hours'
        else null
      end as six_hour_boundary,
      case
        when count(*) >= 4
          then (
            select first_provider_call_at + interval '24 hours'
            from recent
            order by first_provider_call_at desc
            offset 3
            limit 1
          )
        else null
      end as twenty_four_hour_boundary
    from recent
  )
  select case
    when six_hour_boundary is null then twenty_four_hour_boundary
    when twenty_four_hour_boundary is null then six_hour_boundary
    else greatest(six_hour_boundary, twenty_four_hour_boundary)
  end
  from boundaries;
$$;


ALTER FUNCTION "tongs"."barstock_discovery_next_eligible_at"("p_workspace_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."barstock_project_episode_links_enforce_workspace"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare
  v_project_workspace uuid;
  v_episode_workspace uuid;
begin
  select a.workspace_id
  into v_project_workspace
  from tongs.barstock_assignments a
  where a.id = new.project_id;

  if v_project_workspace is null then
    raise exception 'Bar Stock project not found for link'
      using errcode = '23503';
  end if;

  select e.workspace_id
  into v_episode_workspace
  from tongs.episodes e
  where e.id = new.workpiece_id;

  if v_episode_workspace is null then
    raise exception 'Episode/workpiece not found for link'
      using errcode = '23503';
  end if;

  if new.workspace_id is null then
    new.workspace_id := v_project_workspace;
  end if;

  if new.workspace_id <> v_project_workspace or new.workspace_id <> v_episode_workspace then
    raise exception 'Project/workpiece link workspace mismatch'
      using errcode = '22023';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "tongs"."barstock_project_episode_links_enforce_workspace"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."barstock_sparks_enforce_workspace"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare
  v_assignment_workspace uuid;
begin
  if new.assignment_id is null then
    return new;
  end if;

  select a.workspace_id
  into v_assignment_workspace
  from tongs.barstock_assignments a
  where a.id = new.assignment_id;

  if v_assignment_workspace is null then
    raise exception 'Bar Stock project not found for spark assignment'
      using errcode = '23503';
  end if;

  if new.workspace_id is null then
    new.workspace_id := v_assignment_workspace;
  end if;

  if new.workspace_id <> v_assignment_workspace then
    raise exception 'Spark/project workspace mismatch'
      using errcode = '22023';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "tongs"."barstock_sparks_enforce_workspace"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."begin_bellows_hammer_handoff"("p_package_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare p tongs.bellows_capture_packages; r tongs.bellows_hammer_handoff_receipts;
begin
  select * into p from tongs.bellows_capture_packages where id=p_package_id;
  if not found then return jsonb_build_object('outcome','package_not_found'); end if;
  if not tongs.has_workspace_role(p.workspace_id,'editor') then return jsonb_build_object('outcome','denied'); end if;
  select * into r from tongs.bellows_hammer_handoff_receipts where package_id=p.id for update;
  if found then return jsonb_build_object('outcome',case when r.state='committed' then 'committed' else 'resumable' end,'receipt',to_jsonb(r)); end if;
  insert into tongs.bellows_hammer_handoff_receipts(package_id,workspace_id,workpiece_id,operation_id,created_by)
  values(p.id,p.workspace_id,p.workpiece_id,gen_random_uuid(),auth.uid()) returning * into r;
  return jsonb_build_object('outcome','pending','receipt',to_jsonb(r));
end $$;


ALTER FUNCTION "tongs"."begin_bellows_hammer_handoff"("p_package_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."begin_broll_operation"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_beat_id" "uuid", "p_operation_type" "text", "p_operation_id" "text", "p_operation_fingerprint" "text", "p_inputs" "jsonb", "p_actor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare
  v_op tongs.broll_operation_receipts%rowtype;
  v_generation_request_id uuid;
begin
  if not tongs.has_workspace_role(p_workspace_id,'editor') then
    raise exception 'workspace editor authority required' using errcode='42501';
  end if;
  if auth.uid() is distinct from p_actor_id then
    raise exception 'operation actor must match authenticated creator' using errcode='42501';
  end if;
  if p_operation_type='candidate_acquire'
     and p_inputs->>'source_kind'='generated'
     and nullif(p_inputs->>'generation_request_id','') is not null then
    begin
      v_generation_request_id:=(p_inputs->>'generation_request_id')::uuid;
    exception when invalid_text_representation then
      raise exception 'invalid generation request identity' using errcode='22023';
    end;
    if not exists(
      select 1 from tongs.broll_generation_attempts attempt
      where attempt.generation_request_id=v_generation_request_id
        and attempt.workspace_id=p_workspace_id and attempt.workpiece_id=p_workpiece_id
        and attempt.beat_id=p_beat_id and attempt.operation_id=p_operation_id
        and attempt.operation_fingerprint=p_operation_fingerprint
        and attempt.initiated_by=p_actor_id
        and attempt.prompt_revision_id=(p_inputs->>'prompt_revision_id')::uuid
        and attempt.prompt_revision=(p_inputs->>'prompt_revision')::bigint
        and attempt.prompt_content_hash=p_inputs->>'prompt_content_hash'
        and attempt.creative_input_hash=p_inputs->>'creative_input_hash'
    ) then
      raise exception 'generation request does not authorize this operation identity' using errcode='42501';
    end if;
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_operation_id,0));
  select * into v_op from tongs.broll_operation_receipts where operation_id=p_operation_id for update;
  if found then
    if v_op.operation_fingerprint<>p_operation_fingerprint
       or v_op.workspace_id<>p_workspace_id or v_op.workpiece_id<>p_workpiece_id
       or v_op.beat_id is distinct from p_beat_id or v_op.operation_type<>p_operation_type then
      return jsonb_build_object('disposition','operation_identity_conflict');
    end if;
    if v_op.state='failed' then
      if tongs._is_terminal_customer_runway_preprovider_failure(v_op.operation_id) then
        return jsonb_build_object(
          'disposition','terminal_failure_replay','operation',to_jsonb(v_op),
          'replacement_allowed',exists(
            select 1 from tongs.broll_generation_replacement_scopes scope
            where scope.original_operation_id=v_op.operation_id
              and scope.user_id=p_actor_id and scope.valid_until>clock_timestamp()
          ),'transmitted',false,'customer_charge_micros',0
        );
      end if;
      update tongs.broll_operation_receipts set
        state=case
          when verified_poster_asset_id is not null then 'poster_asset_verified'
          when verified_asset_id is not null then 'video_asset_verified'
          when provider_response_json is not null then 'provider_or_upload_completed'
          else 'pending' end,
        failed_stage=null,failure_code=null,failure_message=null,updated_at=now()
      where operation_id=p_operation_id returning * into v_op;
    end if;
    return jsonb_build_object('disposition','replay','operation',to_jsonb(v_op));
  end if;
  insert into tongs.broll_operation_receipts(
    operation_id,operation_fingerprint,operation_type,state,workspace_id,
    workpiece_id,beat_id,normalized_inputs_json,created_by
  ) values(
    p_operation_id,p_operation_fingerprint,p_operation_type,'pending',p_workspace_id,
    p_workpiece_id,p_beat_id,p_inputs,p_actor_id
  ) returning * into v_op;
  return jsonb_build_object('disposition','reserved','operation',to_jsonb(v_op));
end $$;


ALTER FUNCTION "tongs"."begin_broll_operation"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_beat_id" "uuid", "p_operation_type" "text", "p_operation_id" "text", "p_operation_fingerprint" "text", "p_inputs" "jsonb", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."begin_broll_prompt_interpretation"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_beat_id" "uuid", "p_expected_prompt_revision_id" "uuid", "p_expected_prompt_revision" bigint, "p_creator_direction" "text", "p_creative_input_hash" "text", "p_interpretation_contract_version" "text", "p_validator_version" "text", "p_synthesis_contract_version" "text", "p_interpretation_provider" "text", "p_interpretation_model" "text", "p_interpretation_request" "jsonb", "p_operation_id" "text", "p_operation_fingerprint" "text", "p_actor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare v_seq tongs.broll_prompt_sequences%rowtype; v_current jsonb; v_inputs jsonb; v_op tongs.broll_operation_receipts%rowtype;
begin
 if not tongs.has_workspace_role(p_workspace_id,'editor') then raise exception 'workspace editor authority required' using errcode='42501'; end if;
 if auth.uid() is distinct from p_actor_id then raise exception 'operation actor must match authenticated creator' using errcode='42501'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_operation_id,0));
 select * into v_op from tongs.broll_operation_receipts where operation_id=p_operation_id for update;
 if found then
  if v_op.operation_fingerprint<>p_operation_fingerprint or v_op.workspace_id<>p_workspace_id or v_op.workpiece_id<>p_workpiece_id or v_op.beat_id is distinct from p_beat_id or v_op.operation_type<>'prompt_interpretation' then
   return jsonb_build_object('disposition','operation_identity_conflict');
  end if;
  if v_op.state='failed' then
   update tongs.broll_operation_receipts set state=case when provider_response_json is not null then 'provider_or_upload_completed' else 'pending' end,failed_stage=null,failure_code=null,failure_message=null,updated_at=now() where operation_id=p_operation_id returning * into v_op;
  end if;
  return jsonb_build_object('disposition','replay','operation',to_jsonb(v_op));
 end if;
 insert into tongs.broll_prompt_sequences(workspace_id,workpiece_id,beat_id) values(p_workspace_id,p_workpiece_id,p_beat_id) on conflict do nothing;
 select * into v_seq from tongs.broll_prompt_sequences where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and beat_id=p_beat_id for update;
 if v_seq.current_prompt_revision<>p_expected_prompt_revision or v_seq.current_prompt_revision_id is distinct from p_expected_prompt_revision_id then
  return jsonb_build_object('disposition','prompt_revision_conflict','current_revision_id',v_seq.current_prompt_revision_id,'current_revision',v_seq.current_prompt_revision);
 end if;
 v_current:=tongs.broll_current_creative_input(p_workspace_id,p_workpiece_id,p_beat_id,p_creator_direction,p_interpretation_contract_version,p_synthesis_contract_version);
 if v_current->>'disposition'<>'current' then return jsonb_build_object('disposition',v_current->>'disposition'); end if;
 if v_current->>'creative_input_hash' is distinct from p_creative_input_hash then return jsonb_build_object('disposition','creative_input_conflict','current_creative_input_hash',v_current->>'creative_input_hash'); end if;
 if coalesce(p_validator_version,'')='' or coalesce(p_interpretation_provider,'')='' or coalesce(p_interpretation_model,'')='' then return jsonb_build_object('disposition','interpretation_contract_incomplete'); end if;
 v_inputs:=jsonb_build_object(
  'expected_prompt_revision_id',p_expected_prompt_revision_id,'expected_prompt_revision',p_expected_prompt_revision,
  'creator_direction',coalesce(p_creator_direction,''),'creative_input_hash',p_creative_input_hash,
  'interpretation_contract_version',p_interpretation_contract_version,'validator_version',p_validator_version,
  'synthesis_contract_version',p_synthesis_contract_version,'interpretation_provider',p_interpretation_provider,
  'interpretation_model',p_interpretation_model,'interpretation_request',coalesce(p_interpretation_request,'{}'::jsonb)
 );
 return tongs.begin_broll_operation(p_workspace_id,p_workpiece_id,p_beat_id,'prompt_interpretation',p_operation_id,p_operation_fingerprint,v_inputs,p_actor_id);
end $$;


ALTER FUNCTION "tongs"."begin_broll_prompt_interpretation"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_beat_id" "uuid", "p_expected_prompt_revision_id" "uuid", "p_expected_prompt_revision" bigint, "p_creator_direction" "text", "p_creative_input_hash" "text", "p_interpretation_contract_version" "text", "p_validator_version" "text", "p_synthesis_contract_version" "text", "p_interpretation_provider" "text", "p_interpretation_model" "text", "p_interpretation_request" "jsonb", "p_operation_id" "text", "p_operation_fingerprint" "text", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."begin_broll_runway_submission"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_submission_attempt_id" "uuid", "p_prompt_revision_id" "uuid", "p_prompt_revision" bigint, "p_prompt_content_hash" "text", "p_model" "text", "p_duration_seconds" integer, "p_ratio" "text", "p_actor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare v_op tongs.broll_operation_receipts%rowtype; v_prompt jsonb;
begin
 select * into v_op from tongs.broll_operation_receipts where operation_id=p_operation_id for update;
 if not found then return jsonb_build_object('disposition','operation_not_found'); end if;
 if not tongs.has_workspace_role(v_op.workspace_id,'editor') then raise exception 'workspace editor authority required' using errcode='42501'; end if;
 if v_op.operation_fingerprint<>p_operation_fingerprint or v_op.operation_type<>'candidate_acquire' then return jsonb_build_object('disposition','operation_identity_conflict'); end if;
 if v_op.provider_task_id is not null then return jsonb_build_object('disposition','replay','operation',to_jsonb(v_op)); end if;
 if v_op.state='submission_unknown' then return jsonb_build_object('disposition','submission_unknown','operation',to_jsonb(v_op)); end if;
 if v_op.state='submitting' then
  update tongs.broll_operation_receipts set state='submission_unknown',submission_unknown_at=coalesce(submission_unknown_at,now()),ambiguity_reason=coalesce(ambiguity_reason,'recovered_inflight_submission_without_task_id'),updated_at=now() where operation_id=p_operation_id returning * into v_op;
  return jsonb_build_object('disposition','submission_unknown','operation',to_jsonb(v_op));
 end if;
 if v_op.state<>'pending' then return jsonb_build_object('disposition','operation_stage_conflict','operation',to_jsonb(v_op)); end if;
 v_prompt:=tongs.assert_current_broll_prompt(v_op.workspace_id,v_op.workpiece_id,v_op.beat_id,p_prompt_revision_id,p_prompt_revision,p_prompt_content_hash);
 if v_prompt->>'disposition'<>'verified' then return v_prompt; end if;
 update tongs.broll_operation_receipts set state='submitting',submission_attempt_id=p_submission_attempt_id,submitting_at=now(),
  normalized_inputs_json=normalized_inputs_json||jsonb_build_object('runway',jsonb_build_object('model',p_model,'duration_seconds',p_duration_seconds,'ratio',p_ratio,'submission_attempt_id',p_submission_attempt_id,'prompt_revision_id',p_prompt_revision_id,'prompt_revision',p_prompt_revision,'prompt_content_hash',p_prompt_content_hash)),updated_at=now()
 where operation_id=p_operation_id returning * into v_op;
 return jsonb_build_object('disposition','submitting','operation',to_jsonb(v_op));
end $$;


ALTER FUNCTION "tongs"."begin_broll_runway_submission"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_submission_attempt_id" "uuid", "p_prompt_revision_id" "uuid", "p_prompt_revision" bigint, "p_prompt_content_hash" "text", "p_model" "text", "p_duration_seconds" integer, "p_ratio" "text", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."begin_customer_hearth_research_stage"("p_reservation_id" "uuid", "p_stage_key" "text", "p_stage_type" "text", "p_stage_ordinal" integer, "p_request_fingerprint" "text", "p_request_json" "jsonb", "p_maximum_supplier_cost_micros" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  binding tongs.openai_text_funding_bindings%rowtype;
  reservation tongs.funding_reservations%rowtype;
  quote_binding tongs.openai_text_customer_quote_bindings%rowtype;
  latest tongs.customer_hearth_research_stage_events%rowtype;
  searches bigint; captured_bytes bigint;
begin
  perform tongs._require_pricing_service_role();
  perform pg_advisory_xact_lock(hashtextextended('customer-hearth-research-stage:'||p_reservation_id::text,0));
  select * into binding from tongs.openai_text_funding_bindings where reservation_id=p_reservation_id;
  select * into reservation from tongs.funding_reservations where id=p_reservation_id;
  select * into quote_binding from tongs.openai_text_customer_quote_bindings where quote_id=reservation.quote_id;
  select * into latest from tongs.customer_hearth_research_stage_events
    where reservation_id=p_reservation_id and stage_key=btrim(p_stage_key)
    order by sequence desc limit 1;
  if found then
    if latest.event_type='authorized' then
      insert into tongs.customer_hearth_research_stage_events values(
        gen_random_uuid(),p_reservation_id,btrim(p_stage_key),2,latest.stage_type,latest.stage_ordinal,
        'submission_unknown',latest.request_fingerprint,latest.maximum_supplier_cost_micros,
        latest.maximum_supplier_cost_micros,'estimated',latest.request_json,null,
        '{"reason":"authorized_stage_reentered_without_capture","duplicate_submission_prohibited":true}',now()
      );
      insert into tongs.customer_hearth_research_component_expenses values(
        gen_random_uuid(),p_reservation_id,'stage:'||btrim(p_stage_key),latest.stage_type,
        latest.maximum_supplier_cost_micros,'estimated',
        case when latest.stage_type='search' then 'Brave Search' else 'retrieval origin' end,
        '{"submission_unknown":true}',now()
      ) on conflict(expense_key) do nothing;
      return jsonb_build_object('replay',true,'capture',null,'event_type','submission_unknown');
    end if;
    return jsonb_build_object('replay',true,'capture',latest.capture_json,'event_type',latest.event_type);
  end if;
  if binding.reservation_id is null or reservation.id is null or quote_binding.quote_id is null
     or binding.route_code<>'hearth.research_synthesis'
     or binding.cost_policy_revision_id<>'12000000-0000-4000-8000-000000000001'::uuid
     or binding.model<>'gpt-5.6-luna' or quote_binding.request_fingerprint<>p_request_fingerprint
     or tongs._funding_reservation_state(p_reservation_id)<>'reserved'
     or now()>=reservation.created_at+interval '60 seconds'
     or p_stage_ordinal not between 1 and 24
     or p_stage_type not in ('search','retrieval')
     or p_maximum_supplier_cost_micros<>(case when p_stage_type='search' then 5000 else 0 end)
  then raise exception 'customer research stage not authorized' using errcode='42501'; end if;
  if exists(select 1 from tongs.customer_hearth_research_stage_events where reservation_id=p_reservation_id and event_type='submission_unknown')
  then raise exception 'research supplier reconciliation required' using errcode='42501'; end if;
  select count(*) into searches from tongs.customer_hearth_research_stage_events
    where reservation_id=p_reservation_id and stage_type='search' and event_type='authorized';
  if p_stage_type='search' and searches>=6 then raise exception 'research search cap reached' using errcode='42501'; end if;
  select coalesce(sum((capture_json->>'response_bytes')::bigint),0) into captured_bytes
    from tongs.customer_hearth_research_stage_events where reservation_id=p_reservation_id and event_type='captured';
  if captured_bytes>=1048576 then raise exception 'research capture cap reached' using errcode='42501'; end if;
  insert into tongs.customer_hearth_research_stage_events values(
    gen_random_uuid(),p_reservation_id,btrim(p_stage_key),1,p_stage_type,p_stage_ordinal,'authorized',
    p_request_fingerprint,p_maximum_supplier_cost_micros,null,'not_incurred',p_request_json,null,'{}',now()
  );
  insert into tongs.customer_hearth_research_component_expenses values(
    gen_random_uuid(),p_reservation_id,'platform:'||p_reservation_id::text,'platform_execution',1456,
    'estimated','Netlify/Supabase','{"classification":"attributable_variable_execution"}',now()
  ) on conflict(expense_key) do nothing;
  return jsonb_build_object('replay',false,'authorized',true);
end $$;


ALTER FUNCTION "tongs"."begin_customer_hearth_research_stage"("p_reservation_id" "uuid", "p_stage_key" "text", "p_stage_type" "text", "p_stage_ordinal" integer, "p_request_fingerprint" "text", "p_request_json" "jsonb", "p_maximum_supplier_cost_micros" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."begin_hammer_audio_render"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_recording_revision_id" "uuid", "p_composition_revision" bigint, "p_composition_fingerprint" "text", "p_render_plan_fingerprint" "text", "p_renderer_version" "text", "p_output_profile_id" "text", "p_actor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare op tongs.hammer_audio_render_operations%rowtype;
begin
  if auth.role()<>'service_role' then raise exception 'Hammer audio render begin requires service authority' using errcode='42501'; end if;
  if p_actor_id is null or not exists(select 1 from tongs.episodes where id=p_workpiece_id and workspace_id=p_workspace_id) then raise exception 'Hammer audio render relationship mismatch' using errcode='22023'; end if;
  if not exists(select 1 from tongs.recording_revisions where id=p_recording_revision_id and workpiece_id=p_workpiece_id) then raise exception 'Hammer recording revision mismatch' using errcode='22023'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_operation_id,0));
  select * into op from tongs.hammer_audio_render_operations where operation_id=p_operation_id;
  if found then
    if op.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict'); end if;
    return jsonb_build_object('disposition','replay','operation',to_jsonb(op));
  end if;
  insert into tongs.hammer_audio_render_operations(operation_id,operation_fingerprint,workspace_id,workpiece_id,recording_revision_id,composition_revision,composition_fingerprint,render_plan_fingerprint,renderer_version,output_profile_id,state,created_by)
  values(p_operation_id,p_operation_fingerprint,p_workspace_id,p_workpiece_id,p_recording_revision_id,p_composition_revision,p_composition_fingerprint,p_render_plan_fingerprint,p_renderer_version,p_output_profile_id,'rendering',p_actor_id)
  returning * into op;
  return jsonb_build_object('disposition','started','operation',to_jsonb(op));
end$$;


ALTER FUNCTION "tongs"."begin_hammer_audio_render"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_recording_revision_id" "uuid", "p_composition_revision" bigint, "p_composition_fingerprint" "text", "p_render_plan_fingerprint" "text", "p_renderer_version" "text", "p_output_profile_id" "text", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."begin_hammer_video_render"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_recording_revision_id" "uuid", "p_composition_revision" bigint, "p_composition_fingerprint" "text", "p_render_plan_fingerprint" "text", "p_background_effect_fingerprint" "text", "p_audio_master_asset_id" "uuid", "p_replacement_asset_id" "uuid", "p_renderer_version" "text", "p_output_profile_id" "text", "p_segmentation_authority" "jsonb", "p_actor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare op tongs.hammer_video_render_operations%rowtype;
begin
  if auth.role()<>'service_role' then raise exception 'Hammer video render begin requires service authority' using errcode='42501'; end if;
  if p_actor_id is null or not exists(select 1 from tongs.episodes where id=p_workpiece_id and workspace_id=p_workspace_id) then raise exception 'Hammer video render relationship mismatch' using errcode='22023'; end if;
  if not exists(select 1 from tongs.recording_revisions where id=p_recording_revision_id and workpiece_id=p_workpiece_id) then raise exception 'Hammer recording revision mismatch' using errcode='22023'; end if;
  if not exists(select 1 from tongs.assets where id=p_audio_master_asset_id and workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and asset_kind='hammer_audio_master' and status='ready') then raise exception 'Hammer audio master relationship mismatch' using errcode='22023'; end if;
  if p_replacement_asset_id is not null and not exists(select 1 from tongs.assets where id=p_replacement_asset_id and workspace_id=p_workspace_id and (workpiece_id=p_workpiece_id or asset_scope='workspace') and mime_type like'image/%' and status='ready') then raise exception 'Hammer replacement asset relationship mismatch' using errcode='22023'; end if;
  if p_background_effect_fingerprint is not null and (p_segmentation_authority is null or p_segmentation_authority->>'failure_policy'<>'fail_closed') then raise exception 'Hammer segmentation authority missing' using errcode='22023'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_operation_id,0));
  select * into op from tongs.hammer_video_render_operations where operation_id=p_operation_id;
  if found then
    if op.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict'); end if;
    return jsonb_build_object('disposition','replay','operation',to_jsonb(op));
  end if;
  insert into tongs.hammer_video_render_operations(operation_id,operation_fingerprint,workspace_id,workpiece_id,recording_revision_id,composition_revision,composition_fingerprint,render_plan_fingerprint,background_effect_fingerprint,audio_master_asset_id,replacement_asset_id,renderer_version,output_profile_id,segmentation_authority_json,state,created_by)
  values(p_operation_id,p_operation_fingerprint,p_workspace_id,p_workpiece_id,p_recording_revision_id,p_composition_revision,p_composition_fingerprint,p_render_plan_fingerprint,p_background_effect_fingerprint,p_audio_master_asset_id,p_replacement_asset_id,p_renderer_version,p_output_profile_id,p_segmentation_authority,'pending',p_actor_id)
  returning * into op;
  return jsonb_build_object('disposition','started','operation',to_jsonb(op));
end$$;


