CREATE OR REPLACE FUNCTION "tongs"."begin_image_prompt_interpretation"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_image_moment_id" "text", "p_image_map_revision_id" "uuid", "p_script_approval_id" "uuid", "p_expected_prompt_revision_id" "uuid", "p_expected_prompt_revision" bigint, "p_operation_id" "text", "p_operation_fingerprint" "text", "p_normalized_inputs_json" "jsonb", "p_actor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare v_seq tongs.image_map_prompt_sequences%rowtype; v_map tongs.image_map_revisions%rowtype; v_script tongs.script_approval_revisions%rowtype; v_op tongs.image_map_prompt_operation_receipts%rowtype;
begin
  if not tongs.has_workspace_role(p_workspace_id,'editor') then raise exception 'workspace editor authority required' using errcode='42501'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_operation_id,0));
  select * into v_op from tongs.image_map_prompt_operation_receipts where operation_id=p_operation_id for update;
  if found then
    if v_op.workspace_id<>p_workspace_id or v_op.workpiece_id<>p_workpiece_id or v_op.image_moment_id<>p_image_moment_id then return jsonb_build_object('disposition','operation_identity_conflict'); end if;
    if v_op.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict'); end if;
    if v_op.state='failed' then
      update tongs.image_map_prompt_operation_receipts set state=case when provider_response_json is null then 'pending' else 'provider_completed' end,failed_stage=null,failure_code=null,failure_message=null,updated_at=now() where operation_id=p_operation_id returning * into v_op;
    end if;
    return jsonb_build_object('disposition','replay','operation',to_jsonb(v_op));
  end if;
  select * into v_map from tongs.image_map_revisions where id=p_image_map_revision_id and workspace_id=p_workspace_id and workpiece_id=p_workpiece_id;
  if not found then return jsonb_build_object('disposition','image_map_revision_conflict'); end if;
  select * into v_script from tongs.script_approval_revisions where id=p_script_approval_id and workspace_id=p_workspace_id and workpiece_id=p_workpiece_id;
  if not found or v_map.source_script_approval_id<>v_script.id then return jsonb_build_object('disposition','script_revision_conflict'); end if;
  if not exists(select 1 from jsonb_array_elements(v_map.document_json->'entries') e where e->>'id'=p_image_moment_id) then return jsonb_build_object('disposition','image_moment_not_found'); end if;
  insert into tongs.image_map_prompt_sequences(workspace_id,workpiece_id,image_moment_id) values(p_workspace_id,p_workpiece_id,p_image_moment_id) on conflict do nothing;
  select * into v_seq from tongs.image_map_prompt_sequences where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and image_moment_id=p_image_moment_id for update;
  if v_seq.current_prompt_revision<>p_expected_prompt_revision or v_seq.current_prompt_revision_id is distinct from p_expected_prompt_revision_id then
    return jsonb_build_object('disposition','prompt_revision_conflict','current_prompt_revision_id',v_seq.current_prompt_revision_id,'current_prompt_revision',v_seq.current_prompt_revision);
  end if;
  insert into tongs.image_map_prompt_operation_receipts(operation_id,operation_fingerprint,operation_type,state,workspace_id,workpiece_id,image_moment_id,image_map_revision_id,image_map_revision,script_approval_id,script_approval_revision,expected_prompt_revision_id,expected_prompt_revision,normalized_inputs_json,created_by)
  values(p_operation_id,p_operation_fingerprint,'interpretation','pending',p_workspace_id,p_workpiece_id,p_image_moment_id,v_map.id,v_map.revision,v_script.id,v_script.approval_revision,p_expected_prompt_revision_id,p_expected_prompt_revision,p_normalized_inputs_json,p_actor_id)
  returning * into v_op;
  return jsonb_build_object('disposition','reserved','operation',to_jsonb(v_op));
end $$;


ALTER FUNCTION "tongs"."begin_image_prompt_interpretation"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_image_moment_id" "text", "p_image_map_revision_id" "uuid", "p_script_approval_id" "uuid", "p_expected_prompt_revision_id" "uuid", "p_expected_prompt_revision" bigint, "p_operation_id" "text", "p_operation_fingerprint" "text", "p_normalized_inputs_json" "jsonb", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."begin_my_hearth_script_proposal_application"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_proposal_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare proposal tongs.hearth_script_generation_proposals%rowtype;
  binding tongs.hearth_script_generation_proposal_draft_bindings%rowtype;
  current_file tongs.workpiece_files%rowtype; terminal text; started uuid; paid_result_id uuid;
begin
  if auth.uid() is null or not tongs.has_workspace_role(p_workspace_id,'editor') then
    raise exception 'workspace editor authority required' using errcode='42501';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('hearth-script-proposal:'||p_proposal_id::text,0));
  select * into proposal from tongs.hearth_script_generation_proposals
    where id=p_proposal_id and user_id=auth.uid() and workspace_id=p_workspace_id
      and workpiece_id=p_workpiece_id for share;
  if proposal.id is null then return jsonb_build_object('disposition','not_found'); end if;
  select event_type into terminal from tongs.hearth_script_generation_proposal_events
    where proposal_id=proposal.id and event_type in ('applied','rejected','superseded')
    order by created_at desc,id desc limit 1;
  if terminal is not null then
    return jsonb_build_object('disposition',terminal,'proposal_id',proposal.id);
  end if;
  if exists(select 1 from tongs.hearth_script_generation_proposals newer
    where newer.user_id=proposal.user_id and newer.workspace_id=proposal.workspace_id
      and newer.workpiece_id=proposal.workpiece_id
      and (newer.created_at,newer.id)>(proposal.created_at,proposal.id)) then
    return jsonb_build_object('disposition','superseded','proposal_id',proposal.id);
  end if;
  select * into binding from tongs.hearth_script_generation_proposal_draft_bindings
    where proposal_id=proposal.id;
  select id into started from tongs.hearth_script_generation_proposal_events
    where proposal_id=proposal.id and event_type='application_started';
  select * into current_file from tongs.workpiece_files
    where workpiece_id=proposal.workpiece_id and path=binding.expected_draft_path for share;
  if started is null and (current_file.revision<>binding.expected_draft_revision
    or lower(current_file.hash_value)<>binding.expected_draft_hash) then
    return jsonb_build_object(
      'disposition','stale','proposal_id',proposal.id,
      'expected_draft_revision',binding.expected_draft_revision,
      'expected_draft_hash',binding.expected_draft_hash,
      'current_draft_revision',current_file.revision,
      'current_draft_hash',lower(current_file.hash_value)
    );
  end if;
  if started is null then
    insert into tongs.hearth_script_generation_proposal_events(
      proposal_id,event_type,idempotency_key,actor_id,
      expected_draft_revision,expected_draft_hash,details
    ) values(
      proposal.id,'application_started','hearth-script-proposal:apply-start:'||proposal.id::text,
      auth.uid(),binding.expected_draft_revision,binding.expected_draft_hash,
      jsonb_build_object('workspace_id',p_workspace_id,'workpiece_id',p_workpiece_id)
    ) returning id into started;
  end if;
  select result.id into paid_result_id from tongs.openai_text_persisted_results result
    where result.reservation_id=proposal.reservation_id and result.route_code='hearth.script_generation';
  return proposal.result_json||jsonb_build_object(
    'disposition',case when current_file.revision=binding.expected_draft_revision
      and lower(current_file.hash_value)=binding.expected_draft_hash then 'started' else 'resume' end,
    'proposal_id',proposal.id,'proposal_state','proposed',
    'expected_draft_revision',binding.expected_draft_revision,
    'expected_draft_hash',binding.expected_draft_hash,
    'current_draft_revision',current_file.revision,
    'current_draft_hash',lower(current_file.hash_value),
    'created_at',proposal.created_at,'operation_id',proposal.operation_id,
    'source_paid_result_id',paid_result_id,'application_started',true,
    'canonical_revision_id','hearth-script-proposal-'||proposal.id::text
  );
end $$;


ALTER FUNCTION "tongs"."begin_my_hearth_script_proposal_application"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_proposal_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."begin_owner_broll_prompt_interpretation"("p_owner_cost_attempt_id" "uuid", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_beat_id" "uuid", "p_operation_fingerprint" "text", "p_financial_environment" "text", "p_runtime_environment" "text", "p_expected_prompt_revision_id" "uuid", "p_expected_prompt_revision" bigint, "p_creator_direction" "text", "p_creative_input_hash" "text", "p_interpretation_contract_version" "text", "p_validator_version" "text", "p_synthesis_contract_version" "text", "p_interpretation_provider" "text", "p_interpretation_model" "text", "p_interpretation_request" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $_$
declare
  v_authority jsonb;
  v_operation_key text;
  v_sequence tongs.broll_prompt_sequences%rowtype;
  v_current jsonb;
  v_inputs jsonb;
  v_existing tongs.broll_operation_receipts%rowtype;
begin
  v_authority:=tongs._assert_owner_hearth_operation_attempt(
    p_owner_cost_attempt_id,'motion.broll_interpretation',p_user_id,p_workspace_id,p_workpiece_id,
    p_operation_fingerprint,p_financial_environment,p_runtime_environment,
    p_interpretation_provider,p_interpretation_model,
    array['authorized','submitted','response_captured','succeeded']);
  if p_interpretation_provider<>'openai' or p_interpretation_model<>'gpt-5.6-luna'
    or p_beat_id is null or lower(p_creative_input_hash) !~ '^[0-9a-f]{64}$'
    or nullif(btrim(p_validator_version),'') is null
  then raise exception 'invalid owner B-roll interpretation contract' using errcode='22023'; end if;
  v_operation_key:=v_authority->>'operation_key';
  perform pg_advisory_xact_lock(hashtextextended('owner-broll-prompt:'||p_owner_cost_attempt_id::text,0));
  select * into v_existing from tongs.broll_operation_receipts
    where operation_id=v_operation_key or owner_cost_attempt_id=p_owner_cost_attempt_id for update;
  if found then
    if v_existing.operation_id<>v_operation_key
      or v_existing.owner_cost_attempt_id is distinct from p_owner_cost_attempt_id
      or v_existing.operation_fingerprint<>lower(p_operation_fingerprint)
      or v_existing.workspace_id<>p_workspace_id or v_existing.workpiece_id<>p_workpiece_id
      or v_existing.beat_id is distinct from p_beat_id
    then raise exception 'owner B-roll interpretation replay conflict' using errcode='23505'; end if;
    return jsonb_build_object('disposition','replay','operation',to_jsonb(v_existing));
  end if;
  insert into tongs.broll_prompt_sequences(workspace_id,workpiece_id,beat_id)
    values(p_workspace_id,p_workpiece_id,p_beat_id) on conflict do nothing;
  select * into v_sequence from tongs.broll_prompt_sequences
    where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and beat_id=p_beat_id for update;
  if v_sequence.current_prompt_revision<>p_expected_prompt_revision
    or v_sequence.current_prompt_revision_id is distinct from p_expected_prompt_revision_id
  then return jsonb_build_object('disposition','prompt_revision_conflict',
    'current_revision_id',v_sequence.current_prompt_revision_id,
    'current_revision',v_sequence.current_prompt_revision); end if;
  v_current:=tongs.broll_current_creative_input(
    p_workspace_id,p_workpiece_id,p_beat_id,p_creator_direction,
    p_interpretation_contract_version,p_synthesis_contract_version);
  if v_current->>'disposition'<>'current' then
    return jsonb_build_object('disposition',v_current->>'disposition'); end if;
  if v_current->>'creative_input_hash' is distinct from lower(p_creative_input_hash) then
    return jsonb_build_object('disposition','creative_input_conflict',
      'current_creative_input_hash',v_current->>'creative_input_hash'); end if;
  v_inputs:=jsonb_build_object(
    'expected_prompt_revision_id',p_expected_prompt_revision_id,
    'expected_prompt_revision',p_expected_prompt_revision,
    'creator_direction',coalesce(p_creator_direction,''),
    'creative_input_hash',lower(p_creative_input_hash),
    'interpretation_contract_version',p_interpretation_contract_version,
    'validator_version',p_validator_version,
    'synthesis_contract_version',p_synthesis_contract_version,
    'interpretation_provider',p_interpretation_provider,
    'interpretation_model',p_interpretation_model,
    'interpretation_request',coalesce(p_interpretation_request,'{}'::jsonb));
  insert into tongs.broll_operation_receipts(
    operation_id,operation_fingerprint,operation_type,state,workspace_id,workpiece_id,
    beat_id,normalized_inputs_json,created_by,owner_cost_attempt_id
  ) values(
    v_operation_key,lower(p_operation_fingerprint),'prompt_interpretation','pending',
    p_workspace_id,p_workpiece_id,p_beat_id,v_inputs,p_user_id,p_owner_cost_attempt_id
  ) returning * into v_existing;
  return jsonb_build_object('disposition','reserved','operation',to_jsonb(v_existing));
end $_$;


ALTER FUNCTION "tongs"."begin_owner_broll_prompt_interpretation"("p_owner_cost_attempt_id" "uuid", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_beat_id" "uuid", "p_operation_fingerprint" "text", "p_financial_environment" "text", "p_runtime_environment" "text", "p_expected_prompt_revision_id" "uuid", "p_expected_prompt_revision" bigint, "p_creator_direction" "text", "p_creative_input_hash" "text", "p_interpretation_contract_version" "text", "p_validator_version" "text", "p_synthesis_contract_version" "text", "p_interpretation_provider" "text", "p_interpretation_model" "text", "p_interpretation_request" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."begin_owner_hearth_research_stage"("p_reservation_id" "uuid", "p_stage_key" "text", "p_stage_type" "text", "p_stage_ordinal" integer, "p_request_fingerprint" "text", "p_request_json" "jsonb", "p_maximum_supplier_cost_micros" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare o tongs.owner_hearth_research_operations%rowtype; latest tongs.owner_hearth_research_stage_events%rowtype; searches bigint; captured_bytes bigint;
begin
 perform tongs._require_pricing_service_role(); perform pg_advisory_xact_lock(hashtextextended('owner-research-stage:'||p_reservation_id::text,0));
 select * into o from tongs.owner_hearth_research_operations where reservation_id=p_reservation_id;
 select * into latest from tongs.owner_hearth_research_stage_events where reservation_id=p_reservation_id and stage_key=btrim(p_stage_key) order by sequence desc limit 1;
 if found then
  if latest.event_type='authorized' then
   insert into tongs.owner_hearth_research_stage_events values(gen_random_uuid(),p_reservation_id,btrim(p_stage_key),2,latest.stage_type,latest.stage_ordinal,
    'submission_unknown',latest.request_fingerprint,latest.maximum_supplier_cost_micros,latest.maximum_supplier_cost_micros,'estimated',latest.request_json,null,
    '{"reason":"authorized_stage_reentered_without_capture","duplicate_submission_prohibited":true}',now());
   insert into tongs.owner_hearth_research_component_expenses values(gen_random_uuid(),p_reservation_id,'stage:'||btrim(p_stage_key),latest.stage_type,
    latest.maximum_supplier_cost_micros,'estimated',case when latest.stage_type='search' then 'Brave Search' else 'retrieval origin' end,
    '{"submission_unknown":true}',now()) on conflict(expense_key) do nothing;
   return jsonb_build_object('replay',true,'capture',null,'event_type','submission_unknown');
  end if;
  return jsonb_build_object('replay',true,'capture',latest.capture_json,'event_type',latest.event_type);
 end if;
 if o.id is null or o.request_fingerprint<>p_request_fingerprint or now()>=o.execution_deadline_at or p_stage_ordinal not between 1 and o.maximum_http_attempts
  or p_stage_type not in('search','retrieval') or p_maximum_supplier_cost_micros<>(case when p_stage_type='search' then 5000 else 0 end)
  or not exists(select 1 from tongs.paid_operation_aggregate_bindings where reservation_id=p_reservation_id) then raise exception 'research stage not authorized' using errcode='42501'; end if;
 if exists(select 1 from tongs.owner_hearth_research_stage_events where reservation_id=p_reservation_id and event_type='submission_unknown') then
  raise exception 'research supplier reconciliation required' using errcode='42501'; end if;
 select count(*) into searches from tongs.owner_hearth_research_stage_events where reservation_id=p_reservation_id and stage_type='search' and event_type='authorized';
 if p_stage_type='search' and searches>=o.maximum_searches then raise exception 'research search cap reached' using errcode='42501'; end if;
 select coalesce(sum((capture_json->>'response_bytes')::bigint),0) into captured_bytes from tongs.owner_hearth_research_stage_events
  where reservation_id=p_reservation_id and event_type='captured';
 if captured_bytes>=1048576 then raise exception 'research capture cap reached' using errcode='42501'; end if;
 insert into tongs.owner_hearth_research_stage_events values(gen_random_uuid(),p_reservation_id,btrim(p_stage_key),1,p_stage_type,p_stage_ordinal,'authorized',
  p_request_fingerprint,p_maximum_supplier_cost_micros,null,'not_incurred',p_request_json,null,'{}',now());
 insert into tongs.owner_hearth_research_component_expenses values(gen_random_uuid(),p_reservation_id,'platform:'||p_reservation_id::text,'platform_execution',1456,'estimated',
  'Netlify/Supabase',jsonb_build_object('covers','execution,database writes,initial delivery','rate_verification_required',true),now()) on conflict(expense_key) do nothing;
 return jsonb_build_object('replay',false,'authorized',true);
end $$;


ALTER FUNCTION "tongs"."begin_owner_hearth_research_stage"("p_reservation_id" "uuid", "p_stage_key" "text", "p_stage_type" "text", "p_stage_ordinal" integer, "p_request_fingerprint" "text", "p_request_json" "jsonb", "p_maximum_supplier_cost_micros" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."begin_owner_provider_attempt"("p_reservation_id" "uuid", "p_attempt_key" "text", "p_lease_seconds" integer, "p_evidence_json" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_control tongs.paid_execution_control_revisions%rowtype;
  v_reservation tongs.funding_reservations%rowtype;
  v_budget tongs.owner_operating_budgets%rowtype;
  v_revision tongs.owner_operating_budget_revisions%rowtype;
  v_state text;
  v_existing tongs.funding_reservation_events%rowtype;
  v_consumed bigint;
  v_held bigint;
  v_sequence integer;
  v_lease timestamptz;
begin
  perform tongs._require_pricing_service_role();
  if length(btrim(coalesce(p_attempt_key,'')))<8 or p_lease_seconds<5 or p_lease_seconds>900
     or jsonb_typeof(coalesce(p_evidence_json,'null'::jsonb))<>'object' then
    raise exception 'invalid provider attempt lease' using errcode='22023';
  end if;
  select * into v_control from tongs._current_paid_execution_control();
  if not v_control.owner_budget_spending_enabled or not v_control.provider_execution_enabled then
    raise exception 'owner-budget provider execution is not activated' using errcode='42501';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('provider-attempt:'||p_reservation_id::text,0));
  select * into v_reservation from tongs.funding_reservations where id=p_reservation_id for update;
  if not found or v_reservation.funding_source_type<>'owner_budget' then
    raise exception 'owner-funded reservation not found' using errcode='P0002';
  end if;
  select * into v_existing from tongs.funding_reservation_events
    where reservation_id=p_reservation_id and provider_attempt_key=btrim(p_attempt_key);
  if found then
    return jsonb_build_object('reservation_id',p_reservation_id,'attempt_key',v_existing.provider_attempt_key,
      'state',tongs._funding_reservation_state(p_reservation_id),'replay',true,
      'lease_expires_at',v_existing.lease_expires_at,'provider_execution_authorized',false,
      'reason','duplicate_attempt');
  end if;
  v_state:=tongs._funding_reservation_state(p_reservation_id);
  if v_state='submission_unknown' then
    return jsonb_build_object('reservation_id',p_reservation_id,'state',v_state,'replay',true,
      'provider_execution_authorized',false,'reason','ambiguous_submission_requires_reconciliation');
  elsif v_state in ('settled','released') then
    raise exception 'reservation is terminal' using errcode='P0001';
  elsif v_state not in ('reserved','provider_attempt_shadowed','provider_failure_recorded') then
    raise exception 'reservation is not attemptable' using errcode='P0001';
  end if;
  select * into v_budget from tongs.owner_operating_budgets where id=v_reservation.funding_source_id for update;
  select * into v_revision from tongs.owner_operating_budget_revisions
    where budget_id=v_budget.id order by revision desc limit 1;
  if v_revision.status<>'active' or v_revision.maximum_amount_micros is null
     or now()<v_budget.period_start or now()>=v_budget.period_end then
    raise exception 'active capped owner operating budget required' using errcode='P0001';
  end if;
  select tongs._owner_operating_budget_effective_consumed(v_budget.id) into v_consumed;
  select coalesce(sum(reservation.reserved_wholesale_spend_micros),0) into v_held
    from tongs.funding_reservations reservation
    where reservation.funding_source_type='owner_budget' and reservation.funding_source_id=v_budget.id
      and tongs._funding_reservation_state(reservation.id) not in ('settled','released');
  if v_consumed+v_held>v_revision.maximum_amount_micros then
    raise exception 'owner operating budget cap exhausted before provider boundary' using errcode='P0001';
  end if;
  v_lease:=now()+make_interval(secs=>p_lease_seconds);
  select coalesce(max(sequence),0)+1 into v_sequence from tongs.funding_reservation_events
    where reservation_id=p_reservation_id;
  insert into tongs.funding_reservation_events(
    id,reservation_id,sequence,event_type,event_key,provider_attempt_key,lease_expires_at,evidence_json
  ) values (gen_random_uuid(),p_reservation_id,v_sequence,'provider_attempt_shadowed',
    'reservation:'||p_reservation_id::text||':attempt:'||btrim(p_attempt_key),btrim(p_attempt_key),v_lease,
    coalesce(p_evidence_json,'{}'::jsonb)||jsonb_build_object('owner_budget_id',v_budget.id));
  return jsonb_build_object('reservation_id',p_reservation_id,'attempt_key',btrim(p_attempt_key),
    'state','provider_attempt_shadowed','replay',false,'lease_expires_at',v_lease,
    'provider_execution_authorized',true,'reason','owner_budget_authorized');
end $$;


ALTER FUNCTION "tongs"."begin_owner_provider_attempt"("p_reservation_id" "uuid", "p_attempt_key" "text", "p_lease_seconds" integer, "p_evidence_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."begin_owner_unified_visual_plan"("p_owner_cost_attempt_id" "uuid", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_operation_fingerprint" "text", "p_financial_environment" "text", "p_runtime_environment" "text", "p_script_approval_id" "uuid", "p_expected_image_revision_id" "uuid", "p_expected_image_revision" bigint, "p_expected_broll_revision_id" "uuid", "p_expected_broll_revision" bigint, "p_expected_reference_revision_id" "uuid", "p_expected_reference_revision" bigint, "p_expected_reference_visual_revision_id" "uuid", "p_expected_reference_visual_revision" bigint, "p_normalized_inputs_json" "jsonb", "p_model" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_authority jsonb;
  v_operation_key text;
  v_existing tongs.unified_visual_plan_operations%rowtype;
  v_approval tongs.script_approval_revisions%rowtype;
  v_image tongs.workpiece_image_map_sequences%rowtype;
  v_broll tongs.broll_plan_sequences%rowtype;
  v_reference tongs.reference_clip_plan_sequences%rowtype;
  v_reference_visual tongs.reference_visual_plan_sequences%rowtype;
begin
  v_authority:=tongs._assert_owner_hearth_operation_attempt(
    p_owner_cost_attempt_id,'visual.unified_plan',p_user_id,p_workspace_id,p_workpiece_id,
    p_operation_fingerprint,p_financial_environment,p_runtime_environment,
    'openai',p_model,array['authorized','submitted','response_captured','succeeded']);
  if p_model<>'gpt-5.6-luna' or jsonb_typeof(coalesce(p_normalized_inputs_json,'null'::jsonb))<>'object'
  then raise exception 'invalid owner unified visual-plan contract' using errcode='22023'; end if;
  v_operation_key:=v_authority->>'operation_key';
  perform pg_advisory_xact_lock(hashtextextended('owner-unified-plan:'||p_owner_cost_attempt_id::text,0));
  select * into v_existing from tongs.unified_visual_plan_operations
    where operation_id=v_operation_key or owner_cost_attempt_id=p_owner_cost_attempt_id for update;
  if found then
    if v_existing.operation_id<>v_operation_key
      or v_existing.owner_cost_attempt_id is distinct from p_owner_cost_attempt_id
      or v_existing.operation_fingerprint<>lower(p_operation_fingerprint)
      or v_existing.workspace_id<>p_workspace_id or v_existing.workpiece_id<>p_workpiece_id
    then raise exception 'owner unified visual-plan replay conflict' using errcode='23505'; end if;
    return jsonb_build_object('disposition','replay','operation',to_jsonb(v_existing));
  end if;
  select * into v_approval from tongs.script_approval_revisions
    where id=p_script_approval_id and workspace_id=p_workspace_id and workpiece_id=p_workpiece_id;
  if not found or not exists(select 1 from tongs.workpiece_script_approval_sequences sequence
    where sequence.workspace_id=p_workspace_id and sequence.workpiece_id=p_workpiece_id
      and sequence.current_approval_id=v_approval.id)
  then return jsonb_build_object('disposition','script_revision_conflict'); end if;
  select * into v_image from tongs.workpiece_image_map_sequences where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id;
  select * into v_broll from tongs.broll_plan_sequences where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id;
  select * into v_reference from tongs.reference_clip_plan_sequences where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id;
  select * into v_reference_visual from tongs.reference_visual_plan_sequences where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id;
  if coalesce(v_image.current_revision,0)<>p_expected_image_revision
    or v_image.current_revision_id is distinct from p_expected_image_revision_id
    or coalesce(v_broll.current_plan_revision,0)<>p_expected_broll_revision
    or v_broll.current_plan_revision_id is distinct from p_expected_broll_revision_id
    or coalesce(v_reference.current_plan_revision,0)<>p_expected_reference_revision
    or v_reference.current_plan_revision_id is distinct from p_expected_reference_revision_id
    or coalesce(v_reference_visual.current_plan_revision,0)<>p_expected_reference_visual_revision
    or v_reference_visual.current_plan_revision_id is distinct from p_expected_reference_visual_revision_id
  then return jsonb_build_object('disposition','child_revision_conflict'); end if;
  insert into tongs.unified_visual_plan_operations(
    operation_id,operation_fingerprint,workspace_id,workpiece_id,
    script_approval_id,script_approval_revision,script_content_hash,
    contract_version,expected_reference_visual_revision_id,
    expected_reference_visual_revision,normalized_inputs_json,created_by,owner_cost_attempt_id
  ) values(
    v_operation_key,lower(p_operation_fingerprint),p_workspace_id,p_workpiece_id,
    v_approval.id,v_approval.approval_revision,v_approval.script_content_hash,
    'forge.unified-visual-plan.v2',p_expected_reference_visual_revision_id,
    p_expected_reference_visual_revision,p_normalized_inputs_json,p_user_id,p_owner_cost_attempt_id
  ) returning * into v_existing;
  return jsonb_build_object('disposition','reserved','operation',to_jsonb(v_existing));
end $$;


ALTER FUNCTION "tongs"."begin_owner_unified_visual_plan"("p_owner_cost_attempt_id" "uuid", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_operation_fingerprint" "text", "p_financial_environment" "text", "p_runtime_environment" "text", "p_script_approval_id" "uuid", "p_expected_image_revision_id" "uuid", "p_expected_image_revision" bigint, "p_expected_broll_revision_id" "uuid", "p_expected_broll_revision" bigint, "p_expected_reference_revision_id" "uuid", "p_expected_reference_revision" bigint, "p_expected_reference_visual_revision_id" "uuid", "p_expected_reference_visual_revision" bigint, "p_normalized_inputs_json" "jsonb", "p_model" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."begin_paid_media_provider_attempt"("p_paid_media_operation_id" "uuid", "p_operation_fingerprint" "text", "p_attempt_id" "uuid", "p_request_payload_hash" "text", "p_request_evidence_json" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare v_op tongs.paid_media_operations%rowtype; v_attempt tongs.paid_media_provider_attempts%rowtype; v_endpoint text;
begin
  select * into v_op from tongs.paid_media_operations where id=p_paid_media_operation_id for update;
  if not found then raise exception 'paid media operation not found' using errcode='P0002'; end if;
  if v_op.operation_fingerprint<>p_operation_fingerprint then raise exception 'paid operation fingerprint mismatch' using errcode='22023'; end if;
  if v_op.state='settled' then return jsonb_build_object('operation',to_jsonb(v_op),'replay',true); end if;
  select * into v_attempt from tongs.paid_media_provider_attempts where paid_media_operation_id=v_op.id order by ordinal desc limit 1;
  if found then
    if v_attempt.id<>p_attempt_id or v_attempt.request_payload_hash<>p_request_payload_hash then raise exception 'provider attempt replay conflict' using errcode='23505'; end if;
    return jsonb_build_object('operation',to_jsonb(v_op),'attempt',to_jsonb(v_attempt),'replay',true);
  end if;
  if v_op.state<>'reserved' then raise exception 'paid operation is not reserved for provider submission' using errcode='P0001'; end if;
  v_endpoint:=case when v_op.media_kind='video' then '/v1/text_to_video' else '/v1/images/generations' end;
  insert into tongs.paid_media_provider_attempts(id,paid_media_operation_id,user_id,ordinal,provider,model_snapshot,endpoint,
    request_payload_hash,request_evidence_json,state,transmitted,submitted_at)
  values(p_attempt_id,v_op.id,v_op.user_id,1,v_op.provider,v_op.model_snapshot,v_endpoint,
    p_request_payload_hash,p_request_evidence_json,'submitting',false,now()) returning * into v_attempt;
  update tongs.paid_media_operations set state='submitting',active_attempt_id=v_attempt.id,updated_at=now() where id=v_op.id returning * into v_op;
  insert into tongs.paid_media_operation_events values(gen_random_uuid(),v_op.id,v_op.user_id,'provider_submission_started',3,to_jsonb(v_attempt),v_op.actor_id,now());
  return jsonb_build_object('operation',to_jsonb(v_op),'attempt',to_jsonb(v_attempt),'replay',false);
end $$;


ALTER FUNCTION "tongs"."begin_paid_media_provider_attempt"("p_paid_media_operation_id" "uuid", "p_operation_fingerprint" "text", "p_attempt_id" "uuid", "p_request_payload_hash" "text", "p_request_evidence_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."begin_paid_operation_aggregate_attempt"("p_reservation_id" "uuid", "p_event_key" "text", "p_attempt_number" smallint, "p_caller_class" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare b tongs.paid_operation_aggregate_bindings%rowtype; result jsonb;
begin
 perform tongs._require_pricing_service_role();
 select * into b from tongs.paid_operation_aggregate_bindings where reservation_id=p_reservation_id;
 if not found then return jsonb_build_object('enforcement_enabled',false,'authorized',true,'reason','aggregate_assignment_inactive'); end if;
 result:=tongs.begin_restricted_beta_attempt(b.hold_id,p_event_key,p_attempt_number,p_caller_class);
 return jsonb_build_object('enforcement_enabled',true)||result;
end $$;


ALTER FUNCTION "tongs"."begin_paid_operation_aggregate_attempt"("p_reservation_id" "uuid", "p_event_key" "text", "p_attempt_number" smallint, "p_caller_class" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."begin_provider_attempt"("p_reservation_id" "uuid", "p_attempt_key" "text", "p_lease_seconds" integer, "p_evidence_json" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_control tongs.paid_execution_control_revisions%rowtype;
  v_reservation tongs.funding_reservations%rowtype;
  v_state text;
  v_existing tongs.funding_reservation_events%rowtype;
  v_sequence integer;
  v_lease timestamptz;
  v_authorized boolean;
  v_reason text;
begin
  perform tongs._require_pricing_service_role();
  if length(btrim(coalesce(p_attempt_key, ''))) < 8 or p_lease_seconds < 5 or p_lease_seconds > 900
     or jsonb_typeof(coalesce(p_evidence_json, 'null'::jsonb)) <> 'object' then
    raise exception 'invalid provider attempt lease' using errcode = '22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('provider-attempt:' || p_reservation_id::text, 0));
  select * into v_reservation from tongs.funding_reservations where id = p_reservation_id for update;
  if not found then raise exception 'funding reservation not found' using errcode = 'P0002'; end if;
  select * into v_existing from tongs.funding_reservation_events
    where reservation_id = p_reservation_id and provider_attempt_key = btrim(p_attempt_key);
  if found then
    return jsonb_build_object('reservation_id', p_reservation_id, 'attempt_key', v_existing.provider_attempt_key,
      'state', tongs._funding_reservation_state(p_reservation_id), 'replay', true,
      'lease_expires_at', v_existing.lease_expires_at, 'provider_execution_authorized', false,
      'reason', 'duplicate_attempt');
  end if;
  v_state := tongs._funding_reservation_state(p_reservation_id);
  if v_state = 'submission_unknown' then
    return jsonb_build_object('reservation_id', p_reservation_id, 'state', v_state,
      'replay', true, 'provider_execution_authorized', false,
      'reason', 'ambiguous_submission_requires_reconciliation');
  elsif v_state in ('settled', 'released') then
    raise exception 'reservation is terminal' using errcode = 'P0001';
  elsif v_state not in ('reserved', 'provider_attempt_shadowed', 'provider_failure_recorded') then
    raise exception 'reservation is not attemptable' using errcode = 'P0001';
  end if;
  select * into v_control from tongs._current_paid_execution_control();
  v_authorized := v_control.provider_execution_enabled and case
    when v_reservation.funding_source_type in ('customer_deposit', 'paid_allowance')
      then v_control.customer_settlement_enabled
    when v_reservation.funding_source_type = 'none' then true
    else false
  end;
  v_reason := case
    when v_reservation.funding_source_type = 'owner_budget' then 'owner_budget_requires_owner_boundary'
    when not v_control.provider_execution_enabled then 'shadow_mode'
    when v_reservation.funding_source_type in ('customer_deposit', 'paid_allowance')
      and not v_control.customer_settlement_enabled then 'customer_settlement_disabled'
    when v_authorized then 'authorized'
    else 'funding_lane_not_authorized'
  end;
  v_lease := now() + make_interval(secs => p_lease_seconds);
  select coalesce(max(sequence),0)+1 into v_sequence from tongs.funding_reservation_events
    where reservation_id = p_reservation_id;
  insert into tongs.funding_reservation_events(
    id, reservation_id, sequence, event_type, event_key, provider_attempt_key,
    lease_expires_at, evidence_json
  ) values (
    gen_random_uuid(), p_reservation_id, v_sequence, 'provider_attempt_shadowed',
    'reservation:' || p_reservation_id::text || ':attempt:' || btrim(p_attempt_key),
    btrim(p_attempt_key), v_lease, coalesce(p_evidence_json, '{}'::jsonb)
  );
  return jsonb_build_object('reservation_id', p_reservation_id, 'attempt_key', btrim(p_attempt_key),
    'state', 'provider_attempt_shadowed', 'replay', false, 'lease_expires_at', v_lease,
    'provider_execution_authorized', v_authorized, 'reason', v_reason);
end;
$$;


ALTER FUNCTION "tongs"."begin_provider_attempt"("p_reservation_id" "uuid", "p_attempt_key" "text", "p_lease_seconds" integer, "p_evidence_json" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."begin_provider_attempt"("p_reservation_id" "uuid", "p_attempt_key" "text", "p_lease_seconds" integer, "p_evidence_json" "jsonb") IS 'Shadow lease interface. Returns provider_execution_authorized=false until a later approved control revision.';



CREATE OR REPLACE FUNCTION "tongs"."begin_reference_clip_acquisition"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_plan_revision_id" "uuid", "p_plan_revision" bigint, "p_opportunity_id" "uuid", "p_opportunity_revision_id" "uuid", "p_opportunity_revision" bigint, "p_acquisition_type" "text", "p_inputs" "jsonb", "p_operation_id" "text", "p_operation_fingerprint" "text", "p_actor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare op tongs.reference_clip_acquisition_operations%rowtype;seq tongs.reference_clip_plan_sequences%rowtype;opportunity tongs.reference_clip_opportunity_revisions%rowtype;
begin
 if not tongs.has_workspace_role(p_workspace_id,'editor') or auth.uid() is distinct from p_actor_id then raise exception 'workspace editor authority required' using errcode='42501';end if;
 if p_acquisition_type not in('upload','external_fetch') then return jsonb_build_object('disposition','unsupported_acquisition_type');end if;
 perform pg_advisory_xact_lock(hashtextextended(p_operation_id,0));select * into op from tongs.reference_clip_acquisition_operations where operation_id=p_operation_id for update;
 if found then if op.operation_fingerprint<>p_operation_fingerprint or op.workspace_id<>p_workspace_id or op.workpiece_id<>p_workpiece_id or op.opportunity_revision_id<>p_opportunity_revision_id or op.acquisition_type<>p_acquisition_type then return jsonb_build_object('disposition','operation_identity_conflict');end if;return jsonb_build_object('disposition','replay','operation',to_jsonb(op));end if;
 select * into seq from tongs.reference_clip_plan_sequences where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id for update;
 if seq.current_plan_revision_id is distinct from p_plan_revision_id or seq.current_plan_revision<>p_plan_revision then return jsonb_build_object('disposition','plan_revision_conflict');end if;
 perform 1 from tongs.reference_clip_plan_membership where plan_revision_id=p_plan_revision_id and opportunity_id=p_opportunity_id and opportunity_revision_id=p_opportunity_revision_id and opportunity_revision=p_opportunity_revision;
 if not found then return jsonb_build_object('disposition','opportunity_not_current');end if;
 select * into opportunity from tongs.reference_clip_opportunity_revisions where id=p_opportunity_revision_id;
 if opportunity.source_status<>'linked' then return jsonb_build_object('disposition','source_link_required');end if;
 insert into tongs.reference_clip_acquisition_operations(operation_id,operation_fingerprint,workspace_id,workpiece_id,plan_revision_id,plan_revision,opportunity_id,opportunity_revision_id,opportunity_revision,acquisition_type,state,normalized_inputs_json,created_by)values(p_operation_id,p_operation_fingerprint,p_workspace_id,p_workpiece_id,p_plan_revision_id,p_plan_revision,p_opportunity_id,p_opportunity_revision_id,p_opportunity_revision,p_acquisition_type,'pending',p_inputs,p_actor_id)returning * into op;
 return jsonb_build_object('disposition','reserved','operation',to_jsonb(op));
end$$;


