CREATE OR REPLACE FUNCTION "tongs"."begin_reference_visual_render"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_opportunity_revision_id" "uuid", "p_recipe_revision_id" "uuid", "p_rights_declaration_revision_id" "uuid", "p_renderer_name" "text", "p_renderer_version" "text", "p_operation_id" "text", "p_operation_fingerprint" "text", "p_actor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$declare op tongs.reference_visual_render_operations%rowtype;begin if not tongs.has_workspace_role(p_workspace_id,'editor') or auth.uid() is distinct from p_actor_id then raise exception 'workspace editor authority required' using errcode='42501';end if;perform pg_advisory_xact_lock(hashtextextended(p_operation_id,0));select * into op from tongs.reference_visual_render_operations where operation_id=p_operation_id;if found then if op.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict');end if;return jsonb_build_object('disposition','replay','operation',to_jsonb(op));end if;if not exists(select 1 from tongs.reference_visual_recipe_sequences s join tongs.reference_visual_recipe_revisions r on r.id=s.current_recipe_revision_id where r.id=p_recipe_revision_id and r.workspace_id=p_workspace_id and r.workpiece_id=p_workpiece_id and not exists(select 1 from unnest(r.evidence_revision_ids)e(id) join tongs.reference_visual_evidence_revisions ev on ev.id=e.id where ev.confirmation_state<>'creator_confirmed'))then return jsonb_build_object('disposition','current_confirmed_recipe_required');end if;if not exists(select 1 from tongs.reference_visual_rights_declaration_sequences s where s.workspace_id=p_workspace_id and s.workpiece_id=p_workpiece_id and s.current_declaration_revision_id=p_rights_declaration_revision_id)then return jsonb_build_object('disposition','current_rights_declaration_required');end if;insert into tongs.reference_visual_render_operations(operation_id,operation_fingerprint,workspace_id,workpiece_id,opportunity_revision_id,recipe_revision_id,rights_declaration_revision_id,renderer_name,renderer_version,created_by)values(p_operation_id,p_operation_fingerprint,p_workspace_id,p_workpiece_id,p_opportunity_revision_id,p_recipe_revision_id,p_rights_declaration_revision_id,p_renderer_name,p_renderer_version,p_actor_id)returning * into op;return jsonb_build_object('disposition','reserved','operation',to_jsonb(op));end$$;


