    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'tongs', 'pg_temp'
    AS $$
  select case coalesce(lower(btrim(p_plan_item_id)), '')
    when 'creator' then 536870912000::bigint
    else 0::bigint
  end;
$$;


