CREATE OR REPLACE FUNCTION "tongs"."billing_status_entitles_access"("p_status" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'tongs', 'pg_temp'
    AS $$
  select coalesce(lower(btrim(p_status)), '') in ('active', 'trialing');
$$;


ALTER FUNCTION "tongs"."billing_status_entitles_access"("p_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."billing_storage_entitled_bytes"("p_item_id" "text") RETURNS bigint
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'tongs'
    AS $$
  select case coalesce(lower(btrim(p_item_id)), '')
    -- Legacy ladder values (kept for existing subscriptions)
    when '50gb' then 268435456000::bigint
    when '100gb' then 1099511627776::bigint
    when '1tb' then 5497558138880::bigint
    -- New stackable ladder values
    when '50gb_v2' then 53687091200::bigint
    when '150gb' then 161061273600::bigint
    when '500gb' then 536870912000::bigint
    else 0::bigint
  end;
$$;


