CREATE OR REPLACE FUNCTION "tongs"."billing_storage_entitlement_active"("p_status" "text", "p_current_period_end" timestamp with time zone) RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'tongs'
    AS $$
  select (
    coalesce(lower(btrim(p_status)), '') in ('active', 'trialing')
    and coalesce(p_current_period_end > now(), true)
  )
  or (
    coalesce(lower(btrim(p_status)), '') in ('past_due', 'unpaid')
    and coalesce(p_current_period_end > now(), false)
  );
$$;


