CREATE OR REPLACE FUNCTION "tongs"."bind_bounded_provider_quote_request"("p_quote_id" "uuid", "p_user_id" "uuid", "p_operation_id" "text", "p_route_code" "text", "p_request_fingerprint" "text", "p_model" "text", "p_service_tier" "text", "p_estimator_revision" "text", "p_tokenizer_revision" "text", "p_serialized_body_sha256" "text", "p_serialized_bytes" bigint, "p_tokenizer_input_tokens" bigint, "p_protocol_overhead_tokens" bigint, "p_utf8_byte_token_upper_bound" bigint, "p_bounded_input_tokens" bigint, "p_maximum_output_tokens" bigint, "p_maximum_attempts" smallint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $_$
declare existing tongs.bounded_provider_quote_request_bindings%rowtype;
  quote_binding tongs.openai_text_customer_quote_bindings%rowtype;
  cost_policy tongs.openai_text_cost_policy_revisions%rowtype;
begin
  perform tongs._require_pricing_service_role();
  if p_serialized_body_sha256 !~ '^[0-9a-f]{64}$' or p_request_fingerprint !~ '^[0-9a-f]{64}$'
     or p_serialized_bytes<=0 or p_tokenizer_input_tokens<=0 or p_protocol_overhead_tokens<0
     or p_utf8_byte_token_upper_bound<>p_serialized_bytes
     or p_bounded_input_tokens<>greatest(p_tokenizer_input_tokens+p_protocol_overhead_tokens,p_utf8_byte_token_upper_bound)
     or p_maximum_output_tokens<=0 or p_maximum_attempts not between 1 and 4 then
    raise exception 'invalid bounded quote request evidence' using errcode='22023';
  end if;
  select * into quote_binding from tongs.openai_text_customer_quote_bindings where quote_id=p_quote_id;
  select * into cost_policy from tongs.openai_text_cost_policy_revisions where id=quote_binding.cost_policy_revision_id;
  if quote_binding.quote_id is null or quote_binding.user_id<>p_user_id
     or quote_binding.canonical_operation_id<>btrim(p_operation_id)
     or quote_binding.route_code<>p_route_code or quote_binding.request_fingerprint<>p_request_fingerprint
     or quote_binding.runtime_model<>p_model or cost_policy.id is null
     or cost_policy.maximum_input_units<p_bounded_input_tokens
     or cost_policy.maximum_output_units<>p_maximum_output_tokens
     or cost_policy.maximum_attempts<>p_maximum_attempts then
    raise exception 'bounded request does not match quote limits' using errcode='42501';
  end if;
  select * into existing from tongs.bounded_provider_quote_request_bindings where quote_id=p_quote_id;
  if found then
    if existing.serialized_body_sha256<>p_serialized_body_sha256
       or existing.request_fingerprint<>p_request_fingerprint or existing.model<>p_model
       or existing.estimator_revision<>p_estimator_revision or existing.tokenizer_revision<>p_tokenizer_revision
       or existing.bounded_input_tokens<>p_bounded_input_tokens
       or existing.maximum_output_tokens<>p_maximum_output_tokens
       or existing.maximum_attempts<>p_maximum_attempts then
      raise exception 'bounded provider quote request replay conflict' using errcode='23505';
    end if;
    return to_jsonb(existing)||jsonb_build_object('replay',true);
  end if;
  insert into tongs.bounded_provider_quote_request_bindings(
    quote_id,route_code,operation_id,request_fingerprint,model,service_tier,pricing_revision_id,
    estimator_revision,tokenizer_revision,serialized_body_sha256,serialized_bytes,
    tokenizer_input_tokens,protocol_overhead_tokens,utf8_byte_token_upper_bound,bounded_input_tokens,
    maximum_output_tokens,maximum_attempts
  ) values(
    p_quote_id,p_route_code,btrim(p_operation_id),p_request_fingerprint,p_model,btrim(p_service_tier),
    quote_binding.pricing_revision_id,btrim(p_estimator_revision),btrim(p_tokenizer_revision),
    lower(p_serialized_body_sha256),p_serialized_bytes,p_tokenizer_input_tokens,p_protocol_overhead_tokens,
    p_utf8_byte_token_upper_bound,p_bounded_input_tokens,p_maximum_output_tokens,p_maximum_attempts
  ) returning * into existing;
  return to_jsonb(existing)||jsonb_build_object('replay',false);
end $_$;


ALTER FUNCTION "tongs"."bind_bounded_provider_quote_request"("p_quote_id" "uuid", "p_user_id" "uuid", "p_operation_id" "text", "p_route_code" "text", "p_request_fingerprint" "text", "p_model" "text", "p_service_tier" "text", "p_estimator_revision" "text", "p_tokenizer_revision" "text", "p_serialized_body_sha256" "text", "p_serialized_bytes" bigint, "p_tokenizer_input_tokens" bigint, "p_protocol_overhead_tokens" bigint, "p_utf8_byte_token_upper_bound" bigint, "p_bounded_input_tokens" bigint, "p_maximum_output_tokens" bigint, "p_maximum_attempts" smallint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."bind_bounded_provider_request"("p_reservation_id" "uuid", "p_route_code" "text", "p_request_fingerprint" "text", "p_model" "text", "p_service_tier" "text", "p_estimator_revision" "text", "p_tokenizer_revision" "text", "p_serialized_body_sha256" "text", "p_serialized_bytes" bigint, "p_tokenizer_input_tokens" bigint, "p_protocol_overhead_tokens" bigint, "p_utf8_byte_token_upper_bound" bigint, "p_bounded_input_tokens" bigint, "p_maximum_output_tokens" bigint, "p_maximum_attempts" smallint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $_$
declare existing tongs.bounded_provider_request_bindings%rowtype; binding tongs.openai_text_funding_bindings%rowtype;
 reservation tongs.funding_reservations%rowtype; quote tongs.customer_spending_quotes%rowtype;
 authority tongs.spending_quote_authority_bindings%rowtype; quote_request tongs.bounded_provider_quote_request_bindings%rowtype;
 ownerop tongs.owner_hearth_operation_authorizations%rowtype; retention_hash text;
begin
 perform tongs._require_pricing_service_role();
 if p_serialized_body_sha256!~'^[0-9a-f]{64}$' or p_request_fingerprint!~'^[0-9a-f]{64}$' or p_serialized_bytes<=0
   or p_utf8_byte_token_upper_bound<>p_serialized_bytes
   or p_bounded_input_tokens<>greatest(p_tokenizer_input_tokens+p_protocol_overhead_tokens,p_utf8_byte_token_upper_bound)
   or p_maximum_attempts not between 1 and 4 then raise exception 'invalid bounded provider request evidence' using errcode='22023'; end if;
 select * into binding from tongs.openai_text_funding_bindings where reservation_id=p_reservation_id;
 select * into reservation from tongs.funding_reservations where id=p_reservation_id;
 select * into quote from tongs.customer_spending_quotes where id=reservation.quote_id;
 select * into authority from tongs.spending_quote_authority_bindings where quote_id=quote.id;
 select * into quote_request from tongs.bounded_provider_quote_request_bindings where quote_id=quote.id;
 select * into ownerop from tongs.owner_hearth_operation_authorizations where reservation_id=p_reservation_id;
 if binding.reservation_id is null or reservation.id is null or quote.id is null or authority.quote_id is null
   or binding.route_code<>p_route_code or binding.model<>p_model or quote.request_fingerprint<>p_request_fingerprint
   or quote_request.quote_id is null or quote_request.serialized_body_sha256<>p_serialized_body_sha256
   or quote_request.estimator_revision<>p_estimator_revision or quote_request.tokenizer_revision<>p_tokenizer_revision
   or quote_request.bounded_input_tokens<>p_bounded_input_tokens or quote_request.maximum_output_tokens<>p_maximum_output_tokens
   or quote_request.maximum_attempts<>p_maximum_attempts
   or (ownerop.id is not null and (ownerop.request_fingerprint<>p_request_fingerprint or ownerop.serialized_body_sha256<>p_serialized_body_sha256))
   then raise exception 'bounded request does not match accepted quote authority' using errcode='42501'; end if;
 retention_hash:=encode(extensions.digest(convert_to(quote.retention_policy::text,'utf8'),'sha256'),'hex');
 select * into existing from tongs.bounded_provider_request_bindings where reservation_id=p_reservation_id;
 if found then
  if existing.serialized_body_sha256<>p_serialized_body_sha256 or existing.accepted_authority_hash<>authority.accepted_authority_hash then
   raise exception 'bounded provider request replay conflict' using errcode='23505'; end if;
  return to_jsonb(existing)||jsonb_build_object('replay',true);
 end if;
 insert into tongs.bounded_provider_request_bindings(reservation_id,quote_id,operation_id,route_code,request_fingerprint,model,service_tier,
  pricing_revision_id,accepted_authority_hash,retention_policy_hash,estimator_revision,tokenizer_revision,serialized_body_sha256,
  serialized_bytes,tokenizer_input_tokens,protocol_overhead_tokens,utf8_byte_token_upper_bound,bounded_input_tokens,maximum_output_tokens,maximum_attempts)
 values(p_reservation_id,quote.id,reservation.operation_id,p_route_code,p_request_fingerprint,p_model,btrim(p_service_tier),quote.pricing_revision_id,
  authority.accepted_authority_hash,retention_hash,btrim(p_estimator_revision),btrim(p_tokenizer_revision),p_serialized_body_sha256,p_serialized_bytes,
  p_tokenizer_input_tokens,p_protocol_overhead_tokens,p_utf8_byte_token_upper_bound,p_bounded_input_tokens,p_maximum_output_tokens,p_maximum_attempts)
 returning * into existing;
 return to_jsonb(existing)||jsonb_build_object('replay',false);
end $_$;


ALTER FUNCTION "tongs"."bind_bounded_provider_request"("p_reservation_id" "uuid", "p_route_code" "text", "p_request_fingerprint" "text", "p_model" "text", "p_service_tier" "text", "p_estimator_revision" "text", "p_tokenizer_revision" "text", "p_serialized_body_sha256" "text", "p_serialized_bytes" bigint, "p_tokenizer_input_tokens" bigint, "p_protocol_overhead_tokens" bigint, "p_utf8_byte_token_upper_bound" bigint, "p_bounded_input_tokens" bigint, "p_maximum_output_tokens" bigint, "p_maximum_attempts" smallint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."bind_customer_hearth_research_quote_request"("p_reservation_id" "uuid", "p_request_fingerprint" "text", "p_model" "text", "p_service_tier" "text", "p_estimator_revision" "text", "p_tokenizer_revision" "text", "p_serialized_body_sha256" "text", "p_serialized_bytes" bigint, "p_tokenizer_input_tokens" bigint, "p_protocol_overhead_tokens" bigint, "p_utf8_byte_token_upper_bound" bigint, "p_bounded_input_tokens" bigint, "p_maximum_output_tokens" bigint, "p_maximum_attempts" smallint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  reservation tongs.funding_reservations%rowtype;
  quote_binding tongs.openai_text_customer_quote_bindings%rowtype;
  bound jsonb;
begin
  perform tongs._require_pricing_service_role();
  select * into reservation from tongs.funding_reservations where id=p_reservation_id;
  select * into quote_binding from tongs.openai_text_customer_quote_bindings where quote_id=reservation.quote_id;
  if quote_binding.quote_id is null or quote_binding.route_code<>'hearth.research_synthesis'
     or quote_binding.cost_policy_revision_id<>'12000000-0000-4000-8000-000000000001'::uuid
     or quote_binding.request_fingerprint<>p_request_fingerprint
     or p_model<>'gpt-5.6-luna' or p_maximum_output_tokens<>16384 or p_maximum_attempts<>1
     or p_bounded_input_tokens>128000
     or exists(select 1 from tongs.customer_hearth_research_stage_events where reservation_id=p_reservation_id and event_type='submission_unknown')
  then return jsonb_build_object('authorized',false,'reason','request_outside_customer_research_authority'); end if;
  bound:=tongs.bind_bounded_provider_quote_request(
    quote_binding.quote_id,quote_binding.user_id,quote_binding.canonical_operation_id,
    quote_binding.route_code,quote_binding.request_fingerprint,p_model,p_service_tier,
    p_estimator_revision,p_tokenizer_revision,p_serialized_body_sha256,p_serialized_bytes,
    p_tokenizer_input_tokens,p_protocol_overhead_tokens,p_utf8_byte_token_upper_bound,
    p_bounded_input_tokens,p_maximum_output_tokens,p_maximum_attempts
  );
  return bound||jsonb_build_object('authorized',true);
end $$;


ALTER FUNCTION "tongs"."bind_customer_hearth_research_quote_request"("p_reservation_id" "uuid", "p_request_fingerprint" "text", "p_model" "text", "p_service_tier" "text", "p_estimator_revision" "text", "p_tokenizer_revision" "text", "p_serialized_body_sha256" "text", "p_serialized_bytes" bigint, "p_tokenizer_input_tokens" bigint, "p_protocol_overhead_tokens" bigint, "p_utf8_byte_token_upper_bound" bigint, "p_bounded_input_tokens" bigint, "p_maximum_output_tokens" bigint, "p_maximum_attempts" smallint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."bind_financial_environment_configuration_pair"("p_actor_id" "uuid", "p_pricing_revision_id" "uuid", "p_cost_policy_revision_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_pricing tongs.private_pricing_revisions%rowtype;
  v_policy tongs.private_pricing_policies%rowtype;
  v_cost tongs.openai_text_cost_policy_revisions%rowtype;
  v_publication tongs.private_pricing_publications%rowtype;
  v_test_revision integer;
  v_live_revision integer;
  v_expected_sku text;
begin
  perform tongs._require_pricing_service_role();
  if p_actor_id is null or not tongs.is_platform_operator(p_actor_id)
     or nullif(btrim(coalesce(p_reason, '')), '') is null then
    raise exception 'platform operator and configuration reason required' using errcode = '42501';
  end if;
  select * into v_pricing from tongs.private_pricing_revisions where id = p_pricing_revision_id;
  select * into v_policy from tongs.private_pricing_policies where id = v_pricing.policy_id;
  select * into v_cost from tongs.openai_text_cost_policy_revisions where id = p_cost_policy_revision_id;
  v_expected_sku := 'openai-text:hearth.chat_completion:gpt-5.6-luna:' || p_cost_policy_revision_id::text;
  select distinct on (publication.policy_id) publication.* into v_publication
  from tongs.private_pricing_publications publication
  where publication.policy_id = v_policy.id
  order by publication.policy_id, publication.publication_revision desc;
  if v_pricing.id is null or v_policy.id is null or v_cost.id is null
     or v_publication.action is distinct from 'published'
     or v_publication.pricing_revision_id is distinct from v_pricing.id
     or v_pricing.lifecycle_state <> 'review_ready' or v_pricing.currency <> 'USD'
     or v_pricing.markup_basis_points <> 3300
     or v_pricing.full_cost_ceiling_micros <> 11015
     or v_pricing.failure_cost_ceiling_micros <> 0
     or v_pricing.customer_price_ceiling_micros <> 15000
     or v_pricing.customer_credit_units <> 3
     or v_policy.scope_kind <> 'sku' or lower(v_policy.provider) <> 'openai'
     or lower(v_policy.sku) <> lower(v_expected_sku)
     or v_cost.route_code <> 'hearth.chat_completion'
     or v_cost.full_cost_ceiling_micros <> 11015
     or v_cost.maximum_input_units <> 2000 or v_cost.maximum_output_units <> 512
     or v_cost.maximum_attempts <> 1 or v_cost.cost_coverage <> 'complete'
     or v_cost.lifecycle_state not in ('pilot_candidate', 'active') then
    raise exception 'published environment-neutral Luna pricing and bounded cost policy required' using errcode = 'P0001';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('financial-environment-configuration-pair', 0));
  select coalesce(max(revision), 0) + 1 into v_test_revision
  from tongs.financial_environment_configuration_revisions where environment = 'test';
  select coalesce(max(revision), 0) + 1 into v_live_revision
  from tongs.financial_environment_configuration_revisions where environment = 'live';
  insert into tongs.financial_environment_configuration_revisions(
    environment, revision, lifecycle_state, workflow_contract, route_code,
    provider, model, cost_policy_revision_id, pricing_revision_id,
    wholesale_exposure_ceiling_micros, maximum_concurrency,
    rolling_window_seconds, maximum_operation_count,
    required_stripe_identifier_slots, reason
  ) values
    ('test', v_test_revision, 'certification_ready', 'forge.customer-financial-path.v2',
     'hearth.chat_completion', 'openai', 'gpt-5.6-luna', p_cost_policy_revision_id,
     p_pricing_revision_id, 11015, 1, 86400, 1,
     '["ai_credit_pack_price_ids","subscription_price_ids","webhook_endpoint_secret"]', btrim(p_reason)),
    ('live', v_live_revision, 'inactive_ready', 'forge.customer-financial-path.v2',
     'hearth.chat_completion', 'openai', 'gpt-5.6-luna', p_cost_policy_revision_id,
     p_pricing_revision_id, 11015, 1, 86400, 1,
     '["ai_credit_pack_price_ids","subscription_price_ids","webhook_endpoint_secret"]', btrim(p_reason));
  return jsonb_build_object(
    'test_configuration_revision', v_test_revision,
    'live_configuration_revision', v_live_revision,
    'pricing_revision_id', p_pricing_revision_id,
    'cost_policy_revision_id', p_cost_policy_revision_id,
    'workflow_contract', 'forge.customer-financial-path.v2'
  );
end $$;


ALTER FUNCTION "tongs"."bind_financial_environment_configuration_pair"("p_actor_id" "uuid", "p_pricing_revision_id" "uuid", "p_cost_policy_revision_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."bind_openai_text_funding_reservation"("p_operation_id" "text", "p_route_code" "text", "p_reservation_id" "uuid", "p_credential_funding" "text", "p_model" "text", "p_cost_policy_revision_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare v_res tongs.funding_reservations%rowtype; v_quote tongs.customer_spending_quotes%rowtype;
  v_cost tongs.openai_text_cost_policy_revisions%rowtype; v_rollout tongs.openai_text_rollout_revisions%rowtype;
  v_existing tongs.openai_text_funding_bindings%rowtype;
begin
  perform tongs._require_pricing_service_role();
  if length(btrim(coalesce(p_operation_id,'')))<8 or p_credential_funding not in ('forge','byo_customer')
    or length(btrim(coalesce(p_model,'')))<2 then raise exception 'invalid OpenAI text funding binding' using errcode='22023'; end if;
  perform pg_advisory_xact_lock(hashtextextended('openai-text-binding:'||btrim(p_operation_id),0));
  select * into v_existing from tongs.openai_text_funding_bindings where operation_id=btrim(p_operation_id);
  if found then
    if v_existing.reservation_id<>p_reservation_id or v_existing.route_code<>btrim(p_route_code)
      or v_existing.credential_funding<>p_credential_funding or v_existing.model<>btrim(p_model)
      or v_existing.cost_policy_revision_id is distinct from p_cost_policy_revision_id then
      raise exception 'OpenAI text binding replay conflict' using errcode='23505'; end if;
    return jsonb_build_object('operation_id',v_existing.operation_id,'reservation_id',v_existing.reservation_id,'replay',true,'provider_execution_authorized',false);
  end if;
  select * into v_res from tongs.funding_reservations where id=p_reservation_id for update;
  if not found or v_res.operation_id<>btrim(p_operation_id) or tongs._funding_reservation_state(v_res.id)<>'reserved' then
    raise exception 'eligible reserved funding allocation not found' using errcode='P0002'; end if;
  select * into v_quote from tongs.customer_spending_quotes where id=v_res.quote_id;
  select * into v_cost from tongs.openai_text_cost_policy_revisions where id=p_cost_policy_revision_id;
  if not found or v_cost.route_code<>btrim(p_route_code) or v_cost.cost_coverage<>'complete'
    or v_cost.lifecycle_state not in ('pilot_candidate','active') then raise exception 'pricing_not_configured' using errcode='P0001'; end if;
  if v_res.reserved_wholesale_spend_micros<>v_cost.full_cost_ceiling_micros
    or v_quote.full_cost_ceiling_micros<>v_cost.full_cost_ceiling_micros then
    raise exception 'reservation does not cover exact OpenAI text cost policy' using errcode='P0001'; end if;
  if p_credential_funding='byo_customer' and v_cost.direct_provider_ceiling_micros<>0 then
    raise exception 'BYO pricing must not reserve Forge OpenAI provider cost' using errcode='P0001'; end if;
  select * into v_rollout from tongs._current_openai_text_rollout(btrim(p_route_code));
  insert into tongs.openai_text_funding_bindings(operation_id,route_code,reservation_id,credential_funding,model,
    pricing_revision_id,maximum_input_units,maximum_output_units,maximum_attempts,cost_policy_revision_id,rollout_revision)
  values(btrim(p_operation_id),btrim(p_route_code),p_reservation_id,p_credential_funding,btrim(p_model),
    v_quote.pricing_revision_id,v_cost.maximum_input_units,v_cost.maximum_output_units,v_cost.maximum_attempts,v_cost.id,v_rollout.revision);
  return jsonb_build_object('operation_id',btrim(p_operation_id),'reservation_id',p_reservation_id,'replay',false,
    'provider_execution_authorized',false,'rollout_mode',v_rollout.mode,'cost_policy_revision_id',v_cost.id);
end $$;


ALTER FUNCTION "tongs"."bind_openai_text_funding_reservation"("p_operation_id" "text", "p_route_code" "text", "p_reservation_id" "uuid", "p_credential_funding" "text", "p_model" "text", "p_cost_policy_revision_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."bind_openai_text_quote_catalog"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare e tongs.openai_text_model_catalog_entries%rowtype;
begin
 select ce.* into e from tongs.openai_text_model_catalog_entries ce join tongs.openai_text_model_catalog_revisions c on c.id=ce.catalog_revision_id and c.lifecycle_state='active'
 join tongs.openai_text_model_route_compatibility x on x.catalog_entry_id=ce.id and x.route_code=new.route_code and x.cost_policy_revision_id=new.cost_policy_revision_id
 where ce.runtime_model_id=new.runtime_model and ce.lifecycle_state='active' and ce.availability_status='generation_compatible' order by c.revision desc limit 1;
 if not found then raise exception 'pricing_not_configured: quote model lacks an active exact catalog binding' using errcode='P0001'; end if;
 new.model_catalog_revision_id:=e.catalog_revision_id; new.model_catalog_entry_id:=e.id; return new;
end $$;


ALTER FUNCTION "tongs"."bind_openai_text_quote_catalog"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."bind_owner_hearth_research_bounded_provider_request"("p_reservation_id" "uuid", "p_route_code" "text", "p_request_fingerprint" "text", "p_model" "text", "p_service_tier" "text", "p_estimator_revision" "text", "p_tokenizer_revision" "text", "p_serialized_body_sha256" "text", "p_serialized_bytes" bigint, "p_tokenizer_input_tokens" bigint, "p_protocol_overhead_tokens" bigint, "p_utf8_byte_token_upper_bound" bigint, "p_bounded_input_tokens" bigint, "p_maximum_output_tokens" bigint, "p_maximum_attempts" smallint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare o tongs.owner_hearth_research_operations%rowtype; f tongs.owner_hearth_research_frozen_requests%rowtype; q tongs.customer_spending_quotes%rowtype;
 auth tongs.spending_quote_authority_bindings%rowtype; existing tongs.bounded_provider_request_bindings%rowtype; retention_hash text;
begin
 perform tongs._require_pricing_service_role(); select * into o from tongs.owner_hearth_research_operations where reservation_id=p_reservation_id;
 select * into f from tongs.owner_hearth_research_frozen_requests where reservation_id=p_reservation_id; select * into q from tongs.customer_spending_quotes where id=o.quote_id;
 select * into auth from tongs.spending_quote_authority_bindings where quote_id=o.quote_id;
 if o.id is null or f.reservation_id is null or auth.quote_id is null or p_route_code<>'hearth.research_synthesis' or o.request_fingerprint<>p_request_fingerprint
  or o.provider_model_id<>p_model or f.serialized_body_sha256<>p_serialized_body_sha256 or f.serialized_bytes<>p_serialized_bytes
  or f.tokenizer_revision<>p_tokenizer_revision or f.bounded_input_tokens<>p_bounded_input_tokens or f.maximum_output_tokens<>p_maximum_output_tokens
  or p_maximum_attempts<>1 or p_utf8_byte_token_upper_bound<>p_serialized_bytes then raise exception 'final research payload does not match frozen authority' using errcode='42501'; end if;
 select * into existing from tongs.bounded_provider_request_bindings where reservation_id=p_reservation_id;
 if found then
  if existing.serialized_body_sha256<>p_serialized_body_sha256 then raise exception 'research provider binding replay conflict' using errcode='23505'; end if;
  return to_jsonb(existing)||jsonb_build_object('replay',true);
 end if;
 retention_hash:=encode(extensions.digest(convert_to(q.retention_policy::text,'utf8'),'sha256'),'hex');
 insert into tongs.bounded_provider_request_bindings values(p_reservation_id,o.quote_id,o.operation_id,p_route_code,p_request_fingerprint,p_model,p_service_tier,
  o.pricing_revision_id,auth.accepted_authority_hash,retention_hash,p_estimator_revision,p_tokenizer_revision,p_serialized_body_sha256,p_serialized_bytes,
  p_tokenizer_input_tokens,p_protocol_overhead_tokens,p_utf8_byte_token_upper_bound,p_bounded_input_tokens,p_maximum_output_tokens,1,now()) returning * into existing;
 return to_jsonb(existing)||jsonb_build_object('replay',false);
end $$;


ALTER FUNCTION "tongs"."bind_owner_hearth_research_bounded_provider_request"("p_reservation_id" "uuid", "p_route_code" "text", "p_request_fingerprint" "text", "p_model" "text", "p_service_tier" "text", "p_estimator_revision" "text", "p_tokenizer_revision" "text", "p_serialized_body_sha256" "text", "p_serialized_bytes" bigint, "p_tokenizer_input_tokens" bigint, "p_protocol_overhead_tokens" bigint, "p_utf8_byte_token_upper_bound" bigint, "p_bounded_input_tokens" bigint, "p_maximum_output_tokens" bigint, "p_maximum_attempts" smallint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."bind_owner_runway_funding_reservation"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_reservation_id" "uuid", "p_operator_user_id" "uuid", "p_workspace_id" "uuid", "p_model" "text", "p_duration_seconds" integer, "p_ratio" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $_$
declare
  v_operation text := nullif(btrim(coalesce(p_operation_id,'')),'');
  v_reservation tongs.funding_reservations%rowtype;
  v_quote tongs.customer_spending_quotes%rowtype;
  v_pricing tongs.private_pricing_revisions%rowtype;
  v_policy tongs.private_pricing_policies%rowtype;
  v_existing tongs.runway_funding_bindings%rowtype;
  v_cost_stack jsonb;
  v_direct bigint;
  v_supporting bigint;
begin
  perform tongs._require_pricing_service_role();
  if v_operation is null or p_operation_fingerprint !~ '^[0-9a-f]{64}$'
     or p_reservation_id is null or p_operator_user_id is null
     or not tongs.is_platform_operator(p_operator_user_id) or p_workspace_id is null
     or p_model<>'gen4.5' or p_duration_seconds<>5 or p_ratio<>'1280:720' then
    raise exception 'invalid owner Runway funding binding' using errcode='22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('runway-funding-binding:'||v_operation,0));
  select * into v_existing from tongs.runway_funding_bindings where operation_id=v_operation;
  if found then
    if v_existing.operation_fingerprint<>p_operation_fingerprint
       or v_existing.reservation_id<>p_reservation_id
       or v_existing.user_id<>p_operator_user_id or v_existing.workspace_id<>p_workspace_id
       or v_existing.model<>p_model or v_existing.duration_seconds<>p_duration_seconds
       or v_existing.ratio<>p_ratio then
      raise exception 'owner Runway funding binding replay conflict' using errcode='23505';
    end if;
    return jsonb_build_object('operation_id',v_operation,'reservation_id',p_reservation_id,
      'replay',true,'provider_execution_authorized',false);
  end if;
  select * into v_reservation from tongs.funding_reservations where id=p_reservation_id for update;
  if not found or v_reservation.operation_id<>v_operation
     or v_reservation.user_id<>p_operator_user_id
     or v_reservation.funding_source_type<>'owner_budget'
     or tongs._funding_reservation_state(v_reservation.id)<>'reserved' then
    raise exception 'eligible owner reservation not found' using errcode='P0002';
  end if;
  select * into v_quote from tongs.customer_spending_quotes where id=v_reservation.quote_id;
  if not found or v_quote.user_id<>p_operator_user_id
     or v_quote.workspace_id is distinct from p_workspace_id or v_quote.operation_id<>v_operation
     or v_quote.tool<>'tongs_broll_v2' or v_quote.request_fingerprint<>p_operation_fingerprint
     or v_quote.normal_maximum_charge_micros<>0
     or v_quote.billable_failure_maximum_charge_micros<>0 or v_quote.customer_credit_units<>0
     or not exists(select 1 from tongs.customer_spending_quote_acceptances a
       where a.quote_id=v_quote.id and a.user_id=p_operator_user_id) then
    raise exception 'owner Runway quote identity does not match operation' using errcode='42501';
  end if;
  select * into v_pricing from tongs.private_pricing_revisions where id=v_quote.pricing_revision_id;
  select * into v_policy from tongs.private_pricing_policies where id=v_pricing.policy_id;
  if v_pricing.lifecycle_state<>'draft' or v_pricing.markup_basis_points is not null
     or v_pricing.customer_price_ceiling_micros is not null
     or v_pricing.billable_failure_ceiling_micros is not null
     or v_pricing.customer_credit_units is not null
     or lower(coalesce(v_policy.provider,''))<>'runway'
     or lower(coalesce(v_policy.sku,''))<>lower('gen4.5:'||p_duration_seconds::text||'s:'||p_ratio) then
    raise exception 'exact owner-only Runway cost revision required' using errcode='P0001';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object(
      'component_code',component.component_code,'component_kind',component.component_kind,
      'provider_label',component.provider_label,'success_ceiling_micros',component.success_ceiling_micros,
      'failure_ceiling_micros',component.failure_ceiling_micros,
      'cost_policy_revision',component.cost_policy_revision,'tail_policy',component.tail_policy,
      'tail_policy_details',component.tail_policy_details) order by component.ordinal),'[]'::jsonb),
    coalesce(sum(component.success_ceiling_micros) filter(where component.component_kind='direct_provider'
      and lower(component.provider_label)='runway'),0),
    coalesce(sum(component.success_ceiling_micros) filter(where not(component.component_kind='direct_provider'
      and lower(component.provider_label)='runway')),0)
  into v_cost_stack,v_direct,v_supporting
  from tongs.private_pricing_cost_components component where component.pricing_revision_id=v_pricing.id;
  if jsonb_array_length(v_cost_stack)=0 or v_direct<>600000 or v_supporting<>150000
     or v_pricing.full_cost_ceiling_micros<>750000
     or v_reservation.reserved_wholesale_spend_micros<>750000 then
    raise exception 'owner Runway reservation does not cover approved cost stack' using errcode='P0001';
  end if;
  insert into tongs.runway_funding_bindings(
    operation_id,operation_fingerprint,reservation_id,user_id,workspace_id,model,duration_seconds,
    ratio,direct_provider_ceiling_micros,supporting_cost_ceiling_micros,total_cost_ceiling_micros,
    pricing_revision_id,cost_stack_json
  ) values (v_operation,p_operation_fingerprint,p_reservation_id,p_operator_user_id,p_workspace_id,
    p_model,p_duration_seconds,p_ratio,v_direct,v_supporting,v_direct+v_supporting,v_pricing.id,v_cost_stack);
  return jsonb_build_object('operation_id',v_operation,'reservation_id',p_reservation_id,
    'replay',false,'provider_execution_authorized',false,
    'direct_provider_ceiling_micros',v_direct,'supporting_cost_ceiling_micros',v_supporting,
    'total_cost_ceiling_micros',v_direct+v_supporting,'customer_charge_micros',0);
end;
$_$;


ALTER FUNCTION "tongs"."bind_owner_runway_funding_reservation"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_reservation_id" "uuid", "p_operator_user_id" "uuid", "p_workspace_id" "uuid", "p_model" "text", "p_duration_seconds" integer, "p_ratio" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."bind_reference_visual_candidate_source_set"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
begin
 if new.source_set_revision_id is null then
   select coalesce(ro.source_set_revision_id,ao.source_set_revision_id) into new.source_set_revision_id
   from (select new.provenance_json->>'operation_id' operation_id) p
   left join tongs.reference_visual_render_operations ro on ro.operation_id=p.operation_id
   left join tongs.reference_visual_acquisition_operations ao on ao.operation_id=p.operation_id;
 end if;
 if new.source_set_revision_id is null then
   new.source_set_revision_id:=tongs.reference_visual_current_source_set(new.workspace_id,new.workpiece_id,new.opportunity_id);
 end if;
 if new.source_set_revision_id is null then raise exception 'candidate Source-set authority required' using errcode='23514';end if;
 if new.rights_declaration_revision_id is not null and not exists(
   select 1 from tongs.reference_visual_rights_declaration_revisions r
   where r.id=new.rights_declaration_revision_id and r.source_set_revision_id=new.source_set_revision_id
 ) then raise exception 'candidate rights must cover its exact Source set' using errcode='23514';end if;
 if new.sequence_revision_id is not null and exists(
   select 1 from tongs.reference_visual_sequence_membership member
   where member.sequence_revision_id=new.sequence_revision_id and not exists(
     select 1 from tongs.reference_visual_source_set_members source_member
     where source_member.source_set_revision_id=new.source_set_revision_id
       and source_member.source_revision_id=member.source_revision_id
       and source_member.workpiece_source_link_revision_id=member.workpiece_source_link_revision_id
   )
 ) then raise exception 'sequence members must belong to the candidate Source set' using errcode='23514';end if;
 return new;
end$$;


ALTER FUNCTION "tongs"."bind_reference_visual_candidate_source_set"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."bind_reference_visual_child_to_source_member"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare member_id uuid;
begin
 select sm.id into member_id from tongs.reference_visual_plan_sequences ps join lateral(select ss.* from tongs.reference_visual_source_set_revisions ss where ss.workspace_id=new.workspace_id and ss.workpiece_id=new.workpiece_id and ss.opportunity_id=new.opportunity_id and ss.plan_revision_id=ps.current_plan_revision_id order by ss.revision desc limit 1)set_revision on true join tongs.reference_visual_source_set_members sm on sm.source_set_revision_id=set_revision.id and sm.source_revision_id=new.source_revision_id and sm.workpiece_source_link_revision_id=new.workpiece_source_link_revision_id where ps.workspace_id=new.workspace_id and ps.workpiece_id=new.workpiece_id;
 new.source_set_member_id:=member_id;return new;
end$$;


ALTER FUNCTION "tongs"."bind_reference_visual_child_to_source_member"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."bind_runway_funding_reservation"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_reservation_id" "uuid", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_model" "text", "p_duration_seconds" integer, "p_ratio" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $_$
declare
  v_operation text := nullif(btrim(coalesce(p_operation_id, '')), '');
  v_reservation tongs.funding_reservations%rowtype;
  v_quote tongs.customer_spending_quotes%rowtype;
  v_pricing tongs.private_pricing_revisions%rowtype;
  v_policy tongs.private_pricing_policies%rowtype;
  v_existing tongs.runway_funding_bindings%rowtype;
  v_cost_stack jsonb;
  v_direct bigint;
  v_supporting bigint;
begin
  perform tongs._require_pricing_service_role();
  if v_operation is null or p_operation_fingerprint !~ '^[0-9a-f]{64}$'
     or p_reservation_id is null or p_user_id is null or p_workspace_id is null
     or p_model <> 'gen4.5' or p_duration_seconds not between 2 and 10
     or p_ratio not in ('1280:720', '720:1280') then
    raise exception 'invalid Runway funding binding' using errcode = '22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('runway-funding-binding:' || v_operation, 0));
  select * into v_existing from tongs.runway_funding_bindings where operation_id = v_operation;
  if found then
    if v_existing.operation_fingerprint <> p_operation_fingerprint
       or v_existing.reservation_id <> p_reservation_id
       or v_existing.user_id <> p_user_id
       or v_existing.workspace_id <> p_workspace_id
       or v_existing.model <> p_model
       or v_existing.duration_seconds <> p_duration_seconds
       or v_existing.ratio <> p_ratio then
      raise exception 'Runway funding binding replay conflict' using errcode = '23505';
    end if;
    return jsonb_build_object('operation_id', v_operation, 'reservation_id', p_reservation_id,
      'replay', true, 'provider_execution_authorized', false);
  end if;
  select * into v_reservation from tongs.funding_reservations where id = p_reservation_id for update;
  if not found or v_reservation.operation_id <> v_operation
     or v_reservation.user_id <> p_user_id
     or v_reservation.funding_source_type not in ('customer_deposit', 'paid_allowance', 'owner_budget')
     or tongs._funding_reservation_state(v_reservation.id) <> 'reserved' then
    raise exception 'eligible reserved funding allocation not found' using errcode = 'P0002';
  end if;
  select * into v_quote from tongs.customer_spending_quotes where id = v_reservation.quote_id;
  if not found or v_quote.user_id <> p_user_id or v_quote.workspace_id is distinct from p_workspace_id
     or v_quote.operation_id <> v_operation or v_quote.tool <> 'tongs_broll_v2'
     or v_quote.request_fingerprint <> p_operation_fingerprint then
    raise exception 'Runway quote identity does not match operation' using errcode = '42501';
  end if;
  if v_reservation.funding_source_type = 'owner_budget' and not tongs.is_platform_operator(p_user_id) then
    raise exception 'owner budget requires platform-operator operation identity' using errcode = '42501';
  end if;
  select * into v_pricing from tongs.private_pricing_revisions where id = v_quote.pricing_revision_id;
  select * into v_policy from tongs.private_pricing_policies where id = v_pricing.policy_id;
  if v_pricing.lifecycle_state <> 'review_ready' or lower(coalesce(v_policy.provider, '')) <> 'runway'
     or lower(coalesce(v_policy.sku, '')) <> lower('gen4.5:' || p_duration_seconds::text || 's:' || p_ratio) then
    raise exception 'exact Runway SKU pricing revision required' using errcode = 'P0001';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object(
      'component_code', component.component_code,
      'component_kind', component.component_kind,
      'provider_label', component.provider_label,
      'success_ceiling_micros', component.success_ceiling_micros,
      'failure_ceiling_micros', component.failure_ceiling_micros,
      'cost_policy_revision', component.cost_policy_revision,
      'tail_policy', component.tail_policy,
      'tail_policy_details', component.tail_policy_details
    ) order by component.ordinal), '[]'::jsonb),
    coalesce(sum(component.success_ceiling_micros) filter (
      where component.component_kind = 'direct_provider' and lower(component.provider_label) = 'runway'
    ), 0),
    coalesce(sum(component.success_ceiling_micros) filter (
      where not (component.component_kind = 'direct_provider' and lower(component.provider_label) = 'runway')
    ), 0)
  into v_cost_stack, v_direct, v_supporting
  from tongs.private_pricing_cost_components component
  where component.pricing_revision_id = v_pricing.id;
  if jsonb_array_length(v_cost_stack) = 0 or v_direct <> p_duration_seconds::bigint * 120000
     or v_direct + v_supporting <> v_pricing.full_cost_ceiling_micros
     or v_pricing.full_cost_ceiling_micros <> v_reservation.reserved_wholesale_spend_micros then
    raise exception 'Runway reservation does not cover the complete priced cost stack' using errcode = 'P0001';
  end if;
  insert into tongs.runway_funding_bindings(
    operation_id, operation_fingerprint, reservation_id, user_id, workspace_id,
    model, duration_seconds, ratio, direct_provider_ceiling_micros,
    supporting_cost_ceiling_micros, total_cost_ceiling_micros,
    pricing_revision_id, cost_stack_json
  ) values (
    v_operation, p_operation_fingerprint, p_reservation_id, p_user_id, p_workspace_id,
    p_model, p_duration_seconds, p_ratio, v_direct, v_supporting,
    v_direct + v_supporting, v_pricing.id, v_cost_stack
  );
  return jsonb_build_object('operation_id', v_operation, 'reservation_id', p_reservation_id,
    'replay', false, 'provider_execution_authorized', false,
    'direct_provider_ceiling_micros', v_direct,
    'supporting_cost_ceiling_micros', v_supporting,
    'total_cost_ceiling_micros', v_direct + v_supporting);
end;
$_$;


ALTER FUNCTION "tongs"."bind_runway_funding_reservation"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_reservation_id" "uuid", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_model" "text", "p_duration_seconds" integer, "p_ratio" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."bind_spending_quote_authority"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare v_authority jsonb; v_hash text;
begin
  v_authority:=tongs._resolve_spending_authority(new.user_id,new.workspace_id,new.tool);
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'quote_id',new.id,'acting_user_id',new.user_id,
    'payer_kind',v_authority->>'payer_kind','payer_user_id',v_authority->>'payer_user_id',
    'org_id',v_authority->>'org_id','preference_revision_id',v_authority->>'preference_revision_id',
    'organization_account_revision_id',v_authority->>'organization_account_revision_id',
    'organization_permission_revision_id',v_authority->>'organization_permission_revision_id',
    'owner_principal_revision',v_authority->>'owner_principal_revision',
    'route_code',new.tool,'request_fingerprint',new.request_fingerprint,
    'pricing_revision_id',new.pricing_revision_id,'quote_hash',new.quote_hash,'expires_at',new.expires_at
  )::text,'utf8'),'sha256'),'hex');
  insert into tongs.spending_quote_authority_bindings(
    quote_id,acting_user_id,payer_kind,payer_user_id,org_id,preference_revision_id,
    organization_account_revision_id,organization_permission_revision_id,
    owner_principal_revision,accepted_authority_hash
  ) values(
    new.id,new.user_id,v_authority->>'payer_kind',(v_authority->>'payer_user_id')::uuid,
    nullif(v_authority->>'org_id','')::uuid,nullif(v_authority->>'preference_revision_id','')::uuid,
    nullif(v_authority->>'organization_account_revision_id','')::uuid,
    nullif(v_authority->>'organization_permission_revision_id','')::uuid,
    nullif(v_authority->>'owner_principal_revision','')::integer,v_hash
  );
  return new;
end $$;


ALTER FUNCTION "tongs"."bind_spending_quote_authority"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."blend_structural_intent_vector"("p_existing" "jsonb", "p_incoming" "jsonb", "p_weight" double precision) RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'tongs', 'pg_temp'
    AS $$
declare
  v_existing jsonb := case
    when jsonb_typeof(coalesce(p_existing, '{}'::jsonb)) = 'object' then coalesce(p_existing, '{}'::jsonb)
    else '{}'::jsonb
  end;
  v_incoming jsonb := case
    when jsonb_typeof(coalesce(p_incoming, '{}'::jsonb)) = 'object' then coalesce(p_incoming, '{}'::jsonb)
    else '{}'::jsonb
  end;
  v_weight double precision := least(1.0, greatest(0.01, coalesce(p_weight, 0.15)));
  v_key text;
  v_result jsonb := '{}'::jsonb;
  v_has_existing boolean;
  v_has_incoming boolean;
  v_existing_num double precision;
  v_incoming_num double precision;
begin
  for v_key in
    select keys.key
    from (
      select jsonb_object_keys(v_existing) as key
      union
      select jsonb_object_keys(v_incoming) as key
    ) keys
  loop
    v_has_existing := jsonb_typeof(v_existing -> v_key) = 'number';
    v_has_incoming := jsonb_typeof(v_incoming -> v_key) = 'number';

    if v_has_existing and v_has_incoming then
      v_existing_num := (v_existing ->> v_key)::double precision;
      v_incoming_num := (v_incoming ->> v_key)::double precision;
      v_result := v_result || jsonb_build_object(
        v_key,
        (v_existing_num * (1.0 - v_weight)) + (v_incoming_num * v_weight)
      );
    elsif v_has_incoming then
      v_incoming_num := (v_incoming ->> v_key)::double precision;
      v_result := v_result || jsonb_build_object(v_key, v_incoming_num);
    elsif v_has_existing then
      v_existing_num := (v_existing ->> v_key)::double precision;
      v_result := v_result || jsonb_build_object(v_key, v_existing_num);
    end if;
  end loop;

  return v_result;
end;
$$;


ALTER FUNCTION "tongs"."blend_structural_intent_vector"("p_existing" "jsonb", "p_incoming" "jsonb", "p_weight" double precision) OWNER TO "postgres";


