CREATE OR REPLACE FUNCTION "tongs"."brand_rule_errors"("p_rules" "jsonb") RETURNS "text"[]
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'tongs', 'extensions'
    AS $_$
declare v_errors text[]:='{}'; v_value text;
begin
 if jsonb_typeof(p_rules)<>'object' then return array['Rules must be an object.']; end if;
 if length(btrim(coalesce(p_rules#>>'{public_identity,program_name}','')))=0 then v_errors:=array_append(v_errors,'Public program name is required.'); end if;
 foreach v_value in array array[coalesce(p_rules#>>'{palette,primary}',''),coalesce(p_rules#>>'{palette,secondary}',''),coalesce(p_rules#>>'{palette,accent}','')] loop if v_value!~*'^#[0-9a-f]{6}$' then v_errors:=array_append(v_errors,'Palette colors must be six-digit hex values.'); exit; end if; end loop;
 if length(btrim(coalesce(p_rules#>>'{typography,heading_family}','')))=0 or length(btrim(coalesce(p_rules#>>'{typography,body_family}','')))=0 then v_errors:=array_append(v_errors,'Basic typography is required.'); end if;
 if coalesce((p_rules#>>'{audio,music_volume}')::numeric,-1)<0 or coalesce((p_rules#>>'{audio,music_volume}')::numeric,2)>1 or coalesce((p_rules#>>'{audio,ducking}')::numeric,-1)<0 or coalesce((p_rules#>>'{audio,ducking}')::numeric,2)>1 then v_errors:=array_append(v_errors,'Audio values must be between zero and one.'); end if;
 return v_errors; exception when invalid_text_representation then return array['Brand rules contain invalid numeric values.']; end $_$;


ALTER FUNCTION "tongs"."brand_rule_errors"("p_rules" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."brand_rules_hash"("p_rules" "jsonb") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'tongs', 'extensions'
    AS $$
  select encode(extensions.digest(convert_to(coalesce(p_rules,'{}'::jsonb)::text,'UTF8'),'sha256'),'hex') $$;


ALTER FUNCTION "tongs"."brand_rules_hash"("p_rules" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."broll_current_creative_input"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_beat_id" "uuid", "p_creator_direction" "text", "p_interpretation_contract_version" "text", "p_synthesis_contract_version" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare v_seq tongs.broll_plan_sequences%rowtype; v_plan tongs.broll_plan_revisions%rowtype; v_member tongs.broll_plan_beat_membership%rowtype; v_beat tongs.broll_beat_revisions%rowtype; v_payload jsonb; v_hash text;
begin
 if not tongs.has_workspace_role(p_workspace_id,'viewer') then raise exception 'workspace viewer authority required' using errcode='42501'; end if;
 select * into v_seq from tongs.broll_plan_sequences where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id;
 if not found or v_seq.current_plan_revision_id is null then return jsonb_build_object('disposition','plan_missing'); end if;
 select * into v_plan from tongs.broll_plan_revisions where id=v_seq.current_plan_revision_id;
 select * into v_member from tongs.broll_plan_beat_membership where plan_revision_id=v_plan.id and beat_id=p_beat_id;
 if not found then return jsonb_build_object('disposition','beat_not_current'); end if;
 select * into v_beat from tongs.broll_beat_revisions where id=v_member.beat_revision_id;
 v_payload:=jsonb_build_object(
   'workspace_id',p_workspace_id,'workpiece_id',p_workpiece_id,'beat_id',p_beat_id,'ordinal',v_member.ordinal,
   'script_approval_id',v_plan.script_approval_id,'script_approval_revision',v_plan.script_approval_revision,'script_content_hash',v_plan.script_content_hash,
   'source_context',jsonb_build_object('before',v_beat.context_before,'focus',v_beat.context_focus,'after',v_beat.context_after,'anchor_assessment',v_beat.canonical_anchor_assessment),
   'narrative_purpose',v_beat.narrative_purpose,'placement_hint',v_beat.placement_hint,'duration_target_ms',v_beat.duration_target_ms,
   'shot_type',v_beat.shot_type,'motion_intent',v_beat.motion_intent,'pacing',v_beat.mood_pacing,
   'creator_direction',coalesce(p_creator_direction,''),
   'interpretation_contract_version',p_interpretation_contract_version,'synthesis_contract_version',p_synthesis_contract_version
 );
 v_hash:=encode(extensions.digest(convert_to(v_payload::text,'UTF8'),'sha256'),'hex');
 return jsonb_build_object('disposition','current','creative_input_hash',v_hash,'creative_inputs',v_payload,'plan_revision',to_jsonb(v_plan),'membership',to_jsonb(v_member),'beat_revision',to_jsonb(v_beat));
end $$;


ALTER FUNCTION "tongs"."broll_current_creative_input"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_beat_id" "uuid", "p_creator_direction" "text", "p_interpretation_contract_version" "text", "p_synthesis_contract_version" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."calendar_event_assignments_enforce_workspace"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare
  v_event_workspace uuid;
  v_assignment_workspace uuid;
begin
  select ce.workspace_id
  into v_event_workspace
  from tongs.calendar_events ce
  where ce.id = new.event_id;

  if v_event_workspace is null then
    raise exception 'Calendar event not found for assignment link'
      using errcode = '23503';
  end if;

  select e.workspace_id
  into v_assignment_workspace
  from tongs.episodes e
  where e.id = new.assignment_id;

  if v_assignment_workspace is null then
    raise exception 'Episode/workpiece not found for calendar assignment link'
      using errcode = '23503';
  end if;

  if new.workspace_id is null then
    new.workspace_id := v_event_workspace;
  end if;

  if new.workspace_id <> v_event_workspace
     or new.workspace_id <> v_assignment_workspace then
    raise exception 'Calendar event assignment workspace mismatch'
      using errcode = '22023';
  end if;

  return new;
end
$$;


ALTER FUNCTION "tongs"."calendar_event_assignments_enforce_workspace"() OWNER TO "postgres";


