CREATE OR REPLACE FUNCTION "tongs"."checkpoint_youtube_publication_job"("p_job_id" "uuid", "p_worker_id" "text", "p_state" "text", "p_current_stage" "text", "p_transferred_bytes" bigint, "p_total_bytes" bigint, "p_next_run_at" timestamp with time zone, "p_provider_processing_state" "text" DEFAULT NULL::"text", "p_external_object_id" "text" DEFAULT NULL::"text", "p_external_url" "text" DEFAULT NULL::"text", "p_retryable" boolean DEFAULT false, "p_user_action_code" "text" DEFAULT NULL::"text", "p_encrypted_session_uri" "text" DEFAULT NULL::"text", "p_session_encryption_key_version" "text" DEFAULT NULL::"text", "p_session_ciphertext_version" "text" DEFAULT NULL::"text", "p_credential_generation_id" "uuid" DEFAULT NULL::"uuid", "p_provider_request_id" "text" DEFAULT NULL::"text", "p_raw_transport_evidence" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare v_job tongs.youtube_publication_jobs%rowtype;
begin
  if auth.role()<>'service_role' then raise exception 'Forbidden' using errcode='42501'; end if;
  select * into v_job from tongs.youtube_publication_jobs where id=p_job_id for update;
  if not found or v_job.lease_owner<>p_worker_id or v_job.lease_expires_at<now() then return jsonb_build_object('disposition','lease_lost'); end if;
  if p_transferred_bytes<v_job.transferred_bytes or p_total_bytes<v_job.total_bytes then return jsonb_build_object('disposition','invalid','code','upload_progress_must_be_monotonic'); end if;
  update tongs.youtube_publication_jobs set state=p_state,current_stage=p_current_stage,transferred_bytes=p_transferred_bytes,total_bytes=p_total_bytes,
    next_run_at=p_next_run_at,provider_processing_state=coalesce(p_provider_processing_state,provider_processing_state),external_object_id=coalesce(p_external_object_id,external_object_id),external_url=coalesce(p_external_url,external_url),retryable=p_retryable,user_action_code=p_user_action_code,
    lease_owner=null,lease_expires_at=null,last_heartbeat_at=now(),updated_at=now() where id=p_job_id;
  update tongs.youtube_publication_job_secrets set encrypted_resumable_session_uri=coalesce(p_encrypted_session_uri,encrypted_resumable_session_uri),session_encryption_key_version=coalesce(p_session_encryption_key_version,session_encryption_key_version),session_ciphertext_version=coalesce(p_session_ciphertext_version,session_ciphertext_version),credential_generation_id=coalesce(p_credential_generation_id,credential_generation_id),provider_request_id=coalesce(p_provider_request_id,provider_request_id),raw_transport_evidence=raw_transport_evidence||coalesce(p_raw_transport_evidence,'{}'::jsonb),updated_at=now() where job_id=p_job_id;
  return jsonb_build_object('disposition','checkpointed','job_id',p_job_id,'state',p_state);
end; $$;


ALTER FUNCTION "tongs"."checkpoint_youtube_publication_job"("p_job_id" "uuid", "p_worker_id" "text", "p_state" "text", "p_current_stage" "text", "p_transferred_bytes" bigint, "p_total_bytes" bigint, "p_next_run_at" timestamp with time zone, "p_provider_processing_state" "text", "p_external_object_id" "text", "p_external_url" "text", "p_retryable" boolean, "p_user_action_code" "text", "p_encrypted_session_uri" "text", "p_session_encryption_key_version" "text", "p_session_ciphertext_version" "text", "p_credential_generation_id" "uuid", "p_provider_request_id" "text", "p_raw_transport_evidence" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."claim_barstock_discovery_refresh"("p_workspace_id" "uuid", "p_preference_revision" bigint, "p_trigger" "text", "p_operation_key" "text", "p_lease_token_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare
  u uuid := auth.uid();
  p tongs.workspace_discovery_preferences%rowtype;
  r tongs.barstock_discovery_runs%rowtype;
  c6 int;
  c24 int;
  next_eligible timestamptz;
begin
  if u is null or not tongs.has_workspace_role(p_workspace_id, 'editor') then
    return jsonb_build_object('outcome', 'denied');
  end if;

  select * into p
  from tongs.workspace_discovery_preferences
  where workspace_id = p_workspace_id
    and user_id = u
    and revision = p_preference_revision;

  if p.user_id is null
    or not p.enabled
    or (p_trigger = 'automatic' and not p.auto_refresh_authorized) then
    return jsonb_build_object('outcome', 'not_authorized');
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(p_workspace_id::text || ':' || u::text || ':topic-discovery', 0)
  );

  select * into r
  from tongs.barstock_discovery_runs
  where workspace_id = p_workspace_id
    and user_id = u
    and operation_key = p_operation_key
  for update;

  if r.id is not null then
    if r.preference_revision <> p_preference_revision then
      return jsonb_build_object('outcome', 'operation_identity_conflict', 'run_id', r.id);
    end if;
    if r.status in ('ready', 'partial', 'empty') then
      return jsonb_build_object('outcome', 'existing', 'run_id', r.id);
    end if;
    if r.lease_expires_at > now() then
      return jsonb_build_object('outcome', 'in_progress', 'run_id', r.id);
    end if;
    if r.attempt_count >= 2 then
      return jsonb_build_object('outcome', 'attempts_exhausted', 'run_id', r.id);
    end if;

    update tongs.barstock_discovery_runs
    set attempt_count = attempt_count + 1,
      status = 'leased',
      lease_token_hash = p_lease_token_hash,
      lease_expires_at = now() + interval '5 minutes',
      failure_reason = null,
      updated_at = now()
    where id = r.id
    returning * into r;

    return jsonb_build_object(
      'outcome', 'claimed',
      'run_id', r.id,
      'lease_expires_at', r.lease_expires_at,
      'recovered', true
    );
  end if;

  if exists(
    select 1
    from tongs.barstock_discovery_runs
    where workspace_id = p_workspace_id
      and user_id = u
      and status in ('leased', 'refreshing')
      and lease_expires_at > now()
  ) then
    return jsonb_build_object('outcome', 'in_progress');
  end if;

  select
    count(*) filter (where first_provider_call_at > now() - interval '6 hours'),
    count(*) filter (where first_provider_call_at > now() - interval '24 hours')
  into c6, c24
  from tongs.barstock_discovery_runs
  where workspace_id = p_workspace_id and user_id = u;

  if c6 >= 1 or c24 >= 4 then
    next_eligible := tongs.barstock_discovery_next_eligible_at(p_workspace_id, u);
    return jsonb_build_object(
      'outcome', 'budget_blocked',
      'next_eligible_at', next_eligible
    );
  end if;

  insert into tongs.barstock_discovery_runs(
    workspace_id,
    user_id,
    preference_revision,
    preference_hash,
    operation_key,
    trigger_kind,
    status,
    lease_token_hash,
    lease_expires_at
  ) values (
    p_workspace_id,
    u,
    p.revision,
    encode(extensions.digest(convert_to(to_jsonb(p)::text, 'UTF8'), 'sha256'), 'hex'),
    p_operation_key,
    p_trigger,
    'leased',
    p_lease_token_hash,
    now() + interval '5 minutes'
  ) returning * into r;

  return jsonb_build_object(
    'outcome', 'claimed',
    'run_id', r.id,
    'lease_expires_at', r.lease_expires_at,
    'recovered', false
  );
end;
$$;


ALTER FUNCTION "tongs"."claim_barstock_discovery_refresh"("p_workspace_id" "uuid", "p_preference_revision" bigint, "p_trigger" "text", "p_operation_key" "text", "p_lease_token_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."claim_broll_runway_poll"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_provider_task_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare v_op tongs.broll_operation_receipts%rowtype; v_delay numeric;
begin
 select * into v_op from tongs.broll_operation_receipts where operation_id=p_operation_id for update;
 if not found then return jsonb_build_object('disposition','operation_not_found'); end if;
 if not tongs.has_workspace_role(v_op.workspace_id,'editor') then raise exception 'workspace editor authority required' using errcode='42501'; end if;
 if v_op.operation_fingerprint<>p_operation_fingerprint or v_op.provider_task_id is distinct from p_provider_task_id then return jsonb_build_object('disposition','provider_task_conflict'); end if;
 if v_op.state<>'provider_submitted' then return jsonb_build_object('disposition','replay','operation',to_jsonb(v_op)); end if;
 if v_op.provider_next_poll_at is not null and v_op.provider_next_poll_at>now() then return jsonb_build_object('disposition','poll_not_due','retry_at',v_op.provider_next_poll_at,'operation',to_jsonb(v_op)); end if;
 v_delay:=least(60,5*power(2,least(v_op.provider_poll_attempt,4)))+(random()*1.5);
 update tongs.broll_operation_receipts set provider_poll_attempt=provider_poll_attempt+1,provider_last_polled_at=now(),provider_next_poll_at=now()+make_interval(secs=>v_delay),updated_at=now() where operation_id=p_operation_id returning * into v_op;
 return jsonb_build_object('disposition','poll_claimed','operation',to_jsonb(v_op));
end $$;


ALTER FUNCTION "tongs"."claim_broll_runway_poll"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_provider_task_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."claim_publication_attempt"("p_publication_operation_id" "uuid", "p_retry" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare v_user uuid:=auth.uid(); v_op tongs.publication_operations%rowtype; v_latest tongs.publication_attempts%rowtype; v_number integer; v_id uuid; v_destination tongs.publishing_executable_destinations%rowtype;
begin
  select * into v_op from tongs.publication_operations where id=p_publication_operation_id for update;
  if not found then return jsonb_build_object('disposition','blocked','code','publication_operation_missing'); end if;
  if v_user is null or not tongs.has_workspace_role(v_op.workspace_id,'editor') then raise exception 'Not authorized to claim publication attempt' using errcode='42501'; end if;
  select * into v_destination from tongs.publishing_executable_destinations where id=v_op.executable_destination_id;
  if not found or v_destination.state<>'active' or v_destination.current_capability_revision_id<>v_op.destination_capability_revision_id or not tongs.publishing_destination_grant_is_active(v_op.workspace_id,v_op.executable_destination_id) then return jsonb_build_object('disposition','blocked','code','publication_operation_blocked'); end if;
  select * into v_latest from tongs.publication_attempts where publication_operation_id=v_op.id order by attempt_number desc limit 1;
  if found then
    if v_latest.state in('reserved','preparing_execution','submitting') then return jsonb_build_object('disposition','blocked','code','publication_attempt_already_active'); end if;
    if v_latest.state='succeeded' then return jsonb_build_object('disposition','blocked','code','publication_operation_already_succeeded'); end if;
    if v_latest.state='outcome_unknown' then return jsonb_build_object('disposition','blocked','code','publication_external_reconciliation_required'); end if;
    if not p_retry or v_latest.state not in('confirmed_failure','recoverable_failure') then return jsonb_build_object('disposition','blocked','code','publication_safe_retry_unavailable'); end if;
    v_number:=v_latest.attempt_number+1;
  else
    if p_retry then return jsonb_build_object('disposition','blocked','code','publication_safe_retry_unavailable'); end if;
    v_number:=1;
  end if;
  insert into tongs.publication_attempts(publication_operation_id,attempt_number,state) values(v_op.id,v_number,'reserved') returning id into v_id;
  return jsonb_build_object('disposition','claimed','publication_operation_id',v_op.id,'publication_attempt_id',v_id,'attempt_number',v_number,'state','reserved');
exception when unique_violation then return jsonb_build_object('disposition','blocked','code','publication_attempt_already_active'); end; $$;


ALTER FUNCTION "tongs"."claim_publication_attempt"("p_publication_operation_id" "uuid", "p_retry" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."claim_youtube_publication_job"("p_worker_id" "text", "p_lease_seconds" integer DEFAULT 600) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare v_job tongs.youtube_publication_jobs%rowtype;
begin
  if auth.role()<>'service_role' then raise exception 'Forbidden' using errcode='42501'; end if;
  select * into v_job from tongs.youtube_publication_jobs where state not in('published','scheduled','blocked','failed','outcome_unknown') and next_run_at<=now() and (lease_expires_at is null or lease_expires_at<now()) order by next_run_at,created_at for update skip locked limit 1;
  if not found then return jsonb_build_object('disposition','empty'); end if;
  update tongs.youtube_publication_jobs set lease_owner=p_worker_id,lease_expires_at=now()+make_interval(secs=>greatest(30,least(p_lease_seconds,840))),last_heartbeat_at=now(),attempt_count=attempt_count+1,updated_at=now() where id=v_job.id;
  return jsonb_build_object('disposition','claimed','job_id',v_job.id,'publication_operation_id',v_job.publication_operation_id,'publication_attempt_id',v_job.publication_attempt_id,'attempt_state',(select state from tongs.publication_attempts where id=v_job.publication_attempt_id),'finalized_package_id',v_job.finalized_package_id,'state',v_job.state,'current_stage',v_job.current_stage,'transferred_bytes',v_job.transferred_bytes,'total_bytes',v_job.total_bytes,'attempt_count',v_job.attempt_count,'external_object_id',v_job.external_object_id,
    'resolved_package',(select resolved_package from tongs.quench_destination_package_revisions where id=v_job.finalized_package_id),
    'connection_id',(select d.connection_id from tongs.publication_operations o join tongs.publishing_executable_destinations d on d.id=o.executable_destination_id where o.id=v_job.publication_operation_id),
    'secret',(select jsonb_build_object('encrypted_resumable_session_uri',s.encrypted_resumable_session_uri,'session_encryption_key_version',s.session_encryption_key_version,'session_ciphertext_version',s.session_ciphertext_version,'credential_generation_id',s.credential_generation_id) from tongs.youtube_publication_job_secrets s where s.job_id=v_job.id));
end; $$;


ALTER FUNCTION "tongs"."claim_youtube_publication_job"("p_worker_id" "text", "p_lease_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."clear_my_ai_operation_model_override"("p_operation_code" "text", "p_expected_revision" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare uid uuid:=auth.uid(); prior integer;
begin
 if uid is null then raise exception 'authentication required' using errcode='28000'; end if;
 perform pg_advisory_xact_lock(hashtextextended('ai-operation-model:'||uid::text||':'||p_operation_code,0));
 select coalesce(max(revision),0) into prior from tongs.ai_operation_model_override_revisions where user_id=uid and operation_code=p_operation_code;
 if p_expected_revision is not null and p_expected_revision<>prior then raise exception 'operation override changed; reload' using errcode='40001'; end if;
 insert into tongs.ai_operation_model_override_revisions(id,user_id,operation_code,revision,override_state,model_identity_id) values(gen_random_uuid(),uid,p_operation_code,prior+1,'clear',null);
 return tongs.read_my_ai_operation_model_override(p_operation_code);
end $$;


ALTER FUNCTION "tongs"."clear_my_ai_operation_model_override"("p_operation_code" "text", "p_expected_revision" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."clear_my_hearth_conversation"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_expected_generation" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare v_thread tongs.hearth_conversation_threads%rowtype;
begin
  perform tongs.assert_workspace_role(p_workspace_id,'editor');
  select * into v_thread from tongs.hearth_conversation_threads t
    where t.workspace_id=p_workspace_id and t.workpiece_id=p_workpiece_id for update;
  if not found then return jsonb_build_object('status','empty','generation',1); end if;
  if v_thread.generation<>p_expected_generation then
    return jsonb_build_object('status','generation_conflict','generation',v_thread.generation);
  end if;
  delete from tongs.hearth_conversation_messages where workpiece_id=p_workpiece_id and generation=v_thread.generation;
  update tongs.hearth_conversation_threads set generation=generation+1,next_sequence=1,completeness='complete',updated_at=now()
    where workpiece_id=p_workpiece_id returning generation into v_thread.generation;
  return jsonb_build_object('status','cleared','generation',v_thread.generation);
end $$;


ALTER FUNCTION "tongs"."clear_my_hearth_conversation"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_expected_generation" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."clear_workspace_default_brand_profile"("p_workspace_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$ begin perform tongs.assert_workspace_role(p_workspace_id,'editor'); delete from tongs.workspace_default_brand_profiles where workspace_id=p_workspace_id; return jsonb_build_object('workspace_id',p_workspace_id,'profile_id',null); end $$;


ALTER FUNCTION "tongs"."clear_workspace_default_brand_profile"("p_workspace_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."close_customer_paid_execution_test_authorization"("p_authorization_id" "uuid", "p_operator_user_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_reason text:=nullif(btrim(coalesce(p_reason,'')), '');
  v_authorization tongs.customer_paid_execution_test_authorizations%rowtype;
  v_latest tongs.customer_paid_execution_test_authorization_revisions%rowtype;
begin
  perform tongs._require_pricing_service_role();
  if p_authorization_id is null or p_operator_user_id is null or v_reason is null
     or not tongs.is_platform_operator(p_operator_user_id) then
    raise exception 'invalid customer test authorization closure' using errcode='22023';
  end if;
  select * into v_authorization
  from tongs.customer_paid_execution_test_authorizations
  where id=p_authorization_id;
  if not found then raise exception 'customer test authorization not found' using errcode='P0002'; end if;
  perform pg_advisory_xact_lock(hashtextextended('customer-paid-test-authorization:'||v_authorization.id::text,0));
  select * into v_latest from tongs.customer_paid_execution_test_authorization_revisions
    where authorization_id=v_authorization.id order by revision desc limit 1;
  if v_latest.status='closed' then
    return jsonb_build_object('authorization_id',v_authorization.id,'status','closed','replay',true);
  end if;
  insert into tongs.customer_paid_execution_test_authorization_revisions(
    authorization_id,revision,status,reason,actor_id
  ) values (v_authorization.id,v_latest.revision+1,'closed',v_reason,p_operator_user_id);
  return jsonb_build_object('authorization_id',v_authorization.id,'status','closed','replay',false,
    'new_reservations_authorized',false,'reconciliation_preserved',true);
end $$;


ALTER FUNCTION "tongs"."close_customer_paid_execution_test_authorization"("p_authorization_id" "uuid", "p_operator_user_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."close_customer_paid_execution_test_authorization_for_reservatio"("p_reservation_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_reason text:=nullif(btrim(coalesce(p_reason,'')),'');
  v_authorization tongs.customer_paid_execution_test_authorizations%rowtype;
  v_latest tongs.customer_paid_execution_test_authorization_revisions%rowtype;
begin
  perform tongs._require_pricing_service_role();
  if p_reservation_id is null or v_reason is null then
    raise exception 'invalid customer test authorization closure' using errcode='22023';
  end if;
  select a.* into v_authorization
  from tongs.customer_paid_execution_test_authorization_quotes binding
  join tongs.customer_paid_execution_test_authorizations a
    on a.id=binding.authorization_id
  join tongs.funding_reservations reservation on reservation.quote_id=binding.quote_id
  where reservation.id=p_reservation_id;
  if not found then raise exception 'customer test authorization not found' using errcode='P0002'; end if;
  perform pg_advisory_xact_lock(hashtextextended('customer-paid-test-authorization:'||v_authorization.id::text,0));
  select * into v_latest from tongs.customer_paid_execution_test_authorization_revisions
    where authorization_id=v_authorization.id order by revision desc limit 1;
  if v_latest.status='closed' then
    return jsonb_build_object('authorization_id',v_authorization.id,'status','closed','replay',true);
  end if;
  insert into tongs.customer_paid_execution_test_authorization_revisions(
    authorization_id,revision,status,reason,actor_id
  ) values (v_authorization.id,v_latest.revision+1,'closed',v_reason,v_authorization.created_by);
  return jsonb_build_object('authorization_id',v_authorization.id,'status','closed','replay',false,
    'new_reservations_authorized',false,'reconciliation_preserved',true);
end $$;


ALTER FUNCTION "tongs"."close_customer_paid_execution_test_authorization_for_reservatio"("p_reservation_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."close_hammer_customer_test_acceptance"("p_close_id" "uuid", "p_authorization_id" "uuid", "p_actor_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_scope tongs.customer_paid_execution_scope_authorizations%rowtype;
  v_existing tongs.hammer_customer_test_acceptance_closures%rowtype;
  v_rollout tongs.openai_text_rollout_revisions%rowtype;
  v_test_loss tongs.openai_text_failure_loss_rollout_revisions%rowtype;
  v_live_loss tongs.openai_text_failure_loss_rollout_revisions%rowtype;
begin
  perform tongs._require_pricing_service_role();
  if p_close_id is null or p_authorization_id is null or p_actor_id is null
     or not tongs.is_platform_operator(p_actor_id)
     or length(btrim(coalesce(p_reason, ''))) not between 8 and 500 then
    raise exception 'invalid Hammer customer Test shutdown'
      using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended('hammer-customer-test-acceptance', 0)
  );

  select * into v_existing
  from tongs.hammer_customer_test_acceptance_closures
  where id = p_close_id;
  if found then
    if v_existing.authorization_id <> p_authorization_id
       or v_existing.actor_id <> p_actor_id
       or v_existing.reason <> btrim(p_reason)
       or v_existing.route_revision <> 5
       or v_existing.test_loss_revision <> 3
       or (select revision from tongs.openai_text_rollout_revisions
           where route_code = 'hammer.transcript_cleanup'
           order by revision desc limit 1) <> 5
       or (select mode from tongs.openai_text_rollout_revisions
           where route_code = 'hammer.transcript_cleanup'
           order by revision desc limit 1) <> 'halt_new'
       or (select revision from tongs.openai_text_failure_loss_rollout_revisions
           where route_code = 'hammer.transcript_cleanup'
             and financial_environment = 'test'
           order by revision desc limit 1) <> 3
       or (select mode from tongs.openai_text_failure_loss_rollout_revisions
           where route_code = 'hammer.transcript_cleanup'
             and financial_environment = 'test'
           order by revision desc limit 1) <> 'halt_new'
       or (select revision from tongs.openai_text_failure_loss_rollout_revisions
           where route_code = 'hammer.transcript_cleanup'
             and financial_environment = 'live'
           order by revision desc limit 1) <> 1
       or (select mode from tongs.openai_text_failure_loss_rollout_revisions
           where route_code = 'hammer.transcript_cleanup'
             and financial_environment = 'live'
           order by revision desc limit 1) <> 'halt_new'
       or exists (
         select 1
         from tongs.customer_paid_execution_scope_authorizations scope_auth
         where scope_auth.route_code = 'hammer.transcript_cleanup'
           and tongs._hammer_scope_is_effective(
             scope_auth.id, clock_timestamp()
           )
       ) then
      raise exception 'Hammer customer Test shutdown replay conflict'
        using errcode = '23505';
    end if;
    return jsonb_build_object(
      'close_id', v_existing.id,
      'authorization_id', v_existing.authorization_id,
      'route_revision', 5,
      'route_mode', 'halt_new',
      'test_loss_revision', 3,
      'test_loss_mode', 'halt_new',
      'live_loss_revision', 1,
      'live_loss_mode', 'halt_new',
      'effective_scope_count', 0,
      'replay', true
    );
  end if;

  if exists (
    select 1 from tongs.hammer_customer_test_acceptance_closures
    where authorization_id = p_authorization_id
  ) then
    raise exception 'Hammer customer Test shutdown already exists'
      using errcode = '23505';
  end if;

  select * into v_scope
  from tongs.customer_paid_execution_scope_authorizations
  where id = p_authorization_id;
  if not found
     or v_scope.authorization_kind <> 'normal_customer'
     or v_scope.financial_environment <> 'test'
     or v_scope.route_code <> 'hammer.transcript_cleanup'
     or v_scope.provider <> 'openai'
     or v_scope.model_or_sku <> 'gpt-5.4-mini'
     or v_scope.pricing_revision_id <>
       '40010000-0000-4000-8000-000000000402'::uuid
     or v_scope.cost_policy_revision_id <>
       '40010000-0000-4000-8000-000000000301'::uuid
     or v_scope.maximum_operation_count <> 1
     or v_scope.maximum_customer_charge_micros <> 230000
     or v_scope.maximum_wholesale_exposure_micros <> 169728
     or v_scope.maximum_concurrency <> 1 then
    raise exception 'specific B1-C Hammer activation required for shutdown'
      using errcode = '42501';
  end if;

  select * into v_rollout
  from tongs.openai_text_rollout_revisions
  where route_code = 'hammer.transcript_cleanup'
  order by revision desc limit 1;
  select * into v_test_loss
  from tongs.openai_text_failure_loss_rollout_revisions
  where route_code = 'hammer.transcript_cleanup'
    and financial_environment = 'test'
  order by revision desc limit 1;
  select * into v_live_loss
  from tongs.openai_text_failure_loss_rollout_revisions
  where route_code = 'hammer.transcript_cleanup'
    and financial_environment = 'live'
  order by revision desc limit 1;

  if v_rollout.revision <> 4 or v_rollout.mode <> 'enforce'
     or v_rollout.cost_policy_revision_id <>
       '40010000-0000-4000-8000-000000000301'::uuid
     or v_test_loss.revision <> 2 or v_test_loss.mode <> 'enforce'
     or v_test_loss.loss_policy_revision_id <>
       '40010000-0000-4000-8000-000000000601'::uuid
     or v_live_loss.revision <> 1 or v_live_loss.mode <> 'halt_new'
     or v_live_loss.loss_policy_revision_id <>
       '40010000-0000-4000-8000-000000000602'::uuid
     or exists (
       select 1 from tongs.customer_paid_execution_scope_authorizations
       where route_code = 'hammer.transcript_cleanup'
         and financial_environment = 'live'
     ) then
    raise exception 'exact active Hammer customer Test authority required for shutdown'
      using errcode = '42501';
  end if;

  insert into tongs.openai_text_rollout_revisions(
    route_code, revision, mode, cost_policy_revision_id,
    reason, actor_id, funding_scope
  ) values (
    'hammer.transcript_cleanup', 5, 'halt_new', null,
    btrim(p_reason), p_actor_id, 'forge'
  );
  insert into tongs.openai_text_failure_loss_rollout_revisions(
    route_code, financial_environment, revision, mode,
    loss_policy_revision_id, source_limit_event_id, reason, actor_id
  ) values (
    'hammer.transcript_cleanup', 'test', 3, 'halt_new',
    '40010000-0000-4000-8000-000000000601', null,
    btrim(p_reason), p_actor_id
  );
  insert into tongs.hammer_customer_test_acceptance_closures(
    id, authorization_id, actor_id, reason,
    route_revision, test_loss_revision
  ) values (
    p_close_id, p_authorization_id, p_actor_id, btrim(p_reason), 5, 3
  ) returning * into v_existing;

  if exists (
    select 1
    from tongs.customer_paid_execution_scope_authorizations scope_auth
    where scope_auth.route_code = 'hammer.transcript_cleanup'
      and tongs._hammer_scope_is_effective(
        scope_auth.id, clock_timestamp()
      )
  )
  or (select revision from tongs.openai_text_failure_loss_rollout_revisions
      where route_code = 'hammer.transcript_cleanup'
        and financial_environment = 'live'
      order by revision desc limit 1) <> 1
  or (select mode from tongs.openai_text_failure_loss_rollout_revisions
      where route_code = 'hammer.transcript_cleanup'
        and financial_environment = 'live'
      order by revision desc limit 1) <> 'halt_new' then
    raise exception 'Hammer shutdown did not remove effective customer authority'
      using errcode = '42501';
  end if;

  return jsonb_build_object(
    'close_id', v_existing.id,
    'authorization_id', v_existing.authorization_id,
    'route_revision', 5,
    'route_mode', 'halt_new',
    'test_loss_revision', 3,
    'test_loss_mode', 'halt_new',
    'live_loss_revision', 1,
    'live_loss_mode', 'halt_new',
    'effective_scope_count', 0,
    'replay', false
  );
end
$$;


ALTER FUNCTION "tongs"."close_hammer_customer_test_acceptance"("p_close_id" "uuid", "p_authorization_id" "uuid", "p_actor_id" "uuid", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."close_hammer_customer_test_acceptance"("p_close_id" "uuid", "p_authorization_id" "uuid", "p_actor_id" "uuid", "p_reason" "text") IS 'Independent, append-only, service-role shutdown for one exact Hammer customer Test acceptance. It changes no reservation, settlement, supplier, or reconciliation evidence.';



CREATE OR REPLACE FUNCTION "tongs"."close_hearth_test_execution_authorization"("p_authorization_id" "uuid", "p_actor_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare v_seq integer; v_state text;
begin
  perform tongs._require_pricing_service_role();
  if not tongs.is_platform_operator(p_actor_id) then raise exception 'platform operator required' using errcode='42501'; end if;
  perform pg_advisory_xact_lock(hashtextextended('test-authorization:'||p_authorization_id::text,0));
  v_state:=tongs._test_authorization_state(p_authorization_id);
  if v_state='closed' then return jsonb_build_object('authorization_id',p_authorization_id,'state','closed','replay',true); end if;
  if v_state<>'opened' then raise exception 'Test authorization not open' using errcode='P0002'; end if;
  select coalesce(max(sequence),0)+1 into v_seq from tongs.test_paid_execution_authorization_events where authorization_id=p_authorization_id;
  insert into tongs.test_paid_execution_authorization_events(id,authorization_id,sequence,event_type,event_key,actor_id,reason)
  values(gen_random_uuid(),p_authorization_id,v_seq,'closed','test-authorization:'||p_authorization_id||':closed',p_actor_id,btrim(p_reason));
  return jsonb_build_object('authorization_id',p_authorization_id,'state','closed','replay',false);
end $$;


ALTER FUNCTION "tongs"."close_hearth_test_execution_authorization"("p_authorization_id" "uuid", "p_actor_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."close_openai_text_failure_exposure"("p_reservation_id" "uuid", "p_attempt_key" "text", "p_outcome" "text", "p_actual_supplier_cost_micros" bigint, "p_evidence_json" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  hold tongs.openai_text_failure_exposure_holds%rowtype;
  reservation tongs.funding_reservations%rowtype;
  existing_event tongs.openai_text_failure_exposure_events%rowtype;
  risk_rollout tongs.openai_text_failure_loss_rollout_revisions%rowtype;
  event_sequence integer;
  next_revision integer;
  loss_event_key text;
  canonical_environment text;
  limit_event_id uuid;
begin
  perform tongs._require_pricing_service_role();
  if p_outcome not in('success_released','failure_realized','unresolved','reconciled')
    or (p_outcome='success_released' and p_actual_supplier_cost_micros is null)
    or p_actual_supplier_cost_micros<0
    or jsonb_typeof(coalesce(p_evidence_json,'null'::jsonb))<>'object' then
    raise exception 'invalid OpenAI failure exposure close' using errcode='22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('openai-text-attempt:'||btrim(p_attempt_key),0));
  select * into hold from tongs.openai_text_failure_exposure_holds
  where reservation_id=p_reservation_id and attempt_key=btrim(p_attempt_key);
  select * into reservation from tongs.funding_reservations where id=p_reservation_id;
  if hold.id is null or reservation.id is null then
    raise exception 'OpenAI failure exposure hold not found' using errcode='P0002';
  end if;
  canonical_environment:=coalesce(hold.financial_environment,reservation.funding_environment);
  loss_event_key:=btrim(p_attempt_key)||':loss:'||p_outcome;
  select * into existing_event from tongs.openai_text_failure_exposure_events
  where event_key=loss_event_key;
  if found then return jsonb_build_object('hold_id',hold.id,'outcome',existing_event.event_type,'replay',true); end if;
  select * into existing_event from tongs.openai_text_failure_exposure_events
  where hold_id=hold.id order by sequence desc limit 1;
  if existing_event.event_type in('success_released','failure_realized','reconciled') then
    raise exception 'OpenAI failure exposure is terminal' using errcode='P0001';
  end if;
  select coalesce(max(sequence),0)+1 into event_sequence
  from tongs.openai_text_failure_exposure_events where hold_id=hold.id;
  insert into tongs.openai_text_failure_exposure_events(
    id,hold_id,sequence,event_key,event_type,actual_supplier_cost_micros,evidence_json
  ) values(
    gen_random_uuid(),hold.id,event_sequence,loss_event_key,p_outcome,p_actual_supplier_cost_micros,p_evidence_json);

  if p_actual_supplier_cost_micros is not null
    and p_actual_supplier_cost_micros>hold.authorized_exposure_micros then
    insert into tongs.pricing_discrepancies(
      id,reservation_id,discrepancy_key,discrepancy_type,quoted_ceiling_micros,
      observed_amount_micros,evidence_json
    ) values(
      gen_random_uuid(),p_reservation_id,btrim(p_attempt_key)||':failure-loss-overrun',
      'wholesale_ceiling_overrun',hold.authorized_exposure_micros,p_actual_supplier_cost_micros,
      p_evidence_json||jsonb_build_object('component','openai_failure_loss'))
    on conflict(discrepancy_key) do nothing;

    insert into tongs.openai_text_failure_limit_events(
      id,route_code,reservation_id,event_key,event_type,requested_micros,committed_micros,
      configured_limit_micros,evidence_json,financial_environment,environment_authority
    ) values(
      gen_random_uuid(),hold.route_code,p_reservation_id,btrim(p_attempt_key)||':overrun-halted',
      'overrun_halted',p_actual_supplier_cost_micros,p_actual_supplier_cost_micros,
      hold.authorized_exposure_micros,p_evidence_json,
      case when canonical_environment in('test','live') then canonical_environment else null end,
      case when canonical_environment in('test','live') then 'canonical_reservation' else null end)
    returning id into limit_event_id;

    if canonical_environment in('test','live') and hold.loss_policy_revision_id is not null then
      perform pg_advisory_xact_lock(hashtextextended(
        'openai-text-loss:'||hold.route_code||':'||canonical_environment,0));
      select * into risk_rollout
      from tongs._current_openai_text_failure_loss_rollout(hold.route_code,canonical_environment);
      if risk_rollout.route_code is null then
        raise exception 'environment-scoped OpenAI failure-loss rollout is unavailable' using errcode='P0001';
      end if;
      if risk_rollout.mode<>'halt_new' then
        select coalesce(max(revision),0)+1 into next_revision
        from tongs.openai_text_failure_loss_rollout_revisions risk_revision
        where risk_revision.route_code=hold.route_code
          and risk_revision.financial_environment=canonical_environment;
        insert into tongs.openai_text_failure_loss_rollout_revisions(
          route_code,financial_environment,revision,mode,loss_policy_revision_id,
          source_limit_event_id,reason
        ) values(
          hold.route_code,canonical_environment,next_revision,'halt_new',
          risk_rollout.loss_policy_revision_id,limit_event_id,
          'Automatic halt: actual OpenAI failure cost exceeded the authorized per-attempt ceiling.');
      end if;
    else
      select coalesce(max(revision),0)+1 into next_revision
      from tongs.openai_text_rollout_revisions where route_code=hold.route_code;
      insert into tongs.openai_text_rollout_revisions(route_code,revision,mode,reason)
      values(hold.route_code,next_revision,'halt_new',
        'Automatic halt: actual OpenAI failure cost exceeded the authorized per-attempt ceiling.');
    end if;
  end if;
  return jsonb_build_object(
    'hold_id',hold.id,'outcome',p_outcome,'replay',false,
    'route_halted',p_actual_supplier_cost_micros>hold.authorized_exposure_micros,
    'financial_environment',case when canonical_environment in('test','live') then canonical_environment else null end);
end $$;


ALTER FUNCTION "tongs"."close_openai_text_failure_exposure"("p_reservation_id" "uuid", "p_attempt_key" "text", "p_outcome" "text", "p_actual_supplier_cost_micros" bigint, "p_evidence_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."close_openai_text_test_certification"("p_batch_id" "uuid", "p_actor_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare v_seq integer; v_total integer; v_terminal integer;
begin perform tongs._require_pricing_service_role(); if not tongs.is_platform_operator(p_actor_id) then raise exception 'platform operator required' using errcode='42501'; end if;
  perform pg_advisory_xact_lock(hashtextextended('openai-text-test-certification:'||p_batch_id::text,0)); if tongs._openai_text_test_certification_batch_state(p_batch_id)='closed' then return jsonb_build_object('batch_id',p_batch_id,'state','closed','replay',true); end if;
  select count(*) into v_total from tongs.openai_text_test_certification_reservations where batch_id=p_batch_id; select count(*) into v_terminal from tongs.openai_text_test_certification_reservations r where r.batch_id=p_batch_id and tongs._openai_text_test_certification_reservation_state(r.id) in ('settled','released');
  if v_total<>14 or v_terminal<>14 then raise exception 'all certification operations must be terminal before closure' using errcode='P0001'; end if;
  select coalesce(max(sequence),0)+1 into v_seq from tongs.openai_text_test_certification_batch_events where batch_id=p_batch_id;
  insert into tongs.openai_text_test_certification_batch_events values(gen_random_uuid(),p_batch_id,v_seq,'closed','openai-text-test-certification:'||p_batch_id||':closed',p_actor_id,btrim(p_reason),now());
  return jsonb_build_object('batch_id',p_batch_id,'state','closed','replay',false,'new_reservations_authorized',false,'reconciliation_preserved',true); end $$;


ALTER FUNCTION "tongs"."close_openai_text_test_certification"("p_batch_id" "uuid", "p_actor_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."close_owner_hearth_chat_luna_pilot"("p_operator_user_id" "uuid", "p_budget_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_reason text:=nullif(btrim(coalesce(p_reason,'')),'');
  v_budget tongs.owner_operating_budgets%rowtype;
  v_budget_revision tongs.owner_operating_budget_revisions%rowtype;
  v_rollout tongs.openai_text_rollout_revisions%rowtype;
  v_next_rollout integer; v_closed jsonb;
begin
  perform tongs._require_pricing_service_role();
  if p_operator_user_id is null or not tongs.is_platform_operator(p_operator_user_id)
     or p_budget_id is null or v_reason is null then
    raise exception 'invalid owner Luna pilot closure' using errcode='22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('owner-hearth-openai-luna-pilot',0));
  select * into v_budget from tongs.owner_operating_budgets where id=p_budget_id for update;
  select * into v_budget_revision from tongs.owner_operating_budget_revisions
    where budget_id=p_budget_id order by revision desc limit 1;
  if not found or v_budget.created_by<>p_operator_user_id or v_budget.environment<>'production'
     or lower(coalesce(v_budget.provider,''))<>'openai'
     or lower(coalesce(v_budget.route,''))<>'hearth.chat_completion'
     or lower(coalesce(v_budget.sku,''))<>'gpt-5.6-luna'
     or v_budget_revision.maximum_amount_micros<>11015 then
    raise exception 'exact owner Luna pilot budget not found' using errcode='P0002';
  end if;
  if exists(select 1 from tongs.funding_reservations r
    where r.funding_source_type='owner_budget' and r.funding_source_id=p_budget_id
      and tongs._funding_reservation_state(r.id) not in ('settled','released')) then
    raise exception 'owner Luna pilot has unresolved funding reservations' using errcode='P0001';
  end if;
  select * into v_rollout from tongs._current_openai_text_rollout('hearth.chat_completion');
  if v_rollout.mode<>'halt_new' then
    select coalesce(max(revision),0)+1 into v_next_rollout
      from tongs.openai_text_rollout_revisions where route_code='hearth.chat_completion';
    insert into tongs.openai_text_rollout_revisions(
      route_code,revision,mode,cost_policy_revision_id,reason,actor_id
    ) values (
      'hearth.chat_completion',v_next_rollout,'halt_new',v_rollout.cost_policy_revision_id,
      v_reason,p_operator_user_id
    );
  else
    v_next_rollout:=v_rollout.revision;
  end if;
  if v_budget_revision.status<>'closed' then
    perform set_config('request.jwt.claim.sub',p_operator_user_id::text,true);
    v_closed:=tongs.revise_owner_operating_budget(p_budget_id,'closed',11015,v_reason);
  else
    v_closed:=jsonb_build_object('budget_id',p_budget_id,'revision',v_budget_revision.revision,
      'status','closed','maximum_amount_micros',11015,'spending_enabled',false);
  end if;
  return jsonb_build_object('budget',v_closed,'rollout_mode','halt_new',
    'rollout_revision',v_next_rollout,'new_reservations_enabled',false);
end $$;


ALTER FUNCTION "tongs"."close_owner_hearth_chat_luna_pilot"("p_operator_user_id" "uuid", "p_budget_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."close_owner_hearth_chat_pilot"("p_operator_user_id" "uuid", "p_budget_id" "uuid", "p_reason" "text") RETURNS "jsonb"
