    ) values (
      'hearth.chat_completion',v_next_rollout,'halt_new',v_rollout.cost_policy_revision_id,
      v_reason,p_operator_user_id
    );
  else
    v_next_rollout:=v_rollout.revision;
  end if;
  if v_budget_revision.status<>'closed' then
    perform set_config('request.jwt.claim.sub',p_operator_user_id::text,true);
    v_closed:=tongs.revise_owner_operating_budget(p_budget_id,'closed',30000,v_reason);
  else
    v_closed:=jsonb_build_object('budget_id',p_budget_id,'revision',v_budget_revision.revision,
      'status','closed','maximum_amount_micros',30000,'spending_enabled',false);
  end if;
  return jsonb_build_object('budget',v_closed,'rollout_mode','halt_new',
    'rollout_revision',v_next_rollout,'new_reservations_enabled',false);
end $$;


ALTER FUNCTION "tongs"."close_owner_hearth_chat_pilot"("p_operator_user_id" "uuid", "p_budget_id" "uuid", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."close_owner_hearth_chat_pilot"("p_operator_user_id" "uuid", "p_budget_id" "uuid", "p_reason" "text") IS 'Closes the exact owner pilot budget and moves the Hearth OpenAI route to halt_new after all reservations are terminal.';



CREATE OR REPLACE FUNCTION "tongs"."close_owner_hearth_unsuccessful_compatibility_batch"("p_authorization_id" "uuid", "p_operator_user_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare authz tongs.owner_hearth_authorizations%rowtype; latest tongs.owner_hearth_authorization_events%rowtype;
 result_count bigint; passed_count bigint; seq integer; budget_revision integer; event_id uuid;
begin
 if coalesce(auth.role(),'')<>'service_role' or not tongs.is_platform_operator(p_operator_user_id)
   or length(btrim(coalesce(p_reason,'')))<3 then raise exception 'service-role operator required' using errcode='42501'; end if;
 perform pg_advisory_xact_lock(hashtextextended('owner-hearth-close-unsuccessful:'||p_authorization_id::text,0));
 select * into authz from tongs.owner_hearth_authorizations where id=p_authorization_id;
 select * into latest from tongs.owner_hearth_authorization_events where authorization_id=p_authorization_id order by sequence desc limit 1;
 if authz.authorization_kind<>'compatibility_batch' then raise exception 'compatibility authorization required' using errcode='42501'; end if;
 if latest.state='closed' then return jsonb_build_object('authorization_id',authz.id,'state','closed','replay',true); end if;
 select count(*),count(*) filter(where r.status='passed') into result_count,passed_count
 from tongs.owner_hearth_compatibility_results r join tongs.owner_hearth_operation_authorizations o on o.id=r.operation_authorization_id
 where o.authorization_id=authz.id;
 if result_count<>5 or passed_count=5 or exists(
  select 1 from tongs.owner_hearth_compatibility_results r join tongs.owner_hearth_operation_authorizations o on o.id=r.operation_authorization_id
  where o.authorization_id=authz.id and r.status='ambiguous'
 ) then raise exception 'five terminal unsuccessful compatibility results required' using errcode='P0001'; end if;
 select coalesce(max(sequence),0)+1 into seq from tongs.owner_hearth_authorization_events where authorization_id=authz.id;
 insert into tongs.owner_hearth_authorization_events(id,authorization_id,sequence,event_key,state,reason,evidence_json)
 values(gen_random_uuid(),authz.id,seq,'owner-hearth-compat:'||authz.id::text||':closed-unsuccessful','closed',btrim(p_reason),
  jsonb_build_object('result_count',result_count,'passed_count',passed_count,'creator_session_created',false));
 select coalesce(max(revision),0)+1 into budget_revision from tongs.owner_operating_budget_revisions where budget_id=authz.budget_id;
 event_id:=extensions.uuid_generate_v5(authz.budget_id,'owner-hearth-compat-budget-closed-unsuccessful');
 perform tongs._create_accounting_event(event_id,'owner-hearth-compat-budget:'||authz.budget_id::text||':closed-unsuccessful',
  'owner_operating_budget_revised','owner_internal','owner_operating_budget',authz.budget_id::text,'USD',authz.owner_user_id,
  authz.workspace_id,p_operator_user_id,jsonb_build_object('status','closed','maximum_amount_micros',authz.maximum_amount_micros,
   'reason',btrim(p_reason),'customer_revenue_micros',0),now());
 insert into tongs.owner_operating_budget_revisions(budget_id,revision,status,maximum_amount_micros,reason,actor_id,journal_event_id)
 values(authz.budget_id,budget_revision,'closed',authz.maximum_amount_micros,btrim(p_reason),p_operator_user_id,event_id);
 return jsonb_build_object('authorization_id',authz.id,'state','closed','budget_id',authz.budget_id,'budget_state','closed',
  'creator_session_created',false,'result_count',result_count,'passed_count',passed_count,'replay',false);
end $$;


ALTER FUNCTION "tongs"."close_owner_hearth_unsuccessful_compatibility_batch"("p_authorization_id" "uuid", "p_operator_user_id" "uuid", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."close_owner_hearth_unsuccessful_compatibility_batch"("p_authorization_id" "uuid", "p_operator_user_id" "uuid", "p_reason" "text") IS 'Closes a fully exercised unsuccessful compatibility batch and its budget without creating a creator session.';



CREATE OR REPLACE FUNCTION "tongs"."commit_ai_pricing_policy_revision"("p_policy_code" "text", "p_expected_revision" integer, "p_revision_id" "uuid", "p_provider" "text", "p_model" "text", "p_media_kind" "text", "p_generation_mode" "text", "p_billable_dimensions" "jsonb", "p_provider_billing_unit" "text", "p_provider_price_micros_per_unit" bigint, "p_provider_currency" "text", "p_forge_credit_conversion_numerator" bigint, "p_forge_credit_conversion_denominator" bigint, "p_markup_numerator" bigint, "p_markup_denominator" bigint, "p_addon_credits" bigint, "p_effective_from" timestamp with time zone, "p_effective_through" timestamp with time zone, "p_is_active" boolean, "p_price_source_type" "text", "p_price_source_reference" "text", "p_price_source_version" "text", "p_actor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_policy tongs.ai_pricing_policies%rowtype;
  v_sequence tongs.ai_pricing_policy_sequences%rowtype;
  v_revision tongs.ai_pricing_policy_revisions%rowtype;
  v_next integer;
  v_hash text;
begin
  if nullif(btrim(p_policy_code), '') is null or p_revision_id is null
     or p_provider_price_micros_per_unit < 0 or p_forge_credit_conversion_numerator <= 0
     or p_forge_credit_conversion_denominator <= 0 or p_markup_numerator <= 0 or p_markup_denominator <= 0
     or p_addon_credits < 0 or jsonb_typeof(p_billable_dimensions) <> 'object' then
    raise exception 'invalid pricing-policy revision' using errcode = '22023';
  end if;
  insert into tongs.ai_pricing_policies (policy_code) values (btrim(p_policy_code))
    on conflict (policy_code) do nothing;
  select * into v_policy from tongs.ai_pricing_policies where policy_code = btrim(p_policy_code) for update;
  select * into v_sequence from tongs.ai_pricing_policy_sequences where policy_id = v_policy.id for update;
  if found and v_sequence.current_revision <> coalesce(p_expected_revision, 0) then
    raise exception 'stale pricing-policy revision' using errcode = '40001';
  elsif not found and coalesce(p_expected_revision, 0) <> 0 then
    raise exception 'stale pricing-policy revision' using errcode = '40001';
  end if;
  select * into v_revision from tongs.ai_pricing_policy_revisions where id = p_revision_id;
  if found then return jsonb_build_object('policy', to_jsonb(v_policy), 'revision', to_jsonb(v_revision), 'replay', true); end if;
  v_next := coalesce(v_sequence.current_revision, 0) + 1;
  v_hash := encode(extensions.digest(convert_to(jsonb_build_object(
    'policy_id', v_policy.id, 'revision', v_next, 'provider', lower(btrim(p_provider)), 'model', btrim(p_model),
    'media_kind', lower(btrim(p_media_kind)), 'generation_mode', btrim(p_generation_mode),
    'billable_dimensions', p_billable_dimensions, 'provider_billing_unit', btrim(p_provider_billing_unit),
    'provider_price_micros_per_unit', p_provider_price_micros_per_unit, 'provider_currency', upper(btrim(p_provider_currency)),
    'forge_credit_conversion_numerator', p_forge_credit_conversion_numerator,
    'forge_credit_conversion_denominator', p_forge_credit_conversion_denominator,
    'markup_numerator', p_markup_numerator, 'markup_denominator', p_markup_denominator,
    'addon_credits', p_addon_credits, 'effective_from', p_effective_from, 'effective_through', p_effective_through,
    'is_active', p_is_active, 'price_source_type', p_price_source_type,
    'price_source_reference', p_price_source_reference, 'price_source_version', p_price_source_version
  )::text, 'utf8'), 'sha256'), 'hex');
  insert into tongs.ai_pricing_policy_revisions (
    id, policy_id, revision, previous_revision_id, provider, model, media_kind, generation_mode,
    billable_dimensions, provider_billing_unit, provider_price_micros_per_unit, provider_currency,
    forge_credit_conversion_numerator, forge_credit_conversion_denominator, markup_numerator, markup_denominator,
    addon_credits, effective_from, effective_through, is_active, price_source_type, price_source_reference,
    price_source_version, actor_id, content_hash
  ) values (
    p_revision_id, v_policy.id, v_next, v_sequence.current_revision_id, lower(btrim(p_provider)), btrim(p_model),
    lower(btrim(p_media_kind)), btrim(p_generation_mode), p_billable_dimensions, btrim(p_provider_billing_unit),
    p_provider_price_micros_per_unit, upper(btrim(p_provider_currency)), p_forge_credit_conversion_numerator,
    p_forge_credit_conversion_denominator, p_markup_numerator, p_markup_denominator, p_addon_credits,
    p_effective_from, p_effective_through, p_is_active, p_price_source_type, p_price_source_reference,
    p_price_source_version, p_actor_id, v_hash
  ) returning * into v_revision;
  insert into tongs.ai_pricing_policy_sequences values (v_policy.id, v_revision.id, v_revision.revision, now())
    on conflict (policy_id) do update set current_revision_id = excluded.current_revision_id,
      current_revision = excluded.current_revision, updated_at = now();
  return jsonb_build_object('policy', to_jsonb(v_policy), 'revision', to_jsonb(v_revision), 'replay', false);
end;
$$;


ALTER FUNCTION "tongs"."commit_ai_pricing_policy_revision"("p_policy_code" "text", "p_expected_revision" integer, "p_revision_id" "uuid", "p_provider" "text", "p_model" "text", "p_media_kind" "text", "p_generation_mode" "text", "p_billable_dimensions" "jsonb", "p_provider_billing_unit" "text", "p_provider_price_micros_per_unit" bigint, "p_provider_currency" "text", "p_forge_credit_conversion_numerator" bigint, "p_forge_credit_conversion_denominator" bigint, "p_markup_numerator" bigint, "p_markup_denominator" bigint, "p_addon_credits" bigint, "p_effective_from" timestamp with time zone, "p_effective_through" timestamp with time zone, "p_is_active" boolean, "p_price_source_type" "text", "p_price_source_reference" "text", "p_price_source_version" "text", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."commit_broll_candidate"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_prompt_revision_id" "uuid", "p_source_kind" "text", "p_license_json" "jsonb", "p_provenance_json" "jsonb", "p_actor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare v_op tongs.broll_operation_receipts%rowtype; v_asset tongs.assets%rowtype; v_prompt tongs.broll_prompt_revisions%rowtype; v_candidate tongs.broll_candidates%rowtype; v_rev tongs.broll_candidate_revisions%rowtype; v_hash text; v_immutable text; v_result jsonb; v_poster_required boolean;
begin
 select * into v_op from tongs.broll_operation_receipts where operation_id=p_operation_id for update;
 if not found then return jsonb_build_object('disposition','operation_not_found'); end if;
 if not tongs.has_workspace_role(v_op.workspace_id,'editor') then raise exception 'workspace editor authority required' using errcode='42501'; end if;
 if auth.uid() is distinct from p_actor_id then raise exception 'candidate actor must match authenticated creator' using errcode='42501'; end if;
 if v_op.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict'); end if;
 if v_op.state='candidate_committed' then return v_op.receipt_json; end if;
 v_poster_required:=coalesce((v_op.normalized_inputs_json->>'poster_required')::boolean,false);
 if v_op.state not in('video_asset_verified','poster_asset_verified') then return jsonb_build_object('disposition','video_asset_verification_required'); end if;
 if v_poster_required and v_op.state<>'poster_asset_verified' then return jsonb_build_object('disposition','poster_asset_verification_required'); end if;
 select * into v_asset from tongs.assets where id=v_op.verified_asset_id and status='ready' and asset_kind='broll_candidate_video';
 if not found then return jsonb_build_object('disposition','verified_video_asset_required'); end if;
 if p_source_kind='generated' and p_prompt_revision_id is null then return jsonb_build_object('disposition','prompt_revision_required'); end if;
 if p_prompt_revision_id is not null then select * into v_prompt from tongs.broll_prompt_revisions where id=p_prompt_revision_id and workspace_id=v_op.workspace_id and workpiece_id=v_op.workpiece_id and beat_id=v_op.beat_id; if not found then return jsonb_build_object('disposition','prompt_revision_conflict'); end if; end if;
 insert into tongs.broll_candidates(workspace_id,workpiece_id,beat_id,created_by) values(v_op.workspace_id,v_op.workpiece_id,v_op.beat_id,p_actor_id) returning * into v_candidate;
 v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('asset_id',v_asset.id,'asset_hash',v_asset.content_hash,'poster_asset_id',v_op.verified_poster_asset_id,'prompt_hash',v_prompt.content_hash,'source_kind',p_source_kind,'license',p_license_json,'provenance',p_provenance_json)::text,'UTF8'),'sha256'),'hex');
 v_immutable:=encode(extensions.digest(convert_to(jsonb_build_object('candidate_id',v_candidate.id,'content_hash',v_hash,'revision',1,'operation_id',p_operation_id)::text,'UTF8'),'sha256'),'hex');
 insert into tongs.broll_candidate_revisions(candidate_id,workspace_id,workpiece_id,beat_id,revision,prompt_revision_id,prompt_revision,prompt_content_hash,asset_id,asset_content_hash,asset_path,storage_bucket,storage_key,mime_type,duration_ms,width,height,poster_asset_id,source_kind,provider,provider_request_id,source_url,license_json,provenance_json,content_hash,immutable_revision_hash,created_by)
 values(v_candidate.id,v_op.workspace_id,v_op.workpiece_id,v_op.beat_id,1,v_prompt.id,v_prompt.revision,v_prompt.content_hash,v_asset.id,v_asset.content_hash,v_asset.path,v_asset.storage_bucket,v_asset.storage_key,v_asset.mime_type,(v_asset.metadata_json->>'duration_ms')::bigint,v_asset.width,v_asset.height,v_op.verified_poster_asset_id,p_source_kind,v_asset.provider,v_asset.provider_request_id,p_provenance_json->>'source_url',p_license_json,p_provenance_json,v_hash,v_immutable,p_actor_id) returning * into v_rev;
 v_result:=jsonb_build_object('disposition','committed','candidate_revision',to_jsonb(v_rev));
 update tongs.broll_operation_receipts set state='candidate_committed',result_candidate_revision_id=v_rev.id,receipt_json=v_result,updated_at=now() where operation_id=p_operation_id;
 return v_result;
end $$;


ALTER FUNCTION "tongs"."commit_broll_candidate"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_prompt_revision_id" "uuid", "p_source_kind" "text", "p_license_json" "jsonb", "p_provenance_json" "jsonb", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."commit_broll_generation_references"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_beat_id" "uuid", "p_operation_id" "text", "p_operation_fingerprint" "text", "p_references" "jsonb", "p_actor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $_$
declare op tongs.broll_operation_receipts%rowtype; item jsonb; existing tongs.assets%rowtype; committed jsonb:='[]'::jsonb;
begin
  if auth.role()<>'service_role' then raise exception 'B-roll reference commit requires service authority' using errcode='42501'; end if;
  if jsonb_typeof(p_references)<>'array' or jsonb_array_length(p_references) not between 1 and 3 then return jsonb_build_object('disposition','invalid_reference_count'); end if;
  select * into op from tongs.broll_operation_receipts where operation_id=p_operation_id and workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and beat_id=p_beat_id for update;
  if not found then return jsonb_build_object('disposition','operation_not_found'); end if;
  if op.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict'); end if;
  for item in select value from jsonb_array_elements(p_references) loop
    if (item->>'ordinal')::integer not between 0 and 2 or item->>'mime_type' not in('image/jpeg','image/png','image/webp') or (item->>'byte_size')::bigint<=0 or item->>'content_hash'!~'^[0-9a-f]{64}$' then
      return jsonb_build_object('disposition','invalid_reference_evidence');
    end if;
    select * into existing from tongs.assets where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and operation_id=p_operation_id and asset_kind='broll_generation_reference' and (metadata_json->>'ordinal')::integer=(item->>'ordinal')::integer;
    if found then
      if existing.content_hash<>item->>'content_hash' or existing.storage_key<>item->>'storage_key' then return jsonb_build_object('disposition','reference_replay_conflict'); end if;
    else
      insert into tongs.assets(workspace_id,workpiece_id,path,mime_type,bytes,storage_bucket,storage_key,provider,request_id,created_by,asset_kind,status,metadata_json,operation_id,operation_fingerprint,content_hash,ready_at)
      values(p_workspace_id,p_workpiece_id,item->>'path',item->>'mime_type',(item->>'byte_size')::bigint,item->>'storage_bucket',item->>'storage_key','creator-upload',p_operation_id,p_actor_id,'broll_generation_reference','ready',jsonb_strip_nulls(jsonb_build_object('ordinal',(item->>'ordinal')::integer,'file_name',item->>'file_name','stage_label',item->>'stage_label','beat_id',p_beat_id)),p_operation_id,p_operation_fingerprint,item->>'content_hash',now()) returning * into existing;
    end if;
    committed:=committed||jsonb_build_array(jsonb_build_object('asset_id',existing.id,'ordinal',(item->>'ordinal')::integer,'content_hash',existing.content_hash));
  end loop;
  return jsonb_build_object('disposition','committed','references',committed);
end$_$;


ALTER FUNCTION "tongs"."commit_broll_generation_references"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_beat_id" "uuid", "p_operation_id" "text", "p_operation_fingerprint" "text", "p_references" "jsonb", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."commit_broll_operation_asset"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_asset_kind" "text", "p_path" "text", "p_mime_type" "text", "p_byte_size" bigint, "p_content_hash" "text", "p_storage_bucket" "text", "p_storage_key" "text", "p_width" integer, "p_height" integer, "p_duration_ms" bigint, "p_provider" "text", "p_provider_request_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $_$
declare
  v_op tongs.broll_operation_receipts%rowtype;
  v_asset tongs.assets%rowtype;
  v_expected_kind text;
  v_next_state text;
begin
  if auth.role()<>'service_role' then
    raise exception 'B-roll asset commit requires Tongs service authority' using errcode='42501';
  end if;
  select * into v_op from tongs.broll_operation_receipts where operation_id=p_operation_id for update;
  if not found then return jsonb_build_object('disposition','operation_not_found'); end if;
  if v_op.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict'); end if;
  if v_op.operation_type<>'candidate_acquire' then return jsonb_build_object('disposition','candidate_acquisition_operation_required'); end if;
  if p_asset_kind not in('broll_candidate_video','broll_candidate_poster') then return jsonb_build_object('disposition','unsupported_broll_asset_kind'); end if;
  if p_byte_size<=0 or p_content_hash!~'^[0-9a-f]{64}$' or p_width<=0 or p_height<=0 then return jsonb_build_object('disposition','invalid_verified_media_evidence'); end if;
  if p_asset_kind='broll_candidate_video' and (p_mime_type not like 'video/%' or coalesce(p_duration_ms,0)<=0) then return jsonb_build_object('disposition','invalid_verified_video_evidence'); end if;
  if p_asset_kind='broll_candidate_poster' and p_mime_type not like 'image/%' then return jsonb_build_object('disposition','invalid_verified_poster_evidence'); end if;
  v_expected_kind:=p_asset_kind;
  select * into v_asset from tongs.assets
    where workspace_id=v_op.workspace_id and workpiece_id=v_op.workpiece_id
      and operation_id=p_operation_id and asset_kind=v_expected_kind for update;
  if found then
    if v_asset.operation_fingerprint<>p_operation_fingerprint or v_asset.content_hash<>p_content_hash
      or v_asset.storage_bucket<>p_storage_bucket or v_asset.storage_key<>p_storage_key
      or v_asset.bytes<>p_byte_size or v_asset.mime_type<>p_mime_type then
      return jsonb_build_object('disposition','asset_replay_conflict');
    end if;
    return jsonb_build_object('disposition','replay','operation',to_jsonb(v_op),'asset',to_jsonb(v_asset));
  end if;
  if p_asset_kind='broll_candidate_video' and v_op.state<>'provider_or_upload_completed' then return jsonb_build_object('disposition','provider_or_upload_result_required'); end if;
  if p_asset_kind='broll_candidate_poster' and v_op.state<>'video_asset_verified' then return jsonb_build_object('disposition','video_asset_verification_required'); end if;
  insert into tongs.assets(
    workspace_id,workpiece_id,path,mime_type,bytes,storage_bucket,storage_key,provider,
    provider_request_id,request_id,created_by,asset_kind,status,metadata_json,width,height,
    operation_id,operation_fingerprint,content_hash,ready_at
  ) values(
    v_op.workspace_id,v_op.workpiece_id,p_path,p_mime_type,p_byte_size,p_storage_bucket,p_storage_key,p_provider,
    p_provider_request_id,p_operation_id,v_op.created_by,p_asset_kind,'ready',
    jsonb_strip_nulls(jsonb_build_object('duration_ms',p_duration_ms,'inspection_authority','tongs-service.v1')),
    p_width,p_height,p_operation_id,p_operation_fingerprint,p_content_hash,now()
  ) returning * into v_asset;
  v_next_state:=case when p_asset_kind='broll_candidate_video' then 'video_asset_verified' else 'poster_asset_verified' end;
  update tongs.broll_operation_receipts set
    state=v_next_state,
    verified_asset_id=case when p_asset_kind='broll_candidate_video' then v_asset.id else verified_asset_id end,
    verified_poster_asset_id=case when p_asset_kind='broll_candidate_poster' then v_asset.id else verified_poster_asset_id end,
    failed_stage=null,failure_code=null,failure_message=null,updated_at=now()
  where operation_id=p_operation_id returning * into v_op;
  return jsonb_build_object('disposition',v_next_state,'operation',to_jsonb(v_op),'asset',to_jsonb(v_asset));
end $_$;


ALTER FUNCTION "tongs"."commit_broll_operation_asset"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_asset_kind" "text", "p_path" "text", "p_mime_type" "text", "p_byte_size" bigint, "p_content_hash" "text", "p_storage_bucket" "text", "p_storage_key" "text", "p_width" integer, "p_height" integer, "p_duration_ms" bigint, "p_provider" "text", "p_provider_request_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."commit_broll_plan"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_expected_revision_id" "uuid", "p_expected_revision" bigint, "p_script_approval_id" "uuid", "p_source_context_contract_version" "text", "p_beats" "jsonb", "p_operation_id" "text", "p_operation_fingerprint" "text", "p_actor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare
  v_seq tongs.broll_plan_sequences%rowtype;
  v_script tongs.script_approval_revisions%rowtype;
  v_plan tongs.broll_plan_revisions%rowtype;
  v_op tongs.broll_operation_receipts%rowtype;
  v_beat jsonb;
  v_beat_rev tongs.broll_beat_revisions%rowtype;
  v_prev tongs.broll_beat_revisions%rowtype;
  v_beat_id uuid;
  v_hash text;
  v_immutable text;
  v_ordinal int := 0;
  v_result jsonb;
begin
  if not tongs.has_workspace_role(p_workspace_id,'editor') then
    raise exception 'workspace editor authority required' using errcode='42501';
  end if;
  if jsonb_typeof(p_beats) <> 'array' then
    return jsonb_build_object('disposition','beats_array_required');
  end if;

  perform pg_advisory_xact_lock(hashtextextended(p_operation_id,0));
  select * into v_op from tongs.broll_operation_receipts where operation_id=p_operation_id for update;
  if found then
    if v_op.operation_fingerprint<>p_operation_fingerprint then
      return jsonb_build_object('disposition','operation_identity_conflict');
    end if;
    return v_op.receipt_json;
  end if;

  insert into tongs.broll_plan_sequences(workspace_id,workpiece_id)
  values(p_workspace_id,p_workpiece_id) on conflict do nothing;
  select * into v_seq from tongs.broll_plan_sequences
  where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id for update;
  if v_seq.current_plan_revision<>p_expected_revision
    or v_seq.current_plan_revision_id is distinct from p_expected_revision_id then
    return jsonb_build_object(
      'disposition','plan_revision_conflict',
      'current_revision_id',v_seq.current_plan_revision_id,
      'current_revision',v_seq.current_plan_revision
    );
  end if;

  select * into v_script from tongs.script_approval_revisions
  where id=p_script_approval_id and workspace_id=p_workspace_id and workpiece_id=p_workpiece_id;
  if not found then return jsonb_build_object('disposition','script_revision_conflict'); end if;

  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'script_approval_id',v_script.id,'script_hash',v_script.script_content_hash,
    'contract',p_source_context_contract_version,'beats',p_beats
  )::text,'UTF8'),'sha256'),'hex');
  v_immutable:=encode(extensions.digest(convert_to(jsonb_build_object(
    'content_hash',v_hash,'revision',v_seq.current_plan_revision+1,
    'previous_revision_id',v_seq.current_plan_revision_id,'operation_id',p_operation_id
  )::text,'UTF8'),'sha256'),'hex');

  insert into tongs.broll_plan_revisions(
    workspace_id,workpiece_id,revision,previous_revision_id,previous_revision,
    script_approval_id,script_approval_revision,script_content_hash,
    source_context_contract_version,content_hash,immutable_revision_hash,created_by
  ) values(
    p_workspace_id,p_workpiece_id,v_seq.current_plan_revision+1,v_seq.current_plan_revision_id,
    nullif(v_seq.current_plan_revision,0),v_script.id,v_script.approval_revision,
    v_script.script_content_hash,p_source_context_contract_version,v_hash,v_immutable,p_actor_id
  ) returning * into v_plan;

  for v_beat in select value from jsonb_array_elements(p_beats) loop
    v_ordinal:=v_ordinal+1;
    v_beat_id:=coalesce(nullif(v_beat->>'beat_id','')::uuid,gen_random_uuid());
    select * into v_prev from tongs.broll_beat_revisions
    where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and beat_id=v_beat_id
    order by revision desc limit 1;
    v_hash:=encode(extensions.digest(convert_to(v_beat::text,'UTF8'),'sha256'),'hex');
    v_immutable:=encode(extensions.digest(convert_to(jsonb_build_object(
      'content_hash',v_hash,'plan_revision_id',v_plan.id,'beat_id',v_beat_id,
      'revision',coalesce(v_prev.revision,0)+1
    )::text,'UTF8'),'sha256'),'hex');
    insert into tongs.broll_beat_revisions(
      workspace_id,workpiece_id,beat_id,revision,previous_revision_id,previous_revision,
      source_plan_revision_id,source_plan_revision,script_approval_id,script_approval_revision,
      context_before,context_focus,context_after,canonical_anchor_assessment,narrative_purpose,
      placement_hint,duration_target_ms,shot_type,motion_intent,mood_pacing,asset_category,
      trim_guidance_json,content_hash,immutable_revision_hash,created_by
    ) values(
      p_workspace_id,p_workpiece_id,v_beat_id,coalesce(v_prev.revision,0)+1,v_prev.id,v_prev.revision,
      v_plan.id,v_plan.revision,v_script.id,v_script.approval_revision,
      coalesce(v_beat->>'context_before',''),v_beat->>'context_focus',coalesce(v_beat->>'context_after',''),
      coalesce(v_beat->'canonical_anchor_assessment','{}'),v_beat->>'narrative_purpose',
      v_beat->>'placement_hint',coalesce((v_beat->>'duration_target_ms')::bigint,4000),
      v_beat->>'shot_type',v_beat->>'motion_intent',v_beat->>'mood_pacing',v_beat->>'asset_category',
      coalesce(v_beat->'trim_guidance','{}'),v_hash,v_immutable,p_actor_id
    ) returning * into v_beat_rev;
    insert into tongs.broll_plan_beat_membership(
      plan_revision_id,workspace_id,workpiece_id,plan_revision,ordinal,
      beat_id,beat_revision_id,beat_revision
    ) values(
      v_plan.id,p_workspace_id,p_workpiece_id,v_plan.revision,v_ordinal,
      v_beat_id,v_beat_rev.id,v_beat_rev.revision
    );
  end loop;

  update tongs.broll_plan_sequences
  set current_plan_revision_id=v_plan.id,current_plan_revision=v_plan.revision,updated_at=now()
  where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id;
  v_result:=jsonb_build_object(
    'disposition','committed','plan_revision',to_jsonb(v_plan),
    'beat_count',jsonb_array_length(p_beats),'empty',jsonb_array_length(p_beats)=0
  );
  insert into tongs.broll_operation_receipts(
    operation_id,operation_fingerprint,operation_type,state,workspace_id,workpiece_id,
    normalized_inputs_json,result_plan_revision_id,receipt_json,created_by
  ) values(
    p_operation_id,p_operation_fingerprint,'plan_commit','committed',p_workspace_id,p_workpiece_id,
    jsonb_build_object('beats',p_beats,'beat_count',jsonb_array_length(p_beats),'empty',jsonb_array_length(p_beats)=0),
    v_plan.id,v_result,p_actor_id
  );
  return v_result;
end
$$;


ALTER FUNCTION "tongs"."commit_broll_plan"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_expected_revision_id" "uuid", "p_expected_revision" bigint, "p_script_approval_id" "uuid", "p_source_context_contract_version" "text", "p_beats" "jsonb", "p_operation_id" "text", "p_operation_fingerprint" "text", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."commit_broll_prompt_creator_edit"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_beat_id" "uuid", "p_expected_prompt_revision_id" "uuid", "p_expected_prompt_revision" bigint, "p_final_prompt" "text", "p_operation_id" "text", "p_operation_fingerprint" "text", "p_actor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare v_seq tongs.broll_prompt_sequences%rowtype; v_current tongs.broll_prompt_revisions%rowtype; v_prompt tongs.broll_prompt_revisions%rowtype; v_op tongs.broll_operation_receipts%rowtype; v_hash text; v_immutable text; v_result jsonb; v_status jsonb;
begin
 if not tongs.has_workspace_role(p_workspace_id,'editor') then raise exception 'workspace editor authority required' using errcode='42501'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_operation_id,0));
 select * into v_op from tongs.broll_operation_receipts where operation_id=p_operation_id for update;
 if found then if v_op.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict'); end if; return v_op.receipt_json; end if;
 select * into v_seq from tongs.broll_prompt_sequences where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and beat_id=p_beat_id for update;
 if not found or v_seq.current_prompt_revision_id is distinct from p_expected_prompt_revision_id or v_seq.current_prompt_revision<>p_expected_prompt_revision then return jsonb_build_object('disposition','prompt_revision_conflict','current_revision_id',v_seq.current_prompt_revision_id,'current_revision',v_seq.current_prompt_revision); end if;
 select * into v_current from tongs.broll_prompt_revisions where id=v_seq.current_prompt_revision_id;
 v_status:=tongs.read_broll_prompt_status(p_workspace_id,p_workpiece_id,p_beat_id);
 if v_status->>'status' not in('current','creator_edited') then return jsonb_build_object('disposition','prompt_authority_invalid','prompt_status',v_status); end if;
 v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('prior_content_hash',v_current.content_hash,'final_prompt',p_final_prompt,'prompt_source','creator_edited')::text,'UTF8'),'sha256'),'hex');
 v_immutable:=encode(extensions.digest(convert_to(jsonb_build_object('content_hash',v_hash,'revision',v_current.revision+1,'previous_revision_id',v_current.id,'operation_id',p_operation_id)::text,'UTF8'),'sha256'),'hex');
 insert into tongs.broll_prompt_revisions(workspace_id,workpiece_id,beat_id,revision,previous_revision_id,previous_revision,source_beat_revision_id,source_beat_revision,source_plan_revision_id,source_plan_revision,script_approval_id,script_approval_revision,script_content_hash,source_context_json,creator_direction,creative_input_hash,motion_brief_json,final_prompt,prompt_source,interpretation_contract_version,validator_version,synthesis_contract_version,interpretation_provider,interpretation_model,interpretation_request_json,provider_response_json,origin_operation_id,origin_operation_fingerprint,authority_status,content_hash,immutable_revision_hash,created_by)
 select workspace_id,workpiece_id,beat_id,revision+1,id,revision,source_beat_revision_id,source_beat_revision,source_plan_revision_id,source_plan_revision,script_approval_id,script_approval_revision,script_content_hash,source_context_json,creator_direction,creative_input_hash,motion_brief_json,p_final_prompt,'creator_edited',interpretation_contract_version,validator_version,synthesis_contract_version,interpretation_provider,interpretation_model,interpretation_request_json,provider_response_json,p_operation_id,p_operation_fingerprint,authority_status,v_hash,v_immutable,p_actor_id from tongs.broll_prompt_revisions where id=v_current.id returning * into v_prompt;
 update tongs.broll_prompt_sequences set current_prompt_revision_id=v_prompt.id,current_prompt_revision=v_prompt.revision,updated_at=now() where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and beat_id=p_beat_id;
 v_result:=jsonb_build_object('disposition','committed','prompt_revision',to_jsonb(v_prompt),'prompt_status',tongs.read_broll_prompt_status(p_workspace_id,p_workpiece_id,p_beat_id));
 insert into tongs.broll_operation_receipts(operation_id,operation_fingerprint,operation_type,state,workspace_id,workpiece_id,beat_id,normalized_inputs_json,result_prompt_revision_id,receipt_json,created_by) values(p_operation_id,p_operation_fingerprint,'prompt_edit','committed',p_workspace_id,p_workpiece_id,p_beat_id,jsonb_build_object('expected_prompt_revision_id',p_expected_prompt_revision_id,'expected_prompt_revision',p_expected_prompt_revision,'final_prompt',p_final_prompt),v_prompt.id,v_result,p_actor_id);
 return v_result;
end $$;


ALTER FUNCTION "tongs"."commit_broll_prompt_creator_edit"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_beat_id" "uuid", "p_expected_prompt_revision_id" "uuid", "p_expected_prompt_revision" bigint, "p_final_prompt" "text", "p_operation_id" "text", "p_operation_fingerprint" "text", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."commit_broll_prompt_interpretation"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_source_beat_revision_id" "uuid", "p_motion_brief" "jsonb", "p_final_prompt" "text", "p_interpretation_contract_version" "text", "p_validator_version" "text", "p_synthesis_contract_version" "text", "p_actor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare v_op tongs.broll_operation_receipts%rowtype; v_seq tongs.broll_prompt_sequences%rowtype; v_prompt tongs.broll_prompt_revisions%rowtype; v_current jsonb; v_plan jsonb; v_beat jsonb; v_inputs jsonb; v_hash text; v_immutable text; v_result jsonb; v_missing text[]:=array[]::text[]; v_required text; v_direction text; v_provider text; v_model text;
begin
 select * into v_op from tongs.broll_operation_receipts where operation_id=p_operation_id for update;
 if not found then return jsonb_build_object('disposition','operation_not_found'); end if;
 if v_op.owner_cost_attempt_id is not null then perform tongs._require_accounting_service_role(); elsif not tongs.has_workspace_role(v_op.workspace_id,'editor') then raise exception 'workspace editor authority required' using errcode='42501'; end if;
 if v_op.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict'); end if;
 if v_op.state='committed' then return v_op.receipt_json; end if;
 if v_op.operation_type<>'prompt_interpretation' or v_op.state<>'provider_or_upload_completed' then return jsonb_build_object('disposition','provider_response_required'); end if;
 foreach v_required in array array['narrative_purpose','central_message','visible_subjects','action_over_time','camera_behavior','start_frame','end_frame','target_duration','pacing','setting','mood','continuity','must_include','avoid','loopability'] loop
   if not p_motion_brief ? v_required or p_motion_brief->v_required in('null'::jsonb,'""'::jsonb,'[]'::jsonb,'{}'::jsonb) then v_missing:=array_append(v_missing,v_required); end if;
 end loop;
 if cardinality(v_missing)>0 then return jsonb_build_object('disposition','interpretation_incomplete','invalid_fields',to_jsonb(v_missing)); end if;
 v_direction:=coalesce(v_op.normalized_inputs_json->>'creator_direction',''); v_provider:=v_op.normalized_inputs_json->>'interpretation_provider'; v_model:=v_op.normalized_inputs_json->>'interpretation_model';
 if coalesce(v_provider,'')='' or coalesce(v_model,'')='' then return jsonb_build_object('disposition','interpretation_incomplete','invalid_fields',jsonb_build_array('interpretation_provider','interpretation_model')); end if;
 insert into tongs.broll_prompt_sequences(workspace_id,workpiece_id,beat_id) values(v_op.workspace_id,v_op.workpiece_id,v_op.beat_id) on conflict do nothing;
 select * into v_seq from tongs.broll_prompt_sequences where workspace_id=v_op.workspace_id and workpiece_id=v_op.workpiece_id and beat_id=v_op.beat_id for update;
 if v_seq.current_prompt_revision<>coalesce((v_op.normalized_inputs_json->>'expected_prompt_revision')::bigint,0) or v_seq.current_prompt_revision_id is distinct from nullif(v_op.normalized_inputs_json->>'expected_prompt_revision_id','')::uuid then return jsonb_build_object('disposition','prompt_revision_conflict','current_revision_id',v_seq.current_prompt_revision_id,'current_revision',v_seq.current_prompt_revision); end if;
 v_current:=tongs.broll_current_creative_input(v_op.workspace_id,v_op.workpiece_id,v_op.beat_id,v_direction,p_interpretation_contract_version,p_synthesis_contract_version);
 if v_current->>'disposition'<>'current' then return jsonb_build_object('disposition',v_current->>'disposition'); end if;
 v_beat:=v_current->'beat_revision'; v_plan:=v_current->'plan_revision'; v_inputs:=v_current->'creative_inputs';
 if (v_beat->>'id')::uuid is distinct from p_source_beat_revision_id then return jsonb_build_object('disposition','beat_revision_conflict'); end if;
 v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('creative_input_hash',v_current->>'creative_input_hash','motion_brief',p_motion_brief,'final_prompt',p_final_prompt,'contracts',jsonb_build_object('interpretation',p_interpretation_contract_version,'validator',p_validator_version,'synthesis',p_synthesis_contract_version))::text,'UTF8'),'sha256'),'hex');
 v_immutable:=encode(extensions.digest(convert_to(jsonb_build_object('content_hash',v_hash,'revision',v_seq.current_prompt_revision+1,'previous_revision_id',v_seq.current_prompt_revision_id,'operation_id',p_operation_id)::text,'UTF8'),'sha256'),'hex');
 insert into tongs.broll_prompt_revisions(workspace_id,workpiece_id,beat_id,revision,previous_revision_id,previous_revision,source_beat_revision_id,source_beat_revision,source_plan_revision_id,source_plan_revision,script_approval_id,script_approval_revision,script_content_hash,source_context_json,creator_direction,creative_input_hash,motion_brief_json,final_prompt,prompt_source,interpretation_contract_version,validator_version,synthesis_contract_version,interpretation_provider,interpretation_model,interpretation_request_json,provider_response_json,origin_operation_id,origin_operation_fingerprint,authority_status,content_hash,immutable_revision_hash,created_by)
 values(v_op.workspace_id,v_op.workpiece_id,v_op.beat_id,v_seq.current_prompt_revision+1,v_seq.current_prompt_revision_id,nullif(v_seq.current_prompt_revision,0),(v_beat->>'id')::uuid,(v_beat->>'revision')::bigint,(v_plan->>'id')::uuid,(v_plan->>'revision')::bigint,(v_plan->>'script_approval_id')::uuid,(v_plan->>'script_approval_revision')::bigint,v_plan->>'script_content_hash',jsonb_build_object('before',v_inputs#>>'{source_context,before}','focus',v_inputs#>>'{source_context,focus}','after',v_inputs#>>'{source_context,after}','anchor_assessment',v_inputs#>'{source_context,anchor_assessment}','narrative_purpose',v_inputs->>'narrative_purpose','placement_hint',v_inputs->>'placement_hint','duration_target_ms',(v_inputs->>'duration_target_ms')::bigint,'shot_type',v_inputs->>'shot_type','motion_intent',v_inputs->>'motion_intent','pacing',v_inputs->>'pacing'),v_direction,v_current->>'creative_input_hash',p_motion_brief,p_final_prompt,'ai_derived',p_interpretation_contract_version,p_validator_version,p_synthesis_contract_version,v_provider,v_model,coalesce(v_op.normalized_inputs_json->'interpretation_request','{}'::jsonb),v_op.provider_response_json,p_operation_id,p_operation_fingerprint,'verified',v_hash,v_immutable,p_actor_id) returning * into v_prompt;
 update tongs.broll_prompt_sequences set current_prompt_revision_id=v_prompt.id,current_prompt_revision=v_prompt.revision,creator_direction=v_direction,creator_direction_revision=creator_direction_revision+1,updated_at=now() where workspace_id=v_op.workspace_id and workpiece_id=v_op.workpiece_id and beat_id=v_op.beat_id;
 v_result:=jsonb_build_object('disposition','committed','prompt_revision',to_jsonb(v_prompt),'provider_response_hash',v_op.provider_response_hash,'prompt_status',tongs.read_broll_prompt_status(v_op.workspace_id,v_op.workpiece_id,v_op.beat_id));
 update tongs.broll_operation_receipts set state='committed',result_prompt_revision_id=v_prompt.id,receipt_json=v_result,updated_at=now() where operation_id=p_operation_id;
 return v_result;
end $$;


ALTER FUNCTION "tongs"."commit_broll_prompt_interpretation"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_source_beat_revision_id" "uuid", "p_motion_brief" "jsonb", "p_final_prompt" "text", "p_interpretation_contract_version" "text", "p_validator_version" "text", "p_synthesis_contract_version" "text", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."commit_chat_source_reconciliation"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_chat_revision" bigint, "p_chat_hash" "text", "p_recovered_sources" "jsonb", "p_matches" "jsonb", "p_operation_id" "text", "p_operation_fingerprint" "text", "p_actor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
#variable_conflict use_column
declare existing tongs.chat_source_reconciliation_receipts%rowtype;chat_file tongs.workpiece_files%rowtype;
 item jsonb;match jsonb;src tongs.sources%rowtype;src_seq tongs.source_sequences%rowtype;src_rev tongs.source_revisions%rowtype;
 link_seq tongs.workpiece_source_link_sequences%rowtype;link_rev tongs.workpiece_source_link_revisions%rowtype;
 source_receipt jsonb;link_receipt jsonb;attr_receipt jsonb;resolved jsonb;opp_before jsonb;opp_after jsonb;
 plan_id uuid;approval_id uuid;family text;v_opportunity_id uuid;opportunity_revision_id uuid;opportunity_revision bigint;
 v_stable_key text;child_hash text;created_count integer:=0;reused_count integer:=0;matched_count integer:=0;
 source_results jsonb:='[]'::jsonb;match_results jsonb:='[]'::jsonb;result jsonb;
begin
 if not tongs.has_workspace_role(p_workspace_id,'editor')or auth.uid()is distinct from p_actor_id then raise exception 'workspace editor authority required' using errcode='42501';end if;
 if jsonb_typeof(p_recovered_sources)<>'array'or jsonb_typeof(p_matches)<>'array'then return jsonb_build_object('disposition','invalid_reconciliation_contract');end if;
 perform pg_advisory_xact_lock(hashtextextended(p_operation_id,0));
 select * into existing from tongs.chat_source_reconciliation_receipts where operation_id=p_operation_id;
 if found then if existing.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict');end if;return existing.result_json;end if;
 select * into chat_file from tongs.workpiece_files where workpiece_id=p_workpiece_id and path='hearth/chat.v1.json';
 if not found or chat_file.revision<>p_chat_revision or lower(chat_file.hash_value)<>lower(p_chat_hash)then return jsonb_build_object('disposition','chat_snapshot_conflict');end if;

 for item in select value from jsonb_array_elements(p_recovered_sources)loop
  v_stable_key:='url:'||lower(item->>'normalized_url');
  select * into src from tongs.sources where workspace_id=p_workspace_id and stable_key=v_stable_key;
  if found then
   select * into src_seq from tongs.source_sequences where workspace_id=p_workspace_id and source_id=src.id;
   select * into src_rev from tongs.source_revisions where id=src_seq.current_source_revision_id;
   reused_count:=reused_count+1;
  else
   child_hash:=encode(extensions.digest(convert_to(jsonb_build_object('parent',p_operation_id,'kind','source','url',item->>'normalized_url')::text,'UTF8'),'sha256'),'hex');
   source_receipt:=tongs.commit_source_revision(p_workspace_id,null,v_stable_key,0,coalesce(nullif(item->>'source_type',''),'webpage'),coalesce(nullif(item->>'title',''),item->>'host'),null,null,null,item->>'normalized_url',null,null,null,
    jsonb_build_object('recovered_from_chat',true),jsonb_build_object('authority','hearth_chat_reconciliation','chat_revision',p_chat_revision,'chat_hash',lower(p_chat_hash),'message_evidence',coalesce(item->'message_evidence','[]'::jsonb)),
    'forge.source.metadata.v1','forge.source.provenance.v1','forge:source:chat-recovery:'||substr(child_hash,1,48),child_hash,p_actor_id);
   if coalesce(source_receipt->>'disposition','')<>'committed'then raise exception 'chat Source recovery failed' using detail=source_receipt::text;end if;
   src_rev:=jsonb_populate_record(null::tongs.source_revisions,source_receipt->'source_revision');src:=jsonb_populate_record(null::tongs.sources,source_receipt->'source');created_count:=created_count+1;
  end if;
  select ls.* into link_seq from tongs.workpiece_source_link_sequences ls join tongs.workpiece_source_link_revisions lr on lr.id=ls.current_link_revision_id where ls.workspace_id=p_workspace_id and ls.workpiece_id=p_workpiece_id and lr.source_id=src.id limit 1;
  if found then select * into link_rev from tongs.workpiece_source_link_revisions where id=link_seq.current_link_revision_id;
  else
   child_hash:=encode(extensions.digest(convert_to(jsonb_build_object('parent',p_operation_id,'kind','link','source',src.id)::text,'UTF8'),'sha256'),'hex');
   link_receipt:=tongs.commit_workpiece_source_link_revision(p_workspace_id,p_workpiece_id,null,0,src_rev.id,src_rev.revision,'script_research',null,null,
    jsonb_build_object('chat_message_evidence',coalesce(item->'message_evidence','[]'::jsonb)),'{}','{}',null,'Recovered from the canonical Hearth chat snapshot',
    jsonb_build_object('authority','hearth_chat_reconciliation','chat_revision',p_chat_revision,'chat_hash',lower(p_chat_hash)),'forge:source:chat-recovery-link:'||substr(child_hash,1,48),child_hash,p_actor_id);
   if coalesce(link_receipt->>'disposition','')<>'committed'then raise exception 'chat Source link recovery failed' using detail=link_receipt::text;end if;
   link_rev:=jsonb_populate_record(null::tongs.workpiece_source_link_revisions,link_receipt->'link_revision');
  end if;
  source_results:=source_results||jsonb_build_array(jsonb_build_object('normalized_url',item->>'normalized_url','source_revision_id',src_rev.id,'workpiece_source_link_revision_id',link_rev.id,'status',case when source_receipt is null then'reused'else'created'end));source_receipt:=null;
 end loop;

 for match in select value from jsonb_array_elements(p_matches)loop
  if match->>'status'<>'exact'then match_results:=match_results||jsonb_build_array(match);continue;end if;
  family:=match->>'family';v_opportunity_id:=(match->>'opportunity_id')::uuid;v_stable_key:='url:'||lower(match->>'normalized_url');
  select s.* into src from tongs.sources s where s.workspace_id=p_workspace_id and s.stable_key=v_stable_key;
  select r.* into src_rev from tongs.source_sequences q join tongs.source_revisions r on r.id=q.current_source_revision_id where q.workspace_id=p_workspace_id and q.source_id=src.id;
  select r.* into link_rev from tongs.workpiece_source_link_sequences q join tongs.workpiece_source_link_revisions r on r.id=q.current_link_revision_id where q.workspace_id=p_workspace_id and q.workpiece_id=p_workpiece_id and r.source_id=src.id limit 1;
  if src_rev.id is null or link_rev.id is null then raise exception 'matched Source authority missing';end if;
  if family='reference_clip'then
   select q.current_plan_revision_id,o.id,o.revision,to_jsonb(o) into plan_id,opportunity_revision_id,opportunity_revision,opp_before from tongs.reference_clip_plan_sequences q join tongs.reference_clip_plan_membership m on m.plan_revision_id=q.current_plan_revision_id and m.opportunity_id=v_opportunity_id join tongs.reference_clip_opportunity_revisions o on o.id=m.opportunity_revision_id where q.workspace_id=p_workspace_id and q.workpiece_id=p_workpiece_id;
  elsif family='reference_visual'then
   select q.current_plan_revision_id,o.id,o.revision,to_jsonb(o) into plan_id,opportunity_revision_id,opportunity_revision,opp_before from tongs.reference_visual_plan_sequences q join tongs.reference_visual_plan_membership m on m.plan_revision_id=q.current_plan_revision_id and m.opportunity_id=v_opportunity_id join tongs.reference_visual_opportunity_revisions o on o.id=m.opportunity_revision_id where q.workspace_id=p_workspace_id and q.workpiece_id=p_workpiece_id;
  else raise exception 'unsupported reconciliation family';end if;
  if opportunity_revision_id is null then raise exception 'reconciliation opportunity missing';end if;
  select id into approval_id from tongs.script_approval_revisions where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id order by approval_revision desc limit 1;
  child_hash:=encode(extensions.digest(convert_to(jsonb_build_object('parent',p_operation_id,'kind','seed-attribution','family',family,'opportunity',v_opportunity_id)::text,'UTF8'),'sha256'),'hex');
  attr_receipt:=tongs.commit_visual_source_attribution(p_workspace_id,p_workpiece_id,family,v_opportunity_id,approval_id,p_operation_id,plan_id,'selection_required','supporting','Recovered chat evidence selected a unique Source',jsonb_build_object('recovery',true),jsonb_build_array(jsonb_build_object('role','candidate','source_revision_id',src_rev.id,'workpiece_source_link_revision_id',link_rev.id)),0,'forge:visual-source-attribution:recovery-seed:'||substr(child_hash,1,40),child_hash,p_actor_id);
  if coalesce(attr_receipt->>'disposition','')<>'committed'then raise exception 'recovery attribution seed failed' using detail=attr_receipt::text;end if;
  child_hash:=encode(extensions.digest(convert_to(jsonb_build_object('parent',p_operation_id,'kind','resolve','family',family,'opportunity',v_opportunity_id)::text,'UTF8'),'sha256'),'hex');
  resolved:=tongs.resolve_visual_source_attribution(p_workspace_id,p_workpiece_id,family,v_opportunity_id,1,opportunity_revision_id,opportunity_revision,src_rev.id,link_rev.id,'forge:visual-source-attribution:recovery-resolve:'||substr(child_hash,1,36),child_hash,p_actor_id);
  if coalesce(resolved->>'disposition','')<>'committed'then raise exception 'visual Source recovery failed' using detail=resolved::text;end if;
  opp_after:=resolved->'opportunity_revision';
  if (opp_before-ARRAY['id','revision','previous_revision_id','previous_revision','source_plan_revision_id','source_plan_revision','source_status','source_id','source_revision_id','source_revision','workpiece_source_link_id','workpiece_source_link_revision_id','workpiece_source_link_revision','content_hash','immutable_revision_hash','created_at','created_by'])
     is distinct from(opp_after-ARRAY['id','revision','previous_revision_id','previous_revision','source_plan_revision_id','source_plan_revision','source_status','source_id','source_revision_id','source_revision','workpiece_source_link_id','workpiece_source_link_revision_id','workpiece_source_link_revision','content_hash','immutable_revision_hash','created_at','created_by'])then raise exception 'visual reconciliation changed editorial content';end if;
  matched_count:=matched_count+1;match_results:=match_results||jsonb_build_array(match||jsonb_build_object('committed',true,'source_revision_id',src_rev.id,'workpiece_source_link_revision_id',link_rev.id));
 end loop;
 result:=jsonb_build_object('disposition','committed','recovered_from_chat',p_recovered_sources,'canonical_episode_sources',source_results,'visual_opportunity_matches',match_results,'created_source_count',created_count,'reused_source_count',reused_count,'matched_count',matched_count,'chat_revision',p_chat_revision,'chat_hash',lower(p_chat_hash));
 insert into tongs.chat_source_reconciliation_receipts(operation_id,operation_fingerprint,workspace_id,workpiece_id,chat_revision,chat_hash,result_json,created_by)values(p_operation_id,p_operation_fingerprint,p_workspace_id,p_workpiece_id,p_chat_revision,lower(p_chat_hash),result,p_actor_id);
 return result;
end$$;


ALTER FUNCTION "tongs"."commit_chat_source_reconciliation"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_chat_revision" bigint, "p_chat_hash" "text", "p_recovered_sources" "jsonb", "p_matches" "jsonb", "p_operation_id" "text", "p_operation_fingerprint" "text", "p_actor_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."commit_chat_source_reconciliation"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_chat_revision" bigint, "p_chat_hash" "text", "p_recovered_sources" "jsonb", "p_matches" "jsonb", "p_operation_id" "text", "p_operation_fingerprint" "text", "p_actor_id" "uuid") IS 'Atomically promotes verified Hearth chat URLs; invariant compares all editorial fields while allowing only revision, plan, and Source authority identifiers to advance.';



CREATE OR REPLACE FUNCTION "tongs"."commit_cleanup_review_discard"("p_actor" "uuid", "p_workspace" "uuid", "p_workpiece" "uuid", "p_revision" "uuid", "p_basis_hash" "text", "p_candidate_hash" "text", "p_basis" "jsonb", "p_candidate" "jsonb", "p_evidence" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare current_evidence jsonb; d tongs.hammer_cleanup_review_decisions%rowtype;
begin
  current_evidence:=tongs.read_cleanup_review_basis(p_actor,p_workspace,p_workpiece,p_revision,true);
  if current_evidence is distinct from p_evidence then raise exception 'cleanup_review_stale_basis' using errcode='40001'; end if;
  if p_basis->>'contract_version' is distinct from 'hammer-cleanup-review-v1' or p_basis->>'generator_version' is distinct from 'hammer-cleanup-generator-v1'
    or p_basis->>'workspace_id' is distinct from p_workspace::text or p_basis->>'workpiece_id' is distinct from p_workpiece::text
    or p_basis->>'recording_revision_id' is distinct from p_revision::text
    or p_basis->>'canonical_recording_id' is distinct from current_evidence->>'canonical_recording_id'
    or p_basis#>>'{media,media_id}' is distinct from current_evidence->>'media_id'
    or p_basis#>>'{media,sha256}' is distinct from lower(current_evidence#>>'{media,hash_value}')
    or p_basis#>>'{media,bytes}' is distinct from current_evidence#>>'{media,bytes}'
    or p_candidate->>'kind' is distinct from p_basis->>'kind' then raise exception 'cleanup_review_descriptor_invalid' using errcode='22023'; end if;
  insert into tongs.hammer_cleanup_review_decisions(workspace_id,workpiece_id,canonical_recording_id,recording_revision_id,contract_version,
    basis_fingerprint,candidate_fingerprint,basis_descriptor,candidate_descriptor,evidence_tokens,authored_by)
  values(p_workspace,p_workpiece,(current_evidence->>'canonical_recording_id')::uuid,p_revision,'hammer-cleanup-review-v1',
    p_basis_hash,p_candidate_hash,p_basis,p_candidate,p_evidence,p_actor) on conflict do nothing returning * into d;
  if d.id is not null then return jsonb_build_object('outcome','committed','receipt',to_jsonb(d)); end if;
  select * into d from tongs.hammer_cleanup_review_decisions where workspace_id=p_workspace and workpiece_id=p_workpiece
    and recording_revision_id=p_revision and basis_fingerprint=p_basis_hash and candidate_fingerprint=p_candidate_hash;
  if d.id is null or d.basis_descriptor is distinct from p_basis or d.candidate_descriptor is distinct from p_candidate then
    raise exception 'cleanup_review_idempotency_conflict' using errcode='40001'; end if;
  return jsonb_build_object('outcome','already_committed','receipt',to_jsonb(d));
end $$;


ALTER FUNCTION "tongs"."commit_cleanup_review_discard"("p_actor" "uuid", "p_workspace" "uuid", "p_workpiece" "uuid", "p_revision" "uuid", "p_basis_hash" "text", "p_candidate_hash" "text", "p_basis" "jsonb", "p_candidate" "jsonb", "p_evidence" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."commit_compound_ai_pricing_policy_revision"("p_policy_code" "text", "p_expected_revision" integer, "p_revision_id" "uuid", "p_provider" "text", "p_model" "text", "p_model_snapshot" "text", "p_media_kind" "text", "p_generation_mode" "text", "p_endpoint" "text", "p_billable_dimensions" "jsonb", "p_rate_components" "jsonb", "p_provider_currency" "text", "p_forge_credit_conversion_numerator" bigint, "p_forge_credit_conversion_denominator" bigint, "p_markup_numerator" bigint, "p_markup_denominator" bigint, "p_addon_credits" bigint, "p_customer_rounding_rule" "text", "p_effective_from" timestamp with time zone, "p_effective_through" timestamp with time zone, "p_is_active" boolean, "p_price_source_type" "text", "p_price_source_reference" "text", "p_price_source_version" "text", "p_actor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $_$
declare
  v_policy tongs.ai_pricing_policies%rowtype;
  v_sequence tongs.ai_pricing_policy_sequences%rowtype;
  v_revision tongs.ai_pricing_policy_revisions%rowtype;
  v_next integer;
  v_hash text;
  v_components jsonb;
  v_component jsonb;
  v_component_count integer;
  v_distinct_count integer;
  v_currency text := upper(btrim(coalesce(p_provider_currency, '')));
begin
  if nullif(btrim(p_policy_code), '') is null or p_revision_id is null
     or nullif(btrim(p_provider), '') is null or nullif(btrim(p_model), '') is null
     or nullif(btrim(p_model_snapshot), '') is null or nullif(btrim(p_endpoint), '') is null
     or lower(btrim(coalesce(p_media_kind, ''))) not in ('image', 'video', 'audio', 'text')
     or jsonb_typeof(p_billable_dimensions) <> 'object'
     or jsonb_typeof(p_rate_components) <> 'array'
     or jsonb_array_length(p_rate_components) = 0
     or v_currency !~ '^[A-Z]{3}$'
     or p_forge_credit_conversion_numerator <= 0 or p_forge_credit_conversion_denominator <= 0
     or p_markup_numerator <= 0 or p_markup_denominator <= 0 or p_addon_credits < 0
     or p_customer_rounding_rule <> 'ceiling_whole_credit'
     or (p_effective_through is not null and p_effective_through <= p_effective_from) then
    raise exception 'invalid compound pricing-policy revision' using errcode = '22023';
  end if;

  select count(*), count(distinct value->>'component_kind')
    into v_component_count, v_distinct_count
  from jsonb_array_elements(p_rate_components);
  if v_component_count <> v_distinct_count then
    raise exception 'duplicate compound pricing component kind' using errcode = '22023';
  end if;

  select jsonb_agg(value order by (value->>'ordinal')::integer, value->>'component_kind')
    into v_components
  from jsonb_array_elements(p_rate_components);

  for v_component in select value from jsonb_array_elements(v_components) loop
    if nullif(btrim(v_component->>'component_kind'), '') is null
       or nullif(btrim(v_component->>'unit_kind'), '') is null
       or coalesce((v_component->>'ordinal')::integer, 0) <= 0
       or coalesce((v_component->>'rate_numerator')::bigint, -1) < 0
       or coalesce((v_component->>'rate_denominator')::bigint, 0) <= 0
       or coalesce(upper(v_component->>'currency'), '') <> v_currency
       or coalesce(jsonb_typeof(v_component->'metadata'), 'null') <> 'object' then
      raise exception 'invalid compound pricing component' using errcode = '22023';
    end if;
  end loop;

  insert into tongs.ai_pricing_policies (policy_code) values (btrim(p_policy_code))
    on conflict (policy_code) do nothing;
  select * into v_policy from tongs.ai_pricing_policies where policy_code = btrim(p_policy_code) for update;
  select * into v_sequence from tongs.ai_pricing_policy_sequences where policy_id = v_policy.id for update;
  if found and v_sequence.current_revision <> coalesce(p_expected_revision, 0) then
    raise exception 'stale pricing-policy revision' using errcode = '40001';
  elsif not found and coalesce(p_expected_revision, 0) <> 0 then
    raise exception 'stale pricing-policy revision' using errcode = '40001';
  end if;
  select * into v_revision from tongs.ai_pricing_policy_revisions where id = p_revision_id;
  if found then
    if v_revision.policy_id <> v_policy.id
       or v_revision.provider <> lower(btrim(p_provider))
       or v_revision.model <> btrim(p_model)
       or v_revision.model_snapshot <> btrim(p_model_snapshot)
       or v_revision.media_kind <> lower(btrim(p_media_kind))
       or v_revision.generation_mode <> btrim(p_generation_mode)
       or v_revision.endpoint <> btrim(p_endpoint)
       or v_revision.billable_dimensions <> p_billable_dimensions
       or v_revision.provider_currency <> v_currency
       or v_revision.forge_credit_conversion_numerator <> p_forge_credit_conversion_numerator
       or v_revision.forge_credit_conversion_denominator <> p_forge_credit_conversion_denominator
       or v_revision.markup_numerator <> p_markup_numerator
       or v_revision.markup_denominator <> p_markup_denominator
       or v_revision.addon_credits <> p_addon_credits
       or v_revision.customer_rounding_rule <> p_customer_rounding_rule
       or v_revision.effective_from <> p_effective_from
       or v_revision.effective_through is distinct from p_effective_through
       or v_revision.is_active <> p_is_active
       or v_revision.price_source_type <> p_price_source_type
       or v_revision.price_source_reference <> p_price_source_reference
       or v_revision.price_source_version is distinct from p_price_source_version
       or exists (
         select 1
         from jsonb_array_elements(v_components) proposed
         full join tongs.ai_pricing_rate_components stored
           on stored.pricing_policy_revision_id = v_revision.id
          and stored.component_kind = proposed->>'component_kind'
         where proposed is null or stored.id is null
            or stored.id <> (proposed->>'id')::uuid
            or stored.ordinal <> (proposed->>'ordinal')::integer
            or stored.unit_kind <> proposed->>'unit_kind'
            or stored.rate_numerator <> (proposed->>'rate_numerator')::bigint
            or stored.rate_denominator <> (proposed->>'rate_denominator')::bigint
            or stored.currency <> upper(proposed->>'currency')
            or stored.metadata_json <> proposed->'metadata'
       ) then
      raise exception 'compound pricing-policy replay conflict' using errcode = '23505';
    end if;
    return jsonb_build_object(
      'policy', to_jsonb(v_policy), 'revision', to_jsonb(v_revision),
      'rate_components', (select jsonb_agg(to_jsonb(c) order by c.ordinal) from tongs.ai_pricing_rate_components c where c.pricing_policy_revision_id = v_revision.id),
      'replay', true
    );
  end if;

  v_next := coalesce(v_sequence.current_revision, 0) + 1;
  v_hash := encode(extensions.digest(convert_to(jsonb_build_object(
    'policy_id', v_policy.id, 'revision', v_next, 'pricing_contract_version', 'compound_v2',
    'provider', lower(btrim(p_provider)), 'model', btrim(p_model), 'model_snapshot', btrim(p_model_snapshot),
    'media_kind', lower(btrim(p_media_kind)), 'generation_mode', btrim(p_generation_mode),
    'endpoint', btrim(p_endpoint), 'billable_dimensions', p_billable_dimensions,
    'rate_components', v_components, 'provider_currency', v_currency,
    'forge_credit_conversion_numerator', p_forge_credit_conversion_numerator,
    'forge_credit_conversion_denominator', p_forge_credit_conversion_denominator,
    'markup_numerator', p_markup_numerator, 'markup_denominator', p_markup_denominator,
    'addon_credits', p_addon_credits, 'customer_rounding_rule', p_customer_rounding_rule,
    'effective_from', p_effective_from, 'effective_through', p_effective_through,
    'is_active', p_is_active, 'price_source_type', p_price_source_type,
    'price_source_reference', p_price_source_reference, 'price_source_version', p_price_source_version
  )::text, 'utf8'), 'sha256'), 'hex');

  insert into tongs.ai_pricing_policy_revisions (
    id, policy_id, revision, previous_revision_id, provider, model, media_kind, generation_mode,
    billable_dimensions, provider_billing_unit, provider_price_micros_per_unit, provider_currency,
    forge_credit_conversion_numerator, forge_credit_conversion_denominator, markup_numerator, markup_denominator,
    addon_credits, effective_from, effective_through, is_active, price_source_type, price_source_reference,
    price_source_version, actor_id, content_hash, pricing_contract_version, model_snapshot, endpoint,
    customer_rounding_rule
  ) values (
    p_revision_id, v_policy.id, v_next, v_sequence.current_revision_id, lower(btrim(p_provider)), btrim(p_model),
    lower(btrim(p_media_kind)), btrim(p_generation_mode), p_billable_dimensions, 'compound_component', 0,
    v_currency, p_forge_credit_conversion_numerator, p_forge_credit_conversion_denominator,
    p_markup_numerator, p_markup_denominator, p_addon_credits, p_effective_from, p_effective_through,
    p_is_active, p_price_source_type, p_price_source_reference, p_price_source_version, p_actor_id,
    v_hash, 'compound_v2', btrim(p_model_snapshot), btrim(p_endpoint), p_customer_rounding_rule
  ) returning * into v_revision;

  for v_component in select value from jsonb_array_elements(v_components) loop
    insert into tongs.ai_pricing_rate_components (
      id, pricing_policy_revision_id, ordinal, component_kind, unit_kind, rate_numerator,
      rate_denominator, currency, metadata_json, content_hash
    ) values (
      (v_component->>'id')::uuid, v_revision.id, (v_component->>'ordinal')::integer,
      btrim(v_component->>'component_kind'), btrim(v_component->>'unit_kind'),
      (v_component->>'rate_numerator')::bigint, (v_component->>'rate_denominator')::bigint,
      v_currency, v_component->'metadata',
      encode(extensions.digest(convert_to(jsonb_build_object(
        'pricing_policy_revision_id', v_revision.id, 'ordinal', (v_component->>'ordinal')::integer,
        'component_kind', btrim(v_component->>'component_kind'), 'unit_kind', btrim(v_component->>'unit_kind'),
        'rate_numerator', (v_component->>'rate_numerator')::bigint,
        'rate_denominator', (v_component->>'rate_denominator')::bigint,
        'currency', v_currency, 'metadata', v_component->'metadata'
      )::text, 'utf8'), 'sha256'), 'hex')
    );
  end loop;

  insert into tongs.ai_pricing_policy_sequences values (v_policy.id, v_revision.id, v_revision.revision, now())
    on conflict (policy_id) do update set current_revision_id = excluded.current_revision_id,
      current_revision = excluded.current_revision, updated_at = now();
  return jsonb_build_object(
    'policy', to_jsonb(v_policy), 'revision', to_jsonb(v_revision),
    'rate_components', (select jsonb_agg(to_jsonb(c) order by c.ordinal) from tongs.ai_pricing_rate_components c where c.pricing_policy_revision_id = v_revision.id),
    'replay', false
  );
end;
$_$;


ALTER FUNCTION "tongs"."commit_compound_ai_pricing_policy_revision"("p_policy_code" "text", "p_expected_revision" integer, "p_revision_id" "uuid", "p_provider" "text", "p_model" "text", "p_model_snapshot" "text", "p_media_kind" "text", "p_generation_mode" "text", "p_endpoint" "text", "p_billable_dimensions" "jsonb", "p_rate_components" "jsonb", "p_provider_currency" "text", "p_forge_credit_conversion_numerator" bigint, "p_forge_credit_conversion_denominator" bigint, "p_markup_numerator" bigint, "p_markup_denominator" bigint, "p_addon_credits" bigint, "p_customer_rounding_rule" "text", "p_effective_from" timestamp with time zone, "p_effective_through" timestamp with time zone, "p_is_active" boolean, "p_price_source_type" "text", "p_price_source_reference" "text", "p_price_source_version" "text", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."commit_hammer_audio_master"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_path" "text", "p_mime_type" "text", "p_byte_size" bigint, "p_content_hash" "text", "p_storage_bucket" "text", "p_storage_key" "text", "p_duration_ms" bigint, "p_render_evidence" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $_$
declare op tongs.hammer_audio_render_operations%rowtype; a tongs.assets%rowtype; receipt jsonb;
begin
  if auth.role()<>'service_role' then raise exception 'Hammer audio master commit requires service authority' using errcode='42501'; end if;
  select * into op from tongs.hammer_audio_render_operations where operation_id=p_operation_id for update;
  if not found then return jsonb_build_object('disposition','operation_not_found'); end if;
  if op.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict'); end if;
  if op.state='completed' then return op.receipt_json; end if;
  if op.state not in('pending','rendering') then return jsonb_build_object('disposition','operation_not_committable','state',op.state); end if;
  if p_mime_type not like'audio/%' or p_byte_size<=0 or p_duration_ms<=0 or p_content_hash!~'^[0-9a-f]{64}$' then return jsonb_build_object('disposition','invalid_verified_audio_evidence'); end if;
  select * into a from tongs.assets where operation_id=p_operation_id and asset_kind='hammer_audio_master' for update;
  if found then
    if a.operation_fingerprint<>p_operation_fingerprint or a.content_hash<>p_content_hash or a.storage_bucket<>p_storage_bucket or a.storage_key<>p_storage_key or a.bytes<>p_byte_size then return jsonb_build_object('disposition','asset_replay_conflict'); end if;
  else
    insert into tongs.assets(workspace_id,workpiece_id,asset_scope,path,mime_type,bytes,storage_bucket,storage_key,provider,request_id,created_by,asset_kind,status,metadata_json,operation_id,operation_fingerprint,content_hash,provenance_classification,provenance_json,ready_at)
    values(op.workspace_id,op.workpiece_id,'workpiece',p_path,p_mime_type,p_byte_size,p_storage_bucket,p_storage_key,'hammer-renderer',p_operation_id,op.created_by,'hammer_audio_master','ready',jsonb_build_object('duration_ms',p_duration_ms,'recording_revision_id',op.recording_revision_id,'composition_revision',op.composition_revision,'composition_fingerprint',op.composition_fingerprint,'render_plan_fingerprint',op.render_plan_fingerprint,'renderer_version',op.renderer_version,'output_profile_id',op.output_profile_id),p_operation_id,p_operation_fingerprint,p_content_hash,'canonical_native',coalesce(p_render_evidence,'{}'::jsonb),now()) returning * into a;
  end if;
  receipt:=jsonb_build_object('disposition','committed','operation_id',op.operation_id,'operation_fingerprint',op.operation_fingerprint,'asset',to_jsonb(a),'render_evidence',p_render_evidence);
  update tongs.hammer_audio_render_operations set state='completed',output_asset_id=a.id,render_evidence_json=p_render_evidence,receipt_json=receipt,failure_code=null,failure_message=null,updated_at=now() where operation_id=p_operation_id;
  return receipt;
end$_$;


ALTER FUNCTION "tongs"."commit_hammer_audio_master"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_path" "text", "p_mime_type" "text", "p_byte_size" bigint, "p_content_hash" "text", "p_storage_bucket" "text", "p_storage_key" "text", "p_duration_ms" bigint, "p_render_evidence" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."commit_hammer_history_epoch"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_canonical_recording_id" "uuid", "p_revision_id" "uuid", "p_epoch_id" "uuid", "p_idempotency_key" "text", "p_operation_fingerprint" "text", "p_expected_revision_updated_at" timestamp with time zone, "p_expected_history_path" "text", "p_predecessor_registry_revision" bigint, "p_predecessor_registry_updated_at" timestamp with time zone, "p_predecessor_sha256" "text", "p_predecessor_bytes" bigint, "p_archive_path" "text", "p_archive_registry_revision" bigint, "p_archive_registry_updated_at" timestamp with time zone, "p_epoch_path" "text", "p_epoch_registry_revision" bigint, "p_epoch_registry_updated_at" timestamp with time zone, "p_epoch_sha256" "text", "p_epoch_bytes" bigint, "p_base_editor_state_hash" "text", "p_base_component_sha256" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_revision tongs.recording_revisions%rowtype;
  v_predecessor tongs.workpiece_files%rowtype;
  v_archive tongs.workpiece_files%rowtype;
  v_epoch_file tongs.workpiece_files%rowtype;
  v_existing tongs.hammer_history_epoch_transitions%rowtype;
  v_epoch tongs.hammer_history_epochs%rowtype;
  v_transition tongs.hammer_history_epoch_transitions%rowtype;
  v_committed_updated_at timestamptz;
begin
  if v_actor is null or not tongs.has_workspace_role(p_workspace_id, 'editor') then
    return jsonb_build_object('outcome', 'conflict', 'code', 'history_epoch_forbidden', 'terminal', true, 'retryable', false);
  end if;

  if p_idempotency_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{15,127}$'
    or p_operation_fingerprint !~ '^[0-9a-f]{64}$'
    or p_predecessor_sha256 !~ '^[0-9a-f]{64}$'
    or p_epoch_sha256 !~ '^[0-9a-f]{64}$'
    or p_predecessor_bytes <= 0
    or p_epoch_bytes <= 0
    or p_base_editor_state_hash !~ '^hammer-state:[0-9a-f]{8}$'
    or not tongs.is_hammer_history_component_sha256(p_base_component_sha256)
  then
    return jsonb_build_object('outcome', 'conflict', 'code', 'history_epoch_request_invalid', 'terminal', true, 'retryable', false);
  end if;

  if p_archive_path <> format('hammer/revisions/%s/history/archive/%s.history.v1.json', p_revision_id, p_predecessor_sha256)
    or p_epoch_path <> format('hammer/revisions/%s/history/epochs/%s.v1.json', p_revision_id, p_epoch_id)
    or p_expected_history_path = p_archive_path
    or p_expected_history_path = p_epoch_path
  then
    return jsonb_build_object('outcome', 'conflict', 'code', 'history_epoch_path_invalid', 'terminal', true, 'retryable', false);
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    p_workspace_id::text || ':' || p_workpiece_id::text || ':' || p_revision_id::text || ':' || p_idempotency_key,
    0
  ));

  select * into v_existing
  from tongs.hammer_history_epoch_transitions
  where workspace_id = p_workspace_id
    and workpiece_id = p_workpiece_id
    and recording_revision_id = p_revision_id
    and idempotency_key = p_idempotency_key;

  if v_existing.transition_id is not null then
    if v_existing.operation_fingerprint = p_operation_fingerprint
      and v_existing.epoch_id = p_epoch_id
      and v_existing.canonical_recording_id = p_canonical_recording_id
    then
      return jsonb_build_object(
        'outcome', 'already_committed',
        'epoch_id', v_existing.epoch_id,
        'transition_id', v_existing.transition_id,
        'history_path', v_existing.committed_history_path,
        'revision_updated_at', v_existing.committed_revision_updated_at,
        'operation_fingerprint', v_existing.operation_fingerprint
      );
    end if;
    return jsonb_build_object('outcome', 'conflict', 'code', 'history_epoch_idempotency_conflict', 'terminal', true, 'retryable', false);
  end if;

  select rr.* into v_revision
  from tongs.recording_revisions rr
  join tongs.episodes e
    on e.id = rr.workpiece_id
   and e.workspace_id = rr.workspace_id
   and e.active_revision_id = rr.id
   and e.canonical_recording_id = rr.canonical_recording_id
  join tongs.canonical_recordings cr
    on cr.id = rr.canonical_recording_id
   and cr.workspace_id = rr.workspace_id
   and cr.workpiece_id = rr.workpiece_id
  where rr.id = p_revision_id
    and rr.workspace_id = p_workspace_id
    and rr.workpiece_id = p_workpiece_id
    and rr.canonical_recording_id = p_canonical_recording_id
    and rr.status = 'active'
  for update of rr;

  if v_revision.id is null then
    return jsonb_build_object('outcome', 'conflict', 'code', 'history_epoch_identity_conflict', 'terminal', true, 'retryable', false);
  end if;
  if v_revision.updated_at <> p_expected_revision_updated_at then
    return jsonb_build_object('outcome', 'conflict', 'code', 'history_epoch_revision_token_conflict', 'terminal', true, 'retryable', false);
  end if;
  if v_revision.history_path is distinct from p_expected_history_path then
    return jsonb_build_object('outcome', 'conflict', 'code', 'history_epoch_pointer_conflict', 'terminal', true, 'retryable', false);
  end if;

  select * into v_predecessor
  from tongs.workpiece_files
  where workpiece_id = p_workpiece_id and path = p_expected_history_path
  for update;
  if v_predecessor.workpiece_id is null
    or v_predecessor.revision <> p_predecessor_registry_revision
    or v_predecessor.updated_at <> p_predecessor_registry_updated_at
    or lower(v_predecessor.hash_value) <> p_predecessor_sha256
    or v_predecessor.bytes <> p_predecessor_bytes
    or v_predecessor.content_type <> 'application/json'
    or v_predecessor.hash_algo <> 'sha256'
    or v_predecessor.storage_bucket <> 'forge-workpieces'
    or v_predecessor.storage_key <> format('workpieces/%s/%s', p_workpiece_id, p_expected_history_path)
  then
    return jsonb_build_object('outcome', 'conflict', 'code', 'history_epoch_predecessor_registry_conflict', 'terminal', true, 'retryable', false);
  end if;

  select * into v_archive
  from tongs.workpiece_files
  where workpiece_id = p_workpiece_id and path = p_archive_path
  for update;
  if v_archive.workpiece_id is null
    or v_archive.revision <> p_archive_registry_revision
    or v_archive.updated_at <> p_archive_registry_updated_at
    or lower(v_archive.hash_value) <> p_predecessor_sha256
    or v_archive.bytes <> p_predecessor_bytes
    or v_archive.content_type <> 'application/json'
    or v_archive.file_type <> 'hammer_history_archive'
    or v_archive.hash_algo <> 'sha256'
    or v_archive.storage_bucket <> 'forge-workpieces'
    or v_archive.storage_key <> format('workpieces/%s/%s', p_workpiece_id, p_archive_path)
  then
    return jsonb_build_object('outcome', 'conflict', 'code', 'history_epoch_archive_registry_conflict', 'terminal', true, 'retryable', false);
  end if;

  select * into v_epoch_file
  from tongs.workpiece_files
  where workpiece_id = p_workpiece_id and path = p_epoch_path
  for update;
  if v_epoch_file.workpiece_id is null
    or v_epoch_file.revision <> p_epoch_registry_revision
    or v_epoch_file.updated_at <> p_epoch_registry_updated_at
    or lower(v_epoch_file.hash_value) <> p_epoch_sha256
    or v_epoch_file.bytes <> p_epoch_bytes
    or v_epoch_file.content_type <> 'application/json'
    or v_epoch_file.file_type <> 'hammer_history_epoch'
    or v_epoch_file.hash_algo <> 'sha256'
    or v_epoch_file.storage_bucket <> 'forge-workpieces'
    or v_epoch_file.storage_key <> format('workpieces/%s/%s', p_workpiece_id, p_epoch_path)
  then
    return jsonb_build_object('outcome', 'conflict', 'code', 'history_epoch_artifact_registry_conflict', 'terminal', true, 'retryable', false);
  end if;

  update tongs.recording_revisions
  set history_path = p_epoch_path,
      updated_at = clock_timestamp(),
      updated_by = v_actor
  where id = p_revision_id
    and workspace_id = p_workspace_id
    and workpiece_id = p_workpiece_id
    and canonical_recording_id = p_canonical_recording_id
    and status = 'active'
    and updated_at = p_expected_revision_updated_at
    and history_path is not distinct from p_expected_history_path
  returning updated_at into v_committed_updated_at;

  if v_committed_updated_at is null then
    return jsonb_build_object('outcome', 'conflict', 'code', 'history_epoch_cas_conflict', 'terminal', true, 'retryable', false);
  end if;

  insert into tongs.hammer_history_epochs (
    epoch_id, workspace_id, workpiece_id, canonical_recording_id, recording_revision_id,
    artifact_path, artifact_sha256, artifact_bytes, artifact_registry_revision, artifact_registry_updated_at,
    base_editor_state_hash, base_component_sha256, creation_reason,
    predecessor_original_path, predecessor_archive_path, predecessor_sha256, predecessor_bytes,
    predecessor_registry_revision, predecessor_registry_updated_at,
    archive_registry_revision, archive_registry_updated_at, initiating_user_id
  ) values (
    p_epoch_id, p_workspace_id, p_workpiece_id, p_canonical_recording_id, p_revision_id,
    p_epoch_path, p_epoch_sha256, p_epoch_bytes, p_epoch_registry_revision, p_epoch_registry_updated_at,
    p_base_editor_state_hash, p_base_component_sha256, 'legacy_history_unrecoverable',
    p_expected_history_path, p_archive_path, p_predecessor_sha256, p_predecessor_bytes,
    p_predecessor_registry_revision, p_predecessor_registry_updated_at,
    p_archive_registry_revision, p_archive_registry_updated_at, v_actor
  ) returning * into v_epoch;

  insert into tongs.hammer_history_epoch_transitions (
    epoch_id, workspace_id, workpiece_id, canonical_recording_id, recording_revision_id,
    idempotency_key, operation_fingerprint, expected_revision_updated_at, expected_history_path,
    committed_history_path, committed_revision_updated_at,
    predecessor_original_path, predecessor_archive_path, predecessor_sha256, predecessor_bytes,
    predecessor_registry_revision, predecessor_registry_updated_at,
    archive_registry_revision, archive_registry_updated_at,
    epoch_artifact_sha256, epoch_artifact_bytes, epoch_registry_revision, epoch_registry_updated_at,
    outcome, initiated_by
  ) values (
    p_epoch_id, p_workspace_id, p_workpiece_id, p_canonical_recording_id, p_revision_id,
    p_idempotency_key, p_operation_fingerprint, p_expected_revision_updated_at, p_expected_history_path,
    p_epoch_path, v_committed_updated_at,
    p_expected_history_path, p_archive_path, p_predecessor_sha256, p_predecessor_bytes,
    p_predecessor_registry_revision, p_predecessor_registry_updated_at,
    p_archive_registry_revision, p_archive_registry_updated_at,
    p_epoch_sha256, p_epoch_bytes, p_epoch_registry_revision, p_epoch_registry_updated_at,
    'committed', v_actor
  ) returning * into v_transition;

  return jsonb_build_object(
    'outcome', 'committed',
    'epoch_id', v_epoch.epoch_id,
    'transition_id', v_transition.transition_id,
    'history_path', v_epoch.artifact_path,
    'revision_updated_at', v_committed_updated_at,
    'operation_fingerprint', v_transition.operation_fingerprint
  );
exception
  when unique_violation then
    return jsonb_build_object('outcome', 'conflict', 'code', 'history_epoch_uniqueness_conflict', 'terminal', true, 'retryable', false);
  when foreign_key_violation or check_violation or not_null_violation then
    return jsonb_build_object('outcome', 'conflict', 'code', 'history_epoch_constraint_conflict', 'terminal', true, 'retryable', false);
end;
$_$;


ALTER FUNCTION "tongs"."commit_hammer_history_epoch"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_canonical_recording_id" "uuid", "p_revision_id" "uuid", "p_epoch_id" "uuid", "p_idempotency_key" "text", "p_operation_fingerprint" "text", "p_expected_revision_updated_at" timestamp with time zone, "p_expected_history_path" "text", "p_predecessor_registry_revision" bigint, "p_predecessor_registry_updated_at" timestamp with time zone, "p_predecessor_sha256" "text", "p_predecessor_bytes" bigint, "p_archive_path" "text", "p_archive_registry_revision" bigint, "p_archive_registry_updated_at" timestamp with time zone, "p_epoch_path" "text", "p_epoch_registry_revision" bigint, "p_epoch_registry_updated_at" timestamp with time zone, "p_epoch_sha256" "text", "p_epoch_bytes" bigint, "p_base_editor_state_hash" "text", "p_base_component_sha256" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."commit_hammer_history_epoch"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_canonical_recording_id" "uuid", "p_revision_id" "uuid", "p_epoch_id" "uuid", "p_idempotency_key" "text", "p_operation_fingerprint" "text", "p_expected_revision_updated_at" timestamp with time zone, "p_expected_history_path" "text", "p_predecessor_registry_revision" bigint, "p_predecessor_registry_updated_at" timestamp with time zone, "p_predecessor_sha256" "text", "p_predecessor_bytes" bigint, "p_archive_path" "text", "p_archive_registry_revision" bigint, "p_archive_registry_updated_at" timestamp with time zone, "p_epoch_path" "text", "p_epoch_registry_revision" bigint, "p_epoch_registry_updated_at" timestamp with time zone, "p_epoch_sha256" "text", "p_epoch_bytes" bigint, "p_base_editor_state_hash" "text", "p_base_component_sha256" "jsonb") IS 'Atomically validates staged immutable history artifacts, records the epoch receipt, and CAS-advances recording_revisions.history_path.';



CREATE OR REPLACE FUNCTION "tongs"."commit_hammer_history_epoch_head"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_canonical_recording_id" "uuid", "p_revision_id" "uuid", "p_epoch_id" "uuid", "p_head_id" "uuid", "p_sequence" bigint, "p_idempotency_key" "text", "p_operation_fingerprint" "text", "p_expected_revision_updated_at" timestamp with time zone, "p_expected_history_path" "text", "p_parent_head_id" "uuid", "p_parent_sha256" "text", "p_parent_registry_revision" bigint, "p_parent_registry_updated_at" timestamp with time zone, "p_head_path" "text", "p_head_sha256" "text", "p_head_bytes" bigint, "p_head_registry_revision" bigint, "p_head_registry_updated_at" timestamp with time zone, "p_result_editor_state_hash" "text", "p_result_component_authority" "jsonb", "p_envelope" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_revision tongs.recording_revisions%rowtype;
  v_epoch tongs.hammer_history_epochs%rowtype;
  v_parent_head tongs.hammer_history_epoch_heads%rowtype;
  v_parent_file tongs.workpiece_files%rowtype;
  v_head_file tongs.workpiece_files%rowtype;
  v_existing tongs.hammer_history_epoch_head_transitions%rowtype;
  v_head tongs.hammer_history_epoch_heads%rowtype;
  v_transition tongs.hammer_history_epoch_head_transitions%rowtype;
  v_committed_updated_at timestamptz;
begin
  if v_actor is null or not tongs.has_workspace_role(p_workspace_id, 'editor') then
    return jsonb_build_object('outcome','conflict','code','history_epoch_head_forbidden','terminal',true,'retryable',false);
  end if;
  if p_sequence <= 0
    or p_idempotency_key !~ '^[A-Za-z0-9][A-Za-z0-9._:-]{15,127}$'
    or p_operation_fingerprint !~ '^[0-9a-f]{64}$'
    or p_parent_sha256 !~ '^[0-9a-f]{64}$'
    or p_head_sha256 !~ '^[0-9a-f]{64}$'
    or p_head_bytes <= 0 or p_parent_registry_revision <= 0 or p_head_registry_revision <= 0
    or p_result_editor_state_hash !~ '^hammer-state:[0-9a-f]{8}$'
    or jsonb_typeof(p_result_component_authority) <> 'object'
  then
    return jsonb_build_object('outcome','conflict','code','history_epoch_head_request_invalid','terminal',true,'retryable',false);
  end if;
  if p_head_path <> format('hammer/revisions/%s/history/epochs/%s/heads/%s.history.v1.json', p_revision_id, p_epoch_id, p_head_id)
    or p_expected_history_path = p_head_path
  then
    return jsonb_build_object('outcome','conflict','code','history_epoch_head_path_invalid','terminal',true,'retryable',false);
  end if;
  if jsonb_typeof(p_envelope) <> 'object'
    or p_envelope->>'schema' <> 'forge.hammer-history-epoch-head'
    or p_envelope->>'schema_version' <> '1'
    or p_envelope->>'workspace_id' <> p_workspace_id::text
    or p_envelope->>'workpiece_id' <> p_workpiece_id::text
    or p_envelope->>'canonical_recording_id' <> p_canonical_recording_id::text
    or p_envelope->>'recording_revision_id' <> p_revision_id::text
    or p_envelope->>'epoch_id' <> p_epoch_id::text
    or p_envelope->>'head_id' <> p_head_id::text
    or p_envelope->>'sequence' <> p_sequence::text
    or p_envelope#>>'{parent,path}' <> p_expected_history_path
    or p_envelope#>>'{parent,head_id}' is distinct from p_parent_head_id::text
    or p_envelope#>>'{parent,sha256}' <> p_parent_sha256
    or p_envelope#>>'{parent,registry_revision}' <> p_parent_registry_revision::text
    or (p_envelope#>>'{parent,registry_updated_at}')::timestamptz <> p_parent_registry_updated_at
    or p_envelope#>>'{result,editor_state_hash}' <> p_result_editor_state_hash
    or p_envelope#>'{result,component_authority}' <> p_result_component_authority
    or p_envelope#>>'{artifact,path}' <> p_head_path
    or p_envelope#>>'{artifact,sha256}' <> p_head_sha256
    or p_envelope#>>'{artifact,bytes}' <> p_head_bytes::text
    or p_envelope#>>'{artifact,registry_revision}' <> p_head_registry_revision::text
    or (p_envelope#>>'{artifact,registry_updated_at}')::timestamptz <> p_head_registry_updated_at
    or jsonb_typeof(p_envelope->'history') <> 'object'
    or p_envelope#>>'{boundary,prior_history_status}' <> 'unavailable'
    or p_envelope#>>'{boundary,merged}' <> 'false'
    or p_envelope#>>'{boundary,traversable}' <> 'false'
    or p_envelope#>>'{creation,initiating_user_id}' <> v_actor::text
  then
    return jsonb_build_object('outcome','conflict','code','history_epoch_head_envelope_conflict','terminal',true,'retryable',false);
  end if;

  perform pg_advisory_xact_lock(hashtextextended(p_workspace_id::text || ':' || p_workpiece_id::text || ':' || p_revision_id::text, 0));

  select * into v_existing from tongs.hammer_history_epoch_head_transitions
  where workspace_id = p_workspace_id and workpiece_id = p_workpiece_id
    and recording_revision_id = p_revision_id and idempotency_key = p_idempotency_key;
  if v_existing.transition_id is not null then
    if v_existing.operation_fingerprint = p_operation_fingerprint and v_existing.head_id = p_head_id
      and v_existing.epoch_id = p_epoch_id and v_existing.sequence = p_sequence
      and v_existing.canonical_recording_id = p_canonical_recording_id
      and v_existing.expected_revision_updated_at = p_expected_revision_updated_at
      and v_existing.expected_history_path = p_expected_history_path
      and v_existing.parent_head_id is not distinct from p_parent_head_id
      and v_existing.parent_sha256 = p_parent_sha256
      and v_existing.parent_registry_revision = p_parent_registry_revision
      and v_existing.parent_registry_updated_at = p_parent_registry_updated_at
      and v_existing.committed_history_path = p_head_path
      and v_existing.head_sha256 = p_head_sha256 and v_existing.head_bytes = p_head_bytes
      and v_existing.head_registry_revision = p_head_registry_revision
      and v_existing.head_registry_updated_at = p_head_registry_updated_at
      and v_existing.result_editor_state_hash = p_result_editor_state_hash
      and v_existing.result_component_authority = p_result_component_authority
      and v_existing.envelope = p_envelope
    then
      return jsonb_build_object('outcome','already_committed','epoch_id',v_existing.epoch_id,'head_id',v_existing.head_id,
        'sequence',v_existing.sequence,'transition_id',v_existing.transition_id,'history_path',v_existing.committed_history_path,
        'revision_updated_at',v_existing.committed_revision_updated_at,'operation_fingerprint',v_existing.operation_fingerprint);
    end if;
    return jsonb_build_object('outcome','conflict','code','history_epoch_head_idempotency_conflict','terminal',true,'retryable',false);
  end if;

  select rr.* into v_revision from tongs.recording_revisions rr
  join tongs.episodes e on e.id = rr.workpiece_id and e.workspace_id = rr.workspace_id
    and e.active_revision_id = rr.id and e.canonical_recording_id = rr.canonical_recording_id
  join tongs.canonical_recordings cr on cr.id = rr.canonical_recording_id
    and cr.workspace_id = rr.workspace_id and cr.workpiece_id = rr.workpiece_id
  where rr.id = p_revision_id and rr.workspace_id = p_workspace_id and rr.workpiece_id = p_workpiece_id
    and rr.canonical_recording_id = p_canonical_recording_id and rr.status = 'active'
  for update of rr;
  if v_revision.id is null then
    return jsonb_build_object('outcome','conflict','code','history_epoch_head_identity_conflict','terminal',true,'retryable',false);
  end if;
  if v_revision.updated_at <> p_expected_revision_updated_at then
    return jsonb_build_object('outcome','conflict','code','history_epoch_head_revision_token_conflict','terminal',true,'retryable',false);
  end if;
  if v_revision.history_path is distinct from p_expected_history_path then
    return jsonb_build_object('outcome','conflict','code','history_epoch_head_pointer_conflict','terminal',true,'retryable',false);
  end if;

  perform 1 from tongs.workpiece_files f
  where f.workpiece_id = p_workpiece_id
    and f.path in (select value->>'path' from jsonb_each(p_result_component_authority))
  for update;
  if not tongs.is_hammer_history_component_authority(p_result_component_authority) then
    return jsonb_build_object('outcome','conflict','code','history_epoch_head_component_authority_conflict','terminal',true,'retryable',false);
  end if;
  if p_result_component_authority#>>'{transcript,path}' is distinct from v_revision.revision_transcript_path
    or p_result_component_authority#>>'{visual_timeline,path}' is distinct from v_revision.visual_timeline_path
    or p_result_component_authority#>>'{visual_placements,path}' is distinct from v_revision.visual_placements_path
    or p_result_component_authority#>>'{audio,path}' is distinct from v_revision.audio_polish_path
    or p_result_component_authority#>>'{editorial_authority,path}' is distinct from v_revision.editorial_authority_path
  then
    return jsonb_build_object('outcome','conflict','code','history_epoch_head_component_authority_conflict','terminal',true,'retryable',false);
  end if;

  select * into v_epoch from tongs.hammer_history_epochs
  where epoch_id = p_epoch_id and workspace_id = p_workspace_id and workpiece_id = p_workpiece_id
    and canonical_recording_id = p_canonical_recording_id and recording_revision_id = p_revision_id;
  if v_epoch.epoch_id is null then
    return jsonb_build_object('outcome','conflict','code','history_epoch_head_epoch_conflict','terminal',true,'retryable',false);
  end if;
  if p_envelope#>>'{base,editor_state_hash}' <> v_epoch.base_editor_state_hash
    or p_envelope#>'{base,component_sha256}' <> v_epoch.base_component_sha256
    or p_envelope#>>'{epoch_anchor,path}' <> v_epoch.artifact_path
    or p_envelope#>>'{epoch_anchor,sha256}' <> v_epoch.artifact_sha256
  then
    return jsonb_build_object('outcome','conflict','code','history_epoch_head_epoch_authority_conflict','terminal',true,'retryable',false);
  end if;

  if p_sequence = 1 then
    if p_parent_head_id is not null or p_expected_history_path <> v_epoch.artifact_path
      or p_parent_sha256 <> v_epoch.artifact_sha256 or p_parent_registry_revision <> v_epoch.artifact_registry_revision
      or p_parent_registry_updated_at <> v_epoch.artifact_registry_updated_at
    then
      return jsonb_build_object('outcome','conflict','code','history_epoch_head_parent_conflict','terminal',true,'retryable',false);
    end if;
  else
    select * into v_parent_head from tongs.hammer_history_epoch_heads
    where epoch_id = p_epoch_id and sequence = p_sequence - 1;
    if v_parent_head.head_id is null or p_parent_head_id <> v_parent_head.head_id
      or p_expected_history_path <> v_parent_head.artifact_path or p_parent_sha256 <> v_parent_head.artifact_sha256
      or p_parent_registry_revision <> v_parent_head.artifact_registry_revision
      or p_parent_registry_updated_at <> v_parent_head.artifact_registry_updated_at
    then
      return jsonb_build_object('outcome','conflict','code','history_epoch_head_parent_conflict','terminal',true,'retryable',false);
    end if;
  end if;

  select * into v_parent_file from tongs.workpiece_files
  where workpiece_id = p_workpiece_id and path = p_expected_history_path for update;
  if v_parent_file.workpiece_id is null or lower(v_parent_file.hash_value) <> p_parent_sha256
    or v_parent_file.revision <> p_parent_registry_revision or v_parent_file.updated_at <> p_parent_registry_updated_at
    or v_parent_file.content_type <> 'application/json' or v_parent_file.hash_algo <> 'sha256'
    or v_parent_file.storage_bucket <> 'forge-workpieces'
    or v_parent_file.storage_key <> format('workpieces/%s/%s', p_workpiece_id, p_expected_history_path)
  then
    return jsonb_build_object('outcome','conflict','code','history_epoch_head_parent_registry_conflict','terminal',true,'retryable',false);
  end if;

  select * into v_head_file from tongs.workpiece_files
  where workpiece_id = p_workpiece_id and path = p_head_path for update;
  if v_head_file.workpiece_id is null or v_head_file.file_type <> 'hammer_history_epoch_head'
    or v_head_file.content_type <> 'application/json' or v_head_file.hash_algo <> 'sha256'
    or lower(v_head_file.hash_value) <> p_head_sha256 or v_head_file.bytes <> p_head_bytes
    or v_head_file.revision <> p_head_registry_revision or v_head_file.updated_at <> p_head_registry_updated_at
    or v_head_file.storage_bucket <> 'forge-workpieces'
    or v_head_file.storage_key <> format('workpieces/%s/%s', p_workpiece_id, p_head_path)
  then
    return jsonb_build_object('outcome','conflict','code','history_epoch_head_registry_conflict','terminal',true,'retryable',false);
  end if;

  insert into tongs.hammer_history_epoch_heads (
    head_id, epoch_id, workspace_id, workpiece_id, canonical_recording_id, recording_revision_id, sequence,
    artifact_path, artifact_sha256, artifact_bytes, artifact_registry_revision, artifact_registry_updated_at,
    parent_kind, parent_head_id, parent_path, parent_sha256, parent_registry_revision, parent_registry_updated_at,
    base_editor_state_hash, base_component_sha256, result_editor_state_hash, result_component_authority, initiated_by
  ) values (
    p_head_id, p_epoch_id, p_workspace_id, p_workpiece_id, p_canonical_recording_id, p_revision_id, p_sequence,
    p_head_path, p_head_sha256, p_head_bytes, p_head_registry_revision, p_head_registry_updated_at,
    case when p_sequence = 1 then 'epoch_anchor' else 'epoch_head' end, p_parent_head_id, p_expected_history_path,
    p_parent_sha256, p_parent_registry_revision, p_parent_registry_updated_at,
    v_epoch.base_editor_state_hash, v_epoch.base_component_sha256, p_result_editor_state_hash, p_result_component_authority, v_actor
  ) returning * into v_head;

  update tongs.recording_revisions set history_path = p_head_path, updated_at = clock_timestamp(), updated_by = v_actor
  where id = p_revision_id and workspace_id = p_workspace_id and workpiece_id = p_workpiece_id
    and canonical_recording_id = p_canonical_recording_id and status = 'active'
    and updated_at = p_expected_revision_updated_at and history_path is not distinct from p_expected_history_path
  returning updated_at into v_committed_updated_at;
  if v_committed_updated_at is null then
    return jsonb_build_object('outcome','conflict','code','history_epoch_head_cas_conflict','terminal',true,'retryable',false);
  end if;

  insert into tongs.hammer_history_epoch_head_transitions (
    head_id, epoch_id, workspace_id, workpiece_id, canonical_recording_id, recording_revision_id, sequence,
    idempotency_key, operation_fingerprint, expected_revision_updated_at, expected_history_path,
    committed_history_path, committed_revision_updated_at, parent_head_id, parent_sha256, parent_registry_revision,
    parent_registry_updated_at, head_sha256, head_bytes, head_registry_revision, head_registry_updated_at,
    result_editor_state_hash, result_component_authority, envelope, outcome, initiated_by
  ) values (
    p_head_id, p_epoch_id, p_workspace_id, p_workpiece_id, p_canonical_recording_id, p_revision_id, p_sequence,
    p_idempotency_key, p_operation_fingerprint, p_expected_revision_updated_at, p_expected_history_path,
    p_head_path, v_committed_updated_at, p_parent_head_id, p_parent_sha256, p_parent_registry_revision,
    p_parent_registry_updated_at, p_head_sha256, p_head_bytes, p_head_registry_revision, p_head_registry_updated_at,
    p_result_editor_state_hash, p_result_component_authority, p_envelope, 'committed', v_actor
  ) returning * into v_transition;

  return jsonb_build_object('outcome','committed','epoch_id',v_head.epoch_id,'head_id',v_head.head_id,
    'sequence',v_head.sequence,'transition_id',v_transition.transition_id,'history_path',v_head.artifact_path,
    'revision_updated_at',v_committed_updated_at,'operation_fingerprint',v_transition.operation_fingerprint);
exception
  when unique_violation then
    return jsonb_build_object('outcome','conflict','code','history_epoch_head_uniqueness_conflict','terminal',true,'retryable',false);
  when foreign_key_violation or check_violation or not_null_violation or invalid_text_representation then
    return jsonb_build_object('outcome','conflict','code','history_epoch_head_constraint_conflict','terminal',true,'retryable',false);
end;
$_$;


ALTER FUNCTION "tongs"."commit_hammer_history_epoch_head"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_canonical_recording_id" "uuid", "p_revision_id" "uuid", "p_epoch_id" "uuid", "p_head_id" "uuid", "p_sequence" bigint, "p_idempotency_key" "text", "p_operation_fingerprint" "text", "p_expected_revision_updated_at" timestamp with time zone, "p_expected_history_path" "text", "p_parent_head_id" "uuid", "p_parent_sha256" "text", "p_parent_registry_revision" bigint, "p_parent_registry_updated_at" timestamp with time zone, "p_head_path" "text", "p_head_sha256" "text", "p_head_bytes" bigint, "p_head_registry_revision" bigint, "p_head_registry_updated_at" timestamp with time zone, "p_result_editor_state_hash" "text", "p_result_component_authority" "jsonb", "p_envelope" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."commit_hammer_history_epoch_head"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_canonical_recording_id" "uuid", "p_revision_id" "uuid", "p_epoch_id" "uuid", "p_head_id" "uuid", "p_sequence" bigint, "p_idempotency_key" "text", "p_operation_fingerprint" "text", "p_expected_revision_updated_at" timestamp with time zone, "p_expected_history_path" "text", "p_parent_head_id" "uuid", "p_parent_sha256" "text", "p_parent_registry_revision" bigint, "p_parent_registry_updated_at" timestamp with time zone, "p_head_path" "text", "p_head_sha256" "text", "p_head_bytes" bigint, "p_head_registry_revision" bigint, "p_head_registry_updated_at" timestamp with time zone, "p_result_editor_state_hash" "text", "p_result_component_authority" "jsonb", "p_envelope" "jsonb") IS 'Validates one staged immutable post-epoch history head and atomically records it and advances recording_revisions.history_path.';



CREATE OR REPLACE FUNCTION "tongs"."commit_hammer_history_epoch_head_with_components"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_canonical_recording_id" "uuid", "p_revision_id" "uuid", "p_epoch_id" "uuid", "p_head_id" "uuid", "p_sequence" bigint, "p_idempotency_key" "text", "p_operation_fingerprint" "text", "p_expected_revision_updated_at" timestamp with time zone, "p_expected_history_path" "text", "p_parent_head_id" "uuid", "p_parent_sha256" "text", "p_parent_bytes" bigint, "p_parent_registry_revision" bigint, "p_parent_registry_updated_at" timestamp with time zone, "p_component_changes" "jsonb", "p_head_path" "text", "p_head_sha256" "text", "p_head_bytes" bigint, "p_head_registry_revision" bigint, "p_head_registry_updated_at" timestamp with time zone, "p_head_storage_bucket" "text", "p_head_storage_key" "text", "p_result_editor_state_hash" "text", "p_result_component_authority" "jsonb", "p_envelope" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $_$
declare
  v_actor uuid := auth.uid(); v_revision tongs.recording_revisions%rowtype;
  v_existing tongs.hammer_history_epoch_head_transitions%rowtype; v_change jsonb;
  v_current tongs.workpiece_files%rowtype; v_parent tongs.workpiece_files%rowtype;
  v_result jsonb; v_code text; v_expected_path text; v_transition_id uuid; v_recorded_parent_bytes bigint;
begin
  if v_actor is null or not tongs.has_workspace_role(p_workspace_id, 'editor') then
    return jsonb_build_object('outcome','conflict','code','history_epoch_atomic_forbidden','terminal',true,'retryable',false);
  end if;
  if p_parent_bytes is null or p_parent_bytes <= 0
    or jsonb_typeof(p_component_changes) <> 'array' or jsonb_array_length(p_component_changes) = 0
    or jsonb_array_length(p_component_changes) > 5
    or (select count(distinct value->>'component') from jsonb_array_elements(p_component_changes)) <> jsonb_array_length(p_component_changes)
    or (select count(distinct value->>'path') from jsonb_array_elements(p_component_changes)) <> jsonb_array_length(p_component_changes)
    or p_head_storage_bucket <> 'forge-workpieces'
    or p_head_storage_key <> format('workpieces/%s/%s', p_workpiece_id, p_head_path) then
    return jsonb_build_object('outcome','conflict','code','history_epoch_atomic_request_invalid','terminal',true,'retryable',false);
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_workspace_id::text || ':' || p_workpiece_id::text || ':' || p_revision_id::text, 0));
  select * into v_existing from tongs.hammer_history_epoch_head_transitions
    where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and recording_revision_id=p_revision_id
      and idempotency_key=p_idempotency_key;
  if v_existing.transition_id is not null then
    select parent_bytes into v_recorded_parent_bytes from tongs.hammer_history_epoch_atomic_parent_evidence
      where transition_id=v_existing.transition_id;
    if v_existing.operation_fingerprint=p_operation_fingerprint and v_existing.head_id=p_head_id
      and v_existing.epoch_id=p_epoch_id and v_existing.sequence=p_sequence
      and v_existing.canonical_recording_id=p_canonical_recording_id
      and v_existing.expected_revision_updated_at=p_expected_revision_updated_at
      and v_existing.expected_history_path=p_expected_history_path
      and v_existing.parent_head_id is not distinct from p_parent_head_id
      and v_existing.parent_sha256=p_parent_sha256 and v_recorded_parent_bytes=p_parent_bytes
      and v_existing.parent_registry_revision=p_parent_registry_revision
      and v_existing.parent_registry_updated_at=p_parent_registry_updated_at
      and v_existing.committed_history_path=p_head_path
      and v_existing.head_sha256=p_head_sha256 and v_existing.head_bytes=p_head_bytes
      and v_existing.head_registry_revision=p_head_registry_revision
      and v_existing.head_registry_updated_at=p_head_registry_updated_at
      and v_existing.result_editor_state_hash=p_result_editor_state_hash
      and v_existing.result_component_authority=p_result_component_authority
      and v_existing.envelope->'component_changes'=p_component_changes
      and v_existing.envelope=p_envelope
    then
      return jsonb_build_object('outcome','already_committed','epoch_id',v_existing.epoch_id,'head_id',v_existing.head_id,
        'sequence',v_existing.sequence,'transition_id',v_existing.transition_id,'history_path',v_existing.committed_history_path,
        'revision_updated_at',v_existing.committed_revision_updated_at,'operation_fingerprint',v_existing.operation_fingerprint);
    end if;
    return jsonb_build_object('outcome','conflict','code','history_epoch_atomic_idempotency_conflict','terminal',true,'retryable',false);
  end if;
  select rr.* into v_revision from tongs.recording_revisions rr
    join tongs.episodes e on e.id=rr.workpiece_id and e.workspace_id=rr.workspace_id and e.active_revision_id=rr.id
    where rr.id=p_revision_id and rr.workspace_id=p_workspace_id and rr.workpiece_id=p_workpiece_id
      and rr.canonical_recording_id=p_canonical_recording_id and rr.status='active' for update of rr;
  if v_revision.id is null then return jsonb_build_object('outcome','conflict','code','history_epoch_atomic_identity_conflict','terminal',true,'retryable',false); end if;
  if v_revision.updated_at <> p_expected_revision_updated_at then return jsonb_build_object('outcome','conflict','code','history_epoch_atomic_revision_token_conflict','terminal',true,'retryable',false); end if;
  if v_revision.history_path is distinct from p_expected_history_path then return jsonb_build_object('outcome','conflict','code','history_epoch_atomic_pointer_conflict','terminal',true,'retryable',false); end if;
  if p_envelope->'component_changes' is distinct from p_component_changes then
    return jsonb_build_object('outcome','conflict','code','history_epoch_atomic_envelope_conflict','terminal',true,'retryable',false);
  end if;
  select * into v_parent from tongs.workpiece_files
    where workpiece_id=p_workpiece_id and path=p_expected_history_path for update;
  if v_parent.workpiece_id is null or v_parent.bytes<>p_parent_bytes or lower(v_parent.hash_value)<>p_parent_sha256
    or v_parent.revision<>p_parent_registry_revision or v_parent.updated_at<>p_parent_registry_updated_at
    or v_parent.content_type<>'application/json' or v_parent.hash_algo<>'sha256'
    or v_parent.storage_bucket<>'forge-workpieces'
    or v_parent.storage_key<>format('workpieces/%s/%s',p_workpiece_id,p_expected_history_path)
  then return jsonb_build_object('outcome','conflict','code','history_epoch_atomic_parent_conflict','terminal',true,'retryable',false); end if;

  begin
    perform set_config('tongs.history_atomic_registry_tokens','on',true);
    for v_change in select value from jsonb_array_elements(p_component_changes) loop
      if jsonb_typeof(v_change) <> 'object' or (select count(*) from jsonb_object_keys(v_change)) <> 4
        or not (v_change ?& array['component','path','expected','next'])
        or (v_change->>'component') not in ('audio','editorial_authority','transcript','visual_placements','visual_timeline')
        or jsonb_typeof(v_change->'expected') <> 'object' or jsonb_typeof(v_change->'next') <> 'object'
        or (select count(*) from jsonb_object_keys(v_change->'expected')) <> 6
        or not ((v_change->'expected') ?& array['sha256','bytes','revision','updated_at','storage_bucket','storage_key'])
        or (select count(*) from jsonb_object_keys(v_change->'next')) <> 6
        or not ((v_change->'next') ?& array['sha256','bytes','revision','updated_at','storage_bucket','storage_key'])
      then v_code := 'history_epoch_atomic_component_invalid'; raise exception using errcode='P0001'; end if;
      v_expected_path := case v_change->>'component'
        when 'transcript' then v_revision.revision_transcript_path
        when 'visual_timeline' then v_revision.visual_timeline_path
        when 'visual_placements' then v_revision.visual_placements_path
        when 'audio' then v_revision.audio_polish_path
        when 'editorial_authority' then v_revision.editorial_authority_path
      end;
      if v_expected_path is null or v_change->>'path' <> v_expected_path
      then v_code := 'history_epoch_atomic_component_invalid'; raise exception using errcode='P0001'; end if;
      select * into v_current from tongs.workpiece_files where workpiece_id=p_workpiece_id and path=v_change->>'path' for update;
      if v_current.workpiece_id is null
        or lower(v_current.hash_value) <> v_change#>>'{expected,sha256}' or v_current.bytes <> (v_change#>>'{expected,bytes}')::bigint
        or v_current.revision <> (v_change#>>'{expected,revision}')::bigint
        or v_current.updated_at <> (v_change#>>'{expected,updated_at}')::timestamptz
        or v_current.storage_bucket <> v_change#>>'{expected,storage_bucket}' or v_current.storage_key <> v_change#>>'{expected,storage_key}'
      then v_code := 'history_epoch_atomic_component_conflict'; raise exception using errcode='P0001'; end if;
      if v_change#>>'{next,sha256}' !~ '^[0-9a-f]{64}$' or (v_change#>>'{next,bytes}')::bigint <= 0
        or (v_change#>>'{next,revision}')::bigint <> v_current.revision + 1
        or (v_change#>>'{next,sha256}') = lower(v_current.hash_value)
        or (v_change#>>'{next,updated_at}')::timestamptz <= v_current.updated_at
        or v_change#>>'{next,storage_bucket}' <> 'forge-workpieces'
        or v_change#>>'{next,storage_key}' !~ format('^workpieces/%s/hammer/staging/history-atomic/%s/',p_workpiece_id,p_head_id)
      then v_code := 'history_epoch_atomic_component_invalid'; raise exception using errcode='P0001'; end if;
      update tongs.workpiece_files set hash_value=v_change#>>'{next,sha256}', bytes=(v_change#>>'{next,bytes}')::bigint,
        revision=(v_change#>>'{next,revision}')::bigint, updated_at=(v_change#>>'{next,updated_at}')::timestamptz,
        storage_bucket=v_change#>>'{next,storage_bucket}', storage_key=v_change#>>'{next,storage_key}',
        written_by_tool='tongs', written_by_tool_version='history-atomic-v1', written_by_lane='forge-managed'
        where workpiece_id=p_workpiece_id and path=v_change->>'path';
    end loop;
    insert into tongs.workpiece_files(workpiece_id,path,file_type,content_type,bytes,hash_algo,hash_value,storage_bucket,storage_key,written_by_tool,written_by_tool_version,written_by_lane,revision,updated_at)
      values(p_workpiece_id,p_head_path,'hammer_history_epoch_head','application/json',p_head_bytes,'sha256',p_head_sha256,
        p_head_storage_bucket,p_head_storage_key,'tongs','history-atomic-v1','forge-managed',p_head_registry_revision,p_head_registry_updated_at);
    v_result := tongs.commit_hammer_history_epoch_head(p_workspace_id,p_workpiece_id,p_canonical_recording_id,p_revision_id,
      p_epoch_id,p_head_id,p_sequence,p_idempotency_key,p_operation_fingerprint,p_expected_revision_updated_at,p_expected_history_path,
      p_parent_head_id,p_parent_sha256,p_parent_registry_revision,p_parent_registry_updated_at,p_head_path,p_head_sha256,p_head_bytes,
      p_head_registry_revision,p_head_registry_updated_at,p_result_editor_state_hash,p_result_component_authority,p_envelope);
    if v_result->>'outcome'='conflict' then v_code:=v_result->>'code'; raise exception using errcode='P0001'; end if;
    v_transition_id := (v_result->>'transition_id')::uuid;
    insert into tongs.hammer_history_epoch_atomic_parent_evidence(
      transition_id,workspace_id,workpiece_id,recording_revision_id,idempotency_key,parent_bytes
    ) values(v_transition_id,p_workspace_id,p_workpiece_id,p_revision_id,p_idempotency_key,p_parent_bytes);
    return v_result;
  exception
    when sqlstate 'P0001' then return jsonb_build_object('outcome','conflict','code',coalesce(v_code,'history_epoch_atomic_conflict'),'terminal',true,'retryable',false);
    when unique_violation then return jsonb_build_object('outcome','conflict','code','history_epoch_atomic_uniqueness_conflict','terminal',true,'retryable',false);
    when foreign_key_violation or check_violation or not_null_violation or invalid_text_representation then
      return jsonb_build_object('outcome','conflict','code','history_epoch_atomic_constraint_conflict','terminal',true,'retryable',false);
  end;
end;
$_$;


ALTER FUNCTION "tongs"."commit_hammer_history_epoch_head_with_components"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_canonical_recording_id" "uuid", "p_revision_id" "uuid", "p_epoch_id" "uuid", "p_head_id" "uuid", "p_sequence" bigint, "p_idempotency_key" "text", "p_operation_fingerprint" "text", "p_expected_revision_updated_at" timestamp with time zone, "p_expected_history_path" "text", "p_parent_head_id" "uuid", "p_parent_sha256" "text", "p_parent_bytes" bigint, "p_parent_registry_revision" bigint, "p_parent_registry_updated_at" timestamp with time zone, "p_component_changes" "jsonb", "p_head_path" "text", "p_head_sha256" "text", "p_head_bytes" bigint, "p_head_registry_revision" bigint, "p_head_registry_updated_at" timestamp with time zone, "p_head_storage_bucket" "text", "p_head_storage_key" "text", "p_result_editor_state_hash" "text", "p_result_component_authority" "jsonb", "p_envelope" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."commit_hammer_history_epoch_head_with_components"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_canonical_recording_id" "uuid", "p_revision_id" "uuid", "p_epoch_id" "uuid", "p_head_id" "uuid", "p_sequence" bigint, "p_idempotency_key" "text", "p_operation_fingerprint" "text", "p_expected_revision_updated_at" timestamp with time zone, "p_expected_history_path" "text", "p_parent_head_id" "uuid", "p_parent_sha256" "text", "p_parent_bytes" bigint, "p_parent_registry_revision" bigint, "p_parent_registry_updated_at" timestamp with time zone, "p_component_changes" "jsonb", "p_head_path" "text", "p_head_sha256" "text", "p_head_bytes" bigint, "p_head_registry_revision" bigint, "p_head_registry_updated_at" timestamp with time zone, "p_head_storage_bucket" "text", "p_head_storage_key" "text", "p_result_editor_state_hash" "text", "p_result_component_authority" "jsonb", "p_envelope" "jsonb") IS 'Atomically installs changed component authority and an immutable history head, including exact parent byte evidence.';



CREATE OR REPLACE FUNCTION "tongs"."commit_hammer_video_master"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_attempt_id" "uuid", "p_path" "text", "p_mime_type" "text", "p_byte_size" bigint, "p_content_hash" "text", "p_storage_bucket" "text", "p_storage_key" "text", "p_duration_ms" bigint, "p_width" integer, "p_height" integer, "p_fps" numeric, "p_render_evidence" "jsonb", "p_acknowledged_result_fingerprint" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $_$
declare op tongs.hammer_video_render_operations%rowtype; a tongs.assets%rowtype; receipt jsonb;
begin
  if auth.role()<>'service_role' then raise exception 'Hammer video master commit requires service authority' using errcode='42501'; end if;
  select * into op from tongs.hammer_video_render_operations where operation_id=p_operation_id for update;
  if not found then return jsonb_build_object('disposition','operation_not_found'); end if;
  if op.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict'); end if;
  if op.state='completed' then return op.receipt_json; end if;
  if op.state<>'rendering' or not exists(select 1 from tongs.hammer_video_render_attempts where attempt_id=p_attempt_id and operation_id=p_operation_id and state in('reserved','running')) then return jsonb_build_object('disposition','operation_not_committable','state',op.state); end if;
  if p_mime_type not like'video/%' or p_byte_size<=0 or p_duration_ms<=0 or p_width<=0 or p_height<=0 or p_fps<=0 or p_content_hash!~'^[0-9a-f]{64}$' or coalesce(p_acknowledged_result_fingerprint,'')='' then return jsonb_build_object('disposition','invalid_verified_video_evidence'); end if;
  select * into a from tongs.assets where operation_id=p_operation_id and asset_kind='hammer_video_master' for update;
  if found then
    if a.operation_fingerprint<>p_operation_fingerprint or a.content_hash<>p_content_hash or a.storage_bucket<>p_storage_bucket or a.storage_key<>p_storage_key or a.bytes<>p_byte_size then return jsonb_build_object('disposition','asset_replay_conflict'); end if;
  else
    insert into tongs.assets(workspace_id,workpiece_id,asset_scope,path,mime_type,bytes,storage_bucket,storage_key,provider,request_id,created_by,asset_kind,status,metadata_json,operation_id,operation_fingerprint,content_hash,provenance_classification,provenance_json,ready_at)
    values(op.workspace_id,op.workpiece_id,'workpiece',p_path,p_mime_type,p_byte_size,p_storage_bucket,p_storage_key,'hammer-video-renderer',p_operation_id,op.created_by,'hammer_video_master','ready',jsonb_build_object('duration_ms',p_duration_ms,'width',p_width,'height',p_height,'fps',p_fps,'recording_revision_id',op.recording_revision_id,'composition_revision',op.composition_revision,'composition_fingerprint',op.composition_fingerprint,'render_plan_fingerprint',op.render_plan_fingerprint,'background_effect_fingerprint',op.background_effect_fingerprint,'audio_master_asset_id',op.audio_master_asset_id,'replacement_asset_id',op.replacement_asset_id,'renderer_version',op.renderer_version,'output_profile_id',op.output_profile_id),p_operation_id,p_operation_fingerprint,p_content_hash,'canonical_native',coalesce(p_render_evidence,'{}'::jsonb),now()) returning * into a;
  end if;
  receipt:=jsonb_build_object('disposition','committed','operation_id',op.operation_id,'operation_fingerprint',op.operation_fingerprint,'attempt_id',p_attempt_id,'asset',to_jsonb(a),'render_evidence',p_render_evidence,'acknowledged_result_fingerprint',p_acknowledged_result_fingerprint);
  update tongs.hammer_video_render_attempts set state='completed',progress=1,provider_evidence_json=p_render_evidence,updated_at=now() where attempt_id=p_attempt_id;
  update tongs.hammer_video_render_operations set state='completed',output_asset_id=a.id,acknowledged_result_fingerprint=p_acknowledged_result_fingerprint,render_evidence_json=p_render_evidence,receipt_json=receipt,failure_code=null,failure_message=null,updated_at=now() where operation_id=p_operation_id;
  return receipt;
end$_$;


ALTER FUNCTION "tongs"."commit_hammer_video_master"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_attempt_id" "uuid", "p_path" "text", "p_mime_type" "text", "p_byte_size" bigint, "p_content_hash" "text", "p_storage_bucket" "text", "p_storage_key" "text", "p_duration_ms" bigint, "p_width" integer, "p_height" integer, "p_fps" numeric, "p_render_evidence" "jsonb", "p_acknowledged_result_fingerprint" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."commit_hearth_editorial_preflight_v1"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_expected_revision" bigint, "p_expected_revision_id" "uuid", "p_expected_source_file_revision" bigint, "p_expected_script_hash" "text", "p_script_text" "text", "p_research_artifact_id" "uuid", "p_research_artifact_hash" "text", "p_checker_contract_version" "text", "p_report_json" "jsonb", "p_operation_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare v_user uuid:=auth.uid();v_file tongs.workpiece_files%rowtype;v_research tongs.hearth_research_artifact_revisions%rowtype;
 v_seq tongs.workpiece_hearth_preflight_sequences%rowtype;v_review tongs.hearth_script_review_revisions%rowtype;v_report tongs.hearth_editorial_preflight_reports%rowtype;v_receipt tongs.hearth_preflight_operation_receipts%rowtype;
 v_script text;v_hash text;v_report_hash text;v_projection_hash text;v_immutable text;v_fingerprint text;v_result jsonb;v_item jsonb;v_ordinal int:=0;
begin
 if v_user is null or not tongs.has_workspace_role(p_workspace_id,'editor') then return jsonb_build_object('disposition','denied','reason','editor_required');end if;
 if p_report_json->>'schema'<>'forge.hearth.editorial-preflight.v1' or jsonb_typeof(p_report_json->'findings')<>'array' then return jsonb_build_object('disposition','invalid','reason','report_contract_invalid');end if;
 select * into v_file from tongs.workpiece_files where workpiece_id=p_workpiece_id and path='script/script.md' for share;
 if not found or v_file.revision<>p_expected_source_file_revision or lower(v_file.hash_value)<>lower(p_expected_script_hash) then return jsonb_build_object('disposition','stale','reason','script_source_changed');end if;
 v_script:=tongs.normalize_script_approval_text(p_script_text);v_hash:=encode(extensions.digest(convert_to(v_script,'UTF8'),'sha256'),'hex');
 if v_hash<>lower(p_expected_script_hash) then return jsonb_build_object('disposition','stale','reason','script_bytes_changed');end if;
 if p_research_artifact_id is not null then
   select r.* into v_research from tongs.hearth_research_artifact_revisions r join tongs.workpiece_hearth_research_sequences s on s.current_artifact_id=r.id where r.id=p_research_artifact_id and r.workspace_id=p_workspace_id and r.workpiece_id=p_workpiece_id;
   if not found or v_research.artifact_content_hash<>lower(p_research_artifact_hash) then return jsonb_build_object('disposition','stale','reason','research_artifact_changed');end if;
 end if;
 v_report_hash:=encode(extensions.digest(convert_to(p_report_json::text,'UTF8'),'sha256'),'hex');
 v_projection_hash:=encode(extensions.digest(convert_to(coalesce(p_report_json->'findings','[]'::jsonb)::text,'UTF8'),'sha256'),'hex');
 v_fingerprint:=encode(extensions.digest(convert_to(jsonb_build_object('workspace_id',p_workspace_id,'workpiece_id',p_workpiece_id,'source_revision',p_expected_source_file_revision,'script_hash',v_hash,'research_id',p_research_artifact_id,'research_hash',p_research_artifact_hash,'checker',p_checker_contract_version,'report_hash',v_report_hash)::text,'UTF8'),'sha256'),'hex');
 select * into v_receipt from tongs.hearth_preflight_operation_receipts where operation_id=p_operation_id;
 if found then if v_receipt.operation_fingerprint<>v_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict');end if;return v_receipt.immutable_result_json;end if;
 insert into tongs.workpiece_hearth_preflight_sequences(workspace_id,workpiece_id) values(p_workspace_id,p_workpiece_id) on conflict do nothing;
 select * into v_seq from tongs.workpiece_hearth_preflight_sequences where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id for update;
 if v_seq.current_revision<>p_expected_revision or v_seq.current_report_id is distinct from p_expected_revision_id then return jsonb_build_object('disposition','revision_conflict','current_revision',v_seq.current_revision,'current_report_id',v_seq.current_report_id);end if;
 select * into v_review from tongs.hearth_script_review_revisions where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and source_file_revision=p_expected_source_file_revision and script_content_hash=v_hash;
 if not found then
   insert into tongs.hearth_script_review_revisions(workspace_id,workpiece_id,source_file_path,source_file_revision,script_content_hash,script_text,snapshot_content_hash,created_by)
   values(p_workspace_id,p_workpiece_id,'script/script.md',p_expected_source_file_revision,v_hash,v_script,encode(extensions.digest(convert_to(jsonb_build_object('workpiece_id',p_workpiece_id,'source_revision',p_expected_source_file_revision,'script_hash',v_hash)::text,'UTF8'),'sha256'),'hex'),v_user)
   returning * into v_review;
 end if;
 v_immutable:=encode(extensions.digest(convert_to(jsonb_build_object('report_hash',v_report_hash,'revision',v_seq.current_revision+1,'previous_revision_id',v_seq.current_report_id,'script_review_revision_id',v_review.id,'operation_id',p_operation_id)::text,'UTF8'),'sha256'),'hex');
 insert into tongs.hearth_editorial_preflight_reports(workspace_id,workpiece_id,revision,previous_revision_id,previous_revision,script_review_revision_id,source_file_path,source_file_revision,script_content_hash,research_artifact_id,research_artifact_revision,research_artifact_hash,checker_contract_version,report_json,report_content_hash,projection_content_hash,immutable_revision_hash,created_by)
 values(p_workspace_id,p_workpiece_id,v_seq.current_revision+1,v_seq.current_report_id,nullif(v_seq.current_revision,0),v_review.id,'script/script.md',p_expected_source_file_revision,v_hash,v_research.id,v_research.revision,v_research.artifact_content_hash,p_checker_contract_version,p_report_json,v_report_hash,v_projection_hash,v_immutable,v_user) returning * into v_report;
 for v_item in select value from jsonb_array_elements(p_report_json->'findings') loop
   insert into tongs.hearth_editorial_preflight_findings values(v_report.id,p_workspace_id,p_workpiece_id,v_report.revision,v_ordinal,coalesce(nullif(v_item->>'id',''),'finding-'||v_ordinal),coalesce(nullif(v_item->>'code',''),'unknown'),coalesce(nullif(v_item->>'severity',''),'warning'),coalesce(nullif(v_item->>'category',''),'editorial'),coalesce(nullif(v_item->>'message',''),'Unspecified producer finding.'),v_item,encode(extensions.digest(convert_to(v_item::text,'UTF8'),'sha256'),'hex'));
   v_ordinal:=v_ordinal+1;
 end loop;
 update tongs.workpiece_hearth_preflight_sequences set current_report_id=v_report.id,current_revision=v_report.revision,updated_at=now() where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id;
 v_result:=jsonb_build_object('disposition','committed','report',to_jsonb(v_report),'findings',p_report_json->'findings');
 insert into tongs.hearth_preflight_operation_receipts values(p_operation_id,v_fingerprint,p_workspace_id,p_workpiece_id,v_report.id,v_report.revision,v_result,v_user,now());
 return v_result;
exception when invalid_text_representation or not_null_violation or check_violation then return jsonb_build_object('disposition','invalid','reason','preflight_projection_invalid');
end;$$;


ALTER FUNCTION "tongs"."commit_hearth_editorial_preflight_v1"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_expected_revision" bigint, "p_expected_revision_id" "uuid", "p_expected_source_file_revision" bigint, "p_expected_script_hash" "text", "p_script_text" "text", "p_research_artifact_id" "uuid", "p_research_artifact_hash" "text", "p_checker_contract_version" "text", "p_report_json" "jsonb", "p_operation_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."commit_hearth_research_artifact_v1"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_expected_revision" bigint, "p_expected_revision_id" "uuid", "p_artifact_json" "jsonb", "p_contract_version" "text", "p_operation_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare
  v_user uuid := auth.uid(); v_seq tongs.workpiece_hearth_research_sequences%rowtype;
  v_row tongs.hearth_research_artifact_revisions%rowtype; v_receipt tongs.hearth_research_operation_receipts%rowtype;
  v_hash text;v_projection_hash text;v_immutable text;v_fingerprint text;v_status text;v_brief text;v_result jsonb;
  v_item jsonb;v_ordinal int:=0;v_claim_key text;v_source_ids text[];v_evidence record;
begin
  if v_user is null or not tongs.has_workspace_role(p_workspace_id,'editor') then return jsonb_build_object('disposition','denied','reason','editor_required');end if;
  if not exists(select 1 from tongs.episodes where id=p_workpiece_id and workspace_id=p_workspace_id) then return jsonb_build_object('disposition','not_found','reason','episode_membership_invalid');end if;
  if p_artifact_json->>'schema'<>'forge.hearth.research-artifact.v1' or jsonb_typeof(p_artifact_json->'result')<>'object' then return jsonb_build_object('disposition','invalid','reason','artifact_contract_invalid');end if;
  v_status:=p_artifact_json#>>'{result,artifact,status}';
  if v_status not in ('complete','partial') then return jsonb_build_object('disposition','invalid','reason','only_substantive_artifacts_are_canonical');end if;
  if p_artifact_json#>>'{result,artifact,workpieceId}' is distinct from p_workpiece_id::text then return jsonb_build_object('disposition','invalid','reason','workpiece_identity_mismatch');end if;
  v_brief:=coalesce(p_artifact_json#>>'{result,brief,briefFingerprint}',p_artifact_json#>>'{result,artifact,briefFingerprint}','');
  if length(v_brief)<8 then return jsonb_build_object('disposition','invalid','reason','brief_fingerprint_required');end if;
  v_hash:=encode(extensions.digest(convert_to(p_artifact_json::text,'UTF8'),'sha256'),'hex');
  v_projection_hash:=encode(extensions.digest(convert_to(jsonb_build_object('claims',coalesce(p_artifact_json#>'{result,creatorClaims}','[]'::jsonb),'findings',coalesce(p_artifact_json#>'{result,artifact,findings}','[]'::jsonb),'evidence',coalesce(p_artifact_json#>'{result,evidence}','[]'::jsonb))::text,'UTF8'),'sha256'),'hex');
  v_fingerprint:=encode(extensions.digest(convert_to(jsonb_build_object('workspace_id',p_workspace_id,'workpiece_id',p_workpiece_id,'expected_revision',p_expected_revision,'expected_revision_id',p_expected_revision_id,'artifact_hash',v_hash,'contract_version',p_contract_version)::text,'UTF8'),'sha256'),'hex');
  select * into v_receipt from tongs.hearth_research_operation_receipts where operation_id=p_operation_id;
  if found then if v_receipt.operation_fingerprint<>v_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict');end if;return v_receipt.immutable_result_json;end if;
  insert into tongs.workpiece_hearth_research_sequences(workspace_id,workpiece_id) values(p_workspace_id,p_workpiece_id) on conflict do nothing;
  select * into v_seq from tongs.workpiece_hearth_research_sequences where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id for update;
  if v_seq.current_revision<>p_expected_revision or v_seq.current_artifact_id is distinct from p_expected_revision_id then return jsonb_build_object('disposition','revision_conflict','current_revision',v_seq.current_revision,'current_artifact_id',v_seq.current_artifact_id);end if;
  if v_seq.current_artifact_id is not null and exists(select 1 from tongs.hearth_research_artifact_revisions where id=v_seq.current_artifact_id and artifact_content_hash=v_hash) then
    select * into v_row from tongs.hearth_research_artifact_revisions where id=v_seq.current_artifact_id;
    v_result:=jsonb_build_object('disposition','no_change','artifact',to_jsonb(v_row));
  else
    v_immutable:=encode(extensions.digest(convert_to(jsonb_build_object('artifact_hash',v_hash,'revision',v_seq.current_revision+1,'previous_revision_id',v_seq.current_artifact_id,'operation_id',p_operation_id)::text,'UTF8'),'sha256'),'hex');
    insert into tongs.hearth_research_artifact_revisions(workspace_id,workpiece_id,revision,previous_revision_id,previous_revision,brief_fingerprint,artifact_status,artifact_json,artifact_content_hash,projection_content_hash,immutable_revision_hash,contract_version,committed_by)
    values(p_workspace_id,p_workpiece_id,v_seq.current_revision+1,v_seq.current_artifact_id,nullif(v_seq.current_revision,0),v_brief,v_status,p_artifact_json,v_hash,v_projection_hash,v_immutable,p_contract_version,v_user) returning * into v_row;
    for v_item in select value from jsonb_array_elements(coalesce(p_artifact_json#>'{result,creatorClaims}','[]'::jsonb)) loop
      v_claim_key:=coalesce(nullif(v_item->>'claimId',''),'creator-'||v_ordinal::text);
      v_source_ids:=array(select jsonb_array_elements_text(coalesce(v_item->'sourceIds','[]'::jsonb)));
      insert into tongs.hearth_research_artifact_claims values(v_row.id,p_workspace_id,p_workpiece_id,v_row.revision,v_ordinal,v_claim_key,v_item->>'text',v_item->>'claimKind',coalesce(v_item->>'provenanceStatus','creator_supplied_unverified'),coalesce(v_item->>'scope','current_subject'),v_source_ids,v_item->'entityLead',encode(extensions.digest(convert_to(v_item::text,'UTF8'),'sha256'),'hex'));
      v_ordinal:=v_ordinal+1;
    end loop;
    for v_item in select value from jsonb_array_elements(coalesce(p_artifact_json#>'{result,artifact,findings}','[]'::jsonb)) loop
      v_claim_key:='finding-'||v_ordinal::text;
      v_source_ids:=array(select jsonb_array_elements_text(coalesce(v_item->'sourceIds','[]'::jsonb)));
      insert into tongs.hearth_research_artifact_claims values(v_row.id,p_workspace_id,p_workpiece_id,v_row.revision,v_ordinal,v_claim_key,v_item->>'text',null,case v_item->>'status' when 'verified_fact' then 'verified_by_current_run' when 'reported_claim' then 'reported_by_accessible_secondary' when 'editorial_interpretation' then 'opinion_interpretation' else coalesce(v_item->>'provenanceStatus','uncertain') end,coalesce(v_item->>'scope','current_subject'),v_source_ids,jsonb_strip_nulls(jsonb_build_object('name',v_item->>'businessName','entityRole',v_item->>'entityRole','businessStatus',v_item->>'businessStatus')),encode(extensions.digest(convert_to(v_item::text,'UTF8'),'sha256'),'hex'));
      v_ordinal:=v_ordinal+1;
    end loop;
    v_ordinal:=0;
    for v_item in select value from jsonb_array_elements(coalesce(p_artifact_json#>'{result,evidence}','[]'::jsonb)) loop
      if length(coalesce(v_item->>'excerpt',''))>8192 then return jsonb_build_object('disposition','invalid','reason','evidence_excerpt_too_large');end if;
      insert into tongs.hearth_research_evidence_snapshots(artifact_id,workspace_id,workpiece_id,artifact_revision,ordinal,evidence_key,source_id,evidence_state,authority,access_failure_reason,citation_json,excerpt,inspected_at,content_hash)
      values(v_row.id,p_workspace_id,p_workpiece_id,v_row.revision,v_ordinal,coalesce(nullif(v_item->>'evidenceId',''),'evidence-'||v_ordinal),v_item->>'sourceId',coalesce(v_item->>'state','inaccessible'),coalesce(v_item->>'authority','unassessed'),null,jsonb_build_object('sourceId',v_item->>'sourceId'),v_item->>'excerpt',null,encode(extensions.digest(convert_to(v_item::text,'UTF8'),'sha256'),'hex'));
      v_ordinal:=v_ordinal+1;
    end loop;
    for v_item in select to_jsonb(c) from tongs.hearth_research_artifact_claims c where c.artifact_id=v_row.id loop
      for v_evidence in select e.ordinal,e.source_id,e.evidence_state from tongs.hearth_research_evidence_snapshots e where e.artifact_id=v_row.id and e.source_id=any(array(select jsonb_array_elements_text(v_item->'source_ids'))) loop
        insert into tongs.hearth_research_claim_evidence values(v_row.id,(v_item->>'ordinal')::int,v_evidence.ordinal,p_workspace_id,p_workpiece_id,case when v_evidence.evidence_state='inaccessible' then 'inaccessible_only' when v_item->>'provenance_status'='conflicting' then 'conflicts' when v_item->>'provenance_status'='reported_by_accessible_secondary' then 'reports' else 'supports' end);
      end loop;
    end loop;
    update tongs.workpiece_hearth_research_sequences set current_artifact_id=v_row.id,current_revision=v_row.revision,updated_at=now() where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id;
    v_result:=jsonb_build_object('disposition','committed','artifact',to_jsonb(v_row));
  end if;
  insert into tongs.hearth_research_operation_receipts values(p_operation_id,v_fingerprint,p_workspace_id,p_workpiece_id,v_row.id,v_row.revision,v_result,v_user,now());
  return v_result;
exception when invalid_text_representation or not_null_violation or check_violation then return jsonb_build_object('disposition','invalid','reason','artifact_projection_invalid');
end;$$;


ALTER FUNCTION "tongs"."commit_hearth_research_artifact_v1"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_expected_revision" bigint, "p_expected_revision_id" "uuid", "p_artifact_json" "jsonb", "p_contract_version" "text", "p_operation_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."commit_image_map_revision"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_expected_current_revision" bigint, "p_expected_current_revision_id" "uuid", "p_target_script_approval_id" "uuid", "p_anchor_contract_version" "text", "p_document_json" "jsonb", "p_mutation_kind" "text", "p_affected_entry_ids" "text"[], "p_normalized_mutation_inputs" "jsonb", "p_operation_contract_version" "text", "p_operation_id" "text", "p_actor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare
  v_sequence tongs.workpiece_image_map_sequences%rowtype;
  v_approval_sequence tongs.workpiece_script_approval_sequences%rowtype;
  v_approval tongs.script_approval_revisions%rowtype;
  v_current tongs.image_map_revisions%rowtype;
  v_revision tongs.image_map_revisions%rowtype;
  v_receipt tongs.hearth_authority_operation_receipts%rowtype;
  v_provenance text;
  v_document_hash text;
  v_semantic_hash text;
  v_revision_hash text;
  v_fingerprint text;
  v_result jsonb;
  v_next bigint;
begin
  if p_actor_id is null then
    raise exception 'actor is required' using errcode='22023';
  end if;
  if p_mutation_kind not in ('commit_image_map','repair_to_approved_script','resolve_manual_anchor','reapply_visual_plan','regenerate_from_approved_script') then
    raise exception 'invalid image-map mutation kind' using errcode='22023';
  end if;
  v_provenance := tongs.image_map_plan_provenance(p_document_json);
  v_document_hash := encode(extensions.digest(convert_to(p_document_json::text,'UTF8'),'sha256'),'hex');

  select * into v_approval_sequence from tongs.workpiece_script_approval_sequences
    where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id for share;
  if p_target_script_approval_id is not null then
    if not found or v_approval_sequence.current_approval_id is distinct from p_target_script_approval_id then
      return jsonb_build_object('disposition','script_revision_conflict');
    end if;
    select * into v_approval from tongs.script_approval_revisions
      where id=p_target_script_approval_id and workspace_id=p_workspace_id and workpiece_id=p_workpiece_id;
    if not found then return jsonb_build_object('disposition','canonical_approval_required'); end if;
  elsif v_provenance <> 'provenance_unknown' then
    return jsonb_build_object('disposition','canonical_approval_required');
  end if;

  v_semantic_hash := encode(extensions.digest(convert_to(jsonb_build_object(
    'workspace_id',p_workspace_id,'workpiece_id',p_workpiece_id,
    'source_script_approval_id',v_approval.id,'source_script_hash',v_approval.script_content_hash,
    'anchor_contract_version',p_anchor_contract_version,'provenance_state',v_provenance,
    'document_content_hash',v_document_hash,'document',p_document_json
  )::text,'UTF8'),'sha256'),'hex');
  v_fingerprint := encode(extensions.digest(convert_to(jsonb_build_object(
    'contract',p_operation_contract_version,'workspace_id',p_workspace_id,'workpiece_id',p_workpiece_id,
    'mutation_kind',p_mutation_kind,'source_revision_id',p_expected_current_revision_id,
    'source_revision',p_expected_current_revision,'target_approval_id',v_approval.id,
    'target_script_hash',v_approval.script_content_hash,
    'affected_entry_ids',to_jsonb((select array_agg(x order by x) from unnest(coalesce(p_affected_entry_ids,array[]::text[])) x)),
    'normalized_inputs',coalesce(p_normalized_mutation_inputs,'{}'::jsonb)
  )::text,'UTF8'),'sha256'),'hex');

  select * into v_receipt from tongs.hearth_authority_operation_receipts where operation_id=p_operation_id;
  if found then
    if v_receipt.operation_fingerprint <> v_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict'); end if;
    return v_receipt.immutable_result_json;
  end if;

  insert into tongs.workpiece_image_map_sequences(workspace_id,workpiece_id)
  values(p_workspace_id,p_workpiece_id) on conflict do nothing;
  select * into v_sequence from tongs.workpiece_image_map_sequences
    where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id for update;
  if v_sequence.current_revision <> p_expected_current_revision
    or v_sequence.current_revision_id is distinct from p_expected_current_revision_id then
    return jsonb_build_object('disposition','revision_conflict','current_revision',v_sequence.current_revision,'current_revision_id',v_sequence.current_revision_id);
  end if;
  if v_sequence.current_revision_id is not null then
    select * into v_current from tongs.image_map_revisions where id=v_sequence.current_revision_id;
    if v_current.semantic_state_hash=v_semantic_hash then
      v_result := jsonb_build_object('disposition','no_change','image_map_revision',to_jsonb(v_current));
      insert into tongs.hearth_authority_operation_receipts(
        operation_id,operation_fingerprint,workspace_id,workpiece_id,mutation_kind,
        source_image_map_revision_id,source_image_map_revision,target_script_approval_id,target_script_approval_revision,
        result_image_map_revision_id,result_image_map_revision,immutable_result_json,created_by
      ) values(p_operation_id,v_fingerprint,p_workspace_id,p_workpiece_id,p_mutation_kind,
        case when p_mutation_kind='commit_image_map' then null else v_current.id end,
        case when p_mutation_kind='commit_image_map' then null else v_current.revision end,
        v_approval.id,v_approval.approval_revision,v_current.id,v_current.revision,v_result,
        p_actor_id);
      return v_result;
    end if;
  end if;
  v_next := v_sequence.current_revision+1;
  v_revision_hash := encode(extensions.digest(convert_to(jsonb_build_object(
    'semantic_state_hash',v_semantic_hash,'revision',v_next,'previous_revision_id',v_sequence.current_revision_id,
    'created_at',clock_timestamp()::text,'operation_id',p_operation_id
  )::text,'UTF8'),'sha256'),'hex');
  insert into tongs.image_map_revisions(
    workspace_id,workpiece_id,revision,previous_revision_id,previous_revision,
    source_script_approval_id,source_script_approval_revision,source_script_content_hash,
    anchor_contract_version,provenance_state,document_json,document_content_hash,
    semantic_state_hash,immutable_revision_hash,created_by
  ) values(p_workspace_id,p_workpiece_id,v_next,v_sequence.current_revision_id,
    case when v_sequence.current_revision=0 then null else v_sequence.current_revision end,
    v_approval.id,v_approval.approval_revision,v_approval.script_content_hash,
    p_anchor_contract_version,v_provenance,p_document_json,v_document_hash,v_semantic_hash,v_revision_hash,
    p_actor_id) returning * into v_revision;
  update tongs.workpiece_image_map_sequences set current_revision_id=v_revision.id,current_revision=v_revision.revision,updated_at=now()
    where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id;
  v_result := jsonb_build_object('disposition','committed','image_map_revision',to_jsonb(v_revision));
  insert into tongs.hearth_authority_operation_receipts(
    operation_id,operation_fingerprint,workspace_id,workpiece_id,mutation_kind,
    source_image_map_revision_id,source_image_map_revision,target_script_approval_id,target_script_approval_revision,
    result_image_map_revision_id,result_image_map_revision,immutable_result_json,created_by
  ) values(p_operation_id,v_fingerprint,p_workspace_id,p_workpiece_id,p_mutation_kind,
    case when p_mutation_kind='commit_image_map' then null else v_sequence.current_revision_id end,
    case when p_mutation_kind='commit_image_map' then null else nullif(v_sequence.current_revision,0) end,
    v_approval.id,v_approval.approval_revision,v_revision.id,v_revision.revision,v_result,v_revision.created_by);
  return v_result;
end
$$;


ALTER FUNCTION "tongs"."commit_image_map_revision"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_expected_current_revision" bigint, "p_expected_current_revision_id" "uuid", "p_target_script_approval_id" "uuid", "p_anchor_contract_version" "text", "p_document_json" "jsonb", "p_mutation_kind" "text", "p_affected_entry_ids" "text"[], "p_normalized_mutation_inputs" "jsonb", "p_operation_contract_version" "text", "p_operation_id" "text", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."commit_image_prompt_creator_edit"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_image_moment_id" "text", "p_expected_prompt_revision_id" "uuid", "p_expected_prompt_revision" bigint, "p_final_prompt" "text", "p_operation_id" "text", "p_operation_fingerprint" "text", "p_actor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare v_seq tongs.image_map_prompt_sequences%rowtype; v_current tongs.image_map_prompt_revisions%rowtype; v_rev tongs.image_map_prompt_revisions%rowtype; v_op tongs.image_map_prompt_operation_receipts%rowtype; v_hash text; v_immutable text; v_receipt jsonb;
begin
  if not tongs.has_workspace_role(p_workspace_id,'editor') then raise exception 'workspace editor authority required' using errcode='42501'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_operation_id,0));
  select * into v_op from tongs.image_map_prompt_operation_receipts where operation_id=p_operation_id for update;
  if found then if v_op.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict'); end if; return v_op.receipt_json; end if;
  select * into v_seq from tongs.image_map_prompt_sequences where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and image_moment_id=p_image_moment_id for update;
  if not found or v_seq.current_prompt_revision_id is distinct from p_expected_prompt_revision_id or v_seq.current_prompt_revision<>p_expected_prompt_revision then return jsonb_build_object('disposition','prompt_revision_conflict','current_prompt_revision_id',v_seq.current_prompt_revision_id,'current_prompt_revision',v_seq.current_prompt_revision); end if;
  select * into v_current from tongs.image_map_prompt_revisions where id=v_seq.current_prompt_revision_id;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('prior_content_hash',v_current.content_hash,'final_prompt',p_final_prompt,'prompt_source','creator_edited')::text,'UTF8'),'sha256'),'hex');
  v_immutable:=encode(extensions.digest(convert_to(jsonb_build_object('content_hash',v_hash,'operation_id',p_operation_id,'revision',v_current.revision+1,'previous_revision_id',v_current.id)::text,'UTF8'),'sha256'),'hex');
  insert into tongs.image_map_prompt_revisions(workspace_id,workpiece_id,image_moment_id,image_map_revision_id,image_map_revision,script_approval_id,script_approval_revision,revision,previous_revision_id,previous_revision,source_context_json,creator_direction,interpretation_contract_version,validator_version,synthesis_contract_version,interpretation_model,interpretation_request_json,interpretation_response_json,visual_brief_json,ai_synthesized_prompt,final_prompt,prompt_source,content_hash,immutable_revision_hash,created_by)
  select workspace_id,workpiece_id,image_moment_id,image_map_revision_id,image_map_revision,script_approval_id,script_approval_revision,revision+1,id,revision,source_context_json,creator_direction,interpretation_contract_version,validator_version,synthesis_contract_version,interpretation_model,interpretation_request_json,interpretation_response_json,visual_brief_json,ai_synthesized_prompt,p_final_prompt,'creator_edited',v_hash,v_immutable,p_actor_id from tongs.image_map_prompt_revisions where id=v_current.id returning * into v_rev;
  update tongs.image_map_prompt_sequences set current_prompt_revision_id=v_rev.id,current_prompt_revision=v_rev.revision,updated_at=now() where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and image_moment_id=p_image_moment_id;
  v_receipt:=jsonb_build_object('disposition','committed','prompt_revision',to_jsonb(v_rev));
  insert into tongs.image_map_prompt_operation_receipts(operation_id,operation_fingerprint,operation_type,state,workspace_id,workpiece_id,image_moment_id,image_map_revision_id,image_map_revision,script_approval_id,script_approval_revision,expected_prompt_revision_id,expected_prompt_revision,normalized_inputs_json,result_revision_id,result_revision,receipt_json,created_by)
  values(p_operation_id,p_operation_fingerprint,'creator_edit','committed',p_workspace_id,p_workpiece_id,p_image_moment_id,v_current.image_map_revision_id,v_current.image_map_revision,v_current.script_approval_id,v_current.script_approval_revision,v_current.id,v_current.revision,jsonb_build_object('final_prompt',p_final_prompt),v_rev.id,v_rev.revision,v_receipt,p_actor_id);
  return v_receipt;
end $$;


ALTER FUNCTION "tongs"."commit_image_prompt_creator_edit"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_image_moment_id" "text", "p_expected_prompt_revision_id" "uuid", "p_expected_prompt_revision" bigint, "p_final_prompt" "text", "p_operation_id" "text", "p_operation_fingerprint" "text", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."commit_image_prompt_interpretation"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_visual_brief_json" "jsonb", "p_ai_synthesized_prompt" "text", "p_final_prompt" "text", "p_interpretation_contract_version" "text", "p_validator_version" "text", "p_synthesis_contract_version" "text", "p_interpretation_model" "text", "p_interpretation_request_json" "jsonb", "p_actor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare v_op tongs.image_map_prompt_operation_receipts%rowtype; v_seq tongs.image_map_prompt_sequences%rowtype; v_rev tongs.image_map_prompt_revisions%rowtype; v_missing text[]; v_content text; v_content_hash text; v_immutable_hash text; v_receipt jsonb;
begin
  select * into v_op from tongs.image_map_prompt_operation_receipts where operation_id=p_operation_id for update;
  if not found then return jsonb_build_object('disposition','operation_not_found'); end if;
  if not tongs.has_workspace_role(v_op.workspace_id,'editor') then raise exception 'workspace editor authority required' using errcode='42501'; end if;
  if v_op.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict'); end if;
  if v_op.state='committed' then return v_op.receipt_json; end if;
  if v_op.state<>'provider_completed' then return jsonb_build_object('disposition','provider_response_required','state',v_op.state); end if;
  v_missing:=tongs.validate_image_map_visual_brief(p_visual_brief_json);
  if cardinality(v_missing)>0 then return jsonb_build_object('disposition','interpretation_incomplete','invalid_fields',to_jsonb(v_missing)); end if;
  select * into v_seq from tongs.image_map_prompt_sequences where workspace_id=v_op.workspace_id and workpiece_id=v_op.workpiece_id and image_moment_id=v_op.image_moment_id for update;
  if v_seq.current_prompt_revision<>v_op.expected_prompt_revision or v_seq.current_prompt_revision_id is distinct from v_op.expected_prompt_revision_id then return jsonb_build_object('disposition','prompt_revision_conflict','current_prompt_revision_id',v_seq.current_prompt_revision_id,'current_prompt_revision',v_seq.current_prompt_revision); end if;
  v_content:=jsonb_build_object('source_context',v_op.normalized_inputs_json->'source_context','creator_direction',v_op.normalized_inputs_json->>'creator_direction','visual_brief',p_visual_brief_json,'ai_synthesized_prompt',p_ai_synthesized_prompt,'final_prompt',p_final_prompt,'prompt_source','ai_derived','contracts',jsonb_build_object('interpretation',p_interpretation_contract_version,'validator',p_validator_version,'synthesis',p_synthesis_contract_version))::text;
  v_content_hash:=encode(extensions.digest(convert_to(v_content,'UTF8'),'sha256'),'hex');
  v_immutable_hash:=encode(extensions.digest(convert_to(jsonb_build_object('content_hash',v_content_hash,'operation_id',p_operation_id,'revision',v_seq.current_prompt_revision+1,'previous_revision_id',v_seq.current_prompt_revision_id)::text,'UTF8'),'sha256'),'hex');
  insert into tongs.image_map_prompt_revisions(workspace_id,workpiece_id,image_moment_id,image_map_revision_id,image_map_revision,script_approval_id,script_approval_revision,revision,previous_revision_id,previous_revision,source_context_json,creator_direction,interpretation_contract_version,validator_version,synthesis_contract_version,interpretation_model,interpretation_request_json,interpretation_response_json,visual_brief_json,ai_synthesized_prompt,final_prompt,prompt_source,content_hash,immutable_revision_hash,created_by)
  values(v_op.workspace_id,v_op.workpiece_id,v_op.image_moment_id,v_op.image_map_revision_id,v_op.image_map_revision,v_op.script_approval_id,v_op.script_approval_revision,v_seq.current_prompt_revision+1,v_seq.current_prompt_revision_id,nullif(v_seq.current_prompt_revision,0),v_op.normalized_inputs_json->'source_context',v_op.normalized_inputs_json->>'creator_direction',p_interpretation_contract_version,p_validator_version,p_synthesis_contract_version,p_interpretation_model,p_interpretation_request_json,v_op.provider_response_json,p_visual_brief_json,p_ai_synthesized_prompt,p_final_prompt,'ai_derived',v_content_hash,v_immutable_hash,p_actor_id) returning * into v_rev;
  update tongs.image_map_prompt_sequences set current_prompt_revision_id=v_rev.id,current_prompt_revision=v_rev.revision,updated_at=now() where workspace_id=v_rev.workspace_id and workpiece_id=v_rev.workpiece_id and image_moment_id=v_rev.image_moment_id;
  v_receipt:=jsonb_build_object('disposition','committed','prompt_revision',to_jsonb(v_rev),'provider_response_hash',v_op.provider_response_hash);
  update tongs.image_map_prompt_operation_receipts set state='committed',result_revision_id=v_rev.id,result_revision=v_rev.revision,receipt_json=v_receipt,failed_stage=null,failure_code=null,failure_message=null,updated_at=now() where operation_id=p_operation_id;
  return v_receipt;
end $$;


ALTER FUNCTION "tongs"."commit_image_prompt_interpretation"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_visual_brief_json" "jsonb", "p_ai_synthesized_prompt" "text", "p_final_prompt" "text", "p_interpretation_contract_version" "text", "p_validator_version" "text", "p_synthesis_contract_version" "text", "p_interpretation_model" "text", "p_interpretation_request_json" "jsonb", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."commit_operator_pricing_revision"("p_markup_rule_revision_id" "uuid", "p_policy_id" "uuid", "p_policy_code" "text", "p_scope_kind" "text", "p_provider" "text", "p_sku" "text", "p_expected_revision" integer, "p_revision_id" "uuid", "p_customer_credit_units" bigint, "p_currency" "text", "p_cost_components" "jsonb", "p_billable_failure_classes" "jsonb", "p_free_failure_classes" "jsonb", "p_included_quantity" "jsonb", "p_retention_policy" "jsonb", "p_change_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare v_actor uuid := auth.uid(); v_markup integer; v_result jsonb; v_free jsonb;
begin
  if v_actor is null or not tongs.is_platform_operator(v_actor) then
    raise exception 'platform operator required' using errcode = '42501';
  end if;
  v_markup := tongs._effective_markup_basis_points(p_markup_rule_revision_id, coalesce(p_provider,''), coalesce(p_sku,''));
  v_free := coalesce(p_free_failure_classes, '[]'::jsonb) ||
    '["forge_failure","provider_failure","provider_billed_failure","unknown_fault","prebilling_rejection","forge_validation_failure","persistence_failure"]'::jsonb;
  v_result := tongs.commit_private_pricing_revision(
    p_policy_id,p_policy_code,p_scope_kind,p_provider,p_sku,p_expected_revision,p_revision_id,
    v_markup,p_customer_credit_units,p_currency,p_cost_components,'[]'::jsonb,
    (select jsonb_agg(distinct value) from jsonb_array_elements(v_free)),
    p_included_quantity,p_retention_policy,p_change_reason
  );
  insert into tongs.private_pricing_revision_markup_sources(pricing_revision_id,markup_rule_revision_id,effective_markup_basis_points)
    values(p_revision_id,p_markup_rule_revision_id,v_markup) on conflict(pricing_revision_id) do nothing;
  return v_result || jsonb_build_object('markup_rule_revision_id',p_markup_rule_revision_id,
    'effective_markup_basis_points',v_markup,'published',false,'customer_failure_ceiling_micros',0,
    'customer_rounding_rule','cost-plus rounded upward to the next USD cent');
end $$;


ALTER FUNCTION "tongs"."commit_operator_pricing_revision"("p_markup_rule_revision_id" "uuid", "p_policy_id" "uuid", "p_policy_code" "text", "p_scope_kind" "text", "p_provider" "text", "p_sku" "text", "p_expected_revision" integer, "p_revision_id" "uuid", "p_customer_credit_units" bigint, "p_currency" "text", "p_cost_components" "jsonb", "p_billable_failure_classes" "jsonb", "p_free_failure_classes" "jsonb", "p_included_quantity" "jsonb", "p_retention_policy" "jsonb", "p_change_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."commit_private_markup_rule_revision"("p_revision_id" "uuid", "p_expected_revision" integer, "p_default_markup_basis_points" integer, "p_overrides_json" "jsonb", "p_change_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_previous tongs.private_markup_rule_revisions%rowtype;
  v_existing tongs.private_markup_rule_revisions%rowtype;
  v_revision integer;
  v_overrides jsonb := coalesce(p_overrides_json, '[]'::jsonb);
  v_reason text := nullif(btrim(coalesce(p_change_reason, '')), '');
  v_hash text;
begin
  if v_actor is null or not tongs.is_platform_operator(v_actor) then
    raise exception 'platform operator required' using errcode = '42501';
  end if;
  if p_revision_id is null or p_default_markup_basis_points is null
     or p_default_markup_basis_points < 0 or v_reason is null then
    raise exception 'invalid markup rule revision' using errcode = '22023';
  end if;
  perform tongs._validate_markup_overrides(v_overrides);
  perform pg_advisory_xact_lock(hashtextextended('private-markup-rules', 0));
  select * into v_existing from tongs.private_markup_rule_revisions where id = p_revision_id;
  if found then
    return jsonb_build_object('revision_id', v_existing.id, 'revision', v_existing.revision,
      'replay', true, 'published', false);
  end if;
  select * into v_previous from tongs.private_markup_rule_revisions order by revision desc limit 1;
  if coalesce(v_previous.revision, 0) <> coalesce(p_expected_revision, 0) then
    raise exception 'stale markup rule revision' using errcode = '40001';
  end if;
  v_revision := coalesce(v_previous.revision, 0) + 1;
  v_hash := encode(extensions.digest(convert_to(jsonb_build_object(
    'revision', v_revision,
    'default_markup_basis_points', p_default_markup_basis_points,
    'overrides', v_overrides,
    'change_reason', v_reason
  )::text, 'utf8'), 'sha256'), 'hex');
  insert into tongs.private_markup_rule_revisions(
    id, revision, previous_revision_id, default_markup_basis_points,
    overrides_json, change_reason, content_hash, actor_id
  ) values (
    p_revision_id, v_revision, v_previous.id, p_default_markup_basis_points,
    v_overrides, v_reason, v_hash, v_actor
  );
  return jsonb_build_object('revision_id', p_revision_id, 'revision', v_revision,
    'replay', false, 'published', false);
end;
$$;


ALTER FUNCTION "tongs"."commit_private_markup_rule_revision"("p_revision_id" "uuid", "p_expected_revision" integer, "p_default_markup_basis_points" integer, "p_overrides_json" "jsonb", "p_change_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."commit_private_pricing_revision"("p_policy_id" "uuid", "p_policy_code" "text", "p_scope_kind" "text", "p_provider" "text", "p_sku" "text", "p_expected_revision" integer, "p_revision_id" "uuid", "p_markup_basis_points" integer, "p_customer_credit_units" bigint, "p_currency" "text", "p_cost_components" "jsonb", "p_billable_failure_classes" "jsonb", "p_free_failure_classes" "jsonb", "p_included_quantity" "jsonb", "p_retention_policy" "jsonb", "p_change_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_policy tongs.private_pricing_policies%rowtype;
  v_existing tongs.private_pricing_revisions%rowtype;
  v_previous tongs.private_pricing_revisions%rowtype;
  v_revision integer;
  v_currency text := upper(btrim(coalesce(p_currency, '')));
  v_components jsonb := coalesce(p_cost_components, '[]'::jsonb);
  v_component jsonb;
  v_ordinal integer := 0;
  v_success numeric := 0;
  v_failure numeric := 0;
  v_success_price numeric;
  v_failure_price numeric;
  v_state text;
  v_hash text;
  v_reason text := nullif(btrim(coalesce(p_change_reason, '')), '');
begin
  if v_actor is null or not tongs.is_platform_operator(v_actor) then
    raise exception 'platform operator required' using errcode = '42501';
  end if;
  if p_policy_id is null or p_revision_id is null
     or nullif(btrim(coalesce(p_policy_code, '')), '') is null
     or p_scope_kind not in ('default', 'provider', 'sku')
     or v_currency !~ '^[A-Z]{3}$'
     or jsonb_typeof(v_components) <> 'array' or jsonb_array_length(v_components) = 0
     or jsonb_typeof(coalesce(p_billable_failure_classes, 'null'::jsonb)) <> 'array'
     or jsonb_typeof(coalesce(p_free_failure_classes, 'null'::jsonb)) <> 'array'
     or jsonb_typeof(coalesce(p_included_quantity, 'null'::jsonb)) <> 'object'
     or jsonb_typeof(coalesce(p_retention_policy, 'null'::jsonb)) <> 'object'
     or p_markup_basis_points < 0 or p_customer_credit_units < 0
     or (p_markup_basis_points is not null and p_customer_credit_units is null)
     or v_reason is null then
    raise exception 'invalid private pricing revision' using errcode = '22023';
  end if;
  if (p_scope_kind = 'default' and (nullif(btrim(coalesce(p_provider, '')), '') is not null or nullif(btrim(coalesce(p_sku, '')), '') is not null))
     or (p_scope_kind = 'provider' and (nullif(btrim(coalesce(p_provider, '')), '') is null or nullif(btrim(coalesce(p_sku, '')), '') is not null))
     or (p_scope_kind = 'sku' and (nullif(btrim(coalesce(p_provider, '')), '') is null or nullif(btrim(coalesce(p_sku, '')), '') is null)) then
    raise exception 'pricing scope does not match provider and SKU' using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('private-pricing:' || p_policy_id::text, 0));
  select * into v_policy from tongs.private_pricing_policies where id = p_policy_id;
  if not found then
    insert into tongs.private_pricing_policies(id, policy_code, scope_kind, provider, sku, created_by)
    values (p_policy_id, btrim(p_policy_code), p_scope_kind,
      nullif(lower(btrim(coalesce(p_provider, ''))), ''), nullif(lower(btrim(coalesce(p_sku, ''))), ''), v_actor)
    returning * into v_policy;
  elsif v_policy.policy_code <> btrim(p_policy_code) or v_policy.scope_kind <> p_scope_kind
     or v_policy.provider is distinct from nullif(lower(btrim(coalesce(p_provider, ''))), '')
     or v_policy.sku is distinct from nullif(lower(btrim(coalesce(p_sku, ''))), '') then
    raise exception 'pricing policy identity conflict' using errcode = '23505';
  end if;
  select * into v_existing from tongs.private_pricing_revisions where id = p_revision_id;
  if found then return jsonb_build_object('revision_id', v_existing.id, 'revision', v_existing.revision,
    'state', v_existing.lifecycle_state, 'replay', true, 'activation_enabled', false); end if;
  select * into v_previous from tongs.private_pricing_revisions
    where policy_id = p_policy_id order by revision desc limit 1;
  if coalesce(v_previous.revision, 0) <> coalesce(p_expected_revision, 0) then
    raise exception 'stale private pricing revision' using errcode = '40001';
  end if;

  for v_component in select value from jsonb_array_elements(v_components) loop
    v_ordinal := v_ordinal + 1;
    if jsonb_typeof(v_component) <> 'object'
       or nullif(btrim(coalesce(v_component->>'component_code', '')), '') is null
       or v_component->>'component_kind' not in (
         'direct_provider', 'supporting_provider', 'compute', 'storage', 'bandwidth_egress',
         'transactional_notification', 'payment_processing', 'retention_tail', 'contingency')
       or v_component->>'credential_funding' not in ('forge', 'byo_customer')
       or nullif(btrim(coalesce(v_component->>'provider_label', '')), '') is null
       or nullif(btrim(coalesce(v_component->>'cost_policy_revision', '')), '') is null
       or v_component->>'tail_policy' not in ('none', 'included_until', 'plan_funded', 'recurring_metered')
       or not (v_component ? 'success_ceiling_micros')
       or not (v_component ? 'failure_ceiling_micros') then
      raise exception 'unpriced or invalid cost component at ordinal %', v_ordinal using errcode = '22023';
    end if;
    if (v_component->>'success_ceiling_micros')::numeric < 0
       or (v_component->>'failure_ceiling_micros')::numeric < 0
       or (v_component->>'failure_ceiling_micros')::numeric > (v_component->>'success_ceiling_micros')::numeric
       or (v_component->>'credential_funding' = 'byo_customer'
         and ((v_component->>'success_ceiling_micros')::numeric <> 0
           or (v_component->>'failure_ceiling_micros')::numeric <> 0))
       or (v_component->>'tail_policy' = 'included_until'
         and nullif(v_component#>>'{tail_policy_details,included_until}', '') is null) then
      raise exception 'invalid cost ceiling, BYO cost, or tail policy at ordinal %', v_ordinal using errcode = '22023';
    end if;
    v_success := v_success + (v_component->>'success_ceiling_micros')::numeric;
    v_failure := v_failure + (v_component->>'failure_ceiling_micros')::numeric;
  end loop;
  if v_success > 9223372036854775807::numeric or v_failure > 9223372036854775807::numeric then
    raise exception 'pricing cost stack overflows bigint micros' using errcode = '22003';
  end if;
  if p_markup_basis_points is null then
    v_state := 'draft'; v_success_price := null; v_failure_price := null;
  else
    v_state := 'review_ready';
    v_success_price := ceil(v_success * (10000::numeric + p_markup_basis_points::numeric) / 10000::numeric);
    v_failure_price := ceil(v_failure * (10000::numeric + p_markup_basis_points::numeric) / 10000::numeric);
    if v_success_price > 9223372036854775807::numeric or v_failure_price > 9223372036854775807::numeric then
      raise exception 'pricing customer ceiling overflows bigint micros' using errcode = '22003';
    end if;
    if v_success_price > 0 and coalesce(p_customer_credit_units, 0) = 0 then
      raise exception 'positive customer price requires positive credit units' using errcode = '22023';
    end if;
  end if;
  v_revision := coalesce(v_previous.revision, 0) + 1;
  v_hash := encode(extensions.digest(convert_to(jsonb_build_object(
    'policy_id', p_policy_id, 'revision', v_revision, 'currency', v_currency,
    'markup_basis_points', p_markup_basis_points, 'customer_credit_units', p_customer_credit_units,
    'cost_components', v_components, 'billable_failure_classes', p_billable_failure_classes,
    'free_failure_classes', p_free_failure_classes, 'included_quantity', p_included_quantity,
    'retention_policy', p_retention_policy, 'change_reason', v_reason
  )::text, 'utf8'), 'sha256'), 'hex');
  insert into tongs.private_pricing_revisions(
    id, policy_id, revision, previous_revision_id, lifecycle_state, currency,
    markup_basis_points, full_cost_ceiling_micros, failure_cost_ceiling_micros,
    customer_price_ceiling_micros, billable_failure_ceiling_micros, customer_credit_units,
    billable_failure_classes, free_failure_classes, included_quantity, retention_policy,
    change_reason, content_hash, actor_id
  ) values (
    p_revision_id, p_policy_id, v_revision, v_previous.id, v_state, v_currency,
    p_markup_basis_points, v_success::bigint, v_failure::bigint,
    v_success_price::bigint, v_failure_price::bigint,
    case when p_markup_basis_points is null then null else p_customer_credit_units end,
    p_billable_failure_classes, p_free_failure_classes, p_included_quantity, p_retention_policy,
    v_reason, v_hash, v_actor
  );
  v_ordinal := 0;
  for v_component in select value from jsonb_array_elements(v_components) loop
    v_ordinal := v_ordinal + 1;
    insert into tongs.private_pricing_cost_components(
      pricing_revision_id, ordinal, component_code, component_kind, credential_funding,
      provider_label, success_ceiling_micros, failure_ceiling_micros, cost_policy_revision,
      tail_policy, tail_policy_details
    ) values (
      p_revision_id, v_ordinal, btrim(v_component->>'component_code'), v_component->>'component_kind',
      v_component->>'credential_funding', btrim(v_component->>'provider_label'),
      (v_component->>'success_ceiling_micros')::bigint, (v_component->>'failure_ceiling_micros')::bigint,
      btrim(v_component->>'cost_policy_revision'), v_component->>'tail_policy',
      coalesce(v_component->'tail_policy_details', '{}'::jsonb)
    );
  end loop;
  return jsonb_build_object('revision_id', p_revision_id, 'revision', v_revision, 'state', v_state,
    'activation_enabled', false, 'replay', false);
end;
$_$;


ALTER FUNCTION "tongs"."commit_private_pricing_revision"("p_policy_id" "uuid", "p_policy_code" "text", "p_scope_kind" "text", "p_provider" "text", "p_sku" "text", "p_expected_revision" integer, "p_revision_id" "uuid", "p_markup_basis_points" integer, "p_customer_credit_units" bigint, "p_currency" "text", "p_cost_components" "jsonb", "p_billable_failure_classes" "jsonb", "p_free_failure_classes" "jsonb", "p_included_quantity" "jsonb", "p_retention_policy" "jsonb", "p_change_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."commit_publishing_credential_generation"("p_credential_authority_id" "uuid", "p_expected_generation" integer, "p_encryption_key_version" "text", "p_ciphertext_version" "text", "p_encrypted_refresh_token" "text", "p_encrypted_access_token" "text", "p_access_token_expires_at" timestamp with time zone, "p_granted_scopes" "text"[], "p_provider_grant_identity_hash" "text", "p_validated_at" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $_$
declare v_authority tongs.publishing_provider_credential_authorities%rowtype; v_connection tongs.publishing_provider_connections%rowtype; v_id uuid:=gen_random_uuid(); v_generation integer;
begin
  if auth.role()<>'service_role' then raise exception 'Forbidden' using errcode='42501'; end if;
  if p_provider_grant_identity_hash!~'^[a-f0-9]{64}$' or coalesce(array_length(p_granted_scopes,1),0)=0 or btrim(coalesce(p_encrypted_refresh_token,''))='' then
    return jsonb_build_object('disposition','invalid','code','credential_evidence_incomplete');
  end if;
  select * into v_authority from tongs.publishing_provider_credential_authorities where id=p_credential_authority_id for update;
  if not found then return jsonb_build_object('disposition','blocked','code','credential_authority_missing'); end if;
  if v_authority.current_generation<>p_expected_generation then return jsonb_build_object('disposition','generation_conflict','current_generation',v_authority.current_generation); end if;
  select * into v_connection from tongs.publishing_provider_connections where id=v_authority.connection_id for update;
  if v_connection.state in('revoked','disconnected','invalid') or v_authority.state in('revoked','invalid') then
    return jsonb_build_object('disposition','blocked','code','connection_reauthorization_required');
  end if;
  if v_connection.provider_grant_subject_hash is not null and v_connection.provider_grant_subject_hash<>p_provider_grant_identity_hash then
    return jsonb_build_object('disposition','blocked','code','provider_grant_identity_conflict');
  end if;
  v_generation:=v_authority.current_generation+1;
  insert into tongs.publishing_provider_credential_generations(id,credential_authority_id,connection_id,generation,encryption_key_version,ciphertext_version,encrypted_refresh_token,encrypted_access_token,access_token_expires_at,granted_scopes,provider_grant_identity_hash,supersedes_generation_id,refreshed_at,rotated_at,validated_at)
  values(v_id,v_authority.id,v_authority.connection_id,v_generation,p_encryption_key_version,p_ciphertext_version,p_encrypted_refresh_token,nullif(btrim(coalesce(p_encrypted_access_token,'')),''),p_access_token_expires_at,p_granted_scopes,p_provider_grant_identity_hash,v_authority.current_generation_id,case when v_generation>1 then now() end,case when v_generation>1 then now() end,p_validated_at);
  update tongs.publishing_provider_credential_authorities set current_generation_id=v_id,current_generation=v_generation,state='available',updated_at=now() where id=v_authority.id;
  update tongs.publishing_provider_connections set state='active',authorization_revision=authorization_revision+case when connected_at is null then 0 else 1 end,provider_grant_subject_hash=p_provider_grant_identity_hash,granted_scopes=p_granted_scopes,connected_at=coalesce(connected_at,now()),revoked_at=null,updated_at=now() where id=v_connection.id;
  return jsonb_build_object('disposition','committed','credential_authority_id',v_authority.id,'credential_generation_id',v_id,'generation',v_generation);
end; $_$;


ALTER FUNCTION "tongs"."commit_publishing_credential_generation"("p_credential_authority_id" "uuid", "p_expected_generation" integer, "p_encryption_key_version" "text", "p_ciphertext_version" "text", "p_encrypted_refresh_token" "text", "p_encrypted_access_token" "text", "p_access_token_expires_at" timestamp with time zone, "p_granted_scopes" "text"[], "p_provider_grant_identity_hash" "text", "p_validated_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."commit_publishing_destination_capability_revision"("p_destination_id" "uuid", "p_expected_revision" integer, "p_contract_version" "text", "p_observation_source" "text", "p_capabilities" "jsonb", "p_adapter_id" "text", "p_adapter_version" "text", "p_observed_at" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs', 'extensions'
    AS $$
declare v_destination tongs.publishing_executable_destinations%rowtype; v_current tongs.publishing_destination_capability_revisions%rowtype; v_hash text; v_id uuid:=gen_random_uuid(); v_revision integer;
begin
  if auth.role()<>'service_role' then raise exception 'Forbidden' using errcode='42501'; end if;
  if p_observation_source not in('provider_api','verified_configuration') or jsonb_typeof(p_capabilities)<>'object' then return jsonb_build_object('disposition','invalid','code','invalid_capability_evidence'); end if;
  select * into v_destination from tongs.publishing_executable_destinations where id=p_destination_id for update;
  if not found then return jsonb_build_object('disposition','blocked','code','destination_missing'); end if;
  if v_destination.state <> 'active' then return jsonb_build_object('disposition','blocked','code','destination_not_active'); end if;
  select * into v_current from tongs.publishing_destination_capability_revisions where id=v_destination.current_capability_revision_id;
  if coalesce(v_current.revision,0)<>p_expected_revision then return jsonb_build_object('disposition','revision_conflict','current_revision',coalesce(v_current.revision,0)); end if;
  v_hash:=encode(extensions.digest(convert_to(p_capabilities::text,'UTF8'),'sha256'),'hex');
  if v_current.content_hash=v_hash then return jsonb_build_object('disposition','no_change','capability_revision_id',v_current.id,'revision',v_current.revision,'content_hash',v_hash); end if;
  v_revision:=coalesce(v_current.revision,0)+1;
  insert into tongs.publishing_destination_capability_revisions(id,executable_destination_id,revision,previous_revision_id,contract_version,observation_source,capabilities_json,content_hash,adapter_id,adapter_version,observed_at)
  values(v_id,p_destination_id,v_revision,v_current.id,p_contract_version,p_observation_source,p_capabilities,v_hash,p_adapter_id,p_adapter_version,p_observed_at);
  update tongs.publishing_executable_destinations set current_capability_revision_id=v_id,updated_at=now() where id=p_destination_id;
  return jsonb_build_object('disposition','committed','capability_revision_id',v_id,'revision',v_revision,'content_hash',v_hash);
end; $$;


ALTER FUNCTION "tongs"."commit_publishing_destination_capability_revision"("p_destination_id" "uuid", "p_expected_revision" integer, "p_contract_version" "text", "p_observation_source" "text", "p_capabilities" "jsonb", "p_adapter_id" "text", "p_adapter_version" "text", "p_observed_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."commit_quench_release_decision"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_destination_scope_id" "uuid", "p_expected_decision_id" "uuid", "p_expected_revision" integer, "p_decision_kind" "text", "p_intent_state" "text", "p_manifest_snapshot_id" "uuid", "p_metadata_revision" bigint, "p_metadata_hash" "text", "p_candidate_set_id" "uuid", "p_active_binding_id" "uuid", "p_capability_revision_id" "uuid", "p_assignments" "jsonb", "p_operation_id" "text", "p_operation_fingerprint" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $_$
declare v_user uuid:=auth.uid(); v_manifest_file tongs.workpiece_files%rowtype; v_metadata_file tongs.workpiece_files%rowtype; v_manifest tongs.quench_release_manifest_snapshots%rowtype;
 v_binding tongs.workpiece_brand_bindings%rowtype; v_set tongs.thumbnail_candidate_sets%rowtype; v_scope tongs.quench_destination_scopes%rowtype; v_cap tongs.quench_destination_capability_revisions%rowtype;
 v_seq tongs.quench_release_decision_sequences%rowtype; v_receipt tongs.quench_release_operation_receipts%rowtype; v_current tongs.quench_release_decision_revisions%rowtype;
 v_entry jsonb; v_candidate tongs.thumbnail_candidate_revisions%rowtype; v_asset tongs.assets%rowtype; v_id uuid:=gen_random_uuid(); v_revision int; v_ordered jsonb; v_hash text; v_result jsonb; v_count int:=0;
begin
 -- Authorization precedes every lock, receipt read, replay, and mutation.
 if v_user is null or p_workspace_id is null or not tongs.has_workspace_role(p_workspace_id,'editor') then return jsonb_build_object('disposition','denied','code','editor_required'); end if;
 if not exists(select 1 from tongs.episodes where id=p_workpiece_id and workspace_id=p_workspace_id) then return jsonb_build_object('disposition','denied','code','workspace_workpiece_mismatch'); end if;
 if p_operation_id is null or length(btrim(p_operation_id))=0 or p_operation_fingerprint!~'^[a-f0-9]{64}$' then return jsonb_build_object('disposition','invalid','code','invalid_operation_identity'); end if;
 -- Global order: manifest, metadata, binding, candidate set, capability, decision, operation.
 select * into v_manifest_file from tongs.workpiece_files where workpiece_id=p_workpiece_id and path='hammer/release-packet/manifest.v1.json' for update;
 select * into v_metadata_file from tongs.workpiece_files where workpiece_id=p_workpiece_id and path='metadata.json' for update;
 perform pg_advisory_xact_lock(hashtextextended(p_workspace_id::text||':'||p_workpiece_id::text||':brand',0));
 select * into v_binding from tongs.workpiece_brand_bindings where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id order by revision desc limit 1;
 perform pg_advisory_xact_lock(hashtextextended(p_workspace_id::text||':'||p_workpiece_id::text||':thumbnail-candidate-set',0));
 select * into v_set from tongs.thumbnail_candidate_sets where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id order by revision desc limit 1;
 perform pg_advisory_xact_lock(hashtextextended(p_destination_scope_id::text||':quench-capability',0));
 select * into v_scope from tongs.quench_destination_scopes where id=p_destination_scope_id and state='active';
 perform pg_advisory_xact_lock(hashtextextended(p_workspace_id::text||':'||p_workpiece_id::text||':'||p_destination_scope_id::text||':quench-decision',0));
 insert into tongs.quench_release_decision_sequences(workspace_id,workpiece_id,destination_scope_id) values(p_workspace_id,p_workpiece_id,p_destination_scope_id) on conflict do nothing;
 select * into v_seq from tongs.quench_release_decision_sequences where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and destination_scope_id=p_destination_scope_id for update;
 perform pg_advisory_xact_lock(hashtextextended(p_operation_id||':quench-operation',0));
 select * into v_receipt from tongs.quench_release_operation_receipts where operation_id=p_operation_id;
 if found then if v_receipt.workspace_id<>p_workspace_id or v_receipt.workpiece_id<>p_workpiece_id or v_receipt.destination_scope_id<>p_destination_scope_id or v_receipt.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_conflict','code','operation_identity_reused'); end if;
  return v_receipt.immutable_result_json||jsonb_build_object('disposition','replayed','applicability',tongs.quench_release_decision_applicability(v_receipt.decision_id)); end if;
 if v_manifest_file.workpiece_id is null then return jsonb_build_object('disposition','blocked','code','manifest_unavailable'); end if;
 if v_metadata_file.workpiece_id is null then return jsonb_build_object('disposition','blocked','code','metadata_unavailable'); end if;
 if v_binding.id is null or v_binding.id<>p_active_binding_id then return jsonb_build_object('disposition','binding_conflict'); end if;
 if v_set.id is null or v_set.id<>p_candidate_set_id then return jsonb_build_object('disposition','candidate_set_conflict'); end if;
 if v_scope.id is null or (v_scope.workspace_id is not null and v_scope.workspace_id<>p_workspace_id) then return jsonb_build_object('disposition','capability_conflict'); end if;
 select * into v_cap from tongs.quench_destination_capability_revisions where id=p_capability_revision_id and destination_scope_id=p_destination_scope_id;
 if not found or v_scope.current_capability_revision_id<>v_cap.id then return jsonb_build_object('disposition','capability_conflict'); end if;
 select * into v_manifest from tongs.quench_release_manifest_snapshots where id=p_manifest_snapshot_id and workspace_id=p_workspace_id and workpiece_id=p_workpiece_id;
 if not found or v_manifest.source_file_revision<>v_manifest_file.revision or v_manifest.manifest_content_hash<>lower(v_manifest_file.hash_value) then return jsonb_build_object('disposition','manifest_conflict'); end if;
 if v_metadata_file.revision<>p_metadata_revision or lower(v_metadata_file.hash_value)<>lower(p_metadata_hash) then return jsonb_build_object('disposition','metadata_conflict'); end if;
 if v_seq.current_decision_id is distinct from p_expected_decision_id or v_seq.current_revision<>p_expected_revision then return jsonb_build_object('disposition','revision_conflict','current_decision_id',v_seq.current_decision_id,'current_revision',v_seq.current_revision); end if;
 if p_intent_state='cancelled' then if v_seq.current_decision_id is null or p_decision_kind not in('single_candidate','experiment_intent') or coalesce(jsonb_array_length(p_assignments),0)<>0 then return jsonb_build_object('disposition','invalid_assignment_set'); end if;
 else if jsonb_typeof(p_assignments)<>'array' then return jsonb_build_object('disposition','invalid_assignment_set'); end if; end if;
 create temporary table if not exists pg_temp.quench_assignments(ordinal int primary key,role text,candidate_id uuid unique,allocation int,composite_id uuid,composite_hash text,recipe_hash text,binding_id uuid,binding_revision int,readability_hash text) on commit drop; truncate pg_temp.quench_assignments;
 for v_entry in select value from jsonb_array_elements(coalesce(p_assignments,'[]'::jsonb)) loop v_count:=v_count+1;
  select * into v_candidate from tongs.thumbnail_candidate_revisions where id=(v_entry->>'candidate_revision_id')::uuid and workspace_id=p_workspace_id and workpiece_id=p_workpiece_id;
  if not found or not exists(select 1 from tongs.thumbnail_candidate_set_members where candidate_set_id=v_set.id and candidate_revision_id=v_candidate.id and workspace_id=p_workspace_id and workpiece_id=p_workpiece_id) then return jsonb_build_object('disposition','invalid_assignment_set','code','candidate_not_in_set'); end if;
  select * into v_asset from tongs.assets where id=v_candidate.composite_asset_id; if not found or v_asset.status<>'ready' or v_asset.content_hash<>v_candidate.composite_content_hash then return jsonb_build_object('disposition','asset_verification_blocked'); end if;
  if tongs.thumbnail_candidate_eligibility(v_candidate.id,v_binding.id) not in('current','approved_historical_brand') then return jsonb_build_object('disposition','candidate_ineligible'); end if;
  insert into pg_temp.quench_assignments values((v_entry->>'assignment_ordinal')::int,v_entry->>'assignment_role',v_candidate.id,nullif(v_entry->>'allocation_basis_points','')::int,v_candidate.composite_asset_id,v_candidate.composite_content_hash,v_candidate.recipe_hash,v_candidate.candidate_binding_id,v_candidate.candidate_binding_revision,v_candidate.readability_evidence_hash);
 end loop;
 if p_intent_state='selected' and (p_decision_kind<>'single_candidate' or v_count<>1 or (select count(*) from pg_temp.quench_assignments where role='selected')<>1 or exists(select 1 from pg_temp.quench_assignments where allocation is not null)) then return jsonb_build_object('disposition','invalid_assignment_set'); end if;
 if p_intent_state='experiment_planned' and (p_decision_kind<>'experiment_intent' or v_count<2 or (select count(*) from pg_temp.quench_assignments where role='control')<>1 or (select count(*) from pg_temp.quench_assignments where role='variant')<1 or exists(select 1 from pg_temp.quench_assignments where role='selected') or ((select count(allocation) from pg_temp.quench_assignments)>0 and ((select count(allocation) from pg_temp.quench_assignments)<>v_count or (select sum(allocation) from pg_temp.quench_assignments)<>10000))) then return jsonb_build_object('disposition','invalid_assignment_set'); end if;
 select coalesce(jsonb_agg(jsonb_build_object('candidate_revision_id',candidate_id,'assignment_role',role,'assignment_ordinal',ordinal,'allocation_basis_points',allocation,'composite_asset_id',composite_id,'composite_content_hash',composite_hash,'recipe_hash',recipe_hash,'candidate_binding_id',binding_id,'candidate_binding_revision',binding_revision,'readability_evidence_hash',readability_hash) order by ordinal),'[]'::jsonb) into v_ordered from pg_temp.quench_assignments;
 v_hash:=encode(extensions.digest(convert_to(jsonb_strip_nulls(jsonb_build_object('workspace_id',p_workspace_id,'workpiece_id',p_workpiece_id,'destination_scope_id',p_destination_scope_id,'decision_kind',p_decision_kind,'intent_state',p_intent_state,'manifest_snapshot_id',v_manifest.id,'manifest_hash',v_manifest.manifest_content_hash,'metadata_revision',v_metadata_file.revision,'metadata_hash',lower(v_metadata_file.hash_value),'candidate_set_id',v_set.id,'candidate_set_revision',v_set.revision,'candidate_set_hash',v_set.content_hash,'active_binding_id',v_binding.id,'active_binding_revision',v_binding.revision,'capability_revision_id',v_cap.id,'capability_hash',v_cap.content_hash,'assignments',v_ordered))::text,'UTF8'),'sha256'),'hex');
 if p_operation_fingerprint<>v_hash then return jsonb_build_object('disposition','operation_conflict','code','operation_fingerprint_mismatch','canonical_fingerprint',v_hash); end if;
 select * into v_current from tongs.quench_release_decision_revisions where id=v_seq.current_decision_id;
 if v_current.decision_content_hash=v_hash then
  v_result:=jsonb_build_object('disposition','no_change','decision_id',v_current.id,'decision_revision',v_current.revision,'decision_content_hash',v_hash);
  insert into tongs.quench_release_operation_receipts(operation_id,operation_fingerprint,workspace_id,workpiece_id,destination_scope_id,mutation_kind,decision_id,decision_revision,immutable_result_json,created_by) values(p_operation_id,v_hash,p_workspace_id,p_workpiece_id,p_destination_scope_id,'commit_release_decision',v_current.id,v_current.revision,v_result,v_user);
  return v_result||jsonb_build_object('applicability',tongs.quench_release_decision_applicability(v_current.id));
 end if;
 v_revision:=v_seq.current_revision+1;
 insert into tongs.quench_release_decision_revisions(id,workspace_id,workpiece_id,destination_scope_id,revision,previous_decision_id,decision_kind,intent_state,manifest_snapshot_id,manifest_content_hash,metadata_revision,metadata_content_hash,metadata_snapshot_json,candidate_set_id,candidate_set_revision,candidate_set_content_hash,active_binding_id,active_binding_revision,capability_revision_id,capability_content_hash,allocation_unit,decision_content_hash,created_by)
 values(v_id,p_workspace_id,p_workpiece_id,p_destination_scope_id,v_revision,v_seq.current_decision_id,p_decision_kind,p_intent_state,v_manifest.id,v_manifest.manifest_content_hash,v_metadata_file.revision,lower(v_metadata_file.hash_value),jsonb_build_object('revision',v_metadata_file.revision,'content_hash',lower(v_metadata_file.hash_value)),v_set.id,v_set.revision,v_set.content_hash,v_binding.id,v_binding.revision,v_cap.id,v_cap.content_hash,case when exists(select 1 from pg_temp.quench_assignments where allocation is not null) then 'basis_points' end,v_hash,v_user);
 insert into tongs.quench_release_candidate_assignments(decision_id,workspace_id,workpiece_id,destination_scope_id,candidate_revision_id,candidate_set_id,assignment_role,assignment_ordinal,allocation_basis_points,composite_asset_id,composite_content_hash,recipe_hash,candidate_binding_id,candidate_binding_revision,readability_evidence_hash)
 select v_id,p_workspace_id,p_workpiece_id,p_destination_scope_id,candidate_id,v_set.id,role,ordinal,allocation,composite_id,composite_hash,recipe_hash,binding_id,binding_revision,readability_hash from pg_temp.quench_assignments;
 update tongs.quench_release_decision_sequences set current_decision_id=v_id,current_revision=v_revision,updated_at=now() where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and destination_scope_id=p_destination_scope_id;
 v_result:=jsonb_build_object('disposition','committed','decision_id',v_id,'decision_revision',v_revision,'decision_content_hash',v_hash);
 insert into tongs.quench_release_operation_receipts(operation_id,operation_fingerprint,workspace_id,workpiece_id,destination_scope_id,mutation_kind,decision_id,decision_revision,immutable_result_json,created_by) values(p_operation_id,v_hash,p_workspace_id,p_workpiece_id,p_destination_scope_id,'commit_release_decision',v_id,v_revision,v_result,v_user);
 return v_result||jsonb_build_object('applicability',tongs.quench_release_decision_applicability(v_id));
exception when unique_violation then select * into v_receipt from tongs.quench_release_operation_receipts where operation_id=p_operation_id; if found and v_receipt.operation_fingerprint=p_operation_fingerprint and v_receipt.workspace_id=p_workspace_id and v_receipt.workpiece_id=p_workpiece_id and v_receipt.destination_scope_id=p_destination_scope_id then return v_receipt.immutable_result_json||jsonb_build_object('disposition','replayed','applicability',tongs.quench_release_decision_applicability(v_receipt.decision_id)); end if; return jsonb_build_object('disposition','operation_conflict'); end $_$;


ALTER FUNCTION "tongs"."commit_quench_release_decision"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_destination_scope_id" "uuid", "p_expected_decision_id" "uuid", "p_expected_revision" integer, "p_decision_kind" "text", "p_intent_state" "text", "p_manifest_snapshot_id" "uuid", "p_metadata_revision" bigint, "p_metadata_hash" "text", "p_candidate_set_id" "uuid", "p_active_binding_id" "uuid", "p_capability_revision_id" "uuid", "p_assignments" "jsonb", "p_operation_id" "text", "p_operation_fingerprint" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."commit_quench_release_decision"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_destination_scope_id" "uuid", "p_expected_decision_id" "uuid", "p_expected_revision" integer, "p_decision_kind" "text", "p_intent_state" "text", "p_manifest_snapshot_id" "uuid", "p_metadata_revision" bigint, "p_metadata_hash" "text", "p_candidate_set_id" "uuid", "p_active_binding_id" "uuid", "p_capability_revision_id" "uuid", "p_assignments" "jsonb", "p_operation_id" "text", "p_operation_fingerprint" "text") IS 'Authorization-first, lock-ordered canonical Quench decision commit authority.';



CREATE OR REPLACE FUNCTION "tongs"."commit_reference_clip_acquisition_asset"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_asset_kind" "text", "p_path" "text", "p_mime_type" "text", "p_byte_size" bigint, "p_content_hash" "text", "p_storage_bucket" "text", "p_storage_key" "text", "p_width" integer, "p_height" integer, "p_duration_ms" bigint, "p_provider" "text", "p_provider_request_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $_$
declare op tongs.reference_clip_acquisition_operations%rowtype;a tongs.assets%rowtype;next_state text;begin if auth.role()<>'service_role' then raise exception 'Reference Clip asset commit requires service authority' using errcode='42501';end if;select * into op from tongs.reference_clip_acquisition_operations where operation_id=p_operation_id for update;if not found then return jsonb_build_object('disposition','operation_not_found');end if;if op.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict');end if;if p_asset_kind not in('reference_clip_video','reference_clip_poster') or p_byte_size<=0 or p_content_hash!~'^[0-9a-f]{64}$' or p_width<=0 or p_height<=0 then return jsonb_build_object('disposition','invalid_verified_media_evidence');end if;if p_asset_kind='reference_clip_video' and(p_mime_type not like 'video/%' or coalesce(p_duration_ms,0)<=0)then return jsonb_build_object('disposition','invalid_verified_video_evidence');end if;if p_asset_kind='reference_clip_poster' and p_mime_type not like 'image/%' then return jsonb_build_object('disposition','invalid_verified_poster_evidence');end if;
 select * into a from tongs.assets where workspace_id=op.workspace_id and workpiece_id=op.workpiece_id and operation_id=p_operation_id and asset_kind=p_asset_kind for update;if found then if a.operation_fingerprint<>p_operation_fingerprint or a.content_hash<>p_content_hash or a.storage_bucket<>p_storage_bucket or a.storage_key<>p_storage_key or a.bytes<>p_byte_size then return jsonb_build_object('disposition','asset_replay_conflict');end if;return jsonb_build_object('disposition','replay','operation',to_jsonb(op),'asset',to_jsonb(a));end if;
 if p_asset_kind='reference_clip_video' and op.state<>'source_acquired' then return jsonb_build_object('disposition','source_acquisition_required');end if;if p_asset_kind='reference_clip_poster' and op.state<>'video_asset_verified' then return jsonb_build_object('disposition','video_asset_verification_required');end if;
 insert into tongs.assets(workspace_id,workpiece_id,path,mime_type,bytes,storage_bucket,storage_key,provider,provider_request_id,request_id,created_by,asset_kind,status,metadata_json,width,height,operation_id,operation_fingerprint,content_hash,ready_at)values(op.workspace_id,op.workpiece_id,p_path,p_mime_type,p_byte_size,p_storage_bucket,p_storage_key,p_provider,p_provider_request_id,p_operation_id,op.created_by,p_asset_kind,'ready',jsonb_strip_nulls(jsonb_build_object('duration_ms',p_duration_ms,'inspection_authority','tongs-service.v1')),p_width,p_height,p_operation_id,p_operation_fingerprint,p_content_hash,now())returning * into a;next_state:=case when p_asset_kind='reference_clip_video' then 'video_asset_verified' else 'poster_asset_verified'end;update tongs.reference_clip_acquisition_operations set state=next_state,verified_video_asset_id=case when p_asset_kind='reference_clip_video' then a.id else verified_video_asset_id end,verified_poster_asset_id=case when p_asset_kind='reference_clip_poster' then a.id else verified_poster_asset_id end,failed_stage=null,failure_code=null,failure_message=null,failure_evidence_json=null,updated_at=now()where operation_id=p_operation_id returning * into op;return jsonb_build_object('disposition',next_state,'operation',to_jsonb(op),'asset',to_jsonb(a));end$_$;


ALTER FUNCTION "tongs"."commit_reference_clip_acquisition_asset"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_asset_kind" "text", "p_path" "text", "p_mime_type" "text", "p_byte_size" bigint, "p_content_hash" "text", "p_storage_bucket" "text", "p_storage_key" "text", "p_width" integer, "p_height" integer, "p_duration_ms" bigint, "p_provider" "text", "p_provider_request_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."commit_reference_clip_acquisition_candidate"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_rights" "jsonb", "p_provenance" "jsonb", "p_actor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare op tongs.reference_clip_acquisition_operations%rowtype;o tongs.reference_clip_opportunity_revisions%rowtype;a tongs.assets%rowtype;c tongs.reference_clip_candidates%rowtype;r tongs.reference_clip_candidate_revisions%rowtype;h text;ih text;result jsonb;begin select * into op from tongs.reference_clip_acquisition_operations where operation_id=p_operation_id for update;if not found then return jsonb_build_object('disposition','operation_not_found');end if;if not tongs.has_workspace_role(op.workspace_id,'editor') or auth.uid() is distinct from p_actor_id then raise exception 'workspace editor authority required' using errcode='42501';end if;if op.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict');end if;if op.state='candidate_committed' then return op.receipt_json;end if;if op.state<>'poster_asset_verified' then return jsonb_build_object('disposition','poster_asset_verification_required');end if;select * into o from tongs.reference_clip_opportunity_revisions where id=op.opportunity_revision_id;select * into a from tongs.assets where id=op.verified_video_asset_id and status='ready';if not found then return jsonb_build_object('disposition','verified_video_asset_required');end if;
 insert into tongs.reference_clip_candidates(workspace_id,workpiece_id,opportunity_id,created_by)values(op.workspace_id,op.workpiece_id,op.opportunity_id,p_actor_id)returning * into c;h:=encode(extensions.digest(convert_to(jsonb_build_object('asset',a.content_hash,'poster',op.verified_poster_asset_id,'source',o.source_revision_id,'link',o.workpiece_source_link_revision_id,'rights',p_rights,'provenance',p_provenance)::text,'UTF8'),'sha256'),'hex');ih:=encode(extensions.digest(convert_to(jsonb_build_object('candidate',c.id,'hash',h,'revision',1,'operation',p_operation_id)::text,'UTF8'),'sha256'),'hex');
 insert into tongs.reference_clip_candidate_revisions(candidate_id,workspace_id,workpiece_id,opportunity_id,revision,opportunity_revision_id,opportunity_revision,source_revision_id,source_revision,workpiece_source_link_revision_id,workpiece_source_link_revision,asset_id,asset_content_hash,asset_path,storage_bucket,storage_key,mime_type,duration_ms,poster_asset_id,rights_basis,rights_holder,license_identifier,license_url,territories,expires_at,attribution_required,attribution_text,rights_evidence_json,provenance_json,content_hash,immutable_revision_hash,created_by)values(c.id,op.workspace_id,op.workpiece_id,op.opportunity_id,1,o.id,o.revision,o.source_revision_id,o.source_revision,o.workpiece_source_link_revision_id,o.workpiece_source_link_revision,a.id,a.content_hash,a.path,a.storage_bucket,a.storage_key,a.mime_type,(a.metadata_json->>'duration_ms')::bigint,op.verified_poster_asset_id,coalesce(p_rights->>'basis','unknown'),p_rights->>'rights_holder',p_rights->>'license_identifier',p_rights->>'license_url',array(select jsonb_array_elements_text(coalesce(p_rights->'territories','[]'))),nullif(p_rights->>'expires_at','')::timestamptz,coalesce((p_rights->>'attribution_required')::boolean,false),p_rights->>'attribution_text',p_rights,p_provenance,h,ih,p_actor_id)returning * into r;result:=jsonb_build_object('disposition','committed','candidate_revision',to_jsonb(r),'operation_id',p_operation_id);update tongs.reference_clip_acquisition_operations set state='candidate_committed',result_candidate_revision_id=r.id,receipt_json=result,failed_stage=null,failure_code=null,failure_message=null,failure_evidence_json=null,updated_at=now()where operation_id=p_operation_id returning * into op;return result;end$$;


ALTER FUNCTION "tongs"."commit_reference_clip_acquisition_candidate"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_rights" "jsonb", "p_provenance" "jsonb", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."commit_reference_clip_candidate"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_opportunity_id" "uuid", "p_opportunity_revision_id" "uuid", "p_asset_id" "uuid", "p_poster_asset_id" "uuid", "p_rights" "jsonb", "p_provenance" "jsonb", "p_operation_id" "text", "p_operation_fingerprint" "text", "p_actor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare seq tongs.reference_clip_plan_sequences%rowtype;o tongs.reference_clip_opportunity_revisions%rowtype;a tongs.assets%rowtype;poster tongs.assets%rowtype;c tongs.reference_clip_candidates%rowtype;r tongs.reference_clip_candidate_revisions%rowtype;h text;ih text;prior jsonb;result jsonb;
begin
 if not tongs.has_workspace_role(p_workspace_id,'editor') then raise exception 'workspace editor authority required' using errcode='42501';end if;select receipt_json into prior from tongs.reference_clip_operation_receipts where operation_id=p_operation_id and operation_fingerprint=p_operation_fingerprint;if found then return prior;end if;if exists(select 1 from tongs.reference_clip_operation_receipts where operation_id=p_operation_id) then return jsonb_build_object('disposition','operation_identity_conflict');end if;
 select * into seq from tongs.reference_clip_plan_sequences where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id for update;perform 1 from tongs.reference_clip_plan_membership where plan_revision_id=seq.current_plan_revision_id and opportunity_id=p_opportunity_id and opportunity_revision_id=p_opportunity_revision_id;if not found then return jsonb_build_object('disposition','opportunity_not_current');end if;select * into o from tongs.reference_clip_opportunity_revisions where id=p_opportunity_revision_id;
 select * into a from tongs.assets where id=p_asset_id and workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and status='ready' and ready_at is not null and content_hash is not null and mime_type like 'video/%';if not found then return jsonb_build_object('disposition','verified_video_asset_required');end if;
 if p_poster_asset_id is not null then select * into poster from tongs.assets where id=p_poster_asset_id and workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and status='ready' and mime_type like 'image/%';if not found then return jsonb_build_object('disposition','verified_poster_asset_required');end if;end if;
 if coalesce(p_rights->>'basis','unknown')='unknown' then return jsonb_build_object('disposition','rights_evidence_required');end if;
 insert into tongs.reference_clip_candidates(workspace_id,workpiece_id,opportunity_id,created_by) values(p_workspace_id,p_workpiece_id,p_opportunity_id,p_actor_id) returning * into c;h:=encode(extensions.digest(convert_to(jsonb_build_object('asset',a.content_hash,'source',o.source_revision_id,'link',o.workpiece_source_link_revision_id,'rights',p_rights,'provenance',p_provenance)::text,'UTF8'),'sha256'),'hex');ih:=encode(extensions.digest(convert_to(jsonb_build_object('candidate',c.id,'hash',h,'revision',1)::text,'UTF8'),'sha256'),'hex');
 insert into tongs.reference_clip_candidate_revisions(candidate_id,workspace_id,workpiece_id,opportunity_id,revision,opportunity_revision_id,opportunity_revision,source_revision_id,source_revision,workpiece_source_link_revision_id,workpiece_source_link_revision,asset_id,asset_content_hash,asset_path,storage_bucket,storage_key,mime_type,duration_ms,poster_asset_id,rights_basis,rights_holder,license_identifier,license_url,territories,expires_at,attribution_required,attribution_text,rights_evidence_json,provenance_json,content_hash,immutable_revision_hash,created_by)
 values(c.id,p_workspace_id,p_workpiece_id,p_opportunity_id,1,o.id,o.revision,o.source_revision_id,o.source_revision,o.workpiece_source_link_revision_id,o.workpiece_source_link_revision,a.id,a.content_hash,a.path,a.storage_bucket,a.storage_key,a.mime_type,coalesce((a.metadata_json->>'duration_ms')::bigint,1),poster.id,p_rights->>'basis',p_rights->>'rights_holder',p_rights->>'license_identifier',p_rights->>'license_url',array(select jsonb_array_elements_text(coalesce(p_rights->'territories','[]'))),nullif(p_rights->>'expires_at','')::timestamptz,coalesce((p_rights->>'attribution_required')::boolean,false),p_rights->>'attribution_text',p_rights,p_provenance,h,ih,p_actor_id) returning * into r;
 result:=jsonb_build_object('disposition','committed','candidate_revision',to_jsonb(r));insert into tongs.reference_clip_operation_receipts(operation_id,operation_fingerprint,operation_type,workspace_id,workpiece_id,opportunity_id,state,result_candidate_revision_id,receipt_json,created_by) values(p_operation_id,p_operation_fingerprint,'candidate_commit',p_workspace_id,p_workpiece_id,p_opportunity_id,'committed',r.id,result,p_actor_id);return result;
end$$;


ALTER FUNCTION "tongs"."commit_reference_clip_candidate"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_opportunity_id" "uuid", "p_opportunity_revision_id" "uuid", "p_asset_id" "uuid", "p_poster_asset_id" "uuid", "p_rights" "jsonb", "p_provenance" "jsonb", "p_operation_id" "text", "p_operation_fingerprint" "text", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."commit_reference_clip_plan"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_expected_revision_id" "uuid", "p_expected_revision" bigint, "p_script_approval_id" "uuid", "p_contract_version" "text", "p_opportunities" "jsonb", "p_operation_id" "text", "p_operation_fingerprint" "text", "p_actor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare s tongs.reference_clip_plan_sequences%rowtype;a tongs.script_approval_revisions%rowtype;p tongs.reference_clip_plan_revisions%rowtype;o jsonb;r tongs.reference_clip_opportunity_revisions%rowtype;prev tongs.reference_clip_opportunity_revisions%rowtype;src tongs.source_revisions%rowtype;lnk tongs.workpiece_source_link_revisions%rowtype;oid uuid;status text;h text;ih text;i int:=0;prior jsonb;result jsonb;
begin
 if not tongs.has_workspace_role(p_workspace_id,'editor') then raise exception 'workspace editor authority required' using errcode='42501';end if;
 select receipt_json into prior from tongs.reference_clip_operation_receipts where operation_id=p_operation_id and operation_fingerprint=p_operation_fingerprint;if found then return prior;end if;
 if exists(select 1 from tongs.reference_clip_operation_receipts where operation_id=p_operation_id) then return jsonb_build_object('disposition','operation_identity_conflict');end if;
 if jsonb_typeof(p_opportunities)<>'array' then return jsonb_build_object('disposition','opportunities_required');end if;
 insert into tongs.reference_clip_plan_sequences(workspace_id,workpiece_id) values(p_workspace_id,p_workpiece_id) on conflict do nothing;select * into s from tongs.reference_clip_plan_sequences where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id for update;
 if s.current_plan_revision<>p_expected_revision or s.current_plan_revision_id is distinct from p_expected_revision_id then return jsonb_build_object('disposition','plan_revision_conflict','current_revision_id',s.current_plan_revision_id,'current_revision',s.current_plan_revision);end if;
 select * into a from tongs.script_approval_revisions where id=p_script_approval_id and workspace_id=p_workspace_id and workpiece_id=p_workpiece_id;if not found then return jsonb_build_object('disposition','script_revision_conflict');end if;
 h:=encode(extensions.digest(convert_to(jsonb_build_object('script',a.script_content_hash,'contract',p_contract_version,'opportunities',p_opportunities)::text,'UTF8'),'sha256'),'hex');ih:=encode(extensions.digest(convert_to(jsonb_build_object('hash',h,'revision',s.current_plan_revision+1,'previous',s.current_plan_revision_id)::text,'UTF8'),'sha256'),'hex');
 insert into tongs.reference_clip_plan_revisions(workspace_id,workpiece_id,revision,previous_revision_id,previous_revision,script_approval_id,script_approval_revision,script_content_hash,contract_version,content_hash,immutable_revision_hash,created_by) values(p_workspace_id,p_workpiece_id,s.current_plan_revision+1,s.current_plan_revision_id,nullif(s.current_plan_revision,0),a.id,a.approval_revision,a.script_content_hash,p_contract_version,h,ih,p_actor_id) returning * into p;
 for o in select value from jsonb_array_elements(p_opportunities) loop
  i:=i+1;oid:=coalesce(nullif(o->>'opportunity_id','')::uuid,gen_random_uuid());status:=coalesce(nullif(o->>'source_status',''),case when nullif(o->>'source_revision_id','') is not null then 'linked' else 'unresolved' end);
  src:=null;lnk:=null;
  if status='linked' then select * into src from tongs.source_revisions where id=(o->>'source_revision_id')::uuid and workspace_id=p_workspace_id;select * into lnk from tongs.workpiece_source_link_revisions where id=(o->>'workpiece_source_link_revision_id')::uuid and workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and source_revision_id=src.id;if src.id is null or lnk.id is null then raise exception 'exact Source revision and workpiece link required';end if;
  elsif status<>'unresolved' then raise exception 'invalid source_status'; end if;
  select * into prev from tongs.reference_clip_opportunity_revisions where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and opportunity_id=oid order by revision desc limit 1;
  h:=encode(extensions.digest(convert_to(o::text,'UTF8'),'sha256'),'hex');ih:=encode(extensions.digest(convert_to(jsonb_build_object('hash',h,'plan',p.id,'opportunity',oid,'revision',coalesce(prev.revision,0)+1)::text,'UTF8'),'sha256'),'hex');
  insert into tongs.reference_clip_opportunity_revisions(opportunity_id,workspace_id,workpiece_id,revision,previous_revision_id,previous_revision,source_plan_revision_id,source_plan_revision,script_approval_id,script_approval_revision,source_status,source_id,source_revision_id,source_revision,workpiece_source_link_id,workpiece_source_link_revision_id,workpiece_source_link_revision,context_before,context_focus,context_after,citation_anchor_json,media_range_json,narrative_purpose,editorial_reason,desired_material,search_terms,placement_hint,duration_target_ms,creator_direction,content_hash,immutable_revision_hash,created_by)
  values(oid,p_workspace_id,p_workpiece_id,coalesce(prev.revision,0)+1,prev.id,prev.revision,p.id,p.revision,a.id,a.approval_revision,status,src.source_id,src.id,src.revision,lnk.link_id,lnk.id,lnk.revision,coalesce(o->>'context_before',''),o->>'context_focus',coalesce(o->>'context_after',''),coalesce(o->'citation_anchor','{}'),coalesce(o->'media_range','{}'),o->>'narrative_purpose',coalesce(o->>'editorial_reason',o->>'narrative_purpose'),coalesce(o->>'desired_material',o->>'creator_direction',o->>'narrative_purpose'),array(select jsonb_array_elements_text(coalesce(o->'search_terms','[]'))),o->>'placement_hint',coalesce((o->>'duration_target_ms')::bigint,5000),o->>'creator_direction',h,ih,p_actor_id) returning * into r;
  insert into tongs.reference_clip_plan_membership values(p.id,p_workspace_id,p_workpiece_id,p.revision,i,oid,r.id,r.revision);
 end loop;
 update tongs.reference_clip_plan_sequences set current_plan_revision_id=p.id,current_plan_revision=p.revision,updated_at=now() where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id;
 result:=jsonb_build_object('disposition','committed','plan_revision',to_jsonb(p));insert into tongs.reference_clip_operation_receipts(operation_id,operation_fingerprint,operation_type,workspace_id,workpiece_id,state,result_plan_revision_id,receipt_json,created_by) values(p_operation_id,p_operation_fingerprint,'plan_commit',p_workspace_id,p_workpiece_id,'committed',p.id,result,p_actor_id);return result;
end$$;


ALTER FUNCTION "tongs"."commit_reference_clip_plan"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_expected_revision_id" "uuid", "p_expected_revision" bigint, "p_script_approval_id" "uuid", "p_contract_version" "text", "p_opportunities" "jsonb", "p_operation_id" "text", "p_operation_fingerprint" "text", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."commit_reference_clip_selection_set"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_opportunity_id" "uuid", "p_candidate_revision_ids" "jsonb", "p_expected_plan_revision_id" "uuid", "p_expected_plan_revision" bigint, "p_expected_selection_set_revision" bigint, "p_operation_id" "text", "p_operation_fingerprint" "text", "p_actor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare seq tongs.reference_clip_plan_sequences%rowtype;member tongs.reference_clip_plan_membership%rowtype;
 current_set tongs.reference_clip_selection_set_revisions%rowtype;new_set tongs.reference_clip_selection_set_revisions%rowtype;
 candidate tongs.reference_clip_candidate_revisions%rowtype;entry jsonb;selected_candidate_id uuid;input_ordinal integer:=0;member_ordinal integer;
 ids uuid[]:=array[]::uuid[];prior jsonb;result jsonb;
begin
 if not tongs.has_workspace_role(p_workspace_id,'editor')then raise exception 'workspace editor authority required' using errcode='42501';end if;
 select jsonb_build_object('disposition','committed','selection_set_revision',to_jsonb(r),'selected_candidate_revision_ids',coalesce((select jsonb_agg(m.candidate_revision_id order by m.ordinal)from tongs.reference_clip_selection_set_members m where m.selection_set_revision_id=r.id),'[]'::jsonb),'canonical_selection_revision',r.canonical_revision) into prior from tongs.reference_clip_selection_set_revisions r where r.operation_id=p_operation_id and r.operation_fingerprint=p_operation_fingerprint;
 if found then return prior;end if;
 if exists(select 1 from tongs.reference_clip_selection_set_revisions where operation_id=p_operation_id)or exists(select 1 from tongs.reference_clip_operation_receipts where operation_id=p_operation_id)then return jsonb_build_object('disposition','operation_identity_conflict');end if;
 if jsonb_typeof(p_candidate_revision_ids)<>'array'then return jsonb_build_object('disposition','candidate_collection_required');end if;
 select * into seq from tongs.reference_clip_plan_sequences where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id for update;
 if not found then return jsonb_build_object('disposition','plan_not_found');end if;
 if seq.current_plan_revision_id is distinct from p_expected_plan_revision_id or seq.current_plan_revision<>p_expected_plan_revision then return jsonb_build_object('disposition','plan_revision_conflict');end if;
 select * into member from tongs.reference_clip_plan_membership where plan_revision_id=seq.current_plan_revision_id and opportunity_id=p_opportunity_id;
 if not found then return jsonb_build_object('disposition','opportunity_not_current');end if;
 select * into current_set from tongs.reference_clip_selection_set_revisions where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and opportunity_id=p_opportunity_id and plan_revision_id=seq.current_plan_revision_id order by revision desc limit 1;
 if coalesce(current_set.revision,0)<>p_expected_selection_set_revision then return jsonb_build_object('disposition','selection_revision_conflict','current_selection_revision',coalesce(current_set.revision,0));end if;
 for entry in select value from jsonb_array_elements(p_candidate_revision_ids)loop
  input_ordinal:=input_ordinal+1;
  begin selected_candidate_id:=(entry#>>'{}')::uuid;exception when others then return jsonb_build_object('disposition','invalid_candidate','ordinal',input_ordinal);end;
  if selected_candidate_id=any(ids)then return jsonb_build_object('disposition','duplicate_candidate','candidate_revision_id',selected_candidate_id);end if;
  select * into candidate from tongs.reference_clip_candidate_revisions cr where cr.id=selected_candidate_id and cr.workspace_id=p_workspace_id and cr.workpiece_id=p_workpiece_id and cr.opportunity_id=p_opportunity_id and cr.opportunity_revision_id=member.opportunity_revision_id;
  if not found then return jsonb_build_object('disposition','invalid_candidate','candidate_revision_id',selected_candidate_id);end if;
  ids:=array_append(ids,selected_candidate_id);
 end loop;
 insert into tongs.reference_clip_selection_set_revisions(workspace_id,workpiece_id,opportunity_id,plan_revision_id,plan_revision,opportunity_revision_id,opportunity_revision,revision,canonical_revision,previous_revision_id,previous_revision,operation_id,operation_fingerprint,created_by)
 values(p_workspace_id,p_workpiece_id,p_opportunity_id,seq.current_plan_revision_id,seq.current_plan_revision,member.opportunity_revision_id,member.opportunity_revision,coalesce(current_set.revision,0)+1,seq.current_selection_revision+1,current_set.id,current_set.revision,p_operation_id,p_operation_fingerprint,p_actor_id)returning * into new_set;
 for member_ordinal in 1..coalesce(array_length(ids,1),0)loop
  select * into candidate from tongs.reference_clip_candidate_revisions where id=ids[member_ordinal];
  insert into tongs.reference_clip_selection_set_members(selection_set_revision_id,workspace_id,workpiece_id,opportunity_id,plan_revision_id,selection_set_revision,candidate_revision_id,candidate_revision,ordinal)
  values(new_set.id,p_workspace_id,p_workpiece_id,p_opportunity_id,seq.current_plan_revision_id,new_set.revision,candidate.id,candidate.revision,member_ordinal);
 end loop;
 update tongs.reference_clip_plan_sequences set current_selection_revision=current_selection_revision+1,updated_at=now()where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id returning current_selection_revision into seq.current_selection_revision;
 result:=jsonb_build_object('disposition','committed','selection_set_revision',to_jsonb(new_set),'selected_candidate_revision_ids',to_jsonb(ids),'canonical_selection_revision',seq.current_selection_revision);
 return result;
end$$;


ALTER FUNCTION "tongs"."commit_reference_clip_selection_set"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_opportunity_id" "uuid", "p_candidate_revision_ids" "jsonb", "p_expected_plan_revision_id" "uuid", "p_expected_plan_revision" bigint, "p_expected_selection_set_revision" bigint, "p_operation_id" "text", "p_operation_fingerprint" "text", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."commit_reference_visual_acquisition"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_path" "text", "p_mime_type" "text", "p_byte_size" bigint, "p_content_hash" "text", "p_storage_bucket" "text", "p_storage_key" "text", "p_width" integer, "p_height" integer, "p_provenance" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $_$
declare op tongs.reference_visual_acquisition_operations%rowtype;o tongs.reference_visual_opportunity_revisions%rowtype;
 a tongs.assets%rowtype;c tongs.reference_visual_candidates%rowtype;r tongs.reference_visual_candidate_revisions%rowtype;h text;ih text;receipt jsonb;
begin
 if auth.role()<>'service_role' then raise exception 'Reference Visual acquisition commit requires service authority' using errcode='42501';end if;
 select * into op from tongs.reference_visual_acquisition_operations where operation_id=p_operation_id for update;
 if not found then return jsonb_build_object('disposition','operation_not_found');end if;
 if op.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict');end if;
 if op.state='candidate_committed' then return op.receipt_json;end if;
 if op.state<>'source_acquired' then return jsonb_build_object('disposition','source_acquisition_required');end if;
 if op.source_set_revision_id is null then return jsonb_build_object('disposition','source_set_authority_required');end if;
 if p_mime_type not like'image/%'or p_byte_size<=0 or p_content_hash!~'^[0-9a-f]{64}$'or p_width<=0 or p_height<=0 then return jsonb_build_object('disposition','invalid_verified_image_evidence');end if;
 select * into o from tongs.reference_visual_opportunity_revisions where id=op.opportunity_revision_id;
 insert into tongs.assets(workspace_id,workpiece_id,path,mime_type,bytes,storage_bucket,storage_key,provider,request_id,created_by,asset_kind,status,metadata_json,width,height,operation_id,operation_fingerprint,content_hash,ready_at)
 values(op.workspace_id,op.workpiece_id,p_path,p_mime_type,p_byte_size,p_storage_bucket,p_storage_key,case when op.acquisition_type='upload'then'creator-upload'else'external-fetch'end,p_operation_id,op.created_by,'reference_visual_image','ready',jsonb_build_object('inspection_authority','tongs-service.v2','source_set_revision_id',op.source_set_revision_id),p_width,p_height,p_operation_id,p_operation_fingerprint,p_content_hash,now())returning * into a;
 insert into tongs.reference_visual_candidates(workspace_id,workpiece_id,opportunity_id,created_by)values(op.workspace_id,op.workpiece_id,o.opportunity_id,op.created_by)returning * into c;
 h:=encode(extensions.digest(convert_to(jsonb_build_object('asset_hash',a.content_hash,'opportunity_revision_id',o.id,'source_set_revision_id',op.source_set_revision_id,'rights_revision_id',op.rights_declaration_revision_id,'provenance',p_provenance)::text,'UTF8'),'sha256'),'hex');
 ih:=encode(extensions.digest(convert_to(jsonb_build_object('candidate',c.id,'revision',1,'content_hash',h,'operation',p_operation_id)::text,'UTF8'),'sha256'),'hex');
 insert into tongs.reference_visual_candidate_revisions(candidate_id,workspace_id,workpiece_id,opportunity_id,revision,opportunity_revision_id,opportunity_revision,source_set_revision_id,candidate_kind,asset_id,rights_declaration_revision_id,render_receipt_json,provenance_json,content_hash,immutable_revision_hash,created_by)
 values(c.id,op.workspace_id,op.workpiece_id,o.opportunity_id,1,o.id,o.revision,op.source_set_revision_id,'archival_still',a.id,op.rights_declaration_revision_id,'{}',coalesce(p_provenance,'{}')||jsonb_build_object('operation_id',p_operation_id,'source_set_revision_id',op.source_set_revision_id),h,ih,op.created_by)returning * into r;
 receipt:=jsonb_build_object('disposition','committed','operation_id',p_operation_id,'source_set_revision_id',op.source_set_revision_id,'asset',to_jsonb(a),'candidate_revision',to_jsonb(r),'rights_declaration_revision_id',op.rights_declaration_revision_id);
 update tongs.reference_visual_acquisition_operations set state='candidate_committed',verified_asset_id=a.id,result_candidate_revision_id=r.id,failed_stage=null,failure_code=null,failure_message=null,receipt_json=receipt,updated_at=now()where operation_id=p_operation_id;return receipt;
end$_$;


ALTER FUNCTION "tongs"."commit_reference_visual_acquisition"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_path" "text", "p_mime_type" "text", "p_byte_size" bigint, "p_content_hash" "text", "p_storage_bucket" "text", "p_storage_key" "text", "p_width" integer, "p_height" integer, "p_provenance" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."commit_reference_visual_evidence"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_opportunity_id" "uuid", "p_evidence_id" "uuid", "p_expected_revision" bigint, "p_source_revision_id" "uuid", "p_workpiece_source_link_revision_id" "uuid", "p_evidence" "jsonb", "p_confirmation_state" "text", "p_operation_id" "text", "p_operation_fingerprint" "text", "p_actor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs', 'extensions'
    AS $$
declare
  op tongs.reference_visual_operation_receipts%rowtype;
  seq tongs.reference_visual_evidence_sequences%rowtype;
  prev tongs.reference_visual_evidence_revisions%rowtype;
  source_revision tongs.source_revisions%rowtype;
  source_link tongs.workpiece_source_link_revisions%rowtype;
  source_member tongs.reference_visual_source_set_members%rowtype;
  opportunity tongs.reference_visual_opportunity_revisions%rowtype;
  revision_row tongs.reference_visual_evidence_revisions%rowtype;
  claim tongs.reference_visual_evidence_claims%rowtype;
  current_claim_revision tongs.reference_visual_evidence_revisions%rowtype;
  intent text:=coalesce(nullif(btrim(p_evidence->>'evidence_intent'),''),'general_support');
  numeric_value numeric;
  computed_claim_fingerprint text;
  n bigint;
  h text;
  ih text;
  result jsonb;
begin
  if not tongs.has_workspace_role(p_workspace_id,'editor') or auth.uid() is distinct from p_actor_id then
    raise exception 'workspace editor authority required' using errcode='42501';
  end if;
  if intent not in('general_support','numeric_stat','dated_timeline','comparison_support') then
    return jsonb_build_object('disposition','invalid_evidence_intent');
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_operation_id,0));
  select * into op from tongs.reference_visual_operation_receipts where operation_id=p_operation_id;
  if found then
    if op.operation_fingerprint<>p_operation_fingerprint then
      return jsonb_build_object('disposition','operation_identity_conflict');
    end if;
    return op.receipt_json;
  end if;
  select * into source_revision from tongs.source_revisions
    where id=p_source_revision_id and workspace_id=p_workspace_id;
  select * into source_link from tongs.workpiece_source_link_revisions
    where id=p_workpiece_source_link_revision_id and workspace_id=p_workspace_id
      and workpiece_id=p_workpiece_id and source_revision_id=source_revision.id;
  if source_revision.id is null or source_link.id is null then
    return jsonb_build_object('disposition','canonical_source_evidence_required');
  end if;
  select o.* into opportunity
  from tongs.reference_visual_plan_sequences ps
  join tongs.reference_visual_plan_membership pm on pm.plan_revision_id=ps.current_plan_revision_id
    and pm.opportunity_id=p_opportunity_id
  join tongs.reference_visual_opportunity_revisions o on o.id=pm.opportunity_revision_id
  where ps.workspace_id=p_workspace_id and ps.workpiece_id=p_workpiece_id;
  if opportunity.id is null then
    return jsonb_build_object('disposition','reference_visual_opportunity_not_current');
  end if;
  select sm.* into source_member
  from tongs.reference_visual_plan_sequences ps
  join lateral(
    select ss.* from tongs.reference_visual_source_set_revisions ss
    where ss.workspace_id=ps.workspace_id and ss.workpiece_id=ps.workpiece_id
      and ss.opportunity_id=p_opportunity_id and ss.plan_revision_id=ps.current_plan_revision_id
    order by ss.revision desc limit 1
  ) current_set on true
  join tongs.reference_visual_source_set_members sm on sm.source_set_revision_id=current_set.id
    and sm.source_revision_id=p_source_revision_id
    and sm.workpiece_source_link_revision_id=p_workpiece_source_link_revision_id
  where ps.workspace_id=p_workspace_id and ps.workpiece_id=p_workpiece_id
    and(nullif(p_evidence->>'source_set_member_id','') is null
      or sm.id::text=p_evidence->>'source_set_member_id');
  if source_member.id is null then
    return jsonb_build_object('disposition','current_source_set_member_required');
  end if;
  if intent='numeric_stat' then
    if opportunity.visual_subtype not in('stat_card','chart')
      or nullif(btrim(coalesce(p_evidence->>'category','')),'') is distinct from opportunity.visual_subtype then
      return jsonb_build_object('disposition','numeric_stat_category_invalid');
    end if;
    if jsonb_typeof(p_evidence->'numeric_value') is distinct from 'number' then
      return jsonb_build_object('disposition','numeric_stat_value_required');
    end if;
    begin numeric_value:=(p_evidence->>'numeric_value')::numeric;
    exception when others then return jsonb_build_object('disposition','numeric_stat_value_invalid');end;
    if numeric_value::text in('NaN','Infinity','-Infinity') then
      return jsonb_build_object('disposition','numeric_stat_value_invalid');
    end if;
    if length(btrim(coalesce(p_evidence->>'unit','')))<1 then
      return jsonb_build_object('disposition','numeric_stat_unit_required');
    end if;
    if lower(btrim(p_evidence->>'unit')) in('year','years','date','dates') then
      return jsonb_build_object('disposition','numeric_stat_date_not_measure');
    end if;
    if length(btrim(coalesce(p_evidence->>'label','')))<2 then
      return jsonb_build_object('disposition','numeric_stat_label_required');
    end if;
    if length(btrim(coalesce(p_evidence->>'raw_excerpt','')))<1 then
      return jsonb_build_object('disposition','numeric_stat_excerpt_required');
    end if;
    if jsonb_typeof(p_evidence->'document_locator') is distinct from 'object'
      or coalesce(p_evidence->'document_locator','{}'::jsonb)='{}'::jsonb then
      return jsonb_build_object('disposition','numeric_stat_locator_required');
    end if;
    if jsonb_typeof(p_evidence->'citation_anchor') is distinct from 'object'
      or length(btrim(coalesce(p_evidence#>>'{citation_anchor,exact}','')))<1 then
      return jsonb_build_object('disposition','numeric_stat_citation_required');
    end if;
  elsif intent='dated_timeline' then
    if opportunity.visual_subtype<>'timeline' or p_evidence->>'category'<>'timeline' then
      return jsonb_build_object('disposition','dated_timeline_category_invalid');
    end if;
    if nullif(btrim(coalesce(p_evidence->>'date','')),'') is null
      and coalesce(p_evidence->>'label','')!~'\m(1[5-9][0-9]{2}|20[0-9]{2}|21[0-9]{2})\M'
      and coalesce(p_evidence->>'raw_excerpt','')!~'\m(1[5-9][0-9]{2}|20[0-9]{2}|21[0-9]{2})\M' then
      return jsonb_build_object('disposition','dated_timeline_date_required');
    end if;
  end if;
  numeric_value:=case when jsonb_typeof(p_evidence->'numeric_value')='number'
    then(p_evidence->>'numeric_value')::numeric else null end;
  computed_claim_fingerprint:=tongs.reference_visual_evidence_claim_fingerprint(
    p_workspace_id,p_workpiece_id,p_opportunity_id,source_member.id,
    source_revision.id,source_link.id,p_evidence->'document_locator',
    p_evidence->>'raw_excerpt',numeric_value,p_evidence->>'unit',
    p_evidence->>'evidence_role',p_evidence->>'category'
  );
  perform pg_advisory_xact_lock(hashtextextended(computed_claim_fingerprint,0));
  select * into claim from tongs.reference_visual_evidence_claims c
    where c.workspace_id=p_workspace_id and c.workpiece_id=p_workpiece_id
      and c.opportunity_id=p_opportunity_id and c.claim_fingerprint=computed_claim_fingerprint;
  if found then
    select e.* into current_claim_revision
    from tongs.reference_visual_evidence_sequences s
    join tongs.reference_visual_evidence_revisions e on e.id=s.current_evidence_revision_id
    where s.workspace_id=p_workspace_id and s.workpiece_id=p_workpiece_id
      and s.evidence_id=claim.canonical_evidence_id;
    if current_claim_revision.id is null then
      return jsonb_build_object('disposition','canonical_claim_not_current');
    end if;
    result:=jsonb_build_object(
      'disposition','replay','canonical_claim_id',claim.claim_id,
      'canonical_evidence_id',claim.canonical_evidence_id,
      'canonical_evidence_revision_id',current_claim_revision.id,
      'canonical_evidence_revision',current_claim_revision.revision,
      'claim_fingerprint',computed_claim_fingerprint,
      'evidence_revision',to_jsonb(current_claim_revision)
    );
    insert into tongs.reference_visual_operation_receipts(
      operation_id,operation_fingerprint,operation_type,workspace_id,workpiece_id,
      state,result_revision_id,receipt_json,created_by,created_at
    ) values(p_operation_id,p_operation_fingerprint,'evidence_commit',p_workspace_id,p_workpiece_id,
      'committed',current_claim_revision.id,result,p_actor_id,now());
    return result;
  end if;
  select * into seq from tongs.reference_visual_evidence_sequences
    where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and evidence_id=p_evidence_id for update;
  if coalesce(seq.current_evidence_revision,0)<>p_expected_revision then
    return jsonb_build_object('disposition','evidence_revision_conflict','current_revision',coalesce(seq.current_evidence_revision,0));
  end if;
  if p_expected_revision>0 then
    select * into prev from tongs.reference_visual_evidence_revisions where id=seq.current_evidence_revision_id;
  end if;
  n:=p_expected_revision+1;
  h:=encode(extensions.digest(convert_to(jsonb_strip_nulls(jsonb_build_object(
    'source_revision_id',source_revision.id,'source_link_revision_id',source_link.id,
    'evidence',p_evidence,'confirmation_state',p_confirmation_state,'evidence_intent',intent
  ))::text,'UTF8'),'sha256'),'hex');
  ih:=encode(extensions.digest(convert_to(jsonb_build_object(
    'content_hash',h,'revision',n,'previous_revision_id',prev.id
  )::text,'UTF8'),'sha256'),'hex');
  insert into tongs.reference_visual_evidence_revisions(
    evidence_id,workspace_id,workpiece_id,opportunity_id,revision,previous_revision_id,previous_revision,
    source_revision_id,source_revision,workpiece_source_link_revision_id,workpiece_source_link_revision,
    evidence_role,origin,confirmation_state,confirmed_by,confirmed_at,citation_anchor_json,
    document_locator_json,media_range_json,raw_excerpt,numeric_value,unit,evidence_date,category,label,
    derivation_formula,rounding_rule,excerpt_content_hash,content_hash,immutable_revision_hash,created_by,
    source_set_member_id,evidence_intent
  ) values(
    p_evidence_id,p_workspace_id,p_workpiece_id,p_opportunity_id,n,prev.id,prev.revision,
    source_revision.id,source_revision.revision,source_link.id,source_link.revision,
    p_evidence->>'evidence_role',coalesce(p_evidence->>'origin','creator_entered'),p_confirmation_state,
    case when p_confirmation_state='creator_confirmed' then p_actor_id end,
    case when p_confirmation_state='creator_confirmed' then now() end,
    coalesce(p_evidence->'citation_anchor','{}'),coalesce(p_evidence->'document_locator','{}'),
    coalesce(p_evidence->'media_range','{}'),p_evidence->>'raw_excerpt',numeric_value,p_evidence->>'unit',
    nullif(p_evidence->>'date','')::date,p_evidence->>'category',p_evidence->>'label',
    p_evidence->>'derivation_formula',p_evidence->>'rounding_rule',lower(p_evidence->>'excerpt_content_hash'),
    h,ih,p_actor_id,source_member.id,intent
  ) returning * into revision_row;
  insert into tongs.reference_visual_evidence_sequences
    values(p_workspace_id,p_workpiece_id,p_evidence_id,revision_row.id,revision_row.revision,now())
  on conflict(workspace_id,workpiece_id,evidence_id) do update set
    current_evidence_revision_id=excluded.current_evidence_revision_id,
    current_evidence_revision=excluded.current_evidence_revision,updated_at=now();
  insert into tongs.reference_visual_evidence_claims(
    workspace_id,workpiece_id,opportunity_id,source_set_member_id,source_revision_id,
    workpiece_source_link_revision_id,claim_fingerprint,canonical_evidence_id,created_by
  ) values(
    p_workspace_id,p_workpiece_id,p_opportunity_id,source_member.id,source_revision.id,
    source_link.id,computed_claim_fingerprint,p_evidence_id,p_actor_id
  ) returning * into claim;
  result:=jsonb_build_object(
    'disposition','committed','canonical_claim_id',claim.claim_id,
    'canonical_evidence_id',p_evidence_id,'canonical_evidence_revision_id',revision_row.id,
    'canonical_evidence_revision',revision_row.revision,'claim_fingerprint',computed_claim_fingerprint,
    'evidence_revision',to_jsonb(revision_row)
  );
  insert into tongs.reference_visual_operation_receipts(
    operation_id,operation_fingerprint,operation_type,workspace_id,workpiece_id,
    state,result_revision_id,receipt_json,created_by,created_at
  ) values(p_operation_id,p_operation_fingerprint,'evidence_commit',p_workspace_id,p_workpiece_id,
    'committed',revision_row.id,result,p_actor_id,now());
  return result;
end$$;


ALTER FUNCTION "tongs"."commit_reference_visual_evidence"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_opportunity_id" "uuid", "p_evidence_id" "uuid", "p_expected_revision" bigint, "p_source_revision_id" "uuid", "p_workpiece_source_link_revision_id" "uuid", "p_evidence" "jsonb", "p_confirmation_state" "text", "p_operation_id" "text", "p_operation_fingerprint" "text", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."commit_reference_visual_plan"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_expected_revision_id" "uuid", "p_expected_revision" bigint, "p_script_approval_id" "uuid", "p_contract_version" "text", "p_opportunities" "jsonb", "p_operation_id" "text", "p_operation_fingerprint" "text", "p_actor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare op tongs.reference_visual_operation_receipts%rowtype;seq tongs.reference_visual_plan_sequences%rowtype;approval tongs.script_approval_revisions%rowtype;plan tongs.reference_visual_plan_revisions%rowtype;item jsonb;opp tongs.reference_visual_opportunity_revisions%rowtype;prev tongs.reference_visual_opportunity_revisions%rowtype;oid uuid;n bigint;ordinal integer:=0;h text;ih text;result jsonb;begin
 if not tongs.has_workspace_role(p_workspace_id,'editor') or auth.uid() is distinct from p_actor_id then raise exception 'workspace editor authority required' using errcode='42501';end if;if jsonb_typeof(p_opportunities)<>'array' then return jsonb_build_object('disposition','opportunities_array_required');end if;perform pg_advisory_xact_lock(hashtextextended(p_operation_id,0));select * into op from tongs.reference_visual_operation_receipts where operation_id=p_operation_id;if found then if op.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict');end if;return op.receipt_json;end if;
 select * into approval from tongs.script_approval_revisions where id=p_script_approval_id and workspace_id=p_workspace_id and workpiece_id=p_workpiece_id; if not found then return jsonb_build_object('disposition','script_approval_not_found');end if;select * into seq from tongs.reference_visual_plan_sequences where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id for update;if coalesce(seq.current_plan_revision,0)<>p_expected_revision or seq.current_plan_revision_id is distinct from p_expected_revision_id then return jsonb_build_object('disposition','plan_revision_conflict','current_revision_id',seq.current_plan_revision_id,'current_revision',coalesce(seq.current_plan_revision,0));end if;n:=p_expected_revision+1;h:=encode(extensions.digest(convert_to(p_opportunities::text,'UTF8'),'sha256'),'hex');ih:=encode(extensions.digest(convert_to(jsonb_build_object('content_hash',h,'revision',n,'previous_revision_id',seq.current_plan_revision_id,'script_approval_id',approval.id)::text,'UTF8'),'sha256'),'hex');insert into tongs.reference_visual_plan_revisions(workspace_id,workpiece_id,revision,previous_revision_id,previous_revision,script_approval_id,script_approval_revision,script_content_hash,contract_version,content_hash,immutable_revision_hash,created_by)values(p_workspace_id,p_workpiece_id,n,seq.current_plan_revision_id,nullif(p_expected_revision,0),approval.id,approval.approval_revision,approval.script_content_hash,p_contract_version,h,ih,p_actor_id)returning * into plan;
 for item in select value from jsonb_array_elements(p_opportunities)loop oid:=coalesce((item->>'opportunity_id')::uuid,gen_random_uuid());select * into prev from tongs.reference_visual_opportunity_revisions where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and opportunity_id=oid order by revision desc limit 1;if coalesce(item->>'source_status','unresolved')='linked' then if not exists(select 1 from tongs.source_revisions sr join tongs.workpiece_source_link_revisions lr on lr.id=(item->>'workpiece_source_link_revision_id')::uuid and lr.source_revision_id=sr.id where sr.id=(item->>'source_revision_id')::uuid and sr.workspace_id=p_workspace_id and lr.workpiece_id=p_workpiece_id)then return jsonb_build_object('disposition','canonical_source_evidence_required');end if;end if;h:=encode(extensions.digest(convert_to(jsonb_strip_nulls(item)::text,'UTF8'),'sha256'),'hex');ih:=encode(extensions.digest(convert_to(jsonb_build_object('content_hash',h,'revision',coalesce(prev.revision,0)+1,'previous_revision_id',prev.id)::text,'UTF8'),'sha256'),'hex');insert into tongs.reference_visual_opportunity_revisions(opportunity_id,workspace_id,workpiece_id,revision,previous_revision_id,previous_revision,source_plan_revision_id,source_plan_revision,script_approval_id,script_approval_revision,source_status,source_revision_id,source_revision,workpiece_source_link_revision_id,workpiece_source_link_revision,visual_subtype,context_before,context_focus,context_after,citation_anchor_json,document_locator_json,media_range_json,editorial_reason,desired_material,search_terms,placement_hint,duration_target_ms,creator_direction,content_hash,immutable_revision_hash,created_by)values(oid,p_workspace_id,p_workpiece_id,coalesce(prev.revision,0)+1,prev.id,prev.revision,plan.id,plan.revision,approval.id,approval.approval_revision,coalesce(item->>'source_status','unresolved'),(item->>'source_revision_id')::uuid,nullif(item->>'source_revision','')::bigint,(item->>'workpiece_source_link_revision_id')::uuid,nullif(item->>'workpiece_source_link_revision','')::bigint,item->>'visual_subtype',coalesce(item->>'context_before',''),item->>'context_focus',coalesce(item->>'context_after',''),coalesce(item->'citation_anchor','{}'),coalesce(item->'document_locator','{}'),coalesce(item->'media_range','{}'),item->>'editorial_reason',item->>'desired_material',coalesce(item->'search_terms','[]'),item->>'placement_hint',coalesce((item->>'duration_target_ms')::bigint,5000),item->>'creator_direction',h,ih,p_actor_id)returning * into opp;insert into tongs.reference_visual_plan_membership values(plan.id,p_workspace_id,p_workpiece_id,plan.revision,ordinal,oid,opp.id,opp.revision);ordinal:=ordinal+1;end loop;
 insert into tongs.reference_visual_plan_sequences values(p_workspace_id,p_workpiece_id,plan.id,plan.revision,now())on conflict(workspace_id,workpiece_id)do update set current_plan_revision_id=excluded.current_plan_revision_id,current_plan_revision=excluded.current_plan_revision,updated_at=now();result:=jsonb_build_object('disposition','committed','plan_revision',to_jsonb(plan));insert into tongs.reference_visual_operation_receipts values(p_operation_id,p_operation_fingerprint,'plan_commit',p_workspace_id,p_workpiece_id,'committed',plan.id,result,p_actor_id,now());return result;end$$;


ALTER FUNCTION "tongs"."commit_reference_visual_plan"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_expected_revision_id" "uuid", "p_expected_revision" bigint, "p_script_approval_id" "uuid", "p_contract_version" "text", "p_opportunities" "jsonb", "p_operation_id" "text", "p_operation_fingerprint" "text", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."commit_reference_visual_recipe"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_opportunity_id" "uuid", "p_recipe_id" "uuid", "p_expected_revision" bigint, "p_prompt_source" "text", "p_visual_subtype" "text", "p_title" "text", "p_subtitle" "text", "p_recipe_json" "jsonb", "p_evidence_revision_ids" "uuid"[], "p_attribution_text" "text", "p_aspect_ratio" "text", "p_accessibility_text" "text", "p_brand_treatment" "jsonb", "p_safe_areas" "jsonb", "p_animation_hints" "jsonb", "p_renderer_contract_version" "text", "p_operation_id" "text", "p_operation_fingerprint" "text", "p_actor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare op tongs.reference_visual_operation_receipts%rowtype;seq tongs.reference_visual_recipe_sequences%rowtype;prev tongs.reference_visual_recipe_revisions%rowtype;recipe_rev tongs.reference_visual_recipe_revisions%rowtype;n bigint;h text;ih text;result jsonb;
begin
 if not tongs.has_workspace_role(p_workspace_id,'editor')or auth.uid() is distinct from p_actor_id then raise exception 'workspace editor authority required'using errcode='42501';end if;perform pg_advisory_xact_lock(hashtextextended(p_operation_id,0));select * into op from tongs.reference_visual_operation_receipts where operation_id=p_operation_id;if found then if op.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict');end if;return op.receipt_json;end if;
 if exists(select 1 from unnest(p_evidence_revision_ids)e(id)left join tongs.reference_visual_evidence_revisions ev on ev.id=e.id and ev.workspace_id=p_workspace_id and ev.workpiece_id=p_workpiece_id and ev.opportunity_id=p_opportunity_id and ev.confirmation_state='creator_confirmed'where ev.id is null)then return jsonb_build_object('disposition','confirmed_evidence_required');end if;
 select * into seq from tongs.reference_visual_recipe_sequences where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and opportunity_id=p_opportunity_id for update;if coalesce(seq.current_recipe_revision,0)<>p_expected_revision then return jsonb_build_object('disposition','recipe_revision_conflict','current_revision',coalesce(seq.current_recipe_revision,0));end if;if p_expected_revision>0 then select * into prev from tongs.reference_visual_recipe_revisions where id=seq.current_recipe_revision_id;end if;n:=p_expected_revision+1;h:=encode(extensions.digest(convert_to(jsonb_strip_nulls(jsonb_build_object('subtype',p_visual_subtype,'title',p_title,'subtitle',p_subtitle,'recipe',p_recipe_json,'evidence_revision_ids',p_evidence_revision_ids,'attribution',p_attribution_text,'aspect_ratio',p_aspect_ratio,'accessibility',p_accessibility_text,'brand',p_brand_treatment,'safe_areas',p_safe_areas,'animation',p_animation_hints,'renderer_contract_version',p_renderer_contract_version))::text,'UTF8'),'sha256'),'hex');ih:=encode(extensions.digest(convert_to(jsonb_build_object('content_hash',h,'revision',n,'previous_revision_id',prev.id)::text,'UTF8'),'sha256'),'hex');
 insert into tongs.reference_visual_recipe_revisions(recipe_id,workspace_id,workpiece_id,opportunity_id,revision,previous_revision_id,previous_revision,prompt_source,visual_subtype,title,subtitle,recipe_json,evidence_revision_ids,attribution_text,aspect_ratio,accessibility_text,brand_treatment_json,safe_areas_json,animation_hints_json,renderer_contract_version,content_hash,immutable_revision_hash,created_by)values(p_recipe_id,p_workspace_id,p_workpiece_id,p_opportunity_id,n,prev.id,prev.revision,p_prompt_source,p_visual_subtype,p_title,p_subtitle,p_recipe_json,p_evidence_revision_ids,p_attribution_text,p_aspect_ratio,p_accessibility_text,coalesce(p_brand_treatment,'{}'),coalesce(p_safe_areas,'{}'),coalesce(p_animation_hints,'{}'),p_renderer_contract_version,h,ih,p_actor_id)returning * into recipe_rev;
 insert into tongs.reference_visual_recipe_sequences values(p_workspace_id,p_workpiece_id,p_opportunity_id,p_recipe_id,recipe_rev.id,recipe_rev.revision,now())on conflict(workspace_id,workpiece_id,opportunity_id)do update set recipe_id=excluded.recipe_id,current_recipe_revision_id=excluded.current_recipe_revision_id,current_recipe_revision=excluded.current_recipe_revision,updated_at=now();result:=jsonb_build_object('disposition','committed','recipe_revision',to_jsonb(recipe_rev));insert into tongs.reference_visual_operation_receipts values(p_operation_id,p_operation_fingerprint,'recipe_commit',p_workspace_id,p_workpiece_id,'committed',recipe_rev.id,result,p_actor_id,now());return result;
end$$;


ALTER FUNCTION "tongs"."commit_reference_visual_recipe"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_opportunity_id" "uuid", "p_recipe_id" "uuid", "p_expected_revision" bigint, "p_prompt_source" "text", "p_visual_subtype" "text", "p_title" "text", "p_subtitle" "text", "p_recipe_json" "jsonb", "p_evidence_revision_ids" "uuid"[], "p_attribution_text" "text", "p_aspect_ratio" "text", "p_accessibility_text" "text", "p_brand_treatment" "jsonb", "p_safe_areas" "jsonb", "p_animation_hints" "jsonb", "p_renderer_contract_version" "text", "p_operation_id" "text", "p_operation_fingerprint" "text", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."commit_reference_visual_render"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_path" "text", "p_mime_type" "text", "p_byte_size" bigint, "p_content_hash" "text", "p_storage_bucket" "text", "p_storage_key" "text", "p_width" integer, "p_height" integer, "p_render_evidence" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $_$
declare op tongs.reference_visual_render_operations%rowtype;a tongs.assets%rowtype;c tongs.reference_visual_candidates%rowtype;
 r tongs.reference_visual_candidate_revisions%rowtype;recipe tongs.reference_visual_recipe_revisions%rowtype;h text;ih text;receipt jsonb;
begin
 if auth.role()<>'service_role'then raise exception 'Reference Visual render commit requires service authority'using errcode='42501';end if;
 select * into op from tongs.reference_visual_render_operations where operation_id=p_operation_id for update;
 if not found then return jsonb_build_object('disposition','operation_not_found');end if;
 if op.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict');end if;
 if op.state='candidate_committed'then return op.receipt_json;end if;
 if op.source_set_revision_id is null then return jsonb_build_object('disposition','source_set_authority_required');end if;
 if p_mime_type not in('image/png','image/svg+xml')or p_byte_size<=0 or p_content_hash!~'^[0-9a-f]{64}$'or p_width<=0 or p_height<=0 then return jsonb_build_object('disposition','invalid_verified_render_evidence');end if;
 select * into recipe from tongs.reference_visual_recipe_revisions where id=op.recipe_revision_id;
 select * into a from tongs.assets where workspace_id=op.workspace_id and workpiece_id=op.workpiece_id and operation_id=p_operation_id and asset_kind='reference_visual_image'for update;
 if found then if a.content_hash<>p_content_hash or a.storage_bucket<>p_storage_bucket or a.storage_key<>p_storage_key or a.bytes<>p_byte_size then return jsonb_build_object('disposition','asset_replay_conflict');end if;
 else insert into tongs.assets(workspace_id,workpiece_id,path,mime_type,bytes,storage_bucket,storage_key,provider,provider_request_id,request_id,created_by,asset_kind,status,metadata_json,width,height,operation_id,operation_fingerprint,content_hash,ready_at)
 values(op.workspace_id,op.workpiece_id,p_path,p_mime_type,p_byte_size,p_storage_bucket,p_storage_key,op.renderer_name,p_operation_id,p_operation_id,op.created_by,'reference_visual_image','ready',jsonb_build_object('renderer_name',op.renderer_name,'renderer_version',op.renderer_version,'recipe_revision_id',op.recipe_revision_id,'source_set_revision_id',op.source_set_revision_id,'source_use_revision_id',op.source_use_revision_id),p_width,p_height,p_operation_id,p_operation_fingerprint,p_content_hash,now())returning * into a;end if;
 insert into tongs.reference_visual_candidates(workspace_id,workpiece_id,opportunity_id,created_by)select op.workspace_id,op.workpiece_id,o.opportunity_id,op.created_by from tongs.reference_visual_opportunity_revisions o where o.id=op.opportunity_revision_id returning * into c;
 h:=encode(extensions.digest(convert_to(jsonb_build_object('asset_hash',a.content_hash,'opportunity_revision_id',op.opportunity_revision_id,'source_set_revision_id',op.source_set_revision_id,'recipe_revision_id',recipe.id,'source_use_revision_id',op.source_use_revision_id,'rights_revision_id',op.rights_declaration_revision_id,'renderer',op.renderer_name,'renderer_version',op.renderer_version,'render_evidence',p_render_evidence)::text,'UTF8'),'sha256'),'hex');
 ih:=encode(extensions.digest(convert_to(jsonb_build_object('candidate_id',c.id,'revision',1,'content_hash',h,'operation_id',p_operation_id)::text,'UTF8'),'sha256'),'hex');
 insert into tongs.reference_visual_candidate_revisions(candidate_id,workspace_id,workpiece_id,opportunity_id,revision,opportunity_revision_id,opportunity_revision,source_set_revision_id,recipe_revision_id,recipe_revision,candidate_kind,asset_id,source_use_revision_id,rights_declaration_revision_id,renderer_name,renderer_version,canonical_render_hash,render_receipt_json,provenance_json,content_hash,immutable_revision_hash,created_by)
 select c.id,op.workspace_id,op.workpiece_id,o.opportunity_id,1,o.id,o.revision,op.source_set_revision_id,recipe.id,recipe.revision,'rendered_visual',a.id,op.source_use_revision_id,op.rights_declaration_revision_id,op.renderer_name,op.renderer_version,p_content_hash,p_render_evidence,jsonb_build_object('authority','tongs-render-v3','operation_id',p_operation_id,'source_set_revision_id',op.source_set_revision_id,'source_use_revision_id',op.source_use_revision_id),h,ih,op.created_by from tongs.reference_visual_opportunity_revisions o where o.id=op.opportunity_revision_id returning * into r;
 receipt:=jsonb_build_object('disposition','committed','operation_id',p_operation_id,'opportunity_revision_id',op.opportunity_revision_id,'source_set_revision_id',op.source_set_revision_id,'recipe_revision_id',recipe.id,'source_use_revision_id',op.source_use_revision_id,'rights_declaration_revision_id',op.rights_declaration_revision_id,'renderer_name',op.renderer_name,'renderer_version',op.renderer_version,'asset',to_jsonb(a),'candidate_revision',to_jsonb(r));
 update tongs.reference_visual_render_operations set state='candidate_committed',render_evidence_json=p_render_evidence,output_asset_id=a.id,result_candidate_revision_id=r.id,failed_stage=null,failure_code=null,failure_message=null,receipt_json=receipt,updated_at=now()where operation_id=p_operation_id;return receipt;
end$_$;


ALTER FUNCTION "tongs"."commit_reference_visual_render"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_path" "text", "p_mime_type" "text", "p_byte_size" bigint, "p_content_hash" "text", "p_storage_bucket" "text", "p_storage_key" "text", "p_width" integer, "p_height" integer, "p_render_evidence" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."commit_reference_visual_rights_declaration"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_opportunity_id" "uuid", "p_declaration_id" "uuid", "p_expected_revision" bigint, "p_rights_status" "text", "p_declaration" "jsonb", "p_operation_id" "text", "p_operation_fingerprint" "text", "p_actor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
 select tongs.commit_reference_visual_rights_declaration(p_workspace_id,p_workpiece_id,p_opportunity_id,
   tongs.reference_visual_current_source_set(p_workspace_id,p_workpiece_id,p_opportunity_id),p_declaration_id,
   p_expected_revision,p_rights_status,p_declaration,p_operation_id,p_operation_fingerprint,p_actor_id)
$$;


ALTER FUNCTION "tongs"."commit_reference_visual_rights_declaration"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_opportunity_id" "uuid", "p_declaration_id" "uuid", "p_expected_revision" bigint, "p_rights_status" "text", "p_declaration" "jsonb", "p_operation_id" "text", "p_operation_fingerprint" "text", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."commit_reference_visual_rights_declaration"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_opportunity_id" "uuid", "p_source_set_revision_id" "uuid", "p_declaration_id" "uuid", "p_expected_revision" bigint, "p_rights_status" "text", "p_declaration" "jsonb", "p_operation_id" "text", "p_operation_fingerprint" "text", "p_actor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare op tongs.reference_visual_operation_receipts%rowtype;seq tongs.reference_visual_rights_declaration_sequences%rowtype;
 prev tongs.reference_visual_rights_declaration_revisions%rowtype;r tongs.reference_visual_rights_declaration_revisions%rowtype;
 n bigint;h text;ih text;result jsonb;current_set uuid;
begin
 if not tongs.has_workspace_role(p_workspace_id,'editor') or auth.uid() is distinct from p_actor_id then raise exception 'workspace editor authority required' using errcode='42501';end if;
 current_set:=tongs.reference_visual_current_source_set(p_workspace_id,p_workpiece_id,p_opportunity_id);
 if current_set is null or current_set is distinct from p_source_set_revision_id then return jsonb_build_object('disposition','current_source_collection_required','current_source_set_revision_id',current_set);end if;
 if coalesce((p_declaration->>'creator_acknowledged_responsibility')::boolean,false) is not true then return jsonb_build_object('disposition','creator_rights_acknowledgement_required');end if;
 if coalesce((p_declaration->>'access_controls_bypassed')::boolean,false) then return jsonb_build_object('disposition','access_control_circumvention_prohibited');end if;
 perform pg_advisory_xact_lock(hashtextextended(p_operation_id,0));
 select * into op from tongs.reference_visual_operation_receipts where operation_id=p_operation_id;
 if found then if op.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict');end if;return op.receipt_json;end if;
 select * into seq from tongs.reference_visual_rights_declaration_sequences where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and opportunity_id=p_opportunity_id for update;
 if p_expected_revision=0 and coalesce(seq.current_declaration_revision,0)>0
   and not tongs.reference_visual_rights_current_for_source_set(seq.current_declaration_revision_id,current_set) then
   p_expected_revision:=seq.current_declaration_revision;
   p_declaration_id:=seq.declaration_id;
 end if;
 if coalesce(seq.current_declaration_revision,0)<>p_expected_revision then return jsonb_build_object('disposition','rights_revision_conflict','current_revision',coalesce(seq.current_declaration_revision,0));end if;
 if p_expected_revision>0 then select * into prev from tongs.reference_visual_rights_declaration_revisions where id=seq.current_declaration_revision_id;end if;
 n:=p_expected_revision+1;
 h:=encode(extensions.digest(convert_to(jsonb_strip_nulls(jsonb_build_object('source_set_revision_id',current_set,'rights_status',p_rights_status,'declaration',p_declaration,'asserted_by',p_actor_id))::text,'UTF8'),'sha256'),'hex');
 ih:=encode(extensions.digest(convert_to(jsonb_build_object('content_hash',h,'revision',n,'previous_revision_id',prev.id)::text,'UTF8'),'sha256'),'hex');
 insert into tongs.reference_visual_rights_declaration_revisions(declaration_id,workspace_id,workpiece_id,opportunity_id,revision,previous_revision_id,previous_revision,source_set_revision_id,rights_status,asserted_by,creator_acknowledged_responsibility,rights_holder,license_identifier,license_url,permission_evidence_json,platform_terms_json,fair_use_rationale,territories,expires_at,attribution_required,attribution_text,provenance_json,access_controls_bypassed,content_hash,immutable_revision_hash)
 values(p_declaration_id,p_workspace_id,p_workpiece_id,p_opportunity_id,n,prev.id,prev.revision,current_set,p_rights_status,p_actor_id,true,p_declaration->>'rights_holder',p_declaration->>'license_identifier',p_declaration->>'license_url',coalesce(p_declaration->'permission_evidence','{}'),coalesce(p_declaration->'platform_terms','{}'),p_declaration->>'fair_use_rationale',case when jsonb_typeof(p_declaration->'territories')='array' then array(select jsonb_array_elements_text(p_declaration->'territories')) end,nullif(p_declaration->>'expires_at','')::timestamptz,coalesce((p_declaration->>'attribution_required')::boolean,false),p_declaration->>'attribution_text',coalesce(p_declaration->'provenance','{}'),false,h,ih)returning * into r;
 insert into tongs.reference_visual_rights_declaration_sequences values(p_workspace_id,p_workpiece_id,p_opportunity_id,p_declaration_id,r.id,r.revision,now()) on conflict(workspace_id,workpiece_id,opportunity_id)do update set declaration_id=excluded.declaration_id,current_declaration_revision_id=excluded.current_declaration_revision_id,current_declaration_revision=excluded.current_declaration_revision,updated_at=now();
 result:=jsonb_build_object('disposition','committed','rights_declaration_revision',to_jsonb(r),'release_ready',p_rights_status<>'rights_unresolved');
 insert into tongs.reference_visual_operation_receipts values(p_operation_id,p_operation_fingerprint,'rights_commit',p_workspace_id,p_workpiece_id,'committed',r.id,result,p_actor_id,now());return result;
end$$;


ALTER FUNCTION "tongs"."commit_reference_visual_rights_declaration"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_opportunity_id" "uuid", "p_source_set_revision_id" "uuid", "p_declaration_id" "uuid", "p_expected_revision" bigint, "p_rights_status" "text", "p_declaration" "jsonb", "p_operation_id" "text", "p_operation_fingerprint" "text", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."commit_reference_visual_sequence"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_opportunity_revision_id" "uuid", "p_sequence_id" "uuid", "p_expected_revision" bigint, "p_rights_declaration_revision_id" "uuid", "p_members" "jsonb", "p_operation_id" "text", "p_operation_fingerprint" "text", "p_actor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$declare op tongs.reference_visual_operation_receipts%rowtype;seq tongs.reference_visual_sequence_sequences%rowtype;prev tongs.reference_visual_sequence_revisions%rowtype;s tongs.reference_visual_sequence_revisions%rowtype;o tongs.reference_visual_opportunity_revisions%rowtype;item jsonb;ord integer:=0;c tongs.reference_visual_candidates%rowtype;r tongs.reference_visual_candidate_revisions%rowtype;h text;ih text;result jsonb;begin if not tongs.has_workspace_role(p_workspace_id,'editor')or auth.uid() is distinct from p_actor_id then raise exception 'workspace editor authority required' using errcode='42501';end if;if jsonb_typeof(p_members)<>'array'or jsonb_array_length(p_members)<2 then return jsonb_build_object('disposition','sequence_members_required');end if;perform pg_advisory_xact_lock(hashtextextended(p_operation_id,0));select * into op from tongs.reference_visual_operation_receipts where operation_id=p_operation_id;if found then if op.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict');end if;return op.receipt_json;end if;select * into o from tongs.reference_visual_opportunity_revisions where id=p_opportunity_revision_id and workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and visual_subtype='archival_sequence';if not found then return jsonb_build_object('disposition','current_archival_sequence_required');end if;if not exists(select 1 from tongs.reference_visual_plan_sequences ps join lateral(select ss.id from tongs.reference_visual_source_set_revisions ss where ss.workspace_id=p_workspace_id and ss.workpiece_id=p_workpiece_id and ss.opportunity_id=o.opportunity_id and ss.plan_revision_id=ps.current_plan_revision_id order by ss.revision desc limit 1)current_set on true join tongs.reference_visual_source_set_members sm on sm.source_set_revision_id=current_set.id where ps.workspace_id=p_workspace_id and ps.workpiece_id=p_workpiece_id)then return jsonb_build_object('disposition','current_source_collection_required');end if;if not exists(select 1 from tongs.reference_visual_rights_declaration_sequences where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and opportunity_id=o.opportunity_id and current_declaration_revision_id=p_rights_declaration_revision_id)then return jsonb_build_object('disposition','current_rights_declaration_required');end if;select * into seq from tongs.reference_visual_sequence_sequences where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and opportunity_id=o.opportunity_id for update;if coalesce(seq.current_sequence_revision,0)<>p_expected_revision then return jsonb_build_object('disposition','sequence_revision_conflict','current_revision',coalesce(seq.current_sequence_revision,0));end if;if p_expected_revision>0 then select * into prev from tongs.reference_visual_sequence_revisions where id=seq.current_sequence_revision_id;end if;if exists(select 1 from jsonb_array_elements(p_members)x left join tongs.assets a on a.id=(x->>'asset_id')::uuid and a.workspace_id=p_workspace_id and a.workpiece_id=p_workpiece_id and a.status='ready' and a.mime_type like'image/%' left join tongs.source_revisions sr on sr.id=(x->>'source_revision_id')::uuid and sr.workspace_id=p_workspace_id left join tongs.workpiece_source_link_revisions lr on lr.id=(x->>'workpiece_source_link_revision_id')::uuid and lr.workpiece_id=p_workpiece_id and lr.source_revision_id=sr.id where a.id is null or sr.id is null or lr.id is null)then return jsonb_build_object('disposition','canonical_sequence_member_evidence_required');end if;h:=encode(extensions.digest(convert_to(p_members::text,'UTF8'),'sha256'),'hex');ih:=encode(extensions.digest(convert_to(jsonb_build_object('content_hash',h,'revision',p_expected_revision+1,'previous_revision_id',prev.id)::text,'UTF8'),'sha256'),'hex');insert into tongs.reference_visual_sequence_revisions(sequence_id,workspace_id,workpiece_id,opportunity_id,revision,previous_revision_id,previous_revision,content_hash,immutable_revision_hash,created_by)values(p_sequence_id,p_workspace_id,p_workpiece_id,o.opportunity_id,p_expected_revision+1,prev.id,prev.revision,h,ih,p_actor_id)returning * into s;for item in select value from jsonb_array_elements(p_members)loop insert into tongs.reference_visual_sequence_membership values(s.id,p_workspace_id,p_workpiece_id,ord,(item->>'asset_id')::uuid,(item->>'source_revision_id')::uuid,(item->>'workpiece_source_link_revision_id')::uuid,nullif(item->>'duration_ms','')::bigint,coalesce(item->'transition_hints','{}'));ord:=ord+1;end loop;insert into tongs.reference_visual_sequence_sequences values(p_workspace_id,p_workpiece_id,o.opportunity_id,p_sequence_id,s.id,s.revision,now())on conflict(workspace_id,workpiece_id,opportunity_id)do update set sequence_id=excluded.sequence_id,current_sequence_revision_id=excluded.current_sequence_revision_id,current_sequence_revision=excluded.current_sequence_revision,updated_at=now();insert into tongs.reference_visual_candidates(workspace_id,workpiece_id,opportunity_id,created_by)values(p_workspace_id,p_workpiece_id,o.opportunity_id,p_actor_id)returning * into c;h:=encode(extensions.digest(convert_to(jsonb_build_object('sequence_revision_id',s.id,'rights_revision_id',p_rights_declaration_revision_id)::text,'UTF8'),'sha256'),'hex');ih:=encode(extensions.digest(convert_to(jsonb_build_object('candidate',c.id,'revision',1,'content_hash',h)::text,'UTF8'),'sha256'),'hex');insert into tongs.reference_visual_candidate_revisions(candidate_id,workspace_id,workpiece_id,opportunity_id,revision,opportunity_revision_id,opportunity_revision,candidate_kind,sequence_revision_id,rights_declaration_revision_id,render_receipt_json,provenance_json,content_hash,immutable_revision_hash,created_by)values(c.id,p_workspace_id,p_workpiece_id,o.opportunity_id,1,o.id,o.revision,'archival_sequence',s.id,p_rights_declaration_revision_id,'{}',jsonb_build_object('authority','tongs-sequence-v1'),h,ih,p_actor_id)returning * into r;result:=jsonb_build_object('disposition','committed','sequence_revision',to_jsonb(s),'candidate_revision',to_jsonb(r));insert into tongs.reference_visual_operation_receipts values(p_operation_id,p_operation_fingerprint,'sequence_commit',p_workspace_id,p_workpiece_id,'committed',s.id,result,p_actor_id,now());return result;end$$;


ALTER FUNCTION "tongs"."commit_reference_visual_sequence"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_opportunity_revision_id" "uuid", "p_sequence_id" "uuid", "p_expected_revision" bigint, "p_rights_declaration_revision_id" "uuid", "p_members" "jsonb", "p_operation_id" "text", "p_operation_fingerprint" "text", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."commit_reference_visual_source_set"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_opportunity_id" "uuid", "p_members" "jsonb", "p_expected_plan_revision_id" "uuid", "p_expected_plan_revision" bigint, "p_expected_source_set_revision" bigint, "p_operation_id" "text", "p_operation_fingerprint" "text", "p_actor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
#variable_conflict use_column
declare seq tongs.reference_visual_plan_sequences%rowtype;membership tongs.reference_visual_plan_membership%rowtype;current_set tongs.reference_visual_source_set_revisions%rowtype;new_set tongs.reference_visual_source_set_revisions%rowtype;prior tongs.reference_visual_source_set_revisions%rowtype;item jsonb;src tongs.source_revisions%rowtype;link_rev tongs.workpiece_source_link_revisions%rowtype;position integer:=0;ids jsonb:='[]'::jsonb;result jsonb;
begin
 if not tongs.has_workspace_role(p_workspace_id,'editor')or auth.uid()is distinct from p_actor_id then raise exception 'workspace editor authority required' using errcode='42501';end if;
 if jsonb_typeof(p_members)<>'array'then return jsonb_build_object('disposition','members_array_required');end if;
 perform pg_advisory_xact_lock(hashtextextended(p_operation_id,0));
 select * into prior from tongs.reference_visual_source_set_revisions where operation_id=p_operation_id;
 if found then if prior.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict');end if;select coalesce(jsonb_agg(jsonb_build_object('source_revision_id',m.source_revision_id,'workpiece_source_link_revision_id',m.workpiece_source_link_revision_id)order by m.ordinal),'[]'::jsonb)into ids from tongs.reference_visual_source_set_members m where m.source_set_revision_id=prior.id;return jsonb_build_object('disposition','committed','source_set_revision',to_jsonb(prior),'members',ids);end if;
 select * into seq from tongs.reference_visual_plan_sequences where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id for update;
 if seq.current_plan_revision_id is distinct from p_expected_plan_revision_id or seq.current_plan_revision<>p_expected_plan_revision then return jsonb_build_object('disposition','plan_revision_conflict');end if;
 select * into membership from tongs.reference_visual_plan_membership where plan_revision_id=seq.current_plan_revision_id and opportunity_id=p_opportunity_id;if not found then return jsonb_build_object('disposition','opportunity_not_current');end if;
 select * into current_set from tongs.reference_visual_source_set_revisions where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and opportunity_id=p_opportunity_id and plan_revision_id=seq.current_plan_revision_id order by revision desc limit 1;
 if coalesce(current_set.revision,0)<>p_expected_source_set_revision then return jsonb_build_object('disposition','source_set_revision_conflict','current_revision',coalesce(current_set.revision,0));end if;
 if exists(select 1 from jsonb_array_elements(p_members)x group by x->>'source_revision_id',x->>'workpiece_source_link_revision_id' having count(*)>1)then return jsonb_build_object('disposition','duplicate_source');end if;
 for item in select value from jsonb_array_elements(p_members)loop
  position:=position+1;
  begin select * into src from tongs.source_revisions where id=(item->>'source_revision_id')::uuid and workspace_id=p_workspace_id;exception when invalid_text_representation then return jsonb_build_object('disposition','invalid_source');end;
  if not found then return jsonb_build_object('disposition','invalid_source');end if;
  begin select * into link_rev from tongs.workpiece_source_link_revisions where id=(item->>'workpiece_source_link_revision_id')::uuid and workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and source_revision_id=src.id;exception when invalid_text_representation then return jsonb_build_object('disposition','invalid_source_link');end;
  if not found then return jsonb_build_object('disposition','invalid_source_link');end if;
 end loop;
 insert into tongs.reference_visual_source_set_revisions(workspace_id,workpiece_id,opportunity_id,plan_revision_id,plan_revision,opportunity_revision_id,opportunity_revision,revision,previous_revision_id,previous_revision,operation_id,operation_fingerprint,created_by)
 values(p_workspace_id,p_workpiece_id,p_opportunity_id,seq.current_plan_revision_id,seq.current_plan_revision,membership.opportunity_revision_id,membership.opportunity_revision,coalesce(current_set.revision,0)+1,current_set.id,current_set.revision,p_operation_id,p_operation_fingerprint,p_actor_id)returning * into new_set;
 position:=0;ids:='[]'::jsonb;
 for item in select value from jsonb_array_elements(p_members)loop position:=position+1;select * into src from tongs.source_revisions where id=(item->>'source_revision_id')::uuid;select * into link_rev from tongs.workpiece_source_link_revisions where id=(item->>'workpiece_source_link_revision_id')::uuid;insert into tongs.reference_visual_source_set_members(source_set_revision_id,workspace_id,workpiece_id,opportunity_id,plan_revision_id,source_set_revision,ordinal,source_revision_id,source_revision,workpiece_source_link_revision_id,workpiece_source_link_revision)values(new_set.id,p_workspace_id,p_workpiece_id,p_opportunity_id,seq.current_plan_revision_id,new_set.revision,position,src.id,src.revision,link_rev.id,link_rev.revision);ids:=ids||jsonb_build_array(jsonb_build_object('source_revision_id',src.id,'workpiece_source_link_revision_id',link_rev.id));end loop;
 result:=jsonb_build_object('disposition','committed','source_set_revision',to_jsonb(new_set),'members',ids);return result;
end$$;


ALTER FUNCTION "tongs"."commit_reference_visual_source_set"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_opportunity_id" "uuid", "p_members" "jsonb", "p_expected_plan_revision_id" "uuid", "p_expected_plan_revision" bigint, "p_expected_source_set_revision" bigint, "p_operation_id" "text", "p_operation_fingerprint" "text", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."commit_reference_visual_source_use"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_opportunity_id" "uuid", "p_use_id" "uuid", "p_expected_revision" bigint, "p_expected_opportunity_revision_id" "uuid", "p_source_revision_id" "uuid", "p_workpiece_source_link_revision_id" "uuid", "p_use_classification" "text", "p_creator_confirmed" boolean, "p_confirmation_note" "text", "p_provenance_json" "jsonb", "p_operation_id" "text", "p_operation_fingerprint" "text", "p_actor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare op tongs.reference_visual_operation_receipts%rowtype;seq tongs.reference_visual_source_use_sequences%rowtype;prev tongs.reference_visual_source_use_revisions%rowtype;opp tongs.reference_visual_opportunity_revisions%rowtype;source_member tongs.reference_visual_source_set_members%rowtype;r tongs.reference_visual_source_use_revisions%rowtype;n bigint;h text;ih text;result jsonb;
begin
 if not tongs.has_workspace_role(p_workspace_id,'editor')or auth.uid() is distinct from p_actor_id then raise exception 'workspace editor authority required' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_operation_id,0));select * into op from tongs.reference_visual_operation_receipts where operation_id=p_operation_id;
 if found then if op.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict');end if;return op.receipt_json;end if;
 select rv.* into opp from tongs.reference_visual_plan_sequences ps join tongs.reference_visual_plan_membership m on m.plan_revision_id=ps.current_plan_revision_id join tongs.reference_visual_opportunity_revisions rv on rv.id=m.opportunity_revision_id where ps.workspace_id=p_workspace_id and ps.workpiece_id=p_workpiece_id and m.opportunity_id=p_opportunity_id for update of rv;
 if not found or opp.id is distinct from p_expected_opportunity_revision_id then return jsonb_build_object('disposition','opportunity_revision_conflict');end if;
 select sm.* into source_member
 from tongs.reference_visual_plan_sequences ps
 join lateral(select ss.* from tongs.reference_visual_source_set_revisions ss where ss.workspace_id=ps.workspace_id and ss.workpiece_id=ps.workpiece_id and ss.plan_revision_id=ps.current_plan_revision_id and ss.opportunity_id=p_opportunity_id order by ss.revision desc limit 1)current_set on true
 join tongs.reference_visual_source_set_members sm on sm.source_set_revision_id=current_set.id
 where ps.workspace_id=p_workspace_id and ps.workpiece_id=p_workpiece_id and sm.source_revision_id=p_source_revision_id and sm.workpiece_source_link_revision_id=p_workpiece_source_link_revision_id;
 if not found then return jsonb_build_object('disposition','linked_source_revision_required');end if;
 if p_use_classification='facts_data_only' and opp.visual_subtype not in('chart','timeline','stat_card','comparison') then return jsonb_build_object('disposition','source_use_incompatible_with_treatment');end if;
 if opp.visual_subtype in('document_excerpt','quote_card') and p_use_classification not in('quoted_or_excerpted_text','mixed') then return jsonb_build_object('disposition','source_use_incompatible_with_treatment');end if;
 if opp.visual_subtype in('archival_still','archival_sequence') and p_use_classification not in('third_party_media','mixed') then return jsonb_build_object('disposition','source_use_incompatible_with_treatment');end if;
 select * into seq from tongs.reference_visual_source_use_sequences where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and opportunity_id=p_opportunity_id for update;
 if coalesce(seq.current_use_revision,0)<>p_expected_revision then return jsonb_build_object('disposition','source_use_revision_conflict','current_revision',coalesce(seq.current_use_revision,0));end if;
 if p_expected_revision>0 then select * into prev from tongs.reference_visual_source_use_revisions where id=seq.current_use_revision_id;end if;n:=p_expected_revision+1;
 h:=encode(extensions.digest(convert_to(jsonb_build_object('opportunity_revision_id',opp.id,'source_set_member_id',source_member.id,'source_revision_id',p_source_revision_id,'workpiece_source_link_revision_id',p_workpiece_source_link_revision_id,'use_classification',p_use_classification,'creator_confirmed',p_creator_confirmed,'confirmation_note',p_confirmation_note,'provenance',coalesce(p_provenance_json,'{}'))::text,'UTF8'),'sha256'),'hex');ih:=encode(extensions.digest(convert_to(jsonb_build_object('use_id',p_use_id,'revision',n,'previous_revision_id',prev.id,'content_hash',h)::text,'UTF8'),'sha256'),'hex');
 insert into tongs.reference_visual_source_use_revisions(use_id,workspace_id,workpiece_id,opportunity_id,revision,previous_revision_id,previous_revision,opportunity_revision_id,source_revision_id,workpiece_source_link_revision_id,use_classification,creator_confirmed,confirmation_note,provenance_json,content_hash,immutable_revision_hash,created_by)values(p_use_id,p_workspace_id,p_workpiece_id,p_opportunity_id,n,prev.id,prev.revision,opp.id,p_source_revision_id,p_workpiece_source_link_revision_id,p_use_classification,p_creator_confirmed,p_confirmation_note,coalesce(p_provenance_json,'{}')||jsonb_build_object('source_set_member_id',source_member.id),h,ih,p_actor_id)returning * into r;
 if r.source_set_member_id is distinct from source_member.id then raise exception 'source-use Source member binding failed' using errcode='23514';end if;
 insert into tongs.reference_visual_source_use_sequences values(p_workspace_id,p_workpiece_id,p_opportunity_id,p_use_id,r.id,r.revision,now())on conflict(workspace_id,workpiece_id,opportunity_id)do update set use_id=excluded.use_id,current_use_revision_id=excluded.current_use_revision_id,current_use_revision=excluded.current_use_revision,updated_at=now();
 result:=jsonb_build_object('disposition','committed','source_use_revision',to_jsonb(r));insert into tongs.reference_visual_operation_receipts values(p_operation_id,p_operation_fingerprint,'source_use_commit',p_workspace_id,p_workpiece_id,'committed',r.id,result,p_actor_id,now());return result;
end$$;


ALTER FUNCTION "tongs"."commit_reference_visual_source_use"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_opportunity_id" "uuid", "p_use_id" "uuid", "p_expected_revision" bigint, "p_expected_opportunity_revision_id" "uuid", "p_source_revision_id" "uuid", "p_workpiece_source_link_revision_id" "uuid", "p_use_classification" "text", "p_creator_confirmed" boolean, "p_confirmation_note" "text", "p_provenance_json" "jsonb", "p_operation_id" "text", "p_operation_fingerprint" "text", "p_actor_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."commit_reference_visual_source_use"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_opportunity_id" "uuid", "p_use_id" "uuid", "p_expected_revision" bigint, "p_expected_opportunity_revision_id" "uuid", "p_source_revision_id" "uuid", "p_workpiece_source_link_revision_id" "uuid", "p_use_classification" "text", "p_creator_confirmed" boolean, "p_confirmation_note" "text", "p_provenance_json" "jsonb", "p_operation_id" "text", "p_operation_fingerprint" "text", "p_actor_id" "uuid") IS 'Commits creator-confirmed Source use against a member of the current canonical Reference Visual Source set.';



CREATE OR REPLACE FUNCTION "tongs"."commit_script_approval_snapshot"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_expected_current_revision" bigint, "p_source_file_path" "text", "p_source_file_revision" bigint, "p_script_text" "text", "p_approval_contract_version" "text", "p_creator_version_label" "text", "p_operation_id" "text", "p_actor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare
  v_sequence tongs.workpiece_script_approval_sequences%rowtype;
  v_current tongs.script_approval_revisions%rowtype;
  v_revision tongs.script_approval_revisions%rowtype;
  v_receipt tongs.hearth_authority_operation_receipts%rowtype;
  v_hash text;
  v_semantic_hash text;
  v_revision_hash text;
  v_fingerprint text;
  v_result jsonb;
begin
  if p_actor_id is null then
    raise exception 'actor is required' using errcode='22023';
  end if;
  if p_source_file_path <> 'script/script.md' or p_script_text is null then
    raise exception 'invalid script approval input' using errcode='22023';
  end if;
  v_hash := encode(extensions.digest(convert_to(p_script_text,'UTF8'),'sha256'),'hex');
  v_semantic_hash := encode(extensions.digest(convert_to(jsonb_build_object(
    'workspace_id',p_workspace_id,'workpiece_id',p_workpiece_id,'source_file_path',p_source_file_path,
    'script_content_hash',v_hash,'script_text',p_script_text,'approval_contract_version',p_approval_contract_version
  )::text,'UTF8'),'sha256'),'hex');
  v_fingerprint := encode(extensions.digest(convert_to(jsonb_build_object(
    'contract','forge.script-approval-operation.v1','workspace_id',p_workspace_id,
    'workpiece_id',p_workpiece_id,'expected_revision',p_expected_current_revision,
    'source_file_path',p_source_file_path,'source_file_revision',p_source_file_revision,
    'script_hash',v_hash,'approval_contract_version',p_approval_contract_version
  )::text,'UTF8'),'sha256'),'hex');

  select * into v_receipt from tongs.hearth_authority_operation_receipts where operation_id=p_operation_id;
  if found then
    if v_receipt.operation_fingerprint <> v_fingerprint then
      return jsonb_build_object('disposition','operation_identity_conflict');
    end if;
    return v_receipt.immutable_result_json;
  end if;

  insert into tongs.workpiece_script_approval_sequences(workspace_id,workpiece_id)
  values(p_workspace_id,p_workpiece_id) on conflict do nothing;
  select * into v_sequence from tongs.workpiece_script_approval_sequences
    where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id for update;
  if v_sequence.current_revision <> p_expected_current_revision then
    return jsonb_build_object('disposition','revision_conflict','current_revision',v_sequence.current_revision,'current_approval_id',v_sequence.current_approval_id);
  end if;
  if v_sequence.current_approval_id is not null then
    select * into v_current from tongs.script_approval_revisions where id=v_sequence.current_approval_id;
    if v_current.semantic_state_hash=v_semantic_hash and v_current.script_content_hash=v_hash and v_current.script_text=p_script_text then
      v_result := jsonb_build_object('disposition','no_change','approval',to_jsonb(v_current));
      insert into tongs.hearth_authority_operation_receipts(
        operation_id,operation_fingerprint,workspace_id,workpiece_id,mutation_kind,
        result_script_approval_id,result_script_approval_revision,immutable_result_json,created_by
      ) values(p_operation_id,v_fingerprint,p_workspace_id,p_workpiece_id,'commit_script_approval',
        v_current.id,v_current.approval_revision,v_result,p_actor_id);
      return v_result;
    end if;
  end if;

  v_revision_hash := encode(extensions.digest(convert_to(jsonb_build_object(
    'semantic_state_hash',v_semantic_hash,'approval_revision',v_sequence.current_revision+1,
    'source_file_revision',p_source_file_revision,'created_at',clock_timestamp()::text,'operation_id',p_operation_id
  )::text,'UTF8'),'sha256'),'hex');
  insert into tongs.script_approval_revisions(
    workspace_id,workpiece_id,approval_revision,source_file_path,source_file_revision,
    script_content_hash,semantic_state_hash,immutable_revision_hash,script_text,approval_contract_version,creator_version_label,created_by
  ) values(p_workspace_id,p_workpiece_id,v_sequence.current_revision+1,p_source_file_path,p_source_file_revision,
    v_hash,v_semantic_hash,v_revision_hash,p_script_text,p_approval_contract_version,p_creator_version_label,
    p_actor_id) returning * into v_revision;
  update tongs.workpiece_script_approval_sequences set current_approval_id=v_revision.id,
    current_revision=v_revision.approval_revision,updated_at=now()
    where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id;
  v_result := jsonb_build_object('disposition','committed','approval',to_jsonb(v_revision));
  insert into tongs.hearth_authority_operation_receipts(
    operation_id,operation_fingerprint,workspace_id,workpiece_id,mutation_kind,
    result_script_approval_id,result_script_approval_revision,immutable_result_json,created_by
  ) values(p_operation_id,v_fingerprint,p_workspace_id,p_workpiece_id,'commit_script_approval',
    v_revision.id,v_revision.approval_revision,v_result,v_revision.created_by);
  return v_result;
end
$$;


ALTER FUNCTION "tongs"."commit_script_approval_snapshot"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_expected_current_revision" bigint, "p_source_file_path" "text", "p_source_file_revision" bigint, "p_script_text" "text", "p_approval_contract_version" "text", "p_creator_version_label" "text", "p_operation_id" "text", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."commit_source_revision"("p_workspace_id" "uuid", "p_source_id" "uuid", "p_stable_key" "text", "p_expected_revision" bigint, "p_source_type" "text", "p_title" "text", "p_author_creator" "text", "p_publisher" "text", "p_published_at" timestamp with time zone, "p_canonical_url" "text", "p_document_identity" "text", "p_canonical_asset_revision_id" "uuid", "p_canonical_asset_content_hash" "text", "p_metadata_json" "jsonb", "p_provenance_json" "jsonb", "p_metadata_contract_version" "text", "p_provenance_contract_version" "text", "p_operation_id" "text", "p_operation_fingerprint" "text", "p_actor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare v_op tongs.source_operation_receipts%rowtype; v_source tongs.sources%rowtype; v_seq tongs.source_sequences%rowtype;
 v_prev tongs.source_revisions%rowtype; v_rev tongs.source_revisions%rowtype; v_asset tongs.assets%rowtype;
 v_content_hash text; v_immutable_hash text; v_result jsonb; v_next bigint;
begin
 if not tongs.has_workspace_role(p_workspace_id,'editor') then raise exception 'workspace editor authority required' using errcode='42501'; end if;
 if auth.uid() is distinct from p_actor_id then raise exception 'Source actor must match authenticated creator' using errcode='42501'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_operation_id,0));
 select * into v_op from tongs.source_operation_receipts where operation_id=p_operation_id for update;
 if found then
  if v_op.operation_fingerprint<>p_operation_fingerprint or v_op.workspace_id<>p_workspace_id or v_op.operation_type<>'source_revision' then return jsonb_build_object('disposition','operation_identity_conflict'); end if;
  return v_op.receipt_json;
 end if;
 if p_source_id is null then
  insert into tongs.sources(workspace_id,stable_key,created_by) values(p_workspace_id,btrim(p_stable_key),p_actor_id)
  on conflict(workspace_id,stable_key) do nothing;
  select * into v_source from tongs.sources where workspace_id=p_workspace_id and stable_key=btrim(p_stable_key) for update;
 else
  select * into v_source from tongs.sources where id=p_source_id and workspace_id=p_workspace_id for update;
  if not found then return jsonb_build_object('disposition','source_not_found'); end if;
  if v_source.stable_key<>btrim(p_stable_key) then return jsonb_build_object('disposition','source_identity_conflict'); end if;
 end if;
 select * into v_seq from tongs.source_sequences where workspace_id=p_workspace_id and source_id=v_source.id for update;
 if found then
  if v_seq.current_source_revision<>p_expected_revision then return jsonb_build_object('disposition','source_revision_conflict','current_revision_id',v_seq.current_source_revision_id,'current_revision',v_seq.current_source_revision); end if;
  select * into v_prev from tongs.source_revisions where id=v_seq.current_source_revision_id;
 else
  if p_expected_revision<>0 then return jsonb_build_object('disposition','source_revision_conflict','current_revision',0); end if;
 end if;
 if p_canonical_asset_revision_id is not null then
  select * into v_asset from tongs.assets where id=p_canonical_asset_revision_id and workspace_id=p_workspace_id and status='ready';
  if not found then return jsonb_build_object('disposition','canonical_asset_not_ready'); end if;
  if v_asset.content_hash is distinct from lower(p_canonical_asset_content_hash) then return jsonb_build_object('disposition','canonical_asset_hash_conflict'); end if;
 end if;
 v_next:=coalesce(v_seq.current_source_revision,0)+1;
 v_content_hash:=encode(extensions.digest(convert_to(jsonb_strip_nulls(jsonb_build_object(
  'source_type',btrim(p_source_type),'title',btrim(p_title),'author_creator',nullif(btrim(p_author_creator),''),
  'publisher',nullif(btrim(p_publisher),''),'published_at',p_published_at,'canonical_url',nullif(btrim(p_canonical_url),''),
  'document_identity',nullif(btrim(p_document_identity),''),'canonical_asset_revision_id',p_canonical_asset_revision_id,
  'canonical_asset_content_hash',lower(p_canonical_asset_content_hash),'metadata_json',coalesce(p_metadata_json,'{}'::jsonb),
  'provenance_json',coalesce(p_provenance_json,'{}'::jsonb),'metadata_contract_version',p_metadata_contract_version,
  'provenance_contract_version',p_provenance_contract_version))::text,'UTF8'),'sha256'),'hex');
 v_immutable_hash:=encode(extensions.digest(convert_to(jsonb_build_object('source_id',v_source.id,'revision',v_next,'previous_revision_id',v_prev.id,'content_hash',v_content_hash)::text,'UTF8'),'sha256'),'hex');
 insert into tongs.source_revisions(source_id,workspace_id,revision,previous_revision_id,previous_revision,source_type,title,author_creator,publisher,published_at,canonical_url,document_identity,canonical_asset_revision_id,canonical_asset_content_hash,metadata_json,provenance_json,metadata_contract_version,provenance_contract_version,content_hash,immutable_revision_hash,created_by)
 values(v_source.id,p_workspace_id,v_next,v_prev.id,v_prev.revision,btrim(p_source_type),btrim(p_title),nullif(btrim(p_author_creator),''),nullif(btrim(p_publisher),''),p_published_at,nullif(btrim(p_canonical_url),''),nullif(btrim(p_document_identity),''),p_canonical_asset_revision_id,lower(p_canonical_asset_content_hash),coalesce(p_metadata_json,'{}'::jsonb),coalesce(p_provenance_json,'{}'::jsonb),btrim(p_metadata_contract_version),btrim(p_provenance_contract_version),v_content_hash,v_immutable_hash,p_actor_id) returning * into v_rev;
 insert into tongs.source_sequences(workspace_id,source_id,current_source_revision_id,current_source_revision) values(p_workspace_id,v_source.id,v_rev.id,v_rev.revision)
 on conflict(workspace_id,source_id) do update set current_source_revision_id=excluded.current_source_revision_id,current_source_revision=excluded.current_source_revision,updated_at=now();
 v_result:=jsonb_build_object('disposition','committed','source',to_jsonb(v_source),'source_revision',to_jsonb(v_rev));
 insert into tongs.source_operation_receipts(operation_id,operation_fingerprint,operation_type,workspace_id,source_id,normalized_inputs_json,state,result_source_revision_id,receipt_json,created_by)
 values(p_operation_id,p_operation_fingerprint,'source_revision',p_workspace_id,v_source.id,jsonb_build_object('stable_key',p_stable_key,'expected_revision',p_expected_revision),'committed',v_rev.id,v_result,p_actor_id);
 return v_result;
end $$;


ALTER FUNCTION "tongs"."commit_source_revision"("p_workspace_id" "uuid", "p_source_id" "uuid", "p_stable_key" "text", "p_expected_revision" bigint, "p_source_type" "text", "p_title" "text", "p_author_creator" "text", "p_publisher" "text", "p_published_at" timestamp with time zone, "p_canonical_url" "text", "p_document_identity" "text", "p_canonical_asset_revision_id" "uuid", "p_canonical_asset_content_hash" "text", "p_metadata_json" "jsonb", "p_provenance_json" "jsonb", "p_metadata_contract_version" "text", "p_provenance_contract_version" "text", "p_operation_id" "text", "p_operation_fingerprint" "text", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."commit_thumbnail_brand_binding_stage"("p_workspace_id" "uuid", "p_operation_id" "uuid", "p_operation_fingerprint" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare v_op tongs.thumbnail_brand_setup_operations%rowtype;v_current tongs.workpiece_brand_bindings%rowtype;v_target tongs.brand_profile_revisions%rowtype;v_binding tongs.workpiece_brand_bindings%rowtype;v_assets uuid[];
begin perform tongs.assert_workspace_role(p_workspace_id,'editor');perform pg_advisory_xact_lock(hashtextextended(p_workspace_id::text||':'||p_operation_id::text||':thumbnail-brand-setup',0));select * into v_op from tongs.thumbnail_brand_setup_operations where workspace_id=p_workspace_id and operation_id=p_operation_id for update;
 if not found then raise exception 'Thumbnail brand setup operation not found' using errcode='P0002';end if;if v_op.operation_fingerprint<>p_operation_fingerprint then raise exception 'Operation identity was reused with a different payload.' using errcode='22023';end if;
 if v_op.state in('binding_committed','verified') then return tongs.thumbnail_brand_setup_json(v_op.id);end if;if v_op.state<>'profile_committed' then raise exception 'Profile stage is incomplete' using errcode='55000';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_workspace_id::text||':'||v_op.workpiece_id::text||':brand',0));select * into v_current from tongs.workpiece_brand_bindings where workspace_id=p_workspace_id and workpiece_id=v_op.workpiece_id order by revision desc limit 1;
 if coalesce(v_current.revision,0)<>v_op.expected_binding_revision then perform set_config('tongs.thumbnail_brand_setup_transition','on',true);update tongs.thumbnail_brand_setup_operations set failed_stage='binding_committed',failure_code='revision_conflict',failure_message='Expected binding revision is stale.',updated_at=now() where id=v_op.id;perform set_config('tongs.thumbnail_brand_setup_transition','off',true);return tongs.thumbnail_brand_setup_json(v_op.id);end if;
 select * into v_target from tongs.brand_profile_revisions where id=v_op.profile_revision_id;if not tongs.brand_revision_is_bindable(p_workspace_id,v_op.profile_id,v_target.id) then perform set_config('tongs.thumbnail_brand_setup_transition','on',true);update tongs.thumbnail_brand_setup_operations set failed_stage='binding_committed',failure_code='target_not_bindable',failure_message='Target profile revision is not bindable.',updated_at=now() where id=v_op.id;perform set_config('tongs.thumbnail_brand_setup_transition','off',true);return tongs.thumbnail_brand_setup_json(v_op.id);end if;
 select coalesce(array_agg(value::uuid),'{}') into v_assets from jsonb_each_text(coalesce(v_target.rules_json->'asset_revision_ids','{}'::jsonb));
 insert into tongs.workpiece_brand_bindings(workspace_id,workpiece_id,revision,state,profile_id,profile_revision_id,profile_revision,profile_content_hash,asset_revision_ids,mutation_reason,operation_id,operation_fingerprint,previous_binding_id,created_by)
 values(p_workspace_id,v_op.workpiece_id,coalesce(v_current.revision,0)+1,'profile',v_op.profile_id,v_target.id,v_target.revision,v_target.content_hash,v_assets,'select_profile_revision',p_operation_id::text||':binding',p_operation_fingerprint,v_current.id,auth.uid()) returning * into v_binding;
 perform set_config('tongs.thumbnail_brand_setup_transition','on',true);update tongs.thumbnail_brand_setup_operations set state='binding_committed',resulting_binding_id=v_binding.id,resulting_binding_revision=v_binding.revision,failed_stage=null,failure_code=null,failure_message=null,updated_at=now() where id=v_op.id;perform set_config('tongs.thumbnail_brand_setup_transition','off',true);
 return tongs.thumbnail_brand_setup_json(v_op.id);
end $$;


ALTER FUNCTION "tongs"."commit_thumbnail_brand_binding_stage"("p_workspace_id" "uuid", "p_operation_id" "uuid", "p_operation_fingerprint" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."commit_thumbnail_brand_profile_stage"("p_workspace_id" "uuid", "p_operation_id" "uuid", "p_operation_fingerprint" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare v_op tongs.thumbnail_brand_setup_operations%rowtype;v_rules jsonb;v_result jsonb;v_revision tongs.brand_profile_revisions%rowtype;
begin perform tongs.assert_workspace_role(p_workspace_id,'editor');select * into v_op from tongs.thumbnail_brand_setup_operations where workspace_id=p_workspace_id and operation_id=p_operation_id for update;
 if not found then raise exception 'Thumbnail brand setup operation not found' using errcode='P0002';end if;if v_op.operation_fingerprint<>p_operation_fingerprint then raise exception 'Operation identity was reused with a different payload.' using errcode='22023';end if;
 if v_op.state in('profile_committed','binding_committed','verified') then return tongs.thumbnail_brand_setup_json(v_op.id);end if;if v_op.state<>'asset_ready' then raise exception 'Asset stage is incomplete' using errcode='55000';end if;
 v_rules:=jsonb_strip_nulls(jsonb_set(v_op.requested_rules_json,'{asset_revision_ids}',
  (coalesce(v_op.requested_rules_json->'asset_revision_ids','{}'::jsonb)-array['transparent_logo','primary_logo','watermark_logo'])
  ||jsonb_build_object(v_op.logo_role,v_op.logo_asset_revision_id),true));
 v_result:=tongs.append_brand_profile_revision(p_workspace_id,v_op.profile_id,v_rules,p_operation_id::text);
 select * into v_revision from tongs.brand_profile_revisions where id=(v_result->>'profile_revision_id')::uuid;
 if v_revision.id is null or not tongs.brand_revision_is_bindable(p_workspace_id,v_op.profile_id,v_revision.id) then
  perform set_config('tongs.thumbnail_brand_setup_transition','on',true);update tongs.thumbnail_brand_setup_operations set failed_stage='profile_committed',failure_code='profile_not_bindable',failure_message='The committed profile revision is not bindable.',updated_at=now() where id=v_op.id;perform set_config('tongs.thumbnail_brand_setup_transition','off',true);return tongs.thumbnail_brand_setup_json(v_op.id);
 end if;
 perform set_config('tongs.thumbnail_brand_setup_transition','on',true);update tongs.thumbnail_brand_setup_operations set state='profile_committed',profile_revision_id=v_revision.id,profile_revision=v_revision.revision,profile_content_hash=v_revision.content_hash,failed_stage=null,failure_code=null,failure_message=null,updated_at=now() where id=v_op.id;perform set_config('tongs.thumbnail_brand_setup_transition','off',true);
 return tongs.thumbnail_brand_setup_json(v_op.id);
end $$;


ALTER FUNCTION "tongs"."commit_thumbnail_brand_profile_stage"("p_workspace_id" "uuid", "p_operation_id" "uuid", "p_operation_fingerprint" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."commit_thumbnail_candidate_set"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_expected_current_revision" integer, "p_candidates" "jsonb", "p_operation_id" "text", "p_operation_fingerprint" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $_$
declare v_user uuid:=auth.uid(); v_op tongs.thumbnail_candidate_set_operations%rowtype; v_current tongs.thumbnail_candidate_sets%rowtype;
 v_binding tongs.workpiece_brand_bindings%rowtype; v_set_id uuid; v_set_revision int; v_set_hash text; v_result jsonb; v_entry jsonb;
 v_candidate tongs.thumbnail_candidate_revisions%rowtype; v_asset tongs.assets%rowtype; v_base tongs.assets%rowtype; v_binding_source tongs.workpiece_brand_bindings%rowtype;
 v_id uuid; v_struct text; v_candidate_hash text; v_ordinal int:=0; v_count int; v_members jsonb:='[]'::jsonb;
begin
 if v_user is null then raise exception 'Not authenticated' using errcode='42501'; end if;
 perform tongs.assert_workspace_role(p_workspace_id,'editor');
 if not exists(select 1 from tongs.episodes where id=p_workpiece_id and workspace_id=p_workspace_id) then raise exception 'workpiece does not belong to workspace' using errcode='22023'; end if;
 if p_operation_id is null or length(btrim(p_operation_id))=0 or p_operation_fingerprint!~'^[a-f0-9]{64}$' then raise exception 'valid operation identity is required' using errcode='22023'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_workspace_id::text||':'||p_workpiece_id::text||':brand',0));
 select * into v_binding from tongs.workpiece_brand_bindings where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id order by revision desc limit 1;
 perform pg_advisory_xact_lock(hashtextextended(p_workspace_id::text||':'||p_workpiece_id::text||':thumbnail-candidate-set',0));
 perform pg_advisory_xact_lock(hashtextextended(p_workspace_id::text||':'||p_operation_id||':thumbnail-authority-operation',0));
 select * into v_op from tongs.thumbnail_candidate_set_operations where workspace_id=p_workspace_id and operation_id=p_operation_id;
 if found then
  if v_op.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict','code','thumbnail_candidate_set_operation_reused'); end if;
  return v_op.result_json||jsonb_build_object('replayed',true,'current_active_binding_id',v_binding.id);
 end if;
 select * into v_current from tongs.thumbnail_candidate_sets where workpiece_id=p_workpiece_id order by revision desc limit 1;
 if coalesce(v_current.revision,0)<>p_expected_current_revision then
  v_result:=jsonb_build_object('disposition','revision_conflict','code','stale_thumbnail_candidate_set_revision','expected_revision',p_expected_current_revision,'current_revision',coalesce(v_current.revision,0),'current_candidate_set_id',v_current.id);
  insert into tongs.thumbnail_candidate_set_operations(workspace_id,workpiece_id,operation_id,operation_fingerprint,disposition,result_json,created_by) values(p_workspace_id,p_workpiece_id,p_operation_id,p_operation_fingerprint,'revision_conflict',v_result,v_user);
  return v_result;
 end if;
 if jsonb_typeof(p_candidates)<>'array' or jsonb_array_length(p_candidates)<3 then raise exception 'candidate set requires at least three candidates' using errcode='22023'; end if;
 create temporary table if not exists pg_temp.forge_candidate_commit(candidate_id uuid primary key,ordinal int unique,title_id uuid,concept_id uuid,base_hash text,structural_hash text,canonical_hash text) on commit drop;
 truncate pg_temp.forge_candidate_commit;
 for v_entry in select value from jsonb_array_elements(p_candidates) loop
  v_ordinal:=v_ordinal+1; v_id:=nullif(v_entry->>'candidate_revision_id','')::uuid;
  if v_id is not null then
   select * into v_candidate from tongs.thumbnail_candidate_revisions where id=v_id and workspace_id=p_workspace_id and workpiece_id=p_workpiece_id;
   if not found then raise exception 'candidate revision is unavailable' using errcode='22023'; end if;
  else
   v_struct:=tongs.thumbnail_structural_fingerprint(coalesce(v_entry->'structural_composition','{}'::jsonb));
   if coalesce(v_entry->>'structural_fingerprint_version','')<>'forge.thumbnail-structural-composition.v1' or v_entry->>'structural_composition_fingerprint'<>v_struct then raise exception 'structural composition fingerprint mismatch' using errcode='22023'; end if;
   select * into v_asset from tongs.assets where id=(v_entry->>'composite_asset_id')::uuid and workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and asset_kind='thumbnail_composite' and status='ready';
   if not found or v_asset.content_hash<>v_entry->>'composite_content_hash' then raise exception 'verified composite asset mismatch' using errcode='22023'; end if;
   select * into v_base from tongs.assets where id=(v_entry->>'base_artwork_asset_id')::uuid and workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and status='ready';
   if not found or v_base.content_hash<>v_entry->>'base_artwork_content_hash' then raise exception 'verified base artwork mismatch' using errcode='22023'; end if;
   select * into v_binding_source from tongs.workpiece_brand_bindings where id=(v_entry->>'candidate_binding_id')::uuid and workspace_id=p_workspace_id and workpiece_id=p_workpiece_id;
   if not found or v_binding_source.revision<>(v_entry->>'candidate_binding_revision')::int then raise exception 'candidate binding provenance mismatch' using errcode='22023'; end if;
   if v_asset.metadata_json->>'recipe_snapshot_hash'<>v_entry->>'recipe_hash' or v_asset.metadata_json->>'base_asset_hash'<>v_entry->>'base_artwork_content_hash'
    or v_asset.metadata_json#>>'{brand_application_provenance,binding_id}'<>v_entry->>'candidate_binding_id'
    or (v_asset.metadata_json#>>'{brand_application_provenance,binding_revision}')::int<>(v_entry->>'candidate_binding_revision')::int
    or v_asset.metadata_json#>>'{readability_evidence,contract_version}'<>v_entry->>'readability_contract_version'
    or v_asset.metadata_json#>>'{readability_evidence,evaluator_version}'<>v_entry->>'readability_evaluator_version'
    or v_asset.metadata_json#>>'{readability_evidence,evaluation_hash}'<>v_entry->>'readability_evidence_hash'
    or coalesce((v_asset.metadata_json#>>'{readability_evidence,passed}')::boolean,false) is not true
    or v_asset.metadata_json->>'composition_engine_version'<>v_entry->>'compositor_version' then raise exception 'candidate immutable provenance verification failed' using errcode='22023'; end if;
   v_candidate_hash:=encode(extensions.digest(convert_to(jsonb_strip_nulls(jsonb_build_object('recipe_id',v_entry->'recipe_id','recipe_revision',v_entry->'recipe_revision','recipe_hash',v_entry->'recipe_hash','title_revision_id',v_entry->'title_revision_id','title_revision',v_entry->'title_revision','concept_revision_id',v_entry->'concept_revision_id','base_artwork_asset_id',v_entry->'base_artwork_asset_id','base_artwork_content_hash',v_entry->'base_artwork_content_hash','structural_composition_fingerprint',v_struct,'composite_asset_id',v_entry->'composite_asset_id','composite_content_hash',v_entry->'composite_content_hash','candidate_binding_id',v_entry->'candidate_binding_id','candidate_binding_revision',v_entry->'candidate_binding_revision','candidate_binding_content_hash',v_entry->'candidate_binding_content_hash','readability_contract_version',v_entry->'readability_contract_version','readability_evaluator_version',v_entry->'readability_evaluator_version','readability_evidence_hash',v_entry->'readability_evidence_hash','compositor_version',v_entry->'compositor_version'))::text,'UTF8'),'sha256'),'hex');
   v_id:=coalesce(nullif(v_entry->>'new_candidate_revision_id','')::uuid,gen_random_uuid());
   insert into tongs.thumbnail_candidate_revisions(id,workspace_id,workpiece_id,recipe_id,recipe_revision,recipe_hash,title_revision_id,title_revision,concept_revision_id,base_artwork_asset_id,base_artwork_content_hash,structural_composition_fingerprint,structural_fingerprint_version,composite_asset_id,composite_content_hash,candidate_binding_id,candidate_binding_revision,candidate_binding_content_hash,readability_contract_version,readability_evaluator_version,readability_evidence_hash,compositor_version,canonical_content_hash,committed_by)
   values(v_id,p_workspace_id,p_workpiece_id,(v_entry->>'recipe_id')::uuid,(v_entry->>'recipe_revision')::int,v_entry->>'recipe_hash',(v_entry->>'title_revision_id')::uuid,(v_entry->>'title_revision')::int,(v_entry->>'concept_revision_id')::uuid,(v_entry->>'base_artwork_asset_id')::uuid,v_entry->>'base_artwork_content_hash',v_struct,'forge.thumbnail-structural-composition.v1',(v_entry->>'composite_asset_id')::uuid,v_entry->>'composite_content_hash',(v_entry->>'candidate_binding_id')::uuid,(v_entry->>'candidate_binding_revision')::int,nullif(v_entry->>'candidate_binding_content_hash',''),'forge.thumbnail-readability.v1',v_entry->>'readability_evaluator_version',v_entry->>'readability_evidence_hash',v_entry->>'compositor_version',v_candidate_hash,v_user) returning * into v_candidate;
  end if;
  insert into pg_temp.forge_candidate_commit values(v_candidate.id,v_ordinal,v_candidate.title_revision_id,v_candidate.concept_revision_id,v_candidate.base_artwork_content_hash,v_candidate.structural_composition_fingerprint,v_candidate.canonical_content_hash);
 end loop;
 select count(*) into v_count from pg_temp.forge_candidate_commit;
 if exists(select 1 from pg_temp.forge_candidate_commit a join pg_temp.forge_candidate_commit b on a.ordinal<b.ordinal where a.title_id=b.title_id and a.concept_id=b.concept_id and a.base_hash=b.base_hash and a.structural_hash=b.structural_hash) then raise exception 'candidate set contains presentation-only duplicates' using errcode='22023'; end if;
 select jsonb_agg(jsonb_build_object('candidate_revision_id',candidate_id,'candidate_ordinal',ordinal,'candidate_content_hash',canonical_hash) order by ordinal) into v_members from pg_temp.forge_candidate_commit;
 v_set_revision:=coalesce(v_current.revision,0)+1; v_set_id:=gen_random_uuid();
 v_set_hash:=encode(extensions.digest(convert_to(jsonb_build_object('schema','forge.thumbnail-candidate-set.v1','workpiece_id',p_workpiece_id,'revision',v_set_revision,'previous_candidate_set_id',v_current.id,'distinction_contract_version','forge.thumbnail-candidate-distinction.v1','members',v_members)::text,'UTF8'),'sha256'),'hex');
 insert into tongs.thumbnail_candidate_sets(id,workspace_id,workpiece_id,revision,previous_candidate_set_id,candidate_count,content_hash,distinction_contract_version,operation_id,operation_fingerprint,committed_by) values(v_set_id,p_workspace_id,p_workpiece_id,v_set_revision,v_current.id,v_count,v_set_hash,'forge.thumbnail-candidate-distinction.v1',p_operation_id,p_operation_fingerprint,v_user);
 insert into tongs.thumbnail_candidate_set_members(workspace_id,workpiece_id,candidate_set_id,candidate_revision_id,candidate_ordinal,created_by) select p_workspace_id,p_workpiece_id,v_set_id,candidate_id,ordinal,v_user from pg_temp.forge_candidate_commit;
 v_result:=jsonb_build_object('disposition','committed','candidate_set_id',v_set_id,'revision',v_set_revision,'previous_candidate_set_id',v_current.id,'candidate_count',v_count,'content_hash',v_set_hash,'active_binding_id',v_binding.id,'members',v_members);
 insert into tongs.thumbnail_candidate_set_operations(workspace_id,workpiece_id,operation_id,operation_fingerprint,disposition,candidate_set_id,result_json,created_by) values(p_workspace_id,p_workpiece_id,p_operation_id,p_operation_fingerprint,'committed',v_set_id,v_result,v_user);
 return v_result;
end $_$;


ALTER FUNCTION "tongs"."commit_thumbnail_candidate_set"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_expected_current_revision" integer, "p_candidates" "jsonb", "p_operation_id" "text", "p_operation_fingerprint" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."commit_visual_source_attribution"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_artifact_family" "text", "p_opportunity_id" "uuid", "p_script_approval_id" "uuid", "p_unified_plan_operation_id" "text", "p_child_plan_revision_id" "uuid", "p_state" "text", "p_relationship" "text", "p_rationale" "text", "p_model_evidence_json" "jsonb", "p_members" "jsonb", "p_expected_revision" bigint, "p_operation_id" "text", "p_operation_fingerprint" "text", "p_actor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
#variable_conflict use_column
declare prior tongs.visual_source_attribution_revisions%rowtype;current_row tongs.visual_source_attribution_revisions%rowtype;created tongs.visual_source_attribution_revisions%rowtype;item jsonb;src tongs.source_revisions%rowtype;link_rev tongs.workpiece_source_link_revisions%rowtype;position integer:=0;members_json jsonb:='[]'::jsonb;immutable_hash text;
begin
 if not tongs.has_workspace_role(p_workspace_id,'editor')or auth.uid()is distinct from p_actor_id then raise exception 'workspace editor authority required' using errcode='42501';end if;
 if p_artifact_family not in('image','broll','reference_clip','reference_visual')or p_state not in('auto_bound','selection_required','creator_selected','none_known')or p_relationship not in('direct','supporting','ambiguous','none')then return jsonb_build_object('disposition','invalid_contract');end if;
 if jsonb_typeof(p_members)<>'array'then return jsonb_build_object('disposition','members_array_required');end if;
 if (p_relationship='none')<>(jsonb_array_length(p_members)=0)then return jsonb_build_object('disposition','relationship_member_conflict');end if;
 if p_relationship='direct'and jsonb_array_length(p_members)<>1 then return jsonb_build_object('disposition','direct_source_count');end if;
 if p_relationship='ambiguous'and jsonb_array_length(p_members)<2 then return jsonb_build_object('disposition','ambiguous_source_count');end if;
 perform pg_advisory_xact_lock(hashtextextended(p_operation_id,0));select * into prior from tongs.visual_source_attribution_revisions where operation_id=p_operation_id;
 if found then if prior.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict');end if;return jsonb_build_object('disposition','committed','attribution_revision',to_jsonb(prior));end if;
 select * into current_row from tongs.visual_source_attribution_revisions where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and artifact_family=p_artifact_family and opportunity_id=p_opportunity_id order by revision desc limit 1 for update;
 if coalesce(current_row.revision,0)<>p_expected_revision then return jsonb_build_object('disposition','attribution_revision_conflict','current_revision',coalesce(current_row.revision,0));end if;
 for item in select value from jsonb_array_elements(p_members)loop position:=position+1;
  begin select * into src from tongs.source_revisions where id=(item->>'source_revision_id')::uuid and workspace_id=p_workspace_id;exception when invalid_text_representation then return jsonb_build_object('disposition','invalid_source');end;
  if not found then return jsonb_build_object('disposition','invalid_source');end if;
  begin select * into link_rev from tongs.workpiece_source_link_revisions where id=(item->>'workpiece_source_link_revision_id')::uuid and workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and source_revision_id=src.id;exception when invalid_text_representation then return jsonb_build_object('disposition','invalid_source_link');end;
  if not found then return jsonb_build_object('disposition','invalid_source_link');end if;
 end loop;
 if p_relationship='direct'and p_artifact_family='reference_clip'and not exists(
  select 1 from tongs.reference_clip_plan_sequences seq
  join tongs.reference_clip_plan_membership membership on membership.plan_revision_id=seq.current_plan_revision_id and membership.opportunity_id=p_opportunity_id
  join tongs.reference_clip_opportunity_revisions opportunity on opportunity.id=membership.opportunity_revision_id
  where seq.workspace_id=p_workspace_id and seq.workpiece_id=p_workpiece_id and opportunity.source_status='linked'
   and opportunity.source_revision_id=(p_members->0->>'source_revision_id')::uuid
   and opportunity.workpiece_source_link_revision_id=(p_members->0->>'workpiece_source_link_revision_id')::uuid
 )then return jsonb_build_object('disposition','attribution_family_authority_conflict');end if;
 if p_relationship='direct'and p_artifact_family='reference_visual'and not exists(
  select 1 from tongs.reference_visual_plan_sequences seq
  join lateral(select source_set.id from tongs.reference_visual_source_set_revisions source_set where source_set.workspace_id=p_workspace_id and source_set.workpiece_id=p_workpiece_id and source_set.plan_revision_id=seq.current_plan_revision_id and source_set.opportunity_id=p_opportunity_id order by source_set.revision desc limit 1)current_set on true
  join tongs.reference_visual_source_set_members member on member.source_set_revision_id=current_set.id
  where seq.workspace_id=p_workspace_id and seq.workpiece_id=p_workpiece_id
   and member.source_revision_id=(p_members->0->>'source_revision_id')::uuid
   and member.workpiece_source_link_revision_id=(p_members->0->>'workpiece_source_link_revision_id')::uuid
   and(select count(*)from tongs.reference_visual_source_set_members exact_count where exact_count.source_set_revision_id=current_set.id)=1
 )then return jsonb_build_object('disposition','attribution_family_authority_conflict');end if;
 immutable_hash:=encode(extensions.digest(convert_to(jsonb_build_object('workspace_id',p_workspace_id,'workpiece_id',p_workpiece_id,'family',p_artifact_family,'opportunity_id',p_opportunity_id,'script_approval_id',p_script_approval_id,'unified_operation',p_unified_plan_operation_id,'child_plan_revision_id',p_child_plan_revision_id,'state',p_state,'relationship',p_relationship,'rationale',coalesce(p_rationale,''),'members',p_members)::text,'UTF8'),'sha256'),'hex');
 insert into tongs.visual_source_attribution_revisions(workspace_id,workpiece_id,artifact_family,opportunity_id,script_approval_id,unified_plan_operation_id,child_plan_revision_id,revision,previous_revision_id,previous_revision,state,relationship,rationale,model_evidence_json,operation_id,operation_fingerprint,immutable_revision_hash,created_by)
 values(p_workspace_id,p_workpiece_id,p_artifact_family,p_opportunity_id,p_script_approval_id,p_unified_plan_operation_id,p_child_plan_revision_id,coalesce(current_row.revision,0)+1,current_row.id,current_row.revision,p_state,p_relationship,coalesce(p_rationale,''),coalesce(p_model_evidence_json,'{}'::jsonb),p_operation_id,p_operation_fingerprint,immutable_hash,p_actor_id)returning * into created;
 position:=0;for item in select value from jsonb_array_elements(p_members)loop position:=position+1;insert into tongs.visual_source_attribution_members(attribution_revision_id,workspace_id,workpiece_id,ordinal,role,source_revision_id,workpiece_source_link_revision_id)values(created.id,p_workspace_id,p_workpiece_id,position,item->>'role',(item->>'source_revision_id')::uuid,(item->>'workpiece_source_link_revision_id')::uuid);end loop;
 select coalesce(jsonb_agg(jsonb_build_object('ordinal',m.ordinal,'role',m.role,'source_revision_id',m.source_revision_id,'workpiece_source_link_revision_id',m.workpiece_source_link_revision_id)order by m.ordinal),'[]'::jsonb)into members_json from tongs.visual_source_attribution_members m where m.attribution_revision_id=created.id;
 return jsonb_build_object('disposition','committed','attribution_revision',to_jsonb(created),'members',members_json);
end$$;


ALTER FUNCTION "tongs"."commit_visual_source_attribution"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_artifact_family" "text", "p_opportunity_id" "uuid", "p_script_approval_id" "uuid", "p_unified_plan_operation_id" "text", "p_child_plan_revision_id" "uuid", "p_state" "text", "p_relationship" "text", "p_rationale" "text", "p_model_evidence_json" "jsonb", "p_members" "jsonb", "p_expected_revision" bigint, "p_operation_id" "text", "p_operation_fingerprint" "text", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."commit_workpiece_source_link_revision"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_link_id" "uuid", "p_expected_revision" bigint, "p_source_revision_id" "uuid", "p_source_revision" bigint, "p_relationship_type" "text", "p_script_approval_id" "uuid", "p_script_approval_revision" bigint, "p_citation_anchor_json" "jsonb", "p_document_locator_json" "jsonb", "p_media_range_json" "jsonb", "p_quotation_excerpt_hash" "text", "p_relationship_note" "text", "p_provenance_json" "jsonb", "p_operation_id" "text", "p_operation_fingerprint" "text", "p_actor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare v_op tongs.source_operation_receipts%rowtype; v_source_rev tongs.source_revisions%rowtype;
 v_seq tongs.workpiece_source_link_sequences%rowtype; v_prev tongs.workpiece_source_link_revisions%rowtype;
 v_rev tongs.workpiece_source_link_revisions%rowtype; v_link uuid:=coalesce(p_link_id,gen_random_uuid());
 v_content_hash text; v_immutable_hash text; v_result jsonb; v_next bigint;
begin
 if not tongs.has_workspace_role(p_workspace_id,'editor') then raise exception 'workspace editor authority required' using errcode='42501'; end if;
 if auth.uid() is distinct from p_actor_id then raise exception 'Source-link actor must match authenticated creator' using errcode='42501'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_operation_id,0));
 select * into v_op from tongs.source_operation_receipts where operation_id=p_operation_id for update;
 if found then
  if v_op.operation_fingerprint<>p_operation_fingerprint or v_op.workspace_id<>p_workspace_id or v_op.workpiece_id is distinct from p_workpiece_id or v_op.operation_type<>'workpiece_link' then return jsonb_build_object('disposition','operation_identity_conflict'); end if;
  return v_op.receipt_json;
 end if;
 select * into v_source_rev from tongs.source_revisions where id=p_source_revision_id and workspace_id=p_workspace_id and revision=p_source_revision;
 if not found then return jsonb_build_object('disposition','source_revision_not_found'); end if;
 select * into v_seq from tongs.workpiece_source_link_sequences where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and link_id=v_link for update;
 if found then
  if v_seq.current_link_revision<>p_expected_revision then return jsonb_build_object('disposition','link_revision_conflict','current_revision_id',v_seq.current_link_revision_id,'current_revision',v_seq.current_link_revision); end if;
  select * into v_prev from tongs.workpiece_source_link_revisions where id=v_seq.current_link_revision_id;
 else
  if p_expected_revision<>0 then return jsonb_build_object('disposition','link_revision_conflict','current_revision',0); end if;
 end if;
 v_next:=coalesce(v_seq.current_link_revision,0)+1;
 v_content_hash:=encode(extensions.digest(convert_to(jsonb_strip_nulls(jsonb_build_object('source_revision_id',v_source_rev.id,'source_revision',v_source_rev.revision,'relationship_type',btrim(p_relationship_type),'script_approval_id',p_script_approval_id,'script_approval_revision',p_script_approval_revision,'citation_anchor',coalesce(p_citation_anchor_json,'{}'::jsonb),'document_locator',coalesce(p_document_locator_json,'{}'::jsonb),'media_range',coalesce(p_media_range_json,'{}'::jsonb),'quotation_excerpt_hash',lower(p_quotation_excerpt_hash),'relationship_note',nullif(btrim(p_relationship_note),''),'provenance',coalesce(p_provenance_json,'{}'::jsonb)))::text,'UTF8'),'sha256'),'hex');
 v_immutable_hash:=encode(extensions.digest(convert_to(jsonb_build_object('link_id',v_link,'revision',v_next,'previous_revision_id',v_prev.id,'content_hash',v_content_hash)::text,'UTF8'),'sha256'),'hex');
 insert into tongs.workpiece_source_link_revisions(link_id,workspace_id,workpiece_id,revision,previous_revision_id,previous_revision,source_id,source_revision_id,source_revision,relationship_type,script_approval_id,script_approval_revision,citation_anchor_json,document_locator_json,media_range_json,quotation_excerpt_hash,relationship_note,provenance_json,content_hash,immutable_revision_hash,created_by)
 values(v_link,p_workspace_id,p_workpiece_id,v_next,v_prev.id,v_prev.revision,v_source_rev.source_id,v_source_rev.id,v_source_rev.revision,btrim(p_relationship_type),p_script_approval_id,p_script_approval_revision,coalesce(p_citation_anchor_json,'{}'::jsonb),coalesce(p_document_locator_json,'{}'::jsonb),coalesce(p_media_range_json,'{}'::jsonb),lower(p_quotation_excerpt_hash),nullif(btrim(p_relationship_note),''),coalesce(p_provenance_json,'{}'::jsonb),v_content_hash,v_immutable_hash,p_actor_id) returning * into v_rev;
 insert into tongs.workpiece_source_link_sequences(workspace_id,workpiece_id,link_id,current_link_revision_id,current_link_revision) values(p_workspace_id,p_workpiece_id,v_link,v_rev.id,v_rev.revision)
 on conflict(workspace_id,workpiece_id,link_id) do update set current_link_revision_id=excluded.current_link_revision_id,current_link_revision=excluded.current_link_revision,updated_at=now();
 v_result:=jsonb_build_object('disposition','committed','link_revision',to_jsonb(v_rev),'source_revision',to_jsonb(v_source_rev));
 insert into tongs.source_operation_receipts(operation_id,operation_fingerprint,operation_type,workspace_id,workpiece_id,source_id,link_id,normalized_inputs_json,state,result_source_revision_id,result_link_revision_id,receipt_json,created_by)
 values(p_operation_id,p_operation_fingerprint,'workpiece_link',p_workspace_id,p_workpiece_id,v_source_rev.source_id,v_link,jsonb_build_object('expected_revision',p_expected_revision),'committed',v_source_rev.id,v_rev.id,v_result,p_actor_id);
 return v_result;
end $$;


ALTER FUNCTION "tongs"."commit_workpiece_source_link_revision"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_link_id" "uuid", "p_expected_revision" bigint, "p_source_revision_id" "uuid", "p_source_revision" bigint, "p_relationship_type" "text", "p_script_approval_id" "uuid", "p_script_approval_revision" bigint, "p_citation_anchor_json" "jsonb", "p_document_locator_json" "jsonb", "p_media_range_json" "jsonb", "p_quotation_excerpt_hash" "text", "p_relationship_note" "text", "p_provenance_json" "jsonb", "p_operation_id" "text", "p_operation_fingerprint" "text", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."commit_youtube_reference_clip_candidate"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_opportunity_id" "uuid", "p_expected_opportunity_revision_id" "uuid", "p_video_id" "text", "p_canonical_url" "text", "p_embed_url" "text", "p_start_ms" bigint, "p_end_ms" bigint, "p_metadata_json" "jsonb", "p_rights" "jsonb", "p_provenance" "jsonb", "p_operation_id" "text", "p_operation_fingerprint" "text", "p_actor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $_$
declare receipt tongs.reference_clip_operation_receipts%rowtype;o tongs.reference_clip_opportunity_revisions%rowtype;c tongs.reference_clip_candidates%rowtype;r tongs.reference_clip_candidate_revisions%rowtype;h text;ih text;result jsonb;
begin
 if not tongs.has_workspace_role(p_workspace_id,'editor')or auth.uid() is distinct from p_actor_id then raise exception 'workspace editor authority required' using errcode='42501';end if;
 select * into receipt from tongs.reference_clip_operation_receipts where operation_id=p_operation_id;
 if found then if receipt.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict');end if;return receipt.receipt_json;end if;
 select rv.* into o from tongs.reference_clip_plan_sequences ps join tongs.reference_clip_plan_membership m on m.plan_revision_id=ps.current_plan_revision_id join tongs.reference_clip_opportunity_revisions rv on rv.id=m.opportunity_revision_id where ps.workspace_id=p_workspace_id and ps.workpiece_id=p_workpiece_id and m.opportunity_id=p_opportunity_id;
 if not found or o.id is distinct from p_expected_opportunity_revision_id then return jsonb_build_object('disposition','opportunity_revision_conflict');end if;
 if o.source_status<>'linked' or o.source_revision_id is null or o.workpiece_source_link_revision_id is null then return jsonb_build_object('disposition','linked_source_revision_required');end if;
 if p_video_id!~'^[A-Za-z0-9_-]{11}$' or p_canonical_url<>('https://www.youtube.com/watch?v='||p_video_id) or p_embed_url<>('https://www.youtube-nocookie.com/embed/'||p_video_id) then return jsonb_build_object('disposition','youtube_identity_invalid');end if;
 if p_start_ms<0 or p_end_ms<=p_start_ms or p_end_ms-p_start_ms>3600000 then return jsonb_build_object('disposition','youtube_range_invalid');end if;
 insert into tongs.reference_clip_candidates(workspace_id,workpiece_id,opportunity_id,created_by)values(p_workspace_id,p_workpiece_id,p_opportunity_id,p_actor_id)returning * into c;
 h:=encode(extensions.digest(convert_to(jsonb_build_object('opportunity_revision_id',o.id,'source_revision_id',o.source_revision_id,'source_link_revision_id',o.workpiece_source_link_revision_id,'delivery_kind','youtube_external_reference','video_id',p_video_id,'canonical_url',p_canonical_url,'embed_url',p_embed_url,'start_ms',p_start_ms,'end_ms',p_end_ms,'metadata',coalesce(p_metadata_json,'{}'),'rights',p_rights,'provenance',p_provenance)::text,'UTF8'),'sha256'),'hex');
 ih:=encode(extensions.digest(convert_to(jsonb_build_object('candidate_id',c.id,'revision',1,'content_hash',h)::text,'UTF8'),'sha256'),'hex');
 insert into tongs.reference_clip_candidate_revisions(candidate_id,workspace_id,workpiece_id,opportunity_id,revision,opportunity_revision_id,opportunity_revision,source_revision_id,source_revision,workpiece_source_link_revision_id,workpiece_source_link_revision,asset_id,asset_content_hash,asset_path,storage_bucket,storage_key,mime_type,duration_ms,poster_asset_id,rights_basis,rights_holder,license_identifier,license_url,territories,expires_at,attribution_required,attribution_text,rights_evidence_json,provenance_json,content_hash,immutable_revision_hash,created_by,delivery_kind,external_provider,external_media_id,external_url,embed_url,start_ms,end_ms,external_metadata_json)
 values(c.id,p_workspace_id,p_workpiece_id,p_opportunity_id,1,o.id,o.revision,o.source_revision_id,o.source_revision,o.workpiece_source_link_revision_id,o.workpiece_source_link_revision,null,null,null,null,null,null,p_end_ms-p_start_ms,null,case p_rights->>'basis' when 'fair_use_claimed' then 'fair_use_claim' else coalesce(p_rights->>'basis','unknown') end,p_rights->>'rights_holder',p_rights->>'license_identifier',p_rights->>'license_url',array(select jsonb_array_elements_text(coalesce(p_rights->'territories','[]'))),nullif(p_rights->>'expires_at','')::timestamptz,coalesce((p_rights->>'attribution_required')::boolean,false),p_rights->>'attribution_text',p_rights,coalesce(p_provenance,'{}')||jsonb_build_object('delivery_kind','youtube_external_reference'),h,ih,p_actor_id,'youtube_external_reference','youtube',p_video_id,p_canonical_url,p_embed_url,p_start_ms,p_end_ms,coalesce(p_metadata_json,'{}'))returning * into r;
 result:=jsonb_build_object('disposition','committed','candidate_revision',to_jsonb(r));
 insert into tongs.reference_clip_operation_receipts(operation_id,operation_fingerprint,operation_type,workspace_id,workpiece_id,opportunity_id,state,normalized_inputs_json,result_candidate_revision_id,receipt_json,created_by)values(p_operation_id,p_operation_fingerprint,'youtube_reference_commit',p_workspace_id,p_workpiece_id,p_opportunity_id,'committed',jsonb_build_object('video_id',p_video_id,'start_ms',p_start_ms,'end_ms',p_end_ms),r.id,result,p_actor_id);
 return result;
end$_$;


ALTER FUNCTION "tongs"."commit_youtube_reference_clip_candidate"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_opportunity_id" "uuid", "p_expected_opportunity_revision_id" "uuid", "p_video_id" "text", "p_canonical_url" "text", "p_embed_url" "text", "p_start_ms" bigint, "p_end_ms" bigint, "p_metadata_json" "jsonb", "p_rights" "jsonb", "p_provenance" "jsonb", "p_operation_id" "text", "p_operation_fingerprint" "text", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."complete_barstock_discovery_refresh"("p_run_id" "uuid", "p_lease_token_hash" "text", "p_stories" "jsonb", "p_usage" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs', 'extensions'
    AS $$
declare r tongs.barstock_discovery_runs%rowtype; item jsonb; src jsonb; s tongs.barstock_discovery_stories%rowtype; v tongs.barstock_discovery_story_revisions%rowtype; rev bigint; ord int:=0; sord int; h text;
begin
 if auth.role()<>'service_role' then return jsonb_build_object('outcome','denied');end if;
 select * into r from tongs.barstock_discovery_runs where id=p_run_id and lease_token_hash=p_lease_token_hash and lease_expires_at>now() and status in('leased','refreshing') for update;
 if r.id is null then return jsonb_build_object('outcome','lease_lost');end if;
 if jsonb_typeof(p_stories)<>'array' or jsonb_array_length(p_stories)>5 then return jsonb_build_object('outcome','invalid_result');end if;
 for item in select value from jsonb_array_elements(p_stories) loop
  insert into tongs.barstock_discovery_stories(workspace_id,user_id,fingerprint) values(r.workspace_id,r.user_id,item->>'fingerprint') on conflict(workspace_id,user_id,fingerprint) do update set last_seen_at=now() returning * into s;
  h:=encode(digest(convert_to(jsonb_strip_nulls(item)::text,'UTF8'),'sha256'),'hex');
  select coalesce(max(revision),0)+1 into rev from tongs.barstock_discovery_story_revisions where story_id=s.id;
  insert into tongs.barstock_discovery_story_revisions(story_id,workspace_id,user_id,revision,headline,summary,suggested_angle,timeliness_reason,event_at,evidence_class,contradiction_state,content_hash)
  values(s.id,r.workspace_id,r.user_id,rev,item->>'headline',item->>'summary',item->>'suggested_angle',item->>'timeliness_reason',nullif(item->>'event_at','')::timestamptz,coalesce(item->>'evidence_class','limited'),coalesce(item->>'contradiction_state','none'),h)
  on conflict(story_id,content_hash) do nothing returning * into v;
  if v.id is null then select * into v from tongs.barstock_discovery_story_revisions where story_id=s.id and content_hash=h;end if;
  sord:=0;
  for src in select value from jsonb_array_elements(coalesce(item->'sources','[]')) loop
   insert into tongs.barstock_discovery_sources(story_revision_id,ordinal,original_url,canonical_url,title,publisher,author,published_at,event_at,retrieved_at,supporting_excerpt,excerpt_hash,extraction_status,authority_class,syndication_cluster)
   values(v.id,sord,src->>'original_url',src->>'canonical_url',src->>'title',nullif(src->>'publisher',''),nullif(src->>'author',''),nullif(src->>'published_at','')::timestamptz,nullif(src->>'event_at','')::timestamptz,coalesce(nullif(src->>'retrieved_at','')::timestamptz,now()),nullif(src->>'supporting_excerpt',''),nullif(src->>'excerpt_hash',''),coalesce(src->>'extraction_status','snippet'),coalesce(src->>'authority_class','general'),coalesce(src->>'syndication_cluster',src->>'canonical_url')) on conflict(story_revision_id,canonical_url) do nothing; sord:=sord+1;
  end loop;
  insert into tongs.barstock_discovery_batch_members(run_id,ordinal,story_revision_id) values(r.id,ord,v.id); ord:=ord+1;
 end loop;
 update tongs.barstock_discovery_runs set status=case when ord=0 then 'empty' else 'ready' end,generated_at=now(),fresh_until=now()+interval '6 hours',lease_token_hash='',lease_expires_at=now(),usage_snapshot=coalesce(p_usage,'{}'),updated_at=now() where id=r.id;
 return jsonb_build_object('outcome','completed','story_count',ord);
end$$;


ALTER FUNCTION "tongs"."complete_barstock_discovery_refresh"("p_run_id" "uuid", "p_lease_token_hash" "text", "p_stories" "jsonb", "p_usage" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."complete_bellows_hammer_handoff"("p_package_id" "uuid", "p_hammer_import_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare r tongs.bellows_hammer_handoff_receipts; h tongs.hammer_recording_import_requests;
begin
  select * into r from tongs.bellows_hammer_handoff_receipts where package_id=p_package_id for update;
  if not found then return jsonb_build_object('outcome','not_found'); end if;
  if not tongs.has_workspace_role(r.workspace_id,'editor') then return jsonb_build_object('outcome','denied'); end if;
  select * into h from tongs.hammer_recording_import_requests where id=p_hammer_import_id and state='committed';
  if not found or h.workspace_id<>r.workspace_id or h.workpiece_id<>r.workpiece_id then return jsonb_build_object('outcome','import_not_committed'); end if;
  update tongs.bellows_hammer_handoff_receipts set state='committed',hammer_import_id=h.id,last_error=null,committed_at=coalesce(committed_at,now()) where id=r.id returning * into r;
  return jsonb_build_object('outcome','committed','receipt',to_jsonb(r));
end $$;


ALTER FUNCTION "tongs"."complete_bellows_hammer_handoff"("p_package_id" "uuid", "p_hammer_import_id" "uuid") OWNER TO "postgres";


