$_$;


ALTER FUNCTION "tongs"."complete_customer_hearth_research_stage"("p_reservation_id" "uuid", "p_stage_key" "text", "p_actual_supplier_cost_micros" bigint, "p_capture_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."complete_hammer_shorts_discovery"("p_discovery_id" "uuid", "p_ai_proposal" "jsonb", "p_candidates" "jsonb", "p_outcome" "text", "p_proposal_fingerprint" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare v_actor uuid:=auth.uid(); v_discovery tongs.hammer_shorts_discoveries%rowtype; v_candidate jsonb;
begin
  select * into v_discovery from tongs.hammer_shorts_discoveries where id=p_discovery_id for update;
  if v_actor is null or v_discovery.id is null or not tongs.has_workspace_role(v_discovery.workspace_id,'editor') then raise exception 'hammer_shorts_editor_required' using errcode='42501'; end if;
  if v_discovery.state='completed' then return jsonb_build_object('discovery',to_jsonb(v_discovery),'candidates',(select coalesce(jsonb_agg(to_jsonb(c) order by c.rank),'[]'::jsonb) from tongs.hammer_short_candidates c where c.discovery_id=p_discovery_id)); end if;
  if p_outcome not in('complete','partial','empty') or jsonb_typeof(p_candidates)<>'array' or jsonb_array_length(p_candidates)>4 then raise exception 'hammer_shorts_result_invalid' using errcode='22023'; end if;
  insert into tongs.hammer_shorts_ai_proposals(discovery_id,workspace_id,schema_version,provider,model,provider_request_id,prompt_fingerprint,proposal_json,proposal_fingerprint) values(p_discovery_id,v_discovery.workspace_id,'HammerShortsAiProposalV1','openai',p_ai_proposal->>'model',p_ai_proposal->>'provider_request_id',p_ai_proposal->>'prompt_fingerprint',p_ai_proposal,p_proposal_fingerprint);
  for v_candidate in select value from jsonb_array_elements(p_candidates) loop
    insert into tongs.hammer_short_candidates(id,discovery_id,basis_lock_id,workspace_id,parent_workpiece_id,proposal_id,rank,segment_ids,core_output_start_sec,core_output_end_sec,duration_sec,envelope_output_start_sec,envelope_output_end_sec,source_intervals,transcript_excerpt,rationale,goal_fit,candidate_fingerprint)
    values((v_candidate->>'candidate_id')::uuid,p_discovery_id,v_discovery.basis_lock_id,v_discovery.workspace_id,v_discovery.parent_workpiece_id,v_candidate->>'proposal_id',(v_candidate->>'rank')::integer,v_candidate->'segment_ids',(v_candidate->>'core_output_start_sec')::numeric,(v_candidate->>'core_output_end_sec')::numeric,(v_candidate->>'duration_sec')::numeric,(v_candidate->>'envelope_output_start_sec')::numeric,(v_candidate->>'envelope_output_end_sec')::numeric,v_candidate->'source_intervals',v_candidate->>'transcript_excerpt',v_candidate->>'rationale',v_candidate->>'goal_fit',v_candidate->>'candidate_fingerprint');
  end loop;
  update tongs.hammer_shorts_discoveries set state='completed',outcome=p_outcome,completed_at=now() where id=p_discovery_id returning * into v_discovery;
  return jsonb_build_object('discovery',to_jsonb(v_discovery),'candidates',(select coalesce(jsonb_agg(to_jsonb(c) order by c.rank),'[]'::jsonb) from tongs.hammer_short_candidates c where c.discovery_id=p_discovery_id));
end $$;


ALTER FUNCTION "tongs"."complete_hammer_shorts_discovery"("p_discovery_id" "uuid", "p_ai_proposal" "jsonb", "p_candidates" "jsonb", "p_outcome" "text", "p_proposal_fingerprint" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."complete_my_hearth_script_proposal_application"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_proposal_id" "uuid", "p_canonical_revision_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare proposal tongs.hearth_script_generation_proposals%rowtype;
  binding tongs.hearth_script_generation_proposal_draft_bindings%rowtype;
  current_file tongs.workpiece_files%rowtype; applied_event tongs.hearth_script_generation_proposal_events%rowtype;
begin
  if auth.uid() is null or not tongs.has_workspace_role(p_workspace_id,'editor') then
    raise exception 'workspace editor authority required' using errcode='42501';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('hearth-script-proposal:'||p_proposal_id::text,0));
  select * into proposal from tongs.hearth_script_generation_proposals
    where id=p_proposal_id and user_id=auth.uid() and workspace_id=p_workspace_id
      and workpiece_id=p_workpiece_id for share;
  if proposal.id is null then return jsonb_build_object('disposition','not_found'); end if;
  select * into applied_event from tongs.hearth_script_generation_proposal_events
    where proposal_id=proposal.id and event_type='applied';
  if applied_event.id is not null then
    return jsonb_build_object(
      'disposition','applied_replay','proposal_id',proposal.id,
      'applied_draft_revision',applied_event.applied_draft_revision,
      'applied_draft_hash',applied_event.applied_draft_hash,
      'canonical_revision_id',applied_event.canonical_revision_id
    );
  end if;
  if exists(select 1 from tongs.hearth_script_generation_proposal_events
    where proposal_id=proposal.id and event_type in ('rejected','superseded')) then
    return jsonb_build_object('disposition','terminal_conflict','proposal_id',proposal.id);
  end if;
  if not exists(select 1 from tongs.hearth_script_generation_proposal_events
    where proposal_id=proposal.id and event_type='application_started') then
    return jsonb_build_object('disposition','application_not_started','proposal_id',proposal.id);
  end if;
  select * into binding from tongs.hearth_script_generation_proposal_draft_bindings
    where proposal_id=proposal.id;
  select * into current_file from tongs.workpiece_files
    where workpiece_id=proposal.workpiece_id and path=binding.expected_draft_path for share;
  if current_file.revision<>binding.expected_draft_revision+1
    or lower(current_file.hash_value)=binding.expected_draft_hash
    or btrim(coalesce(p_canonical_revision_id,''))<>'hearth-script-proposal-'||proposal.id::text then
    return jsonb_build_object(
      'disposition','canonical_commit_unverified','proposal_id',proposal.id,
      'expected_previous_revision',binding.expected_draft_revision,
      'current_draft_revision',current_file.revision,
      'current_draft_hash',lower(current_file.hash_value)
    );
  end if;
  insert into tongs.hearth_script_generation_proposal_events(
    proposal_id,event_type,idempotency_key,actor_id,
    expected_draft_revision,expected_draft_hash,applied_draft_revision,
    applied_draft_hash,canonical_revision_id,details
  ) values(
    proposal.id,'applied','hearth-script-proposal:applied:'||proposal.id::text,auth.uid(),
    binding.expected_draft_revision,binding.expected_draft_hash,current_file.revision,
    lower(current_file.hash_value),btrim(p_canonical_revision_id),
    jsonb_build_object('workspace_id',p_workspace_id,'workpiece_id',p_workpiece_id)
  ) returning * into applied_event;
  return jsonb_build_object(
    'disposition','applied','proposal_id',proposal.id,
    'applied_draft_revision',applied_event.applied_draft_revision,
    'applied_draft_hash',applied_event.applied_draft_hash,
    'canonical_revision_id',applied_event.canonical_revision_id
  );
end $$;


ALTER FUNCTION "tongs"."complete_my_hearth_script_proposal_application"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_proposal_id" "uuid", "p_canonical_revision_id" "text") OWNER TO "postgres";


