CREATE OR REPLACE FUNCTION "tongs"."complete_publishing_oauth_connection_attempt"("p_attempt_id" "uuid", "p_success" boolean, "p_failure_code" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
begin
  if auth.role()<>'service_role' then raise exception 'Forbidden' using errcode='42501'; end if;
  update tongs.publishing_oauth_connection_attempts set state=case when p_success then 'completed' else 'failed' end,failure_code=case when p_success then null else coalesce(nullif(btrim(p_failure_code),''),'oauth_callback_failed') end,updated_at=now() where id=p_attempt_id and state='consumed';
  if not found then return jsonb_build_object('disposition','blocked','code','oauth_attempt_not_consumed'); end if;
  return jsonb_build_object('disposition','completed','success',p_success);
end; $$;


ALTER FUNCTION "tongs"."complete_publishing_oauth_connection_attempt"("p_attempt_id" "uuid", "p_success" boolean, "p_failure_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."configure_account_authority_classification"("p_user_id" "uuid", "p_operator_user_id" "uuid", "p_account_class" "text", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_revision integer;
  v_event_id uuid := gen_random_uuid();
  v_reason text := btrim(coalesce(p_reason, ''));
begin
  if coalesce(current_setting('request.jwt.claim.role', true), '') <> 'service_role'
     or p_operator_user_id is null
     or not tongs.is_platform_operator(p_operator_user_id) then
    raise exception 'service-role platform operator required' using errcode = '42501';
  end if;
  if p_user_id is null or p_account_class not in ('customer', 'owner')
     or length(v_reason) not between 3 and 500 then
    raise exception 'invalid account authority classification revision' using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended('account-authority-classification:' || p_user_id::text, 0)
  );
  select coalesce(max(revision), 0) + 1 into v_revision
  from tongs.account_authority_classification_events
  where user_id = p_user_id;

  insert into tongs.account_authority_classification_events(
    id, user_id, revision, account_class, reason, actor_id, evidence
  ) values (
    v_event_id, p_user_id, v_revision, p_account_class, v_reason,
    p_operator_user_id, jsonb_build_object('source', 'canonical_admin_rpc')
  );

  insert into tongs.account_authority_classifications(
    user_id, account_class, revision, reason, configured_by, configured_at
  ) values (
    p_user_id, p_account_class, v_revision, v_reason, p_operator_user_id, now()
  )
  on conflict (user_id) do update
    set account_class = excluded.account_class,
        revision = excluded.revision,
        reason = excluded.reason,
        configured_by = excluded.configured_by,
        configured_at = excluded.configured_at;

  return jsonb_build_object(
    'user_id', p_user_id,
    'account_class', p_account_class,
    'revision', v_revision,
    'event_id', v_event_id
  );
end
$$;


ALTER FUNCTION "tongs"."configure_account_authority_classification"("p_user_id" "uuid", "p_operator_user_id" "uuid", "p_account_class" "text", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."configure_account_authority_classification"("p_user_id" "uuid", "p_operator_user_id" "uuid", "p_account_class" "text", "p_reason" "text") IS 'Service-role platform-operator mutation path for append-only account authority revisions.';



CREATE OR REPLACE FUNCTION "tongs"."configure_organization_funding_account"("p_org_id" "uuid", "p_payer_user_id" "uuid", "p_currency" "text", "p_status" "text", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $_$
declare v_actor uuid:=auth.uid(); v_revision integer; v_id uuid:=gen_random_uuid();
begin
  if v_actor is null or not exists(select 1 from tongs.org_members om where om.org_id=p_org_id and om.user_id=v_actor and om.org_role in ('owner','admin')) then
    raise exception 'organization owner or admin required' using errcode='42501'; end if;
  if not exists(select 1 from tongs.org_members om where om.org_id=p_org_id and om.user_id=p_payer_user_id)
     or upper(btrim(coalesce(p_currency,'')))!~'^[A-Z]{3}$' or p_status not in ('draft','active','disabled')
     or length(btrim(coalesce(p_reason,''))) not between 3 and 500 then raise exception 'invalid organization funding account revision' using errcode='22023'; end if;
  perform pg_advisory_xact_lock(hashtextextended('org-funding-account:'||p_org_id::text,0));
  select coalesce(max(revision),0)+1 into v_revision from tongs.organization_funding_account_revisions where org_id=p_org_id;
  insert into tongs.organization_funding_account_revisions(id,org_id,revision,payer_user_id,currency,status,reason,actor_id)
  values(v_id,p_org_id,v_revision,p_payer_user_id,upper(btrim(p_currency)),p_status,btrim(p_reason),v_actor);
  return jsonb_build_object('revision_id',v_id,'revision',v_revision,'status',p_status);
end $_$;


ALTER FUNCTION "tongs"."configure_organization_funding_account"("p_org_id" "uuid", "p_payer_user_id" "uuid", "p_currency" "text", "p_status" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."configure_organization_shared_spend_permission"("p_org_id" "uuid", "p_member_user_id" "uuid", "p_status" "text", "p_route_codes" "text"[], "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare v_actor uuid:=auth.uid(); v_revision integer; v_id uuid:=gen_random_uuid();
begin
  if v_actor is null or not exists(select 1 from tongs.org_members om where om.org_id=p_org_id and om.user_id=v_actor and om.org_role in ('owner','admin')) then
    raise exception 'organization owner or admin required' using errcode='42501'; end if;
  if not exists(select 1 from tongs.org_members om where om.org_id=p_org_id and om.user_id=p_member_user_id)
     or p_status not in ('allowed','revoked') or p_route_codes is null
     or length(btrim(coalesce(p_reason,''))) not between 3 and 500 then raise exception 'invalid organization spend permission revision' using errcode='22023'; end if;
  perform pg_advisory_xact_lock(hashtextextended('org-spend-permission:'||p_org_id::text||':'||p_member_user_id::text,0));
  select coalesce(max(revision),0)+1 into v_revision from tongs.organization_shared_spend_permission_revisions where org_id=p_org_id and member_user_id=p_member_user_id;
  insert into tongs.organization_shared_spend_permission_revisions(id,org_id,member_user_id,revision,status,route_codes,reason,actor_id)
  values(v_id,p_org_id,p_member_user_id,v_revision,p_status,p_route_codes,btrim(p_reason),v_actor);
  return jsonb_build_object('revision_id',v_id,'revision',v_revision,'status',p_status);
end $$;


ALTER FUNCTION "tongs"."configure_organization_shared_spend_permission"("p_org_id" "uuid", "p_member_user_id" "uuid", "p_status" "text", "p_route_codes" "text"[], "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."configure_owner_testing_principal"("p_user_id" "uuid", "p_operator_user_id" "uuid", "p_status" "text", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_actor uuid := p_operator_user_id;
  v_revision integer;
  v_id uuid := gen_random_uuid();
begin
  if coalesce(auth.role(),'') <> 'service_role' or v_actor is null
     or not tongs.is_platform_operator(v_actor) then
    raise exception 'service-role platform operator required' using errcode='42501';
  end if;
  if p_user_id is null or p_status not in ('enabled','disabled')
     or length(btrim(coalesce(p_reason,''))) not between 3 and 500 then
    raise exception 'invalid owner-testing principal revision' using errcode='22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('owner-testing-principal:'||p_user_id::text,0));
  select coalesce(max(revision),0)+1 into v_revision
  from tongs.owner_testing_principal_events where user_id=p_user_id;
  insert into tongs.owner_testing_principal_events(id,user_id,revision,status,reason,actor_id)
  values(v_id,p_user_id,v_revision,p_status,btrim(p_reason),v_actor);
  insert into tongs.owner_testing_principals(user_id,status,revision,reason,configured_by)
  values(p_user_id,p_status,v_revision,btrim(p_reason),v_actor)
  on conflict(user_id) do update set status=excluded.status,revision=excluded.revision,
    reason=excluded.reason,configured_by=excluded.configured_by,configured_at=now();
  return jsonb_build_object('user_id',p_user_id,'status',p_status,'revision',v_revision,'event_id',v_id);
end $$;


ALTER FUNCTION "tongs"."configure_owner_testing_principal"("p_user_id" "uuid", "p_operator_user_id" "uuid", "p_status" "text", "p_reason" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "tongs"."bellows_upload_parts" (
    "id" "text" NOT NULL,
    "segment_id" "text" NOT NULL,
    "session_id" "text" NOT NULL,
    "participant_id" "text" NOT NULL,
    "workspace_id" "uuid" NOT NULL,
    "sequence_number" integer NOT NULL,
    "byte_length" bigint NOT NULL,
    "sha256" "text" NOT NULL,
    "storage_bucket" "text" DEFAULT 'bellows-capture'::"text" NOT NULL,
    "storage_key" "text" NOT NULL,
    "upload_state" "text" DEFAULT 'queued'::"text" NOT NULL,
    "attempt_count" integer DEFAULT 0 NOT NULL,
    "last_error" "text",
    "verified_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "bellows_upload_parts_attempt_count_check" CHECK (("attempt_count" >= 0)),
    CONSTRAINT "bellows_upload_parts_byte_length_check" CHECK (("byte_length" >= 0)),
    CONSTRAINT "bellows_upload_parts_check" CHECK ((("upload_state" = 'verified_received'::"text") = ("verified_at" IS NOT NULL))),
    CONSTRAINT "bellows_upload_parts_sequence_number_check" CHECK (("sequence_number" >= 0)),
    CONSTRAINT "bellows_upload_parts_sha256_check" CHECK (("length"("sha256") = 64)),
    CONSTRAINT "bellows_upload_parts_upload_state_check" CHECK (("upload_state" = ANY (ARRAY['queued'::"text", 'uploading'::"text", 'retryable_failed'::"text", 'permanently_failed'::"text", 'verified_received'::"text"])))
);


ALTER TABLE "tongs"."bellows_upload_parts" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."confirm_bellows_upload_part"("p_part_id" "text", "p_sha256" "text") RETURNS "tongs"."bellows_upload_parts"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public', 'auth'
    AS $$
declare v_part tongs.bellows_upload_parts;
begin
  select * into v_part from tongs.bellows_upload_parts where id=p_part_id for update;
  if not found then raise exception 'bellows_upload_part_not_found'; end if;
  perform tongs.bellows_assert_capture_participant(v_part.session_id,v_part.participant_id);
  if v_part.sha256<>lower(p_sha256) then raise exception 'bellows_upload_part_checksum_conflict'; end if;
  update tongs.bellows_upload_parts
    set upload_state='verified_received', verified_at=coalesce(verified_at,now()),
        attempt_count=attempt_count+1, last_error=null
    where id=p_part_id returning * into v_part;
  return v_part;
end $$;


ALTER FUNCTION "tongs"."confirm_bellows_upload_part"("p_part_id" "text", "p_sha256" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."confirm_manual_handoff"("p_snapshot_id" "uuid", "p_result_url" "text", "p_supersedes_receipt_id" "uuid" DEFAULT NULL::"uuid", "p_evidence_json" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare u uuid:=auth.uid(); s tongs.manual_handoff_snapshots%rowtype; prior tongs.manual_handoff_confirmation_receipts%rowtype; cap jsonb; host text; rev integer; n uuid;
begin
 select * into s from tongs.manual_handoff_snapshots where id=p_snapshot_id for update; if not found then return jsonb_build_object('disposition','missing'); end if;
 if u is null or not tongs.has_workspace_role(s.workspace_id,'editor') then raise exception 'Not authorized to confirm manual handoff' using errcode='42501'; end if;
 if tongs.manual_handoff_freshness(s.id)<>'current' then return jsonb_build_object('disposition','blocked','code','manual_handoff_stale'); end if;
 host:=substring(lower(btrim(p_result_url)) from '^https://([^/:?#]+)'); select capabilities_json into cap from tongs.quench_destination_capability_revisions where id=s.destination_capability_revision_id;
 if host is null or not exists(select 1 from jsonb_array_elements_text(coalesce(cap->'allowed_result_hosts','[]'::jsonb))x where lower(x)=host) then return jsonb_build_object('disposition','invalid','code','manual_handoff_result_url_not_allowed'); end if;
 select * into prior from tongs.manual_handoff_confirmation_receipts where manual_handoff_snapshot_id=s.id order by revision desc limit 1;
 if found and (p_supersedes_receipt_id is null or p_supersedes_receipt_id<>prior.id) then return jsonb_build_object('disposition','conflict','code','manual_handoff_supersession_required','current_receipt_id',prior.id); end if;
 rev:=coalesce(prior.revision,0)+1; insert into tongs.manual_handoff_confirmation_receipts(manual_handoff_snapshot_id,revision,supersedes_receipt_id,outcome,result_url,evidence_json,confirmed_by) values(s.id,rev,prior.id,'creator_confirmed',btrim(p_result_url),coalesce(p_evidence_json,'{}'::jsonb),u) returning id into n;
 return jsonb_build_object('disposition','confirmed','receipt_id',n,'revision',rev,'outcome','creator_confirmed');
end$$;


ALTER FUNCTION "tongs"."confirm_manual_handoff"("p_snapshot_id" "uuid", "p_result_url" "text", "p_supersedes_receipt_id" "uuid", "p_evidence_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."connect_user_ai_key"("p_provider" "text", "p_encrypted_api_key" "text", "p_key_label" "text" DEFAULT NULL::"text", "p_provider_account_id" "text" DEFAULT NULL::"text", "p_key_version" integer DEFAULT 1, "p_validation_mode" "text" DEFAULT 'lazy'::"text", "p_last_validated_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_last_validation_status" "text" DEFAULT NULL::"text") RETURNS TABLE("provider" "text", "provider_account_id" "text", "key_label" "text", "key_version" integer, "validation_mode" "text", "status" "text", "connected" boolean, "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "last_validated_at" timestamp with time zone, "last_validation_status" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare
  v_user_id uuid;
  v_provider text;
  v_validation_mode text;
begin
  v_user_id := auth.uid();
  if v_user_id is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;

  v_provider := lower(btrim(coalesce(p_provider, '')));
  if v_provider = '' then
    raise exception 'Provider is required' using errcode = '22023';
  end if;

  if btrim(coalesce(p_encrypted_api_key, '')) = '' then
    raise exception 'Encrypted API key is required' using errcode = '22023';
  end if;

  v_validation_mode := lower(btrim(coalesce(p_validation_mode, 'lazy')));
  if v_validation_mode not in ('strict', 'lazy') then
    raise exception 'Invalid validation_mode' using errcode = '22023';
  end if;

  insert into tongs.user_ai_keys (
    user_id,
    provider,
    provider_account_id,
    encrypted_api_key,
    key_label,
    key_version,
    validation_mode,
    status,
    last_validated_at,
    last_validation_status
  )
  values (
    v_user_id,
    v_provider,
    nullif(btrim(coalesce(p_provider_account_id, '')), ''),
    p_encrypted_api_key,
    nullif(btrim(coalesce(p_key_label, '')), ''),
    greatest(1, coalesce(p_key_version, 1)),
    v_validation_mode,
    'active',
    p_last_validated_at,
    nullif(btrim(coalesce(p_last_validation_status, '')), '')
  )
  on conflict (user_id, provider, provider_account_id)
  do update set
    encrypted_api_key = excluded.encrypted_api_key,
    key_label = excluded.key_label,
    key_version = excluded.key_version,
    validation_mode = excluded.validation_mode,
    status = 'active',
    last_validated_at = excluded.last_validated_at,
    last_validation_status = excluded.last_validation_status,
    updated_at = now();

  return query
  select
    s.provider,
    s.provider_account_id,
    s.key_label,
    s.key_version,
    s.validation_mode,
    s.status,
    (s.status = 'active') as connected,
    s.created_at,
    s.updated_at,
    s.last_validated_at,
    s.last_validation_status
  from tongs.user_ai_keys_safe s
  where s.user_id = v_user_id
    and s.provider = v_provider
    and s.provider_account_id is not distinct from nullif(btrim(coalesce(p_provider_account_id, '')), '');
end;
$$;


ALTER FUNCTION "tongs"."connect_user_ai_key"("p_provider" "text", "p_encrypted_api_key" "text", "p_key_label" "text", "p_provider_account_id" "text", "p_key_version" integer, "p_validation_mode" "text", "p_last_validated_at" timestamp with time zone, "p_last_validation_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."consume_beta_test_credits"("p_consumption_id" "uuid", "p_grant_id" "uuid", "p_allocation_key" "text", "p_operation_id" "text", "p_credit_units" bigint, "p_customer_value_micros" bigint, "p_wholesale_spend_micros" bigint, "p_metadata_json" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  grant_row tongs.beta_credit_grants%rowtype;
  existing tongs.beta_credit_consumptions%rowtype;
  used_units bigint;
  used_value bigint;
  used_wholesale bigint;
  payload jsonb;
begin
  perform tongs._require_accounting_service_role();
  if p_consumption_id is null or p_grant_id is null or p_credit_units <= 0
     or p_customer_value_micros <> p_credit_units * 5000
     or p_wholesale_spend_micros < 0
     or length(btrim(coalesce(p_allocation_key, ''))) not between 8 and 300
     or length(btrim(coalesce(p_operation_id, ''))) not between 8 and 300 then
    raise exception 'invalid beta credit consumption' using errcode = '22023';
  end if;
  select * into grant_row from tongs.beta_credit_grants where id = p_grant_id for update;
  if not found then raise exception 'beta credit grant not found' using errcode = 'P0002'; end if;
  select * into existing from tongs.beta_credit_consumptions
  where allocation_key = btrim(p_allocation_key)
     or (grant_id = p_grant_id and operation_id = btrim(p_operation_id))
  limit 1;
  if found then
    if existing.id <> p_consumption_id or existing.credit_units_consumed <> p_credit_units
       or existing.customer_value_micros <> p_customer_value_micros
       or existing.wholesale_spend_micros <> p_wholesale_spend_micros then
      raise exception 'beta credit consumption replay conflict' using errcode = '23505';
    end if;
    return to_jsonb(existing) || jsonb_build_object('replay', true);
  end if;
  select coalesce(sum(credit_units_consumed),0), coalesce(sum(customer_value_micros),0),
    coalesce(sum(wholesale_spend_micros),0)
  into used_units, used_value, used_wholesale
  from tongs.beta_credit_consumptions where grant_id = p_grant_id;
  if p_credit_units > grant_row.credit_units - used_units
     or p_customer_value_micros > grant_row.customer_value_micros - used_value
     or p_wholesale_spend_micros > grant_row.maximum_wholesale_capacity_micros - used_wholesale then
    raise exception 'insufficient beta Forge Credits' using errcode = 'P0001';
  end if;
  payload := jsonb_build_object(
    'consumption_id', p_consumption_id, 'grant_id', p_grant_id,
    'operation_id', btrim(p_operation_id), 'credit_units', p_credit_units,
    'customer_value_micros', p_customer_value_micros,
    'wholesale_spend_micros', p_wholesale_spend_micros,
    'metadata', coalesce(p_metadata_json, '{}'::jsonb)
  );
  perform tongs._create_accounting_event(
    p_consumption_id, 'beta-credit-consumption:' || btrim(p_allocation_key),
    'beta_test_credits_consumed', 'test', 'forge_operation', btrim(p_operation_id),
    'USD', grant_row.user_id, grant_row.workspace_id, null, payload, now()
  );
  insert into tongs.beta_credit_consumptions(
    id, grant_id, user_id, allocation_key, operation_id,
    credit_units_consumed, customer_value_micros, wholesale_spend_micros,
    journal_event_id, metadata_json
  ) values (
    p_consumption_id, p_grant_id, grant_row.user_id, btrim(p_allocation_key),
    btrim(p_operation_id), p_credit_units, p_customer_value_micros,
    p_wholesale_spend_micros, p_consumption_id, coalesce(p_metadata_json, '{}'::jsonb)
  ) returning * into existing;
  insert into tongs.accounting_journal_entries(
    event_id, line_number, account_code, user_id, workspace_id,
    beta_credit_grant_id, currency, amount_micros
  ) values
    (p_consumption_id, 1, 'beta_credit_deferred_value', grant_row.user_id,
      grant_row.workspace_id, p_grant_id, 'USD', p_customer_value_micros),
    (p_consumption_id, 2, 'service_revenue', grant_row.user_id,
      grant_row.workspace_id, p_grant_id, 'USD', -p_customer_value_micros);
  insert into tongs.accounting_journal_entries(
    event_id, line_number, account_code, user_id, workspace_id,
    beta_credit_grant_id, unit_kind, quantity_delta
  ) values (
    p_consumption_id, 3, 'beta_forge_credit_units', grant_row.user_id,
    grant_row.workspace_id, p_grant_id, 'forge_credit', -p_credit_units
  );
  perform tongs._assert_accounting_event_balanced(p_consumption_id);
  return to_jsonb(existing) || jsonb_build_object('replay', false);
end $$;


ALTER FUNCTION "tongs"."consume_beta_test_credits"("p_consumption_id" "uuid", "p_grant_id" "uuid", "p_allocation_key" "text", "p_operation_id" "text", "p_credit_units" bigint, "p_customer_value_micros" bigint, "p_wholesale_spend_micros" bigint, "p_metadata_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."consume_customer_deposit"("p_consumption_id" "uuid", "p_deposit_id" "uuid", "p_allocation_key" "text", "p_operation_id" "text", "p_revenue_micros" bigint, "p_credit_units" bigint, "p_consumed_at" timestamp with time zone, "p_metadata_json" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_deposit tongs.customer_deposits%rowtype; v_existing tongs.customer_deposit_consumptions%rowtype;
  v_key text:=nullif(btrim(coalesce(p_allocation_key,'')),''); v_operation text:=nullif(btrim(coalesce(p_operation_id,'')),'');
  v_consumed_micros bigint; v_refund_liability bigint; v_fee bigint; v_prior_fee_allocated bigint;
  v_fee_allocation bigint; v_available_units bigint; v_payload jsonb;
begin
  perform tongs._require_accounting_service_role();
  if p_consumption_id is null or p_deposit_id is null or v_key is null or v_operation is null
     or p_revenue_micros<=0 or p_credit_units<=0 then raise exception 'invalid deposit consumption' using errcode='22023'; end if;
  select * into v_deposit from tongs.customer_deposits where id=p_deposit_id for update;
  if not found then raise exception 'deposit not found' using errcode='P0002'; end if;
  select * into v_existing from tongs.customer_deposit_consumptions
    where allocation_key=v_key or (deposit_id=p_deposit_id and operation_id=v_operation) limit 1;
  if found then
    if v_existing.deposit_id<>p_deposit_id or v_existing.allocation_key<>v_key or v_existing.operation_id<>v_operation
       or v_existing.recognized_revenue_micros<>p_revenue_micros or v_existing.credit_units_consumed<>p_credit_units
    then raise exception 'deposit consumption replay conflict' using errcode='23505'; end if;
    return jsonb_build_object('consumption_id',v_existing.id,'replay',true);
  end if;
  select fee_amount_micros into v_fee from tongs.customer_deposit_processor_fees where deposit_id=p_deposit_id;
  if not found then raise exception 'processor fee must be finalized before consumption' using errcode='P0001'; end if;
  select coalesce(sum(recognized_revenue_micros),0),coalesce(sum(allocated_processor_fee_micros),0)
    into v_consumed_micros,v_prior_fee_allocated from tongs.customer_deposit_consumptions where deposit_id=p_deposit_id;
  select coalesce(sum(liability_release_micros),0) into v_refund_liability from tongs.customer_deposit_refunds where deposit_id=p_deposit_id;
  v_available_units:=tongs._unconsumed_deposit_credit_units(p_deposit_id);
  if p_revenue_micros>tongs._unconsumed_deposit_value_micros(p_deposit_id) or p_credit_units>v_available_units
  then raise exception 'insufficient verified deposit balance' using errcode='P0001'; end if;
  v_fee_allocation:=greatest((v_fee*(v_consumed_micros+p_revenue_micros)/v_deposit.gross_amount_micros)-least(v_prior_fee_allocated,(v_fee*(v_consumed_micros+p_revenue_micros)/v_deposit.gross_amount_micros)),0);
  v_payload:=jsonb_build_object('consumption_id',p_consumption_id,'deposit_id',p_deposit_id,'allocation_key',v_key,
    'operation_id',v_operation,'recognized_revenue_micros',p_revenue_micros,'credit_units_consumed',p_credit_units,
    'allocated_processor_fee_micros',v_fee_allocation,'metadata',coalesce(p_metadata_json,'{}'::jsonb));
  perform tongs._create_accounting_event(p_consumption_id,'deposit-consumption:'||v_key,'customer_deposit_consumed',
    v_deposit.stripe_mode,'forge_operation',v_operation,v_deposit.currency,v_deposit.user_id,null,null,v_payload,coalesce(p_consumed_at,now()));
  insert into tongs.customer_deposit_consumptions(id,deposit_id,user_id,allocation_key,operation_id,recognized_revenue_micros,
    credit_units_consumed,allocated_processor_fee_micros,journal_event_id,metadata_json,consumed_at)
  values(p_consumption_id,p_deposit_id,v_deposit.user_id,v_key,v_operation,p_revenue_micros,p_credit_units,
    v_fee_allocation,p_consumption_id,coalesce(p_metadata_json,'{}'::jsonb),coalesce(p_consumed_at,now())) returning * into v_existing;
  insert into tongs.accounting_journal_entries(event_id,line_number,account_code,user_id,deposit_id,currency,amount_micros) values
    (p_consumption_id,1,case when v_deposit.stripe_mode='live' then 'customer_prepaid_liability' else 'test_customer_prepaid_balance' end,v_deposit.user_id,p_deposit_id,v_deposit.currency,p_revenue_micros),
    (p_consumption_id,2,case when v_deposit.stripe_mode='live' then 'service_revenue' else 'test_ai_consumption_revenue' end,v_deposit.user_id,p_deposit_id,v_deposit.currency,-p_revenue_micros);
  insert into tongs.accounting_journal_entries(event_id,line_number,account_code,user_id,deposit_id,unit_kind,quantity_delta)
  values(p_consumption_id,3,case when v_deposit.stripe_mode='live' then 'live_customer_credits' else 'test_customer_credits' end,
    v_deposit.user_id,p_deposit_id,'forge_credit',-p_credit_units);
  perform tongs._assert_accounting_event_balanced(p_consumption_id);
  return jsonb_build_object('consumption_id',p_consumption_id,'replay',false,'allocated_processor_fee_micros',v_fee_allocation);
end $$;


ALTER FUNCTION "tongs"."consume_customer_deposit"("p_consumption_id" "uuid", "p_deposit_id" "uuid", "p_allocation_key" "text", "p_operation_id" "text", "p_revenue_micros" bigint, "p_credit_units" bigint, "p_consumed_at" timestamp with time zone, "p_metadata_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."consume_owner_operating_budget"("p_consumption_id" "uuid", "p_budget_id" "uuid", "p_reservation_id" "uuid", "p_allocation_key" "text", "p_operation_id" "text", "p_expense_amount_micros" bigint, "p_consumed_at" timestamp with time zone, "p_evidence_json" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_budget tongs.owner_operating_budgets%rowtype;
  v_revision tongs.owner_operating_budget_revisions%rowtype;
  v_reservation tongs.funding_reservations%rowtype;
  v_existing tongs.owner_operating_budget_consumptions%rowtype;
  v_consumed bigint;
  v_key text:=nullif(btrim(coalesce(p_allocation_key,'')),'');
  v_operation text:=nullif(btrim(coalesce(p_operation_id,'')),'');
  v_payload jsonb;
begin
  perform tongs._require_pricing_service_role();
  if p_consumption_id is null or p_budget_id is null or p_reservation_id is null
     or v_key is null or v_operation is null or p_expense_amount_micros<=0
     or jsonb_typeof(coalesce(p_evidence_json,'null'::jsonb))<>'object' then
    raise exception 'invalid owner budget consumption' using errcode='22023';
  end if;
  select * into v_budget from tongs.owner_operating_budgets where id=p_budget_id for update;
  if not found then raise exception 'owner operating budget not found' using errcode='P0002'; end if;
  select * into v_revision from tongs.owner_operating_budget_revisions
    where budget_id=p_budget_id order by revision desc limit 1;
  select * into v_reservation from tongs.funding_reservations where id=p_reservation_id for update;
  if not found or v_reservation.funding_source_type<>'owner_budget'
     or v_reservation.funding_source_id<>p_budget_id or v_reservation.operation_id<>v_operation then
    raise exception 'matching owner-funded reservation required' using errcode='P0001';
  end if;
  if v_revision.status not in ('active','paused','closed') or v_revision.maximum_amount_micros is null
     or v_reservation.created_at<v_budget.period_start or v_reservation.created_at>=v_budget.period_end then
    raise exception 'reservation was not funded inside a capped owner budget period' using errcode='P0001';
  end if;
  select * into v_existing from tongs.owner_operating_budget_consumptions
    where allocation_key=v_key or reservation_id=p_reservation_id limit 1;
  if found then
    if v_existing.budget_id<>p_budget_id or v_existing.operation_id<>v_operation
       or v_existing.expense_amount_micros<>p_expense_amount_micros then
      raise exception 'owner budget consumption replay conflict' using errcode='23505';
    end if;
    return jsonb_build_object('consumption_id',v_existing.id,'replay',true,
      'customer_revenue_micros',0,'margin','not_applicable');
  end if;
  select tongs._owner_operating_budget_effective_consumed(p_budget_id) into v_consumed;
  if v_consumed+p_expense_amount_micros>v_revision.maximum_amount_micros then
    insert into tongs.owner_operating_budget_discrepancies(
      id,budget_id,reservation_id,discrepancy_key,maximum_amount_micros,
      prior_consumed_micros,observed_expense_micros,evidence_json
    ) values(gen_random_uuid(),p_budget_id,p_reservation_id,v_key||':budget-overrun',
      v_revision.maximum_amount_micros,v_consumed,p_expense_amount_micros,
      coalesce(p_evidence_json,'{}'::jsonb)) on conflict(discrepancy_key) do nothing;
  end if;
  v_payload:=jsonb_build_object('consumption_id',p_consumption_id,'budget_id',p_budget_id,
    'reservation_id',p_reservation_id,'operation_id',v_operation,
    'expense_amount_micros',p_expense_amount_micros,'customer_revenue_micros',0,
    'margin','not_applicable','evidence',coalesce(p_evidence_json,'{}'::jsonb));
  perform tongs._create_accounting_event(
    p_consumption_id,'owner-budget-consumption:'||v_key,'owner_operating_budget_consumed',
    'owner_internal','forge_operation',v_operation,v_budget.currency,null,v_budget.workspace_id,null,
    v_payload,coalesce(p_consumed_at,now()));
  insert into tongs.owner_operating_budget_consumptions(
    id,budget_id,reservation_id,operation_id,allocation_key,expense_amount_micros,
    currency,journal_event_id,evidence_json,consumed_at
  ) values(p_consumption_id,p_budget_id,p_reservation_id,v_operation,v_key,p_expense_amount_micros,
    v_budget.currency,p_consumption_id,coalesce(p_evidence_json,'{}'::jsonb),coalesce(p_consumed_at,now()));
  insert into tongs.accounting_journal_entries(
    event_id,line_number,account_code,workspace_id,owner_budget_id,currency,amount_micros
  ) values
    (p_consumption_id,1,'owner_research_qa_expense',v_budget.workspace_id,p_budget_id,v_budget.currency,p_expense_amount_micros),
    (p_consumption_id,2,'forge_cash_clearing',v_budget.workspace_id,p_budget_id,v_budget.currency,-p_expense_amount_micros);
  perform tongs._assert_accounting_event_balanced(p_consumption_id);
  return jsonb_build_object('consumption_id',p_consumption_id,'replay',false,
    'remaining_budget_micros',v_revision.maximum_amount_micros-v_consumed-p_expense_amount_micros,
    'customer_revenue_micros',0,'margin','not_applicable');
end;
$$;


ALTER FUNCTION "tongs"."consume_owner_operating_budget"("p_consumption_id" "uuid", "p_budget_id" "uuid", "p_reservation_id" "uuid", "p_allocation_key" "text", "p_operation_id" "text", "p_expense_amount_micros" bigint, "p_consumed_at" timestamp with time zone, "p_evidence_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."consume_paid_allowance"("p_consumption_id" "uuid", "p_allowance_grant_id" "uuid", "p_allocation_key" "text", "p_operation_id" "text", "p_entitlement_units" bigint, "p_recognized_revenue_micros" bigint, "p_wholesale_spend_micros" bigint, "p_consumed_at" timestamp with time zone, "p_metadata_json" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_grant tongs.paid_allowance_grants%rowtype;
  v_existing tongs.paid_allowance_consumptions%rowtype;
  v_key text := nullif(btrim(coalesce(p_allocation_key, '')), '');
  v_operation text := nullif(btrim(coalesce(p_operation_id, '')), '');
  v_used_units bigint;
  v_used_revenue bigint;
  v_used_spend bigint;
  v_payload jsonb;
begin
  perform tongs._require_accounting_service_role();
  if p_consumption_id is null or p_allowance_grant_id is null or v_key is null or v_operation is null
     or p_entitlement_units <= 0 or p_recognized_revenue_micros <= 0 or p_wholesale_spend_micros < 0 then
    raise exception 'invalid paid allowance consumption' using errcode = '22023';
  end if;
  select * into v_grant from tongs.paid_allowance_grants where id = p_allowance_grant_id for update;
  if not found then raise exception 'paid allowance grant not found' using errcode = 'P0002'; end if;
  if now() < v_grant.period_start or now() >= v_grant.period_end then
    raise exception 'paid allowance is outside its funded period' using errcode = 'P0001';
  end if;
  if exists (select 1 from tongs.subscription_cycle_adjustments where receipt_id = v_grant.receipt_id) then
    raise exception 'adjusted subscription cycle cannot fund new consumption' using errcode = 'P0001';
  end if;
  select * into v_existing from tongs.paid_allowance_consumptions
   where allocation_key = v_key or (allowance_grant_id = p_allowance_grant_id and operation_id = v_operation)
   limit 1;
  if found then
    if v_existing.allowance_grant_id <> p_allowance_grant_id
       or v_existing.allocation_key <> v_key or v_existing.operation_id <> v_operation
       or v_existing.entitlement_units_consumed <> p_entitlement_units
       or v_existing.recognized_revenue_micros <> p_recognized_revenue_micros
       or v_existing.wholesale_spend_micros <> p_wholesale_spend_micros then
      raise exception 'allowance consumption replay conflict' using errcode = '23505';
    end if;
    return jsonb_build_object('consumption_id', v_existing.id, 'replay', true);
  end if;
  select coalesce(sum(entitlement_units_consumed), 0), coalesce(sum(recognized_revenue_micros), 0),
    coalesce(sum(wholesale_spend_micros), 0)
  into v_used_units, v_used_revenue, v_used_spend
  from tongs.paid_allowance_consumptions where allowance_grant_id = p_allowance_grant_id;
  if p_entitlement_units > v_grant.entitlement_units - v_used_units
     or p_recognized_revenue_micros > v_grant.allocated_revenue_micros - v_used_revenue
     or p_wholesale_spend_micros > v_grant.maximum_wholesale_spend_micros - v_used_spend then
    raise exception 'insufficient funded allowance balance' using errcode = 'P0001';
  end if;
  v_payload := jsonb_build_object('consumption_id', p_consumption_id,
    'allowance_grant_id', p_allowance_grant_id, 'allocation_key', v_key,
    'operation_id', v_operation, 'entitlement_units_consumed', p_entitlement_units,
    'recognized_revenue_micros', p_recognized_revenue_micros,
    'wholesale_spend_micros', p_wholesale_spend_micros,
    'metadata', coalesce(p_metadata_json, '{}'::jsonb));
  perform tongs._create_accounting_event(
    p_consumption_id, 'allowance-consumption:' || v_key, 'paid_allowance_consumed', v_grant.financial_environment, 'forge_operation', v_operation, v_grant.currency, v_grant.user_id,
    null, null, v_payload, coalesce(p_consumed_at, now())
  );
  insert into tongs.paid_allowance_consumptions(
    id, allowance_grant_id, user_id, allocation_key, operation_id,
    entitlement_units_consumed, recognized_revenue_micros, wholesale_spend_micros,
    journal_event_id, metadata_json, consumed_at
  ) values (
    p_consumption_id, p_allowance_grant_id, v_grant.user_id, v_key, v_operation,
    p_entitlement_units, p_recognized_revenue_micros, p_wholesale_spend_micros,
    p_consumption_id, coalesce(p_metadata_json, '{}'::jsonb), coalesce(p_consumed_at, now())
  );
  insert into tongs.accounting_journal_entries(
    event_id, line_number, account_code, user_id, allowance_grant_id, currency, amount_micros
  ) values
    (p_consumption_id, 1, case when v_grant.financial_environment = 'live' then 'allowance_deferred_liability' else 'test_allowance_deferred_balance' end, v_grant.user_id,
      p_allowance_grant_id, v_grant.currency, p_recognized_revenue_micros),
    (p_consumption_id, 2, case when v_grant.financial_environment = 'live' then 'service_revenue' else 'test_ai_consumption_revenue' end, v_grant.user_id,
      p_allowance_grant_id, v_grant.currency, -p_recognized_revenue_micros);
  insert into tongs.accounting_journal_entries(
    event_id, line_number, account_code, user_id, allowance_grant_id, unit_kind, quantity_delta
  ) values
    (p_consumption_id, 3, case when v_grant.financial_environment = 'live' then 'allowance_entitlement_units' else 'test_allowance_entitlement_units' end, v_grant.user_id,
      p_allowance_grant_id, 'forge_credit', -p_entitlement_units);
  if p_wholesale_spend_micros > 0 then
    insert into tongs.accounting_journal_entries(
      event_id, line_number, account_code, user_id, allowance_grant_id, unit_kind, quantity_delta
    ) values (p_consumption_id, 4, case when v_grant.financial_environment = 'live' then 'allowance_wholesale_capacity_micros' else 'test_allowance_wholesale_capacity_micros' end, v_grant.user_id,
      p_allowance_grant_id, lower(v_grant.currency) || '_micros', -p_wholesale_spend_micros);
  end if;
  perform tongs._assert_accounting_event_balanced(p_consumption_id);
  return jsonb_build_object('consumption_id', p_consumption_id, 'replay', false,
    'remaining_entitlement_units', v_grant.entitlement_units - v_used_units - p_entitlement_units,
    'remaining_revenue_micros', v_grant.allocated_revenue_micros - v_used_revenue - p_recognized_revenue_micros,
    'remaining_wholesale_spend_micros', v_grant.maximum_wholesale_spend_micros - v_used_spend - p_wholesale_spend_micros);
end;
$$;


ALTER FUNCTION "tongs"."consume_paid_allowance"("p_consumption_id" "uuid", "p_allowance_grant_id" "uuid", "p_allocation_key" "text", "p_operation_id" "text", "p_entitlement_units" bigint, "p_recognized_revenue_micros" bigint, "p_wholesale_spend_micros" bigint, "p_consumed_at" timestamp with time zone, "p_metadata_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."consume_publishing_oauth_connection_attempt"("p_provider" "text", "p_state_hash" "text", "p_expected_redirect_uri" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare v_attempt tongs.publishing_oauth_connection_attempts%rowtype;
begin
  if auth.role()<>'service_role' then raise exception 'Forbidden' using errcode='42501'; end if;
  select * into v_attempt from tongs.publishing_oauth_connection_attempts where state_hash=p_state_hash for update;
  if not found then return jsonb_build_object('disposition','blocked','code','oauth_state_invalid'); end if;
  if v_attempt.state<>'pending' then return jsonb_build_object('disposition','blocked','code','oauth_state_replayed'); end if;
  if v_attempt.expires_at<=now() then
    update tongs.publishing_oauth_connection_attempts set state='expired',consumed_at=now(),failure_code='oauth_state_expired',updated_at=now() where id=v_attempt.id;
    return jsonb_build_object('disposition','blocked','code','oauth_state_expired');
  end if;
  if v_attempt.provider<>p_provider or v_attempt.expected_redirect_uri<>p_expected_redirect_uri then return jsonb_build_object('disposition','blocked','code','oauth_state_context_mismatch'); end if;
  update tongs.publishing_oauth_connection_attempts set state='consumed',consumed_at=now(),updated_at=now() where id=v_attempt.id;
  return jsonb_build_object('disposition','consumed','oauth_attempt_id',v_attempt.id,'connection_id',v_attempt.connection_id,'owner_user_id',v_attempt.owner_user_id,'encrypted_pkce_verifier',v_attempt.encrypted_pkce_verifier,'encryption_key_version',v_attempt.encryption_key_version,'ciphertext_version',v_attempt.ciphertext_version);
end; $$;


ALTER FUNCTION "tongs"."consume_publishing_oauth_connection_attempt"("p_provider" "text", "p_state_hash" "text", "p_expected_redirect_uri" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."consume_test_refill"("p_consumption_id" "uuid", "p_grant_id" "uuid", "p_operation_id" "text", "p_credit_units" bigint, "p_provider_mode" "text", "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare v_grant tongs.test_refill_grants%rowtype; v_existing tongs.test_refill_consumptions%rowtype;
  v_used bigint; v_event uuid:=gen_random_uuid();
begin
  perform tongs._require_accounting_service_role();
  if p_provider_mode<>'simulated' then raise exception 'Test refill cannot authorize a real provider' using errcode='42501'; end if;
  if p_consumption_id is null or p_grant_id is null or p_credit_units<=0
     or length(btrim(coalesce(p_operation_id,''))) not between 8 and 300
     or length(btrim(coalesce(p_idempotency_key,''))) not between 8 and 300 then raise exception 'invalid Test consumption' using errcode='22023'; end if;
  perform pg_advisory_xact_lock(hashtextextended('test-refill-consumption:'||p_grant_id::text,0));
  select * into v_existing from tongs.test_refill_consumptions where idempotency_key=btrim(p_idempotency_key);
  if found then
    if v_existing.id<>p_consumption_id or v_existing.grant_id<>p_grant_id or v_existing.operation_id<>btrim(p_operation_id)
       or v_existing.credit_units<>p_credit_units then raise exception 'Test consumption replay conflict' using errcode='23505'; end if;
    return jsonb_build_object('consumption_id',v_existing.id,'replay',true,'environment','test','customer_revenue_micros',0);
  end if;
  select * into v_grant from tongs.test_refill_grants where id=p_grant_id for update;
  if not found or (v_grant.expires_at is not null and v_grant.expires_at<=now()) then raise exception 'eligible Test refill not found' using errcode='P0002'; end if;
  select coalesce(sum(credit_units),0) into v_used from tongs.test_refill_consumptions where grant_id=p_grant_id;
  if p_credit_units>v_grant.credit_units-v_used then raise exception 'insufficient Test refill' using errcode='P0001'; end if;
  perform tongs._create_accounting_event(v_event,'test-consumption:'||btrim(p_idempotency_key),
    'test_refill_consumed','test','simulated_operation',btrim(p_operation_id),null,v_grant.user_id,null,null,
    jsonb_build_object('credit_units',p_credit_units,'provider_mode','simulated','customer_revenue',false),now());
  insert into tongs.accounting_journal_entries(event_id,line_number,account_code,user_id,quantity_delta,unit_kind,metadata_json)
  values(v_event,1,'test_credit_available',v_grant.user_id,-p_credit_units,'test_credit',jsonb_build_object('provider_mode','simulated'));
  insert into tongs.test_refill_consumptions(id,grant_id,operation_id,credit_units,provider_mode,idempotency_key,journal_event_id)
  values(p_consumption_id,p_grant_id,btrim(p_operation_id),p_credit_units,'simulated',btrim(p_idempotency_key),v_event);
  return jsonb_build_object('consumption_id',p_consumption_id,'replay',false,'environment','test','customer_revenue_micros',0,'remaining_credit_units',v_grant.credit_units-v_used-p_credit_units);
end $$;


ALTER FUNCTION "tongs"."consume_test_refill"("p_consumption_id" "uuid", "p_grant_id" "uuid", "p_operation_id" "text", "p_credit_units" bigint, "p_provider_mode" "text", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."control_openai_text_failure_loss_environment"("p_decision_id" "uuid", "p_actor_id" "uuid", "p_route_code" "text", "p_financial_environment" "text", "p_decision_type" "text", "p_additional_loss_capacity_micros" bigint, "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  existing_decision tongs.openai_text_failure_loss_operator_decisions%rowtype;
  current_rollout tongs.openai_text_failure_loss_rollout_revisions%rowtype;
  policy tongs.openai_text_failure_loss_policy_revisions%rowtype;
  known_exposure bigint:=0;
  concurrency integer:=0;
  next_revision integer;
  resulting_mode text;
  effective_limit bigint;
begin
  perform tongs._require_pricing_service_role();
  if p_decision_id is null or p_actor_id is null
    or nullif(btrim(coalesce(p_route_code,'')),'') is null
    or p_financial_environment not in('test','live')
    or p_decision_type not in(
      'emergency_halt','policy_enforce','bounded_test_risk_acceptance'
    )
    or length(btrim(coalesce(p_reason,'')))<12 then
    raise exception 'invalid failure-loss operator decision' using errcode='22023';
  end if;
  if not tongs.is_platform_operator(p_actor_id) then
    raise exception 'platform operator required' using errcode='42501';
  end if;
  if p_decision_type='bounded_test_risk_acceptance' then
    if p_financial_environment<>'test'
      or p_additional_loss_capacity_micros is null
      or p_additional_loss_capacity_micros<=0 then
      raise exception 'bounded risk acceptance is Test-only and requires finite added capacity'
        using errcode='22023';
    end if;
  elsif p_additional_loss_capacity_micros is not null then
    raise exception 'added loss capacity is valid only for bounded Test risk acceptance'
      using errcode='22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    'openai-text-loss:'||btrim(p_route_code)||':'||p_financial_environment,0));
  select * into existing_decision
  from tongs.openai_text_failure_loss_operator_decisions decision
  where decision.id=p_decision_id;
  if found then
    if existing_decision.actor_id is distinct from p_actor_id
      or existing_decision.route_code is distinct from btrim(p_route_code)
      or existing_decision.financial_environment is distinct from p_financial_environment
      or existing_decision.decision_type is distinct from p_decision_type
      or existing_decision.additional_loss_capacity_micros
        is distinct from p_additional_loss_capacity_micros
      or existing_decision.reason is distinct from btrim(p_reason) then
      raise exception 'operator decision idempotency conflict' using errcode='23505';
    end if;
    return jsonb_build_object(
      'decision_id',existing_decision.id,'replay',true,
      'route_code',existing_decision.route_code,
      'financial_environment',existing_decision.financial_environment,
      'decision_type',existing_decision.decision_type,
      'known_exposure_micros',existing_decision.known_exposure_micros,
      'additional_loss_capacity_micros',existing_decision.additional_loss_capacity_micros,
      'effective_aggregate_limit_micros',existing_decision.effective_aggregate_limit_micros,
      'rollout_revision',existing_decision.resulting_rollout_revision,
      'rollout_mode',existing_decision.resulting_rollout_mode
    );
  end if;

  select * into policy
  from tongs.openai_text_failure_loss_policy_revisions policy_row
  where policy_row.route_code=btrim(p_route_code)
    and policy_row.environment=p_financial_environment
    and policy_row.lifecycle_state='active'
  order by policy_row.revision desc limit 1;
  select * into current_rollout
  from tongs._current_openai_text_failure_loss_rollout(
    btrim(p_route_code),p_financial_environment);
  if policy.id is null or current_rollout.route_code is null
    or current_rollout.loss_policy_revision_id is distinct from policy.id then
    raise exception 'environment-scoped OpenAI failure-loss policy is not active'
      using errcode='42501';
  end if;
  select exposure.committed_micros,exposure.concurrency_count
  into known_exposure,concurrency
  from tongs._openai_text_failure_loss_exposure(
    policy.route_code,p_financial_environment,policy.rolling_window_seconds) exposure;

  if p_decision_type='bounded_test_risk_acceptance' then
    if p_additional_loss_capacity_micros>policy.per_operation_limit_micros then
      raise exception 'added Test loss capacity exceeds the hard per-operation limit'
        using errcode='22023';
    end if;
    resulting_mode:='operator_authorized';
    effective_limit:=known_exposure+p_additional_loss_capacity_micros;
  elsif p_decision_type='policy_enforce' then
    resulting_mode:='enforce';
    effective_limit:=policy.aggregate_limit_micros;
  else
    resulting_mode:='halt_new';
    effective_limit:=null;
  end if;

  select coalesce(max(revision),0)+1 into next_revision
  from tongs.openai_text_failure_loss_rollout_revisions rollout
  where rollout.route_code=policy.route_code
    and rollout.financial_environment=p_financial_environment;

  insert into tongs.openai_text_failure_loss_operator_decisions(
    id,route_code,financial_environment,decision_type,loss_policy_revision_id,
    source_rollout_revision,source_rollout_mode,resulting_rollout_revision,
    resulting_rollout_mode,known_exposure_micros,active_concurrency,
    base_aggregate_limit_micros,additional_loss_capacity_micros,
    effective_aggregate_limit_micros,reason,actor_id
  ) values(
    p_decision_id,policy.route_code,p_financial_environment,p_decision_type,policy.id,
    current_rollout.revision,current_rollout.mode,next_revision,resulting_mode,
    known_exposure,concurrency,policy.aggregate_limit_micros,
    p_additional_loss_capacity_micros,effective_limit,btrim(p_reason),p_actor_id
  );
  insert into tongs.openai_text_failure_loss_rollout_revisions(
    route_code,financial_environment,revision,mode,loss_policy_revision_id,
    source_limit_event_id,reason,actor_id,operator_decision_id
  ) values(
    policy.route_code,p_financial_environment,next_revision,resulting_mode,policy.id,
    null,btrim(p_reason),p_actor_id,p_decision_id
  );

  return jsonb_build_object(
    'decision_id',p_decision_id,'replay',false,'route_code',policy.route_code,
    'financial_environment',p_financial_environment,'decision_type',p_decision_type,
    'known_exposure_micros',known_exposure,
    'additional_loss_capacity_micros',p_additional_loss_capacity_micros,
    'effective_aggregate_limit_micros',effective_limit,
    'hard_per_operation_limit_micros',policy.per_operation_limit_micros,
    'hard_maximum_concurrency',policy.maximum_concurrency,
    'rollout_revision',next_revision,'rollout_mode',resulting_mode
  );
end $$;


ALTER FUNCTION "tongs"."control_openai_text_failure_loss_environment"("p_decision_id" "uuid", "p_actor_id" "uuid", "p_route_code" "text", "p_financial_environment" "text", "p_decision_type" "text", "p_additional_loss_capacity_micros" bigint, "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."control_openai_text_failure_loss_environment"("p_decision_id" "uuid", "p_actor_id" "uuid", "p_route_code" "text", "p_financial_environment" "text", "p_decision_type" "text", "p_additional_loss_capacity_micros" bigint, "p_reason" "text") IS 'Appends audited operator halt, base-policy enforcement, or finite Test-only risk acceptance without changing policy limits or exposure history.';



CREATE OR REPLACE FUNCTION "tongs"."correct_customer_operation_relief"("p_correction_id" "uuid", "p_relief_id" "uuid", "p_reservation_id" "uuid", "p_original_consumption_id" "uuid", "p_canonical_result_id" "uuid", "p_funding_environment" "text", "p_corrected_credit_units" bigint, "p_corrected_customer_credit_micros" bigint, "p_corrected_revenue_micros" bigint, "p_reason_code" "text", "p_reason" "text", "p_idempotency_key" "text", "p_operator_user_id" "uuid", "p_evidence_json" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $_$
declare
  v_key text:=btrim(coalesce(p_idempotency_key,''));
  v_reason_code text:=btrim(coalesce(p_reason_code,''));
  v_reason text:=btrim(coalesce(p_reason,''));
  v_evidence jsonb:=coalesce(p_evidence_json,'{}'::jsonb);
  v_existing tongs.customer_operation_relief_corrections%rowtype;
  v_relief tongs.customer_operation_reliefs%rowtype;
  v_reservation tongs.funding_reservations%rowtype;
  v_consumption tongs.customer_deposit_consumptions%rowtype;
  v_result tongs.openai_text_persisted_results%rowtype;
  v_settlement tongs.funding_reservation_events%rowtype;
  v_workspace_id uuid;
  v_positive_money_count integer;
  v_negative_money_count integer;
  v_unit_count integer;
  v_positive_money_total bigint;
  v_negative_money_total bigint;
  v_unit_total bigint;
  v_revenue_account text;
  v_liability_account text;
  v_credit_account text;
  v_prior_units bigint;
  v_prior_customer_micros bigint;
  v_prior_revenue_micros bigint;
  v_payload jsonb;
begin
  perform tongs._require_accounting_service_role();
  if p_operator_user_id is null or not tongs.is_platform_operator(p_operator_user_id) then
    raise exception 'service-role platform operator required' using errcode='42501';
  end if;
  if p_correction_id is null or p_relief_id is null or p_reservation_id is null
     or p_original_consumption_id is null or p_canonical_result_id is null
     or p_funding_environment not in ('test','live')
     or coalesce(p_corrected_credit_units,0)<=0
     or coalesce(p_corrected_customer_credit_micros,0)<=0
     or coalesce(p_corrected_revenue_micros,0)<=0
     or p_corrected_customer_credit_micros<>p_corrected_revenue_micros
     or v_reason_code !~ '^[a-z][a-z0-9_]{2,95}$'
     or v_reason=''
     or length(v_key) not between 8 and 240
     or jsonb_typeof(v_evidence)<>'object' then
    raise exception 'invalid customer-operation relief correction' using errcode='22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('customer-relief-correction:'||p_relief_id::text,0));
  select * into v_existing
  from tongs.customer_operation_relief_corrections correction
  where correction.id=p_correction_id or correction.idempotency_key=v_key
  order by (correction.id=p_correction_id) desc
  limit 1;
  if found then
    if v_existing.id<>p_correction_id
       or v_existing.relief_id<>p_relief_id
       or v_existing.reservation_id<>p_reservation_id
       or v_existing.original_consumption_id<>p_original_consumption_id
       or v_existing.canonical_result_id<>p_canonical_result_id
       or v_existing.funding_environment<>p_funding_environment
       or v_existing.corrected_credit_units<>p_corrected_credit_units
       or v_existing.corrected_customer_credit_micros<>p_corrected_customer_credit_micros
       or v_existing.corrected_revenue_micros<>p_corrected_revenue_micros
       or v_existing.reason_code<>v_reason_code
       or v_existing.reason<>v_reason
       or v_existing.idempotency_key<>v_key
       or v_existing.operator_actor_id<>p_operator_user_id
       or v_existing.evidence_json<>v_evidence then
      raise exception 'customer-operation relief correction replay conflict' using errcode='23505';
    end if;
    return jsonb_build_object(
      'correction_id',v_existing.id,'journal_event_id',v_existing.journal_event_id,
      'relief_id',v_existing.relief_id,'replay',true,
      'corrected_credit_units',v_existing.corrected_credit_units,
      'corrected_customer_credit_micros',v_existing.corrected_customer_credit_micros,
      'corrected_revenue_micros',v_existing.corrected_revenue_micros
    );
  end if;

  select * into v_relief from tongs.customer_operation_reliefs
  where id=p_relief_id for update;
  if not found then raise exception 'customer-operation relief not found' using errcode='P0002'; end if;
  select * into v_reservation from tongs.funding_reservations
  where id=p_reservation_id;
  if not found then raise exception 'funding reservation not found' using errcode='P0002'; end if;
  if v_relief.reservation_id<>v_reservation.id
     or v_relief.funding_source_id<>v_reservation.funding_source_id
     or v_relief.funding_source_type<>v_reservation.funding_source_type then
    raise exception 'relief and reservation do not match' using errcode='22023';
  end if;
  if v_reservation.funding_environment<>p_funding_environment then
    raise exception 'relief correction environment mismatch' using errcode='22023';
  end if;
  -- Purchased-credit relief is the only balance authority that presently
  -- restores customer-operation relief. Fail closed for allowance/beta rows
  -- until their own canonical projections explicitly support correction.
  if v_relief.funding_source_type<>'customer_deposit' then
    raise exception 'relief correction requires purchased-credit funding' using errcode='22023';
  end if;
  if v_relief.original_consumption_id<>p_original_consumption_id then
    raise exception 'original consumption does not match relief' using errcode='22023';
  end if;
  select * into v_consumption from tongs.customer_deposit_consumptions
  where id=p_original_consumption_id;
  if not found or v_consumption.deposit_id<>v_relief.funding_source_id
     or v_consumption.user_id<>v_reservation.user_id
     or v_consumption.operation_id<>v_reservation.operation_id then
    raise exception 'original consumption does not match reservation' using errcode='22023';
  end if;
  select * into v_result from tongs.openai_text_persisted_results
  where id=p_canonical_result_id;
  if not found or v_result.reservation_id<>v_reservation.id
     or v_result.user_id<>v_reservation.user_id
     or not exists (
       select 1 from tongs.openai_text_funding_bindings binding
       where binding.reservation_id=v_reservation.id
         and binding.operation_id=v_result.operation_id
         and binding.route_code=v_result.route_code
         and binding.credential_funding='forge'
     ) then
    raise exception 'qualifying canonical paid result not found' using errcode='P0002';
  end if;
  select * into v_settlement from tongs.funding_reservation_events
  where reservation_id=v_reservation.id and event_type='settled'
  order by sequence desc limit 1;
  if not found or coalesce(v_settlement.customer_charge_micros,0)<v_relief.customer_credit_micros
     or coalesce(v_settlement.credit_units,0)<v_relief.restored_units
     or v_consumption.recognized_revenue_micros<v_relief.revenue_reversal_micros
     or v_consumption.credit_units_consumed<v_relief.restored_units then
    raise exception 'relief lacks matching successful settlement evidence' using errcode='22023';
  end if;

  select coalesce(sum(corrected_credit_units),0),
         coalesce(sum(corrected_customer_credit_micros),0),
         coalesce(sum(corrected_revenue_micros),0)
    into v_prior_units,v_prior_customer_micros,v_prior_revenue_micros
  from tongs.customer_operation_relief_corrections
  where relief_id=v_relief.id;
  if v_prior_units+p_corrected_credit_units>v_relief.restored_units then
    raise exception 'relief correction exceeds restored credit units' using errcode='22003';
  end if;
  if v_prior_customer_micros+p_corrected_customer_credit_micros>v_relief.customer_credit_micros
     or v_prior_revenue_micros+p_corrected_revenue_micros>v_relief.revenue_reversal_micros then
    raise exception 'relief correction exceeds monetary relief' using errcode='22003';
  end if;

  select
    count(*) filter(where entry.currency=v_relief.currency and entry.amount_micros>0),
    count(*) filter(where entry.currency=v_relief.currency and entry.amount_micros<0),
    count(*) filter(where entry.unit_kind='forge_credit' and entry.quantity_delta>0),
    coalesce(sum(entry.amount_micros) filter(where entry.currency=v_relief.currency and entry.amount_micros>0),0),
    coalesce(sum(entry.amount_micros) filter(where entry.currency=v_relief.currency and entry.amount_micros<0),0),
    coalesce(sum(entry.quantity_delta) filter(where entry.unit_kind='forge_credit'),0),
    max(entry.account_code) filter(where entry.currency=v_relief.currency and entry.amount_micros>0),
    max(entry.account_code) filter(where entry.currency=v_relief.currency and entry.amount_micros<0),
    max(entry.account_code) filter(where entry.unit_kind='forge_credit' and entry.quantity_delta>0)
  into v_positive_money_count,v_negative_money_count,v_unit_count,
       v_positive_money_total,v_negative_money_total,v_unit_total,
       v_revenue_account,v_liability_account,v_credit_account
  from tongs.accounting_journal_entries entry
  where entry.event_id=v_relief.journal_event_id;
  if v_positive_money_count<>1 or v_negative_money_count<>1 or v_unit_count<>1
     or v_positive_money_total<>v_relief.revenue_reversal_micros
     or v_negative_money_total<>-v_relief.revenue_reversal_micros
     or v_unit_total<>v_relief.restored_units then
    raise exception 'target relief journal is not a canonical reversible relief' using errcode='22023';
  end if;
  select workspace_id into v_workspace_id from tongs.accounting_journal_events
  where id=v_relief.journal_event_id;

  v_payload:=jsonb_build_object(
    'correction_id',p_correction_id,'relief_id',v_relief.id,
    'reservation_id',v_reservation.id,'original_consumption_id',v_consumption.id,
    'canonical_result_id',v_result.id,'funding_environment',p_funding_environment,
    'corrected_credit_units',p_corrected_credit_units,
    'corrected_customer_credit_micros',p_corrected_customer_credit_micros,
    'corrected_revenue_micros',p_corrected_revenue_micros,
    'reason_code',v_reason_code,'reason',v_reason,'evidence',v_evidence
  );
  perform tongs._create_accounting_event(
    p_correction_id,'customer-relief-correction:'||v_key,
    'customer_operation_relief_corrected',p_funding_environment,
    'customer_operation_relief',v_relief.id::text,v_relief.currency,
    v_reservation.user_id,v_workspace_id,p_operator_user_id,v_payload,now()
  );
  insert into tongs.customer_operation_relief_corrections(
    id,relief_id,reservation_id,original_consumption_id,canonical_result_id,
    funding_environment,corrected_credit_units,corrected_customer_credit_micros,
    corrected_revenue_micros,reason_code,reason,idempotency_key,
    operator_actor_id,journal_event_id,evidence_json,corrected_at
  ) values (
    p_correction_id,v_relief.id,v_reservation.id,v_consumption.id,v_result.id,
    p_funding_environment,p_corrected_credit_units,p_corrected_customer_credit_micros,
    p_corrected_revenue_micros,v_reason_code,v_reason,v_key,
    p_operator_user_id,p_correction_id,v_evidence,now()
  ) returning * into v_existing;
  insert into tongs.accounting_journal_entries(
    event_id,line_number,account_code,user_id,workspace_id,deposit_id,
    currency,amount_micros,metadata_json
  ) values
    (p_correction_id,1,v_revenue_account,v_reservation.user_id,v_workspace_id,
      v_relief.funding_source_id,v_relief.currency,-p_corrected_revenue_micros,
      jsonb_build_object('relief_id',v_relief.id)),
    (p_correction_id,2,v_liability_account,v_reservation.user_id,v_workspace_id,
      v_relief.funding_source_id,v_relief.currency,p_corrected_revenue_micros,
      jsonb_build_object('relief_id',v_relief.id));
  insert into tongs.accounting_journal_entries(
    event_id,line_number,account_code,user_id,workspace_id,deposit_id,
    unit_kind,quantity_delta,metadata_json
  ) values (
    p_correction_id,3,v_credit_account,v_reservation.user_id,v_workspace_id,
    v_relief.funding_source_id,'forge_credit',-p_corrected_credit_units,
    jsonb_build_object('relief_id',v_relief.id)
  );
  perform tongs._assert_accounting_event_balanced(p_correction_id);
  return jsonb_build_object(
    'correction_id',v_existing.id,'journal_event_id',v_existing.journal_event_id,
    'relief_id',v_existing.relief_id,'replay',false,
    'corrected_credit_units',v_existing.corrected_credit_units,
    'corrected_customer_credit_micros',v_existing.corrected_customer_credit_micros,
    'corrected_revenue_micros',v_existing.corrected_revenue_micros
  );
end $_$;


ALTER FUNCTION "tongs"."correct_customer_operation_relief"("p_correction_id" "uuid", "p_relief_id" "uuid", "p_reservation_id" "uuid", "p_original_consumption_id" "uuid", "p_canonical_result_id" "uuid", "p_funding_environment" "text", "p_corrected_credit_units" bigint, "p_corrected_customer_credit_micros" bigint, "p_corrected_revenue_micros" bigint, "p_reason_code" "text", "p_reason" "text", "p_idempotency_key" "text", "p_operator_user_id" "uuid", "p_evidence_json" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."correct_customer_operation_relief"("p_correction_id" "uuid", "p_relief_id" "uuid", "p_reservation_id" "uuid", "p_original_consumption_id" "uuid", "p_canonical_result_id" "uuid", "p_funding_environment" "text", "p_corrected_credit_units" bigint, "p_corrected_customer_credit_micros" bigint, "p_corrected_revenue_micros" bigint, "p_reason_code" "text", "p_reason" "text", "p_idempotency_key" "text", "p_operator_user_id" "uuid", "p_evidence_json" "jsonb") IS 'Operator-authorized, idempotent correction of a linked purchased-credit relief with canonical result evidence joined through its immutable Forge funding binding.';



CREATE OR REPLACE FUNCTION "tongs"."correct_owner_hearth_compatibility_result_after_nonbillable_rej"("p_reservation_id" "uuid", "p_event_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare released jsonb; op tongs.owner_hearth_operation_authorizations%rowtype;
 resultrow tongs.owner_hearth_compatibility_results%rowtype;
 existing tongs.owner_hearth_compatibility_result_corrections%rowtype;
begin
 perform tongs._require_pricing_service_role();
 released:=tongs.release_owner_hearth_definitive_nonbillable_rejection(p_reservation_id,btrim(p_event_key)||':exposure');
 if coalesce((released->>'released')::boolean,false) is not true then
  return released||jsonb_build_object('corrected',false); end if;
 select * into op from tongs.owner_hearth_operation_authorizations where reservation_id=p_reservation_id;
 select * into resultrow from tongs.owner_hearth_compatibility_results where operation_authorization_id=op.id;
 if resultrow.id is null then return released||jsonb_build_object('corrected',false,'effective_status','definitive_rejection'); end if;
 if resultrow.status='definitive_rejection' then
  return released||jsonb_build_object('corrected',false,'effective_status','definitive_rejection'); end if;
 if resultrow.status<>'billed_failure' then
  raise exception 'only a billed-failure compatibility result can receive this correction' using errcode='P0001'; end if;
 insert into tongs.owner_hearth_compatibility_result_corrections(
  id,compatibility_result_id,event_key,original_status,corrected_status,reason,evidence_json
 ) values(
  extensions.uuid_generate_v5(resultrow.id,btrim(p_event_key)||':result-correction'),resultrow.id,btrim(p_event_key)||':result-correction',
  'billed_failure','definitive_rejection','Provider returned credit_balance_exhausted before billable generation; original result remains immutable.',
  jsonb_build_object('provider_request_id',coalesce(released->>'provider_request_id',resultrow.provider_request_id),
   'provider_status',released->>'provider_status','provider_code',released->>'provider_code',
   'provider_cost_reconciled_authoritative',false,'original_history_preserved',true)
 ) on conflict(compatibility_result_id) do nothing;
 select * into existing from tongs.owner_hearth_compatibility_result_corrections where compatibility_result_id=resultrow.id;
 return released||jsonb_build_object('corrected',true,'correction_id',existing.id,'effective_status',existing.corrected_status,
  'provider_request_id',coalesce(released->>'provider_request_id',resultrow.provider_request_id));
end $$;


ALTER FUNCTION "tongs"."correct_owner_hearth_compatibility_result_after_nonbillable_rej"("p_reservation_id" "uuid", "p_event_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."correct_owner_hearth_nonbillable_result"("p_reservation_id" "uuid", "p_event_key" "text") RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
 select tongs.correct_owner_hearth_compatibility_result_after_nonbillable_rej(p_reservation_id,p_event_key);
$$;


ALTER FUNCTION "tongs"."correct_owner_hearth_nonbillable_result"("p_reservation_id" "uuid", "p_event_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."count_missing_org_members_for_org"("p_org_id" "uuid") RETURNS TABLE("missing_members_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
begin
  if p_org_id is null then
    raise exception 'org_id is required'
      using errcode = '22023';
  end if;

  perform tongs.assert_org_role(p_org_id, 'member');

  return query
  select count(distinct tm.user_id)::bigint as missing_members_count
  from tongs.teams t
  join tongs.team_members tm
    on tm.team_id = t.id
  left join tongs.org_members om
    on om.org_id = t.org_id
   and om.user_id = tm.user_id
  where t.org_id = p_org_id
    and om.user_id is null;
end;
$$;


ALTER FUNCTION "tongs"."count_missing_org_members_for_org"("p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."create_ai_credit_quote"("p_quote_id" "uuid", "p_user_id" "uuid", "p_operation_id" "text", "p_tool" "text", "p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_pricing_policy_revision_id" "uuid", "p_request_parameters" "jsonb", "p_requested_output_count" integer, "p_provider_billable_units" bigint, "p_reservation_amount" bigint, "p_request_fingerprint" "text", "p_effective_at" timestamp with time zone, "p_expires_at" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_policy tongs.ai_pricing_policy_revisions%rowtype;
  v_sequence tongs.ai_pricing_policy_sequences%rowtype;
  v_quote tongs.ai_credit_quotes%rowtype;
  v_expense numeric;
  v_charge numeric;
  v_expected_fingerprint text;
begin
  select * into v_policy from tongs.ai_pricing_policy_revisions where id = p_pricing_policy_revision_id;
  if not found then raise exception 'pricing-policy revision not found' using errcode = 'P0002'; end if;
  select * into v_sequence from tongs.ai_pricing_policy_sequences where policy_id = v_policy.policy_id;
  if not found or v_sequence.current_revision_id <> v_policy.id or not v_policy.is_active
     or p_effective_at < v_policy.effective_from
     or (v_policy.effective_through is not null and p_effective_at >= v_policy.effective_through) then
    raise exception 'pricing-policy revision is not currently active' using errcode = 'P0001';
  end if;
  v_expense := p_provider_billable_units::numeric * v_policy.provider_price_micros_per_unit::numeric;
  v_charge := ceil(
    v_expense * v_policy.forge_credit_conversion_numerator::numeric * v_policy.markup_numerator::numeric
    / (v_policy.forge_credit_conversion_denominator::numeric * v_policy.markup_denominator::numeric)
  ) + v_policy.addon_credits;
  v_expected_fingerprint := encode(extensions.digest(convert_to(jsonb_build_object(
    'user_id', p_user_id, 'operation_id', p_operation_id, 'tool', p_tool,
    'workspace_id', p_workspace_id, 'workpiece_id', p_workpiece_id,
    'provider', v_policy.provider, 'model', v_policy.model, 'media_kind', v_policy.media_kind,
    'generation_mode', v_policy.generation_mode, 'request_parameters', p_request_parameters,
    'requested_output_count', p_requested_output_count, 'provider_billable_units', p_provider_billable_units,
    'pricing_policy_revision_id', v_policy.id, 'pricing_policy_revision', v_policy.revision
  )::text, 'utf8'), 'sha256'), 'hex');
  if p_request_fingerprint <> v_expected_fingerprint then raise exception 'quote fingerprint mismatch' using errcode = '22023'; end if;
  if p_reservation_amount < v_charge then raise exception 'reservation amount below quoted charge' using errcode = '22023'; end if;
  select * into v_quote from tongs.ai_credit_quotes where user_id = p_user_id and operation_id = p_operation_id;
  if found then
    if v_quote.id <> p_quote_id or v_quote.request_fingerprint <> p_request_fingerprint
       or v_quote.pricing_policy_revision_id <> p_pricing_policy_revision_id then
      raise exception 'quote replay conflict' using errcode = '23505';
    end if;
    return jsonb_build_object('quote', to_jsonb(v_quote), 'replay', true);
  end if;
  insert into tongs.ai_credit_quotes (
    id, user_id, operation_id, tool, workspace_id, workpiece_id, provider, model, media_kind,
    generation_mode, request_parameters, requested_output_count, provider_billable_units,
    pricing_policy_revision_id, pricing_policy_revision, estimated_provider_expense_micros,
    provider_currency, customer_credit_charge, reservation_amount, request_fingerprint, effective_at, expires_at
  ) values (
    p_quote_id, p_user_id, p_operation_id, p_tool, p_workspace_id, p_workpiece_id, v_policy.provider, v_policy.model,
    v_policy.media_kind, v_policy.generation_mode, p_request_parameters, p_requested_output_count,
    p_provider_billable_units, v_policy.id, v_policy.revision, v_expense::bigint, v_policy.provider_currency,
    v_charge::bigint, p_reservation_amount, p_request_fingerprint, p_effective_at, p_expires_at
  ) returning * into v_quote;
  return jsonb_build_object('quote', to_jsonb(v_quote), 'replay', false);
end;
$$;


ALTER FUNCTION "tongs"."create_ai_credit_quote"("p_quote_id" "uuid", "p_user_id" "uuid", "p_operation_id" "text", "p_tool" "text", "p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_pricing_policy_revision_id" "uuid", "p_request_parameters" "jsonb", "p_requested_output_count" integer, "p_provider_billable_units" bigint, "p_reservation_amount" bigint, "p_request_fingerprint" "text", "p_effective_at" timestamp with time zone, "p_expires_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."create_bellows_join_link"("p_session_id" "text", "p_role_code" "text" DEFAULT 'G1'::"text", "p_expires_hours" integer DEFAULT 24, "p_max_uses" integer DEFAULT 5, "p_created_by_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("join_link_id" "uuid", "session_id" "text", "workspace_id" "uuid", "role_code" "text", "token" "text", "expires_at" timestamp with time zone, "max_uses" integer, "use_count" integer, "revoked_at" timestamp with time zone, "last_used_at" timestamp with time zone, "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare
  v_session tongs.bellows_sessions%rowtype;
  v_user uuid;
  v_role text;
  v_hours integer;
  v_max_uses integer;
  v_token text;
  v_join_link tongs.bellows_session_join_links%rowtype;
begin
  if p_session_id is null or btrim(p_session_id) = '' then
    raise exception 'session_id is required'
      using errcode = '22023';
  end if;

  select *
  into v_session
  from tongs.bellows_sessions
  where id = btrim(p_session_id)
  for update;

  if not found then
    raise exception 'bellows_session_not_found'
      using errcode = 'P0002';
  end if;

  if v_session.lifecycle_state in ('sealed', 'incomplete_capture', 'failed_capture', 'archived') then
    raise exception 'bellows_session_not_joinable'
      using errcode = '22023';
  end if;

  if coalesce(auth.role(), '') <> 'service_role' then
    v_user := auth.uid();

    if v_user is null then
      raise exception 'Not authenticated'
        using errcode = '42501';
    end if;

    perform tongs.assert_workspace_role(v_session.workspace_id, 'editor');
  else
    v_user := coalesce(auth.uid(), p_created_by_user_id);

    if v_user is null then
      raise exception 'created_by_user_id is required for service_role'
        using errcode = '22023';
    end if;
  end if;

  v_role := upper(btrim(coalesce(p_role_code, 'G1')));
  if v_role not in ('S1', 'S2', 'G1', 'G2') then
    raise exception 'Unsupported Bellows role code: %', p_role_code
      using errcode = '22023';
  end if;

  v_hours := coalesce(p_expires_hours, 24);
  if v_hours < 1 then v_hours := 1; end if;
  if v_hours > 720 then v_hours := 720; end if;

  v_max_uses := coalesce(p_max_uses, 5);
  if v_max_uses < 1 then v_max_uses := 1; end if;
  if v_max_uses > 1000 then v_max_uses := 1000; end if;

  v_token := replace(gen_random_uuid()::text, '-', '')
    || replace(gen_random_uuid()::text, '-', '');

  insert into tongs.bellows_session_join_links (
    session_id,
    workspace_id,
    token_hash,
    created_by_user_id,
    role_code,
    expires_at,
    max_uses
  )
  values (
    v_session.id,
    v_session.workspace_id,
    tongs.hash_bellows_join_link_token(v_token),
    v_user,
    v_role,
    now() + make_interval(hours => v_hours),
    v_max_uses
  )
  returning *
  into v_join_link;

  return query
  select
    v_join_link.id,
    v_join_link.session_id,
    v_join_link.workspace_id,
    v_join_link.role_code,
    v_token,
    v_join_link.expires_at,
    v_join_link.max_uses,
    v_join_link.use_count,
    v_join_link.revoked_at,
    v_join_link.last_used_at,
    v_join_link.created_at;
end;
$$;


ALTER FUNCTION "tongs"."create_bellows_join_link"("p_session_id" "text", "p_role_code" "text", "p_expires_hours" integer, "p_max_uses" integer, "p_created_by_user_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "tongs"."bellows_sessions" (
    "id" "text" NOT NULL,
    "workspace_id" "uuid" NOT NULL,
    "host_user_id" "text" NOT NULL,
    "title" "text" NOT NULL,
    "mode" "text" NOT NULL,
    "session_type" "text" NOT NULL,
    "recording_session_id" "uuid",
    "calendar_event_id" "uuid",
    "acting_authority_state" "text" NOT NULL,
    "host_participant_id" "text",
    "acting_host_participant_id" "text",
    "co_host_participant_ids" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "lifecycle_state" "text" NOT NULL,
    "recording_state" "text" NOT NULL,
    "broadcast_state" "text" NOT NULL,
    "upload_state" "text" NOT NULL,
    "seal_state" "text" NOT NULL,
    "outcome" "text",
    "integrity_flags" "text"[] DEFAULT '{}'::"text"[] NOT NULL,
    "snapshot_schema_version" integer DEFAULT 1 NOT NULL,
    "latest_checkpoint_id" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "started_at" timestamp with time zone,
    "ended_at" timestamp with time zone,
    "sealed_at" timestamp with time zone,
    "archived_at" timestamp with time zone,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "workpiece_id" "uuid",
    "recording_capture_authority_id" "uuid",
    "authority_generation" bigint DEFAULT 1 NOT NULL,
    CONSTRAINT "bellows_sessions_acting_authority_state_check" CHECK (("acting_authority_state" = ANY (ARRAY['host_present'::"text", 'co_host_promoted'::"text", 'engine_stewardship'::"text"]))),
    CONSTRAINT "bellows_sessions_authority_generation_check" CHECK (("authority_generation" > 0)),
    CONSTRAINT "bellows_sessions_broadcast_state_check" CHECK (("broadcast_state" = ANY (ARRAY['not_broadcasting'::"text", 'starting'::"text", 'live'::"text", 'degraded'::"text", 'disconnected'::"text", 'ended'::"text"]))),
    CONSTRAINT "bellows_sessions_host_user_id_check" CHECK (("length"("btrim"("host_user_id")) > 0)),
    CONSTRAINT "bellows_sessions_id_check" CHECK (("length"("btrim"("id")) > 0)),
    CONSTRAINT "bellows_sessions_integrity_flags_check" CHECK (("integrity_flags" <@ ARRAY['missing_track'::"text", 'degraded_quality'::"text", 'participant_dropout'::"text", 'upload_interrupted'::"text", 'resync_required'::"text", 'corrupted_capture'::"text"])),
    CONSTRAINT "bellows_sessions_lifecycle_state_check" CHECK (("lifecycle_state" = ANY (ARRAY['idle'::"text", 'configuring'::"text", 'linking_accounts'::"text", 'inviting'::"text", 'waiting_for_participants'::"text", 'preflight_ready'::"text", 'preflight_checks'::"text", 'ready_to_start'::"text", 'countdown'::"text", 'sync_initializing'::"text", 'recording_active'::"text", 'recording_degraded'::"text", 'recording_offline_local'::"text", 'recording_rejoining'::"text", 'finalizing_local'::"text", 'uploading'::"text", 'upload_degraded'::"text", 'upload_paused'::"text", 'upload_resuming'::"text", 'upload_complete_pending_verification'::"text", 'verifying_integrity'::"text", 'assembling_manifest'::"text", 'sealing_session'::"text", 'sealed'::"text", 'incomplete_capture'::"text", 'failed_capture'::"text", 'archived'::"text"]))),
    CONSTRAINT "bellows_sessions_mode_check" CHECK (("mode" = ANY (ARRAY['record_only'::"text", 'live'::"text"]))),
    CONSTRAINT "bellows_sessions_outcome_check" CHECK ((("outcome" IS NULL) OR ("outcome" = ANY (ARRAY['sealed'::"text", 'incomplete_capture'::"text", 'failed_capture'::"text", 'archived'::"text"])))),
    CONSTRAINT "bellows_sessions_recording_state_check" CHECK (("recording_state" = ANY (ARRAY['idle'::"text", 'countdown'::"text", 'sync_initializing'::"text", 'active'::"text", 'degraded'::"text", 'offline_local'::"text", 'rejoining'::"text", 'stopping'::"text", 'stopped'::"text"]))),
    CONSTRAINT "bellows_sessions_seal_state_check" CHECK (("seal_state" = ANY (ARRAY['not_started'::"text", 'verifying_integrity'::"text", 'assembling_manifest'::"text", 'sealing_session'::"text", 'sealed'::"text"]))),
    CONSTRAINT "bellows_sessions_session_type_check" CHECK (("session_type" = ANY (ARRAY['remote'::"text", 'hybrid'::"text", 'solo'::"text"]))),
    CONSTRAINT "bellows_sessions_snapshot_schema_version_check" CHECK (("snapshot_schema_version" > 0)),
    CONSTRAINT "bellows_sessions_title_check" CHECK (("length"("btrim"("title")) > 0)),
    CONSTRAINT "bellows_sessions_upload_state_check" CHECK (("upload_state" = ANY (ARRAY['not_started'::"text", 'finalizing_local'::"text", 'uploading'::"text", 'degraded'::"text", 'paused'::"text", 'resuming'::"text", 'complete_pending_verification'::"text"])))
);


ALTER TABLE "tongs"."bellows_sessions" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."create_bellows_session_header"("p_session_id" "text", "p_workspace_id" "uuid", "p_host_user_id" "text", "p_title" "text", "p_mode" "text", "p_session_type" "text", "p_acting_authority_state" "text", "p_host_participant_id" "text" DEFAULT NULL::"text", "p_acting_host_participant_id" "text" DEFAULT NULL::"text", "p_co_host_participant_ids" "text"[] DEFAULT '{}'::"text"[], "p_lifecycle_state" "text" DEFAULT 'idle'::"text", "p_recording_state" "text" DEFAULT 'idle'::"text", "p_broadcast_state" "text" DEFAULT 'not_broadcasting'::"text", "p_upload_state" "text" DEFAULT 'not_started'::"text", "p_seal_state" "text" DEFAULT 'not_started'::"text", "p_outcome" "text" DEFAULT NULL::"text", "p_integrity_flags" "text"[] DEFAULT '{}'::"text"[], "p_recording_session_id" "uuid" DEFAULT NULL::"uuid", "p_calendar_event_id" "uuid" DEFAULT NULL::"uuid", "p_started_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_ended_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_sealed_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_archived_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_snapshot_schema_version" integer DEFAULT 1) RETURNS "tongs"."bellows_sessions"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare
  v_session tongs.bellows_sessions;
begin
  if p_session_id is null or btrim(p_session_id) = '' then
    raise exception 'session_id is required'
      using errcode = '22023';
  end if;

  if p_host_user_id is null or btrim(p_host_user_id) = '' then
    raise exception 'host_user_id is required'
      using errcode = '22023';
  end if;

  if coalesce(auth.role(), '') <> 'service_role' then
    perform tongs.assert_workspace_role(p_workspace_id, 'editor');
  end if;

  insert into tongs.bellows_sessions (
    id,
    workspace_id,
    host_user_id,
    title,
    mode,
    session_type,
    recording_session_id,
    calendar_event_id,
    acting_authority_state,
    host_participant_id,
    acting_host_participant_id,
    co_host_participant_ids,
    lifecycle_state,
    recording_state,
    broadcast_state,
    upload_state,
    seal_state,
    outcome,
    integrity_flags,
    snapshot_schema_version,
    started_at,
    ended_at,
    sealed_at,
    archived_at
  )
  values (
    btrim(p_session_id),
    p_workspace_id,
    btrim(p_host_user_id),
    coalesce(nullif(btrim(p_title), ''), 'Bellows Session'),
    p_mode,
    p_session_type,
    p_recording_session_id,
    p_calendar_event_id,
    p_acting_authority_state,
    nullif(btrim(coalesce(p_host_participant_id, '')), ''),
    nullif(btrim(coalesce(p_acting_host_participant_id, '')), ''),
    coalesce(p_co_host_participant_ids, '{}'::text[]),
    p_lifecycle_state,
    p_recording_state,
    p_broadcast_state,
    p_upload_state,
    p_seal_state,
    p_outcome,
    coalesce(p_integrity_flags, '{}'::text[]),
    p_snapshot_schema_version,
    p_started_at,
    p_ended_at,
    p_sealed_at,
    p_archived_at
  )
  returning *
  into v_session;

  return v_session;
end;
$$;


ALTER FUNCTION "tongs"."create_bellows_session_header"("p_session_id" "text", "p_workspace_id" "uuid", "p_host_user_id" "text", "p_title" "text", "p_mode" "text", "p_session_type" "text", "p_acting_authority_state" "text", "p_host_participant_id" "text", "p_acting_host_participant_id" "text", "p_co_host_participant_ids" "text"[], "p_lifecycle_state" "text", "p_recording_state" "text", "p_broadcast_state" "text", "p_upload_state" "text", "p_seal_state" "text", "p_outcome" "text", "p_integrity_flags" "text"[], "p_recording_session_id" "uuid", "p_calendar_event_id" "uuid", "p_started_at" timestamp with time zone, "p_ended_at" timestamp with time zone, "p_sealed_at" timestamp with time zone, "p_archived_at" timestamp with time zone, "p_snapshot_schema_version" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."create_brand_profile"("p_workspace_id" "uuid", "p_internal_label" "text", "p_rules" "jsonb", "p_operation_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare v_user uuid:=auth.uid();v_profile uuid:=gen_random_uuid();v_revision uuid:=gen_random_uuid();v_hash text;v_validation jsonb;v_errors text[];v_assets uuid[];
begin if v_user is null then raise exception 'Not authenticated' using errcode='42501';end if;perform tongs.assert_workspace_role(p_workspace_id,'editor');
 if length(btrim(coalesce(p_internal_label,'')))=0 then raise exception 'internal label is required' using errcode='22023';end if;
 v_errors:=tongs.brand_rule_errors(p_rules);select coalesce(array_agg(value::uuid),'{}') into v_assets from jsonb_each_text(coalesce(p_rules->'asset_revision_ids','{}'::jsonb));
 if exists(select 1 from unnest(v_assets)x left join tongs.brand_asset_revisions ar on ar.id=x where ar.id is null or ar.workspace_id<>p_workspace_id or ar.state<>'ready') then v_errors:=array_append(v_errors,'All referenced asset revisions must be ready and workspace-owned.');end if;
 v_hash:=tongs.brand_rules_hash(p_rules);v_validation:=jsonb_build_object('valid',cardinality(v_errors)=0,'bindable',cardinality(v_errors)=0,'errors',to_jsonb(v_errors),'asset_revision_ids',to_jsonb(v_assets));
 insert into tongs.brand_profiles(id,workspace_id,internal_label,created_by,updated_by)values(v_profile,p_workspace_id,btrim(p_internal_label),v_user,v_user);
 insert into tongs.brand_profile_revisions(id,workspace_id,profile_id,revision,rules_json,content_hash,state,eligible_for_new_use,validation_json,verified_at,created_by)values(v_revision,p_workspace_id,v_profile,1,jsonb_strip_nulls(p_rules),v_hash,case when cardinality(v_errors)=0 then 'committed' else 'ineligible' end,cardinality(v_errors)=0,v_validation,now(),v_user);
 return jsonb_build_object('profile_id',v_profile,'profile_revision_id',v_revision,'revision',1,'content_hash',v_hash,'bindable',cardinality(v_errors)=0,'errors',to_jsonb(v_errors));end $$;


ALTER FUNCTION "tongs"."create_brand_profile"("p_workspace_id" "uuid", "p_internal_label" "text", "p_rules" "jsonb", "p_operation_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."create_compound_ai_credit_quote"("p_quote_id" "uuid", "p_user_id" "uuid", "p_operation_id" "text", "p_tool" "text", "p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_pricing_policy_revision_id" "uuid", "p_request_parameters" "jsonb", "p_requested_output_count" integer, "p_usage_estimates" "jsonb", "p_reservation_amount" bigint, "p_request_fingerprint" "text", "p_effective_at" timestamp with time zone, "p_expires_at" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $_$
declare
  v_policy tongs.ai_pricing_policy_revisions%rowtype;
  v_sequence tongs.ai_pricing_policy_sequences%rowtype;
  v_quote tongs.ai_credit_quotes%rowtype;
  v_usage jsonb;
  v_row jsonb;
  v_rate tongs.ai_pricing_rate_components%rowtype;
  v_est_num numeric := 0;
  v_est_den numeric := 1;
  v_max_num numeric := 0;
  v_max_den numeric := 1;
  v_new_num numeric;
  v_new_den numeric;
  v_gcd numeric;
  v_estimated_charge bigint;
  v_maximum_charge bigint;
  v_total_max_units bigint := 0;
  v_expected_fingerprint text;
begin
  select * into v_policy from tongs.ai_pricing_policy_revisions where id = p_pricing_policy_revision_id;
  if not found or v_policy.pricing_contract_version <> 'compound_v2' then
    raise exception 'compound pricing-policy revision not found' using errcode = 'P0002';
  end if;
  select * into v_sequence from tongs.ai_pricing_policy_sequences where policy_id = v_policy.policy_id;
  if not found or v_sequence.current_revision_id <> v_policy.id or not v_policy.is_active
     or p_effective_at < v_policy.effective_from
     or (v_policy.effective_through is not null and p_effective_at >= v_policy.effective_through) then
    raise exception 'pricing-policy revision is not currently active' using errcode = 'P0001';
  end if;
  if p_quote_id is null or p_user_id is null or p_requested_output_count <= 0
     or jsonb_typeof(p_request_parameters) <> 'object'
     or jsonb_typeof(p_usage_estimates) <> 'array' or jsonb_array_length(p_usage_estimates) = 0
     or p_request_fingerprint !~ '^[0-9a-f]{64}$' then
    raise exception 'invalid compound quote request' using errcode = '22023';
  end if;

  select jsonb_agg(value order by value->>'component_kind') into v_usage
  from jsonb_array_elements(p_usage_estimates);
  if (select count(*) from jsonb_array_elements(v_usage)) <>
     (select count(distinct value->>'component_kind') from jsonb_array_elements(v_usage)) then
    raise exception 'duplicate quote usage component' using errcode = '22023';
  end if;

  for v_row in select value from jsonb_array_elements(v_usage) loop
    select * into v_rate from tongs.ai_pricing_rate_components
      where pricing_policy_revision_id = v_policy.id and component_kind = btrim(v_row->>'component_kind');
    if not found or coalesce((v_row->>'estimated_quantity')::bigint, -1) < 0
       or coalesce((v_row->>'maximum_quantity')::bigint, -1) < coalesce((v_row->>'estimated_quantity')::bigint, 0) then
      raise exception 'invalid quote usage component' using errcode = '22023';
    end if;

    v_new_num := v_est_num * v_rate.rate_denominator
      + (v_row->>'estimated_quantity')::bigint * v_rate.rate_numerator * v_est_den;
    v_new_den := v_est_den * v_rate.rate_denominator;
    v_gcd := tongs._ai_pricing_gcd(v_new_num, v_new_den);
    v_est_num := v_new_num / v_gcd;
    v_est_den := v_new_den / v_gcd;

    v_new_num := v_max_num * v_rate.rate_denominator
      + (v_row->>'maximum_quantity')::bigint * v_rate.rate_numerator * v_max_den;
    v_new_den := v_max_den * v_rate.rate_denominator;
    v_gcd := tongs._ai_pricing_gcd(v_new_num, v_new_den);
    v_max_num := v_new_num / v_gcd;
    v_max_den := v_new_den / v_gcd;
    v_total_max_units := v_total_max_units + (v_row->>'maximum_quantity')::bigint;
  end loop;

  v_estimated_charge := tongs._ai_pricing_ceil_fraction(
    v_est_num * v_policy.forge_credit_conversion_numerator * v_policy.markup_numerator,
    v_est_den * v_policy.forge_credit_conversion_denominator * v_policy.markup_denominator
  ) + v_policy.addon_credits;
  v_maximum_charge := tongs._ai_pricing_ceil_fraction(
    v_max_num * v_policy.forge_credit_conversion_numerator * v_policy.markup_numerator,
    v_max_den * v_policy.forge_credit_conversion_denominator * v_policy.markup_denominator
  ) + v_policy.addon_credits;
  if p_reservation_amount <> v_maximum_charge then
    raise exception 'reservation amount must equal canonical maximum charge' using errcode = '22023';
  end if;

  v_expected_fingerprint := encode(extensions.digest(convert_to(jsonb_build_object(
    'user_id', p_user_id, 'operation_id', p_operation_id, 'tool', p_tool,
    'workspace_id', p_workspace_id, 'workpiece_id', p_workpiece_id,
    'provider', v_policy.provider, 'model', v_policy.model, 'model_snapshot', v_policy.model_snapshot,
    'media_kind', v_policy.media_kind, 'generation_mode', v_policy.generation_mode,
    'endpoint', v_policy.endpoint, 'request_parameters', p_request_parameters,
    'requested_output_count', p_requested_output_count, 'usage_estimates', v_usage,
    'pricing_policy_revision_id', v_policy.id, 'pricing_policy_revision', v_policy.revision
  )::text, 'utf8'), 'sha256'), 'hex');
  if p_request_fingerprint <> v_expected_fingerprint then
    raise exception 'quote fingerprint mismatch' using errcode = '22023';
  end if;

  select * into v_quote from tongs.ai_credit_quotes where user_id = p_user_id and operation_id = p_operation_id;
  if found then
    if v_quote.id <> p_quote_id or v_quote.request_fingerprint <> p_request_fingerprint
       or v_quote.pricing_policy_revision_id <> p_pricing_policy_revision_id then
      raise exception 'quote replay conflict' using errcode = '23505';
    end if;
    return jsonb_build_object(
      'quote', to_jsonb(v_quote),
      'usage_components', (select jsonb_agg(to_jsonb(c) order by c.component_kind) from tongs.ai_credit_quote_usage_components c where c.quote_id = v_quote.id),
      'replay', true
    );
  end if;

  insert into tongs.ai_credit_quotes (
    id, user_id, operation_id, tool, workspace_id, workpiece_id, provider, model, media_kind,
    generation_mode, request_parameters, requested_output_count, provider_billable_units,
    pricing_policy_revision_id, pricing_policy_revision, estimated_provider_expense_micros,
    provider_currency, customer_credit_charge, reservation_amount, request_fingerprint, effective_at, expires_at,
    pricing_contract_version, estimated_provider_expense_numerator, estimated_provider_expense_denominator,
    maximum_provider_expense_numerator, maximum_provider_expense_denominator,
    estimated_customer_credit_charge, maximum_customer_credit_charge
  ) values (
    p_quote_id, p_user_id, p_operation_id, p_tool, p_workspace_id, p_workpiece_id, v_policy.provider, v_policy.model,
    v_policy.media_kind, v_policy.generation_mode, p_request_parameters, p_requested_output_count,
    greatest(v_total_max_units, 1), v_policy.id, v_policy.revision,
    ceil(v_est_num / v_est_den)::bigint, v_policy.provider_currency, v_estimated_charge,
    p_reservation_amount, p_request_fingerprint, p_effective_at, p_expires_at, 'compound_v2',
    v_est_num::bigint, v_est_den::bigint, v_max_num::bigint, v_max_den::bigint,
    v_estimated_charge, v_maximum_charge
  ) returning * into v_quote;

  for v_row in select value from jsonb_array_elements(v_usage) loop
    select * into v_rate from tongs.ai_pricing_rate_components
      where pricing_policy_revision_id = v_policy.id and component_kind = btrim(v_row->>'component_kind');
    insert into tongs.ai_credit_quote_usage_components (
      quote_id, pricing_rate_component_id, component_kind, unit_kind,
      estimated_quantity, maximum_quantity, rate_numerator, rate_denominator, currency, content_hash
    ) values (
      v_quote.id, v_rate.id, v_rate.component_kind, v_rate.unit_kind,
      (v_row->>'estimated_quantity')::bigint, (v_row->>'maximum_quantity')::bigint,
      v_rate.rate_numerator, v_rate.rate_denominator, v_rate.currency,
      encode(extensions.digest(convert_to(jsonb_build_object(
        'quote_id', v_quote.id, 'pricing_rate_component_id', v_rate.id,
        'component_kind', v_rate.component_kind, 'unit_kind', v_rate.unit_kind,
        'estimated_quantity', (v_row->>'estimated_quantity')::bigint,
        'maximum_quantity', (v_row->>'maximum_quantity')::bigint,
        'rate_numerator', v_rate.rate_numerator, 'rate_denominator', v_rate.rate_denominator,
        'currency', v_rate.currency
      )::text, 'utf8'), 'sha256'), 'hex')
    );
  end loop;

  return jsonb_build_object(
    'quote', to_jsonb(v_quote),
    'usage_components', (select jsonb_agg(to_jsonb(c) order by c.component_kind) from tongs.ai_credit_quote_usage_components c where c.quote_id = v_quote.id),
    'replay', false
  );
end;
$_$;


ALTER FUNCTION "tongs"."create_compound_ai_credit_quote"("p_quote_id" "uuid", "p_user_id" "uuid", "p_operation_id" "text", "p_tool" "text", "p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_pricing_policy_revision_id" "uuid", "p_request_parameters" "jsonb", "p_requested_output_count" integer, "p_usage_estimates" "jsonb", "p_reservation_amount" bigint, "p_request_fingerprint" "text", "p_effective_at" timestamp with time zone, "p_expires_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."create_customer_hearth_chat_quote"("p_quote_id" "uuid", "p_user_id" "uuid", "p_operation_id" "text", "p_workspace_id" "uuid", "p_request_fingerprint" "text", "p_expires_at" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_authorization tongs.customer_paid_execution_test_authorizations%rowtype;
  v_pricing tongs.private_pricing_revisions%rowtype;
  v_quote tongs.customer_spending_quotes%rowtype;
  v_control tongs.paid_execution_control_revisions%rowtype;
  v_rollout tongs.openai_text_rollout_revisions%rowtype;
  v_create jsonb;
  v_funding jsonb;
begin
  perform tongs._require_pricing_service_role();
  select a.* into v_authorization
  from tongs.customer_paid_execution_test_authorizations a
  join lateral (
    select revision.status from tongs.customer_paid_execution_test_authorization_revisions revision
    where revision.authorization_id=a.id order by revision.revision desc limit 1
  ) latest on true
  where a.user_id=p_user_id and a.workspace_id=p_workspace_id
    and a.route_code='hearth.chat_completion' and a.model='gpt-5.6-luna'
    and latest.status='active' and clock_timestamp()<a.authorization_expires_at
  order by a.created_at desc limit 1;
  if not found then
    raise exception 'customer Hearth paid test authorization is not active' using errcode='42501';
  end if;
  if p_expires_at>v_authorization.authorization_expires_at
     or p_expires_at>clock_timestamp()+interval '10 minutes' then
    raise exception 'quote expiry exceeds bounded authorization' using errcode='22023';
  end if;
  select * into v_pricing from tongs._published_pricing_revision('openai','gpt-5.6-luna');
  select * into v_rollout from tongs._current_openai_text_rollout('hearth.chat_completion');
  select * into v_control from tongs._current_paid_execution_control();
  if v_pricing.id is distinct from v_authorization.pricing_revision_id
     or v_rollout.mode<>'enforce'
     or v_rollout.cost_policy_revision_id is distinct from v_authorization.cost_policy_revision_id then
    raise exception 'pricing_not_configured' using errcode='P0001';
  end if;
  v_create:=tongs.create_shadow_spending_quote(
    p_quote_id,p_user_id,p_operation_id,'hearth.chat_completion',p_workspace_id,
    v_pricing.id,p_request_fingerprint,
    jsonb_build_array(
      jsonb_build_object('component','text_generation','provider_label','OpenAI','credential_source','forge'),
      jsonb_build_object('component','validation_and_persistence','provider_label','Forge supporting services','credential_source','forge')
    ),p_expires_at
  );
  select * into v_quote from tongs.customer_spending_quotes where id=p_quote_id;
  insert into tongs.customer_paid_execution_test_authorization_quotes(authorization_id,quote_id)
    values(v_authorization.id,v_quote.id)
    on conflict (authorization_id) do nothing;
  if not exists (
    select 1 from tongs.customer_paid_execution_test_authorization_quotes binding
    where binding.authorization_id=v_authorization.id and binding.quote_id=v_quote.id
  ) then
    raise exception 'customer paid test operation limit reached' using errcode='P0001';
  end if;
  v_funding:=tongs._select_customer_funding_for_quote(v_quote.id);
  return jsonb_build_object(
    'quote_id',v_quote.id,'operation_id',v_quote.operation_id,'quote_hash',v_quote.quote_hash,
    'request_fingerprint',v_quote.request_fingerprint,'currency',v_quote.currency,
    'normal_maximum_charge_micros',v_quote.normal_maximum_charge_micros,
    'billable_failure_maximum_charge_micros',0,
    'free_failure_classes',v_quote.free_failure_classes,
    'included_quantity',v_quote.included_quantity,'retention_policy',v_quote.retention_policy,
    'provider_funding_summary',v_quote.provider_funding_summary,'expires_at',v_quote.expires_at,
    'funding',v_funding,'customer_spending_enabled',v_control.pricing_activation_enabled
      and v_control.customer_settlement_enabled and v_control.provider_execution_enabled,
    'requires_confirmation',true,'replay',coalesce((v_create->>'replay')::boolean,false)
  );
end $$;


ALTER FUNCTION "tongs"."create_customer_hearth_chat_quote"("p_quote_id" "uuid", "p_user_id" "uuid", "p_operation_id" "text", "p_workspace_id" "uuid", "p_request_fingerprint" "text", "p_expires_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."create_customer_openai_text_quote"("p_quote_id" "uuid", "p_user_id" "uuid", "p_operation_id" "text", "p_route_code" "text", "p_workspace_id" "uuid", "p_workpiece_id" "text", "p_request_fingerprint" "text", "p_model" "text", "p_credential_funding" "text", "p_expires_at" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $_$
declare v_rollout tongs.openai_text_rollout_revisions%rowtype; v_cost tongs.openai_text_cost_policy_revisions%rowtype; selected record;
 v_pricing tongs.private_pricing_revisions%rowtype; v_quote tongs.customer_spending_quotes%rowtype; v_binding tongs.openai_text_customer_quote_bindings%rowtype;
 v_funding jsonb; v_authority jsonb; v_sku text; v_internal_operation text; v_create jsonb;
begin
 perform tongs._require_pricing_service_role();
 if p_quote_id is null or p_user_id is null or p_workspace_id is null or length(btrim(coalesce(p_operation_id,'')))<8 or length(btrim(coalesce(p_workpiece_id,'')))<1 or p_request_fingerprint!~'^[0-9a-f]{64}$' or length(btrim(coalesce(p_model,'')))<2 or p_credential_funding not in ('forge','byo_customer') or p_expires_at is null or p_expires_at<=now() then raise exception 'invalid OpenAI customer quote request' using errcode='22023'; end if;
 select * into v_rollout from tongs._openai_rollout_for_funding(p_route_code,p_credential_funding);
 if not found or (v_rollout.mode<>'enforce' and not exists(select 1 from tongs._owner_paid_execution_canary_for_choice(p_user_id,p_workspace_id,p_route_code,p_model))) then raise exception 'OpenAI text customer spending is not active' using errcode='42501'; end if;
 select * into selected from tongs._eligible_ai_models_for_operation(p_route_code)e where btrim(p_model) in (e.runtime_model_id,e.provider_model_id);
 if not found then raise exception 'pricing_not_configured: exact eligible model required' using errcode='P0001'; end if;
 select * into v_cost from tongs.openai_text_cost_policy_revisions where id=selected.cost_policy_revision_id;
 if v_rollout.cost_policy_revision_id is not null and v_rollout.cost_policy_revision_id<>v_cost.id then raise exception 'OpenAI route is bound to a different cost revision' using errcode='42501'; end if;
 v_sku:=lower('openai-text:'||p_route_code||':'||selected.runtime_model_id||':'||v_cost.id::text);
 v_authority:=tongs._resolve_spending_authority(p_user_id,p_workspace_id,p_route_code);
 if v_authority->>'payer_kind'='owner_testing' then
  select revision.* into v_pricing from tongs.private_pricing_revisions revision
  join tongs.private_pricing_policies policy on policy.id=revision.policy_id
  where revision.lifecycle_state='review_ready' and revision.full_cost_ceiling_micros=v_cost.full_cost_ceiling_micros
    and revision.markup_basis_points=3300 and lower(coalesce(policy.provider,''))='openai'
    and lower(coalesce(policy.sku,''))=v_sku
  order by revision.revision desc limit 1;
 else
  select * into v_pricing from tongs._published_pricing_revision('openai',v_sku);
 end if;
 if not found or v_pricing.full_cost_ceiling_micros<>v_cost.full_cost_ceiling_micros then raise exception 'pricing_not_configured: published exact route price required' using errcode='P0001'; end if;
 select * into v_binding from tongs.openai_text_customer_quote_bindings where quote_id=p_quote_id;
 if found then
  if v_binding.user_id<>p_user_id or v_binding.canonical_operation_id<>btrim(p_operation_id) or v_binding.route_code<>p_route_code or v_binding.workspace_id<>p_workspace_id or v_binding.workpiece_id<>btrim(p_workpiece_id) or v_binding.request_fingerprint<>p_request_fingerprint or v_binding.runtime_model<>selected.runtime_model_id or v_binding.credential_funding<>p_credential_funding or v_binding.cost_policy_revision_id<>v_cost.id or v_binding.pricing_revision_id<>v_pricing.id then raise exception 'OpenAI quote replay conflict' using errcode='23505'; end if;
 else
  v_internal_operation:=left(btrim(p_operation_id),250)||':q:'||p_quote_id::text;
  v_create:=tongs.create_shadow_spending_quote(p_quote_id,p_user_id,v_internal_operation,p_route_code,p_workspace_id,v_pricing.id,p_request_fingerprint,jsonb_build_array(jsonb_build_object('component','ai_model','provider_label','AI provider','credential_source',case when p_credential_funding='forge' then 'forge' else 'byo_customer' end)),p_expires_at);
  insert into tongs.openai_text_customer_quote_bindings(quote_id,user_id,canonical_operation_id,route_code,workspace_id,workpiece_id,request_fingerprint,runtime_model,credential_funding,cost_policy_revision_id,pricing_revision_id,expires_at,model_catalog_revision_id,model_catalog_entry_id)
  values(p_quote_id,p_user_id,btrim(p_operation_id),p_route_code,p_workspace_id,btrim(p_workpiece_id),p_request_fingerprint,selected.runtime_model_id,p_credential_funding,v_cost.id,v_pricing.id,p_expires_at,selected.catalog_revision_id,selected.model_catalog_entry_id);
 end if;
 select * into v_quote from tongs.customer_spending_quotes where id=p_quote_id; v_funding:=tongs._select_customer_funding_for_quote(p_quote_id);
 return jsonb_build_object('quote_id',v_quote.id,'operation_id',btrim(p_operation_id),'quote_hash',v_quote.quote_hash,'request_fingerprint',v_quote.request_fingerprint,'currency',v_quote.currency,'customer_credit_units',case when v_funding->>'payer_kind'='owner_testing' then 0 else v_quote.customer_credit_units end,'maximum_customer_charge_micros',case when v_funding->>'payer_kind'='owner_testing' then 0 else v_quote.normal_maximum_charge_micros end,'failure_customer_charge_micros',0,'failure_terms','Forge-caused and provider-caused failures cost you $0. Uncertain submissions are not retried automatically.','funding_eligible',coalesce((v_funding->>'eligible')::boolean,false),'funding_source',coalesce(v_funding->>'funding_source','none'),'payer_kind',coalesce(v_funding->>'payer_kind','personal'),'funding_label',coalesce(v_funding->>'customer_label','No verified eligible funds'),'funding_environment',v_quote.financial_environment,'expires_at',v_quote.expires_at,'accepted',exists(select 1 from tongs.customer_spending_quote_acceptances a where a.quote_id=v_quote.id));
end $_$;


ALTER FUNCTION "tongs"."create_customer_openai_text_quote"("p_quote_id" "uuid", "p_user_id" "uuid", "p_operation_id" "text", "p_route_code" "text", "p_workspace_id" "uuid", "p_workpiece_id" "text", "p_request_fingerprint" "text", "p_model" "text", "p_credential_funding" "text", "p_expires_at" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."create_customer_openai_text_quote"("p_quote_id" "uuid", "p_user_id" "uuid", "p_operation_id" "text", "p_route_code" "text", "p_workspace_id" "uuid", "p_workpiece_id" "text", "p_request_fingerprint" "text", "p_model" "text", "p_credential_funding" "text", "p_expires_at" timestamp with time zone) IS 'Creates immutable paid OpenAI quotes; Thumbnail Base resolves its published openai-image SKU while all other routes retain their existing SKU family.';



CREATE OR REPLACE FUNCTION "tongs"."create_customer_openai_transcription_quote"("p_quote_id" "uuid", "p_user_id" "uuid", "p_operation_id" "text", "p_route_code" "text", "p_workspace_id" "uuid", "p_workpiece_id" "text", "p_request_fingerprint" "text", "p_model" "text", "p_credential_funding" "text", "p_expires_at" timestamp with time zone, "p_source_asset_revision" "text", "p_source_sha256" "text", "p_source_bytes" bigint, "p_maximum_duration_seconds" numeric, "p_maximum_chunks" integer, "p_output_contract" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $_$
declare result jsonb; existing tongs.openai_transcription_source_bindings%rowtype;
begin
 perform tongs._require_pricing_service_role();
 if p_route_code not in ('hearth.speech_transcription','anvil.realtime_transcription','hammer.transcript_prep','hammer.transcript_regeneration')
  or p_source_sha256!~'^[0-9a-f]{64}$' or p_source_bytes<=0 or p_maximum_chunks<=0 or nullif(btrim(p_source_asset_revision),'') is null or nullif(btrim(p_output_contract),'') is null
 then raise exception 'invalid transcription quote request' using errcode='22023'; end if;
 result:=tongs.create_customer_openai_text_quote(p_quote_id,p_user_id,p_operation_id,p_route_code,p_workspace_id,p_workpiece_id,p_request_fingerprint,p_model,p_credential_funding,p_expires_at);
 select * into existing from tongs.openai_transcription_source_bindings where quote_id=p_quote_id;
 if found then
  if existing.route_code<>p_route_code or existing.user_id<>p_user_id or existing.workspace_id<>p_workspace_id or existing.workpiece_id<>p_workpiece_id
    or existing.source_asset_revision<>p_source_asset_revision or existing.source_sha256<>p_source_sha256 or existing.source_bytes<>p_source_bytes
    or existing.maximum_duration_seconds is distinct from p_maximum_duration_seconds or existing.maximum_chunks<>p_maximum_chunks or existing.output_contract<>p_output_contract
  then raise exception 'transcription source quote replay conflict' using errcode='23505'; end if;
 else
  insert into tongs.openai_transcription_source_bindings values(p_quote_id,p_route_code,p_user_id,p_workspace_id,p_workpiece_id,p_source_asset_revision,p_source_sha256,p_source_bytes,p_maximum_duration_seconds,p_maximum_chunks,p_output_contract,now());
 end if;
 return result;
end $_$;


ALTER FUNCTION "tongs"."create_customer_openai_transcription_quote"("p_quote_id" "uuid", "p_user_id" "uuid", "p_operation_id" "text", "p_route_code" "text", "p_workspace_id" "uuid", "p_workpiece_id" "text", "p_request_fingerprint" "text", "p_model" "text", "p_credential_funding" "text", "p_expires_at" timestamp with time zone, "p_source_asset_revision" "text", "p_source_sha256" "text", "p_source_bytes" bigint, "p_maximum_duration_seconds" numeric, "p_maximum_chunks" integer, "p_output_contract" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."create_customer_paid_execution_scope_authorization"("p_authorization_id" "uuid", "p_actor_id" "uuid", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_financial_environment" "text", "p_route_code" "text", "p_provider" "text", "p_model_or_sku" "text", "p_pricing_revision_id" "uuid", "p_cost_policy_revision_id" "uuid", "p_valid_from" timestamp with time zone, "p_valid_until" timestamp with time zone, "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_config tongs.financial_environment_configuration_revisions%rowtype;
  v_existing tongs.customer_paid_execution_scope_authorizations%rowtype;
begin
  perform tongs._require_pricing_service_role();
  if p_actor_id is null or not tongs.is_platform_operator(p_actor_id)
     or p_authorization_id is null or p_user_id is null or p_workspace_id is null
     or p_financial_environment not in ('test', 'live')
     or p_provider not in ('openai', 'runway')
     or p_valid_from is null or p_valid_until <= p_valid_from
     or nullif(btrim(coalesce(p_reason, '')), '') is null then
    raise exception 'invalid paid execution scope authorization' using errcode = '22023';
  end if;
  select * into v_existing
  from tongs.customer_paid_execution_scope_authorizations
  where id = p_authorization_id;
  if found then
    return to_jsonb(v_existing) || jsonb_build_object('replay', true);
  end if;
  select * into v_config
  from tongs.financial_environment_configuration_revisions
  where environment = p_financial_environment
  order by revision desc limit 1;
  if not found or v_config.lifecycle_state not in ('certification_ready', 'inactive_ready')
     or v_config.pricing_revision_id is distinct from p_pricing_revision_id
     or v_config.cost_policy_revision_id is distinct from p_cost_policy_revision_id
     or v_config.route_code <> p_route_code
     or v_config.provider <> p_provider
     or v_config.model <> p_model_or_sku then
    raise exception 'matching activation-ready financial configuration required' using errcode = '42501';
  end if;
  if p_provider = 'openai' and (
    v_config.wholesale_exposure_ceiling_micros <> 11015
    or v_config.maximum_concurrency <> 1
    or v_config.rolling_window_seconds <> 86400
    or v_config.maximum_operation_count <> 1
  ) then
    raise exception 'bounded Luna certification controls required' using errcode = 'P0001';
  end if;
  insert into tongs.customer_paid_execution_scope_authorizations(
    id, user_id, workspace_id, financial_environment, route_code, provider,
    model_or_sku, pricing_revision_id, cost_policy_revision_id,
    maximum_operation_count, maximum_customer_charge_micros,
    maximum_wholesale_exposure_micros, maximum_concurrency,
    rolling_window_seconds, valid_from, valid_until, status, reason, created_by
  ) values (
    p_authorization_id, p_user_id, p_workspace_id, p_financial_environment,
    p_route_code, p_provider, p_model_or_sku, p_pricing_revision_id,
    p_cost_policy_revision_id, v_config.maximum_operation_count, 15000,
    v_config.wholesale_exposure_ceiling_micros, v_config.maximum_concurrency,
    v_config.rolling_window_seconds, p_valid_from, p_valid_until, 'active',
    btrim(p_reason), p_actor_id
  );
  return jsonb_build_object('authorization_id', p_authorization_id, 'replay', false);
end $$;


ALTER FUNCTION "tongs"."create_customer_paid_execution_scope_authorization"("p_authorization_id" "uuid", "p_actor_id" "uuid", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_financial_environment" "text", "p_route_code" "text", "p_provider" "text", "p_model_or_sku" "text", "p_pricing_revision_id" "uuid", "p_cost_policy_revision_id" "uuid", "p_valid_from" timestamp with time zone, "p_valid_until" timestamp with time zone, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."create_customer_runway_quote"("p_quote_id" "uuid", "p_user_id" "uuid", "p_operation_id" "text", "p_workspace_id" "uuid", "p_operation_fingerprint" "text", "p_model" "text", "p_duration_seconds" integer, "p_ratio" "text", "p_expires_at" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_authorization tongs.runway_customer_test_authorizations%rowtype;
  result jsonb;
  q tongs.customer_spending_quotes%rowtype;
  v_replay boolean;
  v_quote_count integer;
begin
  perform tongs._require_pricing_service_role();
  select * into v_authorization from tongs.runway_customer_test_authorizations
  where user_id=p_user_id and workspace_id=p_workspace_id and status='active'
    and valid_from<=now() and valid_until>now() and operation_id=btrim(p_operation_id)
    and operation_fingerprint=lower(p_operation_fingerprint) and model=p_model
    and duration_seconds=p_duration_seconds and ratio=p_ratio and reference_image_count=0
    and pricing_revision_id='19730000-0000-4000-8000-000000000002'
  order by created_at desc limit 1;
  if not found then raise exception 'Runway customer Test scope is not authorized for this exact operation' using errcode='42501'; end if;
  if p_expires_at>v_authorization.valid_until or p_expires_at>clock_timestamp()+interval '10 minutes' then
    raise exception 'Runway quote expiry exceeds bounded authorization' using errcode='22023'; end if;
  select quote_row.* into q
  from tongs.runway_customer_test_quote_bindings binding
  join tongs.customer_spending_quotes quote_row on quote_row.id=binding.quote_id
  where binding.authorization_id=v_authorization.id and quote_row.expires_at>now()
    and not exists(select 1 from tongs.customer_spending_quote_acceptances acceptance where acceptance.quote_id=quote_row.id)
  order by quote_row.created_at desc limit 1;
  if found then
    p_quote_id:=q.id;
    p_expires_at:=q.expires_at;
  else
    select count(*) into v_quote_count from tongs.runway_customer_test_quote_bindings where authorization_id=v_authorization.id;
    if v_quote_count>=v_authorization.maximum_quote_count then
      raise exception 'Runway customer Test quote renewal limit reached' using errcode='P0001';
    end if;
  end if;
  select exists(select 1 from tongs.customer_spending_quotes where id=p_quote_id) into v_replay;
  result:=tongs._create_customer_runway_quote_before_gen45_customer_test(
    p_quote_id,p_user_id,p_operation_id,p_workspace_id,p_operation_fingerprint,p_model,p_duration_seconds,p_ratio,p_expires_at);
  select * into q from tongs.customer_spending_quotes where id=p_quote_id;
  if q.pricing_revision_id<>v_authorization.pricing_revision_id
     or q.normal_maximum_charge_micros<>v_authorization.maximum_customer_charge_micros
     or q.billable_failure_maximum_charge_micros<>0 or q.customer_credit_units<>160
     or q.full_cost_ceiling_micros<>v_authorization.maximum_wholesale_exposure_micros
     or q.financial_environment<>'test' then
    raise exception 'Runway quote escaped the exact Test product authority' using errcode='42501';
  end if;
  insert into tongs.runway_customer_test_quote_bindings(authorization_id,quote_id)
  values(v_authorization.id,q.id) on conflict do nothing;
  if not exists(select 1 from tongs.runway_customer_test_quote_bindings where authorization_id=v_authorization.id and quote_id=q.id) then
    raise exception 'Runway customer Test quote binding failed' using errcode='P0001';
  end if;
  return jsonb_build_object(
    'quote_id',q.id,'operation_id',q.operation_id,'quote_hash',q.quote_hash,
    'request_fingerprint',q.request_fingerprint,'currency',q.currency,
    'normal_maximum_charge_micros',q.normal_maximum_charge_micros,
    'billable_failure_maximum_charge_micros',q.billable_failure_maximum_charge_micros,
    'customer_credit_units',q.customer_credit_units,'billable_failure_classes',q.billable_failure_classes,
    'free_failure_classes',q.free_failure_classes,'included_quantity',q.included_quantity,
    'retention_policy',q.retention_policy,'provider_funding_summary',q.provider_funding_summary,
    'expires_at',q.expires_at,'funding',coalesce(result->'funding','{}'::jsonb),
    'customer_spending_enabled',true,'requires_confirmation',true,
    'activation_scope','normal_customer_test_exact_operation','replay',v_replay or coalesce((result->>'replay')::boolean,false));
end $$;


ALTER FUNCTION "tongs"."create_customer_runway_quote"("p_quote_id" "uuid", "p_user_id" "uuid", "p_operation_id" "text", "p_workspace_id" "uuid", "p_operation_fingerprint" "text", "p_model" "text", "p_duration_seconds" integer, "p_ratio" "text", "p_expires_at" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."create_customer_runway_quote"("p_quote_id" "uuid", "p_user_id" "uuid", "p_operation_id" "text", "p_workspace_id" "uuid", "p_operation_fingerprint" "text", "p_model" "text", "p_duration_seconds" integer, "p_ratio" "text", "p_expires_at" timestamp with time zone) IS 'Service-only exact-operation customer Test quote. Replays a current immutable quote or permits one immutable replacement after expiry; never reserves funds or calls Runway.';



CREATE OR REPLACE FUNCTION "tongs"."create_episode_identity_internal"("p_workspace_id" "uuid", "p_title" "text", "p_created_by" "uuid", "p_creation_origin" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare
  v_title text := btrim(coalesce(p_title,''));
  v_workpiece_id uuid;
begin
  if p_created_by is null then raise exception 'episode creator is required' using errcode='22023'; end if;
  if length(v_title) not between 1 and 200 then raise exception 'episode title must be between 1 and 200 characters' using errcode='22023'; end if;
  if not exists(select 1 from tongs.workspaces where id=p_workspace_id) then raise exception 'workspace not found' using errcode='23503'; end if;
  insert into tongs.episodes(workspace_id,label,lifecycle_state,created_by,creation_origin)
  values(p_workspace_id,v_title,'active',p_created_by,nullif(btrim(coalesce(p_creation_origin,'')),''))
  returning id into v_workpiece_id;
  return v_workpiece_id;
end;
$$;


ALTER FUNCTION "tongs"."create_episode_identity_internal"("p_workspace_id" "uuid", "p_title" "text", "p_created_by" "uuid", "p_creation_origin" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."create_hearth_chat_test_quote"("p_quote_id" "uuid", "p_authorization_id" "uuid", "p_operation_id" "text", "p_request_fingerprint" "text", "p_expires_at" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $_$
declare v_auth tongs.test_paid_execution_authorizations%rowtype; v_existing tongs.test_customer_spending_quotes%rowtype; v_hash text; v_count integer;
begin
  perform tongs._require_pricing_service_role();
  select * into v_auth from tongs.test_paid_execution_authorizations where id=p_authorization_id;
  if not found or tongs._test_authorization_state(p_authorization_id)<>'opened' or v_auth.expires_at<=now() then raise exception 'Test authorization inactive' using errcode='42501'; end if;
  select * into v_existing from tongs.test_customer_spending_quotes where operation_id=btrim(p_operation_id);
  if found then return jsonb_build_object('quote_id',v_existing.id,'operation_id',v_existing.operation_id,'quote_hash',v_existing.quote_hash,
    'request_fingerprint',v_existing.request_fingerprint,'normal_maximum_charge_micros',20000,'billable_failure_maximum_charge_micros',0,
    'customer_credit_units',2,'currency','USD','expires_at',v_existing.expires_at,'funding',jsonb_build_object('eligible',true,'funding_source','test_customer_deposit','customer_label','Stripe Test AI credits'),'replay',true); end if;
  select count(*) into v_count from tongs.test_customer_spending_quotes where authorization_id=p_authorization_id;
  if v_count>=v_auth.maximum_operations or (v_count+1)*20000>v_auth.maximum_aggregate_charge_micros then raise exception 'Test operation limit reached' using errcode='42501'; end if;
  if p_expires_at<=now() or p_expires_at>v_auth.expires_at or p_request_fingerprint!~'^[0-9a-f]{64}$' then raise exception 'invalid Test quote' using errcode='22023'; end if;
  v_hash:=encode(extensions.digest(concat_ws(':','forge.hearth.test-quote.v1',p_quote_id,p_authorization_id,btrim(p_operation_id),p_request_fingerprint,'20000','0','2'),'sha256'),'hex');
  insert into tongs.test_customer_spending_quotes(id,authorization_id,user_id,workspace_id,operation_id,request_fingerprint,quote_hash,
    currency,normal_maximum_charge_micros,billable_failure_maximum_charge_micros,customer_credit_units,expires_at)
  values(p_quote_id,p_authorization_id,v_auth.user_id,v_auth.workspace_id,btrim(p_operation_id),p_request_fingerprint,v_hash,'USD',20000,0,2,p_expires_at);
  return jsonb_build_object('quote_id',p_quote_id,'operation_id',btrim(p_operation_id),'quote_hash',v_hash,'request_fingerprint',p_request_fingerprint,
    'normal_maximum_charge_micros',20000,'billable_failure_maximum_charge_micros',0,'customer_credit_units',2,'currency','USD','expires_at',p_expires_at,
    'failure_terms','Forge/provider failure costs $0; simulated Test funding is restored.','execution_kind','simulated_test',
    'funding',jsonb_build_object('eligible',true,'funding_source','test_customer_deposit','customer_label','Stripe Test AI credits'),'replay',false);
end $_$;


ALTER FUNCTION "tongs"."create_hearth_chat_test_quote"("p_quote_id" "uuid", "p_authorization_id" "uuid", "p_operation_id" "text", "p_request_fingerprint" "text", "p_expires_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."create_hearth_project_episode"("p_workspace_id" "uuid", "p_project_id" "uuid", "p_title" "text", "p_operation_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare v_user uuid:=auth.uid();v_key text:=btrim(coalesce(p_operation_key,''));v_workpiece uuid;v_link uuid;v_title text:=coalesce(nullif(btrim(p_title),''),'Untitled Episode');
begin
  if v_user is null or not tongs.has_workspace_role(p_workspace_id,'editor') then return jsonb_build_object('outcome','denied');end if;
  if length(v_key) not between 16 and 200 then return jsonb_build_object('outcome','conflict','reason','invalid_operation_key');end if;
  if not exists(select 1 from tongs.barstock_assignments where id=p_project_id and workspace_id=p_workspace_id) then return jsonb_build_object('outcome','not_found','reason','project_not_found');end if;
  perform pg_advisory_xact_lock(hashtextextended(p_workspace_id::text||':'||p_project_id::text||':'||v_key,0));
  select id,workpiece_id into v_link,v_workpiece from tongs.barstock_project_episode_links where workspace_id=p_workspace_id and project_id=p_project_id and creation_operation_key=v_key;
  if v_workpiece is not null then return jsonb_build_object('outcome','existing','created',false,'link_id',v_link,'workpiece_id',v_workpiece,'operation_key',v_key);end if;
  v_workpiece:=tongs.create_episode_identity_internal(p_workspace_id,v_title,v_user,'hearth_project');
  insert into tongs.barstock_project_episode_links(workspace_id,project_id,workpiece_id,creation_operation_key,created_by)
  values(p_workspace_id,p_project_id,v_workpiece,v_key,v_user) returning id into v_link;
  return jsonb_build_object('outcome','created','created',true,'link_id',v_link,'workpiece_id',v_workpiece,'operation_key',v_key);
end$$;


ALTER FUNCTION "tongs"."create_hearth_project_episode"("p_workspace_id" "uuid", "p_project_id" "uuid", "p_title" "text", "p_operation_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."create_my_thumbnail_brand_template"("p_workspace_id" "uuid", "p_slug" "text", "p_name" "text", "p_template_json" "jsonb", "p_is_default" boolean DEFAULT false) RETURNS TABLE("template_id" "uuid", "workspace_id" "uuid", "slug" "text", "name" "text", "template_json" "jsonb", "is_default" boolean, "archived_at" timestamp with time zone, "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "updated_by" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare
  v_user uuid;
  v_slug text := lower(regexp_replace(coalesce(p_slug, ''), '[^a-z0-9]+', '-', 'g'));
  v_name text := nullif(btrim(coalesce(p_name, '')), '');
  v_template_json jsonb := coalesce(p_template_json, '{}'::jsonb);
  v_make_default boolean := coalesce(p_is_default, false);
  v_id uuid := gen_random_uuid();
begin
  v_user := auth.uid();
  if v_user is null then
    raise exception 'Not authenticated'
      using errcode = '42501';
  end if;

  if p_workspace_id is null then
    raise exception 'workspace_id is required'
      using errcode = '22023';
  end if;

  perform tongs.assert_workspace_role(p_workspace_id, 'editor');

  v_slug := trim(both '-' from v_slug);
  if v_slug is null or length(v_slug) = 0 then
    raise exception 'slug is required'
      using errcode = '22023';
  end if;

  if v_name is null then
    raise exception 'name is required'
      using errcode = '22023';
  end if;

  if jsonb_typeof(v_template_json) <> 'object' then
    raise exception 'template_json must be an object'
      using errcode = '22023';
  end if;

  if not exists (
    select 1
    from tongs.workspace_thumbnail_brand_templates existing
    where existing.workspace_id = p_workspace_id
      and existing.archived_at is null
  ) then
    v_make_default := true;
  end if;

  if v_make_default then
    update tongs.workspace_thumbnail_brand_templates existing
    set is_default = false,
        updated_at = now(),
        updated_by = v_user
    where existing.workspace_id = p_workspace_id
      and existing.archived_at is null;
  end if;

  insert into tongs.workspace_thumbnail_brand_templates (
    id,
    workspace_id,
    slug,
    name,
    template_json,
    is_default,
    archived_at,
    created_at,
    updated_at,
    updated_by
  )
  values (
    v_id,
    p_workspace_id,
    v_slug,
    v_name,
    jsonb_strip_nulls(v_template_json),
    v_make_default,
    null,
    now(),
    now(),
    v_user
  );

  return query
  select
    t.id,
    t.workspace_id,
    t.slug,
    t.name,
    t.template_json,
    t.is_default,
    t.archived_at,
    t.created_at,
    t.updated_at,
    t.updated_by
  from tongs.workspace_thumbnail_brand_templates t
  where t.id = v_id;
end;
$$;


ALTER FUNCTION "tongs"."create_my_thumbnail_brand_template"("p_workspace_id" "uuid", "p_slug" "text", "p_name" "text", "p_template_json" "jsonb", "p_is_default" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."create_normal_customer_paid_execution_authorization"("p_authorization_id" "uuid", "p_actor_id" "uuid", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_financial_environment" "text", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  config tongs.financial_environment_configuration_revisions%rowtype;
  existing tongs.customer_paid_execution_scope_authorizations%rowtype;
begin
  perform tongs._require_pricing_service_role();
  if p_authorization_id is null or p_actor_id is null
     or not tongs.is_platform_operator(p_actor_id)
     or p_user_id is null or p_workspace_id is null
     or p_financial_environment not in ('test', 'live')
     or nullif(btrim(coalesce(p_reason, '')), '') is null then
    raise exception 'service-role platform operator and exact customer scope are required'
      using errcode = '42501';
  end if;
  if not exists (
    select 1 from tongs.workspace_members membership
    where membership.workspace_id = p_workspace_id
      and membership.user_id = p_user_id
  ) then
    raise exception 'customer must belong to the authorized workspace'
      using errcode = '42501';
  end if;
  select * into existing
  from tongs.customer_paid_execution_scope_authorizations
  where id = p_authorization_id;
  if found then
    if existing.authorization_kind <> 'normal_customer'
       or existing.user_id <> p_user_id
       or existing.workspace_id <> p_workspace_id
       or existing.financial_environment <> p_financial_environment then
      raise exception 'normal customer authorization replay conflict'
        using errcode = '23505';
    end if;
    return to_jsonb(existing) || jsonb_build_object('replay', true);
  end if;
  select * into config
  from tongs.financial_environment_configuration_revisions
  where environment = p_financial_environment
  order by revision desc limit 1;
  if not found or config.lifecycle_state <> 'customer_rollout_active'
     or config.workflow_contract <> 'forge.customer-financial-path.v2'
     or config.route_code <> 'hearth.chat_completion'
     or config.provider <> 'openai'
     or config.model <> 'gpt-5.6-luna'
     or config.pricing_revision_id <> 'b4c4472f-0325-4c2e-b2ef-9aef5e59e64a'::uuid
     or config.cost_policy_revision_id <> '10000000-0000-4000-8000-000000000010'::uuid
     or config.wholesale_exposure_ceiling_micros <> 11015
     or config.maximum_concurrency <> 1
     or config.maximum_operation_count is not null
     or config.rolling_window_seconds is not null then
    raise exception 'exact active normal customer Luna configuration required'
      using errcode = '42501';
  end if;
  insert into tongs.customer_paid_execution_scope_authorizations(
    id, user_id, workspace_id, financial_environment, route_code, provider,
    model_or_sku, pricing_revision_id, cost_policy_revision_id,
    maximum_operation_count, maximum_customer_charge_micros,
    maximum_wholesale_exposure_micros, maximum_concurrency,
    rolling_window_seconds, valid_from, valid_until, status, reason,
    created_by, authorization_kind
  ) values (
    p_authorization_id, p_user_id, p_workspace_id, p_financial_environment,
    config.route_code, config.provider, config.model,
    config.pricing_revision_id, config.cost_policy_revision_id,
    null, 15000, config.wholesale_exposure_ceiling_micros,
    config.maximum_concurrency, null, now(), null, 'active',
    btrim(p_reason), p_actor_id, 'normal_customer'
  ) returning * into existing;
  return to_jsonb(existing) || jsonb_build_object('replay', false);
end $$;


ALTER FUNCTION "tongs"."create_normal_customer_paid_execution_authorization"("p_authorization_id" "uuid", "p_actor_id" "uuid", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_financial_environment" "text", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."create_normal_customer_paid_execution_authorization"("p_authorization_id" "uuid", "p_actor_id" "uuid", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_financial_environment" "text", "p_reason" "text") IS 'Creates an ongoing active-environment customer scope bounded by credits, per-operation cost, concurrency, idempotency, and settlement rather than a certification operation count.';



CREATE OR REPLACE FUNCTION "tongs"."create_org_team"("p_org_id" "uuid", "p_name" "text") RETURNS TABLE("team_id" "uuid", "org_id" "uuid", "team_name" "text", "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare
  v_user uuid;
  v_name text;
  v_team tongs.teams%rowtype;
begin
  v_user := auth.uid();
  if v_user is null then
    raise exception 'Not authenticated'
      using errcode = '42501';
  end if;

  if p_org_id is null then
    raise exception 'org_id is required'
      using errcode = '22023';
  end if;

  v_name := nullif(trim(coalesce(p_name, '')), '');
  if v_name is null then
    raise exception 'team name is required'
      using errcode = '22023';
  end if;

  perform tongs.assert_org_role(p_org_id, 'admin');

  insert into tongs.teams (
    org_id,
    name,
    created_at,
    updated_at,
    created_by
  )
  values (
    p_org_id,
    v_name,
    now(),
    now(),
    v_user
  )
  returning * into v_team;

  return query
  select
    v_team.id,
    v_team.org_id,
    v_team.name,
    v_team.created_at,
    v_team.updated_at;
end;
$$;


ALTER FUNCTION "tongs"."create_org_team"("p_org_id" "uuid", "p_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."create_owner_hearth_chat_luna_pilot_quote"("p_quote_id" "uuid", "p_acceptance_id" "uuid", "p_acceptance_key" "text", "p_operator_user_id" "uuid", "p_operation_id" "text", "p_workspace_id" "uuid", "p_pricing_revision_id" "uuid", "p_request_fingerprint" "text", "p_expires_at" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $_$
declare
  v_pricing tongs.private_pricing_revisions%rowtype;
  v_policy tongs.private_pricing_policies%rowtype;
  v_existing tongs.customer_spending_quotes%rowtype;
  v_acceptance tongs.customer_spending_quote_acceptances%rowtype;
  v_hash text;
  v_summary jsonb:=jsonb_build_array(
    jsonb_build_object('component','text_generation','provider_label','OpenAI','credential_source','forge'),
    jsonb_build_object('component','validation_and_persistence','provider_label','Forge supporting services','credential_source','forge')
  );
begin
  perform tongs._require_pricing_service_role();
  if p_quote_id is null or p_acceptance_id is null or p_operator_user_id is null
     or not tongs.is_platform_operator(p_operator_user_id) or p_workspace_id is null
     or length(btrim(coalesce(p_operation_id,'')))<8 or length(btrim(coalesce(p_acceptance_key,'')))<8
     or p_request_fingerprint !~ '^[0-9a-f]{64}$' or p_expires_at<=now()
     or p_expires_at>now()+interval '24 hours' then
    raise exception 'invalid owner Luna pilot quote' using errcode='22023';
  end if;
  select * into v_pricing from tongs.private_pricing_revisions where id=p_pricing_revision_id;
  select * into v_policy from tongs.private_pricing_policies where id=v_pricing.policy_id;
  if not found or v_pricing.lifecycle_state<>'review_ready' or v_pricing.currency<>'USD'
     or v_pricing.full_cost_ceiling_micros<>11015 or v_pricing.markup_basis_points<>3300
     or lower(coalesce(v_policy.provider,''))<>'openai'
     or lower(coalesce(v_policy.sku,''))<>'gpt-5.6-luna' then
    raise exception 'exact owner Luna pilot pricing is required' using errcode='P0001';
  end if;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'quote_id',p_quote_id,'operator_user_id',p_operator_user_id,'operation_id',btrim(p_operation_id),
    'tool','hearth.chat_completion','workspace_id',p_workspace_id,'pricing_revision_id',v_pricing.id,
    'pricing_revision',v_pricing.revision,'currency','USD','normal_maximum_charge_micros',0,
    'billable_failure_maximum_charge_micros',0,'customer_credit_units',0,
    'full_cost_ceiling_micros',11015,'request_fingerprint',p_request_fingerprint,
    'provider_funding_summary',v_summary,'expires_at',p_expires_at,'funding_lane','owner_budget'
  )::text,'utf8'),'sha256'),'hex');
  perform pg_advisory_xact_lock(hashtextextended('owner-hearth-luna-quote:'||p_operator_user_id::text||':'||btrim(p_operation_id),0));
  select * into v_existing from tongs.customer_spending_quotes
    where user_id=p_operator_user_id and operation_id=btrim(p_operation_id);
  if found then
    select * into v_acceptance from tongs.customer_spending_quote_acceptances where quote_id=v_existing.id;
    if v_existing.id<>p_quote_id or v_existing.quote_hash<>v_hash or not found
       or v_acceptance.id<>p_acceptance_id or v_acceptance.acceptance_key<>btrim(p_acceptance_key) then
      raise exception 'owner Luna quote replay conflict' using errcode='23505';
    end if;
    return jsonb_build_object('quote_id',v_existing.id,'acceptance_id',v_acceptance.id,
      'replay',true,'customer_charge_micros',0,'owner_cost_ceiling_micros',11015);
  end if;
  insert into tongs.customer_spending_quotes(
    id,user_id,operation_id,tool,workspace_id,pricing_revision_id,pricing_revision,currency,
    normal_maximum_charge_micros,billable_failure_maximum_charge_micros,customer_credit_units,
    full_cost_ceiling_micros,billable_failure_classes,free_failure_classes,included_quantity,
    retention_policy,provider_funding_summary,request_fingerprint,quote_hash,expires_at
  ) values (
    p_quote_id,p_operator_user_id,btrim(p_operation_id),'hearth.chat_completion',p_workspace_id,
    v_pricing.id,v_pricing.revision,'USD',0,0,0,11015,'[]'::jsonb,
    '["provider_failure","forge_failure","unknown_fault"]'::jsonb,
    '{"input_tokens":2000,"output_tokens":512,"attempts":1}'::jsonb,
    '{"kind":"none"}'::jsonb,v_summary,p_request_fingerprint,v_hash,p_expires_at
  );
  insert into tongs.customer_spending_quote_acceptances(id,quote_id,user_id,acceptance_key,accepted_quote_hash)
  values(p_acceptance_id,p_quote_id,p_operator_user_id,btrim(p_acceptance_key),v_hash);
  return jsonb_build_object('quote_id',p_quote_id,'acceptance_id',p_acceptance_id,
    'replay',false,'customer_charge_micros',0,'owner_cost_ceiling_micros',11015);
end $_$;


ALTER FUNCTION "tongs"."create_owner_hearth_chat_luna_pilot_quote"("p_quote_id" "uuid", "p_acceptance_id" "uuid", "p_acceptance_key" "text", "p_operator_user_id" "uuid", "p_operation_id" "text", "p_workspace_id" "uuid", "p_pricing_revision_id" "uuid", "p_request_fingerprint" "text", "p_expires_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."create_owner_hearth_chat_pilot_quote"("p_quote_id" "uuid", "p_acceptance_id" "uuid", "p_acceptance_key" "text", "p_operator_user_id" "uuid", "p_operation_id" "text", "p_workspace_id" "uuid", "p_pricing_revision_id" "uuid", "p_cost_policy_revision_id" "uuid", "p_request_fingerprint" "text", "p_expires_at" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $_$
declare
  v_pricing tongs.private_pricing_revisions%rowtype;
  v_policy tongs.private_pricing_policies%rowtype;
  v_cost tongs.openai_text_cost_policy_revisions%rowtype;
  v_existing tongs.customer_spending_quotes%rowtype;
  v_acceptance tongs.customer_spending_quote_acceptances%rowtype;
  v_hash text;
  v_summary jsonb:=jsonb_build_array(
    jsonb_build_object('component','text_generation','provider_label','OpenAI','credential_source','forge'),
    jsonb_build_object('component','validation_and_persistence','provider_label','Forge supporting services','credential_source','forge')
  );
begin
  perform tongs._require_pricing_service_role();
  if p_quote_id is null or p_acceptance_id is null or p_operator_user_id is null
     or not tongs.is_platform_operator(p_operator_user_id) or p_workspace_id is null
     or length(btrim(coalesce(p_operation_id,'')))<8 or length(btrim(coalesce(p_acceptance_key,'')))<8
     or p_request_fingerprint !~ '^[0-9a-f]{64}$' or p_expires_at<=now()
     or p_expires_at>now()+interval '24 hours' then
    raise exception 'invalid owner Hearth chat pilot quote' using errcode='22023';
  end if;
  if not exists(select 1 from tongs.workspaces w where w.id=p_workspace_id and
    (w.created_by=p_operator_user_id or exists(select 1 from tongs.workspace_members m
      where m.workspace_id=w.id and m.user_id=p_operator_user_id))) then
    raise exception 'operator cannot access pilot workspace' using errcode='42501';
  end if;
  select * into v_cost from tongs.openai_text_cost_policy_revisions where id=p_cost_policy_revision_id;
  select * into v_pricing from tongs.private_pricing_revisions where id=p_pricing_revision_id;
  select * into v_policy from tongs.private_pricing_policies where id=v_pricing.policy_id;
  if v_cost.id is null or v_pricing.id is null or v_policy.id is null
     or v_cost.route_code<>'hearth.chat_completion' or v_cost.cost_coverage<>'complete'
     or v_cost.lifecycle_state<>'pilot_candidate' or v_cost.maximum_attempts<>1
     or v_pricing.currency<>'USD' or v_pricing.full_cost_ceiling_micros<>v_cost.full_cost_ceiling_micros
     or lower(coalesce(v_policy.provider,''))<>'openai'
     or lower(coalesce(v_policy.sku,''))<>'gpt-5.3-chat-latest' then
    raise exception 'exact owner Hearth chat pilot pricing is required' using errcode='P0001';
  end if;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object(
    'quote_id',p_quote_id,'operator_user_id',p_operator_user_id,'operation_id',btrim(p_operation_id),
    'tool','hearth.chat_completion','workspace_id',p_workspace_id,'pricing_revision_id',v_pricing.id,
    'pricing_revision',v_pricing.revision,'currency','USD','normal_maximum_charge_micros',0,
    'billable_failure_maximum_charge_micros',0,'customer_credit_units',0,
    'full_cost_ceiling_micros',v_cost.full_cost_ceiling_micros,
    'request_fingerprint',p_request_fingerprint,'provider_funding_summary',v_summary,
    'expires_at',p_expires_at,'funding_lane','owner_budget'
  )::text,'utf8'),'sha256'),'hex');
  perform pg_advisory_xact_lock(hashtextextended('owner-hearth-chat-quote:'||p_operator_user_id::text||':'||btrim(p_operation_id),0));
  select * into v_existing from tongs.customer_spending_quotes
    where user_id=p_operator_user_id and operation_id=btrim(p_operation_id);
  if found then
    select * into v_acceptance from tongs.customer_spending_quote_acceptances where quote_id=v_existing.id;
    if v_existing.id<>p_quote_id or v_existing.quote_hash<>v_hash or not found
       or v_acceptance.id<>p_acceptance_id or v_acceptance.acceptance_key<>btrim(p_acceptance_key) then
      raise exception 'owner Hearth quote replay conflict' using errcode='23505';
    end if;
    return jsonb_build_object('quote_id',v_existing.id,'acceptance_id',v_acceptance.id,'replay',true,
      'customer_charge_micros',0,'owner_cost_ceiling_micros',v_existing.full_cost_ceiling_micros);
  end if;
  insert into tongs.customer_spending_quotes(
    id,user_id,operation_id,tool,workspace_id,pricing_revision_id,pricing_revision,currency,
    normal_maximum_charge_micros,billable_failure_maximum_charge_micros,customer_credit_units,
    full_cost_ceiling_micros,billable_failure_classes,free_failure_classes,included_quantity,
    retention_policy,provider_funding_summary,request_fingerprint,quote_hash,expires_at
  ) values (
    p_quote_id,p_operator_user_id,btrim(p_operation_id),'hearth.chat_completion',p_workspace_id,
    v_pricing.id,v_pricing.revision,'USD',0,0,0,v_cost.full_cost_ceiling_micros,'[]'::jsonb,
    '["provider_failure","forge_failure","unknown_fault"]'::jsonb,
    jsonb_build_object('input_tokens',v_cost.maximum_input_units,'output_tokens',v_cost.maximum_output_units,'attempts',1),
    '{"kind":"none"}'::jsonb,v_summary,p_request_fingerprint,v_hash,p_expires_at
  );
  insert into tongs.customer_spending_quote_acceptances(id,quote_id,user_id,acceptance_key,accepted_quote_hash)
  values(p_acceptance_id,p_quote_id,p_operator_user_id,btrim(p_acceptance_key),v_hash);
  return jsonb_build_object('quote_id',p_quote_id,'acceptance_id',p_acceptance_id,'replay',false,
    'customer_charge_micros',0,'owner_cost_ceiling_micros',v_cost.full_cost_ceiling_micros);
end $_$;


ALTER FUNCTION "tongs"."create_owner_hearth_chat_pilot_quote"("p_quote_id" "uuid", "p_acceptance_id" "uuid", "p_acceptance_key" "text", "p_operator_user_id" "uuid", "p_operation_id" "text", "p_workspace_id" "uuid", "p_pricing_revision_id" "uuid", "p_cost_policy_revision_id" "uuid", "p_request_fingerprint" "text", "p_expires_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."create_owner_only_openai_text_execution_scope_authorization"("p_authorization_id" "uuid", "p_actor_id" "uuid", "p_owner_user_id" "uuid", "p_workspace_id" "uuid", "p_financial_environment" "text", "p_route_code" "text", "p_model_or_sku" "text", "p_valid_from" timestamp with time zone, "p_valid_until" timestamp with time zone, "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_existing tongs.customer_paid_execution_scope_authorizations%rowtype;
  v_model record;
  v_cost tongs.openai_text_cost_policy_revisions%rowtype;
  v_pricing tongs.private_pricing_revisions%rowtype;
  v_loss tongs.openai_text_failure_loss_policy_revisions%rowtype;
  v_owner_count bigint;
  v_loss_environment text;
begin
  perform tongs._require_pricing_service_role();
  if p_authorization_id is null or p_actor_id is null
     or not tongs.is_platform_operator(p_actor_id)
     or p_owner_user_id is null or p_workspace_id is null
     or p_financial_environment not in ('test', 'live')
     or nullif(btrim(coalesce(p_route_code, '')), '') is null
     or nullif(btrim(coalesce(p_model_or_sku, '')), '') is null
     or p_valid_from is null or p_valid_until is null or p_valid_until <= p_valid_from
     or nullif(btrim(coalesce(p_reason, '')), '') is null then
    raise exception 'invalid owner-only paid execution scope authorization'
      using errcode = '22023';
  end if;

  select count(*) into v_owner_count
  from tongs.account_authority_classifications
  where account_class = 'owner';
  if v_owner_count <> 1
     or not exists (
       select 1 from tongs.account_authority_classifications
       where user_id = p_owner_user_id and account_class = 'owner'
     )
     or not tongs._transition_owner_authority_agrees(p_owner_user_id) then
    raise exception 'canonical owner authority is absent, ambiguous, or disagrees'
      using errcode = '42501';
  end if;
  if not exists (
    select 1 from tongs.workspace_members
    where user_id = p_owner_user_id and workspace_id = p_workspace_id
  ) then
    raise exception 'canonical owner workspace membership required'
      using errcode = '42501';
  end if;

  select * into v_existing
  from tongs.customer_paid_execution_scope_authorizations
  where id = p_authorization_id;
  if found then
    if v_existing.authorization_kind <> 'owner_only'
       or v_existing.user_id <> p_owner_user_id
       or v_existing.workspace_id <> p_workspace_id
       or v_existing.financial_environment <> p_financial_environment
       or v_existing.route_code <> btrim(p_route_code)
       or v_existing.provider <> 'openai'
       or v_existing.model_or_sku <> btrim(p_model_or_sku)
       or v_existing.valid_from <> p_valid_from
       or v_existing.valid_until <> p_valid_until then
      raise exception 'owner-only authorization replay conflict'
        using errcode = '23505';
    end if;
    return to_jsonb(v_existing) || jsonb_build_object('replay', true);
  end if;

  select * into v_model
  from tongs._eligible_ai_models_for_operation(btrim(p_route_code)) eligible
  where eligible.runtime_model_id = btrim(p_model_or_sku);
  if not found then
    raise exception 'exact operation/model financial authority is not eligible'
      using errcode = '42501';
  end if;

  select * into v_cost
  from tongs.openai_text_cost_policy_revisions
  where id = v_model.cost_policy_revision_id;
  select pricing.* into v_pricing
  from tongs._published_pricing_revision(
    'openai', lower('openai-text:' || btrim(p_route_code) || ':' || v_model.runtime_model_id || ':' || v_model.cost_policy_revision_id::text)
  ) pricing;
  if v_cost.id is null or v_pricing.id is null
     or v_cost.cost_coverage <> 'complete'
     or v_pricing.full_cost_ceiling_micros <> v_cost.full_cost_ceiling_micros
     or v_pricing.customer_credit_units <> v_model.customer_credit_units then
    raise exception 'exact published operation/model financial authority required'
      using errcode = '42501';
  end if;

  v_loss_environment := case p_financial_environment when 'test' then 'test' else 'production' end;
  select * into v_loss
  from tongs.openai_text_failure_loss_policy_revisions
  where route_code = btrim(p_route_code)
    and environment = v_loss_environment
    and lifecycle_state = 'active'
  order by revision desc limit 1;
  if not found
     or v_loss.per_operation_limit_micros < v_cost.full_cost_ceiling_micros
     or v_loss.aggregate_limit_micros < v_loss.per_operation_limit_micros then
    raise exception 'active bounded failure-loss authority required for exact environment'
      using errcode = '42501';
  end if;

  insert into tongs.customer_paid_execution_scope_authorizations(
    id, user_id, workspace_id, financial_environment, route_code, provider,
    model_or_sku, pricing_revision_id, cost_policy_revision_id,
    maximum_operation_count, maximum_customer_charge_micros,
    maximum_wholesale_exposure_micros, maximum_concurrency,
    rolling_window_seconds, valid_from, valid_until, status, reason,
    created_by, authorization_kind
  ) values (
    p_authorization_id, p_owner_user_id, p_workspace_id, p_financial_environment,
    btrim(p_route_code), 'openai', btrim(p_model_or_sku),
    v_pricing.id, v_model.cost_policy_revision_id, 1,
    v_pricing.customer_price_ceiling_micros, v_cost.full_cost_ceiling_micros,
    least(v_loss.maximum_concurrency, 1), v_loss.rolling_window_seconds,
    p_valid_from, p_valid_until, 'active', btrim(p_reason), p_actor_id, 'owner_only'
  ) returning * into v_existing;

  return to_jsonb(v_existing) || jsonb_build_object('replay', false);
end
$$;


ALTER FUNCTION "tongs"."create_owner_only_openai_text_execution_scope_authorization"("p_authorization_id" "uuid", "p_actor_id" "uuid", "p_owner_user_id" "uuid", "p_workspace_id" "uuid", "p_financial_environment" "text", "p_route_code" "text", "p_model_or_sku" "text", "p_valid_from" timestamp with time zone, "p_valid_until" timestamp with time zone, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."create_owner_openai_text_canary_quote"("p_quote_id" "uuid", "p_user_id" "uuid", "p_operation_id" "text", "p_route_code" "text", "p_workspace_id" "uuid", "p_workpiece_id" "text", "p_request_fingerprint" "text", "p_model" "text", "p_credential_funding" "text", "p_expires_at" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare result jsonb; quote_row tongs.customer_spending_quotes%rowtype;
begin
  perform tongs._require_pricing_service_role();
  if p_credential_funding<>'forge' or not exists(select 1 from tongs._owner_paid_execution_canary_for_choice(
    p_user_id,p_workspace_id,p_route_code,p_model)) then
    raise exception 'exact owner Test canary authority required' using errcode='42501';
  end if;
  result:=tongs.create_customer_openai_text_quote(
    p_quote_id,p_user_id,p_operation_id,p_route_code,p_workspace_id,p_workpiece_id,
    p_request_fingerprint,p_model,p_credential_funding,p_expires_at);
  select * into quote_row from tongs.customer_spending_quotes where id=p_quote_id;
  return result||jsonb_build_object(
    'customer_credit_units',quote_row.customer_credit_units,
    'maximum_customer_charge_micros',quote_row.normal_maximum_charge_micros,
    'funding_eligible',true,'funding_source','owner_budget','payer_kind','owner_testing',
    'funding_label','Forge Credits','funding_environment','test');
end $$;


ALTER FUNCTION "tongs"."create_owner_openai_text_canary_quote"("p_quote_id" "uuid", "p_user_id" "uuid", "p_operation_id" "text", "p_route_code" "text", "p_workspace_id" "uuid", "p_workpiece_id" "text", "p_request_fingerprint" "text", "p_model" "text", "p_credential_funding" "text", "p_expires_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."create_owner_operating_budget_draft"("p_budget_id" "uuid", "p_environment" "text", "p_workspace_id" "uuid", "p_provider" "text", "p_route" "text", "p_sku" "text", "p_currency" "text", "p_period_start" timestamp with time zone, "p_period_end" timestamp with time zone, "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_event_id uuid := gen_random_uuid();
  v_currency text := upper(btrim(coalesce(p_currency, '')));
  v_reason text := nullif(btrim(coalesce(p_reason, '')), '');
  v_payload jsonb;
begin
  if v_actor is null or not tongs.is_platform_operator(v_actor) then
    raise exception 'platform operator required' using errcode = '42501';
  end if;
  if p_budget_id is null or p_environment not in ('production', 'preview', 'development')
     or v_currency !~ '^[A-Z]{3}$' or p_period_start is null or p_period_end <= p_period_start
     or v_reason is null then
    raise exception 'invalid owner operating budget draft' using errcode = '22023';
  end if;
  v_payload := jsonb_build_object('budget_id', p_budget_id, 'environment', p_environment,
    'workspace_id', p_workspace_id, 'provider', nullif(btrim(coalesce(p_provider, '')), ''),
    'route', nullif(btrim(coalesce(p_route, '')), ''), 'sku', nullif(btrim(coalesce(p_sku, '')), ''),
    'currency', v_currency, 'period_start', p_period_start, 'period_end', p_period_end,
    'status', 'draft', 'maximum_amount_micros', null, 'reason', v_reason);
  perform tongs._create_accounting_event(
    v_event_id, 'owner-budget:' || p_budget_id::text || ':revision:1', 'owner_operating_budget_drafted',
    'owner_internal', 'owner_operating_budget', p_budget_id::text, v_currency, null,
    p_workspace_id, v_actor, v_payload, now()
  );
  insert into tongs.owner_operating_budgets(
    id, environment, workspace_id, provider, route, sku, currency, period_start, period_end, created_by
  ) values (
    p_budget_id, p_environment, p_workspace_id, nullif(btrim(coalesce(p_provider, '')), ''),
    nullif(btrim(coalesce(p_route, '')), ''), nullif(btrim(coalesce(p_sku, '')), ''),
    v_currency, p_period_start, p_period_end, v_actor
  );
  insert into tongs.owner_operating_budget_revisions(
    budget_id, revision, status, maximum_amount_micros, reason, actor_id, journal_event_id
  ) values (p_budget_id, 1, 'draft', null, v_reason, v_actor, v_event_id);
  return jsonb_build_object('budget_id', p_budget_id, 'revision', 1, 'status', 'draft',
    'maximum_amount_micros', null, 'spending_enabled', false);
end;
$_$;


ALTER FUNCTION "tongs"."create_owner_operating_budget_draft"("p_budget_id" "uuid", "p_environment" "text", "p_workspace_id" "uuid", "p_provider" "text", "p_route" "text", "p_sku" "text", "p_currency" "text", "p_period_start" timestamp with time zone, "p_period_end" timestamp with time zone, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."create_owner_runway_spending_quote"("p_quote_id" "uuid", "p_acceptance_id" "uuid", "p_acceptance_key" "text", "p_operator_user_id" "uuid", "p_operation_id" "text", "p_workspace_id" "uuid", "p_pricing_revision_id" "uuid", "p_request_fingerprint" "text", "p_model" "text", "p_duration_seconds" integer, "p_ratio" "text", "p_expires_at" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $_$
declare
  v_revision tongs.private_pricing_revisions%rowtype;
  v_policy tongs.private_pricing_policies%rowtype;
  v_existing tongs.customer_spending_quotes%rowtype;
  v_acceptance tongs.customer_spending_quote_acceptances%rowtype;
  v_operation text := nullif(btrim(coalesce(p_operation_id, '')), '');
  v_sku text := lower(coalesce(p_model, '') || ':' || coalesce(p_duration_seconds, 0)::text || 's:' || coalesce(p_ratio, ''));
  v_hash text;
  v_provider_summary jsonb := jsonb_build_array(
    jsonb_build_object('component','generation','provider_label','Runway','credential_source','forge'),
    jsonb_build_object('component','processing_and_retention','provider_label','Forge supporting services','credential_source','forge')
  );
begin
  perform tongs._require_pricing_service_role();
  if p_quote_id is null or p_acceptance_id is null or p_operator_user_id is null
     or not tongs.is_platform_operator(p_operator_user_id)
     or v_operation is null or length(v_operation) < 8
     or p_workspace_id is null or p_request_fingerprint !~ '^[0-9a-f]{64}$'
     or p_model <> 'gen4.5' or p_duration_seconds <> 5 or p_ratio <> '1280:720'
     or length(btrim(coalesce(p_acceptance_key, ''))) < 8
     or p_expires_at is null or p_expires_at <= now()
     or p_expires_at > now() + interval '24 hours' then
    raise exception 'invalid owner Runway spending quote' using errcode = '22023';
  end if;
  if not exists(
    select 1 from tongs.workspaces workspace
    where workspace.id=p_workspace_id
      and (workspace.created_by=p_operator_user_id or exists(
        select 1 from tongs.workspace_members member
        where member.workspace_id=workspace.id and member.user_id=p_operator_user_id
      ))
  ) then
    raise exception 'operator cannot access pilot workspace' using errcode = '42501';
  end if;
  select * into v_revision from tongs.private_pricing_revisions where id=p_pricing_revision_id;
  select * into v_policy from tongs.private_pricing_policies where id=v_revision.policy_id;
  if not found or v_revision.lifecycle_state <> 'draft'
     or v_revision.markup_basis_points is not null
     or v_revision.customer_price_ceiling_micros is not null
     or v_revision.billable_failure_ceiling_micros is not null
     or v_revision.customer_credit_units is not null
     or v_revision.currency <> 'USD'
     or v_revision.full_cost_ceiling_micros <> 750000
     or lower(coalesce(v_policy.provider,'')) <> 'runway'
     or lower(coalesce(v_policy.sku,'')) <> v_sku then
    raise exception 'exact owner-only Runway cost revision required' using errcode = 'P0001';
  end if;
  v_hash := encode(extensions.digest(convert_to(jsonb_build_object(
    'quote_id',p_quote_id,'operator_user_id',p_operator_user_id,'operation_id',v_operation,
    'tool','tongs_broll_v2','workspace_id',p_workspace_id,
    'pricing_revision_id',v_revision.id,'pricing_revision',v_revision.revision,
    'currency',v_revision.currency,'normal_maximum_charge_micros',0,
    'billable_failure_maximum_charge_micros',0,'customer_credit_units',0,
    'full_cost_ceiling_micros',v_revision.full_cost_ceiling_micros,
    'request_fingerprint',p_request_fingerprint,'provider_funding_summary',v_provider_summary,
    'expires_at',p_expires_at,'funding_lane','owner_budget'
  )::text,'utf8'),'sha256'),'hex');
  perform pg_advisory_xact_lock(hashtextextended('owner-runway-quote:'||p_operator_user_id::text||':'||v_operation,0));
  select * into v_existing from tongs.customer_spending_quotes
    where user_id=p_operator_user_id and operation_id=v_operation;
  if found then
    select * into v_acceptance from tongs.customer_spending_quote_acceptances where quote_id=v_existing.id;
    if v_existing.id<>p_quote_id or v_existing.request_fingerprint<>p_request_fingerprint
       or v_existing.pricing_revision_id<>p_pricing_revision_id or v_existing.quote_hash<>v_hash
       or not found or v_acceptance.id<>p_acceptance_id
       or v_acceptance.acceptance_key<>btrim(p_acceptance_key) then
      raise exception 'owner Runway quote replay conflict' using errcode='23505';
    end if;
    return jsonb_build_object('quote_id',v_existing.id,'acceptance_id',v_acceptance.id,
      'quote_hash',v_existing.quote_hash,'replay',true,'customer_charge_micros',0,
      'customer_credit_units',0,'owner_cost_ceiling_micros',v_existing.full_cost_ceiling_micros,
      'execution_authorized',false);
  end if;
  insert into tongs.customer_spending_quotes(
    id,user_id,operation_id,tool,workspace_id,pricing_revision_id,pricing_revision,
    currency,normal_maximum_charge_micros,billable_failure_maximum_charge_micros,
    customer_credit_units,full_cost_ceiling_micros,billable_failure_classes,
    free_failure_classes,included_quantity,retention_policy,provider_funding_summary,
    request_fingerprint,quote_hash,expires_at
  ) values (
    p_quote_id,p_operator_user_id,v_operation,'tongs_broll_v2',p_workspace_id,
    v_revision.id,v_revision.revision,v_revision.currency,0,0,0,
    v_revision.full_cost_ceiling_micros,v_revision.billable_failure_classes,
    v_revision.free_failure_classes,v_revision.included_quantity,v_revision.retention_policy,
    v_provider_summary,p_request_fingerprint,v_hash,p_expires_at
  );
  insert into tongs.customer_spending_quote_acceptances(
    id,quote_id,user_id,acceptance_key,accepted_quote_hash
  ) values (p_acceptance_id,p_quote_id,p_operator_user_id,btrim(p_acceptance_key),v_hash);
  return jsonb_build_object('quote_id',p_quote_id,'acceptance_id',p_acceptance_id,
    'quote_hash',v_hash,'replay',false,'customer_charge_micros',0,
    'customer_credit_units',0,'owner_cost_ceiling_micros',v_revision.full_cost_ceiling_micros,
    'execution_authorized',false);
end;
$_$;


ALTER FUNCTION "tongs"."create_owner_runway_spending_quote"("p_quote_id" "uuid", "p_acceptance_id" "uuid", "p_acceptance_key" "text", "p_operator_user_id" "uuid", "p_operation_id" "text", "p_workspace_id" "uuid", "p_pricing_revision_id" "uuid", "p_request_fingerprint" "text", "p_model" "text", "p_duration_seconds" integer, "p_ratio" "text", "p_expires_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."create_owner_testing_budget_draft"("p_budget_id" "uuid", "p_owner_testing_user_id" "uuid", "p_operator_user_id" "uuid", "p_environment" "text", "p_workspace_id" "uuid", "p_provider" "text", "p_route" "text", "p_sku" "text", "p_currency" "text", "p_period_start" timestamp with time zone, "p_period_end" timestamp with time zone, "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $_$
declare v_actor uuid:=p_operator_user_id; v_event uuid:=gen_random_uuid(); v_currency text:=upper(btrim(coalesce(p_currency,'')));
begin
  if coalesce(auth.role(),'')<>'service_role' or v_actor is null or not tongs.is_platform_operator(v_actor) then
    raise exception 'service-role platform operator required' using errcode='42501'; end if;
  if not tongs._transition_owner_authority_agrees(p_owner_testing_user_id) then
    raise exception 'explicit owner-testing principal required' using errcode='42501'; end if;
  if p_budget_id is null or p_environment not in ('production','preview','development','test') or v_currency!~'^[A-Z]{3}$'
     or p_period_start is null or p_period_end<=p_period_start or length(btrim(coalesce(p_reason,'')))<3 then
    raise exception 'invalid owner-testing budget draft' using errcode='22023'; end if;
  perform tongs._create_accounting_event(v_event,'owner-testing-budget:'||p_budget_id::text||':revision:1',
    'owner_operating_budget_drafted','owner_internal','owner_operating_budget',p_budget_id::text,v_currency,
    p_owner_testing_user_id,p_workspace_id,v_actor,jsonb_build_object('status','draft','maximum_amount_micros',null,
      'owner_testing_user_id',p_owner_testing_user_id,'reason',btrim(p_reason)),now());
  insert into tongs.owner_operating_budgets(id,environment,workspace_id,provider,route,sku,currency,period_start,period_end,created_by,owner_testing_user_id)
  values(p_budget_id,p_environment,p_workspace_id,nullif(btrim(coalesce(p_provider,'')),''),nullif(btrim(coalesce(p_route,'')),''),
    nullif(btrim(coalesce(p_sku,'')),''),v_currency,p_period_start,p_period_end,v_actor,p_owner_testing_user_id);
  insert into tongs.owner_operating_budget_revisions(budget_id,revision,status,maximum_amount_micros,reason,actor_id,journal_event_id)
  values(p_budget_id,1,'draft',null,btrim(p_reason),v_actor,v_event);
  return jsonb_build_object('budget_id',p_budget_id,'revision',1,'status','draft','maximum_amount_micros',null,
    'owner_testing_user_id',p_owner_testing_user_id,'spending_enabled',false);
end $_$;


ALTER FUNCTION "tongs"."create_owner_testing_budget_draft"("p_budget_id" "uuid", "p_owner_testing_user_id" "uuid", "p_operator_user_id" "uuid", "p_environment" "text", "p_workspace_id" "uuid", "p_provider" "text", "p_route" "text", "p_sku" "text", "p_currency" "text", "p_period_start" timestamp with time zone, "p_period_end" timestamp with time zone, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."create_paid_allowance_grant"("p_grant_id" "uuid", "p_receipt_id" "uuid", "p_entitlement_units" bigint, "p_allocated_revenue_micros" bigint, "p_maximum_wholesale_spend_micros" bigint, "p_allocation_policy_revision" "text", "p_granted_at" timestamp with time zone, "p_metadata_json" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_receipt tongs.subscription_cycle_receipts%rowtype;
  v_existing tongs.paid_allowance_grants%rowtype;
  v_policy text := nullif(btrim(coalesce(p_allocation_policy_revision, '')), '');
  v_allocated bigint;
  v_payload jsonb;
begin
  perform tongs._require_accounting_service_role();
  if p_grant_id is null or p_receipt_id is null or p_entitlement_units <= 0
     or p_allocated_revenue_micros <= 0 or p_maximum_wholesale_spend_micros <= 0
     or p_maximum_wholesale_spend_micros > p_allocated_revenue_micros or v_policy is null then
    raise exception 'invalid paid allowance grant' using errcode = '22023';
  end if;
  select * into v_receipt from tongs.subscription_cycle_receipts where id = p_receipt_id for update;
  if not found then raise exception 'subscription cycle receipt not found' using errcode = 'P0002'; end if;
  
  if exists (select 1 from tongs.subscription_cycle_adjustments where receipt_id = p_receipt_id) then
    raise exception 'adjusted subscription receipt cannot back a new allowance' using errcode = 'P0001';
  end if;
  select * into v_existing from tongs.paid_allowance_grants
   where receipt_id = p_receipt_id and allocation_policy_revision = v_policy;
  if found then
    if v_existing.entitlement_units <> p_entitlement_units
       or v_existing.allocated_revenue_micros <> p_allocated_revenue_micros
       or v_existing.maximum_wholesale_spend_micros <> p_maximum_wholesale_spend_micros then
      raise exception 'allowance grant replay conflict' using errcode = '23505';
    end if;
    return jsonb_build_object('grant_id', v_existing.id, 'replay', true);
  end if;
  select coalesce(sum(allocated_revenue_micros), 0) into v_allocated
  from tongs.paid_allowance_grants where receipt_id = p_receipt_id;
  if p_allocated_revenue_micros > v_receipt.gross_amount_micros - v_allocated then
    raise exception 'allowance allocation exceeds paid cycle backing' using errcode = 'P0001';
  end if;
  v_payload := jsonb_build_object('grant_id', p_grant_id, 'receipt_id', p_receipt_id,
    'entitlement_units', p_entitlement_units, 'allocated_revenue_micros', p_allocated_revenue_micros,
    'maximum_wholesale_spend_micros', p_maximum_wholesale_spend_micros,
    'allocation_policy_revision', v_policy, 'metadata', coalesce(p_metadata_json, '{}'::jsonb));
  perform tongs._create_accounting_event(
    p_grant_id, 'allowance:' || p_receipt_id::text || ':' || v_policy, 'paid_allowance_granted',
    'live', 'subscription_cycle_receipt', p_receipt_id::text, v_receipt.currency,
    v_receipt.user_id, null, null, v_payload, coalesce(p_granted_at, now())
  );
  insert into tongs.paid_allowance_grants(
    id, receipt_id, user_id, stripe_subscription_id, plan_item_id, period_start, period_end,
    entitlement_units, allocated_revenue_micros, maximum_wholesale_spend_micros, currency,
    allocation_policy_revision, journal_event_id, metadata_json, granted_at
  ) values (
    p_grant_id, p_receipt_id, v_receipt.user_id, v_receipt.stripe_subscription_id, v_receipt.plan_item_id,
    v_receipt.period_start, v_receipt.period_end, p_entitlement_units, p_allocated_revenue_micros,
    p_maximum_wholesale_spend_micros, v_receipt.currency, v_policy, p_grant_id,
    coalesce(p_metadata_json, '{}'::jsonb), coalesce(p_granted_at, now())
  );
  insert into tongs.accounting_journal_entries(
    event_id, line_number, account_code, user_id, allowance_grant_id, currency, amount_micros
  ) values
    (p_grant_id, 1, case when v_receipt.stripe_mode = 'live' then 'subscription_deferred_liability' else 'test_subscription_balance' end, v_receipt.user_id, p_grant_id, v_receipt.currency, p_allocated_revenue_micros),
    (p_grant_id, 2, case when v_receipt.stripe_mode = 'live' then 'allowance_deferred_liability' else 'test_allowance_deferred_balance' end, v_receipt.user_id, p_grant_id, v_receipt.currency, -p_allocated_revenue_micros);
  insert into tongs.accounting_journal_entries(
    event_id, line_number, account_code, user_id, allowance_grant_id, unit_kind, quantity_delta
  ) values
    (p_grant_id, 3, case when v_receipt.stripe_mode = 'live' then 'allowance_entitlement_units' else 'test_allowance_entitlement_units' end, v_receipt.user_id, p_grant_id, 'forge_credit', p_entitlement_units),
    (p_grant_id, 4, case when v_receipt.stripe_mode = 'live' then 'allowance_wholesale_capacity_micros' else 'test_allowance_wholesale_capacity_micros' end, v_receipt.user_id, p_grant_id,
      lower(v_receipt.currency) || '_micros', p_maximum_wholesale_spend_micros);
  perform tongs._assert_accounting_event_balanced(p_grant_id);
  return jsonb_build_object('grant_id', p_grant_id, 'replay', false);
end;
$$;


ALTER FUNCTION "tongs"."create_paid_allowance_grant"("p_grant_id" "uuid", "p_receipt_id" "uuid", "p_entitlement_units" bigint, "p_allocated_revenue_micros" bigint, "p_maximum_wholesale_spend_micros" bigint, "p_allocation_policy_revision" "text", "p_granted_at" timestamp with time zone, "p_metadata_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."create_paid_image_authorization_quote"("p_quote_id" "uuid", "p_user_id" "uuid", "p_operation_id" "text", "p_tool" "text", "p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_originating_entity_id" "text", "p_prompt_revision_id" "uuid", "p_prompt_content_hash" "text", "p_prompt" "text", "p_size" "text", "p_quality" "text", "p_output_count" integer, "p_request_metadata" "jsonb", "p_request_fingerprint" "text", "p_effective_at" timestamp with time zone, "p_expires_at" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $_$
declare v_policy tongs.ai_media_authorization_policy_revisions%rowtype; v_pricing tongs.ai_pricing_policy_revisions%rowtype;
  v_schedule tongs.ai_image_output_token_schedules%rowtype; v_existing tongs.ai_credit_quotes%rowtype;
  v_prompt_bytes integer; v_output_tokens bigint; v_output_expense bigint; v_basis bigint; v_ceiling bigint;
  v_params jsonb; v_expected text;
begin
  if p_user_id is null or p_quote_id is null or nullif(btrim(p_operation_id),'') is null or p_request_fingerprint !~ '^[0-9a-f]{64}$'
     or p_prompt_content_hash !~ '^[0-9a-f]{64}$' or nullif(p_prompt,'') is null or p_output_count not between 1 and 4
     or p_size='auto' or p_quality='auto' or coalesce(jsonb_typeof(p_request_metadata),'null')<>'object' then
    raise exception 'unsupported paid image authorization request' using errcode='22023';
  end if;
  v_prompt_bytes:=octet_length(convert_to(p_prompt,'utf8'));
  select r.* into v_policy from tongs.ai_media_authorization_policy_revisions r
    join tongs.ai_media_authorization_policy_sequences s on s.current_revision_id=r.id
    where r.provider='openai' and r.model_snapshot='gpt-image-2-2026-04-21' and r.request_kind='image_generation'
      and r.is_active and r.effective_from<=p_effective_at and (r.effective_through is null or r.effective_through>p_effective_at);
  if not found then raise exception 'active paid image authorization policy not found' using errcode='P0002'; end if;
  if v_prompt_bytes>v_policy.prompt_max_utf8_bytes then raise exception 'image prompt exceeds Forge paid-generation limit' using errcode='22023'; end if;
  if p_request_metadata ?| array['image','images','mask','reference_image','source_image','image_input']
     or coalesce(p_request_metadata->>'operation','generation')<>'generation' then
    raise exception 'image inputs and edits are unsupported for paid image V1' using errcode='22023';
  end if;
  select * into v_schedule from tongs.ai_image_output_token_schedules
    where authorization_policy_revision_id=v_policy.id and size=p_size and quality=p_quality;
  if not found then raise exception 'unsupported paid image size or quality' using errcode='22023'; end if;
  select * into v_pricing from tongs.ai_pricing_policy_revisions where id='72000000-0000-4000-8000-000000000001'::uuid;
  if not found or not v_pricing.is_active then raise exception 'active compound pricing policy not found' using errcode='P0002'; end if;
  v_output_tokens:=v_schedule.output_tokens_per_image*p_output_count;
  v_output_expense:=v_output_tokens*30;
  v_basis:=v_output_expense+v_policy.authorization_text_contingency_micros;
  v_ceiling:=ceil(v_basis::numeric*21/125)::bigint;
  v_params:=jsonb_build_object('size',p_size,'quality',p_quality,'output_count',p_output_count,'operation','generation','metadata',p_request_metadata);
  v_expected:=encode(extensions.digest(convert_to(jsonb_build_object(
    'user_id',p_user_id,'operation_id',btrim(p_operation_id),'tool',btrim(p_tool),'workspace_id',p_workspace_id,
    'workpiece_id',p_workpiece_id,'originating_entity_id',p_originating_entity_id,'prompt_revision_id',p_prompt_revision_id,
    'prompt_content_hash',p_prompt_content_hash,'prompt_utf8_bytes',v_prompt_bytes,'request_parameters',v_params,
    'pricing_policy_revision_id',v_pricing.id,'authorization_policy_revision_id',v_policy.id
  )::text,'utf8'),'sha256'),'hex');
  if v_expected<>p_request_fingerprint then raise exception 'paid image quote fingerprint mismatch' using errcode='22023',detail=v_expected; end if;
  select * into v_existing from tongs.ai_credit_quotes where user_id=p_user_id and operation_id=btrim(p_operation_id);
  if found then
    if v_existing.id<>p_quote_id or v_existing.request_fingerprint<>p_request_fingerprint then raise exception 'paid image quote replay conflict' using errcode='23505'; end if;
    return jsonb_build_object('quote',to_jsonb(v_existing),'replay',true);
  end if;
  insert into tongs.ai_credit_quotes(id,user_id,operation_id,tool,workspace_id,workpiece_id,provider,model,media_kind,generation_mode,
    request_parameters,requested_output_count,provider_billable_units,pricing_policy_revision_id,pricing_policy_revision,
    estimated_provider_expense_micros,provider_currency,customer_credit_charge,reservation_amount,request_fingerprint,effective_at,expires_at,
    pricing_contract_version,estimated_provider_expense_numerator,estimated_provider_expense_denominator,maximum_provider_expense_numerator,
    maximum_provider_expense_denominator,estimated_customer_credit_charge,maximum_customer_credit_charge,
    authorization_policy_revision_id,authorization_policy_revision,prompt_revision_id,prompt_content_hash,prompt_utf8_bytes,
    known_image_output_tokens,known_image_output_expense_micros,authorization_text_contingency_micros,
    authorization_provider_expense_basis_micros,authorized_customer_ceiling)
  values(p_quote_id,p_user_id,btrim(p_operation_id),btrim(p_tool),p_workspace_id,p_workpiece_id,'openai','gpt-image-2','image','generation',
    v_params,p_output_count,v_output_tokens,v_pricing.id,v_pricing.revision,v_basis,'USD',v_ceiling,v_ceiling,p_request_fingerprint,
    p_effective_at,p_expires_at,'compound_v2',v_basis,1,v_basis,1,v_ceiling,v_ceiling,v_policy.id,v_policy.revision,
    p_prompt_revision_id,p_prompt_content_hash,v_prompt_bytes,v_output_tokens,v_output_expense,
    v_policy.authorization_text_contingency_micros,v_basis,v_ceiling) returning * into v_existing;
  return jsonb_build_object('quote',to_jsonb(v_existing),'authorization_policy',to_jsonb(v_policy),'output_schedule',to_jsonb(v_schedule),'replay',false);
end $_$;


ALTER FUNCTION "tongs"."create_paid_image_authorization_quote"("p_quote_id" "uuid", "p_user_id" "uuid", "p_operation_id" "text", "p_tool" "text", "p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_originating_entity_id" "text", "p_prompt_revision_id" "uuid", "p_prompt_content_hash" "text", "p_prompt" "text", "p_size" "text", "p_quality" "text", "p_output_count" integer, "p_request_metadata" "jsonb", "p_request_fingerprint" "text", "p_effective_at" timestamp with time zone, "p_expires_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."create_paid_media_authorization_quote"("p_quote_id" "uuid", "p_user_id" "uuid", "p_operation_id" "text", "p_tool" "text", "p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_originating_entity_id" "text", "p_prompt_revision_id" "uuid", "p_prompt_content_hash" "text", "p_prompt" "text", "p_kind" "text", "p_media_kind" "text", "p_request_metadata" "jsonb", "p_request_parameters" "jsonb", "p_request_fingerprint" "text", "p_effective_at" timestamp with time zone, "p_expires_at" timestamp with time zone, "p_pricing_policy_revision_id" "uuid", "p_authorization_policy_revision_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $_$
declare
  v_existing tongs.ai_credit_quotes%rowtype; v_prompt_bytes integer; v_duration_seconds integer;
  v_provider text; v_model text; v_media_kind text; v_provider_native_rate numeric;
  v_provider_native_units bigint; v_provider_expense_micros bigint; v_basis bigint; v_ceiling bigint; v_params jsonb;
begin
  if p_user_id is null or p_quote_id is null or nullif(btrim(p_operation_id),'') is null
     or p_request_fingerprint !~ '^[0-9a-f]{64}$' or p_prompt_content_hash !~ '^[0-9a-f]{64}$'
     or nullif(p_prompt,'') is null or coalesce(jsonb_typeof(p_request_metadata),'null')<>'object'
     or coalesce(jsonb_typeof(p_request_parameters),'null')<>'object' then
    raise exception 'unsupported paid media authorization request' using errcode='22023';
  end if;
  v_prompt_bytes:=octet_length(convert_to(p_prompt,'utf8')); v_media_kind:=lower(coalesce(p_media_kind,'image'));
  if v_media_kind='image' then
    return tongs.create_paid_image_authorization_quote(p_quote_id,p_user_id,p_operation_id,p_tool,p_workspace_id,
      p_workpiece_id,p_originating_entity_id,p_prompt_revision_id,p_prompt_content_hash,p_prompt,
      coalesce(p_request_parameters->>'size','1024x1024'),coalesce(p_request_parameters->>'quality','medium'),
      coalesce((p_request_parameters->>'output_count')::integer,1),p_request_metadata,p_request_fingerprint,
      p_effective_at,p_expires_at);
  end if;
  if v_media_kind<>'video' or lower(coalesce(p_kind,'video'))<>'video' then
    raise exception 'unsupported paid media authorization kind' using errcode='22023';
  end if;
  v_duration_seconds:=greatest(coalesce((p_request_parameters->>'duration_seconds')::integer,5),1);
  v_provider:=coalesce(p_request_metadata->>'provider','runway');
  v_model:=coalesce(p_request_parameters->>'model',coalesce(p_request_metadata->>'model','gen4.5'));
  v_provider_native_rate:=coalesce((p_request_parameters->>'provider_native_rate')::numeric,12);
  v_provider_native_units:=v_duration_seconds*v_provider_native_rate::bigint;
  v_provider_expense_micros:=v_duration_seconds*120000; v_basis:=v_provider_expense_micros;
  v_ceiling:=ceil(v_basis::numeric*21/125)::bigint;
  v_params:=jsonb_build_object('provider',v_provider,'model',v_model,'generation_mode',
    coalesce(p_request_parameters->>'generation_mode','text_to_video'),'duration_seconds',v_duration_seconds,
    'ratio',coalesce(p_request_parameters->>'ratio','1280:720'),'operation',
    coalesce(p_request_parameters->>'operation','generation'),'metadata',p_request_metadata);
  select * into v_existing from tongs.ai_credit_quotes where user_id=p_user_id and operation_id=btrim(p_operation_id);
  if found then
    if v_existing.id<>p_quote_id or v_existing.request_fingerprint<>p_request_fingerprint then
      raise exception 'paid media quote replay conflict' using errcode='23505';
    end if;
    return jsonb_build_object('quote',to_jsonb(v_existing),'replay',true);
  end if;
  insert into tongs.ai_credit_quotes(
    id,user_id,operation_id,tool,workspace_id,workpiece_id,provider,model,media_kind,generation_mode,
    request_parameters,requested_output_count,provider_billable_units,pricing_policy_revision_id,pricing_policy_revision,
    estimated_provider_expense_micros,provider_currency,customer_credit_charge,reservation_amount,request_fingerprint,
    effective_at,expires_at,pricing_contract_version,estimated_provider_expense_numerator,
    estimated_provider_expense_denominator,maximum_provider_expense_numerator,maximum_provider_expense_denominator,
    estimated_customer_credit_charge,maximum_customer_credit_charge,authorization_policy_revision_id,
    authorization_policy_revision,prompt_revision_id,prompt_content_hash,prompt_utf8_bytes,known_image_output_tokens,
    known_image_output_expense_micros,authorization_text_contingency_micros,
    authorization_provider_expense_basis_micros,authorized_customer_ceiling)
  values(p_quote_id,p_user_id,btrim(p_operation_id),btrim(p_tool),p_workspace_id,p_workpiece_id,v_provider,v_model,
    'video','text_to_video',v_params,1,v_provider_native_units,p_pricing_policy_revision_id,1,
    v_provider_expense_micros,'USD',v_ceiling,v_ceiling,p_request_fingerprint,p_effective_at,p_expires_at,
    'forge.paid-media.quote.v1',v_provider_expense_micros,1,v_provider_expense_micros,1,v_ceiling,v_ceiling,
    p_authorization_policy_revision_id,1,p_prompt_revision_id,p_prompt_content_hash,v_prompt_bytes,null,null,0,v_basis,v_ceiling)
  returning * into v_existing;
  return jsonb_build_object('quote',to_jsonb(v_existing),'replay',false);
end $_$;


ALTER FUNCTION "tongs"."create_paid_media_authorization_quote"("p_quote_id" "uuid", "p_user_id" "uuid", "p_operation_id" "text", "p_tool" "text", "p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_originating_entity_id" "text", "p_prompt_revision_id" "uuid", "p_prompt_content_hash" "text", "p_prompt" "text", "p_kind" "text", "p_media_kind" "text", "p_request_metadata" "jsonb", "p_request_parameters" "jsonb", "p_request_fingerprint" "text", "p_effective_at" timestamp with time zone, "p_expires_at" timestamp with time zone, "p_pricing_policy_revision_id" "uuid", "p_authorization_policy_revision_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."create_publishing_oauth_connection_attempt"("p_owner_user_id" "uuid", "p_connection_id" "uuid", "p_state_hash" "text", "p_encrypted_pkce_verifier" "text", "p_encryption_key_version" "text", "p_ciphertext_version" "text", "p_expected_redirect_uri" "text", "p_expires_at" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $_$
declare v_connection tongs.publishing_provider_connections%rowtype; v_id uuid:=gen_random_uuid();
begin
  if auth.role()<>'service_role' then raise exception 'Forbidden' using errcode='42501'; end if;
  select * into v_connection from tongs.publishing_provider_connections where id=p_connection_id for update;
  if not found or v_connection.owner_user_id<>p_owner_user_id or v_connection.provider<>'google' then return jsonb_build_object('disposition','denied','code','connection_owner_or_provider_mismatch'); end if;
  if v_connection.state<>'pending_authorization' then return jsonb_build_object('disposition','blocked','code','connection_not_pending'); end if;
  if p_state_hash!~'^[a-f0-9]{64}$' or p_expires_at<=now() or p_expected_redirect_uri!~'^https://' then return jsonb_build_object('disposition','invalid','code','oauth_attempt_evidence_invalid'); end if;
  insert into tongs.publishing_oauth_connection_attempts(id,connection_id,owner_user_id,provider,state_hash,encrypted_pkce_verifier,encryption_key_version,ciphertext_version,expected_redirect_uri,expires_at)
  values(v_id,p_connection_id,p_owner_user_id,'google',p_state_hash,p_encrypted_pkce_verifier,p_encryption_key_version,p_ciphertext_version,p_expected_redirect_uri,p_expires_at);
  return jsonb_build_object('disposition','created','oauth_attempt_id',v_id,'connection_id',p_connection_id,'expires_at',p_expires_at);
end; $_$;


ALTER FUNCTION "tongs"."create_publishing_oauth_connection_attempt"("p_owner_user_id" "uuid", "p_connection_id" "uuid", "p_state_hash" "text", "p_encrypted_pkce_verifier" "text", "p_encryption_key_version" "text", "p_ciphertext_version" "text", "p_expected_redirect_uri" "text", "p_expires_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."create_publishing_provider_connection_authority"("p_owner_user_id" "uuid", "p_provider" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare v_connection_id uuid:=gen_random_uuid(); v_credential_id uuid:=gen_random_uuid();
begin
  if auth.role()<>'service_role' then raise exception 'Forbidden' using errcode='42501'; end if;
  if p_provider not in('google','spotify','rumble','rss_host') then return jsonb_build_object('disposition','invalid','code','provider_unsupported'); end if;
  if not exists(select 1 from auth.users where id=p_owner_user_id) then return jsonb_build_object('disposition','invalid','code','owner_missing'); end if;
  insert into tongs.publishing_provider_connections(id,owner_user_id,provider,state)
  values(v_connection_id,p_owner_user_id,p_provider,'pending_authorization');
  insert into tongs.publishing_provider_credential_authorities(id,connection_id,owner_user_id,state)
  values(v_credential_id,v_connection_id,p_owner_user_id,'unavailable');
  update tongs.publishing_provider_connections set credential_authority_id=v_credential_id where id=v_connection_id;
  return jsonb_build_object('disposition','created','provider_connection_id',v_connection_id,'credential_authority_id',v_credential_id);
end; $$;


ALTER FUNCTION "tongs"."create_publishing_provider_connection_authority"("p_owner_user_id" "uuid", "p_provider" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "tongs"."recording_sessions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "title" "text" NOT NULL,
    "session_type" "tongs"."session_type" DEFAULT 'recording'::"tongs"."session_type" NOT NULL,
    "starts_at" timestamp with time zone NOT NULL,
    "ends_at" timestamp with time zone,
    "notes" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "workspace_id" "uuid" NOT NULL,
    "status" "text" DEFAULT 'planned'::"text",
    "created_by" "uuid",
    "calendar_event_id" "uuid"
);


ALTER TABLE "tongs"."recording_sessions" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."create_recording_session"("p_workspace_id" "uuid", "p_title" "text", "p_created_by" "uuid", "p_calendar_event_id" "uuid" DEFAULT NULL::"uuid") RETURNS "tongs"."recording_sessions"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'tongs', 'pg_temp'
    AS $$
declare
  v_session tongs.recording_sessions;
  v_title text := coalesce(nullif(btrim(p_title), ''), 'Recording Session');
begin
  if p_workspace_id is null then
    raise exception 'workspace_id is required' using errcode = '22023';
  end if;

  if p_created_by is null then
    raise exception 'created_by is required' using errcode = '22023';
  end if;

  if p_calendar_event_id is not null then
    if not exists (
      select 1
      from tongs.calendar_events ce
      where ce.id = p_calendar_event_id
        and ce.workspace_id = p_workspace_id
    ) then
      raise exception 'calendar_event_mismatch' using errcode = '22023';
    end if;
  end if;

  insert into tongs.recording_sessions (
    workspace_id,
    title,
    created_by,
    calendar_event_id,
    starts_at,
    ends_at,
    status
  )
  values (
    p_workspace_id,
    v_title,
    p_created_by,
    p_calendar_event_id,
    now(),
    null,
    'planned'
  )
  returning *
  into v_session;

  if p_calendar_event_id is not null then
    update tongs.calendar_events
    set session_id = v_session.id
    where id = p_calendar_event_id
      and workspace_id = p_workspace_id;
  end if;

  return v_session;
end;
$$;


ALTER FUNCTION "tongs"."create_recording_session"("p_workspace_id" "uuid", "p_title" "text", "p_created_by" "uuid", "p_calendar_event_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."create_recording_workpiece"("p_workspace_id" "uuid", "p_title" "text", "p_origin_venue" "text", "p_operation_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare
  v_user uuid:=auth.uid(); v_title text:=btrim(coalesce(p_title,'')); v_venue text:=lower(btrim(coalesce(p_origin_venue,'')));
  v_key text:=btrim(coalesce(p_operation_key,'')); v_fingerprint text; v_existing tongs.recording_workpiece_creation_requests%rowtype;
  v_workpiece uuid; v_receipt tongs.recording_workpiece_creation_requests%rowtype;
begin
  if v_user is null or not tongs.has_workspace_role(p_workspace_id,'editor') then return jsonb_build_object('outcome','denied','reason','editor_required'); end if;
  if length(v_title) not between 1 and 200 then return jsonb_build_object('outcome','conflict','reason','invalid_title'); end if;
  if v_venue not in ('anvil','bellows') then return jsonb_build_object('outcome','conflict','reason','invalid_origin_venue'); end if;
  if length(v_key) not between 16 and 200 then return jsonb_build_object('outcome','conflict','reason','invalid_operation_key'); end if;
  v_fingerprint:=md5(concat_ws('|',p_workspace_id,v_title,v_venue));
  perform pg_advisory_xact_lock(hashtextextended(p_workspace_id::text||':'||v_key,0));
  select * into v_existing from tongs.recording_workpiece_creation_requests where workspace_id=p_workspace_id and operation_key=v_key;
  if found then
    if v_existing.request_fingerprint=v_fingerprint then
      return jsonb_build_object('outcome','existing','workpiece_id',v_existing.workpiece_id,'receipt',to_jsonb(v_existing));
    end if;
    return jsonb_build_object('outcome','conflict','reason','operation_key_reused');
  end if;
  v_workpiece:=tongs.create_episode_identity_internal(p_workspace_id,v_title,v_user,'recording_venue');
  insert into tongs.recording_workpiece_creation_requests(workspace_id,workpiece_id,operation_key,request_fingerprint,title,origin_venue,created_by)
  values(p_workspace_id,v_workpiece,v_key,v_fingerprint,v_title,v_venue,v_user) returning * into v_receipt;
  return jsonb_build_object('outcome','created','workpiece_id',v_workpiece,'receipt',to_jsonb(v_receipt));
end;
$$;


ALTER FUNCTION "tongs"."create_recording_workpiece"("p_workspace_id" "uuid", "p_title" "text", "p_origin_venue" "text", "p_operation_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."create_shadow_spending_quote"("p_quote_id" "uuid", "p_user_id" "uuid", "p_operation_id" "text", "p_tool" "text", "p_workspace_id" "uuid", "p_pricing_revision_id" "uuid", "p_request_fingerprint" "text", "p_provider_funding_summary" "jsonb", "p_expires_at" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $_$
declare
  v_revision tongs.private_pricing_revisions%rowtype;
  v_existing tongs.customer_spending_quotes%rowtype;
  v_operation text:=nullif(btrim(coalesce(p_operation_id,'')),'');
  v_tool text:=nullif(btrim(coalesce(p_tool,'')),'');
  v_hash text;
  v_price bigint;
  v_free jsonb;
  v_runway_renewal_allowed boolean:=false;
begin
  perform tongs._require_pricing_service_role();
  if p_quote_id is null or p_user_id is null or v_operation is null or length(v_operation)<8 or v_tool is null
    or p_request_fingerprint!~'^[0-9a-f]{64}$' or jsonb_typeof(coalesce(p_provider_funding_summary,'null'::jsonb))<>'array'
    or p_expires_at is null or p_expires_at<=now() then raise exception 'invalid shadow spending quote' using errcode='22023'; end if;
  select * into v_revision from tongs.private_pricing_revisions where id=p_pricing_revision_id;
  if not found then raise exception 'private pricing revision not found' using errcode='P0002'; end if;
  if v_revision.lifecycle_state<>'review_ready' or v_revision.markup_basis_points is null or v_revision.customer_credit_units is null then
    raise exception 'pricing_not_configured' using errcode='P0001'; end if;
  if exists(select 1 from jsonb_array_elements(p_provider_funding_summary)item where jsonb_typeof(item)<>'object'
    or item->>'credential_source' not in ('forge','byo_customer') or nullif(btrim(coalesce(item->>'component','')),'') is null
    or nullif(btrim(coalesce(item->>'provider_label','')),'') is null) then raise exception 'invalid provider funding summary' using errcode='22023'; end if;
  v_price:=coalesce(v_revision.settled_customer_price_micros,
    tongs.round_customer_price_micros(v_revision.full_cost_ceiling_micros::numeric*(10000::numeric+v_revision.markup_basis_points)/10000::numeric,v_revision.currency));
  if v_price<>v_revision.customer_price_ceiling_micros then
    raise exception 'pricing_not_configured: settled customer price must equal the published ceiling' using errcode='P0001';
  end if;
  v_free:='["forge_failure","provider_failure","provider_billed_failure","unknown_fault","prebilling_rejection","forge_validation_failure","persistence_failure"]'::jsonb;
  v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('quote_id',p_quote_id,'user_id',p_user_id,
    'operation_id',v_operation,'tool',v_tool,'workspace_id',p_workspace_id,'pricing_revision_id',v_revision.id,
    'pricing_revision',v_revision.revision,'currency',v_revision.currency,'normal_maximum_charge_micros',v_price,
    'billable_failure_maximum_charge_micros',0,'customer_credit_units',v_revision.customer_credit_units,
    'request_fingerprint',p_request_fingerprint,'provider_funding_summary',p_provider_funding_summary,'expires_at',p_expires_at)::text,'utf8'),'sha256'),'hex');
  perform pg_advisory_xact_lock(hashtextextended('spending-quote:'||p_user_id::text||':'||v_operation,0));
  select * into v_existing from tongs.customer_spending_quotes where id=p_quote_id;
  if found then
    if v_existing.user_id<>p_user_id or v_existing.operation_id<>v_operation
       or v_existing.request_fingerprint<>p_request_fingerprint or v_existing.pricing_revision_id<>p_pricing_revision_id then
      raise exception 'shadow spending quote replay conflict' using errcode='23505'; end if;
    return jsonb_build_object('quote_id',v_existing.id,'quote_hash',v_existing.quote_hash,'replay',true,'execution_authorized',false);
  end if;
  if exists(select 1 from tongs.customer_spending_quotes where user_id=p_user_id and operation_id=v_operation) then
    select exists(
      select 1 from tongs.runway_customer_test_authorizations scope_authorization
      where scope_authorization.user_id=p_user_id and scope_authorization.workspace_id=p_workspace_id
        and scope_authorization.operation_id=v_operation and scope_authorization.operation_fingerprint=p_request_fingerprint
        and scope_authorization.pricing_revision_id=p_pricing_revision_id and scope_authorization.financial_environment='test'
        and scope_authorization.status='active' and scope_authorization.valid_from<=now() and scope_authorization.valid_until>now()
        and scope_authorization.model='gen4.5' and scope_authorization.generation_mode='text_to_video'
        and scope_authorization.duration_seconds=5 and scope_authorization.ratio='1280:720'
        and scope_authorization.output_count=1 and scope_authorization.reference_image_count=0
        and scope_authorization.maximum_provider_attempts=1 and scope_authorization.maximum_operation_count=1
        and not exists(select 1 from tongs.customer_spending_quotes current_quote
          where current_quote.user_id=p_user_id and current_quote.operation_id=v_operation and current_quote.expires_at>now())
        and not exists(select 1 from tongs.customer_spending_quote_acceptances acceptance
          join tongs.customer_spending_quotes prior_quote on prior_quote.id=acceptance.quote_id
          where prior_quote.user_id=p_user_id and prior_quote.operation_id=v_operation)
        and not exists(select 1 from tongs.funding_reservations reservation
          where reservation.user_id=p_user_id and reservation.operation_id=v_operation)
    ) into v_runway_renewal_allowed;
    if not v_runway_renewal_allowed then
      raise exception 'shadow spending quote replay conflict' using errcode='23505';
    end if;
  end if;
  insert into tongs.customer_spending_quotes(id,user_id,operation_id,tool,workspace_id,pricing_revision_id,pricing_revision,currency,
    normal_maximum_charge_micros,billable_failure_maximum_charge_micros,customer_credit_units,full_cost_ceiling_micros,
    billable_failure_classes,free_failure_classes,included_quantity,retention_policy,provider_funding_summary,request_fingerprint,quote_hash,expires_at)
  values(p_quote_id,p_user_id,v_operation,v_tool,p_workspace_id,v_revision.id,v_revision.revision,v_revision.currency,v_price,0,
    v_revision.customer_credit_units,v_revision.full_cost_ceiling_micros,'[]'::jsonb,v_free,v_revision.included_quantity,v_revision.retention_policy,
    p_provider_funding_summary,p_request_fingerprint,v_hash,p_expires_at);
  return jsonb_build_object('quote_id',p_quote_id,'quote_hash',v_hash,'replay',false,'execution_authorized',false);
end $_$;


ALTER FUNCTION "tongs"."create_shadow_spending_quote"("p_quote_id" "uuid", "p_user_id" "uuid", "p_operation_id" "text", "p_tool" "text", "p_workspace_id" "uuid", "p_pricing_revision_id" "uuid", "p_request_fingerprint" "text", "p_provider_funding_summary" "jsonb", "p_expires_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."create_standard_customer_certification_aggregate_assignment"("p_assignment_id" "uuid", "p_actor_id" "uuid", "p_scope_authorization_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  scope_auth tongs.customer_paid_execution_scope_authorizations%rowtype;
  existing tongs.paid_execution_aggregate_assignments%rowtype;
begin
  perform tongs._require_pricing_service_role();
  if p_assignment_id is null or p_actor_id is null
     or not tongs.is_platform_operator(p_actor_id)
     or p_scope_authorization_id is null
     or nullif(btrim(coalesce(p_reason, '')), '') is null then
    raise exception 'service-role platform operator and exact scope are required'
      using errcode = '42501';
  end if;
  select * into existing
  from tongs.paid_execution_aggregate_assignments
  where id = p_assignment_id;
  if found then
    return to_jsonb(existing) || jsonb_build_object('replay', true);
  end if;
  select * into scope_auth
  from tongs.customer_paid_execution_scope_authorizations
  where id = p_scope_authorization_id;
  if not found
     or scope_auth.created_by <> p_actor_id
     or scope_auth.status <> 'active'
     or scope_auth.valid_from > now()
     or scope_auth.valid_until <= now()
     or scope_auth.financial_environment <> 'test'
     or scope_auth.route_code <> 'hearth.chat_completion'
     or scope_auth.provider <> 'openai'
     or scope_auth.model_or_sku <> 'gpt-5.6-luna'
     or scope_auth.pricing_revision_id <> 'b4c4472f-0325-4c2e-b2ef-9aef5e59e64a'::uuid
     or scope_auth.cost_policy_revision_id <> '10000000-0000-4000-8000-000000000010'::uuid
     or scope_auth.maximum_operation_count <> 1
     or scope_auth.maximum_customer_charge_micros <> 15000
     or scope_auth.maximum_wholesale_exposure_micros <> 11015
     or scope_auth.maximum_concurrency <> 1
     or scope_auth.rolling_window_seconds <> 86400 then
    raise exception 'exact active bounded Luna customer scope required'
      using errcode = '42501';
  end if;
  if exists (
    select 1 from tongs.paid_execution_aggregate_assignments a
    join tongs.restricted_beta_policy_revisions p on p.id = a.policy_revision_id
    where a.user_id = scope_auth.user_id
      and a.workspace_id = scope_auth.workspace_id
      and a.state = 'active'
      and a.valid_from <= now() and a.valid_until > now()
      and p.environment = 'test'
  ) then
    raise exception 'an active Test aggregate assignment already exists'
      using errcode = '23505';
  end if;
  insert into tongs.paid_execution_aggregate_assignments(
    id, policy_revision_id, user_id, workspace_id, state,
    valid_from, valid_until, reason
  ) values (
    p_assignment_id, 'c0000000-0000-4000-8000-000000000002',
    scope_auth.user_id, scope_auth.workspace_id, 'active', now(),
    scope_auth.valid_until, btrim(p_reason)
  ) returning * into existing;
  return to_jsonb(existing) || jsonb_build_object('replay', false);
end $$;


ALTER FUNCTION "tongs"."create_standard_customer_certification_aggregate_assignment"("p_assignment_id" "uuid", "p_actor_id" "uuid", "p_scope_authorization_id" "uuid", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."create_standard_customer_certification_aggregate_assignment"("p_assignment_id" "uuid", "p_actor_id" "uuid", "p_scope_authorization_id" "uuid", "p_reason" "text") IS 'Creates one exact Test aggregate assignment derived from an active bounded standard-customer scope.';



CREATE OR REPLACE FUNCTION "tongs"."create_workspace"("p_name" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare
  v_user uuid;
begin
  v_user := auth.uid();
  if v_user is null then
    raise exception 'not_authenticated'
      using errcode = '42501';
  end if;

  return tongs.create_workspace_admin(p_name, v_user);
end;
$$;


ALTER FUNCTION "tongs"."create_workspace"("p_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."create_workspace_admin"("p_name" "text", "p_owner_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare
  wid uuid;
  v_owner uuid;
  v_name text;
  v_org_id uuid;
begin
  v_owner := p_owner_id;
  if v_owner is null then
    raise exception 'owner_id is required'
      using errcode = '22023';
  end if;

  v_name := nullif(trim(coalesce(p_name, '')), '');
  if v_name is null then
    v_name := 'Workspace';
  end if;

  v_org_id := tongs.ensure_personal_org(v_owner);

  insert into tongs.workspaces (name, created_by, org_id)
  values (v_name, v_owner, v_org_id)
  returning id into wid;

  insert into tongs.workspace_members (
    workspace_id,
    user_id,
    role,
    created_at,
    created_by
  )
  values (
    wid,
    v_owner,
    'owner',
    now(),
    v_owner
  )
  on conflict (workspace_id, user_id) do update
    set role = excluded.role,
        created_by = coalesce(tongs.workspace_members.created_by, excluded.created_by);

  return wid;
end;
$$;


ALTER FUNCTION "tongs"."create_workspace_admin"("p_name" "text", "p_owner_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."create_workspace_invite"("p_workspace_id" "uuid", "p_email" "text", "p_role" "text" DEFAULT 'viewer'::"text", "p_expires_hours" integer DEFAULT 72) RETURNS TABLE("invite_id" "uuid", "workspace_id" "uuid", "email" "text", "role" "text", "token" "text", "expires_at" timestamp with time zone, "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare
  v_user uuid;
  v_email text;
  v_role text;
  v_hours integer;
  v_token text;
  v_invite tongs.workspace_invites%rowtype;
begin
  v_user := auth.uid();
  if v_user is null then
    raise exception 'not_authenticated'
      using errcode = '42501';
  end if;

  perform tongs.assert_workspace_role(p_workspace_id, 'admin');

  v_email := lower(btrim(coalesce(p_email, '')));
  if v_email = '' then
    raise exception 'invite_email_required'
      using errcode = '22023';
  end if;

  v_role := lower(btrim(coalesce(p_role, 'viewer')));
  if tongs.workspace_role_rank(v_role) = 0 then
    raise exception 'unsupported_invite_role'
      using errcode = '22023';
  end if;

  if v_role = 'owner' and not tongs.has_workspace_role(p_workspace_id, 'owner') then
    raise exception 'owner_invite_requires_owner'
      using errcode = '42501';
  end if;

  v_hours := coalesce(p_expires_hours, 72);
  if v_hours < 1 then v_hours := 1; end if;
  if v_hours > 720 then v_hours := 720; end if;

  -- Deterministic duplicate behavior: only one pending invite per workspace/email.
  update tongs.workspace_invites wi
  set revoked_at = now(),
      updated_at = now()
  where wi.workspace_id = p_workspace_id
    and wi.email = v_email
    and wi.accepted_at is null
    and wi.revoked_at is null;

  v_token := replace(gen_random_uuid()::text, '-', '')
    || replace(gen_random_uuid()::text, '-', '');

  insert into tongs.workspace_invites (
    workspace_id,
    email,
    role,
    token,
    expires_at,
    created_by
  )
  values (
    p_workspace_id,
    v_email,
    v_role,
    v_token,
    now() + make_interval(hours => v_hours),
    v_user
  )
  returning * into v_invite;

  return query
  select
    v_invite.id,
    v_invite.workspace_id,
    v_invite.email,
    v_invite.role,
    v_invite.token,
    v_invite.expires_at,
    v_invite.created_at;
end;
$$;


ALTER FUNCTION "tongs"."create_workspace_invite"("p_workspace_id" "uuid", "p_email" "text", "p_role" "text", "p_expires_hours" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."create_workspace_with_owner"("_name" "text" DEFAULT 'Workspace'::"text") RETURNS TABLE("id" "uuid", "name" "text", "created_by" "uuid", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare
  v_user uuid;
  v_name text;
  v_org_id uuid;
  v_workspace tongs.workspaces%rowtype;
begin
  v_user := auth.uid();
  if v_user is null then
    raise exception 'Not authenticated'
      using errcode = '42501';
  end if;

  v_name := nullif(trim(coalesce(_name, '')), '');
  if v_name is null then
    v_name := 'Workspace';
  end if;

  v_org_id := tongs.ensure_personal_org(v_user);

  insert into tongs.workspaces (name, created_by, org_id)
  values (v_name, v_user, v_org_id)
  returning * into v_workspace;

  insert into tongs.workspace_members (workspace_id, user_id, role, created_at, created_by)
  values (v_workspace.id, v_user, 'owner', now(), v_user)
  on conflict (workspace_id, user_id) do update
    set role = excluded.role,
        created_by = coalesce(workspace_members.created_by, excluded.created_by);

  return query
  select
    v_workspace.id,
    v_workspace.name,
    v_workspace.created_by,
    v_workspace.created_at;
end;
$$;


ALTER FUNCTION "tongs"."create_workspace_with_owner"("_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."decide_thumbnail_candidate_historical_brand"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_candidate_revision_id" "uuid", "p_candidate_set_id" "uuid", "p_active_binding_id" "uuid", "p_decision" "text", "p_reason" "text", "p_expected_current_decision_id" "uuid", "p_expected_current_decision_revision" integer, "p_operation_id" "text", "p_operation_fingerprint" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare v_user uuid:=auth.uid(); v_binding tongs.workpiece_brand_bindings%rowtype; v_candidate tongs.thumbnail_candidate_revisions%rowtype;
 v_current tongs.thumbnail_candidate_brand_decisions%rowtype; v_op tongs.thumbnail_candidate_brand_decision_operations%rowtype; v_id uuid; v_result jsonb; v_state text;
begin
 if v_user is null then raise exception 'Not authenticated' using errcode='42501'; end if; perform tongs.assert_workspace_role(p_workspace_id,'editor');
 if not exists(select 1 from tongs.episodes where id=p_workpiece_id and workspace_id=p_workspace_id) then raise exception 'workpiece does not belong to workspace' using errcode='22023'; end if;
 if p_decision not in('approved','revoked') or length(btrim(coalesce(p_reason,'')))=0 then raise exception 'valid decision and reason are required' using errcode='22023'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_workspace_id::text||':'||p_workpiece_id::text||':brand',0));
 select * into v_binding from tongs.workpiece_brand_bindings where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id order by revision desc limit 1;
 perform pg_advisory_xact_lock(hashtextextended(p_workspace_id::text||':'||p_workpiece_id::text||':'||p_candidate_revision_id::text||':'||p_active_binding_id::text||':thumbnail-candidate-brand-decision',0));
 perform pg_advisory_xact_lock(hashtextextended(p_workspace_id::text||':'||p_operation_id||':thumbnail-authority-operation',0));
 select * into v_op from tongs.thumbnail_candidate_brand_decision_operations where workspace_id=p_workspace_id and operation_id=p_operation_id;
 if found then
  if v_op.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict','code','thumbnail_candidate_brand_operation_reused'); end if;
  select tongs.thumbnail_candidate_eligibility(p_candidate_revision_id,v_binding.id) into v_state;
  return v_op.result_json||jsonb_build_object('replayed',true,'current_eligibility',v_state,'current_active_binding_id',v_binding.id);
 end if;
 if v_binding.id is null or v_binding.id<>p_active_binding_id then
  v_result:=jsonb_build_object('disposition','binding_conflict','code','stale_active_brand_binding','current_active_binding_id',v_binding.id,'current_active_binding_revision',v_binding.revision);
  insert into tongs.thumbnail_candidate_brand_decision_operations(workspace_id,workpiece_id,operation_id,operation_fingerprint,disposition,result_json,created_by) values(p_workspace_id,p_workpiece_id,p_operation_id,p_operation_fingerprint,'binding_conflict',v_result,v_user); return v_result;
 end if;
 select * into v_candidate from tongs.thumbnail_candidate_revisions where id=p_candidate_revision_id and workspace_id=p_workspace_id and workpiece_id=p_workpiece_id;
 if not found then raise exception 'candidate revision is unavailable' using errcode='22023'; end if;
 if v_candidate.candidate_binding_id=v_binding.id then raise exception 'current-brand candidate does not require historical authorization' using errcode='22023'; end if;
 if p_candidate_set_id is not null and not exists(select 1 from tongs.thumbnail_candidate_set_members where candidate_set_id=p_candidate_set_id and candidate_revision_id=p_candidate_revision_id and workspace_id=p_workspace_id and workpiece_id=p_workpiece_id) then raise exception 'candidate set audit context mismatch' using errcode='22023'; end if;
 select * into v_current from tongs.thumbnail_candidate_brand_decisions where candidate_revision_id=p_candidate_revision_id and active_binding_id=p_active_binding_id order by decision_revision desc limit 1;
 if (v_current.id is null and (p_expected_current_decision_id is not null or coalesce(p_expected_current_decision_revision,0)<>0)) or (v_current.id is not null and (p_expected_current_decision_id is distinct from v_current.id or p_expected_current_decision_revision is distinct from v_current.decision_revision)) then
  v_result:=jsonb_build_object('disposition','decision_conflict','code','stale_candidate_brand_decision','current_decision_id',v_current.id,'current_decision_revision',coalesce(v_current.decision_revision,0),'eligibility_state',tongs.thumbnail_candidate_eligibility(p_candidate_revision_id,p_active_binding_id));
  insert into tongs.thumbnail_candidate_brand_decision_operations(workspace_id,workpiece_id,operation_id,operation_fingerprint,disposition,result_json,created_by) values(p_workspace_id,p_workpiece_id,p_operation_id,p_operation_fingerprint,'decision_conflict',v_result,v_user); return v_result;
 end if;
 if v_current.id is not null and v_current.decision=p_decision then
  v_result:=jsonb_build_object('disposition','no_change','decision_id',v_current.id,'decision_revision',v_current.decision_revision,'eligibility_state',tongs.thumbnail_candidate_eligibility(p_candidate_revision_id,p_active_binding_id));
  insert into tongs.thumbnail_candidate_brand_decision_operations(workspace_id,workpiece_id,operation_id,operation_fingerprint,disposition,decision_id,result_json,created_by) values(p_workspace_id,p_workpiece_id,p_operation_id,p_operation_fingerprint,'no_change',v_current.id,v_result,v_user); return v_result;
 end if;
 v_id:=gen_random_uuid();
 insert into tongs.thumbnail_candidate_brand_decisions(id,workspace_id,workpiece_id,candidate_revision_id,candidate_set_id,recipe_id,recipe_revision,recipe_hash,composite_asset_id,composite_content_hash,candidate_binding_id,candidate_binding_revision,active_binding_id,active_binding_revision,decision_revision,decision,reason,previous_decision_id,operation_id,operation_fingerprint,created_by)
 values(v_id,p_workspace_id,p_workpiece_id,v_candidate.id,p_candidate_set_id,v_candidate.recipe_id,v_candidate.recipe_revision,v_candidate.recipe_hash,v_candidate.composite_asset_id,v_candidate.composite_content_hash,v_candidate.candidate_binding_id,v_candidate.candidate_binding_revision,v_binding.id,v_binding.revision,coalesce(v_current.decision_revision,0)+1,p_decision,btrim(p_reason),v_current.id,p_operation_id,p_operation_fingerprint,v_user);
 v_state:=case when p_decision='approved' then 'approved_historical_brand' else 'requires_reapproval' end;
 v_result:=jsonb_build_object('disposition',p_decision,'decision_id',v_id,'decision_revision',coalesce(v_current.decision_revision,0)+1,'candidate_revision_id',v_candidate.id,'authorized_active_binding_id',v_binding.id,'eligibility_state',v_state);
 insert into tongs.thumbnail_candidate_brand_decision_operations(workspace_id,workpiece_id,operation_id,operation_fingerprint,disposition,decision_id,result_json,created_by) values(p_workspace_id,p_workpiece_id,p_operation_id,p_operation_fingerprint,p_decision,v_id,v_result,v_user); return v_result;
end $$;


ALTER FUNCTION "tongs"."decide_thumbnail_candidate_historical_brand"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_candidate_revision_id" "uuid", "p_candidate_set_id" "uuid", "p_active_binding_id" "uuid", "p_decision" "text", "p_reason" "text", "p_expected_current_decision_id" "uuid", "p_expected_current_decision_revision" integer, "p_operation_id" "text", "p_operation_fingerprint" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."delete_org_team"("p_team_id" "uuid") RETURNS TABLE("deleted" boolean, "team_id" "uuid", "org_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare
  v_team tongs.teams%rowtype;
begin
  if p_team_id is null then
    raise exception 'team_id is required'
      using errcode = '22023';
  end if;

  select t.*
  into v_team
  from tongs.teams t
  where t.id = p_team_id
  for update;

  if not found then
    raise exception 'Team not found'
      using errcode = 'P0002';
  end if;

  perform tongs.assert_org_role(v_team.org_id, 'admin');

  delete from tongs.teams
  where id = p_team_id;

  return query
  select true, v_team.id, v_team.org_id;
end;
$$;


ALTER FUNCTION "tongs"."delete_org_team"("p_team_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."delete_workspace_with_owner_check"("_workspace_id" "uuid") RETURNS TABLE("deleted" boolean, "workspace_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare
  v_user uuid;
  v_workspace tongs.workspaces%rowtype;
  v_active_episode_count integer;
begin
  v_user := auth.uid();
  if v_user is null then
    raise exception 'Not authenticated'
      using errcode = '42501';
  end if;

  if _workspace_id is null then
    raise exception 'workspace_id is required'
      using errcode = '22023';
  end if;

  select w.*
  into v_workspace
  from tongs.workspaces w
  where w.id = _workspace_id;

  if not found then
    raise exception 'Workspace not found'
      using errcode = 'P0002';
  end if;

  if not (
    v_workspace.created_by = v_user
    or exists (
      select 1
      from tongs.workspace_members wm
      where wm.workspace_id = _workspace_id
        and wm.user_id = v_user
        and wm.role = 'owner'
    )
  ) then
    raise exception 'Only workspace owners can delete workspaces'
      using errcode = '42501';
  end if;

  select count(*)
  into v_active_episode_count
  from tongs.episodes e
  where e.workspace_id = _workspace_id
    and e.archived_at is null;

  if coalesce(v_active_episode_count, 0) > 0 then
    raise exception 'Archive all episodes before deleting this workspace'
      using errcode = 'P0001';
  end if;

  delete from tongs.workspaces w
  where w.id = _workspace_id;

  if not found then
    raise exception 'Workspace delete failed'
      using errcode = 'P0001';
  end if;

  return query
  select true, _workspace_id;
end;
$$;


ALTER FUNCTION "tongs"."delete_workspace_with_owner_check"("_workspace_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."disconnect_user_ai_key"("p_provider" "text", "p_provider_account_id" "text" DEFAULT NULL::"text") RETURNS TABLE("provider" "text", "provider_account_id" "text", "status" "text", "connected" boolean, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare
  v_user_id uuid;
  v_provider text;
begin
  v_user_id := auth.uid();
  if v_user_id is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;

  v_provider := lower(btrim(coalesce(p_provider, '')));
  if v_provider = '' then
    raise exception 'Provider is required' using errcode = '22023';
  end if;

  update tongs.user_ai_keys
  set
    status = 'revoked',
    updated_at = now()
  where user_id = v_user_id
    and provider = v_provider
    and provider_account_id is not distinct from nullif(btrim(coalesce(p_provider_account_id, '')), '');

  return query
  select
    s.provider,
    s.provider_account_id,
    s.status,
    (s.status = 'active') as connected,
    s.updated_at
  from tongs.user_ai_keys_safe s
  where s.user_id = v_user_id
    and s.provider = v_provider
    and s.provider_account_id is not distinct from nullif(btrim(coalesce(p_provider_account_id, '')), '');
end;
$$;


ALTER FUNCTION "tongs"."disconnect_user_ai_key"("p_provider" "text", "p_provider_account_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."dismiss_barstock_discovery_story"("p_workspace_id" "uuid", "p_story_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare u uuid:=auth.uid(); begin if u is null or not tongs.has_workspace_role(p_workspace_id,'editor') then return jsonb_build_object('outcome','denied');end if;
 if not exists(select 1 from tongs.barstock_discovery_stories where id=p_story_id and workspace_id=p_workspace_id and user_id=u) then return jsonb_build_object('outcome','not_found');end if;
 insert into tongs.barstock_discovery_dismissals(workspace_id,user_id,story_id) values(p_workspace_id,u,p_story_id) on conflict(workspace_id,user_id,story_id) do update set dismissed_at=now(),expires_at=now()+interval '14 days'; return jsonb_build_object('outcome','dismissed','expires_at',now()+interval '14 days'); end$$;


ALTER FUNCTION "tongs"."dismiss_barstock_discovery_story"("p_workspace_id" "uuid", "p_story_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."enforce_barstock_project_atomicity_on_sparks"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'tongs', 'pg_temp'
    AS $$
declare
  v_project_status text;
begin
  -- Only applies when spark is inside a Project
  if new.assignment_id is not null then
    select a.status
      into v_project_status
      from tongs.barstock_assignments a
     where a.id = new.assignment_id;

    if v_project_status is null then
      raise exception using
        errcode = '23503',
        message = 'Spark references non-existent Project (assignment_id).';
    end if;

    -- Block: graduating a spark while project is still open
    if new.status = 'graduated' and coalesce(v_project_status, 'open') <> 'archived' then
      raise exception using
        errcode = '23514',
        message = 'Cannot graduate an individual spark inside an open Project. Archive (graduate) the Project instead.';
    end if;

    -- One-way door: forbid un-graduating sparks inside an archived project
    if old is not null and old.status = 'graduated' and new.status <> 'graduated' and v_project_status = 'archived' then
      raise exception using
        errcode = '23514',
        message = 'Cannot un-graduate sparks in an archived Project.';
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "tongs"."enforce_barstock_project_atomicity_on_sparks"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."enforce_canonical_asset_identity_immutability"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
begin
  if new.workspace_id is distinct from old.workspace_id
    or new.asset_scope is distinct from old.asset_scope
    or new.workpiece_id is distinct from old.workpiece_id
    or new.provenance_classification is distinct from old.provenance_classification then
    raise exception 'canonical_asset_identity_immutable' using errcode = '55000';
  end if;

  if old.status in ('ready','superseded') or old.reference_committed_at is not null then
    if new.storage_bucket is distinct from old.storage_bucket
      or new.storage_key is distinct from old.storage_key
      or new.content_hash is distinct from old.content_hash
      or new.bytes is distinct from old.bytes
      or new.mime_type is distinct from old.mime_type
      or new.asset_kind is distinct from old.asset_kind then
      raise exception 'canonical_asset_evidence_immutable' using errcode = '55000';
    end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "tongs"."enforce_canonical_asset_identity_immutability"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."enforce_canonical_recording_immutable"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'tongs'
    AS $$
begin
  -- Workspace/workpiece identity is never mutable.
  if new.workspace_id <> old.workspace_id then
    raise exception 'canonical_recordings.workspace_id is immutable';
  end if;
  if new.workpiece_id <> old.workpiece_id then
    raise exception 'canonical_recordings.workpiece_id is immutable';
  end if;

  -- Once sealed, media receipt and baseline pointers are immutable.
  if old.sealed_at is not null then
    if new.media_path <> old.media_path
      or coalesce(new.media_content_type, '') <> coalesce(old.media_content_type, '')
      or coalesce(new.media_bytes, -1) <> coalesce(old.media_bytes, -1)
      or coalesce(new.media_duration_ms, -1) <> coalesce(old.media_duration_ms, -1)
      or coalesce(new.recording_session_id::text, '') <> coalesce(old.recording_session_id::text, '')
      or coalesce(new.anvil_capture_session_id, '') <> coalesce(old.anvil_capture_session_id, '')
      or new.media_id <> old.media_id
      or coalesce(new.media_signature, '') <> coalesce(old.media_signature, '')
      or coalesce(new.kept_take_event_id, -1) <> coalesce(old.kept_take_event_id, -1)
    then
      raise exception 'canonical_recordings media receipt fields are immutable after sealed_at';
    end if;

    if coalesce(new.baseline_transcript_path, '') <> coalesce(old.baseline_transcript_path, '')
      or coalesce(new.baseline_timing_path, '') <> coalesce(old.baseline_timing_path, '')
      or coalesce(new.baseline_speaker_map_path, '') <> coalesce(old.baseline_speaker_map_path, '')
    then
      raise exception 'canonical_recordings baseline artifact pointers are immutable after sealed_at';
    end if;

    if new.sealed_at <> old.sealed_at then
      raise exception 'canonical_recordings.sealed_at is immutable once set';
    end if;
  end if;

  -- When sealing (transition null -> non-null), require baseline transcript to be present.
  if old.sealed_at is null and new.sealed_at is not null then
    if new.status <> 'sealed' then
      raise exception 'canonical_recordings.status must be sealed when sealed_at is set';
    end if;
    if new.baseline_transcript_path is null then
      raise exception 'canonical_recordings.baseline_transcript_path must be set before sealing';
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "tongs"."enforce_canonical_recording_immutable"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."enqueue_youtube_publication_job"("p_publication_operation_id" "uuid", "p_publication_attempt_id" "uuid", "p_finalized_package_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare v_user uuid:=auth.uid(); v_op tongs.publication_operations%rowtype; v_pkg tongs.quench_destination_package_revisions%rowtype; v_id uuid;
begin
  select * into v_op from tongs.publication_operations where id=p_publication_operation_id;
  if not found or v_user is null or not tongs.has_workspace_role(v_op.workspace_id,'editor') then raise exception 'Not authorized' using errcode='42501'; end if;
  select * into v_pkg from tongs.quench_destination_package_revisions where id=p_finalized_package_id and state='finalized';
  if not found or v_pkg.workspace_id<>v_op.workspace_id or v_pkg.workpiece_id<>v_op.workpiece_id or v_pkg.executable_destination_id<>v_op.executable_destination_id or v_pkg.manifest_snapshot_id<>v_op.manifest_snapshot_id then return jsonb_build_object('disposition','blocked','code','finalized_package_mismatch'); end if;
  insert into tongs.youtube_publication_jobs(publication_operation_id,publication_attempt_id,finalized_package_id,workspace_id,workpiece_id,state,current_stage)
  values(v_op.id,p_publication_attempt_id,v_pkg.id,v_op.workspace_id,v_op.workpiece_id,'queued','queued')
  on conflict(publication_attempt_id) do update set updated_at=tongs.youtube_publication_jobs.updated_at returning id into v_id;
  insert into tongs.youtube_publication_job_secrets(job_id) values(v_id) on conflict do nothing;
  return jsonb_build_object('disposition','queued','job_id',v_id);
end; $$;


ALTER FUNCTION "tongs"."enqueue_youtube_publication_job"("p_publication_operation_id" "uuid", "p_publication_attempt_id" "uuid", "p_finalized_package_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."ensure_org_member_for_team_member"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare
  v_org_id uuid;
  v_fallback_created_by uuid;
begin
  select t.org_id
  into v_org_id
  from tongs.teams t
  where t.id = new.team_id;

  if v_org_id is null then
    return new;
  end if;

  select owner_row.user_id
  into v_fallback_created_by
  from tongs.org_members owner_row
  where owner_row.org_id = v_org_id
    and owner_row.org_role = 'owner'
  order by owner_row.created_at asc nulls last
  limit 1;

  insert into tongs.org_members (
    org_id,
    user_id,
    org_role,
    created_at,
    created_by
  )
  values (
    v_org_id,
    new.user_id,
    'member',
    coalesce(new.created_at, now()),
    coalesce(new.created_by, v_fallback_created_by)
  )
  on conflict (org_id, user_id) do nothing;

  return new;
end;
$$;


ALTER FUNCTION "tongs"."ensure_org_member_for_team_member"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."ensure_personal_org"("p_user_id" "uuid" DEFAULT "auth"."uid"()) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare
  v_user uuid;
  v_org_id uuid;
begin
  v_user := coalesce(p_user_id, auth.uid());
  if v_user is null then
    raise exception 'Not authenticated'
      using errcode = '42501';
  end if;

  select o.id
  into v_org_id
  from tongs.orgs o
  where o.personal_owner_user_id = v_user
  limit 1;

  if v_org_id is null then
    insert into tongs.orgs (
      name,
      created_by,
      personal_owner_user_id,
      created_at,
      updated_at
    )
    values (
      'Personal Org',
      v_user,
      v_user,
      now(),
      now()
    )
    on conflict (personal_owner_user_id) do update
      set personal_owner_user_id = excluded.personal_owner_user_id
    returning id into v_org_id;
  end if;

  insert into tongs.org_members (
    org_id,
    user_id,
    org_role,
    created_at,
    created_by
  )
  values (
    v_org_id,
    v_user,
    'owner',
    now(),
    v_user
  )
  on conflict (org_id, user_id) do update
  set org_role = 'owner';

  return v_org_id;
end;
$$;


ALTER FUNCTION "tongs"."ensure_personal_org"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."episode_label_from_spark"("spark_title" "text", "spark_body" "text", "spark_created_at" timestamp with time zone) RETURNS "text"
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'tongs', 'pg_temp'
    AS $$
  with src as (
    select
      -- choose title first, fallback to body
      coalesce(nullif(trim(spark_title), ''), nullif(trim(spark_body), ''), '') as base_text
  ),
  token as (
    select tongs._sanitize_keyword(tongs._first_token(base_text)) as kw
    from src
  ),
  kw2 as (
    select case when kw = '' then 'idea' else kw end as kw from token
  )
  select
    (select kw from kw2)
    || '_' || to_char(spark_created_at at time zone 'UTC', 'YYYY-MM-DD')
    || '_' || to_char(spark_created_at at time zone 'UTC', 'HH24MI')
$$;


ALTER FUNCTION "tongs"."episode_label_from_spark"("spark_title" "text", "spark_body" "text", "spark_created_at" timestamp with time zone) OWNER TO "postgres";


