ALTER FUNCTION "tongs"."establish_anvil_capture_authority"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_capture_session_id" "uuid", "p_operation_key" "text", "p_recording_session_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."establish_owner_cost_operation"("p_operation_id" "uuid", "p_operation_key" "text", "p_request_fingerprint" "text", "p_financial_environment" "text", "p_runtime_environment" "text", "p_originating_tool" "text", "p_operation_type" "text", "p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_recording_session_id" "uuid", "p_recording_capture_authority_id" "uuid", "p_anvil_capture_execution_id" "uuid", "p_owner_operating_budget_id" "uuid", "p_creation_evidence" "jsonb", "p_created_at" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $_$
declare
  v_key text := btrim(coalesce(p_operation_key, ''));
  v_fingerprint text := lower(btrim(coalesce(p_request_fingerprint, '')));
  v_financial text := lower(btrim(coalesce(p_financial_environment, '')));
  v_runtime text := lower(btrim(coalesce(p_runtime_environment, '')));
  v_tool text := lower(btrim(coalesce(p_originating_tool, '')));
  v_type text := lower(btrim(coalesce(p_operation_type, '')));
  v_payload jsonb;
  v_hash text;
  v_existing tongs.owner_cost_operations%rowtype;
begin
  perform tongs._require_accounting_service_role();
  if p_operation_id is null or length(v_key) not between 16 and 300
     or v_fingerprint !~ '^[0-9a-f]{64}$' or v_financial not in ('live', 'test')
     or v_runtime not in ('production', 'preview', 'development')
     or length(v_tool) not between 2 and 80 or length(v_type) not between 2 and 100
     or p_created_at is null
     or jsonb_typeof(coalesce(p_creation_evidence, '{}'::jsonb)) <> 'object' then
    raise exception 'invalid owner-cost operation' using errcode = '22023';
  end if;
  perform tongs._validate_owner_cost_attribution(
    p_workspace_id, p_workpiece_id, p_recording_session_id,
    p_recording_capture_authority_id, p_anvil_capture_execution_id
  );
  if p_owner_operating_budget_id is not null and not exists (
    select 1 from tongs.owner_operating_budgets b
    where b.id = p_owner_operating_budget_id and b.environment = v_runtime
      and (b.workspace_id is null or b.workspace_id is not distinct from p_workspace_id)
  ) then raise exception 'owner budget classification mismatch' using errcode = '23514'; end if;

  v_payload := jsonb_build_object(
    'operation_id', p_operation_id, 'operation_key', v_key, 'request_fingerprint', v_fingerprint,
    'financial_environment', v_financial, 'runtime_environment', v_runtime, 'payer', 'forge',
    'originating_tool', v_tool, 'operation_type', v_type, 'workspace_id', p_workspace_id,
    'workpiece_id', p_workpiece_id, 'recording_session_id', p_recording_session_id,
    'recording_capture_authority_id', p_recording_capture_authority_id,
    'anvil_capture_execution_id', p_anvil_capture_execution_id,
    'owner_operating_budget_id', p_owner_operating_budget_id,
    'creation_evidence', coalesce(p_creation_evidence, '{}'::jsonb),
    'created_at', p_created_at
  );
  v_hash := tongs._accounting_payload_hash(v_payload);
  perform pg_advisory_xact_lock(hashtextextended('owner-cost-operation:' || v_key, 0));
  select * into v_existing from tongs.owner_cost_operations o
    where o.operation_key = v_key or o.operation_id = p_operation_id limit 1;
  if found then
    if v_existing.operation_id <> p_operation_id or v_existing.payload_hash <> v_hash then
      raise exception 'owner-cost operation replay conflict' using errcode = '23505';
    end if;
    return jsonb_build_object('operation_id', v_existing.operation_id, 'replay', true);
  end if;
  insert into tongs.owner_cost_operations(
    operation_id, operation_key, request_fingerprint, payload_hash, financial_environment,
    runtime_environment, originating_tool, operation_type, workspace_id, workpiece_id,
    recording_session_id, recording_capture_authority_id, anvil_capture_execution_id,
    owner_operating_budget_id, creation_evidence, created_at
  ) values (
    p_operation_id, v_key, v_fingerprint, v_hash, v_financial, v_runtime, v_tool, v_type,
    p_workspace_id, p_workpiece_id, p_recording_session_id, p_recording_capture_authority_id,
    p_anvil_capture_execution_id, p_owner_operating_budget_id,
    coalesce(p_creation_evidence, '{}'::jsonb), p_created_at
  );
  return jsonb_build_object('operation_id', p_operation_id, 'replay', false);
end;
$_$;


ALTER FUNCTION "tongs"."establish_owner_cost_operation"("p_operation_id" "uuid", "p_operation_key" "text", "p_request_fingerprint" "text", "p_financial_environment" "text", "p_runtime_environment" "text", "p_originating_tool" "text", "p_operation_type" "text", "p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_recording_session_id" "uuid", "p_recording_capture_authority_id" "uuid", "p_anvil_capture_execution_id" "uuid", "p_owner_operating_budget_id" "uuid", "p_creation_evidence" "jsonb", "p_created_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."establish_publication_operation"("p_operation_key" "uuid", "p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_manifest_snapshot_id" "uuid", "p_manifest_content_hash" "text", "p_release_decision_id" "uuid", "p_release_decision_revision" integer, "p_executable_destination_id" "uuid", "p_destination_capability_revision_id" "uuid", "p_publication_intent_contract_version" "text", "p_publication_intent_snapshot" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs', 'extensions'
    AS $$
declare
  v_user uuid := auth.uid(); v_existing tongs.publication_operations%rowtype;
  v_manifest tongs.quench_release_manifest_snapshots%rowtype; v_decision tongs.quench_release_decision_revisions%rowtype;
  v_scope tongs.quench_destination_scopes%rowtype;
  v_destination tongs.publishing_executable_destinations%rowtype; v_cap tongs.publishing_destination_capability_revisions%rowtype;
  v_intent_hash text; v_fingerprint text; v_id uuid;
begin
  if v_user is null or not tongs.has_workspace_role(p_workspace_id, 'editor') then raise exception 'Not authorized to establish publication' using errcode = '42501'; end if;
  if jsonb_typeof(p_publication_intent_snapshot) <> 'object' or length(btrim(p_publication_intent_contract_version)) = 0 then return jsonb_build_object('disposition','invalid','code','publication_intent_invalid'); end if;
  v_intent_hash:=encode(digest(convert_to(p_publication_intent_snapshot::text,'UTF8'),'sha256'),'hex');
  select * into v_existing from tongs.publication_operations where operation_key=p_operation_key;
  if found then
    if v_existing.workspace_id<>p_workspace_id or v_existing.workpiece_id<>p_workpiece_id or v_existing.manifest_snapshot_id<>p_manifest_snapshot_id or v_existing.manifest_content_hash<>lower(p_manifest_content_hash) or v_existing.release_decision_id<>p_release_decision_id or v_existing.release_decision_revision<>p_release_decision_revision or v_existing.executable_destination_id<>p_executable_destination_id or v_existing.destination_capability_revision_id<>p_destination_capability_revision_id or v_existing.publication_intent_contract_version<>p_publication_intent_contract_version or v_existing.publication_intent_content_hash<>v_intent_hash then return jsonb_build_object('disposition','publication_operation_idempotency_conflict'); end if;
    return jsonb_build_object('disposition','replayed','publication_operation_id',v_existing.id,'authority_fingerprint',v_existing.authority_fingerprint);
  end if;
  select * into v_manifest from tongs.quench_release_manifest_snapshots where id=p_manifest_snapshot_id and workspace_id=p_workspace_id and workpiece_id=p_workpiece_id;
  if not found or v_manifest.manifest_content_hash<>lower(p_manifest_content_hash) then return jsonb_build_object('disposition','blocked','code','publication_manifest_mismatch'); end if;
  if not v_manifest.ready_for_quench or v_manifest.canonical_readiness_status<>'ready' or coalesce(v_manifest.parsed_manifest_json->'packaging_media_readiness'->>'state','unresolved')<>'ready' then return jsonb_build_object('disposition','blocked','code','publication_media_not_ready'); end if;
  select * into v_decision from tongs.quench_release_decision_revisions where id=p_release_decision_id and workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and revision=p_release_decision_revision;
  if not found or v_decision.manifest_snapshot_id<>v_manifest.id or v_decision.manifest_content_hash<>v_manifest.manifest_content_hash or v_decision.intent_state='cancelled' then return jsonb_build_object('disposition','blocked','code','publication_release_decision_mismatch'); end if;
  select * into v_scope from tongs.quench_destination_scopes where id=v_decision.destination_scope_id;
  select * into v_destination from tongs.publishing_executable_destinations where id=p_executable_destination_id;
  if not found or v_destination.state<>'active' or not tongs.publishing_destination_grant_is_active(p_workspace_id,p_executable_destination_id) then return jsonb_build_object('disposition','blocked','code','publication_destination_unavailable'); end if;
  if v_scope.platform<>coalesce(p_publication_intent_snapshot->>'platform','') or (v_destination.provider='google' and v_scope.platform<>'youtube') or (v_destination.provider='rss_host' and v_scope.platform<>'podcast_host') then return jsonb_build_object('disposition','blocked','code','publication_destination_decision_mismatch'); end if;
  select * into v_cap from tongs.publishing_destination_capability_revisions where id=p_destination_capability_revision_id and executable_destination_id=p_executable_destination_id;
  if not found or v_destination.current_capability_revision_id<>v_cap.id then return jsonb_build_object('disposition','blocked','code','publication_capability_revision_mismatch'); end if;
  if v_scope.platform='youtube' and coalesce(v_cap.capabilities_json->'video_upload','false'::jsonb)<>'true'::jsonb then return jsonb_build_object('disposition','blocked','code','publication_capability_incompatible'); end if; if v_scope.platform='podcast_host' and not tongs.quench_podcast_host_capability_is_compatible(v_cap.capabilities_json) then return jsonb_build_object('disposition','blocked','code','publication_capability_incompatible'); end if;
  v_fingerprint:=encode(digest(convert_to(jsonb_build_object('workspace_id',p_workspace_id,'workpiece_id',p_workpiece_id,'manifest_snapshot_id',v_manifest.id,'manifest_hash',v_manifest.manifest_content_hash,'decision_id',v_decision.id,'decision_revision',v_decision.revision,'decision_hash',v_decision.decision_content_hash,'destination_id',v_destination.id,'capability_id',v_cap.id,'capability_revision',v_cap.revision,'capability_hash',v_cap.content_hash,'intent_contract',p_publication_intent_contract_version,'intent_hash',v_intent_hash)::text,'UTF8'),'sha256'),'hex');
  insert into tongs.publication_operations(operation_key,authority_fingerprint,workspace_id,workpiece_id,manifest_snapshot_id,manifest_content_hash,release_decision_id,release_decision_scope_id,release_decision_revision,release_decision_content_hash,executable_destination_id,destination_capability_revision_id,destination_capability_revision,destination_capability_content_hash,publication_intent_contract_version,publication_intent_snapshot,publication_intent_content_hash,established_by)
  values(p_operation_key,v_fingerprint,p_workspace_id,p_workpiece_id,v_manifest.id,v_manifest.manifest_content_hash,v_decision.id,v_decision.destination_scope_id,v_decision.revision,v_decision.decision_content_hash,v_destination.id,v_cap.id,v_cap.revision,v_cap.content_hash,p_publication_intent_contract_version,p_publication_intent_snapshot,v_intent_hash,v_user) returning id into v_id;
  return jsonb_build_object('disposition','established','publication_operation_id',v_id,'authority_fingerprint',v_fingerprint);
exception when unique_violation then
  select * into v_existing from tongs.publication_operations where operation_key=p_operation_key;
  if found and v_existing.authority_fingerprint=v_fingerprint then return jsonb_build_object('disposition','replayed','publication_operation_id',v_existing.id,'authority_fingerprint',v_existing.authority_fingerprint); end if;
  return jsonb_build_object('disposition','publication_operation_idempotency_conflict');
end; $$;


ALTER FUNCTION "tongs"."establish_publication_operation"("p_operation_key" "uuid", "p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_manifest_snapshot_id" "uuid", "p_manifest_content_hash" "text", "p_release_decision_id" "uuid", "p_release_decision_revision" integer, "p_executable_destination_id" "uuid", "p_destination_capability_revision_id" "uuid", "p_publication_intent_contract_version" "text", "p_publication_intent_snapshot" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."establish_recording_capture_authority"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_venue" "text", "p_execution_id" "uuid", "p_operation_key" "text", "p_recording_session_id" "uuid" DEFAULT NULL::"uuid", "p_venue_version" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare
  v_user uuid:=auth.uid();
  v_key text:=btrim(coalesce(p_operation_key,''));
  v_venue text:=lower(btrim(coalesce(p_venue,'')));
  v_fingerprint text;
  v_ready record;
  v_existing tongs.recording_capture_authorities%rowtype;
  v_saved tongs.recording_capture_authorities%rowtype;
  v_execution tongs.anvil_capture_executions%rowtype;
begin
  if v_user is null or not tongs.has_workspace_role(p_workspace_id,'editor') then
    return jsonb_build_object('outcome','denied','reason','editor_required');
  end if;
  if v_venue not in ('anvil','bellows') or length(v_key) not between 8 and 200 or (v_venue='anvil' and p_execution_id is null) then
    return jsonb_build_object('outcome','conflict','reason','invalid_capture_request');
  end if;
  if not exists(
    select 1 from tongs.episodes
    where id=p_workpiece_id and workspace_id=p_workspace_id
      and archived_at is null and deleted_at is null
  ) then
    return jsonb_build_object('outcome','not_found','reason','episode_membership_invalid');
  end if;
  v_fingerprint:=md5(concat_ws('|',p_workspace_id,p_workpiece_id,v_venue,p_execution_id,p_recording_session_id));
  perform pg_advisory_xact_lock(hashtextextended(p_workspace_id::text||':'||v_key,0));
  select * into v_existing
  from tongs.recording_capture_authorities
  where workspace_id=p_workspace_id and operation_key=v_key;
  if found then
    if v_existing.request_fingerprint<>v_fingerprint then
      return jsonb_build_object('outcome','conflict','reason','operation_key_reused');
    end if;
    select * into v_execution
    from tongs.anvil_capture_executions
    where recording_capture_authority_id=v_existing.id;
    return jsonb_build_object(
      'outcome','duplicate','capture_authority',to_jsonb(v_existing),
      'venue_execution',case when v_execution.execution_id is null then null else to_jsonb(v_execution) end
    );
  end if;
  select * into v_ready
  from tongs.current_workpiece_ready_scripts
  where workspace_id=p_workspace_id
    and workpiece_id=p_workpiece_id
    and script_path='script/script.md';
  if v_venue='anvil' and v_ready.transition_id is null then
    return jsonb_build_object('outcome','conflict','reason','approved_ready_script_required');
  end if;
  insert into tongs.recording_capture_authorities(
    workspace_id,workpiece_id,recording_session_id,ready_transition_id,
    script_path,script_revision,script_hash,
    script_approval_id,script_approval_revision,script_approval_hash,
    preflight_report_id,preflight_report_revision,preflight_script_hash,
    research_artifact_id,research_artifact_hash,
    operation_key,provenance,established_by,venue,script_binding_kind,request_fingerprint
  ) values(
    p_workspace_id,p_workpiece_id,p_recording_session_id,v_ready.transition_id,
    v_ready.script_path,v_ready.script_revision,v_ready.script_hash,
    v_ready.script_approval_id,v_ready.script_approval_revision,v_ready.script_approval_hash,
    v_ready.preflight_report_id,v_ready.preflight_report_revision,v_ready.preflight_script_hash,
    v_ready.research_artifact_id,v_ready.research_artifact_hash,
    v_key,'live_established',v_user,v_venue,
    case when v_ready.transition_id is null then 'none' else 'approved_canonical_script' end,
    v_fingerprint
  ) returning * into v_saved;
  if v_venue='anvil' then
    insert into tongs.anvil_capture_executions(
      execution_id,recording_capture_authority_id,operation_key,anvil_version,created_by
    ) values(
      p_execution_id,v_saved.id,v_key,p_venue_version,v_user
    ) returning * into v_execution;
  end if;
  return jsonb_build_object(
    'outcome','established','capture_authority',to_jsonb(v_saved),
    'venue_execution',case when v_execution.execution_id is null then null else to_jsonb(v_execution) end
  );
end;
$$;


ALTER FUNCTION "tongs"."establish_recording_capture_authority"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_venue" "text", "p_execution_id" "uuid", "p_operation_key" "text", "p_recording_session_id" "uuid", "p_venue_version" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."fail_barstock_discovery_refresh"("p_run_id" "uuid", "p_lease_token_hash" "text", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
begin if auth.role()<>'service_role' then return jsonb_build_object('outcome','denied');end if; update tongs.barstock_discovery_runs set status='failed',failure_reason=p_reason,lease_token_hash='',lease_expires_at=now(),updated_at=now() where id=p_run_id and lease_token_hash=p_lease_token_hash and lease_expires_at>now() and status in('leased','refreshing'); return jsonb_build_object('outcome',case when found then 'failed' else 'lease_lost' end);end$$;


