CREATE OR REPLACE FUNCTION "tongs"."fail_bellows_hammer_handoff"("p_package_id" "uuid", "p_error" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare r tongs.bellows_hammer_handoff_receipts;
begin
  select * into r from tongs.bellows_hammer_handoff_receipts where package_id=p_package_id for update;
  if not found then return jsonb_build_object('outcome','not_found'); end if;
  if not tongs.has_workspace_role(r.workspace_id,'editor') then return jsonb_build_object('outcome','denied'); end if;
  if r.state='committed' then return jsonb_build_object('outcome','committed','receipt',to_jsonb(r)); end if;
  update tongs.bellows_hammer_handoff_receipts set state='recoverable_failure',last_error=left(coalesce(p_error,'unknown'),1000) where id=r.id returning * into r;
  return jsonb_build_object('outcome','recoverable_failure','receipt',to_jsonb(r));
end $$;


ALTER FUNCTION "tongs"."fail_bellows_hammer_handoff"("p_package_id" "uuid", "p_error" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."fail_broll_operation"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_failed_stage" "text", "p_failure_code" "text", "p_failure_message" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare v_op tongs.broll_operation_receipts%rowtype;
begin
 select * into v_op from tongs.broll_operation_receipts where operation_id=p_operation_id for update;
 if not found then return jsonb_build_object('disposition','operation_not_found'); end if;
 if not tongs.has_workspace_role(v_op.workspace_id,'editor') then raise exception 'workspace editor authority required' using errcode='42501'; end if;
 if v_op.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict'); end if;
 if v_op.state in('committed','candidate_committed','selected') then return jsonb_build_object('disposition','terminal_operation','operation',to_jsonb(v_op)); end if;
 update tongs.broll_operation_receipts set state='failed',failed_stage=p_failed_stage,failure_code=p_failure_code,failure_message=p_failure_message,updated_at=now() where operation_id=p_operation_id returning * into v_op;
 return jsonb_build_object('disposition','failed','operation',to_jsonb(v_op));
end $$;


