    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $_$
  select tongs._finish_customer_hearth_research_stage($1,$2,'failed',$4,null,coalesce($5,'{}')||jsonb_build_object('failure_code',$3))
$_$;


