CREATE OR REPLACE FUNCTION "tongs"."fail_hammer_audio_render"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_failure_code" "text", "p_failure_message" "text", "p_outcome_unknown" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare op tongs.hammer_audio_render_operations%rowtype;
begin
  if auth.role()<>'service_role' then raise exception 'Hammer audio render failure requires service authority' using errcode='42501'; end if;
  update tongs.hammer_audio_render_operations set state=case when p_outcome_unknown then'outcome_unknown'else'failed'end,failure_code=p_failure_code,failure_message=p_failure_message,updated_at=now()
  where operation_id=p_operation_id and operation_fingerprint=p_operation_fingerprint and state in('pending','rendering') returning * into op;
  return jsonb_build_object('disposition',case when op.operation_id is null then'not_updated'else op.state end,'operation',to_jsonb(op));
end$$;


ALTER FUNCTION "tongs"."fail_hammer_audio_render"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_failure_code" "text", "p_failure_message" "text", "p_outcome_unknown" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."fail_hammer_short_derivative"("p_derivative_id" "uuid", "p_failure_code" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare v_actor uuid:=auth.uid(); v_row tongs.hammer_short_derivatives%rowtype;
begin
  select * into v_row from tongs.hammer_short_derivatives where id=p_derivative_id for update;
  if v_actor is null or v_row.id is null or not tongs.has_workspace_role(v_row.workspace_id,'editor') then
    raise exception 'hammer_shorts_editor_required' using errcode='42501';
  end if;
  if v_row.state='ready' then raise exception 'hammer_short_derivative_already_ready' using errcode='40001'; end if;
  update tongs.hammer_short_derivatives set state='failed',failure_code=left(coalesce(nullif(trim(p_failure_code),''),'projection_failed'),120)
  where id=v_row.id returning * into v_row;
  return to_jsonb(v_row);
end $$;


ALTER FUNCTION "tongs"."fail_hammer_short_derivative"("p_derivative_id" "uuid", "p_failure_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."fail_hammer_shorts_discovery"("p_discovery_id" "uuid", "p_failure_code" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare v_actor uuid:=auth.uid(); v_row tongs.hammer_shorts_discoveries%rowtype;
begin
  select * into v_row from tongs.hammer_shorts_discoveries where id=p_discovery_id for update;
  if v_actor is null or v_row.id is null or not tongs.has_workspace_role(v_row.workspace_id,'editor') then
    raise exception 'hammer_shorts_editor_required' using errcode='42501';
  end if;
  if v_row.state='completed' then return to_jsonb(v_row); end if;
  update tongs.hammer_shorts_discoveries set state='failed',failure_code=left(coalesce(nullif(trim(p_failure_code),''),'provider_failed'),120),completed_at=now()
    where id=v_row.id returning * into v_row;
  return to_jsonb(v_row);
end $$;


ALTER FUNCTION "tongs"."fail_hammer_shorts_discovery"("p_discovery_id" "uuid", "p_failure_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."fail_hammer_video_render"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_attempt_id" "uuid", "p_failure_code" "text", "p_failure_message" "text", "p_outcome_unknown" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare op tongs.hammer_video_render_operations%rowtype; attempt_row record; next_state text:=case when p_outcome_unknown then'outcome_unknown'else'failed'end;
begin
  if auth.role()<>'service_role' then raise exception 'Hammer video render failure requires service authority' using errcode='42501'; end if;
  update tongs.hammer_video_render_attempts set state=next_state,failure_code=p_failure_code,failure_message=p_failure_message,updated_at=now()
  where attempt_id=p_attempt_id and operation_id=p_operation_id and state in('reserved','running') returning * into attempt_row;
  update tongs.hammer_video_render_operations set state=next_state,failure_code=p_failure_code,failure_message=p_failure_message,updated_at=now()
  where operation_id=p_operation_id and operation_fingerprint=p_operation_fingerprint and state='rendering' returning * into op;
  return jsonb_build_object('disposition',case when op.operation_id is null then'not_updated'else next_state end,'operation',to_jsonb(op));
end$$;


