CREATE OR REPLACE FUNCTION "tongs"."fail_reference_clip_acquisition"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_failed_stage" "text", "p_failure_code" "text", "p_failure_message" "text", "p_failure_evidence" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$declare op tongs.reference_clip_acquisition_operations%rowtype;begin select * into op from tongs.reference_clip_acquisition_operations where operation_id=p_operation_id for update;if not found then return jsonb_build_object('disposition','operation_not_found');end if;if not tongs.has_workspace_role(op.workspace_id,'editor') then raise exception 'workspace editor authority required' using errcode='42501';end if;if op.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict');end if;if op.state='candidate_committed' then return jsonb_build_object('disposition','terminal_operation','operation',to_jsonb(op));end if;update tongs.reference_clip_acquisition_operations set failed_stage=p_failed_stage,failure_code=p_failure_code,failure_message=p_failure_message,failure_evidence_json=p_failure_evidence,updated_at=now()where operation_id=p_operation_id returning * into op;return jsonb_build_object('disposition','failure_recorded','operation',to_jsonb(op));end$$;


