CREATE OR REPLACE FUNCTION "tongs"."fail_unified_visual_plan"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_failed_stage" "text", "p_failure_code" "text", "p_failure_message" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare op tongs.unified_visual_plan_operations%rowtype;
begin
  select * into op from tongs.unified_visual_plan_operations where operation_id=p_operation_id for update;
  if not found or op.operation_fingerprint<>p_operation_fingerprint then
    return jsonb_build_object('disposition','operation_identity_conflict');
  end if;
  if op.owner_cost_attempt_id is not null then perform tongs._require_accounting_service_role(); elsif not tongs.has_workspace_role(op.workspace_id,'editor') then
    raise exception 'workspace editor authority required' using errcode='42501';
  end if;
  if op.state='verified' then return op.receipt_json; end if;
  if op.state='failed' then
    if op.failed_stage is distinct from p_failed_stage
      or op.failure_code is distinct from p_failure_code
      or op.failure_message is distinct from p_failure_message then
      return jsonb_build_object('disposition','terminal_failure_conflict','operation',to_jsonb(op));
    end if;
    return jsonb_build_object('disposition','failed_replay','operation',to_jsonb(op));
  end if;
  update tongs.unified_visual_plan_operations
  set state='failed',failed_stage=p_failed_stage,failure_code=p_failure_code,
      failure_message=p_failure_message,updated_at=now()
  where operation_id=p_operation_id returning * into op;
  return jsonb_build_object('disposition','failed','operation',to_jsonb(op));
end $$;


ALTER FUNCTION "tongs"."fail_unified_visual_plan"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_failed_stage" "text", "p_failure_code" "text", "p_failure_message" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."finalize_brand_asset_revision"("p_workspace_id" "uuid", "p_revision_id" "uuid", "p_operation_id" "text", "p_content_hash" "text", "p_bytes" bigint, "p_width" integer DEFAULT NULL::integer, "p_height" integer DEFAULT NULL::integer, "p_duration_ms" bigint DEFAULT NULL::bigint, "p_has_audio" boolean DEFAULT NULL::boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $_$
declare v_row tongs.brand_asset_revisions%rowtype;
begin
  perform tongs.assert_workspace_role(p_workspace_id,'editor');
  select * into v_row from tongs.brand_asset_revisions where id=p_revision_id and workspace_id=p_workspace_id for update;
  if not found then raise exception 'asset revision not found' using errcode='P0002'; end if;
  if v_row.operation_id<>p_operation_id then raise exception 'operation identity mismatch' using errcode='22023'; end if;
  if v_row.state='ready' then
    if v_row.content_hash<>p_content_hash or v_row.bytes<>p_bytes then raise exception 'ready asset readback mismatch' using errcode='22023'; end if;
    return to_jsonb(v_row);
  end if;
  if p_content_hash!~'^[a-f0-9]{64}$' or p_bytes<=0 then raise exception 'verified hash and bytes are required' using errcode='22023'; end if;
  if v_row.role in ('video_intro','video_outro') and (p_width is null or p_height is null or p_duration_ms is null or p_has_audio is null) then
    raise exception 'canonical video inspection is required before finalization' using errcode='22023';
  end if;
  perform set_config('tongs.brand_controlled_transition','on',true);
  update tongs.brand_asset_revisions set state='ready',content_hash=p_content_hash,bytes=p_bytes,width=p_width,height=p_height,duration_ms=p_duration_ms,has_audio=p_has_audio,ready_at=now(),failure_message=null where id=p_revision_id;
  perform set_config('tongs.brand_controlled_transition','off',true);
  return (select to_jsonb(ar) from tongs.brand_asset_revisions ar where ar.id=p_revision_id);
end $_$;


ALTER FUNCTION "tongs"."finalize_brand_asset_revision"("p_workspace_id" "uuid", "p_revision_id" "uuid", "p_operation_id" "text", "p_content_hash" "text", "p_bytes" bigint, "p_width" integer, "p_height" integer, "p_duration_ms" bigint, "p_has_audio" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."finalize_hammer_recording_import"("p_import_id" "uuid", "p_verified_media_hash" "text", "p_verified_media_bytes" bigint, "p_verified_media_content_type" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare v_user uuid:=auth.uid(); v_import tongs.hammer_recording_import_requests%rowtype;
  v_duplicate tongs.hammer_recording_import_requests%rowtype; v_revision bigint; v_event_id bigint;
begin
  select * into v_import from tongs.hammer_recording_import_requests where id=p_import_id for update;
  if not found then return jsonb_build_object('outcome','not_found','import',null); end if;
  if v_user is null or not tongs.has_workspace_role(v_import.workspace_id,'editor') then return jsonb_build_object('outcome','denied','import',null); end if;
  if v_import.state='committed' then return jsonb_build_object('outcome','duplicate','import',to_jsonb(v_import)); end if;
  if lower(p_verified_media_hash)<>v_import.expected_media_hash or p_verified_media_bytes<>v_import.expected_media_bytes
     or lower(p_verified_media_content_type)<>lower(v_import.expected_media_content_type) then
    return jsonb_build_object('outcome','conflict','reason','storage_readback_mismatch','import',to_jsonb(v_import));
  end if;
  select * into v_duplicate from tongs.hammer_recording_import_requests
    where workspace_id=v_import.workspace_id and workpiece_id=v_import.workpiece_id
      and verified_media_hash=lower(p_verified_media_hash) and state='committed' limit 1;
  if found then return jsonb_build_object('outcome','duplicate','import',to_jsonb(v_duplicate)); end if;
  insert into tongs.workpiece_files(workpiece_id,path,file_type,content_type,bytes,hash_algo,hash_value,storage_bucket,storage_key,
    written_by_tool,written_by_tool_version,written_by_lane,revision)
  values(v_import.workpiece_id,v_import.media_path,'recording',lower(p_verified_media_content_type),p_verified_media_bytes,'sha256',
    lower(p_verified_media_hash),v_import.storage_bucket,v_import.storage_key,'hammer',v_import.hammer_version,'forge-managed',1)
  on conflict(workpiece_id,path) do update set content_type=excluded.content_type,bytes=excluded.bytes,hash_value=excluded.hash_value,
    storage_bucket=excluded.storage_bucket,storage_key=excluded.storage_key,written_by_tool=excluded.written_by_tool,
    written_by_tool_version=excluded.written_by_tool_version,written_by_lane=excluded.written_by_lane,
    revision=tongs.workpiece_files.revision+1,updated_at=now() returning revision into v_revision;
  perform set_config('tongs.recording_authority_rpc','on',true);
  insert into tongs.workpiece_events(workpiece_id,event_name,payload,correlation_id,written_by_tool,written_by_tool_version,written_by_lane)
  values(v_import.workpiece_id,'hammer.recording.imported.v1',jsonb_build_object('import_id',v_import.id,'workspace_id',v_import.workspace_id,
    'file_path',v_import.media_path,'media_hash',lower(p_verified_media_hash),'media_bytes',p_verified_media_bytes,
    'content_type',lower(p_verified_media_content_type),'provenance',v_import.provenance),v_import.operation_id::text,'hammer',v_import.hammer_version,'forge-managed')
  returning id into v_event_id;
  update tongs.hammer_recording_import_requests set state='committed',verified_media_hash=lower(p_verified_media_hash),
    verified_media_bytes=p_verified_media_bytes,verified_media_content_type=lower(p_verified_media_content_type),media_revision=v_revision,
    failure_stage=null,failure_code=null,failure_details=null,committed_at=now()
    where id=p_import_id returning * into v_import;
  return jsonb_build_object('outcome','committed','import',to_jsonb(v_import),'event_id',v_event_id);
end; $$;


ALTER FUNCTION "tongs"."finalize_hammer_recording_import"("p_import_id" "uuid", "p_verified_media_hash" "text", "p_verified_media_bytes" bigint, "p_verified_media_content_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."finalize_hammer_short_derivative"("p_derivative_id" "uuid", "p_artifact_authority" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $_$
declare
  v_actor uuid:=auth.uid(); v_short tongs.hammer_short_derivatives%rowtype; v_basis tongs.hammer_shorts_basis_locks%rowtype;
  v_path text; v_expected jsonb; v_file tongs.workpiece_files%rowtype; v_derivation uuid;
  v_required constant text[]:=array['transcript','timing_map','editor_session','visual_timeline','visual_placements','audio_polish','history'];
begin
  select * into v_short from tongs.hammer_short_derivatives where id=p_derivative_id for update;
  select * into v_basis from tongs.hammer_shorts_basis_locks where id=v_short.basis_lock_id;
  if v_actor is null or v_short.id is null or not tongs.has_workspace_role(v_short.workspace_id,'editor') then
    raise exception 'hammer_shorts_editor_required' using errcode='42501';
  end if;
  if v_short.state='ready' then return to_jsonb(v_short); end if;
  if jsonb_typeof(p_artifact_authority)<>'object' or not(p_artifact_authority ?& v_required) then
    raise exception 'hammer_short_artifact_authority_invalid' using errcode='22023';
  end if;
  foreach v_path in array v_required loop
    v_expected:=p_artifact_authority->v_path;
    if jsonb_typeof(v_expected)<>'object' or coalesce(v_expected->>'path','')='' or coalesce(v_expected->>'sha256','')!~'^[0-9a-f]{64}$' or coalesce((v_expected->>'bytes')::bigint,0)<=0 then
      raise exception 'hammer_short_artifact_authority_invalid' using errcode='22023';
    end if;
    select * into v_file from tongs.workpiece_files
      where workpiece_id=v_short.child_workpiece_id and path=v_expected->>'path';
    if v_file.workpiece_id is null or lower(v_file.hash_value)<>v_expected->>'sha256' or v_file.bytes<>(v_expected->>'bytes')::bigint then
      raise exception 'hammer_short_artifact_verification_failed' using errcode='40001';
    end if;
  end loop;
  update tongs.canonical_recordings set
    baseline_transcript_path=p_artifact_authority->'transcript'->>'path',
    baseline_timing_path=p_artifact_authority->'timing_map'->>'path',status='sealed',sealed_at=now(),updated_by=v_actor
    where id=v_short.child_canonical_recording_id;
  update tongs.recording_revisions set
    editor_session_path=p_artifact_authority->'editor_session'->>'path',revision_transcript_path=p_artifact_authority->'transcript'->>'path',
    audio_polish_path=p_artifact_authority->'audio_polish'->>'path',visual_timeline_path=p_artifact_authority->'visual_timeline'->>'path',
    visual_placements_path=p_artifact_authority->'visual_placements'->>'path',history_path=p_artifact_authority->'history'->>'path',updated_by=v_actor
    where id=v_short.child_recording_revision_id;
  update tongs.episodes set active_revision_id=v_short.child_recording_revision_id where id=v_short.child_workpiece_id;
  insert into tongs.workpiece_derivations(workspace_id,parent_workpiece_id,child_workpiece_id,derivative_kind,operation_id,operation_fingerprint,created_by)
  values(v_short.workspace_id,v_basis.parent_workpiece_id,v_short.child_workpiece_id,'short',v_short.operation_id,v_short.operation_fingerprint,v_actor)
  on conflict(operation_id) do nothing;
  select id into v_derivation from tongs.workpiece_derivations where operation_id=v_short.operation_id;
  update tongs.hammer_short_derivatives set derivation_id=v_derivation,state='ready',artifact_authority=p_artifact_authority,failure_code=null,finalized_at=now()
    where id=v_short.id returning * into v_short;
  return to_jsonb(v_short);
end $_$;


ALTER FUNCTION "tongs"."finalize_hammer_short_derivative"("p_derivative_id" "uuid", "p_artifact_authority" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."finalize_hearth_thumbnail_direction_generation_result"("p_operation_id" "text", "p_reservation_id" "uuid", "p_result_id" "uuid", "p_canonical_set_id" "uuid", "p_canonical_source_response_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $_$
declare
  result_row tongs.hearth_thumbnail_direction_generation_results%rowtype;
  receipt tongs.hearth_thumbnail_direction_canonical_receipts%rowtype;
begin
  perform tongs._require_pricing_service_role();
  perform pg_advisory_xact_lock(hashtextextended('hearth-thumbnail-direction-finalize:'||p_reservation_id::text,0));
  select * into result_row from tongs.hearth_thumbnail_direction_generation_results
  where id=p_result_id and operation_id=btrim(p_operation_id) and reservation_id=p_reservation_id;
  if result_row.id is null or p_canonical_set_id is null
    or coalesce(p_canonical_source_response_hash,'')!~'^[0-9a-f]{64}$'
  then raise exception 'invalid canonical Thumbnail Directions receipt' using errcode='22023'; end if;
  select * into receipt from tongs.hearth_thumbnail_direction_canonical_receipts where result_id=p_result_id;
  if found then
    if receipt.canonical_set_id<>p_canonical_set_id
      or receipt.canonical_source_response_hash<>p_canonical_source_response_hash
    then raise exception 'canonical Thumbnail Directions receipt replay conflict' using errcode='23505'; end if;
  else
    insert into tongs.hearth_thumbnail_direction_canonical_receipts(
      result_id,canonical_set_id,canonical_source_response_hash
    ) values(p_result_id,p_canonical_set_id,p_canonical_source_response_hash)
    returning * into receipt;
  end if;
  return result_row.result_json||jsonb_build_object('thumbnail_direction_result_id',result_row.id,
    'created_at',result_row.created_at,'provider_request_id',result_row.provider_request_id,
    'input_units',result_row.input_units,'output_units',result_row.output_units,'replay',true,
    'canonical_persisted',true,'canonical_set_id',receipt.canonical_set_id,
    'canonical_source_response_hash',receipt.canonical_source_response_hash,
    'canonical_committed_at',receipt.committed_at,
    'thumbnail_planning_subtree_hash',result_row.result_json#>>'{thumbnail_authority,planning_subtree_hash}',
    'expected_active_strategy_id',result_row.result_json#>'{thumbnail_authority,active_strategy_id}',
    'expected_active_concept_set_id',result_row.result_json#>'{thumbnail_authority,active_concept_set_id}');
end $_$;


ALTER FUNCTION "tongs"."finalize_hearth_thumbnail_direction_generation_result"("p_operation_id" "text", "p_reservation_id" "uuid", "p_result_id" "uuid", "p_canonical_set_id" "uuid", "p_canonical_source_response_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."finalize_owner_hearth_compatibility_batch"("p_authorization_id" "uuid", "p_operator_user_id" "uuid", "p_session_authorization_id" "uuid", "p_session_budget_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare authz tongs.owner_hearth_authorizations%rowtype; session_authz tongs.owner_hearth_authorizations%rowtype;
 latest tongs.owner_hearth_authorization_events%rowtype; passed bigint; event_id uuid;
 spec record; policy_id uuid; price_id uuid; catalog_id uuid:='89000000-0000-4000-8000-000000000003';
begin
 if coalesce(auth.role(),'')<>'service_role' or not tongs.is_platform_operator(p_operator_user_id) then raise exception 'service-role operator required' using errcode='42501'; end if;
 perform pg_advisory_xact_lock(hashtextextended('owner-hearth-finalize:'||p_authorization_id::text,0));
 select * into session_authz from tongs.owner_hearth_authorizations where id=p_session_authorization_id;
 if found then
  if session_authz.authorization_kind<>'creator_session' or session_authz.budget_id<>p_session_budget_id then
   raise exception 'owner Hearth session finalization replay conflict' using errcode='23505';
  end if;
  return jsonb_build_object('compatibility_authorization_id',p_authorization_id,'compatibility_state','closed',
   'session_authorization_id',session_authz.id,'session_state','dormant','session_budget_id',session_authz.budget_id,
   'maximum_amount_micros',session_authz.maximum_amount_micros,'customer_price_published',false,'replay',true);
 end if;
 select * into authz from tongs.owner_hearth_authorizations where id=p_authorization_id;
 select * into latest from tongs.owner_hearth_authorization_events where authorization_id=authz.id order by sequence desc limit 1;
 select count(*) into passed from tongs.owner_hearth_compatibility_results r join tongs.owner_hearth_operation_authorizations o on o.id=r.operation_authorization_id
  where o.authorization_id=authz.id and r.status='passed';
 if authz.authorization_kind<>'compatibility_batch' or latest.state<>'active' or passed<>5
   or exists(select 1 from tongs.owner_hearth_compatibility_results r join tongs.owner_hearth_operation_authorizations o on o.id=r.operation_authorization_id
      where o.authorization_id=authz.id and r.status<>'passed') then raise exception 'all five compatibility operations must pass' using errcode='P0001'; end if;
 insert into tongs.owner_hearth_authorization_events(id,authorization_id,sequence,event_key,state,reason,evidence_json)
 select gen_random_uuid(),authz.id,coalesce(max(sequence),0)+1,'owner-hearth-compat:'||authz.id::text||':closed','closed',p_reason,
  jsonb_build_object('passed_models',5,'customer_charge_micros',0)
 from tongs.owner_hearth_authorization_events where authorization_id=authz.id;
 event_id:=gen_random_uuid();
 perform tongs._create_accounting_event(event_id,'owner-hearth-session-budget:'||p_session_budget_id::text,'owner_operating_budget_created',
  'owner_internal','owner_operating_budget',p_session_budget_id::text,'USD',authz.owner_user_id,authz.workspace_id,p_operator_user_id,
  jsonb_build_object('maximum_amount_micros',10000000,'state','dormant','customer_revenue_micros',0,'reason',p_reason),now());
 insert into tongs.owner_operating_budgets(id,environment,workspace_id,provider,route,sku,currency,period_start,period_end,created_by,owner_testing_user_id)
 values(p_session_budget_id,'production',authz.workspace_id,'openai','hearth.chat_completion',null,'USD',now(),now()+interval '366 days',p_operator_user_id,authz.owner_user_id);
 insert into tongs.owner_operating_budget_revisions(budget_id,revision,status,maximum_amount_micros,reason,actor_id,journal_event_id)
 values(p_session_budget_id,1,'active',10000000,p_reason,p_operator_user_id,event_id);
 insert into tongs.owner_hearth_authorizations(id,authorization_kind,owner_user_id,workspace_id,budget_id,maximum_amount_micros,maximum_operations,
  maximum_concurrency,maximum_attempts,failure_loss_limit_micros,duration_seconds,created_by)
 values(p_session_authorization_id,'creator_session',authz.owner_user_id,authz.workspace_id,p_session_budget_id,10000000,20,2,1,2000000,86400,p_operator_user_id);
 insert into tongs.owner_hearth_authorization_events(id,authorization_id,sequence,event_key,state,reason,evidence_json)
 values(gen_random_uuid(),p_session_authorization_id,1,'owner-hearth-session:'||p_session_authorization_id::text||':dormant','dormant',p_reason,
  jsonb_build_object('starts_on_first_accepted_operation',true,'maximum_operations',20,'maximum_concurrency',2,'failure_loss_limit_micros',2000000,'automatic_renewal',false));

 insert into tongs.openai_text_model_catalog_revisions(id,revision,lifecycle_state,quality_method,source_checked_at,content_hash)
 values(catalog_id,3,'active','Five exact models passed coordinated Hearth Chat Completions generation, validation, and canonical persistence.',now(),
  encode(extensions.digest(convert_to('owner-hearth-catalog-v3:'||p_authorization_id::text,'utf8'),'sha256'),'hex'));
 for spec in select * from (values
  (1,'gpt-6-astra','GPT-6 Astra','81000000-0000-4000-8000-000000000011'::uuid,'60000000-0000-4000-8000-000000000002'::uuid,100),
  (2,'gpt-5.6-sol','GPT-5.6 Sol','81000000-0000-4000-8000-000000000012'::uuid,'56000000-0000-4000-8000-000000000012'::uuid,90),
  (3,'gpt-5.6-terra','GPT-5.6 Terra','81000000-0000-4000-8000-000000000013'::uuid,'56000000-0000-4000-8000-000000000022'::uuid,80),
  (4,'gpt-5.4-mini-2026-03-17','GPT-5.4 Mini','81000000-0000-4000-8000-000000000014'::uuid,'54000000-0000-4000-8000-000000000001'::uuid,70),
  (5,'gpt-5.6-luna','GPT-5.6 Luna','81000000-0000-4000-8000-000000000015'::uuid,'56000000-0000-4000-8000-000000000032'::uuid,60)
 ) v(ordinal,model_id,display_name,cost_id,rate_id,quality_rank)
 loop
  policy_id:=extensions.uuid_generate_v5(p_session_authorization_id,'pricing-policy:'||spec.model_id);
  price_id:=extensions.uuid_generate_v5(p_session_authorization_id,'pricing-revision:'||spec.model_id);
  insert into tongs.private_pricing_policies(id,policy_code,scope_kind,provider,sku,created_by)
  values(policy_id,'owner-hearth-session-'||spec.ordinal,'sku','openai','owner-hearth-session:'||spec.model_id,p_operator_user_id);
  insert into tongs.private_pricing_revisions(id,policy_id,revision,lifecycle_state,currency,markup_basis_points,full_cost_ceiling_micros,
   failure_cost_ceiling_micros,customer_price_ceiling_micros,billable_failure_ceiling_micros,customer_credit_units,billable_failure_classes,
   free_failure_classes,included_quantity,retention_policy,change_reason,content_hash,actor_id)
  select price_id,policy_id,1,'review_ready','USD',3300,c.full_cost_ceiling_micros,c.full_cost_ceiling_micros,
   ((c.full_cost_ceiling_micros*133+999999)/1000000)*10000,0,0,'[]'::jsonb,
   '["provider_failure","forge_failure","forge_validation_failure","persistence_failure","unknown_fault"]'::jsonb,
   jsonb_build_object('input_tokens',32000,'output_tokens',8000,'attempts',1),
   jsonb_build_object('first_30_days','included_in_operation','post_day_30','separate_owner_tail_authorization'),
   'Private owner session basis; customer pricing remains unpublished.',
   encode(extensions.digest(convert_to(p_session_authorization_id::text||':'||spec.model_id||':3300:'||c.full_cost_ceiling_micros::text,'utf8'),'sha256'),'hex'),p_operator_user_id
  from tongs.openai_text_cost_policy_revisions c where c.id=spec.cost_id;
  insert into tongs.owner_hearth_model_terms values(p_session_authorization_id,spec.ordinal,spec.model_id,spec.display_name,spec.cost_id,price_id,
    extensions.uuid_generate_v5('83000000-0000-4000-8000-000000000000'::uuid,'session:'||spec.model_id),
    (select full_cost_ceiling_micros+3 from tongs.openai_text_cost_policy_revisions where id=spec.cost_id));
  insert into tongs.openai_text_model_catalog_entries(id,catalog_revision_id,runtime_model_id,provider_model_id,display_name,tradeoff_summary,
   quality_rank,quality_basis,supported_apis,availability_status,availability_evidence,lifecycle_state,rate_revision_id)
  values(extensions.uuid_generate_v5(catalog_id,spec.model_id),catalog_id,spec.model_id,spec.model_id,spec.display_name,
   case spec.ordinal when 1 then 'Highest quality and highest cost.' when 2 then 'Strong professional reasoning.' when 3 then 'Balanced capability and price.' when 4 then 'Lower-cost bounded work.' else 'Fastest and lowest-cost option.' end,
   spec.quality_rank,'Coordinated owner compatibility batch','["chat_completions"]','generation_compatible',
   jsonb_build_object('compatibility_authorization_id',p_authorization_id,'generation_verified',true,'authoritative_cost_reconciliation',false),'active',spec.rate_id);
  insert into tongs.openai_text_model_route_compatibility(id,catalog_entry_id,route_code,compatibility_status,maximum_input_tokens,maximum_output_tokens,
   maximum_attempts,supporting_cost_coverage,cost_policy_revision_id,evidence_json)
  values(extensions.uuid_generate_v5(catalog_id,spec.model_id||':hearth.chat_completion'),extensions.uuid_generate_v5(catalog_id,spec.model_id),
   'hearth.chat_completion','generation_verified',32000,8000,1,'complete',spec.cost_id,
   jsonb_build_object('compatibility_authorization_id',p_authorization_id,'customer_price_published',false));
 end loop;
 return jsonb_build_object('compatibility_authorization_id',authz.id,'compatibility_state','closed','session_authorization_id',p_session_authorization_id,
  'session_state','dormant','session_budget_id',p_session_budget_id,'maximum_amount_micros',10000000,'customer_price_published',false,'replay',false);
end $$;


ALTER FUNCTION "tongs"."finalize_owner_hearth_compatibility_batch"("p_authorization_id" "uuid", "p_operator_user_id" "uuid", "p_session_authorization_id" "uuid", "p_session_budget_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."finalize_owner_hearth_thumbnail_direction_generation_result"("p_owner_cost_attempt_id" "uuid", "p_result_id" "uuid", "p_canonical_set_id" "uuid", "p_canonical_source_response_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $_$
declare
  v_result tongs.hearth_thumbnail_direction_generation_results%rowtype;
  v_attempt tongs.owner_cost_provider_attempts%rowtype;
  v_operation tongs.owner_cost_operations%rowtype;
  v_receipt tongs.hearth_thumbnail_direction_canonical_receipts%rowtype;
begin
  perform tongs._require_accounting_service_role();
  perform pg_advisory_xact_lock(hashtextextended('owner-thumbnail-direction-finalize:'||p_owner_cost_attempt_id::text,0));
  select * into v_result from tongs.hearth_thumbnail_direction_generation_results
    where id=p_result_id and owner_cost_attempt_id=p_owner_cost_attempt_id;
  select * into v_attempt from tongs.owner_cost_provider_attempts where attempt_id=p_owner_cost_attempt_id;
  select * into v_operation from tongs.owner_cost_operations where operation_id=v_attempt.operation_id;
  if v_result.id is null or v_operation.operation_key<>v_result.operation_id
    or v_operation.operation_type<>'hearth.thumbnail_direction_generation'
    or p_canonical_set_id is null
    or lower(coalesce(p_canonical_source_response_hash,'')) !~ '^[0-9a-f]{64}$'
  then raise exception 'invalid owner canonical Thumbnail Directions receipt' using errcode='22023'; end if;
  perform tongs._assert_owner_hearth_result_authority(
    p_owner_cost_attempt_id,'hearth.thumbnail_direction_generation',v_result.user_id,
    v_result.workspace_id,v_result.workpiece_id,v_result.request_fingerprint,
    v_operation.financial_environment,v_operation.runtime_environment,
    v_result.provider_request_id,v_attempt.model);
  select * into v_receipt from tongs.hearth_thumbnail_direction_canonical_receipts
    where result_id=p_result_id;
  if found then
    if v_receipt.canonical_set_id<>p_canonical_set_id
      or v_receipt.canonical_source_response_hash<>lower(p_canonical_source_response_hash)
    then raise exception 'owner canonical Thumbnail Directions receipt replay conflict' using errcode='23505'; end if;
  else
    insert into tongs.hearth_thumbnail_direction_canonical_receipts(
      result_id,canonical_set_id,canonical_source_response_hash
    ) values(p_result_id,p_canonical_set_id,lower(p_canonical_source_response_hash))
    returning * into v_receipt;
  end if;
  return v_result.result_json||jsonb_build_object(
    'thumbnail_direction_result_id',v_result.id,'created_at',v_result.created_at,
    'provider_request_id',v_result.provider_request_id,'input_units',v_result.input_units,
    'output_units',v_result.output_units,'replay',true,'canonical_persisted',true,
    'canonical_set_id',v_receipt.canonical_set_id,
    'canonical_source_response_hash',v_receipt.canonical_source_response_hash,
    'canonical_committed_at',v_receipt.committed_at,'authority','owner_cost_provider_attempt');
end $_$;


ALTER FUNCTION "tongs"."finalize_owner_hearth_thumbnail_direction_generation_result"("p_owner_cost_attempt_id" "uuid", "p_result_id" "uuid", "p_canonical_set_id" "uuid", "p_canonical_source_response_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."finalize_owner_timeline_image_generation_result"("p_owner_cost_attempt_id" "uuid", "p_operation_fingerprint" "text", "p_image_map_revision_id" "uuid", "p_asset_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_parent tongs.hearth_timeline_image_generation_results%rowtype;
  v_receipt tongs.hearth_timeline_image_generation_delivery_receipts%rowtype;
begin
  perform tongs._require_accounting_service_role();
  perform pg_advisory_xact_lock(hashtextextended(
    'owner-timeline-image-finalize:'||p_owner_cost_attempt_id::text,0));
  select * into v_parent from tongs.hearth_timeline_image_generation_results
    where owner_cost_attempt_id=p_owner_cost_attempt_id
      and request_fingerprint=lower(p_operation_fingerprint);
  if v_parent.id is null or cardinality(p_asset_ids)<>2
     or (select count(*) from tongs.hearth_timeline_image_generation_outputs output
          where output.result_id=v_parent.id and output.staged_asset_id=any(p_asset_ids))<>2
     or (select count(*) from tongs.assets asset
          where asset.id=any(p_asset_ids) and asset.status='ready'
            and asset.workspace_id=v_parent.workspace_id and asset.workpiece_id=v_parent.workpiece_id
            and asset.asset_kind='image_map_candidate_image'
            and asset.provider='openai'
            and asset.request_id=v_parent.operation_id
            and asset.provider_request_id is not distinct from v_parent.provider_request_id)<>2
     or not exists(
          select 1 from tongs.image_map_revisions revision
          where revision.id=p_image_map_revision_id
            and revision.workspace_id=v_parent.workspace_id
            and revision.workpiece_id=v_parent.workpiece_id) then
    raise exception 'owner Timeline Image canonical delivery is incomplete' using errcode='22023';
  end if;
  select * into v_receipt from tongs.hearth_timeline_image_generation_delivery_receipts
    where result_id=v_parent.id;
  if found then
    if v_receipt.image_map_revision_id<>p_image_map_revision_id
       or v_receipt.asset_ids<>p_asset_ids then
      raise exception 'owner Timeline Image finalization replay conflict' using errcode='23505';
    end if;
    return to_jsonb(v_receipt)||jsonb_build_object('replay',true,'authority','owner_cost_provider_attempt');
  end if;
  insert into tongs.hearth_timeline_image_generation_delivery_receipts(
    result_id,image_map_revision_id,asset_ids
  ) values(v_parent.id,p_image_map_revision_id,p_asset_ids) returning * into v_receipt;
  return to_jsonb(v_receipt)||jsonb_build_object('replay',false,'authority','owner_cost_provider_attempt');
end $$;


ALTER FUNCTION "tongs"."finalize_owner_timeline_image_generation_result"("p_owner_cost_attempt_id" "uuid", "p_operation_fingerprint" "text", "p_image_map_revision_id" "uuid", "p_asset_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."finalize_quench_destination_package"("p_operation_key" "uuid", "p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_executable_destination_id" "uuid", "p_manifest_snapshot_id" "uuid", "p_manifest_content_hash" "text", "p_metadata_revision" integer, "p_metadata_content_hash" "text", "p_destination_capability_revision_id" "uuid", "p_resolved_package" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs', 'extensions'
    AS $$
declare v_user uuid:=auth.uid(); v_existing tongs.quench_destination_package_revisions%rowtype;
  v_manifest tongs.quench_release_manifest_snapshots%rowtype; v_destination tongs.publishing_executable_destinations%rowtype;
  v_metadata tongs.workpiece_files%rowtype; v_cap tongs.publishing_destination_capability_revisions%rowtype; v_revision integer; v_hash text; v_id uuid;
begin
  if v_user is null or not tongs.has_workspace_role(p_workspace_id,'editor') then raise exception 'Not authorized' using errcode='42501'; end if;
  if jsonb_typeof(p_resolved_package)<>'object' or p_resolved_package->>'contract_version'<>'forge.finalized-destination-package.v1' then
    return jsonb_build_object('disposition','invalid','code','destination_package_invalid');
  end if;
  v_hash:=encode(digest(convert_to(p_resolved_package::text,'UTF8'),'sha256'),'hex');
  select * into v_existing from tongs.quench_destination_package_revisions where operation_key=p_operation_key;
  if found then
    if v_existing.package_content_hash=v_hash then return jsonb_build_object('disposition','replayed','finalized_package_id',v_existing.id,'revision',v_existing.revision,'package_content_hash',v_hash); end if;
    return jsonb_build_object('disposition','idempotency_conflict');
  end if;
  select * into v_manifest from tongs.quench_release_manifest_snapshots where id=p_manifest_snapshot_id and workspace_id=p_workspace_id and workpiece_id=p_workpiece_id;
  if not found or v_manifest.manifest_content_hash<>lower(p_manifest_content_hash) then return jsonb_build_object('disposition','blocked','code','manifest_mismatch'); end if;
  select * into v_metadata from tongs.workpiece_files where workpiece_id=p_workpiece_id and path='metadata.json';
  if not found or v_metadata.revision<>p_metadata_revision or lower(v_metadata.hash_value)<>lower(p_metadata_content_hash) then return jsonb_build_object('disposition','blocked','code','metadata_mismatch'); end if;
  select * into v_destination from tongs.publishing_executable_destinations where id=p_executable_destination_id and state='active';
  if not found or not tongs.publishing_destination_grant_is_active(p_workspace_id,p_executable_destination_id) then return jsonb_build_object('disposition','blocked','code','destination_unavailable'); end if;
  select * into v_cap from tongs.publishing_destination_capability_revisions where id=p_destination_capability_revision_id and executable_destination_id=p_executable_destination_id;
  if not found or v_destination.current_capability_revision_id<>v_cap.id then return jsonb_build_object('disposition','blocked','code','capability_changed'); end if;
  -- The complete snapshot must have resolved selections; inheritance is never accepted at finalization.
  if p_resolved_package ? 'inherits' or not (p_resolved_package ?& array['title','description','assets','mode','visibility','timezone']) then
    return jsonb_build_object('disposition','invalid','code','destination_package_unresolved');
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_workspace_id::text||p_workpiece_id::text||p_executable_destination_id::text,0));
  select coalesce(max(revision),0)+1 into v_revision from tongs.quench_destination_package_revisions where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and executable_destination_id=p_executable_destination_id;
  insert into tongs.quench_destination_package_revisions(workspace_id,workpiece_id,executable_destination_id,revision,state,contract_version,manifest_snapshot_id,manifest_content_hash,metadata_revision,metadata_content_hash,destination_capability_revision_id,destination_capability_content_hash,resolved_package,package_content_hash,operation_key,created_by)
  values(p_workspace_id,p_workpiece_id,p_executable_destination_id,v_revision,'finalized','forge.finalized-destination-package.v1',p_manifest_snapshot_id,lower(p_manifest_content_hash),p_metadata_revision,lower(p_metadata_content_hash),v_cap.id,v_cap.content_hash,p_resolved_package,v_hash,p_operation_key,v_user) returning id into v_id;
  return jsonb_build_object('disposition','finalized','finalized_package_id',v_id,'revision',v_revision,'package_content_hash',v_hash);
end; $$;


ALTER FUNCTION "tongs"."finalize_quench_destination_package"("p_operation_key" "uuid", "p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_executable_destination_id" "uuid", "p_manifest_snapshot_id" "uuid", "p_manifest_content_hash" "text", "p_metadata_revision" integer, "p_metadata_content_hash" "text", "p_destination_capability_revision_id" "uuid", "p_resolved_package" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."finalize_timeline_image_generation_result"("p_operation_id" "text", "p_request_fingerprint" "text", "p_image_map_revision_id" "uuid", "p_asset_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$ declare parent tongs.hearth_timeline_image_generation_results%rowtype; existing tongs.hearth_timeline_image_generation_delivery_receipts%rowtype;
begin perform tongs._require_pricing_service_role(); perform pg_advisory_xact_lock(hashtextextended('timeline-image-finalize:'||btrim(p_operation_id),0));
 select * into parent from tongs.hearth_timeline_image_generation_results where operation_id=btrim(p_operation_id) and request_fingerprint=lower(p_request_fingerprint);
 if parent.id is null or cardinality(p_asset_ids)<>2 or (select count(*) from tongs.hearth_timeline_image_generation_outputs where result_id=parent.id and staged_asset_id=any(p_asset_ids))<>2
  or (select count(*) from tongs.assets where id=any(p_asset_ids) and status='ready')<>2 then raise exception 'Timeline Image canonical delivery is incomplete' using errcode='22023'; end if;
 select * into existing from tongs.hearth_timeline_image_generation_delivery_receipts where result_id=parent.id;
 if found then return to_jsonb(existing)||jsonb_build_object('replay',true); end if;
 insert into tongs.hearth_timeline_image_generation_delivery_receipts(result_id,image_map_revision_id,asset_ids) values(parent.id,p_image_map_revision_id,p_asset_ids) returning * into existing;
 return to_jsonb(existing)||jsonb_build_object('replay',false); end $$;


ALTER FUNCTION "tongs"."finalize_timeline_image_generation_result"("p_operation_id" "text", "p_request_fingerprint" "text", "p_image_map_revision_id" "uuid", "p_asset_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."finalize_visual_narrative_interpretation_result"("p_operation_id" "text", "p_request_fingerprint" "text", "p_canonical_prompt_revision_id" "uuid", "p_canonical_content_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare result_row tongs.visual_narrative_interpretation_results%rowtype; revision_row tongs.image_map_prompt_revisions%rowtype;
  receipt tongs.visual_narrative_interpretation_canonical_receipts%rowtype;
begin
  perform tongs._require_pricing_service_role();
  perform pg_advisory_xact_lock(hashtextextended('visual-narrative-finalize:'||btrim(p_operation_id),0));
  select * into result_row from tongs.visual_narrative_interpretation_results
  where operation_id=btrim(p_operation_id) and request_fingerprint=lower(p_request_fingerprint);
  select * into revision_row from tongs.image_map_prompt_revisions where id=p_canonical_prompt_revision_id;
  if result_row.id is null or revision_row.id is null or revision_row.content_hash<>lower(p_canonical_content_hash)
    or revision_row.image_moment_id is distinct from (select image_moment_id from tongs.image_map_prompt_operation_receipts where operation_id=result_row.operation_id)
    or revision_row.image_map_revision_id<>result_row.image_map_revision_id or revision_row.script_approval_id<>result_row.script_approval_id
    or revision_row.validator_version<>'forge.image-prompt-validator.v2' or revision_row.prompt_source<>'ai_derived'
  then raise exception 'invalid canonical visual narrative receipt' using errcode='22023'; end if;
  select * into receipt from tongs.visual_narrative_interpretation_canonical_receipts where result_id=result_row.id;
  if found then
    if receipt.canonical_prompt_revision_id<>revision_row.id or receipt.canonical_content_hash<>revision_row.content_hash
    then raise exception 'visual narrative canonical replay conflict' using errcode='23505'; end if;
    return to_jsonb(receipt)||jsonb_build_object('replay',true);
  end if;
  insert into tongs.visual_narrative_interpretation_canonical_receipts(result_id,canonical_prompt_revision_id,canonical_content_hash)
  values(result_row.id,revision_row.id,revision_row.content_hash) returning * into receipt;
  return to_jsonb(receipt)||jsonb_build_object('replay',false);
end $$;


ALTER FUNCTION "tongs"."finalize_visual_narrative_interpretation_result"("p_operation_id" "text", "p_request_fingerprint" "text", "p_canonical_prompt_revision_id" "uuid", "p_canonical_content_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."finish_reference_review_operation_attempt"("p_attempt_id" "uuid", "p_outcome" "text", "p_failure_code" "text" DEFAULT NULL::"text", "p_failure_message" "text" DEFAULT NULL::"text", "p_canonical_receipt_json" "jsonb" DEFAULT NULL::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare v_current tongs.reference_review_operation_attempts%rowtype;v_updated tongs.reference_review_operation_attempts%rowtype;
begin
  if auth.role()<>'service_role' then raise exception 'Only Tongs service authority may finish a Reference review attempt' using errcode='42501';end if;
  select * into v_current from tongs.reference_review_operation_attempts where attempt_id=p_attempt_id for update;
  if not found then return jsonb_build_object('disposition','attempt_not_found');end if;
  if v_current.terminal_outcome is not null then return jsonb_build_object('disposition','terminal','attempt',to_jsonb(v_current));end if;
  if p_outcome not in ('succeeded','failed') then return jsonb_build_object('disposition','invalid_outcome');end if;
  if p_outcome='succeeded' and (p_canonical_receipt_json is null or p_canonical_receipt_json ?| array['asset','assets','evidence','sources','source_members','preview_url','image_url','video_url']) then return jsonb_build_object('disposition','invalid_canonical_receipt');end if;
  if p_outcome='failed' and (nullif(btrim(p_failure_code),'') is null or nullif(btrim(p_failure_message),'') is null) then return jsonb_build_object('disposition','failure_details_required');end if;
  update tongs.reference_review_operation_attempts set terminal_outcome=p_outcome,failure_code=case when p_outcome='failed' then btrim(p_failure_code) end,failure_message=case when p_outcome='failed' then btrim(p_failure_message) end,canonical_receipt_json=case when p_outcome='succeeded' then p_canonical_receipt_json end,completed_at=now() where attempt_id=p_attempt_id returning * into v_updated;
  return jsonb_build_object('disposition',p_outcome,'attempt',to_jsonb(v_updated));
end$$;


ALTER FUNCTION "tongs"."finish_reference_review_operation_attempt"("p_attempt_id" "uuid", "p_outcome" "text", "p_failure_code" "text", "p_failure_message" "text", "p_canonical_receipt_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."freeze_owner_hearth_research_synthesis_request"("p_reservation_id" "uuid", "p_operation_id" "text", "p_request_fingerprint" "text", "p_source_revision_fingerprint" "text", "p_model" "text", "p_instruction_revision" "text", "p_serialized_body" "text", "p_serialized_body_sha256" "text", "p_serialized_bytes" bigint, "p_tokenizer_revision" "text", "p_tokenizer_input_tokens" bigint, "p_protocol_overhead_tokens" bigint, "p_bounded_input_tokens" bigint, "p_maximum_output_tokens" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare o tongs.owner_hearth_research_operations%rowtype; f tongs.owner_hearth_research_frozen_requests%rowtype; computed text;
begin
 perform tongs._require_pricing_service_role(); select * into o from tongs.owner_hearth_research_operations where reservation_id=p_reservation_id;
 computed:=encode(extensions.digest(convert_to(p_serialized_body,'utf8'),'sha256'),'hex');
 select * into f from tongs.owner_hearth_research_frozen_requests where reservation_id=p_reservation_id;
 if found then return jsonb_build_object('authorized',f.serialized_body_sha256=p_serialized_body_sha256,'replay',true,'reason','existing_freeze'); end if;
 if o.id is null or o.operation_id<>btrim(p_operation_id) or o.request_fingerprint<>p_request_fingerprint or o.provider_model_id<>p_model
  or now()>=o.execution_deadline_at or p_instruction_revision<>'hearth-research-synthesis-v1' or computed<>p_serialized_body_sha256
  or octet_length(p_serialized_body)<>p_serialized_bytes or p_bounded_input_tokens<>greatest(p_tokenizer_input_tokens+p_protocol_overhead_tokens,p_serialized_bytes)
  or p_bounded_input_tokens>o.maximum_input_tokens or p_maximum_output_tokens<>o.maximum_output_tokens
  or exists(select 1 from tongs.owner_hearth_research_stage_events where reservation_id=p_reservation_id and event_type='submission_unknown') then
  return jsonb_build_object('authorized',false,'reason','frozen_request_outside_accepted_authority'); end if;
 insert into tongs.owner_hearth_research_frozen_requests values(p_reservation_id,btrim(p_operation_id),p_request_fingerprint,p_source_revision_fingerprint,p_model,
  p_instruction_revision,p_serialized_body,p_serialized_body_sha256,p_serialized_bytes,p_tokenizer_revision,p_tokenizer_input_tokens,p_protocol_overhead_tokens,
  p_bounded_input_tokens,p_maximum_output_tokens,1,now());
 return jsonb_build_object('authorized',true,'replay',false);
end $$;


ALTER FUNCTION "tongs"."freeze_owner_hearth_research_synthesis_request"("p_reservation_id" "uuid", "p_operation_id" "text", "p_request_fingerprint" "text", "p_source_revision_fingerprint" "text", "p_model" "text", "p_instruction_revision" "text", "p_serialized_body" "text", "p_serialized_body_sha256" "text", "p_serialized_bytes" bigint, "p_tokenizer_revision" "text", "p_tokenizer_input_tokens" bigint, "p_protocol_overhead_tokens" bigint, "p_bounded_input_tokens" bigint, "p_maximum_output_tokens" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."fulfill_reference_clip_opportunity"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_opportunity_id" "uuid", "p_expected_opportunity_revision_id" "uuid", "p_expected_opportunity_revision" bigint, "p_source_revision_id" "uuid", "p_workpiece_source_link_revision_id" "uuid", "p_operation_id" "text", "p_operation_fingerprint" "text", "p_actor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare seq tongs.reference_clip_plan_sequences%rowtype; membership tongs.reference_clip_plan_membership%rowtype; old tongs.reference_clip_opportunity_revisions%rowtype;
  src tongs.source_revisions%rowtype; lnk tongs.workpiece_source_link_revisions%rowtype; plan tongs.reference_clip_plan_revisions%rowtype; next_plan tongs.reference_clip_plan_revisions%rowtype;
  next_op tongs.reference_clip_opportunity_revisions%rowtype; r record; h text; ih text; result jsonb; prior jsonb;
begin
  if not tongs.has_workspace_role(p_workspace_id,'editor') then raise exception 'workspace editor authority required' using errcode='42501'; end if;
  select receipt_json into prior from tongs.reference_clip_operation_receipts where operation_id=p_operation_id and operation_fingerprint=p_operation_fingerprint;if found then return prior;end if;
  if exists(select 1 from tongs.reference_clip_operation_receipts where operation_id=p_operation_id) then return jsonb_build_object('disposition','operation_identity_conflict');end if;
  select * into seq from tongs.reference_clip_plan_sequences where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id for update;
  select * into membership from tongs.reference_clip_plan_membership where plan_revision_id=seq.current_plan_revision_id and opportunity_id=p_opportunity_id;
  if not found or membership.opportunity_revision_id is distinct from p_expected_opportunity_revision_id or membership.opportunity_revision<>p_expected_opportunity_revision then return jsonb_build_object('disposition','opportunity_revision_conflict'); end if;
  select * into old from tongs.reference_clip_opportunity_revisions where id=membership.opportunity_revision_id;
  if old.source_status<>'unresolved' then return jsonb_build_object('disposition','source_already_linked'); end if;
  select * into src from tongs.source_revisions where id=p_source_revision_id and workspace_id=p_workspace_id;
  select * into lnk from tongs.workpiece_source_link_revisions where id=p_workpiece_source_link_revision_id and workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and source_revision_id=src.id;
  if src.id is null or lnk.id is null then return jsonb_build_object('disposition','exact_source_and_link_required'); end if;
  select * into plan from tongs.reference_clip_plan_revisions where id=seq.current_plan_revision_id;
  h:=encode(extensions.digest(convert_to(jsonb_build_object('previous_plan',plan.content_hash,'fulfilled_opportunity',old.opportunity_id,'source_revision',src.id,'source_link_revision',lnk.id)::text,'UTF8'),'sha256'),'hex');
  ih:=encode(extensions.digest(convert_to(jsonb_build_object('hash',h,'revision',plan.revision+1,'previous',plan.id)::text,'UTF8'),'sha256'),'hex');
  insert into tongs.reference_clip_plan_revisions(workspace_id,workpiece_id,revision,previous_revision_id,previous_revision,script_approval_id,script_approval_revision,script_content_hash,contract_version,content_hash,immutable_revision_hash,created_by)
    values(p_workspace_id,p_workpiece_id,plan.revision+1,plan.id,plan.revision,plan.script_approval_id,plan.script_approval_revision,plan.script_content_hash,plan.contract_version,h,ih,p_actor_id) returning * into next_plan;
  h:=encode(extensions.digest(convert_to(jsonb_build_object('previous',old.content_hash,'source_revision',src.id,'source_link_revision',lnk.id)::text,'UTF8'),'sha256'),'hex');
  ih:=encode(extensions.digest(convert_to(jsonb_build_object('hash',h,'plan',next_plan.id,'opportunity',old.opportunity_id,'revision',old.revision+1)::text,'UTF8'),'sha256'),'hex');
  insert into tongs.reference_clip_opportunity_revisions(opportunity_id,workspace_id,workpiece_id,revision,previous_revision_id,previous_revision,source_plan_revision_id,source_plan_revision,script_approval_id,script_approval_revision,source_status,source_id,source_revision_id,source_revision,workpiece_source_link_id,workpiece_source_link_revision_id,workpiece_source_link_revision,context_before,context_focus,context_after,citation_anchor_json,media_range_json,narrative_purpose,editorial_reason,desired_material,search_terms,placement_hint,duration_target_ms,creator_direction,content_hash,immutable_revision_hash,created_by)
    values(old.opportunity_id,p_workspace_id,p_workpiece_id,old.revision+1,old.id,old.revision,next_plan.id,next_plan.revision,old.script_approval_id,old.script_approval_revision,'linked',src.source_id,src.id,src.revision,lnk.link_id,lnk.id,lnk.revision,old.context_before,old.context_focus,old.context_after,old.citation_anchor_json,lnk.media_range_json,old.narrative_purpose,old.editorial_reason,old.desired_material,old.search_terms,old.placement_hint,old.duration_target_ms,old.creator_direction,h,ih,p_actor_id) returning * into next_op;
  for r in select * from tongs.reference_clip_plan_membership where plan_revision_id=plan.id order by ordinal loop
    insert into tongs.reference_clip_plan_membership(plan_revision_id,workspace_id,workpiece_id,plan_revision,ordinal,opportunity_id,opportunity_revision_id,opportunity_revision)
    values(next_plan.id,p_workspace_id,p_workpiece_id,next_plan.revision,r.ordinal,r.opportunity_id,case when r.opportunity_id=old.opportunity_id then next_op.id else r.opportunity_revision_id end,case when r.opportunity_id=old.opportunity_id then next_op.revision else r.opportunity_revision end);
  end loop;
  update tongs.reference_clip_plan_sequences set current_plan_revision_id=next_plan.id,current_plan_revision=next_plan.revision,updated_at=now() where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id;
  result:=jsonb_build_object('disposition','committed','plan_revision',to_jsonb(next_plan),'opportunity_revision',to_jsonb(next_op));
  insert into tongs.reference_clip_operation_receipts(operation_id,operation_fingerprint,operation_type,workspace_id,workpiece_id,opportunity_id,state,result_plan_revision_id,receipt_json,created_by)
    values(p_operation_id,p_operation_fingerprint,'source_fulfillment',p_workspace_id,p_workpiece_id,p_opportunity_id,'committed',next_plan.id,result,p_actor_id);
  return result;
end$$;


ALTER FUNCTION "tongs"."fulfill_reference_clip_opportunity"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_opportunity_id" "uuid", "p_expected_opportunity_revision_id" "uuid", "p_expected_opportunity_revision" bigint, "p_source_revision_id" "uuid", "p_workpiece_source_link_revision_id" "uuid", "p_operation_id" "text", "p_operation_fingerprint" "text", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."fulfill_reference_visual_opportunity"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_opportunity_id" "uuid", "p_expected_opportunity_revision_id" "uuid", "p_expected_opportunity_revision" bigint, "p_source_revision_id" "uuid", "p_workpiece_source_link_revision_id" "uuid", "p_operation_id" "text", "p_operation_fingerprint" "text", "p_actor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
#variable_conflict use_column
declare
  op tongs.reference_visual_operation_receipts%rowtype;
  seq tongs.reference_visual_plan_sequences%rowtype;
  old_plan tongs.reference_visual_plan_revisions%rowtype;
  old_opp tongs.reference_visual_opportunity_revisions%rowtype;
  sr tongs.source_revisions%rowtype;
  lr tongs.workpiece_source_link_revisions%rowtype;
  new_plan tongs.reference_visual_plan_revisions%rowtype;
  new_opp tongs.reference_visual_opportunity_revisions%rowtype;
  m tongs.reference_visual_plan_membership%rowtype;
  h text;
  ih text;
  result jsonb;
begin
  if not tongs.has_workspace_role(p_workspace_id, 'editor') or auth.uid() is distinct from p_actor_id then
    raise exception 'workspace editor authority required' using errcode = '42501';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(p_operation_id, 0));
  select * into op from tongs.reference_visual_operation_receipts where operation_id = p_operation_id;
  if found then
    if op.operation_fingerprint <> p_operation_fingerprint then
      return jsonb_build_object('disposition', 'operation_identity_conflict');
    end if;
    return op.receipt_json;
  end if;

  select * into seq
  from tongs.reference_visual_plan_sequences
  where workspace_id = p_workspace_id and workpiece_id = p_workpiece_id
  for update;

  select o.* into old_opp
  from tongs.reference_visual_plan_membership m
  join tongs.reference_visual_opportunity_revisions o on o.id = m.opportunity_revision_id
  where m.plan_revision_id = seq.current_plan_revision_id and m.opportunity_id = p_opportunity_id;

  if not found
    or old_opp.id is distinct from p_expected_opportunity_revision_id
    or old_opp.revision <> p_expected_opportunity_revision then
    return jsonb_build_object('disposition', 'opportunity_revision_conflict');
  end if;
  if old_opp.source_status <> 'unresolved' then
    return jsonb_build_object('disposition', 'opportunity_already_linked');
  end if;

  select * into sr from tongs.source_revisions
  where id = p_source_revision_id and workspace_id = p_workspace_id;
  select * into lr from tongs.workpiece_source_link_revisions
  where id = p_workpiece_source_link_revision_id
    and workspace_id = p_workspace_id
    and workpiece_id = p_workpiece_id
    and source_revision_id = sr.id;
  if sr.id is null or lr.id is null then
    return jsonb_build_object('disposition', 'canonical_source_evidence_required');
  end if;

  select * into old_plan from tongs.reference_visual_plan_revisions where id = seq.current_plan_revision_id;
  h := encode(extensions.digest(convert_to(jsonb_build_object(
    'previous_plan', old_plan.content_hash,
    'fulfilled_opportunity', old_opp.id,
    'source_revision', sr.id,
    'source_link_revision', lr.id
  )::text, 'UTF8'), 'sha256'), 'hex');
  ih := encode(extensions.digest(convert_to(jsonb_build_object(
    'content_hash', h,
    'revision', old_plan.revision + 1,
    'previous_revision_id', old_plan.id
  )::text, 'UTF8'), 'sha256'), 'hex');

  insert into tongs.reference_visual_plan_revisions(
    workspace_id, workpiece_id, revision, previous_revision_id, previous_revision,
    script_approval_id, script_approval_revision, script_content_hash, contract_version,
    content_hash, immutable_revision_hash, created_by
  ) values (
    p_workspace_id, p_workpiece_id, old_plan.revision + 1, old_plan.id, old_plan.revision,
    old_plan.script_approval_id, old_plan.script_approval_revision, old_plan.script_content_hash,
    old_plan.contract_version, h, ih, p_actor_id
  ) returning * into new_plan;

  h := encode(extensions.digest(convert_to(jsonb_build_object(
    'previous', old_opp.content_hash,
    'source_revision', sr.id,
    'source_link_revision', lr.id
  )::text, 'UTF8'), 'sha256'), 'hex');
  ih := encode(extensions.digest(convert_to(jsonb_build_object(
    'content_hash', h,
    'revision', old_opp.revision + 1,
    'previous_revision_id', old_opp.id
  )::text, 'UTF8'), 'sha256'), 'hex');

  insert into tongs.reference_visual_opportunity_revisions(
    opportunity_id, workspace_id, workpiece_id, revision, previous_revision_id, previous_revision,
    source_plan_revision_id, source_plan_revision, script_approval_id, script_approval_revision,
    source_status, source_revision_id, source_revision, workpiece_source_link_revision_id,
    workpiece_source_link_revision, visual_subtype, context_before, context_focus, context_after,
    citation_anchor_json, document_locator_json, media_range_json, editorial_reason, desired_material,
    search_terms, placement_hint, duration_target_ms, creator_direction, content_hash,
    immutable_revision_hash, created_by
  )
  select
    opportunity_id, workspace_id, workpiece_id, revision + 1, id, revision,
    new_plan.id, new_plan.revision, script_approval_id, script_approval_revision,
    'linked', sr.id, sr.revision, lr.id, lr.revision, visual_subtype, context_before, context_focus,
    context_after, citation_anchor_json, document_locator_json, media_range_json, editorial_reason,
    desired_material, search_terms, placement_hint, duration_target_ms, creator_direction, h, ih, p_actor_id
  from tongs.reference_visual_opportunity_revisions
  where id = old_opp.id
  returning * into new_opp;

  for m in
    select * from tongs.reference_visual_plan_membership
    where plan_revision_id = old_plan.id
    order by ordinal
  loop
    insert into tongs.reference_visual_plan_membership values (
      new_plan.id, p_workspace_id, p_workpiece_id, new_plan.revision, m.ordinal, m.opportunity_id,
      case when m.opportunity_id = p_opportunity_id then new_opp.id else m.opportunity_revision_id end,
      case when m.opportunity_id = p_opportunity_id then new_opp.revision else m.opportunity_revision end
    );
  end loop;

  update tongs.reference_visual_plan_sequences
  set current_plan_revision_id = new_plan.id, current_plan_revision = new_plan.revision, updated_at = now()
  where workspace_id = p_workspace_id and workpiece_id = p_workpiece_id;

  result := jsonb_build_object(
    'disposition', 'committed',
    'plan_revision', to_jsonb(new_plan),
    'opportunity_revision', to_jsonb(new_opp)
  );
  insert into tongs.reference_visual_operation_receipts values (
    p_operation_id, p_operation_fingerprint, 'source_fulfillment', p_workspace_id, p_workpiece_id,
    'committed', new_opp.id, result, p_actor_id, now()
  );
  return result;
end
$$;


ALTER FUNCTION "tongs"."fulfill_reference_visual_opportunity"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_opportunity_id" "uuid", "p_expected_opportunity_revision_id" "uuid", "p_expected_opportunity_revision" bigint, "p_source_revision_id" "uuid", "p_workpiece_source_link_revision_id" "uuid", "p_operation_id" "text", "p_operation_fingerprint" "text", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."get_brand_asset_revision_for_inspection"("p_revision_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare v_row tongs.brand_asset_revisions%rowtype;
begin
  select * into v_row from tongs.brand_asset_revisions where id=p_revision_id;
  if not found then raise exception 'asset revision not found' using errcode='P0002'; end if;
  perform tongs.assert_workspace_role(v_row.workspace_id,'editor');
  return to_jsonb(v_row);
end $$;


ALTER FUNCTION "tongs"."get_brand_asset_revision_for_inspection"("p_revision_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."get_my_ai_credit_account"() RETURNS TABLE("settled_balance" bigint, "reserved_balance" bigint, "available_balance" bigint, "billing_mode" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_user_id uuid := auth.uid();
begin
  if v_user_id is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;
  insert into tongs.ai_credits (user_id) values (v_user_id) on conflict do nothing;
  return query
  select c.token_balance,
         tongs._ai_credit_active_holds(v_user_id),
         c.token_balance - tongs._ai_credit_active_holds(v_user_id),
         c.billing_mode
  from tongs.ai_credits c where c.user_id = v_user_id;
end;
$$;


ALTER FUNCTION "tongs"."get_my_ai_credit_account"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."get_my_ai_credits"() RETURNS TABLE("token_balance" bigint, "billing_mode" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'pg_temp'
    AS $$
declare
  v_user uuid := auth.uid();
begin
  insert into tongs.ai_credits (user_id, token_balance, billing_mode)
  values (v_user, 1500000, 'forge')
  on conflict (user_id) do nothing;

  return query
  select ac.token_balance, ac.billing_mode
  from tongs.ai_credits ac
  where ac.user_id = v_user;
end;
$$;


ALTER FUNCTION "tongs"."get_my_ai_credits"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."get_my_ai_key_status"("p_provider" "text" DEFAULT NULL::"text") RETURNS TABLE("provider" "text", "provider_account_id" "text", "key_label" "text", "key_version" integer, "validation_mode" "text", "status" "text", "connected" boolean, "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "last_validated_at" timestamp with time zone, "last_validation_status" "text", "last_used_at" timestamp with time zone)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
  select
    s.provider,
    s.provider_account_id,
    s.key_label,
    s.key_version,
    s.validation_mode,
    s.status,
    (s.status = 'active') as connected,
    s.created_at,
    s.updated_at,
    s.last_validated_at,
    s.last_validation_status,
    s.last_used_at
  from tongs.user_ai_keys_safe s
  where s.user_id = auth.uid()
    and (
      p_provider is null
      or s.provider = lower(btrim(p_provider))
    )
  order by s.updated_at desc;
$$;


ALTER FUNCTION "tongs"."get_my_ai_key_status"("p_provider" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."get_my_ai_spend_rollup"("p_days" integer DEFAULT 1, "p_lane" "text" DEFAULT 'forge'::"text") RETURNS TABLE("day" "date", "feature" "text", "subfeature" "text", "lane" "text", "call_count" bigint, "deduped_action_count" bigint, "total_actual_cost_usd" numeric, "total_billable_tokens" bigint)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
  with params as (
    select
      greatest(coalesce(p_days, 1), 1) as days_window,
      case when coalesce(p_lane, 'forge') = 'byo' then 'byo' else 'forge' end as lane_mode,
      auth.uid() as user_id
  ),
  base as (
    select
      e.id,
      e.created_at,
      e.feature,
      e.subfeature,
      e.lane,
      e.actual_cost_usd,
      e.billable_tokens,
      coalesce(nullif(btrim(e.action_id), ''), e.id::text) as action_rollup_key
    from tongs.ai_usage_events e
    cross join params p
    where e.user_id = p.user_id
      and e.lane = p.lane_mode
      and e.created_at >= (
        date_trunc('day', now())
        - make_interval(days => (p.days_window - 1))
      )
  ),
  call_agg as (
    select
      date_trunc('day', b.created_at)::date as day,
      b.feature,
      b.subfeature,
      b.lane,
      count(*)::bigint as call_count
    from base b
    group by
      date_trunc('day', b.created_at)::date,
      b.feature,
      b.subfeature,
      b.lane
  ),
  dedup as (
    select
      b.*,
      row_number() over (
        partition by b.action_rollup_key
        order by b.created_at desc, b.id desc
      ) as rn
    from base b
  ),
  dedup_agg as (
    select
      date_trunc('day', d.created_at)::date as day,
      d.feature,
      d.subfeature,
      d.lane,
      count(*)::bigint as deduped_action_count,
      coalesce(sum(d.actual_cost_usd), 0)::numeric as total_actual_cost_usd,
      coalesce(sum(d.billable_tokens), 0)::bigint as total_billable_tokens
    from dedup d
    where d.rn = 1
    group by
      date_trunc('day', d.created_at)::date,
      d.feature,
      d.subfeature,
      d.lane
  )
  select
    c.day,
    c.feature,
    c.subfeature,
    c.lane,
    c.call_count,
    coalesce(d.deduped_action_count, 0)::bigint as deduped_action_count,
    case
      when (select lane_mode from params) = 'byo' then coalesce(d.total_actual_cost_usd, 0)::numeric
      else null
    end as total_actual_cost_usd,
    coalesce(d.total_billable_tokens, 0)::bigint as total_billable_tokens
  from call_agg c
  left join dedup_agg d
    on d.day = c.day
    and d.feature is not distinct from c.feature
    and d.subfeature is not distinct from c.subfeature
    and d.lane is not distinct from c.lane
  order by c.day desc, total_actual_cost_usd desc, c.call_count desc;
$$;


ALTER FUNCTION "tongs"."get_my_ai_spend_rollup"("p_days" integer, "p_lane" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."get_my_ai_top_actions"("p_days" integer DEFAULT 7, "p_limit" integer DEFAULT 10, "p_lane" "text" DEFAULT 'forge'::"text") RETURNS TABLE("action_key" "text", "feature" "text", "subfeature" "text", "lane" "text", "call_count" bigint, "total_actual_cost_usd" numeric, "total_billable_tokens" bigint, "last_seen_at" timestamp with time zone)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
  with params as (
    select
      greatest(coalesce(p_days, 1), 1) as days_window,
      greatest(coalesce(p_limit, 10), 1) as row_limit,
      case when coalesce(p_lane, 'forge') = 'byo' then 'byo' else 'forge' end as lane_mode,
      auth.uid() as user_id
  ),
  base as (
    select
      e.id,
      e.created_at,
      e.feature,
      e.subfeature,
      e.lane,
      e.actual_cost_usd,
      e.billable_tokens,
      coalesce(nullif(btrim(e.action_id), ''), e.id::text) as action_rollup_key
    from tongs.ai_usage_events e
    cross join params p
    where e.user_id = p.user_id
      and e.lane = p.lane_mode
      and e.created_at >= (
        date_trunc('day', now())
        - make_interval(days => (p.days_window - 1))
      )
  ),
  action_calls as (
    select
      b.action_rollup_key,
      count(*)::bigint as call_count,
      max(b.created_at) as last_seen_at
    from base b
    group by b.action_rollup_key
  ),
  dedup as (
    select
      b.*,
      row_number() over (
        partition by b.action_rollup_key
        order by b.created_at desc, b.id desc
      ) as rn
    from base b
  ),
  ranked as (
    select
      d.action_rollup_key as action_key,
      d.feature,
      d.subfeature,
      d.lane,
      c.call_count,
      case
        when (select lane_mode from params) = 'byo' then coalesce(d.actual_cost_usd, 0)::numeric
        else null
      end as total_actual_cost_usd,
      coalesce(d.billable_tokens, 0)::bigint as total_billable_tokens,
      c.last_seen_at,
      row_number() over (
        order by
          case
            when (select lane_mode from params) = 'byo' then coalesce(d.actual_cost_usd, 0)
            else 0
          end desc,
          c.call_count desc,
          c.last_seen_at desc,
          d.action_rollup_key desc
      ) as global_rank
    from dedup d
    join action_calls c
      on c.action_rollup_key = d.action_rollup_key
    where d.rn = 1
  )
  select
    r.action_key,
    r.feature,
    r.subfeature,
    r.lane,
    r.call_count,
    r.total_actual_cost_usd,
    r.total_billable_tokens,
    r.last_seen_at
  from ranked r
  cross join params p
  where r.global_rank <= p.row_limit
  order by r.total_actual_cost_usd desc, r.call_count desc, r.last_seen_at desc
  ;
$$;


