CREATE OR REPLACE FUNCTION "tongs"."get_thumbnail_ledger_ingestion_cursor"("p_workspace_id" "uuid", "p_provider" "text", "p_publication_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare v_result jsonb;
begin perform tongs.assert_workspace_role(p_workspace_id,'viewer');
  select to_jsonb(x) into v_result from (select cursor_identity,cursor_json,status,last_success_at,last_error,recorded_at
    from tongs.thumbnail_ledger_ingestion_cursors where workspace_id=p_workspace_id and provider=p_provider and publication_id=p_publication_id
    order by recorded_at desc limit 1)x;
  return coalesce(v_result,'null'::jsonb);
end $$;


ALTER FUNCTION "tongs"."get_thumbnail_ledger_ingestion_cursor"("p_workspace_id" "uuid", "p_provider" "text", "p_publication_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."get_user_ai_key_for_resolution"("p_user_id" "uuid", "p_provider" "text", "p_provider_account_id" "text" DEFAULT NULL::"text") RETURNS TABLE("user_id" "uuid", "provider" "text", "provider_account_id" "text", "encrypted_api_key" "text", "key_version" integer, "validation_mode" "text", "status" "text", "last_validated_at" timestamp with time zone, "last_validation_status" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare
  v_provider text;
begin
  if auth.role() <> 'service_role' then
    raise exception 'Forbidden' using errcode = '42501';
  end if;

  if p_user_id is null then
    raise exception 'p_user_id required' using errcode = '22023';
  end if;

  v_provider := lower(btrim(coalesce(p_provider, '')));
  if v_provider = '' then
    raise exception 'p_provider required' using errcode = '22023';
  end if;

  update tongs.user_ai_keys
  set
    last_used_at = now(),
    updated_at = now()
  where user_id = p_user_id
    and provider = v_provider
    and provider_account_id is not distinct from nullif(btrim(coalesce(p_provider_account_id, '')), '')
    and status = 'active';

  return query
  select
    k.user_id,
    k.provider,
    k.provider_account_id,
    k.encrypted_api_key,
    k.key_version,
    k.validation_mode,
    k.status,
    k.last_validated_at,
    k.last_validation_status
  from tongs.user_ai_keys k
  where k.user_id = p_user_id
    and k.provider = v_provider
    and k.provider_account_id is not distinct from nullif(btrim(coalesce(p_provider_account_id, '')), '');
end;
$$;


ALTER FUNCTION "tongs"."get_user_ai_key_for_resolution"("p_user_id" "uuid", "p_provider" "text", "p_provider_account_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."get_workpiece_brand_binding"("p_workspace_id" "uuid", "p_workpiece_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare v_id uuid; begin perform tongs.assert_workspace_role(p_workspace_id,'viewer'); select id into v_id from tongs.workpiece_brand_bindings where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id order by revision desc limit 1; return case when v_id is null then null else tongs.brand_binding_json(v_id) end; end $$;


ALTER FUNCTION "tongs"."get_workpiece_brand_binding"("p_workspace_id" "uuid", "p_workpiece_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."get_workspace_invite_preview"("p_token" "text") RETURNS TABLE("workspace_id" "uuid", "workspace_name" "text", "role" "text", "email" "text", "expires_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare
  v_user uuid;
  v_user_email text;
  v_token text;
  v_invite tongs.workspace_invites%rowtype;
  v_workspace tongs.workspaces%rowtype;
begin
  v_user := auth.uid();
  if v_user is null then
    raise exception 'not_authenticated'
      using errcode = '42501';
  end if;

  v_token := btrim(coalesce(p_token, ''));
  if v_token = '' then
    raise exception 'invalid_token'
      using errcode = '22023';
  end if;

  select lower(coalesce(u.email, ''))
  into v_user_email
  from auth.users u
  where u.id = v_user;

  if v_user_email is null or v_user_email = '' then
    raise exception 'invite_user_email_missing'
      using errcode = '22023';
  end if;

  select wi.*
  into v_invite
  from tongs.workspace_invites wi
  where wi.token = v_token
  order by wi.created_at desc
  limit 1;

  if not found then
    raise exception 'invalid_token'
      using errcode = '22023';
  end if;

  if v_invite.revoked_at is not null then
    raise exception 'invite_revoked'
      using errcode = '22023';
  end if;

  if v_invite.accepted_at is not null then
    raise exception 'invite_already_accepted'
      using errcode = '22023';
  end if;

  if v_invite.expires_at <= now() then
    raise exception 'invite_expired'
      using errcode = '22023';
  end if;

  if v_invite.email <> v_user_email then
    raise exception 'invite_email_mismatch'
      using errcode = '42501';
  end if;

  select w.*
  into v_workspace
  from tongs.workspaces w
  where w.id = v_invite.workspace_id;

  if not found then
    raise exception 'workspace_not_found_for_invite'
      using errcode = 'P0002';
  end if;

  return query
  select
    v_invite.workspace_id,
    v_workspace.name,
    v_invite.role,
    v_invite.email,
    v_invite.expires_at;
end;
$$;


ALTER FUNCTION "tongs"."get_workspace_invite_preview"("p_token" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."get_workspace_publishing_destination_authorities"("p_workspace_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
  select case when not tongs.has_workspace_role(p_workspace_id,'viewer') then '[]'::jsonb else coalesce(jsonb_agg(jsonb_build_object(
    'workspace_id', p_workspace_id,
    'executable_destination_id', d.id,
    'provider_connection_id', c.id,
    'provider_account_id', a.id,
    'provider', d.provider,
    'destination_kind', d.destination_kind,
    'external_destination_id', d.external_destination_id,
    'display_label', d.display_label,
    'destination_state', d.state,
    'connection_state', c.state,
    'credential_authority_id', ca.id,
    'credential_state', ca.state,
    'capability_revision_id', cap.id,
    'capability_revision', cap.revision,
    'capability_content_hash', cap.content_hash,
    'capabilities', cap.capabilities_json,
    'grant_revision_id', g.id,
    'grant_revision', g.revision
  ) order by d.display_label), '[]'::jsonb) end
  from tongs.publishing_workspace_destination_grant_heads h
  join tongs.publishing_workspace_destination_grant_revisions g on g.id=h.current_grant_revision_id and g.state='active'
  join tongs.publishing_executable_destinations d on d.id=h.executable_destination_id
  join tongs.publishing_provider_accounts a on a.id=d.provider_account_id
  join tongs.publishing_provider_connections c on c.id=d.connection_id
  join tongs.publishing_provider_credential_authorities ca on ca.id=c.credential_authority_id and ca.state='available'
  join tongs.publishing_destination_capability_revisions cap on cap.id=d.current_capability_revision_id
  where h.workspace_id=p_workspace_id and d.state='active' and c.state='active';
$$;


ALTER FUNCTION "tongs"."get_workspace_publishing_destination_authorities"("p_workspace_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."grant_ai_credits"("p_user_id" "uuid", "p_pack_id" "text", "p_tokens" bigint, "p_event_id" "text", "p_session_id" "text", "p_amount_total" bigint DEFAULT NULL::bigint, "p_currency" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare
  v_pack_id text;
  v_event_id text;
  v_session_id text;
  v_currency text;
begin
  if p_user_id is null then
    raise exception 'p_user_id required'
      using errcode = '22023';
  end if;

  if p_tokens is null or p_tokens <= 0 then
    raise exception 'p_tokens must be > 0'
      using errcode = '22023';
  end if;

  v_pack_id := nullif(trim(coalesce(p_pack_id, '')), '');
  if v_pack_id is null then
    raise exception 'p_pack_id required'
      using errcode = '22023';
  end if;

  v_event_id := nullif(trim(coalesce(p_event_id, '')), '');
  if v_event_id is null then
    raise exception 'p_event_id required'
      using errcode = '22023';
  end if;

  v_session_id := nullif(trim(coalesce(p_session_id, '')), '');
  if v_session_id is null then
    raise exception 'p_session_id required'
      using errcode = '22023';
  end if;

  v_currency := nullif(lower(trim(coalesce(p_currency, ''))), '');

  insert into tongs.ai_credits (user_id)
  values (p_user_id)
  on conflict (user_id) do nothing;

  insert into tongs.ai_credit_purchases (
    stripe_event_id,
    stripe_session_id,
    user_id,
    pack_id,
    tokens_granted,
    amount_total,
    currency
  )
  values (
    v_event_id,
    v_session_id,
    p_user_id,
    v_pack_id,
    p_tokens,
    p_amount_total,
    v_currency
  )
  on conflict do nothing;

  -- Idempotent no-op on retries / replays.
  if not found then
    return;
  end if;

  update tongs.ai_credits c
  set
    token_balance = c.token_balance + p_tokens,
    updated_at = now()
  where c.user_id = p_user_id;
end;
$$;


ALTER FUNCTION "tongs"."grant_ai_credits"("p_user_id" "uuid", "p_pack_id" "text", "p_tokens" bigint, "p_event_id" "text", "p_session_id" "text", "p_amount_total" bigint, "p_currency" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."grant_legacy_plan_entitlement_compatibility"("p_compatibility_grant_id" "uuid", "p_receipt_id" "uuid", "p_granted_at" timestamp with time zone, "p_metadata_json" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_receipt tongs.subscription_cycle_receipts%rowtype;
  v_existing tongs.legacy_plan_entitlement_compatibility_grants%rowtype;
  v_plan_grant tongs.plan_credit_grants%rowtype;
  v_credits bigint;
  v_adopted_existing boolean := false;
  v_opening_captured boolean := false;
  v_record_units boolean := false;
  v_payload jsonb;
begin
  perform tongs._require_accounting_service_role();
  if p_compatibility_grant_id is null or p_receipt_id is null
     or jsonb_typeof(coalesce(p_metadata_json, '{}'::jsonb)) <> 'object' then
    raise exception 'invalid legacy plan entitlement compatibility grant' using errcode = '22023';
  end if;

  select * into v_receipt
  from tongs.subscription_cycle_receipts
  where id = p_receipt_id
  for update;
  if not found then
    raise exception 'subscription cycle receipt not found' using errcode = 'P0002';
  end if;
  if v_receipt.stripe_mode <> 'live' or v_receipt.purchase_type <> 'subscription' then
    raise exception 'only live subscription receipts can preserve legacy plan entitlements'
      using errcode = '42501';
  end if;

  select * into v_existing
  from tongs.legacy_plan_entitlement_compatibility_grants
  where receipt_id = p_receipt_id;
  if found then
    return jsonb_build_object(
      'compatibility_grant_id', v_existing.id,
      'receipt_id', v_existing.receipt_id,
      'entitlement_units', v_existing.entitlement_units,
      'adopted_existing', v_existing.adopted_existing,
      'eligible_for_shared_spending_gate', false,
      'replay', true
    );
  end if;

  v_credits := tongs.plan_included_ai_credits(v_receipt.plan_item_id);
  if v_credits <= 0 then
    raise exception 'subscription plan has no configured legacy entitlement: %', v_receipt.plan_item_id
      using errcode = 'P0001';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    'legacy-plan-cycle:' || v_receipt.stripe_subscription_id || ':' ||
    v_receipt.plan_item_id || ':' || v_receipt.period_start::text,
    0
  ));

  select * into v_plan_grant
  from tongs.plan_credit_grants
  where stripe_subscription_id = v_receipt.stripe_subscription_id
    and plan_item_id = v_receipt.plan_item_id
    and period_start = v_receipt.period_start;

  if found then
    if v_plan_grant.user_id <> v_receipt.user_id
       or v_plan_grant.credits_granted <> v_credits then
      raise exception 'existing plan entitlement conflicts with paid receipt' using errcode = '23505';
    end if;
    v_adopted_existing := true;
    select exists(
      select 1
      from tongs.legacy_credit_opening_balances opening
      where opening.user_id = v_receipt.user_id
        and opening.captured_at >= v_plan_grant.created_at
    ) into v_opening_captured;
    v_record_units := not v_opening_captured and not exists(
      select 1
      from tongs.legacy_plan_entitlement_compatibility_grants prior
      where prior.plan_credit_grant_id = v_plan_grant.id
    );
  else
    insert into tongs.ai_credits(user_id)
    values (v_receipt.user_id)
    on conflict (user_id) do nothing;

    insert into tongs.plan_credit_grants(
      user_id, stripe_subscription_id, plan_item_id, period_start, period_end,
      credits_granted, source_event_id
    ) values (
      v_receipt.user_id, v_receipt.stripe_subscription_id, v_receipt.plan_item_id,
      v_receipt.period_start, v_receipt.period_end, v_credits, v_receipt.stripe_event_id
    ) returning * into v_plan_grant;

    update tongs.ai_credits
    set token_balance = token_balance + v_credits,
        updated_at = now()
    where user_id = v_receipt.user_id;
    v_record_units := true;
  end if;

  v_payload := jsonb_build_object(
    'compatibility_grant_id', p_compatibility_grant_id,
    'receipt_id', p_receipt_id,
    'plan_credit_grant_id', v_plan_grant.id,
    'user_id', v_receipt.user_id,
    'entitlement_units', v_credits,
    'adopted_existing', v_adopted_existing,
    'opening_balance_already_captured', v_opening_captured,
    'eligible_for_shared_spending_gate', false,
    'metadata', coalesce(p_metadata_json, '{}'::jsonb)
  );
  perform tongs._create_accounting_event(
    p_compatibility_grant_id,
    'legacy-plan-entitlement:' || p_receipt_id::text,
    'legacy_plan_entitlement_preserved',
    'legacy_unverified',
    'subscription_cycle_receipt',
    p_receipt_id::text,
    null,
    v_receipt.user_id,
    null,
    null,
    v_payload,
    coalesce(p_granted_at, now())
  );

  insert into tongs.legacy_plan_entitlement_compatibility_grants(
    id, receipt_id, plan_credit_grant_id, user_id, entitlement_units,
    adopted_existing, opening_balance_already_captured,
    eligible_for_shared_spending_gate, journal_event_id, metadata_json, granted_at
  ) values (
    p_compatibility_grant_id, p_receipt_id, v_plan_grant.id, v_receipt.user_id, v_credits,
    v_adopted_existing, v_opening_captured, false, p_compatibility_grant_id,
    coalesce(p_metadata_json, '{}'::jsonb), coalesce(p_granted_at, now())
  );

  if v_record_units then
    insert into tongs.accounting_journal_entries(
      event_id, line_number, account_code, user_id, unit_kind, quantity_delta, metadata_json
    ) values (
      p_compatibility_grant_id, 1, 'legacy_unverified_credits', v_receipt.user_id,
      'forge_credit', v_credits,
      jsonb_build_object('compatibility_only', true, 'eligible_for_shared_spending_gate', false)
    );
  end if;

  return jsonb_build_object(
    'compatibility_grant_id', p_compatibility_grant_id,
    'receipt_id', p_receipt_id,
    'entitlement_units', v_credits,
    'adopted_existing', v_adopted_existing,
    'opening_balance_already_captured', v_opening_captured,
    'eligible_for_shared_spending_gate', false,
    'replay', false
  );
end;
$$;


ALTER FUNCTION "tongs"."grant_legacy_plan_entitlement_compatibility"("p_compatibility_grant_id" "uuid", "p_receipt_id" "uuid", "p_granted_at" timestamp with time zone, "p_metadata_json" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."grant_legacy_plan_entitlement_compatibility"("p_compatibility_grant_id" "uuid", "p_receipt_id" "uuid", "p_granted_at" timestamp with time zone, "p_metadata_json" "jsonb") IS 'Separately preserves an existing live plan entitlement after cash receipt. Does not allocate revenue, create a paid allowance, or enable spending.';



CREATE OR REPLACE FUNCTION "tongs"."grant_plan_cycle_ai_credits"("p_user_id" "uuid", "p_stripe_subscription_id" "text", "p_plan_item_id" "text", "p_period_start" timestamp with time zone, "p_period_end" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_source_event_id" "text" DEFAULT NULL::"text") RETURNS bigint
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_receipt tongs.subscription_cycle_receipts%rowtype;
  v_result jsonb;
begin
  perform tongs._require_accounting_service_role();
  select * into v_receipt
  from tongs.subscription_cycle_receipts receipt
  where receipt.stripe_mode = 'live'
    and receipt.stripe_event_id = nullif(btrim(coalesce(p_source_event_id, '')), '')
  for update;
  if not found then
    raise exception 'recorded live subscription receipt required before entitlement grant'
      using errcode = '42501';
  end if;
  if v_receipt.user_id <> p_user_id
     or v_receipt.stripe_subscription_id <> nullif(btrim(coalesce(p_stripe_subscription_id, '')), '')
     or v_receipt.plan_item_id <> nullif(lower(btrim(coalesce(p_plan_item_id, ''))), '')
     or v_receipt.period_start <> p_period_start
     or (p_period_end is not null and v_receipt.period_end <> p_period_end) then
    raise exception 'legacy entitlement request conflicts with recorded receipt' using errcode = '23505';
  end if;
  v_result := tongs.grant_legacy_plan_entitlement_compatibility(
    gen_random_uuid(), v_receipt.id, v_receipt.received_at,
    jsonb_build_object('source', 'legacy_rpc_wrapper', 'source_event_id', p_source_event_id)
  );
  if (v_result->>'replay')::boolean then return 0; end if;
  return (v_result->>'entitlement_units')::bigint;
end;
$$;


ALTER FUNCTION "tongs"."grant_plan_cycle_ai_credits"("p_user_id" "uuid", "p_stripe_subscription_id" "text", "p_plan_item_id" "text", "p_period_start" timestamp with time zone, "p_period_end" timestamp with time zone, "p_source_event_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."grant_subscription_allowance_from_receipt"("p_receipt_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare v_receipt tongs.subscription_cycle_receipts%rowtype; v_term tongs.customer_subscription_allowance_terms%rowtype;
  v_existing tongs.paid_allowance_grants%rowtype; v_result jsonb;
begin
  perform tongs._require_accounting_service_role();
  if p_receipt_id is null then raise exception 'receipt required' using errcode='22023'; end if;
  perform pg_advisory_xact_lock(hashtextextended('subscription-allowance:'||p_receipt_id::text,0));
  select * into v_receipt from tongs.subscription_cycle_receipts where id=p_receipt_id for update;
  if not found then raise exception 'subscription cycle receipt not found' using errcode='P0002'; end if;
  if v_receipt.stripe_mode<>tongs._current_financial_environment() then
    return jsonb_build_object('eligible',false,'reason','inactive_financial_environment','receipt_id',p_receipt_id);
  end if;
  select * into v_term from tongs.customer_subscription_allowance_terms
  where financial_environment=v_receipt.stripe_mode and plan_item_id=v_receipt.plan_item_id
    and interval=coalesce(v_receipt.metadata_json->>'forge_interval','') and lifecycle_state='active'
    and effective_from<=v_receipt.period_start order by effective_from desc limit 1;
  if not found or v_receipt.purchase_type<>'subscription' then
    return jsonb_build_object('eligible',false,'reason','no_active_allowance_term','receipt_id',p_receipt_id);
  end if;
  if exists(select 1 from tongs.subscription_cycle_adjustments where receipt_id=p_receipt_id) then
    return jsonb_build_object('eligible',false,'reason','adjusted_receipt','receipt_id',p_receipt_id);
  end if;
  if v_receipt.gross_amount_micros<v_term.allocated_revenue_micros then
    raise exception 'subscription receipt cannot back configured allowance' using errcode='P0001';
  end if;
  select * into v_existing from tongs.paid_allowance_grants
  where receipt_id=p_receipt_id and allocation_policy_revision=v_term.policy_revision;
  if found then return jsonb_build_object('eligible',true,'grant_id',v_existing.id,'replay',true); end if;
  v_result:=tongs.create_paid_allowance_grant(gen_random_uuid(),p_receipt_id,v_term.entitlement_units,
    v_term.allocated_revenue_micros,v_term.maximum_wholesale_spend_micros,v_term.policy_revision,
    greatest(v_receipt.received_at,v_receipt.period_start),jsonb_build_object('source','versioned_subscription_allowance_term','term_id',v_term.id));
  return v_result||jsonb_build_object('eligible',true,'term_id',v_term.id);
end $$;


ALTER FUNCTION "tongs"."grant_subscription_allowance_from_receipt"("p_receipt_id" "uuid") OWNER TO "postgres";


