CREATE OR REPLACE FUNCTION "tongs"."hearth_preflight_finding_basis_hash"("p_finding" "jsonb") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    SET "search_path" TO 'pg_catalog', 'tongs', 'extensions'
    AS $$
  select encode(
    extensions.digest(
      convert_to(
        lower(btrim(coalesce(p_finding->>'code',''))) || chr(31) ||
        lower(btrim(coalesce(p_finding->>'category',''))) || chr(31) ||
        regexp_replace(
          lower(btrim(coalesce(nullif(p_finding->>'excerpt',''),p_finding->>'message',''))),
          '[[:space:]]+',
          ' ',
          'g'
        ),
        'UTF8'
      ),
      'sha256'
    ),
    'hex'
  );
$$;


