CREATE OR REPLACE FUNCTION "tongs"."hearth_research_artifact_json_is_bounded"("p_artifact" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare v_source jsonb;v_evidence jsonb;
begin
  if octet_length(p_artifact::text)>524288
    or jsonb_typeof(p_artifact#>'{result,sources}') is distinct from 'array'
    or jsonb_typeof(coalesce(p_artifact#>'{result,evidence}','[]'::jsonb))<>'array'
    or jsonb_typeof(coalesce(p_artifact#>'{result,creatorClaims}','[]'::jsonb))<>'array'
    or jsonb_typeof(coalesce(p_artifact#>'{result,artifact,findings}','[]'::jsonb))<>'array'
    or jsonb_array_length(p_artifact#>'{result,sources}')>48
    or jsonb_array_length(coalesce(p_artifact#>'{result,evidence}','[]'::jsonb))>96
    or jsonb_array_length(coalesce(p_artifact#>'{result,creatorClaims}','[]'::jsonb))>96
    or jsonb_array_length(coalesce(p_artifact#>'{result,artifact,findings}','[]'::jsonb))>96 then return false;
  end if;
  for v_source in select value from jsonb_array_elements(p_artifact#>'{result,sources}') loop
    if length(coalesce(v_source->>'extractedText',''))>0 or length(coalesce(v_source->>'transcript',''))>0
      or (v_source->'transcriptSegments' is not null and v_source->'transcriptSegments'<>'null'::jsonb)
      or length(coalesce(v_source->>'snippet',''))>4096 then return false;end if;
  end loop;
  for v_evidence in select value from jsonb_array_elements(coalesce(p_artifact#>'{result,evidence}','[]'::jsonb)) loop
    if length(coalesce(v_evidence->>'excerpt',''))>8192 then return false;end if;
  end loop;
  return true;
exception when others then return false;
end;$$;


ALTER FUNCTION "tongs"."hearth_research_artifact_json_is_bounded"("p_artifact" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."hearth_transition_approved_script_ready"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_script_approval_id" "uuid", "p_idempotency_key" "text", "p_publish_evidence" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare
  v_user uuid:=auth.uid(); v_key text:=btrim(coalesce(p_idempotency_key,''));
  v_approval tongs.script_approval_revisions%rowtype;
  v_existing tongs.workpiece_ready_transition_requests%rowtype;
  v_transition tongs.workpiece_ready_transition_requests%rowtype;
  v_ready tongs.workpiece_ready_script_meta%rowtype; v_fingerprint text;
begin
  if v_user is null or not tongs.has_workspace_role(p_workspace_id,'editor') then
    return jsonb_build_object('outcome','denied','reason','editor_required','ready',null);
  end if;
  if length(v_key) not between 8 and 200 or jsonb_typeof(p_publish_evidence)<>'object' then
    return jsonb_build_object('outcome','conflict','reason','invalid_publish_evidence','ready',null);
  end if;
  select * into v_approval from tongs.script_approval_revisions
    where id=p_script_approval_id and workspace_id=p_workspace_id and workpiece_id=p_workpiece_id;
  if not found then return jsonb_build_object('outcome','not_found','reason','approval_not_found','ready',null); end if;
  if p_publish_evidence->>'transition' is distinct from 'hearth.approved-script.ready.v2'
    or p_publish_evidence->>'script_approval_id' is distinct from v_approval.id::text
    or lower(coalesce(p_publish_evidence->>'script_approval_hash','')) is distinct from v_approval.script_content_hash then
    return jsonb_build_object('outcome','conflict','reason','approval_evidence_mismatch','ready',null);
  end if;
  v_fingerprint:=md5(concat_ws(chr(31),p_workspace_id::text,p_workpiece_id::text,v_approval.id::text,v_approval.approval_revision::text,v_approval.script_content_hash,p_publish_evidence::text));
  select * into v_existing from tongs.workpiece_ready_transition_requests where workspace_id=p_workspace_id and idempotency_key=v_key;
  if found then
    if v_existing.request_fingerprint<>v_fingerprint then return jsonb_build_object('outcome','conflict','reason','idempotency_reuse','ready',null); end if;
    select * into v_ready from tongs.workpiece_ready_script_meta where transition_id=v_existing.id;
    return jsonb_build_object('outcome','duplicate','reason',null,'ready',to_jsonb(v_ready));
  end if;
  insert into tongs.workpiece_ready_transition_requests(workspace_id,workpiece_id,script_path,script_revision,script_hash,
    script_approval_id,script_approval_revision,script_approval_hash,idempotency_key,request_fingerprint,publish_evidence,transitioned_by)
  values(p_workspace_id,p_workpiece_id,v_approval.source_file_path,v_approval.source_file_revision,v_approval.script_content_hash,
    v_approval.id,v_approval.approval_revision,v_approval.script_content_hash,v_key,v_fingerprint,p_publish_evidence,v_user)
  returning * into v_transition;
  insert into tongs.workpiece_ready_script_meta(workspace_id,workpiece_id,script_path,marked_ready_by,marked_ready_at,updated_by,
    script_revision,script_hash,script_approval_id,script_approval_revision,script_approval_hash,transition_id,publish_evidence)
  values(p_workspace_id,p_workpiece_id,v_approval.source_file_path,v_user,now(),v_user,v_approval.source_file_revision,v_approval.script_content_hash,
    v_approval.id,v_approval.approval_revision,v_approval.script_content_hash,v_transition.id,p_publish_evidence)
  on conflict(workpiece_id,script_path) do update set workspace_id=excluded.workspace_id,marked_ready_by=excluded.marked_ready_by,
    marked_ready_at=excluded.marked_ready_at,updated_by=excluded.updated_by,script_revision=excluded.script_revision,script_hash=excluded.script_hash,
    script_approval_id=excluded.script_approval_id,script_approval_revision=excluded.script_approval_revision,
    script_approval_hash=excluded.script_approval_hash,transition_id=excluded.transition_id,publish_evidence=excluded.publish_evidence
  returning * into v_ready;
  return jsonb_build_object('outcome','saved','reason',null,'ready',to_jsonb(v_ready));
end;
$$;


ALTER FUNCTION "tongs"."hearth_transition_approved_script_ready"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_script_approval_id" "uuid", "p_idempotency_key" "text", "p_publish_evidence" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."hearth_transition_approved_script_ready_v4"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_script_approval_id" "uuid", "p_idempotency_key" "text", "p_publish_evidence" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare
  v_user uuid:=auth.uid();
  v_key text:=btrim(coalesce(p_idempotency_key,''));
  v_approval tongs.script_approval_revisions%rowtype;
  v_file tongs.workpiece_files%rowtype;
  v_existing tongs.workpiece_ready_transition_requests%rowtype;
  v_transition tongs.workpiece_ready_transition_requests%rowtype;
  v_ready tongs.workpiece_ready_script_meta%rowtype;
  v_fingerprint text;
begin
  if v_user is null or not tongs.has_workspace_role(p_workspace_id,'editor') then
    return jsonb_build_object('outcome','denied','reason','editor_required','ready',null);
  end if;
  if length(v_key) not between 8 and 200 or jsonb_typeof(p_publish_evidence)<>'object' then
    return jsonb_build_object('outcome','conflict','reason','invalid_publish_evidence','ready',null);
  end if;
  select a.* into v_approval
  from tongs.script_approval_revisions a
  join tongs.workpiece_script_approval_sequences s
    on s.workspace_id=a.workspace_id
    and s.workpiece_id=a.workpiece_id
    and s.current_approval_id=a.id
    and s.current_revision=a.approval_revision
  where a.id=p_script_approval_id
    and a.workspace_id=p_workspace_id
    and a.workpiece_id=p_workpiece_id;
  if not found then
    return jsonb_build_object('outcome','not_found','reason','current_approval_not_found','ready',null);
  end if;
  select * into v_file
  from tongs.workpiece_files
  where workpiece_id=p_workpiece_id and path=v_approval.source_file_path
  for share;
  if not found
    or v_file.revision<>v_approval.source_file_revision
    or lower(coalesce(v_file.hash_value,''))<>v_approval.script_content_hash then
    return jsonb_build_object('outcome','stale','reason','approved_script_is_not_current','ready',null);
  end if;
  if p_publish_evidence->>'transition' is distinct from 'hearth.approved-script.ready.v4'
    or p_publish_evidence->>'script_approval_id' is distinct from v_approval.id::text
    or (p_publish_evidence->>'script_approval_revision')::bigint is distinct from v_approval.approval_revision
    or lower(coalesce(p_publish_evidence->>'script_approval_hash','')) is distinct from v_approval.script_content_hash then
    return jsonb_build_object('outcome','conflict','reason','approval_evidence_mismatch','ready',null);
  end if;
  v_fingerprint:=md5(jsonb_build_object(
    'contract','hearth.approved-script.ready.v4',
    'workspace_id',p_workspace_id,
    'workpiece_id',p_workpiece_id,
    'script_approval_id',v_approval.id,
    'script_approval_revision',v_approval.approval_revision,
    'script_approval_hash',v_approval.script_content_hash,
    'publish_evidence',p_publish_evidence
  )::text);
  select * into v_existing
  from tongs.workpiece_ready_transition_requests
  where workspace_id=p_workspace_id and idempotency_key=v_key;
  if found then
    if v_existing.request_fingerprint<>v_fingerprint then
      return jsonb_build_object('outcome','conflict','reason','idempotency_reuse','ready',null);
    end if;
    select * into v_ready
    from tongs.workpiece_ready_script_meta
    where transition_id=v_existing.id;
    return jsonb_build_object('outcome','duplicate','reason',null,'ready',to_jsonb(v_ready));
  end if;
  insert into tongs.workpiece_ready_transition_requests(
    workspace_id,workpiece_id,script_path,script_revision,script_hash,
    script_approval_id,script_approval_revision,script_approval_hash,
    preflight_report_id,preflight_report_revision,preflight_script_hash,
    research_artifact_id,research_artifact_hash,
    idempotency_key,request_fingerprint,publish_evidence,transitioned_by
  ) values(
    p_workspace_id,p_workpiece_id,v_approval.source_file_path,
    v_approval.source_file_revision,v_approval.script_content_hash,
    v_approval.id,v_approval.approval_revision,v_approval.script_content_hash,
    null,null,null,null,null,
    v_key,v_fingerprint,p_publish_evidence,v_user
  ) returning * into v_transition;
  insert into tongs.workpiece_ready_script_meta(
    workspace_id,workpiece_id,script_path,marked_ready_by,marked_ready_at,updated_by,
    script_revision,script_hash,script_approval_id,script_approval_revision,script_approval_hash,
    preflight_report_id,preflight_report_revision,preflight_script_hash,
    research_artifact_id,research_artifact_hash,
    transition_id,publish_evidence
  ) values(
    p_workspace_id,p_workpiece_id,v_approval.source_file_path,v_user,now(),v_user,
    v_approval.source_file_revision,v_approval.script_content_hash,
    v_approval.id,v_approval.approval_revision,v_approval.script_content_hash,
    null,null,null,null,null,v_transition.id,p_publish_evidence
  )
  on conflict(workpiece_id,script_path) do update set
    workspace_id=excluded.workspace_id,
    marked_ready_by=excluded.marked_ready_by,
    marked_ready_at=excluded.marked_ready_at,
    updated_by=excluded.updated_by,
    script_revision=excluded.script_revision,
    script_hash=excluded.script_hash,
    script_approval_id=excluded.script_approval_id,
    script_approval_revision=excluded.script_approval_revision,
    script_approval_hash=excluded.script_approval_hash,
    preflight_report_id=null,
    preflight_report_revision=null,
    preflight_script_hash=null,
    research_artifact_id=null,
    research_artifact_hash=null,
    transition_id=excluded.transition_id,
    publish_evidence=excluded.publish_evidence
  returning * into v_ready;
  return jsonb_build_object('outcome','saved','reason',null,'ready',to_jsonb(v_ready));
exception
  when invalid_text_representation then
    return jsonb_build_object('outcome','conflict','reason','approval_evidence_mismatch','ready',null);
end;
$$;


ALTER FUNCTION "tongs"."hearth_transition_approved_script_ready_v4"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_script_approval_id" "uuid", "p_idempotency_key" "text", "p_publish_evidence" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."hearth_transition_preflighted_script_ready_v3"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_script_approval_id" "uuid", "p_preflight_report_id" "uuid", "p_idempotency_key" "text", "p_publish_evidence" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare v_user uuid:=auth.uid();v_key text:=btrim(coalesce(p_idempotency_key,''));v_approval tongs.script_approval_revisions%rowtype;v_binding tongs.script_approval_preflight_bindings%rowtype;v_report tongs.hearth_editorial_preflight_reports%rowtype;v_review tongs.hearth_preflight_review_receipts%rowtype;v_existing tongs.workpiece_ready_transition_requests%rowtype;v_transition tongs.workpiece_ready_transition_requests%rowtype;v_ready tongs.workpiece_ready_script_meta%rowtype;v_fingerprint text;
begin
 if v_user is null or not tongs.has_workspace_role(p_workspace_id,'editor') then return jsonb_build_object('outcome','denied','reason','editor_required');end if;
 select * into v_approval from tongs.script_approval_revisions where id=p_script_approval_id and workspace_id=p_workspace_id and workpiece_id=p_workpiece_id;
 select * into v_binding from tongs.script_approval_preflight_bindings where script_approval_id=v_approval.id and preflight_report_id=p_preflight_report_id;
 select * into v_report from tongs.hearth_editorial_preflight_reports where id=v_binding.preflight_report_id;
 select * into v_review from tongs.hearth_preflight_review_receipts where report_id=v_report.id;
 if v_approval.id is null or v_binding.script_approval_id is null or v_review.id is null or v_approval.script_content_hash<>v_report.script_content_hash then return jsonb_build_object('outcome','conflict','reason','reviewed_preflight_required');end if;
 if not exists(select 1 from tongs.workpiece_script_approval_sequences where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and current_approval_id=v_approval.id) then return jsonb_build_object('outcome','stale','reason','approval_not_current');end if;
 if not exists(select 1 from tongs.workpiece_hearth_preflight_sequences where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and current_report_id=v_report.id) then return jsonb_build_object('outcome','stale','reason','preflight_not_current');end if;
 if v_report.research_artifact_id is not null and not exists(select 1 from tongs.workpiece_hearth_research_sequences s join tongs.hearth_research_artifact_revisions r on r.id=s.current_artifact_id where s.workspace_id=p_workspace_id and s.workpiece_id=p_workpiece_id and r.id=v_report.research_artifact_id and r.artifact_content_hash=v_report.research_artifact_hash) then return jsonb_build_object('outcome','stale','reason','research_not_current');end if;
 if length(v_key) not between 8 and 200 or p_publish_evidence->>'transition'<>'hearth.preflighted-script.ready.v3' or p_publish_evidence->>'script_approval_id' is distinct from v_approval.id::text or p_publish_evidence->>'preflight_report_id' is distinct from v_report.id::text then return jsonb_build_object('outcome','conflict','reason','invalid_publish_evidence');end if;
 v_fingerprint:=md5(concat_ws(chr(31),p_workspace_id,p_workpiece_id,v_approval.id,v_report.id,v_approval.script_content_hash,p_publish_evidence::text));
 select * into v_existing from tongs.workpiece_ready_transition_requests where workspace_id=p_workspace_id and idempotency_key=v_key;
 if found then if v_existing.request_fingerprint<>v_fingerprint then return jsonb_build_object('outcome','conflict','reason','idempotency_reuse');end if;select * into v_ready from tongs.workpiece_ready_script_meta where transition_id=v_existing.id;return jsonb_build_object('outcome','duplicate','ready',to_jsonb(v_ready));end if;
 insert into tongs.workpiece_ready_transition_requests(workspace_id,workpiece_id,script_path,script_revision,script_hash,script_approval_id,script_approval_revision,script_approval_hash,preflight_report_id,preflight_report_revision,preflight_script_hash,research_artifact_id,research_artifact_hash,idempotency_key,request_fingerprint,publish_evidence,transitioned_by)
 values(p_workspace_id,p_workpiece_id,v_approval.source_file_path,v_approval.source_file_revision,v_approval.script_content_hash,v_approval.id,v_approval.approval_revision,v_approval.script_content_hash,v_report.id,v_report.revision,v_report.script_content_hash,v_report.research_artifact_id,v_report.research_artifact_hash,v_key,v_fingerprint,p_publish_evidence,v_user) returning * into v_transition;
 insert into tongs.workpiece_ready_script_meta(workspace_id,workpiece_id,script_path,marked_ready_by,marked_ready_at,updated_by,script_revision,script_hash,script_approval_id,script_approval_revision,script_approval_hash,preflight_report_id,preflight_report_revision,preflight_script_hash,research_artifact_id,research_artifact_hash,transition_id,publish_evidence)
 values(p_workspace_id,p_workpiece_id,v_approval.source_file_path,v_user,now(),v_user,v_approval.source_file_revision,v_approval.script_content_hash,v_approval.id,v_approval.approval_revision,v_approval.script_content_hash,v_report.id,v_report.revision,v_report.script_content_hash,v_report.research_artifact_id,v_report.research_artifact_hash,v_transition.id,p_publish_evidence)
 on conflict(workpiece_id,script_path) do update set workspace_id=excluded.workspace_id,marked_ready_by=excluded.marked_ready_by,marked_ready_at=excluded.marked_ready_at,updated_by=excluded.updated_by,script_revision=excluded.script_revision,script_hash=excluded.script_hash,script_approval_id=excluded.script_approval_id,script_approval_revision=excluded.script_approval_revision,script_approval_hash=excluded.script_approval_hash,preflight_report_id=excluded.preflight_report_id,preflight_report_revision=excluded.preflight_report_revision,preflight_script_hash=excluded.preflight_script_hash,research_artifact_id=excluded.research_artifact_id,research_artifact_hash=excluded.research_artifact_hash,transition_id=excluded.transition_id,publish_evidence=excluded.publish_evidence returning * into v_ready;
 return jsonb_build_object('outcome','saved','ready',to_jsonb(v_ready));
end;$$;


ALTER FUNCTION "tongs"."hearth_transition_preflighted_script_ready_v3"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_script_approval_id" "uuid", "p_preflight_report_id" "uuid", "p_idempotency_key" "text", "p_publish_evidence" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."hearth_transition_script_ready"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_script_path" "text", "p_expected_script_revision" bigint, "p_expected_script_hash" "text", "p_idempotency_key" "text", "p_publish_evidence" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $_$
declare
  v_user_id uuid := auth.uid();
  v_path text := btrim(coalesce(p_script_path, ''));
  v_hash text := lower(btrim(coalesce(p_expected_script_hash, '')));
  v_key text := btrim(coalesce(p_idempotency_key, ''));
  v_request_fingerprint text;
  v_episode tongs.episodes%rowtype;
  v_file tongs.workpiece_files%rowtype;
  v_existing tongs.workpiece_ready_transition_requests%rowtype;
  v_transition tongs.workpiece_ready_transition_requests%rowtype;
  v_ready tongs.workpiece_ready_script_meta%rowtype;
begin
  if v_user_id is null or p_workspace_id is null
    or not tongs.has_workspace_role(p_workspace_id, 'editor') then
    return jsonb_build_object('outcome', 'denied', 'ready', null, 'reason', 'editor_required');
  end if;

  if v_path <> 'script/script.md'
    or p_expected_script_revision is null or p_expected_script_revision <= 0
    or v_hash !~ '^[0-9a-f]{64}$'
    or length(v_key) < 8 or length(v_key) > 200
    or p_publish_evidence is null
    or jsonb_typeof(p_publish_evidence) <> 'object'
    or p_publish_evidence->>'transition' <> 'hearth.script.published.v1'
    or p_publish_evidence->>'script_path' is distinct from v_path
    or (p_publish_evidence->>'script_revision')::bigint is distinct from p_expected_script_revision
    or lower(coalesce(p_publish_evidence->>'script_hash', '')) is distinct from v_hash
    or p_publish_evidence#>>'{validation,validator_version}' <> 'shared-script-tags-v1'
    or coalesce((p_publish_evidence#>>'{validation,ok}')::boolean, false) is not true
    or coalesce((p_publish_evidence#>>'{validation,issue_count}')::integer, -1) <> 0 then
    return jsonb_build_object('outcome', 'conflict', 'ready', null, 'reason', 'invalid_publish_evidence');
  end if;

  v_request_fingerprint := md5(concat_ws(chr(31),
    p_workspace_id::text, p_workpiece_id::text, v_path,
    p_expected_script_revision::text, v_hash, p_publish_evidence::text));

  select * into v_existing
  from tongs.workpiece_ready_transition_requests
  where workspace_id = p_workspace_id and idempotency_key = v_key;
  if found then
    if v_existing.request_fingerprint <> v_request_fingerprint then
      return jsonb_build_object('outcome', 'conflict', 'ready', null, 'reason', 'idempotency_reuse');
    end if;
    select * into v_ready from tongs.workpiece_ready_script_meta
    where workpiece_id = v_existing.workpiece_id and script_path = v_existing.script_path;
    return jsonb_build_object('outcome', 'duplicate', 'ready', to_jsonb(v_ready), 'reason', null);
  end if;

  select * into v_episode from tongs.episodes
  where id = p_workpiece_id and workspace_id = p_workspace_id;
  if not found then
    if exists (select 1 from tongs.episodes where id = p_workpiece_id) then
      return jsonb_build_object('outcome', 'denied', 'ready', null, 'reason', 'workspace_mismatch');
    end if;
    return jsonb_build_object('outcome', 'not_found', 'ready', null, 'reason', 'workpiece_not_found');
  end if;

  select * into v_file from tongs.workpiece_files
  where workpiece_id = p_workpiece_id and path = v_path
  for update;
  if not found then
    return jsonb_build_object('outcome', 'not_found', 'ready', null, 'reason', 'script_not_found');
  end if;

  select * into v_existing
  from tongs.workpiece_ready_transition_requests
  where workspace_id = p_workspace_id and idempotency_key = v_key;
  if found then
    if v_existing.request_fingerprint <> v_request_fingerprint then
      return jsonb_build_object('outcome', 'conflict', 'ready', null, 'reason', 'idempotency_reuse');
    end if;
    select * into v_ready from tongs.workpiece_ready_script_meta
    where workpiece_id = v_existing.workpiece_id and script_path = v_existing.script_path;
    return jsonb_build_object('outcome', 'duplicate', 'ready', to_jsonb(v_ready), 'reason', null);
  end if;

  if v_file.revision <> p_expected_script_revision then
    return jsonb_build_object(
      'outcome', 'stale', 'ready', null, 'reason', 'script_revision_mismatch',
      'canonical_script', jsonb_build_object('revision', v_file.revision, 'hash', v_file.hash_value));
  end if;
  if lower(v_file.hash_value) <> v_hash then
    return jsonb_build_object(
      'outcome', 'conflict', 'ready', null, 'reason', 'script_hash_mismatch',
      'canonical_script', jsonb_build_object('revision', v_file.revision, 'hash', v_file.hash_value));
  end if;

  insert into tongs.workpiece_ready_transition_requests (
    workspace_id, workpiece_id, script_path, script_revision, script_hash,
    idempotency_key, request_fingerprint, publish_evidence, transitioned_by
  ) values (
    p_workspace_id, p_workpiece_id, v_path, p_expected_script_revision, v_hash,
    v_key, v_request_fingerprint, p_publish_evidence, v_user_id
  ) returning * into v_transition;

  insert into tongs.workpiece_ready_script_meta (
    workspace_id, workpiece_id, script_path, marked_ready_by, marked_ready_at,
    updated_by, script_revision, script_hash, transition_id, publish_evidence
  ) values (
    p_workspace_id, p_workpiece_id, v_path, v_user_id, now(),
    v_user_id, v_file.revision, lower(v_file.hash_value), v_transition.id, p_publish_evidence
  )
  on conflict (workpiece_id, script_path) do update set
    workspace_id = excluded.workspace_id,
    marked_ready_by = excluded.marked_ready_by,
    marked_ready_at = excluded.marked_ready_at,
    updated_by = excluded.updated_by,
    script_revision = excluded.script_revision,
    script_hash = excluded.script_hash,
    transition_id = excluded.transition_id,
    publish_evidence = excluded.publish_evidence
  returning * into v_ready;

  delete from tongs.workpiece_ready_script_meta
  where workspace_id = p_workspace_id and workpiece_id = p_workpiece_id and script_path <> v_path;

  return jsonb_build_object('outcome', 'saved', 'ready', to_jsonb(v_ready), 'reason', null);
exception
  when invalid_text_representation then
    return jsonb_build_object('outcome', 'conflict', 'ready', null, 'reason', 'invalid_publish_evidence');
end;
$_$;


ALTER FUNCTION "tongs"."hearth_transition_script_ready"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_script_path" "text", "p_expected_script_revision" bigint, "p_expected_script_hash" "text", "p_idempotency_key" "text", "p_publish_evidence" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."image_map_plan_provenance"("p_document" "jsonb") RETURNS "text"
    LANGUAGE "plpgsql" IMMUTABLE STRICT
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare
  v_entries jsonb := p_document->'entries';
  v_entry jsonb;
  v_state text;
  v_seen integer := 0;
  v_has_unknown boolean := false;
  v_has_stale boolean := false;
  v_has_unresolved boolean := false;
begin
  if jsonb_typeof(v_entries) <> 'array' then
    raise exception 'image-map document entries must be an array';
  end if;
  for v_entry in select value from jsonb_array_elements(v_entries) loop
    v_seen := v_seen + 1;
    v_state := v_entry#>>'{canonical_anchor_assessment,state}';
    if v_state not in ('current','stale','unresolved','provenance_unknown') then
      raise exception 'invalid or missing canonical entry assessment';
    end if;
    v_has_unknown := v_has_unknown or v_state='provenance_unknown';
    v_has_stale := v_has_stale or v_state='stale';
    v_has_unresolved := v_has_unresolved or v_state='unresolved';
  end loop;
  -- Deterministic severity: unknown > stale > unresolved > current.
  if v_has_unknown then return 'provenance_unknown'; end if;
  if v_has_stale then return 'stale'; end if;
  if v_has_unresolved then return 'unresolved'; end if;
  return 'current';
end
$$;


ALTER FUNCTION "tongs"."image_map_plan_provenance"("p_document" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."image_map_plan_provenance"("p_document" "jsonb") IS 'Deterministic aggregate of entry assessments: provenance_unknown > stale > unresolved > current.';



CREATE OR REPLACE FUNCTION "tongs"."import_legacy_runway_opening_commitment"("p_reservation_id" "uuid", "p_operator_user_id" "uuid", "p_amount_micros" bigint, "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare r tongs.funding_reservations%rowtype; existing tongs.legacy_supplier_opening_commitments%rowtype;
begin
 if coalesce(auth.role(),'')<>'service_role' or not tongs.is_platform_operator(p_operator_user_id) or p_amount_micros<>750000
   or p_reservation_id is null or length(btrim(coalesce(p_reason,'')))<3 then
  raise exception 'protected exact Runway opening commitment required' using errcode='42501';
 end if;

 select * into existing from tongs.legacy_supplier_opening_commitments
 where commitment_key='runway-owner-pilot:'||p_reservation_id::text;
 if found then return to_jsonb(existing)||jsonb_build_object('replay',true); end if;

 select * into r from tongs.funding_reservations where id=p_reservation_id;
 if found and (r.funding_source_type<>'owner_budget'
    or exists(select 1 from tongs.paid_operation_aggregate_bindings where reservation_id=r.id)) then
  raise exception 'unaggregated historical owner Runway reservation required' using errcode='P0001';
 end if;

 insert into tongs.legacy_supplier_opening_commitments(
  id,environment,provider,reservation_id,commitment_key,amount_micros,status,evidence_json
 ) values(
  gen_random_uuid(),'production','runway',case when r.id is null then null else r.id end,
  'runway-owner-pilot:'||p_reservation_id::text,750000,'unresolved',
  jsonb_build_object(
   'reason',p_reason,
   'legacy_reservation_reference',p_reservation_id,
   'reservation_record_available',r.id is not null,
   'funding_entitlement',false,
   'duplicate_supplier_expense',false,
   'provenance_status',case when r.id is null then 'legacy_reservation_unavailable' else 'canonical_reservation_verified' end
  )
 ) returning * into existing;
 return to_jsonb(existing)||jsonb_build_object('replay',false);
end $$;


ALTER FUNCTION "tongs"."import_legacy_runway_opening_commitment"("p_reservation_id" "uuid", "p_operator_user_id" "uuid", "p_amount_micros" bigint, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."ingest_thumbnail_performance_observation"("p_workspace_id" "uuid", "p_publication_id" "text", "p_provider" "text", "p_provider_schema_version" "text", "p_provider_observation_id" "text", "p_supersedes_observation_id" "uuid", "p_source_payload_hash" "text", "p_observed_from" timestamp with time zone, "p_observed_to" timestamp with time zone, "p_collected_at" timestamp with time zone, "p_timezone" "text", "p_traffic_source" "text", "p_audience_segment" "text", "p_metrics_json" "jsonb", "p_raw_observation" "jsonb", "p_content_hash" "text") RETURNS TABLE("observation_id" "uuid", "disposition" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare v_user uuid:=auth.uid(); v_id uuid;
begin
  if v_user is null then raise exception 'Not authenticated' using errcode='42501'; end if; perform tongs.assert_workspace_role(p_workspace_id,'editor');
  select id into v_id from tongs.thumbnail_performance_observations where workspace_id=p_workspace_id and provider=p_provider and provider_observation_id=p_provider_observation_id;
  if v_id is not null then return query select v_id,'existing'::text; return; end if;
  insert into tongs.thumbnail_performance_observations(workspace_id,publication_id,provider,provider_schema_version,provider_observation_id,supersedes_observation_id,source_payload_hash,observed_from,observed_to,collected_at,timezone,traffic_source,audience_segment,metrics_json,raw_observation,content_hash,created_by)
  values(p_workspace_id,p_publication_id,p_provider,p_provider_schema_version,p_provider_observation_id,p_supersedes_observation_id,p_source_payload_hash,p_observed_from,p_observed_to,p_collected_at,p_timezone,p_traffic_source,p_audience_segment,p_metrics_json,p_raw_observation,p_content_hash,v_user) returning id into v_id;
  return query select v_id,'created'::text;
end $$;


ALTER FUNCTION "tongs"."ingest_thumbnail_performance_observation"("p_workspace_id" "uuid", "p_publication_id" "text", "p_provider" "text", "p_provider_schema_version" "text", "p_provider_observation_id" "text", "p_supersedes_observation_id" "uuid", "p_source_payload_hash" "text", "p_observed_from" timestamp with time zone, "p_observed_to" timestamp with time zone, "p_collected_at" timestamp with time zone, "p_timezone" "text", "p_traffic_source" "text", "p_audience_segment" "text", "p_metrics_json" "jsonb", "p_raw_observation" "jsonb", "p_content_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."is_hammer_history_component_authority"("p_authority" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $_$
declare
  v_key text; v_value jsonb; v_file tongs.workpiece_files%rowtype; v_workpiece_id uuid;
begin
  if jsonb_typeof(p_authority) <> 'object'
    or not (p_authority ?& array['transcript','visual_timeline','visual_placements','audio','editorial_authority'])
    or (select count(*) from jsonb_object_keys(p_authority)) <> 5 then return false; end if;
  begin v_workpiece_id := (p_authority->'transcript'->>'workpiece_id')::uuid;
  exception when others then return false; end;
  for v_key, v_value in select key, value from jsonb_each(p_authority) loop
    if jsonb_typeof(v_value) <> 'object' or (select count(*) from jsonb_object_keys(v_value)) <> 7
      or not (v_value ?& array['workpiece_id','path','sha256','bytes','registry_revision','registry_updated_at','content_type'])
      or v_value->>'workpiece_id' <> v_workpiece_id::text or coalesce(v_value->>'path','') = ''
      or v_value->>'path' ~ '(^/|\.\.)' or v_value->>'sha256' !~ '^[0-9a-f]{64}$'
      or v_value->>'bytes' !~ '^[1-9][0-9]*$' or v_value->>'registry_revision' !~ '^[1-9][0-9]*$'
      or v_value->>'content_type' <> 'application/json' then return false; end if;
    begin perform (v_value->>'registry_updated_at')::timestamptz;
    exception when others then return false; end;
    select * into v_file from tongs.workpiece_files
      where workpiece_id = v_workpiece_id and path = v_value->>'path';
    if v_file.workpiece_id is null or lower(v_file.hash_value) <> v_value->>'sha256'
      or v_file.bytes <> (v_value->>'bytes')::bigint or v_file.revision <> (v_value->>'registry_revision')::bigint
      or v_file.updated_at <> (v_value->>'registry_updated_at')::timestamptz
      or v_file.content_type <> 'application/json' or v_file.hash_algo <> 'sha256'
      or v_file.storage_bucket <> 'forge-workpieces'
      or not (v_file.storage_key = format('workpieces/%s/%s', v_workpiece_id, v_value->>'path')
        or v_file.storage_key ~ format('^workpieces/%s/hammer/staging/history-atomic/[0-9a-f-]+/', v_workpiece_id))
    then return false; end if;
  end loop;
  return true;
end;
$_$;


ALTER FUNCTION "tongs"."is_hammer_history_component_authority"("p_authority" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."is_hammer_history_component_sha256"("p_hashes" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $_$
  select jsonb_typeof(p_hashes) = 'object'
    and p_hashes ?& array['transcript', 'visual_timeline', 'visual_placements', 'audio', 'editorial_authority']
    and not exists (
      select 1
      from jsonb_each_text(p_hashes) as component(name, hash_value)
      where component.hash_value !~ '^[0-9a-f]{64}$'
    );
$_$;


ALTER FUNCTION "tongs"."is_hammer_history_component_sha256"("p_hashes" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."is_platform_operator"("p_user_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_caller uuid := auth.uid();
  v_role text := coalesce(auth.role(), '');
begin
  if p_user_id is null then
    return false;
  end if;

  -- Authenticated callers may only inspect their own operator state. Service-role
  -- callers need the wider form for bootstrapping and server-side authorization.
  if v_role <> 'service_role' and v_caller is distinct from p_user_id then
    return false;
  end if;

  return exists (
    select 1
    from tongs.platform_operators po
    where po.user_id = p_user_id
  );
end;
$$;


