CREATE OR REPLACE FUNCTION "tongs"."list_my_orgs"() RETURNS TABLE("org_id" "uuid", "org_name" "text", "my_org_role" "text", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare
  v_user uuid;
begin
  v_user := auth.uid();
  if v_user is null then
    raise exception 'Not authenticated'
      using errcode = '42501';
  end if;

  return query
  select
    o.id,
    o.name,
    om.org_role,
    o.created_at
  from tongs.org_members om
  join tongs.orgs o
    on o.id = om.org_id
  where om.user_id = v_user
  order by
    case om.org_role
      when 'owner' then 40
      when 'admin' then 30
      when 'member' then 20
      else 0
    end desc,
    lower(o.name) asc,
    o.created_at asc;
end;
$$;


ALTER FUNCTION "tongs"."list_my_orgs"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."list_my_recent_script_references"("p_workspace_id" "uuid", "p_limit" integer DEFAULT 24) RETURNS TABLE("workspace_id" "uuid", "workpiece_id" "uuid", "script_path" "text", "title" "text", "marked_ready_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare
  v_user uuid;
  v_limit integer := greatest(1, least(coalesce(p_limit, 24), 100));
begin
  v_user := auth.uid();
  if v_user is null then
    raise exception 'Not authenticated'
      using errcode = '42501';
  end if;

  if p_workspace_id is null then
    raise exception 'workspace_id is required'
      using errcode = '22023';
  end if;

  perform tongs.assert_workspace_role(p_workspace_id, 'viewer');

  return query
  with ranked as (
    select
      m.workspace_id,
      m.workpiece_id,
      m.script_path,
      m.marked_ready_at,
      e.label,
      row_number() over (
        partition by m.workpiece_id
        order by m.marked_ready_at desc, m.script_path asc
      ) as rn
    from tongs.workpiece_ready_script_meta m
    join tongs.episodes e
      on e.id = m.workpiece_id
    where m.workspace_id = p_workspace_id
  )
  select
    r.workspace_id,
    r.workpiece_id,
    r.script_path,
    coalesce(nullif(btrim(r.label), ''), concat('Episode ', left(r.workpiece_id::text, 8))) as title,
    r.marked_ready_at
  from ranked r
  where r.rn = 1
  order by r.marked_ready_at desc, r.workpiece_id
  limit v_limit;
end;
$$;


