CREATE OR REPLACE FUNCTION "tongs"."list_my_workspace_access"() RETURNS TABLE("workspace_id" "uuid", "workspace_name" "text", "role" "text", "created_at" timestamp with time zone, "source_type" "text", "org_id" "uuid", "org_name" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare
  v_user uuid;
begin
  v_user := auth.uid();
  if v_user is null then
    raise exception 'Not authenticated'
      using errcode = '42501';
  end if;

  return query
  with candidate as (
    select
      w.id as workspace_id,
      w.name as workspace_name,
      w.created_at,
      w.org_id,
      w.created_by,
      wm.role as member_role
    from tongs.workspaces w
    left join tongs.workspace_members wm
      on wm.workspace_id = w.id
     and wm.user_id = v_user
    where w.created_by = v_user
       or wm.user_id = v_user
  )
  select
    c.workspace_id,
    c.workspace_name,
    case
      when c.created_by = v_user then 'owner'
      else coalesce(c.member_role, 'viewer')
    end as role,
    c.created_at,
    case
      when c.org_id is null or o.personal_owner_user_id = v_user then 'personal'
      else 'shared'
    end as source_type,
    c.org_id,
    o.name as org_name
  from candidate c
  left join tongs.orgs o
    on o.id = c.org_id
  order by
    tongs.workspace_role_rank(
      case
        when c.created_by = v_user then 'owner'
        else coalesce(c.member_role, 'viewer')
      end
    ) desc,
    c.created_at asc,
    lower(c.workspace_name) asc;
end;
$$;


ALTER FUNCTION "tongs"."list_my_workspace_access"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."list_my_workspaces"() RETURNS TABLE("workspace_id" "uuid", "workspace_name" "text", "role" "text", "created_at" timestamp with time zone)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
  select
    x.workspace_id,
    x.workspace_name,
    x.role,
    x.created_at
  from tongs.list_my_workspace_access() x
  order by
    tongs.workspace_role_rank(x.role) desc,
    x.created_at asc,
    lower(x.workspace_name) asc;
$$;


ALTER FUNCTION "tongs"."list_my_workspaces"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."list_org_members"("p_org_id" "uuid") RETURNS TABLE("org_id" "uuid", "user_id" "uuid", "user_email" "text", "org_role" "text", "created_at" timestamp with time zone, "created_by" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare
  v_user uuid;
begin
  v_user := auth.uid();
  if v_user is null then
    raise exception 'Not authenticated'
      using errcode = '42501';
  end if;

  if p_org_id is null then
    raise exception 'org_id is required'
      using errcode = '22023';
  end if;

  if not exists (
    select 1
    from tongs.org_members me
    where me.org_id = p_org_id
      and me.user_id = v_user
  ) then
    raise exception 'Insufficient org role (requires member)'
      using errcode = '42501';
  end if;

  return query
  select
    om.org_id,
    om.user_id,
    coalesce(lower(u.email), ''),
    om.org_role,
    om.created_at,
    om.created_by
  from tongs.org_members om
  left join auth.users u
    on u.id = om.user_id
  where om.org_id = p_org_id
  order by
    case om.org_role
      when 'owner' then 40
      when 'admin' then 30
      when 'member' then 20
      else 0
    end desc,
    om.created_at asc,
    coalesce(lower(u.email), '') asc;
end;
$$;


ALTER FUNCTION "tongs"."list_org_members"("p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."list_org_teams"("p_org_id" "uuid") RETURNS TABLE("team_id" "uuid", "org_id" "uuid", "team_name" "text", "member_count" bigint, "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
begin
  perform tongs.assert_org_role(p_org_id, 'member');

  return query
  select
    t.id,
    t.org_id,
    t.name,
    count(tm.user_id)::bigint as member_count,
    t.created_at,
    t.updated_at
  from tongs.teams t
  left join tongs.team_members tm
    on tm.team_id = t.id
  where t.org_id = p_org_id
  group by t.id, t.org_id, t.name, t.created_at, t.updated_at
  order by lower(t.name) asc, t.created_at asc;
end;
$$;


ALTER FUNCTION "tongs"."list_org_teams"("p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."list_team_members"("p_team_id" "uuid") RETURNS TABLE("team_id" "uuid", "user_id" "uuid", "user_email" "text", "team_role" "text", "created_at" timestamp with time zone, "created_by" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare
  v_org_id uuid;
begin
  if p_team_id is null then
    raise exception 'team_id is required'
      using errcode = '22023';
  end if;

  select t.org_id
  into v_org_id
  from tongs.teams t
  where t.id = p_team_id;

  if v_org_id is null then
    raise exception 'Team not found'
      using errcode = 'P0002';
  end if;

  perform tongs.assert_org_role(v_org_id, 'member');

  return query
  select
    tm.team_id,
    tm.user_id,
    coalesce(lower(u.email), '') as user_email,
    tm.team_role,
    tm.created_at,
    tm.created_by
  from tongs.team_members tm
  left join auth.users u
    on u.id = tm.user_id
  where tm.team_id = p_team_id
  order by
    case tm.team_role
      when 'lead' then 20
      when 'member' then 10
      else 0
    end desc,
    tm.created_at asc,
    coalesce(lower(u.email), '') asc;
end;
$$;


ALTER FUNCTION "tongs"."list_team_members"("p_team_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."list_thumbnail_ledger_intelligence"("p_workspace_id" "uuid", "p_limit" integer DEFAULT 100) RETURNS TABLE("launch_intervals" "jsonb", "performance_observations" "jsonb", "analyses" "jsonb", "experiments" "jsonb", "freshness" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$ begin perform tongs.assert_workspace_role(p_workspace_id,'viewer'); return query select
  coalesce((select jsonb_agg(to_jsonb(x) order by started_at desc) from (select * from tongs.thumbnail_launch_intervals where workspace_id=p_workspace_id order by started_at desc limit least(greatest(p_limit,1),500))x),'[]'::jsonb),
  coalesce((select jsonb_agg(to_jsonb(x) order by collected_at desc) from (select * from tongs.thumbnail_performance_observations where workspace_id=p_workspace_id order by collected_at desc limit least(greatest(p_limit,1),500))x),'[]'::jsonb),
  coalesce((select jsonb_agg(to_jsonb(x) order by created_at desc) from (select * from tongs.thumbnail_ledger_analyses where workspace_id=p_workspace_id order by created_at desc limit least(greatest(p_limit,1),500))x),'[]'::jsonb),
  coalesce((select jsonb_agg(to_jsonb(x) order by created_at desc) from (select * from tongs.thumbnail_launch_experiments where workspace_id=p_workspace_id order by created_at desc limit least(greatest(p_limit,1),500))x),'[]'::jsonb),
  coalesce((select to_jsonb(x) from (select max(last_success_at) last_collected_at,case when count(*)=0 then 'unavailable' when bool_or(status='disconnected') then 'disconnected' when max(last_success_at)<now()-interval '48 hours' then 'stale' else 'current' end state from tongs.thumbnail_ledger_ingestion_cursors where workspace_id=p_workspace_id)x),'{"last_collected_at":null,"state":"unavailable"}'::jsonb); end $$;


ALTER FUNCTION "tongs"."list_thumbnail_ledger_intelligence"("p_workspace_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."list_thumbnail_memory_projection"("p_workspace_id" "uuid", "p_limit" integer DEFAULT 100) RETURNS TABLE("launch_facts" "jsonb", "active_interpretations" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
begin
  perform tongs.assert_workspace_role(p_workspace_id, 'viewer');
  return query
  select
    coalesce((select jsonb_agg(to_jsonb(f) order by f.recorded_at desc) from
      (select id, workpiece_id, launch_identity, launch_snapshot_hash, published_at, destination, fact_json, recorded_at
       from tongs.thumbnail_launch_facts where workspace_id = p_workspace_id
       order by recorded_at desc limit greatest(1, least(coalesce(p_limit, 100), 500))) f), '[]'::jsonb),
    coalesce((select jsonb_agg(to_jsonb(i) order by i.created_at desc) from
      (select distinct on (interpretation_key) id, interpretation_key, revision, supersedes_id,
        observation_type, evidence_launch_identities, interpretation_json, created_at
       from tongs.thumbnail_memory_interpretations where workspace_id = p_workspace_id
       order by interpretation_key, revision desc) i), '[]'::jsonb);
end;
$$;


ALTER FUNCTION "tongs"."list_thumbnail_memory_projection"("p_workspace_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."list_workspace_brand_library"("p_workspace_id" "uuid", "p_include_archived" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
begin
  perform tongs.assert_workspace_role(p_workspace_id,'viewer');
  return jsonb_build_object(
    'profiles',coalesce((
      select jsonb_agg(to_jsonb(x) order by x.internal_label)
      from (
        select p.*,d.profile_id is not null is_default
        from tongs.brand_profiles p
        left join tongs.workspace_default_brand_profiles d
          on d.workspace_id=p.workspace_id and d.profile_id=p.id
        where p.workspace_id=p_workspace_id
          and (p_include_archived or p.archived_at is null)
      ) x
    ),'[]'::jsonb),
    'revisions',coalesce((
      select jsonb_agg(
        to_jsonb(r) || jsonb_build_object(
          'rules',r.rules_json,
          'validation',r.validation_json || jsonb_build_object(
            'verified_at',r.verified_at,
            'verification_version',r.verification_version
          )
        )
        order by r.profile_id,r.revision desc
      )
      from tongs.brand_profile_revisions r
      where r.workspace_id=p_workspace_id
    ),'[]'::jsonb),
    'assets',coalesce((
      select jsonb_agg(to_jsonb(a))
      from tongs.brand_assets a
      where a.workspace_id=p_workspace_id
    ),'[]'::jsonb),
    'asset_revisions',coalesce((
      select jsonb_agg(to_jsonb(ar) order by ar.asset_id,ar.revision desc)
      from tongs.brand_asset_revisions ar
      where ar.workspace_id=p_workspace_id
    ),'[]'::jsonb)
  );
end
$$;


ALTER FUNCTION "tongs"."list_workspace_brand_library"("p_workspace_id" "uuid", "p_include_archived" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."list_workspace_invites"("p_workspace_id" "uuid", "p_only_pending" boolean DEFAULT true) RETURNS TABLE("id" "uuid", "workspace_id" "uuid", "email" "text", "role" "text", "created_by" "uuid", "created_by_email" "text", "created_at" timestamp with time zone, "expires_at" timestamp with time zone, "accepted_at" timestamp with time zone, "revoked_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
begin
  if p_workspace_id is null then
    raise exception 'workspace_id is required'
      using errcode = '22023';
  end if;

  perform tongs.assert_workspace_role(p_workspace_id, 'viewer');

  return query
  select
    wi.id,
    wi.workspace_id,
    wi.email,
    wi.role,
    wi.created_by,
    lower(coalesce(created_by_user.email, '')) as created_by_email,
    wi.created_at,
    wi.expires_at,
    wi.accepted_at,
    wi.revoked_at
  from tongs.workspace_invites wi
  left join auth.users created_by_user
    on created_by_user.id = wi.created_by
  where wi.workspace_id = p_workspace_id
    and (
      not coalesce(p_only_pending, true)
      or (wi.accepted_at is null and wi.revoked_at is null)
    )
  order by wi.created_at desc;
end;
$$;


ALTER FUNCTION "tongs"."list_workspace_invites"("p_workspace_id" "uuid", "p_only_pending" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."list_workspace_members"("p_workspace_id" "uuid") RETURNS TABLE("workspace_id" "uuid", "user_id" "uuid", "user_email" "text", "role" "text", "created_at" timestamp with time zone, "created_by" "uuid", "created_by_email" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
begin
  if p_workspace_id is null then
    raise exception 'workspace_id is required'
      using errcode = '22023';
  end if;

  perform tongs.assert_workspace_role(p_workspace_id, 'viewer');

  return query
  select
    wm.workspace_id,
    wm.user_id,
    lower(coalesce(member_user.email, '')) as user_email,
    wm.role,
    wm.created_at,
    wm.created_by,
    lower(coalesce(created_by_user.email, '')) as created_by_email
  from tongs.workspace_members wm
  left join auth.users member_user
    on member_user.id = wm.user_id
  left join auth.users created_by_user
    on created_by_user.id = wm.created_by
  where wm.workspace_id = p_workspace_id
  order by tongs.workspace_role_rank(wm.role) desc, wm.created_at asc;
end;
$$;


ALTER FUNCTION "tongs"."list_workspace_members"("p_workspace_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."lock_hammer_shorts_basis"("p_basis" "jsonb", "p_operation_id" "text", "p_operation_fingerprint" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public', 'extensions'
    AS $_$
declare v_actor uuid:=auth.uid(); v_row tongs.hammer_shorts_basis_locks%rowtype; v_head tongs.hammer_history_epoch_heads%rowtype;
begin
  if v_actor is null or not tongs.has_workspace_role((p_basis->>'workspace_id')::uuid,'editor') then raise exception 'hammer_shorts_editor_required' using errcode='42501'; end if;
  if p_operation_fingerprint!~'^[0-9a-f]{64}$' or p_basis->>'basis_fingerprint'!~'^[0-9a-f]{64}$' then raise exception 'hammer_shorts_fingerprint_invalid' using errcode='22023'; end if;
  select * into v_row from tongs.hammer_shorts_basis_locks where operation_id=p_operation_id; if found then return to_jsonb(v_row); end if;
  select * into v_head from tongs.hammer_history_epoch_heads where head_id=(p_basis->>'history_head_id')::uuid;
  if v_head.head_id is null or v_head.workspace_id<>(p_basis->>'workspace_id')::uuid or v_head.workpiece_id<>(p_basis->>'parent_workpiece_id')::uuid or v_head.recording_revision_id<>(p_basis->>'recording_revision_id')::uuid or v_head.result_editor_state_hash<>p_basis->>'editor_state_hash' then raise exception 'hammer_shorts_basis_not_current' using errcode='40001'; end if;
  if exists(select 1 from tongs.hammer_history_epoch_heads h where h.recording_revision_id=v_head.recording_revision_id and h.sequence>v_head.sequence) then raise exception 'hammer_shorts_basis_not_current' using errcode='40001'; end if;
  insert into tongs.hammer_shorts_basis_locks(workspace_id,parent_workpiece_id,canonical_recording_id,recording_revision_id,history_epoch_id,history_head_id,history_sequence,editor_state_hash,transcript_fingerprint,timeline_fingerprint,render_assembly_fingerprint,output_time_map_fingerprint,basis_fingerprint,operation_id,operation_fingerprint,locked_by)
  values((p_basis->>'workspace_id')::uuid,(p_basis->>'parent_workpiece_id')::uuid,(p_basis->>'canonical_recording_id')::uuid,(p_basis->>'recording_revision_id')::uuid,(p_basis->>'history_epoch_id')::uuid,(p_basis->>'history_head_id')::uuid,(p_basis->>'history_sequence')::bigint,p_basis->>'editor_state_hash',p_basis->>'transcript_fingerprint',p_basis->>'timeline_fingerprint',p_basis->>'render_assembly_fingerprint',p_basis->>'output_time_map_fingerprint',p_basis->>'basis_fingerprint',p_operation_id,p_operation_fingerprint,v_actor) returning * into v_row; return to_jsonb(v_row);
end $_$;


ALTER FUNCTION "tongs"."lock_hammer_shorts_basis"("p_basis" "jsonb", "p_operation_id" "text", "p_operation_fingerprint" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."manual_handoff_freshness"("p_snapshot_id" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
 select case when s.id is null then 'missing' when
  not exists(select 1 from tongs.quench_release_manifest_snapshots m where m.workspace_id=s.workspace_id and m.workpiece_id=s.workpiece_id and m.id=s.manifest_snapshot_id and m.snapshotted_at=(select max(m2.snapshotted_at) from tongs.quench_release_manifest_snapshots m2 where m2.workspace_id=s.workspace_id and m2.workpiece_id=s.workpiece_id))
  or not exists(select 1 from tongs.quench_release_decision_sequences q where q.workspace_id=s.workspace_id and q.workpiece_id=s.workpiece_id and q.destination_scope_id=s.release_decision_scope_id and q.current_decision_id=s.release_decision_id and q.current_revision=s.release_decision_revision)
  or not exists(select 1 from tongs.quench_destination_scopes d where d.id=s.release_decision_scope_id and d.current_capability_revision_id=s.destination_capability_revision_id and d.state='active') then 'stale' else 'current' end
 from (select * from tongs.manual_handoff_snapshots where id=p_snapshot_id)s;
$$;


ALTER FUNCTION "tongs"."manual_handoff_freshness"("p_snapshot_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."mark_bellows_session_latest_checkpoint"("p_session_id" "text", "p_checkpoint_id" "uuid") RETURNS "tongs"."bellows_sessions"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare
  v_session tongs.bellows_sessions;
  v_checkpoint tongs.bellows_session_checkpoints;
begin
  select *
  into v_session
  from tongs.bellows_sessions
  where id = p_session_id
  for update;

  if not found then
    raise exception 'bellows_session_not_found'
      using errcode = 'P0002';
  end if;

  if coalesce(auth.role(), '') <> 'service_role' then
    perform tongs.assert_workspace_role(v_session.workspace_id, 'editor');
  end if;

  select *
  into v_checkpoint
  from tongs.bellows_session_checkpoints
  where session_id = p_session_id
    and id = p_checkpoint_id;

  if not found then
    raise exception 'bellows_checkpoint_not_found'
      using errcode = 'P0002';
  end if;

  update tongs.bellows_sessions
  set
    latest_checkpoint_id = v_checkpoint.id,
    acting_authority_state = v_checkpoint.acting_authority_state,
    host_participant_id = v_checkpoint.host_participant_id,
    acting_host_participant_id = v_checkpoint.acting_host_participant_id,
    co_host_participant_ids = v_checkpoint.co_host_participant_ids,
    lifecycle_state = v_checkpoint.lifecycle_state,
    recording_state = v_checkpoint.recording_state,
    broadcast_state = v_checkpoint.broadcast_state,
    upload_state = v_checkpoint.upload_state,
    seal_state = v_checkpoint.seal_state,
    outcome = v_checkpoint.outcome,
    integrity_flags = v_checkpoint.integrity_flags,
    snapshot_schema_version = v_checkpoint.snapshot_schema_version
  where id = p_session_id
  returning *
  into v_session;

  return v_session;
end;
$$;


ALTER FUNCTION "tongs"."mark_bellows_session_latest_checkpoint"("p_session_id" "text", "p_checkpoint_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."mark_broll_submission_unknown"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_submission_attempt_id" "uuid", "p_reason" "text", "p_transport_evidence" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare v_op tongs.broll_operation_receipts%rowtype;
begin
 select * into v_op from tongs.broll_operation_receipts where operation_id=p_operation_id for update;
 if not found then return jsonb_build_object('disposition','operation_not_found'); end if;
 if not tongs.has_workspace_role(v_op.workspace_id,'editor') then raise exception 'workspace editor authority required' using errcode='42501'; end if;
 if v_op.operation_fingerprint<>p_operation_fingerprint or v_op.submission_attempt_id is distinct from p_submission_attempt_id then return jsonb_build_object('disposition','operation_identity_conflict'); end if;
 if v_op.provider_task_id is not null then return jsonb_build_object('disposition','replay','operation',to_jsonb(v_op)); end if;
 if v_op.state='submission_unknown' then return jsonb_build_object('disposition','replay','operation',to_jsonb(v_op)); end if;
 if v_op.state<>'submitting' then return jsonb_build_object('disposition','submitting_stage_required','operation',to_jsonb(v_op)); end if;
 update tongs.broll_operation_receipts set state='submission_unknown',submission_unknown_at=now(),ambiguity_reason=p_reason,transport_evidence_json=coalesce(p_transport_evidence,'{}'::jsonb),updated_at=now() where operation_id=p_operation_id returning * into v_op;
 return jsonb_build_object('disposition','submission_unknown','operation',to_jsonb(v_op));
end $$;


ALTER FUNCTION "tongs"."mark_broll_submission_unknown"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_submission_attempt_id" "uuid", "p_reason" "text", "p_transport_evidence" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."mark_customer_hearth_research_stage_unknown"("p_reservation_id" "uuid", "p_stage_key" "text", "p_evidence_json" "jsonb") RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $_$
  select tongs._finish_customer_hearth_research_stage($1,$2,'submission_unknown',
    (select maximum_supplier_cost_micros from tongs.customer_hearth_research_stage_events
     where reservation_id=$1 and stage_key=btrim($2) and sequence=1),null,$3)
$_$;


ALTER FUNCTION "tongs"."mark_customer_hearth_research_stage_unknown"("p_reservation_id" "uuid", "p_stage_key" "text", "p_evidence_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."mark_hammer_recording_import_failure"("p_import_id" "uuid", "p_stage" "text", "p_code" "text", "p_details" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare v_user uuid:=auth.uid(); v_import tongs.hammer_recording_import_requests%rowtype;
begin
  select * into v_import from tongs.hammer_recording_import_requests where id=p_import_id for update;
  if not found then return jsonb_build_object('outcome','not_found','import',null); end if;
  if v_user is null or not tongs.has_workspace_role(v_import.workspace_id,'editor') then return jsonb_build_object('outcome','denied','import',null); end if;
  if v_import.state='committed' then return jsonb_build_object('outcome','duplicate','import',to_jsonb(v_import)); end if;
  update tongs.hammer_recording_import_requests set state='recoverable_failure',failure_stage=p_stage,failure_code=p_code,
    failure_details=coalesce(p_details,'{}'::jsonb) where id=p_import_id returning * into v_import;
  return jsonb_build_object('outcome','recoverable_failure','import',to_jsonb(v_import));
end; $$;


ALTER FUNCTION "tongs"."mark_hammer_recording_import_failure"("p_import_id" "uuid", "p_stage" "text", "p_code" "text", "p_details" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."mark_hearth_chat_test_submission_unknown"("p_reservation_id" "uuid", "p_event_key" "text", "p_evidence_json" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare v_seq integer;
begin
  perform tongs._require_pricing_service_role();
  if exists(select 1 from tongs.test_funding_reservation_events where event_key=btrim(p_event_key)) then return jsonb_build_object('state','submission_unknown','replay',true); end if;
  if tongs._test_reservation_state(p_reservation_id)<>'attempt_started' then raise exception 'Test attempt required' using errcode='P0001'; end if;
  select coalesce(max(sequence),0)+1 into v_seq from tongs.test_funding_reservation_events where reservation_id=p_reservation_id;
  insert into tongs.test_funding_reservation_events(id,reservation_id,sequence,event_type,event_key,evidence_json)
  values(gen_random_uuid(),p_reservation_id,v_seq,'submission_unknown',btrim(p_event_key),coalesce(p_evidence_json,'{}'::jsonb));
  return jsonb_build_object('state','submission_unknown','replay',false,'reservation_retained',true,'automatic_resubmission_allowed',false);
end $$;


