CREATE OR REPLACE FUNCTION "tongs"."mark_paid_media_delivery"("p_paid_media_operation_id" "uuid", "p_operation_fingerprint" "text", "p_delivery_evidence_json" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare v_op tongs.paid_media_operations%rowtype;
begin
  select * into v_op from tongs.paid_media_operations where id=p_paid_media_operation_id for update;
  if not found or v_op.operation_fingerprint<>p_operation_fingerprint then raise exception 'paid operation not found or mismatched' using errcode='P0002'; end if;
  if v_op.state in ('delivered','settled') then return jsonb_build_object('operation',to_jsonb(v_op),'replay',true); end if;
  if v_op.state<>'provider_completed' or jsonb_typeof(p_delivery_evidence_json)<>'object' then raise exception 'provider completion is required before delivery' using errcode='P0001'; end if;
  update tongs.paid_media_operations set state='delivered',updated_at=now() where id=v_op.id returning * into v_op;
  insert into tongs.paid_media_operation_events values(gen_random_uuid(),v_op.id,v_op.user_id,'canonical_delivery_verified',
    (select coalesce(max(event_ordinal),0)+1 from tongs.paid_media_operation_events where paid_media_operation_id=v_op.id),p_delivery_evidence_json,v_op.actor_id,now());
  return jsonb_build_object('operation',to_jsonb(v_op),'replay',false);
end $$;


ALTER FUNCTION "tongs"."mark_paid_media_delivery"("p_paid_media_operation_id" "uuid", "p_operation_fingerprint" "text", "p_delivery_evidence_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."mark_paid_media_submission_unknown"("p_paid_media_operation_id" "uuid", "p_operation_fingerprint" "text", "p_attempt_id" "uuid", "p_failure_code" "text", "p_failure_message" "text", "p_evidence_json" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare v_op tongs.paid_media_operations%rowtype; v_attempt tongs.paid_media_provider_attempts%rowtype;
begin
  select * into v_op from tongs.paid_media_operations where id=p_paid_media_operation_id for update;
  if not found or v_op.operation_fingerprint<>p_operation_fingerprint then raise exception 'paid operation not found or mismatched' using errcode='P0002'; end if;
  select * into v_attempt from tongs.paid_media_provider_attempts where id=p_attempt_id and paid_media_operation_id=v_op.id for update;
  if not found then raise exception 'provider attempt not found' using errcode='P0002'; end if;
  if v_attempt.state='submission_unknown' then return jsonb_build_object('operation',to_jsonb(v_op),'attempt',to_jsonb(v_attempt),'replay',true); end if;
  update tongs.paid_media_provider_attempts set state='submission_unknown',transmitted=true,transport_evidence_json=coalesce(p_evidence_json,'{}'),completed_at=now() where id=v_attempt.id returning * into v_attempt;
  update tongs.paid_media_operations set state='submission_unknown',failure_code=p_failure_code,failure_message=p_failure_message,reconciliation_required=true,updated_at=now() where id=v_op.id returning * into v_op;
  insert into tongs.paid_media_operation_events values(gen_random_uuid(),v_op.id,v_op.user_id,'submission_unknown',4,coalesce(p_evidence_json,'{}'),v_op.actor_id,now());
  return jsonb_build_object('operation',to_jsonb(v_op),'attempt',to_jsonb(v_attempt),'replay',false);
end $$;


ALTER FUNCTION "tongs"."mark_paid_media_submission_unknown"("p_paid_media_operation_id" "uuid", "p_operation_fingerprint" "text", "p_attempt_id" "uuid", "p_failure_code" "text", "p_failure_message" "text", "p_evidence_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."mark_submission_unknown"("p_reservation_id" "uuid", "p_event_key" "text", "p_attempt_key" "text", "p_evidence_json" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_reservation tongs.funding_reservations%rowtype;
  v_existing tongs.funding_reservation_events%rowtype;
  v_state text;
  v_sequence integer;
begin
  perform tongs._require_pricing_service_role();
  if length(btrim(coalesce(p_event_key, ''))) < 8 or length(btrim(coalesce(p_attempt_key, ''))) < 8
     or jsonb_typeof(coalesce(p_evidence_json, 'null'::jsonb)) <> 'object' then
    raise exception 'invalid unknown-submission event' using errcode = '22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('provider-attempt:' || p_reservation_id::text, 0));
  select * into v_reservation from tongs.funding_reservations where id = p_reservation_id for update;
  if not found then raise exception 'funding reservation not found' using errcode = 'P0002'; end if;
  select * into v_existing from tongs.funding_reservation_events where event_key = btrim(p_event_key);
  if found then return jsonb_build_object('reservation_id', p_reservation_id, 'state', 'submission_unknown', 'replay', true); end if;
  v_state := tongs._funding_reservation_state(p_reservation_id);
  if v_state in ('settled', 'released') then raise exception 'reservation is terminal' using errcode = 'P0001'; end if;
  if not exists (select 1 from tongs.funding_reservation_events
    where reservation_id = p_reservation_id and provider_attempt_key = btrim(p_attempt_key)
      and event_type = 'provider_attempt_shadowed') then
    raise exception 'provider attempt lease not found' using errcode = 'P0002';
  end if;
  select coalesce(max(sequence),0)+1 into v_sequence from tongs.funding_reservation_events
    where reservation_id = p_reservation_id;
  insert into tongs.funding_reservation_events(
    id, reservation_id, sequence, event_type, event_key, evidence_json
  ) values (gen_random_uuid(), p_reservation_id, v_sequence, 'submission_unknown',
    btrim(p_event_key), coalesce(p_evidence_json, '{}'::jsonb));
  return jsonb_build_object('reservation_id', p_reservation_id, 'state', 'submission_unknown',
    'replay', false, 'reservation_retained', true, 'automatic_resubmission_allowed', false);
end;
$$;


ALTER FUNCTION "tongs"."mark_submission_unknown"("p_reservation_id" "uuid", "p_event_key" "text", "p_attempt_key" "text", "p_evidence_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."mark_thumbnail_brand_asset_ready"("p_workspace_id" "uuid", "p_operation_id" "uuid", "p_operation_fingerprint" "text", "p_actor_id" "uuid", "p_content_hash" "text", "p_bytes" bigint, "p_width" integer DEFAULT NULL::integer, "p_height" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $_$
declare v_op tongs.thumbnail_brand_setup_operations%rowtype;v_asset tongs.brand_asset_revisions%rowtype;
begin if not exists(select 1 from tongs.workspace_members where workspace_id=p_workspace_id and user_id=p_actor_id and tongs.workspace_role_rank(role)>=tongs.workspace_role_rank('editor')) then raise exception 'Insufficient workspace role (requires editor)' using errcode='42501';end if;select * into v_op from tongs.thumbnail_brand_setup_operations where workspace_id=p_workspace_id and operation_id=p_operation_id for update;
 if not found then raise exception 'Thumbnail brand setup operation not found' using errcode='P0002';end if;if v_op.operation_fingerprint<>p_operation_fingerprint then raise exception 'Operation identity was reused with a different payload.' using errcode='22023';end if;
 if v_op.state<>'pending' then return tongs.thumbnail_brand_setup_json(v_op.id);end if;
 select * into v_asset from tongs.brand_asset_revisions where id=v_op.logo_asset_revision_id for update;
 if v_asset.state='ready' and (v_asset.content_hash<>p_content_hash or v_asset.bytes<>p_bytes) then raise exception 'Ready asset readback mismatch' using errcode='22023';end if;
 if v_asset.state<>'ready' then
  if p_content_hash!~'^[a-f0-9]{64}$' or p_bytes<=0 then raise exception 'Verified hash and bytes are required' using errcode='22023';end if;
  perform set_config('tongs.brand_controlled_transition','on',true);update tongs.brand_asset_revisions set state='ready',content_hash=p_content_hash,bytes=p_bytes,width=p_width,height=p_height,ready_at=now(),failure_message=null where id=v_asset.id;perform set_config('tongs.brand_controlled_transition','off',true);
 end if;
 perform set_config('tongs.thumbnail_brand_setup_transition','on',true);update tongs.thumbnail_brand_setup_operations set state='asset_ready',logo_content_hash=p_content_hash,failed_stage=null,failure_code=null,failure_message=null,updated_at=now() where id=v_op.id;perform set_config('tongs.thumbnail_brand_setup_transition','off',true);
 return tongs.thumbnail_brand_setup_json(v_op.id);
end $_$;


ALTER FUNCTION "tongs"."mark_thumbnail_brand_asset_ready"("p_workspace_id" "uuid", "p_operation_id" "uuid", "p_operation_fingerprint" "text", "p_actor_id" "uuid", "p_content_hash" "text", "p_bytes" bigint, "p_width" integer, "p_height" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."mark_unified_visual_plan_submission_unknown"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_reservation_id" "uuid", "p_evidence_json" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  op tongs.unified_visual_plan_operations%rowtype;
  binding tongs.openai_text_funding_bindings%rowtype;
begin
  perform tongs._require_pricing_service_role();
  if jsonb_typeof(coalesce(p_evidence_json,'null'::jsonb))<>'object' then
    raise exception 'invalid unified Visual Plan transport evidence' using errcode='22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('unified-visual-plan-transport:'||btrim(p_operation_id),0));
  select * into op from tongs.unified_visual_plan_operations
    where operation_id=btrim(p_operation_id) for update;
  select * into binding from tongs.openai_text_funding_bindings
    where operation_id=btrim(p_operation_id) and reservation_id=p_reservation_id
      and route_code='visual.unified_plan';
  if op.operation_id is null or op.operation_fingerprint is distinct from p_operation_fingerprint
    or binding.reservation_id is null or binding.model<>'gpt-5.6-luna'
    or binding.maximum_attempts<>1 then
    raise exception 'invalid unified Visual Plan transport identity' using errcode='22023';
  end if;
  if op.state='submission_unknown' then
    return jsonb_build_object('disposition','submission_unknown_replay','operation',to_jsonb(op),
      'automatic_resubmission_allowed',false);
  end if;
  if op.state in('verified','failed') then
    return jsonb_build_object('disposition','terminal_operation_conflict','operation',to_jsonb(op));
  end if;
  update tongs.unified_visual_plan_operations
  set state='submission_unknown',failed_stage='provider_transport',
      failure_code='visual_plan_submission_unknown',
      failure_message='Provider submission may have occurred; automatic resubmission is prohibited pending authoritative reconciliation.',
      updated_at=now()
  where operation_id=op.operation_id returning * into op;
  return jsonb_build_object('disposition','submission_unknown','operation',to_jsonb(op),
    'automatic_resubmission_allowed',false,'evidence',p_evidence_json);
end $$;


ALTER FUNCTION "tongs"."mark_unified_visual_plan_submission_unknown"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_reservation_id" "uuid", "p_evidence_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."mutate_workpiece_brand_binding"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_intent" "text", "p_operation_id" "text", "p_operation_fingerprint" "text", "p_expected_current_revision" integer, "p_profile_id" "uuid" DEFAULT NULL::"uuid", "p_profile_revision_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare v_user uuid:=auth.uid(); v_op tongs.workpiece_brand_binding_operations%rowtype; v_current tongs.workpiece_brand_bindings%rowtype; v_target tongs.brand_profile_revisions%rowtype; v_id uuid; v_result jsonb; v_assets uuid[];
begin if v_user is null then raise exception 'Not authenticated' using errcode='42501'; end if; perform tongs.assert_workspace_role(p_workspace_id,'editor');
  perform pg_advisory_xact_lock(hashtextextended(p_workspace_id::text||':'||p_workpiece_id::text||':brand',0));
  select * into v_op from tongs.workpiece_brand_binding_operations where workspace_id=p_workspace_id and operation_id=p_operation_id;
  if found then if v_op.operation_fingerprint<>p_operation_fingerprint then raise exception 'Operation identity was reused with a different payload.' using errcode='22023'; end if; return v_op.result_json; end if;
  select * into v_current from tongs.workpiece_brand_bindings where workpiece_id=p_workpiece_id order by revision desc limit 1;
  if v_current.id is null or v_current.revision<>p_expected_current_revision then v_result:=jsonb_build_object('disposition','revision_conflict','binding',case when v_current.id is null then null else tongs.brand_binding_json(v_current.id) end,'current_revision',v_current.revision,'message','Expected binding revision is stale.');
  elsif p_intent='disable' and v_current.state='disabled' then v_result:=jsonb_build_object('disposition','no_change','binding',tongs.brand_binding_json(v_current.id),'current_revision',v_current.revision);
  else
    if p_intent='update_to_current_profile_revision' then p_profile_id:=v_current.profile_id; select * into v_target from tongs.brand_profile_revisions r where r.profile_id=p_profile_id and tongs.brand_revision_is_bindable(p_workspace_id,p_profile_id,r.id) order by revision desc limit 1;
    elsif p_intent='select_profile_revision' then select * into v_target from tongs.brand_profile_revisions where id=p_profile_revision_id and profile_id=p_profile_id;
    elsif p_intent<>'disable' then raise exception 'Unsupported brand binding intent' using errcode='22023'; end if;
    if p_intent<>'disable' and (v_target.id is null or not tongs.brand_revision_is_bindable(p_workspace_id,p_profile_id,v_target.id)) then v_result:=jsonb_build_object('disposition','target_not_bindable','binding',tongs.brand_binding_json(v_current.id),'current_revision',v_current.revision,'message','Target profile revision is not bindable.');
    elsif p_intent<>'disable' and v_current.state='profile' and v_current.profile_revision_id=v_target.id then v_result:=jsonb_build_object('disposition','no_change','binding',tongs.brand_binding_json(v_current.id),'current_revision',v_current.revision);
    else v_id:=gen_random_uuid();
      if p_intent='disable' then insert into tongs.workpiece_brand_bindings(id,workspace_id,workpiece_id,revision,state,mutation_reason,operation_id,operation_fingerprint,previous_binding_id,created_by) values(v_id,p_workspace_id,p_workpiece_id,v_current.revision+1,'disabled','disable',p_operation_id,p_operation_fingerprint,v_current.id,v_user);
      else select coalesce(array_agg(value::uuid),'{}') into v_assets from jsonb_each_text(coalesce(v_target.rules_json->'asset_revision_ids','{}'::jsonb)); insert into tongs.workpiece_brand_bindings(id,workspace_id,workpiece_id,revision,state,profile_id,profile_revision_id,profile_revision,profile_content_hash,asset_revision_ids,mutation_reason,operation_id,operation_fingerprint,previous_binding_id,created_by) values(v_id,p_workspace_id,p_workpiece_id,v_current.revision+1,'profile',p_profile_id,v_target.id,v_target.revision,v_target.content_hash,v_assets,p_intent,p_operation_id,p_operation_fingerprint,v_current.id,v_user); end if;
      v_result:=jsonb_build_object('disposition','created_revision','binding',tongs.brand_binding_json(v_id),'current_revision',v_current.revision+1); end if; end if;
  insert into tongs.workpiece_brand_binding_operations(workspace_id,workpiece_id,operation_id,operation_fingerprint,intent,disposition,binding_id,result_json,created_by) values(p_workspace_id,p_workpiece_id,p_operation_id,p_operation_fingerprint,p_intent,v_result->>'disposition',coalesce(v_id,v_current.id),v_result,v_user);
  return v_result; end $$;


ALTER FUNCTION "tongs"."mutate_workpiece_brand_binding"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_intent" "text", "p_operation_id" "text", "p_operation_fingerprint" "text", "p_expected_current_revision" integer, "p_profile_id" "uuid", "p_profile_revision_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."normalize_script_approval_text"("p_text" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE STRICT
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
  select normalize(
    replace(replace(
      case when left(p_text, 1) = U&'\FEFF' then substr(p_text, 2) else p_text end,
      E'\r\n', E'\n'), E'\r', E'\n'),
    NFC
  );
$$;


ALTER FUNCTION "tongs"."normalize_script_approval_text"("p_text" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."open_hammer_authority"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_operation_key" "text", "p_transcript_policy" "text" DEFAULT 'reuse_only'::"text", "p_revision_label" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare
  v_user uuid:=auth.uid(); v_key text:=btrim(coalesce(p_operation_key,''));
  v_policy text:=btrim(coalesce(p_transcript_policy,'reuse_only')); v_fingerprint text;
  v_existing tongs.hammer_preparation_attempts%rowtype; v_attempt tongs.hammer_preparation_attempts%rowtype; v_receipt record;
  v_episode tongs.episodes%rowtype; v_canonical tongs.canonical_recordings%rowtype;
  v_revision tongs.recording_revisions%rowtype; v_take record; v_capture uuid; v_media_id text;
begin
  if v_user is null or not tongs.has_workspace_role(p_workspace_id,'editor') then
    return jsonb_build_object('outcome','denied','reason','editor_required');
  end if;
  select * into v_episode from tongs.episodes where id=p_workpiece_id and workspace_id=p_workspace_id for update;
  if not found then return jsonb_build_object('outcome','not_found','reason','workpiece_membership_mismatch'); end if;
  if length(v_key) not between 8 and 200 or v_policy not in ('reuse_only','allow_ai_fallback') then
    return jsonb_build_object('outcome','conflict','reason','invalid_open_request');
  end if;
  v_fingerprint:=md5(concat_ws('|',p_workspace_id,p_workpiece_id,v_policy,coalesce(p_revision_label,'')));
  select r.request_fingerprint receipt_fingerprint,a.* into v_receipt from tongs.hammer_open_operation_receipts r
    join tongs.hammer_preparation_attempts a on a.id=r.preparation_attempt_id
    where r.workspace_id=p_workspace_id and r.operation_key=v_key;
  if found then
    if v_receipt.receipt_fingerprint<>v_fingerprint then
      return jsonb_build_object('outcome','conflict','reason','hammer_open_idempotency_conflict');
    end if;
    select * into v_canonical from tongs.canonical_recordings where id=v_receipt.canonical_recording_id;
    select * into v_revision from tongs.recording_revisions where id=v_receipt.recording_revision_id;
    return jsonb_build_object('outcome','duplicate','canonical_recording',to_jsonb(v_canonical),
      'revision',to_jsonb(v_revision),'preparation_attempt',to_jsonb(v_receipt)-'receipt_fingerprint');
  end if;

  if v_episode.canonical_recording_id is not null then
    select * into v_canonical from tongs.canonical_recordings
      where id=v_episode.canonical_recording_id and workspace_id=p_workspace_id and workpiece_id=p_workpiece_id;
    if not found then return jsonb_build_object('outcome','blocked','reason','canonical_recording_pointer_invalid'); end if;
  else
    select r.*,c.capture_authority_id into v_take
      from tongs.current_workpiece_recorded_takes r
      left join tongs.anvil_recording_completion_requests c on c.id=r.completion_id
      where r.workspace_id=p_workspace_id and r.workpiece_id=p_workpiece_id and r.keep_id is not null
      order by r.kept_at desc nulls last,r.completed_at desc,r.source_authority_id desc limit 1;
    if not found then return jsonb_build_object('outcome','blocked','reason','canonical_recording_missing_take'); end if;
    v_capture:=v_take.capture_authority_id;
    v_media_id:=case when v_take.source_kind='anvil_capture'
      then 'anvil-completion:'||v_take.source_authority_id::text
      else 'hammer-import:'||v_take.source_authority_id::text end;
    insert into tongs.canonical_recordings(workspace_id,workpiece_id,status,kept_take_event_id,media_path,
      media_content_type,media_bytes,recording_session_id,anvil_capture_session_id,media_id,media_signature,
      source_kind,source_authority_id,source_capture_authority_id,created_by,updated_by)
    values(p_workspace_id,p_workpiece_id,'draft',null,v_take.media_path,v_take.media_content_type,v_take.media_bytes,
      v_take.recording_session_id,v_take.capture_session_id::text,v_media_id,v_take.media_hash,
      v_take.source_kind,v_take.source_authority_id,v_capture,v_user,v_user)
    returning * into v_canonical;
    update tongs.episodes set canonical_recording_id=v_canonical.id,updated_at=now() where id=p_workpiece_id;
  end if;

  if v_episode.active_revision_id is not null then
    select * into v_revision from tongs.recording_revisions where id=v_episode.active_revision_id
      and workspace_id=p_workspace_id and workpiece_id=p_workpiece_id
      and canonical_recording_id=v_canonical.id and status='active';
  end if;
  if v_revision.id is null then
    select * into v_revision from tongs.recording_revisions where workspace_id=p_workspace_id
      and workpiece_id=p_workpiece_id and canonical_recording_id=v_canonical.id and status='active'
      order by created_at desc,id desc limit 1;
  end if;
  if v_revision.id is null then
    insert into tongs.recording_revisions(workspace_id,workpiece_id,canonical_recording_id,status,label,created_by,updated_by)
      values(p_workspace_id,p_workpiece_id,v_canonical.id,'active',p_revision_label,v_user,v_user) returning * into v_revision;
    update tongs.episodes set active_revision_id=v_revision.id,updated_at=now() where id=p_workpiece_id;
  end if;

  select * into v_existing from tongs.hammer_preparation_attempts
    where recording_revision_id=v_revision.id
      and state in ('reserved','resolving_recording','resolving_transcript','awaiting_transcript_choice','transcribing','hydrating')
    for update;
  if found then
    insert into tongs.hammer_open_operation_receipts(workspace_id,workpiece_id,operation_key,request_fingerprint,preparation_attempt_id,opened_by)
      values(p_workspace_id,p_workpiece_id,v_key,v_fingerprint,v_existing.id,v_user);
    return jsonb_build_object('outcome','attached','canonical_recording',to_jsonb(v_canonical),
      'revision',to_jsonb(v_revision),'preparation_attempt',to_jsonb(v_existing));
  end if;

  insert into tongs.hammer_preparation_attempts(workspace_id,workpiece_id,canonical_recording_id,
    recording_revision_id,source_kind,source_authority_id,source_capture_authority_id,media_path,media_id,
    media_hash,transcript_policy,state,operation_key,request_fingerprint,created_by)
  values(p_workspace_id,p_workpiece_id,v_canonical.id,v_revision.id,
    coalesce(v_canonical.source_kind,'legacy_unresolved'),v_canonical.source_authority_id,
    v_canonical.source_capture_authority_id,v_canonical.media_path,v_canonical.media_id,
    lower(v_canonical.media_signature),v_policy,
    case when v_canonical.source_kind is null then 'blocked' else 'resolving_transcript' end,
    v_key,v_fingerprint,v_user) returning * into v_attempt;
  insert into tongs.hammer_open_operation_receipts(workspace_id,workpiece_id,operation_key,request_fingerprint,preparation_attempt_id,opened_by)
    values(p_workspace_id,p_workpiece_id,v_key,v_fingerprint,v_attempt.id,v_user);
  return jsonb_build_object('outcome','opened','canonical_recording',to_jsonb(v_canonical),
    'revision',to_jsonb(v_revision),'preparation_attempt',to_jsonb(v_attempt));
exception when unique_violation then
  select r.request_fingerprint receipt_fingerprint,a.* into v_receipt from tongs.hammer_open_operation_receipts r
    join tongs.hammer_preparation_attempts a on a.id=r.preparation_attempt_id
    where r.workspace_id=p_workspace_id and r.operation_key=v_key;
  if found then
    if v_receipt.receipt_fingerprint<>v_fingerprint then return jsonb_build_object('outcome','conflict','reason','hammer_open_idempotency_conflict'); end if;
    select * into v_canonical from tongs.canonical_recordings where id=v_receipt.canonical_recording_id;
    select * into v_revision from tongs.recording_revisions where id=v_receipt.recording_revision_id;
    return jsonb_build_object('outcome','duplicate','canonical_recording',to_jsonb(v_canonical),'revision',to_jsonb(v_revision),
      'preparation_attempt',to_jsonb(v_receipt)-'receipt_fingerprint');
  end if;
  select * into v_existing from tongs.hammer_preparation_attempts where recording_revision_id=v_revision.id
    and state in ('reserved','resolving_recording','resolving_transcript','awaiting_transcript_choice','transcribing','hydrating');
  if found then
    insert into tongs.hammer_open_operation_receipts(workspace_id,workpiece_id,operation_key,request_fingerprint,preparation_attempt_id,opened_by)
      values(p_workspace_id,p_workpiece_id,v_key,v_fingerprint,v_existing.id,v_user);
    return jsonb_build_object('outcome','attached','canonical_recording',to_jsonb(v_canonical),
      'revision',to_jsonb(v_revision),'preparation_attempt',to_jsonb(v_existing));
  end if;
  raise;
end $$;


ALTER FUNCTION "tongs"."open_hammer_authority"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_operation_key" "text", "p_transcript_policy" "text", "p_revision_label" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."open_hearth_test_execution_authorization"("p_authorization_id" "uuid", "p_actor_id" "uuid", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_deposit_id" "uuid", "p_maximum_operations" integer, "p_maximum_aggregate_charge_micros" bigint, "p_expires_at" timestamp with time zone, "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare v_pricing uuid;
begin
  perform tongs._require_pricing_service_role();
  if not tongs.is_platform_operator(p_actor_id) then raise exception 'platform operator required' using errcode='42501'; end if;
  if p_maximum_operations<1 or p_maximum_operations>10 or p_maximum_aggregate_charge_micros<>p_maximum_operations*20000
     or p_expires_at<=now() or length(btrim(coalesce(p_reason,'')))<8 then raise exception 'invalid Test authorization' using errcode='22023'; end if;
  if not exists(select 1 from tongs.workspace_members where workspace_id=p_workspace_id and user_id=p_user_id) then
    raise exception 'workspace membership required' using errcode='42501'; end if;
  if not exists(select 1 from tongs.customer_deposits where id=p_deposit_id and user_id=p_user_id and stripe_mode='test') then
    raise exception 'eligible Stripe Test deposit required' using errcode='P0002'; end if;
  select id into v_pricing from tongs._published_pricing_revision('openai','gpt-5.6-luna')
    where markup_basis_points=3300 and full_cost_ceiling_micros=11015 and failure_cost_ceiling_micros=0
      and tongs.round_customer_price_micros(full_cost_ceiling_micros::numeric*(10000+markup_basis_points)/10000,currency)=20000;
  if v_pricing is null then raise exception 'published bounded Luna price required' using errcode='P0002'; end if;
  insert into tongs.test_paid_execution_authorizations(id,user_id,workspace_id,deposit_id,pricing_revision_id,route_code,model,
    maximum_operations,maximum_aggregate_charge_micros,expires_at,created_by)
  values(p_authorization_id,p_user_id,p_workspace_id,p_deposit_id,v_pricing,'hearth.chat_completion','gpt-5.6-luna',
    p_maximum_operations,p_maximum_aggregate_charge_micros,p_expires_at,p_actor_id);
  insert into tongs.test_paid_execution_authorization_events(id,authorization_id,sequence,event_type,event_key,actor_id,reason)
  values(gen_random_uuid(),p_authorization_id,1,'opened','test-authorization:'||p_authorization_id||':opened',p_actor_id,btrim(p_reason));
  return jsonb_build_object('authorization_id',p_authorization_id,'state','opened','execution_kind','simulated_test');
end $$;


ALTER FUNCTION "tongs"."open_hearth_test_execution_authorization"("p_authorization_id" "uuid", "p_actor_id" "uuid", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_deposit_id" "uuid", "p_maximum_operations" integer, "p_maximum_aggregate_charge_micros" bigint, "p_expires_at" timestamp with time zone, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."open_openai_text_test_certification"("p_batch_id" "uuid", "p_actor_id" "uuid", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_deposit_id" "uuid", "p_invocation_token_hash" "text", "p_expires_at" timestamp with time zone, "p_terms" "jsonb", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $_$
declare v_term jsonb; v_count integer:=0; v_charge bigint:=0; v_loss bigint:=0; v_model text; v_route text; v_full bigint; v_price bigint; v_term_id uuid;
begin
  perform tongs._require_pricing_service_role();
  if not tongs.is_platform_operator(p_actor_id) or p_expires_at<=now() or p_expires_at>now()+interval '24 hours'
     or p_invocation_token_hash!~'^[0-9a-f]{64}$' or jsonb_typeof(p_terms)<>'array' or length(btrim(coalesce(p_reason,'')))<8 then
    raise exception 'invalid Test certification authorization' using errcode='22023';
  end if;
  if not exists(select 1 from tongs.workspace_members where workspace_id=p_workspace_id and user_id=p_user_id and role='owner') then
    raise exception 'customer owner membership required' using errcode='42501';
  end if;
  if not exists(select 1 from tongs.customer_deposits where id=p_deposit_id and user_id=p_user_id and stripe_mode='test') then
    raise exception 'eligible Stripe Test deposit required' using errcode='42501';
  end if;
  for v_term in select value from jsonb_array_elements(p_terms) loop
    v_count:=v_count+1; v_route:=btrim(v_term->>'route_code'); v_model:=btrim(v_term->>'model');
    if v_route not in ('hearth.research_synthesis','visual.unified_plan','visual.narrative_interpretation','motion.broll_interpretation','hammer.transcript_cleanup','shorts.discovery','quench.metadata')
       or ((v_route like 'visual.%' or v_route='motion.broll_interpretation') and v_model<>'gpt-5-mini')
       or (v_route not like 'visual.%' and v_route<>'motion.broll_interpretation' and v_model<>'gpt-5.3')
       or coalesce((v_term->>'markup_basis_points')::integer,-1)<>3300
       or coalesce((v_term->>'maximum_attempts')::integer,0)<>1
       or v_term->>'rate_evidence_status' not in ('synthetic_test','estimated')
       or coalesce(v_term->'supporting_cost_policy'->>'scope','')<>'validation_and_tongs_persistence_only'
       or coalesce((v_term->'supporting_cost_policy'->>'search_allowed')::boolean,true)
       or coalesce((v_term->'supporting_cost_policy'->>'external_enrichment_allowed')::boolean,true) then
      raise exception 'invalid or unbounded Test route term' using errcode='22023';
    end if;
    v_full:=(v_term->>'direct_provider_ceiling_micros')::bigint+(v_term->>'supporting_cost_ceiling_micros')::bigint;
    v_price:=tongs.round_customer_price_micros(v_full::numeric*13300/10000,'USD');
    if v_price<>(v_term->>'customer_price_ceiling_micros')::bigint or (v_term->>'customer_credit_units')::bigint<>v_price/10000 then
      raise exception 'Test price does not match 33 percent cost-plus rounding' using errcode='22023';
    end if;
    v_charge:=v_charge+v_price; v_loss:=v_loss+(v_term->>'failure_exposure_ceiling_micros')::bigint;
  end loop;
  if v_count<>7 or (select count(distinct value->>'route_code') from jsonb_array_elements(p_terms))<>7 then
    raise exception 'all seven unique routes are required' using errcode='22023';
  end if;
  insert into tongs.openai_text_test_certification_batches(id,user_id,workspace_id,deposit_id,invocation_token_hash,maximum_operation_count,
    maximum_aggregate_charge_micros,maximum_aggregate_failure_exposure_micros,expires_at,created_by,reason)
  values(p_batch_id,p_user_id,p_workspace_id,p_deposit_id,p_invocation_token_hash,14,v_charge,v_loss,p_expires_at,p_actor_id,btrim(p_reason));
  insert into tongs.openai_text_test_certification_batch_events(id,batch_id,sequence,event_type,event_key,actor_id,reason)
  values(gen_random_uuid(),p_batch_id,1,'opened','openai-text-test-certification:'||p_batch_id||':opened',p_actor_id,btrim(p_reason));
  for v_term in select value from jsonb_array_elements(p_terms) loop
    v_term_id:=gen_random_uuid();
    insert into tongs.openai_text_test_certification_terms(id,batch_id,route_code,revision,model,maximum_input_units,maximum_output_units,maximum_attempts,
      input_micros_per_million_tokens,output_micros_per_million_tokens,direct_provider_ceiling_micros,supporting_cost_ceiling_micros,
      failure_exposure_ceiling_micros,markup_basis_points,customer_price_ceiling_micros,customer_credit_units,rate_evidence_status,supporting_cost_policy)
    values(v_term_id,p_batch_id,v_term->>'route_code',1,v_term->>'model',(v_term->>'maximum_input_units')::integer,(v_term->>'maximum_output_units')::integer,1,
      (v_term->>'input_micros_per_million_tokens')::bigint,(v_term->>'output_micros_per_million_tokens')::bigint,
      (v_term->>'direct_provider_ceiling_micros')::bigint,(v_term->>'supporting_cost_ceiling_micros')::bigint,
      (v_term->>'failure_exposure_ceiling_micros')::bigint,3300,(v_term->>'customer_price_ceiling_micros')::bigint,
      (v_term->>'customer_credit_units')::bigint,v_term->>'rate_evidence_status',v_term->'supporting_cost_policy');
  end loop;
  return jsonb_build_object('batch_id',p_batch_id,'state','opened','operation_limit',14,'success_count',7,'failure_count',7,
    'maximum_aggregate_charge_micros',v_charge,'maximum_aggregate_failure_exposure_micros',v_loss,'real_provider_authorized',false);
end $_$;


ALTER FUNCTION "tongs"."open_openai_text_test_certification"("p_batch_id" "uuid", "p_actor_id" "uuid", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_deposit_id" "uuid", "p_invocation_token_hash" "text", "p_expires_at" timestamp with time zone, "p_terms" "jsonb", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."open_quench_authority"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_open_operation_id" "uuid", "p_manifest_snapshot_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs', 'extensions'
    AS $$
declare
  v_user uuid := auth.uid();
  v_existing tongs.quench_open_authority_receipts%rowtype;
  v_manifest tongs.quench_release_manifest_snapshots%rowtype;
  v_fingerprint text;
  v_id uuid;
begin
  if v_user is null or not tongs.has_workspace_role(p_workspace_id, 'viewer') then
    raise exception 'Not authorized to open this Quench review' using errcode = '42501';
  end if;

  if not exists(select 1 from tongs.episodes e where e.id = p_workpiece_id and e.workspace_id = p_workspace_id) then
    return jsonb_build_object('disposition', 'identity_mismatch');
  end if;

  select * into v_existing from tongs.quench_open_authority_receipts where open_operation_id = p_open_operation_id;
  if found then
    if v_existing.workspace_id <> p_workspace_id or v_existing.workpiece_id <> p_workpiece_id
      or v_existing.requested_manifest_snapshot_id is distinct from p_manifest_snapshot_id then
      return jsonb_build_object('disposition', 'quench_open_idempotency_conflict');
    end if;
    return jsonb_build_object('disposition', 'replayed', 'open_authority_id', v_existing.id,
      'open_operation_id', v_existing.open_operation_id, 'workspace_id', v_existing.workspace_id,
      'workpiece_id', v_existing.workpiece_id, 'manifest_snapshot_id', v_existing.manifest_snapshot_id,
      'manifest_content_hash', v_existing.manifest_content_hash, 'state_version', v_existing.state_version,
      'opened_at', v_existing.created_at);
  end if;

  if p_manifest_snapshot_id is not null then
    select * into v_manifest from tongs.quench_release_manifest_snapshots
      where id = p_manifest_snapshot_id and workspace_id = p_workspace_id and workpiece_id = p_workpiece_id;
  else
    select * into v_manifest from tongs.quench_release_manifest_snapshots
      where workspace_id = p_workspace_id and workpiece_id = p_workpiece_id
      order by source_file_revision desc, snapshotted_at desc limit 1;
  end if;
  if not found then return jsonb_build_object('disposition', 'manifest_missing'); end if;

  v_fingerprint := encode(digest(concat_ws('|', p_workspace_id::text, p_workpiece_id::text,
    coalesce(p_manifest_snapshot_id::text, 'current'), v_manifest.id::text, v_manifest.manifest_content_hash), 'sha256'), 'hex');
  insert into tongs.quench_open_authority_receipts(open_operation_id, operation_fingerprint, workspace_id,
    workpiece_id, requested_manifest_snapshot_id, manifest_snapshot_id, manifest_content_hash, created_by)
  values(p_open_operation_id, v_fingerprint, p_workspace_id, p_workpiece_id, p_manifest_snapshot_id,
    v_manifest.id, v_manifest.manifest_content_hash, v_user) returning id into v_id;
  return jsonb_build_object('disposition', 'opened', 'open_authority_id', v_id,
    'open_operation_id', p_open_operation_id, 'workspace_id', p_workspace_id, 'workpiece_id', p_workpiece_id,
    'manifest_snapshot_id', v_manifest.id, 'manifest_content_hash', v_manifest.manifest_content_hash,
    'state_version', 1, 'opened_at', now());
exception when unique_violation then
  select * into v_existing from tongs.quench_open_authority_receipts where open_operation_id = p_open_operation_id;
  if found and v_existing.workspace_id = p_workspace_id and v_existing.workpiece_id = p_workpiece_id
    and v_existing.requested_manifest_snapshot_id is not distinct from p_manifest_snapshot_id then
    return jsonb_build_object('disposition', 'replayed', 'open_authority_id', v_existing.id,
      'open_operation_id', v_existing.open_operation_id, 'workspace_id', v_existing.workspace_id,
      'workpiece_id', v_existing.workpiece_id, 'manifest_snapshot_id', v_existing.manifest_snapshot_id,
      'manifest_content_hash', v_existing.manifest_content_hash, 'state_version', v_existing.state_version,
      'opened_at', v_existing.created_at);
  end if;
  return jsonb_build_object('disposition', 'quench_open_idempotency_conflict');
end; $$;


ALTER FUNCTION "tongs"."open_quench_authority"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_open_operation_id" "uuid", "p_manifest_snapshot_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."open_quench_authority"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_open_operation_id" "uuid", "p_manifest_snapshot_id" "uuid") IS 'Opens or replays one exact Quench review authority using the canonical manifest snapshot timestamp.';



CREATE OR REPLACE FUNCTION "tongs"."org_role_rank"("p_role" "text") RETURNS integer
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'tongs', 'pg_temp'
    AS $$
  select case lower(trim(coalesce(p_role, '')))
    when 'owner' then 40
    when 'admin' then 30
    when 'member' then 20
    else 0
  end;
$$;


ALTER FUNCTION "tongs"."org_role_rank"("p_role" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."persist_hammer_transcript_cleanup_assist_result"("p_operation_id" "text", "p_reservation_id" "uuid", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_request_fingerprint" "text", "p_provider_request_id" "text", "p_input_units" bigint, "p_output_units" bigint, "p_result_json" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare r tongs.hammer_transcript_cleanup_assist_results%rowtype;
begin
  perform tongs._assert_openai_text_domain_result_context('hammer.transcript_cleanup',p_operation_id,p_reservation_id,p_user_id,p_workspace_id,p_workpiece_id,p_request_fingerprint);
  select * into r from tongs.hammer_transcript_cleanup_assist_results where reservation_id=p_reservation_id;
  if not found then insert into tongs.hammer_transcript_cleanup_assist_results(operation_id,reservation_id,user_id,workspace_id,workpiece_id,request_fingerprint,provider_request_id,input_units,output_units,result_json)
    values(btrim(p_operation_id),p_reservation_id,p_user_id,p_workspace_id,p_workpiece_id,p_request_fingerprint,nullif(btrim(coalesce(p_provider_request_id,'')),''),p_input_units,p_output_units,p_result_json) returning * into r; end if;
  return r.result_json||jsonb_build_object('domain_result_id',r.id,'provider_request_id',r.provider_request_id,'input_units',r.input_units,'output_units',r.output_units);
end $$;


ALTER FUNCTION "tongs"."persist_hammer_transcript_cleanup_assist_result"("p_operation_id" "text", "p_reservation_id" "uuid", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_request_fingerprint" "text", "p_provider_request_id" "text", "p_input_units" bigint, "p_output_units" bigint, "p_result_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."persist_hearth_chat_paid_result"("p_result_id" "uuid", "p_operation_id" "text", "p_reservation_id" "uuid", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_workpiece_id" "text", "p_request_fingerprint" "text", "p_provider_request_id" "text", "p_model" "text", "p_input_units" bigint, "p_output_units" bigint, "p_result_hash" "text", "p_result_json" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $_$
declare
  v_binding tongs.openai_text_funding_bindings%rowtype;
  v_reservation tongs.funding_reservations%rowtype;
  v_quote tongs.customer_spending_quotes%rowtype;
  v_existing tongs.openai_text_persisted_results%rowtype;
begin
  perform tongs._require_pricing_service_role();
  if p_result_id is null or p_reservation_id is null or p_user_id is null
     or length(btrim(coalesce(p_workpiece_id,'')))<1
     or p_request_fingerprint !~ '^[0-9a-f]{64}$' or p_result_hash !~ '^[0-9a-f]{64}$'
     or p_input_units<0 or p_output_units<0
     or jsonb_typeof(coalesce(p_result_json,'null'::jsonb))<>'object' then
    raise exception 'invalid canonical Hearth paid result' using errcode='22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('hearth-paid-result:'||p_reservation_id::text,0));
  select * into v_existing from tongs.openai_text_persisted_results where reservation_id=p_reservation_id;
  if found then
    if v_existing.operation_id<>btrim(p_operation_id) or v_existing.result_hash<>p_result_hash
       or v_existing.request_fingerprint<>p_request_fingerprint then
      raise exception 'canonical Hearth result replay conflict' using errcode='23505';
    end if;
    return jsonb_build_object('result_id',v_existing.id,'persisted',true,'replay',true,'result_hash',v_existing.result_hash);
  end if;
  select * into v_binding from tongs.openai_text_funding_bindings
    where operation_id=btrim(p_operation_id) and reservation_id=p_reservation_id;
  select * into v_reservation from tongs.funding_reservations where id=p_reservation_id;
  select * into v_quote from tongs.customer_spending_quotes where id=v_reservation.quote_id;
  if v_binding.operation_id is null or v_reservation.id is null or v_quote.id is null
     or v_binding.route_code<>'hearth.chat_completion'
     or v_binding.model<>btrim(p_model) or v_reservation.user_id<>p_user_id or v_quote.user_id<>p_user_id
     or v_quote.workspace_id is distinct from p_workspace_id
     or v_quote.request_fingerprint<>p_request_fingerprint
     or tongs._funding_reservation_state(p_reservation_id)<>'provider_attempt_shadowed'
     or p_input_units>v_binding.maximum_input_units or p_output_units>v_binding.maximum_output_units then
    raise exception 'canonical Hearth result is not bound to the authorized attempt' using errcode='42501';
  end if;
  insert into tongs.openai_text_persisted_results(
    id,reservation_id,operation_id,route_code,user_id,workspace_id,workpiece_id,
    request_fingerprint,provider_request_id,model,input_units,output_units,result_hash,result_json
  ) values (
    p_result_id,p_reservation_id,btrim(p_operation_id),v_binding.route_code,p_user_id,p_workspace_id,
    btrim(p_workpiece_id),p_request_fingerprint,nullif(btrim(coalesce(p_provider_request_id,'')),''),
    btrim(p_model),p_input_units,p_output_units,p_result_hash,p_result_json
  );
  return jsonb_build_object('result_id',p_result_id,'persisted',true,'replay',false,'result_hash',p_result_hash);
end $_$;


