CREATE OR REPLACE FUNCTION "tongs"."prepare_publishing_connection_reauthorization"("p_owner_user_id" "uuid", "p_connection_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare v_connection tongs.publishing_provider_connections%rowtype;
begin
  if auth.role()<>'service_role' then raise exception 'Forbidden' using errcode='42501'; end if;
  select * into v_connection from tongs.publishing_provider_connections where id=p_connection_id for update;
  if not found or v_connection.owner_user_id<>p_owner_user_id or v_connection.provider<>'google' then return jsonb_build_object('disposition','denied','code','connection_owner_or_provider_mismatch'); end if;
  if v_connection.state not in('revoked','disconnected','invalid','expired','refresh_required') then return jsonb_build_object('disposition','blocked','code','connection_reauthorization_not_required'); end if;
  update tongs.publishing_provider_connections set state='pending_authorization',revoked_at=null,updated_at=now() where id=p_connection_id;
  update tongs.publishing_provider_credential_authorities set state='unavailable',updated_at=now() where id=v_connection.credential_authority_id;
  return jsonb_build_object('disposition','prepared','connection_id',p_connection_id);
end; $$;


ALTER FUNCTION "tongs"."prepare_publishing_connection_reauthorization"("p_owner_user_id" "uuid", "p_connection_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."prepare_thumbnail_candidate_style_provenance"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $_$
declare v_asset tongs.assets%rowtype; v_binding tongs.workpiece_brand_bindings%rowtype; v_has_canonical_style boolean;
begin
  select * into v_asset from tongs.assets where id=new.composite_asset_id;
  select * into v_binding from tongs.workpiece_brand_bindings where id=new.candidate_binding_id;
  v_has_canonical_style := v_asset.metadata_json->>'style_source' in ('brand_profile','forge_standard');
  new.style_source := case when v_has_canonical_style then v_asset.metadata_json->>'style_source'
    when v_binding.state='profile' then 'brand_profile' else 'forge_standard' end;
  new.style_provenance_hash := case when v_has_canonical_style then v_asset.metadata_json->>'style_provenance_hash'
    else encode(extensions.digest(convert_to(jsonb_strip_nulls(jsonb_build_object(
      'contract_version','forge.thumbnail-style-provenance.v1','style_source',new.style_source,
      'legacy_composite_asset_id',new.composite_asset_id,'binding_id',new.candidate_binding_id,
      'binding_revision',new.candidate_binding_revision,'profile_content_hash',new.candidate_binding_content_hash,
      'standard_recipe_id',case when new.style_source='forge_standard' then 'forge-thumbnail-standard' else null end,
      'standard_recipe_version',case when new.style_source='forge_standard' then 1 else null end,
      'resolution_basis','rolling_deployment_legacy_composite'
    ))::text,'UTF8'),'sha256'),'hex') end;
  if new.style_source not in ('brand_profile','forge_standard') or new.style_provenance_hash !~ '^[a-f0-9]{64}$' then
    raise exception 'candidate styling-source provenance is incomplete' using errcode='22023';
  end if;
  if v_has_canonical_style and v_asset.metadata_json->>'style_provenance_hash' <> new.style_provenance_hash then
    raise exception 'candidate styling-source provenance hash mismatch' using errcode='22023';
  end if;
  if v_has_canonical_style and new.style_source = 'forge_standard' and (
    v_asset.metadata_json#>>'{style_application_provenance,standard_recipe_id}' <> 'forge-thumbnail-standard'
    or (v_asset.metadata_json#>>'{style_application_provenance,standard_recipe_version}')::int <> 1
    or coalesce((v_asset.metadata_json#>>'{brand_application_provenance,applied}')::boolean,true) is not false
    or v_asset.metadata_json#>>'{brand_application_provenance,profile_revision_id}' is not null
  ) then raise exception 'Forge standard candidate falsely claims brand treatment' using errcode='22023';
  end if;
  if v_has_canonical_style and new.style_source = 'brand_profile' and (
    v_asset.metadata_json#>>'{style_application_provenance,applied_profile_revision_id}' is null
    or v_asset.metadata_json#>>'{style_application_provenance,applied_profile_content_hash}' is null
    or v_asset.metadata_json#>>'{brand_application_provenance,profile_revision_id}'
      is distinct from v_asset.metadata_json#>>'{style_application_provenance,applied_profile_revision_id}'
  ) then raise exception 'Brand candidate applied provenance is incomplete' using errcode='22023';
  end if;
  if coalesce(v_asset.metadata_json#>>'{brand_binding_context,binding_id}',v_asset.metadata_json#>>'{brand_application_provenance,binding_id}') <> new.candidate_binding_id::text
    or coalesce((v_asset.metadata_json#>>'{brand_binding_context,binding_revision}')::int,(v_asset.metadata_json#>>'{brand_application_provenance,binding_revision}')::int) <> new.candidate_binding_revision then
    raise exception 'candidate styling binding context mismatch' using errcode='22023';
  end if;
  new.canonical_hash_version := 'v2';
  new.canonical_content_hash := encode(extensions.digest(convert_to(jsonb_strip_nulls(jsonb_build_object(
    'schema','forge.thumbnail-candidate.v2','recipe_id',new.recipe_id,'recipe_revision',new.recipe_revision,
    'recipe_hash',new.recipe_hash,'title_revision_id',new.title_revision_id,'title_revision',new.title_revision,
    'concept_revision_id',new.concept_revision_id,'base_artwork_asset_id',new.base_artwork_asset_id,
    'base_artwork_content_hash',new.base_artwork_content_hash,'structural_composition_fingerprint',new.structural_composition_fingerprint,
    'composite_asset_id',new.composite_asset_id,'composite_content_hash',new.composite_content_hash,
    'candidate_binding_id',new.candidate_binding_id,'candidate_binding_revision',new.candidate_binding_revision,
    'candidate_binding_content_hash',new.candidate_binding_content_hash,'style_source',new.style_source,
    'style_provenance_hash',new.style_provenance_hash,'readability_contract_version',new.readability_contract_version,
    'readability_evaluator_version',new.readability_evaluator_version,'readability_evidence_hash',new.readability_evidence_hash,
    'compositor_version',new.compositor_version
  ))::text,'UTF8'),'sha256'),'hex');
  return new;
end $_$;


ALTER FUNCTION "tongs"."prepare_thumbnail_candidate_style_provenance"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."preview_price"("p_pricing_revision_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
  select tongs.preview_private_price(p_pricing_revision_id);
$$;


ALTER FUNCTION "tongs"."preview_price"("p_pricing_revision_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."preview_private_price"("p_pricing_revision_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_result jsonb;
  v_revision tongs.private_pricing_revisions%rowtype;
  v_rounded bigint;
  v_profit bigint;
begin
  v_result:=tongs._preview_private_price_before_rounded_customer_ceiling(p_pricing_revision_id);
  select * into v_revision from tongs.private_pricing_revisions where id=p_pricing_revision_id;
  if v_revision.markup_basis_points is null then return v_result; end if;
  v_rounded:=tongs.round_customer_price_micros(
    v_revision.full_cost_ceiling_micros::numeric*(10000::numeric+v_revision.markup_basis_points)/10000::numeric,
    v_revision.currency
  );
  v_profit:=v_rounded-v_revision.full_cost_ceiling_micros;
  return v_result || jsonb_build_object(
    'unrounded_cost_plus_markup_micros',v_revision.customer_price_ceiling_micros,
    'customer_price_ceiling_micros',v_rounded,
    'expected_margin_micros',v_profit,
    'expected_margin_percentage',case when v_rounded=0 then null
      else round(100::numeric*v_profit::numeric/v_rounded::numeric,4) end
  );
end $$;


ALTER FUNCTION "tongs"."preview_private_price"("p_pricing_revision_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."preview_private_price"("p_pricing_revision_id" "uuid") IS 'Operator-only preview using the same rounded customer ceiling captured by authoritative quotes.';



CREATE OR REPLACE FUNCTION "tongs"."promote_bellows_cohost_authority"("p_session_id" "text", "p_expected_generation" bigint, "p_cohost_participant_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public', 'auth'
    AS $$
declare v_session tongs.bellows_sessions;
begin
  select * into v_session from tongs.bellows_sessions where id=p_session_id for update;
  if not found then return jsonb_build_object('outcome','not_found'); end if;
  if v_session.authority_generation<>p_expected_generation then
    return jsonb_build_object('outcome','stale','authority_generation',v_session.authority_generation);
  end if;
  if not exists(select 1 from tongs.bellows_session_participants p where p.session_id=p_session_id and p.id=p_cohost_participant_id and p.role_code='S2' and p.user_id=auth.uid()) then
    return jsonb_build_object('outcome','denied');
  end if;
  update tongs.bellows_sessions set authority_generation=authority_generation+1,acting_authority_state='co_host_promoted',acting_host_participant_id=p_cohost_participant_id
    where id=p_session_id returning * into v_session;
  return jsonb_build_object('outcome','promoted','authority_generation',v_session.authority_generation,'acting_host_participant_id',v_session.acting_host_participant_id);
end $$;


ALTER FUNCTION "tongs"."promote_bellows_cohost_authority"("p_session_id" "text", "p_expected_generation" bigint, "p_cohost_participant_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."protect_reference_review_operation_attempt"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
begin
  if tg_op='DELETE' then raise exception 'Reference review attempts are immutable' using errcode='55000';end if;
  if old.terminal_outcome is not null then raise exception 'Terminal Reference review attempts are immutable' using errcode='55000';end if;
  if new.attempt_id<>old.attempt_id or new.operation_id<>old.operation_id or new.operation_fingerprint<>old.operation_fingerprint or new.workspace_id<>old.workspace_id or new.workpiece_id<>old.workpiece_id or new.media_family<>old.media_family or new.intent_kind<>old.intent_kind or new.opportunity_id<>old.opportunity_id or new.expected_opportunity_revision_id<>old.expected_opportunity_revision_id or new.expected_plan_revision_id<>old.expected_plan_revision_id or new.expected_revisions_json<>old.expected_revisions_json or new.parent_attempt_id is distinct from old.parent_attempt_id or new.ai_authorization<>old.ai_authorization or new.created_by<>old.created_by or new.created_at<>old.created_at then raise exception 'Reference review attempt identity is immutable' using errcode='55000';end if;
  return new;
end$$;


ALTER FUNCTION "tongs"."protect_reference_review_operation_attempt"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."provision_beta_test_credits"("p_grant_id" "uuid", "p_actor_id" "uuid", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_credit_units" bigint, "p_idempotency_key" "text", "p_reason" "text", "p_metadata_json" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  existing tongs.beta_credit_grants%rowtype;
  value_micros bigint;
  payload jsonb;
begin
  perform tongs._require_accounting_service_role();
  if p_grant_id is null or p_actor_id is null or not tongs.is_platform_operator(p_actor_id)
     or p_user_id is null or p_workspace_id is null or p_credit_units <= 0
     or p_credit_units > 10000000
     or length(btrim(coalesce(p_idempotency_key, ''))) not between 8 and 300
     or length(btrim(coalesce(p_reason, ''))) not between 3 and 300
     or jsonb_typeof(coalesce(p_metadata_json, 'null'::jsonb)) <> 'object' then
    raise exception 'invalid operator beta credit grant' using errcode = '22023';
  end if;
  if tongs._current_financial_environment() <> 'test' then
    raise exception 'beta credits can only be provisioned in Test' using errcode = '42501';
  end if;
  if not exists (
    select 1 from tongs.workspace_members membership
    where membership.workspace_id = p_workspace_id and membership.user_id = p_user_id
  ) then
    raise exception 'beta customer must belong to the target workspace' using errcode = '42501';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('beta-credit-grant:' || btrim(p_idempotency_key), 0));
  select * into existing from tongs.beta_credit_grants
  where id = p_grant_id or idempotency_key = btrim(p_idempotency_key)
  limit 1;
  value_micros := p_credit_units * 5000;
  if found then
    if existing.id <> p_grant_id or existing.user_id <> p_user_id
       or existing.workspace_id <> p_workspace_id
       or existing.credit_units <> p_credit_units then
      raise exception 'beta credit grant replay conflict' using errcode = '23505';
    end if;
    return to_jsonb(existing) || jsonb_build_object('replay', true);
  end if;
  payload := jsonb_build_object(
    'grant_id', p_grant_id, 'user_id', p_user_id, 'workspace_id', p_workspace_id,
    'financial_environment', 'test', 'credit_units', p_credit_units,
    'customer_value_micros', value_micros, 'reason', btrim(p_reason),
    'metadata', coalesce(p_metadata_json, '{}'::jsonb)
  );
  perform tongs._create_accounting_event(
    p_grant_id, 'beta-credit-grant:' || btrim(p_idempotency_key),
    'beta_test_credits_provisioned', 'test', 'beta_credit_grant',
    p_grant_id::text, 'USD', p_user_id, p_workspace_id, p_actor_id,
    payload, now()
  );
  insert into tongs.beta_credit_grants(
    id, user_id, workspace_id, financial_environment, credit_units,
    customer_value_micros, maximum_wholesale_capacity_micros,
    idempotency_key, reason, granted_by, journal_event_id, metadata_json
  ) values (
    p_grant_id, p_user_id, p_workspace_id, 'test', p_credit_units,
    value_micros, value_micros, btrim(p_idempotency_key), btrim(p_reason),
    p_actor_id, p_grant_id, coalesce(p_metadata_json, '{}'::jsonb)
  ) returning * into existing;
  insert into tongs.accounting_journal_entries(
    event_id, line_number, account_code, user_id, workspace_id,
    beta_credit_grant_id, currency, amount_micros
  ) values
    (p_grant_id, 1, 'beta_promotion_expense', p_user_id, p_workspace_id,
      p_grant_id, 'USD', value_micros),
    (p_grant_id, 2, 'beta_credit_deferred_value', p_user_id, p_workspace_id,
      p_grant_id, 'USD', -value_micros);
  insert into tongs.accounting_journal_entries(
    event_id, line_number, account_code, user_id, workspace_id,
    beta_credit_grant_id, unit_kind, quantity_delta
  ) values (
    p_grant_id, 3, 'beta_forge_credit_units', p_user_id, p_workspace_id,
    p_grant_id, 'forge_credit', p_credit_units
  );
  perform tongs._assert_accounting_event_balanced(p_grant_id);
  return to_jsonb(existing) || jsonb_build_object('replay', false);
end $$;


ALTER FUNCTION "tongs"."provision_beta_test_credits"("p_grant_id" "uuid", "p_actor_id" "uuid", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_credit_units" bigint, "p_idempotency_key" "text", "p_reason" "text", "p_metadata_json" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."provision_beta_test_credits"("p_grant_id" "uuid", "p_actor_id" "uuid", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_credit_units" bigint, "p_idempotency_key" "text", "p_reason" "text", "p_metadata_json" "jsonb") IS 'Idempotently provisions an operator-approved quantity of canonical Test Forge Credits for a beta account.';



CREATE OR REPLACE FUNCTION "tongs"."publish_private_pricing_revision"("p_publication_id" "uuid", "p_pricing_revision_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_pricing tongs.private_pricing_revisions%rowtype;
  v_existing tongs.private_pricing_publications%rowtype;
  v_publication_revision integer;
begin
  if v_actor is null or not tongs.is_platform_operator(v_actor) then
    raise exception 'platform operator required' using errcode = '42501';
  end if;
  if p_publication_id is null or nullif(btrim(coalesce(p_reason, '')), '') is null then
    raise exception 'invalid pricing publication' using errcode = '22023';
  end if;
  select * into v_pricing from tongs.private_pricing_revisions where id = p_pricing_revision_id;
  if not found or v_pricing.lifecycle_state <> 'review_ready' then
    raise exception 'review-ready pricing revision required' using errcode = 'P0001';
  end if;
  if not exists (select 1 from tongs.private_pricing_revision_markup_sources
      where pricing_revision_id = v_pricing.id)
     or exists (select 1 from tongs.private_pricing_cost_components component
      where component.pricing_revision_id = v_pricing.id
        and component.tail_policy = 'recurring_metered') then
    raise exception 'pricing revision has an unpriced or recurring cost tail' using errcode = 'P0001';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('pricing-publication:' || v_pricing.policy_id::text, 0));
  select * into v_existing from tongs.private_pricing_publications where id = p_publication_id;
  if found then
    return jsonb_build_object('publication_id', v_existing.id,
      'publication_revision', v_existing.publication_revision, 'replay', true);
  end if;
  select coalesce(max(publication_revision), 0) + 1 into v_publication_revision
  from tongs.private_pricing_publications where policy_id = v_pricing.policy_id;
  insert into tongs.private_pricing_publications(
    id, policy_id, pricing_revision_id, publication_revision, action, reason, actor_id
  ) values (
    p_publication_id, v_pricing.policy_id, v_pricing.id, v_publication_revision,
    'published', btrim(p_reason), v_actor
  );
  return jsonb_build_object('publication_id', p_publication_id,
    'pricing_revision_id', v_pricing.id, 'publication_revision', v_publication_revision,
    'replay', false, 'customer_spending_enabled', false);
end;
$$;


ALTER FUNCTION "tongs"."publish_private_pricing_revision"("p_publication_id" "uuid", "p_pricing_revision_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."publishing_destination_grant_is_active"("p_workspace_id" "uuid", "p_destination_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
  select exists(
    select 1
    from tongs.publishing_workspace_destination_grant_heads h
    join tongs.publishing_workspace_destination_grant_revisions r on r.id = h.current_grant_revision_id
    join tongs.publishing_executable_destinations d on d.id = h.executable_destination_id
    join tongs.publishing_provider_connections c on c.id = d.connection_id
    join tongs.publishing_provider_credential_authorities ca on ca.id = c.credential_authority_id
    where h.workspace_id = p_workspace_id and h.executable_destination_id = p_destination_id
      and r.state = 'active'
      and d.state = 'active'
      and d.current_capability_revision_id is not null
      and c.state = 'active'
      and ca.state = 'available'
      and tongs.has_workspace_role(p_workspace_id, 'viewer')
  );
$$;


ALTER FUNCTION "tongs"."publishing_destination_grant_is_active"("p_workspace_id" "uuid", "p_destination_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."quench_podcast_host_capability_is_compatible"("p_capabilities" "jsonb") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
  select coalesce(p_capabilities->>'provider','')='transistor'
    and coalesce((p_capabilities->>'audio_upload')::boolean,false)
    and coalesce((p_capabilities->>'episode_draft_create')::boolean,false)
    and coalesce((p_capabilities->>'episode_publish')::boolean,false)
    and coalesce((p_capabilities->>'host_owns_rss')::boolean,false)
    and not coalesce((p_capabilities->>'forge_rss_hosting')::boolean,true)
    and not coalesce((p_capabilities->>'direct_spotify_upload')::boolean,true);
$$;


ALTER FUNCTION "tongs"."quench_podcast_host_capability_is_compatible"("p_capabilities" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."quench_release_decision_applicability"("p_decision_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare d tongs.quench_release_decision_revisions%rowtype; s tongs.quench_release_decision_sequences%rowtype; m tongs.quench_release_manifest_snapshots%rowtype;
 f tongs.workpiece_files%rowtype; c tongs.thumbnail_candidate_sets%rowtype; b tongs.workpiece_brand_bindings%rowtype; scope tongs.quench_destination_scopes%rowtype; v_reason text;
begin select * into d from tongs.quench_release_decision_revisions where id=p_decision_id; if not found then return jsonb_build_object('state','blocked','record_posture','historical','reason_codes',jsonb_build_array('decision_not_found')); end if;
 select * into s from tongs.quench_release_decision_sequences where workspace_id=d.workspace_id and workpiece_id=d.workpiece_id and destination_scope_id=d.destination_scope_id;
 if s.current_decision_id is distinct from d.id then return jsonb_build_object('state','superseded','record_posture','historical','reason_codes','[]'::jsonb); end if;
 select * into m from tongs.quench_release_manifest_snapshots where id=d.manifest_snapshot_id;
 select * into f from tongs.workpiece_files where workpiece_id=d.workpiece_id and path=m.source_file_path;
 if m.id is null or f.workpiece_id is null then v_reason:='manifest_unavailable';
 elsif lower(f.hash_value)<>m.manifest_content_hash or f.revision<>m.source_file_revision then return jsonb_build_object('state','requires_review','record_posture','current_revision','reason_codes',jsonb_build_array('manifest_advanced')); end if;
 if v_reason is null then select * into f from tongs.workpiece_files where workpiece_id=d.workpiece_id and path='metadata.json'; if not found then v_reason:='metadata_unavailable'; elsif f.revision<>d.metadata_revision or lower(f.hash_value)<>d.metadata_content_hash then return jsonb_build_object('state','requires_review','record_posture','current_revision','reason_codes',jsonb_build_array('metadata_advanced')); end if; end if;
 select * into b from tongs.workpiece_brand_bindings where workpiece_id=d.workpiece_id order by revision desc limit 1; if b.id is null then v_reason:=coalesce(v_reason,'binding_unavailable'); elsif b.id<>d.active_binding_id then return jsonb_build_object('state','requires_review','record_posture','current_revision','reason_codes',jsonb_build_array('binding_advanced')); end if;
 select * into c from tongs.thumbnail_candidate_sets where workpiece_id=d.workpiece_id order by revision desc limit 1; if c.id is null then v_reason:=coalesce(v_reason,'candidate_set_unavailable'); elsif c.id<>d.candidate_set_id then return jsonb_build_object('state','requires_review','record_posture','current_revision','reason_codes',jsonb_build_array('candidate_set_advanced')); end if;
 select * into scope from tongs.quench_destination_scopes where id=d.destination_scope_id; if scope.id is null or scope.state<>'active' then v_reason:=coalesce(v_reason,'destination_unavailable'); elsif scope.current_capability_revision_id<>d.capability_revision_id then return jsonb_build_object('state','requires_review','record_posture','current_revision','reason_codes',jsonb_build_array('capability_advanced')); end if;
 if v_reason is null and exists(select 1 from tongs.quench_release_candidate_assignments a join tongs.thumbnail_candidate_revisions r on r.id=a.candidate_revision_id left join tongs.assets x on x.id=a.composite_asset_id where a.decision_id=d.id and (x.id is null or x.status<>'ready' or x.content_hash<>a.composite_content_hash or tongs.thumbnail_candidate_eligibility(r.id,b.id) not in('current','approved_historical_brand'))) then v_reason:='candidate_verification_blocked'; end if;
 if v_reason is not null then return jsonb_build_object('state','blocked','record_posture','current_revision','reason_codes',jsonb_build_array(v_reason)); end if;
 return jsonb_build_object('state','current','record_posture','current_revision','reason_codes','[]'::jsonb); end $$;


ALTER FUNCTION "tongs"."quench_release_decision_applicability"("p_decision_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."quote_owner_hearth_research_operation"("p_owner_user_id" "uuid", "p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_request_fingerprint" "text", "p_plan_json" "jsonb", "p_requested_provider_model_id" "text", "p_expires_at" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $_$
declare a tongs.owner_hearth_research_authorizations%rowtype; term tongs.owner_hearth_research_model_terms%rowtype;
 qid uuid:=gen_random_uuid(); op text; qhash text; price tongs.private_pricing_revisions%rowtype; held bigint; consumed bigint;
 accepted_count bigint; storage_amount bigint; search_amount bigint; direct_amount bigint;
begin
 perform tongs._require_pricing_service_role();
 if p_request_fingerprint!~'^[0-9a-f]{64}$' or jsonb_typeof(p_plan_json)<>'object' or p_plan_json->>'schema'<>'forge.hearth.owner-research-plan.v1'
  or p_plan_json->>'route_code'<>'hearth.research_synthesis' or (p_plan_json->>'workspace_id')::uuid<>p_workspace_id
  or (p_plan_json->>'workpiece_id')::uuid<>p_workpiece_id
  or p_expires_at<=now() or p_expires_at>now()+interval '11 minutes' then raise exception 'invalid bounded research plan' using errcode='22023'; end if;
 a:=tongs._owner_hearth_research_latest_authorization(p_owner_user_id,p_workspace_id);
 if a.id is null then raise exception 'owner research authorization is not active' using errcode='42501'; end if;
 if p_plan_json->>'limit_profile'<>a.limit_profile or (p_plan_json->>'maximum_search_requests')::int<>a.maximum_searches
  or (p_plan_json->>'maximum_sources')::int<>a.maximum_sources or (p_plan_json->>'maximum_http_attempts')::int<>a.maximum_http_attempts
  or (p_plan_json->>'maximum_input_tokens')::bigint<>a.maximum_input_tokens or (p_plan_json->>'maximum_output_tokens')::bigint<>a.maximum_output_tokens
  then raise exception 'research plan does not match immutable authorization profile' using errcode='22023'; end if;
 select t.* into term from tongs.owner_hearth_research_model_terms t where t.authorization_id=a.id
  and (nullif(btrim(coalesce(p_requested_provider_model_id,'')),'') is null or t.provider_model_id=btrim(p_requested_provider_model_id))
  and (a.authorization_kind<>'canary' or t.provider_model_id='gpt-6-astra')
  order by t.ordinal limit 1;
 if term.authorization_id is null then raise exception 'requested owner research model is unavailable' using errcode='42501'; end if;
 if a.authorization_kind='canary' and coalesce(nullif(btrim(p_requested_provider_model_id),''),'gpt-6-astra')<>'gpt-6-astra'
  then raise exception 'canary requires GPT-6 Astra' using errcode='42501'; end if;
 direct_amount:=((a.maximum_input_tokens*term.input_micros_per_million_tokens+999999)/1000000)
  +((a.maximum_output_tokens*term.output_micros_per_million_tokens+999999)/1000000);
 search_amount:=a.maximum_searches*5000;
 select * into price from tongs.private_pricing_revisions where id=term.pricing_revision_id;
 select coalesce(sum(c.expense_amount_micros),0) into consumed from tongs.owner_operating_budget_consumptions c where c.budget_id=a.budget_id;
 select coalesce(sum(r.reserved_wholesale_spend_micros),0) into held from tongs.funding_reservations r where r.funding_source_type='owner_budget' and r.funding_source_id=a.budget_id
  and tongs._funding_reservation_state(r.id) not in('settled','released');
 select count(*) into accepted_count from tongs.owner_hearth_research_operations o
  join tongs.owner_hearth_research_authorizations oa on oa.id=o.authorization_id where oa.budget_id=a.budget_id;
 if accepted_count>=11 then raise exception 'owner research package limit reached' using errcode='42501'; end if;
 storage_amount:=case when accepted_count<10 then 7616 else 7612 end;
 op:='owner-research:'||qid::text;
 qhash:=encode(extensions.digest(convert_to(jsonb_build_object('quote_id',qid,'operation_id',op,'plan',p_plan_json,'request_fingerprint',p_request_fingerprint,
  'model',term.provider_model_id,'profile',a.limit_profile,'direct',direct_amount,'search',search_amount,'platform',1456,'storage',storage_amount,'customer',0,'expires_at',p_expires_at)::text,'utf8'),'sha256'),'hex');
 insert into tongs.customer_spending_quotes(id,user_id,operation_id,tool,workspace_id,pricing_revision_id,pricing_revision,currency,
  normal_maximum_charge_micros,billable_failure_maximum_charge_micros,customer_credit_units,full_cost_ceiling_micros,billable_failure_classes,
  free_failure_classes,included_quantity,retention_policy,provider_funding_summary,request_fingerprint,quote_hash,expires_at)
 values(qid,p_owner_user_id,op,'hearth.research_synthesis',p_workspace_id,price.id,price.revision,'USD',0,0,0,
  direct_amount+search_amount+1456+storage_amount,'[]','["provider_failure","forge_failure","persistence_failure","unknown_fault"]',
  jsonb_build_object('attempts',1,'profile',a.limit_profile,'searches',a.maximum_searches,'sources',a.maximum_sources,'http_attempts',a.maximum_http_attempts,
   'input_tokens',a.maximum_input_tokens,'output_tokens',a.maximum_output_tokens),
  '{"canonical_package":"retained","recovery_reads":20,"continuing_storage":"separately_bounded"}',
  '[{"component":"openai_synthesis","credential_source":"forge_owner_research_isolated"},{"component":"brave_search","credential_source":"forge_owner_research_isolated"}]',
  p_request_fingerprint,qhash,p_expires_at);
 insert into tongs.owner_hearth_research_quotes values(qid,a.id,p_owner_user_id,p_workspace_id,p_workpiece_id,op,p_request_fingerprint,p_plan_json,
  p_request_fingerprint,term.provider_model_id,direct_amount,search_amount,1456,storage_amount,3,direct_amount+search_amount+1456+storage_amount,qhash,p_expires_at,now());
 return jsonb_build_object('quote_id',qid,'operation_id',op,'quote_hash',qhash,'request_fingerprint',p_request_fingerprint,'currency','USD',
  'maximum_customer_charge_micros',0,'failure_customer_charge_micros',0,'maximum_owner_commitment_micros',direct_amount+search_amount+1456+storage_amount,
  'funding_eligible',consumed+held+direct_amount+search_amount+1456+storage_amount<=a.maximum_amount_micros,'funding_source','owner_budget',
  'funding_label','Owner research budget','model_display_name',term.display_name,'provider_model_id',term.provider_model_id,'catalog_revision',2,
  'expires_at',p_expires_at,'cost_components',jsonb_build_object('openai_synthesis_micros',direct_amount,'brave_search_micros',search_amount,
  'platform_support_micros',1456,'continuing_storage_micros',storage_amount,'aggregate_risk_micros',3),'limits',jsonb_build_object('profile',a.limit_profile,
  'search_requests',a.maximum_searches,'retained_sources',a.maximum_sources,'http_attempts',a.maximum_http_attempts,
  'input_tokens',a.maximum_input_tokens,'output_tokens',a.maximum_output_tokens));
end $_$;


ALTER FUNCTION "tongs"."quote_owner_hearth_research_operation"("p_owner_user_id" "uuid", "p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_request_fingerprint" "text", "p_plan_json" "jsonb", "p_requested_provider_model_id" "text", "p_expires_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."read_account_authority_classification"("p_user_id" "uuid", "p_operator_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
begin
  if coalesce(current_setting('request.jwt.claim.role', true), '') <> 'service_role'
     or p_operator_user_id is null
     or not tongs.is_platform_operator(p_operator_user_id) then
    raise exception 'service-role platform operator required' using errcode = '42501';
  end if;
  return tongs.resolve_account_authority_classification(p_user_id);
end
$$;


ALTER FUNCTION "tongs"."read_account_authority_classification"("p_user_id" "uuid", "p_operator_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."read_account_authority_classification"("p_user_id" "uuid", "p_operator_user_id" "uuid") IS 'Narrow service-role platform-operator inspection path for account authority metadata.';



CREATE TABLE IF NOT EXISTS "tongs"."ai_pricing_policy_revisions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "policy_id" "uuid" NOT NULL,
    "revision" integer NOT NULL,
    "previous_revision_id" "uuid",
    "provider" "text" NOT NULL,
    "model" "text" NOT NULL,
    "media_kind" "text" NOT NULL,
    "generation_mode" "text" NOT NULL,
    "billable_dimensions" "jsonb" NOT NULL,
    "provider_billing_unit" "text" NOT NULL,
    "provider_price_micros_per_unit" bigint NOT NULL,
    "provider_currency" character(3) NOT NULL,
    "forge_credit_conversion_numerator" bigint NOT NULL,
    "forge_credit_conversion_denominator" bigint NOT NULL,
    "markup_numerator" bigint NOT NULL,
    "markup_denominator" bigint NOT NULL,
    "addon_credits" bigint DEFAULT 0 NOT NULL,
    "effective_from" timestamp with time zone NOT NULL,
    "effective_through" timestamp with time zone,
    "is_active" boolean NOT NULL,
    "price_source_type" "text" NOT NULL,
    "price_source_reference" "text" NOT NULL,
    "price_source_version" "text",
    "actor_id" "uuid",
    "content_hash" "text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "pricing_contract_version" "text" DEFAULT 'scalar_v1'::"text" NOT NULL,
    "model_snapshot" "text",
    "endpoint" "text",
    "customer_rounding_rule" "text" DEFAULT 'ceiling_whole_credit'::"text" NOT NULL,
    CONSTRAINT "ai_pricing_compound_identity_check" CHECK ((("pricing_contract_version" <> 'compound_v2'::"text") OR ((NULLIF("btrim"("model_snapshot"), ''::"text") IS NOT NULL) AND (NULLIF("btrim"("endpoint"), ''::"text") IS NOT NULL)))),
    CONSTRAINT "ai_pricing_contract_version_check" CHECK (("pricing_contract_version" = ANY (ARRAY['scalar_v1'::"text", 'compound_v2'::"text"]))),
    CONSTRAINT "ai_pricing_policy_revisions_addon_credits_check" CHECK (("addon_credits" >= 0)),
    CONSTRAINT "ai_pricing_policy_revisions_billable_dimensions_check" CHECK (("jsonb_typeof"("billable_dimensions") = 'object'::"text")),
    CONSTRAINT "ai_pricing_policy_revisions_check" CHECK ((("effective_through" IS NULL) OR ("effective_through" > "effective_from"))),
    CONSTRAINT "ai_pricing_policy_revisions_content_hash_check" CHECK (("length"("content_hash") = 64)),
    CONSTRAINT "ai_pricing_policy_revisions_forge_credit_conversion_denom_check" CHECK (("forge_credit_conversion_denominator" > 0)),
    CONSTRAINT "ai_pricing_policy_revisions_forge_credit_conversion_numer_check" CHECK (("forge_credit_conversion_numerator" > 0)),
    CONSTRAINT "ai_pricing_policy_revisions_markup_denominator_check" CHECK (("markup_denominator" > 0)),
    CONSTRAINT "ai_pricing_policy_revisions_markup_numerator_check" CHECK (("markup_numerator" > 0)),
    CONSTRAINT "ai_pricing_policy_revisions_media_kind_check" CHECK (("media_kind" = ANY (ARRAY['image'::"text", 'video'::"text", 'audio'::"text", 'text'::"text"]))),
    CONSTRAINT "ai_pricing_policy_revisions_price_source_type_check" CHECK (("price_source_type" = ANY (ARRAY['provider_documentation'::"text", 'contracted_rate'::"text", 'canonical_catalog'::"text", 'operator_entered'::"text"]))),
    CONSTRAINT "ai_pricing_policy_revisions_provider_price_micros_per_uni_check" CHECK (("provider_price_micros_per_unit" >= 0)),
    CONSTRAINT "ai_pricing_policy_revisions_revision_check" CHECK (("revision" > 0)),
    CONSTRAINT "ai_pricing_rounding_rule_check" CHECK (("customer_rounding_rule" = 'ceiling_whole_credit'::"text"))
);


ALTER TABLE "tongs"."ai_pricing_policy_revisions" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."read_active_ai_pricing_policies"() RETURNS SETOF "tongs"."ai_pricing_policy_revisions"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
  select r.* from tongs.ai_pricing_policy_revisions r
  join tongs.ai_pricing_policy_sequences s on s.current_revision_id = r.id
  where r.is_active and r.effective_from <= now()
    and (r.effective_through is null or r.effective_through > now())
  order by r.provider, r.model, r.media_kind, r.generation_mode;
$$;


ALTER FUNCTION "tongs"."read_active_ai_pricing_policies"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."read_ai_model_choices"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare uid uuid:=auth.uid(); choices jsonb;
begin
 if uid is null then raise exception 'authentication required' using errcode='28000'; end if;
 select coalesce(jsonb_agg(jsonb_build_object(
   'selection_key',identity.customer_selection_key,
   'display_name',revision.display_name,
   'relative_cost_class',revision.relative_cost_class
 ) order by case revision.relative_cost_class when 'lower_cost' then 1 when 'mid_range_cost' then 2 else 3 end,revision.display_name),'[]'::jsonb)
 into choices
 from tongs.ai_model_identities identity
 join lateral(
   select r.* from tongs.ai_model_identity_revisions r
   where r.model_identity_id=identity.id order by r.revision desc limit 1
 ) revision on revision.lifecycle_state='active'
 join lateral(
   select choice.* from tongs.ai_global_model_choice_revisions choice
   where choice.model_identity_id=identity.id order by choice.revision desc limit 1
 ) global_choice on global_choice.authority_state='selectable';
 return jsonb_build_object('preference',tongs.read_my_ai_model_preference(),'choices',choices);
end $$;


ALTER FUNCTION "tongs"."read_ai_model_choices"() OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."read_ai_model_choices"() IS 'Returns only active identities whose latest global-choice authority is selectable.';



CREATE OR REPLACE FUNCTION "tongs"."read_ai_operation_model_choices"("p_operation_code" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare uid uuid:=auth.uid(); choices jsonb; global_pref jsonb; override_pref jsonb; applicable_key uuid; applicable_source text; applicable_available boolean:=false;
begin
 if uid is null then raise exception 'authentication required' using errcode='28000'; end if;
 global_pref:=tongs.read_my_ai_model_preference(); override_pref:=tongs.read_my_ai_operation_model_override(p_operation_code);
 if override_pref->>'state'='specific' then applicable_key:=(override_pref->>'selection_key')::uuid; applicable_source:='operation_override'; applicable_available:=coalesce((override_pref->>'available')::boolean,false);
 else applicable_source:='global_preference'; if global_pref->>'selection_key' is not null then applicable_key:=(global_pref->>'selection_key')::uuid; select exists(select 1 from tongs._eligible_ai_models_for_operation(p_operation_code)e where e.customer_selection_key=applicable_key) into applicable_available; end if; end if;
 select coalesce(jsonb_agg(jsonb_build_object('selection_key',e.customer_selection_key,'display_name',e.display_name,'relative_cost_class',e.relative_cost_class,'credit_charge',e.customer_credit_units) order by case e.relative_cost_class when 'lower_cost' then 1 when 'mid_range_cost' then 2 else 3 end),'[]'::jsonb) into choices from tongs._eligible_ai_models_for_operation(p_operation_code)e;
 return jsonb_build_object('operation_code',p_operation_code,'global_preference',global_pref,'operation_override',override_pref,'applicable_source',applicable_source,'applicable_selection_key',applicable_key,'applicable_available',applicable_available,'eligible_choices',choices,'executable',applicable_available,'blocker',case when applicable_key is null then 'Choose a preferred AI model.' when not applicable_available and applicable_source='operation_override' then 'Your operation override is no longer eligible. Change or clear it.' when not applicable_available then 'Your preferred AI model is not eligible for this operation. Choose an operation override.' else null end);
end $$;


ALTER FUNCTION "tongs"."read_ai_operation_model_choices"("p_operation_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."read_ai_pricing_policy"("p_pricing_policy_revision_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
  select jsonb_build_object(
    'revision', to_jsonb(r),
    'rate_components', coalesce((
      select jsonb_agg(to_jsonb(c) order by c.ordinal)
      from tongs.ai_pricing_rate_components c where c.pricing_policy_revision_id = r.id
    ), '[]'::jsonb)
  )
  from tongs.ai_pricing_policy_revisions r
  where r.id = p_pricing_policy_revision_id;
$$;


