CREATE OR REPLACE FUNCTION "tongs"."read_broll_prompt_status"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_beat_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare v_seq tongs.broll_prompt_sequences%rowtype; v_prompt tongs.broll_prompt_revisions%rowtype; v_current jsonb; v_inputs jsonb; v_reasons jsonb:='[]'::jsonb;
begin
 if not tongs.has_workspace_role(p_workspace_id,'viewer') then raise exception 'workspace viewer authority required' using errcode='42501'; end if;
 select * into v_seq from tongs.broll_prompt_sequences where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and beat_id=p_beat_id;
 if not found or v_seq.current_prompt_revision_id is null then return jsonb_build_object('status','missing','sequence',coalesce(to_jsonb(v_seq),'null'::jsonb)); end if;
 select * into v_prompt from tongs.broll_prompt_revisions where id=v_seq.current_prompt_revision_id;
 if v_prompt.authority_status<>'verified' then return jsonb_build_object('status','legacy_unverified','sequence',to_jsonb(v_seq),'prompt_revision',to_jsonb(v_prompt),'mismatch_reasons',jsonb_build_array('legacy_prompt_evidence_missing')); end if;
 v_current:=tongs.broll_current_creative_input(p_workspace_id,p_workpiece_id,p_beat_id,v_seq.creator_direction,v_prompt.interpretation_contract_version,v_prompt.synthesis_contract_version);
 if v_current->>'disposition'<>'current' then return jsonb_build_object('status','stale','sequence',to_jsonb(v_seq),'prompt_revision',to_jsonb(v_prompt),'mismatch_reasons',jsonb_build_array(v_current->>'disposition')); end if;
 v_inputs:=v_current->'creative_inputs';
 if v_prompt.script_approval_id is distinct from (v_inputs->>'script_approval_id')::uuid or v_prompt.script_approval_revision is distinct from (v_inputs->>'script_approval_revision')::bigint or v_prompt.script_content_hash is distinct from v_inputs->>'script_content_hash' then v_reasons:=v_reasons||'"script_approval_changed"'::jsonb; end if;
 if jsonb_build_object(
   'before',v_prompt.source_context_json->'before',
   'focus',v_prompt.source_context_json->'focus',
   'after',v_prompt.source_context_json->'after',
   'anchor_assessment',v_prompt.source_context_json->'anchor_assessment'
 ) is distinct from v_inputs->'source_context' then v_reasons:=v_reasons||'"source_context_changed"'::jsonb; end if;
 if v_prompt.creator_direction is distinct from v_inputs->>'creator_direction' then v_reasons:=v_reasons||'"creator_direction_changed"'::jsonb; end if;
 if v_prompt.source_context_json->>'narrative_purpose' is distinct from v_inputs->>'narrative_purpose' then v_reasons:=v_reasons||'"beat_purpose_changed"'::jsonb; end if;
 if v_prompt.source_context_json->>'placement_hint' is distinct from v_inputs->>'placement_hint' then v_reasons:=v_reasons||'"placement_changed"'::jsonb; end if;
 if (v_prompt.source_context_json->>'duration_target_ms')::bigint is distinct from (v_inputs->>'duration_target_ms')::bigint then v_reasons:=v_reasons||'"duration_changed"'::jsonb; end if;
 if v_prompt.source_context_json->>'shot_type' is distinct from v_inputs->>'shot_type' then v_reasons:=v_reasons||'"shot_type_changed"'::jsonb; end if;
 if v_prompt.source_context_json->>'motion_intent' is distinct from v_inputs->>'motion_intent' then v_reasons:=v_reasons||'"motion_intent_changed"'::jsonb; end if;
 if v_prompt.source_context_json->>'pacing' is distinct from v_inputs->>'pacing' then v_reasons:=v_reasons||'"pacing_changed"'::jsonb; end if;
 if v_prompt.creative_input_hash is distinct from v_current->>'creative_input_hash' and jsonb_array_length(v_reasons)=0 then v_reasons:=v_reasons||'"creative_input_changed"'::jsonb; end if;
 return jsonb_build_object('status',case when jsonb_array_length(v_reasons)>0 then 'stale' when v_prompt.prompt_source='creator_edited' then 'creator_edited' else 'current' end,'sequence',to_jsonb(v_seq),'prompt_revision',to_jsonb(v_prompt),'mismatch_reasons',v_reasons,'current_creative_input_hash',v_current->>'creative_input_hash');
end $$;


ALTER FUNCTION "tongs"."read_broll_prompt_status"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_beat_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."read_broll_runway_operation_status"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_operation_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare v_op tongs.broll_operation_receipts%rowtype; v_public_status text;
begin
 if not tongs.has_workspace_role(p_workspace_id,'viewer') then raise exception 'workspace viewer authority required' using errcode='42501'; end if;
 select * into v_op from tongs.broll_operation_receipts
 where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and operation_id=p_operation_id;
 if not found then return jsonb_build_object('disposition','operation_not_found'); end if;
 v_public_status:=case
  when v_op.state='submission_unknown' then 'submission_unknown'
  when v_op.state in('provider_completed','provider_or_upload_completed','video_asset_verified','poster_asset_verified','candidate_committed','selected') then 'completed'
  when v_op.state='failed' then 'failed'
  else 'pending'
 end;
 return jsonb_build_object(
  'disposition','current','operation_id',v_op.operation_id,'state',v_op.state,'status',v_public_status,
  'provider_task_id',v_op.provider_task_id,'submission_attempt_id',v_op.submission_attempt_id,
  'retry_at',v_op.provider_next_poll_at,'failure_code',v_op.failure_code,'failure_message',v_op.failure_message,
  'ambiguity_reason',v_op.ambiguity_reason,'reconciliation_decision',v_op.reconciliation_decision,
  'candidate_revision_id',v_op.result_candidate_revision_id,'receipt_json',v_op.receipt_json
 );
end $$;


ALTER FUNCTION "tongs"."read_broll_runway_operation_status"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_operation_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."read_cleanup_review_basis"("p_actor" "uuid", "p_workspace" "uuid", "p_workpiece" "uuid", "p_revision" "uuid", "p_write" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $_$
declare r tongs.recording_revisions%rowtype; c tongs.canonical_recordings%rowtype; e tongs.episodes%rowtype;
  t tongs.workpiece_files%rowtype; m tongs.workpiece_files%rowtype; h tongs.workpiece_files%rowtype; role_rank integer;
begin
  select case when w.created_by=p_actor then 40 else tongs.workspace_role_rank(wm.role) end into role_rank
    from tongs.workspaces w left join tongs.workspace_members wm on wm.workspace_id=w.id and wm.user_id=p_actor where w.id=p_workspace;
  if p_actor is null or coalesce(role_rank,0)<(case when p_write then 20 else 10 end) then raise exception 'cleanup_review_forbidden' using errcode='42501'; end if;
  -- Lock order: revision, episode, recording, then registry paths lexically.
  select * into r from tongs.recording_revisions where id=p_revision and workspace_id=p_workspace and workpiece_id=p_workpiece for update;
  select * into e from tongs.episodes where id=p_workpiece and workspace_id=p_workspace for share;
  if r.id is null or e.id is null or r.status is distinct from 'active' or e.active_revision_id is distinct from r.id or e.canonical_recording_id is distinct from r.canonical_recording_id then
    raise exception 'cleanup_review_identity_conflict' using errcode='40001'; end if;
  select * into c from tongs.canonical_recordings where id=r.canonical_recording_id and workpiece_id=p_workpiece and workspace_id=p_workspace for share;
  if c.id is null or c.media_id is null or r.revision_transcript_path is null then raise exception 'cleanup_review_basis_unavailable' using errcode='40001'; end if;
  perform 1 from tongs.workpiece_files where workpiece_id=p_workpiece and path in(r.revision_transcript_path,c.media_path,r.history_path) order by path for share;
  select * into t from tongs.workpiece_files where workpiece_id=p_workpiece and path=r.revision_transcript_path;
  select * into m from tongs.workpiece_files where workpiece_id=p_workpiece and path=c.media_path;
  select * into h from tongs.workpiece_files where workpiece_id=p_workpiece and path=r.history_path;
  if t.workpiece_id is null or m.workpiece_id is null or t.hash_value is null or m.hash_value is null or t.bytes is null or m.bytes is null
    or t.storage_key is null or m.storage_key is null or t.updated_at is null or m.updated_at is null
    or lower(t.hash_value)!~'^[0-9a-f]{64}$' or lower(m.hash_value)!~'^[0-9a-f]{64}$'
    or t.hash_algo is distinct from 'sha256' or m.hash_algo is distinct from 'sha256' or t.content_type is distinct from 'application/json' or t.bytes<=0 or t.bytes>2097152 or m.bytes<=0
    or t.storage_bucket is distinct from 'forge-workpieces' or m.storage_bucket is distinct from 'forge-workpieces'
    or (r.history_path is not null and h.workpiece_id is null) then raise exception 'cleanup_review_evidence_unavailable' using errcode='40001'; end if;
  return jsonb_build_object('workspace_id',p_workspace,'workpiece_id',p_workpiece,'canonical_recording_id',c.id,'recording_revision_id',r.id,
    'media_id',c.media_id,'revision_updated_at',r.updated_at::text,'media_path',c.media_path,'history_path',r.history_path,
    'transcript',to_jsonb(t),'media',to_jsonb(m),'history',case when h.workpiece_id is null then null else to_jsonb(h) end);
end $_$;


ALTER FUNCTION "tongs"."read_cleanup_review_basis"("p_actor" "uuid", "p_workspace" "uuid", "p_workpiece" "uuid", "p_revision" "uuid", "p_write" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."read_credential_lifecycle_execution_gate"("p_configuration_variable_name" "text", "p_financial_environment" "text", "p_runtime_environment" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_row tongs.credential_lifecycle_records%rowtype;
  v_allowed boolean;
begin
  perform tongs._require_credential_lifecycle_writer();
  select * into v_row from tongs.credential_lifecycle_records
  where configuration_variable_name=btrim(p_configuration_variable_name)
    and financial_environment=p_financial_environment
    and runtime_environment=p_runtime_environment
  order by
    case
      when lifecycle_status in ('active','rotation_due')
       and activated_at is not null
       and (expires_at is null or expires_at > statement_timestamp()) then 0
      else 1
    end,
    activated_at desc nulls last,
    credential_id desc
  limit 1;
  if not found then
    return jsonb_build_object('tracked',false,'allowed',true,'status','untracked');
  end if;
  v_allowed := v_row.lifecycle_status in ('active','rotation_due')
    and v_row.activated_at is not null
    and (v_row.expires_at is null or v_row.expires_at > statement_timestamp());
  return jsonb_build_object(
    'tracked',true,
    'allowed',v_allowed,
    'status',v_row.lifecycle_status,
    'credential_id',v_row.credential_id,
    'expires_at',v_row.expires_at,
    'rotation_due_at',v_row.rotation_due_at
  );
end;
$$;


ALTER FUNCTION "tongs"."read_credential_lifecycle_execution_gate"("p_configuration_variable_name" "text", "p_financial_environment" "text", "p_runtime_environment" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."read_credential_lifecycle_execution_gate"("p_configuration_variable_name" "text", "p_financial_environment" "text", "p_runtime_environment" "text") IS 'Service-only fail-closed status for tracked credentials. It never resolves, returns, or falls back to another credential.';



CREATE OR REPLACE FUNCTION "tongs"."read_credential_lifecycle_report"("p_as_of" timestamp with time zone DEFAULT "now"(), "p_only_actionable" boolean DEFAULT false) RETURNS SETOF "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
begin
  perform tongs._require_credential_lifecycle_reader();
  return query
  select jsonb_build_object(
    'credential_id',record.credential_id,
    'provider',record.provider,
    'purpose',record.credential_purpose,
    'configuration_variable_name',record.configuration_variable_name,
    'affected_capability',record.affected_capability,
    'financial_environment',record.financial_environment,
    'runtime_environment',record.runtime_environment,
    'status',record.lifecycle_status,
    'activated_at',record.activated_at,
    'expires_at',record.expires_at,
    'rotation_due_at',record.rotation_due_at,
    'days_remaining',case when record.expires_at is null then null else ceil(extract(epoch from (record.expires_at-coalesce(p_as_of,now())))/86400.0)::integer end,
    'urgency',case when record.expires_at is null then null
      when coalesce(p_as_of,now())>=record.expires_at then 'expired'
      when record.expires_at-coalesce(p_as_of,now())<=interval '1 day' then 'critical'
      when record.expires_at-coalesce(p_as_of,now())<=interval '3 days' then 'urgent'
      when coalesce(p_as_of,now())>=record.rotation_due_at then 'warning' else null end,
    'replacement_credential_id',record.replacement_credential_id,
    'revocation_required',record.revocation_required,
    'revocation_confirmed_at',record.revocation_confirmed_at,
    'activation_deployment_id',record.activation_deployment_id,
    'activation_deployment_sha',record.activation_deployment_sha,
    'last_verification_at',record.last_verification_at,
    'verification',jsonb_build_object(
      'config_presence_verified_at',record.config_presence_verified_at,
      'route_configuration_verified_at',record.route_configuration_verified_at,
      'non_paid_readiness_verified_at',record.non_paid_readiness_verified_at,
      'bounded_smoke_performed_at',record.bounded_smoke_performed_at,
      'smoke_operation_id',record.smoke_operation_id
    ),
    'recommended_action',case
      when record.lifecycle_status in ('expired','revoked','disabled') then 'Keep the affected capability fail-closed until an active replacement is verified.'
      when record.expires_at is not null and coalesce(p_as_of,now())>=record.rotation_due_at then 'Create a replacement externally; update canonical production config; verify presence, isolation, and non-paid readiness; run a bounded smoke only with approval; revoke the old key; record the new expiration.'
      else null end,
    'codex_handoff',jsonb_build_object(
      'steps',jsonb_build_array(
        'create replacement key at provider','update canonical production variable',
        'verify production presence','verify dependent route isolation',
        'verify old and new credential identities','run non-paid readiness verification',
        'perform bounded smoke only if explicitly approved','revoke old provider key',
        'confirm replacement expiration','update lifecycle record'
      )
    )
  )
  from tongs.credential_lifecycle_records record
  where not coalesce(p_only_actionable,false)
     or record.lifecycle_status in ('rotation_due','replacement_ready','replacement_active','revocation_pending','expired')
     or (record.expires_at is not null and coalesce(p_as_of,now())>=record.rotation_due_at)
  order by record.expires_at asc nulls last, record.provider, record.credential_purpose;
end;
$$;


ALTER FUNCTION "tongs"."read_credential_lifecycle_report"("p_as_of" timestamp with time zone, "p_only_actionable" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."read_credit_pack_purchase_availability"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  caller_role text := coalesce(auth.role(), '');
  environment_name text;
  revision_row tongs.customer_product_availability_revisions%rowtype;
begin
  if caller_role not in ('authenticated', 'service_role') then
    raise exception 'authentication required' using errcode = '42501';
  end if;
  environment_name := tongs._current_financial_environment();
  select * into revision_row
  from tongs.customer_product_availability_revisions
  where financial_environment = environment_name
    and product_code = 'forge_credit_pack_purchase'
  order by revision desc limit 1;
  if not found then
    return jsonb_build_object(
      'contract_version','forge.product-availability.v1',
      'product_code','forge_credit_pack_purchase',
      'financial_environment',environment_name,
      'purchase_enabled',false,
      'reason_code','financial_environment_inactive'
    );
  end if;
  return jsonb_build_object(
    'contract_version','forge.product-availability.v1',
    'product_code',revision_row.product_code,
    'financial_environment',revision_row.financial_environment,
    'purchase_enabled',revision_row.availability_state = 'enabled',
    'reason_code',revision_row.customer_reason_code,
    'revision',revision_row.revision
  );
end $$;


ALTER FUNCTION "tongs"."read_credit_pack_purchase_availability"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."read_current_broll_plan"("p_workspace_id" "uuid", "p_workpiece_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
select case when not tongs.has_workspace_role(p_workspace_id,'viewer') then null else (
 select jsonb_build_object('sequence',to_jsonb(s),'plan_revision',to_jsonb(p),'beats',coalesce((
   select jsonb_agg(jsonb_build_object(
     'membership',to_jsonb(m),
     'beat_revision',to_jsonb(b),
     'prompt_revision',to_jsonb(pr),
     'selected_candidate_revision',to_jsonb(selected_cr),
     'candidate_revisions',coalesce(candidates.items,'[]'::jsonb)
   ) order by m.ordinal)
   from tongs.broll_plan_beat_membership m
   join tongs.broll_beat_revisions b on b.id=m.beat_revision_id
   left join tongs.broll_prompt_sequences ps on ps.workspace_id=m.workspace_id and ps.workpiece_id=m.workpiece_id and ps.beat_id=m.beat_id
   left join tongs.broll_prompt_revisions pr on pr.id=ps.current_prompt_revision_id
   left join lateral (
     select sel.* from tongs.broll_selections sel
     where sel.workspace_id=m.workspace_id and sel.workpiece_id=m.workpiece_id and sel.beat_id=m.beat_id and sel.plan_revision_id=m.plan_revision_id
     order by sel.revision desc limit 1
   ) sel on true
   left join tongs.broll_candidate_revisions selected_cr on selected_cr.id=sel.candidate_revision_id
   left join lateral (
     select jsonb_agg(jsonb_build_object(
       'candidate_revision',to_jsonb(cr),
       'video_asset',to_jsonb(video_asset),
       'poster_asset',to_jsonb(poster_asset)
     ) order by cr.created_at,cr.revision) as items
     from tongs.broll_candidate_revisions cr
     join tongs.assets video_asset on video_asset.id=cr.asset_id
     left join tongs.assets poster_asset on poster_asset.id=cr.poster_asset_id
     where cr.workspace_id=m.workspace_id and cr.workpiece_id=m.workpiece_id and cr.beat_id=m.beat_id
   ) candidates on true
   where m.plan_revision_id=s.current_plan_revision_id
 ),'[]'::jsonb))
 from tongs.broll_plan_sequences s
 left join tongs.broll_plan_revisions p on p.id=s.current_plan_revision_id
 where s.workspace_id=p_workspace_id and s.workpiece_id=p_workpiece_id
) end
$$;


ALTER FUNCTION "tongs"."read_current_broll_plan"("p_workspace_id" "uuid", "p_workpiece_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."read_current_hearth_preflight_v1"("p_workspace_id" "uuid", "p_workpiece_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare
  v_user uuid:=auth.uid();
  v_report tongs.hearth_editorial_preflight_reports%rowtype;
  v_file tongs.workpiece_files%rowtype;
  v_research tongs.hearth_research_artifact_revisions%rowtype;
  v_review tongs.hearth_preflight_review_receipts%rowtype;
  v_stale text[]:='{}';
  v_report_hash text;
  v_projection_hash text;
  v_finding_count int;
begin
  if v_user is null or not tongs.has_workspace_role(p_workspace_id,'viewer') then
    return jsonb_build_object('disposition','denied');
  end if;
  select r.* into v_report
  from tongs.hearth_editorial_preflight_reports r
  join tongs.workpiece_hearth_preflight_sequences s on s.current_report_id=r.id
  where s.workspace_id=p_workspace_id
    and s.workpiece_id=p_workpiece_id
    and s.current_revision=r.revision;
  if not found then
    if exists(
      select 1 from tongs.workpiece_hearth_preflight_sequences
      where workspace_id=p_workspace_id
        and workpiece_id=p_workpiece_id
        and current_report_id is not null
    ) then
      return jsonb_build_object('disposition','integrity_error','reason','current_pointer_mismatch');
    end if;
    return jsonb_build_object('disposition','empty','report',null);
  end if;
  v_report_hash:=encode(extensions.digest(convert_to(v_report.report_json::text,'UTF8'),'sha256'),'hex');
  v_projection_hash:=encode(extensions.digest(convert_to(coalesce(v_report.report_json->'findings','[]'::jsonb)::text,'UTF8'),'sha256'),'hex');
  v_finding_count:=jsonb_array_length(coalesce(v_report.report_json->'findings','[]'::jsonb));
  if v_report_hash<>v_report.report_content_hash then
    return jsonb_build_object('disposition','integrity_error','reason','canonical_report_hash_mismatch');
  end if;
  if v_projection_hash<>v_report.projection_content_hash
    or (select count(*) from tongs.hearth_editorial_preflight_findings where report_id=v_report.id)<>v_finding_count then
    return jsonb_build_object('disposition','integrity_error','reason','finding_projection_count_mismatch');
  end if;
  if exists(
    select 1
    from tongs.hearth_editorial_preflight_findings f
    cross join lateral (select (v_report.report_json->'findings')->f.ordinal item) j
    where f.report_id=v_report.id
      and (
        j.item is null
        or f.content_hash<>encode(extensions.digest(convert_to(j.item::text,'UTF8'),'sha256'),'hex')
        or f.finding_key is distinct from coalesce(nullif(j.item->>'id',''),'finding-'||f.ordinal::text)
        or f.finding_code is distinct from coalesce(nullif(j.item->>'code',''),'unknown')
        or f.severity is distinct from coalesce(nullif(j.item->>'severity',''),'warning')
        or f.category is distinct from coalesce(nullif(j.item->>'category',''),'editorial')
        or f.message is distinct from coalesce(nullif(j.item->>'message',''),'Unspecified producer finding.')
        or f.finding_basis_hash<>tongs.hearth_preflight_finding_basis_hash(j.item)
      )
  ) then
    return jsonb_build_object('disposition','integrity_error','reason','finding_projection_mismatch');
  end if;
  select * into v_file
  from tongs.workpiece_files
  where workpiece_id=p_workpiece_id and path=v_report.source_file_path;
  if not found or lower(v_file.hash_value)<>v_report.script_content_hash then
    v_stale:=array_append(v_stale,'script_changed');
  end if;
  if v_report.research_artifact_id is not null then
    select r.* into v_research
    from tongs.hearth_research_artifact_revisions r
    join tongs.workpiece_hearth_research_sequences s on s.current_artifact_id=r.id
    where s.workspace_id=p_workspace_id and s.workpiece_id=p_workpiece_id;
    if not found
      or v_research.id<>v_report.research_artifact_id
      or v_research.artifact_content_hash<>v_report.research_artifact_hash then
      v_stale:=array_append(v_stale,'research_changed');
    end if;
  end if;
  select * into v_review
  from tongs.hearth_preflight_review_receipts
  where report_id=v_report.id;
  return jsonb_build_object(
    'disposition',case when cardinality(v_stale)>0 then 'stale' else 'current' end,
    'stale_reasons',to_jsonb(v_stale),
    'report',to_jsonb(v_report),
    'review',case when v_review.id is null then null else to_jsonb(v_review) end,
    'findings',(
      select coalesce(jsonb_agg(
        to_jsonb(current_finding) || jsonb_build_object(
          'latest_action',(
            select a.action
            from tongs.hearth_preflight_finding_acknowledgements a
            join tongs.hearth_editorial_preflight_findings prior_finding
              on prior_finding.report_id=a.report_id
              and prior_finding.ordinal=a.finding_ordinal
            join tongs.hearth_editorial_preflight_reports prior_report
              on prior_report.id=prior_finding.report_id
            where prior_report.workspace_id=v_report.workspace_id
              and prior_report.workpiece_id=v_report.workpiece_id
              and prior_report.script_content_hash=v_report.script_content_hash
              and prior_report.checker_contract_version=v_report.checker_contract_version
              and prior_finding.finding_basis_hash=current_finding.finding_basis_hash
            order by case when a.action='resolve' then 1 else 0 end desc, a.acted_at desc
            limit 1
          )
        ) order by current_finding.ordinal
      ),'[]')
      from tongs.hearth_editorial_preflight_findings current_finding
      where current_finding.report_id=v_report.id
    )
  );
end;
$$;


ALTER FUNCTION "tongs"."read_current_hearth_preflight_v1"("p_workspace_id" "uuid", "p_workpiece_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."read_current_hearth_research_artifact_v1"("p_workspace_id" "uuid", "p_workpiece_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare
  v_user uuid:=auth.uid();
  v_seq tongs.workpiece_hearth_research_sequences%rowtype;
  v_row tongs.hearth_research_artifact_revisions%rowtype;
  v_hash text;v_projection_hash text;v_creator_count int;v_finding_count int;v_evidence_count int;
begin
  if v_user is null or not tongs.has_workspace_role(p_workspace_id,'viewer') then return jsonb_build_object('disposition','denied');end if;
  select * into v_seq from tongs.workpiece_hearth_research_sequences where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id;
  if not found or v_seq.current_artifact_id is null then return jsonb_build_object('disposition','empty','artifact',null);end if;
  select * into v_row from tongs.hearth_research_artifact_revisions where id=v_seq.current_artifact_id and workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and revision=v_seq.current_revision;
  if not found then return jsonb_build_object('disposition','integrity_error','reason','current_pointer_mismatch');end if;
  v_hash:=encode(extensions.digest(convert_to(v_row.artifact_json::text,'UTF8'),'sha256'),'hex');
  v_projection_hash:=encode(extensions.digest(convert_to(jsonb_build_object('claims',coalesce(v_row.artifact_json#>'{result,creatorClaims}','[]'::jsonb),'findings',coalesce(v_row.artifact_json#>'{result,artifact,findings}','[]'::jsonb),'evidence',coalesce(v_row.artifact_json#>'{result,evidence}','[]'::jsonb))::text,'UTF8'),'sha256'),'hex');
  if v_hash<>v_row.artifact_content_hash then return jsonb_build_object('disposition','integrity_error','reason','canonical_json_hash_mismatch');end if;
  if v_projection_hash<>v_row.projection_content_hash then return jsonb_build_object('disposition','integrity_error','reason','projection_hash_mismatch');end if;
  v_creator_count:=jsonb_array_length(coalesce(v_row.artifact_json#>'{result,creatorClaims}','[]'::jsonb));
  v_finding_count:=jsonb_array_length(coalesce(v_row.artifact_json#>'{result,artifact,findings}','[]'::jsonb));
  v_evidence_count:=jsonb_array_length(coalesce(v_row.artifact_json#>'{result,evidence}','[]'::jsonb));
  if (select count(*) from tongs.hearth_research_artifact_claims where artifact_id=v_row.id)<>v_creator_count+v_finding_count
    or (select count(*) from tongs.hearth_research_evidence_snapshots where artifact_id=v_row.id)<>v_evidence_count then
    return jsonb_build_object('disposition','integrity_error','reason','projection_count_mismatch');
  end if;
  if exists(
    select 1 from tongs.hearth_research_artifact_claims c
    cross join lateral (select case when c.ordinal<v_creator_count then (v_row.artifact_json#>'{result,creatorClaims}')->c.ordinal else (v_row.artifact_json#>'{result,artifact,findings}')->(c.ordinal-v_creator_count) end item) j
    where c.artifact_id=v_row.id and (
      j.item is null
      or c.content_hash<>encode(extensions.digest(convert_to(j.item::text,'UTF8'),'sha256'),'hex')
      or c.claim_text is distinct from j.item->>'text'
      or c.source_ids is distinct from array(select jsonb_array_elements_text(coalesce(j.item->'sourceIds','[]'::jsonb)))
      or (c.ordinal<v_creator_count and (c.claim_key is distinct from coalesce(nullif(j.item->>'claimId',''),'creator-'||c.ordinal::text)
        or c.claim_kind is distinct from j.item->>'claimKind'
        or c.provenance_status is distinct from coalesce(j.item->>'provenanceStatus','creator_supplied_unverified')
        or c.claim_scope is distinct from coalesce(j.item->>'scope','current_subject')))
    )
  ) then return jsonb_build_object('disposition','integrity_error','reason','claim_projection_mismatch');end if;
  if exists(
    select 1 from tongs.hearth_research_evidence_snapshots e
    cross join lateral (select (v_row.artifact_json#>'{result,evidence}')->e.ordinal item) j
    where e.artifact_id=v_row.id and (
      j.item is null
      or e.content_hash<>encode(extensions.digest(convert_to(j.item::text,'UTF8'),'sha256'),'hex')
      or e.evidence_key is distinct from coalesce(nullif(j.item->>'evidenceId',''),'evidence-'||e.ordinal::text)
      or e.source_id is distinct from j.item->>'sourceId'
      or e.evidence_state is distinct from coalesce(j.item->>'state','inaccessible')
      or e.authority is distinct from coalesce(j.item->>'authority','unassessed')
      or e.excerpt is distinct from j.item->>'excerpt'
    )
  ) then return jsonb_build_object('disposition','integrity_error','reason','evidence_projection_mismatch');end if;
  if exists(
    select 1 from tongs.hearth_research_claim_evidence ce
    join tongs.hearth_research_artifact_claims c on c.artifact_id=ce.artifact_id and c.ordinal=ce.claim_ordinal
    join tongs.hearth_research_evidence_snapshots e on e.artifact_id=ce.artifact_id and e.ordinal=ce.evidence_ordinal
    where ce.artifact_id=v_row.id and (not e.source_id=any(c.source_ids) or ce.relationship is distinct from case when e.evidence_state='inaccessible' then 'inaccessible_only' when c.provenance_status='conflicting' then 'conflicts' when c.provenance_status='reported_by_accessible_secondary' then 'reports' else 'supports' end)
  ) or exists(
    select 1 from tongs.hearth_research_artifact_claims c join tongs.hearth_research_evidence_snapshots e on e.artifact_id=c.artifact_id and e.source_id=any(c.source_ids)
    where c.artifact_id=v_row.id and not exists(select 1 from tongs.hearth_research_claim_evidence ce where ce.artifact_id=c.artifact_id and ce.claim_ordinal=c.ordinal and ce.evidence_ordinal=e.ordinal)
  ) then return jsonb_build_object('disposition','integrity_error','reason','claim_evidence_projection_mismatch');end if;
  return jsonb_build_object('disposition','current','artifact',to_jsonb(v_row),'claims',(select coalesce(jsonb_agg(to_jsonb(c) order by ordinal),'[]') from tongs.hearth_research_artifact_claims c where c.artifact_id=v_row.id),'evidence',(select coalesce(jsonb_agg(to_jsonb(e) order by ordinal),'[]') from tongs.hearth_research_evidence_snapshots e where e.artifact_id=v_row.id));
end;$$;


ALTER FUNCTION "tongs"."read_current_hearth_research_artifact_v1"("p_workspace_id" "uuid", "p_workpiece_id" "uuid") OWNER TO "postgres";


