CREATE OR REPLACE FUNCTION "tongs"."read_current_visual_source_attributions"("p_workspace_id" "uuid", "p_workpiece_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
 select case when not tongs.has_workspace_role(p_workspace_id,'viewer')then null else coalesce(jsonb_agg(jsonb_build_object('attribution_revision',to_jsonb(a),'sources',coalesce((select jsonb_agg(jsonb_build_object('ordinal',m.ordinal,'role',m.role,'source_revision_id',m.source_revision_id,'workpiece_source_link_revision_id',m.workpiece_source_link_revision_id,'title',s.title,'publisher',s.publisher,'source_type',s.source_type,'canonical_url',s.canonical_url)order by m.ordinal)from tongs.visual_source_attribution_members m join tongs.source_revisions s on s.id=m.source_revision_id where m.attribution_revision_id=a.id),'[]'::jsonb))order by a.artifact_family,a.opportunity_id),'[]'::jsonb)end
 from tongs.visual_source_attribution_revisions a where a.workspace_id=p_workspace_id and a.workpiece_id=p_workpiece_id and a.revision=(select max(x.revision)from tongs.visual_source_attribution_revisions x where x.workspace_id=a.workspace_id and x.workpiece_id=a.workpiece_id and x.artifact_family=a.artifact_family and x.opportunity_id=a.opportunity_id)
$$;


ALTER FUNCTION "tongs"."read_current_visual_source_attributions"("p_workspace_id" "uuid", "p_workpiece_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."read_customer_paid_execution_test_authorizations"("p_limit" integer DEFAULT 50) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare v_actor uuid:=auth.uid();
begin
  if v_actor is null or not tongs.is_platform_operator(v_actor) then
    raise exception 'platform operator required' using errcode='42501';
  end if;
  return coalesce((
    select jsonb_agg(to_jsonb(row_data) order by row_data.created_at desc)
    from (
      select a.id,a.user_id,a.workspace_id,
        a.route_code,a.provider,a.model,
        a.pricing_revision_id,a.cost_policy_revision_id,
        a.maximum_operation_count,a.maximum_customer_charge_micros,
        a.authorization_expires_at,latest.status,
        binding.quote_id,reservation.id as reservation_id,
        case when reservation.id is null then null else tongs._funding_reservation_state(reservation.id) end as reservation_state,
        a.created_at
      from tongs.customer_paid_execution_test_authorizations a
      join lateral (
        select revision.status from tongs.customer_paid_execution_test_authorization_revisions revision
        where revision.authorization_id=a.id order by revision.revision desc limit 1
      ) latest on true
      left join tongs.customer_paid_execution_test_authorization_quotes binding
        on binding.authorization_id=a.id
      left join tongs.funding_reservations reservation on reservation.quote_id=binding.quote_id
      order by a.created_at desc limit greatest(1,least(coalesce(p_limit,50),250))
    ) row_data
  ),'[]'::jsonb);
end $$;


ALTER FUNCTION "tongs"."read_customer_paid_execution_test_authorizations"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."read_customer_test_billing"("p_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare v_user uuid; v_base jsonb; v_receipts jsonb;
begin
  if coalesce(auth.role(),'')='service_role' then v_user:=p_user_id; else v_user:=auth.uid(); end if;
  if v_user is null or (coalesce(auth.role(),'')<>'service_role' and p_user_id is not null and p_user_id<>v_user) then raise exception 'customer required' using errcode='42501'; end if;
  v_base:=tongs._read_customer_test_billing_before_openai_text_certification(v_user);
  select coalesce(jsonb_agg(jsonb_build_object('operation_id',r.operation_id,'route_code',o.route_code,'customer_charge_micros',s.customer_charge_micros,'outcome',s.outcome,'failure_class',s.failure_class,'settled_at',s.settled_at,'execution_kind','simulated_test','certification',true) order by s.settled_at desc),'[]'::jsonb) into v_receipts
  from tongs.openai_text_test_certification_reservations r join tongs.openai_text_test_certification_operations o on o.id=r.operation_record_id join tongs.openai_text_test_certification_settlements s on s.reservation_id=r.id where r.user_id=v_user;
  return jsonb_set(v_base,'{receipts}',v_receipts||coalesce(v_base->'receipts','[]'::jsonb),true)||jsonb_build_object('contract_version','forge.customer-test-billing.v2');
end $$;


ALTER FUNCTION "tongs"."read_customer_test_billing"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."read_existing_openai_text_funding_handle"("p_user_id" "uuid", "p_operation_id" "text", "p_route_code" "text", "p_request_fingerprint" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_binding tongs.openai_text_funding_bindings%rowtype;
  v_res tongs.funding_reservations%rowtype;
  v_quote_binding tongs.openai_text_customer_quote_bindings%rowtype;
begin
  perform tongs._require_pricing_service_role();

  select * into v_binding
  from tongs.openai_text_funding_bindings
  where operation_id = btrim(p_operation_id)
    and route_code = p_route_code;
  if not found then
    return null;
  end if;

  select * into v_res
  from tongs.funding_reservations
  where id = v_binding.reservation_id;

  select * into v_quote_binding
  from tongs.openai_text_customer_quote_bindings
  where quote_id = v_res.quote_id;

  if not found
    or v_res.id is null
    or v_res.funding_environment not in ('test', 'live', 'owner_internal')
    or v_quote_binding.user_id <> p_user_id
    or v_quote_binding.request_fingerprint <> p_request_fingerprint then
    raise exception 'existing funding context mismatch' using errcode = '42501';
  end if;

  return jsonb_build_object(
    'operation_id', v_binding.operation_id,
    'reservation_id', v_binding.reservation_id,
    'request_fingerprint', v_quote_binding.request_fingerprint,
    'funding_environment', v_res.funding_environment,
    'reservation_state', tongs._funding_reservation_state(v_binding.reservation_id)
  );
end $$;


ALTER FUNCTION "tongs"."read_existing_openai_text_funding_handle"("p_user_id" "uuid", "p_operation_id" "text", "p_route_code" "text", "p_request_fingerprint" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."read_existing_openai_text_funding_handle"("p_user_id" "uuid", "p_operation_id" "text", "p_route_code" "text", "p_request_fingerprint" "text") IS 'Returns the strict immutable paid-execution handle shape for an authorized existing ordinary OpenAI operation, including its bound financial environment.';



CREATE OR REPLACE FUNCTION "tongs"."read_existing_openai_text_test_certification_funding_handle"("p_user_id" "uuid", "p_operation_id" "text", "p_route_code" "text", "p_request_fingerprint" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_operation tongs.openai_text_test_certification_operations%rowtype;
  v_reservation tongs.openai_text_test_certification_reservations%rowtype;
begin
  perform tongs._require_pricing_service_role();

  select * into v_operation
  from tongs.openai_text_test_certification_operations
  where operation_id=btrim(p_operation_id)
    and route_code=btrim(p_route_code);

  if not found then
    return null;
  end if;

  select * into v_reservation
  from tongs.openai_text_test_certification_reservations
  where operation_record_id=v_operation.id;

  if not found
     or v_reservation.user_id<>p_user_id
     or v_operation.request_fingerprint<>lower(btrim(p_request_fingerprint)) then
    raise exception 'existing Test funding context mismatch' using errcode='42501';
  end if;

  return jsonb_build_object(
    'operation_id',v_reservation.operation_id,
    'reservation_id',v_reservation.id,
    'request_fingerprint',v_operation.request_fingerprint,
    'reservation_state',tongs._openai_text_test_certification_reservation_state(v_reservation.id),
    'execution_kind','simulated_test',
    'real_provider_authorized',false
  );
end $$;


