CREATE OR REPLACE FUNCTION "tongs"."read_hearth_chat_paid_result"("p_operation_id" "text", "p_reservation_id" "uuid", "p_user_id" "uuid", "p_request_fingerprint" "text") RETURNS "jsonb"
