CREATE OR REPLACE FUNCTION "tongs"."read_my_accounting_balances"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_user uuid := auth.uid();
  v_live_credits bigint;
  v_test_credits bigint;
  v_legacy_credits bigint;
  v_allowance_units bigint;
  v_liabilities jsonb;
begin
  if v_user is null then raise exception 'authentication required' using errcode = '42501'; end if;
  select coalesce(sum(quantity_delta) filter (where account_code = 'live_customer_credits'), 0),
         coalesce(sum(quantity_delta) filter (where account_code = 'test_customer_credits'), 0),
         coalesce(sum(quantity_delta) filter (where account_code = 'legacy_unverified_credits'), 0),
         coalesce(sum(quantity_delta) filter (where account_code = 'allowance_entitlement_units'), 0)
    into v_live_credits, v_test_credits, v_legacy_credits, v_allowance_units
  from tongs.accounting_journal_entries where user_id = v_user;
  select coalesce(jsonb_agg(jsonb_build_object('currency', currency,
    'prepaid_balance_micros', prepaid_balance_micros, 'allowance_backing_micros', allowance_backing_micros)
    order by currency), '[]'::jsonb) into v_liabilities
  from (
    select currency,
      -coalesce(sum(amount_micros) filter (where account_code = 'customer_prepaid_liability'), 0) as prepaid_balance_micros,
      -coalesce(sum(amount_micros) filter (where account_code = 'allowance_deferred_liability'), 0) as allowance_backing_micros
    from tongs.accounting_journal_entries
    where user_id = v_user and account_code in ('customer_prepaid_liability', 'allowance_deferred_liability')
    group by currency
  ) balances;
  return jsonb_build_object('live', jsonb_build_object('credit_units', v_live_credits,
      'currency_balances', v_liabilities, 'eligible_for_live_funding', true),
    'test', jsonb_build_object('credit_units', v_test_credits, 'eligible_for_live_funding', false),
    'legacy_unverified', jsonb_build_object('credit_units', v_legacy_credits, 'eligible_for_live_funding', false),
    'paid_allowance', jsonb_build_object('entitlement_units', v_allowance_units,
      'execution_enforcement_active', false));
end;
$$;


ALTER FUNCTION "tongs"."read_my_accounting_balances"() OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."read_my_accounting_balances"() IS 'Customer-safe balances derived from append-only events; excludes wholesale costs, fees, revenue, markup, and margin.';



CREATE TABLE IF NOT EXISTS "tongs"."ai_credit_quotes" (
    "id" "uuid" NOT NULL,
    "user_id" "uuid" NOT NULL,
    "operation_id" "text" NOT NULL,
    "tool" "text" NOT NULL,
    "workspace_id" "uuid",
    "workpiece_id" "uuid",
    "provider" "text" NOT NULL,
    "model" "text" NOT NULL,
    "media_kind" "text" NOT NULL,
    "generation_mode" "text" NOT NULL,
    "request_parameters" "jsonb" NOT NULL,
    "requested_output_count" integer NOT NULL,
    "provider_billable_units" bigint NOT NULL,
    "pricing_policy_revision_id" "uuid" NOT NULL,
    "pricing_policy_revision" integer NOT NULL,
    "estimated_provider_expense_micros" bigint NOT NULL,
    "provider_currency" character(3) NOT NULL,
    "customer_credit_charge" bigint NOT NULL,
    "reservation_amount" bigint NOT NULL,
    "request_fingerprint" "text" NOT NULL,
    "effective_at" timestamp with time zone NOT NULL,
    "expires_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "pricing_contract_version" "text" DEFAULT 'scalar_v1'::"text" NOT NULL,
    "estimated_provider_expense_numerator" bigint,
    "estimated_provider_expense_denominator" bigint,
    "maximum_provider_expense_numerator" bigint,
    "maximum_provider_expense_denominator" bigint,
    "estimated_customer_credit_charge" bigint,
    "maximum_customer_credit_charge" bigint,
    "authorization_policy_revision_id" "uuid",
    "authorization_policy_revision" integer,
    "prompt_revision_id" "uuid",
    "prompt_content_hash" "text",
    "prompt_utf8_bytes" integer,
    "known_image_output_tokens" bigint,
    "known_image_output_expense_micros" bigint,
    "authorization_text_contingency_micros" bigint,
    "authorization_provider_expense_basis_micros" bigint,
    "authorized_customer_ceiling" bigint,
    CONSTRAINT "ai_credit_quotes_check" CHECK (("reservation_amount" >= "customer_credit_charge")),
    CONSTRAINT "ai_credit_quotes_check1" CHECK ((("expires_at" IS NULL) OR ("expires_at" > "effective_at"))),
    CONSTRAINT "ai_credit_quotes_compound_exact_shape_check" CHECK ((("pricing_contract_version" <> 'compound_v2'::"text") OR (("estimated_provider_expense_numerator" IS NOT NULL) AND ("estimated_provider_expense_numerator" >= 0) AND ("estimated_provider_expense_denominator" IS NOT NULL) AND ("estimated_provider_expense_denominator" > 0) AND ("maximum_provider_expense_numerator" IS NOT NULL) AND ("maximum_provider_expense_numerator" >= 0) AND ("maximum_provider_expense_denominator" IS NOT NULL) AND ("maximum_provider_expense_denominator" > 0) AND ("estimated_customer_credit_charge" IS NOT NULL) AND ("estimated_customer_credit_charge" >= 0) AND ("maximum_customer_credit_charge" IS NOT NULL) AND ("maximum_customer_credit_charge" >= "estimated_customer_credit_charge") AND ("reservation_amount" >= "maximum_customer_credit_charge")))),
    CONSTRAINT "ai_credit_quotes_contract_version_check" CHECK (("pricing_contract_version" = ANY (ARRAY['scalar_v1'::"text", 'compound_v2'::"text", 'forge.paid-media.quote.v1'::"text"]))),
    CONSTRAINT "ai_credit_quotes_customer_credit_charge_check" CHECK (("customer_credit_charge" >= 0)),
    CONSTRAINT "ai_credit_quotes_estimated_provider_expense_micros_check" CHECK (("estimated_provider_expense_micros" >= 0)),
    CONSTRAINT "ai_credit_quotes_path_b_shape_check" CHECK ((("authorization_policy_revision_id" IS NULL) OR (("media_kind" = 'image'::"text") AND ("authorization_policy_revision" IS NOT NULL) AND ("authorization_policy_revision" > 0) AND ("prompt_content_hash" ~ '^[0-9a-f]{64}$'::"text") AND ("prompt_utf8_bytes" IS NOT NULL) AND (("prompt_utf8_bytes" >= 1) AND ("prompt_utf8_bytes" <= 16384)) AND ("known_image_output_tokens" IS NOT NULL) AND ("known_image_output_tokens" > 0) AND ("known_image_output_expense_micros" IS NOT NULL) AND ("known_image_output_expense_micros" >= 0) AND ("authorization_text_contingency_micros" IS NOT NULL) AND ("authorization_text_contingency_micros" >= 0) AND ("authorization_provider_expense_basis_micros" IS NOT NULL) AND ("authorization_provider_expense_basis_micros" >= "known_image_output_expense_micros") AND ("authorized_customer_ceiling" IS NOT NULL) AND ("authorized_customer_ceiling" > 0) AND ("reservation_amount" = "authorized_customer_ceiling")) OR (("media_kind" = 'video'::"text") AND ("pricing_contract_version" = 'forge.paid-media.quote.v1'::"text") AND ("authorization_policy_revision" IS NOT NULL) AND ("authorization_policy_revision" > 0) AND ("prompt_content_hash" ~ '^[0-9a-f]{64}$'::"text") AND ("prompt_utf8_bytes" IS NOT NULL) AND (("prompt_utf8_bytes" >= 1) AND ("prompt_utf8_bytes" <= 16384)) AND ("known_image_output_tokens" IS NULL) AND ("known_image_output_expense_micros" IS NULL) AND ("authorization_text_contingency_micros" IS NOT NULL) AND ("authorization_text_contingency_micros" >= 0) AND ("authorization_provider_expense_basis_micros" IS NOT NULL) AND ("authorization_provider_expense_basis_micros" >= 0) AND ("authorized_customer_ceiling" IS NOT NULL) AND ("authorized_customer_ceiling" > 0) AND ("customer_credit_charge" = "authorized_customer_ceiling") AND ("estimated_customer_credit_charge" = "authorized_customer_ceiling") AND ("maximum_customer_credit_charge" = "authorized_customer_ceiling") AND ("reservation_amount" = "authorized_customer_ceiling")))),
    CONSTRAINT "ai_credit_quotes_provider_billable_units_check" CHECK (("provider_billable_units" > 0)),
    CONSTRAINT "ai_credit_quotes_request_fingerprint_check" CHECK (("length"("request_fingerprint") = 64)),
    CONSTRAINT "ai_credit_quotes_request_parameters_check" CHECK (("jsonb_typeof"("request_parameters") = 'object'::"text")),
    CONSTRAINT "ai_credit_quotes_requested_output_count_check" CHECK (("requested_output_count" > 0))
);


