CREATE OR REPLACE FUNCTION "tongs"."read_my_ai_funding_options"("p_workspace_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_user uuid := auth.uid();
  v_workspace tongs.workspaces%rowtype;
  v_preference tongs.ai_funding_preference_revisions%rowtype;
  v_org_account tongs.organization_funding_account_revisions%rowtype;
  v_permission tongs.organization_shared_spend_permission_revisions%rowtype;
  v_owner boolean := false;
begin
  if v_user is null then raise exception 'authentication required' using errcode='42501'; end if;
  select * into v_workspace from tongs.workspaces where id=p_workspace_id;
  if not found or not exists(select 1 from tongs.workspace_members wm where wm.workspace_id=p_workspace_id and wm.user_id=v_user) then
    raise exception 'workspace membership required' using errcode='42501';
  end if;
  select * into v_preference from tongs.ai_funding_preference_revisions
    where user_id=v_user and workspace_id=p_workspace_id order by revision desc limit 1;
  v_owner := tongs._transition_owner_authority_agrees(v_user);
  if v_workspace.org_id is not null then
    select * into v_org_account from tongs.organization_funding_account_revisions
      where org_id=v_workspace.org_id order by revision desc limit 1;
    select * into v_permission from tongs.organization_shared_spend_permission_revisions
      where org_id=v_workspace.org_id and member_user_id=v_user order by revision desc limit 1;
  end if;
  return jsonb_build_object(
    'workspace_id',p_workspace_id,
    'org_id',v_workspace.org_id,
    'selected_payer',coalesce(v_preference.payer_kind,'personal'),
    'selected_revision_id',v_preference.id,
    'options',jsonb_build_array(
      jsonb_build_object('kind','personal','label','My purchased credits','available',true),
      jsonb_build_object('kind','organization_shared','label','Organization shared credits',
        'available',v_org_account.status='active' and v_permission.status='allowed'),
      jsonb_build_object('kind','owner_testing','label','Private owner testing',
        'available',v_owner,'requires_active_budget',true)
    )
  );
end $$;


ALTER FUNCTION "tongs"."read_my_ai_funding_options"("p_workspace_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."read_my_ai_model_preference"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare uid uuid:=auth.uid(); pref tongs.ai_model_preference_revisions%rowtype; model record;
begin
 if uid is null then raise exception 'authentication required' using errcode='28000'; end if;
 select * into pref from tongs.ai_model_preference_revisions where user_id=uid order by revision desc limit 1;
 if not found then return jsonb_build_object('selection_key',null,'display_name',null,'relative_cost_class',null,'revision',0); end if;
 select i.customer_selection_key,r.display_name,r.relative_cost_class into model from tongs.ai_model_identities i join lateral(select * from tongs.ai_model_identity_revisions where model_identity_id=i.id order by revision desc limit 1)r on true where i.id=pref.model_identity_id;
 return jsonb_build_object('selection_key',model.customer_selection_key,'display_name',model.display_name,'relative_cost_class',model.relative_cost_class,'revision',pref.revision,'updated_at',pref.created_at);
end $$;


ALTER FUNCTION "tongs"."read_my_ai_model_preference"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."read_my_ai_operation_model_override"("p_operation_code" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare uid uuid:=auth.uid(); override_row tongs.ai_operation_model_override_revisions%rowtype; model record; available boolean:=false;
begin
 if uid is null then raise exception 'authentication required' using errcode='28000'; end if;
 select * into override_row from tongs.ai_operation_model_override_revisions where user_id=uid and operation_code=p_operation_code order by revision desc limit 1;
 if not found or override_row.override_state='clear' then return jsonb_build_object('state','clear','selection_key',null,'display_name',null,'revision',coalesce(override_row.revision,0),'available',true); end if;
 select i.customer_selection_key,r.display_name into model from tongs.ai_model_identities i join lateral(select * from tongs.ai_model_identity_revisions where model_identity_id=i.id order by revision desc limit 1)r on true where i.id=override_row.model_identity_id;
 select exists(select 1 from tongs._eligible_ai_models_for_operation(p_operation_code) e where e.model_identity_id=override_row.model_identity_id) into available;
 return jsonb_build_object('state','specific','selection_key',model.customer_selection_key,'display_name',model.display_name,'revision',override_row.revision,'available',available,'updated_at',override_row.created_at);
end $$;


