CREATE OR REPLACE FUNCTION "tongs"."read_my_customer_funding"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_user uuid := auth.uid();
  v_environment text;
  v_environments jsonb;
  v_active jsonb;
  v_reservations jsonb;
  v_legacy jsonb;
  v_deposits jsonb;
begin
  if v_user is null then raise exception 'authentication required' using errcode = '42501'; end if;
  v_environment := tongs._current_financial_environment();
  with environment_names as (
    select unnest(array['test'::text,'live'::text]) environment
  ), deposit_balances as (
    select deposit.*,
      exists(select 1 from tongs.customer_deposit_processor_fees fee where fee.deposit_id=deposit.id) fee_verified,
      coalesce(used.used_charge,0)::bigint used_charge,
      coalesce(refunded.refunded_charge,0)::bigint refunded_charge,
      coalesce(held.customer_charge_micros,0)::bigint held_charge,
      tongs._effective_deposit_credit_units(deposit.id) effective_units,
      tongs._available_deposit_credit_units(deposit.id) available_units
    from tongs.customer_deposits deposit
    left join lateral (
      select coalesce(sum(c.recognized_revenue_micros),0) used_charge
      from tongs.customer_deposit_consumptions c where c.deposit_id=deposit.id
    ) used on true
    left join lateral (
      select coalesce(sum(r.liability_release_micros),0) refunded_charge
      from tongs.customer_deposit_refunds r where r.deposit_id=deposit.id
    ) refunded on true
    left join lateral tongs._active_funding_hold('customer_deposit',deposit.id) held on true
    where deposit.user_id=v_user
  ), allowance_balances as (
    select allowance.*,
      coalesce(used.used_revenue,0)::bigint used_revenue,
      coalesce(used.used_units,0)::bigint used_units,
      coalesce(used.used_wholesale,0)::bigint used_wholesale,
      coalesce(held.customer_charge_micros,0)::bigint held_charge,
      coalesce(held.credit_units,0)::bigint held_units,
      coalesce(held.wholesale_spend_micros,0)::bigint held_wholesale
    from tongs.paid_allowance_grants allowance
    left join lateral (
      select coalesce(sum(c.recognized_revenue_micros),0) used_revenue,
        coalesce(sum(c.entitlement_units_consumed),0) used_units,
        coalesce(sum(c.wholesale_spend_micros),0) used_wholesale
      from tongs.paid_allowance_consumptions c where c.allowance_grant_id=allowance.id
    ) used on true
    left join lateral tongs._active_funding_hold('paid_allowance',allowance.id) held on true
    where allowance.user_id=v_user and now()>=allowance.period_start and now()<allowance.period_end
      and not exists(select 1 from tongs.subscription_cycle_adjustments a where a.receipt_id=allowance.receipt_id)
  ), beta_balances as (
    select beta.*,
      coalesce(used.used_value,0)::bigint used_value,
      coalesce(used.used_units,0)::bigint used_units,
      coalesce(used.used_wholesale,0)::bigint used_wholesale,
      coalesce(held.customer_charge_micros,0)::bigint held_value,
      coalesce(held.credit_units,0)::bigint held_units,
      coalesce(held.wholesale_spend_micros,0)::bigint held_wholesale
    from tongs.beta_credit_grants beta
    left join lateral (
      select coalesce(sum(c.customer_value_micros),0) used_value,
        coalesce(sum(c.credit_units_consumed),0) used_units,
        coalesce(sum(c.wholesale_spend_micros),0) used_wholesale
      from tongs.beta_credit_consumptions c where c.grant_id=beta.id
    ) used on true
    left join lateral tongs._active_funding_hold('beta_grant',beta.id) held on true
    where beta.user_id=v_user
  ), summaries as (
    select environment_names.environment, jsonb_build_object(
      'purchased', jsonb_build_object(
        'currency','USD',
        'available_micros',coalesce(sum(tongs._available_deposit_value_micros(d.id)) filter(where d.fee_verified),0),
        'available_credit_units',coalesce(sum(d.available_units) filter(where d.fee_verified),0),
        'pending_fee_deposit_count',count(d.id) filter(where not d.fee_verified),
        'pending_fee_micros',coalesce(sum(d.gross_amount_micros) filter(where not d.fee_verified),0),
        'provider_execution_eligible',coalesce(sum(d.available_units) filter(where d.fee_verified),0)>0
      ),
      'allowances', jsonb_build_object(
        'currency','USD',
        'available_revenue_micros',coalesce((select sum(greatest(a.allocated_revenue_micros-a.used_revenue-a.held_charge,0)) from allowance_balances a where a.financial_environment=environment_names.environment),0),
        'available_entitlement_units',coalesce((select sum(greatest(a.entitlement_units-a.used_units-a.held_units,0)) from allowance_balances a where a.financial_environment=environment_names.environment),0),
        'available_wholesale_micros',coalesce((select sum(greatest(a.maximum_wholesale_spend_micros-a.used_wholesale-a.held_wholesale,0)) from allowance_balances a where a.financial_environment=environment_names.environment),0),
        'provider_execution_eligible',coalesce((select bool_or(a.entitlement_units-a.used_units-a.held_units>0 and a.maximum_wholesale_spend_micros-a.used_wholesale-a.held_wholesale>0) from allowance_balances a where a.financial_environment=environment_names.environment),false)
      ),
      'beta_grants', jsonb_build_object(
        'currency','USD',
        'available_customer_value_micros',coalesce((select sum(greatest(b.customer_value_micros-b.used_value-b.held_value,0)) from beta_balances b where b.financial_environment=environment_names.environment),0),
        'available_credit_units',coalesce((select sum(greatest(b.credit_units-b.used_units-b.held_units,0)) from beta_balances b where b.financial_environment=environment_names.environment),0),
        'available_wholesale_micros',coalesce((select sum(greatest(b.maximum_wholesale_capacity_micros-b.used_wholesale-b.held_wholesale,0)) from beta_balances b where b.financial_environment=environment_names.environment),0),
        'provider_execution_eligible',coalesce((select bool_or(b.credit_units-b.used_units-b.held_units>0 and b.maximum_wholesale_capacity_micros-b.used_wholesale-b.held_wholesale>0) from beta_balances b where b.financial_environment=environment_names.environment),false)
      )
    ) summary
    from environment_names
    left join deposit_balances d on d.stripe_mode=environment_names.environment
    group by environment_names.environment
  ) select jsonb_object_agg(environment,summary) into v_environments from summaries;
  v_active := coalesce(v_environments->v_environment,'{}'::jsonb);
  select jsonb_build_object(
    'reservation_count',count(*),
    'reserved_customer_charge_micros',coalesce(sum(reserved_customer_charge_micros),0),
    'reserved_credit_units',coalesce(sum(reserved_credit_units),0)
  ) into v_reservations
  from tongs.funding_reservations reservation
  where reservation.user_id=v_user and reservation.funding_environment=v_environment
    and tongs._funding_reservation_state(reservation.id)
      in('reserved','attempt_started','provider_attempt_shadowed','submission_unknown');
  select jsonb_build_object(
    'credit_units',coalesce(sum(opening.credit_units),0),
    'provider_execution_eligible',false,'reason','legacy_unverified'
  ) into v_legacy from tongs.legacy_credit_opening_balances opening where opening.user_id=v_user;
  select coalesce(jsonb_agg(jsonb_build_object(
    'deposit_id',deposit.id,'financial_environment',deposit.stripe_mode,
    'pack_id',deposit.pack_id,'currency',deposit.currency,
    'gross_amount_micros',deposit.gross_amount_micros,
    'source_credit_units',deposit.credit_units,
    'credit_units',tongs._effective_deposit_credit_units(deposit.id),
    'available_credit_units',tongs._available_deposit_credit_units(deposit.id),
    'conversion_value_remainder_micros',coalesce(conversion.value_remainder_micros,0),
    'received_at',deposit.received_at
  ) order by deposit.received_at desc),'[]'::jsonb) into v_deposits
  from tongs.customer_deposits deposit
  left join tongs.legacy_deposit_credit_conversions conversion on conversion.deposit_id=deposit.id
  where deposit.user_id=v_user;
  return jsonb_build_object(
    'contract_version','forge.customer-funding.v4',
    'credit_contract','forge.credit-economy.v1',
    'active_environment',v_environment,
    'environments',coalesce(v_environments,'{}'::jsonb),
    'active_spendable',coalesce(v_active,'{}'::jsonb),
    'active_reservations',coalesce(v_reservations,'{}'::jsonb),
    'legacy_unverified',coalesce(v_legacy,'{}'::jsonb),
    'deposits',coalesce(v_deposits,'[]'::jsonb)
  );
end $$;


ALTER FUNCTION "tongs"."read_my_customer_funding"() OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."read_my_customer_funding"() IS 'Customer-scoped Forge Credit funding read model v4. Reports Test and Live separately and exposes only canonical spendable balances.';



CREATE OR REPLACE FUNCTION "tongs"."read_my_customer_runway_generation_attempt"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_beat_id" "uuid", "p_prompt_revision_id" "uuid", "p_prompt_revision" bigint, "p_prompt_content_hash" "text", "p_creative_input_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $_$
declare
  v_actor uuid:=auth.uid();
  v_attempt tongs.broll_generation_attempts%rowtype;
begin
  if v_actor is null or not tongs.has_workspace_role(p_workspace_id,'editor') then
    raise exception 'workspace editor authority required' using errcode='42501';
  end if;
  if p_workspace_id is null or p_workpiece_id is null or p_beat_id is null
     or p_prompt_revision_id is null or p_prompt_revision is null or p_prompt_revision<=0
     or p_prompt_content_hash is null or p_prompt_content_hash!~'^[0-9a-f]{64}$'
     or p_creative_input_hash is null or p_creative_input_hash!~'^[0-9a-f]{64}$' then
    raise exception 'invalid generation attempt readback context' using errcode='22023';
  end if;

  select attempt.* into v_attempt
  from tongs.broll_generation_attempts attempt
  where attempt.initiated_by=v_actor
    and attempt.workspace_id=p_workspace_id
    and attempt.workpiece_id=p_workpiece_id
    and attempt.beat_id=p_beat_id
    and attempt.prompt_revision_id=p_prompt_revision_id
    and attempt.prompt_revision=p_prompt_revision
    and attempt.prompt_content_hash=lower(p_prompt_content_hash)
    and attempt.creative_input_hash=lower(p_creative_input_hash)
  order by attempt.initiated_at desc
  limit 1;

  if not found then
    return jsonb_build_object('disposition','generation_attempt_not_found');
  end if;

  return jsonb_build_object(
    'disposition','generation_attempt_current',
    'generation_request_id',v_attempt.generation_request_id,
    'attempt_ordinal',v_attempt.attempt_ordinal,
    'previous_operation_id',v_attempt.previous_operation_id,
    'operation_id',v_attempt.operation_id,
    'operation_fingerprint',v_attempt.operation_fingerprint,
    'creative_input_hash',v_attempt.creative_input_hash,
    'prompt_revision_id',v_attempt.prompt_revision_id,
    'prompt_revision',v_attempt.prompt_revision,
    'prompt_content_hash',v_attempt.prompt_content_hash,
    'replay',true
  );
end $_$;


ALTER FUNCTION "tongs"."read_my_customer_runway_generation_attempt"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_beat_id" "uuid", "p_prompt_revision_id" "uuid", "p_prompt_revision" bigint, "p_prompt_content_hash" "text", "p_creative_input_hash" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."read_my_customer_runway_generation_attempt"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_beat_id" "uuid", "p_prompt_revision_id" "uuid", "p_prompt_revision" bigint, "p_prompt_content_hash" "text", "p_creative_input_hash" "text") IS 'Read-only recovery of the signed-in customer''s exact durable Runway generation-attempt identity. Creates no attempt, quote, reservation, charge, or provider action.';



CREATE OR REPLACE FUNCTION "tongs"."read_my_hearth_conversation"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_after_sequence" bigint DEFAULT 0, "p_limit" integer DEFAULT 500) RETURNS TABLE("generation" bigint, "completeness" "text", "sequence" bigint, "client_message_key" "text", "role" "text", "content" "text", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare v_thread tongs.hearth_conversation_threads%rowtype;
begin
  perform tongs.assert_workspace_role(p_workspace_id, 'viewer');
  if not exists(select 1 from tongs.episodes e where e.id=p_workpiece_id and e.workspace_id=p_workspace_id) then
    raise exception 'workpiece does not belong to workspace' using errcode='22023';
  end if;
  select * into v_thread from tongs.hearth_conversation_threads t
    where t.workspace_id=p_workspace_id and t.workpiece_id=p_workpiece_id;
  if not found then return; end if;
  if not exists(
    select 1 from tongs.hearth_conversation_messages m
    where m.workspace_id=p_workspace_id and m.workpiece_id=p_workpiece_id
      and m.generation=v_thread.generation and m.sequence>greatest(0,coalesce(p_after_sequence,0))
  ) then
    return query select v_thread.generation,v_thread.completeness,null::bigint,null::text,null::text,null::text,null::timestamptz;
    return;
  end if;
  return query select v_thread.generation,v_thread.completeness,m.sequence,m.client_message_key,m.role,m.content,m.created_at
    from tongs.hearth_conversation_messages m
    where m.workspace_id=p_workspace_id and m.workpiece_id=p_workpiece_id
      and m.generation=v_thread.generation and m.sequence>greatest(0,coalesce(p_after_sequence,0))
    order by m.sequence asc limit greatest(1,least(coalesce(p_limit,500),1000));
end $$;


ALTER FUNCTION "tongs"."read_my_hearth_conversation"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_after_sequence" bigint, "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."read_my_openai_text_model_preference"("p_route_code" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare snapshot jsonb:=tongs.read_ai_operation_model_choices(p_route_code); chosen jsonb;
begin
 chosen:=case when snapshot->>'applicable_source'='operation_override' then snapshot->'operation_override' else snapshot->'global_preference' end;
 return jsonb_build_object('route_code',p_route_code,'preference_kind',case when chosen->>'selection_key' is null then 'best_available' else 'specific' end,'selection_key',chosen->'selection_key','display_name',chosen->'display_name','revision',coalesce((chosen->>'revision')::integer,0),'available',snapshot->'applicable_available','preference_source',snapshot->'applicable_source');
end $$;


ALTER FUNCTION "tongs"."read_my_openai_text_model_preference"("p_route_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."read_my_openai_transcription_result"("p_operation_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare uid uuid:=auth.uid(); r tongs.openai_transcription_canonical_results%rowtype; customer_charge bigint:=0; settled boolean:=false;
begin
 if uid is null then raise exception 'authentication required' using errcode='28000'; end if;
 select * into r from tongs.openai_transcription_canonical_results where operation_id=p_operation_id and user_id=uid;
 if not found then return null; end if;
  if not exists(select 1 from tongs.workspace_members where workspace_id=r.workspace_id and user_id=uid) then
    raise exception 'current workspace access required' using errcode='42501'; end if;
 select coalesce(e.customer_charge_micros,0),true into customer_charge,settled from tongs.funding_reservation_events e where e.reservation_id=r.reservation_id and e.event_type='settled' order by e.sequence desc limit 1;
 return jsonb_build_object('operation_id',r.operation_id,'route_code',r.route_code,'workpiece_id',r.workpiece_id,'result',r.transcript_json,
  'customer_charge_micros',customer_charge,'status',case when settled then 'settled' else 'persistence_complete_reconciliation_pending' end,'created_at',r.created_at);
end $$;


ALTER FUNCTION "tongs"."read_my_openai_transcription_result"("p_operation_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."read_my_openai_transcription_result"("p_operation_id" "text") IS 'Customer-safe result and charge only; no wholesale rate, supplier expense, markup, or margin fields.';



CREATE OR REPLACE FUNCTION "tongs"."read_my_paid_media_operation"("p_paid_media_operation_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
  select jsonb_build_object('operation',to_jsonb(o),'quote',to_jsonb(q),'reservation',tongs.read_my_ai_credit_reservation(o.reservation_id),
    'attempts',coalesce((select jsonb_agg(to_jsonb(a) order by a.ordinal) from tongs.paid_media_provider_attempts a where a.paid_media_operation_id=o.id),'[]'::jsonb),
    'events',coalesce((select jsonb_agg(to_jsonb(e) order by e.event_ordinal) from tongs.paid_media_operation_events e where e.paid_media_operation_id=o.id),'[]'::jsonb))
  from tongs.paid_media_operations o join tongs.ai_credit_quotes q on q.id=o.quote_id
  where o.id=p_paid_media_operation_id and o.user_id=auth.uid();
$$;


ALTER FUNCTION "tongs"."read_my_paid_media_operation"("p_paid_media_operation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."read_my_pending_hearth_script_proposal"("p_workspace_id" "uuid", "p_workpiece_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare proposal tongs.hearth_script_generation_proposals%rowtype;
  binding tongs.hearth_script_generation_proposal_draft_bindings%rowtype;
  paid_result_id uuid; started boolean;
begin
  if auth.uid() is null or not tongs.has_workspace_role(p_workspace_id,'viewer') then
    raise exception 'workspace access required' using errcode='42501';
  end if;
  select candidate.* into proposal
  from tongs.hearth_script_generation_proposals candidate
  where candidate.user_id=auth.uid() and candidate.workspace_id=p_workspace_id
    and candidate.workpiece_id=p_workpiece_id
    and not exists(
      select 1 from tongs.hearth_script_generation_proposals newer
      where newer.user_id=candidate.user_id and newer.workspace_id=candidate.workspace_id
        and newer.workpiece_id=candidate.workpiece_id
        and (newer.created_at,newer.id)>(candidate.created_at,candidate.id)
    )
    and not exists(
      select 1 from tongs.hearth_script_generation_proposal_events terminal
      where terminal.proposal_id=candidate.id
        and terminal.event_type in ('applied','rejected','superseded')
    )
  order by candidate.created_at desc,candidate.id desc limit 1;
  if proposal.id is null then return null; end if;
  select * into binding from tongs.hearth_script_generation_proposal_draft_bindings
    where proposal_id=proposal.id;
  select result.id into paid_result_id from tongs.openai_text_persisted_results result
    where result.reservation_id=proposal.reservation_id and result.route_code='hearth.script_generation';
  select exists(select 1 from tongs.hearth_script_generation_proposal_events event
    where event.proposal_id=proposal.id and event.event_type='application_started') into started;
  return proposal.result_json||jsonb_build_object(
    'proposal_id',proposal.id,'proposal_state','proposed','created_at',proposal.created_at,
    'operation_id',proposal.operation_id,'source_paid_result_id',paid_result_id,
    'expected_draft_revision',binding.expected_draft_revision,
    'expected_draft_hash',binding.expected_draft_hash,
    'application_started',started
  );
end $$;


