CREATE OR REPLACE FUNCTION "tongs"."read_openai_text_test_certification"("p_batch_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare v_actor uuid:=auth.uid();
begin
  if coalesce(auth.role(),'')<>'service_role' and (v_actor is null or not tongs.is_platform_operator(v_actor)) then raise exception 'platform operator required' using errcode='42501'; end if;
  return jsonb_build_object('contract_version','forge.openai-text-test-certification.v1','environment','test','live_provider_authorized',false,
    'batches',(select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at desc),'[]'::jsonb) from (select b.id,b.user_id,b.workspace_id,b.deposit_id,b.maximum_operation_count,b.maximum_aggregate_charge_micros,b.maximum_aggregate_failure_exposure_micros,b.expires_at,b.created_at,tongs._openai_text_test_certification_batch_state(b.id) status from tongs.openai_text_test_certification_batches b where p_batch_id is null or b.id=p_batch_id) x),
    'terms',(select coalesce(jsonb_agg(to_jsonb(t) order by t.route_code),'[]'::jsonb) from tongs.openai_text_test_certification_terms t where p_batch_id is null or t.batch_id=p_batch_id),
    'operations',(select coalesce(jsonb_agg(to_jsonb(x) order by x.route_code,x.scenario),'[]'::jsonb) from (select o.id quote_id,o.batch_id,o.route_code,o.scenario,o.operation_id,o.workpiece_id,o.quote_hash,o.request_fingerprint,o.normal_maximum_charge_micros,o.accepted_by,r.id reservation_id,tongs._openai_text_test_certification_reservation_state(r.id) reservation_state,res.id result_id,s.id settlement_id,s.customer_charge_micros,s.failure_class,(select count(*) from tongs.openai_text_test_certification_evidence e where e.reservation_id=r.id and e.evidence_kind='provider_capture') provider_execution_count from tongs.openai_text_test_certification_operations o left join tongs.openai_text_test_certification_reservations r on r.operation_record_id=o.id left join tongs.openai_text_test_certification_results res on res.reservation_id=r.id left join tongs.openai_text_test_certification_settlements s on s.reservation_id=r.id where p_batch_id is null or o.batch_id=p_batch_id) x),
    'expenses',(select coalesce(jsonb_agg(to_jsonb(e) order by e.created_at),'[]'::jsonb) from tongs.openai_text_test_certification_expenses e join tongs.openai_text_test_certification_reservations r on r.id=e.reservation_id where p_batch_id is null or r.batch_id=p_batch_id));
end $$;


ALTER FUNCTION "tongs"."read_openai_text_test_certification"("p_batch_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."read_openai_text_test_certification_invocation"("p_batch_id" "uuid", "p_operation_id" "text", "p_reservation_id" "uuid", "p_invocation_token" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare v_batch tongs.openai_text_test_certification_batches%rowtype; v_op tongs.openai_text_test_certification_operations%rowtype; v_res tongs.openai_text_test_certification_reservations%rowtype; v_term tongs.openai_text_test_certification_terms%rowtype;
begin
  perform tongs._require_pricing_service_role(); select * into v_batch from tongs.openai_text_test_certification_batches where id=p_batch_id;
  if not found or v_batch.expires_at<=now() or tongs._openai_text_test_certification_batch_state(v_batch.id)<>'opened'
     or encode(extensions.digest(convert_to(coalesce(p_invocation_token,''),'UTF8'),'sha256'),'hex')<>v_batch.invocation_token_hash then raise exception 'Test invocation denied' using errcode='42501'; end if;
  select * into v_res from tongs.openai_text_test_certification_reservations where id=p_reservation_id and batch_id=p_batch_id and operation_id=btrim(p_operation_id);
  select * into v_op from tongs.openai_text_test_certification_operations where id=v_res.operation_record_id; select * into v_term from tongs.openai_text_test_certification_terms where id=v_op.term_id;
  if v_res.id is null or v_op.id is null or v_term.id is null then raise exception 'Test reservation not found' using errcode='P0002'; end if;
  return jsonb_build_object('batch_id',v_batch.id,'user_id',v_batch.user_id,'workspace_id',v_batch.workspace_id,'deposit_id',v_batch.deposit_id,'operation_record_id',v_op.id,
    'operation_id',v_op.operation_id,'reservation_id',v_res.id,'route_code',v_op.route_code,'scenario',v_op.scenario,'workpiece_id',v_op.workpiece_id,
    'request_fingerprint',v_op.request_fingerprint,'request_json',v_op.request_json,'model',v_term.model,'real_provider_authorized',false);
end $$;


ALTER FUNCTION "tongs"."read_openai_text_test_certification_invocation"("p_batch_id" "uuid", "p_operation_id" "text", "p_reservation_id" "uuid", "p_invocation_token" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."read_openai_text_test_certification_result"("p_route_code" "text", "p_operation_id" "text", "p_reservation_id" "uuid", "p_user_id" "uuid", "p_request_fingerprint" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare v_result tongs.openai_text_test_certification_results%rowtype; v_settlement tongs.openai_text_test_certification_settlements%rowtype;
begin perform tongs._require_pricing_service_role(); select * into v_result from tongs.openai_text_test_certification_results where route_code=p_route_code and operation_id=p_operation_id and reservation_id=p_reservation_id and user_id=p_user_id and request_fingerprint=p_request_fingerprint;
  if not found then raise exception 'Test result not found' using errcode='P0002'; end if; select * into v_settlement from tongs.openai_text_test_certification_settlements where reservation_id=p_reservation_id;
  return jsonb_build_object('provider_request_id',v_result.provider_request_id,'customer_charge_micros',coalesce(v_settlement.customer_charge_micros,0),'result_json',v_result.result_json); end $$;


ALTER FUNCTION "tongs"."read_openai_text_test_certification_result"("p_route_code" "text", "p_operation_id" "text", "p_reservation_id" "uuid", "p_user_id" "uuid", "p_request_fingerprint" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."read_operator_legacy_credit_reconciliation_summary"("p_actor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare v_cases jsonb;
begin
  perform tongs._require_pricing_service_role();
  if p_actor_id is null or not tongs.is_platform_operator(p_actor_id) then
    raise exception 'platform operator required' using errcode = '42501';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object(
    'case_id', reconciliation.id,
    'user_id', reconciliation.user_id,
    'opening_credit_units', reconciliation.opening_credit_units,
    'captured_at', reconciliation.captured_at,
    'source_relation', reconciliation.source_relation,
    'initial_classification', reconciliation.classification,
    'latest_classification', coalesce(decision.classification, reconciliation.classification),
    'supported_credit_units', decision.supported_credit_units,
    'unresolved_reason', reconciliation.unresolved_reason,
    'evidence_count', evidence.evidence_count,
    'conversion_count', conversion.conversion_count
  ) order by reconciliation.captured_at, reconciliation.user_id), '[]'::jsonb)
  into v_cases
  from tongs.legacy_credit_reconciliation_cases reconciliation
  left join lateral (
    select item.classification, item.supported_credit_units
    from tongs.legacy_credit_reconciliation_decisions item
    where item.case_id = reconciliation.id
    order by item.decided_at desc, item.id desc limit 1
  ) decision on true
  left join lateral (
    select count(*) evidence_count
    from tongs.legacy_credit_reconciliation_evidence item
    where item.case_id = reconciliation.id
  ) evidence on true
  left join lateral (
    select count(*) conversion_count
    from tongs.legacy_credit_conversion_mappings item
    where item.case_id = reconciliation.id
  ) conversion on true;
  return jsonb_build_object(
    'contract_version', 'forge.legacy-credit-reconciliation-summary.v1',
    'cases', v_cases
  );
end $$;


ALTER FUNCTION "tongs"."read_operator_legacy_credit_reconciliation_summary"("p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."read_owner_accounting_foundation"("p_user_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT 250) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_limit integer := least(greatest(coalesce(p_limit, 250), 1), 2000);
  v_events jsonb;
  v_budgets jsonb;
begin
  if coalesce(auth.role(), '') <> 'service_role'
     and (v_actor is null or not tongs.is_platform_operator(v_actor)) then
    raise exception 'platform operator required' using errcode = '42501';
  end if;
  select coalesce(jsonb_agg(to_jsonb(event_row) order by event_row.occurred_at desc), '[]'::jsonb)
    into v_events
  from (
    select e.id, e.event_type, e.environment, e.source_type, e.source_id, e.currency,
      e.user_id, e.workspace_id, e.occurred_at, e.created_at, e.metadata_json,
      coalesce((select sum(j.amount_micros) from tongs.accounting_journal_entries j
        where j.event_id = e.id), 0) as monetary_imbalance_micros
    from tongs.accounting_journal_events e
    where p_user_id is null or e.user_id = p_user_id
    order by e.occurred_at desc limit v_limit
  ) event_row;
  select coalesce(jsonb_agg(to_jsonb(budget_row) order by budget_row.created_at desc), '[]'::jsonb)
    into v_budgets
  from (
    select b.*, revision.revision, revision.status, revision.maximum_amount_micros,
      revision.reason, revision.created_at as revision_created_at
    from tongs.owner_operating_budgets b
    join lateral (
      select r.revision, r.status, r.maximum_amount_micros, r.reason, r.created_at
      from tongs.owner_operating_budget_revisions r where r.budget_id = b.id
      order by r.revision desc limit 1
    ) revision on true
  ) budget_row;
  return jsonb_build_object('events', v_events, 'owner_operating_budgets', v_budgets,
    'spending_gate_active', false);
end;
$$;


ALTER FUNCTION "tongs"."read_owner_accounting_foundation"("p_user_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."read_owner_billing_console"("p_limit" integer DEFAULT 250) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_result jsonb;
  v_pricing jsonb;
begin
  v_result:=tongs._read_owner_billing_console_before_rounded_customer_ceiling(p_limit);
  select coalesce(jsonb_agg(
    price.item || case
      when revision.markup_basis_points is null then '{}'::jsonb
      else jsonb_build_object(
        'unrounded_cost_plus_markup_micros',revision.customer_price_ceiling_micros,
        'customer_price_ceiling_micros',rounded.customer_price_micros,
        'expected_contribution_profit_micros',rounded.customer_price_micros-revision.full_cost_ceiling_micros,
        'expected_contribution_margin_percentage',case when rounded.customer_price_micros=0 then null
          else round(100::numeric*(rounded.customer_price_micros-revision.full_cost_ceiling_micros)::numeric
            /rounded.customer_price_micros::numeric,4) end
      )
    end order by price.ordinality
  ),'[]'::jsonb) into v_pricing
  from jsonb_array_elements(coalesce(v_result->'pricing_revisions','[]'::jsonb))
    with ordinality as price(item,ordinality)
  join tongs.private_pricing_revisions revision
    on revision.id=(price.item->>'pricing_revision_id')::uuid
  cross join lateral (
    select case when revision.markup_basis_points is null then null else
      tongs.round_customer_price_micros(
        revision.full_cost_ceiling_micros::numeric*(10000::numeric+revision.markup_basis_points)/10000::numeric,
        revision.currency
      ) end as customer_price_micros
  ) rounded;
  return jsonb_set(v_result,'{pricing_revisions}',v_pricing,true);
end $$;


ALTER FUNCTION "tongs"."read_owner_billing_console"("p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."read_owner_billing_console"("p_limit" integer) IS 'Operator-only billing console with rounded customer prices and contribution values aligned to authoritative quote terms.';



CREATE OR REPLACE FUNCTION "tongs"."read_owner_broll_prompt_interpretation"("p_owner_cost_attempt_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare v_result jsonb;
begin
  perform tongs._require_owner_cost_reader();
  select to_jsonb(receipt)||jsonb_build_object(
      'prompt_revision',case when prompt.id is null then null else to_jsonb(prompt) end,
      'owner_operation',jsonb_build_object(
        'operation_id',owner_operation.operation_id,'operation_key',owner_operation.operation_key,
        'financial_environment',owner_operation.financial_environment,
        'runtime_environment',owner_operation.runtime_environment),
      'valuations',coalesce((select jsonb_agg(to_jsonb(valuation) order by valuation.revision)
        from tongs.owner_cost_valuations valuation where valuation.attempt_id=attempt.attempt_id),'[]'::jsonb))
    into v_result
    from tongs.broll_operation_receipts receipt
    join tongs.owner_cost_provider_attempts attempt on attempt.attempt_id=receipt.owner_cost_attempt_id
    join tongs.owner_cost_operations owner_operation on owner_operation.operation_id=attempt.operation_id
    left join tongs.broll_prompt_revisions prompt on prompt.id=receipt.result_prompt_revision_id
    where receipt.owner_cost_attempt_id=p_owner_cost_attempt_id;
  return v_result;
end
$$;


ALTER FUNCTION "tongs"."read_owner_broll_prompt_interpretation"("p_owner_cost_attempt_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."read_owner_cost_operation"("p_operation_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare v_result jsonb;
begin
  perform tongs._require_owner_cost_reader();
  select jsonb_build_object(
    'operation', to_jsonb(o),
    'attempts', coalesce((
      select jsonb_agg(to_jsonb(a) || jsonb_build_object(
        'events', coalesce((select jsonb_agg(to_jsonb(e) order by e.event_sequence)
          from tongs.owner_cost_attempt_events e where e.attempt_id = a.attempt_id), '[]'::jsonb),
        'valuations', coalesce((select jsonb_agg(to_jsonb(v) order by v.cost_component, v.revision)
          from tongs.owner_cost_valuations v where v.attempt_id = a.attempt_id), '[]'::jsonb)
      ) order by a.attempt_number)
      from tongs.owner_cost_provider_attempts a where a.operation_id = o.operation_id
    ), '[]'::jsonb),
    'links', coalesce((select jsonb_agg(to_jsonb(l) order by l.associated_at)
      from tongs.owner_cost_operation_links l where l.operation_id = o.operation_id), '[]'::jsonb)
  ) into v_result
  from tongs.owner_cost_operations o where o.operation_id = p_operation_id;
  return v_result;
end;
$$;


ALTER FUNCTION "tongs"."read_owner_cost_operation"("p_operation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."read_owner_cost_summary"("p_financial_environment" "text", "p_currency" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $_$
declare
  v_environment text := lower(btrim(coalesce(p_financial_environment, '')));
  v_currency text := nullif(upper(btrim(coalesce(p_currency, ''))), '');
  v_totals jsonb;
begin
  perform tongs._require_owner_cost_reader();
  if v_environment not in ('live', 'test') or (v_currency is not null and v_currency !~ '^[A-Z]{3}$') then
    raise exception 'financial environment and optional ISO currency are required' using errcode = '22023';
  end if;
  select coalesce(jsonb_agg(to_jsonb(summary_row) order by summary_row.currency), '[]'::jsonb)
  into v_totals
  from (
    select entry.currency, sum(entry.amount_micros)::bigint as recognized_expense_micros
    from tongs.accounting_journal_entries entry
    join tongs.accounting_journal_events event on event.id = entry.event_id
    where event.source_type = 'owner_cost_valuation'
      and event.environment = v_environment
      and entry.account_code = case when v_environment = 'live' then 'forge_operating_expense' else 'test_forge_operating_expense' end
      and (v_currency is null or entry.currency = v_currency)
    group by entry.currency
  ) summary_row;
  return jsonb_build_object('financial_environment', v_environment, 'totals_from_canonical_journal', v_totals);
end;
$_$;


ALTER FUNCTION "tongs"."read_owner_cost_summary"("p_financial_environment" "text", "p_currency" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."read_owner_cost_summary"("p_financial_environment" "text", "p_currency" "text") IS 'Owner-only recognized expense summary derived exclusively from canonical accounting journal entries and requiring an explicit financial environment.';



CREATE OR REPLACE FUNCTION "tongs"."read_owner_hearth_activation_audit"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
begin
 if coalesce(auth.role(),'')<>'service_role' and not tongs.is_platform_operator(auth.uid()) then raise exception 'platform operator required' using errcode='42501'; end if;
 return jsonb_build_object(
  'authorizations',(select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at desc),'[]'::jsonb) from tongs.owner_hearth_authorizations x),
  'authorization_events',(select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at desc),'[]'::jsonb) from tongs.owner_hearth_authorization_events x),
  'operations',(select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at desc),'[]'::jsonb) from tongs.owner_hearth_operation_authorizations x),
  'compatibility_results',(select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at desc),'[]'::jsonb) from tongs.owner_hearth_compatibility_results x),
  'tail_authorizations',(select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at desc),'[]'::jsonb) from tongs.owner_hearth_tail_authorizations x),
  'tail_periods',(select coalesce(jsonb_agg(to_jsonb(x) order by x.coverage_start),'[]'::jsonb) from tongs.owner_hearth_tail_periods x),
  'tail_measurements',(select coalesce(jsonb_agg(to_jsonb(x) order by x.period_start,x.revision),'[]'::jsonb) from tongs.owner_hearth_tail_measurements x),
  'legacy_opening_commitments',(select coalesce(jsonb_agg(to_jsonb(x) order by x.created_at desc),'[]'::jsonb) from tongs.legacy_supplier_opening_commitments x),
  'customer_price_published',false);
end $$;


ALTER FUNCTION "tongs"."read_owner_hearth_activation_audit"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."read_owner_hearth_execution_requirement"("p_owner_user_id" "uuid", "p_workspace_id" "uuid", "p_route_code" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare authz tongs.owner_hearth_authorizations%rowtype; ev tongs.owner_hearth_authorization_events%rowtype;
  tail tongs.owner_hearth_tail_authorizations%rowtype; expired_count bigint;
begin
 perform tongs._require_pricing_service_role();
 if p_route_code<>'hearth.chat_completion' or p_owner_user_id is null or p_workspace_id is null then
  return tongs.read_openai_text_route_execution_requirement(p_route_code); end if;
 if not tongs._transition_owner_authority_agrees(p_owner_user_id)
    or not exists(select 1 from tongs.workspace_members where workspace_id=p_workspace_id and user_id=p_owner_user_id) then
  return tongs.read_openai_text_route_execution_requirement(p_route_code); end if;
 perform tongs.refresh_owner_hearth_tail_expiry(p_owner_user_id,p_workspace_id);
 select a.* into authz from tongs.owner_hearth_authorizations a
 join lateral(select * from tongs.owner_hearth_authorization_events e where e.authorization_id=a.id order by sequence desc limit 1) latest on true
 where a.owner_user_id=p_owner_user_id and a.workspace_id=p_workspace_id and latest.state in ('active','dormant')
   and (latest.expires_at is null or latest.expires_at>now())
 order by (a.authorization_kind='creator_session') desc,a.created_at desc limit 1;
 if not found then return tongs.read_openai_text_route_execution_requirement(p_route_code); end if;
 select * into ev from tongs.owner_hearth_authorization_events where authorization_id=authz.id order by sequence desc limit 1;
 select * into tail from tongs.owner_hearth_tail_authorizations where owner_user_id=p_owner_user_id and workspace_id=p_workspace_id order by created_at desc limit 1;
 select count(*) into expired_count from tongs.owner_hearth_tail_periods p where p.tail_authorization_id=tail.id and p.coverage_end<=now()
   and not exists(select 1 from tongs.owner_hearth_tail_events e where e.tail_authorization_id=tail.id and e.event_type='replacement_funded' and e.created_at>=p.coverage_end);
 if exists(select 1 from tongs.owner_hearth_tail_events e where e.tail_authorization_id=tail.id and e.event_type='continuing_obligation'
   and coalesce((e.evidence_json->>'halt_new_required')::boolean,false)) then expired_count:=expired_count+1; end if;
 if expired_count>0 then return jsonb_build_object('route_code',p_route_code,'mode','halt_new','funding_context_required',true,
   'owner_testing_effective',true,'reason','owner_tail_replacement_funding_required'); end if;
 return jsonb_build_object('route_code',p_route_code,'mode','enforce','funding_context_required',true,
  'owner_testing_effective',true,'authorization_id',authz.id,'authorization_kind',authz.authorization_kind,
  'authorization_state',ev.state,'dedicated_credential_required',true);
end $$;


ALTER FUNCTION "tongs"."read_owner_hearth_execution_requirement"("p_owner_user_id" "uuid", "p_workspace_id" "uuid", "p_route_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."read_owner_hearth_image_result"("p_owner_cost_attempt_id" "uuid", "p_route_code" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_result jsonb;
  v_route text:=lower(btrim(coalesce(p_route_code,'')));
begin
  perform tongs._require_owner_cost_reader();
  if v_route='hearth.thumbnail_base_generation' then
    select to_jsonb(result)||jsonb_build_object(
      'owner_operation',jsonb_build_object(
        'operation_id',operation.operation_id,'operation_key',operation.operation_key,
        'workspace_id',operation.workspace_id,'workpiece_id',operation.workpiece_id,
        'financial_environment',operation.financial_environment,
        'runtime_environment',operation.runtime_environment),
      'valuations',coalesce((select jsonb_agg(to_jsonb(valuation) order by valuation.revision)
        from tongs.owner_cost_valuations valuation where valuation.attempt_id=attempt.attempt_id),'[]'::jsonb)
    ) into v_result
    from tongs.hearth_thumbnail_base_generation_results result
    join tongs.owner_cost_provider_attempts attempt on attempt.attempt_id=result.owner_cost_attempt_id
    join tongs.owner_cost_operations operation on operation.operation_id=attempt.operation_id
    where result.owner_cost_attempt_id=p_owner_cost_attempt_id;
  elsif v_route='hearth.timeline_image_generation' then
    select to_jsonb(result)||jsonb_build_object(
      'outputs',coalesce((select jsonb_agg(to_jsonb(output) order by output.child_ordinal)
        from tongs.hearth_timeline_image_generation_outputs output where output.result_id=result.id),'[]'::jsonb),
      'canonical_receipt',case when receipt.result_id is null then null else to_jsonb(receipt) end,
      'owner_operation',jsonb_build_object(
        'operation_id',operation.operation_id,'operation_key',operation.operation_key,
        'workspace_id',operation.workspace_id,'workpiece_id',operation.workpiece_id,
        'financial_environment',operation.financial_environment,
        'runtime_environment',operation.runtime_environment),
      'valuations',coalesce((select jsonb_agg(to_jsonb(valuation) order by valuation.revision)
        from tongs.owner_cost_valuations valuation where valuation.attempt_id=attempt.attempt_id),'[]'::jsonb)
    ) into v_result
    from tongs.hearth_timeline_image_generation_results result
    join tongs.owner_cost_provider_attempts attempt on attempt.attempt_id=result.owner_cost_attempt_id
    join tongs.owner_cost_operations operation on operation.operation_id=attempt.operation_id
    left join tongs.hearth_timeline_image_generation_delivery_receipts receipt on receipt.result_id=result.id
    where result.owner_cost_attempt_id=p_owner_cost_attempt_id;
  else
    raise exception 'unsupported owner Hearth image result route' using errcode='22023';
  end if;
  return v_result;
end $$;


ALTER FUNCTION "tongs"."read_owner_hearth_image_result"("p_owner_cost_attempt_id" "uuid", "p_route_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."read_owner_hearth_research_canary_reconciliation"("p_authorization_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare a tongs.owner_hearth_research_authorizations%rowtype; o tongs.owner_hearth_research_operations%rowtype;
 pkg tongs.owner_hearth_research_result_packages%rowtype; hold tongs.openai_text_failure_exposure_holds%rowtype;
 funding_state text; funding_event tongs.funding_reservation_events%rowtype; loss_event tongs.openai_text_failure_exposure_events%rowtype;
 aggregate_event tongs.restricted_beta_exposure_events%rowtype; source_count bigint; expected_sources bigint; expense_basis text;
begin
 perform tongs._require_pricing_service_role();
 select * into a from tongs.owner_hearth_research_authorizations where id=p_authorization_id;
 if a.id is null or a.authorization_kind<>'canary' or a.limit_profile<>'canary' or a.maximum_operations<>1
  then return jsonb_build_object('reconciled',false,'reason','canary_authorization_mismatch'); end if;
 if (select count(*) from tongs.owner_hearth_research_operations where authorization_id=a.id)<>1
  then return jsonb_build_object('reconciled',false,'reason','canary_operation_count_mismatch'); end if;
 select * into o from tongs.owner_hearth_research_operations where authorization_id=a.id;
 if o.provider_model_id<>'gpt-6-astra' or o.limit_profile<>'canary' or o.maximum_searches<>1 or o.maximum_sources<>2
  or o.maximum_http_attempts<>24 or o.maximum_input_tokens<>8000 or o.maximum_output_tokens<>1000 or o.full_cost_ceiling_micros<>144072
  then return jsonb_build_object('reconciled',false,'reason','canary_operation_authority_mismatch'); end if;
 select tongs._funding_reservation_state(o.reservation_id) into funding_state;
 if funding_state<>'settled' then return jsonb_build_object('reconciled',false,'reason','settlement_not_terminal'); end if;
 select * into funding_event from tongs.funding_reservation_events where reservation_id=o.reservation_id order by sequence desc limit 1;
 if funding_event.event_type<>'settled' or coalesce(funding_event.customer_charge_micros,0)<>0
  then return jsonb_build_object('reconciled',false,'reason','zero_customer_settlement_missing'); end if;
 if exists(select 1 from tongs.owner_hearth_research_stage_events where reservation_id=o.reservation_id and event_type in('authorized','submission_unknown'))
  then return jsonb_build_object('reconciled',false,'reason','supplier_stage_unresolved'); end if;
 if not exists(select 1 from tongs.owner_hearth_research_stage_events where reservation_id=o.reservation_id and stage_type='search' and event_type in('captured','failed'))
  then return jsonb_build_object('reconciled',false,'reason','supplier_stage_evidence_missing'); end if;
 if not exists(select 1 from tongs.paid_operation_aggregate_bindings b where b.reservation_id=o.reservation_id and b.operation_id=o.operation_id
   and b.supplier_exposure_ceiling_micros=130000 and b.supporting_exposure_ceiling_micros=14072)
  then return jsonb_build_object('reconciled',false,'reason','shared_aggregate_binding_missing'); end if;
 select e.* into aggregate_event from tongs.paid_operation_aggregate_bindings b join tongs.restricted_beta_exposure_events e on e.hold_id=b.hold_id
  where b.reservation_id=o.reservation_id order by e.sequence desc limit 1;
 if aggregate_event.id is null or aggregate_event.event_type not in('settled_unconfirmed','reconciled')
  then return jsonb_build_object('reconciled',false,'reason','aggregate_supplier_obligation_not_retained'); end if;
 select * into hold from tongs.openai_text_failure_exposure_holds where reservation_id=o.reservation_id;
 select * into loss_event from tongs.openai_text_failure_exposure_events where hold_id=hold.id order by sequence desc limit 1;
 if hold.id is null or loss_event.id is null or loss_event.event_type not in('success_released','failure_realized','reconciled')
  then return jsonb_build_object('reconciled',false,'reason','provider_attempt_not_terminal'); end if;
 if loss_event.event_type='unresolved' or (loss_event.event_type='authorized' and hold.lease_expires_at>now())
  then return jsonb_build_object('reconciled',false,'reason','provider_lease_or_obligation_unresolved'); end if;
 if not exists(select 1 from tongs.owner_hearth_research_frozen_requests f where f.reservation_id=o.reservation_id and f.operation_id=o.operation_id
   and f.model='gpt-6-astra' and f.maximum_output_tokens=1000)
  or not exists(select 1 from tongs.bounded_provider_request_bindings b where b.reservation_id=o.reservation_id and b.operation_id=o.operation_id
   and b.model='gpt-6-astra' and b.maximum_output_tokens=1000 and b.maximum_attempts=1)
  or not exists(select 1 from tongs.openai_text_provider_captures c where c.reservation_id=o.reservation_id and c.attempt_number=1)
  then return jsonb_build_object('reconciled',false,'reason','frozen_provider_capture_chain_incomplete'); end if;
 select * into pkg from tongs.owner_hearth_research_result_packages where reservation_id=o.reservation_id and operation_id=o.operation_id;
 if pkg.id is null or pkg.request_fingerprint<>o.request_fingerprint or pkg.review_state<>'ready_for_review'
  then return jsonb_build_object('reconciled',false,'reason','canonical_package_missing'); end if;
 select count(*) into source_count from tongs.owner_hearth_research_source_records where result_package_id=pkg.id;
 expected_sources:=jsonb_array_length(coalesce(pkg.research_result_json->'sources','[]'::jsonb));
 if source_count<>expected_sources or source_count>2
  then return jsonb_build_object('reconciled',false,'reason','canonical_sources_mismatch'); end if;
 if not exists(select 1 from tongs.owner_hearth_research_review_events e where e.result_package_id=pkg.id and e.review_state='ready_for_review')
  or not exists(select 1 from tongs.owner_hearth_research_recovery_reads r where r.result_package_id=pkg.id)
  then return jsonb_build_object('reconciled',false,'reason','review_or_recovery_readback_missing'); end if;
 if not ('{search,synthesis,platform_execution,database_write,delivery,continuing_storage}'::text[]
   <@ (select coalesce(array_agg(distinct component),'{}'::text[]) from tongs.owner_hearth_research_component_expenses where reservation_id=o.reservation_id))
  then return jsonb_build_object('reconciled',false,'reason','component_cost_trace_incomplete'); end if;
 select case when bool_and(cost_status='authoritative') then 'authoritative' else 'conservative_estimated' end into expense_basis
  from tongs.owner_hearth_research_component_expenses where reservation_id=o.reservation_id;
 return jsonb_build_object('reconciled',true,'reason','terminal_settlement_with_retained_supplier_exposure','expense_basis',expense_basis,
  'authoritative_provider_billing_required',false,'waiting_period_seconds',0,'customer_charge_micros',0,'automatic_resubmission_allowed',false,
  'reservation_id',o.reservation_id,'operation_id',o.operation_id,'result_package_id',pkg.id);
end $$;


ALTER FUNCTION "tongs"."read_owner_hearth_research_canary_reconciliation"("p_authorization_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."read_owner_hearth_research_execution_requirement"("p_owner_user_id" "uuid", "p_workspace_id" "uuid", "p_route_code" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare a tongs.owner_hearth_research_authorizations%rowtype; ev tongs.owner_hearth_research_authorization_events%rowtype;
begin
 perform tongs._require_pricing_service_role();
 if p_route_code<>'hearth.research_synthesis' then return tongs.read_openai_text_route_execution_requirement(p_route_code); end if;
 if not tongs._transition_owner_authority_agrees(p_owner_user_id)
   or not exists(select 1 from tongs.workspace_members m where m.workspace_id=p_workspace_id and m.user_id=p_owner_user_id) then
  return tongs.read_openai_text_route_execution_requirement(p_route_code); end if;
 a:=tongs._owner_hearth_research_latest_authorization(p_owner_user_id,p_workspace_id);
 if a.id is null then return tongs.read_openai_text_route_execution_requirement(p_route_code); end if;
 select * into ev from tongs.owner_hearth_research_authorization_events where authorization_id=a.id order by sequence desc limit 1;
 if not exists(select 1 from tongs.owner_hearth_research_storage_allowances s where s.owner_user_id=p_owner_user_id and s.workspace_id=p_workspace_id and s.budget_id=a.budget_id) then
  return jsonb_build_object('route_code',p_route_code,'mode','halt_new','funding_context_required',true,'owner_testing_effective',true,'reason','research_storage_allowance_unverified'); end if;
 return jsonb_build_object('route_code',p_route_code,'mode','enforce','funding_context_required',true,'owner_testing_effective',true,
  'authorization_id',a.id,'authorization_kind',a.authorization_kind,'authorization_state',ev.state,'dedicated_credential_required',true,
  'limit_profile',a.limit_profile,'maximum_searches',a.maximum_searches,'maximum_sources',a.maximum_sources,
  'maximum_http_attempts',a.maximum_http_attempts,'maximum_input_tokens',a.maximum_input_tokens,'maximum_output_tokens',a.maximum_output_tokens,
  'required_provider_model_id',case when a.authorization_kind='canary' then 'gpt-6-astra' else null end);
end $$;


ALTER FUNCTION "tongs"."read_owner_hearth_research_execution_requirement"("p_owner_user_id" "uuid", "p_workspace_id" "uuid", "p_route_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."read_owner_hearth_research_result"("p_operation_id" "text", "p_reservation_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare pkg tongs.owner_hearth_research_result_packages%rowtype; ordinal int; allowance tongs.owner_hearth_research_storage_allowances%rowtype; latest_review text;
begin
 perform tongs._require_pricing_service_role(); select * into pkg from tongs.owner_hearth_research_result_packages where operation_id=btrim(p_operation_id) and reservation_id=p_reservation_id;
 if pkg.id is null then raise exception 'owner research result not found' using errcode='P0002'; end if;
 select * into allowance from tongs.owner_hearth_research_storage_allowances where owner_user_id=pkg.owner_user_id and workspace_id=pkg.workspace_id;
 select coalesce(max(r.ordinal),0)+1 into ordinal from tongs.owner_hearth_research_recovery_reads r where r.result_package_id=pkg.id;
 if ordinal>allowance.maximum_recovery_reads_per_package then raise exception 'bounded research recovery read limit reached' using errcode='42501'; end if;
 insert into tongs.owner_hearth_research_recovery_reads values(gen_random_uuid(),pkg.id,ordinal,'owner-research-read:'||pkg.id::text||':'||ordinal,0,now());
 insert into tongs.owner_hearth_research_component_expenses values(gen_random_uuid(),p_reservation_id,'recovery-read:'||pkg.id::text||':'||ordinal,'recovery_read',0,'estimated',
  'Netlify/Supabase',jsonb_build_object('covered_by_storage_allowance_id',allowance.id),now());
 select e.review_state into latest_review from tongs.owner_hearth_research_review_events e where e.result_package_id=pkg.id order by e.sequence desc limit 1;
 return pkg.result_json||jsonb_build_object('domain_result_id',pkg.id,'provider_request_id',pkg.provider_request_id,'input_units',pkg.input_units,'output_units',pkg.output_units,
  'review_state',latest_review,'research_result',pkg.research_result_json,'recovery_read_ordinal',ordinal);
end $$;


ALTER FUNCTION "tongs"."read_owner_hearth_research_result"("p_operation_id" "text", "p_reservation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."read_owner_hearth_text_result"("p_owner_cost_attempt_id" "uuid", "p_route_code" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $_$
declare
  v_route text:=lower(btrim(coalesce(p_route_code,'')));
  v_table text;
  v_result jsonb;
begin
  perform tongs._require_owner_cost_reader();
  v_table:=case v_route
    when 'hearth.chat_completion' then 'openai_text_persisted_results'
    when 'hearth.script_generation' then 'hearth_script_generation_proposals'
    when 'hearth.research_synthesis' then 'hearth_research_synthesis_results'
    when 'hearth.title_generation' then 'hearth_title_generation_results'
    when 'hearth.tag_generation' then 'hearth_tag_generation_results'
    when 'hearth.framing_pack_generation' then 'hearth_framing_pack_generation_results'
    when 'hearth.thumbnail_direction_generation' then 'hearth_thumbnail_direction_generation_results'
    else null end;
  if v_table is null then raise exception 'unsupported owner Hearth result route' using errcode='22023'; end if;
  execute format(
    'select to_jsonb(r)||jsonb_build_object(''owner_operation'',jsonb_build_object(''operation_id'',o.operation_id,''operation_key'',o.operation_key,''workspace_id'',o.workspace_id,''workpiece_id'',o.workpiece_id,''financial_environment'',o.financial_environment,''runtime_environment'',o.runtime_environment),''valuations'',coalesce((select jsonb_agg(jsonb_build_object(''valuation_id'',v.valuation_id,''basis'',v.valuation_basis,''recognition_mode'',v.recognition_mode,''journal_event_id'',v.journal_event_id) order by v.revision) from tongs.owner_cost_valuations v where v.attempt_id=a.attempt_id),''[]''::jsonb)) from tongs.%I r join tongs.owner_cost_provider_attempts a on a.attempt_id=r.owner_cost_attempt_id join tongs.owner_cost_operations o on o.operation_id=a.operation_id where r.owner_cost_attempt_id=$1',
    v_table
  ) into v_result using p_owner_cost_attempt_id;
  return v_result;
end $_$;


ALTER FUNCTION "tongs"."read_owner_hearth_text_result"("p_owner_cost_attempt_id" "uuid", "p_route_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."read_owner_operating_budget_activity"("p_budget_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare v_actor uuid:=auth.uid(); v_budget jsonb; v_consumptions jsonb;
begin
 if coalesce(auth.role(),'')<>'service_role' and (v_actor is null or not tongs.is_platform_operator(v_actor)) then
  raise exception 'platform operator required' using errcode='42501'; end if;
 select to_jsonb(b) into v_budget from (
  select budget.*,revision.revision,revision.status,revision.maximum_amount_micros,revision.reason,
   tongs._owner_operating_budget_effective_consumed(budget.id) effective_consumed_micros
  from tongs.owner_operating_budgets budget
  join lateral(select r.revision,r.status,r.maximum_amount_micros,r.reason
    from tongs.owner_operating_budget_revisions r where r.budget_id=budget.id order by r.revision desc limit 1) revision on true
  where budget.id=p_budget_id
 ) b;
 if v_budget is null then raise exception 'owner operating budget not found' using errcode='P0002'; end if;
 select coalesce(jsonb_agg(to_jsonb(c)||jsonb_build_object(
   'effective_expense_amount_micros',tongs._owner_operating_budget_effective_consumption(c.id),
   'reconciliation_adjustments',coalesce((select jsonb_agg(to_jsonb(a) order by a.created_at)
     from tongs.owner_operating_budget_reconciliation_adjustments a where a.consumption_id=c.id),'[]'::jsonb)
 ) order by c.consumed_at),'[]'::jsonb) into v_consumptions
 from tongs.owner_operating_budget_consumptions c where c.budget_id=p_budget_id;
 return jsonb_build_object('budget',v_budget,'consumptions',v_consumptions,
  'discrepancies',(select coalesce(jsonb_agg(to_jsonb(d) order by d.created_at),'[]'::jsonb)
    from tongs.owner_operating_budget_discrepancies d where d.budget_id=p_budget_id),
  'customer_revenue_micros',0,'margin','not_applicable');
end $$;


ALTER FUNCTION "tongs"."read_owner_operating_budget_activity"("p_budget_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."read_owner_pricing_reservations"("p_limit" integer DEFAULT 250) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_limit integer := least(greatest(coalesce(p_limit,250),1),2000);
  v_control tongs.paid_execution_control_revisions%rowtype;
  v_pricing jsonb;
  v_reservations jsonb;
  v_discrepancies jsonb;
begin
  if coalesce(auth.role(), '') <> 'service_role'
     and (v_actor is null or not tongs.is_platform_operator(v_actor)) then
    raise exception 'platform operator required' using errcode = '42501';
  end if;
  select * into v_control from tongs._current_paid_execution_control();
  select coalesce(jsonb_agg(to_jsonb(row_data) order by row_data.created_at desc), '[]'::jsonb)
    into v_pricing from (
      select policy.policy_code, policy.scope_kind, policy.provider, policy.sku,
        revision.id as revision_id, revision.revision, revision.lifecycle_state, revision.currency,
        revision.markup_basis_points, revision.full_cost_ceiling_micros,
        revision.failure_cost_ceiling_micros, revision.customer_price_ceiling_micros,
        revision.billable_failure_ceiling_micros, revision.customer_credit_units,
        revision.content_hash, revision.created_at
      from tongs.private_pricing_revisions revision
      join tongs.private_pricing_policies policy on policy.id = revision.policy_id
      order by revision.created_at desc limit v_limit
    ) row_data;
  select coalesce(jsonb_agg(to_jsonb(row_data) order by row_data.created_at desc), '[]'::jsonb)
    into v_reservations from (
      select reservation.*, tongs._funding_reservation_state(reservation.id) as state
      from tongs.funding_reservations reservation order by reservation.created_at desc limit v_limit
    ) row_data;
  select coalesce(jsonb_agg(to_jsonb(discrepancy) order by discrepancy.created_at desc), '[]'::jsonb)
    into v_discrepancies from (
      select * from tongs.pricing_discrepancies order by created_at desc limit v_limit
    ) discrepancy;
  return jsonb_build_object('control', to_jsonb(v_control), 'pricing_revisions', v_pricing,
    'reservations', v_reservations, 'pricing_discrepancies', v_discrepancies);
end;
$$;


ALTER FUNCTION "tongs"."read_owner_pricing_reservations"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."read_owner_purchase_activity"("p_stripe_mode" "text" DEFAULT 'test'::"text", "p_limit" integer DEFAULT 100) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare v_base jsonb; v_mode text:=lower(btrim(coalesce(p_stripe_mode,''))); v_deposits jsonb;
begin
  if coalesce(auth.role(),'')<>'service_role' and (auth.uid() is null or not tongs.is_platform_operator(auth.uid())) then raise exception 'platform operator required' using errcode='42501'; end if;
  v_base:=tongs._read_owner_purchase_activity_before_test_ai_deposits(v_mode,p_limit);
  select coalesce(jsonb_agg(to_jsonb(x) order by x.observed_at desc),'[]'::jsonb) into v_deposits from (
    select d.id::text purchase_id,d.user_id,c.email customer_email,c.customer_name,d.stripe_mode,'ai_credits'::text purchase_type,d.pack_id item_id,'one_time'::text interval,'paid'::text status,
      d.stripe_session_id checkout_session_id,null::text stripe_invoice_id,'paid'::text payment_status,lower(d.currency) checkout_currency,(d.gross_amount_micros/10000)::bigint checkout_amount_minor,
      e.processed_at checkout_processed_at,d.id::text accounting_receipt_id,d.gross_amount_micros accounted_cash_micros,d.currency accounting_currency,d.received_at accounting_received_at,
      0::integer allowance_grant_count,0::bigint allocated_revenue_micros,0::bigint maximum_wholesale_spend_micros,
      coalesce(cons.recognized,0)::bigint recognized_revenue_micros,'deposit_receipt_recorded'::text accounting_state,
      (d.stripe_mode='live' and fee.id is not null)::boolean live_funding_eligible,
      case when e.stripe_event_id is null then '[]'::jsonb else jsonb_build_array(jsonb_build_object('event_id',e.stripe_event_id,'event_type',e.event_type,'processed_at',e.processed_at)) end signed_webhook_events,
      coalesce(e.processed_at,d.received_at) observed_at
    from tongs.customer_deposits d join tongs.billing_customers c on c.user_id=d.user_id
    left join tongs.billing_events e on e.stripe_event_id=d.stripe_event_id and e.livemode=(d.stripe_mode='live')
    left join tongs.customer_deposit_processor_fees fee on fee.deposit_id=d.id
    left join lateral (select sum(recognized_revenue_micros) recognized from tongs.customer_deposit_consumptions where deposit_id=d.id) cons on true
    where d.stripe_mode=v_mode order by d.received_at desc limit least(greatest(coalesce(p_limit,100),1),500)
  ) x;
  return jsonb_set(v_base,'{purchases}',v_deposits||coalesce(v_base->'purchases','[]'::jsonb),true)
    || jsonb_build_object('contract_version','forge.owner-purchase-activity.v2');
end $$;


ALTER FUNCTION "tongs"."read_owner_purchase_activity"("p_stripe_mode" "text", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."read_owner_unified_visual_plan_operation"("p_owner_cost_attempt_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare v_result jsonb;
begin
  perform tongs._require_owner_cost_reader();
  select to_jsonb(operation)||jsonb_build_object(
      'owner_operation',jsonb_build_object(
        'operation_id',owner_operation.operation_id,'operation_key',owner_operation.operation_key,
        'financial_environment',owner_operation.financial_environment,
        'runtime_environment',owner_operation.runtime_environment),
      'valuations',coalesce((select jsonb_agg(to_jsonb(valuation) order by valuation.revision)
        from tongs.owner_cost_valuations valuation where valuation.attempt_id=attempt.attempt_id),'[]'::jsonb))
    into v_result
    from tongs.unified_visual_plan_operations operation
    join tongs.owner_cost_provider_attempts attempt on attempt.attempt_id=operation.owner_cost_attempt_id
    join tongs.owner_cost_operations owner_operation on owner_operation.operation_id=attempt.operation_id
    where operation.owner_cost_attempt_id=p_owner_cost_attempt_id;
  return v_result;
end
$$;


ALTER FUNCTION "tongs"."read_owner_unified_visual_plan_operation"("p_owner_cost_attempt_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."read_owner_visual_narrative_interpretation_result"("p_owner_cost_attempt_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare v_result jsonb;
begin
  perform tongs._require_owner_cost_reader();
  select to_jsonb(r)||jsonb_build_object(
    'owner_operation',jsonb_build_object(
      'operation_id',o.operation_id,'operation_key',o.operation_key,
      'workspace_id',o.workspace_id,'workpiece_id',o.workpiece_id,
      'financial_environment',o.financial_environment,'runtime_environment',o.runtime_environment),
    'canonical_receipt',case when receipt.result_id is null then null else to_jsonb(receipt) end
  ) into v_result
  from tongs.visual_narrative_interpretation_results r
  join tongs.owner_cost_provider_attempts a on a.attempt_id=r.owner_cost_attempt_id
  join tongs.owner_cost_operations o on o.operation_id=a.operation_id
  left join tongs.visual_narrative_interpretation_canonical_receipts receipt on receipt.result_id=r.id
  where r.owner_cost_attempt_id=p_owner_cost_attempt_id;
  return v_result;
end $$;


ALTER FUNCTION "tongs"."read_owner_visual_narrative_interpretation_result"("p_owner_cost_attempt_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."read_owner_workspace_cost_audit"("p_workspace_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
begin
  if coalesce(auth.role(), '') <> 'service_role'
     and not tongs.is_platform_operator(auth.uid()) then
    raise exception 'platform operator authority required' using errcode = '42501';
  end if;
  return tongs.read_workspace_cost_ledger(p_workspace_id, p_from, p_to);
end;
$$;


ALTER FUNCTION "tongs"."read_owner_workspace_cost_audit"("p_workspace_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."read_paid_execution_aggregate_admin"("p_limit" integer DEFAULT 250) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare lim integer:=least(greatest(coalesce(p_limit,250),1),2000);
begin
 if coalesce(auth.role(),'')<>'service_role' and not tongs.is_platform_operator(auth.uid()) then raise exception 'platform operator required' using errcode='42501'; end if;
 return jsonb_build_object(
  'assignments',(select coalesce(jsonb_agg(to_jsonb(x) order by created_at desc),'[]'::jsonb) from (select * from tongs.paid_execution_aggregate_assignments order by created_at desc limit lim)x),
  'bindings',(select coalesce(jsonb_agg(to_jsonb(x) order by created_at desc),'[]'::jsonb) from (select * from tongs.paid_operation_aggregate_bindings order by created_at desc limit lim)x),
  'holds',(select coalesce(jsonb_agg(to_jsonb(x) order by created_at desc),'[]'::jsonb) from (select * from tongs.restricted_beta_exposure_holds order by created_at desc limit lim)x),
  'events',(select coalesce(jsonb_agg(to_jsonb(x) order by created_at desc),'[]'::jsonb) from (select * from tongs.restricted_beta_exposure_events order by created_at desc limit lim)x));
end $$;


ALTER FUNCTION "tongs"."read_paid_execution_aggregate_admin"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."read_pending_customer_deposits_for_fee_recovery"("p_limit" integer DEFAULT 20) RETURNS TABLE("deposit_id" "uuid", "stripe_payment_intent_id" "text", "currency" "text", "received_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
begin
  perform tongs._require_accounting_service_role();
  if p_limit not between 1 and 50 then raise exception 'recovery limit must be between 1 and 50' using errcode='22023'; end if;
  return query select deposit.id,deposit.stripe_payment_intent_id,deposit.currency,deposit.received_at
    from tongs.customer_deposits deposit
    where deposit.stripe_mode='live' and deposit.stripe_payment_intent_id is not null
      and not exists(select 1 from tongs.customer_deposit_processor_fees fee where fee.deposit_id=deposit.id)
    order by deposit.received_at asc limit p_limit;
end $$;


ALTER FUNCTION "tongs"."read_pending_customer_deposits_for_fee_recovery"("p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."read_publication_operation"("p_publication_operation_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare v_op tongs.publication_operations%rowtype; v_state text;
begin
  select * into v_op from tongs.publication_operations where id=p_publication_operation_id;
  if not found then return jsonb_build_object('disposition','missing'); end if;
  if auth.uid() is null or not tongs.has_workspace_role(v_op.workspace_id,'viewer') then raise exception 'Not authorized to read publication operation' using errcode='42501'; end if;
  select case a.state when 'reserved' then 'reserved' when 'preparing_execution' then 'executing' when 'submitting' then 'executing' when 'succeeded' then 'succeeded' when 'confirmed_failure' then 'retryable_failure' when 'recoverable_failure' then 'retryable_failure' when 'blocked' then 'blocked' when 'outcome_unknown' then 'outcome_unknown' else 'reserved' end into v_state from tongs.publication_attempts a where a.publication_operation_id=v_op.id order by a.attempt_number desc limit 1;
  return jsonb_build_object('disposition','found','operation_state',coalesce(v_state,'reserved'),'authority',to_jsonb(v_op),'attempts',(select coalesce(jsonb_agg(to_jsonb(a) order by a.attempt_number),'[]'::jsonb) from tongs.publication_attempts a where a.publication_operation_id=v_op.id),'receipts',(select coalesce(jsonb_agg(to_jsonb(r) order by r.observed_at),'[]'::jsonb) from tongs.publication_receipts r where r.publication_operation_id=v_op.id));
end; $$;


ALTER FUNCTION "tongs"."read_publication_operation"("p_publication_operation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."read_publication_operations_for_manifest"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_manifest_snapshot_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
  select case when auth.uid() is null or not tongs.has_workspace_role(p_workspace_id,'viewer') then '[]'::jsonb else coalesce(jsonb_agg(jsonb_build_object(
    'publication_operation_id',o.id,'operation_key',o.operation_key,'authority_fingerprint',o.authority_fingerprint,
    'manifest_snapshot_id',o.manifest_snapshot_id,'release_decision_id',o.release_decision_id,'release_decision_revision',o.release_decision_revision,
    'executable_destination_id',o.executable_destination_id,'destination_capability_revision_id',o.destination_capability_revision_id,
    'operation_state',coalesce((select case a.state when 'reserved' then 'reserved' when 'preparing_execution' then 'executing' when 'submitting' then 'executing' when 'succeeded' then 'succeeded' when 'confirmed_failure' then 'retryable_failure' when 'recoverable_failure' then 'retryable_failure' when 'blocked' then 'blocked' when 'outcome_unknown' then 'outcome_unknown' end from tongs.publication_attempts a where a.publication_operation_id=o.id order by a.attempt_number desc limit 1),'reserved'),
    'established_at',o.established_at
  ) order by o.established_at desc),'[]'::jsonb) end from tongs.publication_operations o
  where o.workspace_id=p_workspace_id and o.workpiece_id=p_workpiece_id and o.manifest_snapshot_id=p_manifest_snapshot_id;
$$;


ALTER FUNCTION "tongs"."read_publication_operations_for_manifest"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_manifest_snapshot_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."read_quench_metadata_assist_result"("p_operation_id" "text", "p_reservation_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$ declare r tongs.quench_metadata_assist_results%rowtype; begin
  perform tongs._require_pricing_service_role(); select * into r from tongs.quench_metadata_assist_results where operation_id=btrim(p_operation_id) and reservation_id=p_reservation_id;
  if not found then raise exception 'metadata assist result not found' using errcode='P0002'; end if;
  return r.result_json||jsonb_build_object('domain_result_id',r.id,'provider_request_id',r.provider_request_id,'input_units',r.input_units,'output_units',r.output_units);
end $$;


