CREATE OR REPLACE FUNCTION "tongs"."read_workspace_billing_ledger"("p_workspace_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_operations jsonb;
  v_balance bigint;
begin
  if auth.uid() is null or not tongs.has_workspace_role(p_workspace_id, 'viewer') then
    raise exception 'workspace viewer authority required' using errcode = '42501';
  end if;
  if p_from is null or p_to is null or p_to <= p_from then
    raise exception 'invalid ledger time range' using errcode = '22023';
  end if;

  select c.token_balance into v_balance
  from tongs.ai_credits c
  where c.user_id = auth.uid();

  select coalesce(jsonb_agg(jsonb_build_object(
    'operation_id', o.operation_id,
    'occurred_at', o.created_at,
    'state', o.state,
    'tool', o.originating_tool,
    'media_kind', o.media_kind,
    'provider', o.provider,
    'payment_source', case
      when o.payer = 'customer_provider_account' then 'provider_byo'
      when o.payer = 'forge' then 'forge_funded'
      else 'unknown'
    end,
    'maximum_customer_charge_credits', o.authorized_customer_ceiling,
    'settled_customer_charge_credits', case
      when o.state = 'settled' then coalesce((o.terminal_receipt_json->>'settled_customer_charge')::bigint, 0)
      else null
    end,
    'workpiece_id', o.workpiece_id
  ) order by o.created_at desc), '[]'::jsonb)
  into v_operations
  from tongs.paid_media_operations o
  where o.workspace_id = p_workspace_id
    and o.created_at >= p_from and o.created_at < p_to;

  return jsonb_build_object(
    'contract_version', 'forge.workspace-billing-ledger.v1',
    'workspace_id', p_workspace_id,
    'from', p_from,
    'to', p_to,
    'current_user_credit_balance', coalesce(v_balance, 0),
    'operations', v_operations,
    'coverage', jsonb_build_object(
      'paid_media', 'customer_charge_receipts',
      'legacy_ai_activity', 'unavailable_until_workspace_scoped_accounting'
    )
  );
end;
$$;


ALTER FUNCTION "tongs"."read_workspace_billing_ledger"("p_workspace_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."read_workspace_cost_ledger"("p_workspace_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_components jsonb;
  v_fly_count bigint;
begin
  if coalesce(auth.role(), '') <> 'service_role'
     and not tongs.is_platform_operator(auth.uid()) then
    raise exception 'platform operator authority required' using errcode = '42501';
  end if;
  if p_workspace_id is null or p_from is null or p_to is null or p_to <= p_from then
    raise exception 'invalid ledger scope or time range' using errcode = '22023';
  end if;

  with component_rows as (
    select e.created_at as incurred_at, 'ai_request'::text as category, e.feature, e.subfeature,
      coalesce(nullif(e.provider, ''), 'unknown') as provider,
      coalesce(nullif(e.effective_ai_key_source, ''), nullif(e.key_source, ''),
        case when e.lane = 'byo' then 'user_byo' else 'forge_managed' end) as key_source,
      case when coalesce(nullif(e.effective_ai_key_source, ''), nullif(e.key_source, ''), '') in ('user_byo', 'byo')
        then 'customer_provider_account' else 'forge' end as payer,
      'pricing_estimate'::text as cost_basis,
      coalesce(e.estimated_cost_usd, e.actual_cost_usd, 0)::numeric as cost_usd,
      e.workpiece_id
    from tongs.ai_usage_events e
    where e.workspace_id = p_workspace_id and e.status = 'success'
      and e.created_at >= p_from and e.created_at < p_to

    union all

    select coalesce(a.completed_at, a.created_at), 'paid_media'::text, o.originating_tool, o.media_kind,
      coalesce(nullif(a.provider, ''), nullif(o.provider, ''), 'unknown'),
      o.credential_source, o.payer, 'provider_usage_actual'::text,
      usage_totals.cost_usd, o.workpiece_id
    from tongs.paid_media_provider_attempts a
    join tongs.paid_media_operations o on o.id = a.paid_media_operation_id
    join lateral (
      select (sum(u.expense_numerator / u.expense_denominator) / 1000000)::numeric as cost_usd
      from tongs.paid_media_actual_usage_components u
      where u.provider_attempt_id = a.id
    ) usage_totals on usage_totals.cost_usd is not null
    where o.workspace_id = p_workspace_id
      and coalesce(a.completed_at, a.created_at) >= p_from
      and coalesce(a.completed_at, a.created_at) < p_to

    union all

    select x.incurred_at, 'infrastructure'::text, x.service, null::text, x.provider,
      'external_billing'::text, x.payer, x.cost_basis, x.amount_usd::numeric, x.workpiece_id
    from tongs.external_cost_observations x
    where x.workspace_id = p_workspace_id
      and x.incurred_at >= p_from and x.incurred_at < p_to
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'incurred_at', incurred_at, 'category', category, 'feature', feature,
    'subfeature', subfeature, 'provider', provider, 'key_source', key_source,
    'payer', payer, 'cost_basis', cost_basis, 'cost_usd', cost_usd,
    'workpiece_id', workpiece_id
  ) order by incurred_at desc), '[]'::jsonb)
  into v_components from component_rows where cost_usd > 0;

  select count(*) into v_fly_count
  from tongs.external_cost_observations x
  where x.workspace_id = p_workspace_id
    and lower(x.provider) in ('fly', 'fly.io', 'fly_io')
    and x.incurred_at >= p_from and x.incurred_at < p_to;

  return jsonb_build_object(
    'contract_version', 'forge.owner-workspace-cost-audit.v1',
    'workspace_id', p_workspace_id, 'from', p_from, 'to', p_to,
    'components', v_components,
    'coverage', jsonb_build_object(
      'ai_requests', jsonb_build_object('state', 'estimated'),
      'paid_media', jsonb_build_object('state', 'provider_usage_actual'),
      'fly_io', jsonb_build_object('state', case when v_fly_count > 0 then 'invoice_actual' else 'unavailable' end)
    )
  );
end;
$$;


ALTER FUNCTION "tongs"."read_workspace_cost_ledger"("p_workspace_id" "uuid", "p_from" timestamp with time zone, "p_to" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."read_youtube_publication_progress"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_publication_operation_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
  select case when auth.uid() is null or not tongs.has_workspace_role(p_workspace_id,'viewer') then null else
    (select jsonb_build_object('publication_operation_id',j.publication_operation_id,'stage',j.state,'transferred_bytes',j.transferred_bytes,'total_bytes',j.total_bytes,
      'percent',case when j.total_bytes>0 then least(100,floor(j.transferred_bytes*100.0/j.total_bytes)) else 0 end,
      'retryable',j.retryable,'user_action_code',j.user_action_code,'provider_processing_state',j.provider_processing_state,
      'external_object_id',j.external_object_id,'external_url',j.external_url,'updated_at',j.updated_at)
     from tongs.youtube_publication_jobs j where j.workspace_id=p_workspace_id and j.workpiece_id=p_workpiece_id and j.publication_operation_id=p_publication_operation_id)
  end;
$$;


ALTER FUNCTION "tongs"."read_youtube_publication_progress"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_publication_operation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."rearm_owner_hearth_chat_luna_pilot"("p_operator_user_id" "uuid", "p_budget_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_reason text:=nullif(btrim(coalesce(p_reason,'')),'');
  v_budget tongs.owner_operating_budgets%rowtype;
  v_budget_revision tongs.owner_operating_budget_revisions%rowtype;
  v_rollout tongs.openai_text_rollout_revisions%rowtype;
  v_next_rollout integer;
begin
  perform tongs._require_pricing_service_role();
  if p_operator_user_id is null or not tongs.is_platform_operator(p_operator_user_id)
     or p_budget_id is null or v_reason is null then
    raise exception 'invalid owner Luna pilot rearm' using errcode='22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('owner-hearth-openai-luna-pilot',0));
  select * into v_budget from tongs.owner_operating_budgets where id=p_budget_id;
  select * into v_budget_revision from tongs.owner_operating_budget_revisions
    where budget_id=p_budget_id order by revision desc limit 1;
  if not found or v_budget.created_by<>p_operator_user_id or v_budget.environment<>'production'
     or lower(coalesce(v_budget.provider,''))<>'openai'
     or lower(coalesce(v_budget.route,''))<>'hearth.chat_completion'
     or lower(coalesce(v_budget.sku,''))<>'gpt-5.6-luna'
     or v_budget_revision.status<>'active' or v_budget_revision.maximum_amount_micros<>11015
     or clock_timestamp()>=v_budget.period_end then
    raise exception 'exact active owner Luna pilot budget not found' using errcode='P0002';
  end if;
  if not exists(select 1 from tongs.openai_text_activation_decisions
    where proposal_id='30000000-0000-4000-8000-000000000002'::uuid
      and decision='approved' and operator_user_id=p_operator_user_id) then
    raise exception 'approved Luna pilot decision missing' using errcode='42501';
  end if;
  if exists(select 1 from tongs.funding_reservations r
    where r.funding_source_type='owner_budget' and r.funding_source_id=p_budget_id
      and (tongs._funding_reservation_state(r.id)<>'released' or exists(
        select 1 from tongs.funding_reservation_events e
        where e.reservation_id=r.id and e.event_type='provider_attempt_shadowed'))) then
    raise exception 'Luna pilot cannot rearm after a provider attempt or unresolved reservation' using errcode='P0001';
  end if;
  select * into v_rollout from tongs._current_openai_text_rollout('hearth.chat_completion');
  if v_rollout.mode<>'halt_new' or v_rollout.cost_policy_revision_id is distinct from
     '10000000-0000-4000-8000-000000000010'::uuid then
    raise exception 'Luna pilot rearm requires exact halted rollout' using errcode='P0001';
  end if;
  select coalesce(max(revision),0)+1 into v_next_rollout
    from tongs.openai_text_rollout_revisions where route_code='hearth.chat_completion';
  insert into tongs.openai_text_rollout_revisions(
    route_code,revision,mode,cost_policy_revision_id,reason,actor_id
  ) values (
    'hearth.chat_completion',v_next_rollout,'enforce',
    '10000000-0000-4000-8000-000000000010',v_reason,p_operator_user_id
  );
  return jsonb_build_object(
    'budget_id',p_budget_id,'rollout_mode','enforce','rollout_revision',v_next_rollout,
    'maximum_amount_micros',11015,'customer_settlement_enabled',false,
    'prior_provider_submissions',0
  );
end $$;


ALTER FUNCTION "tongs"."rearm_owner_hearth_chat_luna_pilot"("p_operator_user_id" "uuid", "p_budget_id" "uuid", "p_reason" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."rearm_owner_hearth_chat_luna_pilot"("p_operator_user_id" "uuid", "p_budget_id" "uuid", "p_reason" "text") IS 'Rearms the exact Luna owner pilot only after all earlier reservations were released before any provider attempt; creates no budget and does not increase its cap.';



CREATE OR REPLACE FUNCTION "tongs"."rearm_owner_hearth_preprovider_release"("p_reservation_id" "uuid", "p_operator_user_id" "uuid", "p_event_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare op tongs.owner_hearth_operation_authorizations%rowtype;
 authz tongs.owner_hearth_authorizations%rowtype;
 auth_event tongs.owner_hearth_authorization_events%rowtype;
 latest tongs.funding_reservation_events%rowtype;
 released tongs.funding_reservation_events%rowtype;
 reserved_event tongs.funding_reservation_events%rowtype;
 recovery tongs.owner_hearth_operation_recovery_authorizations%rowtype;
 nextseq integer;
 recovery_expiry timestamptz;
 recovery_replay boolean:=false;
begin
 perform tongs._require_pricing_service_role();
 if p_reservation_id is null or p_operator_user_id is null
    or not tongs.is_platform_operator(p_operator_user_id)
    or length(btrim(coalesce(p_event_key,'')))<8 then
  raise exception 'service-role platform operator required' using errcode='42501'; end if;
 perform pg_advisory_xact_lock(hashtextextended('owner-hearth-preprovider-rearm:'||p_reservation_id::text,0));
 select * into op from tongs.owner_hearth_operation_authorizations where reservation_id=p_reservation_id;
 select * into authz from tongs.owner_hearth_authorizations where id=op.authorization_id;
 select * into auth_event from tongs.owner_hearth_authorization_events where authorization_id=authz.id order by sequence desc limit 1;
 if op.id is null or authz.authorization_kind<>'compatibility_batch'
    or authz.owner_user_id<>p_operator_user_id or auth_event.state<>'active'
    or auth_event.expires_at<=now() then
  raise exception 'active exact-owner compatibility authorization required' using errcode='42501'; end if;
 select * into released from tongs.funding_reservation_events
 where reservation_id=p_reservation_id and event_type='released'
 order by sequence desc limit 1;
 if released.id is null or released.evidence_json->>'reason'<>'aggregate_concurrency_exhausted'
    or coalesce((released.evidence_json->>'transmitted')::boolean,true) then
  raise exception 'aggregate-concurrency pre-provider release evidence required' using errcode='P0001'; end if;
 if exists(select 1 from tongs.funding_reservation_events e where e.reservation_id=p_reservation_id and e.event_type='provider_attempt_shadowed')
    or exists(select 1 from tongs.openai_text_failure_exposure_holds h where h.reservation_id=p_reservation_id)
    or exists(select 1 from tongs.openai_text_usage_evidence u where u.reservation_id=p_reservation_id)
    or exists(select 1 from tongs.supplier_expenses s where s.reservation_id=p_reservation_id)
    or exists(select 1 from tongs.owner_hearth_compatibility_results r where r.operation_authorization_id=op.id) then
  raise exception 'provider or terminal evidence prevents pre-provider recovery' using errcode='P0001'; end if;
 select * into latest from tongs.funding_reservation_events where reservation_id=p_reservation_id order by sequence desc limit 1;
 if latest.event_type='released' then
  select coalesce(max(sequence),0)+1 into nextseq from tongs.funding_reservation_events where reservation_id=p_reservation_id;
  insert into tongs.funding_reservation_events(id,reservation_id,sequence,event_type,event_key,evidence_json)
  values(extensions.uuid_generate_v5(p_reservation_id,btrim(p_event_key)),p_reservation_id,nextseq,'reserved',btrim(p_event_key),
   jsonb_build_object('operator_user_id',p_operator_user_id,'recovery','aggregate_terminal_concurrency_fix',
    'transmitted',false,'provider_submission_count',0,'original_operation_identity_preserved',true))
  returning * into reserved_event;
 elsif latest.event_type='reserved' and latest.evidence_json->>'recovery'='aggregate_terminal_concurrency_fix' then
  reserved_event:=latest;
 else
  raise exception 'reservation is not eligible for pre-provider recovery' using errcode='P0001'; end if;
 select * into recovery from tongs.owner_hearth_operation_recovery_authorizations
 where operation_authorization_id=op.id and event_key=btrim(p_event_key)||':quote-recovery';
 if found then
  recovery_replay:=true;
 else
  recovery_expiry:=least(auth_event.expires_at,now()+interval '10 minutes');
  insert into tongs.owner_hearth_operation_recovery_authorizations(
   id,operation_authorization_id,reservation_id,event_key,authorized_by,reason,expires_at,evidence_json
  ) values(
   extensions.uuid_generate_v5(op.id,'preprovider-recovery:'||btrim(p_event_key)),op.id,p_reservation_id,btrim(p_event_key)||':quote-recovery',
   p_operator_user_id,'Continue unchanged accepted compatibility operation after pre-provider aggregate-concurrency defect.',
   recovery_expiry,jsonb_build_object('original_quote_expires_at',op.expires_at,'request_fingerprint',op.request_fingerprint,
    'serialized_body_sha256',op.serialized_body_sha256,'pricing_revision_id',op.pricing_revision_id,
    'cost_policy_revision_id',op.cost_policy_revision_id,'customer_charge_micros',0)
  ) returning * into recovery;
 end if;
 return jsonb_build_object('reservation_id',p_reservation_id,'operation_id',op.operation_id,'model',op.provider_model_id,
  'reservation_state','reserved','recovery_expires_at',recovery.expires_at,'replay',recovery_replay);
end $$;


ALTER FUNCTION "tongs"."rearm_owner_hearth_preprovider_release"("p_reservation_id" "uuid", "p_operator_user_id" "uuid", "p_event_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."rearm_owner_hearth_preprovider_release"("p_reservation_id" "uuid", "p_operator_user_id" "uuid", "p_event_key" "text") IS 'Append-only recovery for an exact owner compatibility operation rejected by aggregate concurrency before any provider attempt; preserves the original operation and accepted terms.';



CREATE OR REPLACE FUNCTION "tongs"."rearm_standard_customer_preprovider_release"("p_reservation_id" "uuid", "p_actor_id" "uuid", "p_event_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  reservation tongs.funding_reservations%rowtype;
  scope_auth tongs.customer_paid_execution_scope_authorizations%rowtype;
  binding tongs.openai_text_funding_bindings%rowtype;
  quote_binding tongs.openai_text_customer_quote_bindings%rowtype;
  assignment tongs.paid_execution_aggregate_assignments%rowtype;
  latest tongs.funding_reservation_events%rowtype;
  released tongs.funding_reservation_events%rowtype;
  rearmed tongs.funding_reservation_events%rowtype;
  next_sequence integer;
begin
  perform tongs._require_pricing_service_role();
  if p_reservation_id is null or p_actor_id is null
     or not tongs.is_platform_operator(p_actor_id)
     or length(btrim(coalesce(p_event_key, ''))) < 8 then
    raise exception 'service-role platform operator required' using errcode = '42501';
  end if;
  perform pg_advisory_xact_lock(
    hashtextextended('standard-customer-preprovider-rearm:' || p_reservation_id::text, 0)
  );
  select * into reservation from tongs.funding_reservations
  where id = p_reservation_id;
  select * into scope_auth from tongs.customer_paid_execution_scope_authorizations
  where id = reservation.rollout_authorization_id;
  select * into binding from tongs.openai_text_funding_bindings
  where reservation_id = reservation.id;
  select * into quote_binding from tongs.openai_text_customer_quote_bindings
  where quote_id = reservation.quote_id;
  select * into assignment
  from tongs._active_paid_execution_aggregate_assignment(
    reservation.user_id, quote_binding.workspace_id, 'test'
  );
  if reservation.id is null
     or reservation.funding_environment <> 'test'
     or reservation.funding_source_type not in ('customer_deposit', 'paid_allowance')
     or reservation.reserved_customer_charge_micros <> 15000
     or reservation.reserved_credit_units <> 3
     or reservation.reserved_wholesale_spend_micros <> 11015
     or scope_auth.id is null
     or scope_auth.created_by <> p_actor_id
     or scope_auth.status <> 'active'
     or scope_auth.valid_until <= now()
     or scope_auth.maximum_operation_count <> 1
     or binding.route_code <> 'hearth.chat_completion'
     or binding.model <> 'gpt-5.6-luna'
     or binding.maximum_attempts <> 1
     or binding.credential_funding <> 'forge'
     or binding.cost_policy_revision_id <> '10000000-0000-4000-8000-000000000010'::uuid
     or binding.pricing_revision_id <> 'b4c4472f-0325-4c2e-b2ef-9aef5e59e64a'::uuid
     or quote_binding.canonical_operation_id <> binding.operation_id
     or quote_binding.user_id <> reservation.user_id
     or assignment.id is null
     or assignment.policy_revision_id <> 'c0000000-0000-4000-8000-000000000002'::uuid then
    raise exception 'exact active standard-customer certification context required'
      using errcode = '42501';
  end if;
  if not exists (
    select 1 from tongs.customer_spending_quote_acceptances a
    where a.quote_id = reservation.quote_id and a.user_id = reservation.user_id
  ) then
    raise exception 'accepted immutable quote required' using errcode = '42501';
  end if;
  select * into released from tongs.funding_reservation_events
  where reservation_id = reservation.id and event_type = 'released'
  order by sequence desc limit 1;
  if released.id is null
     or released.evidence_json->>'reason' <> 'restricted_beta_inactive'
     or coalesce((released.evidence_json->>'transmitted')::boolean, true) then
    raise exception 'exact untransmitted aggregate pre-provider release required'
      using errcode = 'P0001';
  end if;
  if exists (
      select 1 from tongs.funding_reservation_events e
      where e.reservation_id = reservation.id
        and e.event_type in ('provider_attempt_shadowed', 'attempt_started', 'submission_unknown', 'settled')
    )
    or exists (select 1 from tongs.openai_text_failure_exposure_holds h where h.reservation_id = reservation.id)
    or exists (select 1 from tongs.openai_text_usage_evidence u where u.reservation_id = reservation.id)
    or exists (select 1 from tongs.openai_text_persisted_results p where p.reservation_id = reservation.id)
    or exists (select 1 from tongs.supplier_expenses s where s.reservation_id = reservation.id)
    or exists (select 1 from tongs.paid_operation_aggregate_bindings b where b.reservation_id = reservation.id) then
    raise exception 'provider, terminal, or aggregate evidence prevents pre-provider recovery'
      using errcode = 'P0001';
  end if;
  select * into latest from tongs.funding_reservation_events
  where reservation_id = reservation.id order by sequence desc limit 1;
  if latest.event_type = 'released' then
    select coalesce(max(sequence), 0) + 1 into next_sequence
    from tongs.funding_reservation_events where reservation_id = reservation.id;
    insert into tongs.funding_reservation_events(
      id, reservation_id, sequence, event_type, event_key, evidence_json
    ) values (
      extensions.uuid_generate_v5(reservation.id, btrim(p_event_key)),
      reservation.id, next_sequence, 'reserved', btrim(p_event_key),
      jsonb_build_object(
        'operator_user_id', p_actor_id,
        'recovery', 'standard_customer_aggregate_assignment_installed',
        'transmitted', false,
        'provider_submission_count', 0,
        'original_operation_identity_preserved', true
      )
    ) returning * into rearmed;
  elsif latest.event_type = 'reserved'
        and latest.evidence_json->>'recovery' = 'standard_customer_aggregate_assignment_installed' then
    rearmed := latest;
  else
    raise exception 'reservation is not eligible for pre-provider recovery'
      using errcode = 'P0001';
  end if;
  return jsonb_build_object(
    'reservation_id', reservation.id,
    'operation_id', binding.operation_id,
    'reservation_state', 'reserved',
    'aggregate_assignment_id', assignment.id,
    'replay', rearmed.id = latest.id
  );
end $$;


ALTER FUNCTION "tongs"."rearm_standard_customer_preprovider_release"("p_reservation_id" "uuid", "p_actor_id" "uuid", "p_event_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."rearm_standard_customer_preprovider_release"("p_reservation_id" "uuid", "p_actor_id" "uuid", "p_event_key" "text") IS 'Append-only recovery for an exact standard-customer reservation released before any provider transmission because aggregate authority was inactive.';



CREATE OR REPLACE FUNCTION "tongs"."reassign_reference_clip_source"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_opportunity_id" "uuid", "p_expected_opportunity_revision_id" "uuid", "p_expected_opportunity_revision" bigint, "p_source_revision_id" "uuid", "p_workpiece_source_link_revision_id" "uuid", "p_operation_id" "text", "p_operation_fingerprint" "text", "p_actor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
#variable_conflict use_column
declare prior jsonb; seq tongs.reference_clip_plan_sequences%rowtype; old_plan tongs.reference_clip_plan_revisions%rowtype; old_opp tongs.reference_clip_opportunity_revisions%rowtype; src tongs.source_revisions%rowtype; link_rev tongs.workpiece_source_link_revisions%rowtype; new_plan tongs.reference_clip_plan_revisions%rowtype; new_opp tongs.reference_clip_opportunity_revisions%rowtype; member_rev tongs.reference_clip_plan_membership%rowtype; plan_hash text; opportunity_hash text; immutable_hash text; result jsonb; new_status text;
begin
 if not tongs.has_workspace_role(p_workspace_id,'editor') or auth.uid() is distinct from p_actor_id then raise exception 'workspace editor authority required' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_operation_id,0));select receipt_json into prior from tongs.reference_clip_operation_receipts where operation_id=p_operation_id and operation_fingerprint=p_operation_fingerprint;if found then return prior;end if;if exists(select 1 from tongs.reference_clip_operation_receipts where operation_id=p_operation_id)then return jsonb_build_object('disposition','operation_identity_conflict');end if;
 if (p_source_revision_id is null)<>(p_workpiece_source_link_revision_id is null) then return jsonb_build_object('disposition','source_and_link_must_match');end if;new_status:=case when p_source_revision_id is null then 'unresolved' else 'linked' end;
 select * into seq from tongs.reference_clip_plan_sequences where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id for update;
 select o.* into old_opp from tongs.reference_clip_plan_membership m join tongs.reference_clip_opportunity_revisions o on o.id=m.opportunity_revision_id where m.plan_revision_id=seq.current_plan_revision_id and m.opportunity_id=p_opportunity_id;
 if not found or old_opp.id is distinct from p_expected_opportunity_revision_id or old_opp.revision<>p_expected_opportunity_revision then return jsonb_build_object('disposition','opportunity_revision_conflict');end if;
 if p_source_revision_id is not null then select * into src from tongs.source_revisions where id=p_source_revision_id and workspace_id=p_workspace_id;select * into link_rev from tongs.workpiece_source_link_revisions where id=p_workpiece_source_link_revision_id and workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and source_revision_id=src.id;if src.id is null or link_rev.id is null then return jsonb_build_object('disposition','canonical_source_evidence_required');end if;if old_opp.source_revision_id=src.id and old_opp.workpiece_source_link_revision_id=link_rev.id then return jsonb_build_object('disposition','source_unchanged');end if;elsif old_opp.source_status='unresolved' then return jsonb_build_object('disposition','source_already_unresolved');end if;
 select * into old_plan from tongs.reference_clip_plan_revisions where id=seq.current_plan_revision_id;plan_hash:=encode(extensions.digest(convert_to(jsonb_build_object('previous_plan',old_plan.content_hash,'source_transition_opportunity_revision',old_opp.id,'source_status',new_status,'source_revision',src.id,'source_link_revision',link_rev.id)::text,'UTF8'),'sha256'),'hex');immutable_hash:=encode(extensions.digest(convert_to(jsonb_build_object('hash',plan_hash,'revision',old_plan.revision+1,'previous',old_plan.id)::text,'UTF8'),'sha256'),'hex');
 insert into tongs.reference_clip_plan_revisions(workspace_id,workpiece_id,revision,previous_revision_id,previous_revision,script_approval_id,script_approval_revision,script_content_hash,contract_version,content_hash,immutable_revision_hash,created_by)values(p_workspace_id,p_workpiece_id,old_plan.revision+1,old_plan.id,old_plan.revision,old_plan.script_approval_id,old_plan.script_approval_revision,old_plan.script_content_hash,old_plan.contract_version,plan_hash,immutable_hash,p_actor_id)returning * into new_plan;
 opportunity_hash:=encode(extensions.digest(convert_to(jsonb_build_object('previous',old_opp.content_hash,'source_status',new_status,'source_revision',src.id,'source_link_revision',link_rev.id)::text,'UTF8'),'sha256'),'hex');immutable_hash:=encode(extensions.digest(convert_to(jsonb_build_object('hash',opportunity_hash,'plan',new_plan.id,'opportunity',old_opp.opportunity_id,'revision',old_opp.revision+1)::text,'UTF8'),'sha256'),'hex');
 insert into tongs.reference_clip_opportunity_revisions(opportunity_id,workspace_id,workpiece_id,revision,previous_revision_id,previous_revision,source_plan_revision_id,source_plan_revision,script_approval_id,script_approval_revision,source_status,source_id,source_revision_id,source_revision,workpiece_source_link_id,workpiece_source_link_revision_id,workpiece_source_link_revision,context_before,context_focus,context_after,citation_anchor_json,media_range_json,narrative_purpose,editorial_reason,desired_material,search_terms,placement_hint,duration_target_ms,creator_direction,content_hash,immutable_revision_hash,created_by)
 select opportunity_id,workspace_id,workpiece_id,revision+1,id,revision,new_plan.id,new_plan.revision,script_approval_id,script_approval_revision,new_status,src.source_id,src.id,src.revision,link_rev.link_id,link_rev.id,link_rev.revision,context_before,context_focus,context_after,citation_anchor_json,case when new_status='linked' then link_rev.media_range_json else media_range_json end,narrative_purpose,editorial_reason,desired_material,search_terms,placement_hint,duration_target_ms,creator_direction,opportunity_hash,immutable_hash,p_actor_id from tongs.reference_clip_opportunity_revisions where id=old_opp.id returning * into new_opp;
 for member_rev in select * from tongs.reference_clip_plan_membership where plan_revision_id=old_plan.id order by ordinal loop insert into tongs.reference_clip_plan_membership values(new_plan.id,p_workspace_id,p_workpiece_id,new_plan.revision,member_rev.ordinal,member_rev.opportunity_id,case when member_rev.opportunity_id=p_opportunity_id then new_opp.id else member_rev.opportunity_revision_id end,case when member_rev.opportunity_id=p_opportunity_id then new_opp.revision else member_rev.opportunity_revision end);end loop;
 update tongs.reference_clip_plan_sequences set current_plan_revision_id=new_plan.id,current_plan_revision=new_plan.revision,updated_at=now()where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id;
 result:=jsonb_build_object('disposition','committed','source_status',new_status,'plan_revision',to_jsonb(new_plan),'opportunity_revision',to_jsonb(new_opp));insert into tongs.reference_clip_operation_receipts(operation_id,operation_fingerprint,operation_type,workspace_id,workpiece_id,opportunity_id,state,result_plan_revision_id,receipt_json,created_by)values(p_operation_id,p_operation_fingerprint,'source_fulfillment',p_workspace_id,p_workpiece_id,p_opportunity_id,'committed',new_plan.id,result,p_actor_id);return result;
end$$;


