CREATE OR REPLACE FUNCTION "tongs"."reassign_reference_visual_source"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_opportunity_id" "uuid", "p_expected_opportunity_revision_id" "uuid", "p_expected_opportunity_revision" bigint, "p_source_revision_id" "uuid", "p_workpiece_source_link_revision_id" "uuid", "p_operation_id" "text", "p_operation_fingerprint" "text", "p_actor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
#variable_conflict use_column
declare receipt tongs.reference_visual_operation_receipts%rowtype; seq tongs.reference_visual_plan_sequences%rowtype; old_plan tongs.reference_visual_plan_revisions%rowtype; old_opp tongs.reference_visual_opportunity_revisions%rowtype; src tongs.source_revisions%rowtype; link_rev tongs.workpiece_source_link_revisions%rowtype; new_plan tongs.reference_visual_plan_revisions%rowtype; new_opp tongs.reference_visual_opportunity_revisions%rowtype; member_rev tongs.reference_visual_plan_membership%rowtype; plan_hash text; opportunity_hash text; immutable_hash text; result jsonb; new_status text;
begin
 if not tongs.has_workspace_role(p_workspace_id,'editor') or auth.uid() is distinct from p_actor_id then raise exception 'workspace editor authority required' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_operation_id,0));
 select * into receipt from tongs.reference_visual_operation_receipts where operation_id=p_operation_id;
 if found then if receipt.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict');end if;return receipt.receipt_json;end if;
 if (p_source_revision_id is null)<>(p_workpiece_source_link_revision_id is null) then return jsonb_build_object('disposition','source_and_link_must_match');end if;
 new_status:=case when p_source_revision_id is null then 'unresolved' else 'linked' end;
 select * into seq from tongs.reference_visual_plan_sequences where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id for update;
 select o.* into old_opp from tongs.reference_visual_plan_membership m join tongs.reference_visual_opportunity_revisions o on o.id=m.opportunity_revision_id where m.plan_revision_id=seq.current_plan_revision_id and m.opportunity_id=p_opportunity_id;
 if not found or old_opp.id is distinct from p_expected_opportunity_revision_id or old_opp.revision<>p_expected_opportunity_revision then return jsonb_build_object('disposition','opportunity_revision_conflict');end if;
 if p_source_revision_id is not null then
  select * into src from tongs.source_revisions where id=p_source_revision_id and workspace_id=p_workspace_id;
  select * into link_rev from tongs.workpiece_source_link_revisions where id=p_workpiece_source_link_revision_id and workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and source_revision_id=src.id;
  if src.id is null or link_rev.id is null then return jsonb_build_object('disposition','canonical_source_evidence_required');end if;
  if old_opp.source_revision_id=src.id and old_opp.workpiece_source_link_revision_id=link_rev.id then return jsonb_build_object('disposition','source_unchanged');end if;
 elsif old_opp.source_status='unresolved' then return jsonb_build_object('disposition','source_already_unresolved');end if;
 select * into old_plan from tongs.reference_visual_plan_revisions where id=seq.current_plan_revision_id;
 plan_hash:=encode(extensions.digest(convert_to(jsonb_build_object('previous_plan',old_plan.content_hash,'source_transition_opportunity_revision',old_opp.id,'source_status',new_status,'source_revision',src.id,'source_link_revision',link_rev.id)::text,'UTF8'),'sha256'),'hex');
 immutable_hash:=encode(extensions.digest(convert_to(jsonb_build_object('content_hash',plan_hash,'revision',old_plan.revision+1,'previous_revision_id',old_plan.id)::text,'UTF8'),'sha256'),'hex');
 insert into tongs.reference_visual_plan_revisions(workspace_id,workpiece_id,revision,previous_revision_id,previous_revision,script_approval_id,script_approval_revision,script_content_hash,contract_version,content_hash,immutable_revision_hash,created_by) values(p_workspace_id,p_workpiece_id,old_plan.revision+1,old_plan.id,old_plan.revision,old_plan.script_approval_id,old_plan.script_approval_revision,old_plan.script_content_hash,old_plan.contract_version,plan_hash,immutable_hash,p_actor_id) returning * into new_plan;
 opportunity_hash:=encode(extensions.digest(convert_to(jsonb_build_object('previous',old_opp.content_hash,'source_status',new_status,'source_revision',src.id,'source_link_revision',link_rev.id)::text,'UTF8'),'sha256'),'hex');
 immutable_hash:=encode(extensions.digest(convert_to(jsonb_build_object('content_hash',opportunity_hash,'revision',old_opp.revision+1,'previous_revision_id',old_opp.id)::text,'UTF8'),'sha256'),'hex');
 insert into tongs.reference_visual_opportunity_revisions(opportunity_id,workspace_id,workpiece_id,revision,previous_revision_id,previous_revision,source_plan_revision_id,source_plan_revision,script_approval_id,script_approval_revision,source_status,source_revision_id,source_revision,workpiece_source_link_revision_id,workpiece_source_link_revision,visual_subtype,context_before,context_focus,context_after,citation_anchor_json,document_locator_json,media_range_json,editorial_reason,desired_material,search_terms,placement_hint,duration_target_ms,creator_direction,content_hash,immutable_revision_hash,created_by)
 select opportunity_id,workspace_id,workpiece_id,revision+1,id,revision,new_plan.id,new_plan.revision,script_approval_id,script_approval_revision,new_status,src.id,src.revision,link_rev.id,link_rev.revision,visual_subtype,context_before,context_focus,context_after,citation_anchor_json,document_locator_json,media_range_json,editorial_reason,desired_material,search_terms,placement_hint,duration_target_ms,creator_direction,opportunity_hash,immutable_hash,p_actor_id from tongs.reference_visual_opportunity_revisions where id=old_opp.id returning * into new_opp;
 for member_rev in select * from tongs.reference_visual_plan_membership where plan_revision_id=old_plan.id order by ordinal loop insert into tongs.reference_visual_plan_membership values(new_plan.id,p_workspace_id,p_workpiece_id,new_plan.revision,member_rev.ordinal,member_rev.opportunity_id,case when member_rev.opportunity_id=p_opportunity_id then new_opp.id else member_rev.opportunity_revision_id end,case when member_rev.opportunity_id=p_opportunity_id then new_opp.revision else member_rev.opportunity_revision end);end loop;
 update tongs.reference_visual_plan_sequences set current_plan_revision_id=new_plan.id,current_plan_revision=new_plan.revision,updated_at=now() where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id;
 result:=jsonb_build_object('disposition','committed','source_status',new_status,'plan_revision',to_jsonb(new_plan),'opportunity_revision',to_jsonb(new_opp));
 insert into tongs.reference_visual_operation_receipts values(p_operation_id,p_operation_fingerprint,'source_fulfillment',p_workspace_id,p_workpiece_id,'committed',new_opp.id,result,p_actor_id,now());return result;
end$$;


ALTER FUNCTION "tongs"."reassign_reference_visual_source"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_opportunity_id" "uuid", "p_expected_opportunity_revision_id" "uuid", "p_expected_opportunity_revision" bigint, "p_source_revision_id" "uuid", "p_workpiece_source_link_revision_id" "uuid", "p_operation_id" "text", "p_operation_fingerprint" "text", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."recompute_account_balance"("p_user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare
  v_customer_id text;
  v_plan_item_id text;
  v_plan_interval text;
  v_plan_status text;
  v_plan_current_period_end timestamptz;
  v_plan_entitled boolean := false;
  v_storage_item_id text;
  v_storage_status text;
  v_storage_current_period_end timestamptz;
  v_storage_bytes_entitled bigint := 0;
  v_ai_credit_balance bigint := 0;
begin
  if p_user_id is null then
    raise exception 'p_user_id required'
      using errcode = '22023';
  end if;

  select c.stripe_customer_id
  into v_customer_id
  from tongs.billing_customers c
  where c.user_id = p_user_id;

  select
    s.item_id,
    s.interval,
    s.status,
    s.current_period_end
  into
    v_plan_item_id,
    v_plan_interval,
    v_plan_status,
    v_plan_current_period_end
  from tongs.billing_subscriptions s
  where s.user_id = p_user_id
    and s.purchase_type = 'subscription'
    and tongs.billing_item_is_plan(s.item_id)
  order by
    case when tongs.billing_status_entitles_access(s.status) then 0 else 1 end,
    s.current_period_end desc nulls last,
    s.updated_at desc
  limit 1;

  v_plan_entitled := tongs.billing_status_entitles_access(v_plan_status);

  -- Keep one representative storage row for status/period display.
  select
    s.item_id,
    s.status,
    s.current_period_end
  into
    v_storage_item_id,
    v_storage_status,
    v_storage_current_period_end
  from tongs.billing_subscriptions s
  where s.user_id = p_user_id
    and s.purchase_type = 'cloud_storage'
  order by
    case when tongs.billing_storage_entitlement_active(s.status, s.current_period_end) then 0 else 1 end,
    s.current_period_end desc nulls last,
    s.updated_at desc
  limit 1;

  -- Recurring storage requires both status and valid paid-through period.
  -- Status-only checks can over-grant when Stripe/webhook status updates lag.
  select coalesce(sum(tongs.billing_storage_entitled_bytes(s.item_id)), 0)
  into v_storage_bytes_entitled
  from tongs.billing_subscriptions s
  where s.user_id = p_user_id
    and s.purchase_type = 'cloud_storage'
    and tongs.billing_storage_entitlement_active(s.status, s.current_period_end);

  select c.token_balance
  into v_ai_credit_balance
  from tongs.ai_credits c
  where c.user_id = p_user_id;

  v_ai_credit_balance := coalesce(v_ai_credit_balance, 0);

  insert into tongs.account_balances (
    user_id,
    stripe_customer_id,
    plan_item_id,
    plan_interval,
    plan_status,
    plan_current_period_end,
    plan_entitled,
    storage_item_id,
    storage_status,
    storage_current_period_end,
    storage_bytes_entitled,
    ai_credit_balance
  )
  values (
    p_user_id,
    v_customer_id,
    v_plan_item_id,
    v_plan_interval,
    v_plan_status,
    v_plan_current_period_end,
    coalesce(v_plan_entitled, false),
    v_storage_item_id,
    v_storage_status,
    v_storage_current_period_end,
    coalesce(v_storage_bytes_entitled, 0),
    v_ai_credit_balance
  )
  on conflict (user_id) do update
  set
    stripe_customer_id = excluded.stripe_customer_id,
    plan_item_id = excluded.plan_item_id,
    plan_interval = excluded.plan_interval,
    plan_status = excluded.plan_status,
    plan_current_period_end = excluded.plan_current_period_end,
    plan_entitled = excluded.plan_entitled,
    storage_item_id = excluded.storage_item_id,
    storage_status = excluded.storage_status,
    storage_current_period_end = excluded.storage_current_period_end,
    storage_bytes_entitled = excluded.storage_bytes_entitled,
    ai_credit_balance = excluded.ai_credit_balance,
    updated_at = now();
end;
$$;


ALTER FUNCTION "tongs"."recompute_account_balance"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."recompute_account_balance_from_trigger"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
begin
  if tg_op = 'DELETE' then
    perform tongs.recompute_account_balance(old.user_id);
    return old;
  end if;

  perform tongs.recompute_account_balance(new.user_id);

  if tg_op = 'UPDATE' and old.user_id is distinct from new.user_id then
    perform tongs.recompute_account_balance(old.user_id);
  end if;

  return new;
end;
$$;


ALTER FUNCTION "tongs"."recompute_account_balance_from_trigger"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."reconcile_broll_runway_submission"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_decision" "text", "p_provider_task_id" "text", "p_task_evidence" "jsonb", "p_actor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare v_op tongs.broll_operation_receipts%rowtype; v_hash text; v_entry jsonb;
begin
 select * into v_op from tongs.broll_operation_receipts where operation_id=p_operation_id for update;
 if not found then return jsonb_build_object('disposition','operation_not_found'); end if;
 if auth.role()<>'service_role' and not tongs.has_workspace_role(v_op.workspace_id,'admin') then raise exception 'workspace admin authority required' using errcode='42501'; end if;
 if v_op.operation_fingerprint<>p_operation_fingerprint or v_op.state<>'submission_unknown' then return jsonb_build_object('disposition','reconciliation_conflict','operation',to_jsonb(v_op)); end if;
 if p_decision='attach_task' then
  if p_provider_task_id is null or p_task_evidence is null then return jsonb_build_object('disposition','task_evidence_required'); end if;
  if coalesce(p_task_evidence->>'model','')<>coalesce(v_op.normalized_inputs_json#>>'{runway,model}','') then return jsonb_build_object('disposition','task_model_mismatch'); end if;
  v_hash:=encode(extensions.digest(convert_to(p_task_evidence::text,'UTF8'),'sha256'),'hex');
  update tongs.broll_operation_receipts set state='provider_submitted',provider_task_id=p_provider_task_id,provider_submission_json=p_task_evidence,provider_submission_hash=v_hash,provider_submitted_at=now(),reconciliation_decision=p_decision,reconciled_by=p_actor_id,reconciled_at=now(),updated_at=now() where operation_id=p_operation_id returning * into v_op;
 elsif p_decision='confirmed_not_created' then
  if p_task_evidence is null or (p_task_evidence->>'http_status')::integer not between 400 and 499 then return jsonb_build_object('disposition','definitive_rejection_evidence_required'); end if;
  v_entry:=p_task_evidence||jsonb_build_object('submission_attempt_id',v_op.submission_attempt_id,'submitting_at',v_op.submitting_at,'submission_unknown_at',v_op.submission_unknown_at,'prior_ambiguity_reason',v_op.ambiguity_reason,'prior_transport_evidence',v_op.transport_evidence_json,'decision',p_decision,'actor_id',p_actor_id,'reconciled_at',now());
  update tongs.broll_operation_receipts set state='pending',reconciliation_decision=p_decision,reconciled_by=p_actor_id,reconciled_at=now(),transport_evidence_json=jsonb_build_object('latest',v_entry,'attempts',coalesce(transport_evidence_json->'attempts','[]'::jsonb)||jsonb_build_array(v_entry)),submission_attempt_id=null,submitting_at=null,submission_unknown_at=null,ambiguity_reason=null,updated_at=now() where operation_id=p_operation_id returning * into v_op;
 elsif p_decision='authorize_resubmission' then
  v_entry:=jsonb_build_object('submission_attempt_id',v_op.submission_attempt_id,'submitting_at',v_op.submitting_at,'submission_unknown_at',v_op.submission_unknown_at,'prior_ambiguity_reason',v_op.ambiguity_reason,'prior_transport_evidence',v_op.transport_evidence_json,'decision',p_decision,'actor_id',p_actor_id,'reconciled_at',now());
  update tongs.broll_operation_receipts set state='pending',reconciliation_decision=p_decision,reconciled_by=p_actor_id,reconciled_at=now(),resubmission_authorized_at=now(),resubmission_authorized_by=p_actor_id,transport_evidence_json=jsonb_build_object('latest',v_entry,'attempts',coalesce(transport_evidence_json->'attempts','[]'::jsonb)||jsonb_build_array(v_entry)),submission_attempt_id=null,submitting_at=null,submission_unknown_at=null,ambiguity_reason=null,updated_at=now() where operation_id=p_operation_id returning * into v_op;
 else return jsonb_build_object('disposition','invalid_reconciliation_decision'); end if;
 return jsonb_build_object('disposition','reconciled','operation',to_jsonb(v_op));
end $$;


ALTER FUNCTION "tongs"."reconcile_broll_runway_submission"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_decision" "text", "p_provider_task_id" "text", "p_task_evidence" "jsonb", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."reconcile_current_approved_script_ready_v1"("p_workspace_id" "uuid", "p_workpiece_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_user uuid := auth.uid();
  v_approval tongs.script_approval_revisions%rowtype;
  v_ready_result jsonb;
begin
  if v_user is null or not tongs.has_workspace_role(p_workspace_id,'editor') then
    return jsonb_build_object('outcome','denied','reason','editor_required','ready',null);
  end if;

  if not exists(
    select 1
    from tongs.episodes e
    where e.id=p_workpiece_id
      and e.workspace_id=p_workspace_id
      and e.archived_at is null
      and e.deleted_at is null
  ) then
    return jsonb_build_object('outcome','not_found','reason','active_episode_membership_invalid','ready',null);
  end if;

  select a.* into v_approval
  from tongs.workpiece_script_approval_sequences s
  join tongs.script_approval_revisions a
    on a.id=s.current_approval_id
    and a.workspace_id=s.workspace_id
    and a.workpiece_id=s.workpiece_id
    and a.approval_revision=s.current_revision
  where s.workspace_id=p_workspace_id
    and s.workpiece_id=p_workpiece_id;

  if not found then
    return jsonb_build_object('outcome','not_found','reason','current_approval_not_found','ready',null);
  end if;

  select tongs.hearth_transition_approved_script_ready_v4(
    p_workspace_id,
    p_workpiece_id,
    v_approval.id,
    'hearth-approved-ready-v4:' || p_workpiece_id::text || ':' || v_approval.id::text,
    jsonb_build_object(
      'transition','hearth.approved-script.ready.v4',
      'script_approval_id',v_approval.id,
      'script_approval_revision',v_approval.approval_revision,
      'script_approval_hash',v_approval.script_content_hash
    )
  ) into v_ready_result;

  return v_ready_result || jsonb_build_object(
    'basis','current_script_approval',
    'reconciled_by',v_user
  );
end;
$$;


ALTER FUNCTION "tongs"."reconcile_current_approved_script_ready_v1"("p_workspace_id" "uuid", "p_workpiece_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."reconcile_current_approved_script_ready_v1"("p_workspace_id" "uuid", "p_workpiece_id" "uuid") IS 'Idempotently materializes Ready for an existing current canonical approval after validating workspace role, active workpiece scope, and exact current script identity.';



CREATE OR REPLACE FUNCTION "tongs"."reconcile_runway_execution"("p_operation_id" "text", "p_direct_provider_actual_micros" bigint, "p_supporting_actual_micros" bigint, "p_settlement_id" "uuid", "p_settlement_key" "text", "p_evidence_json" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_operation text:=nullif(btrim(coalesce(p_operation_id,'')),'');
  v_binding tongs.runway_funding_bindings%rowtype;
  v_receipt tongs.runway_execution_reconciliation_receipts%rowtype;
  v_reservation tongs.funding_reservations%rowtype;
  v_existing_expense tongs.supplier_expenses%rowtype;
  v_credits numeric;
  v_derived bigint;
  v_bound bigint;
  v_total bigint;
  v_component text;
  v_evidence jsonb;
  v_expense jsonb;
  v_result jsonb;
begin
  perform tongs._require_pricing_service_role();
  if v_operation is null
     or p_supporting_actual_micros is null or p_supporting_actual_micros<0
     or (p_direct_provider_actual_micros is not null and p_direct_provider_actual_micros<0)
     or p_settlement_id is null
     or length(btrim(coalesce(p_settlement_key,'')))<8
     or jsonb_typeof(coalesce(p_evidence_json,'null'::jsonb))<>'object' then
    raise exception 'invalid Runway reconciliation' using errcode='22023';
  end if;

  select * into v_binding from tongs.runway_funding_bindings where operation_id=v_operation;
  if found then
    select * into v_reservation from tongs.funding_reservations where id=v_binding.reservation_id;
    if v_reservation.funding_source_type='owner_budget' then
      return tongs._reconcile_runway_execution_before_success_finalization(
        p_operation_id,p_direct_provider_actual_micros,p_supporting_actual_micros,
        p_settlement_id,p_settlement_key,p_evidence_json);
    end if;
  end if;

  perform pg_advisory_xact_lock(hashtextextended('runway-reconcile:'||v_operation,0));
  select * into v_receipt from tongs.runway_execution_reconciliation_receipts
    where operation_id=v_operation for update;
  if v_binding.operation_id is null or v_receipt.operation_id is null then
    raise exception 'completed funded Runway operation not found' using errcode='P0002';
  end if;

  if v_receipt.supporting_cost_status='finalized' then
    if v_receipt.supporting_actual_micros<>p_supporting_actual_micros
       or (p_direct_provider_actual_micros is not null
         and p_direct_provider_actual_micros<>v_receipt.direct_provider_actual_micros) then
      raise exception 'Runway reconciliation replay conflict' using errcode='23505';
    end if;
    return coalesce(v_receipt.settlement_result_json,'{}'::jsonb)||jsonb_build_object(
      'replay',true,
      'direct_provider_actual_micros',v_receipt.direct_provider_actual_micros,
      'supporting_actual_micros',v_receipt.supporting_actual_micros);
  end if;

  -- The receipt evidence is the persisted Runway SUCCEEDED task response.
  if coalesce(v_receipt.evidence_json->>'status','')<>'SUCCEEDED'
     or (v_receipt.evidence_json ? 'id'
       and v_receipt.evidence_json->>'id' is distinct from v_receipt.provider_task_id)
     or jsonb_typeof(v_receipt.evidence_json#>'{cost,credits}') is distinct from 'number' then
    raise exception 'authoritative Runway completion cost evidence required' using errcode='P0001';
  end if;
  v_credits:=(v_receipt.evidence_json#>>'{cost,credits}')::numeric;
  if v_credits<0 or v_credits<>trunc(v_credits) or v_credits>1000000 then
    raise exception 'authoritative Runway completion cost evidence required' using errcode='P0001';
  end if;
  -- Runway bills USD 0.01 per credit.
  v_derived:=(v_credits*10000)::bigint;
  if p_direct_provider_actual_micros is not null and p_direct_provider_actual_micros<>v_derived then
    raise exception 'Runway reconciliation actual disagrees with provider cost evidence' using errcode='22023';
  end if;
  -- Gen-4.5 bound pricing: 12 credits/second x USD 0.01.
  v_bound:=v_binding.duration_seconds::bigint*120000;
  v_total:=v_derived+p_supporting_actual_micros;
  v_evidence:=coalesce(p_evidence_json,'{}'::jsonb)||jsonb_build_object(
    'provider','runway',
    'provider_reference',v_receipt.provider_task_id,
    'provider_task_id',v_receipt.provider_task_id,
    'runway_credits',v_credits,
    'micros_per_runway_credit',10000,
    'direct_provider_actual_micros',v_derived,
    'supporting_actual_micros',p_supporting_actual_micros,
    'bound_direct_provider_micros',v_bound,
    'authoritative',true,
    'cost_coverage','confirmed');

  if v_derived>v_binding.direct_provider_ceiling_micros
     or p_supporting_actual_micros>v_binding.supporting_cost_ceiling_micros
     or v_total>v_binding.total_cost_ceiling_micros then
    insert into tongs.pricing_discrepancies(
      id,reservation_id,discrepancy_key,discrepancy_type,
      quoted_ceiling_micros,observed_amount_micros,evidence_json
    ) values (
      gen_random_uuid(),v_binding.reservation_id,
      btrim(p_settlement_key)||':runway-reconciliation-overrun',
      'wholesale_ceiling_overrun',
      case when v_derived>v_binding.direct_provider_ceiling_micros then v_binding.direct_provider_ceiling_micros
        when p_supporting_actual_micros>v_binding.supporting_cost_ceiling_micros then v_binding.supporting_cost_ceiling_micros
        else v_binding.total_cost_ceiling_micros end,
      case when v_derived>v_binding.direct_provider_ceiling_micros then v_derived
        when p_supporting_actual_micros>v_binding.supporting_cost_ceiling_micros then p_supporting_actual_micros
        else v_total end,
      v_evidence
    ) on conflict (discrepancy_key) do nothing;
    return jsonb_build_object('settled',false,'pricing_discrepancy',true,
      'reservation_retained',true,'customer_overcharge_allowed',false,
      'quoted_ceiling_micros',v_binding.total_cost_ceiling_micros,
      'observed_amount_micros',v_total,
      'direct_provider_actual_micros',v_derived);
  end if;
  -- pricing_discrepancies only records overruns; any other disagreement fails closed.
  if v_derived<>v_bound then
    raise exception 'Runway provider cost evidence disagrees with bound pricing' using errcode='P0001';
  end if;

  select component->>'component_code' into v_component
  from jsonb_array_elements(v_binding.cost_stack_json) component
  where component->>'component_kind'='direct_provider'
    and lower(component->>'provider_label')='runway'
  limit 1;
  v_expense:=tongs.record_supplier_expense(
    extensions.uuid_generate_v5(v_binding.reservation_id,'runway-direct-supplier-expense'),
    v_binding.reservation_id,
    'runway-direct-supplier-expense:'||v_binding.operation_id,
    'runway',
    coalesce(v_component,'runway.video'),
    v_receipt.provider_task_id,
    v_reservation.currency,
    v_derived,
    'confirmed',
    'closed',
    v_evidence);
  select * into v_existing_expense from tongs.supplier_expenses
    where expense_key='runway-direct-supplier-expense:'||v_binding.operation_id;
  if v_existing_expense.reservation_id<>v_binding.reservation_id
     or v_existing_expense.amount_micros is distinct from v_derived
     or v_existing_expense.evidence_status<>'confirmed'
     or v_existing_expense.provider_reference is distinct from v_receipt.provider_task_id then
    raise exception 'Runway supplier expense replay conflict' using errcode='23505';
  end if;

  v_result:=tongs.settle_operation(
    v_binding.reservation_id,p_settlement_id,btrim(p_settlement_key),
    'success',null,v_total,v_evidence);
  if coalesce(v_result->>'state','')<>'settled' then
    raise exception 'Runway customer success settlement did not settle: %',v_result using errcode='P0001';
  end if;

  update tongs.runway_execution_reconciliation_receipts
  set supporting_cost_status='finalized',
      direct_provider_actual_micros=v_derived,
      supporting_actual_micros=p_supporting_actual_micros,
      settlement_result_json=v_result||jsonb_build_object('supplier_expense',v_expense),
      reconciled_at=now()
  where operation_id=v_binding.operation_id;

  return v_result||jsonb_build_object(
    'replay',false,
    'direct_provider_actual_micros',v_derived,
    'supporting_actual_micros',p_supporting_actual_micros,
    'actual_fulfillment_cost_micros',v_total,
    'supplier_expense',v_expense);
end $$;


ALTER FUNCTION "tongs"."reconcile_runway_execution"("p_operation_id" "text", "p_direct_provider_actual_micros" bigint, "p_supporting_actual_micros" bigint, "p_settlement_id" "uuid", "p_settlement_key" "text", "p_evidence_json" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."reconcile_runway_execution"("p_operation_id" "text", "p_direct_provider_actual_micros" bigint, "p_supporting_actual_micros" bigint, "p_settlement_id" "uuid", "p_settlement_key" "text", "p_evidence_json" "jsonb") IS 'Finalizes a completed customer-funded Runway operation from persisted provider cost evidence: one confirmed supplier expense, one canonical success settlement, then a finalized receipt. Owner-budget reconciliation delegates to the preserved prior implementation.';



CREATE OR REPLACE FUNCTION "tongs"."reconcile_unified_visual_plan_reference_visual_state_failure"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_reservation_id" "uuid", "p_reference_visual_plan_revision_id" "uuid", "p_reference_visual_plan_revision" bigint, "p_reference_visual_plan_content_hash" "text", "p_provider_response_hash" "text", "p_expected_input_units" bigint, "p_expected_output_units" bigint, "p_expected_supplier_expense_micros" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $_$
declare
  op tongs.unified_visual_plan_operations%rowtype;
  binding tongs.openai_text_funding_bindings%rowtype;
  reservation tongs.funding_reservations%rowtype;
  capture tongs.openai_text_provider_captures%rowtype;
  usage_evidence tongs.openai_text_usage_evidence%rowtype;
  supplier_expense tongs.supplier_expenses%rowtype;
  reference_visual_revision tongs.reference_visual_plan_revisions%rowtype;
  existing_event tongs.unified_visual_plan_persistence_reconciliation_events%rowtype;
  verified_receipt jsonb;
  prior_subject text;
  v_event_key text:='visual-unified-reference-visual-state:'||p_reservation_id::text;
  v_event_id uuid:=extensions.uuid_generate_v5(
    p_reservation_id,'unified-visual-plan-reference-visual-state-recovery-v1');
  capture_count bigint;
  usage_count bigint;
  positive_expense_count bigint;
  positive_expense_sum bigint;
  settlement_count bigint;
  settled_customer_charge bigint;
  settled_credit_units bigint;
begin
  perform tongs._require_pricing_service_role();
  perform pg_advisory_xact_lock(hashtextextended(v_event_key,0));

  if btrim(coalesce(p_operation_id,''))<>p_operation_id
    or p_operation_fingerprint!~'^[0-9a-f]{64}$'
    or p_reference_visual_plan_revision<1
    or p_reference_visual_plan_content_hash!~'^[0-9a-f]{64}$'
    or p_provider_response_hash!~'^[0-9a-f]{64}$'
    or p_expected_input_units<>3332
    or p_expected_output_units<>3769
    or p_expected_supplier_expense_micros<>5190
  then raise exception 'invalid Visual Plan persistence reconciliation request' using errcode='22023'; end if;

  select * into op from tongs.unified_visual_plan_operations
    where operation_id=p_operation_id for update;
  select * into binding from tongs.openai_text_funding_bindings
    where operation_id=p_operation_id and reservation_id=p_reservation_id
      and route_code='visual.unified_plan';
  select * into reservation from tongs.funding_reservations where id=p_reservation_id;

  select count(*) into capture_count from tongs.openai_text_provider_captures
    where reservation_id=p_reservation_id;
  select * into capture from tongs.openai_text_provider_captures
    where reservation_id=p_reservation_id and attempt_number=1;
  select count(*) into usage_count from tongs.openai_text_usage_evidence
    where reservation_id=p_reservation_id;
  select * into usage_evidence from tongs.openai_text_usage_evidence
    where reservation_id=p_reservation_id and attempt_number=1;
  select count(*) filter(where amount_micros>0),
         coalesce(sum(amount_micros) filter(where amount_micros>0),0)
    into positive_expense_count,positive_expense_sum
    from tongs.supplier_expenses where reservation_id=p_reservation_id;
  select * into supplier_expense from tongs.supplier_expenses
    where reservation_id=p_reservation_id and amount_micros>0;
  select count(*),coalesce(sum(customer_charge_micros),0),coalesce(sum(credit_units),0)
    into settlement_count,settled_customer_charge,settled_credit_units
    from tongs.funding_reservation_events
    where reservation_id=p_reservation_id and event_type='settled';
  select * into reference_visual_revision from tongs.reference_visual_plan_revisions
    where id=p_reference_visual_plan_revision_id;
  select * into existing_event
    from tongs.unified_visual_plan_persistence_reconciliation_events
    where event_key=v_event_key;

  if op.operation_id is null
    or op.operation_fingerprint is distinct from p_operation_fingerprint
    or op.contract_version<>'forge.unified-visual-plan.v2'
    or op.state not in('failed','verified')
    or op.provider_response_json is null
    or op.provider_response_hash is distinct from p_provider_response_hash
    or op.normalized_inputs_json->>'provider_contract_version'
       is distinct from 'forge.unified-visual-plan-provider.v5'
    or op.provider_response_json->>'provider_request_id'
       is distinct from capture.provider_request_id
    or (op.provider_response_json->>'input_units')::bigint is distinct from p_expected_input_units
    or (op.provider_response_json->>'output_units')::bigint is distinct from p_expected_output_units
    or jsonb_array_length(coalesce(op.provider_response_json#>'{canonical_plan,reference_visuals}','[]'::jsonb))=0
    or binding.reservation_id is null
    or binding.model<>'gpt-5.6-luna'
    or binding.maximum_attempts<>1
    or binding.maximum_input_units<>32000
    or binding.maximum_output_units<>6144
    or reservation.id is null
    or reservation.operation_id is distinct from p_operation_id||':q:'||reservation.quote_id::text
    or reservation.reserved_credit_units<>4
    or reservation.reserved_wholesale_spend_micros<>13773
    or tongs._funding_reservation_state(p_reservation_id)<>'released'
    or settlement_count<>0
    or settled_customer_charge<>0
    or settled_credit_units<>0
    or capture_count<>1 or capture.id is null or capture.attempt_number<>1
    or capture.input_units is distinct from p_expected_input_units
    or capture.output_units is distinct from p_expected_output_units
    or capture.provider_request_id is null
    or capture.response_evidence_json->>'raw_provider_response_text' is null
    or capture.response_evidence_json->>'validation_contract_revision'
       is distinct from 'forge.unified-visual-plan-provider.v5'
    or usage_count<>1 or usage_evidence.id is null or usage_evidence.attempt_number<>1
    or usage_evidence.provider_request_id is distinct from capture.provider_request_id
    or usage_evidence.input_units is distinct from p_expected_input_units
    or usage_evidence.output_units is distinct from p_expected_output_units
    or usage_evidence.result_validated is not true
    or usage_evidence.canonical_persistence_confirmed is not false
    or usage_evidence.evidence_json->>'validation_contract_revision'
       is distinct from 'forge.unified-visual-plan-provider.v5'
    or positive_expense_count<>1
    or positive_expense_sum is distinct from p_expected_supplier_expense_micros
    or supplier_expense.id is null or supplier_expense.provider<>'openai'
    or supplier_expense.amount_micros is distinct from p_expected_supplier_expense_micros
    or exists(select 1 from tongs.openai_text_persisted_results
      where reservation_id=p_reservation_id)
  then raise exception 'invalid Visual Plan persistence reconciliation evidence' using errcode='22023'; end if;

  if op.image_map_revision_id is null or op.image_map_revision<>1
    or op.broll_plan_revision_id is null or op.broll_plan_revision<>1
    or op.reference_clip_plan_revision_id is null or op.reference_clip_plan_revision<>1
    or reference_visual_revision.id is null
    or reference_visual_revision.workspace_id is distinct from op.workspace_id
    or reference_visual_revision.workpiece_id is distinct from op.workpiece_id
    or reference_visual_revision.revision is distinct from p_reference_visual_plan_revision
    or reference_visual_revision.script_approval_id is distinct from op.script_approval_id
    or reference_visual_revision.script_approval_revision is distinct from op.script_approval_revision
    or reference_visual_revision.script_content_hash is distinct from op.script_content_hash
    or reference_visual_revision.contract_version<>'forge.unified-visual-plan.v2'
    or reference_visual_revision.content_hash is distinct from p_reference_visual_plan_content_hash
    or op.child_membership_evidence_json#>>'{reference_visual,provider_plan_revision_id}'
       is distinct from p_reference_visual_plan_revision_id::text
    or op.child_membership_evidence_json#>>'{reference_visual,final_plan_revision_id}'
       is distinct from p_reference_visual_plan_revision_id::text
    or not exists(select 1 from tongs.image_map_revisions r
      where r.id=op.image_map_revision_id and r.workspace_id=op.workspace_id
        and r.workpiece_id=op.workpiece_id and r.revision=op.image_map_revision
        and r.source_script_approval_id=op.script_approval_id
        and r.source_script_approval_revision=op.script_approval_revision
        and r.source_script_content_hash=op.script_content_hash
        and r.document_content_hash=op.image_plan_content_hash)
    or not exists(select 1 from tongs.broll_plan_revisions r
      where r.id=op.broll_plan_revision_id and r.workspace_id=op.workspace_id
        and r.workpiece_id=op.workpiece_id and r.revision=op.broll_plan_revision
        and r.script_approval_id=op.script_approval_id
        and r.script_approval_revision=op.script_approval_revision
        and r.script_content_hash=op.script_content_hash
        and r.content_hash=op.broll_plan_content_hash)
    or not exists(select 1 from tongs.reference_clip_plan_revisions r
      where r.id=op.reference_clip_plan_revision_id and r.workspace_id=op.workspace_id
        and r.workpiece_id=op.workpiece_id and r.revision=op.reference_clip_plan_revision
        and r.script_approval_id=op.script_approval_id
        and r.script_approval_revision=op.script_approval_revision
        and r.script_content_hash=op.script_content_hash
        and r.content_hash=op.reference_clip_plan_content_hash)
    or not exists(select 1 from tongs.workpiece_image_map_sequences s
      where s.workspace_id=op.workspace_id and s.workpiece_id=op.workpiece_id
        and s.current_revision_id=op.image_map_revision_id and s.current_revision=op.image_map_revision)
    or not exists(select 1 from tongs.broll_plan_sequences s
      where s.workspace_id=op.workspace_id and s.workpiece_id=op.workpiece_id
        and s.current_plan_revision_id=op.broll_plan_revision_id and s.current_plan_revision=op.broll_plan_revision)
    or not exists(select 1 from tongs.reference_clip_plan_sequences s
      where s.workspace_id=op.workspace_id and s.workpiece_id=op.workpiece_id
        and s.current_plan_revision_id=op.reference_clip_plan_revision_id and s.current_plan_revision=op.reference_clip_plan_revision)
    or not exists(select 1 from tongs.reference_visual_plan_sequences s
      where s.workspace_id=op.workspace_id and s.workpiece_id=op.workpiece_id
        and s.current_plan_revision_id=p_reference_visual_plan_revision_id
        and s.current_plan_revision=p_reference_visual_plan_revision)
    or exists(select 1 from tongs.image_map_revisions r
      where r.workspace_id=op.workspace_id and r.workpiece_id=op.workpiece_id
        and r.revision>op.image_map_revision)
    or exists(select 1 from tongs.broll_plan_revisions r
      where r.workspace_id=op.workspace_id and r.workpiece_id=op.workpiece_id
        and r.revision>op.broll_plan_revision)
    or exists(select 1 from tongs.reference_clip_plan_revisions r
      where r.workspace_id=op.workspace_id and r.workpiece_id=op.workpiece_id
        and r.revision>op.reference_clip_plan_revision)
    or exists(select 1 from tongs.reference_visual_plan_revisions r
      where r.workspace_id=op.workspace_id and r.workpiece_id=op.workpiece_id
        and r.revision>p_reference_visual_plan_revision)
  then raise exception 'canonical Visual Plan children changed after the failed receipt' using errcode='23505'; end if;

  if op.state='verified' then
    if existing_event.id is null or op.receipt_json is null
      or existing_event.operation_id is distinct from op.operation_id
      or existing_event.reservation_id is distinct from p_reservation_id
      or existing_event.provider_capture_id is distinct from capture.id
      or existing_event.usage_evidence_id is distinct from usage_evidence.id
      or existing_event.supplier_expense_id is distinct from supplier_expense.id
      or existing_event.evidence_json->>'provider_response_hash' is distinct from p_provider_response_hash
      or existing_event.evidence_json#>>'{reference_visual_plan,content_hash}'
         is distinct from p_reference_visual_plan_content_hash
    then raise exception 'Visual Plan persistence reconciliation replay conflict' using errcode='23505'; end if;
    return jsonb_build_object('disposition','replay','replay',true,
      'operation_id',op.operation_id,'receipt',op.receipt_json,
      'reconciliation_event_id',existing_event.id);
  end if;

  if existing_event.id is not null
    or op.failed_stage is distinct from 'reference_visual_retention'
    or op.failure_code is distinct from 'unified_reference_visual_receipt_failed'
    or op.failure_message is distinct from
       'new row for relation "unified_visual_plan_operations" violates check constraint "unified_visual_plan_operations_state_check"'
    or op.receipt_json is not null
    or op.reference_visual_plan_revision_id is not null
    or op.reference_visual_plan_revision is not null
    or op.reference_visual_plan_content_hash is not null
    or op.reference_visual_plan_empty is not null
  then raise exception 'Visual Plan persistence failure is not the reviewed historical state' using errcode='23505'; end if;

  insert into tongs.unified_visual_plan_persistence_reconciliation_events(
    id,event_key,operation_id,reservation_id,provider_capture_id,usage_evidence_id,
    supplier_expense_id,event_type,evidence_json
  ) values(
    v_event_id,v_event_key,op.operation_id,p_reservation_id,capture.id,usage_evidence.id,
    supplier_expense.id,'reference_visual_state_constraint_recovered',jsonb_build_object(
      'operation_fingerprint',op.operation_fingerprint,
      'provider_response_hash',op.provider_response_hash,
      'provider_contract_version','forge.unified-visual-plan-provider.v5',
      'provider_request_id',capture.provider_request_id,
      'input_units',capture.input_units,'output_units',capture.output_units,
      'supplier_expense_micros',positive_expense_sum,
      'customer_charge_micros',0,'settled_credit_units',0,
      'reservation_state','released','canonical_paid_result_count',0,
      'nonbillable_reason','Forge persistence state-constraint defect after successful child persistence',
      'image_plan',jsonb_build_object('revision_id',op.image_map_revision_id,'revision',op.image_map_revision,'content_hash',op.image_plan_content_hash),
      'broll_plan',jsonb_build_object('revision_id',op.broll_plan_revision_id,'revision',op.broll_plan_revision,'content_hash',op.broll_plan_content_hash),
      'reference_clip_plan',jsonb_build_object('revision_id',op.reference_clip_plan_revision_id,'revision',op.reference_clip_plan_revision,'content_hash',op.reference_clip_plan_content_hash),
      'reference_visual_plan',jsonb_build_object('revision_id',reference_visual_revision.id,'revision',reference_visual_revision.revision,'content_hash',reference_visual_revision.content_hash)
    )
  );

  update tongs.unified_visual_plan_operations
  set state='reference_visual_plan_committed',
      reference_visual_plan_revision_id=reference_visual_revision.id,
      reference_visual_plan_revision=reference_visual_revision.revision,
      reference_visual_plan_content_hash=reference_visual_revision.content_hash,
      reference_visual_plan_empty=false,
      failed_stage=null,failure_code=null,failure_message=null,updated_at=now()
  where operation_id=op.operation_id;

  -- The canonical verifier is intentionally reused. The service-only recovery
  -- temporarily supplies the original actor identity so its workspace-role gate
  -- remains authoritative rather than duplicating receipt construction here.
  prior_subject:=current_setting('request.jwt.claim.sub',true);
  perform set_config('request.jwt.claim.sub',op.created_by::text,true);
  verified_receipt:=tongs.verify_unified_visual_plan(op.operation_id,op.operation_fingerprint);
  perform set_config('request.jwt.claim.sub',coalesce(prior_subject,''),true);
  if verified_receipt->>'disposition'<>'verified'
    or verified_receipt#>>'{reference_visual_plan,revision_id}'
       is distinct from reference_visual_revision.id::text
    or not exists(select 1 from tongs.unified_visual_plan_operations current_op
      where current_op.operation_id=op.operation_id and current_op.state='verified'
        and current_op.receipt_json=verified_receipt)
  then raise exception 'canonical Visual Plan verification did not complete' using errcode='P0001'; end if;

  return jsonb_build_object('disposition','recovered','replay',false,
    'operation_id',op.operation_id,'receipt',verified_receipt,
    'reconciliation_event_id',v_event_id,
    'customer_charge_micros',0,'settled_credit_units',0,
    'supplier_expense_micros',positive_expense_sum,'reservation_state','released');
end $_$;


ALTER FUNCTION "tongs"."reconcile_unified_visual_plan_reference_visual_state_failure"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_reservation_id" "uuid", "p_reference_visual_plan_revision_id" "uuid", "p_reference_visual_plan_revision" bigint, "p_reference_visual_plan_content_hash" "text", "p_provider_response_hash" "text", "p_expected_input_units" bigint, "p_expected_output_units" bigint, "p_expected_supplier_expense_micros" bigint) OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."reconcile_unified_visual_plan_reference_visual_state_failure"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_reservation_id" "uuid", "p_reference_visual_plan_revision_id" "uuid", "p_reference_visual_plan_revision" bigint, "p_reference_visual_plan_content_hash" "text", "p_provider_response_hash" "text", "p_expected_input_units" bigint, "p_expected_output_units" bigint, "p_expected_supplier_expense_micros" bigint) IS 'Service-only, replay-safe recovery of an already-persisted four-child Visual Plan. Requires exact provider, usage, supplier-cost, released-reservation, and unsuperseded child evidence; makes no provider or billing call.';



CREATE OR REPLACE FUNCTION "tongs"."reconcile_unified_visual_plan_validation_failure"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_reservation_id" "uuid", "p_validation_error_code" "text", "p_failure_message" "text", "p_validation_contract_revision" "text", "p_expected_supplier_expense_micros" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $_$
declare
  op tongs.unified_visual_plan_operations%rowtype;
  binding tongs.openai_text_funding_bindings%rowtype;
  capture tongs.openai_text_provider_captures%rowtype;
  existing_evidence tongs.openai_text_validation_failure_evidence%rowtype;
  existing_event tongs.unified_visual_plan_reconciliation_events%rowtype;
  funding_event tongs.funding_reservation_events%rowtype;
  supplier_expense_micros bigint;
  evidence_id uuid:=extensions.uuid_generate_v5(p_reservation_id,'openai-text-validation-failure-v1');
  event_id uuid:=extensions.uuid_generate_v5(p_reservation_id,'unified-visual-plan-validation-reconciliation-v1');
  v_event_key text:='visual-unified-validation:'||p_reservation_id::text;
  was_replay boolean:=false;
begin
  perform tongs._require_pricing_service_role();
  perform pg_advisory_xact_lock(hashtextextended(v_event_key,0));
  select * into op from tongs.unified_visual_plan_operations
    where operation_id=btrim(p_operation_id) for update;
  select * into binding from tongs.openai_text_funding_bindings
    where operation_id=btrim(p_operation_id) and reservation_id=p_reservation_id
      and route_code='visual.unified_plan';
  select * into capture from tongs.openai_text_provider_captures
    where reservation_id=p_reservation_id and attempt_number=1;
  select * into funding_event from tongs.funding_reservation_events
    where reservation_id=p_reservation_id order by sequence desc limit 1;
  select coalesce(sum(amount_micros),0) into supplier_expense_micros
    from tongs.supplier_expenses
    where reservation_id=p_reservation_id and coalesce(amount_micros,0)>0;
  if op.operation_id is null or op.operation_fingerprint is distinct from p_operation_fingerprint
    or op.state not in('pending','failed') or op.provider_response_json is not null or op.receipt_json is not null
    or binding.reservation_id is null or binding.model<>'gpt-5.6-luna' or binding.maximum_attempts<>1
    or capture.id is null or capture.provider_request_id is null
    or capture.response_evidence_json->>'raw_provider_response_text' is null
    or funding_event.event_type<>'released' or coalesce(funding_event.customer_charge_micros,0)<>0
    or coalesce(funding_event.credit_units,0)<>0
    or p_expected_supplier_expense_micros<0
    or supplier_expense_micros is distinct from p_expected_supplier_expense_micros
    or p_validation_error_code!~'^[a-z][a-z0-9_]{2,100}$'
    or p_validation_contract_revision not in(
      'forge.unified-visual-plan-provider.v4','forge.unified-visual-plan-provider.v5')
  then raise exception 'invalid unified Visual Plan reconciliation evidence' using errcode='22023'; end if;
  insert into tongs.openai_text_validation_failure_evidence(
    id,route_code,operation_id,reservation_id,provider_capture_id,provider_request_id,
    model,input_units,output_units,raw_provider_response_text,validation_error_code,validation_contract_revision
  ) values(evidence_id,'visual.unified_plan',op.operation_id,p_reservation_id,capture.id,
    capture.provider_request_id,binding.model,capture.input_units,capture.output_units,
    capture.response_evidence_json->>'raw_provider_response_text',p_validation_error_code,p_validation_contract_revision)
  on conflict(reservation_id) do nothing;
  select * into existing_evidence from tongs.openai_text_validation_failure_evidence
    where reservation_id=p_reservation_id;
  if existing_evidence.id is null
    or existing_evidence.operation_id is distinct from op.operation_id
    or existing_evidence.provider_capture_id is distinct from capture.id
    or existing_evidence.validation_error_code is distinct from p_validation_error_code
    or existing_evidence.validation_contract_revision is distinct from p_validation_contract_revision
  then raise exception 'unified Visual Plan validation evidence replay conflict' using errcode='23505'; end if;
  select * into existing_event from tongs.unified_visual_plan_reconciliation_events where event_key=v_event_key;
  was_replay:=found;
  insert into tongs.unified_visual_plan_reconciliation_events(
    id,event_key,operation_id,reservation_id,provider_capture_id,event_type,evidence_json
  ) values(event_id,v_event_key,op.operation_id,p_reservation_id,capture.id,'validation_failure_terminalized',
    jsonb_build_object('operation_fingerprint',p_operation_fingerprint,'provider_request_id',capture.provider_request_id,
      'model',binding.model,'input_units',capture.input_units,'output_units',capture.output_units,
      'validation_error_code',p_validation_error_code,'validation_contract_revision',p_validation_contract_revision,
      'supplier_expense_micros',supplier_expense_micros,'customer_charge_micros',0,
      'canonical_result_persisted',false))
  on conflict(event_key) do nothing;
  select * into existing_event from tongs.unified_visual_plan_reconciliation_events where event_key=v_event_key;
  if existing_event.operation_id is distinct from op.operation_id
    or existing_event.reservation_id is distinct from p_reservation_id
    or existing_event.provider_capture_id is distinct from capture.id
  then raise exception 'unified Visual Plan reconciliation replay conflict' using errcode='23505'; end if;
  if op.state='pending' then
    update tongs.unified_visual_plan_operations
    set state='failed',failed_stage='validation',failure_code=p_validation_error_code,
        failure_message=p_failure_message,updated_at=now()
    where operation_id=op.operation_id returning * into op;
  elsif op.failed_stage is distinct from 'validation' or op.failure_code is distinct from p_validation_error_code then
    raise exception 'unified Visual Plan terminal failure conflict' using errcode='23505';
  end if;
  return jsonb_build_object('disposition','reconciled','replay',was_replay,
    'operation',to_jsonb(op),'evidence_id',evidence_id,'reconciliation_event_id',event_id);
end $_$;


ALTER FUNCTION "tongs"."reconcile_unified_visual_plan_validation_failure"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_reservation_id" "uuid", "p_validation_error_code" "text", "p_failure_message" "text", "p_validation_contract_revision" "text", "p_expected_supplier_expense_micros" bigint) OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."reconcile_unified_visual_plan_validation_failure"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_reservation_id" "uuid", "p_validation_error_code" "text", "p_failure_message" "text", "p_validation_contract_revision" "text", "p_expected_supplier_expense_micros" bigint) IS 'Service-only replay-safe reconciliation of captured validation failures. Appends evidence before terminalizing the parent operation.';



CREATE TABLE IF NOT EXISTS "tongs"."ai_credit_unfunded_expenses" (
    "id" "uuid" NOT NULL,
    "user_id" "uuid" NOT NULL,
    "provider_request_id" "text",
    "attempted_charge" bigint NOT NULL,
    "reason_code" "text" NOT NULL,
    "evidence_json" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "ai_credit_unfunded_expenses_attempted_charge_check" CHECK (("attempted_charge" > 0))
);


ALTER TABLE "tongs"."ai_credit_unfunded_expenses" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."record_ai_credit_unfunded_expense"("p_user_id" "uuid", "p_event_id" "uuid", "p_provider_request_id" "text", "p_attempted_charge" bigint, "p_reason_code" "text", "p_evidence_json" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "tongs"."ai_credit_unfunded_expenses"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare v_event tongs.ai_credit_unfunded_expenses%rowtype;
begin
  if p_user_id is null or p_event_id is null or p_attempted_charge <= 0 or nullif(btrim(p_reason_code),'') is null then
    raise exception 'invalid unfunded-expense evidence' using errcode = '22023';
  end if;
  select * into v_event from tongs.ai_credit_unfunded_expenses where id=p_event_id;
  if found then
    if v_event.user_id<>p_user_id or v_event.attempted_charge<>p_attempted_charge
       or v_event.provider_request_id is distinct from p_provider_request_id or v_event.reason_code<>p_reason_code then
      raise exception 'unfunded-expense replay conflict' using errcode = '23505';
    end if;
    return v_event;
  end if;
  insert into tongs.ai_credit_unfunded_expenses(id,user_id,provider_request_id,attempted_charge,reason_code,evidence_json)
    values(p_event_id,p_user_id,p_provider_request_id,p_attempted_charge,p_reason_code,coalesce(p_evidence_json,'{}'::jsonb))
    returning * into v_event;
  return v_event;
end;
$$;


ALTER FUNCTION "tongs"."record_ai_credit_unfunded_expense"("p_user_id" "uuid", "p_event_id" "uuid", "p_provider_request_id" "text", "p_attempted_charge" bigint, "p_reason_code" "text", "p_evidence_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."record_barstock_discovery_provider_call"("p_run_id" "uuid", "p_lease_token_hash" "text", "p_provider" "text", "p_request_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare r tongs.barstock_discovery_runs%rowtype;
begin
 if auth.role()<>'service_role' then return jsonb_build_object('outcome','denied');end if;
 select * into r from tongs.barstock_discovery_runs where id=p_run_id and lease_token_hash=p_lease_token_hash and lease_expires_at>now() and status in('leased','refreshing') for update;
 if r.id is null then return jsonb_build_object('outcome','lease_lost');end if;
 if r.provider_call_count>=4 then return jsonb_build_object('outcome','run_budget_exhausted');end if;
 insert into tongs.barstock_discovery_provider_calls(run_id,workspace_id,user_id,provider,request_key) values(r.id,r.workspace_id,r.user_id,p_provider,p_request_key) on conflict(run_id,request_key) do nothing;
 if found then update tongs.barstock_discovery_runs set provider_call_count=provider_call_count+1,first_provider_call_at=coalesce(first_provider_call_at,now()),status='refreshing',updated_at=now() where id=r.id returning * into r;end if;
 return jsonb_build_object('outcome','recorded','provider_call_count',r.provider_call_count);
end$$;


ALTER FUNCTION "tongs"."record_barstock_discovery_provider_call"("p_run_id" "uuid", "p_lease_token_hash" "text", "p_provider" "text", "p_request_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."record_billing_event"("p_stripe_event_id" "text", "p_event_type" "text", "p_user_id" "uuid" DEFAULT NULL::"uuid", "p_stripe_customer_id" "text" DEFAULT NULL::"text", "p_stripe_subscription_id" "text" DEFAULT NULL::"text", "p_stripe_session_id" "text" DEFAULT NULL::"text", "p_livemode" boolean DEFAULT NULL::boolean, "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare
  v_event_id text := nullif(btrim(coalesce(p_stripe_event_id, '')), '');
  v_event_type text := nullif(lower(btrim(coalesce(p_event_type, ''))), '');
  v_customer_id text := nullif(btrim(coalesce(p_stripe_customer_id, '')), '');
  v_subscription_id text := nullif(btrim(coalesce(p_stripe_subscription_id, '')), '');
  v_session_id text := nullif(btrim(coalesce(p_stripe_session_id, '')), '');
  v_payload jsonb := coalesce(p_payload, '{}'::jsonb);
begin
  if v_event_id is null then
    raise exception 'p_stripe_event_id required'
      using errcode = '22023';
  end if;

  if v_event_type is null then
    raise exception 'p_event_type required'
      using errcode = '22023';
  end if;

  insert into tongs.billing_events (
    stripe_event_id,
    event_type,
    user_id,
    stripe_customer_id,
    stripe_subscription_id,
    stripe_session_id,
    livemode,
    payload_json,
    processed_at
  )
  values (
    v_event_id,
    v_event_type,
    p_user_id,
    v_customer_id,
    v_subscription_id,
    v_session_id,
    p_livemode,
    v_payload,
    now()
  )
  on conflict (stripe_event_id) do update
  set
    event_type = excluded.event_type,
    user_id = coalesce(excluded.user_id, tongs.billing_events.user_id),
    stripe_customer_id = coalesce(excluded.stripe_customer_id, tongs.billing_events.stripe_customer_id),
    stripe_subscription_id = coalesce(excluded.stripe_subscription_id, tongs.billing_events.stripe_subscription_id),
    stripe_session_id = coalesce(excluded.stripe_session_id, tongs.billing_events.stripe_session_id),
    livemode = coalesce(excluded.livemode, tongs.billing_events.livemode),
    payload_json = excluded.payload_json,
    processed_at = now();
end;
$$;


ALTER FUNCTION "tongs"."record_billing_event"("p_stripe_event_id" "text", "p_event_type" "text", "p_user_id" "uuid", "p_stripe_customer_id" "text", "p_stripe_subscription_id" "text", "p_stripe_session_id" "text", "p_livemode" boolean, "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."record_broll_provider_or_upload_result"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_result" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare v_op tongs.broll_operation_receipts%rowtype; v_hash text;
begin
 select * into v_op from tongs.broll_operation_receipts where operation_id=p_operation_id for update;
 if not found then return jsonb_build_object('disposition','operation_not_found'); end if;
 if v_op.owner_cost_attempt_id is not null then perform tongs._require_accounting_service_role(); elsif not tongs.has_workspace_role(v_op.workspace_id,'editor') then raise exception 'workspace editor authority required' using errcode='42501'; end if;
 if v_op.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict'); end if;
 if v_op.state='provider_or_upload_completed' then return jsonb_build_object('disposition','replay','operation',to_jsonb(v_op)); end if;
 if v_op.state not in('pending','provider_completed') then return jsonb_build_object('disposition','provider_result_stage_required','operation',to_jsonb(v_op)); end if;
 v_hash:=encode(extensions.digest(convert_to(p_result::text,'UTF8'),'sha256'),'hex');
 update tongs.broll_operation_receipts set state='provider_or_upload_completed',provider_response_json=p_result,provider_response_hash=v_hash,updated_at=now() where operation_id=p_operation_id returning * into v_op;
 return jsonb_build_object('disposition','result_recorded','operation',to_jsonb(v_op));
end $$;


ALTER FUNCTION "tongs"."record_broll_provider_or_upload_result"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_result" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."record_broll_runway_completion"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_provider_task_id" "text", "p_completed_response" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare v_op tongs.broll_operation_receipts%rowtype; v_hash text;
begin
 select * into v_op from tongs.broll_operation_receipts where operation_id=p_operation_id for update;
 if not found then return jsonb_build_object('disposition','operation_not_found'); end if;
 if not tongs.has_workspace_role(v_op.workspace_id,'editor') then raise exception 'workspace editor authority required' using errcode='42501'; end if;
 if v_op.operation_fingerprint<>p_operation_fingerprint or v_op.provider_task_id is distinct from p_provider_task_id then return jsonb_build_object('disposition','provider_task_conflict'); end if;
 if v_op.state in('provider_completed','provider_or_upload_completed','video_asset_verified','poster_asset_verified','candidate_committed') then return jsonb_build_object('disposition','replay','operation',to_jsonb(v_op)); end if;
 if v_op.state<>'provider_submitted' then return jsonb_build_object('disposition','provider_submitted_stage_required','operation',to_jsonb(v_op)); end if;
 v_hash:=encode(extensions.digest(convert_to(p_completed_response::text,'UTF8'),'sha256'),'hex');
 update tongs.broll_operation_receipts set state='provider_completed',provider_completed_json=p_completed_response,provider_completed_hash=v_hash,provider_completed_at=now(),updated_at=now() where operation_id=p_operation_id returning * into v_op;
 return jsonb_build_object('disposition','provider_completed','operation',to_jsonb(v_op));
end $$;


ALTER FUNCTION "tongs"."record_broll_runway_completion"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_provider_task_id" "text", "p_completed_response" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."record_broll_runway_pending"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_provider_task_id" "text", "p_poll_response" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare v_op tongs.broll_operation_receipts%rowtype;
begin
 select * into v_op from tongs.broll_operation_receipts where operation_id=p_operation_id for update;
 if not found then return jsonb_build_object('disposition','operation_not_found'); end if;
 if not tongs.has_workspace_role(v_op.workspace_id,'editor') then raise exception 'workspace editor authority required' using errcode='42501'; end if;
 if v_op.operation_fingerprint<>p_operation_fingerprint or v_op.provider_task_id is distinct from p_provider_task_id then return jsonb_build_object('disposition','provider_task_conflict'); end if;
 if v_op.state<>'provider_submitted' then return jsonb_build_object('disposition','replay','operation',to_jsonb(v_op)); end if;
 update tongs.broll_operation_receipts set provider_last_poll_json=p_poll_response,updated_at=now() where operation_id=p_operation_id returning * into v_op;
 return jsonb_build_object('disposition','provider_pending','operation',to_jsonb(v_op));
end $$;


ALTER FUNCTION "tongs"."record_broll_runway_pending"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_provider_task_id" "text", "p_poll_response" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."record_broll_runway_rejection"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_submission_attempt_id" "uuid", "p_rejection_evidence" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare v_op tongs.broll_operation_receipts%rowtype; v_entry jsonb;
begin
  select * into v_op from tongs.broll_operation_receipts where operation_id=p_operation_id for update;
  if not found then return jsonb_build_object('disposition','operation_not_found'); end if;
  if v_op.operation_fingerprint<>p_operation_fingerprint or v_op.submission_attempt_id<>p_submission_attempt_id then
    return jsonb_build_object('disposition','operation_identity_conflict','operation',to_jsonb(v_op));
  end if;
  if v_op.state='pending' and coalesce(v_op.transport_evidence_json#>>'{latest,submission_attempt_id}','')=p_submission_attempt_id::text then
    return jsonb_build_object('disposition','replay','operation',to_jsonb(v_op));
  end if;
  if v_op.state<>'submitting' then return jsonb_build_object('disposition','submission_stage_required','operation',to_jsonb(v_op)); end if;
  if p_rejection_evidence is null or (p_rejection_evidence->>'http_status')::integer not between 400 and 499 then
    return jsonb_build_object('disposition','definitive_rejection_evidence_required');
  end if;
  v_entry:=p_rejection_evidence||jsonb_build_object(
    'submission_attempt_id',p_submission_attempt_id,
    'submitting_at',v_op.submitting_at,
    'classification','confirmed_not_created',
    'recorded_at',now()
  );
  update tongs.broll_operation_receipts set
    state='pending',
    failure_code='runway_rejected_before_task',
    failure_message=coalesce(p_rejection_evidence->>'provider_message','Runway rejected the request before creating a task.'),
    transport_evidence_json=jsonb_build_object(
      'latest',v_entry,
      'attempts',coalesce(transport_evidence_json->'attempts','[]'::jsonb)||jsonb_build_array(v_entry)
    ),
    submission_attempt_id=null,
    submitting_at=null,
    submission_unknown_at=null,
    ambiguity_reason=null,
    updated_at=now()
  where operation_id=p_operation_id returning * into v_op;
  return jsonb_build_object('disposition','rejection_recorded','operation',to_jsonb(v_op));
end $$;


ALTER FUNCTION "tongs"."record_broll_runway_rejection"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_submission_attempt_id" "uuid", "p_rejection_evidence" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."record_broll_runway_task"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_submission_attempt_id" "uuid", "p_provider_task_id" "text", "p_accepted_response" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare v_op tongs.broll_operation_receipts%rowtype; v_hash text;
begin
 select * into v_op from tongs.broll_operation_receipts where operation_id=p_operation_id for update;
 if not found then return jsonb_build_object('disposition','operation_not_found'); end if;
 if not tongs.has_workspace_role(v_op.workspace_id,'editor') then raise exception 'workspace editor authority required' using errcode='42501'; end if;
 if v_op.operation_fingerprint<>p_operation_fingerprint or v_op.submission_attempt_id is distinct from p_submission_attempt_id then return jsonb_build_object('disposition','operation_identity_conflict'); end if;
 if v_op.provider_task_id is not null then return jsonb_build_object('disposition',case when v_op.provider_task_id=p_provider_task_id then 'replay' else 'provider_task_conflict' end,'operation',to_jsonb(v_op)); end if;
 if v_op.state not in('submitting','submission_unknown') then return jsonb_build_object('disposition','submission_stage_required','operation',to_jsonb(v_op)); end if;
 v_hash:=encode(extensions.digest(convert_to(p_accepted_response::text,'UTF8'),'sha256'),'hex');
 update tongs.broll_operation_receipts set
  state='provider_submitted',provider_task_id=p_provider_task_id,provider_submission_json=p_accepted_response,
  provider_submission_hash=v_hash,provider_submitted_at=now(),ambiguity_reason=null,
  failed_stage=null,failure_code=null,failure_message=null,updated_at=now()
 where operation_id=p_operation_id returning * into v_op;
 return jsonb_build_object('disposition','provider_submitted','operation',to_jsonb(v_op));
end $$;


ALTER FUNCTION "tongs"."record_broll_runway_task"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_submission_attempt_id" "uuid", "p_provider_task_id" "text", "p_accepted_response" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."record_credential_lifecycle_verification"("p_credential_id" "uuid", "p_verification_json" "jsonb", "p_activation_deployment_id" "text", "p_activation_deployment_sha" "text", "p_actor_id" "uuid", "p_event_key" "text", "p_occurred_at" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_row tongs.credential_lifecycle_records%rowtype;
  v_sequence integer;
  v_evidence jsonb:=coalesce(p_verification_json,'{}'::jsonb);
  v_now timestamptz:=coalesce(p_occurred_at,transaction_timestamp());
begin
  perform tongs._require_credential_lifecycle_writer();
  if p_actor_id is null or not tongs.is_platform_operator(p_actor_id) or p_event_key is null
     or not tongs._credential_lifecycle_metadata_safe(v_evidence) then
    raise exception 'invalid credential lifecycle verification' using errcode='22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('credential-lifecycle:'||p_credential_id::text,0));
  select * into v_row from tongs.credential_lifecycle_records where credential_id=p_credential_id for update;
  if not found then raise exception 'credential lifecycle record not found' using errcode='P0002'; end if;
  select coalesce(max(event_sequence),0)+1 into v_sequence
    from tongs.credential_lifecycle_events where credential_id=p_credential_id;
  update tongs.credential_lifecycle_records set
    activation_deployment_id=coalesce(nullif(btrim(coalesce(p_activation_deployment_id,'')),''),activation_deployment_id),
    activation_deployment_sha=coalesce(lower(nullif(btrim(coalesce(p_activation_deployment_sha,'')),'')),activation_deployment_sha),
    last_verification_at=v_now,
    config_presence_verified_at=case when coalesce((v_evidence->>'config_presence_verified')::boolean,false) then v_now else config_presence_verified_at end,
    route_configuration_verified_at=case when coalesce((v_evidence->>'route_configuration_verified')::boolean,false) then v_now else route_configuration_verified_at end,
    non_paid_readiness_verified_at=case when coalesce((v_evidence->>'non_paid_readiness_verified')::boolean,false) then v_now else non_paid_readiness_verified_at end,
    bounded_smoke_performed_at=case when coalesce((v_evidence->>'bounded_smoke_performed')::boolean,false) then v_now else bounded_smoke_performed_at end,
    smoke_operation_id=coalesce(nullif(v_evidence->>'smoke_operation_id',''),smoke_operation_id),
    updated_at=v_now
  where credential_id=p_credential_id returning * into v_row;
  insert into tongs.credential_lifecycle_events(
    event_id,credential_id,event_sequence,event_key,from_status,to_status,event_type,actor_id,evidence_json,occurred_at
  ) values (
    gen_random_uuid(),p_credential_id,v_sequence,btrim(p_event_key),v_row.lifecycle_status,
    v_row.lifecycle_status,'verification_recorded',p_actor_id,v_evidence,v_now
  );
  return to_jsonb(v_row)-'credential_identity_hash';
end;
$$;


ALTER FUNCTION "tongs"."record_credential_lifecycle_verification"("p_credential_id" "uuid", "p_verification_json" "jsonb", "p_activation_deployment_id" "text", "p_activation_deployment_sha" "text", "p_actor_id" "uuid", "p_event_key" "text", "p_occurred_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."record_customer_deposit"("p_deposit_id" "uuid", "p_user_id" "uuid", "p_stripe_event_id" "text", "p_stripe_session_id" "text", "p_stripe_payment_intent_id" "text", "p_livemode" boolean, "p_pack_id" "text", "p_gross_amount_micros" bigint, "p_currency" "text", "p_credit_units" bigint, "p_received_at" timestamp with time zone, "p_metadata_json" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $_$
declare
  v_mode text := case when coalesce(p_livemode, false) then 'live' else 'test' end;
  v_currency text := upper(btrim(coalesce(p_currency, '')));
  v_event_id text := nullif(btrim(coalesce(p_stripe_event_id, '')), '');
  v_session_id text := nullif(btrim(coalesce(p_stripe_session_id, '')), '');
  v_payment_intent text := nullif(btrim(coalesce(p_stripe_payment_intent_id, '')), '');
  v_pack text := nullif(btrim(coalesce(p_pack_id, '')), '');
  v_payload jsonb;
  v_existing tongs.customer_deposits%rowtype;
  v_created boolean;
begin
  perform tongs._require_accounting_service_role();
  if p_deposit_id is null or p_user_id is null or v_event_id is null or v_session_id is null
     or v_pack is null or p_gross_amount_micros <= 0 or p_credit_units <= 0
     or v_currency !~ '^[A-Z]{3}$' or jsonb_typeof(coalesce(p_metadata_json, '{}'::jsonb)) <> 'object' then
    raise exception 'invalid customer deposit' using errcode = '22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(v_mode || ':deposit:' || v_event_id || ':' || v_session_id, 0));
  select * into v_existing
  from tongs.customer_deposits deposit
  where (deposit.stripe_mode = v_mode and deposit.stripe_event_id = v_event_id)
     or (deposit.stripe_mode = v_mode and deposit.stripe_session_id = v_session_id)
     or (v_payment_intent is not null and deposit.stripe_mode = v_mode and deposit.stripe_payment_intent_id = v_payment_intent)
  limit 1;
  if found then
    if v_existing.user_id <> p_user_id
       or v_existing.stripe_event_id <> v_event_id or v_existing.stripe_session_id <> v_session_id
       or v_existing.stripe_payment_intent_id is distinct from v_payment_intent
       or v_existing.pack_id <> v_pack or v_existing.currency <> v_currency
       or v_existing.gross_amount_micros <> p_gross_amount_micros
       or v_existing.credit_units <> p_credit_units then
      raise exception 'customer deposit replay conflict' using errcode = '23505';
    end if;
    return jsonb_build_object('deposit_id', v_existing.id, 'stripe_mode', v_existing.stripe_mode, 'replay', true);
  end if;

  v_payload := jsonb_build_object(
    'deposit_id', p_deposit_id, 'user_id', p_user_id, 'stripe_event_id', v_event_id,
    'stripe_session_id', v_session_id, 'stripe_payment_intent_id', v_payment_intent,
    'stripe_mode', v_mode, 'pack_id', v_pack, 'gross_amount_micros', p_gross_amount_micros,
    'currency', v_currency, 'credit_units', p_credit_units, 'metadata', coalesce(p_metadata_json, '{}'::jsonb)
  );
  v_created := tongs._create_accounting_event(
    p_deposit_id, 'stripe:' || v_mode || ':deposit:' || v_event_id, 'customer_deposit_received',
    v_mode, 'stripe_checkout_session', v_session_id, v_currency, p_user_id, null, null,
    v_payload, coalesce(p_received_at, now())
  );
  if not v_created then raise exception 'deposit event exists without deposit record' using errcode = '23514'; end if;

  insert into tongs.customer_deposits(
    id, user_id, stripe_mode, stripe_event_id, stripe_session_id, stripe_payment_intent_id,
    pack_id, currency, gross_amount_micros, credit_units, journal_event_id, metadata_json, received_at
  ) values (
    p_deposit_id, p_user_id, v_mode, v_event_id, v_session_id, v_payment_intent,
    v_pack, v_currency, p_gross_amount_micros, p_credit_units, p_deposit_id,
    coalesce(p_metadata_json, '{}'::jsonb), coalesce(p_received_at, now())
  ) returning * into v_existing;

  insert into tongs.accounting_journal_entries(
    event_id, line_number, account_code, user_id, deposit_id, currency, amount_micros
  ) values
    (p_deposit_id, 1, case when v_mode = 'live' then 'forge_cash_clearing' else 'test_cash_clearing' end,
      p_user_id, p_deposit_id, v_currency, p_gross_amount_micros),
    (p_deposit_id, 2, case when v_mode = 'live' then 'customer_prepaid_liability' else 'test_customer_prepaid_balance' end,
      p_user_id, p_deposit_id, v_currency, -p_gross_amount_micros);
  insert into tongs.accounting_journal_entries(
    event_id, line_number, account_code, user_id, deposit_id, unit_kind, quantity_delta
  ) values (
    p_deposit_id, 3, case when v_mode = 'live' then 'live_customer_credits' else 'test_customer_credits' end,
    p_user_id, p_deposit_id, 'forge_credit', p_credit_units
  );
  perform tongs._assert_accounting_event_balanced(p_deposit_id);
  return jsonb_build_object('deposit_id', p_deposit_id, 'stripe_mode', v_mode, 'replay', false);
end;
$_$;


ALTER FUNCTION "tongs"."record_customer_deposit"("p_deposit_id" "uuid", "p_user_id" "uuid", "p_stripe_event_id" "text", "p_stripe_session_id" "text", "p_stripe_payment_intent_id" "text", "p_livemode" boolean, "p_pack_id" "text", "p_gross_amount_micros" bigint, "p_currency" "text", "p_credit_units" bigint, "p_received_at" timestamp with time zone, "p_metadata_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."record_customer_deposit_processor_fee"("p_fee_id" "uuid", "p_deposit_id" "uuid", "p_provider_fee_reference" "text", "p_fee_amount_micros" bigint, "p_recorded_at" timestamp with time zone, "p_evidence_json" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_deposit tongs.customer_deposits%rowtype;
  v_existing tongs.customer_deposit_processor_fees%rowtype;
  v_reference text := nullif(btrim(coalesce(p_provider_fee_reference, '')), '');
  v_payload jsonb;
begin
  perform tongs._require_accounting_service_role();
  if p_fee_id is null or p_deposit_id is null or v_reference is null or p_fee_amount_micros < 0 then
    raise exception 'invalid processor fee' using errcode = '22023';
  end if;
  select * into v_deposit from tongs.customer_deposits where id = p_deposit_id for update;
  if not found then raise exception 'deposit not found' using errcode = 'P0002'; end if;
  select * into v_existing from tongs.customer_deposit_processor_fees
  where deposit_id = p_deposit_id or provider_fee_reference = v_reference limit 1;
  if found then
    if v_existing.deposit_id <> p_deposit_id
       or v_existing.provider_fee_reference <> v_reference or v_existing.fee_amount_micros <> p_fee_amount_micros then
      raise exception 'processor fee replay conflict' using errcode = '23505';
    end if;
    return jsonb_build_object('processor_fee_id', v_existing.id, 'replay', true);
  end if;
  if p_fee_amount_micros > v_deposit.gross_amount_micros then
    raise exception 'processor fee exceeds deposit' using errcode = '22023';
  end if;
  v_payload := jsonb_build_object('fee_id', p_fee_id, 'deposit_id', p_deposit_id,
    'provider_fee_reference', v_reference, 'fee_amount_micros', p_fee_amount_micros,
    'evidence', coalesce(p_evidence_json, '{}'::jsonb));
  perform tongs._create_accounting_event(
    p_fee_id, 'stripe:' || v_deposit.stripe_mode || ':processor-fee:' || v_reference,
    'deposit_processor_fee_recorded', v_deposit.stripe_mode, 'stripe_balance_transaction',
    v_reference, v_deposit.currency, v_deposit.user_id, null, null, v_payload, coalesce(p_recorded_at, now())
  );
  insert into tongs.customer_deposit_processor_fees(
    id, deposit_id, provider_fee_reference, fee_amount_micros, journal_event_id, evidence_json, recorded_at
  ) values (p_fee_id, p_deposit_id, v_reference, p_fee_amount_micros, p_fee_id,
    coalesce(p_evidence_json, '{}'::jsonb), coalesce(p_recorded_at, now())) returning * into v_existing;
  if p_fee_amount_micros > 0 then
    insert into tongs.accounting_journal_entries(
      event_id, line_number, account_code, user_id, deposit_id, currency, amount_micros
    ) values
      (p_fee_id, 1, case when v_deposit.stripe_mode='live' then 'processor_fee_expense' else 'test_processor_fee' end,
        v_deposit.user_id, p_deposit_id, v_deposit.currency, p_fee_amount_micros),
      (p_fee_id, 2, case when v_deposit.stripe_mode='live' then 'forge_cash_clearing' else 'test_cash_clearing' end,
        v_deposit.user_id, p_deposit_id, v_deposit.currency, -p_fee_amount_micros);
    perform tongs._assert_accounting_event_balanced(p_fee_id);
  end if;
  return jsonb_build_object('processor_fee_id', p_fee_id, 'replay', false);
end;
$$;


ALTER FUNCTION "tongs"."record_customer_deposit_processor_fee"("p_fee_id" "uuid", "p_deposit_id" "uuid", "p_provider_fee_reference" "text", "p_fee_amount_micros" bigint, "p_recorded_at" timestamp with time zone, "p_evidence_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."record_customer_deposit_refund"("p_refund_id" "uuid", "p_deposit_id" "uuid", "p_stripe_refund_id" "text", "p_stripe_event_id" "text", "p_adjustment_type" "text", "p_refund_amount_micros" bigint, "p_refunded_at" timestamp with time zone, "p_evidence_json" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_deposit tongs.customer_deposits%rowtype;
  v_existing tongs.customer_deposit_refunds%rowtype;
  v_refund_reference text := nullif(btrim(coalesce(p_stripe_refund_id, '')), '');
  v_event_reference text := nullif(btrim(coalesce(p_stripe_event_id, '')), '');
  v_prior_refunds bigint;
  v_consumed_micros bigint;
  v_prior_refunded_units bigint;
  v_consumed_units bigint;
  v_liability_available bigint;
  v_liability_release bigint;
  v_discrepancy bigint;
  v_refunded_units bigint;
  v_payload jsonb;
begin
  perform tongs._require_accounting_service_role();
  if p_refund_id is null or p_deposit_id is null or v_refund_reference is null
     or v_event_reference is null or p_adjustment_type not in ('refund', 'dispute', 'payment_reversal')
     or p_refund_amount_micros <= 0 then
    raise exception 'invalid customer deposit refund' using errcode = '22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('stripe-refund:' || v_refund_reference, 0));
  select * into v_existing from tongs.customer_deposit_refunds where stripe_refund_id = v_refund_reference;
  if found then
    if v_existing.deposit_id <> p_deposit_id or v_existing.adjustment_type <> p_adjustment_type
       or v_existing.refund_amount_micros <> p_refund_amount_micros then
      raise exception 'customer refund replay conflict' using errcode = '23505';
    end if;
    return jsonb_build_object('refund_id', v_existing.id, 'replay', true);
  end if;
  select * into v_deposit from tongs.customer_deposits where id = p_deposit_id for update;
  if not found then raise exception 'deposit not found' using errcode = 'P0002'; end if;
  select coalesce(sum(refund_amount_micros), 0), coalesce(sum(refunded_credit_units), 0)
    into v_prior_refunds, v_prior_refunded_units
  from tongs.customer_deposit_refunds where deposit_id = p_deposit_id;
  if p_refund_amount_micros > v_deposit.gross_amount_micros - v_prior_refunds then
    raise exception 'refund exceeds deposit receipt' using errcode = 'P0001';
  end if;
  select coalesce(sum(recognized_revenue_micros), 0), coalesce(sum(credit_units_consumed), 0)
    into v_consumed_micros, v_consumed_units
  from tongs.customer_deposit_consumptions where deposit_id = p_deposit_id;
  v_liability_available := greatest(v_deposit.gross_amount_micros - v_consumed_micros -
    (select coalesce(sum(liability_release_micros), 0) from tongs.customer_deposit_refunds where deposit_id = p_deposit_id), 0);
  v_liability_release := least(p_refund_amount_micros, v_liability_available);
  v_discrepancy := p_refund_amount_micros - v_liability_release;
  v_refunded_units := least(
    v_deposit.credit_units - v_consumed_units - v_prior_refunded_units,
    greatest((v_deposit.credit_units * (v_prior_refunds + p_refund_amount_micros) / v_deposit.gross_amount_micros) - v_prior_refunded_units, 0)
  );
  v_payload := jsonb_build_object('refund_id', p_refund_id, 'deposit_id', p_deposit_id,
    'stripe_refund_id', v_refund_reference, 'stripe_event_id', v_event_reference,
    'adjustment_type', p_adjustment_type,
    'refund_amount_micros', p_refund_amount_micros, 'refunded_credit_units', v_refunded_units,
    'liability_release_micros', v_liability_release, 'discrepancy_expense_micros', v_discrepancy,
    'evidence', coalesce(p_evidence_json, '{}'::jsonb));
  perform tongs._create_accounting_event(
    p_refund_id, 'stripe:' || v_deposit.stripe_mode || ':refund:' || v_refund_reference,
    'customer_deposit_' || p_adjustment_type, v_deposit.stripe_mode, 'stripe_adjustment', v_refund_reference,
    v_deposit.currency, v_deposit.user_id, null, null, v_payload, coalesce(p_refunded_at, now())
  );
  insert into tongs.customer_deposit_refunds(
    id, deposit_id, stripe_refund_id, stripe_event_id, adjustment_type, refund_amount_micros,
    refunded_credit_units, liability_release_micros, discrepancy_expense_micros,
    journal_event_id, evidence_json, refunded_at
  ) values (
    p_refund_id, p_deposit_id, v_refund_reference, v_event_reference, p_adjustment_type, p_refund_amount_micros,
    v_refunded_units, v_liability_release, v_discrepancy, p_refund_id,
    coalesce(p_evidence_json, '{}'::jsonb), coalesce(p_refunded_at, now())
  );
  insert into tongs.accounting_journal_entries(
    event_id, line_number, account_code, user_id, deposit_id, currency, amount_micros
  )
  select p_refund_id, line_number, account_code, v_deposit.user_id, p_deposit_id,
    v_deposit.currency, amount_micros
  from (values
    (1::smallint, case when v_deposit.stripe_mode = 'live' then 'customer_prepaid_liability' else 'test_customer_prepaid_balance' end, v_liability_release),
    (2::smallint, case when v_deposit.stripe_mode = 'live' then 'refund_discrepancy_expense' else 'test_refund_discrepancy' end, v_discrepancy),
    (3::smallint, case when v_deposit.stripe_mode = 'live' then 'forge_cash_clearing' else 'test_cash_clearing' end, -p_refund_amount_micros)
  ) lines(line_number, account_code, amount_micros)
  where amount_micros <> 0;
  if v_refunded_units > 0 then
    insert into tongs.accounting_journal_entries(
      event_id, line_number, account_code, user_id, deposit_id, unit_kind, quantity_delta
    ) values (p_refund_id, 4,
      case when v_deposit.stripe_mode = 'live' then 'live_customer_credits' else 'test_customer_credits' end,
      v_deposit.user_id, p_deposit_id, 'forge_credit', -v_refunded_units);
  end if;
  perform tongs._assert_accounting_event_balanced(p_refund_id);
  return jsonb_build_object('refund_id', p_refund_id, 'replay', false,
    'liability_release_micros', v_liability_release, 'discrepancy_expense_micros', v_discrepancy,
    'refunded_credit_units', v_refunded_units);
end;
$$;


ALTER FUNCTION "tongs"."record_customer_deposit_refund"("p_refund_id" "uuid", "p_deposit_id" "uuid", "p_stripe_refund_id" "text", "p_stripe_event_id" "text", "p_adjustment_type" "text", "p_refund_amount_micros" bigint, "p_refunded_at" timestamp with time zone, "p_evidence_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."record_hearth_chat_test_evidence"("p_reservation_id" "uuid", "p_evidence_key" "text", "p_evidence_kind" "text", "p_evidence_json" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare v_existing uuid;
begin
  perform tongs._require_pricing_service_role();
  select id into v_existing from tongs.test_paid_execution_evidence where evidence_key=btrim(p_evidence_key);
  if v_existing is not null then return jsonb_build_object('evidence_id',v_existing,'replay',true); end if;
  v_existing:=gen_random_uuid();
  insert into tongs.test_paid_execution_evidence(id,reservation_id,evidence_key,evidence_kind,evidence_json)
  values(v_existing,p_reservation_id,btrim(p_evidence_key),btrim(p_evidence_kind),coalesce(p_evidence_json,'{}'::jsonb));
  return jsonb_build_object('evidence_id',v_existing,'replay',false);
end $$;


ALTER FUNCTION "tongs"."record_hearth_chat_test_evidence"("p_reservation_id" "uuid", "p_evidence_key" "text", "p_evidence_kind" "text", "p_evidence_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."record_hearth_event"("p_event_type" "text", "p_payload" "jsonb" DEFAULT '{}'::"jsonb", "p_episode_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare
  v_user uuid;
  v_event text;
  v_payload jsonb;
  v_workspace_id uuid;
  v_id uuid;
begin
  v_user := auth.uid();
  if v_user is null then
    raise exception 'Not authenticated'
      using errcode = '42501';
  end if;

  v_event := lower(trim(coalesce(p_event_type, '')));
  if v_event = '' then
    raise exception 'p_event_type required'
      using errcode = '22023';
  end if;

  v_payload := coalesce(p_payload, '{}'::jsonb);

  if p_episode_id is not null then
    select e.workspace_id
    into v_workspace_id
    from tongs.episodes e
    where e.id = p_episode_id;
  end if;

  insert into tongs.hearth_interaction_events (
    user_id,
    workspace_id,
    episode_id,
    event_type,
    payload
  )
  values (
    v_user,
    v_workspace_id,
    p_episode_id,
    v_event,
    v_payload
  )
  returning id into v_id;

  if v_event in (
    'user_requested_outline',
    'user_requested_script',
    'user_explicit_draft_now',
    'proposal_discarded',
    'proposal_applied',
    'outline_generated',
    'draft_generated'
  ) then
    perform tongs.update_creator_profile_from_event(v_event, v_payload);
  end if;

  return v_id;
end;
$$;


ALTER FUNCTION "tongs"."record_hearth_event"("p_event_type" "text", "p_payload" "jsonb", "p_episode_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."record_hearth_tag_validation_failure_evidence"("p_operation_id" "text", "p_reservation_id" "uuid", "p_provider_request_id" "text", "p_model" "text", "p_input_units" bigint, "p_output_units" bigint, "p_raw_provider_response_text" "text", "p_validation_error_code" "text", "p_validation_contract_revision" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  binding tongs.openai_text_funding_bindings%rowtype;
  capture tongs.openai_text_provider_captures%rowtype;
  existing tongs.hearth_tag_validation_failure_evidence%rowtype;
  evidence_id uuid := extensions.uuid_generate_v5(
    p_reservation_id, 'hearth-tag-validation-failure-v2');
begin
  perform tongs._require_pricing_service_role();
  perform pg_advisory_xact_lock(hashtextextended(
    'hearth-tag-validation-failure:' || p_reservation_id::text, 0));

  select * into binding from tongs.openai_text_funding_bindings
  where operation_id=btrim(p_operation_id) and reservation_id=p_reservation_id
    and route_code='hearth.tag_generation';
  select * into capture from tongs.openai_text_provider_captures
  where reservation_id=p_reservation_id and attempt_number=1;
  if binding.reservation_id is null or binding.model<>'gpt-5.6-luna'
    or binding.maximum_attempts<>1 or capture.id is null
    or capture.provider_request_id is distinct from nullif(btrim(coalesce(p_provider_request_id,'')), '')
    or capture.input_units is distinct from p_input_units
    or capture.output_units is distinct from p_output_units
    or capture.response_evidence_json->>'raw_provider_response_text'
      is distinct from p_raw_provider_response_text
    or p_model is distinct from binding.model
    or p_validation_contract_revision is distinct from 'tags_top10_comma_block.v2'
    or p_validation_error_code not in (
      'invalid_tag_output','invalid_tag_structure','invalid_tag_count',
      'invalid_tag_candidate','duplicate_tag_candidate'
    )
    or p_raw_provider_response_text is null
    or octet_length(p_raw_provider_response_text) not between 1 and 65536
  then raise exception 'invalid Hearth tag validation evidence' using errcode='22023'; end if;

  select * into existing from tongs.hearth_tag_validation_failure_evidence
  where reservation_id=p_reservation_id or operation_id=btrim(p_operation_id);
  if found then
    if existing.operation_id is distinct from btrim(p_operation_id)
      or existing.reservation_id is distinct from p_reservation_id
      or existing.provider_request_id is distinct from capture.provider_request_id
      or existing.model is distinct from p_model
      or existing.input_units is distinct from p_input_units
      or existing.output_units is distinct from p_output_units
      or existing.raw_provider_response_text is distinct from p_raw_provider_response_text
      or existing.validation_error_code is distinct from p_validation_error_code
      or existing.validation_contract_revision is distinct from p_validation_contract_revision
    then raise exception 'Hearth tag validation evidence replay conflict' using errcode='23505'; end if;
    return jsonb_build_object('evidence_id',existing.id,'replay',true);
  end if;

  insert into tongs.hearth_tag_validation_failure_evidence (
    id,operation_id,reservation_id,provider_request_id,model,input_units,
    output_units,raw_provider_response_text,validation_error_code,
    validation_contract_revision
  ) values (
    evidence_id,btrim(p_operation_id),p_reservation_id,capture.provider_request_id,
    p_model,p_input_units,p_output_units,p_raw_provider_response_text,
    p_validation_error_code,p_validation_contract_revision
  );
  return jsonb_build_object('evidence_id',evidence_id,'replay',false);
end $$;


ALTER FUNCTION "tongs"."record_hearth_tag_validation_failure_evidence"("p_operation_id" "text", "p_reservation_id" "uuid", "p_provider_request_id" "text", "p_model" "text", "p_input_units" bigint, "p_output_units" bigint, "p_raw_provider_response_text" "text", "p_validation_error_code" "text", "p_validation_contract_revision" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."record_hearth_thumbnail_base_generation_result"("p_operation_id" "text", "p_request_fingerprint" "text", "p_provider_body_sha256" "text", "p_prompt_package_hash" "text", "p_render_recipe_id" "uuid", "p_render_recipe_revision" integer, "p_concept_revision_id" "uuid", "p_provider_request_id" "text", "p_provider_response_id" "text", "p_staged_asset_id" "uuid", "p_canonical_receipt_json" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $_$
declare
  binding_row tongs.openai_text_funding_bindings%rowtype;
  reservation_row tongs.funding_reservations%rowtype;
  quote_row tongs.customer_spending_quotes%rowtype;
  asset_row tongs.assets%rowtype;
  existing_row tongs.hearth_thumbnail_base_generation_results%rowtype;
  result_id uuid:=extensions.uuid_generate_v5(
    '19630000-0000-4000-8000-000000000012'::uuid,btrim(p_operation_id));
begin
  perform tongs._require_pricing_service_role();
  if p_operation_id is null or p_request_fingerprint!~'^[0-9a-f]{64}$'
     or p_provider_body_sha256!~'^[0-9a-f]{64}$' or p_prompt_package_hash!~'^[0-9a-f]{64}$'
     or p_render_recipe_id is null or p_render_recipe_revision<=0 or p_concept_revision_id is null
     or p_staged_asset_id is null or jsonb_typeof(p_canonical_receipt_json)<>'object'
  then raise exception 'invalid Thumbnail Base result evidence' using errcode='22023'; end if;
  select * into binding_row from tongs.openai_text_funding_bindings
    where operation_id=btrim(p_operation_id) and route_code='hearth.thumbnail_base_generation';
  if not found then raise exception 'Thumbnail Base funding binding not found' using errcode='P0002'; end if;
  select * into reservation_row from tongs.funding_reservations where id=binding_row.reservation_id;
  select * into quote_row from tongs.customer_spending_quotes where id=reservation_row.quote_id;
  select * into asset_row from tongs.assets where id=p_staged_asset_id;
  if quote_row.request_fingerprint<>lower(p_request_fingerprint)
     or asset_row.workspace_id<>quote_row.workspace_id
     or asset_row.workpiece_id is null
     or asset_row.request_id<>btrim(p_operation_id)
  then raise exception 'Thumbnail Base result evidence conflicts with canonical authority' using errcode='23505'; end if;
  select * into existing_row from tongs.hearth_thumbnail_base_generation_results
    where operation_id=btrim(p_operation_id);
  if found then
    if existing_row.reservation_id<>binding_row.reservation_id
       or existing_row.request_fingerprint<>lower(p_request_fingerprint)
       or existing_row.provider_body_sha256<>lower(p_provider_body_sha256)
       or existing_row.prompt_package_hash<>lower(p_prompt_package_hash)
       or existing_row.render_recipe_id<>p_render_recipe_id
       or existing_row.render_recipe_revision<>p_render_recipe_revision
       or existing_row.concept_revision_id<>p_concept_revision_id
       or existing_row.staged_asset_id<>p_staged_asset_id
    then raise exception 'Thumbnail Base result replay conflict' using errcode='23505'; end if;
    return jsonb_build_object('result_id',existing_row.id,'state',existing_row.state,'replay',true);
  end if;
  insert into tongs.hearth_thumbnail_base_generation_results(
    id,operation_id,reservation_id,user_id,workspace_id,workpiece_id,request_fingerprint,
    provider_body_sha256,prompt_package_hash,render_recipe_id,render_recipe_revision,
    concept_revision_id,provider_request_id,provider_response_id,generated_content_hash,
    staged_asset_id,staged_asset_path,canonical_receipt_json,state,completed_at
  ) values (
    result_id,btrim(p_operation_id),binding_row.reservation_id,reservation_row.user_id,
    quote_row.workspace_id,asset_row.workpiece_id,lower(p_request_fingerprint),
    lower(p_provider_body_sha256),lower(p_prompt_package_hash),p_render_recipe_id,
    p_render_recipe_revision,p_concept_revision_id,nullif(btrim(coalesce(p_provider_request_id,'')),''),
    nullif(btrim(coalesce(p_provider_response_id,'')),''),asset_row.content_hash,
    asset_row.id,asset_row.path,p_canonical_receipt_json,'asset_staged',now()
  );
  return jsonb_build_object('result_id',result_id,'state','asset_staged','replay',false);
end $_$;


ALTER FUNCTION "tongs"."record_hearth_thumbnail_base_generation_result"("p_operation_id" "text", "p_request_fingerprint" "text", "p_provider_body_sha256" "text", "p_prompt_package_hash" "text", "p_render_recipe_id" "uuid", "p_render_recipe_revision" integer, "p_concept_revision_id" "uuid", "p_provider_request_id" "text", "p_provider_response_id" "text", "p_staged_asset_id" "uuid", "p_canonical_receipt_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."record_image_prompt_provider_response"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_provider_response_json" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare v_op tongs.image_map_prompt_operation_receipts%rowtype; v_hash text;
begin
  select * into v_op from tongs.image_map_prompt_operation_receipts where operation_id=p_operation_id for update;
  if not found then return jsonb_build_object('disposition','operation_not_found'); end if;
  if not tongs.has_workspace_role(v_op.workspace_id,'editor') then raise exception 'workspace editor authority required' using errcode='42501'; end if;
  if v_op.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict'); end if;
  if v_op.state in ('provider_completed','committed') then return jsonb_build_object('disposition','replay','operation',to_jsonb(v_op)); end if;
  if v_op.state<>'pending' then return jsonb_build_object('disposition','invalid_operation_state','state',v_op.state); end if;
  v_hash:=encode(extensions.digest(convert_to(p_provider_response_json::text,'UTF8'),'sha256'),'hex');
  update tongs.image_map_prompt_operation_receipts set state='provider_completed',provider_response_json=p_provider_response_json,provider_response_hash=v_hash,failed_stage=null,failure_code=null,failure_message=null,updated_at=now() where operation_id=p_operation_id returning * into v_op;
  return jsonb_build_object('disposition','provider_recorded','operation',to_jsonb(v_op));
end $$;


ALTER FUNCTION "tongs"."record_image_prompt_provider_response"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_provider_response_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."record_legacy_credit_conversion_mapping"("p_mapping_id" "uuid", "p_decision_id" "uuid", "p_source_kind" "text", "p_source_id" "text", "p_canonical_kind" "text", "p_canonical_id" "uuid", "p_converted_credit_units" bigint, "p_reused_existing_journal_event" boolean, "p_evidence_json" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_decision tongs.legacy_credit_reconciliation_decisions%rowtype;
  v_existing tongs.legacy_credit_conversion_mappings%rowtype;
begin
  perform tongs._require_pricing_service_role();
  if p_mapping_id is null or p_decision_id is null or p_canonical_id is null
     or nullif(btrim(coalesce(p_source_kind, '')), '') is null
     or nullif(btrim(coalesce(p_source_id, '')), '') is null
     or nullif(btrim(coalesce(p_canonical_kind, '')), '') is null
     or p_converted_credit_units < 0
     or jsonb_typeof(p_evidence_json) is distinct from 'object' then
    raise exception 'complete legacy conversion mapping is required' using errcode = '22023';
  end if;

  select * into v_decision
  from tongs.legacy_credit_reconciliation_decisions
  where id = p_decision_id;
  if not found or v_decision.decision not in (
    'record_exact_reconciliation', 'approve_supported_amount'
  ) then
    raise exception 'approved reconciliation decision is required' using errcode = '42501';
  end if;
  if p_converted_credit_units > v_decision.supported_credit_units then
    raise exception 'conversion exceeds the approved supported amount' using errcode = '22003';
  end if;

  select * into v_existing
  from tongs.legacy_credit_conversion_mappings
  where source_kind = btrim(p_source_kind) and source_id = btrim(p_source_id);
  if found then
    if v_existing.case_id is distinct from v_decision.case_id
       or v_existing.canonical_kind <> btrim(p_canonical_kind)
       or v_existing.canonical_id <> p_canonical_id
       or v_existing.converted_credit_units <> p_converted_credit_units
       or v_existing.reused_existing_journal_event <> p_reused_existing_journal_event then
      raise exception 'legacy conversion replay conflict' using errcode = '23505';
    end if;
    return to_jsonb(v_existing) || jsonb_build_object('replay', true);
  end if;

  insert into tongs.legacy_credit_conversion_mappings(
    id, case_id, source_kind, source_id, canonical_kind, canonical_id,
    converted_credit_units, reused_existing_journal_event, evidence_json
  ) values (
    p_mapping_id, v_decision.case_id, btrim(p_source_kind), btrim(p_source_id),
    btrim(p_canonical_kind), p_canonical_id, p_converted_credit_units,
    p_reused_existing_journal_event, p_evidence_json || jsonb_build_object('decision_id', p_decision_id)
  );
  return jsonb_build_object('mapping_id', p_mapping_id, 'case_id', v_decision.case_id, 'replay', false);
end $$;


ALTER FUNCTION "tongs"."record_legacy_credit_conversion_mapping"("p_mapping_id" "uuid", "p_decision_id" "uuid", "p_source_kind" "text", "p_source_id" "text", "p_canonical_kind" "text", "p_canonical_id" "uuid", "p_converted_credit_units" bigint, "p_reused_existing_journal_event" boolean, "p_evidence_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."record_legacy_credit_reconciliation_decision"("p_decision_id" "uuid", "p_case_id" "uuid", "p_actor_id" "uuid", "p_classification" "text", "p_decision" "text", "p_supported_credit_units" bigint, "p_calculation_json" "jsonb", "p_evidence_hashes" "jsonb", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare v_existing tongs.legacy_credit_reconciliation_decisions%rowtype;
begin
  perform tongs._require_pricing_service_role();
  if p_actor_id is null or not tongs.is_platform_operator(p_actor_id)
     or p_decision_id is null or p_case_id is null
     or p_classification not in (
       'exact_reconciliation', 'supported_pending_operator_approval',
       'unsupported', 'malformed_or_conflicting'
     )
     or p_decision not in (
       'record_exact_reconciliation', 'approve_supported_amount', 'reject_unsupported_value'
     )
     or p_supported_credit_units < 0
     or jsonb_typeof(p_calculation_json) is distinct from 'object'
     or jsonb_typeof(p_evidence_hashes) is distinct from 'array'
     or jsonb_array_length(p_evidence_hashes) = 0
     or nullif(btrim(coalesce(p_reason, '')), '') is null then
    raise exception 'complete operator reconciliation decision is required' using errcode = '22023';
  end if;
  if (p_classification = 'exact_reconciliation' and p_decision <> 'record_exact_reconciliation')
     or (p_classification = 'supported_pending_operator_approval' and p_decision <> 'approve_supported_amount')
     or (p_classification in ('unsupported', 'malformed_or_conflicting')
         and p_decision <> 'reject_unsupported_value') then
    raise exception 'classification and decision are inconsistent' using errcode = '22023';
  end if;
  if exists (
    select 1 from jsonb_array_elements_text(p_evidence_hashes) hash
    where not exists (
      select 1 from tongs.legacy_credit_reconciliation_evidence evidence
      where evidence.case_id = p_case_id and evidence.evidence_hash = hash
    )
  ) then
    raise exception 'decision cites unknown evidence' using errcode = 'P0002';
  end if;
  select * into v_existing from tongs.legacy_credit_reconciliation_decisions where id = p_decision_id;
  if found then return to_jsonb(v_existing) || jsonb_build_object('replay', true); end if;
  insert into tongs.legacy_credit_reconciliation_decisions(
    id, case_id, classification, decision, supported_credit_units,
    calculation_json, evidence_hashes, reason, actor_id
  ) values (
    p_decision_id, p_case_id, p_classification, p_decision,
    p_supported_credit_units, p_calculation_json, p_evidence_hashes,
    btrim(p_reason), p_actor_id
  );
  return jsonb_build_object('decision_id', p_decision_id, 'classification', p_classification, 'replay', false);
end $$;


ALTER FUNCTION "tongs"."record_legacy_credit_reconciliation_decision"("p_decision_id" "uuid", "p_case_id" "uuid", "p_actor_id" "uuid", "p_classification" "text", "p_decision" "text", "p_supported_credit_units" bigint, "p_calculation_json" "jsonb", "p_evidence_hashes" "jsonb", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."record_legacy_credit_reconciliation_evidence"("p_evidence_id" "uuid", "p_case_id" "uuid", "p_evidence_kind" "text", "p_source_identifier" "text", "p_evidence_json" "jsonb", "p_observed_at" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare v_hash text; v_existing tongs.legacy_credit_reconciliation_evidence%rowtype;
begin
  perform tongs._require_pricing_service_role();
  if p_evidence_id is null or p_case_id is null
     or nullif(btrim(coalesce(p_evidence_kind, '')), '') is null
     or nullif(btrim(coalesce(p_source_identifier, '')), '') is null
     or jsonb_typeof(p_evidence_json) is distinct from 'object'
     or p_observed_at is null then
    raise exception 'complete reconciliation evidence is required' using errcode = '22023';
  end if;
  v_hash := encode(extensions.digest(convert_to(p_evidence_json::text, 'utf8'), 'sha256'), 'hex');
  select * into v_existing from tongs.legacy_credit_reconciliation_evidence
  where case_id = p_case_id and evidence_kind = btrim(p_evidence_kind)
    and source_identifier = btrim(p_source_identifier);
  if found then
    if v_existing.evidence_hash <> v_hash then
      raise exception 'reconciliation evidence replay conflict' using errcode = '23505';
    end if;
    return to_jsonb(v_existing) || jsonb_build_object('replay', true);
  end if;
  insert into tongs.legacy_credit_reconciliation_evidence(
    id, case_id, evidence_kind, source_identifier, evidence_hash,
    evidence_json, observed_at
  ) values (
    p_evidence_id, p_case_id, btrim(p_evidence_kind), btrim(p_source_identifier),
    v_hash, p_evidence_json, p_observed_at
  );
  return jsonb_build_object('evidence_id', p_evidence_id, 'evidence_hash', v_hash, 'replay', false);
end $$;


ALTER FUNCTION "tongs"."record_legacy_credit_reconciliation_evidence"("p_evidence_id" "uuid", "p_case_id" "uuid", "p_evidence_kind" "text", "p_source_identifier" "text", "p_evidence_json" "jsonb", "p_observed_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."record_openai_organization_reconciliation"("p_batch_id" "uuid", "p_source_key" "text", "p_period_start" timestamp with time zone, "p_period_end" timestamp with time zone, "p_currency" "text", "p_total_cost_micros" bigint, "p_source_kind" "text", "p_evidence_status" "text", "p_cost_buckets" "jsonb", "p_usage_buckets" "jsonb", "p_raw_evidence_json" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare existing tongs.openai_organization_reconciliation_batches%rowtype; prior record; cost_sum bigint;
 overlap_count bigint; incompatible_overlap_count bigint;
 v_scope_key text; new_state text:='accepted'; state_reason text:='Non-overlapping provider evidence accepted.'; result jsonb;
begin
 perform tongs._require_pricing_service_role();
 if p_batch_id is null or length(btrim(coalesce(p_source_key,'')))<8 or p_period_end<=p_period_start
    or upper(btrim(coalesce(p_currency,'')))<>'USD' or p_total_cost_micros<0
    or p_source_kind not in ('organization_costs_api','provider_invoice') or p_evidence_status not in ('confirmed','incomplete')
    or jsonb_typeof(coalesce(p_cost_buckets,'null'::jsonb))<>'array' or jsonb_typeof(coalesce(p_usage_buckets,'null'::jsonb))<>'array'
    or jsonb_typeof(coalesce(p_raw_evidence_json,'null'::jsonb))<>'object' then
  raise exception 'invalid OpenAI reconciliation batch' using errcode='22023'; end if;
 select coalesce(sum((item->>'amount_micros')::bigint),0) into cost_sum from jsonb_array_elements(p_cost_buckets)item;
 if cost_sum<>p_total_cost_micros then raise exception 'OpenAI cost bucket total mismatch' using errcode='22023'; end if;
 v_scope_key:=tongs._openai_reconciliation_scope_key(p_source_kind,upper(p_currency),p_raw_evidence_json);
 perform pg_advisory_xact_lock(hashtextextended('openai-reconciliation-scope:'||v_scope_key,0));
 select * into existing from tongs.openai_organization_reconciliation_batches where source_key=btrim(p_source_key);
 if found then
  if existing.total_cost_micros<>p_total_cost_micros or existing.period_start<>p_period_start or existing.period_end<>p_period_end then
   raise exception 'OpenAI reconciliation replay conflict' using errcode='23505'; end if;
  result:=tongs._process_openai_organization_reconciliation(existing.id);
  return result||jsonb_build_object('replay',true);
 end if;
 insert into tongs.openai_organization_reconciliation_batches(id,source_key,period_start,period_end,currency,total_cost_micros,source_kind,evidence_status,raw_evidence_json)
 values(p_batch_id,btrim(p_source_key),p_period_start,p_period_end,'USD',p_total_cost_micros,p_source_kind,p_evidence_status,p_raw_evidence_json);
 insert into tongs.openai_organization_cost_buckets(id,batch_id,bucket_key,project_id,api_key_id,line_item,amount_micros,evidence_json)
 select gen_random_uuid(),p_batch_id,btrim(item->>'bucket_key'),nullif(btrim(coalesce(item->>'project_id','')),''),nullif(btrim(coalesce(item->>'api_key_id','')),''),
  nullif(btrim(coalesce(item->>'line_item','')),''),(item->>'amount_micros')::bigint,coalesce(item->'evidence','{}'::jsonb) from jsonb_array_elements(p_cost_buckets)item;
 insert into tongs.openai_organization_usage_buckets(id,batch_id,bucket_key,model,project_id,api_key_id,input_tokens,cached_input_tokens,output_tokens,request_count,evidence_json)
 select gen_random_uuid(),p_batch_id,btrim(item->>'bucket_key'),nullif(btrim(coalesce(item->>'model','')),''),nullif(btrim(coalesce(item->>'project_id','')),''),nullif(btrim(coalesce(item->>'api_key_id','')),''),
  coalesce((item->>'input_tokens')::bigint,0),coalesce((item->>'cached_input_tokens')::bigint,0),coalesce((item->>'output_tokens')::bigint,0),coalesce((item->>'request_count')::bigint,0),coalesce(item->'evidence','{}'::jsonb)
 from jsonb_array_elements(p_usage_buckets)item;

 select count(*),count(*) filter(where not(p_evidence_status='confirmed' and p_period_start<=b.period_start and p_period_end>=b.period_end))
 into overlap_count,incompatible_overlap_count
 from tongs.openai_organization_reconciliation_batches b
 where b.id<>p_batch_id and tongs._openai_reconciliation_scope_key(b.source_kind,b.currency,b.raw_evidence_json)=v_scope_key
   and tongs._openai_reconciliation_batch_state(b.id)='accepted' and tstzrange(b.period_start,b.period_end,'[)')&&tstzrange(p_period_start,p_period_end,'[)');
 if incompatible_overlap_count>0 then
  new_state:='overlap_quarantined'; state_reason:='Overlapping evidence did not fully and authoritatively supersede every effective window; excluded from totals and allocations.';
 elsif overlap_count>0 then
  state_reason:='Confirmed provider evidence accepted; fully contained earlier windows were superseded append-only.';
 end if;
 for prior in
  select b.* from tongs.openai_organization_reconciliation_batches b
  where b.id<>p_batch_id and tongs._openai_reconciliation_scope_key(b.source_kind,b.currency,b.raw_evidence_json)=v_scope_key
    and tongs._openai_reconciliation_batch_state(b.id)='accepted' and tstzrange(b.period_start,b.period_end,'[)')&&tstzrange(p_period_start,p_period_end,'[)')
 loop
  if new_state='accepted' then
   insert into tongs.openai_reconciliation_batch_state_events(id,batch_id,sequence,event_key,state,related_batch_id,scope_key,reason)
   select extensions.uuid_generate_v5(prior.id,'superseded-by:'||p_batch_id::text),prior.id,coalesce(max(sequence),0)+1,
    'openai-reconciliation:'||prior.id::text||':superseded-by:'||p_batch_id::text,'superseded',p_batch_id,v_scope_key,
    'A confirmed provider window with the same scope fully contains this earlier window.'
   from tongs.openai_reconciliation_batch_state_events where batch_id=prior.id;
  end if;
 end loop;
 insert into tongs.openai_reconciliation_batch_state_events(id,batch_id,sequence,event_key,state,scope_key,reason)
 values(extensions.uuid_generate_v5(p_batch_id,'reconciliation-state:'||new_state),p_batch_id,1,
  'openai-reconciliation:'||p_batch_id::text||':'||new_state,new_state,v_scope_key,state_reason);
 result:=tongs._process_openai_organization_reconciliation(p_batch_id);
 return result||jsonb_build_object('replay',false,'batch_state',new_state,'note',state_reason);
end $$;


ALTER FUNCTION "tongs"."record_openai_organization_reconciliation"("p_batch_id" "uuid", "p_source_key" "text", "p_period_start" timestamp with time zone, "p_period_end" timestamp with time zone, "p_currency" "text", "p_total_cost_micros" bigint, "p_source_kind" "text", "p_evidence_status" "text", "p_cost_buckets" "jsonb", "p_usage_buckets" "jsonb", "p_raw_evidence_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."record_openai_supplier_expense_obligation_settlement"("p_id" "uuid", "p_supplier_expense_id" "uuid", "p_batch_id" "uuid", "p_allocation_id" "uuid", "p_event_key" "text", "p_evidence_json" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  expense tongs.supplier_expenses%rowtype;
  adjustment tongs.openai_supplier_expense_reconciliation_adjustments%rowtype;
  existing tongs.openai_supplier_expense_obligation_settlement_events%rowtype;
  next_sequence integer;
begin
  perform tongs._require_pricing_service_role();
  if p_id is null or length(btrim(coalesce(p_event_key,''))) not between 8 and 300
     or jsonb_typeof(coalesce(p_evidence_json,'null'::jsonb))<>'object' then
    raise exception 'invalid supplier obligation settlement' using errcode='22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('supplier-obligation:'||p_supplier_expense_id::text,0));
  select * into existing
  from tongs.openai_supplier_expense_obligation_settlement_events
  where event_key=btrim(p_event_key) or (supplier_expense_id=p_supplier_expense_id and reconciliation_batch_id=p_batch_id)
  order by created_at limit 1;
  if found then
    if existing.id<>p_id or existing.supplier_expense_id<>p_supplier_expense_id
       or existing.reconciliation_batch_id<>p_batch_id or existing.operation_allocation_id<>p_allocation_id then
      raise exception 'supplier obligation settlement replay conflict' using errcode='23505';
    end if;
    return to_jsonb(existing)||jsonb_build_object('replay',true);
  end if;
  select * into expense from tongs.supplier_expenses where id=p_supplier_expense_id;
  select * into adjustment from tongs.openai_supplier_expense_reconciliation_adjustments
    where supplier_expense_id=p_supplier_expense_id and reconciliation_batch_id=p_batch_id
      and operation_allocation_id=p_allocation_id;
  if expense.id is null or expense.provider<>'openai' or adjustment.id is null
     or tongs._openai_reconciliation_batch_state(p_batch_id)<>'accepted' then
    raise exception 'accepted supplier reconciliation adjustment required' using errcode='P0001';
  end if;
  select coalesce(max(sequence),0)+1 into next_sequence
  from tongs.openai_supplier_expense_obligation_settlement_events
  where supplier_expense_id=p_supplier_expense_id;
  insert into tongs.openai_supplier_expense_obligation_settlement_events(
    id,supplier_expense_id,reconciliation_batch_id,operation_allocation_id,sequence,event_key,
    effective_obligation_status,confirmed_amount_micros,currency,evidence_json
  ) values(
    p_id,p_supplier_expense_id,p_batch_id,p_allocation_id,next_sequence,btrim(p_event_key),
    'closed',adjustment.confirmed_amount_micros,expense.currency,
    coalesce(p_evidence_json,'{}'::jsonb)||jsonb_build_object(
      'authoritative',true,'original_obligation_status',expense.obligation_status,
      'original_estimated_amount_micros',expense.amount_micros)
  ) returning * into existing;
  return to_jsonb(existing)||jsonb_build_object('replay',false);
end $$;


ALTER FUNCTION "tongs"."record_openai_supplier_expense_obligation_settlement"("p_id" "uuid", "p_supplier_expense_id" "uuid", "p_batch_id" "uuid", "p_allocation_id" "uuid", "p_event_key" "text", "p_evidence_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."record_openai_supplier_expense_reconciliation_adjustment"("p_id" "uuid", "p_supplier_expense_id" "uuid", "p_batch_id" "uuid", "p_allocation_id" "uuid", "p_source_key" "text", "p_confirmed_amount_micros" bigint, "p_matching_method" "text", "p_evidence_json" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare e tongs.supplier_expenses%rowtype; a tongs.openai_text_operation_cost_allocations%rowtype;
 existing tongs.openai_supplier_expense_reconciliation_adjustments%rowtype;
begin
 perform tongs._require_pricing_service_role();
 select * into existing from tongs.openai_supplier_expense_reconciliation_adjustments where source_key=btrim(p_source_key);
 if found then
  if existing.supplier_expense_id<>p_supplier_expense_id or existing.reconciliation_batch_id<>p_batch_id or existing.confirmed_amount_micros<>p_confirmed_amount_micros then
   raise exception 'OpenAI expense adjustment replay conflict' using errcode='23505'; end if;
  return to_jsonb(existing)||jsonb_build_object('replay',true);
 end if;
 select * into e from tongs.supplier_expenses where id=p_supplier_expense_id;
 select * into a from tongs.openai_text_operation_cost_allocations where id=p_allocation_id and batch_id=p_batch_id;
 if e.id is null or e.provider<>'openai' or a.id is null or a.allocation_status<>'confirmed'
    or a.allocated_cost_micros<>p_confirmed_amount_micros or e.reservation_id<>a.reservation_id
    or tongs._openai_reconciliation_batch_state(p_batch_id)<>'accepted' then
  raise exception 'confirmed defensible effective operation allocation required' using errcode='P0001'; end if;
 insert into tongs.openai_supplier_expense_reconciliation_adjustments(id,supplier_expense_id,reconciliation_batch_id,operation_allocation_id,source_key,estimated_amount_micros,confirmed_amount_micros,adjustment_micros,currency,matching_method,evidence_json)
 values(p_id,e.id,p_batch_id,a.id,btrim(p_source_key),e.amount_micros,p_confirmed_amount_micros,
  p_confirmed_amount_micros-coalesce(e.amount_micros,0),e.currency,p_matching_method,coalesce(p_evidence_json,'{}'::jsonb)) returning * into existing;
 return to_jsonb(existing)||jsonb_build_object('replay',false);
end $$;


ALTER FUNCTION "tongs"."record_openai_supplier_expense_reconciliation_adjustment"("p_id" "uuid", "p_supplier_expense_id" "uuid", "p_batch_id" "uuid", "p_allocation_id" "uuid", "p_source_key" "text", "p_confirmed_amount_micros" bigint, "p_matching_method" "text", "p_evidence_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."record_openai_text_failure_realized_loss_correction"("p_correction_id" "uuid", "p_correction_key" "text", "p_failure_event_id" "uuid", "p_financial_environment" "text", "p_direct_supplier_cost_micros" bigint, "p_direct_cost_status" "text", "p_attributable_variable_supporting_cost_micros" bigint, "p_supporting_cost_status" "text", "p_excluded_nonrealized_cost_micros" bigint, "p_correction_kind" "text", "p_evidence_json" "jsonb", "p_actor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  event_row tongs.openai_text_failure_exposure_events%rowtype;
  reservation_environment text;
  existing tongs.openai_text_failure_realized_loss_corrections%rowtype;
  next_revision integer;
begin
  perform tongs._require_pricing_service_role();
  if p_correction_id is null or p_failure_event_id is null or p_actor_id is null
    or not tongs.is_platform_operator(p_actor_id)
    or length(btrim(coalesce(p_correction_key,''))) not between 8 and 240
    or p_financial_environment not in('test','live')
    or p_direct_supplier_cost_micros<0
    or p_direct_cost_status not in('estimated','authoritative')
    or p_attributable_variable_supporting_cost_micros<0
    or p_supporting_cost_status not in('verified','none_verified')
    or p_excluded_nonrealized_cost_micros<0
    or p_correction_kind not in('classification_correction','provider_reconciliation')
    or jsonb_typeof(coalesce(p_evidence_json,'null'::jsonb))<>'object' then
    raise exception 'invalid realized-loss correction' using errcode='22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(
    'openai-realized-loss-correction:'||p_failure_event_id::text,0));
  select * into existing from tongs.openai_text_failure_realized_loss_corrections
    where correction_key=btrim(p_correction_key) or id=p_correction_id;
  if found then
    if existing.id<>p_correction_id or existing.failure_event_id<>p_failure_event_id
      or existing.financial_environment<>p_financial_environment
      or existing.direct_supplier_cost_micros<>p_direct_supplier_cost_micros
      or existing.direct_cost_status<>p_direct_cost_status
      or existing.attributable_variable_supporting_cost_micros<>p_attributable_variable_supporting_cost_micros
      or existing.supporting_cost_status<>p_supporting_cost_status
      or existing.excluded_nonrealized_cost_micros<>p_excluded_nonrealized_cost_micros
      or existing.correction_kind<>p_correction_kind then
      raise exception 'realized-loss correction idempotency conflict' using errcode='23505';
    end if;
    return to_jsonb(existing)||jsonb_build_object('replay',true);
  end if;
  select exposure_event.* into event_row
  from tongs.openai_text_failure_exposure_events exposure_event
  where exposure_event.id=p_failure_event_id and exposure_event.event_type='failure_realized';
  if event_row.id is null then
    raise exception 'failure-realized event required' using errcode='P0002';
  end if;
  select reservation.funding_environment into reservation_environment
  from tongs.openai_text_failure_exposure_holds exposure_hold
  join tongs.funding_reservations reservation on reservation.id=exposure_hold.reservation_id
  where exposure_hold.id=event_row.hold_id;
  if reservation_environment is distinct from p_financial_environment then
    raise exception 'correction financial environment mismatch' using errcode='42501';
  end if;
  select coalesce(max(revision),0)+1 into next_revision
  from tongs.openai_text_failure_realized_loss_corrections
  where failure_event_id=p_failure_event_id;
  insert into tongs.openai_text_failure_realized_loss_corrections(
    id,correction_key,failure_event_id,revision,financial_environment,
    direct_supplier_cost_micros,direct_cost_status,
    attributable_variable_supporting_cost_micros,supporting_cost_status,
    excluded_nonrealized_cost_micros,correction_kind,evidence_json,actor_id
  ) values(
    p_correction_id,btrim(p_correction_key),p_failure_event_id,next_revision,
    p_financial_environment,p_direct_supplier_cost_micros,p_direct_cost_status,
    p_attributable_variable_supporting_cost_micros,p_supporting_cost_status,
    p_excluded_nonrealized_cost_micros,p_correction_kind,p_evidence_json,p_actor_id
  ) returning * into existing;
  return to_jsonb(existing)||jsonb_build_object('replay',false);
end $$;


ALTER FUNCTION "tongs"."record_openai_text_failure_realized_loss_correction"("p_correction_id" "uuid", "p_correction_key" "text", "p_failure_event_id" "uuid", "p_financial_environment" "text", "p_direct_supplier_cost_micros" bigint, "p_direct_cost_status" "text", "p_attributable_variable_supporting_cost_micros" bigint, "p_supporting_cost_status" "text", "p_excluded_nonrealized_cost_micros" bigint, "p_correction_kind" "text", "p_evidence_json" "jsonb", "p_actor_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."record_openai_text_failure_realized_loss_correction"("p_correction_id" "uuid", "p_correction_key" "text", "p_failure_event_id" "uuid", "p_financial_environment" "text", "p_direct_supplier_cost_micros" bigint, "p_direct_cost_status" "text", "p_attributable_variable_supporting_cost_micros" bigint, "p_supporting_cost_status" "text", "p_excluded_nonrealized_cost_micros" bigint, "p_correction_kind" "text", "p_evidence_json" "jsonb", "p_actor_id" "uuid") IS 'Appends a Test/Live-isolated realized-loss revision; later authoritative provider reconciliation replaces the estimate in projection without adding a second loss.';



CREATE OR REPLACE FUNCTION "tongs"."record_openai_text_model_visibility"("p_id" "uuid", "p_source_key" "text", "p_catalog_revision_id" "uuid", "p_catalog_entry_id" "uuid", "p_provider_project_fingerprint" "text", "p_provider_model_id" "text", "p_checked_at" timestamp with time zone, "p_http_status" integer, "p_visible" boolean, "p_returned_model_id" "text" DEFAULT NULL::"text", "p_provider_owner_label" "text" DEFAULT NULL::"text", "p_sanitized_evidence_json" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare existing tongs.openai_text_model_visibility_observations%rowtype; entry tongs.openai_text_model_catalog_entries%rowtype;
begin
 perform tongs._require_pricing_service_role();
 select * into existing from tongs.openai_text_model_visibility_observations where source_key=btrim(p_source_key);
 if found then return to_jsonb(existing)||jsonb_build_object('replay',true); end if;
 select * into entry from tongs.openai_text_model_catalog_entries where id=p_catalog_entry_id and catalog_revision_id=p_catalog_revision_id and provider_model_id=btrim(p_provider_model_id);
 if not found then raise exception 'model catalog binding mismatch' using errcode='P0001'; end if;
 if p_sanitized_evidence_json ?| array['authorization','api_key','secret','token','response_body'] then raise exception 'unsanitized model evidence rejected' using errcode='P0001'; end if;
 insert into tongs.openai_text_model_visibility_observations(id,source_key,catalog_revision_id,catalog_entry_id,provider_project_fingerprint,provider_model_id,checked_at,http_status,visible,returned_model_id,provider_owner_label,sanitized_evidence_json)
 values(p_id,btrim(p_source_key),p_catalog_revision_id,p_catalog_entry_id,lower(p_provider_project_fingerprint),btrim(p_provider_model_id),p_checked_at,p_http_status,p_visible,nullif(btrim(coalesce(p_returned_model_id,'')),''),nullif(btrim(coalesce(p_provider_owner_label,'')),''),coalesce(p_sanitized_evidence_json,'{}'::jsonb)) returning * into existing;
 return to_jsonb(existing)||jsonb_build_object('replay',false);
end $$;


ALTER FUNCTION "tongs"."record_openai_text_model_visibility"("p_id" "uuid", "p_source_key" "text", "p_catalog_revision_id" "uuid", "p_catalog_entry_id" "uuid", "p_provider_project_fingerprint" "text", "p_provider_model_id" "text", "p_checked_at" timestamp with time zone, "p_http_status" integer, "p_visible" boolean, "p_returned_model_id" "text", "p_provider_owner_label" "text", "p_sanitized_evidence_json" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."record_openai_text_model_visibility"("p_id" "uuid", "p_source_key" "text", "p_catalog_revision_id" "uuid", "p_catalog_entry_id" "uuid", "p_provider_project_fingerprint" "text", "p_provider_model_id" "text", "p_checked_at" timestamp with time zone, "p_http_status" integer, "p_visible" boolean, "p_returned_model_id" "text", "p_provider_owner_label" "text", "p_sanitized_evidence_json" "jsonb") IS 'Service-only idempotent persistence for a non-generating model visibility check; rejects secret-bearing evidence fields.';



CREATE OR REPLACE FUNCTION "tongs"."record_openai_text_provider_capture"("p_capture_id" "uuid", "p_reservation_id" "uuid", "p_attempt_number" smallint, "p_capture_key" "text", "p_provider_request_id" "text", "p_input_units" bigint, "p_output_units" bigint, "p_response_evidence_json" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare v_binding tongs.openai_text_funding_bindings%rowtype; v_existing tongs.openai_text_provider_captures%rowtype;
begin
  perform tongs._require_pricing_service_role();
  select * into v_binding from tongs.openai_text_funding_bindings where reservation_id=p_reservation_id;
  if not found or p_attempt_number>v_binding.maximum_attempts or p_input_units>v_binding.maximum_input_units
    or p_output_units>v_binding.maximum_output_units then
    raise exception 'OpenAI provider capture exceeded accepted bound' using errcode='P0001';
  end if;
  select * into v_existing from tongs.openai_text_provider_captures
    where reservation_id=p_reservation_id and attempt_number=p_attempt_number;
  if found then return jsonb_build_object('capture_id',v_existing.id,'replay',true); end if;
  insert into tongs.openai_text_provider_captures(id,reservation_id,attempt_number,capture_key,provider_request_id,input_units,output_units,response_evidence_json)
  values(p_capture_id,p_reservation_id,p_attempt_number,btrim(p_capture_key),nullif(btrim(coalesce(p_provider_request_id,'')),''),p_input_units,p_output_units,coalesce(p_response_evidence_json,'{}'::jsonb));
  return jsonb_build_object('capture_id',p_capture_id,'replay',false);
end $$;


ALTER FUNCTION "tongs"."record_openai_text_provider_capture"("p_capture_id" "uuid", "p_reservation_id" "uuid", "p_attempt_number" smallint, "p_capture_key" "text", "p_provider_request_id" "text", "p_input_units" bigint, "p_output_units" bigint, "p_response_evidence_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."record_openai_text_supplier_attempt_expense"("p_reservation_id" "uuid", "p_attempt_key" "text", "p_attempt_number" smallint, "p_provider_reference" "text", "p_amount_micros" bigint, "p_evidence_status" "text", "p_evidence_json" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare v_binding tongs.openai_text_funding_bindings%rowtype; v_existing tongs.supplier_expenses%rowtype; v_key text;
begin
  perform tongs._require_pricing_service_role();
  select * into v_binding from tongs.openai_text_funding_bindings where reservation_id=p_reservation_id;
  if not found or v_binding.credential_funding<>'forge' or p_attempt_number>v_binding.maximum_attempts then
    raise exception 'Forge-funded OpenAI binding required' using errcode='P0002'; end if;
  if p_evidence_status not in ('estimated','confirmed','unresolved') or (p_evidence_status<>'unresolved' and p_amount_micros is null)
    or p_amount_micros<0 then raise exception 'invalid OpenAI supplier expense' using errcode='22023'; end if;
  v_key:=btrim(p_attempt_key)||':supplier-expense';
  select * into v_existing from tongs.supplier_expenses where expense_key=v_key;
  if found then
    if v_existing.amount_micros is distinct from p_amount_micros or v_existing.evidence_status<>p_evidence_status then
      raise exception 'OpenAI supplier expense replay conflict' using errcode='23505'; end if;
    return jsonb_build_object('supplier_expense_id',v_existing.id,'replay',true);
  end if;
  insert into tongs.supplier_expenses(id,reservation_id,expense_key,provider,component_code,provider_reference,currency,
    amount_micros,evidence_status,obligation_status,evidence_json,incurred_at)
  values(gen_random_uuid(),p_reservation_id,v_key,'openai','openai.text.'||v_binding.route_code,
    nullif(btrim(coalesce(p_provider_reference,'')),''),'USD',p_amount_micros,p_evidence_status,
    case when p_evidence_status='confirmed' then 'closed' when p_evidence_status='unresolved' then 'unresolved' else 'open' end,
    p_evidence_json||jsonb_build_object('attempt_number',p_attempt_number,'attempt_key',btrim(p_attempt_key)),now()) returning * into v_existing;
  return jsonb_build_object('supplier_expense_id',v_existing.id,'replay',false,'evidence_status',v_existing.evidence_status);
end $$;


ALTER FUNCTION "tongs"."record_openai_text_supplier_attempt_expense"("p_reservation_id" "uuid", "p_attempt_key" "text", "p_attempt_number" smallint, "p_provider_reference" "text", "p_amount_micros" bigint, "p_evidence_status" "text", "p_evidence_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."record_openai_text_test_certification_capture"("p_capture_id" "uuid", "p_reservation_id" "uuid", "p_capture_key" "text", "p_provider_request_id" "text", "p_attempt_number" smallint, "p_input_units" bigint, "p_output_units" bigint, "p_response_evidence_json" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
begin perform tongs._require_pricing_service_role();
  return tongs.record_openai_text_test_certification_evidence(p_reservation_id,p_capture_key,'provider_capture',coalesce(p_response_evidence_json,'{}')||jsonb_build_object('capture_id',p_capture_id,'provider_request_id',p_provider_request_id,'attempt_number',p_attempt_number,'input_units',p_input_units,'output_units',p_output_units,'simulated',true)); end $$;


ALTER FUNCTION "tongs"."record_openai_text_test_certification_capture"("p_capture_id" "uuid", "p_reservation_id" "uuid", "p_capture_key" "text", "p_provider_request_id" "text", "p_attempt_number" smallint, "p_input_units" bigint, "p_output_units" bigint, "p_response_evidence_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."record_openai_text_test_certification_evidence"("p_reservation_id" "uuid", "p_evidence_key" "text", "p_evidence_kind" "text", "p_evidence_json" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare v_id uuid;
begin perform tongs._require_pricing_service_role(); select id into v_id from tongs.openai_text_test_certification_evidence where evidence_key=p_evidence_key;
  if v_id is not null then return jsonb_build_object('evidence_id',v_id,'replay',true); end if; v_id:=gen_random_uuid();
  insert into tongs.openai_text_test_certification_evidence values(v_id,p_reservation_id,p_evidence_key,p_evidence_kind,coalesce(p_evidence_json,'{}'),now());
  return jsonb_build_object('evidence_id',v_id,'replay',false); end $$;


ALTER FUNCTION "tongs"."record_openai_text_test_certification_evidence"("p_reservation_id" "uuid", "p_evidence_key" "text", "p_evidence_kind" "text", "p_evidence_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."record_openai_text_test_certification_expense"("p_reservation_id" "uuid", "p_expense_key" "text", "p_component_kind" "text", "p_amount_micros" bigint, "p_evidence_json" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare v_id uuid;
begin perform tongs._require_pricing_service_role(); select id into v_id from tongs.openai_text_test_certification_expenses where expense_key=p_expense_key;
  if v_id is not null then return jsonb_build_object('expense_id',v_id,'replay',true); end if; v_id:=gen_random_uuid();
  insert into tongs.openai_text_test_certification_expenses(id,reservation_id,expense_key,component_kind,amount_micros,evidence_status,evidence_json)
  values(v_id,p_reservation_id,p_expense_key,p_component_kind,p_amount_micros,case when p_amount_micros is null then 'unresolved' else 'synthetic_test' end,coalesce(p_evidence_json,'{}')||jsonb_build_object('live_expense',false));
  return jsonb_build_object('expense_id',v_id,'replay',false); end $$;


ALTER FUNCTION "tongs"."record_openai_text_test_certification_expense"("p_reservation_id" "uuid", "p_expense_key" "text", "p_component_kind" "text", "p_amount_micros" bigint, "p_evidence_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."record_openai_text_usage"("p_evidence_id" "uuid", "p_reservation_id" "uuid", "p_evidence_key" "text", "p_provider_request_id" "text", "p_attempt_number" smallint, "p_input_units" bigint, "p_output_units" bigint, "p_provider_reported" boolean, "p_result_validated" boolean, "p_canonical_persistence_confirmed" boolean, "p_evidence_json" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare v_binding tongs.openai_text_funding_bindings%rowtype; v_existing tongs.openai_text_usage_evidence%rowtype;
begin
  perform tongs._require_pricing_service_role();
  select * into v_binding from tongs.openai_text_funding_bindings where reservation_id=p_reservation_id;
  if not found then raise exception 'OpenAI text funding binding required' using errcode='P0001'; end if;
  if p_attempt_number>v_binding.maximum_attempts or p_input_units>v_binding.maximum_input_units or p_output_units>v_binding.maximum_output_units then
    raise exception 'OpenAI text usage exceeded accepted bound' using errcode='P0001'; end if;
  select * into v_existing from tongs.openai_text_usage_evidence where evidence_key=btrim(p_evidence_key);
  if found then return jsonb_build_object('evidence_id',v_existing.id,'replay',true); end if;
  insert into tongs.openai_text_usage_evidence(id,reservation_id,evidence_key,provider_request_id,attempt_number,input_units,output_units,
    provider_reported,result_validated,canonical_persistence_confirmed,evidence_json)
  values(p_evidence_id,p_reservation_id,btrim(p_evidence_key),nullif(btrim(coalesce(p_provider_request_id,'')),''),p_attempt_number,p_input_units,p_output_units,
    p_provider_reported,p_result_validated,p_canonical_persistence_confirmed,coalesce(p_evidence_json,'{}'::jsonb)) returning * into v_existing;
  return jsonb_build_object('evidence_id',v_existing.id,'replay',false,'usable_result',p_result_validated and p_canonical_persistence_confirmed);
end $$;


ALTER FUNCTION "tongs"."record_openai_text_usage"("p_evidence_id" "uuid", "p_reservation_id" "uuid", "p_evidence_key" "text", "p_provider_request_id" "text", "p_attempt_number" smallint, "p_input_units" bigint, "p_output_units" bigint, "p_provider_reported" boolean, "p_result_validated" boolean, "p_canonical_persistence_confirmed" boolean, "p_evidence_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."record_openai_text_validation_failure_evidence"("p_route_code" "text", "p_operation_id" "text", "p_reservation_id" "uuid", "p_provider_request_id" "text", "p_model" "text", "p_input_units" bigint, "p_output_units" bigint, "p_raw_provider_response_text" "text", "p_validation_error_code" "text", "p_validation_contract_revision" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $_$
declare binding tongs.openai_text_funding_bindings%rowtype; capture tongs.openai_text_provider_captures%rowtype;
  existing tongs.openai_text_validation_failure_evidence%rowtype;
  evidence_id uuid:=extensions.uuid_generate_v5(p_reservation_id,'openai-text-validation-failure-v1');
begin
  perform tongs._require_pricing_service_role();
  perform pg_advisory_xact_lock(hashtextextended('openai-text-validation-failure:'||p_reservation_id::text,0));
  select * into binding from tongs.openai_text_funding_bindings where operation_id=btrim(p_operation_id) and reservation_id=p_reservation_id and route_code=p_route_code;
  select * into capture from tongs.openai_text_provider_captures where reservation_id=p_reservation_id and attempt_number=1;
  if p_route_code not in('hearth.framing_pack_generation','visual.unified_plan','hearth.thumbnail_direction_generation','visual.narrative_interpretation')
    or binding.reservation_id is null or binding.model<>'gpt-5.6-luna' or binding.maximum_attempts<>1 or capture.id is null
    or capture.provider_request_id is distinct from nullif(btrim(coalesce(p_provider_request_id,'')),'')
    or capture.input_units is distinct from p_input_units or capture.output_units is distinct from p_output_units
    or capture.response_evidence_json->>'raw_provider_response_text' is distinct from p_raw_provider_response_text or p_model is distinct from binding.model
    or (p_route_code='hearth.framing_pack_generation' and p_validation_contract_revision is distinct from 'framing_pack_seven_sections.v1')
    or (p_route_code='visual.unified_plan' and p_validation_contract_revision not in('forge.unified-visual-plan-provider.v4','forge.unified-visual-plan-provider.v5'))
    or (p_route_code='hearth.thumbnail_direction_generation' and p_validation_contract_revision is distinct from 'thumbnail_directions_three.v1')
    or (p_route_code='visual.narrative_interpretation' and (p_validation_contract_revision is distinct from 'forge.image-prompt-validator.v2' or octet_length(coalesce(p_raw_provider_response_text,''))>16384))
    or p_validation_error_code!~'^[a-z][a-z0-9_]{2,100}$' or octet_length(coalesce(p_raw_provider_response_text,'')) not between 1 and 65536
  then raise exception 'invalid OpenAI text validation evidence' using errcode='22023'; end if;
  select * into existing from tongs.openai_text_validation_failure_evidence where reservation_id=p_reservation_id or operation_id=btrim(p_operation_id);
  if found then
    if existing.route_code is distinct from p_route_code or existing.provider_capture_id is distinct from capture.id
      or existing.raw_provider_response_text is distinct from p_raw_provider_response_text
      or existing.validation_error_code is distinct from p_validation_error_code
      or existing.validation_contract_revision is distinct from p_validation_contract_revision
    then raise exception 'OpenAI text validation evidence replay conflict' using errcode='23505'; end if;
    return jsonb_build_object('evidence_id',existing.id,'replay',true);
  end if;
  insert into tongs.openai_text_validation_failure_evidence(
    id,route_code,operation_id,reservation_id,provider_capture_id,provider_request_id,model,input_units,output_units,
    raw_provider_response_text,validation_error_code,validation_contract_revision
  ) values(evidence_id,p_route_code,btrim(p_operation_id),p_reservation_id,capture.id,capture.provider_request_id,p_model,
    p_input_units,p_output_units,p_raw_provider_response_text,p_validation_error_code,p_validation_contract_revision);
  return jsonb_build_object('evidence_id',evidence_id,'replay',false);
end $_$;


ALTER FUNCTION "tongs"."record_openai_text_validation_failure_evidence"("p_route_code" "text", "p_operation_id" "text", "p_reservation_id" "uuid", "p_provider_request_id" "text", "p_model" "text", "p_input_units" bigint, "p_output_units" bigint, "p_raw_provider_response_text" "text", "p_validation_error_code" "text", "p_validation_contract_revision" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."record_owner_cost_valuation"("p_valuation_id" "uuid", "p_valuation_key" "text", "p_attempt_id" "uuid", "p_cost_component" "text", "p_prior_valuation_id" "uuid", "p_valuation_basis" "text", "p_amount_micros" bigint, "p_currency" "text", "p_recognition_mode" "text", "p_reconciliation_reference" "text", "p_normalized_usage_evidence" "jsonb", "p_private_valuation_evidence" "jsonb", "p_valued_at" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $_$
declare
  v_key text := btrim(coalesce(p_valuation_key, ''));
  v_component text := lower(btrim(coalesce(p_cost_component, '')));
  v_basis text := lower(btrim(coalesce(p_valuation_basis, '')));
  v_currency text := upper(btrim(coalesce(p_currency, '')));
  v_mode text := lower(btrim(coalesce(p_recognition_mode, '')));
  v_reconciliation text := nullif(btrim(coalesce(p_reconciliation_reference, '')), '');
  v_attempt tongs.owner_cost_provider_attempts%rowtype;
  v_operation tongs.owner_cost_operations%rowtype;
  v_latest tongs.owner_cost_valuations%rowtype;
  v_existing tongs.owner_cost_valuations%rowtype;
  v_previous_recognized bigint := 0;
  v_revision integer := 1;
  v_adjustment bigint;
  v_payload jsonb;
  v_hash text;
  v_created boolean;
begin
  perform tongs._require_accounting_service_role();
  if p_valuation_id is null or length(v_key) not between 8 and 300
     or length(v_component) not between 2 and 100
     or v_basis not in ('estimated', 'usage_calculated', 'provider_reported', 'invoice_reconciled')
     or p_amount_micros < 0 or v_currency !~ '^[A-Z]{3}$'
     or v_mode not in ('evidence_only', 'journal_recognized')
     or p_valued_at is null
     or (v_basis = 'invoice_reconciled') <> (v_reconciliation is not null)
     or jsonb_typeof(coalesce(p_normalized_usage_evidence, '{}'::jsonb)) <> 'object'
     or jsonb_typeof(coalesce(p_private_valuation_evidence, '{}'::jsonb)) <> 'object' then
    raise exception 'invalid owner-cost valuation' using errcode = '22023';
  end if;
  select * into v_attempt from tongs.owner_cost_provider_attempts a where a.attempt_id = p_attempt_id;
  if not found then raise exception 'owner-cost attempt not found' using errcode = '23503'; end if;
  select * into v_operation from tongs.owner_cost_operations o where o.operation_id = v_attempt.operation_id;
  perform pg_advisory_xact_lock(hashtextextended('owner-cost-valuation:' || p_attempt_id::text || ':' || v_component, 0));
  select * into v_existing from tongs.owner_cost_valuations v
    where v.valuation_id = p_valuation_id or v.valuation_key = v_key limit 1;
  v_payload := jsonb_build_object(
    'valuation_id', p_valuation_id, 'valuation_key', v_key, 'attempt_id', p_attempt_id,
    'cost_component', v_component, 'prior_valuation_id', p_prior_valuation_id,
    'valuation_basis', v_basis, 'amount_micros', p_amount_micros, 'currency', v_currency,
    'recognition_mode', v_mode, 'reconciliation_reference', v_reconciliation,
    'normalized_usage_evidence', coalesce(p_normalized_usage_evidence, '{}'::jsonb),
    'private_valuation_evidence', coalesce(p_private_valuation_evidence, '{}'::jsonb),
    'valued_at', p_valued_at
  );
  v_hash := tongs._accounting_payload_hash(v_payload);
  if found then
    if v_existing.valuation_id <> p_valuation_id or v_existing.payload_hash <> v_hash then
      raise exception 'owner-cost valuation replay conflict' using errcode = '23505';
    end if;
    return jsonb_build_object(
      'valuation_id', v_existing.valuation_id, 'journal_event_id', v_existing.journal_event_id,
      'journal_adjustment_micros', v_existing.journal_adjustment_micros, 'replay', true
    );
  end if;
  select * into v_latest from tongs.owner_cost_valuations v
    where v.attempt_id = p_attempt_id and v.cost_component = v_component
    order by v.revision desc limit 1;
  if found then
    v_revision := v_latest.revision + 1;
    if p_prior_valuation_id is distinct from v_latest.valuation_id then
      raise exception 'owner-cost valuation prior revision mismatch' using errcode = '23514';
    end if;
    if (case v_basis when 'estimated' then 1 when 'usage_calculated' then 2 when 'provider_reported' then 3 else 4 end)
       < (case v_latest.valuation_basis when 'estimated' then 1 when 'usage_calculated' then 2 when 'provider_reported' then 3 else 4 end) then
      raise exception 'owner-cost valuation basis cannot regress' using errcode = '23514';
    end if;
    if v_latest.currency <> v_currency then
      raise exception 'owner-cost valuation currency cannot change' using errcode = '23514';
    end if;
  elsif p_prior_valuation_id is not null then
    raise exception 'first owner-cost valuation cannot have a prior revision' using errcode = '23514';
  end if;
  if v_operation.owner_operating_budget_id is not null and not exists (
    select 1 from tongs.owner_operating_budgets b
    where b.id = v_operation.owner_operating_budget_id
      and b.environment = v_operation.runtime_environment and b.currency = v_currency
  ) then raise exception 'owner budget currency classification mismatch' using errcode = '23514'; end if;

  if v_mode = 'journal_recognized' then
    select v.amount_micros into v_previous_recognized
    from tongs.owner_cost_valuations v
    where v.attempt_id = p_attempt_id and v.cost_component = v_component
      and v.recognition_mode = 'journal_recognized'
    order by v.revision desc limit 1;
    v_previous_recognized := coalesce(v_previous_recognized, 0);
    v_adjustment := p_amount_micros - v_previous_recognized;
    v_payload := v_payload || jsonb_build_object(
      'operation_id', v_operation.operation_id, 'revision', v_revision,
      'previous_recognized_amount_micros', v_previous_recognized,
      'journal_adjustment_micros', v_adjustment,
      'authority', 'accounting_journal_events_and_entries'
    );
    v_created := tongs._create_accounting_event(
      p_valuation_id, 'owner-cost-valuation:' || v_key, 'forge_operating_expense_valuation',
      v_operation.financial_environment, 'owner_cost_valuation', p_valuation_id::text,
      v_currency, null, v_operation.workspace_id, null, v_payload, p_valued_at
    );
    if not v_created then raise exception 'owner-cost journal event exists without valuation' using errcode = '23514'; end if;
    insert into tongs.owner_cost_valuations(
      valuation_id, valuation_key, attempt_id, cost_component, revision, prior_valuation_id,
      valuation_basis, amount_micros, currency, recognition_mode, reconciliation_reference,
      normalized_usage_evidence, private_valuation_evidence, payload_hash, journal_event_id,
      journal_adjustment_micros, valued_at
    ) values (
      p_valuation_id, v_key, p_attempt_id, v_component, v_revision, p_prior_valuation_id,
      v_basis, p_amount_micros, v_currency, v_mode, v_reconciliation,
      coalesce(p_normalized_usage_evidence, '{}'::jsonb),
      coalesce(p_private_valuation_evidence, '{}'::jsonb),
      tongs._accounting_payload_hash(v_payload - 'operation_id' - 'revision' - 'previous_recognized_amount_micros' - 'journal_adjustment_micros' - 'authority'),
      p_valuation_id, v_adjustment, p_valued_at
    );
    if v_adjustment <> 0 then
      insert into tongs.accounting_journal_entries(
        event_id, line_number, account_code, workspace_id, owner_budget_id,
        currency, amount_micros, metadata_json
      ) values
        (p_valuation_id, 1,
          case when v_operation.financial_environment = 'live' then 'forge_operating_expense' else 'test_forge_operating_expense' end,
          v_operation.workspace_id, v_operation.owner_operating_budget_id, v_currency, v_adjustment,
          jsonb_build_object('valuation_id', p_valuation_id, 'operation_id', v_operation.operation_id)),
        (p_valuation_id, 2,
          case when v_operation.financial_environment = 'live' then 'forge_cash_clearing' else 'test_cash_clearing' end,
          v_operation.workspace_id, v_operation.owner_operating_budget_id, v_currency, -v_adjustment,
          jsonb_build_object('valuation_id', p_valuation_id, 'operation_id', v_operation.operation_id));
    end if;
    perform tongs._assert_accounting_event_balanced(p_valuation_id);
  else
    insert into tongs.owner_cost_valuations(
      valuation_id, valuation_key, attempt_id, cost_component, revision, prior_valuation_id,
      valuation_basis, amount_micros, currency, recognition_mode, reconciliation_reference,
      normalized_usage_evidence, private_valuation_evidence, payload_hash, valued_at
    ) values (
      p_valuation_id, v_key, p_attempt_id, v_component, v_revision, p_prior_valuation_id,
      v_basis, p_amount_micros, v_currency, v_mode, v_reconciliation,
      coalesce(p_normalized_usage_evidence, '{}'::jsonb),
      coalesce(p_private_valuation_evidence, '{}'::jsonb), v_hash, p_valued_at
    );
  end if;
  return jsonb_build_object(
    'valuation_id', p_valuation_id,
    'journal_event_id', case when v_mode = 'journal_recognized' then p_valuation_id else null end,
    'journal_adjustment_micros', v_adjustment, 'replay', false
  );
end;
$_$;


ALTER FUNCTION "tongs"."record_owner_cost_valuation"("p_valuation_id" "uuid", "p_valuation_key" "text", "p_attempt_id" "uuid", "p_cost_component" "text", "p_prior_valuation_id" "uuid", "p_valuation_basis" "text", "p_amount_micros" bigint, "p_currency" "text", "p_recognition_mode" "text", "p_reconciliation_reference" "text", "p_normalized_usage_evidence" "jsonb", "p_private_valuation_evidence" "jsonb", "p_valued_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."record_owner_hearth_compatibility_result"("p_reservation_id" "uuid", "p_result_key" "text", "p_status" "text", "p_provider_request_id" "text", "p_estimated_supplier_expense_micros" bigint, "p_authoritative_supplier_expense_micros" bigint, "p_evidence_json" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare op tongs.owner_hearth_operation_authorizations%rowtype; authz tongs.owner_hearth_authorizations%rowtype; existing tongs.owner_hearth_compatibility_results%rowtype;
begin
 perform tongs._require_pricing_service_role();
 select * into op from tongs.owner_hearth_operation_authorizations where reservation_id=p_reservation_id;
 select * into authz from tongs.owner_hearth_authorizations where id=op.authorization_id;
 if op.id is null or authz.authorization_kind<>'compatibility_batch' or p_status not in ('passed','definitive_rejection','billed_failure','ambiguous') then
  raise exception 'compatibility operation required' using errcode='42501'; end if;
 if p_status='passed' and (tongs._funding_reservation_state(p_reservation_id)<>'settled'
   or not exists(select 1 from tongs.openai_text_persisted_results where reservation_id=p_reservation_id and result_json->>'assistantText'='Ready.')) then
  raise exception 'validated persisted exact Ready result required' using errcode='P0001'; end if;
 select * into existing from tongs.owner_hearth_compatibility_results where operation_authorization_id=op.id;
 if found then return to_jsonb(existing)||jsonb_build_object('replay',true); end if;
 insert into tongs.owner_hearth_compatibility_results(id,operation_authorization_id,result_key,status,provider_request_id,
  estimated_supplier_expense_micros,authoritative_supplier_expense_micros,evidence_json)
 values(gen_random_uuid(),op.id,btrim(p_result_key),p_status,nullif(btrim(coalesce(p_provider_request_id,'')),''),
  p_estimated_supplier_expense_micros,p_authoritative_supplier_expense_micros,coalesce(p_evidence_json,'{}'::jsonb)) returning * into existing;
 if p_status='ambiguous' then
  insert into tongs.owner_hearth_authorization_events(id,authorization_id,sequence,event_key,state,started_at,expires_at,reason,evidence_json)
  select gen_random_uuid(),authz.id,coalesce(max(sequence),0)+1,'owner-hearth-compat:'||authz.id::text||':ambiguous-halt','halt_new',null,null,
   'Ambiguous provider submission halted compatibility activation.',jsonb_build_object('reservation_id',p_reservation_id)
  from tongs.owner_hearth_authorization_events where authorization_id=authz.id;
 end if;
 return to_jsonb(existing)||jsonb_build_object('replay',false);
end $$;


ALTER FUNCTION "tongs"."record_owner_hearth_compatibility_result"("p_reservation_id" "uuid", "p_result_key" "text", "p_status" "text", "p_provider_request_id" "text", "p_estimated_supplier_expense_micros" bigint, "p_authoritative_supplier_expense_micros" bigint, "p_evidence_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."record_owner_hearth_research_review"("p_result_package_id" "uuid", "p_event_key" "text", "p_review_state" "text", "p_note" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare pkg tongs.owner_hearth_research_result_packages%rowtype;
 existing tongs.owner_hearth_research_review_events%rowtype; seq int; actor uuid:=auth.uid();
begin
 if actor is null or p_review_state not in('accepted','changes_requested','rejected') then
  raise exception 'authenticated research review required' using errcode='42501'; end if;
 select * into pkg from tongs.owner_hearth_research_result_packages where id=p_result_package_id;
 if pkg.id is null or pkg.owner_user_id<>actor or not exists(
  select 1 from tongs.workspace_members m where m.workspace_id=pkg.workspace_id and m.user_id=actor) then
  raise exception 'research package review denied' using errcode='42501'; end if;
 select * into existing from tongs.owner_hearth_research_review_events where event_key=btrim(p_event_key);
 if found then
  if existing.result_package_id<>pkg.id or existing.reviewer_id<>actor then
   raise exception 'research review replay binding mismatch' using errcode='42501'; end if;
  return to_jsonb(existing)||jsonb_build_object('replay',true);
 end if;
 select coalesce(max(sequence),0)+1 into seq from tongs.owner_hearth_research_review_events where result_package_id=pkg.id;
 insert into tongs.owner_hearth_research_review_events values(
  gen_random_uuid(),pkg.id,seq,btrim(p_event_key),p_review_state,actor,nullif(btrim(coalesce(p_note,'')),''),now()) returning * into existing;
 return to_jsonb(existing)||jsonb_build_object('replay',false);
end $$;


ALTER FUNCTION "tongs"."record_owner_hearth_research_review"("p_result_package_id" "uuid", "p_event_key" "text", "p_review_state" "text", "p_note" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."record_owner_hearth_tail_measurement"("p_tail_authorization_id" "uuid", "p_period_start" "date", "p_canonical_retained_bytes" bigint, "p_evidence_retained_bytes" bigint, "p_cost_status" "text", "p_measurement_key" "text", "p_evidence_json" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare tail tongs.owner_hearth_tail_authorizations%rowtype; existing tongs.owner_hearth_tail_measurements%rowtype;
 revision_number integer; amount bigint; authorized_total bigint; seq integer; overrun boolean;
begin
 perform tongs._require_pricing_service_role();
 select * into existing from tongs.owner_hearth_tail_measurements where measurement_key=btrim(p_measurement_key);
 if found then return to_jsonb(existing)||jsonb_build_object('replay',true); end if;
 select * into tail from tongs.owner_hearth_tail_authorizations where id=p_tail_authorization_id for update;
 if not found or p_cost_status not in ('measured_estimate','authoritative') or p_canonical_retained_bytes<0 or p_evidence_retained_bytes<0
   or p_canonical_retained_bytes>tail.canonical_capacity_bytes or p_evidence_retained_bytes>tail.evidence_capacity_bytes then
  raise exception 'tail measurement exceeds authorized class capacity' using errcode='22023'; end if;
 amount:=ceil(((p_canonical_retained_bytes+p_evidence_retained_bytes)::numeric*tail.replacement_rate_micros_per_mib_month)/1048576)::bigint;
 select coalesce(max(revision),0)+1 into revision_number from tongs.owner_hearth_tail_measurements
 where tail_authorization_id=tail.id and period_start=p_period_start;
 select coalesce(sum(latest.estimated_cost_micros),0) into authorized_total from (
  select distinct on (m.period_start) m.period_start,m.estimated_cost_micros from tongs.owner_hearth_tail_measurements m
  where m.tail_authorization_id=tail.id order by m.period_start,m.revision desc
 ) latest;
 overrun:=amount>tail.monthly_limit_micros or authorized_total+amount>tail.aggregate_limit_micros;
 insert into tongs.owner_hearth_tail_measurements(id,tail_authorization_id,period_start,revision,canonical_retained_bytes,
  evidence_retained_bytes,estimated_cost_micros,cost_status,measurement_key,evidence_json)
 values(gen_random_uuid(),tail.id,p_period_start,revision_number,p_canonical_retained_bytes,p_evidence_retained_bytes,amount,p_cost_status,
  btrim(p_measurement_key),coalesce(p_evidence_json,'{}'::jsonb)||jsonb_build_object('replacement_cost_basis',true,'incremental_invoice_claimed',false))
 returning * into existing;
 if overrun then
  select coalesce(max(sequence),0)+1 into seq from tongs.owner_hearth_tail_events where tail_authorization_id=tail.id;
  insert into tongs.owner_hearth_tail_events(id,tail_authorization_id,sequence,event_key,event_type,amount_micros,retained_bytes,evidence_json)
  values(gen_random_uuid(),tail.id,seq,'owner-hearth-tail:'||tail.id::text||':overrun:'||btrim(p_measurement_key),'continuing_obligation',amount,
   p_canonical_retained_bytes+p_evidence_retained_bytes,jsonb_build_object('coverage_incomplete',true,'halt_new_required',true,
    'monthly_limit_micros',tail.monthly_limit_micros,'aggregate_limit_micros',tail.aggregate_limit_micros));
 end if;
 return to_jsonb(existing)||jsonb_build_object('replay',false,'coverage_incomplete',overrun);
end $$;


ALTER FUNCTION "tongs"."record_owner_hearth_tail_measurement"("p_tail_authorization_id" "uuid", "p_period_start" "date", "p_canonical_retained_bytes" bigint, "p_evidence_retained_bytes" bigint, "p_cost_status" "text", "p_measurement_key" "text", "p_evidence_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."record_owner_hearth_thumbnail_base_generation_result"("p_owner_cost_attempt_id" "uuid", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_operation_fingerprint" "text", "p_financial_environment" "text", "p_runtime_environment" "text", "p_provider_body_sha256" "text", "p_prompt_package_hash" "text", "p_render_recipe_id" "uuid", "p_render_recipe_revision" integer, "p_concept_revision_id" "uuid", "p_provider_request_id" "text", "p_provider_response_id" "text", "p_staged_asset_id" "uuid", "p_canonical_receipt_json" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $_$
declare
  v_authority jsonb;
  v_operation_key text;
  v_asset tongs.assets%rowtype;
  v_existing tongs.hearth_thumbnail_base_generation_results%rowtype;
  v_result_id uuid:=extensions.uuid_generate_v5(
    '19630000-0000-4000-8000-000000000012'::uuid,p_owner_cost_attempt_id::text);
begin
  perform tongs._require_accounting_service_role();
  v_authority:=tongs._assert_owner_hearth_image_result_authority(
    p_owner_cost_attempt_id,'hearth.thumbnail_base_generation',p_user_id,
    p_workspace_id,p_workpiece_id,p_operation_fingerprint,p_financial_environment,
    p_runtime_environment,p_provider_request_id,'gpt-image-2-2026-04-21',
    'image_generation','gpt-image-2-2026-04-21:1536x1024:high:n1'
  );
  v_operation_key:=v_authority->>'operation_key';
  if lower(coalesce(p_provider_body_sha256,''))!~'^[0-9a-f]{64}$'
     or lower(coalesce(p_prompt_package_hash,''))!~'^[0-9a-f]{64}$'
     or p_render_recipe_id is null or p_render_recipe_revision<=0
     or p_concept_revision_id is null or p_staged_asset_id is null
     or jsonb_typeof(coalesce(p_canonical_receipt_json,'null'::jsonb))<>'object' then
    raise exception 'invalid owner Thumbnail Base result evidence' using errcode='22023';
  end if;
  select * into v_asset from tongs.assets where id=p_staged_asset_id;
  if v_asset.id is null or v_asset.workspace_id<>p_workspace_id
     or v_asset.workpiece_id<>p_workpiece_id or v_asset.request_id<>v_operation_key
     or v_asset.asset_kind<>'thumbnail_image'
     or v_asset.provider<>'openai' or v_asset.provider_request_id is distinct from btrim(p_provider_request_id)
     or v_asset.mime_type<>'image/png' or v_asset.status<>'ready'
     or v_asset.content_hash!~'^[0-9a-f]{64}$'
     or p_canonical_receipt_json->>'asset_id' is distinct from v_asset.id::text
     or p_canonical_receipt_json->>'asset_path' is distinct from v_asset.path
     or p_canonical_receipt_json->>'asset_content_hash' is distinct from v_asset.content_hash
     or p_canonical_receipt_json->>'provider_body_sha256' is distinct from lower(p_provider_body_sha256)
     or p_canonical_receipt_json->>'prompt_package_hash' is distinct from lower(p_prompt_package_hash) then
    raise exception 'owner Thumbnail Base result conflicts with canonical asset authority' using errcode='42501';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    'owner-thumbnail-base-result:'||p_owner_cost_attempt_id::text,0));
  select * into v_existing from tongs.hearth_thumbnail_base_generation_results
    where owner_cost_attempt_id=p_owner_cost_attempt_id or operation_id=v_operation_key;
  if found then
    if v_existing.owner_cost_attempt_id is distinct from p_owner_cost_attempt_id
       or v_existing.operation_id<>v_operation_key
       or v_existing.request_fingerprint<>lower(p_operation_fingerprint)
       or v_existing.provider_body_sha256<>lower(p_provider_body_sha256)
       or v_existing.prompt_package_hash<>lower(p_prompt_package_hash)
       or v_existing.render_recipe_id<>p_render_recipe_id
       or v_existing.render_recipe_revision<>p_render_recipe_revision
       or v_existing.concept_revision_id<>p_concept_revision_id
       or v_existing.provider_request_id is distinct from btrim(p_provider_request_id)
       or v_existing.provider_response_id is distinct from nullif(btrim(coalesce(p_provider_response_id,'')),'')
       or v_existing.staged_asset_id<>p_staged_asset_id
       or v_existing.canonical_receipt_json<>p_canonical_receipt_json then
      raise exception 'owner Thumbnail Base result replay conflict' using errcode='23505';
    end if;
    return to_jsonb(v_existing)||jsonb_build_object('replay',true,'authority','owner_cost_provider_attempt');
  end if;

  insert into tongs.hearth_thumbnail_base_generation_results(
    id,operation_id,reservation_id,owner_cost_attempt_id,user_id,workspace_id,workpiece_id,
    request_fingerprint,provider_body_sha256,prompt_package_hash,render_recipe_id,
    render_recipe_revision,concept_revision_id,provider_request_id,provider_response_id,
    generated_content_hash,staged_asset_id,staged_asset_path,canonical_receipt_json,state,completed_at
  ) values(
    v_result_id,v_operation_key,null,p_owner_cost_attempt_id,p_user_id,p_workspace_id,p_workpiece_id,
    lower(p_operation_fingerprint),lower(p_provider_body_sha256),lower(p_prompt_package_hash),
    p_render_recipe_id,p_render_recipe_revision,p_concept_revision_id,btrim(p_provider_request_id),
    nullif(btrim(coalesce(p_provider_response_id,'')),''),v_asset.content_hash,v_asset.id,v_asset.path,
    p_canonical_receipt_json,'asset_staged',transaction_timestamp()
  ) returning * into v_existing;
  return to_jsonb(v_existing)||jsonb_build_object('replay',false,'authority','owner_cost_provider_attempt');
end $_$;


ALTER FUNCTION "tongs"."record_owner_hearth_thumbnail_base_generation_result"("p_owner_cost_attempt_id" "uuid", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_operation_fingerprint" "text", "p_financial_environment" "text", "p_runtime_environment" "text", "p_provider_body_sha256" "text", "p_prompt_package_hash" "text", "p_render_recipe_id" "uuid", "p_render_recipe_revision" integer, "p_concept_revision_id" "uuid", "p_provider_request_id" "text", "p_provider_response_id" "text", "p_staged_asset_id" "uuid", "p_canonical_receipt_json" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."record_owner_hearth_thumbnail_base_generation_result"("p_owner_cost_attempt_id" "uuid", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_operation_fingerprint" "text", "p_financial_environment" "text", "p_runtime_environment" "text", "p_provider_body_sha256" "text", "p_prompt_package_hash" "text", "p_render_recipe_id" "uuid", "p_render_recipe_revision" integer, "p_concept_revision_id" "uuid", "p_provider_request_id" "text", "p_provider_response_id" "text", "p_staged_asset_id" "uuid", "p_canonical_receipt_json" "jsonb") IS 'Private service-only owner Thumbnail Base persistence; reads no customer-finance authority.';



CREATE OR REPLACE FUNCTION "tongs"."record_owner_operating_budget_reconciliation_adjustment"("p_id" "uuid", "p_reservation_id" "uuid", "p_supplier_expense_id" "uuid", "p_batch_id" "uuid", "p_allocation_id" "uuid", "p_source_key" "text", "p_confirmed_effective_amount_micros" bigint, "p_evidence_json" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  reservation tongs.funding_reservations%rowtype;
  consumption tongs.owner_operating_budget_consumptions%rowtype;
  owner_budget tongs.owner_operating_budgets%rowtype;
  supplier_adjustment tongs.openai_supplier_expense_reconciliation_adjustments%rowtype;
  existing tongs.owner_operating_budget_reconciliation_adjustments%rowtype;
  prior_effective bigint;
  delta bigint;
  payload jsonb;
  created boolean;
begin
  perform tongs._require_pricing_service_role();
  if p_id is null or p_confirmed_effective_amount_micros<0
     or length(btrim(coalesce(p_source_key,''))) not between 8 and 240
     or jsonb_typeof(coalesce(p_evidence_json,'null'::jsonb))<>'object' then
    raise exception 'invalid owner budget reconciliation adjustment' using errcode='22023';
  end if;
  select * into reservation from tongs.funding_reservations where id=p_reservation_id;
  if reservation.id is null then raise exception 'funding reservation not found' using errcode='P0002'; end if;
  if reservation.funding_source_type<>'owner_budget' then
    return jsonb_build_object('applied',false,'reason','not_owner_budget','replay',false);
  end if;
  select * into consumption from tongs.owner_operating_budget_consumptions
    where reservation_id=p_reservation_id;
  if consumption.id is null then
    raise exception 'owner budget consumption required before supplier reconciliation' using errcode='P0001';
  end if;
  select * into owner_budget from tongs.owner_operating_budgets where id=consumption.budget_id;
  if owner_budget.id is null then raise exception 'owner operating budget not found' using errcode='P0002'; end if;
  perform pg_advisory_xact_lock(hashtextextended('owner-budget-reconciliation:'||consumption.id::text,0));
  select * into existing from tongs.owner_operating_budget_reconciliation_adjustments
    where source_key=btrim(p_source_key) or (consumption_id=consumption.id and reconciliation_batch_id=p_batch_id)
    order by created_at limit 1;
  if found then
    if existing.id<>p_id or existing.supplier_expense_id<>p_supplier_expense_id
       or existing.operation_allocation_id<>p_allocation_id
       or existing.confirmed_effective_amount_micros<>p_confirmed_effective_amount_micros then
      raise exception 'owner budget reconciliation replay conflict' using errcode='23505';
    end if;
    return to_jsonb(existing)||jsonb_build_object('applied',true,'replay',true);
  end if;
  select * into supplier_adjustment from tongs.openai_supplier_expense_reconciliation_adjustments
    where supplier_expense_id=p_supplier_expense_id and reconciliation_batch_id=p_batch_id
      and operation_allocation_id=p_allocation_id;
  if supplier_adjustment.id is null
     or not exists(select 1 from tongs.openai_supplier_expense_obligation_settlement_events event
       where event.supplier_expense_id=p_supplier_expense_id and event.reconciliation_batch_id=p_batch_id
         and event.operation_allocation_id=p_allocation_id)
     or tongs._openai_reconciliation_batch_state(p_batch_id)<>'accepted' then
    raise exception 'closed accepted supplier reconciliation required' using errcode='P0001';
  end if;
  prior_effective:=tongs._owner_operating_budget_effective_consumption(consumption.id);
  delta:=p_confirmed_effective_amount_micros-prior_effective;
  if delta=0 then
    return jsonb_build_object('applied',false,'reason','already_effective','replay',true,
      'consumption_id',consumption.id,'effective_amount_micros',prior_effective);
  end if;
  payload:=jsonb_build_object(
    'adjustment_id',p_id,'consumption_id',consumption.id,'reservation_id',p_reservation_id,
    'supplier_expense_id',p_supplier_expense_id,'reconciliation_batch_id',p_batch_id,
    'operation_allocation_id',p_allocation_id,'prior_effective_amount_micros',prior_effective,
    'confirmed_effective_amount_micros',p_confirmed_effective_amount_micros,
    'adjustment_micros',delta,'customer_charge_micros',0,
    'evidence',coalesce(p_evidence_json,'{}'::jsonb));
  created:=tongs._create_accounting_event(
    p_id,'owner-budget-reconciliation:'||btrim(p_source_key),
    'owner_operating_budget_reconciled','owner_internal','owner_budget_reconciliation',
    p_id::text,consumption.currency,null,owner_budget.workspace_id,null,payload,now());
  if not created then raise exception 'owner budget reconciliation journal exists without adjustment' using errcode='23514'; end if;
  insert into tongs.owner_operating_budget_reconciliation_adjustments(
    id,consumption_id,supplier_expense_id,reconciliation_batch_id,operation_allocation_id,
    source_key,prior_effective_amount_micros,confirmed_effective_amount_micros,
    adjustment_micros,currency,journal_event_id,evidence_json
  ) values(
    p_id,consumption.id,p_supplier_expense_id,p_batch_id,p_allocation_id,btrim(p_source_key),
    prior_effective,p_confirmed_effective_amount_micros,delta,consumption.currency,p_id,
    coalesce(p_evidence_json,'{}'::jsonb));
  insert into tongs.accounting_journal_entries(
    event_id,line_number,account_code,workspace_id,owner_budget_id,currency,amount_micros,metadata_json
  ) values
    (p_id,1,'owner_research_qa_expense',owner_budget.workspace_id,consumption.budget_id,
      consumption.currency,delta,jsonb_build_object('reconciliation_adjustment_id',p_id)),
    (p_id,2,'forge_cash_clearing',owner_budget.workspace_id,consumption.budget_id,
      consumption.currency,-delta,jsonb_build_object('reconciliation_adjustment_id',p_id));
  perform tongs._assert_accounting_event_balanced(p_id);
  return jsonb_build_object('applied',true,'replay',false,'adjustment_id',p_id,
    'consumption_id',consumption.id,'prior_effective_amount_micros',prior_effective,
    'confirmed_effective_amount_micros',p_confirmed_effective_amount_micros,
    'adjustment_micros',delta,'journal_event_id',p_id);
end $$;


ALTER FUNCTION "tongs"."record_owner_operating_budget_reconciliation_adjustment"("p_id" "uuid", "p_reservation_id" "uuid", "p_supplier_expense_id" "uuid", "p_batch_id" "uuid", "p_allocation_id" "uuid", "p_source_key" "text", "p_confirmed_effective_amount_micros" bigint, "p_evidence_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."record_paid_media_definitive_rejection"("p_paid_media_operation_id" "uuid", "p_operation_fingerprint" "text", "p_attempt_id" "uuid", "p_failure_code" "text", "p_failure_message" "text", "p_evidence_json" "jsonb", "p_release_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare v_op tongs.paid_media_operations%rowtype; v_attempt tongs.paid_media_provider_attempts%rowtype; v_release jsonb;
begin
  select * into v_op from tongs.paid_media_operations where id=p_paid_media_operation_id for update;
  if not found or v_op.operation_fingerprint<>p_operation_fingerprint then raise exception 'paid operation not found or mismatched' using errcode='P0002'; end if;
  select * into v_attempt from tongs.paid_media_provider_attempts where id=p_attempt_id and paid_media_operation_id=v_op.id for update;
  if not found then raise exception 'provider attempt not found' using errcode='P0002'; end if;
  if v_attempt.state='rejected' then return jsonb_build_object('operation',to_jsonb(v_op),'attempt',to_jsonb(v_attempt),'replay',true); end if;
  update tongs.paid_media_provider_attempts set state='rejected',transmitted=true,transport_evidence_json=coalesce(p_evidence_json,'{}'),completed_at=now() where id=v_attempt.id returning * into v_attempt;
  v_release:=tongs.release_ai_credit_reservation(v_op.user_id,v_op.reservation_id,p_release_id,'provider_not_submitted',p_evidence_json);
  update tongs.paid_media_operations set state='provider_failed',failure_code=p_failure_code,failure_message=p_failure_message,updated_at=now() where id=v_op.id returning * into v_op;
  insert into tongs.paid_media_operation_events values(gen_random_uuid(),v_op.id,v_op.user_id,'provider_rejected_before_task',4,coalesce(p_evidence_json,'{}'),v_op.actor_id,now());
  return jsonb_build_object('operation',to_jsonb(v_op),'attempt',to_jsonb(v_attempt),'release',v_release,'replay',false);
end $$;


ALTER FUNCTION "tongs"."record_paid_media_definitive_rejection"("p_paid_media_operation_id" "uuid", "p_operation_fingerprint" "text", "p_attempt_id" "uuid", "p_failure_code" "text", "p_failure_message" "text", "p_evidence_json" "jsonb", "p_release_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."record_paid_media_provider_reconciliation"("p_paid_media_operation_id" "uuid", "p_operation_fingerprint" "text", "p_attempt_id" "uuid", "p_provider_request_id" "text", "p_provider_response_id" "text", "p_provider_response_json" "jsonb", "p_failure_code" "text", "p_failure_message" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare v_op tongs.paid_media_operations%rowtype; v_attempt tongs.paid_media_provider_attempts%rowtype;
begin
  select * into v_op from tongs.paid_media_operations where id=p_paid_media_operation_id for update;
  if not found or v_op.operation_fingerprint<>p_operation_fingerprint then raise exception 'paid operation not found or mismatched' using errcode='P0002'; end if;
  select * into v_attempt from tongs.paid_media_provider_attempts where id=p_attempt_id and paid_media_operation_id=v_op.id for update;
  if not found then raise exception 'provider attempt not found' using errcode='P0002'; end if;
  if v_attempt.state='evidence_recorded' then return jsonb_build_object('operation',to_jsonb(v_op),'attempt',to_jsonb(v_attempt),'replay',true); end if;
  if v_attempt.state<>'submitting' or jsonb_typeof(p_provider_response_json)<>'object' then raise exception 'provider attempt cannot enter reconciliation' using errcode='P0001'; end if;
  update tongs.paid_media_provider_attempts set state='evidence_recorded',transmitted=true,provider_request_id=p_provider_request_id,
    provider_response_id=p_provider_response_id,provider_response_json=p_provider_response_json,completed_at=now()
    where id=v_attempt.id returning * into v_attempt;
  update tongs.paid_media_operations set state='provider_completed',failure_code=p_failure_code,failure_message=p_failure_message,
    reconciliation_required=true,updated_at=now() where id=v_op.id returning * into v_op;
  insert into tongs.paid_media_operation_events values(gen_random_uuid(),v_op.id,v_op.user_id,'provider_usage_reconciliation_required',
    (select coalesce(max(event_ordinal),0)+1 from tongs.paid_media_operation_events where paid_media_operation_id=v_op.id),
    jsonb_build_object('attempt_id',v_attempt.id,'provider_request_id',p_provider_request_id,'provider_response_id',p_provider_response_id),v_op.actor_id,now());
  return jsonb_build_object('operation',to_jsonb(v_op),'attempt',to_jsonb(v_attempt),'replay',false);
end $$;


ALTER FUNCTION "tongs"."record_paid_media_provider_reconciliation"("p_paid_media_operation_id" "uuid", "p_operation_fingerprint" "text", "p_attempt_id" "uuid", "p_provider_request_id" "text", "p_provider_response_id" "text", "p_provider_response_json" "jsonb", "p_failure_code" "text", "p_failure_message" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."record_paid_media_provider_result"("p_paid_media_operation_id" "uuid", "p_operation_fingerprint" "text", "p_attempt_id" "uuid", "p_provider_request_id" "text", "p_provider_response_id" "text", "p_provider_response_json" "jsonb", "p_usage_components" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_op tongs.paid_media_operations%rowtype;
  v_attempt tongs.paid_media_provider_attempts%rowtype;
  v_component jsonb;
  v_rate record;
  v_contract text;
begin
  select * into v_op from tongs.paid_media_operations where id=p_paid_media_operation_id for update;
  if not found or v_op.operation_fingerprint<>p_operation_fingerprint then
    raise exception 'paid operation not found or mismatched' using errcode='P0002';
  end if;

  select * into v_attempt from tongs.paid_media_provider_attempts where id=p_attempt_id and paid_media_operation_id=v_op.id for update;
  if not found then
    raise exception 'provider attempt not found' using errcode='P0002';
  end if;
  if v_attempt.state='completed' then
    return jsonb_build_object('operation', to_jsonb(v_op), 'attempt', to_jsonb(v_attempt), 'replay', true);
  end if;
  if v_attempt.state not in ('submitting','evidence_recorded') then
    raise exception 'provider attempt is not recoverable' using errcode='P0001';
  end if;
  if jsonb_typeof(p_provider_response_json)<>'object' or not tongs._valid_paid_media_usage_components(p_usage_components) then
    raise exception 'invalid provider result evidence' using errcode='22023';
  end if;

  update tongs.paid_media_provider_attempts
  set state='completed', transmitted=true, provider_request_id=p_provider_request_id,
      provider_response_id=p_provider_response_id, provider_response_json=p_provider_response_json, completed_at=now()
  where id=v_attempt.id returning * into v_attempt;

  for v_component in select value from jsonb_array_elements(p_usage_components) loop
    select c.* into v_rate
    from tongs.ai_pricing_rate_components c
    where c.pricing_policy_revision_id=v_op.pricing_policy_revision_id
      and c.component_kind=v_component->>'component_kind';
    if not found or coalesce((v_component->>'quantity')::bigint,-1)<0 then
      raise exception 'invalid actual usage component' using errcode='22023';
    end if;

    insert into tongs.paid_media_actual_usage_components(
      provider_attempt_id, component_kind, quantity, rate_numerator, rate_denominator,
      expense_numerator, expense_denominator, evidence_json
    )
    values(
      v_attempt.id,
      v_rate.component_kind,
      (v_component->>'quantity')::bigint,
      v_rate.rate_numerator,
      v_rate.rate_denominator,
      (v_component->>'quantity')::numeric * v_rate.rate_numerator,
      v_rate.rate_denominator,
      v_component
    );
  end loop;

  if not exists(select 1 from tongs.paid_media_actual_usage_components where provider_attempt_id=v_attempt.id) then
    raise exception 'provider result is missing authoritative usage' using errcode='22023';
  end if;

  if tongs._paid_media_usage_contract_is_video(p_usage_components) then
    v_contract := 'forge.paid-media.usage.video.v1';
  elsif tongs._paid_media_usage_contract_is_image(p_usage_components) then
    v_contract := 'forge.paid-media.usage.image.v1';
  else
    raise exception 'provider result is missing authoritative usage' using errcode='22023';
  end if;

  update tongs.paid_media_operations
  set state=case when state='delivered' then 'delivered' else 'provider_completed' end,
      failure_code=null,
      failure_message=null,
      reconciliation_required=false,
      updated_at=now()
  where id=v_op.id returning * into v_op;

  insert into tongs.paid_media_operation_events
  values(
    gen_random_uuid(),
    v_op.id,
    v_op.user_id,
    'provider_usage_reconciled',
    (select coalesce(max(event_ordinal), 0)+1 from tongs.paid_media_operation_events where paid_media_operation_id=v_op.id),
    jsonb_build_object(
      'attempt_id', v_attempt.id,
      'provider_request_id', p_provider_request_id,
      'provider_response_id', p_provider_response_id,
      'usage_contract', v_contract
    ),
    v_op.actor_id,
    now()
  );

  return jsonb_build_object('operation', to_jsonb(v_op), 'attempt', to_jsonb(v_attempt), 'replay', false);
end $$;


ALTER FUNCTION "tongs"."record_paid_media_provider_result"("p_paid_media_operation_id" "uuid", "p_operation_fingerprint" "text", "p_attempt_id" "uuid", "p_provider_request_id" "text", "p_provider_response_id" "text", "p_provider_response_json" "jsonb", "p_usage_components" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."record_paid_media_terminal_failure"("p_paid_media_operation_id" "uuid", "p_operation_fingerprint" "text", "p_attempt_id" "uuid", "p_failure_kind" "text", "p_failure_code" "text", "p_failure_message" "text", "p_evidence_json" "jsonb", "p_usage_components" "jsonb", "p_release_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare v_op tongs.paid_media_operations%rowtype; v_attempt tongs.paid_media_provider_attempts%rowtype; v_release jsonb; v_component jsonb; v_rate record;
begin
  select * into v_op from tongs.paid_media_operations where id=p_paid_media_operation_id for update;
  if not found or v_op.operation_fingerprint<>p_operation_fingerprint then raise exception 'paid operation not found or mismatched' using errcode='P0002'; end if;
  if p_failure_kind not in ('provider_billable_failure','delivery_failure') then raise exception 'unsupported paid media terminal failure' using errcode='22023'; end if;
  if v_op.state in ('provider_failed','delivery_failed') then return jsonb_build_object('operation',to_jsonb(v_op),'replay',true); end if;
  select * into v_attempt from tongs.paid_media_provider_attempts where id=p_attempt_id and paid_media_operation_id=v_op.id for update;
  if not found then raise exception 'provider attempt not found' using errcode='P0002'; end if;
  if jsonb_typeof(coalesce(p_usage_components,'[]'))<>'array' then raise exception 'invalid provider failure usage evidence' using errcode='22023'; end if;
  for v_component in select value from jsonb_array_elements(coalesce(p_usage_components,'[]')) loop
    select c.* into v_rate from tongs.ai_pricing_rate_components c where c.pricing_policy_revision_id=v_op.pricing_policy_revision_id and c.component_kind=v_component->>'component_kind';
    if not found or coalesce((v_component->>'quantity')::bigint,-1)<0 then raise exception 'invalid provider failure usage component' using errcode='22023'; end if;
    insert into tongs.paid_media_actual_usage_components(provider_attempt_id,component_kind,quantity,rate_numerator,rate_denominator,expense_numerator,expense_denominator,evidence_json)
    values(v_attempt.id,v_rate.component_kind,(v_component->>'quantity')::bigint,v_rate.rate_numerator,v_rate.rate_denominator,(v_component->>'quantity')::numeric*v_rate.rate_numerator,v_rate.rate_denominator,v_component)
    on conflict(provider_attempt_id,component_kind) do nothing;
  end loop;
  update tongs.paid_media_provider_attempts set state=case when state='completed' then state else 'failed' end,transmitted=true,
    transport_evidence_json=coalesce(p_evidence_json,'{}'),completed_at=coalesce(completed_at,now()) where id=v_attempt.id returning * into v_attempt;
  v_release:=tongs.release_ai_credit_reservation(v_op.user_id,v_op.reservation_id,p_release_id,p_failure_kind,p_evidence_json);
  update tongs.paid_media_operations set state=case when p_failure_kind='delivery_failure' then 'delivery_failed' else 'provider_failed' end,
    failure_code=p_failure_code,failure_message=p_failure_message,reconciliation_required=false,updated_at=now() where id=v_op.id returning * into v_op;
  insert into tongs.paid_media_operation_events values(gen_random_uuid(),v_op.id,v_op.user_id,p_failure_kind,
    (select coalesce(max(event_ordinal),0)+1 from tongs.paid_media_operation_events where paid_media_operation_id=v_op.id),coalesce(p_evidence_json,'{}'),v_op.actor_id,now());
  return jsonb_build_object('operation',to_jsonb(v_op),'attempt',to_jsonb(v_attempt),'release',v_release,'replay',false);
end $$;


ALTER FUNCTION "tongs"."record_paid_media_terminal_failure"("p_paid_media_operation_id" "uuid", "p_operation_fingerprint" "text", "p_attempt_id" "uuid", "p_failure_kind" "text", "p_failure_code" "text", "p_failure_message" "text", "p_evidence_json" "jsonb", "p_usage_components" "jsonb", "p_release_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."record_paid_operation_aggregate_outcome"("p_reservation_id" "uuid", "p_event_key" "text", "p_outcome" "text", "p_supplier_obligation_micros" bigint DEFAULT NULL::bigint, "p_supplier_recovery_micros" bigint DEFAULT NULL::bigint, "p_evidence_json" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare b tongs.paid_operation_aggregate_bindings%rowtype; event_type text; loss bigint:=0;
 result jsonb; remaining bigint; rounding_risk bigint;
begin
 perform tongs._require_pricing_service_role();
 select * into b from tongs.paid_operation_aggregate_bindings where reservation_id=p_reservation_id;
 if not found then return jsonb_build_object('enforcement_enabled',false,'recorded',false,'reason','aggregate_assignment_inactive'); end if;
 event_type:=case p_outcome when 'preprovider_release' then 'released' when 'ambiguous' then 'ambiguous'
  when 'failure' then 'customer_relieved_supplier_obligation' when 'settled_unconfirmed' then 'settled_unconfirmed'
  when 'reconciled_partial' then 'reconciliation_partial' when 'reconciled' then 'reconciled'
  when 'supplier_recovery' then 'supplier_recovery' else null end;
 if event_type is null then raise exception 'invalid aggregate outcome' using errcode='22023'; end if;
 if p_outcome='failure' then loss:=coalesce(p_supplier_obligation_micros,0); end if;
 result:=tongs.record_restricted_beta_exposure_outcome(
  b.hold_id,p_event_key,event_type,p_supplier_obligation_micros,p_supplier_recovery_micros,
  case when p_outcome='failure' then -b.customer_funding_ceiling_micros else 0 end,loss,p_evidence_json);
 if p_outcome='settled_unconfirmed' and p_supplier_obligation_micros is not null
    and coalesce((p_evidence_json->>'provider_usage_reported')::boolean,false) is true then
  rounding_risk:=case when b.credential_funding='forge' then
    least(greatest(coalesce((p_evidence_json->>'direct_cost_rounding_risk_micros')::bigint,3),0),3)
    else 0 end;
  remaining:=p_supplier_obligation_micros+rounding_risk;
  result:=result||jsonb_build_object('conservative_finalization',tongs.record_restricted_beta_exposure_adjustment(
    b.hold_id,p_event_key||':reconciliation-risk','reconciliation_risk',remaining,
    remaining-(b.supplier_exposure_ceiling_micros+b.supporting_exposure_ceiling_micros),
    p_supplier_obligation_micros,jsonb_build_object('authoritative',false,'estimated_realized_supplier_expense_retained',true,
      'direct_rounding_risk_micros',rounding_risk,'supporting_and_tail_costs_remain_unconfirmed',true)));
 elsif p_outcome in ('reconciled','reconciled_partial') then
  result:=result||jsonb_build_object('admission_control',tongs._maybe_halt_restricted_beta_policy(
    b.policy_revision_id,p_event_key||':capacity-check',p_evidence_json));
 end if;
 return jsonb_build_object('enforcement_enabled',true,'recorded',true)||result;
end $$;


ALTER FUNCTION "tongs"."record_paid_operation_aggregate_outcome"("p_reservation_id" "uuid", "p_event_key" "text", "p_outcome" "text", "p_supplier_obligation_micros" bigint, "p_supplier_recovery_micros" bigint, "p_evidence_json" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."record_paid_operation_aggregate_outcome"("p_reservation_id" "uuid", "p_event_key" "text", "p_outcome" "text", "p_supplier_obligation_micros" bigint, "p_supplier_recovery_micros" bigint, "p_evidence_json" "jsonb") IS 'Settled-estimated expense remains committed until append-only authoritative reconciliation adjusts it.';



CREATE OR REPLACE FUNCTION "tongs"."record_paid_operation_tail_obligation"("p_id" "uuid", "p_reservation_id" "uuid", "p_event_key" "text", "p_artifact_class" "text", "p_lifecycle_state" "text", "p_estimated_amount_micros" bigint, "p_retained_bytes" bigint, "p_coverage_ends_at" timestamp with time zone, "p_retention_reason" "text", "p_evidence_json" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare existing tongs.paid_operation_tail_obligation_events%rowtype;
begin
  perform tongs._require_pricing_service_role();
  select * into existing from tongs.paid_operation_tail_obligation_events where event_key=btrim(p_event_key);
  if found then return to_jsonb(existing)||jsonb_build_object('replay',true); end if;
  if not exists(select 1 from tongs.funding_reservations where id=p_reservation_id) then
    raise exception 'unknown funding reservation' using errcode='22023'; end if;
  insert into tongs.paid_operation_tail_obligation_events(
    id,reservation_id,sequence,event_key,artifact_class,lifecycle_state,estimated_amount_micros,
    retained_bytes,coverage_ends_at,retention_reason,evidence_json
  ) select p_id,p_reservation_id,coalesce(max(sequence),0)+1,btrim(p_event_key),p_artifact_class,
    p_lifecycle_state,p_estimated_amount_micros,p_retained_bytes,p_coverage_ends_at,
    btrim(p_retention_reason),coalesce(p_evidence_json,'{}'::jsonb)
    from tongs.paid_operation_tail_obligation_events where reservation_id=p_reservation_id
    returning * into existing;
  return to_jsonb(existing)||jsonb_build_object('replay',false);
end $$;


ALTER FUNCTION "tongs"."record_paid_operation_tail_obligation"("p_id" "uuid", "p_reservation_id" "uuid", "p_event_key" "text", "p_artifact_class" "text", "p_lifecycle_state" "text", "p_estimated_amount_micros" bigint, "p_retained_bytes" bigint, "p_coverage_ends_at" timestamp with time zone, "p_retention_reason" "text", "p_evidence_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."record_provider_failure"("p_reservation_id" "uuid", "p_event_key" "text", "p_failure_class" "text", "p_evidence_json" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_reservation tongs.funding_reservations%rowtype;
  v_quote tongs.customer_spending_quotes%rowtype;
  v_existing tongs.funding_reservation_events%rowtype;
  v_sequence integer;
  v_billable boolean;
  v_disclosed_class text;
begin
  perform tongs._require_pricing_service_role();
  if length(btrim(coalesce(p_event_key, ''))) < 8
     or nullif(btrim(coalesce(p_failure_class, '')), '') is null
     or jsonb_typeof(coalesce(p_evidence_json, 'null'::jsonb)) <> 'object' then
    raise exception 'invalid provider failure' using errcode = '22023';
  end if;
  v_disclosed_class := case btrim(p_failure_class)
    when 'forge_validation_failure' then 'forge_failure'
    when 'persistence_failure' then 'forge_failure'
    else btrim(p_failure_class)
  end;
  perform pg_advisory_xact_lock(hashtextextended('provider-attempt:' || p_reservation_id::text, 0));
  select * into v_reservation from tongs.funding_reservations where id = p_reservation_id for update;
  if not found then raise exception 'funding reservation not found' using errcode = 'P0002'; end if;
  select * into v_quote from tongs.customer_spending_quotes where id = v_reservation.quote_id;
  select * into v_existing from tongs.funding_reservation_events where event_key = btrim(p_event_key);
  if found then return jsonb_build_object('reservation_id', p_reservation_id,
    'failure_class', v_existing.failure_class, 'replay', true); end if;
  if tongs._funding_reservation_state(p_reservation_id) in ('settled', 'released') then
    raise exception 'reservation is terminal' using errcode = 'P0001';
  end if;
  v_billable := exists (select 1 from jsonb_array_elements_text(v_quote.billable_failure_classes) value
    where value in (btrim(p_failure_class), v_disclosed_class));
  if not v_billable and not exists (
    select 1 from jsonb_array_elements_text(v_quote.free_failure_classes) value
    where value in (btrim(p_failure_class), v_disclosed_class)
  ) then raise exception 'failure class was not disclosed by accepted quote' using errcode = 'P0001'; end if;
  select coalesce(max(sequence),0)+1 into v_sequence from tongs.funding_reservation_events
    where reservation_id = p_reservation_id;
  insert into tongs.funding_reservation_events(
    id, reservation_id, sequence, event_type, event_key, failure_class, evidence_json
  ) values (gen_random_uuid(), p_reservation_id, v_sequence, 'provider_failure_recorded',
    btrim(p_event_key), btrim(p_failure_class), coalesce(p_evidence_json, '{}'::jsonb));
  return jsonb_build_object('reservation_id', p_reservation_id, 'failure_class', btrim(p_failure_class),
    'disclosed_as',v_disclosed_class,'billable',v_billable,
    'maximum_customer_charge_micros',case when v_billable then v_quote.billable_failure_maximum_charge_micros else 0 end,
    'replay', false);
end;
$$;


ALTER FUNCTION "tongs"."record_provider_failure"("p_reservation_id" "uuid", "p_event_key" "text", "p_failure_class" "text", "p_evidence_json" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."record_provider_failure"("p_reservation_id" "uuid", "p_event_key" "text", "p_failure_class" "text", "p_evidence_json" "jsonb") IS 'Records precise failure attribution. forge_validation_failure and persistence_failure inherit an accepted broad forge_failure term without changing the quote.';



CREATE OR REPLACE FUNCTION "tongs"."record_publication_attempt_transition"("p_attempt_id" "uuid", "p_expected_state" "text", "p_new_state" "text", "p_side_effect_possible" boolean, "p_credential_generation_id" "uuid" DEFAULT NULL::"uuid", "p_adapter_id" "text" DEFAULT NULL::"text", "p_adapter_version" "text" DEFAULT NULL::"text", "p_provider_request_id" "text" DEFAULT NULL::"text", "p_provider_upload_session_id" "text" DEFAULT NULL::"text", "p_external_object_id" "text" DEFAULT NULL::"text", "p_external_url" "text" DEFAULT NULL::"text", "p_failure_code" "text" DEFAULT NULL::"text", "p_failure_detail_json" "jsonb" DEFAULT NULL::"jsonb", "p_normalized_provider_evidence" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare v_attempt tongs.publication_attempts%rowtype; v_op tongs.publication_operations%rowtype; v_destination tongs.publishing_executable_destinations%rowtype; v_terminal boolean;
begin
  if auth.role()<>'service_role' then raise exception 'Forbidden' using errcode='42501'; end if;
  select * into v_attempt from tongs.publication_attempts where id=p_attempt_id for update;
  if not found then return jsonb_build_object('disposition','blocked','code','publication_attempt_missing'); end if;
  if v_attempt.state<>p_expected_state then return jsonb_build_object('disposition','conflict','code','publication_attempt_state_conflict','state',v_attempt.state); end if;
  update tongs.publication_attempts set state=p_new_state,side_effect_possible=side_effect_possible or p_side_effect_possible,
    credential_generation_id=coalesce(p_credential_generation_id,credential_generation_id),adapter_id=coalesce(p_adapter_id,adapter_id),adapter_version=coalesce(p_adapter_version,adapter_version),
    provider_request_id=coalesce(p_provider_request_id,provider_request_id),provider_upload_session_id=coalesce(p_provider_upload_session_id,provider_upload_session_id),external_object_id=coalesce(p_external_object_id,external_object_id),external_url=coalesce(p_external_url,external_url),
    failure_code=p_failure_code,failure_detail_json=p_failure_detail_json,started_at=coalesce(started_at,case when p_new_state='preparing_execution' then now() end),finished_at=case when p_new_state in('succeeded','confirmed_failure','recoverable_failure','blocked','outcome_unknown') then now() else null end
  where id=p_attempt_id returning * into v_attempt;
  v_terminal:=v_attempt.state in('succeeded','confirmed_failure','recoverable_failure','blocked','outcome_unknown');
  if v_terminal then
    select * into v_op from tongs.publication_operations where id=v_attempt.publication_operation_id;
    select * into v_destination from tongs.publishing_executable_destinations where id=v_op.executable_destination_id;
    insert into tongs.publication_receipts(publication_operation_id,publication_attempt_id,outcome,workspace_id,workpiece_id,manifest_snapshot_id,manifest_content_hash,release_decision_id,release_decision_revision,executable_destination_id,destination_capability_revision_id,credential_generation_id,provider,adapter_id,adapter_version,provider_request_id,provider_upload_session_id,external_object_id,external_url,normalized_provider_evidence)
    values(v_op.id,v_attempt.id,v_attempt.state,v_op.workspace_id,v_op.workpiece_id,v_op.manifest_snapshot_id,v_op.manifest_content_hash,v_op.release_decision_id,v_op.release_decision_revision,v_op.executable_destination_id,v_op.destination_capability_revision_id,v_attempt.credential_generation_id,v_destination.provider,v_attempt.adapter_id,v_attempt.adapter_version,v_attempt.provider_request_id,v_attempt.provider_upload_session_id,v_attempt.external_object_id,v_attempt.external_url,coalesce(p_normalized_provider_evidence,'{}'::jsonb));
    if v_attempt.state='outcome_unknown' then insert into tongs.publication_reconciliation_events(publication_operation_id,publication_attempt_id,event_kind,evidence_json) values(v_op.id,v_attempt.id,'reconciliation_required',jsonb_build_object('failure_code',v_attempt.failure_code,'provider_request_id',v_attempt.provider_request_id,'provider_upload_session_id',v_attempt.provider_upload_session_id)); end if;
  end if;
  return jsonb_build_object('disposition','recorded','publication_operation_id',v_attempt.publication_operation_id,'publication_attempt_id',v_attempt.id,'state',v_attempt.state);
end; $$;


ALTER FUNCTION "tongs"."record_publication_attempt_transition"("p_attempt_id" "uuid", "p_expected_state" "text", "p_new_state" "text", "p_side_effect_possible" boolean, "p_credential_generation_id" "uuid", "p_adapter_id" "text", "p_adapter_version" "text", "p_provider_request_id" "text", "p_provider_upload_session_id" "text", "p_external_object_id" "text", "p_external_url" "text", "p_failure_code" "text", "p_failure_detail_json" "jsonb", "p_normalized_provider_evidence" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."record_publishing_executable_destination"("p_provider_account_id" "uuid", "p_destination_kind" "text", "p_external_destination_id" "text", "p_display_label" "text", "p_state" "text", "p_observed_at" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare v_account tongs.publishing_provider_accounts%rowtype; v_connection tongs.publishing_provider_connections%rowtype; v_destination tongs.publishing_executable_destinations%rowtype;
begin
  if auth.role()<>'service_role' then raise exception 'Forbidden' using errcode='42501'; end if;
  if p_destination_kind not in('channel','page','show','feed') or p_state not in('active','unavailable','ownership_changed','removed') then return jsonb_build_object('disposition','invalid','code','invalid_destination_observation'); end if;
  select * into v_account from tongs.publishing_provider_accounts where id=p_provider_account_id;
  if not found then return jsonb_build_object('disposition','blocked','code','provider_account_missing'); end if;
  if v_account.state <> 'active' then return jsonb_build_object('disposition','blocked','code','provider_account_not_active'); end if;
  select * into v_connection from tongs.publishing_provider_connections where id=v_account.connection_id;
  if v_connection.state <> 'active' then return jsonb_build_object('disposition','blocked','code','connection_not_active'); end if;
  insert into tongs.publishing_executable_destinations(provider_account_id,connection_id,owner_user_id,provider,destination_kind,external_destination_id,display_label,state,observation_revision,observed_at,removed_at)
  values(v_account.id,v_connection.id,v_connection.owner_user_id,v_connection.provider,p_destination_kind,p_external_destination_id,p_display_label,p_state,1,p_observed_at,case when p_state='removed' then p_observed_at end)
  on conflict(connection_id,external_destination_id) do update set provider_account_id=excluded.provider_account_id,destination_kind=excluded.destination_kind,display_label=excluded.display_label,state=excluded.state,observation_revision=tongs.publishing_executable_destinations.observation_revision+1,observed_at=excluded.observed_at,removed_at=excluded.removed_at,updated_at=now()
  returning * into v_destination;
  return jsonb_build_object('disposition','recorded','executable_destination_id',v_destination.id,'observation_revision',v_destination.observation_revision);
end; $$;


ALTER FUNCTION "tongs"."record_publishing_executable_destination"("p_provider_account_id" "uuid", "p_destination_kind" "text", "p_external_destination_id" "text", "p_display_label" "text", "p_state" "text", "p_observed_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."record_publishing_provider_account"("p_connection_id" "uuid", "p_external_account_id" "text", "p_display_label" "text", "p_state" "text", "p_observed_at" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare v_connection tongs.publishing_provider_connections%rowtype; v_account tongs.publishing_provider_accounts%rowtype;
begin
  if auth.role()<>'service_role' then raise exception 'Forbidden' using errcode='42501'; end if;
  if p_state not in('active','unavailable','removed') then return jsonb_build_object('disposition','invalid','code','invalid_account_state'); end if;
  select * into v_connection from tongs.publishing_provider_connections where id=p_connection_id;
  if not found then return jsonb_build_object('disposition','blocked','code','connection_missing'); end if;
  if v_connection.state <> 'active' then return jsonb_build_object('disposition','blocked','code','connection_not_active'); end if;
  insert into tongs.publishing_provider_accounts(connection_id,owner_user_id,provider,external_account_id,display_label,state,observation_revision,observed_at,removed_at)
  values(v_connection.id,v_connection.owner_user_id,v_connection.provider,p_external_account_id,p_display_label,p_state,1,p_observed_at,case when p_state='removed' then p_observed_at end)
  on conflict(connection_id,external_account_id) do update set display_label=excluded.display_label,state=excluded.state,observation_revision=tongs.publishing_provider_accounts.observation_revision+1,observed_at=excluded.observed_at,removed_at=excluded.removed_at,updated_at=now()
  returning * into v_account;
  return jsonb_build_object('disposition','recorded','provider_account_id',v_account.id,'observation_revision',v_account.observation_revision);
end; $$;


ALTER FUNCTION "tongs"."record_publishing_provider_account"("p_connection_id" "uuid", "p_external_account_id" "text", "p_display_label" "text", "p_state" "text", "p_observed_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."record_reference_clip_source_acquired"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_source_evidence" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$declare op tongs.reference_clip_acquisition_operations%rowtype;h text;begin select * into op from tongs.reference_clip_acquisition_operations where operation_id=p_operation_id for update;if not found then return jsonb_build_object('disposition','operation_not_found');end if;if not tongs.has_workspace_role(op.workspace_id,'editor') then raise exception 'workspace editor authority required' using errcode='42501';end if;if op.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict');end if;h:=encode(extensions.digest(convert_to(p_source_evidence::text,'UTF8'),'sha256'),'hex');if op.state<>'pending' then if op.source_evidence_hash<>h then return jsonb_build_object('disposition','source_evidence_conflict');end if;return jsonb_build_object('disposition','replay','operation',to_jsonb(op));end if;update tongs.reference_clip_acquisition_operations set state='source_acquired',source_evidence_json=p_source_evidence,source_evidence_hash=h,failed_stage=null,failure_code=null,failure_message=null,failure_evidence_json=null,updated_at=now() where operation_id=p_operation_id returning * into op;return jsonb_build_object('disposition','source_acquired','operation',to_jsonb(op));end$$;


ALTER FUNCTION "tongs"."record_reference_clip_source_acquired"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_source_evidence" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."record_reference_visual_source_acquired"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_source_evidence" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$declare op tongs.reference_visual_acquisition_operations%rowtype;begin select * into op from tongs.reference_visual_acquisition_operations where operation_id=p_operation_id for update;if not found then return jsonb_build_object('disposition','operation_not_found');end if;if not tongs.has_workspace_role(op.workspace_id,'editor')then raise exception 'workspace editor authority required' using errcode='42501';end if;if op.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict');end if;if op.state<>'pending' then if op.source_evidence_json is distinct from p_source_evidence then return jsonb_build_object('disposition','source_evidence_conflict');end if;return jsonb_build_object('disposition','replay','operation',to_jsonb(op));end if;update tongs.reference_visual_acquisition_operations set state='source_acquired',source_evidence_json=p_source_evidence,failed_stage=null,failure_code=null,failure_message=null,updated_at=now()where operation_id=p_operation_id returning * into op;return jsonb_build_object('disposition','source_acquired','operation',to_jsonb(op));end$$;


ALTER FUNCTION "tongs"."record_reference_visual_source_acquired"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_source_evidence" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."record_restricted_beta_exposure_adjustment"("p_hold_id" "uuid", "p_event_key" "text", "p_event_type" "text", "p_remaining_exposure_micros" bigint, "p_exposure_adjustment_micros" bigint, "p_supplier_obligation_micros" bigint DEFAULT NULL::bigint, "p_evidence_json" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare hold tongs.restricted_beta_exposure_holds%rowtype; existing tongs.restricted_beta_exposure_events%rowtype;
  halt_result jsonb;
begin
  perform tongs._require_pricing_service_role();
  if p_event_type not in ('realized_estimate','reconciliation_risk','authoritative_adjustment','tail_obligation')
     or p_remaining_exposure_micros<0 then raise exception 'invalid exposure adjustment' using errcode='22023'; end if;
  if p_event_type='authoritative_adjustment' and coalesce((p_evidence_json->>'authoritative')::boolean,false) is not true then
    raise exception 'authoritative adjustment evidence required' using errcode='P0001'; end if;
  select * into existing from tongs.restricted_beta_exposure_events where event_key=btrim(p_event_key);
  if found then return to_jsonb(existing)||jsonb_build_object('replay',true); end if;
  select * into hold from tongs.restricted_beta_exposure_holds where id=p_hold_id for update;
  if hold.id is null then raise exception 'unknown exposure hold' using errcode='22023'; end if;
  insert into tongs.restricted_beta_exposure_events(
    id,hold_id,sequence,event_key,event_type,supplier_obligation_micros,
    remaining_exposure_micros,exposure_adjustment_micros,evidence_json
  ) select extensions.uuid_generate_v5(hold.id,btrim(p_event_key)),hold.id,coalesce(max(sequence),0)+1,
    btrim(p_event_key),p_event_type,p_supplier_obligation_micros,p_remaining_exposure_micros,
    p_exposure_adjustment_micros,coalesce(p_evidence_json,'{}'::jsonb)
    from tongs.restricted_beta_exposure_events where hold_id=hold.id returning * into existing;
  halt_result:=tongs._maybe_halt_restricted_beta_policy(
    hold.policy_revision_id,btrim(p_event_key)||':halt-new',coalesce(p_evidence_json,'{}'::jsonb));
  return to_jsonb(existing)||jsonb_build_object('replay',false,'admission_control',halt_result);
end $$;


ALTER FUNCTION "tongs"."record_restricted_beta_exposure_adjustment"("p_hold_id" "uuid", "p_event_key" "text", "p_event_type" "text", "p_remaining_exposure_micros" bigint, "p_exposure_adjustment_micros" bigint, "p_supplier_obligation_micros" bigint, "p_evidence_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."record_restricted_beta_exposure_outcome"("p_hold_id" "uuid", "p_event_key" "text", "p_event_type" "text", "p_supplier_obligation_micros" bigint DEFAULT NULL::bigint, "p_supplier_recovery_micros" bigint DEFAULT NULL::bigint, "p_customer_funding_delta_micros" bigint DEFAULT 0, "p_forge_loss_delta_micros" bigint DEFAULT 0, "p_evidence_json" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare h tongs.restricted_beta_exposure_holds%rowtype; existing tongs.restricted_beta_exposure_events%rowtype;
 last_type text; attempts bigint;
begin
 perform tongs._require_pricing_service_role();
 if p_event_type not in ('ambiguous','customer_relieved_supplier_obligation','settled_unconfirmed','reconciliation_partial','supplier_recovery','released','reconciled') then
  raise exception 'invalid outcome' using errcode='22023'; end if;
 select * into existing from tongs.restricted_beta_exposure_events where event_key=p_event_key;
 if found then return to_jsonb(existing)||jsonb_build_object('replay',true); end if;
 select * into h from tongs.restricted_beta_exposure_holds where id=p_hold_id for update;
 if not found then raise exception 'unknown exposure hold' using errcode='22023'; end if;
 select event_type into last_type from tongs.restricted_beta_exposure_events where hold_id=h.id order by sequence desc limit 1;
 if last_type='released' then return jsonb_build_object('hold_id',h.id,'state',last_type,'replay',true); end if;
 if exists(select 1 from tongs.restricted_beta_exposure_events where hold_id=h.id and event_type='reconciled')
    and p_event_type not in ('reconciled','supplier_recovery') then
  return jsonb_build_object('hold_id',h.id,'state',last_type,'replay',true); end if;
 select count(*) into attempts from tongs.restricted_beta_exposure_events where hold_id=h.id and event_type='attempt_started';
 if p_event_type='released' and attempts>0 and coalesce((p_evidence_json->>'transmitted')::boolean,true) is not false then
  raise exception 'attempted supplier work requires reconciliation' using errcode='P0001'; end if;
 if p_event_type='reconciliation_partial' and (p_supplier_obligation_micros is null or coalesce((p_evidence_json->>'authoritative')::boolean,false) is not true) then
  raise exception 'authoritative partial supplier obligation required' using errcode='P0001'; end if;
 if p_event_type='reconciled' and (p_supplier_obligation_micros is null or coalesce((p_evidence_json->>'authoritative')::boolean,false) is not true) then
  raise exception 'authoritative supplier obligation required for reconciliation' using errcode='P0001'; end if;
 if p_event_type='supplier_recovery' and coalesce(p_supplier_recovery_micros,0)<=0 then
  raise exception 'positive supplier recovery required' using errcode='22023'; end if;
 insert into tongs.restricted_beta_exposure_events(id,hold_id,sequence,event_key,event_type,supplier_obligation_micros,supplier_recovery_micros,customer_funding_delta_micros,forge_loss_delta_micros,evidence_json)
 select extensions.uuid_generate_v5(h.id,p_event_key),h.id,coalesce(max(sequence),0)+1,p_event_key,p_event_type,p_supplier_obligation_micros,p_supplier_recovery_micros,p_customer_funding_delta_micros,p_forge_loss_delta_micros,coalesce(p_evidence_json,'{}'::jsonb)
 from tongs.restricted_beta_exposure_events where hold_id=h.id returning * into existing;
 return to_jsonb(existing)||jsonb_build_object('replay',false);
end $$;


ALTER FUNCTION "tongs"."record_restricted_beta_exposure_outcome"("p_hold_id" "uuid", "p_event_key" "text", "p_event_type" "text", "p_supplier_obligation_micros" bigint, "p_supplier_recovery_micros" bigint, "p_customer_funding_delta_micros" bigint, "p_forge_loss_delta_micros" bigint, "p_evidence_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."record_runway_completion_for_reconciliation"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_provider_task_id" "text", "p_evidence_json" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $_$
declare
  v_binding tongs.runway_funding_bindings%rowtype;
  v_existing tongs.runway_execution_reconciliation_receipts%rowtype;
  v_actual bigint;
begin
  perform tongs._require_pricing_service_role();
  if nullif(btrim(coalesce(p_operation_id, '')), '') is null
     or p_operation_fingerprint !~ '^[0-9a-f]{64}$'
     or nullif(btrim(coalesce(p_provider_task_id, '')), '') is null
     or jsonb_typeof(coalesce(p_evidence_json, 'null'::jsonb)) <> 'object' then
    raise exception 'invalid Runway completion receipt' using errcode = '22023';
  end if;
  select * into v_binding from tongs.runway_funding_bindings where operation_id = btrim(p_operation_id);
  if not found then return jsonb_build_object('recorded', false, 'reason', 'no_funding_binding'); end if;
  if v_binding.operation_fingerprint <> p_operation_fingerprint then
    raise exception 'Runway completion fingerprint mismatch' using errcode = '42501';
  end if;
  v_actual := v_binding.duration_seconds::bigint * 120000;
  select * into v_existing from tongs.runway_execution_reconciliation_receipts
  where operation_id = v_binding.operation_id;
  if found then
    if v_existing.provider_task_id <> btrim(p_provider_task_id)
       or v_existing.direct_provider_estimated_micros <> v_actual then
      raise exception 'Runway completion receipt replay conflict' using errcode = '23505';
    end if;
    return jsonb_build_object('recorded', true, 'replay', true,
      'reservation_id', v_binding.reservation_id,
      'direct_provider_estimated_micros', v_actual,
      'supporting_cost_status', v_existing.supporting_cost_status);
  end if;
  insert into tongs.runway_execution_reconciliation_receipts(
    operation_id, reservation_id, provider_task_id, direct_provider_estimated_micros, evidence_json
  ) values (
    v_binding.operation_id, v_binding.reservation_id, btrim(p_provider_task_id), v_actual,
    coalesce(p_evidence_json, '{}'::jsonb)
  );
  return jsonb_build_object('recorded', true, 'replay', false,
    'reservation_id', v_binding.reservation_id,
    'direct_provider_estimated_micros', v_actual,
    'supporting_cost_status', 'pending',
    'customer_revenue_micros', 0);
end;
$_$;


ALTER FUNCTION "tongs"."record_runway_completion_for_reconciliation"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_provider_task_id" "text", "p_evidence_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."record_runway_failure_for_reconciliation"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_provider_task_id" "text", "p_evidence_json" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $_$
declare
  v_binding tongs.runway_funding_bindings%rowtype;
begin
  perform tongs._require_pricing_service_role();
  if nullif(btrim(coalesce(p_operation_id, '')), '') is null
     or p_operation_fingerprint !~ '^[0-9a-f]{64}$'
     or nullif(btrim(coalesce(p_provider_task_id, '')), '') is null
     or jsonb_typeof(coalesce(p_evidence_json, 'null'::jsonb)) <> 'object' then
    raise exception 'invalid Runway failure receipt' using errcode = '22023';
  end if;
  select * into v_binding from tongs.runway_funding_bindings where operation_id = btrim(p_operation_id);
  if not found then return jsonb_build_object('recorded', false, 'reason', 'no_funding_binding'); end if;
  if v_binding.operation_fingerprint <> p_operation_fingerprint then
    raise exception 'Runway failure fingerprint mismatch' using errcode = '42501';
  end if;
  perform tongs.record_provider_failure(
    v_binding.reservation_id,
    'runway-task:' || btrim(p_provider_task_id) || ':provider-failure',
    'provider_billed_failure',
    coalesce(p_evidence_json, '{}'::jsonb) || jsonb_build_object(
      'provider', 'runway', 'provider_task_id', btrim(p_provider_task_id))
  );
  return jsonb_build_object('recorded', true, 'reservation_id', v_binding.reservation_id,
    'reservation_retained', true, 'requires_cost_reconciliation', true,
    'automatic_resubmission_allowed', false);
end;
$_$;


ALTER FUNCTION "tongs"."record_runway_failure_for_reconciliation"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_provider_task_id" "text", "p_evidence_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."record_stripe_adjustment_accounting"("p_record_id" "uuid", "p_stripe_refund_id" "text", "p_stripe_event_id" "text", "p_stripe_payment_intent_id" "text", "p_adjustment_type" "text", "p_livemode" boolean, "p_amount_micros" bigint, "p_currency" "text", "p_recorded_at" timestamp with time zone, "p_evidence_json" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $_$
declare
  v_mode text := case when coalesce(p_livemode, false) then 'live' else 'test' end;
  v_payment_intent text := nullif(btrim(coalesce(p_stripe_payment_intent_id, '')), '');
  v_refund text := nullif(btrim(coalesce(p_stripe_refund_id, '')), '');
  v_deposit tongs.customer_deposits%rowtype;
  v_receipt tongs.subscription_cycle_receipts%rowtype;
  v_unmatched tongs.accounting_unmatched_provider_events%rowtype;
begin
  perform tongs._require_accounting_service_role();
  if p_record_id is null or v_payment_intent is null or v_refund is null
     or nullif(btrim(coalesce(p_stripe_event_id, '')), '') is null or p_amount_micros <= 0
     or upper(btrim(coalesce(p_currency, ''))) !~ '^[A-Z]{3}$'
     or p_adjustment_type not in ('refund', 'dispute', 'payment_reversal') then
    raise exception 'invalid Stripe refund accounting event' using errcode = '22023';
  end if;
  select * into v_deposit from tongs.customer_deposits
   where stripe_mode = v_mode and stripe_payment_intent_id = v_payment_intent;
  if found then
    if v_deposit.currency <> upper(btrim(p_currency)) then
      raise exception 'Stripe adjustment currency does not match deposit' using errcode = '22023';
    end if;
    return tongs.record_customer_deposit_refund(p_record_id, v_deposit.id, v_refund,
      p_stripe_event_id, p_adjustment_type, p_amount_micros, p_recorded_at, p_evidence_json);
  end if;
  select * into v_receipt from tongs.subscription_cycle_receipts
   where stripe_mode = v_mode and stripe_payment_intent_id = v_payment_intent
   order by received_at desc limit 1;
  if found then
    if v_receipt.currency <> upper(btrim(p_currency)) then
      raise exception 'Stripe adjustment currency does not match subscription receipt' using errcode = '22023';
    end if;
    return tongs.record_subscription_cycle_adjustment(p_record_id, v_receipt.id, v_refund,
      p_stripe_event_id, p_adjustment_type, p_amount_micros, p_recorded_at, p_evidence_json);
  end if;
  perform pg_advisory_xact_lock(hashtextextended('stripe-unmatched:' || v_refund, 0));
  select * into v_unmatched from tongs.accounting_unmatched_provider_events
  where provider = 'stripe' and provider_object_id = v_refund;
  if found then
    if v_unmatched.stripe_mode <> v_mode or v_unmatched.amount_micros <> p_amount_micros
       or v_unmatched.currency <> upper(btrim(p_currency)) or v_unmatched.event_type <> p_adjustment_type then
      raise exception 'unmatched Stripe adjustment replay conflict' using errcode = '23505';
    end if;
    return jsonb_build_object('unmatched', true, 'record_id', v_unmatched.id, 'replay', true);
  end if;
  insert into tongs.accounting_unmatched_provider_events(
    id, provider, provider_event_id, provider_object_id, event_type, stripe_mode,
    amount_micros, currency, evidence_json
  ) values (
    p_record_id, 'stripe', btrim(p_stripe_event_id), v_refund, p_adjustment_type, v_mode,
    p_amount_micros, upper(btrim(p_currency)), coalesce(p_evidence_json, '{}'::jsonb)
  );
  return jsonb_build_object('unmatched', true, 'record_id', p_record_id, 'replay', false);
end;
$_$;


ALTER FUNCTION "tongs"."record_stripe_adjustment_accounting"("p_record_id" "uuid", "p_stripe_refund_id" "text", "p_stripe_event_id" "text", "p_stripe_payment_intent_id" "text", "p_adjustment_type" "text", "p_livemode" boolean, "p_amount_micros" bigint, "p_currency" "text", "p_recorded_at" timestamp with time zone, "p_evidence_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."record_stripe_customer_environment_identifier"("p_user_id" "uuid", "p_financial_environment" "text", "p_stripe_customer_id" "text", "p_evidence_json" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare v_existing text;
begin
  perform tongs._require_pricing_service_role();
  if p_financial_environment not in ('test', 'live')
     or nullif(btrim(coalesce(p_stripe_customer_id, '')), '') is null then
    raise exception 'valid financial environment and Stripe customer are required' using errcode = '22023';
  end if;
  select stripe_customer_id into v_existing
  from tongs.stripe_customer_environment_identifiers
  where user_id = p_user_id and financial_environment = p_financial_environment;
  if found and v_existing <> btrim(p_stripe_customer_id) then
    raise exception 'environment-scoped Stripe customer already exists' using errcode = '23505';
  end if;
  insert into tongs.stripe_customer_environment_identifiers(
    user_id, financial_environment, stripe_customer_id, evidence_json
  ) values (
    p_user_id, p_financial_environment, btrim(p_stripe_customer_id), coalesce(p_evidence_json, '{}'::jsonb)
  ) on conflict (user_id, financial_environment) do nothing;
  return jsonb_build_object(
    'financial_environment', p_financial_environment,
    'stripe_customer_id', btrim(p_stripe_customer_id)
  );
end $$;


ALTER FUNCTION "tongs"."record_stripe_customer_environment_identifier"("p_user_id" "uuid", "p_financial_environment" "text", "p_stripe_customer_id" "text", "p_evidence_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."record_subscription_cycle_adjustment"("p_adjustment_id" "uuid", "p_receipt_id" "uuid", "p_provider_object_id" "text", "p_stripe_event_id" "text", "p_adjustment_type" "text", "p_amount_micros" bigint, "p_adjusted_at" timestamp with time zone, "p_evidence_json" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_receipt tongs.subscription_cycle_receipts%rowtype;
  v_existing tongs.subscription_cycle_adjustments%rowtype;
  v_object text := nullif(btrim(coalesce(p_provider_object_id, '')), '');
  v_event text := nullif(btrim(coalesce(p_stripe_event_id, '')), '');
  v_prior_adjustments bigint;
  v_allocated bigint;
  v_liability_available bigint;
  v_liability_release bigint;
  v_discrepancy bigint;
  v_payload jsonb;
begin
  perform tongs._require_accounting_service_role();
  if p_adjustment_id is null or p_receipt_id is null or v_object is null or v_event is null
     or p_adjustment_type not in ('refund', 'dispute', 'payment_reversal') or p_amount_micros <= 0 then
    raise exception 'invalid subscription cycle adjustment' using errcode = '22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('stripe-adjustment:' || v_object, 0));
  select * into v_existing from tongs.subscription_cycle_adjustments where provider_object_id = v_object;
  if found then
    if v_existing.receipt_id <> p_receipt_id or v_existing.adjustment_type <> p_adjustment_type
       or v_existing.amount_micros <> p_amount_micros then
      raise exception 'subscription adjustment replay conflict' using errcode = '23505';
    end if;
    return jsonb_build_object('adjustment_id', v_existing.id, 'replay', true);
  end if;
  select * into v_receipt from tongs.subscription_cycle_receipts where id = p_receipt_id for update;
  if not found then raise exception 'subscription cycle receipt not found' using errcode = 'P0002'; end if;
  select coalesce(sum(amount_micros), 0), coalesce(sum(liability_release_micros), 0)
    into v_prior_adjustments, v_liability_available
  from tongs.subscription_cycle_adjustments where receipt_id = p_receipt_id;
  if p_amount_micros > v_receipt.gross_amount_micros - v_prior_adjustments then
    raise exception 'adjustment exceeds subscription receipt' using errcode = 'P0001';
  end if;
  select coalesce(sum(allocated_revenue_micros), 0) into v_allocated
  from tongs.paid_allowance_grants where receipt_id = p_receipt_id;
  v_liability_available := greatest(v_receipt.gross_amount_micros - v_allocated - v_liability_available, 0);
  v_liability_release := least(p_amount_micros, v_liability_available);
  v_discrepancy := p_amount_micros - v_liability_release;
  v_payload := jsonb_build_object('adjustment_id', p_adjustment_id, 'receipt_id', p_receipt_id,
    'provider_object_id', v_object, 'stripe_event_id', v_event, 'adjustment_type', p_adjustment_type,
    'amount_micros', p_amount_micros, 'liability_release_micros', v_liability_release,
    'discrepancy_expense_micros', v_discrepancy, 'evidence', coalesce(p_evidence_json, '{}'::jsonb));
  perform tongs._create_accounting_event(
    p_adjustment_id, 'stripe:' || v_receipt.stripe_mode || ':subscription-adjustment:' || v_object,
    'subscription_cycle_' || p_adjustment_type, v_receipt.stripe_mode, 'stripe_adjustment', v_object,
    v_receipt.currency, v_receipt.user_id, null, null, v_payload, coalesce(p_adjusted_at, now())
  );
  insert into tongs.subscription_cycle_adjustments(
    id, receipt_id, provider_object_id, stripe_event_id, adjustment_type, amount_micros,
    liability_release_micros, discrepancy_expense_micros, journal_event_id, evidence_json, adjusted_at
  ) values (
    p_adjustment_id, p_receipt_id, v_object, v_event, p_adjustment_type, p_amount_micros,
    v_liability_release, v_discrepancy, p_adjustment_id, coalesce(p_evidence_json, '{}'::jsonb), coalesce(p_adjusted_at, now())
  );
  insert into tongs.accounting_journal_entries(
    event_id, line_number, account_code, user_id, currency, amount_micros
  )
  select p_adjustment_id, line_number, account_code, v_receipt.user_id,
    v_receipt.currency, amount_micros
  from (values
    (1::smallint, case when v_receipt.stripe_mode = 'live' then 'subscription_deferred_liability' else 'test_subscription_balance' end, v_liability_release),
    (2::smallint, case when v_receipt.stripe_mode = 'live' then 'subscription_adjustment_discrepancy_expense' else 'test_subscription_discrepancy' end, v_discrepancy),
    (3::smallint, case when v_receipt.stripe_mode = 'live' then 'forge_cash_clearing' else 'test_cash_clearing' end, -p_amount_micros)
  ) lines(line_number, account_code, amount_micros)
  where amount_micros <> 0;
  perform tongs._assert_accounting_event_balanced(p_adjustment_id);
  return jsonb_build_object('adjustment_id', p_adjustment_id, 'replay', false,
    'liability_release_micros', v_liability_release, 'discrepancy_expense_micros', v_discrepancy);
end;
$$;


ALTER FUNCTION "tongs"."record_subscription_cycle_adjustment"("p_adjustment_id" "uuid", "p_receipt_id" "uuid", "p_provider_object_id" "text", "p_stripe_event_id" "text", "p_adjustment_type" "text", "p_amount_micros" bigint, "p_adjusted_at" timestamp with time zone, "p_evidence_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."record_subscription_cycle_receipt"("p_receipt_id" "uuid", "p_user_id" "uuid", "p_stripe_event_id" "text", "p_stripe_invoice_id" "text", "p_stripe_subscription_id" "text", "p_stripe_payment_intent_id" "text", "p_livemode" boolean, "p_purchase_type" "text", "p_plan_item_id" "text", "p_gross_amount_micros" bigint, "p_currency" "text", "p_period_start" timestamp with time zone, "p_period_end" timestamp with time zone, "p_received_at" timestamp with time zone, "p_metadata_json" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $_$
declare
  v_mode text := case when coalesce(p_livemode, false) then 'live' else 'test' end;
  v_currency text := upper(btrim(coalesce(p_currency, '')));
  v_event text := nullif(btrim(coalesce(p_stripe_event_id, '')), '');
  v_invoice text := nullif(btrim(coalesce(p_stripe_invoice_id, '')), '');
  v_subscription text := nullif(btrim(coalesce(p_stripe_subscription_id, '')), '');
  v_payment_intent text := nullif(btrim(coalesce(p_stripe_payment_intent_id, '')), '');
  v_plan text := nullif(btrim(coalesce(p_plan_item_id, '')), '');
  v_existing tongs.subscription_cycle_receipts%rowtype;
  v_payload jsonb;
begin
  perform tongs._require_accounting_service_role();
  if p_receipt_id is null or p_user_id is null or v_event is null or v_invoice is null
     or v_subscription is null or v_plan is null or p_purchase_type not in ('subscription', 'cloud_storage')
     or p_gross_amount_micros <= 0 or v_currency !~ '^[A-Z]{3}$'
     or p_period_start is null or p_period_end <= p_period_start then
    raise exception 'invalid subscription cycle receipt' using errcode = '22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('stripe:' || v_mode || ':invoice:' || v_invoice, 0));
  select * into v_existing from tongs.subscription_cycle_receipts
   where (stripe_mode = v_mode and stripe_event_id = v_event)
      or (stripe_mode = v_mode and stripe_invoice_id = v_invoice) limit 1;
  if found then
    if v_existing.user_id <> p_user_id or v_existing.stripe_invoice_id <> v_invoice
       or v_existing.stripe_subscription_id <> v_subscription or v_existing.purchase_type <> p_purchase_type
       or v_existing.plan_item_id <> v_plan or v_existing.currency <> v_currency
       or v_existing.gross_amount_micros <> p_gross_amount_micros
       or v_existing.period_start <> p_period_start or v_existing.period_end <> p_period_end then
      raise exception 'subscription receipt replay conflict' using errcode = '23505';
    end if;
    return jsonb_build_object('receipt_id', v_existing.id, 'stripe_mode', v_existing.stripe_mode, 'replay', true);
  end if;
  v_payload := jsonb_build_object('receipt_id', p_receipt_id, 'user_id', p_user_id,
    'stripe_event_id', v_event, 'stripe_invoice_id', v_invoice, 'stripe_subscription_id', v_subscription,
    'stripe_payment_intent_id', v_payment_intent, 'stripe_mode', v_mode, 'purchase_type', p_purchase_type,
    'plan_item_id', v_plan, 'gross_amount_micros', p_gross_amount_micros, 'currency', v_currency,
    'period_start', p_period_start, 'period_end', p_period_end, 'metadata', coalesce(p_metadata_json, '{}'::jsonb));
  perform tongs._create_accounting_event(
    p_receipt_id, 'stripe:' || v_mode || ':subscription-receipt:' || v_invoice,
    'subscription_cycle_cash_received', v_mode, 'stripe_invoice', v_invoice, v_currency,
    p_user_id, null, null, v_payload, coalesce(p_received_at, now())
  );
  insert into tongs.subscription_cycle_receipts(
    id, user_id, stripe_mode, stripe_event_id, stripe_invoice_id, stripe_subscription_id,
    stripe_payment_intent_id, purchase_type, plan_item_id, currency, gross_amount_micros,
    period_start, period_end, journal_event_id, metadata_json, received_at
  ) values (
    p_receipt_id, p_user_id, v_mode, v_event, v_invoice, v_subscription, v_payment_intent,
    p_purchase_type, v_plan, v_currency, p_gross_amount_micros, p_period_start, p_period_end,
    p_receipt_id, coalesce(p_metadata_json, '{}'::jsonb), coalesce(p_received_at, now())
  );
  insert into tongs.accounting_journal_entries(
    event_id, line_number, account_code, user_id, currency, amount_micros
  ) values
    (p_receipt_id, 1, case when v_mode = 'live' then 'forge_cash_clearing' else 'test_cash_clearing' end,
      p_user_id, v_currency, p_gross_amount_micros),
    (p_receipt_id, 2, case when v_mode = 'live' then 'subscription_deferred_liability' else 'test_subscription_balance' end,
      p_user_id, v_currency, -p_gross_amount_micros);
  perform tongs._assert_accounting_event_balanced(p_receipt_id);
  return jsonb_build_object('receipt_id', p_receipt_id, 'stripe_mode', v_mode, 'replay', false);
end;
$_$;


ALTER FUNCTION "tongs"."record_subscription_cycle_receipt"("p_receipt_id" "uuid", "p_user_id" "uuid", "p_stripe_event_id" "text", "p_stripe_invoice_id" "text", "p_stripe_subscription_id" "text", "p_stripe_payment_intent_id" "text", "p_livemode" boolean, "p_purchase_type" "text", "p_plan_item_id" "text", "p_gross_amount_micros" bigint, "p_currency" "text", "p_period_start" timestamp with time zone, "p_period_end" timestamp with time zone, "p_received_at" timestamp with time zone, "p_metadata_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."record_supplier_expense"("p_expense_id" "uuid", "p_reservation_id" "uuid", "p_expense_key" "text", "p_provider" "text", "p_component_code" "text", "p_provider_reference" "text", "p_currency" "text", "p_amount_micros" bigint, "p_evidence_status" "text", "p_obligation_status" "text", "p_evidence_json" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare v_existing tongs.supplier_expenses%rowtype;
begin
  perform tongs._require_pricing_service_role();
  select * into v_existing from tongs.supplier_expenses where expense_key=btrim(p_expense_key);
  if found then return jsonb_build_object('expense_id',v_existing.id,'replay',true,'evidence_status',v_existing.evidence_status); end if;
  insert into tongs.supplier_expenses(id,reservation_id,expense_key,provider,component_code,provider_reference,currency,
    amount_micros,evidence_status,obligation_status,evidence_json,incurred_at)
  values(p_expense_id,p_reservation_id,btrim(p_expense_key),lower(btrim(p_provider)),btrim(p_component_code),
    nullif(btrim(coalesce(p_provider_reference,'')),''),upper(btrim(p_currency)),p_amount_micros,p_evidence_status,
    p_obligation_status,coalesce(p_evidence_json,'{}'::jsonb),now()) returning * into v_existing;
  return jsonb_build_object('expense_id',v_existing.id,'replay',false,'evidence_status',v_existing.evidence_status);
end $$;


ALTER FUNCTION "tongs"."record_supplier_expense"("p_expense_id" "uuid", "p_reservation_id" "uuid", "p_expense_key" "text", "p_provider" "text", "p_component_code" "text", "p_provider_reference" "text", "p_currency" "text", "p_amount_micros" bigint, "p_evidence_status" "text", "p_obligation_status" "text", "p_evidence_json" "jsonb") OWNER TO "postgres";


