CREATE OR REPLACE FUNCTION "tongs"."record_supplier_recovery_claim"("p_claim_id" "uuid", "p_supplier_expense_id" "uuid", "p_claim_key" "text", "p_claimed_amount_micros" bigint, "p_currency" "text", "p_evidence_json" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
