CREATE OR REPLACE FUNCTION "tongs"."record_supporting_service_plan_observation"("p_id" "uuid", "p_source_key" "text", "p_provider" "text", "p_plan_name" "text", "p_evidence_period_start" "date", "p_evidence_period_end" "date", "p_fixed_charge_micros" bigint, "p_usage_json" "jsonb", "p_evidence_class" "text", "p_source_reference" "text", "p_observed_at" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare existing tongs.supporting_service_plan_observations%rowtype;
begin
 perform tongs._require_pricing_service_role();
 select * into existing from tongs.supporting_service_plan_observations where source_key=btrim(p_source_key);
 if found then return to_jsonb(existing)||jsonb_build_object('replay',true); end if;
 insert into tongs.supporting_service_plan_observations(id,source_key,provider,plan_name,evidence_period_start,evidence_period_end,fixed_charge_micros,usage_json,evidence_class,source_reference,observed_at)
 values(p_id,btrim(p_source_key),lower(btrim(p_provider)),btrim(p_plan_name),p_evidence_period_start,p_evidence_period_end,p_fixed_charge_micros,coalesce(p_usage_json,'{}'::jsonb),p_evidence_class,btrim(p_source_reference),p_observed_at) returning * into existing;
 return to_jsonb(existing)||jsonb_build_object('replay',false);
end $$;


ALTER FUNCTION "tongs"."record_supporting_service_plan_observation"("p_id" "uuid", "p_source_key" "text", "p_provider" "text", "p_plan_name" "text", "p_evidence_period_start" "date", "p_evidence_period_end" "date", "p_fixed_charge_micros" bigint, "p_usage_json" "jsonb", "p_evidence_class" "text", "p_source_reference" "text", "p_observed_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."record_test_refill"("p_grant_id" "uuid", "p_user_id" "uuid", "p_operator_user_id" "uuid", "p_credit_units" bigint, "p_reason" "text", "p_idempotency_key" "text", "p_expires_at" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare v_actor uuid:=p_operator_user_id; v_event uuid:=gen_random_uuid(); v_existing tongs.test_refill_grants%rowtype;
begin
  if coalesce(auth.role(),'')<>'service_role' or v_actor is null or not tongs.is_platform_operator(v_actor) then
    raise exception 'service-role platform operator required' using errcode='42501'; end if;
  if p_grant_id is null or p_user_id is null or p_credit_units<=0
     or length(btrim(coalesce(p_reason,''))) not between 3 and 500
     or length(btrim(coalesce(p_idempotency_key,''))) not between 8 and 300
     or (p_expires_at is not null and p_expires_at<=now()) then raise exception 'invalid Test refill' using errcode='22023'; end if;
  perform pg_advisory_xact_lock(hashtextextended('test-refill:'||btrim(p_idempotency_key),0));
  select * into v_existing from tongs.test_refill_grants where idempotency_key=btrim(p_idempotency_key);
  if found then
    if v_existing.id<>p_grant_id or v_existing.user_id<>p_user_id or v_existing.credit_units<>p_credit_units then
      raise exception 'Test refill replay conflict' using errcode='23505'; end if;
    return jsonb_build_object('grant_id',v_existing.id,'replay',true,'environment','test','live_funding',false);
  end if;
  perform tongs._create_accounting_event(v_event,'test-refill:'||btrim(p_idempotency_key),
    'test_refill_granted','test','operator_test_refill',p_grant_id::text,null,p_user_id,null,v_actor,
    jsonb_build_object('credit_units',p_credit_units,'reason',btrim(p_reason),'live_funding',false,'customer_revenue',false),now());
  insert into tongs.accounting_journal_entries(event_id,line_number,account_code,user_id,quantity_delta,unit_kind,metadata_json)
  values(v_event,1,'test_credit_available',p_user_id,p_credit_units,'test_credit',jsonb_build_object('live_funding',false));
  insert into tongs.test_refill_grants(id,user_id,credit_units,reason,idempotency_key,granted_by,journal_event_id,expires_at)
  values(p_grant_id,p_user_id,p_credit_units,btrim(p_reason),btrim(p_idempotency_key),v_actor,v_event,p_expires_at);
  return jsonb_build_object('grant_id',p_grant_id,'replay',false,'environment','test','live_funding',false,'customer_revenue_micros',0);
end $$;


ALTER FUNCTION "tongs"."record_test_refill"("p_grant_id" "uuid", "p_user_id" "uuid", "p_operator_user_id" "uuid", "p_credit_units" bigint, "p_reason" "text", "p_idempotency_key" "text", "p_expires_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."record_unified_image_plan_membership"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_provider_plan_revision_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare
  op tongs.unified_visual_plan_operations%rowtype;
  seq tongs.workpiece_image_map_sequences%rowtype;
  plan tongs.image_map_revisions%rowtype;
  retained jsonb;
  result jsonb;
begin
  select * into op from tongs.unified_visual_plan_operations where operation_id=p_operation_id for update;
  if not found or op.operation_fingerprint<>p_operation_fingerprint then
    return jsonb_build_object('disposition','operation_identity_conflict');
  end if;
  
if op.owner_cost_attempt_id is not null then
    perform tongs._assert_owner_unified_visual_plan_persistence_authority(
      op.owner_cost_attempt_id,
      op.operation_id,
      op.operation_fingerprint,
      op.workspace_id,
      op.workpiece_id,
      op.created_by
    );
  elsif coalesce(auth.role(), '') = 'service_role' then
    raise exception 'owner-bound Unified Visual Plan operation required for service continuation'
      using errcode = '42501';
  elsif not tongs.has_workspace_role(op.workspace_id, 'editor') then
    raise exception 'workspace editor authority required' using errcode = '42501';
  end if;
  if op.child_membership_evidence_json ? 'image' then
    return jsonb_build_object('disposition','replay','revision_id',op.child_membership_evidence_json->'image'->>'final_plan_revision_id','membership_evidence',op.child_membership_evidence_json);
  end if;
  select * into seq from tongs.workpiece_image_map_sequences where workspace_id=op.workspace_id and workpiece_id=op.workpiece_id for update;
  if not found or seq.current_revision_id is distinct from p_provider_plan_revision_id then
    return jsonb_build_object('disposition','provider_child_not_current');
  end if;
  select * into plan from tongs.image_map_revisions where id=p_provider_plan_revision_id;
  select coalesce(jsonb_agg(jsonb_build_object('entry_id',entry->>'id','selected_asset_id',entry->>'selected_asset_id') order by entry->>'id'),'[]'::jsonb)
    into retained
    from jsonb_array_elements(coalesce(plan.document_json->'entries','[]'::jsonb)) entry
    where nullif(entry->>'selected_asset_id','') is not null;
  update tongs.unified_visual_plan_operations
    set child_membership_evidence_json=child_membership_evidence_json||jsonb_build_object('image',jsonb_build_object(
      'provider_plan_revision_id',p_provider_plan_revision_id,
      'final_plan_revision_id',p_provider_plan_revision_id,
      'provider_proposed',true,
      'creator_retained',retained,
      'creator_added','[]'::jsonb
    )),updated_at=now()
    where operation_id=op.operation_id
    returning child_membership_evidence_json into result;
  return jsonb_build_object('disposition','retained','revision_id',p_provider_plan_revision_id,'retained_count',jsonb_array_length(retained),'membership_evidence',result);
end;
$$;


ALTER FUNCTION "tongs"."record_unified_image_plan_membership"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_provider_plan_revision_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."record_unified_visual_plan_child"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_child_kind" "text", "p_revision_id" "uuid", "p_revision" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare op tongs.unified_visual_plan_operations%rowtype; expected_state text; next_state text; valid boolean:=false; child_hash text; child_empty boolean;
begin
  select * into op from tongs.unified_visual_plan_operations where operation_id=p_operation_id for update;
  if not found or op.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict'); end if;
  if op.owner_cost_attempt_id is not null then perform tongs._require_accounting_service_role(); elsif not tongs.has_workspace_role(op.workspace_id,'editor') then raise exception 'workspace editor authority required' using errcode='42501'; end if;
  if op.state='verified' then return jsonb_build_object('disposition','replay','operation',to_jsonb(op)); end if;
  if op.contract_version<>'forge.unified-visual-plan.v2' then return jsonb_build_object('disposition','historical_contract_immutable'); end if;
  if p_child_kind='image' then
    expected_state:='provider_completed';next_state:='image_plan_committed';
    select r.document_content_hash,coalesce(jsonb_array_length(r.document_json->'entries'),0)=0 into child_hash,child_empty
      from tongs.image_map_revisions r where r.id=p_revision_id and r.workspace_id=op.workspace_id and r.workpiece_id=op.workpiece_id and r.revision=p_revision
        and r.source_script_approval_id=op.script_approval_id and r.source_script_approval_revision=op.script_approval_revision and r.source_script_content_hash=op.script_content_hash;
  elsif p_child_kind='broll' then
    expected_state:='image_plan_committed';next_state:='broll_plan_committed';
    select r.content_hash,not exists(select 1 from tongs.broll_plan_beat_membership m where m.plan_revision_id=r.id) into child_hash,child_empty
      from tongs.broll_plan_revisions r where r.id=p_revision_id and r.workspace_id=op.workspace_id and r.workpiece_id=op.workpiece_id and r.revision=p_revision
        and r.script_approval_id=op.script_approval_id and r.script_approval_revision=op.script_approval_revision and r.script_content_hash=op.script_content_hash;
  elsif p_child_kind='reference_clip' then
    expected_state:='broll_plan_committed';next_state:='reference_plan_committed';
    select r.content_hash,not exists(select 1 from tongs.reference_clip_plan_membership m where m.plan_revision_id=r.id) into child_hash,child_empty
      from tongs.reference_clip_plan_revisions r where r.id=p_revision_id and r.workspace_id=op.workspace_id and r.workpiece_id=op.workpiece_id and r.revision=p_revision
        and r.script_approval_id=op.script_approval_id and r.script_approval_revision=op.script_approval_revision and r.script_content_hash=op.script_content_hash;
  elsif p_child_kind='reference_visual' then
    expected_state:='reference_plan_committed';next_state:='reference_visual_plan_committed';
    select r.content_hash,not exists(select 1 from tongs.reference_visual_plan_membership m where m.plan_revision_id=r.id) into child_hash,child_empty
      from tongs.reference_visual_plan_revisions r where r.id=p_revision_id and r.workspace_id=op.workspace_id and r.workpiece_id=op.workpiece_id and r.revision=p_revision
        and r.script_approval_id=op.script_approval_id and r.script_approval_revision=op.script_approval_revision and r.script_content_hash=op.script_content_hash;
  else return jsonb_build_object('disposition','invalid_child_kind'); end if;
  valid:=child_hash is not null;
  if (p_child_kind='image' and op.image_map_revision_id=p_revision_id) or (p_child_kind='broll' and op.broll_plan_revision_id=p_revision_id)
    or (p_child_kind='reference_clip' and op.reference_clip_plan_revision_id=p_revision_id) or (p_child_kind='reference_visual' and op.reference_visual_plan_revision_id=p_revision_id) then
    return jsonb_build_object('disposition','replay','operation',to_jsonb(op));
  end if;
  if op.state<>expected_state then return jsonb_build_object('disposition','stage_conflict','state',op.state); end if;
  if not valid then return jsonb_build_object('disposition','canonical_child_revision_required'); end if;
  update tongs.unified_visual_plan_operations set state=next_state,
    image_map_revision_id=case when p_child_kind='image' then p_revision_id else image_map_revision_id end,
    image_map_revision=case when p_child_kind='image' then p_revision else image_map_revision end,
    image_plan_content_hash=case when p_child_kind='image' then child_hash else image_plan_content_hash end,
    image_plan_empty=case when p_child_kind='image' then child_empty else image_plan_empty end,
    broll_plan_revision_id=case when p_child_kind='broll' then p_revision_id else broll_plan_revision_id end,
    broll_plan_revision=case when p_child_kind='broll' then p_revision else broll_plan_revision end,
    broll_plan_content_hash=case when p_child_kind='broll' then child_hash else broll_plan_content_hash end,
    broll_plan_empty=case when p_child_kind='broll' then child_empty else broll_plan_empty end,
    reference_clip_plan_revision_id=case when p_child_kind='reference_clip' then p_revision_id else reference_clip_plan_revision_id end,
    reference_clip_plan_revision=case when p_child_kind='reference_clip' then p_revision else reference_clip_plan_revision end,
    reference_clip_plan_content_hash=case when p_child_kind='reference_clip' then child_hash else reference_clip_plan_content_hash end,
    reference_clip_plan_empty=case when p_child_kind='reference_clip' then child_empty else reference_clip_plan_empty end,
    reference_visual_plan_revision_id=case when p_child_kind='reference_visual' then p_revision_id else reference_visual_plan_revision_id end,
    reference_visual_plan_revision=case when p_child_kind='reference_visual' then p_revision else reference_visual_plan_revision end,
    reference_visual_plan_content_hash=case when p_child_kind='reference_visual' then child_hash else reference_visual_plan_content_hash end,
    reference_visual_plan_empty=case when p_child_kind='reference_visual' then child_empty else reference_visual_plan_empty end,
    failed_stage=null,failure_code=null,failure_message=null,updated_at=now()
    where operation_id=p_operation_id returning * into op;
  return jsonb_build_object('disposition',next_state,'operation',to_jsonb(op));
end$$;


ALTER FUNCTION "tongs"."record_unified_visual_plan_child"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_child_kind" "text", "p_revision_id" "uuid", "p_revision" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."record_unified_visual_plan_provider_response"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_provider_response_json" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare op tongs.unified_visual_plan_operations%rowtype; h text;
begin
  select * into op from tongs.unified_visual_plan_operations where operation_id=p_operation_id for update;
  if not found or op.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict'); end if;
  if op.owner_cost_attempt_id is not null then perform tongs._require_accounting_service_role(); elsif not tongs.has_workspace_role(op.workspace_id,'editor') then raise exception 'workspace editor authority required' using errcode='42501'; end if;
  if op.state<>'pending' then return jsonb_build_object('disposition','replay','operation',to_jsonb(op)); end if;
  h:=encode(extensions.digest(convert_to(p_provider_response_json::text,'UTF8'),'sha256'),'hex');
  update tongs.unified_visual_plan_operations set state='provider_completed',provider_response_json=p_provider_response_json,provider_response_hash=h,
    failed_stage=null,failure_code=null,failure_message=null,updated_at=now() where operation_id=p_operation_id returning * into op;
  return jsonb_build_object('disposition','provider_completed','operation',to_jsonb(op));
end$$;


ALTER FUNCTION "tongs"."record_unified_visual_plan_provider_response"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_provider_response_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."recording_transition_take_completed"("p_recording_capture_authority_id" "uuid", "p_media_path" "text", "p_expected_media_revision" bigint, "p_expected_media_hash" "text", "p_expected_media_bytes" bigint, "p_expected_media_content_type" "text", "p_storage_bucket" "text", "p_storage_key" "text", "p_idempotency_key" "text", "p_completion_evidence" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $_$
declare a tongs.recording_capture_authorities%rowtype;v_user uuid:=auth.uid();v_media record;
  v_key text:=btrim(coalesce(p_idempotency_key,''));v_hash text:=lower(btrim(coalesce(p_expected_media_hash,'')));
  v_type text:=lower(btrim(coalesce(p_expected_media_content_type,'')));v_existing tongs.anvil_recording_completion_requests%rowtype;
  v_saved tongs.anvil_recording_completion_requests%rowtype;v_fingerprint text;
begin
  select * into a from tongs.recording_capture_authorities where id=p_recording_capture_authority_id;
  if not found then return jsonb_build_object('outcome','not_found','reason','capture_authority_not_found','completion',null);end if;
  if v_user is null or not tongs.has_workspace_role(a.workspace_id,'editor') then return jsonb_build_object('outcome','denied','reason','editor_required','completion',null);end if;
  if length(v_key) not between 8 and 200 or v_hash !~ '^[0-9a-f]{64}$' or p_expected_media_bytes<=0
    or p_completion_evidence is null or jsonb_typeof(p_completion_evidence)<>'object'
    or p_completion_evidence->>'recording_capture_authority_id' is distinct from a.id::text
    or coalesce((p_completion_evidence#>>'{artifact_validation,ok}')::boolean,false) is not true
    or lower(coalesce(p_completion_evidence#>>'{artifact_validation,sha256}',''))<>v_hash then
    return jsonb_build_object('outcome','conflict','reason','invalid_completion_evidence','completion',null);
  end if;
  select revision,lower(hash_value) hash_value,bytes,lower(content_type) content_type,storage_bucket,storage_key into v_media
    from tongs.workpiece_files where workpiece_id=a.workpiece_id and path=p_media_path;
  if not found then return jsonb_build_object('outcome','not_found','reason','media_not_found','completion',null);end if;
  if v_media.revision<>p_expected_media_revision or v_media.hash_value<>v_hash or v_media.bytes<>p_expected_media_bytes
    or v_media.content_type<>v_type or v_media.storage_bucket<>p_storage_bucket or v_media.storage_key<>p_storage_key then
    return jsonb_build_object('outcome','stale','reason','media_contract_mismatch','completion',null);end if;
  v_fingerprint:=md5(concat_ws('|',a.id,p_media_path,p_expected_media_revision,v_hash,p_expected_media_bytes,v_type,p_completion_evidence::text));
  select * into v_existing from tongs.anvil_recording_completion_requests where workspace_id=a.workspace_id and idempotency_key=v_key;
  if found then
    if v_existing.capture_authority_id=a.id and v_existing.request_fingerprint=v_fingerprint then return jsonb_build_object('outcome','duplicate','completion',to_jsonb(v_existing));end if;
    return jsonb_build_object('outcome','conflict','reason','idempotency_key_reused','completion',null);
  end if;
  insert into tongs.anvil_recording_completion_requests(workspace_id,workpiece_id,capture_authority_id,
    media_path,media_revision,media_hash,media_bytes,media_content_type,storage_bucket,storage_key,recording_session_id,
    idempotency_key,request_fingerprint,completion_evidence,completed_by)
  values(a.workspace_id,a.workpiece_id,a.id,p_media_path,p_expected_media_revision,v_hash,p_expected_media_bytes,v_type,
    p_storage_bucket,p_storage_key,a.recording_session_id,v_key,v_fingerprint,p_completion_evidence,v_user) returning * into v_saved;
  perform set_config('tongs.recording_authority_rpc','on',true);
  insert into tongs.workpiece_events(workpiece_id,event_name,payload,correlation_id,written_by_tool,written_by_tool_version,written_by_lane)
  values(a.workpiece_id,'take_completed',jsonb_build_object('authority_schema','forge.recording-completion.v1','completion_id',v_saved.id,
    'recording_capture_authority_id',a.id,'workspace_id',a.workspace_id,'file_path',p_media_path,'media_revision',p_expected_media_revision,'media_hash',v_hash),
    v_key,'recording',coalesce(p_completion_evidence->>'venue_version','unknown'),'forge-managed');
  return jsonb_build_object('outcome','saved','completion',to_jsonb(v_saved));
end;
$_$;


ALTER FUNCTION "tongs"."recording_transition_take_completed"("p_recording_capture_authority_id" "uuid", "p_media_path" "text", "p_expected_media_revision" bigint, "p_expected_media_hash" "text", "p_expected_media_bytes" bigint, "p_expected_media_content_type" "text", "p_storage_bucket" "text", "p_storage_key" "text", "p_idempotency_key" "text", "p_completion_evidence" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."recording_transition_take_completed_verified"("p_recording_capture_authority_id" "uuid", "p_media_path" "text", "p_expected_media_revision" bigint, "p_expected_media_hash" "text", "p_expected_media_bytes" bigint, "p_expected_media_content_type" "text", "p_storage_bucket" "text", "p_storage_key" "text", "p_duration_ms" bigint, "p_has_audio_stream" boolean, "p_has_video_stream" boolean, "p_probe_implementation" "text", "p_idempotency_key" "text", "p_completion_evidence" "jsonb", "p_completed_by" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $_$
declare
  a tongs.recording_capture_authorities%rowtype;
  v_media record;
  v_key text:=btrim(coalesce(p_idempotency_key,''));
  v_hash text:=lower(btrim(coalesce(p_expected_media_hash,'')));
  v_type text:=lower(btrim(coalesce(p_expected_media_content_type,'')));
  v_fingerprint text;
  v_existing tongs.anvil_recording_completion_requests%rowtype;
  v_verification tongs.recording_media_verification_receipts%rowtype;
  v_saved tongs.anvil_recording_completion_requests%rowtype;
  v_evidence jsonb;
begin
  select * into a from tongs.recording_capture_authorities where id=p_recording_capture_authority_id;
  if not found then return jsonb_build_object('outcome','not_found','reason','capture_authority_not_found','completion',null); end if;
  if not exists(select 1 from tongs.workspace_members where workspace_id=a.workspace_id and user_id=p_completed_by and role in ('owner','editor'))
     and not exists(select 1 from tongs.workspaces where id=a.workspace_id and created_by=p_completed_by) then
    return jsonb_build_object('outcome','denied','reason','editor_required','completion',null);
  end if;
  if length(v_key) not between 8 and 200 or v_hash !~ '^[0-9a-f]{64}$' or p_expected_media_bytes<=0
     or p_duration_ms<=0 or p_has_audio_stream is not true or length(btrim(coalesce(p_probe_implementation,'')))<2
     or (v_type like 'video/%' and p_has_video_stream is not true)
     or (v_type not like 'audio/%' and v_type not like 'video/%') then
    return jsonb_build_object('outcome','conflict','reason','canonical_media_verification_invalid','completion',null);
  end if;
  select revision,lower(hash_value) hash_value,bytes,lower(content_type) content_type,storage_bucket,storage_key into v_media
    from tongs.workpiece_files where workpiece_id=a.workpiece_id and path=p_media_path;
  if not found then return jsonb_build_object('outcome','not_found','reason','media_not_found','completion',null); end if;
  if v_media.revision<>p_expected_media_revision or v_media.hash_value<>v_hash or v_media.bytes<>p_expected_media_bytes
     or v_media.content_type<>v_type or v_media.storage_bucket<>p_storage_bucket or v_media.storage_key<>p_storage_key then
    return jsonb_build_object('outcome','stale','reason','media_contract_mismatch','completion',null);
  end if;
  v_evidence:=coalesce(p_completion_evidence,'{}'::jsonb) || jsonb_build_object('canonical_media_verification',jsonb_build_object(
    'source','trusted_tongs_storage_readback','sha256',v_hash,'bytes',p_expected_media_bytes,'content_type',v_type,
    'duration_ms',p_duration_ms,'has_audio_stream',p_has_audio_stream,'has_video_stream',p_has_video_stream,
    'probe_implementation',btrim(p_probe_implementation)));
  v_fingerprint:=md5(concat_ws('|',a.id,p_media_path,p_expected_media_revision,v_hash,p_expected_media_bytes,v_type,
    p_duration_ms,p_has_audio_stream,p_has_video_stream,btrim(p_probe_implementation),v_evidence::text));
  select * into v_existing from tongs.anvil_recording_completion_requests where workspace_id=a.workspace_id and idempotency_key=v_key;
  if found then
    if v_existing.capture_authority_id=a.id and v_existing.request_fingerprint=v_fingerprint and v_existing.media_verification_receipt_id is not null then
      return jsonb_build_object('outcome','duplicate','completion',to_jsonb(v_existing));
    end if;
    return jsonb_build_object('outcome','conflict','reason','idempotency_key_reused','completion',null);
  end if;
  insert into tongs.recording_media_verification_receipts(workspace_id,workpiece_id,recording_capture_authority_id,
    media_path,media_revision,media_hash,media_bytes,media_content_type,storage_bucket,storage_key,duration_ms,
    has_audio_stream,has_video_stream,probe_implementation,verification_evidence,verified_by)
  values(a.workspace_id,a.workpiece_id,a.id,p_media_path,p_expected_media_revision,v_hash,p_expected_media_bytes,v_type,
    p_storage_bucket,p_storage_key,p_duration_ms,p_has_audio_stream,p_has_video_stream,btrim(p_probe_implementation),
    v_evidence->'canonical_media_verification',p_completed_by) returning * into v_verification;
  insert into tongs.anvil_recording_completion_requests(workspace_id,workpiece_id,capture_authority_id,
    media_path,media_revision,media_hash,media_bytes,media_content_type,storage_bucket,storage_key,recording_session_id,
    idempotency_key,request_fingerprint,completion_evidence,completed_by,media_verification_receipt_id)
  values(a.workspace_id,a.workpiece_id,a.id,p_media_path,p_expected_media_revision,v_hash,p_expected_media_bytes,v_type,
    p_storage_bucket,p_storage_key,a.recording_session_id,v_key,v_fingerprint,v_evidence,p_completed_by,v_verification.id) returning * into v_saved;
  perform set_config('tongs.recording_authority_rpc','on',true);
  insert into tongs.workpiece_events(workpiece_id,event_name,payload,correlation_id,written_by_tool,written_by_tool_version,written_by_lane)
  values(a.workpiece_id,'take_completed',jsonb_build_object('authority_schema','forge.recording-completion.v2','completion_id',v_saved.id,
    'recording_capture_authority_id',a.id,'media_verification_receipt_id',v_verification.id,'workspace_id',a.workspace_id,
    'file_path',p_media_path,'media_revision',p_expected_media_revision,'media_hash',v_hash),v_key,'recording',
    coalesce(p_completion_evidence->>'venue_version','unknown'),'forge-managed');
  return jsonb_build_object('outcome','saved','completion',to_jsonb(v_saved),'media_verification',to_jsonb(v_verification));
end;
$_$;


ALTER FUNCTION "tongs"."recording_transition_take_completed_verified"("p_recording_capture_authority_id" "uuid", "p_media_path" "text", "p_expected_media_revision" bigint, "p_expected_media_hash" "text", "p_expected_media_bytes" bigint, "p_expected_media_content_type" "text", "p_storage_bucket" "text", "p_storage_key" "text", "p_duration_ms" bigint, "p_has_audio_stream" boolean, "p_has_video_stream" boolean, "p_probe_implementation" "text", "p_idempotency_key" "text", "p_completion_evidence" "jsonb", "p_completed_by" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."recording_transition_take_decision"("p_recording_capture_authority_id" "uuid", "p_completion_id" "uuid", "p_decision" "text", "p_idempotency_key" "text", "p_decision_evidence" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare a tongs.recording_capture_authorities%rowtype;c tongs.anvil_recording_completion_requests%rowtype;e tongs.anvil_capture_executions%rowtype;
begin
  select * into a from tongs.recording_capture_authorities where id=p_recording_capture_authority_id;
  select * into c from tongs.anvil_recording_completion_requests where id=p_completion_id and capture_authority_id=a.id;
  if a.id is null or c.id is null then return jsonb_build_object('outcome','not_found','reason','capture_completion_mismatch');end if;
  if p_decision_evidence is null or jsonb_typeof(p_decision_evidence)<>'object'
    or p_decision_evidence->>'decision' is distinct from p_decision
    or p_decision_evidence->>'completion_id' is distinct from c.id::text
    or p_decision_evidence->>'recording_capture_authority_id' is distinct from a.id::text then
    return jsonb_build_object('outcome','conflict','reason','invalid_decision_evidence');
  end if;
  select * into e from tongs.anvil_capture_executions where recording_capture_authority_id=a.id;
  if a.venue='anvil' and e.execution_id is null then return jsonb_build_object('outcome','conflict','reason','venue_execution_missing');end if;
  if p_decision='keep' then return tongs.anvil_transition_take_kept(a.workspace_id,a.workpiece_id,e.execution_id,c.id,p_idempotency_key,
    p_decision_evidence||jsonb_build_object('schema','anvil.take-decision.v1','capture_session_id',e.execution_id));end if;
  if p_decision='discard' then return tongs.anvil_transition_take_discarded(a.workspace_id,a.workpiece_id,e.execution_id,c.id,p_idempotency_key,
    p_decision_evidence||jsonb_build_object('schema','anvil.take-decision.v1','capture_session_id',e.execution_id));end if;
  return jsonb_build_object('outcome','conflict','reason','decision_invalid');
end;
$$;


ALTER FUNCTION "tongs"."recording_transition_take_decision"("p_recording_capture_authority_id" "uuid", "p_completion_id" "uuid", "p_decision" "text", "p_idempotency_key" "text", "p_decision_evidence" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."recover_expired_unified_visual_plan_attempt"("p_operation_id" "text", "p_operation_fingerprint" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  op tongs.unified_visual_plan_operations%rowtype;
  binding tongs.openai_text_funding_bindings%rowtype;
  attempt_event tongs.funding_reservation_events%rowtype;
  hold tongs.openai_text_failure_exposure_holds%rowtype;
  expense_micros bigint;
  evidence jsonb;
  event_id uuid;
  v_event_key text;
  existing_event tongs.unified_visual_plan_transport_recovery_events%rowtype;
begin
  perform tongs._require_pricing_service_role();
  perform pg_advisory_xact_lock(hashtextextended('unified-visual-plan-transport:'||btrim(p_operation_id),0));
  select * into op from tongs.unified_visual_plan_operations
    where operation_id=btrim(p_operation_id) for update;
  select * into binding from tongs.openai_text_funding_bindings
    where operation_id=btrim(p_operation_id) and route_code='visual.unified_plan';
  if op.operation_id is null or op.operation_fingerprint is distinct from p_operation_fingerprint
    or binding.reservation_id is null or binding.model<>'gpt-5.6-luna'
    or binding.maximum_attempts<>1 then
    raise exception 'invalid unified Visual Plan recovery identity' using errcode='22023';
  end if;
  v_event_key:='visual-unified-transport:'||binding.reservation_id::text;
  select * into existing_event from tongs.unified_visual_plan_transport_recovery_events
    where unified_visual_plan_transport_recovery_events.event_key=v_event_key;
  if found or op.state='submission_unknown' then
    return jsonb_build_object('disposition','submission_unknown_replay','operation',to_jsonb(op),
      'recovery_event_id',existing_event.id,'automatic_resubmission_allowed',false);
  end if;
  if op.state in('verified','failed') then
    return jsonb_build_object('disposition','terminal_operation','operation',to_jsonb(op));
  end if;
  if op.state<>'pending' or op.provider_response_json is not null or op.receipt_json is not null
    or exists(select 1 from tongs.openai_text_provider_captures c where c.reservation_id=binding.reservation_id)
    or exists(select 1 from tongs.openai_text_usage_evidence u where u.reservation_id=binding.reservation_id)
    or exists(select 1 from tongs.openai_text_persisted_results r where r.reservation_id=binding.reservation_id) then
    raise exception 'captured or persisted provider evidence requires authoritative reconciliation' using errcode='P0001';
  end if;
  select * into attempt_event from tongs.funding_reservation_events
    where reservation_id=binding.reservation_id
    order by sequence desc limit 1;
  if attempt_event.id is null or attempt_event.event_type<>'provider_attempt_shadowed'
    or attempt_event.provider_attempt_key is null then
    raise exception 'provider attempt lease not found' using errcode='P0002';
  end if;
  if attempt_event.lease_expires_at is null or attempt_event.lease_expires_at>now() then
    return jsonb_build_object('disposition','attempt_in_progress','lease_expires_at',attempt_event.lease_expires_at);
  end if;
  select * into hold from tongs.openai_text_failure_exposure_holds
    where reservation_id=binding.reservation_id and attempt_key=attempt_event.provider_attempt_key;
  if hold.id is null then raise exception 'failure exposure hold not found' using errcode='P0002'; end if;
  select coalesce(sum(amount_micros),0) into expense_micros from tongs.supplier_expenses
    where reservation_id=binding.reservation_id and coalesce(amount_micros,0)>0;
  if expense_micros<>0 then
    raise exception 'supplier expense evidence requires authoritative reconciliation' using errcode='P0001';
  end if;
  evidence:=jsonb_build_object(
    'route_code','visual.unified_plan','operation_id',op.operation_id,
    'reservation_id',binding.reservation_id,'attempt_key',attempt_event.provider_attempt_key,
    'lease_expires_at',attempt_event.lease_expires_at,'recovered_at',now(),
    'transmission_status','unknown','transmitted',null,
    'reason','attempt lease expired without a durable provider outcome',
    'automatic_resubmission_allowed',false,'provider_capture_count',0,
    'usage_evidence_count',0,'canonical_result_count',0,'supplier_expense_micros',0
  );
  perform tongs.close_openai_text_failure_exposure(binding.reservation_id,
    attempt_event.provider_attempt_key,'unresolved',null,evidence);
  perform tongs.mark_submission_unknown(binding.reservation_id,
    attempt_event.provider_attempt_key||':submission-unknown',attempt_event.provider_attempt_key,evidence);
  perform tongs.record_paid_operation_aggregate_outcome(binding.reservation_id,
    attempt_event.provider_attempt_key||':aggregate-ambiguous','ambiguous',null,null,evidence);
  update tongs.unified_visual_plan_operations
  set state='submission_unknown',failed_stage='provider_transport',
      failure_code='visual_plan_submission_unknown',
      failure_message='Provider submission may have occurred; automatic resubmission is prohibited pending authoritative reconciliation.',
      updated_at=now()
  where operation_id=op.operation_id returning * into op;
  event_id:=extensions.uuid_generate_v5(binding.reservation_id,'unified-visual-plan-expired-attempt-recovery-v1');
  insert into tongs.unified_visual_plan_transport_recovery_events(
    id,event_key,operation_id,reservation_id,failure_exposure_hold_id,event_type,evidence_json
  ) values(event_id,v_event_key,op.operation_id,binding.reservation_id,hold.id,
    'expired_attempt_submission_unknown',evidence)
  on conflict(event_key) do nothing;
  return jsonb_build_object('disposition','submission_unknown','operation',to_jsonb(op),
    'recovery_event_id',event_id,'automatic_resubmission_allowed',false,'evidence',evidence);
end $$;


ALTER FUNCTION "tongs"."recover_expired_unified_visual_plan_attempt"("p_operation_id" "text", "p_operation_fingerprint" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."recover_expired_unified_visual_plan_attempt"("p_operation_id" "text", "p_operation_fingerprint" "text") IS 'Service-only replay-safe stale-attempt recovery. It records ambiguity and prohibits provider replay; it does not infer non-transmission from missing captures.';



CREATE OR REPLACE FUNCTION "tongs"."reference_visual_candidate_assets_available"("p_candidate_revision_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
 select not exists(select 1 from tongs.reference_visual_candidate_revisions c join lateral(select c.asset_id as asset_id where c.asset_id is not null union all select sm.asset_id from tongs.reference_visual_sequence_membership sm where sm.sequence_revision_id=c.sequence_revision_id)member on true join tongs.reference_visual_asset_restriction_sequences rs on rs.asset_id=member.asset_id join tongs.reference_visual_asset_restriction_revisions rr on rr.id=rs.current_restriction_revision_id where c.id=p_candidate_revision_id and rr.availability_state in('disputed','disabled'))
$$;


ALTER FUNCTION "tongs"."reference_visual_candidate_assets_available"("p_candidate_revision_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."reference_visual_candidate_current_for_plan"("p_candidate_revision_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
 select exists(
   select 1 from tongs.reference_visual_candidate_revisions c
   join tongs.reference_visual_plan_sequences ps
     on ps.workspace_id=c.workspace_id and ps.workpiece_id=c.workpiece_id
   join tongs.reference_visual_plan_membership pm
     on pm.plan_revision_id=ps.current_plan_revision_id
    and pm.opportunity_id=c.opportunity_id and pm.opportunity_revision_id=c.opportunity_revision_id
   where c.id=p_candidate_revision_id
     and c.source_set_revision_id=tongs.reference_visual_current_source_set(c.workspace_id,c.workpiece_id,c.opportunity_id)
     and c.created_at>coalesce((select max(r.reset_at) from tongs.reference_visual_evidence_resets r
       where r.workspace_id=c.workspace_id and r.workpiece_id=c.workpiece_id
         and r.opportunity_id=c.opportunity_id),'-infinity'::timestamptz)
     and (c.recipe_revision_id is null or
       tongs.reference_visual_recipe_current_for_source_set(c.recipe_revision_id,c.source_set_revision_id))
     and (c.source_use_revision_id is null or
       tongs.reference_visual_source_use_current_for_source_set(c.source_use_revision_id,c.source_set_revision_id))
     and case when c.source_use_revision_id is not null and exists(
       select 1 from tongs.reference_visual_source_use_revisions u
       where u.id=c.source_use_revision_id and u.use_classification='facts_data_only'
     ) then c.rights_declaration_revision_id is null
     else tongs.reference_visual_rights_current_for_source_set(c.rights_declaration_revision_id,c.source_set_revision_id) end
 )
$$;


ALTER FUNCTION "tongs"."reference_visual_candidate_current_for_plan"("p_candidate_revision_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."reference_visual_candidate_release_ready"("p_candidate_revision_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
 select coalesce((select tongs.reference_visual_candidate_assets_available(c.id) and case when u.use_classification='facts_data_only' then u.creator_confirmed and c.rights_declaration_revision_id is null else rd.rights_status is not null and rd.rights_status<>'rights_unresolved'end from tongs.reference_visual_candidate_revisions c left join tongs.reference_visual_source_use_revisions u on u.id=c.source_use_revision_id left join tongs.reference_visual_rights_declaration_revisions rd on rd.id=c.rights_declaration_revision_id where c.id=p_candidate_revision_id),false)
$$;


ALTER FUNCTION "tongs"."reference_visual_candidate_release_ready"("p_candidate_revision_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."reference_visual_current_source_set"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_opportunity_id" "uuid") RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
 select ss.id
 from tongs.reference_visual_plan_sequences ps
 join lateral(
   select x.id from tongs.reference_visual_source_set_revisions x
   where x.workspace_id=ps.workspace_id and x.workpiece_id=ps.workpiece_id
     and x.opportunity_id=p_opportunity_id and x.plan_revision_id=ps.current_plan_revision_id
   order by x.revision desc limit 1
 ) ss on true
 where ps.workspace_id=p_workspace_id and ps.workpiece_id=p_workpiece_id
$$;


ALTER FUNCTION "tongs"."reference_visual_current_source_set"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_opportunity_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."reference_visual_evidence_claim_fingerprint"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_opportunity_id" "uuid", "p_source_set_member_id" "uuid", "p_source_revision_id" "uuid", "p_workpiece_source_link_revision_id" "uuid", "p_document_locator" "jsonb", "p_raw_excerpt" "text", "p_numeric_value" numeric, "p_unit" "text", "p_evidence_role" "text", "p_category" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'tongs', 'extensions'
    AS $$
  select encode(extensions.digest(convert_to(jsonb_build_object(
    'workspace_id',p_workspace_id,
    'workpiece_id',p_workpiece_id,
    'opportunity_id',p_opportunity_id,
    'source_set_member_id',p_source_set_member_id,
    'source_revision_id',p_source_revision_id,
    'workpiece_source_link_revision_id',p_workpiece_source_link_revision_id,
    'document_locator',coalesce(p_document_locator,'{}'::jsonb),
    'raw_excerpt',regexp_replace(btrim(coalesce(p_raw_excerpt,'')),E'\\s+',' ','g'),
    'numeric_value',p_numeric_value,
    'unit',lower(regexp_replace(btrim(coalesce(p_unit,'')),E'\\s+',' ','g')),
    'evidence_role',btrim(coalesce(p_evidence_role,'')),
    'category',btrim(coalesce(p_category,''))
  )::text,'UTF8'),'sha256'),'hex')
$$;


ALTER FUNCTION "tongs"."reference_visual_evidence_claim_fingerprint"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_opportunity_id" "uuid", "p_source_set_member_id" "uuid", "p_source_revision_id" "uuid", "p_workpiece_source_link_revision_id" "uuid", "p_document_locator" "jsonb", "p_raw_excerpt" "text", "p_numeric_value" numeric, "p_unit" "text", "p_evidence_role" "text", "p_category" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."reference_visual_evidence_current_for_source_set"("p_evidence_revision_id" "uuid", "p_source_set_revision_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
 select exists(
   select 1
   from tongs.reference_visual_evidence_revisions e
   join tongs.reference_visual_evidence_sequences es
     on es.workspace_id=e.workspace_id and es.workpiece_id=e.workpiece_id
    and es.evidence_id=e.evidence_id and es.current_evidence_revision_id=e.id
   join tongs.reference_visual_evidence_claims claim
     on claim.workspace_id=e.workspace_id and claim.workpiece_id=e.workpiece_id
    and claim.opportunity_id=e.opportunity_id and claim.canonical_evidence_id=e.evidence_id
   join tongs.reference_visual_source_set_revisions ss on ss.id=p_source_set_revision_id
   join tongs.reference_visual_source_set_members active
     on active.source_set_revision_id=ss.id
    and active.source_revision_id=e.source_revision_id
    and active.workpiece_source_link_revision_id=e.workpiece_source_link_revision_id
   where e.id=p_evidence_revision_id and e.workspace_id=ss.workspace_id
     and e.workpiece_id=ss.workpiece_id and e.opportunity_id=ss.opportunity_id
     and e.confirmation_state='creator_confirmed'
     and claim.claim_fingerprint=tongs.reference_visual_evidence_claim_fingerprint(
       e.workspace_id,e.workpiece_id,e.opportunity_id,e.source_set_member_id,
       e.source_revision_id,e.workpiece_source_link_revision_id,e.document_locator_json,
       e.raw_excerpt,e.numeric_value,e.unit,e.evidence_role,e.category)
     and greatest(claim.created_at,coalesce((select max(a.activated_at)
       from tongs.reference_visual_evidence_claim_activations a
       where a.canonical_claim_id=claim.claim_id),'-infinity'::timestamptz))
       >coalesce((select max(r.reset_at) from tongs.reference_visual_evidence_resets r
         where r.workspace_id=e.workspace_id and r.workpiece_id=e.workpiece_id
           and r.opportunity_id=e.opportunity_id),'-infinity'::timestamptz)
 )
$$;


ALTER FUNCTION "tongs"."reference_visual_evidence_current_for_source_set"("p_evidence_revision_id" "uuid", "p_source_set_revision_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."reference_visual_recipe_current_for_source_set"("p_recipe_revision_id" "uuid", "p_source_set_revision_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
 select exists(
   select 1 from tongs.reference_visual_recipe_revisions r
   join tongs.reference_visual_recipe_sequences rs
     on rs.workspace_id=r.workspace_id and rs.workpiece_id=r.workpiece_id
    and rs.opportunity_id=r.opportunity_id and rs.current_recipe_revision_id=r.id
   join tongs.reference_visual_source_set_revisions ss
     on ss.id=p_source_set_revision_id and ss.workspace_id=r.workspace_id
    and ss.workpiece_id=r.workpiece_id and ss.opportunity_id=r.opportunity_id
   where r.id=p_recipe_revision_id
     and not exists(select 1 from unnest(r.evidence_revision_ids) e(id)
       where not tongs.reference_visual_evidence_current_for_source_set(e.id,ss.id))
 )
$$;


ALTER FUNCTION "tongs"."reference_visual_recipe_current_for_source_set"("p_recipe_revision_id" "uuid", "p_source_set_revision_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."reference_visual_rights_current_for_source_set"("p_rights_revision_id" "uuid", "p_source_set_revision_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
 select exists(
   select 1 from tongs.reference_visual_rights_declaration_revisions r
   join tongs.reference_visual_rights_declaration_sequences rs
     on rs.workspace_id=r.workspace_id and rs.workpiece_id=r.workpiece_id
    and rs.opportunity_id=r.opportunity_id and rs.current_declaration_revision_id=r.id
   where r.id=p_rights_revision_id and r.source_set_revision_id=p_source_set_revision_id
     and r.rights_status<>'rights_unresolved'
     and (r.expires_at is null or r.expires_at>now())
 )
$$;


ALTER FUNCTION "tongs"."reference_visual_rights_current_for_source_set"("p_rights_revision_id" "uuid", "p_source_set_revision_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."reference_visual_source_use_current_for_source_set"("p_source_use_revision_id" "uuid", "p_source_set_revision_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
 select exists(
   select 1 from tongs.reference_visual_source_use_revisions u
   join tongs.reference_visual_source_use_sequences us
     on us.workspace_id=u.workspace_id and us.workpiece_id=u.workpiece_id
    and us.opportunity_id=u.opportunity_id and us.current_use_revision_id=u.id
   join tongs.reference_visual_source_set_revisions ss on ss.id=p_source_set_revision_id
   join tongs.reference_visual_source_set_members primary_source
     on primary_source.source_set_revision_id=ss.id and primary_source.ordinal=1
    and primary_source.source_revision_id=u.source_revision_id
    and primary_source.workpiece_source_link_revision_id=u.workpiece_source_link_revision_id
   where u.id=p_source_use_revision_id and u.workspace_id=ss.workspace_id
     and u.workpiece_id=ss.workpiece_id and u.opportunity_id=ss.opportunity_id
     and u.creator_confirmed
 )
$$;


ALTER FUNCTION "tongs"."reference_visual_source_use_current_for_source_set"("p_source_use_revision_id" "uuid", "p_source_set_revision_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."refresh_credential_lifecycle_alerts"("p_as_of" timestamp with time zone, "p_actor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_row tongs.credential_lifecycle_records%rowtype;
  v_target text;
  v_urgency text;
  v_sequence integer;
  v_created integer := 0;
  v_transitioned integer := 0;
  v_now timestamptz := coalesce(p_as_of, transaction_timestamp());
begin
  perform tongs._require_credential_lifecycle_writer();
  if p_actor_id is null or not tongs.is_platform_operator(p_actor_id) then
    raise exception 'platform operator required' using errcode='42501';
  end if;
  for v_row in
    select * from tongs.credential_lifecycle_records
    where expires_at is not null and lifecycle_status not in ('revoked','disabled')
    order by credential_id for update
  loop
    v_target := case
      when v_now >= v_row.expires_at then 'expired'
      when v_now >= v_row.rotation_due_at and v_row.lifecycle_status='active' then 'rotation_due'
      else v_row.lifecycle_status end;
    if v_target <> v_row.lifecycle_status then
      select coalesce(max(event_sequence),0)+1 into v_sequence
        from tongs.credential_lifecycle_events where credential_id=v_row.credential_id;
      update tongs.credential_lifecycle_records set lifecycle_status=v_target,updated_at=v_now
        where credential_id=v_row.credential_id;
      insert into tongs.credential_lifecycle_events(
        event_id,credential_id,event_sequence,event_key,from_status,to_status,event_type,actor_id,evidence_json,occurred_at
      ) values (
        gen_random_uuid(),v_row.credential_id,v_sequence,
        'deadline:'||v_row.credential_id::text||':'||v_target||':'||extract(epoch from v_row.expires_at)::bigint,
        v_row.lifecycle_status,v_target,'deadline_reached',p_actor_id,
        jsonb_build_object('deadline_at',v_row.expires_at,'evaluated_at',v_now),v_now
      );
      v_transitioned := v_transitioned + 1;
    end if;
    v_urgency := case
      when v_now >= v_row.expires_at then 'expired'
      when v_row.expires_at-v_now <= interval '1 day' then 'critical'
      when v_row.expires_at-v_now <= interval '3 days' then 'urgent'
      when v_now >= v_row.rotation_due_at then 'warning'
      else null end;
    if v_urgency is not null then
      insert into tongs.credential_lifecycle_alerts(
        alert_id,credential_id,alert_key,urgency,provider,credential_purpose,
        configuration_variable_name,affected_capability,deadline_at,recommended_action,created_at
      ) values (
        gen_random_uuid(),v_row.credential_id,
        'credential-alert:'||v_row.credential_id::text||':'||v_urgency||':'||extract(epoch from v_row.expires_at)::bigint,
        v_urgency,v_row.provider,v_row.credential_purpose,v_row.configuration_variable_name,
        v_row.affected_capability,v_row.expires_at,
        case when v_urgency='expired'
          then 'Credential expired. Keep the capability fail-closed; provision and verify a replacement before use.'
          else 'Create a replacement at the provider, update the canonical production variable, verify isolation and readiness, then revoke the old credential.' end,
        v_now
      ) on conflict (credential_id,urgency,deadline_at) do nothing;
      if found then v_created := v_created + 1; end if;
    end if;
  end loop;
  return jsonb_build_object('evaluated_at',v_now,'records_transitioned',v_transitioned,'alerts_created',v_created);
end;
$$;


ALTER FUNCTION "tongs"."refresh_credential_lifecycle_alerts"("p_as_of" timestamp with time zone, "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."refresh_owner_hearth_tail_expiry"("p_owner_user_id" "uuid", "p_workspace_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare tail tongs.owner_hearth_tail_authorizations%rowtype; period_row record; seq integer; appended integer:=0;
begin
 perform tongs._require_pricing_service_role();
 select * into tail from tongs.owner_hearth_tail_authorizations
 where owner_user_id=p_owner_user_id and workspace_id=p_workspace_id order by created_at desc limit 1;
 if not found then return jsonb_build_object('tail_authorization_found',false,'expired_periods',0); end if;
 for period_row in select p.* from tongs.owner_hearth_tail_periods p where p.tail_authorization_id=tail.id and p.coverage_end<=now()
 loop
  select coalesce(max(sequence),0)+1 into seq from tongs.owner_hearth_tail_events where tail_authorization_id=tail.id;
  insert into tongs.owner_hearth_tail_events(id,tail_authorization_id,sequence,event_key,event_type,evidence_json)
  values(gen_random_uuid(),tail.id,seq,'owner-hearth-tail:'||tail.id::text||':expired:'||period_row.id::text,'funding_expired',
   jsonb_build_object('tail_period_id',period_row.id,'coverage_end',period_row.coverage_end,'content_preserved',true,'costs_continue',true))
  on conflict(event_key) do nothing;
  if found then appended:=appended+1; end if;
  select coalesce(max(sequence),0)+1 into seq from tongs.owner_hearth_tail_events where tail_authorization_id=tail.id;
  insert into tongs.owner_hearth_tail_events(id,tail_authorization_id,sequence,event_key,event_type,evidence_json)
  values(gen_random_uuid(),tail.id,seq,'owner-hearth-tail:'||tail.id::text||':continuing:'||period_row.id::text,'continuing_obligation',
   jsonb_build_object('tail_period_id',period_row.id,'coverage_end',period_row.coverage_end,'replacement_funding_required',true,
    'canonical_content_preserved',true,'provider_evidence_preserved',true,'reported_cost_is_not_zero',true))
  on conflict(event_key) do nothing;
 end loop;
 return jsonb_build_object('tail_authorization_found',true,'expiry_events_appended',appended,
  'expired_periods',(select count(*) from tongs.owner_hearth_tail_periods p where p.tail_authorization_id=tail.id and p.coverage_end<=now()));
end $$;


ALTER FUNCTION "tongs"."refresh_owner_hearth_tail_expiry"("p_owner_user_id" "uuid", "p_workspace_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "tongs"."bellows_segments" (
    "id" "text" NOT NULL,
    "session_id" "text" NOT NULL,
    "track_id" "text" NOT NULL,
    "participant_id" "text" NOT NULL,
    "workspace_id" "uuid" NOT NULL,
    "recorder_generation" integer NOT NULL,
    "boundary_reason" "text" NOT NULL,
    "mime_type" "text" NOT NULL,
    "capture_profile" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "started_at" timestamp with time zone NOT NULL,
    "ended_at" timestamp with time zone,
    "start_offset_ms" bigint NOT NULL,
    "duration_ms" bigint,
    "expected_part_count" integer,
    "byte_length" bigint,
    "sha256" "text",
    "storage_bucket" "text",
    "storage_key" "text",
    "integrity_state" "text" DEFAULT 'pending'::"text" NOT NULL,
    "verified_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "bellows_segments_boundary_reason_check" CHECK (("boundary_reason" = ANY (ARRAY['initial'::"text", 'manual_stop'::"text", 'page_recovery'::"text", 'device_restart'::"text", 'permission_reset'::"text", 'capture_error'::"text"]))),
    CONSTRAINT "bellows_segments_byte_length_check" CHECK ((("byte_length" IS NULL) OR ("byte_length" >= 0))),
    CONSTRAINT "bellows_segments_capture_profile_check" CHECK (("jsonb_typeof"("capture_profile") = 'object'::"text")),
    CONSTRAINT "bellows_segments_check" CHECK ((("integrity_state" = 'verified'::"text") = ("verified_at" IS NOT NULL))),
    CONSTRAINT "bellows_segments_duration_ms_check" CHECK ((("duration_ms" IS NULL) OR ("duration_ms" >= 0))),
    CONSTRAINT "bellows_segments_expected_part_count_check" CHECK ((("expected_part_count" IS NULL) OR ("expected_part_count" >= 0))),
    CONSTRAINT "bellows_segments_integrity_state_check" CHECK (("integrity_state" = ANY (ARRAY['pending'::"text", 'verified'::"text", 'failed'::"text", 'unverifiable'::"text", 'missing'::"text"]))),
    CONSTRAINT "bellows_segments_recorder_generation_check" CHECK (("recorder_generation" > 0)),
    CONSTRAINT "bellows_segments_start_offset_ms_check" CHECK (("start_offset_ms" >= 0))
);


ALTER TABLE "tongs"."bellows_segments" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."register_bellows_capture_segment"("p_session_id" "text", "p_participant_id" "text", "p_track_id" "text", "p_segment_id" "text", "p_recorder_generation" integer, "p_boundary_reason" "text", "p_mime_type" "text", "p_capture_profile" "jsonb", "p_started_at" timestamp with time zone, "p_start_offset_ms" bigint) RETURNS "tongs"."bellows_segments"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public', 'auth'
    AS $$
declare v_session tongs.bellows_sessions; v_existing tongs.bellows_segments; v_result tongs.bellows_segments;
begin
  select * into v_session from tongs.bellows_sessions where id = p_session_id for update;
  if not found then raise exception 'bellows_session_not_found'; end if;
  if not tongs.has_workspace_role(v_session.workspace_id, 'editor') then raise exception 'bellows_capture_forbidden'; end if;
  insert into tongs.bellows_session_participants(id,session_id,workspace_id,user_id,role_code)
    values(p_participant_id,p_session_id,v_session.workspace_id,auth.uid(),'S1') on conflict (id) do nothing;
  insert into tongs.bellows_tracks(id,session_id,participant_id,workspace_id,kind)
    values(p_track_id,p_session_id,p_participant_id,v_session.workspace_id,'audio_video') on conflict (id) do nothing;
  select * into v_existing from tongs.bellows_segments where id = p_segment_id;
  if found then
    if v_existing.session_id <> p_session_id or v_existing.track_id <> p_track_id
      or v_existing.recorder_generation <> p_recorder_generation or v_existing.mime_type <> p_mime_type then
      raise exception 'bellows_segment_identity_conflict';
    end if;
    return v_existing;
  end if;
  insert into tongs.bellows_segments(id,session_id,track_id,participant_id,workspace_id,recorder_generation,boundary_reason,mime_type,capture_profile,started_at,start_offset_ms)
    values(p_segment_id,p_session_id,p_track_id,p_participant_id,v_session.workspace_id,p_recorder_generation,p_boundary_reason,p_mime_type,coalesce(p_capture_profile,'{}'),p_started_at,p_start_offset_ms)
    returning * into v_result;
  return v_result;
end $$;


ALTER FUNCTION "tongs"."register_bellows_capture_segment"("p_session_id" "text", "p_participant_id" "text", "p_track_id" "text", "p_segment_id" "text", "p_recorder_generation" integer, "p_boundary_reason" "text", "p_mime_type" "text", "p_capture_profile" "jsonb", "p_started_at" timestamp with time zone, "p_start_offset_ms" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."register_bellows_upload_part"("p_session_id" "text", "p_participant_id" "text", "p_segment_id" "text", "p_part_id" "text", "p_sequence_number" integer, "p_byte_length" bigint, "p_sha256" "text", "p_storage_key" "text") RETURNS "tongs"."bellows_upload_parts"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public', 'auth'
    AS $$
declare v_segment tongs.bellows_segments; v_existing tongs.bellows_upload_parts; v_result tongs.bellows_upload_parts;
begin
  select * into v_segment from tongs.bellows_segments where id=p_segment_id and session_id=p_session_id;
  if not found then raise exception 'bellows_segment_not_found'; end if;
  if v_segment.participant_id<>p_participant_id then raise exception 'bellows_segment_participant_conflict'; end if;
  perform tongs.bellows_assert_capture_participant(p_session_id,p_participant_id);
  select * into v_existing from tongs.bellows_upload_parts where id=p_part_id;
  if found then
    if v_existing.segment_id<>p_segment_id or v_existing.participant_id<>p_participant_id
      or v_existing.sequence_number<>p_sequence_number or v_existing.byte_length<>p_byte_length
      or v_existing.sha256<>lower(p_sha256) or v_existing.storage_key<>p_storage_key then
      raise exception 'bellows_upload_part_identity_conflict';
    end if;
    return v_existing;
  end if;
  insert into tongs.bellows_upload_parts(id,segment_id,session_id,participant_id,workspace_id,sequence_number,byte_length,sha256,storage_key)
    values(p_part_id,p_segment_id,p_session_id,p_participant_id,v_segment.workspace_id,p_sequence_number,p_byte_length,lower(p_sha256),p_storage_key)
    returning * into v_result;
  return v_result;
end $$;


ALTER FUNCTION "tongs"."register_bellows_upload_part"("p_session_id" "text", "p_participant_id" "text", "p_segment_id" "text", "p_part_id" "text", "p_sequence_number" integer, "p_byte_length" bigint, "p_sha256" "text", "p_storage_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."register_credential_lifecycle"("p_credential_id" "uuid", "p_provider" "text", "p_credential_purpose" "text", "p_configuration_variable_name" "text", "p_affected_capability" "text", "p_financial_environment" "text", "p_runtime_environment" "text", "p_credential_identity_hash" "text", "p_provider_created_at" timestamp with time zone, "p_activated_at" timestamp with time zone, "p_expires_at" timestamp with time zone, "p_rotation_lead" interval, "p_lifecycle_status" "text", "p_activation_deployment_id" "text", "p_activation_deployment_sha" "text", "p_verification_json" "jsonb", "p_metadata_json" "jsonb", "p_actor_id" "uuid", "p_event_key" "text", "p_occurred_at" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_existing tongs.credential_lifecycle_records%rowtype;
  v_lead interval := coalesce(p_rotation_lead, interval '7 days');
  v_metadata jsonb := coalesce(p_metadata_json, '{}'::jsonb);
  v_verification jsonb := coalesce(p_verification_json, '{}'::jsonb);
  v_rotation_due timestamptz := case when p_expires_at is null then null else p_expires_at - v_lead end;
  v_now timestamptz := coalesce(p_occurred_at, transaction_timestamp());
begin
  perform tongs._require_credential_lifecycle_writer();
  if p_credential_id is null or p_provider is null or p_credential_purpose is null
     or p_configuration_variable_name is null or p_affected_capability is null
     or p_actor_id is null or not tongs.is_platform_operator(p_actor_id)
     or p_event_key is null or not tongs._credential_lifecycle_metadata_safe(v_metadata)
     or not tongs._credential_lifecycle_metadata_safe(v_verification) then
    raise exception 'invalid credential lifecycle registration' using errcode = '22023';
  end if;
  if p_lifecycle_status not in ('planned','active') then
    raise exception 'credential registration status must be planned or active' using errcode = '22023';
  end if;
  if p_expires_at is not null and p_expires_at <= v_now then
    raise exception 'new credential expiration must be in the future' using errcode = '22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('credential-lifecycle:'||p_credential_id::text, 0));
  select * into v_existing from tongs.credential_lifecycle_records where credential_id = p_credential_id;
  if found then
    if v_existing.provider <> btrim(p_provider)
       or v_existing.credential_purpose <> btrim(p_credential_purpose)
       or v_existing.configuration_variable_name <> btrim(p_configuration_variable_name)
       or v_existing.credential_identity_hash is distinct from lower(p_credential_identity_hash)
       or v_existing.expires_at is distinct from p_expires_at then
      raise exception 'credential lifecycle registration conflict' using errcode = '23505';
    end if;
    return to_jsonb(v_existing) - 'credential_identity_hash' || jsonb_build_object('replay', true);
  end if;

  insert into tongs.credential_lifecycle_records(
    credential_id,provider,credential_purpose,configuration_variable_name,affected_capability,
    financial_environment,runtime_environment,credential_identity_hash,provider_created_at,
    activated_at,expires_at,rotation_lead,rotation_due_at,lifecycle_status,
    activation_deployment_id,activation_deployment_sha,last_verification_at,
    config_presence_verified_at,route_configuration_verified_at,
    non_paid_readiness_verified_at,bounded_smoke_performed_at,smoke_operation_id,
    metadata_json,created_by,created_at,updated_at
  ) values (
    p_credential_id,btrim(p_provider),btrim(p_credential_purpose),btrim(p_configuration_variable_name),
    btrim(p_affected_capability),p_financial_environment,p_runtime_environment,
    lower(p_credential_identity_hash),p_provider_created_at,p_activated_at,p_expires_at,v_lead,
    v_rotation_due,p_lifecycle_status,nullif(btrim(coalesce(p_activation_deployment_id,'')),''),
    lower(nullif(btrim(coalesce(p_activation_deployment_sha,'')),'')),v_now,
    case when coalesce((v_verification->>'config_presence_verified')::boolean,false) then v_now end,
    case when coalesce((v_verification->>'route_configuration_verified')::boolean,false) then v_now end,
    case when coalesce((v_verification->>'non_paid_readiness_verified')::boolean,false) then v_now end,
    case when coalesce((v_verification->>'bounded_smoke_performed')::boolean,false) then v_now end,
    nullif(v_verification->>'smoke_operation_id',''),v_metadata,p_actor_id,v_now,v_now
  ) returning * into v_existing;
  insert into tongs.credential_lifecycle_events(
    event_id,credential_id,event_sequence,event_key,from_status,to_status,event_type,actor_id,evidence_json,occurred_at
  ) values (
    gen_random_uuid(),p_credential_id,1,btrim(p_event_key),null,p_lifecycle_status,
    'registered',p_actor_id,v_verification,v_now
  );
  return to_jsonb(v_existing) - 'credential_identity_hash' || jsonb_build_object('replay', false);
end;
$$;


ALTER FUNCTION "tongs"."register_credential_lifecycle"("p_credential_id" "uuid", "p_provider" "text", "p_credential_purpose" "text", "p_configuration_variable_name" "text", "p_affected_capability" "text", "p_financial_environment" "text", "p_runtime_environment" "text", "p_credential_identity_hash" "text", "p_provider_created_at" timestamp with time zone, "p_activated_at" timestamp with time zone, "p_expires_at" timestamp with time zone, "p_rotation_lead" interval, "p_lifecycle_status" "text", "p_activation_deployment_id" "text", "p_activation_deployment_sha" "text", "p_verification_json" "jsonb", "p_metadata_json" "jsonb", "p_actor_id" "uuid", "p_event_key" "text", "p_occurred_at" timestamp with time zone) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "tongs"."assets" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "workspace_id" "uuid" NOT NULL,
    "workpiece_id" "uuid",
    "path" "text" NOT NULL,
    "mime_type" "text" NOT NULL,
    "bytes" bigint NOT NULL,
    "storage_bucket" "text" DEFAULT 'forge-workpieces'::"text" NOT NULL,
    "storage_key" "text" NOT NULL,
    "provider" "text" NOT NULL,
    "provider_request_id" "text",
    "request_id" "text",
    "prompt" "text",
    "created_by" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "asset_kind" "text" DEFAULT 'thumbnail_image'::"text" NOT NULL,
    "status" "text" DEFAULT 'ready'::"text" NOT NULL,
    "metadata_json" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "supersedes_asset_id" "uuid",
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "variant_kind" "text" DEFAULT 'original'::"text" NOT NULL,
    "source_asset_id" "uuid",
    "width" integer,
    "height" integer,
    "cache_control" "text",
    "variant_version" integer DEFAULT 1 NOT NULL,
    "operation_id" "text",
    "operation_fingerprint" "text",
    "reuse_identity" "text",
    "content_hash" "text",
    "failure_code" "text",
    "failure_message" "text",
    "reference_committed_at" timestamp with time zone,
    "ready_at" timestamp with time zone,
    "failed_at" timestamp with time zone,
    "asset_scope" "text" DEFAULT 'workpiece'::"text" NOT NULL,
    "workspace_reuse_policy" "text" DEFAULT 'not_applicable'::"text" NOT NULL,
    "provenance_classification" "text" DEFAULT 'canonical_native'::"text" NOT NULL,
    "provenance_json" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    CONSTRAINT "assets_asset_kind_check" CHECK (("asset_kind" = ANY (ARRAY['thumbnail_image'::"text", 'thumbnail_composite'::"text", 'image_map_json'::"text", 'image_map_candidate_image'::"text", 'broll_candidate_video'::"text", 'broll_candidate_poster'::"text", 'broll_generation_reference'::"text", 'reference_clip_video'::"text", 'reference_clip_poster'::"text", 'reference_visual_image'::"text", 'source_desk_audio'::"text", 'source_desk_video'::"text", 'hammer_audio_master'::"text", 'hammer_video_master'::"text"]))),
    CONSTRAINT "assets_bytes_check" CHECK (("bytes" >= 0)),
    CONSTRAINT "assets_content_hash_check" CHECK ((("content_hash" IS NULL) OR ("content_hash" ~ '^[0-9a-f]{64}$'::"text"))),
    CONSTRAINT "assets_failure_diagnostics_check" CHECK (((("status" = 'failed'::"text") AND ("failure_code" IS NOT NULL) AND ("btrim"("failure_code") <> ''::"text") AND ("failure_message" IS NOT NULL) AND ("btrim"("failure_message") <> ''::"text") AND ("failed_at" IS NOT NULL)) OR (("status" <> 'failed'::"text") AND ("failure_code" IS NULL) AND ("failure_message" IS NULL) AND ("failed_at" IS NULL)))),
    CONSTRAINT "assets_kind_shape_check" CHECK (((("asset_kind" = ANY (ARRAY['thumbnail_image'::"text", 'thumbnail_composite'::"text", 'broll_candidate_poster'::"text", 'broll_generation_reference'::"text", 'reference_clip_poster'::"text", 'reference_visual_image'::"text"])) AND ("mime_type" ~~ 'image/%'::"text")) OR (("asset_kind" = 'image_map_json'::"text") AND ("mime_type" = 'application/json'::"text") AND ("prompt" IS NULL)) OR (("asset_kind" = 'image_map_candidate_image'::"text") AND ("mime_type" ~~ 'image/%'::"text") AND (("prompt" IS NOT NULL) OR ("provider" = 'creator_upload'::"text"))) OR (("asset_kind" = ANY (ARRAY['broll_candidate_video'::"text", 'reference_clip_video'::"text", 'source_desk_video'::"text", 'hammer_video_master'::"text"])) AND ("mime_type" ~~ 'video/%'::"text")) OR (("asset_kind" = ANY (ARRAY['source_desk_audio'::"text", 'hammer_audio_master'::"text"])) AND ("mime_type" ~~ 'audio/%'::"text")))),
    CONSTRAINT "assets_mime_type_check" CHECK (("mime_type" <> ''::"text")),
    CONSTRAINT "assets_operation_fingerprint_check" CHECK (((("operation_id" IS NULL) AND ("operation_fingerprint" IS NULL)) OR (("operation_id" IS NOT NULL) AND ("operation_fingerprint" ~ '^[0-9a-f]{64}$'::"text")))),
    CONSTRAINT "assets_operation_id_check" CHECK ((("operation_id" IS NULL) OR ("btrim"("operation_id") <> ''::"text"))),
    CONSTRAINT "assets_path_check" CHECK ((("path" <> ''::"text") AND ("path" !~ '^/'::"text") AND ("path" !~ '\\.\\.'::"text"))),
    CONSTRAINT "assets_prompt_nullable_nonempty_check" CHECK ((("prompt" IS NULL) OR ("btrim"("prompt") <> ''::"text"))),
    CONSTRAINT "assets_provenance_classification_check" CHECK (("provenance_classification" = ANY (ARRAY['canonical_native'::"text", 'legacy_resolved'::"text", 'legacy_unresolved'::"text", 'conflicting_evidence'::"text"]))),
    CONSTRAINT "assets_provenance_json_check" CHECK (("jsonb_typeof"("provenance_json") = 'object'::"text")),
    CONSTRAINT "assets_provider_check" CHECK (("provider" <> ''::"text")),
    CONSTRAINT "assets_ready_timestamp_check" CHECK (((("status" = 'ready'::"text") AND ("ready_at" IS NOT NULL)) OR ("status" <> 'ready'::"text"))),
    CONSTRAINT "assets_reuse_identity_check" CHECK ((("reuse_identity" IS NULL) OR ("reuse_identity" ~ '^[0-9a-f]{64}$'::"text"))),
    CONSTRAINT "assets_scope_shape_check" CHECK (((("asset_scope" = 'workpiece'::"text") AND ("workpiece_id" IS NOT NULL) AND ("workspace_reuse_policy" = 'not_applicable'::"text")) OR (("asset_scope" = 'workspace'::"text") AND ("workpiece_id" IS NULL) AND ("workspace_reuse_policy" = ANY (ARRAY['allowed'::"text", 'restricted'::"text"]))))),
    CONSTRAINT "assets_source_desk_duration_check" CHECK ((("asset_kind" <> ALL (ARRAY['source_desk_audio'::"text", 'source_desk_video'::"text"])) OR (("status" <> 'ready'::"text") OR (("jsonb_typeof"(("metadata_json" -> 'duration_ms'::"text")) = 'number'::"text") AND ((("metadata_json" ->> 'duration_ms'::"text"))::bigint > 0))))),
    CONSTRAINT "assets_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'ready'::"text", 'failed'::"text", 'superseded'::"text"]))),
    CONSTRAINT "assets_storage_key_check" CHECK ((("storage_key" <> ''::"text") AND ("storage_key" !~ '^/'::"text"))),
    CONSTRAINT "assets_thumbnail_ready_hash_check" CHECK ((("asset_kind" <> ALL (ARRAY['thumbnail_image'::"text", 'thumbnail_composite'::"text"])) OR ("status" <> 'ready'::"text") OR ("content_hash" IS NOT NULL))),
    CONSTRAINT "assets_variant_dims_check" CHECK (((("width" IS NULL) OR ("width" > 0)) AND (("height" IS NULL) OR ("height" > 0)))),
    CONSTRAINT "assets_variant_kind_check" CHECK (("variant_kind" = ANY (ARRAY['original'::"text", 'preview'::"text", 'thumb'::"text"]))),
    CONSTRAINT "assets_variant_version_check" CHECK (("variant_version" >= 1))
);


ALTER TABLE "tongs"."assets" OWNER TO "postgres";


COMMENT ON COLUMN "tongs"."assets"."path" IS 'Presentation/workpiece metadata only. A path never selects canonical asset identity.';



COMMENT ON COLUMN "tongs"."assets"."asset_scope" IS 'Canonical ownership discriminator. workpiece requires workpiece_id; workspace requires null workpiece_id. Null never means unknown.';



COMMENT ON COLUMN "tongs"."assets"."workspace_reuse_policy" IS 'Explicit policy for using workspace-scoped media in a workpiece. It is never inferred from null workpiece ownership.';



COMMENT ON COLUMN "tongs"."assets"."provenance_classification" IS 'Canonical identity provenance. Unresolved legacy references belong in asset_legacy_reference_evidence, not fabricated asset rows.';



CREATE OR REPLACE FUNCTION "tongs"."register_source_desk_timed_asset"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_path" "text", "p_mime_type" "text", "p_bytes" bigint, "p_storage_bucket" "text", "p_storage_key" "text", "p_content_hash" "text", "p_duration_ms" bigint, "p_width" integer, "p_height" integer, "p_operation_id" "text", "p_actor_id" "uuid", "p_source_asset_id" "uuid" DEFAULT NULL::"uuid") RETURNS "tongs"."assets"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $_$
declare v_kind text; v_asset tongs.assets%rowtype;
begin
  if auth.role()<>'service_role' then raise exception 'Source Desk asset registration requires service authority' using errcode='42501'; end if;
  if not exists(select 1 from tongs.episodes where id=p_workpiece_id and workspace_id=p_workspace_id) then raise exception 'Workpiece identity mismatch' using errcode='22023'; end if;
  v_kind:=case when p_mime_type like 'audio/%' then 'source_desk_audio' when p_mime_type like 'video/%' then 'source_desk_video' else null end;
  if v_kind is null or p_duration_ms<=0 or p_bytes<=0 or p_content_hash!~'^[0-9a-f]{64}$' then raise exception 'Invalid verified timed-media evidence' using errcode='22023'; end if;
  insert into tongs.assets(workspace_id,workpiece_id,path,mime_type,bytes,storage_bucket,storage_key,provider,request_id,
    created_by,asset_kind,status,metadata_json,width,height,operation_id,operation_fingerprint,content_hash,ready_at)
  values(p_workspace_id,p_workpiece_id,p_path,p_mime_type,p_bytes,p_storage_bucket,p_storage_key,'creator-upload',p_operation_id,
    p_actor_id,v_kind,'ready',jsonb_strip_nulls(jsonb_build_object('duration_ms',p_duration_ms,'inspection_authority','tongs-service.v1','source_asset_id',p_source_asset_id)),
    p_width,p_height,p_operation_id,p_content_hash,p_content_hash,now())
  on conflict(storage_bucket,storage_key) do update set
    path=excluded.path,mime_type=excluded.mime_type,bytes=excluded.bytes,asset_kind=excluded.asset_kind,status='ready',
    metadata_json=excluded.metadata_json,width=excluded.width,height=excluded.height,operation_id=excluded.operation_id,
    operation_fingerprint=excluded.operation_fingerprint,content_hash=excluded.content_hash,ready_at=excluded.ready_at
  returning * into v_asset;
  return v_asset;
end $_$;


