CREATE OR REPLACE FUNCTION "tongs"."release_ai_credit_reservation"("p_user_id" "uuid", "p_reservation_id" "uuid", "p_release_id" "uuid", "p_reason" "text", "p_metadata_json" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_account tongs.ai_credits%rowtype;
  v_reservation tongs.ai_credit_reservations%rowtype;
  v_existing tongs.ai_credit_reservation_events%rowtype;
  v_remaining bigint;
begin
  select * into v_account from tongs.ai_credits where user_id = p_user_id for update;
  if not found then raise exception 'AI-credit account not found' using errcode = 'P0002'; end if;
  select * into v_reservation from tongs.ai_credit_reservations where id = p_reservation_id and user_id = p_user_id for update;
  if not found then raise exception 'reservation not found' using errcode = 'P0002'; end if;
  select * into v_existing from tongs.ai_credit_reservation_events where reservation_id = p_reservation_id and idempotency_key = p_release_id;
  if found then return jsonb_build_object('event', to_jsonb(v_existing), 'replay', true); end if;
  select greatest(0, v_reservation.amount - coalesce(sum(amount), 0)) into v_remaining
    from tongs.ai_credit_reservation_events where reservation_id = p_reservation_id and event_type in ('settled', 'released');
  insert into tongs.ai_credit_reservation_events (
    reservation_id, user_id, event_type, amount, idempotency_key, reason, actor_id, metadata_json
  ) values (p_reservation_id, p_user_id, 'released', v_remaining, p_release_id,
    coalesce(nullif(btrim(p_reason), ''), 'reservation_released'), p_user_id, coalesce(p_metadata_json, '{}'::jsonb))
  returning * into v_existing;
  return jsonb_build_object('event', to_jsonb(v_existing), 'replay', false,
    'settled_balance', v_account.token_balance, 'reserved_balance', tongs._ai_credit_active_holds(p_user_id),
    'available_balance', v_account.token_balance - tongs._ai_credit_active_holds(p_user_id));
end;
$$;


ALTER FUNCTION "tongs"."release_ai_credit_reservation"("p_user_id" "uuid", "p_reservation_id" "uuid", "p_release_id" "uuid", "p_reason" "text", "p_metadata_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."release_operation"("p_reservation_id" "uuid", "p_release_key" "text", "p_reason" "text", "p_evidence_json" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_reservation tongs.funding_reservations%rowtype;
  v_existing tongs.funding_reservation_events%rowtype;
  v_state text;
  v_sequence integer;
begin
  perform tongs._require_pricing_service_role();
  if length(btrim(coalesce(p_release_key, ''))) < 8
     or nullif(btrim(coalesce(p_reason, '')), '') is null
     or jsonb_typeof(coalesce(p_evidence_json, 'null'::jsonb)) <> 'object' then
    raise exception 'invalid reservation release' using errcode = '22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('provider-attempt:' || p_reservation_id::text, 0));
  select * into v_reservation from tongs.funding_reservations where id = p_reservation_id for update;
  if not found then raise exception 'funding reservation not found' using errcode = 'P0002'; end if;
  select * into v_existing from tongs.funding_reservation_events where event_key = btrim(p_release_key);
  if found then return jsonb_build_object('reservation_id', p_reservation_id, 'state', 'released', 'replay', true); end if;
  v_state := tongs._funding_reservation_state(p_reservation_id);
  if v_state = 'submission_unknown' then
    raise exception 'ambiguous submission reservation requires reconciliation' using errcode = 'P0001';
  elsif v_state = 'settled' then
    raise exception 'settled reservation cannot be released' using errcode = 'P0001';
  elsif v_state = 'released' then
    raise exception 'release replay key conflict' using errcode = '23505';
  end if;
  select coalesce(max(sequence),0)+1 into v_sequence from tongs.funding_reservation_events
    where reservation_id = p_reservation_id;
  insert into tongs.funding_reservation_events(
    id, reservation_id, sequence, event_type, event_key, evidence_json
  ) values (gen_random_uuid(), p_reservation_id, v_sequence, 'released', btrim(p_release_key),
    coalesce(p_evidence_json, '{}'::jsonb) || jsonb_build_object('reason', btrim(p_reason)));
  return jsonb_build_object('reservation_id', p_reservation_id, 'state', 'released',
    'replay', false, 'funds_released', true);
end;
$$;


ALTER FUNCTION "tongs"."release_operation"("p_reservation_id" "uuid", "p_release_key" "text", "p_reason" "text", "p_evidence_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."release_owner_hearth_definitive_nonbillable_rejection"("p_reservation_id" "uuid", "p_event_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $_$
declare op tongs.owner_hearth_operation_authorizations%rowtype; authz tongs.owner_hearth_authorizations%rowtype;
 funding_latest tongs.funding_reservation_events%rowtype; provider_failure tongs.funding_reservation_events%rowtype;
 failure_hold tongs.openai_text_failure_exposure_holds%rowtype; failure_latest tongs.openai_text_failure_exposure_events%rowtype;
 aggregate_binding tongs.paid_operation_aggregate_bindings%rowtype; aggregate_latest tongs.restricted_beta_exposure_events%rowtype;
 detail jsonb:='{}'::jsonb; provider_code text; provider_type text; provider_status integer; nextseq integer;
 direct_expense_count bigint; nonzero_expense_count bigint; capture_count bigint;
begin
 perform tongs._require_pricing_service_role();
 if p_reservation_id is null or length(btrim(coalesce(p_event_key,'')))<8 then
  raise exception 'invalid definitive rejection release' using errcode='22023'; end if;
 perform pg_advisory_xact_lock(hashtextextended('owner-hearth-definitive-rejection:'||p_reservation_id::text,0));
 select * into op from tongs.owner_hearth_operation_authorizations where reservation_id=p_reservation_id;
 select * into authz from tongs.owner_hearth_authorizations where id=op.authorization_id;
 if op.id is null or authz.authorization_kind<>'compatibility_batch' then
  raise exception 'owner compatibility operation required' using errcode='42501'; end if;
 select * into funding_latest from tongs.funding_reservation_events where reservation_id=p_reservation_id order by sequence desc limit 1;
 select * into provider_failure from tongs.funding_reservation_events
  where reservation_id=p_reservation_id and event_type='provider_failure_recorded' order by sequence desc limit 1;
 if funding_latest.event_type<>'settled' or coalesce(funding_latest.customer_charge_micros,0)<>0
    or coalesce(funding_latest.wholesale_spend_micros,0)<>0 or provider_failure.id is null
    or provider_failure.failure_class<>'provider_failure' then
  return jsonb_build_object('released',false,'reason','not_zero_charge_provider_rejection'); end if;
 provider_status:=case when (provider_failure.evidence_json->>'status')~'^[0-9]+$'
   then (provider_failure.evidence_json->>'status')::integer else null end;
 begin detail:=coalesce(nullif(provider_failure.evidence_json->>'detail',''),'{}')::jsonb;
 exception when others then detail:='{}'::jsonb; end;
 provider_code:=coalesce(detail#>>'{error,code}','');
 provider_type:=coalesce(detail#>>'{error,type}','');
 if provider_status<>429 or not (provider_code in ('credit_balance_exhausted','insufficient_quota')
   or provider_type in ('credit_balance_exhausted','insufficient_quota')) then
  return jsonb_build_object('released',false,'reason','provider_rejection_not_proven_nonbillable',
   'provider_status',provider_status,'provider_code',nullif(provider_code,'')); end if;
 select count(*),count(*) filter(where coalesce(amount_micros,0)>0) into direct_expense_count,nonzero_expense_count
 from tongs.supplier_expenses where reservation_id=p_reservation_id and provider='openai';
 select count(*) into capture_count from tongs.openai_text_usage_evidence where reservation_id=p_reservation_id;
 if nonzero_expense_count>0 or capture_count>0 then
  return jsonb_build_object('released',false,'reason','supplier_usage_or_nonzero_expense_exists'); end if;
 select * into failure_hold from tongs.openai_text_failure_exposure_holds where reservation_id=p_reservation_id order by created_at desc limit 1;
 if failure_hold.id is not null then
  select * into failure_latest from tongs.openai_text_failure_exposure_events where hold_id=failure_hold.id order by sequence desc limit 1;
  if failure_latest.event_type<>'success_released' then
   if failure_latest.event_type<>'failure_realized' or failure_latest.actual_supplier_cost_micros is not null then
    raise exception 'failure exposure is not eligible for definitive rejection correction' using errcode='P0001'; end if;
   select coalesce(max(sequence),0)+1 into nextseq from tongs.openai_text_failure_exposure_events where hold_id=failure_hold.id;
   insert into tongs.openai_text_failure_exposure_events(id,hold_id,sequence,event_key,event_type,actual_supplier_cost_micros,evidence_json)
   values(extensions.uuid_generate_v5(failure_hold.id,btrim(p_event_key)||':failure-release'),failure_hold.id,nextseq,
    btrim(p_event_key)||':failure-release','success_released',0,jsonb_build_object(
     'definitive_nonbillable_rejection',true,'provider_status',provider_status,'provider_code',coalesce(nullif(provider_code,''),provider_type),
     'provider_cost_reconciled_authoritative',false,'supplier_expense_evidence_preserved',direct_expense_count>0));
  end if;
 end if;
 select * into aggregate_binding from tongs.paid_operation_aggregate_bindings where reservation_id=p_reservation_id;
 if aggregate_binding.hold_id is not null then
  select * into aggregate_latest from tongs.restricted_beta_exposure_events where hold_id=aggregate_binding.hold_id order by sequence desc limit 1;
  if aggregate_latest.event_type<>'released' then
   select coalesce(max(sequence),0)+1 into nextseq from tongs.restricted_beta_exposure_events where hold_id=aggregate_binding.hold_id;
   insert into tongs.restricted_beta_exposure_events(id,hold_id,sequence,event_key,event_type,supplier_obligation_micros,
    customer_funding_delta_micros,forge_loss_delta_micros,remaining_exposure_micros,exposure_adjustment_micros,evidence_json)
   values(extensions.uuid_generate_v5(aggregate_binding.hold_id,btrim(p_event_key)||':aggregate-release'),aggregate_binding.hold_id,nextseq,
    btrim(p_event_key)||':aggregate-release','released',0,0,0,0,
    -(aggregate_binding.supplier_exposure_ceiling_micros+aggregate_binding.supporting_exposure_ceiling_micros),jsonb_build_object(
     'transmitted',true,'definitive_nonbillable_rejection',true,'provider_status',provider_status,
     'provider_code',coalesce(nullif(provider_code,''),provider_type),'provider_cost_reconciled_authoritative',false,
     'supplier_expense_evidence_preserved',direct_expense_count>0));
  end if;
 end if;
 return jsonb_build_object('released',true,'replay',failure_latest.event_type='success_released' and aggregate_latest.event_type='released',
  'provider_request_id',provider_failure.evidence_json->>'provider_reference','provider_status',provider_status,
  'provider_code',coalesce(nullif(provider_code,''),provider_type),'supplier_expense_evidence_status',
  case when direct_expense_count>0 then 'preserved_unresolved' else 'none' end,'provider_cost_reconciled_authoritative',false);
end $_$;


ALTER FUNCTION "tongs"."release_owner_hearth_definitive_nonbillable_rejection"("p_reservation_id" "uuid", "p_event_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."release_owner_hearth_definitive_nonbillable_rejection"("p_reservation_id" "uuid", "p_event_key" "text") IS 'Releases owner compatibility admission after a proven OpenAI credit-balance rejection without claiming authoritative cost reconciliation.';



CREATE OR REPLACE FUNCTION "tongs"."relieve_failed_customer_operation"("p_relief_id" "uuid", "p_reservation_id" "uuid", "p_relief_key" "text", "p_reason" "text", "p_evidence_json" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_res tongs.funding_reservations%rowtype;
  v_event tongs.funding_reservation_events%rowtype;
  v_existing tongs.customer_operation_reliefs%rowtype;
  v_consumption_id uuid;
  v_units bigint;
  v_charge bigint;
  v_user uuid;
  v_workspace uuid;
  v_payload jsonb;
begin
  perform tongs._require_accounting_service_role();
  perform pg_advisory_xact_lock(hashtextextended('customer-relief:' || p_reservation_id::text, 0));
  select * into v_existing from tongs.customer_operation_reliefs
  where reservation_id = p_reservation_id or relief_key = btrim(p_relief_key) limit 1;
  if found then
    return jsonb_build_object(
      'relief_id',v_existing.id,'replay',true,
      'customer_credit_micros',v_existing.customer_credit_micros
    );
  end if;
  select * into v_res from tongs.funding_reservations
  where id = p_reservation_id for update;
  if not found then raise exception 'funding reservation not found' using errcode = 'P0002'; end if;
  select * into v_event from tongs.funding_reservation_events
  where reservation_id = p_reservation_id and event_type = 'settled'
  order by sequence desc limit 1;
  if not found or coalesce(v_event.customer_charge_micros,0) = 0 then
    return jsonb_build_object(
      'relief_id',null,'replay',false,'customer_credit_micros',0,
      'reason','no_customer_charge'
    );
  end if;
  if v_res.funding_source_type = 'customer_deposit' then
    select id,user_id,credit_units_consumed
      into v_consumption_id,v_user,v_units
    from tongs.customer_deposit_consumptions
    where deposit_id = v_res.funding_source_id and operation_id = v_res.operation_id;
  elsif v_res.funding_source_type = 'paid_allowance' then
    select id,user_id,entitlement_units_consumed
      into v_consumption_id,v_user,v_units
    from tongs.paid_allowance_consumptions
    where allowance_grant_id = v_res.funding_source_id and operation_id = v_res.operation_id;
  elsif v_res.funding_source_type = 'beta_grant' then
    select consumption.id,consumption.user_id,consumption.credit_units_consumed,grant_row.workspace_id
      into v_consumption_id,v_user,v_units,v_workspace
    from tongs.beta_credit_consumptions consumption
    join tongs.beta_credit_grants grant_row on grant_row.id = consumption.grant_id
    where consumption.grant_id = v_res.funding_source_id
      and consumption.operation_id = v_res.operation_id;
  else
    raise exception 'customer relief requires customer funding source' using errcode = '22023';
  end if;
  if v_consumption_id is null then
    raise exception 'customer consumption not found for relief' using errcode = 'P0002';
  end if;
  v_charge := v_event.customer_charge_micros;
  v_payload := jsonb_build_object(
    'reservation_id',p_reservation_id,'original_consumption_id',v_consumption_id,
    'customer_credit_micros',v_charge,'restored_units',v_units,
    'reason',btrim(p_reason)
  );
  perform tongs._create_accounting_event(
    p_relief_id,'operation-relief:' || btrim(p_relief_key),
    'customer_operation_relieved',v_res.funding_environment,'forge_operation',
    v_res.operation_id,v_res.currency,v_user,v_workspace,null,v_payload,now()
  );
  insert into tongs.customer_operation_reliefs(
    id,reservation_id,relief_key,funding_source_type,funding_source_id,
    original_consumption_id,currency,customer_credit_micros,restored_units,
    revenue_reversal_micros,reason,journal_event_id,evidence_json,relieved_at
  ) values (
    p_relief_id,p_reservation_id,btrim(p_relief_key),v_res.funding_source_type,
    v_res.funding_source_id,v_consumption_id,v_res.currency,v_charge,v_units,
    v_charge,btrim(p_reason),p_relief_id,coalesce(p_evidence_json,'{}'::jsonb),now()
  ) returning * into v_existing;
  insert into tongs.accounting_journal_entries(
    event_id,line_number,account_code,user_id,workspace_id,deposit_id,
    allowance_grant_id,beta_credit_grant_id,currency,amount_micros
  ) values
    (p_relief_id,1,'service_revenue_reversal',v_user,v_workspace,
      case when v_res.funding_source_type='customer_deposit' then v_res.funding_source_id end,
      case when v_res.funding_source_type='paid_allowance' then v_res.funding_source_id end,
      case when v_res.funding_source_type='beta_grant' then v_res.funding_source_id end,
      v_res.currency,v_charge),
    (p_relief_id,2,
      case v_res.funding_source_type
        when 'customer_deposit' then 'customer_prepaid_liability'
        when 'paid_allowance' then 'allowance_deferred_liability'
        else 'beta_credit_deferred_value' end,
      v_user,v_workspace,
      case when v_res.funding_source_type='customer_deposit' then v_res.funding_source_id end,
      case when v_res.funding_source_type='paid_allowance' then v_res.funding_source_id end,
      case when v_res.funding_source_type='beta_grant' then v_res.funding_source_id end,
      v_res.currency,-v_charge);
  insert into tongs.accounting_journal_entries(
    event_id,line_number,account_code,user_id,workspace_id,deposit_id,
    allowance_grant_id,beta_credit_grant_id,unit_kind,quantity_delta
  ) values (
    p_relief_id,3,
    case v_res.funding_source_type
      when 'customer_deposit' then 'live_customer_credits'
      when 'paid_allowance' then 'allowance_entitlement_units'
      else 'beta_forge_credit_units' end,
    v_user,v_workspace,
    case when v_res.funding_source_type='customer_deposit' then v_res.funding_source_id end,
    case when v_res.funding_source_type='paid_allowance' then v_res.funding_source_id end,
    case when v_res.funding_source_type='beta_grant' then v_res.funding_source_id end,
    'forge_credit',v_units
  );
  perform tongs._assert_accounting_event_balanced(p_relief_id);
  return jsonb_build_object(
    'relief_id',v_existing.id,'replay',false,'customer_credit_micros',v_charge,
    'restored_units',v_units,'revenue_reversal_micros',v_charge
  );
end $$;


ALTER FUNCTION "tongs"."relieve_failed_customer_operation"("p_relief_id" "uuid", "p_reservation_id" "uuid", "p_relief_key" "text", "p_reason" "text", "p_evidence_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."remove_team_member"("p_team_id" "uuid", "p_user_id" "uuid") RETURNS TABLE("removed" boolean, "team_id" "uuid", "user_id" "uuid", "old_team_role" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare
  v_user uuid;
  v_org_id uuid;
  v_old_role text;
  v_removed boolean := false;
  v_event_timestamp timestamptz := now();
begin
  v_user := auth.uid();
  if v_user is null then
    raise exception 'Not authenticated'
      using errcode = '42501';
  end if;

  if p_team_id is null then
    raise exception 'team_id is required'
      using errcode = '22023';
  end if;

  if p_user_id is null then
    raise exception 'user_id is required'
      using errcode = '22023';
  end if;

  select t.org_id
  into v_org_id
  from tongs.teams t
  where t.id = p_team_id;

  if v_org_id is null then
    raise exception 'Team not found'
      using errcode = 'P0002';
  end if;

  perform tongs.assert_org_role(v_org_id, 'admin');

  delete from tongs.team_members tm
  where tm.team_id = p_team_id
    and tm.user_id = p_user_id
  returning tm.team_role into v_old_role;

  v_removed := found;

  if v_removed and to_regclass('tongs.hearth_interaction_events') is not null then
    insert into tongs.hearth_interaction_events (
      user_id,
      workspace_id,
      episode_id,
      event_type,
      payload
    )
    values (
      v_user,
      null,
      null,
      'team.member.remove',
      jsonb_build_object(
        'org_id', v_org_id,
        'team_id', p_team_id,
        'actor_user_id', v_user,
        'target_user_id', p_user_id,
        'old_role', v_old_role,
        'timestamp', v_event_timestamp
      )
    );
  end if;

  return query
  select v_removed, p_team_id, p_user_id, v_old_role;
end;
$$;


ALTER FUNCTION "tongs"."remove_team_member"("p_team_id" "uuid", "p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."remove_workspace_member"("p_workspace_id" "uuid", "p_user_id" "uuid") RETURNS TABLE("removed" boolean, "workspace_id" "uuid", "user_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare
  v_user uuid;
  v_target_role text;
  v_is_creator boolean;
begin
  v_user := auth.uid();
  if v_user is null then
    raise exception 'not_authenticated'
      using errcode = '42501';
  end if;

  if p_workspace_id is null or p_user_id is null then
    raise exception 'workspace_id_and_user_id_required'
      using errcode = '22023';
  end if;

  perform tongs.assert_workspace_role(p_workspace_id, 'admin');

  select
    wm.role,
    (w.created_by = wm.user_id)
  into
    v_target_role,
    v_is_creator
  from tongs.workspace_members wm
  join tongs.workspaces w
    on w.id = wm.workspace_id
  where wm.workspace_id = p_workspace_id
    and wm.user_id = p_user_id
  for update;

  if not found then
    return query select false, p_workspace_id, p_user_id;
    return;
  end if;

  if v_is_creator then
    raise exception 'creator_remove_blocked'
      using errcode = '42501';
  end if;

  if v_target_role = 'owner' then
    raise exception 'owner_remove_blocked'
      using errcode = '42501';
  end if;

  delete from tongs.workspace_members wm
  where wm.workspace_id = p_workspace_id
    and wm.user_id = p_user_id;

  return query select true, p_workspace_id, p_user_id;
end;
$$;


