CREATE OR REPLACE FUNCTION "tongs"."rename_org_team"("p_team_id" "uuid", "p_name" "text") RETURNS TABLE("team_id" "uuid", "org_id" "uuid", "team_name" "text", "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare
  v_name text;
  v_team tongs.teams%rowtype;
begin
  if p_team_id is null then
    raise exception 'team_id is required'
      using errcode = '22023';
  end if;

  v_name := nullif(trim(coalesce(p_name, '')), '');
  if v_name is null then
    raise exception 'team name is required'
      using errcode = '22023';
  end if;

  select t.*
  into v_team
  from tongs.teams t
  where t.id = p_team_id
  for update;

  if not found then
    raise exception 'Team not found'
      using errcode = 'P0002';
  end if;

  perform tongs.assert_org_role(v_team.org_id, 'admin');

  update tongs.teams t
  set
    name = v_name,
    updated_at = now()
  where t.id = p_team_id
  returning * into v_team;

  return query
  select
    v_team.id,
    v_team.org_id,
    v_team.name,
    v_team.created_at,
    v_team.updated_at;
end;
$$;


