CREATE TABLE IF NOT EXISTS "tongs"."recording_session_items" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "session_id" "uuid" NOT NULL,
    "position" integer NOT NULL,
    "episode_id" "uuid" NOT NULL,
    "script_path" "text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "recording_session_items_position_check" CHECK (("position" > 0)),
    CONSTRAINT "recording_session_items_script_path_check" CHECK (("length"("btrim"("script_path")) > 0))
);


ALTER TABLE "tongs"."recording_session_items" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."replace_recording_session_items"("p_session_id" "uuid", "p_items" "jsonb") RETURNS SETOF "tongs"."recording_session_items"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'tongs', 'pg_temp'
    AS $$
declare
  v_workspace_id uuid;
  v_item jsonb;
  v_position integer := 0;
  v_episode_id uuid;
  v_script_path text;
begin
  if p_items is null or jsonb_typeof(p_items) <> 'array' then
    raise exception 'p_items must be a JSON array' using errcode = '22023';
  end if;

  select rs.workspace_id
  into v_workspace_id
  from tongs.recording_sessions rs
  where rs.id = p_session_id;

  if v_workspace_id is null then
    raise exception 'recording_session_not_found' using errcode = 'P0002';
  end if;

  delete from tongs.recording_session_items
  where session_id = p_session_id;

  for v_item in
    select value
    from jsonb_array_elements(p_items)
  loop
    v_position := v_position + 1;
    v_episode_id := nullif(v_item ->> 'episode_id', '')::uuid;
    v_script_path := btrim(coalesce(v_item ->> 'script_path', ''));

    if v_episode_id is null then
      raise exception 'episode_id is required for each item' using errcode = '22023';
    end if;

    if v_script_path = '' then
      raise exception 'script_path is required for each item' using errcode = '22023';
    end if;

    if not exists (
      select 1
      from tongs.episodes e
      where e.id = v_episode_id
        and e.workspace_id = v_workspace_id
    ) then
      raise exception 'episode workspace mismatch or episode not found' using errcode = '22023';
    end if;

    insert into tongs.recording_session_items (
      session_id,
      position,
      episode_id,
      script_path
    )
    values (
      p_session_id,
      v_position,
      v_episode_id,
      v_script_path
    );
  end loop;

  return query
  select i.*
  from tongs.recording_session_items i
  where i.session_id = p_session_id
  order by i.position asc, i.created_at asc;
end;
$$;


ALTER FUNCTION "tongs"."replace_recording_session_items"("p_session_id" "uuid", "p_items" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."reserve_ai_credits"("p_user_id" "uuid", "p_operation_id" "text", "p_tool" "text", "p_purpose" "text", "p_media_class" "text", "p_amount" bigint, "p_request_fingerprint" "text", "p_authorization_json" "jsonb", "p_reservation_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $_$
declare
  v_account tongs.ai_credits%rowtype;
  v_existing tongs.ai_credit_reservations%rowtype;
  v_holds bigint;
begin
  if p_user_id is null or p_reservation_id is null or p_amount <= 0
     or nullif(btrim(coalesce(p_operation_id, '')), '') is null
     or nullif(btrim(coalesce(p_tool, '')), '') is null
     or nullif(btrim(coalesce(p_purpose, '')), '') is null
     or p_request_fingerprint !~ '^[0-9a-f]{64}$'
     or jsonb_typeof(p_authorization_json) <> 'object' then
    raise exception 'invalid AI-credit reservation' using errcode = '22023';
  end if;
  insert into tongs.ai_credits (user_id) values (p_user_id) on conflict do nothing;
  select * into v_account from tongs.ai_credits where user_id = p_user_id for update;
  select * into v_existing from tongs.ai_credit_reservations
    where user_id = p_user_id and operation_id = p_operation_id for update;
  if found then
    if v_existing.id <> p_reservation_id or v_existing.amount <> p_amount
       or v_existing.tool <> btrim(p_tool) or v_existing.purpose <> btrim(p_purpose)
       or v_existing.media_class is distinct from nullif(btrim(coalesce(p_media_class, '')), '')
       or v_existing.request_fingerprint <> p_request_fingerprint
       or v_existing.authorization_json <> p_authorization_json then
      raise exception 'AI-credit reservation replay conflict' using errcode = '23505';
    end if;
    return jsonb_build_object('reservation', to_jsonb(v_existing), 'settled_balance', v_account.token_balance,
      'reserved_balance', tongs._ai_credit_active_holds(p_user_id),
      'available_balance', v_account.token_balance - tongs._ai_credit_active_holds(p_user_id));
  end if;
  v_holds := tongs._ai_credit_active_holds(p_user_id);
  if p_amount > v_account.token_balance - v_holds then
    raise exception 'insufficient AI credits' using errcode = 'P0001',
      detail = jsonb_build_object('required', p_amount, 'available', v_account.token_balance - v_holds)::text;
  end if;
  insert into tongs.ai_credit_reservations (
    id, user_id, operation_id, tool, purpose, media_class, amount, request_fingerprint, authorization_json
  ) values (
    p_reservation_id, p_user_id, btrim(p_operation_id), btrim(p_tool), btrim(p_purpose),
    nullif(btrim(coalesce(p_media_class, '')), ''), p_amount, p_request_fingerprint, p_authorization_json
  ) returning * into v_existing;
  insert into tongs.ai_credit_reservation_events (
    reservation_id, user_id, event_type, amount, idempotency_key, reason, actor_id, metadata_json
  ) values (p_reservation_id, p_user_id, 'reserved', p_amount, p_reservation_id, 'reservation_created', p_user_id, p_authorization_json);
  return jsonb_build_object('reservation', to_jsonb(v_existing), 'settled_balance', v_account.token_balance,
    'reserved_balance', tongs._ai_credit_active_holds(p_user_id),
    'available_balance', v_account.token_balance - tongs._ai_credit_active_holds(p_user_id));
end;
$_$;


ALTER FUNCTION "tongs"."reserve_ai_credits"("p_user_id" "uuid", "p_operation_id" "text", "p_tool" "text", "p_purpose" "text", "p_media_class" "text", "p_amount" bigint, "p_request_fingerprint" "text", "p_authorization_json" "jsonb", "p_reservation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."reserve_brand_asset_revision"("p_workspace_id" "uuid", "p_profile_id" "uuid", "p_asset_id" "uuid", "p_role" "text", "p_internal_label" "text", "p_filename" "text", "p_mime_type" "text", "p_operation_id" "text", "p_operation_fingerprint" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare v_user uuid:=auth.uid(); v_asset uuid; v_id uuid; v_revision int; v_key text; v_existing tongs.brand_asset_revisions%rowtype;
begin if v_user is null then raise exception 'Not authenticated' using errcode='42501'; end if; perform tongs.assert_workspace_role(p_workspace_id,'editor');
  if not exists(select 1 from tongs.brand_profiles where id=p_profile_id and workspace_id=p_workspace_id and archived_at is null) then raise exception 'profile unavailable' using errcode='22023'; end if;
  select * into v_existing from tongs.brand_asset_revisions where workspace_id=p_workspace_id and operation_id=p_operation_id;
  if found then if v_existing.operation_fingerprint<>p_operation_fingerprint then raise exception 'Operation identity reused with different asset payload.' using errcode='22023'; end if; return to_jsonb(v_existing); end if;
  v_asset:=p_asset_id; if v_asset is null then v_asset:=gen_random_uuid(); insert into tongs.brand_assets(id,workspace_id,profile_id,role,internal_label,created_by) values(v_asset,p_workspace_id,p_profile_id,p_role,btrim(p_internal_label),v_user);
  elsif not exists(select 1 from tongs.brand_assets where id=v_asset and workspace_id=p_workspace_id and profile_id=p_profile_id and role=p_role and archived_at is null) then raise exception 'asset unavailable or role mismatch' using errcode='22023'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_workspace_id::text||':'||v_asset::text,0)); select coalesce(max(revision),0)+1 into v_revision from tongs.brand_asset_revisions where asset_id=v_asset;
  v_id:=gen_random_uuid(); v_key:=format('workspaces/%s/assets/branding/%s/%s/r%s/%s',p_workspace_id,p_profile_id,v_asset,v_revision,regexp_replace(p_filename,'[^A-Za-z0-9._-]+','-','g'));
  insert into tongs.brand_asset_revisions(id,workspace_id,asset_id,revision,role,state,storage_key,mime_type,operation_id,operation_fingerprint,created_by)
    values(v_id,p_workspace_id,v_asset,v_revision,p_role,'pending',v_key,p_mime_type,p_operation_id,p_operation_fingerprint,v_user);
  return (select to_jsonb(ar) from tongs.brand_asset_revisions ar where ar.id=v_id); end $$;


ALTER FUNCTION "tongs"."reserve_brand_asset_revision"("p_workspace_id" "uuid", "p_profile_id" "uuid", "p_asset_id" "uuid", "p_role" "text", "p_internal_label" "text", "p_filename" "text", "p_mime_type" "text", "p_operation_id" "text", "p_operation_fingerprint" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."reserve_customer_hearth_chat_quote"("p_quote_id" "uuid", "p_reservation_id" "uuid", "p_idempotency_key" "text", "p_request_fingerprint" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_control tongs.paid_execution_control_revisions%rowtype;
  v_quote tongs.customer_spending_quotes%rowtype;
  v_authorization tongs.customer_paid_execution_test_authorizations%rowtype;
  v_existing tongs.funding_reservations%rowtype;
  v_funding jsonb;
  v_result jsonb;
  v_binding jsonb;
begin
  perform tongs._require_pricing_service_role();
  select * into v_control from tongs._current_paid_execution_control();
  if not v_control.pricing_activation_enabled or not v_control.customer_settlement_enabled
     or not v_control.provider_execution_enabled then
    raise exception 'customer spending is not activated' using errcode='42501';
  end if;
  select * into v_quote from tongs.customer_spending_quotes where id=p_quote_id;
  select * into v_authorization
    from tongs._active_customer_paid_execution_test_authorization_for_quote(p_quote_id);
  if v_quote.id is null or v_authorization.id is null
     or v_quote.tool<>'hearth.chat_completion'
     or v_quote.request_fingerprint<>p_request_fingerprint
     or v_quote.normal_maximum_charge_micros<>20000
     or v_quote.billable_failure_maximum_charge_micros<>0 then
    raise exception 'accepted Hearth quote is outside the authorized test scope' using errcode='42501';
  end if;
  select * into v_existing from tongs.funding_reservations where quote_id=p_quote_id;
  if found then
    if v_existing.id<>p_reservation_id or v_existing.idempotency_key<>btrim(p_idempotency_key) then
      raise exception 'operation reservation replay conflict' using errcode='23505';
    end if;
    v_funding:=jsonb_build_object('eligible',true,'funding_source',v_existing.funding_source_type,
      'funding_source_id',v_existing.funding_source_id,
      'customer_label',case v_existing.funding_source_type when 'customer_deposit' then 'Verified AI credit purchase' else 'Paid-plan allowance' end);
  else
    v_funding:=tongs._select_customer_funding_for_quote(p_quote_id);
    if not coalesce((v_funding->>'eligible')::boolean,false) then
      raise exception 'insufficient verified funding' using errcode='P0001';
    end if;
  end if;
  v_result:=tongs.reserve_operation(
    p_reservation_id,p_quote_id,v_funding->>'funding_source',
    (v_funding->>'funding_source_id')::uuid,p_idempotency_key
  );
  v_binding:=tongs.bind_openai_text_funding_reservation(
    v_quote.operation_id,'hearth.chat_completion',p_reservation_id,'forge','gpt-5.6-luna',
    v_authorization.cost_policy_revision_id
  );
  return jsonb_build_object('reservation_id',p_reservation_id,'operation_id',v_quote.operation_id,
    'request_fingerprint',v_quote.request_fingerprint,'state',v_result->>'state',
    'replay',coalesce((v_result->>'replay')::boolean,false),
    'funding_source',v_funding->>'funding_source','funding_label',v_funding->>'customer_label',
    'provider_execution_authorized',false,
    'binding_replay',coalesce((v_binding->>'replay')::boolean,false));
end $$;


ALTER FUNCTION "tongs"."reserve_customer_hearth_chat_quote"("p_quote_id" "uuid", "p_reservation_id" "uuid", "p_idempotency_key" "text", "p_request_fingerprint" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."reserve_customer_openai_text_quote"("p_quote_id" "uuid", "p_reservation_id" "uuid", "p_user_id" "uuid", "p_operation_id" "text", "p_route_code" "text", "p_workspace_id" "uuid", "p_workpiece_id" "text", "p_request_fingerprint" "text", "p_model" "text", "p_credential_funding" "text", "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare v_qb tongs.openai_text_customer_quote_bindings%rowtype; v_quote tongs.customer_spending_quotes%rowtype; v_funding jsonb; v_reserved jsonb; v_cost tongs.openai_text_cost_policy_revisions%rowtype; v_rollout tongs.openai_text_rollout_revisions%rowtype; v_existing tongs.openai_text_funding_bindings%rowtype;
begin
 perform tongs._require_pricing_service_role(); perform pg_advisory_xact_lock(hashtextextended('openai-text-ordinary:'||p_user_id::text||':'||btrim(p_operation_id),0));
 select * into v_qb from tongs.openai_text_customer_quote_bindings where quote_id=p_quote_id; select * into v_quote from tongs.customer_spending_quotes where id=p_quote_id;
 if v_qb.quote_id is null or v_quote.id is null or v_qb.user_id<>p_user_id or v_qb.canonical_operation_id<>btrim(p_operation_id) or v_qb.route_code<>p_route_code or v_qb.workspace_id<>p_workspace_id or v_qb.workpiece_id<>btrim(p_workpiece_id) or v_qb.request_fingerprint<>p_request_fingerprint or v_qb.runtime_model<>btrim(p_model) or v_qb.credential_funding<>p_credential_funding or not exists(select 1 from tongs.customer_spending_quote_acceptances a where a.quote_id=p_quote_id and a.user_id=p_user_id and a.accepted_quote_hash=v_quote.quote_hash) then raise exception 'accepted exact OpenAI quote required' using errcode='42501'; end if;
 if v_quote.expires_at<=now() and not exists(select 1 from tongs.funding_reservations r where r.quote_id=p_quote_id) then raise exception 'spending quote expired' using errcode='P0001'; end if;
 select * into v_cost from tongs.openai_text_cost_policy_revisions where id=v_qb.cost_policy_revision_id; select * into v_rollout from tongs._openai_rollout_for_funding(p_route_code,p_credential_funding);
 if v_rollout.mode<>'enforce' or (v_rollout.cost_policy_revision_id is not null and v_rollout.cost_policy_revision_id<>v_cost.id) or not exists(select 1 from tongs._eligible_ai_models_for_operation(p_route_code)e where e.model_catalog_entry_id=v_qb.model_catalog_entry_id and e.cost_policy_revision_id=v_cost.id and e.runtime_model_id=v_qb.runtime_model) then raise exception 'OpenAI text route is not active for this accepted cost revision' using errcode='42501'; end if;
 v_funding:=tongs._select_customer_funding_for_quote(p_quote_id); if coalesce((v_funding->>'eligible')::boolean,false) is not true then raise exception 'insufficient verified funding' using errcode='P0001'; end if;
 v_reserved:=tongs.reserve_operation(p_reservation_id,p_quote_id,v_funding->>'funding_source',(v_funding->>'funding_source_id')::uuid,p_idempotency_key);
 select * into v_existing from tongs.openai_text_funding_bindings where operation_id=btrim(p_operation_id);
 if found then if v_existing.reservation_id<>p_reservation_id or v_existing.route_code<>p_route_code or v_existing.model<>btrim(p_model) or v_existing.cost_policy_revision_id<>v_cost.id then raise exception 'OpenAI binding replay conflict' using errcode='23505'; end if;
 else insert into tongs.openai_text_funding_bindings(operation_id,route_code,reservation_id,credential_funding,model,pricing_revision_id,maximum_input_units,maximum_output_units,maximum_attempts,cost_policy_revision_id,rollout_revision) values(btrim(p_operation_id),p_route_code,p_reservation_id,p_credential_funding,btrim(p_model),v_qb.pricing_revision_id,v_cost.maximum_input_units,v_cost.maximum_output_units,v_cost.maximum_attempts,v_cost.id,v_rollout.revision); end if;
 return jsonb_build_object('paid_execution',jsonb_build_object('operation_id',btrim(p_operation_id),'reservation_id',p_reservation_id,'request_fingerprint',p_request_fingerprint,'funding_environment',(select funding_environment from tongs.funding_reservations where id=p_reservation_id)),'reservation_state',tongs._funding_reservation_state(p_reservation_id),'funding_source',v_funding->>'funding_source','replay',coalesce((v_reserved->>'replay')::boolean,false));
end $$;


ALTER FUNCTION "tongs"."reserve_customer_openai_text_quote"("p_quote_id" "uuid", "p_reservation_id" "uuid", "p_user_id" "uuid", "p_operation_id" "text", "p_route_code" "text", "p_workspace_id" "uuid", "p_workpiece_id" "text", "p_request_fingerprint" "text", "p_model" "text", "p_credential_funding" "text", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."reserve_customer_openai_transcription_quote"("p_quote_id" "uuid", "p_reservation_id" "uuid", "p_user_id" "uuid", "p_operation_id" "text", "p_route_code" "text", "p_workspace_id" "uuid", "p_workpiece_id" "text", "p_request_fingerprint" "text", "p_model" "text", "p_credential_funding" "text", "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
begin
 perform tongs._require_pricing_service_role();
 if not exists(select 1 from tongs.openai_transcription_source_bindings s where s.quote_id=p_quote_id and s.route_code=p_route_code and s.user_id=p_user_id and s.workspace_id=p_workspace_id and s.workpiece_id=p_workpiece_id)
 then raise exception 'exact transcription source binding required' using errcode='42501'; end if;
 return tongs.reserve_customer_openai_text_quote(p_quote_id,p_reservation_id,p_user_id,p_operation_id,p_route_code,p_workspace_id,p_workpiece_id,p_request_fingerprint,p_model,p_credential_funding,p_idempotency_key);
end $$;


ALTER FUNCTION "tongs"."reserve_customer_openai_transcription_quote"("p_quote_id" "uuid", "p_reservation_id" "uuid", "p_user_id" "uuid", "p_operation_id" "text", "p_route_code" "text", "p_workspace_id" "uuid", "p_workpiece_id" "text", "p_request_fingerprint" "text", "p_model" "text", "p_credential_funding" "text", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."reserve_customer_runway_quote"("p_quote_id" "uuid", "p_reservation_id" "uuid", "p_idempotency_key" "text", "p_operation_fingerprint" "text", "p_model" "text", "p_duration_seconds" integer, "p_ratio" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_authorization tongs.runway_customer_test_authorizations%rowtype;
  q tongs.customer_spending_quotes%rowtype;
  result jsonb;
begin
  perform tongs._require_pricing_service_role();
  select a.* into v_authorization
  from tongs.runway_customer_test_quote_bindings b
  join tongs.runway_customer_test_authorizations a on a.id=b.authorization_id
  where b.quote_id=p_quote_id and a.status='active' and a.valid_from<=now() and a.valid_until>now();
  select * into q from tongs.customer_spending_quotes where id=p_quote_id;
  if v_authorization.id is null or q.id is null
     or not exists(select 1 from tongs.customer_spending_quote_acceptances where quote_id=q.id)
     or v_authorization.operation_fingerprint<>lower(p_operation_fingerprint)
     or v_authorization.model<>p_model or v_authorization.duration_seconds<>p_duration_seconds
     or v_authorization.ratio<>p_ratio or q.pricing_revision_id<>v_authorization.pricing_revision_id
     or q.normal_maximum_charge_micros<>800000 or q.customer_credit_units<>160
     or q.billable_failure_maximum_charge_micros<>0 or q.full_cost_ceiling_micros<>600000
     or q.financial_environment<>'test' then
    raise exception 'accepted Runway quote is outside the authorized exact Test scope' using errcode='42501';
  end if;
  result:=tongs._reserve_customer_runway_quote_before_gen45_customer_test(
    p_quote_id,p_reservation_id,p_idempotency_key,p_operation_fingerprint,
    p_model,p_duration_seconds,p_ratio);
  if not exists(select 1 from tongs.funding_reservations
    where id=p_reservation_id and runway_test_authorization_id=v_authorization.id
      and funding_environment='test') then
    raise exception 'Runway reservation did not retain exact Test authorization' using errcode='42501';
  end if;
  return result||jsonb_build_object('activation_scope','normal_customer_test_exact_operation');
end $$;


ALTER FUNCTION "tongs"."reserve_customer_runway_quote"("p_quote_id" "uuid", "p_reservation_id" "uuid", "p_idempotency_key" "text", "p_operation_fingerprint" "text", "p_model" "text", "p_duration_seconds" integer, "p_ratio" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."reserve_hammer_recording_import"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_operation_id" "uuid", "p_request_fingerprint" "text", "p_media_path" "text", "p_original_filename" "text", "p_expected_media_hash" "text", "p_expected_media_bytes" bigint, "p_expected_media_content_type" "text", "p_storage_bucket" "text", "p_storage_key" "text", "p_hammer_version" "text", "p_provenance" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare v_user uuid:=auth.uid(); v_existing tongs.hammer_recording_import_requests%rowtype; v_saved tongs.hammer_recording_import_requests%rowtype;
begin
  perform pg_advisory_xact_lock(hashtextextended(p_workspace_id::text||':'||p_operation_id::text,0));
  if v_user is null or not tongs.has_workspace_role(p_workspace_id,'editor') then return jsonb_build_object('outcome','denied','import',null); end if;
  if not exists(select 1 from tongs.episodes where id=p_workpiece_id and workspace_id=p_workspace_id) then return jsonb_build_object('outcome','not_found','import',null); end if;
  select * into v_existing from tongs.hammer_recording_import_requests where workspace_id=p_workspace_id and operation_id=p_operation_id;
  if found then
    if v_existing.request_fingerprint=p_request_fingerprint then return jsonb_build_object('outcome',case when v_existing.state='committed' then 'duplicate' else 'resumable' end,'import',to_jsonb(v_existing)); end if;
    return jsonb_build_object('outcome','conflict','reason','operation_id_reused','import',null);
  end if;
  select * into v_existing from tongs.hammer_recording_import_requests
    where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and state='committed'
      and verified_media_hash=lower(p_expected_media_hash) limit 1;
  if found then return jsonb_build_object('outcome','duplicate','import',to_jsonb(v_existing)); end if;
  insert into tongs.hammer_recording_import_requests(workspace_id,workpiece_id,operation_id,request_fingerprint,state,
    media_path,original_filename,expected_media_hash,expected_media_bytes,expected_media_content_type,storage_bucket,
    storage_key,hammer_version,provenance,imported_by)
  values(p_workspace_id,p_workpiece_id,p_operation_id,lower(p_request_fingerprint),'reserved',p_media_path,p_original_filename,
    lower(p_expected_media_hash),p_expected_media_bytes,lower(p_expected_media_content_type),p_storage_bucket,p_storage_key,
    p_hammer_version,coalesce(p_provenance,'{}'::jsonb),v_user) returning * into v_saved;
  return jsonb_build_object('outcome','reserved','import',to_jsonb(v_saved));
end; $$;


ALTER FUNCTION "tongs"."reserve_hammer_recording_import"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_operation_id" "uuid", "p_request_fingerprint" "text", "p_media_path" "text", "p_original_filename" "text", "p_expected_media_hash" "text", "p_expected_media_bytes" bigint, "p_expected_media_content_type" "text", "p_storage_bucket" "text", "p_storage_key" "text", "p_hammer_version" "text", "p_provenance" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."reserve_hammer_short_derivative"("p_candidate_id" "uuid", "p_display_label" "text", "p_operation_id" "text", "p_operation_fingerprint" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $_$
declare
  v_actor uuid:=auth.uid();
  v_candidate tongs.hammer_short_candidates%rowtype;
  v_basis tongs.hammer_shorts_basis_locks%rowtype;
  v_parent tongs.canonical_recordings%rowtype;
  v_existing tongs.hammer_short_derivatives%rowtype;
  v_child uuid:=gen_random_uuid();
  v_canonical uuid:=gen_random_uuid();
  v_revision uuid:=gen_random_uuid();
  v_head uuid;
begin
  if p_operation_fingerprint !~ '^[0-9a-f]{64}$' then
    raise exception 'hammer_shorts_fingerprint_invalid' using errcode='22023';
  end if;
  select * into v_candidate from tongs.hammer_short_candidates where id=p_candidate_id;
  select * into v_basis from tongs.hammer_shorts_basis_locks where id=v_candidate.basis_lock_id;
  if v_actor is null or v_candidate.id is null or not tongs.has_workspace_role(v_candidate.workspace_id,'editor') then
    raise exception 'hammer_shorts_editor_required' using errcode='42501';
  end if;
  select * into v_existing from tongs.hammer_short_derivatives where operation_id=p_operation_id or candidate_id=p_candidate_id;
  if found then
    if v_existing.operation_fingerprint <> p_operation_fingerprint then
      raise exception 'hammer_shorts_operation_conflict' using errcode='40001';
    end if;
    return to_jsonb(v_existing);
  end if;
  if v_candidate.rejected_at is not null then
    raise exception 'hammer_shorts_candidate_rejected' using errcode='40001';
  end if;
  select head_id into v_head from tongs.hammer_history_epoch_heads where recording_revision_id=v_basis.recording_revision_id order by sequence desc limit 1;
  if v_head is distinct from v_basis.history_head_id or exists(
    select 1 from tongs.episodes e where e.id=v_basis.parent_workpiece_id and e.active_revision_id is distinct from v_basis.recording_revision_id
  ) then
    raise exception 'hammer_shorts_candidate_stale' using errcode='40001';
  end if;
  select * into v_parent from tongs.canonical_recordings where id=v_basis.canonical_recording_id;
  if v_parent.id is null then raise exception 'hammer_shorts_parent_recording_missing' using errcode='40001'; end if;

  insert into tongs.episodes(id,workspace_id,label,created_by,creation_origin,lifecycle_state,active_revision_id)
  values(v_child,v_candidate.workspace_id,coalesce(nullif(trim(p_display_label),''),'Short'),v_actor,'hammer_short_derivative_v1','active',null);
  insert into tongs.canonical_recordings(
    id,workspace_id,workpiece_id,status,kept_take_event_id,media_path,media_content_type,media_bytes,media_duration_ms,
    recording_session_id,anvil_capture_session_id,media_id,media_signature,created_by,updated_by
  ) values(
    v_canonical,v_candidate.workspace_id,v_child,'draft',v_parent.kept_take_event_id,v_parent.media_path,v_parent.media_content_type,
    v_parent.media_bytes,v_parent.media_duration_ms,v_parent.recording_session_id,v_parent.anvil_capture_session_id,v_parent.media_id,
    v_parent.media_signature,v_actor,v_actor
  );
  insert into tongs.recording_revisions(id,workspace_id,workpiece_id,canonical_recording_id,status,label,created_by,updated_by)
  values(v_revision,v_candidate.workspace_id,v_child,v_canonical,'active','Projected Short',v_actor,v_actor);
  insert into tongs.hammer_short_derivatives(
    workspace_id,basis_lock_id,candidate_id,child_workpiece_id,child_canonical_recording_id,child_recording_revision_id,
    state,core_range,envelope_range,operation_id,operation_fingerprint,created_by
  ) values(
    v_candidate.workspace_id,v_basis.id,v_candidate.id,v_child,v_canonical,v_revision,'preparing',
    jsonb_build_object('start_sec',v_candidate.core_output_start_sec,'end_sec',v_candidate.core_output_end_sec),
    jsonb_build_object('start_sec',v_candidate.envelope_output_start_sec,'end_sec',v_candidate.envelope_output_end_sec),
    p_operation_id,p_operation_fingerprint,v_actor
  ) returning * into v_existing;
  return to_jsonb(v_existing);
end $_$;


ALTER FUNCTION "tongs"."reserve_hammer_short_derivative"("p_candidate_id" "uuid", "p_display_label" "text", "p_operation_id" "text", "p_operation_fingerprint" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."reserve_hammer_shorts_discovery"("p_request" "jsonb", "p_operation_id" "text", "p_operation_fingerprint" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare v_actor uuid:=auth.uid(); v_basis tongs.hammer_shorts_basis_locks%rowtype; v_row tongs.hammer_shorts_discoveries%rowtype;
begin
  select * into v_basis from tongs.hammer_shorts_basis_locks where id=(p_request->>'basis_lock_id')::uuid;
  if v_actor is null or v_basis.id is null or not tongs.has_workspace_role(v_basis.workspace_id,'editor') then raise exception 'hammer_shorts_editor_required' using errcode='42501'; end if;
  select * into v_row from tongs.hammer_shorts_discoveries where operation_id=p_operation_id; if found then return to_jsonb(v_row); end if;
  insert into tongs.hammer_shorts_discoveries(workspace_id,parent_workpiece_id,basis_lock_id,goal,duration_preset,minimum_duration_sec,maximum_duration_sec,target_candidate_count,prompt_version,contract_version,provider,model,request_fingerprint,operation_id,operation_fingerprint,created_by)
  values(v_basis.workspace_id,v_basis.parent_workpiece_id,v_basis.id,p_request->>'goal',p_request->>'duration_preset',(p_request->>'minimum_duration_sec')::numeric,(p_request->>'maximum_duration_sec')::numeric,(p_request->>'target_candidate_count')::integer,p_request->>'prompt_version',p_request->>'contract_version','openai',p_request->>'model',p_request->>'request_fingerprint',p_operation_id,p_operation_fingerprint,v_actor) returning * into v_row; return to_jsonb(v_row);
end $$;


ALTER FUNCTION "tongs"."reserve_hammer_shorts_discovery"("p_request" "jsonb", "p_operation_id" "text", "p_operation_fingerprint" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."reserve_hammer_video_render_attempt"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_lease_owner" "text", "p_lease_seconds" integer DEFAULT 300) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare op tongs.hammer_video_render_operations%rowtype; a tongs.hammer_video_render_attempts%rowtype; n bigint;
begin
  if auth.role()<>'service_role' then raise exception 'Hammer video render attempt requires service authority' using errcode='42501'; end if;
  select * into op from tongs.hammer_video_render_operations where operation_id=p_operation_id for update;
  if not found then return jsonb_build_object('disposition','operation_not_found'); end if;
  if op.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict'); end if;
  if op.state not in('pending','failed') then return jsonb_build_object('disposition','operation_not_reservable','state',op.state); end if;
  if exists(select 1 from tongs.hammer_video_render_attempts where operation_id=p_operation_id and state in('reserved','running') and lease_expires_at>now()) then return jsonb_build_object('disposition','attempt_already_active'); end if;
  select coalesce(max(attempt_number),0)+1 into n from tongs.hammer_video_render_attempts where operation_id=p_operation_id;
  insert into tongs.hammer_video_render_attempts(operation_id,attempt_number,state,lease_owner,lease_expires_at)
  values(p_operation_id,n,'reserved',p_lease_owner,now()+make_interval(secs=>greatest(30,p_lease_seconds))) returning * into a;
  update tongs.hammer_video_render_operations set state='rendering',updated_at=now() where operation_id=p_operation_id;
  return jsonb_build_object('disposition','reserved','attempt',to_jsonb(a));
end$$;


ALTER FUNCTION "tongs"."reserve_hammer_video_render_attempt"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_lease_owner" "text", "p_lease_seconds" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."reserve_hearth_chat_test_quote"("p_reservation_id" "uuid", "p_quote_id" "uuid", "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare v_quote tongs.test_customer_spending_quotes%rowtype; v_auth tongs.test_paid_execution_authorizations%rowtype; v_dep tongs.customer_deposits%rowtype;
 v_existing tongs.test_funding_reservations%rowtype; v_used_units bigint; v_used_micros bigint; v_refund_units bigint; v_refund_micros bigint; v_hold_units bigint; v_hold_micros bigint;
begin
  perform tongs._require_pricing_service_role();
  select * into v_quote from tongs.test_customer_spending_quotes where id=p_quote_id;
  if not found or v_quote.expires_at<=now() or not exists(select 1 from tongs.test_customer_spending_quote_acceptances where quote_id=p_quote_id) then raise exception 'accepted Test quote required' using errcode='P0001'; end if;
  select * into v_auth from tongs.test_paid_execution_authorizations where id=v_quote.authorization_id for update;
  if tongs._test_authorization_state(v_auth.id)<>'opened' or v_auth.expires_at<=now() then raise exception 'Test authorization inactive' using errcode='42501'; end if;
  perform pg_advisory_xact_lock(hashtextextended('test-deposit:'||v_auth.deposit_id::text,0));
  select * into v_existing from tongs.test_funding_reservations where quote_id=p_quote_id;
  if found then return jsonb_build_object('reservation_id',v_existing.id,'state',tongs._test_reservation_state(v_existing.id),'execution_kind','simulated_test','replay',true); end if;
  select * into v_dep from tongs.customer_deposits where id=v_auth.deposit_id for update;
  if not found or v_dep.stripe_mode<>'test' or v_dep.user_id<>v_quote.user_id then raise exception 'Stripe Test deposit required' using errcode='42501'; end if;
  select coalesce(sum(credit_units_consumed),0),coalesce(sum(recognized_test_revenue_micros),0) into v_used_units,v_used_micros from tongs.test_customer_deposit_consumptions where deposit_id=v_dep.id;
  select coalesce(sum(refunded_credit_units),0),coalesce(sum(liability_release_micros),0) into v_refund_units,v_refund_micros from tongs.customer_deposit_refunds where deposit_id=v_dep.id;
  select coalesce(sum(r.reserved_credit_units),0),coalesce(sum(r.reserved_customer_charge_micros),0) into v_hold_units,v_hold_micros
    from tongs.test_funding_reservations r where r.deposit_id=v_dep.id and tongs._test_reservation_state(r.id) in ('reserved','attempt_started','submission_unknown');
  if 2>v_dep.credit_units-v_used_units-v_refund_units-v_hold_units or 20000>v_dep.gross_amount_micros-v_used_micros-v_refund_micros-v_hold_micros then raise exception 'insufficient Stripe Test balance' using errcode='P0001'; end if;
  insert into tongs.test_funding_reservations(id,quote_id,deposit_id,user_id,operation_id,reserved_customer_charge_micros,reserved_credit_units,idempotency_key,execution_kind)
  values(p_reservation_id,p_quote_id,v_dep.id,v_quote.user_id,v_quote.operation_id,20000,2,btrim(p_idempotency_key),'simulated_test');
  insert into tongs.test_funding_reservation_events(id,reservation_id,sequence,event_type,event_key,evidence_json)
  values(gen_random_uuid(),p_reservation_id,1,'reserved','test-reservation:'||p_reservation_id||':reserved',jsonb_build_object('provider_execution_kind','simulated_test','real_provider_authorized',false));
  return jsonb_build_object('reservation_id',p_reservation_id,'state','reserved','funding_source','test_customer_deposit','execution_kind','simulated_test','real_provider_authorized',false,'replay',false);
end $$;


ALTER FUNCTION "tongs"."reserve_hearth_chat_test_quote"("p_reservation_id" "uuid", "p_quote_id" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."reserve_openai_text_test_certification_operation"("p_reservation_id" "uuid", "p_operation_record_id" "uuid", "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare v_op tongs.openai_text_test_certification_operations%rowtype; v_batch tongs.openai_text_test_certification_batches%rowtype; v_existing tongs.openai_text_test_certification_reservations%rowtype; v_balance bigint; v_holds bigint; v_count integer;
begin
  perform tongs._require_pricing_service_role(); select * into v_op from tongs.openai_text_test_certification_operations where id=p_operation_record_id;
  select * into v_batch from tongs.openai_text_test_certification_batches where id=v_op.batch_id for update;
  if v_op.id is null or v_batch.id is null or v_op.expires_at<=now() or tongs._openai_text_test_certification_batch_state(v_batch.id)<>'opened' then raise exception 'accepted Test quote required' using errcode='42501'; end if;
  perform pg_advisory_xact_lock(hashtextextended('openai-text-test-certification:'||v_batch.id::text,0));
  select * into v_existing from tongs.openai_text_test_certification_reservations where operation_record_id=v_op.id;
  if found then return jsonb_build_object('reservation_id',v_existing.id,'state',tongs._openai_text_test_certification_reservation_state(v_existing.id),'replay',true,'real_provider_authorized',false); end if;
  if exists(select 1 from tongs.openai_text_test_certification_reservations r where r.batch_id=v_batch.id and tongs._openai_text_test_certification_reservation_state(r.id) in ('reserved','attempt_started','submission_unknown')) then raise exception 'Test certification concurrency limit reached' using errcode='P0001'; end if;
  select count(*) into v_count from tongs.openai_text_test_certification_reservations where batch_id=v_batch.id;
  if v_count>=v_batch.maximum_operation_count then raise exception 'Test operation limit reached' using errcode='42501'; end if;
  select coalesce(sum(quantity_delta),0) into v_balance from tongs.accounting_journal_entries where user_id=v_batch.user_id and account_code='test_customer_credits';
  select coalesce(sum(reserved_credit_units),0) into v_holds from tongs.openai_text_test_certification_reservations r where r.deposit_id=v_batch.deposit_id and tongs._openai_text_test_certification_reservation_state(r.id) in ('reserved','attempt_started','submission_unknown');
  if v_op.reserved_credit_units>v_balance-v_holds then raise exception 'insufficient Stripe Test balance' using errcode='P0001'; end if;
  insert into tongs.openai_text_test_certification_reservations(id,operation_record_id,batch_id,deposit_id,user_id,operation_id,reserved_customer_charge_micros,reserved_credit_units,idempotency_key,execution_kind)
  values(p_reservation_id,v_op.id,v_batch.id,v_batch.deposit_id,v_batch.user_id,v_op.operation_id,v_op.normal_maximum_charge_micros,v_op.reserved_credit_units,btrim(p_idempotency_key),'simulated_test');
  insert into tongs.openai_text_test_certification_reservation_events(id,reservation_id,sequence,event_type,event_key,evidence_json)
  values(gen_random_uuid(),p_reservation_id,1,'reserved','openai-text-test-reservation:'||p_reservation_id||':reserved',jsonb_build_object('real_provider_authorized',false,'concurrency_limit',1));
  return jsonb_build_object('reservation_id',p_reservation_id,'state','reserved','replay',false,'execution_kind','simulated_test','real_provider_authorized',false);
end $$;


ALTER FUNCTION "tongs"."reserve_openai_text_test_certification_operation"("p_reservation_id" "uuid", "p_operation_record_id" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."reserve_operation"("p_reservation_id" "uuid", "p_quote_id" "uuid", "p_funding_source_type" "text", "p_funding_source_id" "uuid", "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_control tongs.paid_execution_control_revisions%rowtype;
  v_quote tongs.customer_spending_quotes%rowtype;
  v_existing tongs.funding_reservations%rowtype;
  v_deposit tongs.customer_deposits%rowtype;
  v_allowance tongs.paid_allowance_grants%rowtype; v_beta tongs.beta_credit_grants%rowtype;
  v_budget tongs.owner_operating_budgets%rowtype;
  v_budget_revision tongs.owner_operating_budget_revisions%rowtype;
  v_hold record;
  v_used_charge bigint;
  v_used_units bigint;
  v_used_wholesale bigint;
  v_refunded_charge bigint;
  v_refunded_units bigint;
  v_reserve_charge bigint;
  v_reserve_units bigint;
  v_reserve_wholesale bigint;
begin
  perform tongs._require_pricing_service_role();
  select * into v_control from tongs._current_paid_execution_control();
  if not v_control.reservation_shadow_enabled then
    raise exception 'reservation shadow is disabled' using errcode = '42501';
  end if;
  if p_reservation_id is null or p_quote_id is null
     or p_funding_source_type not in ('customer_deposit', 'paid_allowance', 'beta_grant', 'owner_budget', 'none')
     or length(btrim(coalesce(p_idempotency_key, ''))) < 8 then
    raise exception 'invalid operation reservation' using errcode = '22023';
  end if;
  select * into v_quote from tongs.customer_spending_quotes where id = p_quote_id;
  if not found then raise exception 'spending quote not found' using errcode = 'P0002'; end if;
  if v_quote.expires_at <= now() then raise exception 'spending quote expired' using errcode = 'P0001'; end if;
  if not exists (select 1 from tongs.customer_spending_quote_acceptances where quote_id = p_quote_id) then
    raise exception 'accepted spending quote required' using errcode = 'P0001';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(
    'funding-reservation:' || v_quote.user_id::text || ':' || v_quote.operation_id, 0));
  select * into v_existing from tongs.funding_reservations
  where user_id = v_quote.user_id and operation_id = v_quote.operation_id;
  if found then
    if v_existing.id <> p_reservation_id or v_existing.quote_id <> p_quote_id
       or v_existing.funding_source_type <> p_funding_source_type
       or v_existing.funding_source_id is distinct from p_funding_source_id
       or v_existing.idempotency_key <> btrim(p_idempotency_key) then
      raise exception 'operation reservation replay conflict' using errcode = '23505';
    end if;
    return jsonb_build_object('reservation_id', v_existing.id,
      'state', tongs._funding_reservation_state(v_existing.id), 'replay', true,
      'provider_execution_authorized', false, 'shadow_mode', true);
  end if;

  v_reserve_charge := v_quote.normal_maximum_charge_micros;
  v_reserve_units := v_quote.customer_credit_units;
  v_reserve_wholesale := v_quote.full_cost_ceiling_micros;
  if p_funding_source_type = 'none' then
    if p_funding_source_id is not null or v_reserve_charge <> 0 or v_reserve_units <> 0 or v_reserve_wholesale <> 0 then
      raise exception 'zero-Forge-cost quote required for no-funding reservation' using errcode = 'P0001';
    end if;
  elsif p_funding_source_id is null then
    raise exception 'funding source id required' using errcode = '22023';
  elsif p_funding_source_type = 'customer_deposit' then
    select * into v_deposit from tongs.customer_deposits where id = p_funding_source_id for update;
    if not found or not tongs._quote_payer_allows_user(v_quote.id, v_deposit.user_id) or v_deposit.currency <> v_quote.currency then
      raise exception 'eligible customer deposit not found' using errcode = 'P0002';
    end if;
    if v_deposit.stripe_mode <> v_quote.financial_environment then raise exception 'cross-environment customer funding is forbidden' using errcode = '42501'; end if;
    if not exists (select 1 from tongs.customer_deposit_processor_fees where deposit_id = v_deposit.id) then
      raise exception 'processor fee must be finalized before reservation' using errcode = 'P0001';
    end if;
    select coalesce(sum(recognized_revenue_micros),0), coalesce(sum(credit_units_consumed),0)
      into v_used_charge, v_used_units from tongs.customer_deposit_consumptions
      where deposit_id = v_deposit.id;
    select coalesce(sum(liability_release_micros),0), coalesce(sum(refunded_credit_units),0)
      into v_refunded_charge, v_refunded_units from tongs.customer_deposit_refunds
      where deposit_id = v_deposit.id;
    select * into v_hold from tongs._active_funding_hold('customer_deposit', v_deposit.id);
    if v_reserve_charge > v_deposit.gross_amount_micros - v_used_charge - v_refunded_charge - v_hold.customer_charge_micros
       or v_reserve_units > v_deposit.credit_units - v_used_units - v_refunded_units - v_hold.credit_units then
      raise exception 'insufficient verified deposit balance' using errcode = 'P0001';
    end if;
  elsif p_funding_source_type = 'paid_allowance' then
    select * into v_allowance from tongs.paid_allowance_grants where id = p_funding_source_id for update;
    if not found or not tongs._quote_payer_allows_user(v_quote.id, v_allowance.user_id) or v_allowance.currency <> v_quote.currency then
      raise exception 'eligible paid allowance not found' using errcode = 'P0002';
    end if;
    if now() < v_allowance.period_start or now() >= v_allowance.period_end
       or exists (select 1 from tongs.subscription_cycle_adjustments where receipt_id = v_allowance.receipt_id) then
      raise exception 'paid allowance is not currently funded' using errcode = 'P0001';
    end if;
    select coalesce(sum(recognized_revenue_micros),0), coalesce(sum(entitlement_units_consumed),0),
      coalesce(sum(wholesale_spend_micros),0)
      into v_used_charge, v_used_units, v_used_wholesale
    from tongs.paid_allowance_consumptions where allowance_grant_id = v_allowance.id;
    select * into v_hold from tongs._active_funding_hold('paid_allowance', v_allowance.id);
    if v_reserve_charge > v_allowance.allocated_revenue_micros - v_used_charge - v_hold.customer_charge_micros
       or v_reserve_units > v_allowance.entitlement_units - v_used_units - v_hold.credit_units
       or v_reserve_wholesale > v_allowance.maximum_wholesale_spend_micros - v_used_wholesale - v_hold.wholesale_spend_micros then
      raise exception 'insufficient funded allowance balance' using errcode = 'P0001';
    end if;
  elsif p_funding_source_type = 'beta_grant' then
    select * into v_beta from tongs.beta_credit_grants where id = p_funding_source_id for update;
    if not found or not tongs._quote_payer_allows_user(v_quote.id, v_beta.user_id)
       or v_beta.workspace_id <> v_quote.workspace_id
       or v_beta.financial_environment <> v_quote.financial_environment then
      raise exception 'eligible beta credit grant not found' using errcode = 'P0002';
    end if;
    select coalesce(sum(customer_value_micros),0), coalesce(sum(credit_units_consumed),0),
      coalesce(sum(wholesale_spend_micros),0)
      into v_used_charge, v_used_units, v_used_wholesale
    from tongs.beta_credit_consumptions where grant_id = v_beta.id;
    select * into v_hold from tongs._active_funding_hold('beta_grant', v_beta.id);
    if v_reserve_charge > v_beta.customer_value_micros - v_used_charge - v_hold.customer_charge_micros
       or v_reserve_units > v_beta.credit_units - v_used_units - v_hold.credit_units
       or v_reserve_wholesale > v_beta.maximum_wholesale_capacity_micros - v_used_wholesale - v_hold.wholesale_spend_micros then
      raise exception 'insufficient beta Forge Credits' using errcode = 'P0001';
    end if;
  else
    if not v_control.owner_budget_spending_enabled then
      raise exception 'owner-budget spending is not activated' using errcode = '42501';
    end if;
    select * into v_budget from tongs.owner_operating_budgets where id = p_funding_source_id for update;
    select revision.* into v_budget_revision from tongs.owner_operating_budget_revisions revision
      where revision.budget_id = p_funding_source_id order by revision.revision desc limit 1;
    if not found or not tongs._quote_owner_budget_allows(v_quote.id, v_budget.id) or v_budget_revision.status <> 'active' or v_budget_revision.maximum_amount_micros is null
       or now() < v_budget.period_start or now() >= v_budget.period_end or v_budget.currency <> v_quote.currency then
      raise exception 'eligible owner operating budget not found' using errcode = 'P0002';
    end if;
    select * into v_hold from tongs._active_funding_hold('owner_budget', v_budget.id);
    if v_reserve_wholesale > v_budget_revision.maximum_amount_micros - v_hold.wholesale_spend_micros then
      raise exception 'insufficient owner operating budget' using errcode = 'P0001';
    end if;
    v_reserve_charge := 0;
    v_reserve_units := 0;
  end if;

  insert into tongs.funding_reservations(
    id, quote_id, user_id, operation_id, funding_source_type, funding_source_id,
    currency, reserved_customer_charge_micros, reserved_credit_units,
    reserved_wholesale_spend_micros, idempotency_key
  ) values (
    p_reservation_id, p_quote_id, v_quote.user_id, v_quote.operation_id,
    p_funding_source_type, p_funding_source_id, v_quote.currency,
    v_reserve_charge, v_reserve_units, v_reserve_wholesale, btrim(p_idempotency_key)
  );
  insert into tongs.funding_reservation_events(
    id, reservation_id, sequence, event_type, event_key, evidence_json
  ) values (gen_random_uuid(), p_reservation_id, 1, 'reserved',
    'reservation:' || p_reservation_id::text || ':reserved',
    jsonb_build_object('shadow_mode', true, 'provider_execution_authorized', false));
  return jsonb_build_object('reservation_id', p_reservation_id, 'state', 'reserved',
    'replay', false, 'provider_execution_authorized', false, 'shadow_mode', true);
end;
$$;


ALTER FUNCTION "tongs"."reserve_operation"("p_reservation_id" "uuid", "p_quote_id" "uuid", "p_funding_source_type" "text", "p_funding_source_id" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."reserve_owner_openai_text_canary_quote"("p_quote_id" "uuid", "p_reservation_id" "uuid", "p_user_id" "uuid", "p_operation_id" "text", "p_route_code" "text", "p_workspace_id" "uuid", "p_workpiece_id" "text", "p_request_fingerprint" "text", "p_model" "text", "p_credential_funding" "text", "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  quote_binding tongs.openai_text_customer_quote_bindings%rowtype;
  quote_row tongs.customer_spending_quotes%rowtype;
  authority record;
  cost tongs.openai_text_cost_policy_revisions%rowtype;
  reserved jsonb;
  existing tongs.openai_text_funding_bindings%rowtype;
  rollout tongs.openai_text_rollout_revisions%rowtype;
begin
  perform tongs._require_pricing_service_role();
  perform pg_advisory_xact_lock(hashtextextended('openai-text-owner-canary:'||p_user_id::text||':'||btrim(p_operation_id),0));
  if p_credential_funding<>'forge' then raise exception 'Forge credential funding required' using errcode='42501'; end if;
  select * into authority from tongs._owner_paid_execution_canary_for_choice(
    p_user_id,p_workspace_id,p_route_code,p_model);
  if not found then raise exception 'exact owner Test canary authority required' using errcode='42501'; end if;
  select * into quote_binding from tongs.openai_text_customer_quote_bindings where quote_id=p_quote_id;
  select * into quote_row from tongs.customer_spending_quotes where id=p_quote_id;
  if quote_binding.quote_id is null or quote_row.id is null or quote_binding.user_id<>p_user_id
     or quote_binding.canonical_operation_id<>btrim(p_operation_id) or quote_binding.route_code<>p_route_code
     or quote_binding.workspace_id<>p_workspace_id or quote_binding.workpiece_id<>btrim(p_workpiece_id)
     or quote_binding.request_fingerprint<>p_request_fingerprint or quote_binding.runtime_model<>btrim(p_model)
     or quote_binding.credential_funding<>'forge'
     or quote_binding.pricing_revision_id<>authority.pricing_revision_id
     or quote_binding.cost_policy_revision_id<>authority.cost_policy_revision_id
     or not exists(select 1 from tongs.customer_spending_quote_acceptances acceptance
       where acceptance.quote_id=p_quote_id and acceptance.user_id=p_user_id
         and acceptance.accepted_quote_hash=quote_row.quote_hash) then
    raise exception 'accepted exact owner canary quote required' using errcode='42501';
  end if;
  if quote_row.expires_at<=now() and not exists(select 1 from tongs.funding_reservations where quote_id=p_quote_id) then
    raise exception 'spending quote expired' using errcode='P0001';
  end if;
  select * into cost from tongs.openai_text_cost_policy_revisions where id=authority.cost_policy_revision_id;
  if cost.id is null or cost.maximum_attempts<>1 or cost.full_cost_ceiling_micros<>quote_row.full_cost_ceiling_micros then
    raise exception 'exact bounded cost authority required' using errcode='42501';
  end if;
  reserved:=tongs.reserve_operation(p_reservation_id,p_quote_id,'owner_budget',authority.budget_id,p_idempotency_key);
  select * into rollout from tongs._current_openai_text_rollout(p_route_code);
  select * into existing from tongs.openai_text_funding_bindings where operation_id=btrim(p_operation_id);
  if found then
    if existing.reservation_id<>p_reservation_id or existing.route_code<>p_route_code
       or existing.model<>btrim(p_model) or existing.cost_policy_revision_id<>cost.id then
      raise exception 'OpenAI binding replay conflict' using errcode='23505';
    end if;
  else
    insert into tongs.openai_text_funding_bindings(
      operation_id,route_code,reservation_id,credential_funding,model,pricing_revision_id,
      maximum_input_units,maximum_output_units,maximum_attempts,cost_policy_revision_id,rollout_revision
    ) values(btrim(p_operation_id),p_route_code,p_reservation_id,'forge',btrim(p_model),
      authority.pricing_revision_id,cost.maximum_input_units,cost.maximum_output_units,
      cost.maximum_attempts,cost.id,rollout.revision);
  end if;
  return jsonb_build_object('paid_execution',jsonb_build_object(
    'operation_id',btrim(p_operation_id),'reservation_id',p_reservation_id,
    'request_fingerprint',p_request_fingerprint,'funding_environment','test'),
    'reservation_state',tongs._funding_reservation_state(p_reservation_id),
    'funding_source','owner_budget','replay',coalesce((reserved->>'replay')::boolean,false));
end $$;


ALTER FUNCTION "tongs"."reserve_owner_openai_text_canary_quote"("p_quote_id" "uuid", "p_reservation_id" "uuid", "p_user_id" "uuid", "p_operation_id" "text", "p_route_code" "text", "p_workspace_id" "uuid", "p_workpiece_id" "text", "p_request_fingerprint" "text", "p_model" "text", "p_credential_funding" "text", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."reserve_owner_runway_operation"("p_reservation_id" "uuid", "p_quote_id" "uuid", "p_budget_id" "uuid", "p_idempotency_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_quote tongs.customer_spending_quotes%rowtype;
  v_budget tongs.owner_operating_budgets%rowtype;
  v_budget_revision tongs.owner_operating_budget_revisions%rowtype;
  v_existing tongs.funding_reservations%rowtype;
  v_hold record;
begin
  perform tongs._require_pricing_service_role();
  if p_reservation_id is null or p_quote_id is null or p_budget_id is null
     or length(btrim(coalesce(p_idempotency_key,'')))<8 then
    raise exception 'invalid owner Runway reservation' using errcode='22023';
  end if;
  select * into v_quote from tongs.customer_spending_quotes where id=p_quote_id;
  if not found or v_quote.expires_at<=now() or v_quote.tool<>'tongs_broll_v2'
     or v_quote.normal_maximum_charge_micros<>0
     or v_quote.billable_failure_maximum_charge_micros<>0 or v_quote.customer_credit_units<>0
     or v_quote.full_cost_ceiling_micros<>750000
     or not tongs.is_platform_operator(v_quote.user_id)
     or not exists(select 1 from tongs.customer_spending_quote_acceptances acceptance
       where acceptance.quote_id=v_quote.id and acceptance.user_id=v_quote.user_id) then
    raise exception 'accepted zero-customer owner Runway quote required' using errcode='P0001';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('funding-reservation:'||v_quote.user_id::text||':'||v_quote.operation_id,0));
  select * into v_existing from tongs.funding_reservations
    where user_id=v_quote.user_id and operation_id=v_quote.operation_id;
  if found then
    if v_existing.id<>p_reservation_id or v_existing.quote_id<>p_quote_id
       or v_existing.funding_source_type<>'owner_budget' or v_existing.funding_source_id<>p_budget_id
       or v_existing.idempotency_key<>btrim(p_idempotency_key) then
      raise exception 'owner Runway reservation replay conflict' using errcode='23505';
    end if;
    return jsonb_build_object('reservation_id',v_existing.id,
      'state',tongs._funding_reservation_state(v_existing.id),'replay',true,
      'reserved_wholesale_spend_micros',v_existing.reserved_wholesale_spend_micros,
      'provider_execution_authorized',false);
  end if;
  select * into v_budget from tongs.owner_operating_budgets where id=p_budget_id for update;
  select * into v_budget_revision from tongs.owner_operating_budget_revisions
    where budget_id=p_budget_id order by revision desc limit 1;
  if not found or v_budget_revision.status<>'active' or v_budget_revision.maximum_amount_micros<>750000
     or v_budget.environment<>'production' or v_budget.workspace_id is distinct from v_quote.workspace_id
     or lower(coalesce(v_budget.provider,''))<>'runway'
     or lower(coalesce(v_budget.route,''))<>'tongs_broll_v2'
     or lower(coalesce(v_budget.sku,''))<>'gen4.5:5s:1280:720'
     or v_budget.currency<>v_quote.currency or now()<v_budget.period_start or now()>=v_budget.period_end then
    raise exception 'exact active owner Runway pilot budget required' using errcode='P0002';
  end if;
  select * into v_hold from tongs._active_funding_hold('owner_budget',p_budget_id);
  if v_quote.full_cost_ceiling_micros > v_budget_revision.maximum_amount_micros-v_hold.wholesale_spend_micros then
    raise exception 'insufficient owner Runway pilot budget' using errcode='P0001';
  end if;
  insert into tongs.funding_reservations(
    id,quote_id,user_id,operation_id,funding_source_type,funding_source_id,currency,
    reserved_customer_charge_micros,reserved_credit_units,reserved_wholesale_spend_micros,idempotency_key
  ) values(p_reservation_id,p_quote_id,v_quote.user_id,v_quote.operation_id,'owner_budget',p_budget_id,
    v_quote.currency,0,0,v_quote.full_cost_ceiling_micros,btrim(p_idempotency_key));
  insert into tongs.funding_reservation_events(
    id,reservation_id,sequence,event_type,event_key,evidence_json
  ) values(gen_random_uuid(),p_reservation_id,1,'reserved',
    'reservation:'||p_reservation_id::text||':reserved',
    jsonb_build_object('funding_lane','owner_budget','customer_charge_micros',0,
      'customer_credit_units',0,'provider_execution_authorized',false));
  return jsonb_build_object('reservation_id',p_reservation_id,'state','reserved','replay',false,
    'reserved_wholesale_spend_micros',v_quote.full_cost_ceiling_micros,
    'customer_charge_micros',0,'customer_credit_units',0,'provider_execution_authorized',false);
end;
$$;


ALTER FUNCTION "tongs"."reserve_owner_runway_operation"("p_reservation_id" "uuid", "p_quote_id" "uuid", "p_budget_id" "uuid", "p_idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."reserve_restricted_beta_exposure"("p_hold_id" "uuid", "p_policy_revision_id" "uuid", "p_capability_code" "text", "p_operation_identity" "text", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_request_fingerprint" "text", "p_model_or_sku" "text", "p_funding_class" "text", "p_opaque_funding_handle" "text", "p_provider_mode" "text", "p_caller_class" "text", "p_customer_funding_ceiling_micros" bigint, "p_supplier_exposure_ceiling_micros" bigint, "p_supporting_exposure_ceiling_micros" bigint, "p_tail_exposure_ceiling_micros" bigint, "p_unreconciled_exposure_ceiling_micros" bigint, "p_retry_exposure_ceiling_micros" bigint, "p_lease_seconds" integer, "p_event_key" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare pol tongs.restricted_beta_policy_revisions%rowtype; term tongs.restricted_beta_policy_capabilities%rowtype;
 existing tongs.restricted_beta_exposure_holds%rowtype; ev tongs.restricted_beta_cost_evidence_revisions%rowtype;
 requested bigint; committed bigint; concurrent_count bigint;
begin
 perform tongs._require_pricing_service_role();
 select * into pol from tongs.restricted_beta_policy_revisions where id=p_policy_revision_id;
 if not found or pol.lifecycle_state='draft' then return jsonb_build_object('authorized',false,'reason','restricted_beta_inactive'); end if;
 if pol.lifecycle_state<>'active' then return jsonb_build_object('authorized',false,'reason','halt_new'); end if;
 if exists(select 1 from tongs.aggregate_financial_halt_events where policy_revision_id=pol.id) then
  return jsonb_build_object('authorized',false,'reason','aggregate_authoritative_overrun_halt'); end if;
 perform pg_advisory_xact_lock(hashtext('restricted-beta:'||pol.environment));
 select * into existing from tongs.restricted_beta_exposure_holds where operation_identity=btrim(p_operation_identity);
 if found then
  if existing.policy_revision_id<>pol.id or existing.request_fingerprint<>lower(p_request_fingerprint)
     or existing.model_or_sku<>p_model_or_sku or existing.user_id is distinct from p_user_id
     or existing.workspace_id is distinct from p_workspace_id then
   raise exception 'operation binding mismatch' using errcode='22023'; end if;
  return jsonb_build_object('authorized',true,'replay',true,'hold_id',existing.id);
 end if;
 select * into term from tongs.restricted_beta_policy_capabilities where policy_revision_id=pol.id and capability_code=p_capability_code;
 if not found or term.admission_mode='block' then return jsonb_build_object('authorized',false,'reason','capability_not_covered'); end if;
 select * into ev from tongs.restricted_beta_cost_evidence_revisions where id=term.cost_evidence_revision_id;
 if not found or ev.coverage_state<>'complete' or ev.evidence_state='unresolved' or ev.valid_until<=now()
    or ev.observed_at < now()-make_interval(secs=>pol.evidence_max_age_seconds) then
  return jsonb_build_object('authorized',false,'reason','cost_evidence_stale_or_incomplete'); end if;
 if p_model_or_sku<>term.exact_model_or_sku then return jsonb_build_object('authorized',false,'reason','model_or_sku_mismatch'); end if;
 if not(term.permitted_callers_json ? p_caller_class) then return jsonb_build_object('authorized',false,'reason','caller_not_permitted'); end if;
 
 if nullif(btrim(p_opaque_funding_handle),'') is null then return jsonb_build_object('authorized',false,'reason','funding_context_required'); end if;
 if p_supplier_exposure_ceiling_micros>term.per_operation_supplier_ceiling_micros
    or p_supporting_exposure_ceiling_micros>term.per_operation_supporting_ceiling_micros
    or p_tail_exposure_ceiling_micros>term.per_operation_tail_ceiling_micros then
  return jsonb_build_object('authorized',false,'reason','operation_ceiling_exceeded'); end if;
 requested:=p_supplier_exposure_ceiling_micros+p_supporting_exposure_ceiling_micros+p_tail_exposure_ceiling_micros+p_unreconciled_exposure_ceiling_micros+p_retry_exposure_ceiling_micros;
 select c.committed_micros into committed from tongs._restricted_beta_policy_commitment(pol.id)c;
 concurrent_count:=tongs._restricted_beta_policy_execution_concurrency(pol.id);
 if concurrent_count>=pol.maximum_concurrency then return jsonb_build_object('authorized',false,'reason','aggregate_concurrency_exhausted','committed_micros',committed); end if;
 if committed+requested+pol.reserved_headroom_micros>pol.aggregate_forge_exposure_limit_micros then
  return jsonb_build_object('authorized',false,'reason','aggregate_exposure_exhausted','committed_micros',committed,'requested_micros',requested); end if;
 insert into tongs.restricted_beta_exposure_holds(id,policy_revision_id,capability_term_id,operation_identity,user_id,workspace_id,request_fingerprint,model_or_sku,funding_class,funding_handle_hash,provider_mode,caller_class,customer_funding_ceiling_micros,supplier_exposure_ceiling_micros,supporting_exposure_ceiling_micros,tail_exposure_ceiling_micros,unreconciled_exposure_ceiling_micros,retry_exposure_ceiling_micros,lease_expires_at)
 values(p_hold_id,pol.id,term.id,btrim(p_operation_identity),p_user_id,p_workspace_id,lower(p_request_fingerprint),p_model_or_sku,p_funding_class,encode(extensions.digest(convert_to(p_opaque_funding_handle,'utf8'),'sha256'),'hex'),p_provider_mode,p_caller_class,p_customer_funding_ceiling_micros,p_supplier_exposure_ceiling_micros,p_supporting_exposure_ceiling_micros,p_tail_exposure_ceiling_micros,p_unreconciled_exposure_ceiling_micros,p_retry_exposure_ceiling_micros,now()+make_interval(secs=>p_lease_seconds));
 insert into tongs.restricted_beta_exposure_events(id,hold_id,sequence,event_key,event_type,customer_funding_delta_micros,evidence_json)
 values(extensions.uuid_generate_v5(p_hold_id,'reserved'),p_hold_id,1,p_event_key,'reserved',p_customer_funding_ceiling_micros,jsonb_build_object('caller_class',p_caller_class));
 return jsonb_build_object('authorized',true,'replay',false,'hold_id',p_hold_id,'aggregate_before_micros',committed,'reserved_exposure_micros',requested);
end $$;


ALTER FUNCTION "tongs"."reserve_restricted_beta_exposure"("p_hold_id" "uuid", "p_policy_revision_id" "uuid", "p_capability_code" "text", "p_operation_identity" "text", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_request_fingerprint" "text", "p_model_or_sku" "text", "p_funding_class" "text", "p_opaque_funding_handle" "text", "p_provider_mode" "text", "p_caller_class" "text", "p_customer_funding_ceiling_micros" bigint, "p_supplier_exposure_ceiling_micros" bigint, "p_supporting_exposure_ceiling_micros" bigint, "p_tail_exposure_ceiling_micros" bigint, "p_unreconciled_exposure_ceiling_micros" bigint, "p_retry_exposure_ceiling_micros" bigint, "p_lease_seconds" integer, "p_event_key" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."reserve_restricted_beta_exposure"("p_hold_id" "uuid", "p_policy_revision_id" "uuid", "p_capability_code" "text", "p_operation_identity" "text", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_request_fingerprint" "text", "p_model_or_sku" "text", "p_funding_class" "text", "p_opaque_funding_handle" "text", "p_provider_mode" "text", "p_caller_class" "text", "p_customer_funding_ceiling_micros" bigint, "p_supplier_exposure_ceiling_micros" bigint, "p_supporting_exposure_ceiling_micros" bigint, "p_tail_exposure_ceiling_micros" bigint, "p_unreconciled_exposure_ceiling_micros" bigint, "p_retry_exposure_ceiling_micros" bigint, "p_lease_seconds" integer, "p_event_key" "text") IS 'Atomic service-only aggregate admission across routes and users. No active policy exists in this migration.';



CREATE OR REPLACE FUNCTION "tongs"."reset_my_style_profile"("p_workspace_id" "uuid") RETURNS TABLE("reset" boolean, "workspace_id" "uuid", "user_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare
  v_user uuid;
  v_deleted_count integer := 0;
begin
  v_user := auth.uid();
  if v_user is null then
    raise exception 'Not authenticated'
      using errcode = '42501';
  end if;

  if p_workspace_id is null then
    raise exception 'workspace_id is required'
      using errcode = '22023';
  end if;

  perform tongs.assert_workspace_role(p_workspace_id, 'viewer');

  delete from tongs.user_style_profile p
  where p.workspace_id = p_workspace_id
    and p.user_id = v_user;
  get diagnostics v_deleted_count = row_count;

  return query
  select (v_deleted_count > 0), p_workspace_id, v_user;
end;
$$;


ALTER FUNCTION "tongs"."reset_my_style_profile"("p_workspace_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."reset_my_writing_profile"("p_workspace_id" "uuid") RETURNS TABLE("workspace_id" "uuid", "user_id" "uuid", "default_audience" "text", "default_structure" "text", "style_notes" "text", "last_used_tone_preset" "text", "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare
  v_user uuid;
begin
  v_user := auth.uid();
  if v_user is null then
    raise exception 'Not authenticated'
      using errcode = '42501';
  end if;

  if p_workspace_id is null then
    raise exception 'workspace_id is required'
      using errcode = '22023';
  end if;

  perform tongs.assert_workspace_role(p_workspace_id, 'viewer');

  insert into tongs.workspace_writing_profiles (
    workspace_id,
    user_id,
    default_audience,
    default_structure,
    style_notes,
    created_at,
    updated_at
  )
  values (
    p_workspace_id,
    v_user,
    null,
    null,
    null,
    now(),
    now()
  )
  on conflict on constraint workspace_writing_profiles_pkey do update
    set default_audience = null,
        default_structure = null,
        style_notes = null,
        updated_at = now();

  return query
  select
    p.workspace_id,
    p.user_id,
    p.default_audience,
    p.default_structure,
    p.style_notes,
    p.last_used_tone_preset,
    p.updated_at
  from tongs.workspace_writing_profiles p
  where p.workspace_id = p_workspace_id
    and p.user_id = v_user;
end;
$$;


ALTER FUNCTION "tongs"."reset_my_writing_profile"("p_workspace_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."reset_reference_visual_evidence"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_opportunity_id" "uuid", "p_expected_opportunity_revision_id" "uuid", "p_expected_opportunity_revision" bigint, "p_reset_request_id" "uuid", "p_operation_id" "text", "p_operation_fingerprint" "text", "p_actor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare
  existing tongs.reference_visual_evidence_resets%rowtype;
  current_opp tongs.reference_visual_opportunity_revisions%rowtype;
begin
  if not tongs.has_workspace_role(p_workspace_id,'editor') or auth.uid() is distinct from p_actor_id then
    raise exception 'workspace editor authority required' using errcode='42501';
  end if;
  if p_reset_request_id is null then
    return jsonb_build_object('disposition','reset_request_id_required');
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_workspace_id::text||':'||p_opportunity_id::text||':'||p_reset_request_id::text,0));
  select * into existing from tongs.reference_visual_evidence_resets
  where operation_id=p_operation_id or(
    workspace_id=p_workspace_id and workpiece_id=p_workpiece_id
    and opportunity_id=p_opportunity_id and reset_request_id=p_reset_request_id
  );
  if found then
    if existing.operation_fingerprint<>p_operation_fingerprint then
      return jsonb_build_object('disposition','operation_identity_conflict');
    end if;
    return jsonb_build_object('disposition','committed','reset_id',existing.id,
      'reset_at',existing.reset_at,'sources_preserved',true,'source_use_preserved',true,
      'rights_preserved',true,'replay',true);
  end if;
  select o.* into current_opp
  from tongs.reference_visual_plan_sequences ps
  join tongs.reference_visual_plan_membership pm
    on pm.plan_revision_id=ps.current_plan_revision_id and pm.opportunity_id=p_opportunity_id
  join tongs.reference_visual_opportunity_revisions o on o.id=pm.opportunity_revision_id
  where ps.workspace_id=p_workspace_id and ps.workpiece_id=p_workpiece_id;
  if current_opp.id is null or current_opp.id is distinct from p_expected_opportunity_revision_id
    or current_opp.revision<>p_expected_opportunity_revision then
    return jsonb_build_object('disposition','opportunity_revision_conflict');
  end if;
  insert into tongs.reference_visual_evidence_resets(
    operation_id,operation_fingerprint,workspace_id,workpiece_id,opportunity_id,reset_request_id,
    opportunity_revision_id,opportunity_revision,reset_by,reset_at
  ) values(
    p_operation_id,p_operation_fingerprint,p_workspace_id,p_workpiece_id,p_opportunity_id,p_reset_request_id,
    current_opp.id,current_opp.revision,p_actor_id,clock_timestamp()
  ) returning * into existing;
  return jsonb_build_object('disposition','committed','reset_id',existing.id,
    'reset_at',existing.reset_at,'sources_preserved',true,'source_use_preserved',true,
    'rights_preserved',true,'replay',false);
end$$;


ALTER FUNCTION "tongs"."reset_reference_visual_evidence"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_opportunity_id" "uuid", "p_expected_opportunity_revision_id" "uuid", "p_expected_opportunity_revision" bigint, "p_reset_request_id" "uuid", "p_operation_id" "text", "p_operation_fingerprint" "text", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."resolve_account_authority_classification"("p_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_row tongs.account_authority_classifications%rowtype;
begin
  if coalesce(current_setting('request.jwt.claim.role', true), '') <> 'service_role' then
    raise exception 'service role required' using errcode = '42501';
  end if;
  if p_user_id is null then
    raise exception 'account user id required' using errcode = '22023';
  end if;

  select * into v_row
  from tongs.account_authority_classifications
  where user_id = p_user_id;

  if not found then
    return jsonb_build_object(
      'user_id', p_user_id,
      'account_class', 'customer',
      'revision', null,
      'configured_at', null,
      'explicit', false
    );
  end if;

  return jsonb_build_object(
    'user_id', v_row.user_id,
    'account_class', v_row.account_class,
    'revision', v_row.revision,
    'configured_at', v_row.configured_at,
    'explicit', true
  );
end
$$;


ALTER FUNCTION "tongs"."resolve_account_authority_classification"("p_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."resolve_account_authority_classification"("p_user_id" "uuid") IS 'Service-only current account authority resolver. Missing rows resolve to the customer default without creating state.';



CREATE OR REPLACE FUNCTION "tongs"."resolve_active_compound_ai_pricing_policy"("p_provider" "text", "p_model" "text", "p_model_snapshot" "text", "p_media_kind" "text", "p_endpoint" "text", "p_size" "text", "p_quality" "text", "p_effective_at" timestamp with time zone DEFAULT "now"()) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_revision_id uuid;
  v_count integer;
begin
  select count(*), (array_agg(r.id order by r.id))[1]
    into v_count, v_revision_id
  from tongs.ai_pricing_policy_revisions r
  join tongs.ai_pricing_policy_sequences s on s.current_revision_id = r.id
  where r.pricing_contract_version = 'compound_v2'
    and r.is_active
    and r.provider = lower(btrim(p_provider))
    and r.model = btrim(p_model)
    and r.model_snapshot = btrim(p_model_snapshot)
    and r.media_kind = lower(btrim(p_media_kind))
    and r.endpoint = btrim(p_endpoint)
    and r.effective_from <= p_effective_at
    and (r.effective_through is null or r.effective_through > p_effective_at)
    and (r.billable_dimensions->'sizes') ? p_size
    and (r.billable_dimensions->'qualities') ? p_quality;
  if v_count = 0 then
    raise exception 'active compound pricing policy not found' using errcode = 'P0002';
  elsif v_count > 1 then
    raise exception 'ambiguous active compound pricing policy' using errcode = 'P0003';
  end if;
  return tongs.read_ai_pricing_policy(v_revision_id);
end;
$$;


ALTER FUNCTION "tongs"."resolve_active_compound_ai_pricing_policy"("p_provider" "text", "p_model" "text", "p_model_snapshot" "text", "p_media_kind" "text", "p_endpoint" "text", "p_size" "text", "p_quality" "text", "p_effective_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."resolve_ai_access_policy"("p_org_id" "uuid", "p_workspace_id" "uuid", "p_user_id" "uuid", "p_tool" "text", "p_feature" "text" DEFAULT NULL::"text", "p_action" "text" DEFAULT NULL::"text", "p_requested_mode" "tongs"."ai_mode" DEFAULT NULL::"tongs"."ai_mode", "p_personal_ai_configured" boolean DEFAULT false, "p_org_ai_available" boolean DEFAULT true, "p_requested_funding_source" "tongs"."ai_funding_source" DEFAULT NULL::"tongs"."ai_funding_source", "p_estimated_cost_usd" numeric DEFAULT NULL::numeric, "p_provider" "text" DEFAULT NULL::"text", "p_model" "text" DEFAULT NULL::"text", "p_request_id" "text" DEFAULT NULL::"text", "p_write_ledger" boolean DEFAULT true) RETURNS TABLE("decision_type" "tongs"."ai_decision_type", "reason_code" "text", "selected_funding_source" "tongs"."ai_funding_source", "fallback_available" boolean, "fallback_used" boolean, "effective_policy_snapshot" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
begin
  if coalesce(auth.role(), '') <> 'service_role' and auth.uid() is distinct from p_user_id then
    raise exception 'policy may only be resolved for the current user' using errcode = '42501';
  end if;
  if coalesce(auth.role(), '') <> 'service_role'
     and p_org_id is not null
     and not exists (
       select 1 from tongs.org_members membership
       where membership.org_id = p_org_id and membership.user_id = auth.uid()
     ) then
    raise exception 'organization membership required' using errcode = '42501';
  end if;
  if coalesce(auth.role(), '') <> 'service_role'
     and p_workspace_id is not null
     and not tongs.has_workspace_role(p_workspace_id, 'viewer') then
    raise exception 'workspace viewer authority required' using errcode = '42501';
  end if;

  return query
  select resolved.decision_type,
    resolved.reason_code,
    resolved.selected_funding_source,
    resolved.fallback_available,
    resolved.fallback_used,
    coalesce(resolved.effective_policy_snapshot, '{}'::jsonb) - 'caps'
  from tongs.resolve_ai_policy(
    p_org_id,
    p_workspace_id,
    p_user_id,
    p_tool,
    p_feature,
    p_action,
    p_requested_mode,
    p_personal_ai_configured,
    p_org_ai_available,
    p_requested_funding_source,
    p_estimated_cost_usd,
    p_provider,
    p_model,
    p_request_id,
    p_write_ledger
  ) resolved;
end;
$$;


ALTER FUNCTION "tongs"."resolve_ai_access_policy"("p_org_id" "uuid", "p_workspace_id" "uuid", "p_user_id" "uuid", "p_tool" "text", "p_feature" "text", "p_action" "text", "p_requested_mode" "tongs"."ai_mode", "p_personal_ai_configured" boolean, "p_org_ai_available" boolean, "p_requested_funding_source" "tongs"."ai_funding_source", "p_estimated_cost_usd" numeric, "p_provider" "text", "p_model" "text", "p_request_id" "text", "p_write_ledger" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."resolve_ai_policy"("p_org_id" "uuid", "p_workspace_id" "uuid", "p_user_id" "uuid", "p_tool" "text", "p_feature" "text" DEFAULT NULL::"text", "p_action" "text" DEFAULT NULL::"text", "p_requested_mode" "tongs"."ai_mode" DEFAULT NULL::"tongs"."ai_mode", "p_personal_ai_configured" boolean DEFAULT false, "p_org_ai_available" boolean DEFAULT true, "p_requested_funding_source" "tongs"."ai_funding_source" DEFAULT NULL::"tongs"."ai_funding_source", "p_estimated_cost_usd" numeric DEFAULT NULL::numeric, "p_provider" "text" DEFAULT NULL::"text", "p_model" "text" DEFAULT NULL::"text", "p_request_id" "text" DEFAULT NULL::"text", "p_write_ledger" boolean DEFAULT true) RETURNS TABLE("decision_type" "tongs"."ai_decision_type", "reason_code" "text", "selected_funding_source" "tongs"."ai_funding_source", "fallback_available" boolean, "fallback_used" boolean, "effective_policy_snapshot" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare
  v_membership record;
  v_feature_key text := lower(btrim(coalesce(p_feature, '')));
begin
  if p_user_id is null then
    raise exception 'p_user_id required'
      using errcode = '22023';
  end if;

  if nullif(btrim(coalesce(p_tool, '')), '') is null then
    raise exception 'p_tool required'
      using errcode = '22023';
  end if;

  select *
  into v_membership
  from tongs.resolve_membership_entitlement(p_user_id, p_org_id, p_workspace_id);

  if not coalesce(v_membership.org_toolbox_allowed, false) then
    return query
    select
      'HARD_DENY'::tongs.ai_decision_type,
      'MEMBERSHIP_REQUIRED_STUDIO_OR_FOUNDER'::text,
      null::tongs.ai_funding_source,
      false,
      false,
      jsonb_build_object(
        'membership_required', true,
        'profile_tier', v_membership.profile_tier,
        'active_plan_code', v_membership.active_plan_code,
        'source_meta', v_membership.source_meta
      );
    return;
  end if;

  -- Explicit exclusion: Forge credit funding does not cover image-generation flows.
  if v_feature_key = 'image_generation'
     and p_requested_funding_source in (
       'org_shared_credits'::tongs.ai_funding_source,
       'forge_managed_credits'::tongs.ai_funding_source,
       'personal_credits'::tongs.ai_funding_source
     ) then
    if coalesce(p_personal_ai_configured, false) then
      return query
      select
        'SOFT_DENY'::tongs.ai_decision_type,
        'NO_VALID_FUNDING_SOURCE'::text,
        null::tongs.ai_funding_source,
        true,
        false,
        jsonb_build_object(
          'image_generation_credit_excluded', true,
          'feature', 'image_generation',
          'recommended_funding', 'personal_byo_key'
        );
      return;
    end if;

    return query
    select
      'HARD_DENY'::tongs.ai_decision_type,
      'PERSONAL_AI_REQUIRED_NOT_CONFIGURED'::text,
      null::tongs.ai_funding_source,
      false,
      false,
      jsonb_build_object(
        'image_generation_credit_excluded', true,
        'feature', 'image_generation',
        'requires_personal_byo', true
      );
    return;
  end if;

  return query
  select *
  from tongs.resolve_ai_policy_legacy(
    p_org_id,
    p_workspace_id,
    p_user_id,
    p_tool,
    p_feature,
    p_action,
    p_requested_mode,
    p_personal_ai_configured,
    p_org_ai_available,
    p_requested_funding_source,
    p_estimated_cost_usd,
    p_provider,
    p_model,
    p_request_id,
    p_write_ledger
  );
end;
$$;


ALTER FUNCTION "tongs"."resolve_ai_policy"("p_org_id" "uuid", "p_workspace_id" "uuid", "p_user_id" "uuid", "p_tool" "text", "p_feature" "text", "p_action" "text", "p_requested_mode" "tongs"."ai_mode", "p_personal_ai_configured" boolean, "p_org_ai_available" boolean, "p_requested_funding_source" "tongs"."ai_funding_source", "p_estimated_cost_usd" numeric, "p_provider" "text", "p_model" "text", "p_request_id" "text", "p_write_ledger" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."resolve_ai_policy_legacy"("p_org_id" "uuid", "p_workspace_id" "uuid", "p_user_id" "uuid", "p_tool" "text", "p_feature" "text" DEFAULT NULL::"text", "p_action" "text" DEFAULT NULL::"text", "p_requested_mode" "tongs"."ai_mode" DEFAULT NULL::"tongs"."ai_mode", "p_personal_ai_configured" boolean DEFAULT false, "p_org_ai_available" boolean DEFAULT true, "p_requested_funding_source" "tongs"."ai_funding_source" DEFAULT NULL::"tongs"."ai_funding_source", "p_estimated_cost_usd" numeric DEFAULT NULL::numeric, "p_provider" "text" DEFAULT NULL::"text", "p_model" "text" DEFAULT NULL::"text", "p_request_id" "text" DEFAULT NULL::"text", "p_write_ledger" boolean DEFAULT true) RETURNS TABLE("decision_type" "tongs"."ai_decision_type", "reason_code" "text", "selected_funding_source" "tongs"."ai_funding_source", "fallback_available" boolean, "fallback_used" boolean, "effective_policy_snapshot" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare
  v_membership record;
  v_org_policy tongs.organization_ai_policy%rowtype;
  v_member_policy tongs.member_ai_policy%rowtype;
  v_resolved_mode tongs.ai_mode := 'ORG_FIRST_PERSONAL_FALLBACK'::tongs.ai_mode;
  v_decision tongs.ai_decision_type;
  v_reason text := null;
  v_selected_funding tongs.ai_funding_source := null;
  v_fallback_available boolean := false;
  v_fallback_used boolean := false;
  v_fallback_from tongs.ai_funding_source := null;
  v_fallback_to tongs.ai_funding_source := null;
  v_effective_snapshot jsonb := '{}'::jsonb;
  v_feature_key text := lower(btrim(coalesce(p_feature, '')));
  v_org_features jsonb := jsonb_build_object(
    'heavy_tasks', true,
    'image_generation', true,
    'research_flows', true
  );
  v_org_monthly_cap numeric := null;
  v_member_monthly_cap numeric := null;
  v_org_usage_month numeric := 0;
  v_member_usage_month numeric := 0;
  v_org_allowed boolean := false;
  v_personal_allowed boolean := false;
  v_mode_from text := 'org_default';
  v_org_fallback_allowed boolean := true;
begin
  if p_user_id is null then
    raise exception 'p_user_id required'
      using errcode = '22023';
  end if;

  if nullif(btrim(coalesce(p_tool, '')), '') is null then
    raise exception 'p_tool required'
      using errcode = '22023';
  end if;

  select *
  into v_membership
  from tongs.resolve_membership_entitlement(p_user_id, p_org_id, p_workspace_id);

  select *
  into v_org_policy
  from tongs.organization_ai_policy op
  where op.org_id = p_org_id;

  select *
  into v_member_policy
  from tongs.member_ai_policy mp
  where mp.org_id = p_org_id
    and mp.user_id = p_user_id;

  if found then
    null;
  end if;

  if v_org_policy.org_id is not null then
    v_resolved_mode := v_org_policy.default_mode;
    v_mode_from := 'org_default';
    v_org_features := coalesce(v_org_policy.feature_flags, v_org_features);
    v_org_monthly_cap := v_org_policy.org_monthly_cap_usd;
    v_org_fallback_allowed := v_org_policy.fallback_allowed;
  end if;

  if v_member_policy.org_id is not null then
    if not v_member_policy.ai_enabled then
      v_resolved_mode := 'AI_DISABLED'::tongs.ai_mode;
      v_mode_from := 'member_ai_enabled_false';
    elsif v_member_policy.mode_override is not null then
      v_resolved_mode := v_member_policy.mode_override;
      v_mode_from := 'member_override';
    end if;

    v_member_monthly_cap := v_member_policy.monthly_cap_usd;
  end if;

  if p_requested_mode is not null then
    v_resolved_mode := p_requested_mode;
    v_mode_from := 'request_override';
  end if;

  v_org_allowed :=
    coalesce(v_org_policy.shared_org_ai_enabled, true)
    and coalesce(p_org_ai_available, true)
    and coalesce(v_membership.org_toolbox_allowed, false);

  v_personal_allowed :=
    coalesce(v_org_policy.member_byo_allowed, true)
    and coalesce(p_personal_ai_configured, false);

  v_fallback_available :=
    (v_resolved_mode = 'ORG_FIRST_PERSONAL_FALLBACK'::tongs.ai_mode)
    and coalesce(v_org_fallback_allowed, true)
    and v_personal_allowed;

  if v_feature_key in ('heavy_tasks', 'image_generation', 'research_flows') then
    if coalesce((v_org_features ->> v_feature_key)::boolean, true) = false then
      v_decision := 'HARD_DENY';
      if v_feature_key = 'heavy_tasks' then
        v_reason := 'FEATURE_DISABLED_HEAVY_TASKS';
      elsif v_feature_key = 'image_generation' then
        v_reason := 'FEATURE_DISABLED_IMAGE';
      else
        v_reason := 'FEATURE_DISABLED_RESEARCH';
      end if;
    elsif v_member_policy.org_id is not null then
      if v_feature_key = 'heavy_tasks' and not v_member_policy.allow_heavy_tasks then
        v_decision := 'HARD_DENY';
        v_reason := 'FEATURE_DISABLED_HEAVY_TASKS';
      elsif v_feature_key = 'image_generation' and not v_member_policy.allow_image_generation then
        v_decision := 'HARD_DENY';
        v_reason := 'FEATURE_DISABLED_IMAGE';
      elsif v_feature_key = 'research_flows' and not v_member_policy.allow_research_flows then
        v_decision := 'HARD_DENY';
        v_reason := 'FEATURE_DISABLED_RESEARCH';
      end if;
    end if;
  end if;

  if v_decision is null then
    if v_resolved_mode = 'AI_DISABLED'::tongs.ai_mode then
      v_decision := 'HARD_DENY';
      v_reason := 'ORG_AI_DISABLED';
    elsif v_resolved_mode = 'ORG_ONLY'::tongs.ai_mode then
      if v_org_allowed then
        v_decision := 'ALLOW';
        v_selected_funding := coalesce(
          case
            when p_requested_funding_source in ('org_byo_key', 'org_shared_credits', 'forge_managed_credits')
              then p_requested_funding_source
            else null
          end,
          'org_shared_credits'::tongs.ai_funding_source
        );
      elsif not coalesce(v_membership.org_toolbox_allowed, false) then
        v_decision := 'HARD_DENY';
        v_reason := 'MEMBERSHIP_REQUIRED_STUDIO_OR_FOUNDER';
      else
        v_decision := 'HARD_DENY';
        v_reason := 'ORG_MEMBER_NOT_AUTHORIZED';
      end if;
    elsif v_resolved_mode = 'PERSONAL_ONLY'::tongs.ai_mode then
      if v_personal_allowed then
        v_decision := 'ALLOW';
        v_selected_funding := coalesce(
          case
            when p_requested_funding_source in ('personal_byo_key', 'personal_credits')
              then p_requested_funding_source
            else null
          end,
          'personal_byo_key'::tongs.ai_funding_source
        );
      else
        v_decision := 'SOFT_DENY';
        v_reason := 'PERSONAL_AI_REQUIRED_NOT_CONFIGURED';
      end if;
    else
      if v_org_allowed then
        v_decision := 'ALLOW';
        v_selected_funding := coalesce(
          case
            when p_requested_funding_source in ('org_byo_key', 'org_shared_credits', 'forge_managed_credits')
              then p_requested_funding_source
            else null
          end,
          'org_shared_credits'::tongs.ai_funding_source
        );
      elsif v_personal_allowed and coalesce(v_org_fallback_allowed, true) then
        v_decision := 'ALLOW';
        v_fallback_used := true;
        v_fallback_from := 'org_shared_credits'::tongs.ai_funding_source;
        v_fallback_to := coalesce(
          case
            when p_requested_funding_source in ('personal_byo_key', 'personal_credits')
              then p_requested_funding_source
            else null
          end,
          'personal_byo_key'::tongs.ai_funding_source
        );
        v_selected_funding := v_fallback_to;
      elsif not coalesce(v_membership.org_toolbox_allowed, false) and not v_personal_allowed then
        v_decision := 'HARD_DENY';
        v_reason := 'MEMBERSHIP_REQUIRED_STUDIO_OR_FOUNDER';
      else
        v_decision := 'SOFT_DENY';
        v_reason := 'NO_VALID_FUNDING_SOURCE';
      end if;
    end if;
  end if;

  if v_decision = 'ALLOW' and v_org_monthly_cap is not null and v_selected_funding in ('org_byo_key', 'org_shared_credits', 'forge_managed_credits') then
    select coalesce(sum(coalesce(l.actual_cost_usd, l.estimated_cost_usd, 0)), 0)
    into v_org_usage_month
    from tongs.ai_usage_ledger l
    where l.org_id = p_org_id
      and l.decision_type = 'ALLOW'
      and l.created_at >= date_trunc('month', now());

    if (v_org_usage_month + coalesce(p_estimated_cost_usd, 0)) > v_org_monthly_cap then
      if v_personal_allowed and v_resolved_mode = 'ORG_FIRST_PERSONAL_FALLBACK'::tongs.ai_mode and coalesce(v_org_fallback_allowed, true) then
        v_fallback_used := true;
        v_fallback_from := v_selected_funding;
        v_fallback_to := coalesce(
          case
            when p_requested_funding_source in ('personal_byo_key', 'personal_credits')
              then p_requested_funding_source
            else null
          end,
          'personal_byo_key'::tongs.ai_funding_source
        );
        v_selected_funding := v_fallback_to;
      else
        v_decision := 'HARD_DENY';
        v_reason := 'ORG_CAP_EXCEEDED';
        v_selected_funding := null;
      end if;
    end if;
  end if;

  if v_decision = 'ALLOW' and v_member_monthly_cap is not null then
    select coalesce(sum(coalesce(l.actual_cost_usd, l.estimated_cost_usd, 0)), 0)
    into v_member_usage_month
    from tongs.ai_usage_ledger l
    where l.user_id = p_user_id
      and l.org_id = p_org_id
      and l.decision_type = 'ALLOW'
      and l.created_at >= date_trunc('month', now());

    if (v_member_usage_month + coalesce(p_estimated_cost_usd, 0)) > v_member_monthly_cap then
      v_decision := 'HARD_DENY';
      v_reason := 'ORG_CAP_EXCEEDED';
      v_selected_funding := null;
    end if;
  end if;

  if v_decision <> 'ALLOW' and v_reason is null then
    v_reason := 'NO_VALID_FUNDING_SOURCE';
  end if;

  v_effective_snapshot := jsonb_build_object(
    'resolved_mode', v_resolved_mode,
    'mode_source', v_mode_from,
    'caps', jsonb_build_object(
      'org_monthly_cap_usd', v_org_monthly_cap,
      'member_monthly_cap_usd', v_member_monthly_cap,
      'org_usage_month_usd', v_org_usage_month,
      'member_usage_month_usd', v_member_usage_month
    ),
    'feature_flags', jsonb_build_object(
      'org', v_org_features,
      'member', jsonb_build_object(
        'allow_heavy_tasks', coalesce(v_member_policy.allow_heavy_tasks, true),
        'allow_image_generation', coalesce(v_member_policy.allow_image_generation, true),
        'allow_research_flows', coalesce(v_member_policy.allow_research_flows, true)
      )
    ),
    'membership_entitlement', jsonb_build_object(
      'profile_tier', v_membership.profile_tier,
      'active_plan_code', v_membership.active_plan_code,
      'founders_club_flag', v_membership.founders_club_flag,
      'is_founder_entitled', v_membership.is_founder_entitled,
      'is_studio_entitled', v_membership.is_studio_entitled,
      'org_toolbox_allowed', v_membership.org_toolbox_allowed,
      'workspace_role', v_membership.workspace_role,
      'org_role', v_membership.org_role,
      'source_meta', v_membership.source_meta
    ),
    'fallback', jsonb_build_object(
      'available', v_fallback_available,
      'used', v_fallback_used,
      'from', v_fallback_from,
      'to', v_fallback_to,
      'org_fallback_allowed', v_org_fallback_allowed
    ),
    'inputs', jsonb_build_object(
      'requested_mode', p_requested_mode,
      'requested_funding_source', p_requested_funding_source,
      'personal_ai_configured', coalesce(p_personal_ai_configured, false),
      'org_ai_available', coalesce(p_org_ai_available, true),
      'tool', btrim(p_tool),
      'feature', nullif(btrim(coalesce(p_feature, '')), ''),
      'action', nullif(btrim(coalesce(p_action, '')), '')
    )
  );

  if coalesce(p_write_ledger, true) then
    insert into tongs.ai_usage_ledger (
      org_id,
      workspace_id,
      user_id,
      tool,
      feature,
      action,
      provider,
      model,
      funding_source,
      estimated_cost_usd,
      actual_cost_usd,
      decision_type,
      reason_code,
      fallback_available,
      fallback_used,
      fallback_from,
      fallback_to,
      request_id,
      effective_policy_snapshot
    )
    values (
      p_org_id,
      p_workspace_id,
      p_user_id,
      btrim(p_tool),
      nullif(btrim(coalesce(p_feature, '')), ''),
      nullif(btrim(coalesce(p_action, '')), ''),
      nullif(btrim(coalesce(p_provider, '')), ''),
      nullif(btrim(coalesce(p_model, '')), ''),
      v_selected_funding,
      p_estimated_cost_usd,
      null,
      v_decision,
      v_reason,
      v_fallback_available,
      v_fallback_used,
      v_fallback_from,
      v_fallback_to,
      nullif(btrim(coalesce(p_request_id, '')), ''),
      v_effective_snapshot
    );
  end if;

  return query
  select
    v_decision,
    v_reason,
    v_selected_funding,
    v_fallback_available,
    v_fallback_used,
    v_effective_snapshot;
end;
$$;


ALTER FUNCTION "tongs"."resolve_ai_policy_legacy"("p_org_id" "uuid", "p_workspace_id" "uuid", "p_user_id" "uuid", "p_tool" "text", "p_feature" "text", "p_action" "text", "p_requested_mode" "tongs"."ai_mode", "p_personal_ai_configured" boolean, "p_org_ai_available" boolean, "p_requested_funding_source" "tongs"."ai_funding_source", "p_estimated_cost_usd" numeric, "p_provider" "text", "p_model" "text", "p_request_id" "text", "p_write_ledger" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."resolve_bellows_join_link"("p_session_id" "text", "p_token" "text") RETURNS TABLE("join_link_id" "uuid", "session_id" "text", "workspace_id" "uuid", "role_code" "text", "title" "text", "host_user_id" "text", "lifecycle_state" "text", "expires_at" timestamp with time zone, "max_uses" integer, "use_count" integer, "last_used_at" timestamp with time zone, "resolved_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare
  v_now timestamptz := now();
  v_join_link tongs.bellows_session_join_links%rowtype;
  v_resolution record;
begin
  if p_session_id is null or btrim(p_session_id) = '' then
    return;
  end if;

  if p_token is null or btrim(p_token) = '' then
    return;
  end if;

  select
    jl.*,
    s.title as session_title,
    s.host_user_id as session_host_user_id,
    s.lifecycle_state as session_lifecycle_state
  into v_resolution
  from tongs.bellows_session_join_links jl
  join tongs.bellows_sessions s
    on s.id = jl.session_id
  where jl.session_id = btrim(p_session_id)
    and jl.token_hash = tongs.hash_bellows_join_link_token(p_token)
  for update of jl;

  if not found then
    return;
  end if;

  if v_resolution.revoked_at is not null then
    return;
  end if;

  if v_resolution.expires_at <= v_now then
    return;
  end if;

  if v_resolution.use_count >= v_resolution.max_uses then
    return;
  end if;

  if v_resolution.session_lifecycle_state in ('sealed', 'incomplete_capture', 'failed_capture', 'archived') then
    return;
  end if;

  update tongs.bellows_session_join_links jl
  set
    use_count = jl.use_count + 1,
    last_used_at = v_now,
    updated_at = v_now
  where jl.id = v_resolution.id
  returning *
  into v_join_link;

  return query
  select
    v_join_link.id,
    v_join_link.session_id,
    v_join_link.workspace_id,
    v_join_link.role_code,
    v_resolution.session_title,
    v_resolution.session_host_user_id,
    v_resolution.session_lifecycle_state,
    v_join_link.expires_at,
    v_join_link.max_uses,
    v_join_link.use_count,
    v_join_link.last_used_at,
    v_now;
end;
$$;


ALTER FUNCTION "tongs"."resolve_bellows_join_link"("p_session_id" "text", "p_token" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."resolve_canonical_asset_authority"("p_workspace_id" "uuid", "p_canonical_asset_id" "uuid", "p_expected_workpiece_id" "uuid" DEFAULT NULL::"uuid", "p_required_asset_kind" "text" DEFAULT NULL::"text", "p_expected_content_hash" "text" DEFAULT NULL::"text", "p_expected_storage_bucket" "text" DEFAULT NULL::"text", "p_expected_storage_key" "text" DEFAULT NULL::"text", "p_expected_path" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $_$
declare
  v_asset tongs.assets%rowtype;
  v_state text;
  v_code text;
  v_duration bigint;
begin
  if auth.role() <> 'service_role' and not tongs.can_access_workspace(p_workspace_id) then
    raise exception 'workspace access required' using errcode='42501';
  end if;
  select * into v_asset from tongs.assets where id=p_canonical_asset_id;
  if not found then
    return jsonb_build_object('state','unresolved','code','canonical_asset_missing','canonical_asset_id',p_canonical_asset_id);
  end if;
  if v_asset.workspace_id <> p_workspace_id then
    return jsonb_build_object('state','relationship_mismatch','code','canonical_asset_workspace_mismatch','canonical_asset_id',p_canonical_asset_id);
  end if;
  if p_expected_workpiece_id is not null then
    if v_asset.asset_scope='workpiece' and v_asset.workpiece_id is distinct from p_expected_workpiece_id then
      return jsonb_build_object('state','relationship_mismatch','code','canonical_asset_workpiece_mismatch','canonical_asset_id',p_canonical_asset_id);
    end if;
    if v_asset.asset_scope='workspace' and v_asset.workspace_reuse_policy<>'allowed' then
      return jsonb_build_object('state','relationship_mismatch','code','canonical_asset_workspace_reuse_not_allowed','canonical_asset_id',p_canonical_asset_id);
    end if;
  end if;
  if p_required_asset_kind is not null and v_asset.asset_kind <> p_required_asset_kind then
    return jsonb_build_object('state','invalid','code','canonical_asset_kind_mismatch','canonical_asset_id',p_canonical_asset_id);
  end if;
  if p_expected_content_hash is not null and v_asset.content_hash is distinct from lower(p_expected_content_hash) then
    return jsonb_build_object('state','invalid','code','canonical_asset_hash_mismatch','canonical_asset_id',p_canonical_asset_id);
  end if;
  if (p_expected_storage_bucket is not null and v_asset.storage_bucket is distinct from p_expected_storage_bucket)
    or (p_expected_storage_key is not null and v_asset.storage_key is distinct from p_expected_storage_key)
    or (p_expected_path is not null and v_asset.path is distinct from p_expected_path) then
    return jsonb_build_object('state','invalid','code','canonical_asset_storage_evidence_mismatch','canonical_asset_id',p_canonical_asset_id);
  end if;
  if v_asset.provenance_classification='legacy_unresolved' then v_state:='unresolved'; v_code:='legacy_asset_unresolved';
  elsif v_asset.provenance_classification='conflicting_evidence' then v_state:='invalid'; v_code:='canonical_asset_conflicting_evidence';
  elsif v_asset.status='pending' then v_state:='processing'; v_code:=null;
  elsif v_asset.status<>'ready' then v_state:='invalid'; v_code:='canonical_asset_not_ready';
  elsif v_asset.content_hash is null or v_asset.ready_at is null then v_state:='invalid'; v_code:='canonical_asset_evidence_incomplete';
  elsif v_asset.mime_type like 'image/%' and (v_asset.width is null or v_asset.height is null) then v_state:='invalid'; v_code:='canonical_asset_intrinsic_metadata_missing';
  elsif v_asset.mime_type like 'video/%' and not (
    nullif(v_asset.metadata_json->>'duration_ms','') ~ '^[1-9][0-9]*$'
  ) then v_state:='invalid'; v_code:='canonical_asset_intrinsic_metadata_missing';
  else v_state:='ready'; v_code:=null;
  end if;
  v_duration:=case when nullif(v_asset.metadata_json->>'duration_ms','') ~ '^[0-9]+$' then (v_asset.metadata_json->>'duration_ms')::bigint else null end;
  return jsonb_strip_nulls(jsonb_build_object(
    'state',v_state,'code',v_code,
    'canonical_asset_id',v_asset.id,
    'workspace_id',v_asset.workspace_id,
    'scope',jsonb_strip_nulls(jsonb_build_object('kind',v_asset.asset_scope,'workpiece_id',v_asset.workpiece_id,'workspace_reuse_policy',v_asset.workspace_reuse_policy)),
    'asset_kind',v_asset.asset_kind,
    'content_hash',v_asset.content_hash,
    'storage_bucket',v_asset.storage_bucket,
    'storage_object_key',v_asset.storage_key,
    'path',v_asset.path,
    'mime_type',v_asset.mime_type,
    'bytes',v_asset.bytes,
    'intrinsic_width',v_asset.width,
    'intrinsic_height',v_asset.height,
    'duration_ms',v_duration,
    'asset_status',v_asset.status,
    'provenance_classification',v_asset.provenance_classification,
    'provenance',v_asset.provenance_json,
    'ready_at',v_asset.ready_at
  ));
end;
$_$;


ALTER FUNCTION "tongs"."resolve_canonical_asset_authority"("p_workspace_id" "uuid", "p_canonical_asset_id" "uuid", "p_expected_workpiece_id" "uuid", "p_required_asset_kind" "text", "p_expected_content_hash" "text", "p_expected_storage_bucket" "text", "p_expected_storage_key" "text", "p_expected_path" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."resolve_hammer_audio_master"("p_operation_id" "text", "p_operation_fingerprint" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare op tongs.hammer_audio_render_operations%rowtype; a tongs.assets%rowtype;
begin
  select * into op from tongs.hammer_audio_render_operations where operation_id=p_operation_id and operation_fingerprint=p_operation_fingerprint;
  if not found then return jsonb_build_object('disposition','operation_not_found'); end if;
  if auth.role()<>'service_role' and not tongs.has_workspace_role(op.workspace_id,'viewer') then raise exception 'Hammer audio master read denied' using errcode='42501'; end if;
  if op.state<>'completed' or op.output_asset_id is null then return jsonb_build_object('disposition','not_completed','state',op.state); end if;
  select * into a from tongs.assets where id=op.output_asset_id and workspace_id=op.workspace_id and workpiece_id=op.workpiece_id and asset_kind='hammer_audio_master';
  if not found then return jsonb_build_object('disposition','master_relationship_invalid'); end if;
  return jsonb_build_object('disposition','resolved','operation',to_jsonb(op),'asset',to_jsonb(a),'receipt',op.receipt_json);
end$$;


