CREATE OR REPLACE FUNCTION "tongs"."resolve_hearth_chat_paid_execution_context"("p_operation_id" "text", "p_reservation_id" "uuid", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_workpiece_id" "text", "p_request_fingerprint" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $_$
declare
  v_binding tongs.openai_text_funding_bindings%rowtype;
  v_reservation tongs.funding_reservations%rowtype;
  v_quote tongs.customer_spending_quotes%rowtype;
  v_cost tongs.openai_text_cost_policy_revisions%rowtype;
  v_rollout tongs.openai_text_rollout_revisions%rowtype;
  v_rate tongs.openai_text_provider_rate_revisions%rowtype;
  v_rate_id uuid;
  v_failure_limit bigint;
begin
  perform tongs._require_pricing_service_role();
  if length(btrim(coalesce(p_operation_id,'')))<8 or p_reservation_id is null or p_user_id is null
     or length(btrim(coalesce(p_workpiece_id,'')))<1
     or p_request_fingerprint !~ '^[0-9a-f]{64}$' then
    raise exception 'invalid Hearth paid execution handle' using errcode='22023';
  end if;
  select * into v_binding from tongs.openai_text_funding_bindings
    where operation_id=btrim(p_operation_id) and reservation_id=p_reservation_id;
  if not found or v_binding.route_code<>'hearth.chat_completion' then
    raise exception 'funded Hearth chat binding required' using errcode='P0002';
  end if;
  select * into v_reservation from tongs.funding_reservations where id=p_reservation_id;
  select * into v_quote from tongs.customer_spending_quotes where id=v_reservation.quote_id;
  if not found or v_reservation.user_id<>p_user_id or v_quote.user_id<>p_user_id
     or v_quote.operation_id<>v_binding.operation_id
     or v_quote.workspace_id is distinct from p_workspace_id
     or v_quote.request_fingerprint<>p_request_fingerprint
     or not exists(select 1 from tongs.customer_spending_quote_acceptances a
       where a.quote_id=v_quote.id and a.user_id=p_user_id) then
    raise exception 'accepted reserved Hearth funding context does not match request' using errcode='42501';
  end if;
  select * into v_cost from tongs.openai_text_cost_policy_revisions where id=v_binding.cost_policy_revision_id;
  select * into v_rollout from tongs._current_openai_text_rollout(v_binding.route_code);
  if v_cost.id is null or v_rollout.route_code is null or v_rollout.mode<>'enforce'
     or v_rollout.cost_policy_revision_id is distinct from v_binding.cost_policy_revision_id
     or v_cost.lifecycle_state not in ('pilot_candidate','active') or v_cost.cost_coverage<>'complete'
     or v_reservation.reserved_wholesale_spend_micros<>v_cost.full_cost_ceiling_micros then
    raise exception 'Hearth chat execution is not activated for the accepted cost revision' using errcode='42501';
  end if;
  v_rate_id:=nullif(v_cost.attempt_plan->0->>'rate_revision_id','')::uuid;
  select * into v_rate from tongs.openai_text_provider_rate_revisions where id=v_rate_id;
  if not found or v_rate.provider_model_id<>v_binding.model then
    raise exception 'pricing_not_configured: exact OpenAI model rate missing' using errcode='P0001';
  end if;
  v_failure_limit:=case when v_binding.credential_funding='forge' then v_cost.full_cost_ceiling_micros else 0 end;
  return jsonb_build_object(
    'operation_id',v_binding.operation_id,
    'reservation_id',v_binding.reservation_id,
    'quote_id',v_reservation.quote_id,
    'route_code',v_binding.route_code,
    'user_id',v_reservation.user_id,
    'workspace_id',v_quote.workspace_id,
    'workpiece_id',btrim(p_workpiece_id),
    'request_fingerprint',v_quote.request_fingerprint,
    'funding_source_type',v_reservation.funding_source_type,
    'funding_source_id',v_reservation.funding_source_id,
    'credential_funding',v_binding.credential_funding,
    'model',v_binding.model,
    'maximum_input_units',v_binding.maximum_input_units,
    'maximum_output_units',v_binding.maximum_output_units,
    'maximum_attempts',v_binding.maximum_attempts,
    'maximum_failure_exposure_micros',v_failure_limit,
    'direct_provider_ceiling_micros',v_cost.direct_provider_ceiling_micros,
    'supporting_cost_ceiling_micros',v_cost.supporting_cost_ceiling_micros,
    'full_cost_ceiling_micros',v_cost.full_cost_ceiling_micros,
    'input_micros_per_million_tokens',v_rate.input_micros_per_million_tokens,
    'cached_input_micros_per_million_tokens',v_rate.cached_input_micros_per_million_tokens,
    'output_micros_per_million_tokens',v_rate.output_micros_per_million_tokens,
    'cost_policy_revision_id',v_cost.id,
    'rollout_revision',v_rollout.revision
    ,'reservation_state',tongs._funding_reservation_state(p_reservation_id)
  );
end $_$;


ALTER FUNCTION "tongs"."resolve_hearth_chat_paid_execution_context"("p_operation_id" "text", "p_reservation_id" "uuid", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_workpiece_id" "text", "p_request_fingerprint" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."resolve_hearth_chat_paid_execution_context"("p_operation_id" "text", "p_reservation_id" "uuid", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_workpiece_id" "text", "p_request_fingerprint" "text") IS 'Resolves immutable accepted funding and pricing bounds for the server-owned Hearth execution adapter; browser-supplied monetary fields are never accepted.';



CREATE OR REPLACE FUNCTION "tongs"."resolve_hearth_chat_test_execution_context"("p_operation_id" "text", "p_reservation_id" "uuid", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_workpiece_id" "text", "p_request_fingerprint" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare v_res tongs.test_funding_reservations%rowtype; v_quote tongs.test_customer_spending_quotes%rowtype;
begin
  perform tongs._require_pricing_service_role();
  select * into v_res from tongs.test_funding_reservations where id=p_reservation_id;
  select * into v_quote from tongs.test_customer_spending_quotes where id=v_res.quote_id;
  if v_res.operation_id<>p_operation_id or v_res.user_id<>p_user_id or v_quote.workspace_id<>p_workspace_id or v_quote.request_fingerprint<>p_request_fingerprint then raise exception 'Test execution context mismatch' using errcode='42501'; end if;
  return jsonb_build_object('operation_id',v_res.operation_id,'reservation_id',v_res.id,'quote_id',v_quote.id,'funding_source_type','customer_deposit','funding_source_id',v_res.deposit_id,
    'credential_funding','forge','model','gpt-5.6-luna','maximum_input_units',2000,'maximum_output_units',512,'maximum_attempts',1,
    'maximum_failure_exposure_micros',0,'direct_provider_ceiling_micros',1015,'supporting_cost_ceiling_micros',10000,
    'input_micros_per_million_tokens',200000,'output_micros_per_million_tokens',1200000,'reservation_state',tongs._test_reservation_state(v_res.id),
    'execution_kind','simulated_test','real_provider_authorized',false);
end $$;


ALTER FUNCTION "tongs"."resolve_hearth_chat_test_execution_context"("p_operation_id" "text", "p_reservation_id" "uuid", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_workpiece_id" "text", "p_request_fingerprint" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."resolve_legacy_asset_reference_exact"("p_reference_id" "uuid", "p_canonical_asset_id" "uuid", "p_actor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $_$
declare
  v_ref tongs.asset_legacy_reference_evidence%rowtype;
  v_asset tongs.assets%rowtype;
  v_intrinsic jsonb;
  v_duration bigint;
begin
  if auth.role() <> 'service_role' then
    raise exception 'service authority required' using errcode='42501';
  end if;
  select * into v_ref from tongs.asset_legacy_reference_evidence where id=p_reference_id for update;
  if not found then return jsonb_build_object('disposition','legacy_reference_missing'); end if;
  if v_ref.classification in ('canonical_proven','legacy_resolved') then
    if v_ref.resolved_asset_id <> p_canonical_asset_id then
      return jsonb_build_object('disposition','conflicting_evidence');
    end if;
    return jsonb_build_object('disposition','already_resolved','canonical_asset_id',v_ref.resolved_asset_id);
  end if;
  select * into v_asset from tongs.assets
    where id=p_canonical_asset_id and workspace_id=v_ref.workspace_id;
  if not found then return jsonb_build_object('disposition','canonical_asset_missing'); end if;
  if v_ref.expected_workpiece_id is not null and not (
    (v_asset.asset_scope='workpiece' and v_asset.workpiece_id=v_ref.expected_workpiece_id)
    or (v_asset.asset_scope='workspace' and v_asset.workspace_reuse_policy='allowed')
  ) then return jsonb_build_object('disposition','canonical_asset_workpiece_mismatch'); end if;

  -- Exact storage identity or exact content hash is mandatory. Path is only corroboration.
  if not (
    (v_ref.storage_bucket_assertion is not null and v_ref.storage_key_assertion is not null
      and v_ref.storage_bucket_assertion=v_asset.storage_bucket and v_ref.storage_key_assertion=v_asset.storage_key)
    or
    (v_ref.content_hash_assertion is not null and v_ref.content_hash_assertion=v_asset.content_hash)
  ) then
    return jsonb_build_object('disposition','asset_relationship_unverified');
  end if;
  if v_ref.content_hash_assertion is not null and v_ref.content_hash_assertion is distinct from v_asset.content_hash then
    return jsonb_build_object('disposition','canonical_asset_hash_mismatch');
  end if;
  if v_ref.mime_type_assertion is not null and v_ref.mime_type_assertion is distinct from v_asset.mime_type then
    return jsonb_build_object('disposition','canonical_asset_kind_mismatch');
  end if;
  if v_ref.path_assertion is not null and v_ref.path_assertion is distinct from v_asset.path then
    return jsonb_build_object('disposition','conflicting_evidence');
  end if;
  v_intrinsic := coalesce(v_asset.metadata_json,'{}'::jsonb);
  v_duration := case
    when nullif(v_intrinsic->>'duration_ms','') ~ '^[0-9]+$'
      then (v_intrinsic->>'duration_ms')::bigint
    else null
  end;
  if v_ref.width_assertion is not null and v_ref.width_assertion is distinct from v_asset.width then return jsonb_build_object('disposition','conflicting_evidence'); end if;
  if v_ref.height_assertion is not null and v_ref.height_assertion is distinct from v_asset.height then return jsonb_build_object('disposition','conflicting_evidence'); end if;
  if v_ref.duration_ms_assertion is not null and v_ref.duration_ms_assertion is distinct from v_duration then
    return jsonb_build_object('disposition','conflicting_evidence');
  end if;

  update tongs.asset_legacy_reference_evidence
  set classification='legacy_resolved', resolved_asset_id=v_asset.id, resolved_at=now(),
      resolution_evidence_json=jsonb_build_object(
        'resolver','tongs.resolve_legacy_asset_reference_exact.v1',
        'actor_id',p_actor_id,
        'canonical_asset_id',v_asset.id,
        'content_hash',v_asset.content_hash,
        'storage_bucket',v_asset.storage_bucket,
        'storage_key',v_asset.storage_key
      )
  where id=v_ref.id;
  return jsonb_build_object('disposition','legacy_resolved','canonical_asset_id',v_asset.id);
end;
$_$;


ALTER FUNCTION "tongs"."resolve_legacy_asset_reference_exact"("p_reference_id" "uuid", "p_canonical_asset_id" "uuid", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."resolve_membership_entitlement"("p_user_id" "uuid", "p_org_id" "uuid", "p_workspace_id" "uuid" DEFAULT NULL::"uuid") RETURNS TABLE("profile_tier" "text", "active_plan_code" "text", "founders_club_flag" boolean, "is_founder_entitled" boolean, "is_studio_entitled" boolean, "org_toolbox_allowed" boolean, "workspace_role" "text", "org_role" "text", "source_meta" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $_$
declare
  v_profile_tier text := 'free';
  v_plan_code text;
  v_plan_entitled boolean := false;
  v_workspace_role text;
  v_org_role text;
  v_from_profile_founder boolean := false;
  v_from_user_plan_founder boolean := false;
  v_from_public_balance_founder boolean := false;
  v_founders boolean := false;
begin
  if p_user_id is null then
    raise exception 'p_user_id required' using errcode = '22023';
  end if;

  if pg_catalog.to_regclass('public.profiles') is not null then
    execute $sql$
      select lower(btrim(btrim(coalesce(p.tier, 'free'), '"')))
      from public.profiles p
      where p.user_id = $1
    $sql$ into v_profile_tier using p_user_id;
    v_profile_tier := coalesce(v_profile_tier, 'free');
  end if;

  select lower(btrim(coalesce(ab.plan_item_id, ''))), coalesce(ab.plan_entitled, false)
  into v_plan_code, v_plan_entitled
  from tongs.account_balances ab
  where ab.user_id = p_user_id;
  if v_plan_code = '' then v_plan_code := null; end if;

  v_from_profile_founder := v_profile_tier in ('founder', 'founders_club', 'founders club', 'founder''s club');

  if pg_catalog.to_regclass('public.user_plans') is not null then
    execute $sql$
      select exists (select 1 from public.user_plans up where up.user_id = $1
        and coalesce(up.is_founder, false) and coalesce(up.status, '') in ('active', 'trialing'))
    $sql$ into v_from_user_plan_founder using p_user_id;
  end if;

  if pg_catalog.to_regclass('public.account_balances') is not null
     and exists (select 1 from information_schema.columns c where c.table_schema = 'public'
       and c.table_name = 'account_balances' and c.column_name = 'founders_club') then
    execute $sql$
      select coalesce(ab.founders_club, false) from public.account_balances ab
      where ab.user_id = $1 limit 1
    $sql$ into v_from_public_balance_founder using p_user_id;
    v_from_public_balance_founder := coalesce(v_from_public_balance_founder, false);
  end if;

  v_founders := v_from_profile_founder or v_from_user_plan_founder or v_from_public_balance_founder;

  if p_workspace_id is not null then
    select case when w.created_by = p_user_id then 'owner' else wm.role end
    into v_workspace_role from tongs.workspaces w
    left join tongs.workspace_members wm on wm.workspace_id = w.id and wm.user_id = p_user_id
    where w.id = p_workspace_id limit 1;
  end if;

  if p_org_id is not null then
    select om.org_role into v_org_role from tongs.org_members om
    where om.org_id = p_org_id and om.user_id = p_user_id limit 1;
  end if;

  return query select
    v_profile_tier, v_plan_code, v_founders, v_founders,
    ((v_plan_entitled and v_plan_code = 'studio') or v_profile_tier = 'studio'),
    (v_founders or (v_plan_entitled and v_plan_code in ('creator', 'pro', 'studio'))),
    v_workspace_role, v_org_role,
    jsonb_build_object('profile_tier', v_profile_tier, 'plan_item_id', v_plan_code,
      'plan_entitled', v_plan_entitled, 'legacy_profile_available', pg_catalog.to_regclass('public.profiles') is not null,
      'founder_sources', jsonb_build_object('profile_tier', v_from_profile_founder,
        'public_user_plans', v_from_user_plan_founder,
        'public_account_balances_founders_club', v_from_public_balance_founder));
end;
$_$;


ALTER FUNCTION "tongs"."resolve_membership_entitlement"("p_user_id" "uuid", "p_org_id" "uuid", "p_workspace_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."resolve_openai_text_model_for_funding_quote"("p_user_id" "uuid", "p_workspace_id" "uuid", "p_route_code" "text", "p_credential_funding" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
begin
 perform tongs._require_pricing_service_role();
 perform tongs._resolve_spending_authority(p_user_id,p_workspace_id,p_route_code);
 return tongs.resolve_openai_text_model_for_quote(p_user_id,p_route_code,p_credential_funding);
end $$;


ALTER FUNCTION "tongs"."resolve_openai_text_model_for_funding_quote"("p_user_id" "uuid", "p_workspace_id" "uuid", "p_route_code" "text", "p_credential_funding" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."resolve_openai_text_model_for_quote"("p_user_id" "uuid", "p_route_code" "text", "p_credential_funding" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare override_row tongs.ai_operation_model_override_revisions%rowtype; global_row tongs.ai_model_preference_revisions%rowtype; selected record; source text;
begin
 perform tongs._require_pricing_service_role();
 if p_credential_funding<>'forge' then raise exception 'BYO model access and support-only pricing are not verified; no Forge fallback is permitted' using errcode='P0001'; end if;
 select * into override_row from tongs.ai_operation_model_override_revisions where user_id=p_user_id and operation_code=p_route_code order by revision desc limit 1;
 if found and override_row.override_state='specific' then
   select * into selected from tongs._eligible_ai_models_for_operation(p_route_code)e where e.model_identity_id=override_row.model_identity_id;
   if not found then raise exception 'operation_model_override_unavailable: change or clear the explicit operation override' using errcode='P0001'; end if;
   source:='operation_override';
 else
   select * into global_row from tongs.ai_model_preference_revisions where user_id=p_user_id order by revision desc limit 1;
   if not found then raise exception 'global_model_preference_required: choose a preferred AI model' using errcode='P0001'; end if;
   if not exists(
     select 1 from tongs.ai_global_model_choice_revisions choice
     where choice.model_identity_id=global_row.model_identity_id
       and choice.revision=(select max(latest.revision) from tongs.ai_global_model_choice_revisions latest where latest.model_identity_id=choice.model_identity_id)
       and choice.authority_state='selectable'
   ) then raise exception 'global_model_preference_unavailable: choose an eligible operation override' using errcode='P0001'; end if;
   select * into selected from tongs._eligible_ai_models_for_operation(p_route_code)e where e.model_identity_id=global_row.model_identity_id;
   if not found then raise exception 'global_model_preference_unavailable: choose an eligible operation override' using errcode='P0001'; end if;
   source:='global_preference';
 end if;
 return jsonb_build_object(
   'catalog_revision_id',selected.catalog_revision_id,'catalog_revision',selected.catalog_revision,
   'model_catalog_entry_id',selected.model_catalog_entry_id,'customer_selection_key',selected.customer_selection_key,
   'runtime_model_id',selected.runtime_model_id,'provider_model_id',selected.provider_model_id,
   'display_name',selected.display_name,
   'tradeoff_summary',case selected.relative_cost_class when 'lower_cost' then 'Lower cost' when 'mid_range_cost' then 'Mid-range cost' else 'Higher cost' end,
   'cost_policy_revision_id',selected.cost_policy_revision_id,'preference_source',source
 );
end $$;


ALTER FUNCTION "tongs"."resolve_openai_text_model_for_quote"("p_user_id" "uuid", "p_route_code" "text", "p_credential_funding" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."resolve_openai_text_model_for_quote"("p_user_id" "uuid", "p_route_code" "text", "p_credential_funding" "text") IS 'Strict resolution: explicit operation override, otherwise global preference, otherwise stop. Ineligible explicit choices never fall through.';



CREATE OR REPLACE FUNCTION "tongs"."resolve_openai_text_paid_execution_context"("p_route_code" "text", "p_operation_id" "text", "p_reservation_id" "uuid", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_workpiece_id" "text", "p_request_fingerprint" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
 v_binding tongs.openai_text_funding_bindings%rowtype;
 v_res tongs.funding_reservations%rowtype;
 v_quote tongs.customer_spending_quotes%rowtype;
 v_qb tongs.openai_text_customer_quote_bindings%rowtype;
 v_cost tongs.openai_text_cost_policy_revisions%rowtype;
 v_rollout tongs.openai_text_rollout_revisions%rowtype;
 v_rate tongs.openai_text_provider_rate_revisions%rowtype;
 v_failure bigint;
 v_route_activated boolean;
 v_owner_canary_activated boolean;
begin
 perform tongs._require_pricing_service_role();
 select * into v_binding from tongs.openai_text_funding_bindings
  where operation_id=btrim(p_operation_id) and reservation_id=p_reservation_id and route_code=p_route_code;
 if not found then raise exception 'exact funded OpenAI text route binding required' using errcode='P0002'; end if;
 select * into v_res from tongs.funding_reservations where id=p_reservation_id;
 select * into v_quote from tongs.customer_spending_quotes where id=v_res.quote_id;
 select * into v_qb from tongs.openai_text_customer_quote_bindings where quote_id=v_quote.id;
 if not found or v_res.user_id<>p_user_id or v_quote.user_id<>p_user_id or v_qb.user_id<>p_user_id
  or v_qb.canonical_operation_id<>btrim(p_operation_id) or v_qb.route_code<>p_route_code or v_qb.workspace_id<>p_workspace_id
  or v_qb.workpiece_id<>btrim(p_workpiece_id) or v_qb.request_fingerprint<>p_request_fingerprint or v_quote.request_fingerprint<>p_request_fingerprint
  or v_qb.runtime_model<>v_binding.model or v_qb.pricing_revision_id<>v_binding.pricing_revision_id
  or v_qb.cost_policy_revision_id<>v_binding.cost_policy_revision_id
  or not exists(select 1 from tongs.customer_spending_quote_acceptances a where a.quote_id=v_quote.id and a.user_id=p_user_id)
  then raise exception 'accepted reserved OpenAI text funding context does not match request' using errcode='42501'; end if;
 if v_res.funding_environment is null
  or v_res.funding_environment not in ('test','live','owner_internal')
  then raise exception 'canonical funding reservation environment is invalid' using errcode='42501'; end if;
 select * into v_cost from tongs.openai_text_cost_policy_revisions where id=v_binding.cost_policy_revision_id;
 select * into v_rollout from tongs._current_openai_text_rollout(p_route_code);
 v_route_activated:=coalesce(v_rollout.mode='enforce' and v_rollout.cost_policy_revision_id=v_cost.id,false);
 v_owner_canary_activated:=coalesce(v_rollout.mode='halt_new' and exists(
   select 1 from tongs._owner_paid_execution_canary_for_reservation(p_reservation_id)
 ),false);
 if v_cost.id is null or not (v_route_activated or v_owner_canary_activated)
  or v_cost.lifecycle_state not in ('pilot_candidate','active') or v_cost.cost_coverage<>'complete'
  or v_res.reserved_wholesale_spend_micros<>v_cost.full_cost_ceiling_micros
  then raise exception 'OpenAI text route is not activated for the accepted complete cost revision' using errcode='42501'; end if;
 select rate.* into v_rate from tongs.openai_text_provider_rate_revisions rate
  where rate.id=nullif(v_cost.attempt_plan->0->>'rate_revision_id','')::uuid;
 if not found or v_binding.model not in (v_rate.runtime_model_alias,v_rate.provider_model_id)
  then raise exception 'pricing_not_configured: exact OpenAI model rate missing' using errcode='P0001'; end if;
 v_failure:=case when v_binding.credential_funding='forge' then v_cost.full_cost_ceiling_micros else 0 end;
 return jsonb_build_object(
  'operation_id',v_binding.operation_id,'reservation_id',v_binding.reservation_id,'quote_id',v_quote.id,'route_code',v_binding.route_code,
  'user_id',p_user_id,'workspace_id',p_workspace_id,'workpiece_id',btrim(p_workpiece_id),'request_fingerprint',p_request_fingerprint,
  'funding_source_type',v_res.funding_source_type,'funding_source_id',v_res.funding_source_id,
  'funding_environment',v_res.funding_environment,'credential_funding',v_binding.credential_funding,'model',v_binding.model,
  'maximum_input_units',v_binding.maximum_input_units,'maximum_output_units',v_binding.maximum_output_units,'maximum_attempts',v_binding.maximum_attempts,
  'maximum_failure_exposure_micros',v_failure,'direct_provider_ceiling_micros',v_cost.direct_provider_ceiling_micros,
  'supporting_cost_ceiling_micros',v_cost.supporting_cost_ceiling_micros,'full_cost_ceiling_micros',v_cost.full_cost_ceiling_micros,
  'input_micros_per_million_tokens',v_rate.input_micros_per_million_tokens,
  'cached_input_micros_per_million_tokens',v_rate.cached_input_micros_per_million_tokens,
  'output_micros_per_million_tokens',v_rate.output_micros_per_million_tokens,
  'cost_policy_revision_id',v_cost.id,'pricing_revision_id',v_quote.pricing_revision_id,
  'rollout_revision',v_rollout.revision,'reservation_state',tongs._funding_reservation_state(p_reservation_id));
end $$;


ALTER FUNCTION "tongs"."resolve_openai_text_paid_execution_context"("p_route_code" "text", "p_operation_id" "text", "p_reservation_id" "uuid", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_workpiece_id" "text", "p_request_fingerprint" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."resolve_openai_text_paid_execution_context"("p_route_code" "text", "p_operation_id" "text", "p_reservation_id" "uuid", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_workpiece_id" "text", "p_request_fingerprint" "text") IS 'Resolves exact accepted complete-cost execution authority, including the immutable reservation funding environment. General callers require route enforce; an exact active owner-only Test canary reservation may resolve while the route remains halt_new.';



CREATE OR REPLACE FUNCTION "tongs"."resolve_openai_text_recovery_context"("p_route_code" "text", "p_operation_id" "text", "p_reservation_id" "uuid", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_workpiece_id" "text", "p_request_fingerprint" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare v_binding tongs.openai_text_funding_bindings%rowtype; v_res tongs.funding_reservations%rowtype; v_quote tongs.customer_spending_quotes%rowtype;
 v_qb tongs.openai_text_customer_quote_bindings%rowtype; v_cost tongs.openai_text_cost_policy_revisions%rowtype; v_rollout tongs.openai_text_rollout_revisions%rowtype;
 v_rate tongs.openai_text_provider_rate_revisions%rowtype; v_failure bigint;
begin
 perform tongs._require_pricing_service_role();
    if not exists(select 1 from tongs.openai_text_provider_captures where reservation_id=p_reservation_id)
       and tongs._funding_reservation_state(p_reservation_id) not in ('settled','submission_unknown','attempt_started') then
      raise exception 'recovery evidence required; provider execution forbidden' using errcode='42501'; end if;
 select * into v_binding from tongs.openai_text_funding_bindings where operation_id=btrim(p_operation_id) and reservation_id=p_reservation_id and route_code=p_route_code;
 if not found then raise exception 'exact funded OpenAI text route binding required' using errcode='P0002'; end if;
 select * into v_res from tongs.funding_reservations where id=p_reservation_id;
 select * into v_quote from tongs.customer_spending_quotes where id=v_res.quote_id;
 select * into v_qb from tongs.openai_text_customer_quote_bindings where quote_id=v_quote.id;
 if not found or v_res.user_id<>p_user_id or v_quote.user_id<>p_user_id or v_qb.user_id<>p_user_id
  or v_qb.canonical_operation_id<>btrim(p_operation_id) or v_qb.route_code<>p_route_code or v_qb.workspace_id<>p_workspace_id
  or v_qb.workpiece_id<>btrim(p_workpiece_id) or v_qb.request_fingerprint<>p_request_fingerprint or v_quote.request_fingerprint<>p_request_fingerprint
  or v_qb.runtime_model<>v_binding.model or v_qb.pricing_revision_id<>v_binding.pricing_revision_id
  or not exists(select 1 from tongs.customer_spending_quote_acceptances a where a.quote_id=v_quote.id and a.user_id=p_user_id)
  then raise exception 'accepted reserved OpenAI text funding context does not match request' using errcode='42501'; end if;
 select * into v_cost from tongs.openai_text_cost_policy_revisions where id=v_binding.cost_policy_revision_id;
 select * into v_rollout from tongs._current_openai_text_rollout(p_route_code);
 if v_cost.id is null 
  or v_cost.cost_coverage<>'complete' or v_res.reserved_wholesale_spend_micros<>v_cost.full_cost_ceiling_micros then raise exception 'OpenAI text route is not activated for the accepted complete cost revision' using errcode='42501'; end if;
 select rate.* into v_rate from tongs.openai_text_provider_rate_revisions rate where rate.id=nullif(v_cost.attempt_plan->0->>'rate_revision_id','')::uuid;
 if not found or v_binding.model not in (v_rate.runtime_model_alias,v_rate.provider_model_id) then raise exception 'pricing_not_configured: exact OpenAI model rate missing' using errcode='P0001'; end if;
  v_failure := CASE when v_binding.credential_funding='forge' then v_cost.full_cost_ceiling_micros else 0 end;
 return jsonb_build_object('operation_id',v_binding.operation_id,'reservation_id',v_binding.reservation_id,'quote_id',v_quote.id,'route_code',v_binding.route_code,
  'user_id',p_user_id,'workspace_id',p_workspace_id,'workpiece_id',btrim(p_workpiece_id),'request_fingerprint',p_request_fingerprint,
  'funding_source_type',v_res.funding_source_type,'funding_source_id',v_res.funding_source_id,'credential_funding',v_binding.credential_funding,'model',v_binding.model,
  'maximum_input_units',v_binding.maximum_input_units,'maximum_output_units',v_binding.maximum_output_units,'maximum_attempts',v_binding.maximum_attempts,
  'maximum_failure_exposure_micros',v_failure,'direct_provider_ceiling_micros',v_cost.direct_provider_ceiling_micros,'supporting_cost_ceiling_micros',v_cost.supporting_cost_ceiling_micros,
  'full_cost_ceiling_micros',v_cost.full_cost_ceiling_micros,'input_micros_per_million_tokens',v_rate.input_micros_per_million_tokens,
  'cached_input_micros_per_million_tokens',v_rate.cached_input_micros_per_million_tokens,'output_micros_per_million_tokens',v_rate.output_micros_per_million_tokens,'audio_input_micros_per_million_tokens',coalesce(v_rate.audio_input_micros_per_million_tokens,v_rate.input_micros_per_million_tokens),'text_input_micros_per_million_tokens',coalesce(v_rate.text_input_micros_per_million_tokens,v_rate.input_micros_per_million_tokens),
  'cost_policy_revision_id',v_cost.id,'pricing_revision_id',v_quote.pricing_revision_id,'rollout_revision',v_rollout.revision,'reservation_state',tongs._funding_reservation_state(p_reservation_id));
end $$;


