CREATE OR REPLACE FUNCTION "tongs"."resolve_openai_transcription_model_for_quote"("p_user_id" "uuid", "p_route_code" "text", "p_credential_funding" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare r tongs.openai_text_rollout_revisions%rowtype; c tongs.openai_text_cost_policy_revisions%rowtype; rate tongs.openai_text_provider_rate_revisions%rowtype;
begin
 perform tongs._require_pricing_service_role();
 select * into r from tongs._current_openai_text_rollout(p_route_code);
 if not found or r.mode<>'enforce' or r.cost_policy_revision_id is null then raise exception 'OpenAI transcription is not active' using errcode='42501'; end if;
 select * into c from tongs.openai_text_cost_policy_revisions where id=r.cost_policy_revision_id;
 select * into rate from tongs.openai_text_provider_rate_revisions where id=nullif(c.attempt_plan->0->>'rate_revision_id','')::uuid;
 if c.cost_coverage<>'complete' or c.lifecycle_state not in ('pilot_candidate','active') or rate.id is null or rate.billing_basis<>'audio_and_text_tokens' then
  raise exception 'pricing_not_configured: complete transcription rate and supporting costs required' using errcode='P0001';
 end if;
 return jsonb_build_object('catalog_revision_id',rate.id,'catalog_revision',rate.revision,'model_catalog_entry_id',rate.id,
  'runtime_model_id',rate.runtime_model_alias,'provider_model_id',rate.provider_model_id,
  'display_name',rate.provider_model_id,'tradeoff_summary','Bounded OpenAI audio transcription; no search, enrichment, generation, or paid transcode is included.');
end $$;


ALTER FUNCTION "tongs"."resolve_openai_transcription_model_for_quote"("p_user_id" "uuid", "p_route_code" "text", "p_credential_funding" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."resolve_org_user_by_email"("p_org_id" "uuid", "p_email" "text") RETURNS TABLE("user_id" "uuid", "email" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare
  v_email text;
begin
  if p_org_id is null then
    raise exception 'org_id is required'
      using errcode = '22023';
  end if;

  v_email := lower(trim(coalesce(p_email, '')));
  if v_email = '' then
    raise exception 'email is required'
      using errcode = '22023';
  end if;

  perform tongs.assert_org_role(p_org_id, 'admin');

  return query
  select
    u.id,
    lower(u.email)
  from auth.users u
  where lower(u.email) = v_email
  limit 1;
end;
$$;


ALTER FUNCTION "tongs"."resolve_org_user_by_email"("p_org_id" "uuid", "p_email" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."resolve_owner_hearth_model_for_operation"("p_owner_user_id" "uuid", "p_workspace_id" "uuid", "p_requested_provider_model_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare authz tongs.owner_hearth_authorizations%rowtype; ev tongs.owner_hearth_authorization_events%rowtype; term tongs.owner_hearth_model_terms%rowtype;
  pref tongs.openai_text_user_model_preference_revisions%rowtype;
begin
 perform tongs._require_pricing_service_role();
 select a.* into authz from tongs.owner_hearth_authorizations a
 join lateral(select * from tongs.owner_hearth_authorization_events e where e.authorization_id=a.id order by sequence desc limit 1) latest on true
 where a.owner_user_id=p_owner_user_id and a.workspace_id=p_workspace_id and latest.state in ('active','dormant')
   and (latest.expires_at is null or latest.expires_at>now())
 order by (a.authorization_kind='creator_session') desc,a.created_at desc limit 1;
 if not found then raise exception 'owner Hearth authorization is not active' using errcode='42501'; end if;
 select * into ev from tongs.owner_hearth_authorization_events where authorization_id=authz.id order by sequence desc limit 1;
 select * into pref from tongs.openai_text_user_model_preference_revisions where user_id=p_owner_user_id order by revision desc limit 1;
 select t.* into term from tongs.owner_hearth_model_terms t where t.authorization_id=authz.id
   and (case when nullif(btrim(coalesce(p_requested_provider_model_id,'')),'') is not null then t.provider_model_id=btrim(p_requested_provider_model_id)
      when coalesce(pref.preference_kind,'best_available')='specific' then t.provider_model_id=pref.provider_model_id else true end)
 order by t.ordinal limit 1;
 if not found then raise exception 'requested owner Hearth model is not eligible' using errcode='P0001'; end if;
 return jsonb_build_object('authorization_id',authz.id,'authorization_kind',authz.authorization_kind,'authorization_state',ev.state,
  'provider_model_id',term.provider_model_id,'runtime_model_id',term.provider_model_id,'display_name',term.display_name,
  'cost_policy_revision_id',term.cost_policy_revision_id,'pricing_revision_id',term.pricing_revision_id,
  'maximum_exposure_micros',term.maximum_exposure_micros);
end $$;


ALTER FUNCTION "tongs"."resolve_owner_hearth_model_for_operation"("p_owner_user_id" "uuid", "p_workspace_id" "uuid", "p_requested_provider_model_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."resolve_owner_hearth_paid_execution_context"("p_operation_id" "text", "p_reservation_id" "uuid", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_workpiece_id" "text", "p_request_fingerprint" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare op tongs.owner_hearth_operation_authorizations%rowtype; authz tongs.owner_hearth_authorizations%rowtype; latest tongs.owner_hearth_authorization_events%rowtype;
 res tongs.funding_reservations%rowtype; cost tongs.openai_text_cost_policy_revisions%rowtype; rate tongs.openai_text_provider_rate_revisions%rowtype;
 reservation_state text; recovery_expiry timestamptz;
begin
 perform tongs._require_pricing_service_role();
 select * into op from tongs.owner_hearth_operation_authorizations where operation_id=btrim(p_operation_id) and reservation_id=p_reservation_id;
 select * into authz from tongs.owner_hearth_authorizations where id=op.authorization_id;
 select * into latest from tongs.owner_hearth_authorization_events where authorization_id=authz.id order by sequence desc limit 1;
 select * into res from tongs.funding_reservations where id=p_reservation_id;
 reservation_state:=tongs._funding_reservation_state(p_reservation_id);
 if op.id is null or authz.id is null or res.id is null or op.owner_user_id<>p_user_id or op.workspace_id<>p_workspace_id
   or op.workpiece_id<>btrim(p_workpiece_id) or op.request_fingerprint<>p_request_fingerprint or res.funding_source_id<>authz.budget_id
   or not exists(select 1 from tongs.customer_spending_quote_acceptances where quote_id=op.quote_id and user_id=p_user_id)
   then raise exception 'exact owner Hearth funding context required' using errcode='42501'; end if;
 if latest.state not in ('active','closed') or (latest.state='active' and latest.expires_at<=now()) then
  raise exception 'owner Hearth authorization halted' using errcode='42501'; end if;
 select expires_at into recovery_expiry from tongs.owner_hearth_operation_recovery_authorizations
 where operation_authorization_id=op.id order by created_at desc limit 1;
 if reservation_state not in ('settled','released') and op.expires_at<=now()
    and coalesce(recovery_expiry,'-infinity'::timestamptz)<=now() then
  raise exception 'owner Hearth accepted quote expired' using errcode='42501'; end if;
 select * into cost from tongs.openai_text_cost_policy_revisions where id=op.cost_policy_revision_id;
 select r.* into rate from tongs.openai_text_provider_rate_revisions r where r.id=nullif(cost.attempt_plan->0->>'rate_revision_id','')::uuid;
 if cost.id is null or rate.id is null or rate.provider_model_id<>op.provider_model_id or res.reserved_wholesale_spend_micros<>cost.full_cost_ceiling_micros then
  raise exception 'exact owner Hearth model cost revision required' using errcode='P0001'; end if;
 return jsonb_build_object('operation_id',op.operation_id,'reservation_id',op.reservation_id,'quote_id',op.quote_id,'route_code','hearth.chat_completion',
  'user_id',op.owner_user_id,'workspace_id',op.workspace_id,'workpiece_id',op.workpiece_id,'request_fingerprint',op.request_fingerprint,
  'funding_source_type','owner_budget','funding_source_id',authz.budget_id,'credential_funding','forge','model',op.provider_model_id,
  'maximum_input_units',cost.maximum_input_units,'maximum_output_units',cost.maximum_output_units,'maximum_attempts',1,
  'maximum_failure_exposure_micros',cost.full_cost_ceiling_micros+3,'direct_provider_ceiling_micros',cost.direct_provider_ceiling_micros,
  'supporting_cost_ceiling_micros',cost.supporting_cost_ceiling_micros,'full_cost_ceiling_micros',cost.full_cost_ceiling_micros,
  'input_micros_per_million_tokens',rate.input_micros_per_million_tokens,'cached_input_micros_per_million_tokens',rate.cached_input_micros_per_million_tokens,
  'output_micros_per_million_tokens',rate.output_micros_per_million_tokens,'cost_policy_revision_id',cost.id,'pricing_revision_id',op.pricing_revision_id,
  'owner_hearth_authorization_id',authz.id,'reservation_state',reservation_state,
  'recovery_authorized',recovery_expiry>now(),'effective_expires_at',greatest(op.expires_at,recovery_expiry));
end $$;


ALTER FUNCTION "tongs"."resolve_owner_hearth_paid_execution_context"("p_operation_id" "text", "p_reservation_id" "uuid", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_workpiece_id" "text", "p_request_fingerprint" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."resolve_owner_hearth_research_paid_execution_context"("p_operation_id" "text", "p_reservation_id" "uuid", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_workpiece_id" "text", "p_request_fingerprint" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare o tongs.owner_hearth_research_operations%rowtype; t tongs.owner_hearth_research_model_terms%rowtype;
begin
 perform tongs._require_pricing_service_role(); select * into o from tongs.owner_hearth_research_operations where operation_id=btrim(p_operation_id) and reservation_id=p_reservation_id;
 select * into t from tongs.owner_hearth_research_model_terms where authorization_id=o.authorization_id and provider_model_id=o.provider_model_id;
 if o.id is null or o.owner_user_id<>p_user_id or o.workspace_id<>p_workspace_id or o.workpiece_id::text<>btrim(p_workpiece_id) or o.request_fingerprint<>p_request_fingerprint
  then raise exception 'exact owner research context required' using errcode='42501'; end if;
 return jsonb_build_object('operation_id',o.operation_id,'reservation_id',o.reservation_id,'quote_id',o.quote_id,'route_code','hearth.research_synthesis',
  'user_id',o.owner_user_id,'workspace_id',o.workspace_id,'workpiece_id',o.workpiece_id,'request_fingerprint',o.request_fingerprint,
  'funding_source_type','owner_budget','credential_funding','forge','model',o.provider_model_id,'maximum_input_units',o.maximum_input_tokens,'maximum_output_units',o.maximum_output_tokens,
  'maximum_attempts',1,'maximum_failure_exposure_micros',o.full_cost_ceiling_micros+3,'direct_provider_ceiling_micros',o.direct_provider_ceiling_micros,
  'supporting_cost_ceiling_micros',1456,'full_cost_ceiling_micros',o.full_cost_ceiling_micros,'input_micros_per_million_tokens',t.input_micros_per_million_tokens,
  'cached_input_micros_per_million_tokens',t.input_micros_per_million_tokens,'output_micros_per_million_tokens',t.output_micros_per_million_tokens,
  'cost_policy_revision_id',o.cost_policy_revision_id,'pricing_revision_id',o.pricing_revision_id,'reservation_state',tongs._funding_reservation_state(o.reservation_id));
end $$;


