CREATE OR REPLACE FUNCTION "tongs"."resolve_transition_owner_authority"("p_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_canonical tongs.account_authority_classifications%rowtype;
  v_legacy tongs.owner_testing_principals%rowtype;
  v_canonical_owner boolean := false;
  v_legacy_enabled boolean := false;
  v_state text;
begin
  if coalesce(auth.role(), '') <> 'service_role'
     and coalesce(current_setting('request.jwt.claim.role', true), '') <> 'service_role' then
    raise exception 'service role required' using errcode = '42501';
  end if;
  if p_user_id is null then
    raise exception 'account user id required' using errcode = '22023';
  end if;

  select * into v_canonical
  from tongs.account_authority_classifications
  where user_id = p_user_id;
  v_canonical_owner := found and v_canonical.account_class = 'owner';

  select * into v_legacy
  from tongs.owner_testing_principals
  where user_id = p_user_id;
  v_legacy_enabled := found and v_legacy.status = 'enabled';

  v_state := case
    when v_canonical_owner and v_legacy_enabled then 'eligible'
    when v_canonical_owner <> v_legacy_enabled then 'authority_mismatch'
    else 'not_owner'
  end;

  return jsonb_build_object(
    'user_id', p_user_id,
    'canonical_user_id', v_canonical.user_id,
    'account_class', coalesce(v_canonical.account_class, 'customer'),
    'account_authority_revision', v_canonical.revision,
    'account_authority_explicit', v_canonical.user_id is not null,
    'legacy_user_id', v_legacy.user_id,
    'legacy_principal_status', v_legacy.status,
    'legacy_principal_revision', v_legacy.revision,
    'same_user', (v_canonical.user_id is null or v_canonical.user_id = p_user_id)
      and (v_legacy.user_id is null or v_legacy.user_id = p_user_id),
    'consistent', v_canonical_owner = v_legacy_enabled,
    'eligible', v_canonical_owner and v_legacy_enabled,
    'state', v_state,
    'authority_mode', 'canonical_legacy_dual_read'
  );
end
$$;


ALTER FUNCTION "tongs"."resolve_transition_owner_authority"("p_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."resolve_transition_owner_authority"("p_user_id" "uuid") IS 'Service-only dual-read transition resolver. Raw authority evidence is never browser-readable.';



CREATE OR REPLACE FUNCTION "tongs"."resolve_visual_source_attribution"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_artifact_family" "text", "p_opportunity_id" "uuid", "p_expected_attribution_revision" bigint, "p_expected_opportunity_revision_id" "uuid", "p_expected_opportunity_revision" bigint, "p_source_revision_id" "uuid", "p_workpiece_source_link_revision_id" "uuid", "p_operation_id" "text", "p_operation_fingerprint" "text", "p_actor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
#variable_conflict use_column
declare current_attribution tongs.visual_source_attribution_revisions%rowtype;family_result jsonb;family_plan jsonb;family_opportunity jsonb;source_set_result jsonb;source_set_revision bigint:=0;members jsonb:='[]'::jsonb;attribution_result jsonb;child_plan_revision_id uuid;child_plan_revision bigint;
begin
 if not tongs.has_workspace_role(p_workspace_id,'editor')or auth.uid()is distinct from p_actor_id then raise exception 'workspace editor authority required' using errcode='42501';end if;
 if p_artifact_family not in('reference_clip','reference_visual')then return jsonb_build_object('disposition','unsupported_family');end if;
 if (p_source_revision_id is null)<>(p_workpiece_source_link_revision_id is null)then return jsonb_build_object('disposition','source_and_link_must_match');end if;
 perform pg_advisory_xact_lock(hashtextextended(p_operation_id,0));
 select * into current_attribution from tongs.visual_source_attribution_revisions where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and artifact_family=p_artifact_family and opportunity_id=p_opportunity_id order by revision desc limit 1 for update;
 if not found then return jsonb_build_object('disposition','attribution_required');end if;
 if current_attribution.revision<>p_expected_attribution_revision then return jsonb_build_object('disposition','attribution_revision_conflict','current_revision',current_attribution.revision);end if;
 if p_artifact_family='reference_clip'then
  family_result:=tongs.reassign_reference_clip_source(p_workspace_id,p_workpiece_id,p_opportunity_id,p_expected_opportunity_revision_id,p_expected_opportunity_revision,p_source_revision_id,p_workpiece_source_link_revision_id,p_operation_id||':family',p_operation_fingerprint,p_actor_id);
 else
  family_result:=tongs.reassign_reference_visual_source(p_workspace_id,p_workpiece_id,p_opportunity_id,p_expected_opportunity_revision_id,p_expected_opportunity_revision,p_source_revision_id,p_workpiece_source_link_revision_id,p_operation_id||':family',p_operation_fingerprint,p_actor_id);
 end if;
 if coalesce(family_result->>'disposition','')<>'committed'then return jsonb_build_object('disposition','family_authority_conflict','family_receipt',family_result);end if;
 family_plan:=family_result->'plan_revision';family_opportunity:=family_result->'opportunity_revision';
 begin child_plan_revision_id:=(family_plan->>'id')::uuid;child_plan_revision:=(family_plan->>'revision')::bigint;exception when others then return jsonb_build_object('disposition','family_receipt_invalid');end;
 if p_artifact_family='reference_visual'then
  select coalesce(max(revision),0)into source_set_revision from tongs.reference_visual_source_set_revisions where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and opportunity_id=p_opportunity_id and plan_revision_id=child_plan_revision_id;
  members:=case when p_source_revision_id is null then'[]'::jsonb else jsonb_build_array(jsonb_build_object('source_revision_id',p_source_revision_id,'workpiece_source_link_revision_id',p_workpiece_source_link_revision_id))end;
  source_set_result:=tongs.commit_reference_visual_source_set(p_workspace_id,p_workpiece_id,p_opportunity_id,members,child_plan_revision_id,child_plan_revision,source_set_revision,p_operation_id||':source-set',p_operation_fingerprint,p_actor_id);
  if coalesce(source_set_result->>'disposition','')<>'committed'then return jsonb_build_object('disposition','family_source_set_conflict','family_receipt',family_result,'source_set_receipt',source_set_result);end if;
 end if;
 members:=case when p_source_revision_id is null then'[]'::jsonb else jsonb_build_array(jsonb_build_object('role','direct_basis','source_revision_id',p_source_revision_id,'workpiece_source_link_revision_id',p_workpiece_source_link_revision_id))end;
 attribution_result:=tongs.commit_visual_source_attribution(p_workspace_id,p_workpiece_id,p_artifact_family,p_opportunity_id,current_attribution.script_approval_id,current_attribution.unified_plan_operation_id,child_plan_revision_id,case when p_source_revision_id is null then'none_known'else'creator_selected'end,case when p_source_revision_id is null then'none'else'direct'end,current_attribution.rationale,current_attribution.model_evidence_json,members,current_attribution.revision,p_operation_id||':attribution',p_operation_fingerprint,p_actor_id);
 if coalesce(attribution_result->>'disposition','')<>'committed'then raise exception 'visual attribution and family authority diverged' using errcode='P0001',detail=attribution_result::text;end if;
 return jsonb_build_object('disposition','committed','family_receipt',family_result,'source_set_receipt',source_set_result,'attribution_receipt',attribution_result,'opportunity_revision',family_opportunity);
end$$;


ALTER FUNCTION "tongs"."resolve_visual_source_attribution"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_artifact_family" "text", "p_opportunity_id" "uuid", "p_expected_attribution_revision" bigint, "p_expected_opportunity_revision_id" "uuid", "p_expected_opportunity_revision" bigint, "p_source_revision_id" "uuid", "p_workpiece_source_link_revision_id" "uuid", "p_operation_id" "text", "p_operation_fingerprint" "text", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."resolve_workpiece_brand_default"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_operation_id" "text", "p_operation_fingerprint" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare v_user uuid:=auth.uid();v_op tongs.workpiece_brand_binding_operations%rowtype;v_current tongs.workpiece_brand_bindings%rowtype;v_default uuid;v_revision tongs.brand_profile_revisions%rowtype;v_id uuid;v_result jsonb;v_assets uuid[];
begin if v_user is null then raise exception 'Not authenticated' using errcode='42501';end if;perform tongs.assert_workspace_role(p_workspace_id,'editor');if not exists(select 1 from tongs.episodes where id=p_workpiece_id and workspace_id=p_workspace_id)then raise exception 'workpiece does not belong to workspace' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_workspace_id::text||':'||p_workpiece_id::text||':brand',0));
 select * into v_op from tongs.workpiece_brand_binding_operations where workspace_id=p_workspace_id and operation_id=p_operation_id;if found then if v_op.operation_fingerprint<>p_operation_fingerprint then raise exception 'Operation identity was reused with a different payload.' using errcode='22023';end if;return v_op.result_json;end if;
 select * into v_current from tongs.workpiece_brand_bindings where workpiece_id=p_workpiece_id order by revision desc limit 1;
 if found then v_result:=jsonb_build_object('disposition','existing_binding','binding',tongs.brand_binding_json(v_current.id));insert into tongs.workpiece_brand_binding_operations(workspace_id,workpiece_id,operation_id,operation_fingerprint,intent,disposition,binding_id,result_json,created_by)values(p_workspace_id,p_workpiece_id,p_operation_id,p_operation_fingerprint,'resolve_default','existing_binding',v_current.id,v_result,v_user);return v_result;end if;
 select profile_id into v_default from tongs.workspace_default_brand_profiles where workspace_id=p_workspace_id;if v_default is not null then select * into v_revision from tongs.brand_profile_revisions r where r.profile_id=v_default and tongs.brand_revision_is_bindable(p_workspace_id,v_default,r.id) order by revision desc limit 1;end if;
 v_id:=gen_random_uuid();if v_revision.id is null then insert into tongs.workpiece_brand_bindings(id,workspace_id,workpiece_id,revision,state,mutation_reason,operation_id,operation_fingerprint,created_by)values(v_id,p_workspace_id,p_workpiece_id,1,'disabled','resolve_default',p_operation_id,p_operation_fingerprint,v_user);
 else select coalesce(array_agg(value::uuid),'{}')into v_assets from jsonb_each_text(coalesce(v_revision.rules_json->'asset_revision_ids','{}'::jsonb));insert into tongs.workpiece_brand_bindings(id,workspace_id,workpiece_id,revision,state,profile_id,profile_revision_id,profile_revision,profile_content_hash,asset_revision_ids,mutation_reason,operation_id,operation_fingerprint,created_by)values(v_id,p_workspace_id,p_workpiece_id,1,'profile',v_default,v_revision.id,v_revision.revision,v_revision.content_hash,v_assets,'resolve_default',p_operation_id,p_operation_fingerprint,v_user);end if;
 v_result:=jsonb_build_object('disposition','created_binding','binding',tongs.brand_binding_json(v_id));insert into tongs.workpiece_brand_binding_operations(workspace_id,workpiece_id,operation_id,operation_fingerprint,intent,disposition,binding_id,result_json,created_by)values(p_workspace_id,p_workpiece_id,p_operation_id,p_operation_fingerprint,'resolve_default','created_binding',v_id,v_result,v_user);return v_result;end $$;


ALTER FUNCTION "tongs"."resolve_workpiece_brand_default"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_operation_id" "text", "p_operation_fingerprint" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."retain_reference_visual_source_set_on_membership"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare prior tongs.reference_visual_source_set_revisions%rowtype;created tongs.reference_visual_source_set_revisions%rowtype;member tongs.reference_visual_source_set_members%rowtype;fp text;actor uuid;
begin
 if exists(select 1 from tongs.reference_visual_source_set_revisions where plan_revision_id=new.plan_revision_id and opportunity_id=new.opportunity_id)then return new;end if;
 select s.* into prior from tongs.reference_visual_source_set_revisions s where s.workspace_id=new.workspace_id and s.workpiece_id=new.workpiece_id and s.opportunity_id=new.opportunity_id and s.opportunity_revision_id=new.opportunity_revision_id order by s.created_at desc,s.revision desc limit 1;
 if not found then return new;end if;select created_by into actor from tongs.reference_visual_plan_revisions where id=new.plan_revision_id;fp:=encode(extensions.digest(convert_to(jsonb_build_object('retained_source_set',prior.id,'plan',new.plan_revision_id)::text,'UTF8'),'sha256'),'hex');
 insert into tongs.reference_visual_source_set_revisions(workspace_id,workpiece_id,opportunity_id,plan_revision_id,plan_revision,opportunity_revision_id,opportunity_revision,revision,operation_id,operation_fingerprint,created_by)
 values(new.workspace_id,new.workpiece_id,new.opportunity_id,new.plan_revision_id,new.plan_revision,new.opportunity_revision_id,new.opportunity_revision,1,'forge:reference-visual:source-set:retain:'||new.plan_revision_id||':'||new.opportunity_id,fp,actor)returning * into created;
 for member in select * from tongs.reference_visual_source_set_members where source_set_revision_id=prior.id order by ordinal loop insert into tongs.reference_visual_source_set_members(source_set_revision_id,workspace_id,workpiece_id,opportunity_id,plan_revision_id,source_set_revision,ordinal,source_revision_id,source_revision,workpiece_source_link_revision_id,workpiece_source_link_revision)values(created.id,new.workspace_id,new.workpiece_id,new.opportunity_id,new.plan_revision_id,1,member.ordinal,member.source_revision_id,member.source_revision,member.workpiece_source_link_revision_id,member.workpiece_source_link_revision);end loop;
 return new;
end$$;


ALTER FUNCTION "tongs"."retain_reference_visual_source_set_on_membership"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."retain_unified_reference_clip_selections"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_provider_plan_revision_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare result jsonb;final_plan uuid;op tongs.unified_visual_plan_operations%rowtype;target tongs.reference_clip_plan_membership%rowtype;source_set tongs.reference_clip_selection_set_revisions%rowtype;new_set tongs.reference_clip_selection_set_revisions%rowtype;sm tongs.reference_clip_selection_set_members%rowtype;previous_selection tongs.reference_clip_selections%rowtype;first_member tongs.reference_clip_selection_set_members%rowtype;candidate tongs.reference_clip_candidate_revisions%rowtype;fp text;
begin

 select * into op
 from tongs.unified_visual_plan_operations
 where operation_id=p_operation_id
 for update;
 if not found or op.operation_fingerprint<>p_operation_fingerprint then
  return jsonb_build_object('disposition','operation_identity_conflict');
 end if;
 if op.owner_cost_attempt_id is not null then
  perform tongs._assert_owner_unified_visual_plan_persistence_authority(
   op.owner_cost_attempt_id,op.operation_id,op.operation_fingerprint,
   op.workspace_id,op.workpiece_id,op.created_by);
 elsif coalesce(auth.role(),'')='service_role' then
  raise exception 'owner-bound Unified Visual Plan operation required for service continuation'
   using errcode='42501';
 elsif not tongs.has_workspace_role(op.workspace_id,'editor') then
  raise exception 'workspace editor authority required' using errcode='42501';
 end if;
 -- The legacy merger discovers retained opportunities through the deprecated singular log.
 -- Seed one non-authoritative marker per nonempty active set; collection membership remains exclusively authoritative below.
 for source_set in
  select latest.* from(
   select distinct on(x.opportunity_id)x.* from tongs.reference_clip_selection_set_revisions x
   where x.workspace_id=op.workspace_id and x.workpiece_id=op.workpiece_id and x.plan_revision_id<>p_provider_plan_revision_id
   order by x.opportunity_id,x.created_at desc,x.revision desc
  )latest where exists(select 1 from tongs.reference_clip_selection_set_members present where present.selection_set_revision_id=latest.id)
 loop
  if exists(select 1 from tongs.reference_clip_selections s where s.operation_id=p_operation_id||':retain:set-marker:'||source_set.opportunity_id)then continue;end if;
  select * into first_member from tongs.reference_clip_selection_set_members where selection_set_revision_id=source_set.id order by ordinal limit 1;
  select * into candidate from tongs.reference_clip_candidate_revisions where id=first_member.candidate_revision_id;
  select * into previous_selection from tongs.reference_clip_selections where workspace_id=op.workspace_id and workpiece_id=op.workpiece_id order by revision desc limit 1;
  fp:=encode(extensions.digest(convert_to(jsonb_build_object('retention_set_marker',source_set.id,'candidate',candidate.id)::text,'UTF8'),'sha256'),'hex');
  insert into tongs.reference_clip_selections(workspace_id,workpiece_id,revision,previous_selection_id,previous_revision,plan_revision_id,plan_revision,opportunity_id,opportunity_revision_id,opportunity_revision,candidate_revision_id,candidate_revision,operation_id,operation_fingerprint,created_by)
  values(op.workspace_id,op.workpiece_id,coalesce(previous_selection.revision,0)+1,previous_selection.id,previous_selection.revision,source_set.plan_revision_id,source_set.plan_revision,source_set.opportunity_id,source_set.opportunity_revision_id,source_set.opportunity_revision,candidate.id,candidate.revision,p_operation_id||':retain:set-marker:'||source_set.opportunity_id,fp,op.created_by);
 end loop;
 result:=tongs.retain_unified_reference_clip_selections_singular_legacy(p_operation_id,p_operation_fingerprint,p_provider_plan_revision_id);
 if result->>'disposition' not in('retained','replay')then return result;end if;final_plan:=(result->>'revision_id')::uuid;
 for target in select m.* from tongs.reference_clip_plan_membership m where m.plan_revision_id=final_plan loop
  if exists(select 1 from tongs.reference_clip_selection_set_revisions where plan_revision_id=final_plan and opportunity_id=target.opportunity_id)then continue;end if;
  select x.* into source_set from tongs.reference_clip_selection_set_revisions x where x.workspace_id=op.workspace_id and x.workpiece_id=op.workpiece_id and x.opportunity_id=target.opportunity_id and x.plan_revision_id<>final_plan order by x.created_at desc,x.revision desc limit 1;
  if not found then continue;end if;
  fp:=encode(extensions.digest(convert_to(jsonb_build_object('parent',p_operation_id,'source_selection_set',source_set.id,'plan',final_plan)::text,'UTF8'),'sha256'),'hex');
  insert into tongs.reference_clip_selection_set_revisions(workspace_id,workpiece_id,opportunity_id,plan_revision_id,plan_revision,opportunity_revision_id,opportunity_revision,revision,canonical_revision,operation_id,operation_fingerprint,created_by)
  values(op.workspace_id,op.workpiece_id,target.opportunity_id,final_plan,target.plan_revision,target.opportunity_revision_id,target.opportunity_revision,1,(select current_selection_revision from tongs.reference_clip_plan_sequences where workspace_id=op.workspace_id and workpiece_id=op.workpiece_id),p_operation_id||':retain:reference-set:'||target.opportunity_id,fp,op.created_by)returning * into new_set;
  for sm in select * from tongs.reference_clip_selection_set_members where selection_set_revision_id=source_set.id order by ordinal loop
   insert into tongs.reference_clip_selection_set_members(selection_set_revision_id,workspace_id,workpiece_id,opportunity_id,plan_revision_id,selection_set_revision,candidate_revision_id,candidate_revision,ordinal)values(new_set.id,op.workspace_id,op.workpiece_id,target.opportunity_id,final_plan,1,sm.candidate_revision_id,sm.candidate_revision,sm.ordinal);
  end loop;
 end loop;
 return result;
end$$;


ALTER FUNCTION "tongs"."retain_unified_reference_clip_selections"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_provider_plan_revision_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."retain_unified_reference_clip_selections_singular_legacy"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_provider_plan_revision_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare
  op tongs.unified_visual_plan_operations%rowtype;
  approval tongs.script_approval_revisions%rowtype;
  seq tongs.reference_clip_plan_sequences%rowtype;
  provider_plan tongs.reference_clip_plan_revisions%rowtype;
  successor tongs.reference_clip_plan_revisions%rowtype;
  member tongs.reference_clip_plan_membership%rowtype;
  selected tongs.reference_clip_selections%rowtype;
  previous_selection tongs.reference_clip_selections%rowtype;
  retained jsonb := '[]'::jsonb;
  provider_members jsonb := '[]'::jsonb;
  retained_count integer := 0;
  next_ordinal integer := 1;
  content_hash text;
  immutable_hash text;
  selection_fingerprint text;
  evidence jsonb;
begin
  select * into op
  from tongs.unified_visual_plan_operations
  where operation_id = p_operation_id
  for update;

  if not found or op.operation_fingerprint <> p_operation_fingerprint then
    return jsonb_build_object('disposition', 'operation_identity_conflict');
  end if;
  
if op.owner_cost_attempt_id is not null then
    perform tongs._assert_owner_unified_visual_plan_persistence_authority(
      op.owner_cost_attempt_id,
      op.operation_id,
      op.operation_fingerprint,
      op.workspace_id,
      op.workpiece_id,
      op.created_by
    );
  elsif coalesce(auth.role(), '') = 'service_role' then
    raise exception 'owner-bound Unified Visual Plan operation required for service continuation'
      using errcode = '42501';
  elsif not tongs.has_workspace_role(op.workspace_id, 'editor') then
    raise exception 'workspace editor authority required' using errcode = '42501';
  end if;

  if op.child_membership_evidence_json ? 'reference_clip' then
    if op.child_membership_evidence_json->'reference_clip'->>'provider_plan_revision_id' <> p_provider_plan_revision_id::text then
      return jsonb_build_object('disposition', 'retention_identity_conflict');
    end if;
    return jsonb_build_object(
      'disposition', 'replay',
      'revision_id', op.child_membership_evidence_json->'reference_clip'->>'final_plan_revision_id',
      'retained_count', jsonb_array_length(coalesce(op.child_membership_evidence_json->'reference_clip'->'creator_retained', '[]'::jsonb)),
      'membership_evidence', op.child_membership_evidence_json
    );
  end if;

  select * into seq
  from tongs.reference_clip_plan_sequences
  where workspace_id = op.workspace_id and workpiece_id = op.workpiece_id
  for update;
  if seq.current_plan_revision_id is distinct from p_provider_plan_revision_id then
    return jsonb_build_object('disposition', 'provider_child_not_current');
  end if;

  select * into provider_plan from tongs.reference_clip_plan_revisions where id = p_provider_plan_revision_id;
  select * into approval from tongs.script_approval_revisions where id = op.script_approval_id;

  select coalesce(jsonb_agg(jsonb_build_object(
      'ordinal', m.ordinal,
      'opportunity_id', m.opportunity_id,
      'opportunity_revision_id', m.opportunity_revision_id
    ) order by m.ordinal, m.opportunity_id), '[]'::jsonb)
  into provider_members
  from tongs.reference_clip_plan_membership m
  where m.plan_revision_id = provider_plan.id;

  select coalesce(jsonb_agg(jsonb_build_object(
      'opportunity_id', x.opportunity_id,
      'selection_id', x.id,
      'candidate_revision_id', x.candidate_revision_id
    ) order by x.opportunity_id), '[]'::jsonb), count(*)
  into retained, retained_count
  from (
    select distinct on (s.opportunity_id) s.*
    from tongs.reference_clip_selections s
    join tongs.reference_clip_opportunity_revisions o on o.id = s.opportunity_revision_id
    where s.workspace_id = op.workspace_id
      and s.workpiece_id = op.workpiece_id
      and strpos(approval.script_text, o.context_focus) > 0
      and not exists (
        select 1 from tongs.reference_clip_plan_membership m
        where m.plan_revision_id = provider_plan.id and m.opportunity_id = s.opportunity_id
      )
    order by s.opportunity_id, s.revision desc
  ) x;

  if retained_count > 0 then
    content_hash := encode(extensions.digest(convert_to(jsonb_build_object(
      'provider_plan', provider_plan.content_hash,
      'provider_members', provider_members,
      'creator_retained', retained
    )::text, 'UTF8'), 'sha256'), 'hex');
    immutable_hash := encode(extensions.digest(convert_to(jsonb_build_object(
      'content_hash', content_hash,
      'revision', provider_plan.revision + 1,
      'previous_revision_id', provider_plan.id
    )::text, 'UTF8'), 'sha256'), 'hex');

    insert into tongs.reference_clip_plan_revisions(
      workspace_id, workpiece_id, revision, previous_revision_id, previous_revision,
      script_approval_id, script_approval_revision, script_content_hash,
      contract_version, content_hash, immutable_revision_hash, created_by
    ) values (
      op.workspace_id, op.workpiece_id, provider_plan.revision + 1, provider_plan.id, provider_plan.revision,
      provider_plan.script_approval_id, provider_plan.script_approval_revision, provider_plan.script_content_hash,
      'forge.unified-visual-plan.retained.v2', content_hash, immutable_hash, op.created_by
    ) returning * into successor;

    for member in
      select * from tongs.reference_clip_plan_membership
      where plan_revision_id = provider_plan.id
      order by ordinal, opportunity_id
    loop
      insert into tongs.reference_clip_plan_membership(
        plan_revision_id, workspace_id, workpiece_id, plan_revision, ordinal,
        opportunity_id, opportunity_revision_id, opportunity_revision
      ) values (
        successor.id, op.workspace_id, op.workpiece_id, successor.revision, next_ordinal,
        member.opportunity_id, member.opportunity_revision_id, member.opportunity_revision
      );
      next_ordinal := next_ordinal + 1;
    end loop;

    for selected in
      select distinct on (s.opportunity_id) s.*
      from tongs.reference_clip_selections s
      join tongs.reference_clip_opportunity_revisions o on o.id = s.opportunity_revision_id
      where s.workspace_id = op.workspace_id
        and s.workpiece_id = op.workpiece_id
        and strpos(approval.script_text, o.context_focus) > 0
        and not exists (
          select 1 from tongs.reference_clip_plan_membership m
          where m.plan_revision_id = provider_plan.id and m.opportunity_id = s.opportunity_id
        )
      order by s.opportunity_id, s.revision desc
    loop
      insert into tongs.reference_clip_plan_membership(
        plan_revision_id, workspace_id, workpiece_id, plan_revision, ordinal,
        opportunity_id, opportunity_revision_id, opportunity_revision
      ) values (
        successor.id, op.workspace_id, op.workpiece_id, successor.revision, next_ordinal,
        selected.opportunity_id, selected.opportunity_revision_id, selected.opportunity_revision
      );
      next_ordinal := next_ordinal + 1;

      select * into previous_selection
      from tongs.reference_clip_selections
      where workspace_id = op.workspace_id and workpiece_id = op.workpiece_id
      order by revision desc limit 1;
      selection_fingerprint := encode(extensions.digest(convert_to(jsonb_build_object(
        'parent', op.operation_id,
        'retained_selection', selected.id,
        'plan', successor.id
      )::text, 'UTF8'), 'sha256'), 'hex');
      insert into tongs.reference_clip_selections(
        workspace_id, workpiece_id, revision, previous_selection_id, previous_revision,
        plan_revision_id, plan_revision, opportunity_id, opportunity_revision_id, opportunity_revision,
        candidate_revision_id, candidate_revision, operation_id, operation_fingerprint, created_by
      ) values (
        op.workspace_id, op.workpiece_id, coalesce(previous_selection.revision, 0) + 1,
        previous_selection.id, previous_selection.revision,
        successor.id, successor.revision, selected.opportunity_id, selected.opportunity_revision_id, selected.opportunity_revision,
        selected.candidate_revision_id, selected.candidate_revision,
        op.operation_id || ':retain:reference:' || selected.opportunity_id,
        selection_fingerprint, op.created_by
      );
    end loop;

    update tongs.reference_clip_plan_sequences
    set current_plan_revision_id = successor.id,
        current_plan_revision = successor.revision,
        current_selection_revision = (
          select max(revision) from tongs.reference_clip_selections
          where workspace_id = op.workspace_id and workpiece_id = op.workpiece_id
        ),
        updated_at = now()
    where workspace_id = op.workspace_id and workpiece_id = op.workpiece_id;
  else
    successor := provider_plan;
  end if;

  evidence := jsonb_build_object(
    'provider_plan_revision_id', provider_plan.id,
    'final_plan_revision_id', successor.id,
    'provider_proposed', provider_members,
    'creator_retained', retained,
    'creator_added', '[]'::jsonb
  );
  update tongs.unified_visual_plan_operations
  set child_membership_evidence_json = child_membership_evidence_json || jsonb_build_object('reference_clip', evidence),
      updated_at = now()
  where operation_id = op.operation_id
  returning child_membership_evidence_json into evidence;

  return jsonb_build_object(
    'disposition', 'retained',
    'revision_id', successor.id,
    'retained_count', retained_count,
    'membership_evidence', evidence
  );
end
$$;


ALTER FUNCTION "tongs"."retain_unified_reference_clip_selections_singular_legacy"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_provider_plan_revision_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."retain_unified_visual_plan_selections"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_child_kind" "text", "p_provider_plan_revision_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare
  op tongs.unified_visual_plan_operations%rowtype;
  approval tongs.script_approval_revisions%rowtype;
  retained jsonb:='[]'::jsonb;
  retained_count integer:=0;
  result jsonb;
  bseq tongs.broll_plan_sequences%rowtype; bp tongs.broll_plan_revisions%rowtype; bnext tongs.broll_plan_revisions%rowtype;
  bs tongs.broll_selections%rowtype; bprev tongs.broll_selections%rowtype; bm tongs.broll_plan_beat_membership%rowtype; bord integer;
  rseq tongs.reference_clip_plan_sequences%rowtype; rp tongs.reference_clip_plan_revisions%rowtype; rnext tongs.reference_clip_plan_revisions%rowtype;
  rs tongs.reference_clip_selections%rowtype; rprev tongs.reference_clip_selections%rowtype; rm tongs.reference_clip_plan_membership%rowtype; rord integer;
  vseq tongs.reference_visual_plan_sequences%rowtype; vp tongs.reference_visual_plan_revisions%rowtype; vnext tongs.reference_visual_plan_revisions%rowtype;
  vs tongs.reference_visual_selections%rowtype; vprev tongs.reference_visual_selections%rowtype; vm tongs.reference_visual_plan_membership%rowtype; vord integer;
  iseq tongs.workpiece_image_map_sequences%rowtype; ip tongs.image_map_revisions%rowtype; inext tongs.image_map_revisions%rowtype;
  retained_entries jsonb:='[]'::jsonb; next_document jsonb; semantic_hash text;
  h text; ih text; selection_fingerprint text;
  original_provider_plan_revision_id uuid:=p_provider_plan_revision_id;
begin
  select * into op from tongs.unified_visual_plan_operations where operation_id=p_operation_id for update;
  if not found or op.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict'); end if;
  
if op.owner_cost_attempt_id is not null then
    perform tongs._assert_owner_unified_visual_plan_persistence_authority(
      op.owner_cost_attempt_id,
      op.operation_id,
      op.operation_fingerprint,
      op.workspace_id,
      op.workpiece_id,
      op.created_by
    );
  elsif coalesce(auth.role(), '') = 'service_role' then
    raise exception 'owner-bound Unified Visual Plan operation required for service continuation'
      using errcode = '42501';
  elsif not tongs.has_workspace_role(op.workspace_id, 'editor') then
    raise exception 'workspace editor authority required' using errcode = '42501';
  end if;
  if op.child_membership_evidence_json ? p_child_kind then
    if op.child_membership_evidence_json->p_child_kind->>'provider_plan_revision_id'<>p_provider_plan_revision_id::text then return jsonb_build_object('disposition','retention_identity_conflict');end if;
    return jsonb_build_object('disposition','replay','revision_id',op.child_membership_evidence_json->p_child_kind->>'final_plan_revision_id','retained_count',jsonb_array_length(coalesce(op.child_membership_evidence_json->p_child_kind->'creator_retained','[]'::jsonb)),'membership_evidence',op.child_membership_evidence_json);
  end if;
  select * into approval from tongs.script_approval_revisions where id=op.script_approval_id;

  if p_child_kind='broll' then
    select * into bseq from tongs.broll_plan_sequences where workspace_id=op.workspace_id and workpiece_id=op.workpiece_id for update;
    if bseq.current_plan_revision_id is distinct from p_provider_plan_revision_id then return jsonb_build_object('disposition','provider_child_not_current'); end if;
    select * into bp from tongs.broll_plan_revisions where id=p_provider_plan_revision_id;
    select coalesce(jsonb_agg(jsonb_build_object('beat_id',x.beat_id,'selection_id',x.id) order by x.revision),'[]'::jsonb),count(*)
      into retained,retained_count from (
        select distinct on (s.beat_id) s.* from tongs.broll_selections s
        join tongs.broll_beat_revisions br on br.id=s.beat_revision_id
        where s.workspace_id=op.workspace_id and s.workpiece_id=op.workpiece_id and s.decision='selected'
          and strpos(approval.script_text,br.context_focus)>0
          and not exists(select 1 from tongs.broll_plan_beat_membership m where m.plan_revision_id=bp.id and m.beat_id=s.beat_id)
        order by s.beat_id,s.revision desc
      )x;
    if retained_count>0 then
      h:=encode(extensions.digest(convert_to(jsonb_build_object('provider_plan',bp.content_hash,'creator_retained',retained)::text,'UTF8'),'sha256'),'hex');
      ih:=encode(extensions.digest(convert_to(jsonb_build_object('content_hash',h,'revision',bp.revision+1,'previous_revision_id',bp.id)::text,'UTF8'),'sha256'),'hex');
      insert into tongs.broll_plan_revisions(workspace_id,workpiece_id,revision,previous_revision_id,previous_revision,script_approval_id,script_approval_revision,script_content_hash,source_context_contract_version,content_hash,immutable_revision_hash,created_by)
        values(op.workspace_id,op.workpiece_id,bp.revision+1,bp.id,bp.revision,bp.script_approval_id,bp.script_approval_revision,bp.script_content_hash,'forge.unified-visual-plan.retained.v1',h,ih,op.created_by) returning * into bnext;
      bord:=1;for bm in select * from tongs.broll_plan_beat_membership where plan_revision_id=bp.id order by ordinal loop insert into tongs.broll_plan_beat_membership values(bnext.id,op.workspace_id,op.workpiece_id,bnext.revision,bord,bm.beat_id,bm.beat_revision_id,bm.beat_revision);bord:=bord+1;end loop;
      for bs in select distinct on (s.beat_id)s.* from tongs.broll_selections s join tongs.broll_beat_revisions br on br.id=s.beat_revision_id where s.workspace_id=op.workspace_id and s.workpiece_id=op.workpiece_id and s.decision='selected' and strpos(approval.script_text,br.context_focus)>0 and not exists(select 1 from tongs.broll_plan_beat_membership m where m.plan_revision_id=bp.id and m.beat_id=s.beat_id) order by s.beat_id,s.revision desc loop
        insert into tongs.broll_plan_beat_membership values(bnext.id,op.workspace_id,op.workpiece_id,bnext.revision,bord,bs.beat_id,bs.beat_revision_id,bs.beat_revision);bord:=bord+1;
        select * into bprev from tongs.broll_selections where workspace_id=op.workspace_id and workpiece_id=op.workpiece_id order by revision desc limit 1;
        selection_fingerprint:=encode(extensions.digest(convert_to(jsonb_build_object('parent',op.operation_id,'retained_selection',bs.id,'plan',bnext.id)::text,'UTF8'),'sha256'),'hex');
        insert into tongs.broll_selections(workspace_id,workpiece_id,revision,previous_selection_id,previous_revision,plan_revision_id,plan_revision,beat_id,beat_revision_id,beat_revision,candidate_revision_id,candidate_revision,decision,operation_id,operation_fingerprint,created_by)
          values(op.workspace_id,op.workpiece_id,coalesce(bprev.revision,0)+1,bprev.id,bprev.revision,bnext.id,bnext.revision,bs.beat_id,bs.beat_revision_id,bs.beat_revision,bs.candidate_revision_id,bs.candidate_revision,'selected',op.operation_id||':retain:broll:'||bs.beat_id,selection_fingerprint,op.created_by);
      end loop;
      update tongs.broll_plan_sequences set current_plan_revision_id=bnext.id,current_plan_revision=bnext.revision,current_selection_revision=(select max(revision)from tongs.broll_selections where workspace_id=op.workspace_id and workpiece_id=op.workpiece_id),updated_at=now() where workspace_id=op.workspace_id and workpiece_id=op.workpiece_id;
      p_provider_plan_revision_id:=bnext.id;
    end if;
  elsif p_child_kind='reference_clip' then
    select * into rseq from tongs.reference_clip_plan_sequences where workspace_id=op.workspace_id and workpiece_id=op.workpiece_id for update;if rseq.current_plan_revision_id is distinct from p_provider_plan_revision_id then return jsonb_build_object('disposition','provider_child_not_current');end if;select * into rp from tongs.reference_clip_plan_revisions where id=p_provider_plan_revision_id;
    select coalesce(jsonb_agg(jsonb_build_object('opportunity_id',x.opportunity_id,'selection_id',x.id)order by x.revision),'[]'::jsonb),count(*) into retained,retained_count from(select distinct on(s.opportunity_id)s.* from tongs.reference_clip_selections s join tongs.reference_clip_opportunity_revisions o on o.id=s.opportunity_revision_id where s.workspace_id=op.workspace_id and s.workpiece_id=op.workpiece_id and strpos(approval.script_text,o.context_focus)>0 and not exists(select 1 from tongs.reference_clip_plan_membership m where m.plan_revision_id=rp.id and m.opportunity_id=s.opportunity_id)order by s.opportunity_id,s.revision desc)x;
    if retained_count>0 then
      h:=encode(extensions.digest(convert_to(jsonb_build_object('provider_plan',rp.content_hash,'creator_retained',retained)::text,'UTF8'),'sha256'),'hex');ih:=encode(extensions.digest(convert_to(jsonb_build_object('content_hash',h,'revision',rp.revision+1,'previous_revision_id',rp.id)::text,'UTF8'),'sha256'),'hex');
      insert into tongs.reference_clip_plan_revisions(workspace_id,workpiece_id,revision,previous_revision_id,previous_revision,script_approval_id,script_approval_revision,script_content_hash,contract_version,content_hash,immutable_revision_hash,created_by)values(op.workspace_id,op.workpiece_id,rp.revision+1,rp.id,rp.revision,rp.script_approval_id,rp.script_approval_revision,rp.script_content_hash,'forge.unified-visual-plan.retained.v1',h,ih,op.created_by)returning * into rnext;
      rord:=0;for rm in select * from tongs.reference_clip_plan_membership where plan_revision_id=rp.id order by ordinal loop insert into tongs.reference_clip_plan_membership values(rnext.id,op.workspace_id,op.workpiece_id,rnext.revision,rord,rm.opportunity_id,rm.opportunity_revision_id,rm.opportunity_revision);rord:=rord+1;end loop;
      for rs in select distinct on(s.opportunity_id)s.* from tongs.reference_clip_selections s join tongs.reference_clip_opportunity_revisions o on o.id=s.opportunity_revision_id where s.workspace_id=op.workspace_id and s.workpiece_id=op.workpiece_id and strpos(approval.script_text,o.context_focus)>0 and not exists(select 1 from tongs.reference_clip_plan_membership m where m.plan_revision_id=rp.id and m.opportunity_id=s.opportunity_id)order by s.opportunity_id,s.revision desc loop
        insert into tongs.reference_clip_plan_membership values(rnext.id,op.workspace_id,op.workpiece_id,rnext.revision,rord,rs.opportunity_id,rs.opportunity_revision_id,rs.opportunity_revision);rord:=rord+1;select * into rprev from tongs.reference_clip_selections where workspace_id=op.workspace_id and workpiece_id=op.workpiece_id order by revision desc limit 1;selection_fingerprint:=encode(extensions.digest(convert_to(jsonb_build_object('parent',op.operation_id,'retained_selection',rs.id,'plan',rnext.id)::text,'UTF8'),'sha256'),'hex');insert into tongs.reference_clip_selections(workspace_id,workpiece_id,revision,previous_selection_id,previous_revision,plan_revision_id,plan_revision,opportunity_id,opportunity_revision_id,opportunity_revision,candidate_revision_id,candidate_revision,operation_id,operation_fingerprint,created_by)values(op.workspace_id,op.workpiece_id,coalesce(rprev.revision,0)+1,rprev.id,rprev.revision,rnext.id,rnext.revision,rs.opportunity_id,rs.opportunity_revision_id,rs.opportunity_revision,rs.candidate_revision_id,rs.candidate_revision,op.operation_id||':retain:reference:'||rs.opportunity_id,selection_fingerprint,op.created_by);
      end loop;
      update tongs.reference_clip_plan_sequences set current_plan_revision_id=rnext.id,current_plan_revision=rnext.revision,current_selection_revision=(select max(revision)from tongs.reference_clip_selections where workspace_id=op.workspace_id and workpiece_id=op.workpiece_id),updated_at=now()where workspace_id=op.workspace_id and workpiece_id=op.workpiece_id;p_provider_plan_revision_id:=rnext.id;
    end if;
  elsif p_child_kind='reference_visual' then
    select * into vseq from tongs.reference_visual_plan_sequences where workspace_id=op.workspace_id and workpiece_id=op.workpiece_id for update;if vseq.current_plan_revision_id is distinct from p_provider_plan_revision_id then return jsonb_build_object('disposition','provider_child_not_current');end if;select * into vp from tongs.reference_visual_plan_revisions where id=p_provider_plan_revision_id;
    select coalesce(jsonb_agg(jsonb_build_object('opportunity_id',x.opportunity_id,'selection_id',x.id)order by x.created_at),'[]'::jsonb),count(*) into retained,retained_count from(select distinct on(s.opportunity_id)s.* from tongs.reference_visual_selections s join tongs.reference_visual_opportunity_revisions o on o.opportunity_id=s.opportunity_id where s.workspace_id=op.workspace_id and s.workpiece_id=op.workpiece_id and strpos(approval.script_text,o.context_focus)>0 and not exists(select 1 from tongs.reference_visual_plan_membership m where m.plan_revision_id=vp.id and m.opportunity_id=s.opportunity_id)order by s.opportunity_id,s.revision desc,o.revision desc)x;
    if retained_count>0 then
      h:=encode(extensions.digest(convert_to(jsonb_build_object('provider_plan',vp.content_hash,'creator_retained',retained)::text,'UTF8'),'sha256'),'hex');ih:=encode(extensions.digest(convert_to(jsonb_build_object('content_hash',h,'revision',vp.revision+1,'previous_revision_id',vp.id)::text,'UTF8'),'sha256'),'hex');insert into tongs.reference_visual_plan_revisions(workspace_id,workpiece_id,revision,previous_revision_id,previous_revision,script_approval_id,script_approval_revision,script_content_hash,contract_version,content_hash,immutable_revision_hash,created_by)values(op.workspace_id,op.workpiece_id,vp.revision+1,vp.id,vp.revision,vp.script_approval_id,vp.script_approval_revision,vp.script_content_hash,'forge.unified-visual-plan.retained.v1',h,ih,op.created_by)returning * into vnext;
      vord:=0;for vm in select * from tongs.reference_visual_plan_membership where plan_revision_id=vp.id order by ordinal loop insert into tongs.reference_visual_plan_membership values(vnext.id,op.workspace_id,op.workpiece_id,vnext.revision,vord,vm.opportunity_id,vm.opportunity_revision_id,vm.opportunity_revision);vord:=vord+1;end loop;
      for vs in select distinct on(s.opportunity_id)s.* from tongs.reference_visual_selections s join tongs.reference_visual_opportunity_revisions o on o.opportunity_id=s.opportunity_id where s.workspace_id=op.workspace_id and s.workpiece_id=op.workpiece_id and strpos(approval.script_text,o.context_focus)>0 and not exists(select 1 from tongs.reference_visual_plan_membership m where m.plan_revision_id=vp.id and m.opportunity_id=s.opportunity_id)order by s.opportunity_id,s.revision desc,o.revision desc loop
        select * into vm from tongs.reference_visual_plan_membership m where m.opportunity_id=vs.opportunity_id order by m.plan_revision desc limit 1;insert into tongs.reference_visual_plan_membership values(vnext.id,op.workspace_id,op.workpiece_id,vnext.revision,vord,vm.opportunity_id,vm.opportunity_revision_id,vm.opportunity_revision);vord:=vord+1;select * into vprev from tongs.reference_visual_selections where workspace_id=op.workspace_id and workpiece_id=op.workpiece_id and opportunity_id=vs.opportunity_id order by revision desc limit 1;selection_fingerprint:=encode(extensions.digest(convert_to(jsonb_build_object('parent',op.operation_id,'retained_selection',vs.id,'plan',vnext.id)::text,'UTF8'),'sha256'),'hex');insert into tongs.reference_visual_selections(workspace_id,workpiece_id,opportunity_id,revision,previous_selection_id,previous_revision,plan_revision_id,plan_revision,candidate_revision_id,operation_id,operation_fingerprint,created_by)values(op.workspace_id,op.workpiece_id,vs.opportunity_id,coalesce(vprev.revision,0)+1,vprev.id,vprev.revision,vnext.id,vnext.revision,vs.candidate_revision_id,op.operation_id||':retain:visual:'||vs.opportunity_id,selection_fingerprint,op.created_by);
      end loop;
      update tongs.reference_visual_plan_sequences set current_plan_revision_id=vnext.id,current_plan_revision=vnext.revision,updated_at=now()where workspace_id=op.workspace_id and workpiece_id=op.workpiece_id;p_provider_plan_revision_id:=vnext.id;
    end if;
  elsif p_child_kind='image' then
    select * into iseq from tongs.workpiece_image_map_sequences where workspace_id=op.workspace_id and workpiece_id=op.workpiece_id for update;if iseq.current_revision_id is distinct from p_provider_plan_revision_id then return jsonb_build_object('disposition','provider_child_not_current');end if;select * into ip from tongs.image_map_revisions where id=p_provider_plan_revision_id;
    select coalesce(jsonb_agg(x.entry order by x.source_revision,x.entry->>'id'),'[]'::jsonb),count(*) into retained_entries,retained_count from(
      select distinct on(e->>'id') e as entry,r.revision as source_revision from tongs.image_map_revisions r cross join lateral jsonb_array_elements(coalesce(r.document_json->'entries','[]'::jsonb))e
      where r.workspace_id=op.workspace_id and r.workpiece_id=op.workpiece_id and nullif(e->>'selected_asset_id','') is not null and strpos(approval.script_text,coalesce(e->>'anchor',e->>'prompt_basis',''))>0
        and not exists(select 1 from jsonb_array_elements(coalesce(ip.document_json->'entries','[]'::jsonb))current_entry where current_entry->>'id'=e->>'id')
      order by e->>'id',r.revision desc
    )x;
    retained:=coalesce((select jsonb_agg(jsonb_build_object('entry_id',e->>'id','selected_asset_id',e->>'selected_asset_id'))from jsonb_array_elements(retained_entries)e),'[]'::jsonb);
    if retained_count>0 then
      next_document:=jsonb_set(ip.document_json,'{entries}',coalesce(ip.document_json->'entries','[]'::jsonb)||retained_entries,true);h:=encode(extensions.digest(convert_to(next_document::text,'UTF8'),'sha256'),'hex');semantic_hash:=encode(extensions.digest(convert_to(jsonb_build_object('script',ip.source_script_content_hash,'document',h)::text,'UTF8'),'sha256'),'hex');ih:=encode(extensions.digest(convert_to(jsonb_build_object('content_hash',h,'semantic_state_hash',semantic_hash,'revision',ip.revision+1,'previous_revision_id',ip.id)::text,'UTF8'),'sha256'),'hex');
      insert into tongs.image_map_revisions(workspace_id,workpiece_id,revision,previous_revision_id,previous_revision,source_script_approval_id,source_script_approval_revision,source_script_content_hash,anchor_contract_version,provenance_state,document_json,document_content_hash,semantic_state_hash,immutable_revision_hash,created_by)
        values(op.workspace_id,op.workpiece_id,ip.revision+1,ip.id,ip.revision,ip.source_script_approval_id,ip.source_script_approval_revision,ip.source_script_content_hash,'forge.unified-visual-plan.retained.v1','current',next_document,h,semantic_hash,ih,op.created_by)returning * into inext;
      update tongs.workpiece_image_map_sequences set current_revision_id=inext.id,current_revision=inext.revision,updated_at=now()where workspace_id=op.workspace_id and workpiece_id=op.workpiece_id;p_provider_plan_revision_id:=inext.id;
    end if;
  else return jsonb_build_object('disposition','invalid_child_kind');end if;

  update tongs.unified_visual_plan_operations set child_membership_evidence_json=child_membership_evidence_json||jsonb_build_object(p_child_kind,jsonb_build_object('provider_plan_revision_id',original_provider_plan_revision_id,'final_plan_revision_id',p_provider_plan_revision_id,'provider_proposed',true,'creator_retained',retained,'creator_added','[]'::jsonb)),updated_at=now()where operation_id=op.operation_id returning child_membership_evidence_json into result;
  return jsonb_build_object('disposition','retained','revision_id',p_provider_plan_revision_id,'retained_count',retained_count,'membership_evidence',result);
end$$;


ALTER FUNCTION "tongs"."retain_unified_visual_plan_selections"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_child_kind" "text", "p_provider_plan_revision_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."retry_youtube_publication_stage"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_publication_operation_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare v_job tongs.youtube_publication_jobs%rowtype;
begin
  perform tongs.require_workspace_role(p_workspace_id,'editor');
  select * into v_job from tongs.youtube_publication_jobs
   where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and publication_operation_id=p_publication_operation_id for update;
  if not found then return jsonb_build_object('disposition','not_found'); end if;
  if v_job.state<>'failed' or not v_job.retryable then return jsonb_build_object('disposition','not_retryable','state',v_job.state); end if;
  if v_job.current_stage not in('queued','video_upload','provider_processing','thumbnail','captions') then return jsonb_build_object('disposition','invalid_stage','stage',v_job.current_stage); end if;
  update tongs.youtube_publication_jobs set state=v_job.current_stage,attempt_count=0,next_run_at=now(),lease_owner=null,
    lease_expires_at=null,last_heartbeat_at=null,retryable=false,user_action_code=null,updated_at=now() where id=v_job.id;
  return jsonb_build_object('disposition','retry_queued','job_id',v_job.id,'stage',v_job.current_stage);
end; $$;


ALTER FUNCTION "tongs"."retry_youtube_publication_stage"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_publication_operation_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."review_hearth_editorial_preflight_v1"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_report_id" "uuid", "p_operation_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare
  v_user uuid:=auth.uid();
  v_report tongs.hearth_editorial_preflight_reports%rowtype;
  v_receipt tongs.hearth_preflight_review_receipts%rowtype;
begin
  if v_user is null or not tongs.has_workspace_role(p_workspace_id,'editor') then
    return jsonb_build_object('disposition','denied');
  end if;
  select * into v_receipt
  from tongs.hearth_preflight_review_receipts
  where operation_id=p_operation_id or report_id=p_report_id;
  if found then
    return jsonb_build_object('disposition','duplicate','review',to_jsonb(v_receipt));
  end if;
  select r.* into v_report
  from tongs.hearth_editorial_preflight_reports r
  join tongs.workpiece_hearth_preflight_sequences s
    on s.current_report_id=r.id and s.current_revision=r.revision
  join tongs.workpiece_files wf
    on wf.workpiece_id=r.workpiece_id
    and wf.path=r.source_file_path
    and lower(wf.hash_value)=r.script_content_hash
  where r.id=p_report_id
    and r.workspace_id=p_workspace_id
    and r.workpiece_id=p_workpiece_id
    and (
      r.research_artifact_id is null
      or exists(
        select 1
        from tongs.workpiece_hearth_research_sequences rs
        join tongs.hearth_research_artifact_revisions ra on ra.id=rs.current_artifact_id
        where rs.workspace_id=r.workspace_id
          and rs.workpiece_id=r.workpiece_id
          and ra.id=r.research_artifact_id
          and ra.artifact_content_hash=r.research_artifact_hash
      )
    );
  if not found then
    return jsonb_build_object('disposition','stale','reason','preflight_not_current');
  end if;
  if exists(
    select 1
    from tongs.hearth_editorial_preflight_findings current_finding
    where current_finding.report_id=v_report.id
      and current_finding.severity in ('blocker','warning')
      and not exists(
        select 1
        from tongs.hearth_preflight_finding_acknowledgements a
        join tongs.hearth_editorial_preflight_findings prior_finding
          on prior_finding.report_id=a.report_id
          and prior_finding.ordinal=a.finding_ordinal
        join tongs.hearth_editorial_preflight_reports prior_report
          on prior_report.id=prior_finding.report_id
        where prior_report.workspace_id=v_report.workspace_id
          and prior_report.workpiece_id=v_report.workpiece_id
          and prior_report.script_content_hash=v_report.script_content_hash
          and prior_report.checker_contract_version=v_report.checker_contract_version
          and prior_finding.finding_basis_hash=current_finding.finding_basis_hash
          and (
            (current_finding.severity='blocker' and a.action='resolve')
            or (current_finding.severity='warning' and a.action in ('acknowledge','resolve'))
          )
      )
  ) then
    return jsonb_build_object('disposition','blocked','reason','findings_unhandled');
  end if;
  insert into tongs.hearth_preflight_review_receipts(
    workspace_id,workpiece_id,report_id,report_revision,script_content_hash,
    research_artifact_id,research_artifact_hash,operation_id,reviewed_by
  ) values(
    p_workspace_id,p_workpiece_id,v_report.id,v_report.revision,v_report.script_content_hash,
    v_report.research_artifact_id,v_report.research_artifact_hash,p_operation_id,v_user
  ) returning * into v_receipt;
  return jsonb_build_object('disposition','reviewed','review',to_jsonb(v_receipt));
end;
$$;


ALTER FUNCTION "tongs"."review_hearth_editorial_preflight_v1"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_report_id" "uuid", "p_operation_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."revise_owner_operating_budget"("p_budget_id" "uuid", "p_status" "text", "p_maximum_amount_micros" bigint, "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_budget tongs.owner_operating_budgets%rowtype;
  v_revision integer;
  v_event_id uuid := gen_random_uuid();
  v_reason text := nullif(btrim(coalesce(p_reason, '')), '');
  v_payload jsonb;
begin
  if v_actor is null or not tongs.is_platform_operator(v_actor) then
    raise exception 'platform operator required' using errcode = '42501';
  end if;
  if p_budget_id is null or p_status not in ('draft', 'active', 'paused', 'closed')
     or (p_maximum_amount_micros is not null and p_maximum_amount_micros <= 0)
     or (p_status = 'active' and p_maximum_amount_micros is null) or v_reason is null then
    raise exception 'invalid owner operating budget revision' using errcode = '22023';
  end if;
  select * into v_budget from tongs.owner_operating_budgets where id = p_budget_id for update;
  if not found then raise exception 'owner operating budget not found' using errcode = 'P0002'; end if;
  select coalesce(max(revision), 0) + 1 into v_revision
  from tongs.owner_operating_budget_revisions where budget_id = p_budget_id;
  v_payload := jsonb_build_object('budget_id', p_budget_id, 'revision', v_revision,
    'status', p_status, 'maximum_amount_micros', p_maximum_amount_micros, 'reason', v_reason);
  perform tongs._create_accounting_event(
    v_event_id, 'owner-budget:' || p_budget_id::text || ':revision:' || v_revision::text,
    'owner_operating_budget_revised', 'owner_internal', 'owner_operating_budget', p_budget_id::text,
    v_budget.currency, null, v_budget.workspace_id, v_actor, v_payload, now()
  );
  insert into tongs.owner_operating_budget_revisions(
    budget_id, revision, status, maximum_amount_micros, reason, actor_id, journal_event_id
  ) values (p_budget_id, v_revision, p_status, p_maximum_amount_micros, v_reason, v_actor, v_event_id);
  return jsonb_build_object('budget_id', p_budget_id, 'revision', v_revision, 'status', p_status,
    'maximum_amount_micros', p_maximum_amount_micros,
    'spending_enabled', false);
end;
$$;


ALTER FUNCTION "tongs"."revise_owner_operating_budget"("p_budget_id" "uuid", "p_status" "text", "p_maximum_amount_micros" bigint, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."revoke_bellows_join_link"("p_join_link_id" "uuid") RETURNS TABLE("revoked" boolean, "join_link_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare
  v_join_link tongs.bellows_session_join_links%rowtype;
begin
  select *
  into v_join_link
  from tongs.bellows_session_join_links
  where id = p_join_link_id
  for update;

  if not found then
    raise exception 'bellows_join_link_not_found'
      using errcode = 'P0002';
  end if;

  if coalesce(auth.role(), '') <> 'service_role' then
    if auth.uid() is null then
      raise exception 'Not authenticated'
        using errcode = '42501';
    end if;

    perform tongs.assert_workspace_role(v_join_link.workspace_id, 'editor');
  end if;

  if v_join_link.revoked_at is not null then
    return query select false, v_join_link.id;
    return;
  end if;

  update tongs.bellows_session_join_links jl
  set
    revoked_at = now(),
    updated_at = now()
  where jl.id = v_join_link.id;

  return query select true, v_join_link.id;
end;
$$;


ALTER FUNCTION "tongs"."revoke_bellows_join_link"("p_join_link_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."revoke_workspace_invite"("p_invite_id" "uuid") RETURNS TABLE("revoked" boolean, "invite_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare
  v_user uuid;
  v_invite tongs.workspace_invites%rowtype;
begin
  v_user := auth.uid();
  if v_user is null then
    raise exception 'Not authenticated'
      using errcode = '42501';
  end if;

  select wi.*
  into v_invite
  from tongs.workspace_invites wi
  where wi.id = p_invite_id
  for update;

  if not found then
    raise exception 'Invite not found'
      using errcode = 'P0002';
  end if;

  perform tongs.assert_workspace_role(v_invite.workspace_id, 'admin');

  if v_invite.accepted_at is not null then
    raise exception 'Invite already accepted'
      using errcode = '22023';
  end if;

  if v_invite.revoked_at is not null then
    return query select false, v_invite.id;
    return;
  end if;

  update tongs.workspace_invites wi
  set revoked_at = now(),
      updated_at = now()
  where wi.id = v_invite.id;

  return query select true, v_invite.id;
end;
$$;


ALTER FUNCTION "tongs"."revoke_workspace_invite"("p_invite_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."round_customer_price_micros"("p_amount_micros" numeric, "p_currency" "text") RETURNS bigint
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO 'pg_catalog'
    AS $$
declare v_increment bigint;
begin
  if p_amount_micros is null or p_amount_micros < 0 then
    raise exception 'invalid customer price' using errcode = '22023';
  end if;
  -- Current supported quote currencies use two decimal minor units. Add a currency map before adding others.
  if upper(btrim(coalesce(p_currency,''))) <> 'USD' then
    raise exception 'pricing_not_configured: unsupported currency rounding policy' using errcode = 'P0001';
  end if;
  v_increment := 10000;
  if p_amount_micros > 9223372036854775807::numeric then
    raise exception 'pricing customer ceiling overflows bigint micros' using errcode = '22003';
  end if;
  return (ceil(p_amount_micros / v_increment::numeric) * v_increment)::bigint;
end $$;


ALTER FUNCTION "tongs"."round_customer_price_micros"("p_amount_micros" numeric, "p_currency" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."round_customer_price_micros"("p_amount_micros" numeric, "p_currency" "text") IS 'Preserves micro precision through calculation, then rounds customer price upward to the next USD cent.';



CREATE OR REPLACE FUNCTION "tongs"."seal_complete_bellows_capture"("p_session_id" "text", "p_authority_generation" bigint, "p_workpiece_id" "uuid", "p_manifest" "jsonb", "p_manifest_sha256" "text") RETURNS "tongs"."bellows_capture_packages"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public', 'auth'
    AS $$
declare v_session tongs.bellows_sessions; v_package tongs.bellows_capture_packages;
begin
  select * into v_session from tongs.bellows_sessions where id=p_session_id for update;
  if not found then raise exception 'bellows_session_not_found'; end if;
  if v_session.authority_generation<>p_authority_generation then raise exception 'bellows_stale_authority_generation'; end if;
  if not exists(select 1 from tongs.bellows_session_participants p where p.session_id=p_session_id and p.id=v_session.acting_host_participant_id and p.user_id=auth.uid()) then raise exception 'bellows_seal_forbidden'; end if;
  if exists(select 1 from tongs.bellows_segments where session_id=p_session_id and integrity_state<>'verified')
    or not exists(select 1 from tongs.bellows_segments where session_id=p_session_id)
    or exists(select 1 from tongs.bellows_integrity_findings where session_id=p_session_id) then
    raise exception 'bellows_complete_seal_integrity_failed';
  end if;
  insert into tongs.bellows_capture_packages(session_id,workspace_id,workpiece_id,outcome,manifest,manifest_sha256,hammer_handoff_id)
    values(p_session_id,v_session.workspace_id,p_workpiece_id,'sealed',p_manifest,lower(p_manifest_sha256),'bellows:'||p_session_id)
    on conflict(session_id) do nothing returning * into v_package;
  if v_package.id is null then
    select * into v_package from tongs.bellows_capture_packages where session_id=p_session_id;
    if v_package.manifest_sha256<>lower(p_manifest_sha256) then raise exception 'bellows_capture_package_identity_conflict'; end if;
  end if;
  update tongs.bellows_sessions set lifecycle_state='sealed',outcome='sealed',seal_state='sealed',sealed_at=coalesce(sealed_at,now()),workpiece_id=p_workpiece_id where id=p_session_id;
  return v_package;
end $$;


ALTER FUNCTION "tongs"."seal_complete_bellows_capture"("p_session_id" "text", "p_authority_generation" bigint, "p_workpiece_id" "uuid", "p_manifest" "jsonb", "p_manifest_sha256" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."seed_my_thumbnail_brand_templates"("p_workspace_id" "uuid") RETURNS TABLE("inserted_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
