        )
      ),
      false,
      v_user
    ),
    (
      p_workspace_id,
      'cinematic',
      'Cinematic',
      jsonb_build_object(
        'title_style', jsonb_build_object(
          'font_preset', 'cinematic_serif',
          'text_color', '#F8F5EC',
          'shadow', jsonb_build_object('enabled', true, 'strength', 'strong')
        ),
        'layout', jsonb_build_object(
          'title_position', 'bottom',
          'alignment', 'center',
          'max_lines', 3
        ),
        'background_treatment', jsonb_build_object(
          'darken', 0.24,
