ALTER FUNCTION "tongs"."seed_my_thumbnail_brand_templates"("p_workspace_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."select_broll_candidate"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_beat_id" "uuid", "p_candidate_revision_id" "uuid", "p_expected_plan_revision_id" "uuid", "p_expected_plan_revision" bigint, "p_expected_selection_revision" bigint, "p_operation_id" "text", "p_operation_fingerprint" "text", "p_actor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare v_seq tongs.broll_plan_sequences%rowtype; v_member tongs.broll_plan_beat_membership%rowtype; v_candidate tongs.broll_candidate_revisions%rowtype; v_previous tongs.broll_selections%rowtype; v_selection tongs.broll_selections%rowtype; v_op tongs.broll_operation_receipts%rowtype; v_result jsonb;
begin
 if not tongs.has_workspace_role(p_workspace_id,'editor') then raise exception 'workspace editor authority required' using errcode='42501'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_operation_id,0));
 select * into v_op from tongs.broll_operation_receipts where operation_id=p_operation_id for update;
 if found then if v_op.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict'); end if; return v_op.receipt_json; end if;
 select * into v_seq from tongs.broll_plan_sequences where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id for update;
 if not found or v_seq.current_plan_revision_id is distinct from p_expected_plan_revision_id or v_seq.current_plan_revision<>p_expected_plan_revision then return jsonb_build_object('disposition','plan_revision_conflict','current_revision_id',v_seq.current_plan_revision_id,'current_revision',v_seq.current_plan_revision); end if;
 if v_seq.current_selection_revision<>p_expected_selection_revision then return jsonb_build_object('disposition','selection_revision_conflict','current_selection_revision',v_seq.current_selection_revision); end if;
 select * into v_member from tongs.broll_plan_beat_membership where plan_revision_id=v_seq.current_plan_revision_id and beat_id=p_beat_id;
 if not found then return jsonb_build_object('disposition','beat_not_current'); end if;
 select * into v_candidate from tongs.broll_candidate_revisions where id=p_candidate_revision_id and workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and beat_id=p_beat_id;
 if not found then return jsonb_build_object('disposition','candidate_not_attached'); end if;
 select * into v_previous from tongs.broll_selections where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id order by revision desc limit 1;
 insert into tongs.broll_selections(workspace_id,workpiece_id,revision,previous_selection_id,previous_revision,plan_revision_id,plan_revision,beat_id,beat_revision_id,beat_revision,candidate_revision_id,candidate_revision,decision,operation_id,operation_fingerprint,created_by)
 values(p_workspace_id,p_workpiece_id,v_seq.current_selection_revision+1,v_previous.id,v_previous.revision,v_seq.current_plan_revision_id,v_seq.current_plan_revision,p_beat_id,v_member.beat_revision_id,v_member.beat_revision,v_candidate.id,v_candidate.revision,'selected',p_operation_id,p_operation_fingerprint,p_actor_id) returning * into v_selection;
 update tongs.broll_plan_sequences set current_selection_revision=v_selection.revision,updated_at=now() where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id;
 v_result:=jsonb_build_object('disposition','committed','selection',to_jsonb(v_selection));
 insert into tongs.broll_operation_receipts(operation_id,operation_fingerprint,operation_type,state,workspace_id,workpiece_id,beat_id,normalized_inputs_json,result_selection_id,receipt_json,created_by) values(p_operation_id,p_operation_fingerprint,'selection','selected',p_workspace_id,p_workpiece_id,p_beat_id,jsonb_build_object('candidate_revision_id',p_candidate_revision_id),v_selection.id,v_result,p_actor_id);
 return v_result;
end $$;


ALTER FUNCTION "tongs"."select_broll_candidate"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_beat_id" "uuid", "p_candidate_revision_id" "uuid", "p_expected_plan_revision_id" "uuid", "p_expected_plan_revision" bigint, "p_expected_selection_revision" bigint, "p_operation_id" "text", "p_operation_fingerprint" "text", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."select_image_map_candidate"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_expected_current_revision" bigint, "p_expected_current_revision_id" "uuid", "p_image_map_entry_id" "text", "p_candidate_asset_id" "uuid", "p_operation_contract_version" "text", "p_operation_id" "text", "p_actor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare
  v_sequence tongs.workpiece_image_map_sequences%rowtype;
  v_current tongs.image_map_revisions%rowtype;
  v_revision tongs.image_map_revisions%rowtype;
  v_receipt tongs.hearth_authority_operation_receipts%rowtype;
  v_document jsonb;
  v_document_hash text;
  v_semantic_hash text;
  v_revision_hash text;
  v_fingerprint text;
  v_result jsonb;
  v_next bigint;
begin
  if p_actor_id is null then raise exception 'actor is required' using errcode='22023'; end if;
  if not exists (
    select 1 from tongs.assets a
    where a.id=p_candidate_asset_id and a.workspace_id=p_workspace_id and a.workpiece_id=p_workpiece_id
      and a.metadata_json->>'image_map_entry_id'=p_image_map_entry_id and a.status='ready'
  ) then
    return jsonb_build_object('disposition','candidate_not_attached');
  end if;

  insert into tongs.workpiece_image_map_sequences(workspace_id,workpiece_id)
  values(p_workspace_id,p_workpiece_id) on conflict do nothing;
  select * into v_sequence from tongs.workpiece_image_map_sequences
    where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id for update;
  if v_sequence.current_revision <> p_expected_current_revision
    or v_sequence.current_revision_id is distinct from p_expected_current_revision_id then
    return jsonb_build_object('disposition','revision_conflict','current_revision',v_sequence.current_revision,'current_revision_id',v_sequence.current_revision_id);
  end if;
  select * into v_current from tongs.image_map_revisions where id=v_sequence.current_revision_id;
  if not found then return jsonb_build_object('disposition','canonical_image_map_required'); end if;
  if not exists (
    select 1 from jsonb_array_elements(v_current.document_json->'entries') e,
      jsonb_array_elements(coalesce(e->'candidate_assets','[]'::jsonb)) a
    where e->>'id'=p_image_map_entry_id and a->>'asset_id'=p_candidate_asset_id::text
  ) then return jsonb_build_object('disposition','candidate_not_attached'); end if;

  v_fingerprint := encode(extensions.digest(convert_to(jsonb_build_object(
    'contract',p_operation_contract_version,'workspace_id',p_workspace_id,'workpiece_id',p_workpiece_id,
    'source_revision_id',p_expected_current_revision_id,'source_revision',p_expected_current_revision,
    'entry_id',p_image_map_entry_id,'candidate_asset_id',p_candidate_asset_id
  )::text,'UTF8'),'sha256'),'hex');
  select * into v_receipt from tongs.hearth_authority_operation_receipts where operation_id=p_operation_id;
  if found then
    if v_receipt.operation_fingerprint <> v_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict'); end if;
    return v_receipt.immutable_result_json;
  end if;

  select jsonb_set(v_current.document_json,'{entries}',jsonb_agg(
    case when e->>'id'=p_image_map_entry_id
      then e || jsonb_build_object('selected_asset_id',p_candidate_asset_id::text,'status','selected')
      else e end order by ord
  )) into v_document
  from jsonb_array_elements(v_current.document_json->'entries') with ordinality entries(e,ord);
  if v_document = v_current.document_json then
    v_result := jsonb_build_object('disposition','no_change','image_map_revision',to_jsonb(v_current));
    insert into tongs.hearth_authority_operation_receipts(
      operation_id,operation_fingerprint,workspace_id,workpiece_id,mutation_kind,
      source_image_map_revision_id,source_image_map_revision,target_script_approval_id,target_script_approval_revision,
      result_image_map_revision_id,result_image_map_revision,immutable_result_json,created_by
    ) values(p_operation_id,v_fingerprint,p_workspace_id,p_workpiece_id,'select_candidate',v_current.id,v_current.revision,
      v_current.source_script_approval_id,v_current.source_script_approval_revision,v_current.id,v_current.revision,v_result,p_actor_id);
    return v_result;
  end if;

  v_document_hash := encode(extensions.digest(convert_to(v_document::text,'UTF8'),'sha256'),'hex');
  v_semantic_hash := encode(extensions.digest(convert_to(jsonb_build_object(
    'workspace_id',p_workspace_id,'workpiece_id',p_workpiece_id,
    'source_script_approval_id',v_current.source_script_approval_id,'source_script_hash',v_current.source_script_content_hash,
    'anchor_contract_version',v_current.anchor_contract_version,'provenance_state',v_current.provenance_state,
    'document_content_hash',v_document_hash,'document',v_document
  )::text,'UTF8'),'sha256'),'hex');
  v_next := v_sequence.current_revision+1;
  v_revision_hash := encode(extensions.digest(convert_to(jsonb_build_object(
    'semantic_state_hash',v_semantic_hash,'revision',v_next,'previous_revision_id',v_current.id,
    'created_at',clock_timestamp()::text,'operation_id',p_operation_id
  )::text,'UTF8'),'sha256'),'hex');
  insert into tongs.image_map_revisions(
    workspace_id,workpiece_id,revision,previous_revision_id,previous_revision,
    source_script_approval_id,source_script_approval_revision,source_script_content_hash,
    anchor_contract_version,provenance_state,document_json,document_content_hash,
    semantic_state_hash,immutable_revision_hash,created_by
  ) values(p_workspace_id,p_workpiece_id,v_next,v_current.id,v_current.revision,
    v_current.source_script_approval_id,v_current.source_script_approval_revision,v_current.source_script_content_hash,
    v_current.anchor_contract_version,v_current.provenance_state,v_document,v_document_hash,
    v_semantic_hash,v_revision_hash,p_actor_id) returning * into v_revision;
  update tongs.workpiece_image_map_sequences set current_revision_id=v_revision.id,current_revision=v_revision.revision,updated_at=now()
    where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id;
  v_result := jsonb_build_object('disposition','committed','image_map_revision',to_jsonb(v_revision));
  insert into tongs.hearth_authority_operation_receipts(
    operation_id,operation_fingerprint,workspace_id,workpiece_id,mutation_kind,
    source_image_map_revision_id,source_image_map_revision,target_script_approval_id,target_script_approval_revision,
    result_image_map_revision_id,result_image_map_revision,immutable_result_json,created_by
  ) values(p_operation_id,v_fingerprint,p_workspace_id,p_workpiece_id,'select_candidate',v_current.id,v_current.revision,
    v_current.source_script_approval_id,v_current.source_script_approval_revision,v_revision.id,v_revision.revision,v_result,p_actor_id);
  return v_result;
end
$$;


ALTER FUNCTION "tongs"."select_image_map_candidate"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_expected_current_revision" bigint, "p_expected_current_revision_id" "uuid", "p_image_map_entry_id" "text", "p_candidate_asset_id" "uuid", "p_operation_contract_version" "text", "p_operation_id" "text", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."select_reference_clip_candidate"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_opportunity_id" "uuid", "p_candidate_revision_id" "uuid", "p_expected_plan_revision_id" "uuid", "p_expected_plan_revision" bigint, "p_expected_selection_revision" bigint, "p_operation_id" "text", "p_operation_fingerprint" "text", "p_actor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare seq tongs.reference_clip_plan_sequences%rowtype;current_set tongs.reference_clip_selection_set_revisions%rowtype;legacy_receipt tongs.reference_clip_operation_receipts%rowtype;ids jsonb;result jsonb;legacy_replay boolean:=false;
begin
 select * into current_set from tongs.reference_clip_selection_set_revisions where operation_id=p_operation_id;
 if found then
  if current_set.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict');end if;
  select coalesce(jsonb_agg(candidate_revision_id order by ordinal),'[]'::jsonb)into ids from tongs.reference_clip_selection_set_members where selection_set_revision_id=current_set.id;
  return jsonb_build_object('disposition','committed','selection_set_revision',to_jsonb(current_set),'selected_candidate_revision_ids',ids,'canonical_selection_revision',current_set.canonical_revision);
 end if;
 select * into legacy_receipt from tongs.reference_clip_operation_receipts where operation_id=p_operation_id;
 if found and legacy_receipt.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict');end if;
 legacy_replay:=found;
 select * into seq from tongs.reference_clip_plan_sequences where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id;
 if coalesce(seq.current_selection_revision,0)<>p_expected_selection_revision then return jsonb_build_object('disposition','selection_revision_conflict','current_selection_revision',coalesce(seq.current_selection_revision,0));end if;
 select * into current_set from tongs.reference_clip_selection_set_revisions where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and opportunity_id=p_opportunity_id and plan_revision_id=p_expected_plan_revision_id order by revision desc limit 1;
 select coalesce(jsonb_agg(candidate_revision_id order by ordinal),'[]'::jsonb)into ids from tongs.reference_clip_selection_set_members where selection_set_revision_id=current_set.id;
 if legacy_replay then return jsonb_build_object('disposition','committed','selection_set_revision',to_jsonb(current_set),'selected_candidate_revision_ids',ids,'canonical_selection_revision',current_set.canonical_revision);end if;
 result:=tongs.commit_reference_clip_selection_set(p_workspace_id,p_workpiece_id,p_opportunity_id,ids||jsonb_build_array(p_candidate_revision_id),p_expected_plan_revision_id,p_expected_plan_revision,coalesce(current_set.revision,0),p_operation_id,p_operation_fingerprint,p_actor_id);
 return result;
end$$;


ALTER FUNCTION "tongs"."select_reference_clip_candidate"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_opportunity_id" "uuid", "p_candidate_revision_id" "uuid", "p_expected_plan_revision_id" "uuid", "p_expected_plan_revision" bigint, "p_expected_selection_revision" bigint, "p_operation_id" "text", "p_operation_fingerprint" "text", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."select_reference_visual_candidate"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_opportunity_id" "uuid", "p_candidate_revision_id" "uuid", "p_expected_plan_revision_id" "uuid", "p_expected_plan_revision" bigint, "p_expected_selection_revision" bigint, "p_operation_id" "text", "p_operation_fingerprint" "text", "p_actor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare op tongs.reference_visual_operation_receipts%rowtype;seq tongs.reference_visual_plan_sequences%rowtype;
 member_rev tongs.reference_visual_plan_membership%rowtype;cand_rev tongs.reference_visual_candidate_revisions%rowtype;
 previous_selection tongs.reference_visual_selections%rowtype;new_selection tongs.reference_visual_selections%rowtype;active_revision bigint;result jsonb;
begin
 if not tongs.has_workspace_role(p_workspace_id,'editor')or auth.uid() is distinct from p_actor_id then raise exception 'workspace editor authority required' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_operation_id,0));select * into op from tongs.reference_visual_operation_receipts where operation_id=p_operation_id;
 if found then if op.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict');end if;return op.receipt_json;end if;
 select * into seq from tongs.reference_visual_plan_sequences where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id for update;
 if seq.current_plan_revision_id is distinct from p_expected_plan_revision_id or seq.current_plan_revision<>p_expected_plan_revision then return jsonb_build_object('disposition','plan_revision_conflict');end if;
 select * into member_rev from tongs.reference_visual_plan_membership where plan_revision_id=seq.current_plan_revision_id and opportunity_id=p_opportunity_id;
 if not found then return jsonb_build_object('disposition','opportunity_not_current');end if;
 select * into cand_rev from tongs.reference_visual_candidate_revisions where id=p_candidate_revision_id and workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and opportunity_id=p_opportunity_id and opportunity_revision_id=member_rev.opportunity_revision_id;
 if not found then return jsonb_build_object('disposition','candidate_not_attached');end if;
 if not tongs.reference_visual_candidate_release_ready(cand_rev.id) then return jsonb_build_object('disposition','candidate_not_release_ready');end if;
 if not tongs.reference_visual_candidate_current_for_plan(cand_rev.id) then return jsonb_build_object('disposition','candidate_not_current_for_plan');end if;
 select * into previous_selection from tongs.reference_visual_selections where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and opportunity_id=p_opportunity_id and plan_revision_id=seq.current_plan_revision_id order by revision desc limit 1;
 active_revision:=case when previous_selection.id is not null and tongs.reference_visual_candidate_current_for_plan(previous_selection.candidate_revision_id) then previous_selection.revision else 0 end;
 if active_revision<>p_expected_selection_revision then return jsonb_build_object('disposition','selection_revision_conflict','current_revision',active_revision);end if;
 insert into tongs.reference_visual_selections(workspace_id,workpiece_id,opportunity_id,revision,previous_selection_id,previous_revision,plan_revision_id,plan_revision,candidate_revision_id,operation_id,operation_fingerprint,created_by)
 values(p_workspace_id,p_workpiece_id,p_opportunity_id,coalesce(previous_selection.revision,0)+1,previous_selection.id,previous_selection.revision,seq.current_plan_revision_id,seq.current_plan_revision,cand_rev.id,p_operation_id,p_operation_fingerprint,p_actor_id)returning * into new_selection;
 result:=jsonb_build_object('disposition','committed','selection',to_jsonb(new_selection));insert into tongs.reference_visual_operation_receipts values(p_operation_id,p_operation_fingerprint,'selection',p_workspace_id,p_workpiece_id,'committed',new_selection.id,result,p_actor_id,now());return result;
end$$;


ALTER FUNCTION "tongs"."select_reference_visual_candidate"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_opportunity_id" "uuid", "p_candidate_revision_id" "uuid", "p_expected_plan_revision_id" "uuid", "p_expected_plan_revision" bigint, "p_expected_selection_revision" bigint, "p_operation_id" "text", "p_operation_fingerprint" "text", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."set_adaptive_style_features"("p_workspace_id" "uuid", "p_alignment_enabled" boolean, "p_ai_accelerate_enabled" boolean) RETURNS TABLE("workspace_id" "uuid", "adaptive_style_alignment_enabled" boolean, "adaptive_style_ai_accelerate_enabled" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare
  v_user uuid;
  v_before tongs.workspaces%rowtype;
  v_alignment_enabled boolean := coalesce(p_alignment_enabled, false);
  v_ai_accelerate_enabled boolean := coalesce(p_ai_accelerate_enabled, false);
  v_event_timestamp timestamptz := now();
begin
  v_user := auth.uid();
  if v_user is null then
    raise exception 'Not authenticated'
      using errcode = '42501';
  end if;

  if p_workspace_id is null then
    raise exception 'workspace_id is required'
      using errcode = '22023';
  end if;

  perform tongs.assert_workspace_role(p_workspace_id, 'admin');

  select w.*
  into v_before
  from tongs.workspaces w
  where w.id = p_workspace_id
  for update;

  if not found then
    raise exception 'Workspace not found'
      using errcode = 'P0002';
  end if;

  update tongs.workspaces w
  set
    adaptive_style_alignment_enabled = v_alignment_enabled,
    adaptive_style_ai_accelerate_enabled = v_ai_accelerate_enabled
  where w.id = p_workspace_id;

  if to_regclass('tongs.hearth_interaction_events') is not null then
    if v_before.adaptive_style_alignment_enabled is distinct from v_alignment_enabled then
      insert into tongs.hearth_interaction_events (
        user_id,
        workspace_id,
        episode_id,
        event_type,
        payload
      )
      values (
        v_user,
        p_workspace_id,
        null,
        'workspace.feature.toggled',
        jsonb_build_object(
          'workspace_id', p_workspace_id,
          'flag_name', 'adaptive_style_alignment_enabled',
          'old', coalesce(v_before.adaptive_style_alignment_enabled, false),
          'new', v_alignment_enabled,
          'actor_user_id', v_user,
          'timestamp', v_event_timestamp
        )
      );
    end if;

    if v_before.adaptive_style_ai_accelerate_enabled is distinct from v_ai_accelerate_enabled then
      insert into tongs.hearth_interaction_events (
        user_id,
        workspace_id,
        episode_id,
        event_type,
        payload
      )
      values (
        v_user,
        p_workspace_id,
        null,
        'workspace.feature.toggled',
        jsonb_build_object(
          'workspace_id', p_workspace_id,
          'flag_name', 'adaptive_style_ai_accelerate_enabled',
          'old', coalesce(v_before.adaptive_style_ai_accelerate_enabled, false),
          'new', v_ai_accelerate_enabled,
          'actor_user_id', v_user,
          'timestamp', v_event_timestamp
        )
      );
    end if;
  end if;

  return query
  select
    p_workspace_id,
    v_alignment_enabled,
    v_ai_accelerate_enabled;
end;
$$;


ALTER FUNCTION "tongs"."set_adaptive_style_features"("p_workspace_id" "uuid", "p_alignment_enabled" boolean, "p_ai_accelerate_enabled" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."set_brand_profile_archived"("p_workspace_id" "uuid", "p_profile_id" "uuid", "p_archived" boolean, "p_clear_default" boolean DEFAULT false, "p_replacement_profile_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare v_is_default boolean;
begin perform tongs.assert_workspace_role(p_workspace_id,'editor'); select exists(select 1 from tongs.workspace_default_brand_profiles where workspace_id=p_workspace_id and profile_id=p_profile_id) into v_is_default;
  if p_archived and v_is_default and not p_clear_default and p_replacement_profile_id is null then raise exception 'Archiving the default requires explicit replacement or clear.' using errcode='22023'; end if;
  if p_archived and v_is_default then if p_replacement_profile_id is not null then perform tongs.set_workspace_default_brand_profile(p_workspace_id,p_replacement_profile_id); else perform tongs.clear_workspace_default_brand_profile(p_workspace_id); end if; end if;
  update tongs.brand_profiles set archived_at=case when p_archived then now() else null end,updated_by=auth.uid() where id=p_profile_id and workspace_id=p_workspace_id;
  return jsonb_build_object('profile_id',p_profile_id,'archived',p_archived); end $$;


ALTER FUNCTION "tongs"."set_brand_profile_archived"("p_workspace_id" "uuid", "p_profile_id" "uuid", "p_archived" boolean, "p_clear_default" boolean, "p_replacement_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."set_broll_prompt_creator_direction"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_beat_id" "uuid", "p_expected_direction_revision" bigint, "p_creator_direction" "text", "p_actor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare v_seq tongs.broll_prompt_sequences%rowtype;
begin
 if not tongs.has_workspace_role(p_workspace_id,'editor') then raise exception 'workspace editor authority required' using errcode='42501'; end if;
 insert into tongs.broll_prompt_sequences(workspace_id,workpiece_id,beat_id) values(p_workspace_id,p_workpiece_id,p_beat_id) on conflict do nothing;
 select * into v_seq from tongs.broll_prompt_sequences where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and beat_id=p_beat_id for update;
 if v_seq.creator_direction_revision<>p_expected_direction_revision then return jsonb_build_object('disposition','creator_direction_conflict','current_creator_direction',v_seq.creator_direction,'current_creator_direction_revision',v_seq.creator_direction_revision); end if;
 update tongs.broll_prompt_sequences set creator_direction=coalesce(p_creator_direction,''),creator_direction_revision=creator_direction_revision+1,updated_at=now() where workspace_id=p_workspace_id and workpiece_id=p_workpiece_id and beat_id=p_beat_id returning * into v_seq;
 return jsonb_build_object('disposition','committed','sequence',to_jsonb(v_seq));
end $$;


ALTER FUNCTION "tongs"."set_broll_prompt_creator_direction"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_beat_id" "uuid", "p_expected_direction_revision" bigint, "p_creator_direction" "text", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."set_credential_lifecycle_deadline"("p_credential_id" "uuid", "p_expires_at" timestamp with time zone, "p_rotation_lead" interval, "p_evidence_json" "jsonb", "p_actor_id" "uuid", "p_event_key" "text", "p_occurred_at" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_row tongs.credential_lifecycle_records%rowtype;
  v_sequence integer;
  v_lead interval := coalesce(p_rotation_lead, interval '7 days');
  v_evidence jsonb := coalesce(p_evidence_json,'{}'::jsonb);
  v_now timestamptz := coalesce(p_occurred_at,transaction_timestamp());
begin
  perform tongs._require_credential_lifecycle_writer();
  if p_expires_at is null or p_expires_at<=v_now or v_lead<=interval '0 seconds'
     or p_event_key is null or p_actor_id is null or not tongs.is_platform_operator(p_actor_id)
     or not tongs._credential_lifecycle_metadata_safe(v_evidence) then
    raise exception 'invalid credential lifecycle deadline' using errcode='22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('credential-lifecycle:'||p_credential_id::text,0));
  select * into v_row from tongs.credential_lifecycle_records where credential_id=p_credential_id for update;
  if not found then raise exception 'credential lifecycle record not found' using errcode='P0002'; end if;
  if v_row.lifecycle_status in ('revoked','disabled') then
    raise exception 'terminal credential deadline cannot change' using errcode='22023';
  end if;
  select coalesce(max(event_sequence),0)+1 into v_sequence
    from tongs.credential_lifecycle_events where credential_id=p_credential_id;
  update tongs.credential_lifecycle_records set
    expires_at=p_expires_at,rotation_lead=v_lead,rotation_due_at=p_expires_at-v_lead,
    updated_at=v_now
  where credential_id=p_credential_id returning * into v_row;
  insert into tongs.credential_lifecycle_events(
    event_id,credential_id,event_sequence,event_key,from_status,to_status,event_type,actor_id,evidence_json,occurred_at
  ) values (
    gen_random_uuid(),p_credential_id,v_sequence,btrim(p_event_key),v_row.lifecycle_status,
    v_row.lifecycle_status,'deadline_recorded',p_actor_id,
    v_evidence||jsonb_build_object('expires_at',p_expires_at,'rotation_lead_seconds',extract(epoch from v_lead)),v_now
  );
  return to_jsonb(v_row)-'credential_identity_hash';
end;
$$;


ALTER FUNCTION "tongs"."set_credential_lifecycle_deadline"("p_credential_id" "uuid", "p_expires_at" timestamp with time zone, "p_rotation_lead" interval, "p_evidence_json" "jsonb", "p_actor_id" "uuid", "p_event_key" "text", "p_occurred_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."set_my_ai_funding_preference"("p_workspace_id" "uuid", "p_payer_kind" "text", "p_org_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_user uuid := auth.uid();
  v_workspace tongs.workspaces%rowtype;
  v_revision integer;
  v_id uuid := gen_random_uuid();
begin
  if v_user is null then raise exception 'authentication required' using errcode='42501'; end if;
  select * into v_workspace from tongs.workspaces where id=p_workspace_id;
  if not found or not exists(select 1 from tongs.workspace_members wm where wm.workspace_id=p_workspace_id and wm.user_id=v_user) then
    raise exception 'workspace membership required' using errcode='42501';
  end if;
  if p_payer_kind not in ('personal','organization_shared','owner_testing') then
    raise exception 'invalid payer selection' using errcode='22023';
  end if;
  if p_payer_kind='organization_shared' then
    if p_org_id is null or v_workspace.org_id is distinct from p_org_id
       or not exists(select 1 from tongs.org_members om where om.org_id=p_org_id and om.user_id=v_user) then
      raise exception 'organization funding membership required' using errcode='42501';
    end if;
  elsif p_org_id is not null then
    raise exception 'organization id is only valid for shared funding' using errcode='22023';
  end if;
  if p_payer_kind='owner_testing' and not tongs._transition_owner_authority_agrees(v_user) then raise exception 'explicit owner-testing identity required' using errcode='42501'; end if;
  perform pg_advisory_xact_lock(hashtextextended('ai-funding-preference:'||v_user::text||':'||p_workspace_id::text,0));
  select coalesce(max(revision),0)+1 into v_revision from tongs.ai_funding_preference_revisions
    where user_id=v_user and workspace_id=p_workspace_id;
  insert into tongs.ai_funding_preference_revisions(id,user_id,workspace_id,revision,payer_kind,org_id,actor_id)
  values(v_id,v_user,p_workspace_id,v_revision,p_payer_kind,p_org_id,v_user);
  return jsonb_build_object('preference_id',v_id,'revision',v_revision,'payer_kind',p_payer_kind,'org_id',p_org_id);
end $$;


ALTER FUNCTION "tongs"."set_my_ai_funding_preference"("p_workspace_id" "uuid", "p_payer_kind" "text", "p_org_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."set_my_ai_model_preference"("p_selection_key" "uuid", "p_expected_revision" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare uid uuid:=auth.uid(); prior integer; identity_id uuid;
begin
 if uid is null then raise exception 'authentication required' using errcode='28000'; end if;
 select identity.id into identity_id
 from tongs.ai_model_identities identity
 join lateral(
   select r.* from tongs.ai_model_identity_revisions r
   where r.model_identity_id=identity.id order by r.revision desc limit 1
 ) revision on revision.lifecycle_state='active'
 join lateral(
   select choice.* from tongs.ai_global_model_choice_revisions choice
   where choice.model_identity_id=identity.id order by choice.revision desc limit 1
 ) global_choice on global_choice.authority_state='selectable'
 where identity.customer_selection_key=p_selection_key;
 if identity_id is null then raise exception 'model selection unavailable' using errcode='P0001'; end if;
 perform pg_advisory_xact_lock(hashtextextended('ai-model-pref:'||uid::text,0));
 select coalesce(max(revision),0) into prior from tongs.ai_model_preference_revisions where user_id=uid;
 if p_expected_revision is not null and p_expected_revision<>prior then raise exception 'preference changed; reload' using errcode='40001'; end if;
 insert into tongs.ai_model_preference_revisions(id,user_id,revision,model_identity_id)
 values(gen_random_uuid(),uid,prior+1,identity_id);
 return tongs.read_my_ai_model_preference();
end $$;


ALTER FUNCTION "tongs"."set_my_ai_model_preference"("p_selection_key" "uuid", "p_expected_revision" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."set_my_ai_operation_model_override"("p_operation_code" "text", "p_selection_key" "uuid", "p_expected_revision" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare uid uuid:=auth.uid(); prior integer; identity_id uuid;
begin
 if uid is null then raise exception 'authentication required' using errcode='28000'; end if;
 select model_identity_id into identity_id from tongs._eligible_ai_models_for_operation(p_operation_code) where customer_selection_key=p_selection_key;
 if identity_id is null then raise exception 'selected model is not currently eligible for this operation' using errcode='P0001'; end if;
 perform pg_advisory_xact_lock(hashtextextended('ai-operation-model:'||uid::text||':'||p_operation_code,0));
 select coalesce(max(revision),0) into prior from tongs.ai_operation_model_override_revisions where user_id=uid and operation_code=p_operation_code;
 if p_expected_revision is not null and p_expected_revision<>prior then raise exception 'operation override changed; reload' using errcode='40001'; end if;
 insert into tongs.ai_operation_model_override_revisions(id,user_id,operation_code,revision,override_state,model_identity_id) values(gen_random_uuid(),uid,p_operation_code,prior+1,'specific',identity_id);
 return tongs.read_my_ai_operation_model_override(p_operation_code);
end $$;


ALTER FUNCTION "tongs"."set_my_ai_operation_model_override"("p_operation_code" "text", "p_selection_key" "uuid", "p_expected_revision" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."set_my_barstock_discovery_preferences"("p_workspace_id" "uuid", "p_expected_revision" bigint, "p_genre" "text", "p_topic_interests" "text"[] DEFAULT '{}'::"text"[], "p_editorial_scope" "text" DEFAULT NULL::"text", "p_language" "text" DEFAULT NULL::"text", "p_region" "text" DEFAULT NULL::"text", "p_enabled" boolean DEFAULT true, "p_auto_refresh_authorized" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare u uuid:=auth.uid(); r tongs.workspace_discovery_preferences%rowtype;
begin
 if u is null or not tongs.has_workspace_role(p_workspace_id,'editor') then return jsonb_build_object('outcome','denied'); end if;
 if nullif(btrim(p_genre),'') is null then return jsonb_build_object('outcome','invalid','reason','genre_required'); end if;
 insert into tongs.workspace_discovery_preferences(workspace_id,user_id,genre,topic_interests,editorial_scope,language,region,enabled,auto_refresh_authorized)
 values(p_workspace_id,u,btrim(p_genre),coalesce(p_topic_interests,'{}'),nullif(btrim(p_editorial_scope),''),nullif(btrim(p_language),''),nullif(btrim(p_region),''),p_enabled,p_auto_refresh_authorized)
 on conflict(workspace_id,user_id) do update set genre=excluded.genre,topic_interests=excluded.topic_interests,editorial_scope=excluded.editorial_scope,language=excluded.language,region=excluded.region,enabled=excluded.enabled,auto_refresh_authorized=excluded.auto_refresh_authorized,revision=workspace_discovery_preferences.revision+1,updated_at=now()
 where workspace_discovery_preferences.revision=p_expected_revision returning * into r;
 if r.user_id is null then return jsonb_build_object('outcome','revision_conflict'); end if;
 return jsonb_build_object('outcome','saved','preference',to_jsonb(r));
end$$;


ALTER FUNCTION "tongs"."set_my_barstock_discovery_preferences"("p_workspace_id" "uuid", "p_expected_revision" bigint, "p_genre" "text", "p_topic_interests" "text"[], "p_editorial_scope" "text", "p_language" "text", "p_region" "text", "p_enabled" boolean, "p_auto_refresh_authorized" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."set_my_openai_text_model_preference"("p_route_code" "text", "p_preference_kind" "text", "p_selection_key" "uuid" DEFAULT NULL::"uuid", "p_expected_revision" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
begin
 if p_preference_kind='specific' then perform tongs.set_my_ai_operation_model_override(p_route_code,p_selection_key,p_expected_revision);
 elsif p_preference_kind='best_available' and p_selection_key is null then perform tongs.clear_my_ai_operation_model_override(p_route_code,p_expected_revision);
 else raise exception 'invalid preference' using errcode='22023'; end if;
 return tongs.read_my_openai_text_model_preference(p_route_code);
end $$;


ALTER FUNCTION "tongs"."set_my_openai_text_model_preference"("p_route_code" "text", "p_preference_kind" "text", "p_selection_key" "uuid", "p_expected_revision" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."set_my_writing_profile"("p_workspace_id" "uuid", "p_default_audience" "text" DEFAULT NULL::"text", "p_default_structure" "text" DEFAULT NULL::"text", "p_style_notes" "text" DEFAULT NULL::"text") RETURNS TABLE("workspace_id" "uuid", "user_id" "uuid", "default_audience" "text", "default_structure" "text", "style_notes" "text", "last_used_tone_preset" "text", "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare
  v_user uuid;
  v_default_audience text := nullif(btrim(coalesce(p_default_audience, '')), '');
  v_default_structure text := nullif(btrim(coalesce(p_default_structure, '')), '');
  v_style_notes text := nullif(btrim(coalesce(p_style_notes, '')), '');
begin
  v_user := auth.uid();
  if v_user is null then
    raise exception 'Not authenticated'
      using errcode = '42501';
  end if;

  if p_workspace_id is null then
    raise exception 'workspace_id is required'
      using errcode = '22023';
  end if;

  perform tongs.assert_workspace_role(p_workspace_id, 'viewer');

  insert into tongs.workspace_writing_profiles (
    workspace_id,
    user_id,
    default_audience,
    default_structure,
    style_notes,
    created_at,
    updated_at
  )
  values (
    p_workspace_id,
    v_user,
    v_default_audience,
    v_default_structure,
    v_style_notes,
    now(),
    now()
  )
  on conflict on constraint workspace_writing_profiles_pkey do update
    set default_audience = excluded.default_audience,
        default_structure = excluded.default_structure,
        style_notes = excluded.style_notes,
        updated_at = now();

  return query
  select
    p.workspace_id,
    p.user_id,
    p.default_audience,
    p.default_structure,
    p.style_notes,
    p.last_used_tone_preset,
    p.updated_at
  from tongs.workspace_writing_profiles p
  where p.workspace_id = p_workspace_id
    and p.user_id = v_user;
end;
$$;


ALTER FUNCTION "tongs"."set_my_writing_profile"("p_workspace_id" "uuid", "p_default_audience" "text", "p_default_structure" "text", "p_style_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."set_my_writing_tone_preset"("p_workspace_id" "uuid", "p_tone_preset" "text") RETURNS TABLE("workspace_id" "uuid", "user_id" "uuid", "default_audience" "text", "default_structure" "text", "style_notes" "text", "last_used_tone_preset" "text", "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare
  v_user uuid;
  v_tone_preset text := lower(nullif(btrim(coalesce(p_tone_preset, '')), ''));
begin
  v_user := auth.uid();
  if v_user is null then
    raise exception 'Not authenticated'
      using errcode = '42501';
  end if;

  if p_workspace_id is null then
    raise exception 'workspace_id is required'
      using errcode = '22023';
  end if;

  if v_tone_preset is null then
    raise exception 'tone_preset is required'
      using errcode = '22023';
  end if;

  if v_tone_preset not in ('neutral_conversational', 'newsroom_neutral', 'spicy_but_safe') then
    raise exception 'Unsupported tone preset: %', v_tone_preset
      using errcode = '22023';
  end if;

  perform tongs.assert_workspace_role(p_workspace_id, 'viewer');

  insert into tongs.workspace_writing_profiles (
    workspace_id,
    user_id,
    last_used_tone_preset,
    created_at,
    updated_at
  )
  values (
    p_workspace_id,
    v_user,
    v_tone_preset,
    now(),
    now()
  )
  on conflict on constraint workspace_writing_profiles_pkey do update
    set last_used_tone_preset = excluded.last_used_tone_preset,
        updated_at = now();

  return query
  select
    p.workspace_id,
    p.user_id,
    p.default_audience,
    p.default_structure,
    p.style_notes,
    p.last_used_tone_preset,
    p.updated_at
  from tongs.workspace_writing_profiles p
  where p.workspace_id = p_workspace_id
    and p.user_id = v_user;
end;
$$;


ALTER FUNCTION "tongs"."set_my_writing_tone_preset"("p_workspace_id" "uuid", "p_tone_preset" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."set_platform_operator"("p_user_id" "uuid", "p_enabled" boolean, "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
begin
  if auth.role() <> 'service_role' then
    raise exception 'service role authority required' using errcode = '42501';
  end if;
  if p_user_id is null or p_enabled is null or nullif(btrim(coalesce(p_reason, '')), '') is null then
    raise exception 'user, enabled state, and reason are required' using errcode = '22023';
  end if;
  if not exists (select 1 from auth.users u where u.id = p_user_id) then
    raise exception 'platform operator user not found' using errcode = 'P0002';
  end if;

  if p_enabled then
    insert into tongs.platform_operators(user_id, reason, granted_by)
    values (p_user_id, btrim(p_reason), auth.uid())
    on conflict (user_id) do update
      set reason = excluded.reason,
          granted_by = excluded.granted_by,
          granted_at = now();
  else
    delete from tongs.platform_operators where user_id = p_user_id;
  end if;

  return jsonb_build_object(
    'user_id', p_user_id,
    'enabled', p_enabled,
    'changed_at', now()
  );
end;
$$;


ALTER FUNCTION "tongs"."set_platform_operator"("p_user_id" "uuid", "p_enabled" boolean, "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."set_publishing_provider_connection_state"("p_actor_user_id" "uuid", "p_connection_id" "uuid", "p_connection_state" "text", "p_credential_state" "text", "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare v_connection tongs.publishing_provider_connections%rowtype;
begin
  if auth.role()<>'service_role' then raise exception 'Forbidden' using errcode='42501'; end if;
  if p_connection_state not in('refresh_required','expired','revoked','invalid','disconnected') or p_credential_state not in('refresh_required','expired','revoked','invalid') then return jsonb_build_object('disposition','invalid','code','invalid_connection_transition'); end if;
  select * into v_connection from tongs.publishing_provider_connections where id=p_connection_id for update;
  if not found or v_connection.owner_user_id<>p_actor_user_id then return jsonb_build_object('disposition','denied','code','connection_owner_required'); end if;
  update tongs.publishing_provider_connections set state=p_connection_state,authorization_revision=authorization_revision+1,revoked_at=case when p_connection_state in('revoked','disconnected') then now() else revoked_at end,updated_at=now() where id=p_connection_id;
  update tongs.publishing_provider_credential_authorities set state=p_credential_state,updated_at=now() where id=v_connection.credential_authority_id;
  return jsonb_build_object('disposition','committed','connection_id',p_connection_id,'connection_state',p_connection_state,'credential_state',p_credential_state,'reason',p_reason);
end; $$;


ALTER FUNCTION "tongs"."set_publishing_provider_connection_state"("p_actor_user_id" "uuid", "p_connection_id" "uuid", "p_connection_state" "text", "p_credential_state" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."set_publishing_workspace_destination_grant"("p_workspace_id" "uuid", "p_destination_id" "uuid", "p_expected_revision" integer, "p_state" "text", "p_reason" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare
  v_user uuid := auth.uid();
  v_destination tongs.publishing_executable_destinations%rowtype;
  v_connection tongs.publishing_provider_connections%rowtype;
  v_head tongs.publishing_workspace_destination_grant_heads%rowtype;
  v_id uuid := gen_random_uuid();
  v_revision integer;
begin
  if v_user is null or not tongs.has_workspace_role(p_workspace_id, 'admin') then
    return jsonb_build_object('disposition','denied','code','workspace_admin_required');
  end if;
  if p_state not in('active','revoked') then
    return jsonb_build_object('disposition','invalid','code','invalid_grant_state');
  end if;
  select * into v_destination from tongs.publishing_executable_destinations where id = p_destination_id;
  if not found then return jsonb_build_object('disposition','blocked','code','destination_missing'); end if;
  select * into v_connection from tongs.publishing_provider_connections where id = v_destination.connection_id;
  if not found or v_connection.owner_user_id <> v_user then
    return jsonb_build_object('disposition','denied','code','connection_owner_required');
  end if;
  if p_state = 'active' and (
    v_connection.state <> 'active'
    or v_destination.state <> 'active'
    or v_destination.current_capability_revision_id is null
    or not exists(
      select 1 from tongs.publishing_provider_credential_authorities ca
      where ca.id = v_connection.credential_authority_id and ca.state = 'available'
    )
  ) then
    return jsonb_build_object('disposition','blocked','code','destination_not_executable');
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_workspace_id::text||':'||p_destination_id::text||':publishing-grant',0));
  select * into v_head from tongs.publishing_workspace_destination_grant_heads where workspace_id=p_workspace_id and executable_destination_id=p_destination_id for update;
  if coalesce(v_head.current_revision,0) <> p_expected_revision then
    return jsonb_build_object('disposition','revision_conflict','current_revision',coalesce(v_head.current_revision,0),'current_grant_revision_id',v_head.current_grant_revision_id);
  end if;
  if v_head.current_grant_revision_id is not null and exists(select 1 from tongs.publishing_workspace_destination_grant_revisions where id=v_head.current_grant_revision_id and state=p_state) then
    return jsonb_build_object('disposition','no_change','grant_revision_id',v_head.current_grant_revision_id,'revision',v_head.current_revision,'state',p_state);
  end if;
  v_revision := coalesce(v_head.current_revision,0) + 1;
  insert into tongs.publishing_workspace_destination_grant_revisions(id,workspace_id,executable_destination_id,connection_id,revision,previous_grant_revision_id,state,granted_by_user_id,reason)
  values(v_id,p_workspace_id,p_destination_id,v_destination.connection_id,v_revision,v_head.current_grant_revision_id,p_state,v_user,nullif(btrim(coalesce(p_reason,'')),''));
  insert into tongs.publishing_workspace_destination_grant_heads(workspace_id,executable_destination_id,current_grant_revision_id,current_revision)
  values(p_workspace_id,p_destination_id,v_id,v_revision)
  on conflict(workspace_id,executable_destination_id) do update set current_grant_revision_id=excluded.current_grant_revision_id,current_revision=excluded.current_revision,updated_at=now();
  return jsonb_build_object('disposition','committed','grant_revision_id',v_id,'revision',v_revision,'state',p_state);
end; $$;


ALTER FUNCTION "tongs"."set_publishing_workspace_destination_grant"("p_workspace_id" "uuid", "p_destination_id" "uuid", "p_expected_revision" integer, "p_state" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."set_reference_material_rollout"("p_workspace_id" "uuid", "p_enabled" boolean) RETURNS TABLE("workspace_id" "uuid", "reference_material_review_enabled" boolean)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
begin
  if auth.uid() is null then
    raise exception 'Not authenticated' using errcode = '42501';
  end if;
  if p_workspace_id is null then
    raise exception 'workspace_id is required' using errcode = '22023';
  end if;
  perform tongs.assert_workspace_role(p_workspace_id, 'admin');
  return query
  update tongs.workspaces w
  set reference_material_review_enabled = coalesce(p_enabled, false)
  where w.id = p_workspace_id
  returning w.id, w.reference_material_review_enabled;
  if not found then
    raise exception 'Workspace not found' using errcode = 'P0002';
  end if;
end;
$$;


ALTER FUNCTION "tongs"."set_reference_material_rollout"("p_workspace_id" "uuid", "p_enabled" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."set_runway_execution_rollout_mode"("p_mode" "text", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_current tongs.runway_execution_rollout_revisions%rowtype;
  v_control tongs.paid_execution_control_revisions%rowtype;
  v_revision integer;
begin
  if v_actor is null or not tongs.is_platform_operator(v_actor) then
    raise exception 'platform operator required' using errcode = '42501';
  end if;
  if p_mode not in ('enforce', 'halt_new') or nullif(btrim(coalesce(p_reason, '')), '') is null then
    raise exception 'invalid Runway rollout mode revision' using errcode = '22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('runway-rollout', 0));
  select * into v_current from tongs._current_runway_execution_rollout();
  if v_current.mode = 'halt_new' and p_mode = 'enforce' then
    raise exception 'halted Runway execution requires a reviewed recovery migration' using errcode = '42501';
  end if;
  if p_mode = 'enforce' then
    select * into v_control from tongs._current_paid_execution_control();
    if not v_control.pricing_activation_enabled or not v_control.provider_execution_enabled
       or not v_control.owner_budget_spending_enabled then
      raise exception 'pricing, provider execution, and owner-budget spending must be activated before Runway cutover'
        using errcode = '42501';
    end if;
  end if;
  select coalesce(max(revision), 0) + 1 into v_revision from tongs.runway_execution_rollout_revisions;
  insert into tongs.runway_execution_rollout_revisions(revision, mode, reason, actor_id)
  values (v_revision, p_mode, btrim(p_reason), v_actor);
  return jsonb_build_object('revision', v_revision, 'mode', p_mode,
    'new_paid_submissions_allowed', p_mode = 'enforce',
    'polling_and_reconciliation_available', true);
end;
$$;


ALTER FUNCTION "tongs"."set_runway_execution_rollout_mode"("p_mode" "text", "p_reason" "text") OWNER TO "postgres";


