CREATE OR REPLACE FUNCTION "tongs"."settle_ai_credit_reservation"("p_user_id" "uuid", "p_reservation_id" "uuid", "p_settlement_id" "uuid", "p_customer_charge" bigint, "p_provider_request_id" "text", "p_reason" "text", "p_metadata_json" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_account tongs.ai_credits%rowtype;
  v_reservation tongs.ai_credit_reservations%rowtype;
  v_event tongs.ai_credit_reservation_events%rowtype;
  v_release bigint;
  v_prior_release bigint;
begin
  if p_customer_charge < 0 then raise exception 'customer charge cannot be negative' using errcode = '22023'; end if;
  select * into v_account from tongs.ai_credits where user_id = p_user_id for update;
  if not found then raise exception 'AI-credit account not found' using errcode = 'P0002'; end if;
  select * into v_reservation from tongs.ai_credit_reservations where id = p_reservation_id and user_id = p_user_id for update;
  if not found then raise exception 'reservation not found' using errcode = 'P0002'; end if;
  select * into v_event from tongs.ai_credit_reservation_events where reservation_id = p_reservation_id and event_type = 'settled';
  if found then
    if v_event.idempotency_key <> p_settlement_id or v_event.amount <> p_customer_charge then
      raise exception 'settlement replay conflict' using errcode = '23505';
    end if;
    return jsonb_build_object('event', to_jsonb(v_event), 'replay', true);
  end if;
  select coalesce(sum(amount), 0)::bigint into v_prior_release
    from tongs.ai_credit_reservation_events where reservation_id = p_reservation_id and event_type = 'released';
  if v_prior_release > 0 then raise exception 'released reservation cannot be settled' using errcode = 'P0001'; end if;
  if p_customer_charge > v_reservation.amount then raise exception 'charge exceeds reservation' using errcode = '22023'; end if;
  if p_customer_charge > v_account.token_balance then raise exception 'insufficient settled AI credits' using errcode = 'P0001'; end if;
  insert into tongs.ai_credit_ledger (request_id, user_id, delta, reason, provider_request_id)
    values (p_settlement_id, p_user_id, -p_customer_charge,
      coalesce(nullif(btrim(p_reason), ''), 'reservation_settlement'), p_provider_request_id);
  update tongs.ai_credits set token_balance = token_balance - p_customer_charge, updated_at = now() where user_id = p_user_id;
  insert into tongs.ai_credit_reservation_events (
    reservation_id, user_id, event_type, amount, idempotency_key, reason, actor_id, metadata_json
  ) values (p_reservation_id, p_user_id, 'settled', p_customer_charge, p_settlement_id,
    coalesce(nullif(btrim(p_reason), ''), 'reservation_settlement'), p_user_id, coalesce(p_metadata_json, '{}'::jsonb))
  returning * into v_event;
  v_release := v_reservation.amount - p_customer_charge;
  if v_release > 0 then
    insert into tongs.ai_credit_reservation_events (
      reservation_id, user_id, event_type, amount, idempotency_key, reason, actor_id, metadata_json
    ) values (p_reservation_id, p_user_id, 'released', v_release,
      (substr(md5(p_settlement_id::text || ':release'),1,8)||'-'||substr(md5(p_settlement_id::text || ':release'),9,4)||'-4'||substr(md5(p_settlement_id::text || ':release'),14,3)||'-8'||substr(md5(p_settlement_id::text || ':release'),18,3)||'-'||substr(md5(p_settlement_id::text || ':release'),21,12))::uuid,
      'unused_reservation_released', p_user_id, '{}'::jsonb);
  end if;
  return jsonb_build_object('event', to_jsonb(v_event), 'replay', false,
    'released_amount', v_release, 'settled_balance', v_account.token_balance - p_customer_charge,
    'reserved_balance', tongs._ai_credit_active_holds(p_user_id),
    'available_balance', v_account.token_balance - p_customer_charge - tongs._ai_credit_active_holds(p_user_id));
end;
$$;


ALTER FUNCTION "tongs"."settle_ai_credit_reservation"("p_user_id" "uuid", "p_reservation_id" "uuid", "p_settlement_id" "uuid", "p_customer_charge" bigint, "p_provider_request_id" "text", "p_reason" "text", "p_metadata_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."settle_customer_hearth_research_before_synthesis"("p_reservation_id" "uuid", "p_failure_class" "text", "p_evidence_json" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare binding tongs.openai_text_funding_bindings%rowtype;
begin
  perform tongs._require_pricing_service_role();
  select * into binding from tongs.openai_text_funding_bindings where reservation_id=p_reservation_id;
  if binding.reservation_id is null or binding.route_code<>'hearth.research_synthesis'
     or binding.cost_policy_revision_id<>'12000000-0000-4000-8000-000000000001'::uuid
  then raise exception 'customer Hearth research reservation required' using errcode='42501'; end if;
  return tongs.settle_openai_customer_failure_without_duplicate_expense(
    p_reservation_id,
    extensions.uuid_generate_v5(p_reservation_id,'customer-hearth-research-relief:'||btrim(p_failure_class)),
    'customer-hearth-research:'||p_reservation_id::text||':'||btrim(p_failure_class),
    btrim(p_failure_class),
    coalesce(p_evidence_json,'{}')||jsonb_build_object('customer_charge_micros',0)
  );
end $$;


ALTER FUNCTION "tongs"."settle_customer_hearth_research_before_synthesis"("p_reservation_id" "uuid", "p_failure_class" "text", "p_evidence_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."settle_hearth_chat_test_operation"("p_reservation_id" "uuid", "p_settlement_id" "uuid", "p_settlement_key" "text", "p_outcome" "text", "p_failure_class" "text", "p_evidence_json" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare v_res tongs.test_funding_reservations%rowtype; v_existing tongs.test_paid_execution_settlements%rowtype; v_seq integer; v_charge bigint; v_payload jsonb;
begin
  perform tongs._require_pricing_service_role(); perform pg_advisory_xact_lock(hashtextextended('test-settlement:'||p_reservation_id::text,0));
  select * into v_existing from tongs.test_paid_execution_settlements where reservation_id=p_reservation_id;
  if found then return jsonb_build_object('settlement_id',v_existing.id,'customer_charge_micros',v_existing.customer_charge_micros,'replay',true,'state',case when v_existing.outcome='success' then 'settled' else 'released' end); end if;
  select * into v_res from tongs.test_funding_reservations where id=p_reservation_id for update;
  if not found or tongs._test_reservation_state(p_reservation_id)<>'attempt_started' or p_outcome not in ('success','nonbillable_failure') then raise exception 'invalid Test settlement' using errcode='P0001'; end if;
  if p_outcome='success' and not exists(select 1 from tongs.test_hearth_chat_paid_results where reservation_id=p_reservation_id) then raise exception 'canonical Test result required' using errcode='P0001'; end if;
  v_charge:=case when p_outcome='success' then 20000 else 0 end;
  insert into tongs.test_paid_execution_settlements(id,reservation_id,settlement_key,outcome,failure_class,customer_charge_micros,evidence_json)
  values(p_settlement_id,p_reservation_id,btrim(p_settlement_key),p_outcome,case when p_outcome='success' then null else coalesce(nullif(btrim(p_failure_class),''),'provider_failure') end,v_charge,coalesce(p_evidence_json,'{}'::jsonb));
  if p_outcome='success' then
    v_payload:=jsonb_build_object('reservation_id',p_reservation_id,'operation_id',v_res.operation_id,'recognized_test_revenue_micros',20000,'credit_units_consumed',2,'simulated',true);
    perform tongs._create_accounting_event(p_settlement_id,'test-deposit-consumption:'||v_res.operation_id,'test_customer_deposit_consumed','test','simulated_forge_operation',v_res.operation_id,'USD',v_res.user_id,null,null,v_payload,now());
    insert into tongs.test_customer_deposit_consumptions(id,reservation_id,deposit_id,user_id,operation_id,recognized_test_revenue_micros,credit_units_consumed,journal_event_id)
    values(p_settlement_id,p_reservation_id,v_res.deposit_id,v_res.user_id,v_res.operation_id,20000,2,p_settlement_id);
    insert into tongs.accounting_journal_entries(event_id,line_number,account_code,user_id,deposit_id,currency,amount_micros) values
      (p_settlement_id,1,'test_customer_prepaid_balance',v_res.user_id,v_res.deposit_id,'USD',20000),
      (p_settlement_id,2,'test_ai_consumption_revenue',v_res.user_id,v_res.deposit_id,'USD',-20000);
    insert into tongs.accounting_journal_entries(event_id,line_number,account_code,user_id,deposit_id,unit_kind,quantity_delta)
      values(p_settlement_id,3,'test_customer_credits',v_res.user_id,v_res.deposit_id,'forge_credit',-2);
    perform tongs._assert_accounting_event_balanced(p_settlement_id);
  end if;
  select coalesce(max(sequence),0)+1 into v_seq from tongs.test_funding_reservation_events where reservation_id=p_reservation_id;
  insert into tongs.test_funding_reservation_events(id,reservation_id,sequence,event_type,event_key,evidence_json)
  values(gen_random_uuid(),p_reservation_id,v_seq,case when p_outcome='success' then 'settled' else 'released' end,'test-settlement:'||p_settlement_id,coalesce(p_evidence_json,'{}'::jsonb));
  return jsonb_build_object('settlement_id',p_settlement_id,'customer_charge_micros',v_charge,'replay',false,'state',case when p_outcome='success' then 'settled' else 'released' end);
end $$;


ALTER FUNCTION "tongs"."settle_hearth_chat_test_operation"("p_reservation_id" "uuid", "p_settlement_id" "uuid", "p_settlement_key" "text", "p_outcome" "text", "p_failure_class" "text", "p_evidence_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."settle_openai_customer_failure_without_duplicate_expense"("p_reservation_id" "uuid", "p_relief_id" "uuid", "p_event_key" "text", "p_failure_class" "text", "p_evidence_json" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  state text;
  relief jsonb;
  released jsonb;
  original_customer_charge_micros bigint:=0;
begin
  perform tongs._require_pricing_service_role();
  if p_relief_id is null
     or length(btrim(coalesce(p_event_key,'')))<8
     or nullif(btrim(coalesce(p_failure_class,'')),'') is null
     or jsonb_typeof(coalesce(p_evidence_json,'null'::jsonb))<>'object' then
    raise exception 'invalid OpenAI customer failure settlement' using errcode='22023';
  end if;
  if not exists(
    select 1
    from tongs.openai_text_funding_bindings
    where reservation_id=p_reservation_id
  ) then
    raise exception 'OpenAI funding binding required' using errcode='P0002';
  end if;

  state:=tongs._funding_reservation_state(p_reservation_id);
  if state='submission_unknown' then
    raise exception 'ambiguous submission reservation requires reconciliation' using errcode='P0001';
  elsif state='settled' then
    -- The immutable generic paid result is written only after route validation
    -- and canonical domain persistence. Match it back to the exact immutable
    -- funding binding so an unrelated result can never suppress valid relief.
    if exists(
      select 1
      from tongs.openai_text_persisted_results result
      join tongs.openai_text_funding_bindings binding
        on binding.reservation_id=result.reservation_id
       and binding.operation_id=result.operation_id
       and binding.route_code=result.route_code
      where result.reservation_id=p_reservation_id
    ) then
      select coalesce(event.customer_charge_micros,0)
      into original_customer_charge_micros
      from tongs.funding_reservation_events event
      where event.reservation_id=p_reservation_id
        and event.event_type='settled'
      order by event.sequence desc
      limit 1;

      return jsonb_build_object(
        'reservation_id',p_reservation_id,
        'state','settled_result_preserved',
        'replay',true,
        'customer_charge_micros',coalesce(original_customer_charge_micros,0),
        'customer_relief',null,
        'supplier_expense_created',false,
        'reason','canonical_result_already_persisted'
      );
    end if;

    -- Preserve the existing customer-protection path for a genuinely failed
    -- paid operation that settled without delivering a canonical result.
    relief:=tongs.relieve_failed_customer_operation(
      p_relief_id,
      p_reservation_id,
      btrim(p_event_key)||':customer-relief',
      'Forge/provider failure customer protection',
      coalesce(p_evidence_json,'{}'::jsonb)
    );
    return jsonb_build_object(
      'reservation_id',p_reservation_id,
      'state','relieved',
      'customer_charge_micros',0,
      'customer_relief',relief,
      'supplier_expense_created',false
    );
  elsif state='released' then
    return jsonb_build_object(
      'reservation_id',p_reservation_id,
      'state','released',
      'replay',true,
      'customer_charge_micros',0,
      'supplier_expense_created',false
    );
  end if;

  released:=tongs.release_operation(
    p_reservation_id,
    btrim(p_event_key)||':zero-charge-release',
    'Confirmed '||btrim(p_failure_class)||'; customer charge zero',
    coalesce(p_evidence_json,'{}'::jsonb)
  );
  return released||jsonb_build_object(
    'customer_charge_micros',0,
    'supplier_expense_created',false
  );
end
$$;


ALTER FUNCTION "tongs"."settle_openai_customer_failure_without_duplicate_expense"("p_reservation_id" "uuid", "p_relief_id" "uuid", "p_event_key" "text", "p_failure_class" "text", "p_evidence_json" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."settle_openai_customer_failure_without_duplicate_expense"("p_reservation_id" "uuid", "p_relief_id" "uuid", "p_event_key" "text", "p_failure_class" "text", "p_evidence_json" "jsonb") IS 'Releases or relieves genuine failed paid operations without duplicating supplier expense; settled operations with an immutable canonical result are preserved and cannot receive automatic failure relief.';



CREATE OR REPLACE FUNCTION "tongs"."settle_openai_text_test_certification_operation"("p_reservation_id" "uuid", "p_settlement_id" "uuid", "p_settlement_key" "text", "p_outcome" "text", "p_failure_class" "text", "p_actual_fulfillment_cost_micros" bigint, "p_evidence_json" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare v_res tongs.openai_text_test_certification_reservations%rowtype; v_op tongs.openai_text_test_certification_operations%rowtype; v_existing tongs.openai_text_test_certification_settlements%rowtype; v_charge bigint; v_units bigint; v_event uuid;
begin perform tongs._require_pricing_service_role(); perform pg_advisory_xact_lock(hashtextextended('openai-text-test-settlement:'||p_reservation_id::text,0));
  select * into v_existing from tongs.openai_text_test_certification_settlements where reservation_id=p_reservation_id; if found then return jsonb_build_object('settlement_id',v_existing.id,'customer_charge_micros',v_existing.customer_charge_micros,'state',case when v_existing.outcome='success' then 'settled' else 'released' end,'replay',true); end if;
  select * into v_res from tongs.openai_text_test_certification_reservations where id=p_reservation_id; select * into v_op from tongs.openai_text_test_certification_operations where id=v_res.operation_record_id;
  if tongs._openai_text_test_certification_reservation_state(p_reservation_id)<>'attempt_started' or p_outcome not in ('success','nonbillable_failure') or (p_outcome='success' and v_op.scenario<>'success') or (p_outcome='success' and not exists(select 1 from tongs.openai_text_test_certification_results where reservation_id=p_reservation_id)) then raise exception 'invalid Test settlement' using errcode='P0001'; end if;
  v_charge:=case when p_outcome='success' then v_op.normal_maximum_charge_micros else 0 end; v_units:=case when p_outcome='success' then v_op.reserved_credit_units else 0 end;
  insert into tongs.openai_text_test_certification_settlements(id,reservation_id,settlement_key,outcome,failure_class,customer_charge_micros,customer_credit_units,evidence_json)
  values(p_settlement_id,p_reservation_id,p_settlement_key,p_outcome,case when p_outcome='success' then null else coalesce(nullif(p_failure_class,''),'forge_failure') end,v_charge,v_units,coalesce(p_evidence_json,'{}')||jsonb_build_object('execution_kind','simulated_test','live_revenue',false));
  if p_outcome='success' then
    v_event:=p_settlement_id; perform tongs._create_accounting_event(v_event,'openai-text-test-consumption:'||v_op.operation_id,'test_customer_deposit_consumed','test','simulated_forge_operation',v_op.operation_id,'USD',v_res.user_id,null,null,jsonb_build_object('route_code',v_op.route_code,'simulated',true,'recognized_test_revenue_micros',v_charge,'credit_units_consumed',v_units),now());
    insert into tongs.openai_text_test_certification_consumptions(id,reservation_id,deposit_id,user_id,operation_id,recognized_test_revenue_micros,credit_units_consumed,journal_event_id) values(v_event,p_reservation_id,v_res.deposit_id,v_res.user_id,v_op.operation_id,v_charge,v_units,v_event);
    insert into tongs.accounting_journal_entries(event_id,line_number,account_code,user_id,deposit_id,currency,amount_micros) values(v_event,1,'test_customer_prepaid_balance',v_res.user_id,v_res.deposit_id,'USD',v_charge),(v_event,2,'test_ai_consumption_revenue',v_res.user_id,v_res.deposit_id,'USD',-v_charge);
    insert into tongs.accounting_journal_entries(event_id,line_number,account_code,user_id,deposit_id,unit_kind,quantity_delta) values(v_event,3,'test_customer_credits',v_res.user_id,v_res.deposit_id,'forge_credit',-v_units); perform tongs._assert_accounting_event_balanced(v_event);
  end if;
  insert into tongs.openai_text_test_certification_reservation_events(id,reservation_id,sequence,event_type,event_key,evidence_json)
  values(gen_random_uuid(),p_reservation_id,3,case when p_outcome='success' then 'settled' else 'released' end,'openai-text-test-settlement:'||p_settlement_id,coalesce(p_evidence_json,'{}'));
  return jsonb_build_object('settlement_id',p_settlement_id,'customer_charge_micros',v_charge,'state',case when p_outcome='success' then 'settled' else 'released' end,'replay',false); end $$;


ALTER FUNCTION "tongs"."settle_openai_text_test_certification_operation"("p_reservation_id" "uuid", "p_settlement_id" "uuid", "p_settlement_key" "text", "p_outcome" "text", "p_failure_class" "text", "p_actual_fulfillment_cost_micros" bigint, "p_evidence_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."settle_operation"("p_reservation_id" "uuid", "p_settlement_id" "uuid", "p_settlement_key" "text", "p_outcome" "text", "p_failure_class" "text", "p_actual_fulfillment_cost_micros" bigint, "p_evidence_json" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare v_res tongs.funding_reservations%rowtype; v_quote tongs.customer_spending_quotes%rowtype;
  v_state text; v_sequence integer; v_relief jsonb; v_expense jsonb; v_expense_id uuid:=gen_random_uuid();
begin
  perform tongs._require_pricing_service_role();
  if p_outcome='success' then
    return tongs._settle_operation_before_zero_failure_policy(p_reservation_id,p_settlement_id,p_settlement_key,
      p_outcome,p_failure_class,p_actual_fulfillment_cost_micros,p_evidence_json);
  end if;
  if p_outcome not in ('billable_failure','nonbillable_failure') or p_actual_fulfillment_cost_micros<0 then
    raise exception 'invalid operation settlement' using errcode='22023'; end if;
  perform pg_advisory_xact_lock(hashtextextended('provider-attempt:'||p_reservation_id::text,0));
  select * into v_res from tongs.funding_reservations where id=p_reservation_id for update;
  if not found then raise exception 'funding reservation not found' using errcode='P0002'; end if;
  select * into v_quote from tongs.customer_spending_quotes where id=v_res.quote_id;
  if p_actual_fulfillment_cost_micros>0 then
    v_expense:=tongs.record_supplier_expense(v_expense_id,p_reservation_id,btrim(p_settlement_key)||':supplier-expense',
      coalesce(nullif(p_evidence_json->>'provider',''),'unknown_supplier'),'failure_fulfillment',
      p_evidence_json->>'provider_reference',v_res.currency,p_actual_fulfillment_cost_micros,
      case when coalesce((p_evidence_json->>'authoritative')::boolean,false) then 'confirmed' else 'estimated' end,
      case when coalesce((p_evidence_json->>'obligation_resolved')::boolean,false) then 'closed' else 'unresolved' end,
      coalesce(p_evidence_json,'{}'::jsonb));
  else
    v_expense:=tongs.record_supplier_expense(v_expense_id,p_reservation_id,btrim(p_settlement_key)||':supplier-expense',
      coalesce(nullif(p_evidence_json->>'provider',''),'unknown_supplier'),'failure_fulfillment',
      p_evidence_json->>'provider_reference',v_res.currency,null,'unresolved','unresolved',coalesce(p_evidence_json,'{}'::jsonb));
  end if;
  v_state:=tongs._funding_reservation_state(p_reservation_id);
  if v_state='settled' then
    v_relief:=tongs.relieve_failed_customer_operation(gen_random_uuid(),p_reservation_id,
      btrim(p_settlement_key)||':customer-relief','Forge/provider failure customer protection',p_evidence_json);
  elsif v_state<>'released' then
    select coalesce(max(sequence),0)+1 into v_sequence from tongs.funding_reservation_events where reservation_id=p_reservation_id;
    insert into tongs.funding_reservation_events(id,reservation_id,sequence,event_type,event_key,
      customer_charge_micros,credit_units,wholesale_spend_micros,failure_class,evidence_json)
    values(gen_random_uuid(),p_reservation_id,v_sequence,'released',btrim(p_settlement_key)||':zero-charge-release',
      0,0,p_actual_fulfillment_cost_micros,coalesce(nullif(btrim(p_failure_class),''),'unknown_fault'),
      coalesce(p_evidence_json,'{}'::jsonb)||jsonb_build_object('reason','confirmed failure; customer charge zero'));
  end if;
  return jsonb_build_object('reservation_id',p_reservation_id,'state',case when v_state='settled' then 'relieved' else 'released' end,
    'replay',coalesce((v_expense->>'replay')::boolean,false),'customer_charge_micros',0,'credit_units',0,
    'revenue_reversal',v_relief,'supplier_expense',v_expense,'supplier_obligation_preserved',true,
    'automatic_resubmission',false);
end $$;


ALTER FUNCTION "tongs"."settle_operation"("p_reservation_id" "uuid", "p_settlement_id" "uuid", "p_settlement_key" "text", "p_outcome" "text", "p_failure_class" "text", "p_actual_fulfillment_cost_micros" bigint, "p_evidence_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."settle_owner_hearth_operation"("p_reservation_id" "uuid", "p_settlement_id" "uuid", "p_settlement_key" "text", "p_outcome" "text", "p_failure_class" "text", "p_actual_fulfillment_cost_micros" bigint, "p_evidence_json" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare op tongs.owner_hearth_operation_authorizations%rowtype; res tongs.funding_reservations%rowtype;
 existing tongs.funding_reservation_events%rowtype; nextseq integer; consumption jsonb;
begin
 perform tongs._require_pricing_service_role();
 if p_settlement_id is null or length(btrim(coalesce(p_settlement_key,'')))<8
   or p_outcome not in ('success','billable_failure','nonbillable_failure') or p_actual_fulfillment_cost_micros<0
   or jsonb_typeof(coalesce(p_evidence_json,'null'::jsonb))<>'object' then
  raise exception 'invalid owner Hearth settlement' using errcode='22023'; end if;
 perform pg_advisory_xact_lock(hashtextextended('owner-hearth-settle:'||p_reservation_id::text,0));
 select * into op from tongs.owner_hearth_operation_authorizations where reservation_id=p_reservation_id;
 select * into res from tongs.funding_reservations where id=p_reservation_id for update;
 if op.id is null or res.id is null or res.funding_source_type<>'owner_budget'
   or res.funding_source_id<>(select a.budget_id from tongs.owner_hearth_authorizations a where a.id=op.authorization_id) then
  raise exception 'exact owner Hearth reservation required' using errcode='42501'; end if;
 select * into existing from tongs.funding_reservation_events where event_key=btrim(p_settlement_key);
 if found then return jsonb_build_object('reservation_id',p_reservation_id,'state','settled','replay',true,
  'owner_expense_micros',existing.wholesale_spend_micros,'customer_charge_micros',0,'customer_revenue_micros',0,'margin','not_applicable'); end if;
 if tongs._funding_reservation_state(p_reservation_id) in ('settled','released') then raise exception 'owner Hearth reservation is terminal' using errcode='P0001'; end if;
 if p_actual_fulfillment_cost_micros>res.reserved_wholesale_spend_micros then
  insert into tongs.pricing_discrepancies(id,reservation_id,discrepancy_key,discrepancy_type,quoted_ceiling_micros,observed_amount_micros,evidence_json)
  values(gen_random_uuid(),res.id,btrim(p_settlement_key)||':owner-cost-overrun','wholesale_ceiling_overrun',res.reserved_wholesale_spend_micros,
   p_actual_fulfillment_cost_micros,coalesce(p_evidence_json,'{}'::jsonb)) on conflict(discrepancy_key) do nothing;
 end if;
 if p_actual_fulfillment_cost_micros>0 then
  consumption:=tongs.consume_owner_operating_budget(p_settlement_id,res.funding_source_id,res.id,
   'owner-hearth-settlement:'||res.id::text,res.operation_id,p_actual_fulfillment_cost_micros,now(),
   coalesce(p_evidence_json,'{}'::jsonb)||jsonb_build_object('customer_revenue_micros',0,'operation_outcome',p_outcome));
 end if;
 select coalesce(max(sequence),0)+1 into nextseq from tongs.funding_reservation_events where reservation_id=res.id;
 insert into tongs.funding_reservation_events(id,reservation_id,sequence,event_type,event_key,customer_charge_micros,credit_units,
  wholesale_spend_micros,failure_class,evidence_json)
 values(gen_random_uuid(),res.id,nextseq,'settled',btrim(p_settlement_key),0,0,p_actual_fulfillment_cost_micros,
  nullif(btrim(coalesce(p_failure_class,'')),''),coalesce(p_evidence_json,'{}'::jsonb)||jsonb_build_object(
   'operation_outcome',p_outcome,'customer_revenue_micros',0,'supplier_cost_status',
   case when coalesce((p_evidence_json->>'authoritative')::boolean,false) then 'authoritative' else 'estimated' end));
 return jsonb_build_object('reservation_id',res.id,'state','settled','replay',false,'owner_expense_micros',p_actual_fulfillment_cost_micros,
  'customer_charge_micros',0,'customer_revenue_micros',0,'margin','not_applicable','cost_authoritative',
  coalesce((p_evidence_json->>'authoritative')::boolean,false));
end $$;


ALTER FUNCTION "tongs"."settle_owner_hearth_operation"("p_reservation_id" "uuid", "p_settlement_id" "uuid", "p_settlement_key" "text", "p_outcome" "text", "p_failure_class" "text", "p_actual_fulfillment_cost_micros" bigint, "p_evidence_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."settle_owner_hearth_research_before_synthesis"("p_reservation_id" "uuid", "p_failure_class" "text", "p_evidence_json" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare amount bigint; sid uuid:=extensions.uuid_generate_v5(p_reservation_id,'pre-synthesis-settlement');
begin
 perform tongs._require_pricing_service_role();
 select coalesce(sum(amount_micros),0) into amount from tongs.owner_hearth_research_component_expenses where reservation_id=p_reservation_id;
 return tongs.settle_owner_hearth_research_operation(p_reservation_id,sid,'owner-research:'||p_reservation_id::text||':pre-synthesis','nonbillable_failure',p_failure_class,
  greatest(0,amount-(select coalesce(sum(amount_micros),0) from tongs.owner_hearth_research_component_expenses where reservation_id=p_reservation_id and component in('search','retrieval'))),
  coalesce(p_evidence_json,'{}')||jsonb_build_object('openai_submitted',false,'customer_charge_micros',0));
end $$;


ALTER FUNCTION "tongs"."settle_owner_hearth_research_before_synthesis"("p_reservation_id" "uuid", "p_failure_class" "text", "p_evidence_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."settle_owner_hearth_research_operation"("p_reservation_id" "uuid", "p_settlement_id" "uuid", "p_settlement_key" "text", "p_outcome" "text", "p_failure_class" "text", "p_actual_fulfillment_cost_micros" bigint, "p_evidence_json" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare o tongs.owner_hearth_research_operations%rowtype; r tongs.funding_reservations%rowtype; stage_cost bigint; total bigint; seq int; existing tongs.funding_reservation_events%rowtype;
begin
 perform tongs._require_pricing_service_role(); perform pg_advisory_xact_lock(hashtextextended('owner-research-settle:'||p_reservation_id::text,0));
 select * into o from tongs.owner_hearth_research_operations where reservation_id=p_reservation_id; select * into r from tongs.funding_reservations where id=p_reservation_id for update;
 select * into existing from tongs.funding_reservation_events where event_key=btrim(p_settlement_key);
 if found then return jsonb_build_object('reservation_id',p_reservation_id,'state','settled','replay',true,'owner_expense_micros',existing.wholesale_spend_micros,'customer_charge_micros',0); end if;
 insert into tongs.owner_hearth_research_component_expenses values(gen_random_uuid(),p_reservation_id,'synthesis:'||p_reservation_id::text,'synthesis',
  greatest(0,p_actual_fulfillment_cost_micros-1456),'estimated','OpenAI',coalesce(p_evidence_json,'{}')||jsonb_build_object('customer_charge_micros',0),now())
  on conflict(expense_key) do nothing;
 select coalesce(sum(amount_micros),0) into stage_cost from tongs.owner_hearth_research_component_expenses where reservation_id=p_reservation_id and component in('search','retrieval','continuing_storage');
 total:=p_actual_fulfillment_cost_micros+stage_cost;
 if o.id is null or total>r.reserved_wholesale_spend_micros then raise exception 'research settlement exceeds accepted owner commitment' using errcode='42501'; end if;
 if total>0 then perform tongs.consume_owner_operating_budget(p_settlement_id,r.funding_source_id,r.id,'owner-research:'||r.id::text,r.operation_id,total,now(),
  coalesce(p_evidence_json,'{}')||jsonb_build_object('customer_charge_micros',0,'component_expenses_micros',stage_cost)); end if;
 select coalesce(max(sequence),0)+1 into seq from tongs.funding_reservation_events where reservation_id=r.id;
 insert into tongs.funding_reservation_events(id,reservation_id,sequence,event_type,event_key,customer_charge_micros,credit_units,wholesale_spend_micros,failure_class,evidence_json)
 values(gen_random_uuid(),r.id,seq,'settled',btrim(p_settlement_key),0,0,total,nullif(btrim(coalesce(p_failure_class,'')),''),
  coalesce(p_evidence_json,'{}')||jsonb_build_object('customer_revenue_micros',0,'supplier_expenses_retained',true));
 return jsonb_build_object('reservation_id',r.id,'state','settled','replay',false,'owner_expense_micros',total,'customer_charge_micros',0,'customer_revenue_micros',0);
end $$;


ALTER FUNCTION "tongs"."settle_owner_hearth_research_operation"("p_reservation_id" "uuid", "p_settlement_id" "uuid", "p_settlement_key" "text", "p_outcome" "text", "p_failure_class" "text", "p_actual_fulfillment_cost_micros" bigint, "p_evidence_json" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."settle_owner_operation"("p_reservation_id" "uuid", "p_settlement_id" "uuid", "p_settlement_key" "text", "p_outcome" "text", "p_failure_class" "text", "p_actual_fulfillment_cost_micros" bigint, "p_evidence_json" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_control tongs.paid_execution_control_revisions%rowtype;
  v_reservation tongs.funding_reservations%rowtype;
  v_quote tongs.customer_spending_quotes%rowtype;
  v_existing tongs.funding_reservation_events%rowtype;
  v_expense bigint;
  v_sequence integer;
  v_consumption jsonb;
begin
  perform tongs._require_pricing_service_role();
  select * into v_control from tongs._current_paid_execution_control();
  if not v_control.owner_budget_spending_enabled or not v_control.provider_execution_enabled then
    raise exception 'owner-budget provider execution is not activated' using errcode = '42501';
  end if;
  if p_settlement_id is null or length(btrim(coalesce(p_settlement_key,''))) < 8
     or p_outcome not in ('success','billable_failure','nonbillable_failure')
     or p_actual_fulfillment_cost_micros < 0
     or jsonb_typeof(coalesce(p_evidence_json,'null'::jsonb)) <> 'object' then
    raise exception 'invalid owner operation settlement' using errcode = '22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('provider-attempt:'||p_reservation_id::text,0));
  select * into v_reservation from tongs.funding_reservations where id=p_reservation_id for update;
  if not found or v_reservation.funding_source_type <> 'owner_budget' then
    raise exception 'owner-funded reservation not found' using errcode = 'P0002';
  end if;
  select * into v_quote from tongs.customer_spending_quotes where id=v_reservation.quote_id;
  select * into v_existing from tongs.funding_reservation_events where event_key=btrim(p_settlement_key);
  if found then return jsonb_build_object('reservation_id',p_reservation_id,'state','settled','replay',true,
    'owner_expense_micros',v_existing.wholesale_spend_micros,'customer_revenue_micros',0,'margin','not_applicable'); end if;
  if tongs._funding_reservation_state(p_reservation_id) in ('settled','released') then
    raise exception 'owner-funded reservation is terminal' using errcode = 'P0001';
  end if;
  if p_outcome='billable_failure' and not exists (
    select 1 from jsonb_array_elements_text(v_quote.billable_failure_classes) value
    where value=btrim(coalesce(p_failure_class,''))
  ) then raise exception 'failure class is not billable under accepted quote' using errcode = 'P0001'; end if;
  v_expense := case when p_outcome='nonbillable_failure' then 0 else p_actual_fulfillment_cost_micros end;
  if v_expense > v_reservation.reserved_wholesale_spend_micros then
    insert into tongs.pricing_discrepancies(
      id,reservation_id,discrepancy_key,discrepancy_type,quoted_ceiling_micros,observed_amount_micros,evidence_json
    ) values (gen_random_uuid(),p_reservation_id,btrim(p_settlement_key)||':owner-cost-overrun',
      'wholesale_ceiling_overrun',v_reservation.reserved_wholesale_spend_micros,v_expense,
      coalesce(p_evidence_json,'{}'::jsonb)) on conflict(discrepancy_key) do nothing;
  end if;
  if v_expense > 0 then
    v_consumption := tongs.consume_owner_operating_budget(
      p_settlement_id,v_reservation.funding_source_id,p_reservation_id,
      'owner-reservation-settlement:'||p_reservation_id::text,v_reservation.operation_id,
      v_expense,now(),coalesce(p_evidence_json,'{}'::jsonb)
    );
  end if;
  select coalesce(max(sequence),0)+1 into v_sequence from tongs.funding_reservation_events
    where reservation_id=p_reservation_id;
  insert into tongs.funding_reservation_events(
    id,reservation_id,sequence,event_type,event_key,customer_charge_micros,credit_units,
    wholesale_spend_micros,failure_class,evidence_json
  ) values (gen_random_uuid(),p_reservation_id,v_sequence,'settled',btrim(p_settlement_key),0,0,v_expense,
    nullif(btrim(coalesce(p_failure_class,'')),''),coalesce(p_evidence_json,'{}'::jsonb));
  return jsonb_build_object('reservation_id',p_reservation_id,'state','settled','replay',false,
    'owner_expense_micros',v_expense,'customer_debit_micros',0,'customer_revenue_micros',0,
    'margin','not_applicable','accounting_consumption',v_consumption);
end;
$$;


ALTER FUNCTION "tongs"."settle_owner_operation"("p_reservation_id" "uuid", "p_settlement_id" "uuid", "p_settlement_key" "text", "p_outcome" "text", "p_failure_class" "text", "p_actual_fulfillment_cost_micros" bigint, "p_evidence_json" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."settle_owner_operation"("p_reservation_id" "uuid", "p_settlement_id" "uuid", "p_settlement_key" "text", "p_outcome" "text", "p_failure_class" "text", "p_actual_fulfillment_cost_micros" bigint, "p_evidence_json" "jsonb") IS 'Separate owner-funded settlement path; production remains disabled until an approved control revision and capped active budget exist.';



CREATE OR REPLACE FUNCTION "tongs"."settle_paid_media_operation"("p_paid_media_operation_id" "uuid", "p_operation_fingerprint" "text", "p_settlement_id" "uuid", "p_overage_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare v_op tongs.paid_media_operations%rowtype; v_attempt tongs.paid_media_provider_attempts%rowtype;
  v_num numeric:=0; v_den numeric:=1; v_row record; v_gcd numeric; v_calculated bigint; v_settled bigint; v_overage bigint; v_financial jsonb; v_receipt jsonb;
begin
  select * into v_op from tongs.paid_media_operations where id=p_paid_media_operation_id for update;
  if not found or v_op.operation_fingerprint<>p_operation_fingerprint then raise exception 'paid operation not found or mismatched' using errcode='P0002'; end if;
  if v_op.state='settled' then return jsonb_build_object('operation',to_jsonb(v_op),'receipt',v_op.terminal_receipt_json,'replay',true); end if;
  if v_op.state<>'delivered' then raise exception 'canonical delivery is required before settlement' using errcode='P0001'; end if;
  select * into v_attempt from tongs.paid_media_provider_attempts where id=v_op.active_attempt_id;
  for v_row in select expense_numerator,expense_denominator from tongs.paid_media_actual_usage_components where provider_attempt_id=v_attempt.id loop
    v_num:=v_num*v_row.expense_denominator+v_row.expense_numerator*v_den; v_den:=v_den*v_row.expense_denominator;
    v_gcd:=tongs._ai_pricing_gcd(v_num,v_den); v_num:=v_num/v_gcd; v_den:=v_den/v_gcd;
  end loop;
  v_calculated:=ceil(v_num*21/(v_den*125))::bigint; v_settled:=least(v_calculated,v_op.authorized_customer_ceiling); v_overage:=greatest(v_calculated-v_settled,0);
  v_financial:=tongs.settle_ai_credit_reservation(v_op.user_id,v_op.reservation_id,p_settlement_id,v_settled,v_attempt.provider_request_id,
    'paid_media_generation',jsonb_build_object('paid_media_operation_id',v_op.id,'provider_expense_numerator',v_num,'provider_expense_denominator',v_den));
  if v_overage>0 then insert into tongs.paid_media_pricing_overages values(p_overage_id,v_op.id,v_op.user_id,v_overage,'customer_authorization_ceiling',v_num,v_den,'{}',now()); end if;
  v_receipt:=jsonb_build_object('operation_id',v_op.operation_id,'operation_fingerprint',v_op.operation_fingerprint,'user_id',v_op.user_id,
    'workspace_id',v_op.workspace_id,'workpiece_id',v_op.workpiece_id,'tool',v_op.originating_tool,'quote_id',v_op.quote_id,
    'authorization_policy_revision_id',v_op.authorization_policy_revision_id,'pricing_policy_revision_id',v_op.pricing_policy_revision_id,
    'authorized_customer_ceiling',v_op.authorized_customer_ceiling,'reservation_id',v_op.reservation_id,'provider_attempt_id',v_attempt.id,
    'provider_request_id',v_attempt.provider_request_id,'provider_response_id',v_attempt.provider_response_id,
    'actual_usage',(select jsonb_agg(to_jsonb(u) order by u.component_kind) from tongs.paid_media_actual_usage_components u where u.provider_attempt_id=v_attempt.id),
    'provider_expense_numerator',v_num,'provider_expense_denominator',v_den,'calculated_customer_charge',v_calculated,
    'settled_customer_charge',v_settled,'forge_pricing_overage',v_overage,'released_reservation',v_op.authorized_customer_ceiling-v_settled,
    'delivery_evidence',(select evidence_json from tongs.paid_media_operation_events where paid_media_operation_id=v_op.id and event_type='canonical_delivery_verified'),
    'state','settled','contract_version',v_op.contract_version,'settled_at',now());
  update tongs.paid_media_operations set state='settled',terminal_receipt_json=v_receipt,updated_at=now() where id=v_op.id returning * into v_op;
  insert into tongs.paid_media_operation_events values(gen_random_uuid(),v_op.id,v_op.user_id,'settled',
    (select coalesce(max(event_ordinal),0)+1 from tongs.paid_media_operation_events where paid_media_operation_id=v_op.id),v_receipt,v_op.actor_id,now());
  return jsonb_build_object('operation',to_jsonb(v_op),'receipt',v_receipt,'financial',v_financial,'replay',false);
end $$;


ALTER FUNCTION "tongs"."settle_paid_media_operation"("p_paid_media_operation_id" "uuid", "p_operation_fingerprint" "text", "p_settlement_id" "uuid", "p_overage_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."snapshot_quench_release_manifest"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_source_revision" bigint, "p_manifest_bytes" "bytea", "p_manifest_hash" "text", "p_parsed" "jsonb", "p_validation" "jsonb", "p_status" "text", "p_ready" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare f tongs.workpiece_files%rowtype; v_id uuid; v_hash text:=lower(p_manifest_hash);
begin
 if current_user not in('postgres','service_role','supabase_admin') then return jsonb_build_object('disposition','denied','code','service_role_required'); end if;
 select * into f from tongs.workpiece_files where workpiece_id=p_workpiece_id and path='hammer/release-packet/manifest.v1.json' for update;
 if not found then return jsonb_build_object('disposition','blocked','code','manifest_not_found'); end if;
 if f.revision<>p_source_revision or lower(f.hash_value)<>v_hash or encode(extensions.digest(p_manifest_bytes,'sha256'),'hex')<>v_hash then return jsonb_build_object('disposition','blocked','code','manifest_hash_mismatch'); end if;
 if p_parsed->>'packet_kind'<>'quench_release_packet' or (p_parsed->>'workpiece_id')::uuid<>p_workpiece_id or coalesce((p_parsed->>'workspace_id')::uuid,p_workspace_id)<>p_workspace_id then return jsonb_build_object('disposition','blocked','code','manifest_identity_mismatch'); end if;
 insert into tongs.quench_release_manifest_snapshots(workspace_id,workpiece_id,source_file_path,source_file_revision,source_storage_bucket,source_storage_key,manifest_version,manifest_content_hash,manifest_bytes,parsed_manifest_json,validation_contract_version,validation_result_json,canonical_readiness_status,ready_for_quench)
 values(p_workspace_id,p_workpiece_id,f.path,f.revision,f.storage_bucket,f.storage_key,1,v_hash,p_manifest_bytes,p_parsed,'forge.hammer-quench-manifest-validation.v1',p_validation,p_status,p_ready)
 on conflict(workpiece_id,source_file_path,source_file_revision,manifest_content_hash) do nothing;
 select id into v_id from tongs.quench_release_manifest_snapshots where workpiece_id=p_workpiece_id and source_file_path=f.path and source_file_revision=f.revision and manifest_content_hash=v_hash;
 return jsonb_build_object('disposition','verified','manifest_snapshot_id',v_id,'manifest_content_hash',v_hash); exception when others then return jsonb_build_object('disposition','blocked','code','manifest_invalid'); end $$;


ALTER FUNCTION "tongs"."snapshot_quench_release_manifest"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_source_revision" bigint, "p_manifest_bytes" "bytea", "p_manifest_hash" "text", "p_parsed" "jsonb", "p_validation" "jsonb", "p_status" "text", "p_ready" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."stage_owner_timeline_image_generation_result"("p_owner_cost_attempt_id" "uuid", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_operation_fingerprint" "text", "p_financial_environment" "text", "p_runtime_environment" "text", "p_provider_body_sha256" "text", "p_provider_request_id" "text", "p_provider_response_id" "text", "p_prompt_revision_id" "uuid", "p_prompt_content_hash" "text", "p_semantic_authority_hash" "text", "p_image_moment_id" "text", "p_outputs" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $_$
declare
  v_authority jsonb;
  v_operation_key text;
  v_prompt tongs.image_map_prompt_revisions%rowtype;
  v_existing tongs.hearth_timeline_image_generation_results%rowtype;
  v_result_id uuid:=extensions.uuid_generate_v5(
    '19670000-0000-4000-8000-000000000011'::uuid,p_owner_cost_attempt_id::text);
  v_item jsonb;
begin
  perform tongs._require_accounting_service_role();
  v_authority:=tongs._assert_owner_hearth_image_result_authority(
    p_owner_cost_attempt_id,'hearth.timeline_image_generation',p_user_id,
    p_workspace_id,p_workpiece_id,p_operation_fingerprint,p_financial_environment,
    p_runtime_environment,p_provider_request_id,'gpt-image-2-2026-04-21',
    'image_generation','gpt-image-2-2026-04-21:1536x1024:high:n2'
  );
  v_operation_key:=v_authority->>'operation_key';
  select * into v_prompt from tongs.image_map_prompt_revisions where id=p_prompt_revision_id;
  if lower(coalesce(p_provider_body_sha256,''))!~'^[0-9a-f]{64}$'
     or lower(coalesce(p_prompt_content_hash,''))!~'^[0-9a-f]{64}$'
     or lower(coalesce(p_semantic_authority_hash,''))!~'^[0-9a-f]{64}$'
     or nullif(btrim(coalesce(p_image_moment_id,'')),'') is null
     or v_prompt.id is null or v_prompt.workspace_id<>p_workspace_id
     or v_prompt.workpiece_id<>p_workpiece_id
     or v_prompt.image_moment_id<>btrim(p_image_moment_id)
     or v_prompt.content_hash<>lower(p_prompt_content_hash)
     or jsonb_typeof(coalesce(p_outputs,'null'::jsonb))<>'array'
     or jsonb_array_length(p_outputs)<>2
     or (select array_agg((value->>'child_ordinal')::integer order by (value->>'child_ordinal')::integer)
           from jsonb_array_elements(p_outputs))<>array[1,2]
     or exists(select 1 from jsonb_array_elements(p_outputs) output
       where output->>'mime_type'<>'image/png'
          or nullif(output->>'bytes_base64','') is null
          or nullif(output->>'staged_asset_id','') is null) then
    raise exception 'invalid owner Timeline Image result evidence' using errcode='22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    'owner-timeline-image-result:'||p_owner_cost_attempt_id::text,0));
  select * into v_existing from tongs.hearth_timeline_image_generation_results
    where owner_cost_attempt_id=p_owner_cost_attempt_id or operation_id=v_operation_key;
  if found then
    if v_existing.owner_cost_attempt_id is distinct from p_owner_cost_attempt_id
       or v_existing.operation_id<>v_operation_key
       or v_existing.request_fingerprint<>lower(p_operation_fingerprint)
       or v_existing.provider_body_sha256<>lower(p_provider_body_sha256)
       or v_existing.provider_request_id is distinct from btrim(p_provider_request_id)
       or v_existing.provider_response_id is distinct from nullif(btrim(coalesce(p_provider_response_id,'')),'')
       or v_existing.prompt_revision_id<>p_prompt_revision_id
       or v_existing.prompt_content_hash<>lower(p_prompt_content_hash)
       or v_existing.semantic_authority_hash<>lower(p_semantic_authority_hash)
       or v_existing.image_moment_id<>btrim(p_image_moment_id) then
      raise exception 'owner Timeline Image result replay conflict' using errcode='23505';
    end if;
    if (select count(*) from tongs.hearth_timeline_image_generation_outputs output
        where output.result_id=v_existing.id)<>2 then
      raise exception 'owner Timeline Image replay is incomplete' using errcode='23505';
    end if;
    if exists(
      select 1
      from jsonb_array_elements(p_outputs) item
      left join tongs.hearth_timeline_image_generation_outputs output
        on output.result_id=v_existing.id
       and output.child_ordinal=(item->>'child_ordinal')::integer
      where output.result_id is null
         or output.bytes_base64<>item->>'bytes_base64'
         or output.staged_asset_id<>(item->>'staged_asset_id')::uuid
         or output.content_hash<>encode(extensions.digest(
              decode(item->>'bytes_base64','base64'),'sha256'),'hex')
    ) then
      raise exception 'owner Timeline Image output replay conflict' using errcode='23505';
    end if;
    return to_jsonb(v_existing)||jsonb_build_object('replay',true,'authority','owner_cost_provider_attempt');
  end if;

  insert into tongs.hearth_timeline_image_generation_results(
    id,operation_id,reservation_id,owner_cost_attempt_id,user_id,workspace_id,workpiece_id,
    image_moment_id,request_fingerprint,provider_body_sha256,provider_request_id,
    provider_response_id,model,prompt_revision_id,prompt_content_hash,semantic_authority_hash,
    image_count,provider_attempt_count,supplier_cost_micros
  ) values(
    v_result_id,v_operation_key,null,p_owner_cost_attempt_id,p_user_id,p_workspace_id,p_workpiece_id,
    btrim(p_image_moment_id),lower(p_operation_fingerprint),lower(p_provider_body_sha256),
    btrim(p_provider_request_id),nullif(btrim(coalesce(p_provider_response_id,'')),''),
    'gpt-image-2-2026-04-21',p_prompt_revision_id,lower(p_prompt_content_hash),
    lower(p_semantic_authority_hash),2,1,null
  ) returning * into v_existing;
  for v_item in select * from jsonb_array_elements(p_outputs) loop
    insert into tongs.hearth_timeline_image_generation_outputs(
      result_id,child_ordinal,bytes_base64,content_hash,mime_type,staged_asset_id,staged_asset_path
    ) values(
      v_result_id,(v_item->>'child_ordinal')::integer,v_item->>'bytes_base64',
      encode(extensions.digest(decode(v_item->>'bytes_base64','base64'),'sha256'),'hex'),
      'image/png',(v_item->>'staged_asset_id')::uuid,
      'assets/image-map/candidates/'||p_workpiece_id||'/'||btrim(p_image_moment_id)||'/'
        ||(v_item->>'staged_asset_id')||'-candidate-'||(v_item->>'child_ordinal')||'.png'
    );
  end loop;
  return to_jsonb(v_existing)||jsonb_build_object('replay',false,'authority','owner_cost_provider_attempt');
end $_$;


ALTER FUNCTION "tongs"."stage_owner_timeline_image_generation_result"("p_owner_cost_attempt_id" "uuid", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_operation_fingerprint" "text", "p_financial_environment" "text", "p_runtime_environment" "text", "p_provider_body_sha256" "text", "p_provider_request_id" "text", "p_provider_response_id" "text", "p_prompt_revision_id" "uuid", "p_prompt_content_hash" "text", "p_semantic_authority_hash" "text", "p_image_moment_id" "text", "p_outputs" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."stage_owner_timeline_image_generation_result"("p_owner_cost_attempt_id" "uuid", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_operation_fingerprint" "text", "p_financial_environment" "text", "p_runtime_environment" "text", "p_provider_body_sha256" "text", "p_provider_request_id" "text", "p_provider_response_id" "text", "p_prompt_revision_id" "uuid", "p_prompt_content_hash" "text", "p_semantic_authority_hash" "text", "p_image_moment_id" "text", "p_outputs" "jsonb") IS 'Private service-only owner Timeline Image staging; reads no customer-finance authority.';



CREATE OR REPLACE FUNCTION "tongs"."stage_owner_visual_narrative_interpretation_result"("p_owner_cost_attempt_id" "uuid", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_request_fingerprint" "text", "p_financial_environment" "text", "p_runtime_environment" "text", "p_provider_body_sha256" "text", "p_provider_request_id" "text", "p_model" "text", "p_input_units" bigint, "p_output_units" bigint, "p_visual_brief_json" "jsonb", "p_contracts_json" "jsonb", "p_image_map_revision_id" "uuid", "p_image_map_revision" bigint, "p_script_approval_id" "uuid", "p_script_approval_revision" bigint, "p_creator_direction" "text", "p_visual_style" "text", "p_synthesized_prompt" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $_$
declare
  v_authority jsonb;
  v_operation_key text;
  v_map tongs.image_map_revisions%rowtype;
  v_existing tongs.visual_narrative_interpretation_results%rowtype;
  v_result_id uuid:=extensions.uuid_generate_v5(p_owner_cost_attempt_id,'owner-visual-narrative-result');
begin
  perform tongs._require_accounting_service_role();
  v_authority:=tongs._assert_owner_hearth_result_authority(
    p_owner_cost_attempt_id,'visual.narrative_interpretation',p_user_id,p_workspace_id,p_workpiece_id,
    p_request_fingerprint,p_financial_environment,p_runtime_environment,p_provider_request_id,p_model
  );
  v_operation_key:=v_authority->>'operation_key';
  select * into v_map from tongs.image_map_revisions where id=p_image_map_revision_id;
  if lower(coalesce(p_provider_body_sha256,'')) !~ '^[0-9a-f]{64}$'
     or p_model<>'gpt-5.6-luna' or p_input_units not between 0 and 4096
     or p_output_units not between 0 and 1024
     or cardinality(tongs.validate_image_map_visual_brief(p_visual_brief_json))>0
     or p_contracts_json<>jsonb_build_object(
       'interpretation','forge.image-prompt-interpretation.v2',
       'validator','forge.image-prompt-validator.v2',
       'synthesis','forge.image-prompt-synthesis.v3')
     or v_map.id is null or v_map.workspace_id<>p_workspace_id or v_map.workpiece_id<>p_workpiece_id
     or v_map.revision<>p_image_map_revision or v_map.source_script_approval_id<>p_script_approval_id
     or v_map.source_script_approval_revision<>p_script_approval_revision
     or length(btrim(coalesce(p_creator_direction,'')))=0
     or length(btrim(coalesce(p_synthesized_prompt,'')))=0
  then raise exception 'invalid owner visual narrative result evidence' using errcode='22023'; end if;
  perform pg_advisory_xact_lock(hashtextextended('owner-visual-narrative-result:'||p_owner_cost_attempt_id::text,0));
  select * into v_existing from tongs.visual_narrative_interpretation_results
    where owner_cost_attempt_id=p_owner_cost_attempt_id or operation_id=v_operation_key;
  if found then
    if v_existing.owner_cost_attempt_id<>p_owner_cost_attempt_id
       or v_existing.request_fingerprint<>lower(p_request_fingerprint)
       or v_existing.provider_body_sha256<>lower(p_provider_body_sha256)
       or v_existing.visual_brief_json<>p_visual_brief_json
       or v_existing.synthesized_prompt<>p_synthesized_prompt
    then raise exception 'owner visual narrative result replay conflict' using errcode='23505'; end if;
    return to_jsonb(v_existing)||jsonb_build_object('replay',true,'authority','owner_cost_provider_attempt');
  end if;
  insert into tongs.visual_narrative_interpretation_results(
    id,operation_id,reservation_id,owner_cost_attempt_id,user_id,workspace_id,workpiece_id,
    request_fingerprint,provider_body_sha256,provider_request_id,model,input_units,output_units,
    visual_brief_json,contracts_json,image_map_revision_id,image_map_revision,script_approval_id,
    script_approval_revision,creator_direction,visual_style,synthesized_prompt
  ) values(
    v_result_id,v_operation_key,null,p_owner_cost_attempt_id,p_user_id,p_workspace_id,p_workpiece_id,
    lower(p_request_fingerprint),lower(p_provider_body_sha256),nullif(btrim(coalesce(p_provider_request_id,'')),''),
    p_model,p_input_units,p_output_units,p_visual_brief_json,p_contracts_json,p_image_map_revision_id,
    p_image_map_revision,p_script_approval_id,p_script_approval_revision,btrim(p_creator_direction),
    nullif(btrim(coalesce(p_visual_style,'')),''),p_synthesized_prompt
  ) returning * into v_existing;
  return to_jsonb(v_existing)||jsonb_build_object('replay',false,'authority','owner_cost_provider_attempt');
end $_$;


ALTER FUNCTION "tongs"."stage_owner_visual_narrative_interpretation_result"("p_owner_cost_attempt_id" "uuid", "p_user_id" "uuid", "p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_request_fingerprint" "text", "p_financial_environment" "text", "p_runtime_environment" "text", "p_provider_body_sha256" "text", "p_provider_request_id" "text", "p_model" "text", "p_input_units" bigint, "p_output_units" bigint, "p_visual_brief_json" "jsonb", "p_contracts_json" "jsonb", "p_image_map_revision_id" "uuid", "p_image_map_revision" bigint, "p_script_approval_id" "uuid", "p_script_approval_revision" bigint, "p_creator_direction" "text", "p_visual_style" "text", "p_synthesized_prompt" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."stage_timeline_image_generation_result"("p_operation_id" "text", "p_request_fingerprint" "text", "p_provider_body_sha256" "text", "p_provider_request_id" "text", "p_provider_response_id" "text", "p_prompt_revision_id" "uuid", "p_prompt_content_hash" "text", "p_semantic_authority_hash" "text", "p_image_moment_id" "text", "p_outputs" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare binding tongs.openai_text_funding_bindings%rowtype; reservation tongs.funding_reservations%rowtype; quote tongs.customer_spending_quotes%rowtype; quote_binding tongs.openai_text_customer_quote_bindings%rowtype; bounded tongs.bounded_provider_request_bindings%rowtype; result_id uuid:=extensions.uuid_generate_v5('19670000-0000-4000-8000-000000000011'::uuid,btrim(p_operation_id)); item jsonb; existing uuid;
begin
 perform tongs._require_pricing_service_role(); perform pg_advisory_xact_lock(hashtextextended('timeline-image-result:'||btrim(p_operation_id),0));
 select * into binding from tongs.openai_text_funding_bindings where operation_id=btrim(p_operation_id) and route_code='hearth.timeline_image_generation';
 select * into reservation from tongs.funding_reservations where id=binding.reservation_id;
 select * into quote from tongs.customer_spending_quotes where id=reservation.quote_id;
 select * into quote_binding from tongs.openai_text_customer_quote_bindings where quote_id=quote.id;
 select * into bounded from tongs.bounded_provider_request_bindings where reservation_id=reservation.id;
 select id into existing from tongs.hearth_timeline_image_generation_results where operation_id=btrim(p_operation_id);
 if existing is not null then return jsonb_build_object('result_id',existing,'replay',true); end if;
 if binding.reservation_id is null or binding.model<>'gpt-image-2-2026-04-21' or binding.maximum_output_units<>2 or binding.maximum_attempts<>1
  or quote_binding.request_fingerprint<>lower(p_request_fingerprint) or bounded.serialized_body_sha256<>lower(p_provider_body_sha256)
  or bounded.maximum_output_tokens<>2 or bounded.maximum_attempts<>1 or jsonb_typeof(p_outputs)<>'array' or jsonb_array_length(p_outputs)<>2
  or (select array_agg((value->>'child_ordinal')::int order by (value->>'child_ordinal')::int) from jsonb_array_elements(p_outputs))<>array[1,2]
 then raise exception 'invalid Timeline Image result evidence' using errcode='22023'; end if;
 insert into tongs.hearth_timeline_image_generation_results(id,operation_id,reservation_id,user_id,workspace_id,workpiece_id,image_moment_id,
  request_fingerprint,provider_body_sha256,provider_request_id,provider_response_id,model,prompt_revision_id,prompt_content_hash,semantic_authority_hash,image_count,provider_attempt_count,supplier_cost_micros)
 values(result_id,btrim(p_operation_id),reservation.id,reservation.user_id,quote_binding.workspace_id,quote_binding.workpiece_id::uuid,btrim(p_image_moment_id),lower(p_request_fingerprint),lower(p_provider_body_sha256),
  nullif(btrim(coalesce(p_provider_request_id,'')),''),nullif(btrim(coalesce(p_provider_response_id,'')),''),'gpt-image-2-2026-04-21',p_prompt_revision_id,lower(p_prompt_content_hash),lower(p_semantic_authority_hash),2,1,334900);
 for item in select * from jsonb_array_elements(p_outputs) loop
  insert into tongs.hearth_timeline_image_generation_outputs(result_id,child_ordinal,bytes_base64,content_hash,mime_type,staged_asset_id,staged_asset_path)
  values(result_id,(item->>'child_ordinal')::int,item->>'bytes_base64',encode(extensions.digest(decode(item->>'bytes_base64','base64'),'sha256'),'hex'),item->>'mime_type',(item->>'staged_asset_id')::uuid,
   'assets/image-map/candidates/'||quote_binding.workpiece_id||'/'||btrim(p_image_moment_id)||'/'||(item->>'staged_asset_id')||'-candidate-'||(item->>'child_ordinal')||'.png');
 end loop;
 return jsonb_build_object('result_id',result_id,'replay',false);
end $$;


ALTER FUNCTION "tongs"."stage_timeline_image_generation_result"("p_operation_id" "text", "p_request_fingerprint" "text", "p_provider_body_sha256" "text", "p_provider_request_id" "text", "p_provider_response_id" "text", "p_prompt_revision_id" "uuid", "p_prompt_content_hash" "text", "p_semantic_authority_hash" "text", "p_image_moment_id" "text", "p_outputs" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."stage_visual_narrative_interpretation_result"("p_operation_id" "text", "p_request_fingerprint" "text", "p_provider_body_sha256" "text", "p_provider_request_id" "text", "p_input_units" bigint, "p_output_units" bigint, "p_visual_brief_json" "jsonb", "p_contracts_json" "jsonb", "p_image_map_revision_id" "uuid", "p_image_map_revision" bigint, "p_script_approval_id" "uuid", "p_script_approval_revision" bigint, "p_creator_direction" "text", "p_visual_style" "text", "p_synthesized_prompt" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare binding tongs.openai_text_funding_bindings%rowtype; reservation tongs.funding_reservations%rowtype;
  quote tongs.customer_spending_quotes%rowtype; bounded tongs.bounded_provider_request_bindings%rowtype;
  map_row tongs.image_map_revisions%rowtype; existing tongs.visual_narrative_interpretation_results%rowtype;
  result_id uuid:=extensions.uuid_generate_v5('19000000-0000-4000-8000-000000000008'::uuid,btrim(p_operation_id));
begin
  perform tongs._require_pricing_service_role();
  perform pg_advisory_xact_lock(hashtextextended('visual-narrative-result:'||btrim(p_operation_id),0));
  select * into binding from tongs.openai_text_funding_bindings where operation_id=btrim(p_operation_id) and route_code='visual.narrative_interpretation';
  select * into reservation from tongs.funding_reservations where id=binding.reservation_id;
  select * into quote from tongs.customer_spending_quotes where id=reservation.quote_id;
  select * into bounded from tongs.bounded_provider_request_bindings where reservation_id=reservation.id;
  select * into map_row from tongs.image_map_revisions where id=p_image_map_revision_id;
  if binding.reservation_id is null or binding.model<>'gpt-5.6-luna' or binding.maximum_input_units<>4096
    or binding.maximum_output_units<>1024 or binding.maximum_attempts<>1
    or quote.request_fingerprint<>lower(p_request_fingerprint) or bounded.serialized_body_sha256<>lower(p_provider_body_sha256)
    or bounded.serialized_bytes<=0 or bounded.maximum_output_tokens<>1024 or bounded.maximum_attempts<>1
    or cardinality(tongs.validate_image_map_visual_brief(p_visual_brief_json))>0
    or p_contracts_json<>jsonb_build_object('interpretation','forge.image-prompt-interpretation.v2','validator','forge.image-prompt-validator.v2','synthesis','forge.image-prompt-synthesis.v3')
    or map_row.id is null or map_row.revision<>p_image_map_revision or map_row.source_script_approval_id<>p_script_approval_id
    or map_row.source_script_approval_revision<>p_script_approval_revision
    or p_input_units not between 0 and 4096 or p_output_units not between 0 and 1024
    or length(btrim(coalesce(p_creator_direction,'')))=0 or length(btrim(coalesce(p_synthesized_prompt,'')))=0
  then raise exception 'invalid visual narrative result evidence' using errcode='22023'; end if;
  select * into existing from tongs.visual_narrative_interpretation_results where operation_id=btrim(p_operation_id);
  if found then
    if existing.request_fingerprint<>lower(p_request_fingerprint) or existing.provider_body_sha256<>lower(p_provider_body_sha256)
      or existing.visual_brief_json<>p_visual_brief_json or existing.synthesized_prompt<>p_synthesized_prompt
    then raise exception 'visual narrative result replay conflict' using errcode='23505'; end if;
    return to_jsonb(existing)||jsonb_build_object('replay',true);
  end if;
  insert into tongs.visual_narrative_interpretation_results(
    id,operation_id,reservation_id,user_id,workspace_id,workpiece_id,request_fingerprint,provider_body_sha256,
    provider_request_id,model,input_units,output_units,visual_brief_json,contracts_json,image_map_revision_id,
    image_map_revision,script_approval_id,script_approval_revision,creator_direction,visual_style,synthesized_prompt
  ) values(result_id,btrim(p_operation_id),reservation.id,reservation.user_id,map_row.workspace_id,map_row.workpiece_id,
    lower(p_request_fingerprint),lower(p_provider_body_sha256),nullif(btrim(coalesce(p_provider_request_id,'')),''),
    'gpt-5.6-luna',p_input_units,p_output_units,p_visual_brief_json,p_contracts_json,map_row.id,map_row.revision,
    p_script_approval_id,p_script_approval_revision,btrim(p_creator_direction),nullif(btrim(coalesce(p_visual_style,'')),''),p_synthesized_prompt);
  return jsonb_build_object('result_id',result_id,'replay',false);
end $$;


ALTER FUNCTION "tongs"."stage_visual_narrative_interpretation_result"("p_operation_id" "text", "p_request_fingerprint" "text", "p_provider_body_sha256" "text", "p_provider_request_id" "text", "p_input_units" bigint, "p_output_units" bigint, "p_visual_brief_json" "jsonb", "p_contracts_json" "jsonb", "p_image_map_revision_id" "uuid", "p_image_map_revision" bigint, "p_script_approval_id" "uuid", "p_script_approval_revision" bigint, "p_creator_direction" "text", "p_visual_style" "text", "p_synthesized_prompt" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."start_customer_runway_generation_attempt"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_beat_id" "uuid", "p_prompt_revision_id" "uuid", "p_prompt_revision" bigint, "p_prompt_content_hash" "text", "p_creative_input_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $_$
declare
  v_actor uuid:=auth.uid();
  v_scope tongs.broll_generation_replacement_scopes%rowtype;
  v_attempt tongs.broll_generation_attempts%rowtype;
  v_original_authorization tongs.runway_customer_test_authorizations%rowtype;
  v_generation_request_id uuid;
  v_authorization_id uuid;
  v_operation_fingerprint text;
  v_operation_id text;
  v_valid_from timestamptz:=clock_timestamp();
  v_valid_until timestamptz;
begin
  if v_actor is null or not tongs.has_workspace_role(p_workspace_id,'editor') then
    raise exception 'workspace editor authority required' using errcode='42501';
  end if;
  if p_prompt_revision_id is null or p_prompt_revision is null or p_prompt_revision<=0
     or p_prompt_content_hash!~'^[0-9a-f]{64}$' or p_creative_input_hash!~'^[0-9a-f]{64}$' then
    raise exception 'invalid generation attempt context' using errcode='22023';
  end if;
  select * into v_scope from tongs.broll_generation_replacement_scopes
  where user_id=v_actor and workspace_id=p_workspace_id and workpiece_id=p_workpiece_id
    and beat_id=p_beat_id and prompt_revision_id=p_prompt_revision_id
    and prompt_revision=p_prompt_revision and prompt_content_hash=lower(p_prompt_content_hash)
    and creative_input_hash=lower(p_creative_input_hash)
  for update;
  if not found then
    raise exception 'no bounded replacement generation authority exists for this exact request' using errcode='42501';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('broll-generation-replacement:'||v_scope.id::text,0));
  select * into v_attempt from tongs.broll_generation_attempts
  where replacement_scope_id=v_scope.id;
  if found then
    return jsonb_build_object(
      'disposition','generation_attempt_replay','generation_request_id',v_attempt.generation_request_id,
      'attempt_ordinal',v_attempt.attempt_ordinal,'previous_operation_id',v_attempt.previous_operation_id,
      'operation_id',v_attempt.operation_id,'operation_fingerprint',v_attempt.operation_fingerprint,
      'creative_input_hash',v_attempt.creative_input_hash,'prompt_revision_id',v_attempt.prompt_revision_id,
      'prompt_revision',v_attempt.prompt_revision,'prompt_content_hash',v_attempt.prompt_content_hash,
      'replay',true
    );
  end if;
  if v_scope.valid_from>v_valid_from or v_scope.valid_until<=v_valid_from then
    raise exception 'bounded replacement generation authority is not current' using errcode='42501';
  end if;
  if not tongs._is_terminal_customer_runway_preprovider_failure(v_scope.original_operation_id) then
    raise exception 'original generation is not a definitive untransmitted terminal failure' using errcode='42501';
  end if;
  if not exists(
    select 1 from tongs.broll_prompt_sequences sequence
    where sequence.workspace_id=p_workspace_id and sequence.workpiece_id=p_workpiece_id
      and sequence.beat_id=p_beat_id and sequence.current_prompt_revision_id=p_prompt_revision_id
      and sequence.current_prompt_revision=p_prompt_revision
  ) or not exists(
    select 1 from tongs.broll_prompt_revisions prompt
    where prompt.id=p_prompt_revision_id and prompt.workspace_id=p_workspace_id
      and prompt.workpiece_id=p_workpiece_id and prompt.beat_id=p_beat_id
      and prompt.revision=p_prompt_revision and prompt.content_hash=lower(p_prompt_content_hash)
  ) then
    raise exception 'canonical prompt authority changed before replacement attempt' using errcode='55000';
  end if;
  select * into v_original_authorization from tongs.runway_customer_test_authorizations
  where id=v_scope.original_authorization_id;
  if not found or v_original_authorization.user_id<>v_actor
     or v_original_authorization.workspace_id<>p_workspace_id
     or v_original_authorization.operation_id<>v_scope.original_operation_id
     or v_original_authorization.operation_fingerprint<>v_scope.original_operation_fingerprint
     or v_original_authorization.financial_environment<>'test'
     or v_original_authorization.model<>'gen4.5'
     or v_original_authorization.generation_mode<>'text_to_video'
     or v_original_authorization.duration_seconds<>5 or v_original_authorization.ratio<>'1280:720'
     or v_original_authorization.reference_image_count<>0 or v_original_authorization.output_count<>1
     or v_original_authorization.maximum_provider_attempts<>1
     or v_original_authorization.maximum_customer_charge_micros<>800000
     or v_original_authorization.maximum_wholesale_exposure_micros<>600000
     or v_original_authorization.maximum_concurrency<>1 then
    raise exception 'original customer Runway authority does not match replacement scope' using errcode='42501';
  end if;
  v_generation_request_id:=extensions.uuid_generate_v5(v_scope.id,'generation-attempt-2');
  v_operation_fingerprint:=encode(extensions.digest(convert_to(jsonb_build_object(
    'creative_input_hash',v_scope.creative_input_hash,
    'generation_request_id',v_generation_request_id,
    'attempt_ordinal',2,
    'previous_operation_id',v_scope.original_operation_id
  )::text,'utf8'),'sha256'),'hex');
  v_operation_id:='forge:broll:acquire:'||v_operation_fingerprint;
  v_authorization_id:=extensions.uuid_generate_v5(v_generation_request_id,'runway-test-authorization');
  v_valid_until:=least(v_scope.valid_until,v_valid_from+interval '24 hours');
  insert into tongs.broll_generation_attempts(
    generation_request_id,replacement_scope_id,attempt_ordinal,previous_operation_id,
    workspace_id,workpiece_id,beat_id,prompt_revision_id,prompt_revision,
    prompt_content_hash,creative_input_hash,operation_id,operation_fingerprint,initiated_by
  ) values(
    v_generation_request_id,v_scope.id,2,v_scope.original_operation_id,
    p_workspace_id,p_workpiece_id,p_beat_id,p_prompt_revision_id,p_prompt_revision,
    lower(p_prompt_content_hash),lower(p_creative_input_hash),v_operation_id,v_operation_fingerprint,v_actor
  ) returning * into v_attempt;
  insert into tongs.runway_customer_test_authorizations(
    id,user_id,workspace_id,financial_environment,route_code,provider,model,
    generation_mode,duration_seconds,ratio,output_count,reference_image_count,
    maximum_provider_attempts,pricing_revision_id,operation_id,operation_fingerprint,
    maximum_operation_count,maximum_customer_charge_micros,
    maximum_wholesale_exposure_micros,maximum_concurrency,valid_from,valid_until,
    status,reason,created_by,maximum_quote_count
  ) values(
    v_authorization_id,v_actor,p_workspace_id,'test','tongs_broll_v2','runway','gen4.5',
    'text_to_video',5,'1280:720',1,0,1,v_original_authorization.pricing_revision_id,
    v_operation_id,v_operation_fingerprint,1,800000,600000,1,v_valid_from,v_valid_until,
    'active','One explicit replacement for the proven untransmitted terminal customer Test attempt.',
    v_original_authorization.created_by,2
  );
  insert into tongs.paid_execution_aggregate_assignments(
    id,policy_revision_id,user_id,workspace_id,state,valid_from,valid_until,reason
  ) values(
    extensions.uuid_generate_v5(v_authorization_id,'aggregate-assignment'),
    '19730000-0000-4000-8000-000000000005',v_actor,p_workspace_id,'active',
    v_valid_from,v_valid_until,
    'Exact one-operation replacement normal-customer Test Runway Gen-4.5 exposure assignment.'
  );
  return jsonb_build_object(
    'disposition','generation_attempt_started','generation_request_id',v_attempt.generation_request_id,
    'attempt_ordinal',v_attempt.attempt_ordinal,'previous_operation_id',v_attempt.previous_operation_id,
    'operation_id',v_attempt.operation_id,'operation_fingerprint',v_attempt.operation_fingerprint,
    'creative_input_hash',v_attempt.creative_input_hash,'prompt_revision_id',v_attempt.prompt_revision_id,
    'prompt_revision',v_attempt.prompt_revision,'prompt_content_hash',v_attempt.prompt_content_hash,
    'authorization_id',v_authorization_id,'replay',false
  );
end $_$;


ALTER FUNCTION "tongs"."start_customer_runway_generation_attempt"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_beat_id" "uuid", "p_prompt_revision_id" "uuid", "p_prompt_revision" bigint, "p_prompt_content_hash" "text", "p_creative_input_hash" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "tongs"."start_customer_runway_generation_attempt"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_beat_id" "uuid", "p_prompt_revision_id" "uuid", "p_prompt_revision" bigint, "p_prompt_content_hash" "text", "p_creative_input_hash" "text") IS 'Creator-initiated, idempotent creation of the single exact normal-customer Test Runway replacement identity. Creates no quote, reservation, acceptance, debit, or provider call.';



CREATE OR REPLACE FUNCTION "tongs"."sync_legacy_profile_from_account_balance"("p_user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare
  v_customer_id text;
  v_plan_status text;
  v_plan_current_period_end timestamptz;
  v_plan_entitled boolean := false;
  v_plan_subscription_id text;
begin
  if p_user_id is null then
    raise exception 'p_user_id required'
      using errcode = '22023';
  end if;

  if pg_catalog.to_regclass('public.profiles') is null then
    return;
  end if;

  insert into public.profiles (user_id)
  values (p_user_id)
  on conflict (user_id) do nothing;

  select
    ab.stripe_customer_id,
    ab.plan_status,
    ab.plan_current_period_end,
    ab.plan_entitled
  into
    v_customer_id,
    v_plan_status,
    v_plan_current_period_end,
    v_plan_entitled
  from tongs.account_balances ab
  where ab.user_id = p_user_id;

  select s.stripe_subscription_id
  into v_plan_subscription_id
  from tongs.billing_subscriptions s
  where s.user_id = p_user_id
    and s.purchase_type = 'subscription'
    and tongs.billing_item_is_plan(s.item_id)
  order by
    case when tongs.billing_status_entitles_access(s.status) then 0 else 1 end,
    s.current_period_end desc nulls last,
    s.updated_at desc
  limit 1;

  update public.profiles p
  set
    stripe_customer_id = v_customer_id,
    stripe_subscription_id = v_plan_subscription_id,
    subscription_status = v_plan_status,
    current_period_end = v_plan_current_period_end,
    anvil_paid = coalesce(v_plan_entitled, false)
  where p.user_id = p_user_id;
end;
$$;


ALTER FUNCTION "tongs"."sync_legacy_profile_from_account_balance"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."thumbnail_brand_setup_asset_hash"("p_workspace_id" "uuid", "p_workpiece_id" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
  select encode(extensions.digest(convert_to(coalesce(jsonb_agg(jsonb_build_array(a.id,a.asset_kind,a.status,a.content_hash,a.storage_bucket,a.storage_key) order by a.id),'[]'::jsonb)::text,'UTF8'),'sha256'),'hex')
  from tongs.assets a where a.workspace_id=p_workspace_id and a.workpiece_id=p_workpiece_id and a.asset_kind in('thumbnail_image','thumbnail_composite')
$$;


ALTER FUNCTION "tongs"."thumbnail_brand_setup_asset_hash"("p_workspace_id" "uuid", "p_workpiece_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."thumbnail_brand_setup_json"("p_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
  select to_jsonb(o)-'requested_rules_json' from tongs.thumbnail_brand_setup_operations o where o.id=p_id
$$;


ALTER FUNCTION "tongs"."thumbnail_brand_setup_json"("p_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."thumbnail_candidate_eligibility"("p_candidate_id" "uuid", "p_active_binding_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare c tongs.thumbnail_candidate_revisions%rowtype; d text; v_latest_set uuid; v_asset tongs.assets%rowtype;
begin
 select * into c from tongs.thumbnail_candidate_revisions where id=p_candidate_id;
 if c.id is null then return 'blocked'; end if;
 select * into v_asset from tongs.assets where id=c.composite_asset_id;
 if v_asset.id is null or v_asset.status<>'ready' or v_asset.content_hash<>c.composite_content_hash then return 'blocked'; end if;
 select id into v_latest_set from tongs.thumbnail_candidate_sets where workpiece_id=c.workpiece_id order by revision desc limit 1;
 if v_latest_set is null or not exists(select 1 from tongs.thumbnail_candidate_set_members where candidate_set_id=v_latest_set and candidate_revision_id=c.id) then return 'historical_brand'; end if;
 if c.style_source='forge_standard' then return 'current'; end if;
 if c.candidate_binding_id=p_active_binding_id then return 'current'; end if;
 select decision into d from tongs.thumbnail_candidate_brand_decisions where candidate_revision_id=c.id and active_binding_id=p_active_binding_id order by decision_revision desc limit 1;
 if d='approved' then return 'approved_historical_brand'; end if;
 return 'requires_reapproval';
end $$;


ALTER FUNCTION "tongs"."thumbnail_candidate_eligibility"("p_candidate_id" "uuid", "p_active_binding_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."thumbnail_structural_fingerprint"("p_value" "jsonb") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
 select encode(extensions.digest(convert_to(jsonb_strip_nulls(jsonb_build_object(
  'layout_family',p_value->'layout_family','title_block_zone',p_value->'title_block_zone','title_alignment',p_value->'title_alignment',
  'subject_zone',p_value->'subject_zone','subject_scale_class',p_value->'subject_scale_class','crop_mode',p_value->'crop_mode',
  'foreground_layering',p_value->'foreground_layering','background_treatment',p_value->'background_treatment'))::text,'UTF8'),'sha256'),'hex') $$;


ALTER FUNCTION "tongs"."thumbnail_structural_fingerprint"("p_value" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."thumbnail_title_revision_identity"("p_recipe" "jsonb") RETURNS "uuid"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
 with h as(select encode(extensions.digest(convert_to(jsonb_build_object('title_id',p_recipe->'title_id','title_revision',p_recipe->'title_revision','title_text',p_recipe->'title_text')::text,'UTF8'),'sha256'),'hex') v)
 select (substr(v,1,8)||'-'||substr(v,9,4)||'-5'||substr(v,14,3)||'-a'||substr(v,18,3)||'-'||substr(v,21,12))::uuid from h $$;


ALTER FUNCTION "tongs"."thumbnail_title_revision_identity"("p_recipe" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."touch_updated_at"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'tongs', 'pg_temp'
    AS $$
begin
  new.updated_at = now();
  return new;
end;
$$;


ALTER FUNCTION "tongs"."touch_updated_at"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."track_henry_event"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_event_name" "text", "p_surface" "text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'tongs'
    AS $$
declare
  v_event_id uuid;
begin
  if auth.uid() is null then
    raise exception 'Authentication required';
  end if;
  if p_workspace_id is null then
    raise exception 'workspace_id is required';
  end if;
  if not tongs.can_access_workspace(p_workspace_id) then
    raise exception 'Workspace access denied';
  end if;
  if nullif(trim(coalesce(p_event_name, '')), '') is null then
    raise exception 'event_name is required';
  end if;
  if nullif(trim(coalesce(p_surface, '')), '') is null then
    raise exception 'surface is required';
  end if;

  insert into tongs.henry_events (
    user_id,
    workspace_id,
    workpiece_id,
    event_name,
    surface,
    metadata
  ) values (
    auth.uid(),
    p_workspace_id,
    p_workpiece_id,
    trim(p_event_name),
    trim(p_surface),
    coalesce(p_metadata, '{}'::jsonb)
  )
  returning event_id into v_event_id;

  return v_event_id;
end;
$$;


ALTER FUNCTION "tongs"."track_henry_event"("p_workspace_id" "uuid", "p_workpiece_id" "uuid", "p_event_name" "text", "p_surface" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."transition_credential_lifecycle"("p_credential_id" "uuid", "p_expected_status" "text", "p_new_status" "text", "p_replacement_credential_id" "uuid", "p_revocation_confirmed_at" timestamp with time zone, "p_verification_json" "jsonb", "p_actor_id" "uuid", "p_event_key" "text", "p_occurred_at" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_row tongs.credential_lifecycle_records%rowtype;
  v_replacement tongs.credential_lifecycle_records%rowtype;
  v_sequence integer;
  v_event_type text := 'status_transition';
  v_evidence jsonb := coalesce(p_verification_json, '{}'::jsonb);
  v_now timestamptz := coalesce(p_occurred_at, transaction_timestamp());
  v_allowed boolean := false;
begin
  perform tongs._require_credential_lifecycle_writer();
  if p_actor_id is null or not tongs.is_platform_operator(p_actor_id)
     or p_event_key is null or not tongs._credential_lifecycle_metadata_safe(v_evidence) then
    raise exception 'invalid credential lifecycle transition' using errcode = '22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('credential-lifecycle:'||p_credential_id::text, 0));
  select * into v_row from tongs.credential_lifecycle_records where credential_id=p_credential_id for update;
  if not found then raise exception 'credential lifecycle record not found' using errcode='P0002'; end if;
  if v_row.lifecycle_status <> p_expected_status then
    raise exception 'credential lifecycle status conflict' using errcode='40001';
  end if;
  v_allowed := case v_row.lifecycle_status
    when 'planned' then p_new_status in ('active','disabled')
    when 'active' then p_new_status in ('rotation_due','replacement_ready','expired','disabled')
    when 'rotation_due' then p_new_status in ('replacement_ready','expired','disabled')
    when 'replacement_ready' then p_new_status in ('replacement_active','expired','disabled')
    when 'replacement_active' then p_new_status in ('revocation_pending','disabled')
    when 'revocation_pending' then p_new_status in ('revoked','disabled')
    when 'expired' then p_new_status in ('replacement_ready','disabled')
    else false end;
  if not v_allowed then raise exception 'invalid credential lifecycle transition' using errcode='22023'; end if;

  if p_new_status in ('replacement_ready','replacement_active','revocation_pending') then
    if p_replacement_credential_id is null then
      raise exception 'replacement credential required' using errcode='22023';
    end if;
    select * into v_replacement from tongs.credential_lifecycle_records
      where credential_id=p_replacement_credential_id;
    if not found or v_replacement.credential_id=v_row.credential_id
       or v_replacement.provider<>v_row.provider
       or v_replacement.configuration_variable_name<>v_row.configuration_variable_name
       or v_replacement.financial_environment<>v_row.financial_environment
       or v_replacement.runtime_environment<>v_row.runtime_environment then
      raise exception 'replacement credential authority mismatch' using errcode='23514';
    end if;
    v_event_type := 'replacement_linked';
  end if;
  if p_new_status='revoked' and p_revocation_confirmed_at is null then
    raise exception 'revocation confirmation required' using errcode='22023';
  end if;
  if p_new_status='revoked' then v_event_type := 'revocation_confirmed'; end if;

  select coalesce(max(event_sequence),0)+1 into v_sequence
    from tongs.credential_lifecycle_events where credential_id=p_credential_id;
  update tongs.credential_lifecycle_records set
    lifecycle_status=p_new_status,
    activated_at=case
      when p_expected_status='planned' and p_new_status='active'
        then coalesce(activated_at,v_now)
      else activated_at
    end,
    replacement_credential_id=coalesce(p_replacement_credential_id,replacement_credential_id),
    revocation_required=case when p_new_status in ('replacement_active','revocation_pending','revoked') then true else revocation_required end,
    revocation_confirmed_at=case when p_new_status='revoked' then p_revocation_confirmed_at else revocation_confirmed_at end,
    last_verification_at=v_now,
    config_presence_verified_at=case when coalesce((v_evidence->>'config_presence_verified')::boolean,false) then v_now else config_presence_verified_at end,
    route_configuration_verified_at=case when coalesce((v_evidence->>'route_configuration_verified')::boolean,false) then v_now else route_configuration_verified_at end,
    non_paid_readiness_verified_at=case when coalesce((v_evidence->>'non_paid_readiness_verified')::boolean,false) then v_now else non_paid_readiness_verified_at end,
    bounded_smoke_performed_at=case when coalesce((v_evidence->>'bounded_smoke_performed')::boolean,false) then v_now else bounded_smoke_performed_at end,
    smoke_operation_id=coalesce(nullif(v_evidence->>'smoke_operation_id',''),smoke_operation_id),
    updated_at=v_now
  where credential_id=p_credential_id returning * into v_row;
  insert into tongs.credential_lifecycle_events(
    event_id,credential_id,event_sequence,event_key,from_status,to_status,event_type,actor_id,evidence_json,occurred_at
  ) values (
    gen_random_uuid(),p_credential_id,v_sequence,btrim(p_event_key),p_expected_status,p_new_status,
    v_event_type,p_actor_id,v_evidence,v_now
  );
  return to_jsonb(v_row) - 'credential_identity_hash';
end;
$$;


ALTER FUNCTION "tongs"."transition_credential_lifecycle"("p_credential_id" "uuid", "p_expected_status" "text", "p_new_status" "text", "p_replacement_credential_id" "uuid", "p_revocation_confirmed_at" timestamp with time zone, "p_verification_json" "jsonb", "p_actor_id" "uuid", "p_event_key" "text", "p_occurred_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."update_creator_profile_from_event"("p_event_type" "text", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS TABLE("user_id" "uuid", "clarify_first_bias" real, "outline_first_bias" real, "script_first_bias" real, "tone_style" "text", "risk_sensitivity" real, "confidence" real)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare
  v_user uuid;
  v_event text;
  v_payload jsonb;
  v_delta_clarify real := 0.0;
  v_delta_outline real := 0.0;
  v_delta_script real := 0.0;
  v_delta_conf real := 0.02;
  v_tone_style text;
  v_risk real;
  v_from_gate_text text;
begin
  v_user := auth.uid();
  if v_user is null then
    raise exception 'Not authenticated'
      using errcode = '42501';
  end if;

  v_event := lower(trim(coalesce(p_event_type, '')));
  v_payload := coalesce(p_payload, '{}'::jsonb);

  insert into tongs.hearth_creator_profiles (user_id)
  values (v_user)
  on conflict on constraint hearth_creator_profiles_pkey do nothing;

  if v_event = 'user_requested_outline' then
    v_delta_outline := v_delta_outline + 0.05;
    v_delta_script := v_delta_script - 0.03;
  elsif v_event = 'user_requested_script' then
    v_delta_outline := v_delta_outline - 0.03;
    v_delta_script := v_delta_script + 0.05;
  elsif v_event = 'user_explicit_draft_now' then
    v_delta_clarify := v_delta_clarify - 0.05;
  elsif v_event = 'proposal_discarded' then
    v_delta_clarify := v_delta_clarify + 0.02;
  elsif v_event = 'outline_generated' then
    v_delta_outline := v_delta_outline + 0.02;
  elsif v_event = 'draft_generated' then
    v_delta_script := v_delta_script + 0.02;
  elsif v_event = 'proposal_applied' then
    v_from_gate_text := lower(trim(coalesce(v_payload->>'from_gate', '')));
    if v_from_gate_text in ('1', 'true', 't', 'yes', 'y') then
      v_delta_clarify := v_delta_clarify + 0.03;
    end if;
  end if;

  select p.tone_style, p.risk_sensitivity
  into v_tone_style, v_risk
  from tongs.hearth_creator_profiles p
  where p.user_id = v_user;

  if jsonb_typeof(v_payload->'tone_style') = 'string' then
    v_tone_style := nullif(trim(v_payload->>'tone_style'), '');
  end if;
  if v_tone_style is null then
    v_tone_style := 'neutral_conversational';
  end if;

  if jsonb_typeof(v_payload->'risk_sensitivity') = 'number' then
    v_risk := least(1.0, greatest(0.0, (v_payload->>'risk_sensitivity')::real));
  elsif v_risk is null then
    v_risk := 0.5;
  end if;

  update tongs.hearth_creator_profiles p
  set
    clarify_first_bias = least(1.0, greatest(0.0, (p.clarify_first_bias * 0.98) + v_delta_clarify)),
    outline_first_bias = least(1.0, greatest(0.0, (p.outline_first_bias * 0.98) + v_delta_outline)),
    script_first_bias = least(1.0, greatest(0.0, (p.script_first_bias * 0.98) + v_delta_script)),
    tone_style = v_tone_style,
    risk_sensitivity = v_risk,
    confidence = least(1.0, greatest(0.0, p.confidence + v_delta_conf)),
    profile_json = coalesce(p.profile_json, '{}'::jsonb) || jsonb_build_object(
      'last_event', v_event,
      'last_event_at', now()
    ),
    updated_at = now()
  where p.user_id = v_user;

  return query
  select
    p.user_id,
    p.clarify_first_bias,
    p.outline_first_bias,
    p.script_first_bias,
    p.tone_style,
    p.risk_sensitivity,
    p.confidence
  from tongs.hearth_creator_profiles p
  where p.user_id = v_user;
end;
$$;


ALTER FUNCTION "tongs"."update_creator_profile_from_event"("p_event_type" "text", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."update_my_thumbnail_brand_template"("p_workspace_id" "uuid", "p_template_id" "uuid", "p_name" "text" DEFAULT NULL::"text", "p_template_json" "jsonb" DEFAULT NULL::"jsonb", "p_is_default" boolean DEFAULT NULL::boolean) RETURNS TABLE("template_id" "uuid", "workspace_id" "uuid", "slug" "text", "name" "text", "template_json" "jsonb", "is_default" boolean, "archived_at" timestamp with time zone, "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "updated_by" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare
  v_user uuid;
  v_name text := nullif(btrim(coalesce(p_name, '')), '');
  v_template_json jsonb := p_template_json;
  v_target tongs.workspace_thumbnail_brand_templates%rowtype;
  v_make_default boolean;
begin
  v_user := auth.uid();
  if v_user is null then
    raise exception 'Not authenticated'
      using errcode = '42501';
  end if;

  if p_workspace_id is null or p_template_id is null then
    raise exception 'workspace_id and template_id are required'
      using errcode = '22023';
  end if;

  perform tongs.assert_workspace_role(p_workspace_id, 'editor');

  select *
  into v_target
  from tongs.workspace_thumbnail_brand_templates t
  where t.workspace_id = p_workspace_id
    and t.id = p_template_id
  limit 1;

  if not found then
    raise exception 'template not found'
      using errcode = 'P0002';
  end if;

  if v_target.archived_at is not null then
    raise exception 'template is archived'
      using errcode = '22023';
  end if;

  if p_template_json is not null and jsonb_typeof(v_template_json) <> 'object' then
    raise exception 'template_json must be an object'
      using errcode = '22023';
  end if;

  v_make_default := coalesce(p_is_default, v_target.is_default);

  if v_make_default then
    update tongs.workspace_thumbnail_brand_templates other_templates
    set is_default = false,
        updated_at = now(),
        updated_by = v_user
    where other_templates.workspace_id = p_workspace_id
      and other_templates.id <> p_template_id
      and other_templates.archived_at is null;
  end if;

  update tongs.workspace_thumbnail_brand_templates t
  set name = coalesce(v_name, t.name),
      template_json = coalesce(jsonb_strip_nulls(v_template_json), t.template_json),
      is_default = v_make_default,
      updated_at = now(),
      updated_by = v_user
  where t.workspace_id = p_workspace_id
    and t.id = p_template_id;

  return query
  select
    t.id,
    t.workspace_id,
    t.slug,
    t.name,
    t.template_json,
    t.is_default,
    t.archived_at,
    t.created_at,
    t.updated_at,
    t.updated_by
  from tongs.workspace_thumbnail_brand_templates t
  where t.id = p_template_id;
end;
$$;


ALTER FUNCTION "tongs"."update_my_thumbnail_brand_template"("p_workspace_id" "uuid", "p_template_id" "uuid", "p_name" "text", "p_template_json" "jsonb", "p_is_default" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."update_workspace_member_role"("p_workspace_id" "uuid", "p_user_id" "uuid", "p_role" "text") RETURNS TABLE("workspace_id" "uuid", "user_id" "uuid", "role" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare
  v_user uuid;
  v_role text;
  v_current_role text;
  v_is_creator boolean;
begin
  v_user := auth.uid();
  if v_user is null then
    raise exception 'not_authenticated'
      using errcode = '42501';
  end if;

  if p_workspace_id is null or p_user_id is null then
    raise exception 'workspace_id_and_user_id_required'
      using errcode = '22023';
  end if;

  perform tongs.assert_workspace_role(p_workspace_id, 'admin');

  v_role := lower(btrim(coalesce(p_role, '')));
  if tongs.workspace_role_rank(v_role) = 0 then
    raise exception 'unsupported_workspace_role'
      using errcode = '22023';
  end if;

  if v_role = 'owner' and not tongs.has_workspace_role(p_workspace_id, 'owner') then
    raise exception 'owner_assignment_requires_owner'
      using errcode = '42501';
  end if;

  select
    wm.role,
    (w.created_by = wm.user_id)
  into
    v_current_role,
    v_is_creator
  from tongs.workspace_members wm
  join tongs.workspaces w
    on w.id = wm.workspace_id
  where wm.workspace_id = p_workspace_id
    and wm.user_id = p_user_id
  for update;

  if not found then
    raise exception 'workspace_member_not_found'
      using errcode = 'P0002';
  end if;

  if v_is_creator and v_role <> 'owner' then
    raise exception 'creator_role_locked'
      using errcode = '42501';
  end if;

  if v_current_role = 'owner' and v_role <> 'owner' then
    raise exception 'owner_role_locked'
      using errcode = '42501';
  end if;

  update tongs.workspace_members wm
  set role = v_role
  where wm.workspace_id = p_workspace_id
    and wm.user_id = p_user_id;

  return query
  select
    p_workspace_id,
    p_user_id,
    v_role;
end;
$$;


ALTER FUNCTION "tongs"."update_workspace_member_role"("p_workspace_id" "uuid", "p_user_id" "uuid", "p_role" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."upsert_billing_customer"("p_user_id" "uuid", "p_stripe_customer_id" "text", "p_email" "text" DEFAULT NULL::"text", "p_customer_name" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare
  v_stripe_customer_id text := nullif(btrim(coalesce(p_stripe_customer_id, '')), '');
  v_email text := nullif(btrim(coalesce(p_email, '')), '');
  v_customer_name text := nullif(btrim(coalesce(p_customer_name, '')), '');
  v_metadata jsonb := coalesce(p_metadata, '{}'::jsonb);
begin
  if p_user_id is null then
    raise exception 'p_user_id required'
      using errcode = '22023';
  end if;

  if v_stripe_customer_id is null then
    raise exception 'p_stripe_customer_id required'
      using errcode = '22023';
  end if;

  delete from tongs.billing_customers
  where user_id = p_user_id
    and stripe_customer_id <> v_stripe_customer_id;

  insert into tongs.billing_customers (
    user_id,
    stripe_customer_id,
    email,
    customer_name,
    metadata_json
  )
  values (
    p_user_id,
    v_stripe_customer_id,
    v_email,
    v_customer_name,
    v_metadata
  )
  on conflict (stripe_customer_id) do update
  set
    user_id = excluded.user_id,
    email = coalesce(excluded.email, tongs.billing_customers.email),
    customer_name = coalesce(excluded.customer_name, tongs.billing_customers.customer_name),
    metadata_json = tongs.billing_customers.metadata_json || excluded.metadata_json,
    updated_at = now();
end;
$$;


ALTER FUNCTION "tongs"."upsert_billing_customer"("p_user_id" "uuid", "p_stripe_customer_id" "text", "p_email" "text", "p_customer_name" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."upsert_billing_one_time_purchase"("p_user_id" "uuid", "p_stripe_customer_id" "text", "p_stripe_event_id" "text", "p_stripe_session_id" "text", "p_purchase_type" "text", "p_item_id" "text", "p_status" "text", "p_payment_intent_id" "text" DEFAULT NULL::"text", "p_amount_total" bigint DEFAULT NULL::bigint, "p_currency" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare
  v_customer_id text := nullif(btrim(coalesce(p_stripe_customer_id, '')), '');
  v_event_id text := nullif(btrim(coalesce(p_stripe_event_id, '')), '');
  v_session_id text := nullif(btrim(coalesce(p_stripe_session_id, '')), '');
  v_purchase_type text := nullif(lower(btrim(coalesce(p_purchase_type, ''))), '');
  v_item_id text := nullif(lower(btrim(coalesce(p_item_id, ''))), '');
  v_status text := nullif(lower(btrim(coalesce(p_status, ''))), '');
  v_payment_intent_id text := nullif(btrim(coalesce(p_payment_intent_id, '')), '');
  v_currency text := nullif(lower(btrim(coalesce(p_currency, ''))), '');
  v_metadata jsonb := coalesce(p_metadata, '{}'::jsonb);
begin
  if p_user_id is null then
    raise exception 'p_user_id required'
      using errcode = '22023';
  end if;

  if v_customer_id is null then
    raise exception 'p_stripe_customer_id required'
      using errcode = '22023';
  end if;

  if v_event_id is null then
    raise exception 'p_stripe_event_id required'
      using errcode = '22023';
  end if;

  if v_session_id is null then
    raise exception 'p_stripe_session_id required'
      using errcode = '22023';
  end if;

  if v_purchase_type is distinct from 'ai_credits' then
    raise exception 'Unsupported one-time purchase_type: %', coalesce(v_purchase_type, 'null')
      using errcode = '22023';
  end if;

  if v_item_id is null then
    raise exception 'p_item_id required'
      using errcode = '22023';
  end if;

  if v_status is null then
    raise exception 'p_status required'
      using errcode = '22023';
  end if;

  insert into tongs.billing_one_time_purchases (
    stripe_session_id,
    stripe_event_id,
    stripe_customer_id,
    user_id,
    purchase_type,
    item_id,
    status,
    payment_intent_id,
    amount_total,
    currency,
    metadata_json
  )
  values (
    v_session_id,
    v_event_id,
    v_customer_id,
    p_user_id,
    v_purchase_type,
    v_item_id,
    v_status,
    v_payment_intent_id,
    p_amount_total,
    v_currency,
    v_metadata
  )
  on conflict (stripe_session_id) do update
  set
    stripe_event_id = excluded.stripe_event_id,
    stripe_customer_id = excluded.stripe_customer_id,
    user_id = excluded.user_id,
    purchase_type = excluded.purchase_type,
    item_id = excluded.item_id,
    status = excluded.status,
    payment_intent_id = coalesce(excluded.payment_intent_id, tongs.billing_one_time_purchases.payment_intent_id),
    amount_total = coalesce(excluded.amount_total, tongs.billing_one_time_purchases.amount_total),
    currency = coalesce(excluded.currency, tongs.billing_one_time_purchases.currency),
    metadata_json = tongs.billing_one_time_purchases.metadata_json || excluded.metadata_json,
    updated_at = now();
end;
$$;


ALTER FUNCTION "tongs"."upsert_billing_one_time_purchase"("p_user_id" "uuid", "p_stripe_customer_id" "text", "p_stripe_event_id" "text", "p_stripe_session_id" "text", "p_purchase_type" "text", "p_item_id" "text", "p_status" "text", "p_payment_intent_id" "text", "p_amount_total" bigint, "p_currency" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."upsert_billing_subscription"("p_user_id" "uuid", "p_stripe_customer_id" "text", "p_stripe_subscription_id" "text", "p_purchase_type" "text", "p_item_id" "text", "p_interval" "text", "p_status" "text", "p_price_id" "text" DEFAULT NULL::"text", "p_current_period_start" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_current_period_end" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_cancel_at_period_end" boolean DEFAULT false, "p_canceled_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare
  v_customer_id text := nullif(btrim(coalesce(p_stripe_customer_id, '')), '');
  v_subscription_id text := nullif(btrim(coalesce(p_stripe_subscription_id, '')), '');
  v_purchase_type text := nullif(lower(btrim(coalesce(p_purchase_type, ''))), '');
  v_item_id text := nullif(lower(btrim(coalesce(p_item_id, ''))), '');
  v_interval text := nullif(lower(btrim(coalesce(p_interval, ''))), '');
  v_status text := nullif(lower(btrim(coalesce(p_status, ''))), '');
  v_price_id text := nullif(btrim(coalesce(p_price_id, '')), '');
  v_metadata jsonb := coalesce(p_metadata, '{}'::jsonb);
begin
  if p_user_id is null then
    raise exception 'p_user_id required'
      using errcode = '22023';
  end if;

  if v_customer_id is null then
    raise exception 'p_stripe_customer_id required'
      using errcode = '22023';
  end if;

  if v_subscription_id is null then
    raise exception 'p_stripe_subscription_id required'
      using errcode = '22023';
  end if;

  if v_purchase_type not in ('subscription', 'cloud_storage') then
    raise exception 'Unsupported subscription purchase_type: %', coalesce(v_purchase_type, 'null')
      using errcode = '22023';
  end if;

  if v_item_id is null then
    raise exception 'p_item_id required'
      using errcode = '22023';
  end if;

  if v_interval is null then
    raise exception 'p_interval required'
      using errcode = '22023';
  end if;

  if v_status is null then
    raise exception 'p_status required'
      using errcode = '22023';
  end if;

  if v_purchase_type = 'subscription' and v_interval not in ('monthly', 'quarterly') then
    raise exception 'Invalid interval for subscription: %', v_interval
      using errcode = '22023';
  end if;

  if v_purchase_type = 'cloud_storage' and v_interval <> 'monthly' then
    raise exception 'Invalid interval for cloud_storage: %', v_interval
      using errcode = '22023';
  end if;

  -- Plan subscriptions remain mutually exclusive by entitled plan.
  if v_purchase_type = 'subscription'
     and tongs.billing_item_is_plan(v_item_id)
     and tongs.billing_status_entitles_access(v_status) then
    update tongs.billing_subscriptions s
    set
      status = 'replaced',
      cancel_at_period_end = true,
      canceled_at = coalesce(s.canceled_at, now()),
      updated_at = now()
    where s.user_id = p_user_id
      and s.purchase_type = 'subscription'
      and tongs.billing_item_is_plan(s.item_id)
      and s.stripe_subscription_id <> v_subscription_id
      and tongs.billing_status_entitles_access(s.status);
  end if;

  insert into tongs.billing_subscriptions (
    stripe_subscription_id,
    user_id,
    stripe_customer_id,
    purchase_type,
    item_id,
    interval,
    status,
    price_id,
    current_period_start,
    current_period_end,
    cancel_at_period_end,
    canceled_at,
    metadata_json
  )
  values (
    v_subscription_id,
    p_user_id,
    v_customer_id,
    v_purchase_type,
    v_item_id,
    v_interval,
    v_status,
    v_price_id,
    p_current_period_start,
    p_current_period_end,
    coalesce(p_cancel_at_period_end, false),
    p_canceled_at,
    v_metadata
  )
  on conflict (stripe_subscription_id) do update
  set
    user_id = excluded.user_id,
    stripe_customer_id = excluded.stripe_customer_id,
    purchase_type = excluded.purchase_type,
    item_id = excluded.item_id,
    interval = excluded.interval,
    status = excluded.status,
    price_id = coalesce(excluded.price_id, tongs.billing_subscriptions.price_id),
    current_period_start = excluded.current_period_start,
    current_period_end = excluded.current_period_end,
    cancel_at_period_end = excluded.cancel_at_period_end,
    canceled_at = excluded.canceled_at,
    metadata_json = tongs.billing_subscriptions.metadata_json || excluded.metadata_json,
    updated_at = now();
end;
$$;


ALTER FUNCTION "tongs"."upsert_billing_subscription"("p_user_id" "uuid", "p_stripe_customer_id" "text", "p_stripe_subscription_id" "text", "p_purchase_type" "text", "p_item_id" "text", "p_interval" "text", "p_status" "text", "p_price_id" "text", "p_current_period_start" timestamp with time zone, "p_current_period_end" timestamp with time zone, "p_cancel_at_period_end" boolean, "p_canceled_at" timestamp with time zone, "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."upsert_my_henry_message_state"("p_workspace_id" "uuid", "p_message_id" "text", "p_last_seen_at" timestamp with time zone, "p_last_dismissed_at" timestamp with time zone, "p_cooldown_until" timestamp with time zone, "p_increment_dismiss" integer DEFAULT 0) RETURNS TABLE("user_id" "uuid", "workspace_id" "uuid", "message_id" "text", "last_seen_at" timestamp with time zone, "last_dismissed_at" timestamp with time zone, "cooldown_until" timestamp with time zone, "dismiss_count" integer, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'tongs'
    AS $$
#variable_conflict use_column
declare
  v_message_id text;
begin
  if auth.uid() is null then
    raise exception 'Authentication required';
  end if;
  if p_workspace_id is null then
    raise exception 'workspace_id is required';
  end if;
  if not tongs.can_access_workspace(p_workspace_id) then
    raise exception 'Workspace access denied';
  end if;

  v_message_id := nullif(trim(coalesce(p_message_id, '')), '');
  if v_message_id is null then
    raise exception 'message_id is required';
  end if;

  insert into tongs.henry_message_state (
    user_id,
    workspace_id,
    message_id,
    last_seen_at,
    last_dismissed_at,
    cooldown_until,
    dismiss_count,
    updated_at
  ) values (
    auth.uid(),
    p_workspace_id,
    v_message_id,
    coalesce(p_last_seen_at, now()),
    p_last_dismissed_at,
    p_cooldown_until,
    greatest(coalesce(p_increment_dismiss, 0), 0),
    now()
  )
  on conflict on constraint henry_message_state_pkey do update
  set
    last_seen_at = coalesce(excluded.last_seen_at, tongs.henry_message_state.last_seen_at),
    last_dismissed_at = coalesce(excluded.last_dismissed_at, tongs.henry_message_state.last_dismissed_at),
    cooldown_until = coalesce(excluded.cooldown_until, tongs.henry_message_state.cooldown_until),
    dismiss_count = tongs.henry_message_state.dismiss_count + greatest(coalesce(p_increment_dismiss, 0), 0),
    updated_at = now();

  return query
  select
    p.user_id,
    p.workspace_id,
    p.message_id,
    p.last_seen_at,
    p.last_dismissed_at,
    p.cooldown_until,
    p.dismiss_count,
    p.updated_at
  from tongs.henry_message_state p
  where p.user_id = auth.uid()
    and p.workspace_id = p_workspace_id
    and p.message_id = v_message_id
  limit 1;
end;
$$;


ALTER FUNCTION "tongs"."upsert_my_henry_message_state"("p_workspace_id" "uuid", "p_message_id" "text", "p_last_seen_at" timestamp with time zone, "p_last_dismissed_at" timestamp with time zone, "p_cooldown_until" timestamp with time zone, "p_increment_dismiss" integer) OWNER TO "postgres";


