ALTER FUNCTION "tongs"."upsert_my_henry_preferences"("p_workspace_id" "uuid", "p_show_henry" boolean, "p_hide_tips" boolean, "p_muted_until" timestamp with time zone, "p_open_last_tab" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."upsert_script_draft_v1"("p_script_id" "uuid", "p_origin_spark_id" "uuid", "p_title_working" "text", "p_body_anvil" "text", "p_base_state" "tongs"."script_base_state", "p_relevance" "tongs"."script_relevance", "p_revision" integer) RETURNS TABLE("script_id" "uuid", "revision" integer, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql"
    SET "search_path" TO 'tongs', 'pg_temp'
    AS $$
begin
  if p_script_id is null then
    raise exception 'p_script_id is required';
  end if;

  if p_body_anvil is null then
    raise exception 'p_body_anvil must not be null';
  end if;

  insert into tongs.scripts (
    id,
    origin_spark_id,
    title_working,
    body_anvil,
    base_state,
    relevance,
    revision,
    owner_user_id
  )
  values (
    p_script_id,
    p_origin_spark_id,
    p_title_working,
    p_body_anvil,
    coalesce(p_base_state, 'warming'),
    coalesce(p_relevance, 'other'),
    coalesce(p_revision, 0),
    auth.uid()
  )
  on conflict (id) do update set
    origin_spark_id = excluded.origin_spark_id,
    title_working   = excluded.title_working,
    body_anvil      = excluded.body_anvil,
    base_state      = excluded.base_state,
    relevance       = excluded.relevance,
    revision        = greatest(tongs.scripts.revision, excluded.revision)
  where tongs.scripts.owner_user_id = auth.uid()
  returning id, revision, updated_at
  into script_id, revision, updated_at;

  insert into tongs.script_revisions (script_id, revision, body_anvil, owner_user_id)
  values (script_id, revision, p_body_anvil, auth.uid())
  on conflict (script_id, revision) do nothing;

  return next;
end $$;


ALTER FUNCTION "tongs"."upsert_script_draft_v1"("p_script_id" "uuid", "p_origin_spark_id" "uuid", "p_title_working" "text", "p_body_anvil" "text", "p_base_state" "tongs"."script_base_state", "p_relevance" "tongs"."script_relevance", "p_revision" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."upsert_style_profile_metrics"("p_workspace_id" "uuid", "p_avg_sentence_length" double precision, "p_sentence_length_variance" double precision, "p_pause_per_1000_words" double precision, "p_reflective_pause_ratio" double precision, "p_avg_s1_block_length" double precision, "p_avg_s2_block_length" double precision, "p_structural_intent_vector" "jsonb" DEFAULT '{}'::"jsonb", "p_adaptation_weight" double precision DEFAULT 0.15) RETURNS TABLE("workspace_id" "uuid", "user_id" "uuid", "avg_sentence_length" double precision, "sentence_length_variance" double precision, "pause_per_1000_words" double precision, "reflective_pause_ratio" double precision, "avg_s1_block_length" double precision, "avg_s2_block_length" double precision, "structural_intent_vector" "jsonb", "adaptation_weight" double precision, "scripts_analyzed_count" integer, "last_updated" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare
  v_user uuid;
  v_flags tongs.workspaces%rowtype;
  v_existing tongs.user_style_profile%rowtype;
  v_weight double precision := least(1.0, greatest(0.01, coalesce(p_adaptation_weight, 0.15)));
  v_avg_sentence_length double precision := greatest(0, coalesce(p_avg_sentence_length, 0));
  v_sentence_length_variance double precision := greatest(0, coalesce(p_sentence_length_variance, 0));
  v_pause_per_1000_words double precision := greatest(0, coalesce(p_pause_per_1000_words, 0));
  v_reflective_pause_ratio double precision := least(1.0, greatest(0, coalesce(p_reflective_pause_ratio, 0)));
  v_avg_s1_block_length double precision := greatest(0, coalesce(p_avg_s1_block_length, 0));
  v_avg_s2_block_length double precision := greatest(0, coalesce(p_avg_s2_block_length, 0));
  v_structural_intent_vector jsonb := case
    when jsonb_typeof(coalesce(p_structural_intent_vector, '{}'::jsonb)) = 'object'
      then coalesce(p_structural_intent_vector, '{}'::jsonb)
    else '{}'::jsonb
  end;
begin
  v_user := auth.uid();
  if v_user is null then
    raise exception 'Not authenticated'
      using errcode = '42501';
  end if;

  if p_workspace_id is null then
    raise exception 'workspace_id is required'
      using errcode = '22023';
  end if;

  perform tongs.assert_workspace_role(p_workspace_id, 'editor');

  select w.*
  into v_flags
  from tongs.workspaces w
  where w.id = p_workspace_id;

  if not found then
    raise exception 'Workspace not found'
      using errcode = 'P0002';
  end if;

  if coalesce(v_flags.adaptive_style_alignment_enabled, false) is false then
    raise exception 'Adaptive style alignment is disabled for this workspace'
      using errcode = '42501';
  end if;

  select p.*
  into v_existing
  from tongs.user_style_profile p
  where p.workspace_id = p_workspace_id
    and p.user_id = v_user
  for update;

  if not found then
    insert into tongs.user_style_profile (
      workspace_id,
      user_id,
      avg_sentence_length,
      sentence_length_variance,
      pause_per_1000_words,
      reflective_pause_ratio,
      avg_s1_block_length,
      avg_s2_block_length,
      structural_intent_vector,
      adaptation_weight,
      scripts_analyzed_count,
      created_at,
      last_updated
    )
    values (
      p_workspace_id,
      v_user,
      v_avg_sentence_length,
      v_sentence_length_variance,
      v_pause_per_1000_words,
      v_reflective_pause_ratio,
      v_avg_s1_block_length,
      v_avg_s2_block_length,
      v_structural_intent_vector,
      v_weight,
      1,
      now(),
      now()
    );
  else
    update tongs.user_style_profile p
    set
      avg_sentence_length = (v_existing.avg_sentence_length * (1.0 - v_weight))
        + (v_avg_sentence_length * v_weight),
      sentence_length_variance = (v_existing.sentence_length_variance * (1.0 - v_weight))
        + (v_sentence_length_variance * v_weight),
      pause_per_1000_words = (v_existing.pause_per_1000_words * (1.0 - v_weight))
        + (v_pause_per_1000_words * v_weight),
      reflective_pause_ratio = (v_existing.reflective_pause_ratio * (1.0 - v_weight))
        + (v_reflective_pause_ratio * v_weight),
      avg_s1_block_length = (v_existing.avg_s1_block_length * (1.0 - v_weight))
        + (v_avg_s1_block_length * v_weight),
      avg_s2_block_length = (v_existing.avg_s2_block_length * (1.0 - v_weight))
        + (v_avg_s2_block_length * v_weight),
      structural_intent_vector = tongs.blend_structural_intent_vector(
        v_existing.structural_intent_vector,
        v_structural_intent_vector,
        v_weight
      ),
      adaptation_weight = v_weight,
      scripts_analyzed_count = v_existing.scripts_analyzed_count + 1,
      last_updated = now()
    where p.workspace_id = p_workspace_id
      and p.user_id = v_user;
  end if;

  return query
  select
    p.workspace_id,
    p.user_id,
    p.avg_sentence_length,
    p.sentence_length_variance,
    p.pause_per_1000_words,
    p.reflective_pause_ratio,
    p.avg_s1_block_length,
    p.avg_s2_block_length,
    p.structural_intent_vector,
    p.adaptation_weight,
    p.scripts_analyzed_count,
    p.last_updated
  from tongs.user_style_profile p
  where p.workspace_id = p_workspace_id
    and p.user_id = v_user;
end;
$$;


ALTER FUNCTION "tongs"."upsert_style_profile_metrics"("p_workspace_id" "uuid", "p_avg_sentence_length" double precision, "p_sentence_length_variance" double precision, "p_pause_per_1000_words" double precision, "p_reflective_pause_ratio" double precision, "p_avg_s1_block_length" double precision, "p_avg_s2_block_length" double precision, "p_structural_intent_vector" "jsonb", "p_adaptation_weight" double precision) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."validate_bellows_recording_authority_binding"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare v_authority tongs.recording_capture_authorities%rowtype;
begin
  if tg_op='UPDATE' and old.recording_capture_authority_id is not null
     and new.recording_capture_authority_id is distinct from old.recording_capture_authority_id then
    raise exception using errcode='55000',message='Bellows recording capture authority is immutable once established';
  end if;
  if new.recording_capture_authority_id is null then return new; end if;
  select * into v_authority from tongs.recording_capture_authorities where id=new.recording_capture_authority_id;
  if not found or v_authority.venue<>'bellows' or v_authority.workspace_id<>new.workspace_id
     or v_authority.workpiece_id is distinct from new.workpiece_id then
    raise exception using errcode='23514',message='Bellows authority must identify the same workspace and workpiece with Bellows as capture venue';
  end if;
  return new;
end $$;


ALTER FUNCTION "tongs"."validate_bellows_recording_authority_binding"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."validate_bellows_session_join_link"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare
  v_session tongs.bellows_sessions%rowtype;
begin
  select *
  into v_session
  from tongs.bellows_sessions
  where id = new.session_id;

  if not found then
    raise exception 'bellows_session_not_found'
      using errcode = 'P0002';
  end if;

  if v_session.workspace_id <> new.workspace_id then
    raise exception 'bellows_join_link_workspace_mismatch'
      using errcode = '22023';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "tongs"."validate_bellows_session_join_link"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."validate_bellows_session_links"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public'
    AS $$
declare
  v_recording_workspace_id uuid;
  v_calendar_workspace_id uuid;
begin
  if new.recording_session_id is not null then
    select rs.workspace_id
    into v_recording_workspace_id
    from tongs.recording_sessions rs
    where rs.id = new.recording_session_id;

    if v_recording_workspace_id is null then
      raise exception 'bellows_recording_session_not_found'
        using errcode = 'P0002';
    end if;

    if v_recording_workspace_id <> new.workspace_id then
      raise exception 'bellows_recording_session_workspace_mismatch'
        using errcode = '22023';
    end if;
  end if;

  if new.calendar_event_id is not null then
    select ce.workspace_id
    into v_calendar_workspace_id
    from tongs.calendar_events ce
    where ce.id = new.calendar_event_id;

    if v_calendar_workspace_id is null then
      raise exception 'bellows_calendar_event_not_found'
        using errcode = 'P0002';
    end if;

    if v_calendar_workspace_id <> new.workspace_id then
      raise exception 'bellows_calendar_event_workspace_mismatch'
        using errcode = '22023';
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "tongs"."validate_bellows_session_links"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."validate_hammer_history_epoch_head_parent"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare
  v_epoch tongs.hammer_history_epochs%rowtype;
  v_parent tongs.hammer_history_epoch_heads%rowtype;
begin
  select * into v_epoch from tongs.hammer_history_epochs where epoch_id = new.epoch_id;
  if v_epoch.epoch_id is null then
    raise exception using errcode = '23503', message = 'history_epoch_head_epoch_missing';
  end if;
  if new.sequence = 1 then
    if new.parent_kind <> 'epoch_anchor' or new.parent_head_id is not null
      or new.parent_path <> v_epoch.artifact_path or new.parent_sha256 <> v_epoch.artifact_sha256
      or new.parent_registry_revision <> v_epoch.artifact_registry_revision
      or new.parent_registry_updated_at <> v_epoch.artifact_registry_updated_at
    then
      raise exception using errcode = '23514', message = 'history_epoch_head_anchor_parent_conflict';
    end if;
  else
    select * into v_parent from tongs.hammer_history_epoch_heads
    where epoch_id = new.epoch_id and sequence = new.sequence - 1;
    if v_parent.head_id is null or new.parent_kind <> 'epoch_head' or new.parent_head_id <> v_parent.head_id
      or new.parent_path <> v_parent.artifact_path or new.parent_sha256 <> v_parent.artifact_sha256
      or new.parent_registry_revision <> v_parent.artifact_registry_revision
      or new.parent_registry_updated_at <> v_parent.artifact_registry_updated_at
    then
      raise exception using errcode = '23514', message = 'history_epoch_head_parent_conflict';
    end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "tongs"."validate_hammer_history_epoch_head_parent"() OWNER TO "postgres";


