CREATE OR REPLACE FUNCTION "tongs"."validate_image_map_visual_brief"("p_brief" "jsonb") RETURNS "text"[]
    LANGUAGE "plpgsql" IMMUTABLE STRICT
    SET "search_path" TO 'pg_catalog'
    AS $$
declare invalid text[]:=array[]::text[]; key text; value jsonb; item jsonb;
begin
  if jsonb_typeof(p_brief)<>'object' or octet_length(p_brief::text)>16384 then return array['response']; end if;
  foreach key in array array['narrative_purpose','central_message','relationship_or_action','emotional_tone','setting','composition'] loop
    value:=p_brief->key;
    if jsonb_typeof(value)<>'string' or length(btrim(value#>>'{}'))=0
      or (value#>>'{}')~*'(supporting the stated narrative idea|contextually accurate environment|clear editorial hierarchy|visual evidence of (the idea|supporting)|clear, grounded,? and documentary|appropriate context|make the relationship clear|offer alternate angles|create multiple interpretations)'
    then invalid:=array_append(invalid,key); end if;
  end loop;
  foreach key in array array['primary_subjects','essential_visual_evidence','avoid'] loop
    value:=p_brief->key;
    if jsonb_typeof(value)<>'array' or jsonb_array_length(value)<1
      or (key='primary_subjects' and jsonb_array_length(value)>4)
      or (key<>'primary_subjects' and jsonb_array_length(value)>5)
    then invalid:=array_append(invalid,key); continue; end if;
    for item in select * from jsonb_array_elements(value) loop
      if jsonb_typeof(item)<>'string' or length(btrim(item#>>'{}'))=0
        or (item#>>'{}')~*'(supporting the stated narrative idea|contextually accurate environment|clear editorial hierarchy|visual evidence of (the idea|supporting)|appropriate context|offer alternate angles|create multiple interpretations)'
      then invalid:=array_append(invalid,key); exit; end if;
    end loop;
  end loop;
  if p_brief->>'visual_mode' not in('literal','documentary','editorial','metaphorical','historical_reconstruction','diagrammatic')
  then invalid:=array_append(invalid,'visual_mode'); end if;
  if jsonb_typeof(p_brief->'source_context')<>'object' or jsonb_typeof(p_brief#>'{source_context,focus}')<>'string'
    or length(btrim(p_brief#>>'{source_context,focus}'))=0
  then invalid:=array_append(invalid,'source_context'); end if;
  return(select coalesce(array_agg(distinct field),array[]::text[]) from unnest(invalid) field);
end $$;


ALTER FUNCTION "tongs"."validate_image_map_visual_brief"("p_brief" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."validate_publication_attempt_transition"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
begin
  if tg_op = 'DELETE' then raise exception 'Publication attempt identity is immutable' using errcode = '55000'; end if;
  if old.id <> new.id or old.publication_operation_id <> new.publication_operation_id or old.attempt_number <> new.attempt_number or old.created_at <> new.created_at then
    raise exception 'Publication attempt identity is immutable' using errcode = '55000';
  end if;
  if old.state = new.state then raise exception 'Publication attempt transition must advance state' using errcode = '23514'; end if;
  if not (
    (old.state = 'reserved' and new.state in('preparing_execution','blocked','recoverable_failure')) or
    (old.state = 'preparing_execution' and new.state in('submitting','blocked','recoverable_failure','confirmed_failure')) or
    (old.state = 'submitting' and new.state in('succeeded','confirmed_failure','outcome_unknown'))
  ) then raise exception 'Invalid publication attempt transition' using errcode = '23514'; end if;
  if old.side_effect_possible and not new.side_effect_possible then raise exception 'Publication side-effect evidence cannot be cleared' using errcode = '55000'; end if;
  if old.credential_generation_id is not null and old.credential_generation_id is distinct from new.credential_generation_id then raise exception 'Publication attempt credential evidence is immutable once recorded' using errcode='55000'; end if;
  if old.provider_request_id is not null and old.provider_request_id is distinct from new.provider_request_id then raise exception 'Publication provider request identity is immutable once recorded' using errcode='55000'; end if;
  if old.provider_upload_session_id is not null and old.provider_upload_session_id is distinct from new.provider_upload_session_id then raise exception 'Publication provider session identity is immutable once recorded' using errcode='55000'; end if;
  new.updated_at := now(); return new;
end; $$;


ALTER FUNCTION "tongs"."validate_publication_attempt_transition"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."validate_quench_release_decision_cardinality"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare d tongs.quench_release_decision_revisions%rowtype; v_count int; v_selected int; v_control int; v_variant int; v_allocated int; v_total int;
begin select * into d from tongs.quench_release_decision_revisions where id=new.id;
 select count(*),count(*) filter(where assignment_role='selected'),count(*) filter(where assignment_role='control'),count(*) filter(where assignment_role='variant'),count(allocation_basis_points),coalesce(sum(allocation_basis_points),0)
 into v_count,v_selected,v_control,v_variant,v_allocated,v_total from tongs.quench_release_candidate_assignments where decision_id=d.id;
 if d.intent_state='cancelled' then if d.previous_decision_id is null or v_count<>0 then raise exception 'cancelled decision requires previous decision and zero assignments' using errcode='23514'; end if;
 elsif d.decision_kind='single_candidate' then if d.intent_state<>'selected' or v_count<>1 or v_selected<>1 or v_control<>0 or v_variant<>0 or v_allocated<>0 then raise exception 'invalid single-candidate assignment set' using errcode='23514'; end if;
 elsif d.decision_kind='experiment_intent' then if d.intent_state<>'experiment_planned' or v_count<2 or v_selected<>0 or v_control<>1 or v_variant<1 or (v_allocated<>0 and (v_allocated<>v_count or v_total<>10000)) then raise exception 'invalid experiment assignment set' using errcode='23514'; end if; end if;
 return null; end $$;


ALTER FUNCTION "tongs"."validate_quench_release_decision_cardinality"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."verify_accounting_reconstruction"() RETURNS TABLE("event_id" "uuid", "currency" "text", "imbalance_micros" bigint)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare v_actor uuid := auth.uid();
begin
  if coalesce(auth.role(), '') <> 'service_role'
     and (v_actor is null or not tongs.is_platform_operator(v_actor)) then
    raise exception 'platform operator required' using errcode = '42501';
  end if;
  return query
  select entry.event_id, entry.currency, sum(entry.amount_micros)::bigint
  from tongs.accounting_journal_entries entry where entry.amount_micros <> 0
  group by entry.event_id, entry.currency having sum(entry.amount_micros) <> 0;
end;
$$;


ALTER FUNCTION "tongs"."verify_accounting_reconstruction"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."verify_bellows_capture_segment"("p_segment_id" "text", "p_expected_part_count" integer, "p_byte_length" bigint, "p_sha256" "text", "p_storage_key" "text", "p_ended_at" timestamp with time zone, "p_duration_ms" bigint) RETURNS "tongs"."bellows_segments"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'tongs', 'public', 'auth', 'storage'
    AS $$
declare v_segment tongs.bellows_segments; v_count integer; v_bytes bigint; v_object_bytes bigint;
begin
  select * into v_segment from tongs.bellows_segments where id=p_segment_id for update;
  if not found then raise exception 'bellows_segment_not_found'; end if;
  perform tongs.bellows_assert_capture_participant(v_segment.session_id,v_segment.participant_id);
  select count(*),coalesce(sum(byte_length),0) into v_count,v_bytes
    from tongs.bellows_upload_parts where segment_id=p_segment_id and upload_state='verified_received';
  if v_count<>p_expected_part_count or v_bytes<>p_byte_length then raise exception 'bellows_segment_parts_incomplete'; end if;
  select (metadata ->> 'size')::bigint into v_object_bytes
    from storage.objects where bucket_id='bellows-capture' and name=p_storage_key;
  if v_object_bytes is null then raise exception 'bellows_canonical_segment_missing'; end if;
  if v_object_bytes<>p_byte_length then raise exception 'bellows_canonical_segment_size_conflict'; end if;
  update tongs.bellows_segments
    set expected_part_count=p_expected_part_count,byte_length=p_byte_length,sha256=lower(p_sha256),
        storage_bucket='bellows-capture',storage_key=p_storage_key,ended_at=p_ended_at,
        duration_ms=p_duration_ms,integrity_state='verified',verified_at=now()
    where id=p_segment_id returning * into v_segment;
  return v_segment;
end $$;


ALTER FUNCTION "tongs"."verify_bellows_capture_segment"("p_segment_id" "text", "p_expected_part_count" integer, "p_byte_length" bigint, "p_sha256" "text", "p_storage_key" "text", "p_ended_at" timestamp with time zone, "p_duration_ms" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."verify_broll_operation_asset"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_asset_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare v_op tongs.broll_operation_receipts%rowtype; v_asset tongs.assets%rowtype;
begin
 select * into v_op from tongs.broll_operation_receipts where operation_id=p_operation_id for update;
 if not found then return jsonb_build_object('disposition','operation_not_found'); end if;
 if not tongs.has_workspace_role(v_op.workspace_id,'editor') then raise exception 'workspace editor authority required' using errcode='42501'; end if;
 if v_op.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict'); end if;
 if v_op.verified_asset_id is not null then return jsonb_build_object('disposition','replay','operation',to_jsonb(v_op)); end if;
 if v_op.state<>'provider_or_upload_completed' then return jsonb_build_object('disposition','provider_or_upload_result_required'); end if;
 select * into v_asset from tongs.assets where id=p_asset_id and workspace_id=v_op.workspace_id and workpiece_id=v_op.workpiece_id and status='ready' and mime_type like 'video/%' and content_hash is not null and ready_at is not null;
 if not found then return jsonb_build_object('disposition','verified_video_asset_required'); end if;
 update tongs.broll_operation_receipts set state='asset_verified',verified_asset_id=v_asset.id,updated_at=now() where operation_id=p_operation_id returning * into v_op;
 return jsonb_build_object('disposition','asset_verified','operation',to_jsonb(v_op),'asset',to_jsonb(v_asset));
end $$;


ALTER FUNCTION "tongs"."verify_broll_operation_asset"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_asset_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."verify_broll_operation_poster"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_poster_asset_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare v_op tongs.broll_operation_receipts%rowtype; v_asset tongs.assets%rowtype;
begin
 select * into v_op from tongs.broll_operation_receipts where operation_id=p_operation_id for update;
 if not found then return jsonb_build_object('disposition','operation_not_found'); end if;
 if not tongs.has_workspace_role(v_op.workspace_id,'editor') then raise exception 'workspace editor authority required' using errcode='42501'; end if;
 if v_op.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict'); end if;
 if v_op.verified_poster_asset_id is not null then
  if v_op.verified_poster_asset_id<>p_poster_asset_id then return jsonb_build_object('disposition','poster_asset_conflict'); end if;
  return jsonb_build_object('disposition','replay','operation',to_jsonb(v_op));
 end if;
 if v_op.state<>'asset_verified' then return jsonb_build_object('disposition','video_asset_verification_required'); end if;
 select * into v_asset from tongs.assets where id=p_poster_asset_id and workspace_id=v_op.workspace_id and workpiece_id=v_op.workpiece_id and status='ready' and asset_kind='broll_candidate_poster' and mime_type like 'image/%' and content_hash is not null and ready_at is not null;
 if not found then return jsonb_build_object('disposition','verified_poster_asset_required'); end if;
 update tongs.broll_operation_receipts set verified_poster_asset_id=v_asset.id,updated_at=now() where operation_id=p_operation_id returning * into v_op;
 return jsonb_build_object('disposition','poster_asset_verified','operation',to_jsonb(v_op),'asset',to_jsonb(v_asset));
end $$;


ALTER FUNCTION "tongs"."verify_broll_operation_poster"("p_operation_id" "text", "p_operation_fingerprint" "text", "p_poster_asset_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."verify_owner_cost_reconstruction"() RETURNS TABLE("issue_code" "text", "valuation_id" "uuid", "journal_event_id" "uuid", "details" "jsonb")
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
begin
  perform tongs._require_owner_cost_reader();
  return query
  with recognized as (
    select v.*, a.operation_id, o.financial_environment
    from tongs.owner_cost_valuations v
    join tongs.owner_cost_provider_attempts a on a.attempt_id = v.attempt_id
    join tongs.owner_cost_operations o on o.operation_id = a.operation_id
    where v.recognition_mode = 'journal_recognized'
  ), checks as (
    select 'journal_header_mismatch'::text as issue_code, r.valuation_id, r.journal_event_id,
      jsonb_build_object('source_type', e.source_type, 'source_id', e.source_id, 'environment', e.environment, 'currency', e.currency) as details
    from recognized r
    left join tongs.accounting_journal_events e on e.id = r.journal_event_id
    where e.id is null or e.source_type <> 'owner_cost_valuation' or e.source_id <> r.valuation_id::text
       or e.environment <> r.financial_environment or e.currency <> r.currency
    union all
    select 'journal_adjustment_mismatch', r.valuation_id, r.journal_event_id,
      jsonb_build_object('expected_adjustment_micros', r.journal_adjustment_micros, 'journal_expense_micros', coalesce(sum(j.amount_micros), 0))
    from recognized r
    left join tongs.accounting_journal_entries j on j.event_id = r.journal_event_id
      and j.account_code = case when r.financial_environment = 'live' then 'forge_operating_expense' else 'test_forge_operating_expense' end
    group by r.valuation_id, r.journal_event_id, r.journal_adjustment_micros
    having coalesce(sum(j.amount_micros), 0) <> r.journal_adjustment_micros
    union all
    select 'journal_unbalanced', r.valuation_id, r.journal_event_id,
      jsonb_build_object('imbalance_micros', coalesce(sum(j.amount_micros), 0))
    from recognized r
    left join tongs.accounting_journal_entries j on j.event_id = r.journal_event_id
    group by r.valuation_id, r.journal_event_id
    having coalesce(sum(j.amount_micros), 0) <> 0
    union all
    select 'cumulative_recognition_mismatch', latest.valuation_id, latest.journal_event_id,
      jsonb_build_object('latest_amount_micros', latest.amount_micros, 'cumulative_adjustments_micros', sums.total_adjustment)
    from (
      select distinct on (v.attempt_id, v.cost_component) v.*
      from recognized v order by v.attempt_id, v.cost_component, v.revision desc
    ) latest
    join (
      select v.attempt_id, v.cost_component, sum(v.journal_adjustment_micros)::bigint as total_adjustment
      from recognized v group by v.attempt_id, v.cost_component
    ) sums using (attempt_id, cost_component)
    where latest.amount_micros <> sums.total_adjustment
  )
  select c.issue_code, c.valuation_id, c.journal_event_id, c.details from checks c;
end;
$$;


ALTER FUNCTION "tongs"."verify_owner_cost_reconstruction"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."verify_thumbnail_brand_setup"("p_workspace_id" "uuid", "p_operation_id" "uuid", "p_operation_fingerprint" "text", "p_actor_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare v_op tongs.thumbnail_brand_setup_operations%rowtype;v_asset tongs.brand_asset_revisions%rowtype;v_revision tongs.brand_profile_revisions%rowtype;v_binding tongs.workpiece_brand_bindings%rowtype;v_set tongs.thumbnail_candidate_sets%rowtype;v_count int;v_thumbnail_count int;v_thumbnail_hash text;v_receipt jsonb;
begin if not exists(select 1 from tongs.workspace_members where workspace_id=p_workspace_id and user_id=p_actor_id and tongs.workspace_role_rank(role)>=tongs.workspace_role_rank('editor')) then raise exception 'Insufficient workspace role (requires editor)' using errcode='42501';end if;select * into v_op from tongs.thumbnail_brand_setup_operations where workspace_id=p_workspace_id and operation_id=p_operation_id for update;
 if not found then raise exception 'Thumbnail brand setup operation not found' using errcode='P0002';end if;if v_op.operation_fingerprint<>p_operation_fingerprint then raise exception 'Operation identity was reused with a different payload.' using errcode='22023';end if;if v_op.state='verified' then return v_op.receipt_json;end if;if v_op.state<>'binding_committed' then raise exception 'Binding stage is incomplete' using errcode='55000';end if;
 select * into v_asset from tongs.brand_asset_revisions where id=v_op.logo_asset_revision_id;select * into v_revision from tongs.brand_profile_revisions where id=v_op.profile_revision_id;select * into v_binding from tongs.workpiece_brand_bindings where workspace_id=p_workspace_id and workpiece_id=v_op.workpiece_id order by revision desc limit 1;select * into v_set from tongs.thumbnail_candidate_sets where workspace_id=p_workspace_id and workpiece_id=v_op.workpiece_id order by revision desc limit 1;select count(*) into v_count from tongs.thumbnail_candidate_set_members where candidate_set_id=v_set.id;select count(*) into v_thumbnail_count from tongs.assets where workspace_id=p_workspace_id and workpiece_id=v_op.workpiece_id and asset_kind in('thumbnail_image','thumbnail_composite');v_thumbnail_hash:=tongs.thumbnail_brand_setup_asset_hash(p_workspace_id,v_op.workpiece_id);
 if v_asset.state<>'ready' or v_asset.role<>v_op.logo_role or v_asset.content_hash<>v_op.logo_content_hash or v_asset.storage_bucket<>v_op.storage_bucket or v_asset.storage_key<>v_op.storage_key or v_revision.id<>v_op.profile_revision_id or v_revision.content_hash<>v_op.profile_content_hash or v_revision.rules_json#>>array['asset_revision_ids',v_op.logo_role]<>v_asset.id::text or v_binding.id<>v_op.resulting_binding_id or v_binding.revision<>v_op.resulting_binding_revision or v_binding.profile_revision_id<>v_revision.id or not(v_op.logo_asset_revision_id=any(v_binding.asset_revision_ids)) or v_set.id is distinct from v_op.prior_candidate_set_id or v_set.revision is distinct from v_op.prior_candidate_set_revision or coalesce(v_set.candidate_count,0)<>v_op.prior_candidate_count or v_set.content_hash is distinct from v_op.prior_candidate_content_hash or coalesce(v_count,0)<>v_op.prior_candidate_count or v_thumbnail_count<>v_op.prior_thumbnail_count or v_thumbnail_hash<>v_op.prior_thumbnail_identity_hash then
  perform set_config('tongs.thumbnail_brand_setup_transition','on',true);update tongs.thumbnail_brand_setup_operations set failed_stage='verified',failure_code='canonical_readback_mismatch',failure_message='Canonical renderer or preservation evidence does not match the setup operation.',updated_at=now() where id=v_op.id;perform set_config('tongs.thumbnail_brand_setup_transition','off',true);return tongs.thumbnail_brand_setup_json(v_op.id);
 end if;
 v_receipt:=jsonb_build_object('schema_version','forge.thumbnail-brand-setup-receipt.v1','operation_id',v_op.operation_id,'workspace_id',p_workspace_id,'workpiece_id',v_op.workpiece_id,'logo',jsonb_build_object('asset_revision_id',v_asset.id,'role',v_asset.role,'content_hash',v_asset.content_hash,'storage_bucket',v_asset.storage_bucket,'storage_key',v_asset.storage_key),'profile',jsonb_build_object('profile_id',v_op.profile_id,'revision_id',v_revision.id,'revision',v_revision.revision,'content_hash',v_revision.content_hash),'binding',jsonb_build_object('id',v_binding.id,'revision',v_binding.revision),'renderer',jsonb_build_object('style_source','brand_profile','logo_asset_revision_id',v_asset.id,'storage_bucket',v_asset.storage_bucket,'storage_key',v_asset.storage_key),'preservation',jsonb_build_object('candidate_set_id',v_set.id,'candidate_set_revision',v_set.revision,'candidate_count',coalesce(v_set.candidate_count,0),'candidate_content_hash',v_set.content_hash,'thumbnail_count',v_thumbnail_count,'thumbnail_identity_hash',v_thumbnail_hash,'existing_thumbnails_unchanged',true,'existing_candidates_unchanged',true),'verified_at',now());
 perform set_config('tongs.thumbnail_brand_setup_transition','on',true);update tongs.thumbnail_brand_setup_operations set state='verified',resolved_style_source='brand_profile',renderer_verified_logo_revision_id=v_asset.id,renderer_verified_storage_bucket=v_asset.storage_bucket,renderer_verified_storage_key=v_asset.storage_key,receipt_json=v_receipt,failed_stage=null,failure_code=null,failure_message=null,updated_at=now() where id=v_op.id;perform set_config('tongs.thumbnail_brand_setup_transition','off',true);
 return v_receipt;
end $$;


ALTER FUNCTION "tongs"."verify_thumbnail_brand_setup"("p_workspace_id" "uuid", "p_operation_id" "uuid", "p_operation_fingerprint" "text", "p_actor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."verify_thumbnail_candidate_identity"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare a tongs.assets%rowtype; r jsonb;
begin select * into a from tongs.assets where id=new.composite_asset_id and workspace_id=new.workspace_id and workpiece_id=new.workpiece_id;
 if a.id is null then raise exception 'candidate composite authority is unavailable' using errcode='22023'; end if; r:=a.metadata_json->'recipe_snapshot';
 if r is null or r->>'id'<>new.recipe_id::text or (r->>'revision')::int<>new.recipe_revision or a.metadata_json->>'recipe_snapshot_hash'<>new.recipe_hash or r->>'concept_revision_id'<>new.concept_revision_id::text or tongs.thumbnail_title_revision_identity(r)<>new.title_revision_id or (r->>'title_revision')::int<>new.title_revision then raise exception 'candidate recipe, title, or concept identity mismatch' using errcode='22023'; end if; return new; end $$;


ALTER FUNCTION "tongs"."verify_thumbnail_candidate_identity"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."verify_unified_visual_plan"("p_operation_id" "text", "p_operation_fingerprint" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
declare op tongs.unified_visual_plan_operations%rowtype; receipt jsonb;
begin
  select * into op from tongs.unified_visual_plan_operations where operation_id=p_operation_id for update;
  if not found or op.operation_fingerprint<>p_operation_fingerprint then return jsonb_build_object('disposition','operation_identity_conflict');end if;
  if op.owner_cost_attempt_id is not null then perform tongs._require_accounting_service_role(); elsif not tongs.has_workspace_role(op.workspace_id,'editor') then raise exception 'workspace editor authority required' using errcode='42501';end if;
  if op.state='verified' then return op.receipt_json;end if;
  if op.contract_version<>'forge.unified-visual-plan.v2' or op.state<>'reference_visual_plan_committed' then return jsonb_build_object('disposition','stage_conflict','state',op.state);end if;
  if not exists(select 1 from tongs.workpiece_image_map_sequences where workspace_id=op.workspace_id and workpiece_id=op.workpiece_id and current_revision_id=op.image_map_revision_id and current_revision=op.image_map_revision)
    or not exists(select 1 from tongs.broll_plan_sequences where workspace_id=op.workspace_id and workpiece_id=op.workpiece_id and current_plan_revision_id=op.broll_plan_revision_id and current_plan_revision=op.broll_plan_revision)
    or not exists(select 1 from tongs.reference_clip_plan_sequences where workspace_id=op.workspace_id and workpiece_id=op.workpiece_id and current_plan_revision_id=op.reference_clip_plan_revision_id and current_plan_revision=op.reference_clip_plan_revision)
    or not exists(select 1 from tongs.reference_visual_plan_sequences where workspace_id=op.workspace_id and workpiece_id=op.workpiece_id and current_plan_revision_id=op.reference_visual_plan_revision_id and current_plan_revision=op.reference_visual_plan_revision) then return jsonb_build_object('disposition','child_revision_no_longer_current');end if;
  receipt:=jsonb_build_object('disposition','verified','contract_version',op.contract_version,'operation_id',op.operation_id,'operation_fingerprint',op.operation_fingerprint,'script_approval_id',op.script_approval_id,'script_approval_revision',op.script_approval_revision,'script_content_hash',op.script_content_hash,'provider_response_hash',op.provider_response_hash,'child_membership_evidence',op.child_membership_evidence_json,
    'image_plan',jsonb_build_object('revision_id',op.image_map_revision_id,'revision',op.image_map_revision,'content_hash',op.image_plan_content_hash,'empty',op.image_plan_empty),
    'broll_plan',jsonb_build_object('revision_id',op.broll_plan_revision_id,'revision',op.broll_plan_revision,'content_hash',op.broll_plan_content_hash,'empty',op.broll_plan_empty),
    'reference_clip_plan',jsonb_build_object('revision_id',op.reference_clip_plan_revision_id,'revision',op.reference_clip_plan_revision,'content_hash',op.reference_clip_plan_content_hash,'empty',op.reference_clip_plan_empty),
    'reference_visual_plan',jsonb_build_object('revision_id',op.reference_visual_plan_revision_id,'revision',op.reference_visual_plan_revision,'content_hash',op.reference_visual_plan_content_hash,'empty',op.reference_visual_plan_empty));
  update tongs.unified_visual_plan_operations set state='verified',receipt_json=receipt,failed_stage=null,failure_code=null,failure_message=null,updated_at=now()where operation_id=p_operation_id;
  return receipt;
end$$;


ALTER FUNCTION "tongs"."verify_unified_visual_plan"("p_operation_id" "text", "p_operation_fingerprint" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."withdraw_private_pricing_policy"("p_publication_id" "uuid", "p_policy_id" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
declare
  v_actor uuid := auth.uid();
  v_revision integer;
begin
  if v_actor is null or not tongs.is_platform_operator(v_actor) then
    raise exception 'platform operator required' using errcode = '42501';
  end if;
  if p_publication_id is null or p_policy_id is null
     or nullif(btrim(coalesce(p_reason, '')), '') is null then
    raise exception 'invalid pricing withdrawal' using errcode = '22023';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('pricing-publication:' || p_policy_id::text, 0));
  select coalesce(max(publication_revision), 0) + 1 into v_revision
  from tongs.private_pricing_publications where policy_id = p_policy_id;
  insert into tongs.private_pricing_publications(
    id, policy_id, publication_revision, action, reason, actor_id
  ) values (p_publication_id, p_policy_id, v_revision, 'withdrawn', btrim(p_reason), v_actor);
  return jsonb_build_object('publication_id', p_publication_id,
    'publication_revision', v_revision, 'action', 'withdrawn');
end;
$$;


ALTER FUNCTION "tongs"."withdraw_private_pricing_policy"("p_publication_id" "uuid", "p_policy_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."workpiece_file_advance_revision"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
begin
  if current_setting('tongs.history_atomic_registry_tokens', true) = 'on' then
    if new.revision <> old.revision + 1 then
      raise exception using errcode='23514', message='history_atomic_registry_revision_invalid';
    end if;
  else new.revision := old.revision + 1; end if;
  return new;
end;
$$;


ALTER FUNCTION "tongs"."workpiece_file_advance_revision"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "tongs"."workpiece_file_set_updated_at"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'pg_catalog', 'tongs'
    AS $$
begin
  if current_setting('tongs.history_atomic_registry_tokens', true) <> 'on' then new.updated_at := now(); end if;
  return new;
end;
$$;


