CREATE OR REPLACE FUNCTION "tongs"."workspace_role_rank"("_role" "text") RETURNS integer
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO 'tongs', 'pg_temp'
    AS $$
  select case lower(coalesce(btrim(_role), ''))
    when 'viewer' then 10
    when 'editor' then 20
    when 'member' then 20
    when 'admin' then 30
    when 'owner' then 40
    else 0
  end;
$$;


