CREATE TABLE IF NOT EXISTS "tongs"."ai_usage_events" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "occurred_at_ms" bigint DEFAULT ((EXTRACT(epoch FROM "now"()) * (1000)::numeric))::bigint NOT NULL,
    "user_id" "uuid" NOT NULL,
    "workspace_id" "uuid",
    "workpiece_id" "uuid",
    "session_id" "uuid",
    "action_id" "text",
    "feature" "text" NOT NULL,
    "subfeature" "text",
    "model" "text" NOT NULL,
    "reasoning_effort" "text",
    "input_tokens" integer DEFAULT 0 NOT NULL,
    "output_tokens" integer DEFAULT 0 NOT NULL,
    "total_tokens" integer DEFAULT 0 NOT NULL,
    "estimated_cost_usd" numeric(12,6) DEFAULT 0 NOT NULL,
    "actual_cost_usd" numeric(12,6) DEFAULT 0 NOT NULL,
    "billable_tokens" integer DEFAULT 0 NOT NULL,
    "trigger" "text" NOT NULL,
    "status" "text" NOT NULL,
    "provider_request_id" "text",
    "lane" "text" DEFAULT 'forge'::"text" NOT NULL,
    "provider" "text",
    "correlation_id" "text",
    "policy_enforced" boolean DEFAULT true NOT NULL,
    "key_source" "text" DEFAULT 'forge'::"text" NOT NULL,
    "effective_ai_key_source" "text",
    "key_resolution_status" "text",
    "effective_billing_lane" "text",
    "policy_decision_type" "text",
    "policy_reason_code" "text",
    "policy_snapshot" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    CONSTRAINT "ai_usage_events_actual_cost_nonnegative" CHECK (("actual_cost_usd" >= (0)::numeric)),
    CONSTRAINT "ai_usage_events_billable_tokens_nonnegative" CHECK (("billable_tokens" >= 0)),
    CONSTRAINT "ai_usage_events_effective_ai_key_source_check" CHECK ((("effective_ai_key_source" IS NULL) OR ("effective_ai_key_source" = ANY (ARRAY['forge_managed'::"text", 'user_byo'::"text", 'org_shared'::"text"])))),
    CONSTRAINT "ai_usage_events_effective_billing_lane_check" CHECK ((("effective_billing_lane" IS NULL) OR ("effective_billing_lane" = ANY (ARRAY['forge'::"text", 'byo'::"text"])))),
    CONSTRAINT "ai_usage_events_estimated_cost_nonnegative" CHECK (("estimated_cost_usd" >= (0)::numeric)),
    CONSTRAINT "ai_usage_events_feature_nonempty" CHECK (("btrim"("feature") <> ''::"text")),
    CONSTRAINT "ai_usage_events_input_tokens_nonnegative" CHECK (("input_tokens" >= 0)),
    CONSTRAINT "ai_usage_events_key_resolution_status_check" CHECK ((("key_resolution_status" IS NULL) OR ("key_resolution_status" = ANY (ARRAY['available'::"text", 'missing_required_key'::"text", 'provider_not_supported'::"text", 'policy_denied'::"text"])))),
    CONSTRAINT "ai_usage_events_key_source_check" CHECK (("key_source" = ANY (ARRAY['forge'::"text", 'byo'::"text", 'org_shared'::"text"]))),
    CONSTRAINT "ai_usage_events_lane_check" CHECK (("lane" = ANY (ARRAY['forge'::"text", 'byo'::"text"]))),
    CONSTRAINT "ai_usage_events_model_nonempty" CHECK (("btrim"("model") <> ''::"text")),
    CONSTRAINT "ai_usage_events_output_tokens_nonnegative" CHECK (("output_tokens" >= 0)),
    CONSTRAINT "ai_usage_events_policy_decision_type_check" CHECK ((("policy_decision_type" IS NULL) OR ("policy_decision_type" = ANY (ARRAY['ALLOW'::"text", 'SOFT_DENY'::"text", 'HARD_DENY'::"text"])))),
    CONSTRAINT "ai_usage_events_policy_snapshot_object_check" CHECK (("jsonb_typeof"("policy_snapshot") = 'object'::"text")),
    CONSTRAINT "ai_usage_events_status_check" CHECK (("status" = ANY (ARRAY['success'::"text", 'error'::"text"]))),
    CONSTRAINT "ai_usage_events_total_tokens_nonnegative" CHECK (("total_tokens" >= 0)),
    CONSTRAINT "ai_usage_events_trigger_check" CHECK (("trigger" = ANY (ARRAY['user'::"text", 'system'::"text"])))
);


ALTER TABLE "tongs"."ai_usage_events" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "tongs"."ai_usage_ledger" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
