    "actual_cost_usd" numeric(12,4),
    "decision_type" "tongs"."ai_decision_type" NOT NULL,
    "reason_code" "text",
    "allowed" boolean GENERATED ALWAYS AS (("decision_type" = 'ALLOW'::"tongs"."ai_decision_type")) STORED,
    "fallback_available" boolean DEFAULT false NOT NULL,
    "fallback_used" boolean DEFAULT false NOT NULL,
    "fallback_from" "tongs"."ai_funding_source",
    "fallback_to" "tongs"."ai_funding_source",
    "request_id" "text",
    "effective_policy_snapshot" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "ai_usage_ledger_actual_cost_usd_check" CHECK ((("actual_cost_usd" IS NULL) OR ("actual_cost_usd" >= (0)::numeric))),
    CONSTRAINT "ai_usage_ledger_effective_policy_snapshot_object" CHECK (("jsonb_typeof"("effective_policy_snapshot") = 'object'::"text")),
    CONSTRAINT "ai_usage_ledger_estimated_cost_usd_check" CHECK ((("estimated_cost_usd" IS NULL) OR ("estimated_cost_usd" >= (0)::numeric)))
);


ALTER TABLE "tongs"."ai_usage_ledger" OWNER TO "postgres";


