);


ALTER TABLE "tongs"."anvil_capture_executions" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "tongs"."recording_capture_authorities" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "__forge_dropped_attnum_2" boolean,
    "workspace_id" "uuid" NOT NULL,
    "workpiece_id" "uuid" NOT NULL,
    "recording_session_id" "uuid",
    "ready_transition_id" "uuid",
    "script_path" "text",
    "script_revision" bigint,
    "script_hash" "text",
    "operation_key" "text" NOT NULL,
    "provenance" "text" NOT NULL,
    "established_by" "uuid" NOT NULL,
    "established_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "script_approval_id" "uuid",
    "script_approval_revision" bigint,
    "script_approval_hash" "text",
    "venue" "text" NOT NULL,
    "script_binding_kind" "text" NOT NULL,
    "request_fingerprint" "text" NOT NULL,
    "preflight_report_id" "uuid",
    "preflight_report_revision" bigint,
    "preflight_script_hash" "text",
    "research_artifact_id" "uuid",
    "research_artifact_hash" "text",
    CONSTRAINT "anvil_capture_authorities_operation_key_check" CHECK ((("length"("btrim"("operation_key")) >= 8) AND ("length"("btrim"("operation_key")) <= 200))),
    CONSTRAINT "anvil_capture_authorities_provenance_check" CHECK (("provenance" = ANY (ARRAY['live_established'::"text", 'completion_backfill'::"text"]))),
    CONSTRAINT "anvil_capture_authorities_script_hash_check" CHECK (("script_hash" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "anvil_capture_authorities_script_path_check" CHECK (("script_path" = 'script/script.md'::"text")),
    CONSTRAINT "anvil_capture_authorities_script_revision_check" CHECK (("script_revision" > 0)),
    CONSTRAINT "capture_approval_tuple_shape" CHECK (((("script_approval_id" IS NULL) AND ("script_approval_revision" IS NULL) AND ("script_approval_hash" IS NULL)) OR (("script_approval_id" IS NOT NULL) AND ("script_approval_revision" > 0) AND ("script_approval_hash" ~ '^[0-9a-f]{64}$'::"text")))),
    CONSTRAINT "recording_capture_script_binding_check" CHECK (((("script_binding_kind" = 'none'::"text") AND ("ready_transition_id" IS NULL) AND ("script_path" IS NULL) AND ("script_revision" IS NULL) AND ("script_hash" IS NULL) AND ("script_approval_id" IS NULL) AND ("script_approval_revision" IS NULL) AND ("script_approval_hash" IS NULL)) OR (("script_binding_kind" = 'approved_canonical_script'::"text") AND ("ready_transition_id" IS NOT NULL) AND ("script_path" = 'script/script.md'::"text") AND ("script_revision" > 0) AND ("script_hash" ~ '^[0-9a-f]{64}$'::"text") AND ("script_approval_id" IS NOT NULL) AND ("script_approval_revision" > 0) AND ("script_approval_hash" = "script_hash")))),
    CONSTRAINT "recording_capture_venue_check" CHECK (("venue" = ANY (ARRAY['anvil'::"text", 'bellows'::"text"])))
);


ALTER TABLE "tongs"."recording_capture_authorities" OWNER TO "postgres";


CREATE OR REPLACE VIEW "tongs"."anvil_capture_authorities" WITH ("security_invoker"='true') AS
 SELECT "a"."id",
    "a"."workspace_id",
    "a"."workpiece_id",
    "a"."recording_session_id",
    "a"."ready_transition_id",
    "a"."script_path",
    "a"."script_revision",
    "a"."script_hash",
    "a"."operation_key",
    "a"."provenance",
    "a"."established_by",
    "a"."established_at",
    "a"."script_approval_id",
    "a"."script_approval_revision",
    "a"."script_approval_hash",
    "a"."venue",
    "a"."script_binding_kind",
    "a"."request_fingerprint",
    "e"."execution_id" AS "capture_session_id"
   FROM ("tongs"."recording_capture_authorities" "a"
     JOIN "tongs"."anvil_capture_executions" "e" ON (("e"."recording_capture_authority_id" = "a"."id")))
  WHERE ("a"."venue" = 'anvil'::"text");


ALTER VIEW "tongs"."anvil_capture_authorities" OWNER TO "postgres";


