    "maximum_attempts" smallint NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "bounded_provider_quote_request_b_protocol_overhead_tokens_check" CHECK (("protocol_overhead_tokens" >= 0)),
