    CONSTRAINT "broll_provider_completion_hash_shape" CHECK ((("provider_completed_hash" IS NULL) OR ("provider_completed_hash" ~ '^[0-9a-f]{64}$'::"text"))),
    CONSTRAINT "broll_provider_completion_pair" CHECK ((("provider_completed_json" IS NULL) = ("provider_completed_hash" IS NULL))),
    CONSTRAINT "broll_provider_submission_hash_shape" CHECK ((("provider_submission_hash" IS NULL) OR ("provider_submission_hash" ~ '^[0-9a-f]{64}$'::"text"))),
    CONSTRAINT "broll_provider_submission_pair" CHECK ((("provider_submission_json" IS NULL) = ("provider_submission_hash" IS NULL))),
    CONSTRAINT "broll_provider_task_shape" CHECK ((("provider_task_id" IS NULL) OR (("length"("provider_task_id") >= 8) AND ("length"("provider_task_id") <= 200)))),
    CONSTRAINT "broll_submission_attempt_shape" CHECK (((("state" <> ALL (ARRAY['submitting'::"text", 'submission_unknown'::"text", 'provider_submitted'::"text", 'provider_completed'::"text"])) OR (("submission_attempt_id" IS NOT NULL) AND ("submitting_at" IS NOT NULL))) AND (("state" <> ALL (ARRAY['provider_submitted'::"text", 'provider_completed'::"text"])) OR (("provider_task_id" IS NOT NULL) AND ("provider_submission_json" IS NOT NULL) AND ("provider_submitted_at" IS NOT NULL)))))
