CREATE OR REPLACE VIEW "tongs"."canonical_asset_ambiguous_evidence_report" WITH ("security_invoker"='true') AS
 SELECT "a"."workspace_id",
    'same_path_different_content'::"text" AS "ambiguity_kind",
    "a"."path" AS "evidence_key",
    NULL::"text" AS "source_surface",
    "array_agg"("a"."id" ORDER BY "a"."created_at") AS "candidate_asset_ids",
    "array_agg"(DISTINCT "a"."content_hash") FILTER (WHERE ("a"."content_hash" IS NOT NULL)) AS "content_hashes",
    "count"(*) AS "reference_count"
   FROM "tongs"."assets" "a"
  GROUP BY "a"."workspace_id", "a"."path"
 HAVING ("count"(DISTINCT "a"."content_hash") FILTER (WHERE ("a"."content_hash" IS NOT NULL)) > 1)
UNION ALL
 SELECT "r"."workspace_id",
    "r"."classification" AS "ambiguity_kind",
    COALESCE((("r"."storage_bucket_assertion" || '/'::"text") || "r"."storage_key_assertion"), "r"."path_assertion", "r"."legacy_identifier", "r"."source_record_key") AS "evidence_key",
    "r"."source_surface",
    ARRAY[]::"uuid"[] AS "candidate_asset_ids",
        CASE
            WHEN ("r"."content_hash_assertion" IS NULL) THEN ARRAY[]::"text"[]
            ELSE ARRAY["r"."content_hash_assertion"]
        END AS "content_hashes",
    (1)::bigint AS "reference_count"
   FROM "tongs"."asset_legacy_reference_evidence" "r"
  WHERE ("r"."classification" = ANY (ARRAY['legacy_unresolved'::"text", 'conflicting_evidence'::"text"]));


ALTER VIEW "tongs"."canonical_asset_ambiguous_evidence_report" OWNER TO "postgres";


