    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "credential_lifecycle_records_activation_deployment_sha_check" CHECK ((("activation_deployment_sha" IS NULL) OR ("activation_deployment_sha" ~ '^[0-9a-f]{7,64}$'::"text"))),
    CONSTRAINT "credential_lifecycle_records_affected_capability_check" CHECK ((("length"("btrim"("affected_capability")) >= 3) AND ("length"("btrim"("affected_capability")) <= 200))),
    CONSTRAINT "credential_lifecycle_records_check" CHECK ((("replacement_credential_id" IS NULL) OR ("replacement_credential_id" <> "credential_id"))),
    CONSTRAINT "credential_lifecycle_records_check1" CHECK ((("expires_at" IS NULL) OR ("provider_created_at" IS NULL) OR ("expires_at" > "provider_created_at"))),
    CONSTRAINT "credential_lifecycle_records_check2" CHECK (((("expires_at" IS NULL) AND ("rotation_due_at" IS NULL)) OR (("expires_at" IS NOT NULL) AND ("rotation_due_at" = ("expires_at" - "rotation_lead"))))),
    CONSTRAINT "credential_lifecycle_records_check3" CHECK ((("revocation_confirmed_at" IS NULL) OR "revocation_required")),
    CONSTRAINT "credential_lifecycle_records_check4" CHECK ((("lifecycle_status" <> 'revoked'::"text") OR ("revocation_confirmed_at" IS NOT NULL))),
    CONSTRAINT "credential_lifecycle_records_configuration_variable_name_check" CHECK (("configuration_variable_name" ~ '^[A-Z][A-Z0-9_]{2,127}$'::"text")),
    CONSTRAINT "credential_lifecycle_records_credential_identity_hash_check" CHECK ((("credential_identity_hash" IS NULL) OR ("credential_identity_hash" ~ '^[0-9a-f]{64}$'::"text"))),
    CONSTRAINT "credential_lifecycle_records_credential_purpose_check" CHECK ((("length"("btrim"("credential_purpose")) >= 3) AND ("length"("btrim"("credential_purpose")) <= 200))),
    CONSTRAINT "credential_lifecycle_records_financial_environment_check" CHECK (("financial_environment" = ANY (ARRAY['live'::"text", 'test'::"text"]))),
    CONSTRAINT "credential_lifecycle_records_lifecycle_status_check" CHECK (("lifecycle_status" = ANY (ARRAY['planned'::"text", 'active'::"text", 'rotation_due'::"text", 'replacement_ready'::"text", 'replacement_active'::"text", 'revocation_pending'::"text", 'revoked'::"text", 'expired'::"text", 'disabled'::"text"]))),
    CONSTRAINT "credential_lifecycle_records_metadata_json_check" CHECK ((("jsonb_typeof"("metadata_json") = 'object'::"text") AND "tongs"."_credential_lifecycle_metadata_safe"("metadata_json"))),
    CONSTRAINT "credential_lifecycle_records_provider_check" CHECK ((("length"("btrim"("provider")) >= 2) AND ("length"("btrim"("provider")) <= 80))),
    CONSTRAINT "credential_lifecycle_records_rotation_lead_check" CHECK (("rotation_lead" > '00:00:00'::interval)),
    CONSTRAINT "credential_lifecycle_records_runtime_environment_check" CHECK (("runtime_environment" = ANY (ARRAY['production'::"text", 'preview'::"text", 'development'::"text"])))
);

