    "transition_id" "uuid",
    "publish_evidence" "jsonb",
    "script_approval_id" "uuid",
    "script_approval_revision" bigint,
    "script_approval_hash" "text",
    "preflight_report_id" "uuid",
    "preflight_report_revision" bigint,
    "preflight_script_hash" "text",
    "research_artifact_id" "uuid",
    "research_artifact_hash" "text",
    CONSTRAINT "ready_meta_approval_tuple_shape" CHECK (((("script_approval_id" IS NULL) AND ("script_approval_revision" IS NULL) AND ("script_approval_hash" IS NULL)) OR (("script_approval_id" IS NOT NULL) AND ("script_approval_revision" > 0) AND ("script_approval_hash" ~ '^[0-9a-f]{64}$'::"text")))),
    CONSTRAINT "ready_meta_preflight_shape" CHECK (((("preflight_report_id" IS NULL) AND ("preflight_report_revision" IS NULL) AND ("preflight_script_hash" IS NULL)) OR (("preflight_report_id" IS NOT NULL) AND ("preflight_report_revision" > 0) AND ("preflight_script_hash" ~ '^[0-9a-f]{64}$'::"text")))),
    CONSTRAINT "workpiece_ready_script_meta_hash_check" CHECK ((("script_hash" IS NULL) OR ("script_hash" ~ '^[0-9a-f]{64}$'::"text"))),
    CONSTRAINT "workpiece_ready_script_meta_path_check" CHECK ((("length"("btrim"("script_path")) > 0) AND ("left"("script_path", 1) <> '/'::"text") AND (POSITION(('..'::"text") IN ("script_path")) = 0) AND (POSITION(("chr"(92)) IN ("script_path")) = 0))),
    CONSTRAINT "workpiece_ready_script_meta_revision_positive" CHECK ((("script_revision" IS NULL) OR ("script_revision" > 0)))
);


