CREATE OR REPLACE VIEW "tongs"."current_workpiece_ready_scripts" WITH ("security_invoker"='true') AS
 SELECT "m"."workspace_id",
    "m"."workpiece_id",
    "m"."script_path",
    "m"."script_revision",
    "m"."script_hash",
    "m"."transition_id",
    "m"."marked_ready_by",
    "m"."marked_ready_at",
    "m"."publish_evidence",
    "a"."created_at" AS "script_updated_at",
    "m"."script_approval_id",
    "m"."script_approval_revision",
    "m"."script_approval_hash",
    "a"."created_at" AS "script_approved_at",
    "m"."preflight_report_id",
    "m"."preflight_report_revision",
    "m"."preflight_script_hash",
    "m"."research_artifact_id",
    "m"."research_artifact_hash",
    "r"."reviewed_at" AS "preflight_reviewed_at"
   FROM (((((("tongs"."workpiece_ready_script_meta" "m"
     JOIN "tongs"."episodes" "e" ON ((("e"."id" = "m"."workpiece_id") AND ("e"."workspace_id" = "m"."workspace_id"))))
     JOIN "tongs"."workpiece_files" "f" ON ((("f"."workpiece_id" = "m"."workpiece_id") AND ("f"."path" = "m"."script_path") AND ("f"."revision" = "m"."script_revision") AND ("lower"("f"."hash_value") = "m"."script_hash"))))
     JOIN "tongs"."script_approval_revisions" "a" ON ((("a"."id" = "m"."script_approval_id") AND ("a"."workspace_id" = "m"."workspace_id") AND ("a"."workpiece_id" = "m"."workpiece_id") AND ("a"."approval_revision" = "m"."script_approval_revision") AND ("a"."source_file_path" = "m"."script_path") AND ("a"."source_file_revision" = "m"."script_revision") AND ("a"."script_content_hash" = "m"."script_approval_hash"))))
     LEFT JOIN "tongs"."script_approval_preflight_bindings" "b" ON ((("b"."script_approval_id" = "a"."id") AND ("b"."preflight_report_id" = "m"."preflight_report_id") AND ("b"."preflight_report_revision" = "m"."preflight_report_revision") AND ("b"."preflight_script_hash" = "m"."preflight_script_hash"))))
     LEFT JOIN "tongs"."hearth_editorial_preflight_reports" "p" ON ((("p"."id" = "b"."preflight_report_id") AND ("p"."workspace_id" = "m"."workspace_id") AND ("p"."workpiece_id" = "m"."workpiece_id"))))
     LEFT JOIN "tongs"."hearth_preflight_review_receipts" "r" ON (("r"."report_id" = "p"."id")))
  WHERE (("e"."archived_at" IS NULL) AND ("m"."transition_id" IS NOT NULL));


ALTER VIEW "tongs"."current_workpiece_ready_scripts" OWNER TO "postgres";


COMMENT ON VIEW "tongs"."current_workpiece_ready_scripts" IS 'Ready contracts whose stored revision/hash exactly match the current canonical script file.';



