CREATE OR REPLACE VIEW "tongs"."current_workpiece_recorded_takes" WITH ("security_invoker"='true') AS
 SELECT "c"."workspace_id",
    "c"."workpiece_id",
    "e"."execution_id" AS "capture_session_id",
    "c"."id" AS "completion_id",
    "k"."id" AS "keep_id",
    "a"."ready_transition_id",
    "a"."script_revision",
    "a"."script_hash",
    "c"."media_path",
    "c"."media_revision",
    "c"."media_hash",
    "c"."completion_evidence",
    "k"."decision_evidence",
    "c"."created_at" AS "completed_at",
    "k"."created_at" AS "kept_at",
    "c"."completed_by",
    "k"."kept_by",
    'anvil_capture'::"text" AS "source_kind",
    "c"."id" AS "source_authority_id",
    "c"."media_content_type",
    "c"."media_bytes",
    "a"."recording_session_id"
   FROM (((("tongs"."anvil_recording_completion_requests" "c"
     JOIN "tongs"."recording_capture_authorities" "a" ON (("a"."id" = "c"."capture_authority_id")))
     JOIN "tongs"."recording_media_verification_receipts" "v" ON (("v"."id" = "c"."media_verification_receipt_id")))
     LEFT JOIN "tongs"."anvil_capture_executions" "e" ON (("e"."recording_capture_authority_id" = "a"."id")))
     LEFT JOIN "tongs"."anvil_recording_keep_requests" "k" ON (("k"."completion_id" = "c"."id")))
  WHERE ("k"."id" IS NOT NULL)
UNION ALL
 SELECT "h"."workspace_id",
    "h"."workpiece_id",
    NULL::"uuid" AS "capture_session_id",
    NULL::"uuid" AS "completion_id",
    "h"."id" AS "keep_id",
    NULL::"uuid" AS "ready_transition_id",
    NULL::bigint AS "script_revision",
    NULL::"text" AS "script_hash",
    "h"."media_path",
    NULL::bigint AS "media_revision",
    "h"."verified_media_hash" AS "media_hash",
    ("h"."provenance" || "jsonb_build_object"('artifact_validation', "jsonb_build_object"('content_type', "h"."verified_media_content_type", 'bytes', "h"."verified_media_bytes", 'sha256', "h"."verified_media_hash", 'path', "h"."media_path", 'ok', true))) AS "completion_evidence",
    "jsonb_build_object"('schema', 'hammer.recording-import-acceptance.v1', 'decision', 'keep', 'import_id', "h"."id", 'deliberate_attach', (COALESCE(("h"."provenance" ->> 'deliberate_attach'::"text"), 'false'::"text") = 'true'::"text")) AS "decision_evidence",
    "h"."committed_at" AS "completed_at",
    "h"."committed_at" AS "kept_at",
    "h"."imported_by" AS "completed_by",
    "h"."imported_by" AS "kept_by",
    'hammer_import'::"text" AS "source_kind",
    "h"."id" AS "source_authority_id",
    "h"."verified_media_content_type" AS "media_content_type",
    "h"."verified_media_bytes" AS "media_bytes",
    NULL::"uuid" AS "recording_session_id"
   FROM "tongs"."hammer_recording_import_requests" "h"
  WHERE ("h"."state" = 'committed'::"text");


ALTER VIEW "tongs"."current_workpiece_recorded_takes" OWNER TO "postgres";


COMMENT ON VIEW "tongs"."current_workpiece_recorded_takes" IS 'Canonical recorded truth: an exact Ready-bound script and validated media completion followed by an explicit keep decision.';



