    CONSTRAINT "image_map_revisions_check2" CHECK (((("revision" = 1) AND ("previous_revision_id" IS NULL)) OR (("revision" > 1) AND ("previous_revision_id" IS NOT NULL) AND ("previous_revision" = ("revision" - 1))))),
    CONSTRAINT "image_map_revisions_check3" CHECK ((("provenance_state" = 'provenance_unknown'::"text") OR (("source_script_approval_id" IS NOT NULL) AND ("source_script_content_hash" IS NOT NULL)))),
    CONSTRAINT "image_map_revisions_document_content_hash_check" CHECK (("document_content_hash" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "image_map_revisions_document_json_check" CHECK (("jsonb_typeof"("document_json") = 'object'::"text")),
    CONSTRAINT "image_map_revisions_immutable_revision_hash_check" CHECK (("immutable_revision_hash" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "image_map_revisions_provenance_state_check" CHECK (("provenance_state" = ANY (ARRAY['current'::"text", 'stale'::"text", 'unresolved'::"text", 'provenance_unknown'::"text"]))),
    CONSTRAINT "image_map_revisions_revision_check" CHECK (("revision" > 0)),
    CONSTRAINT "image_map_revisions_semantic_state_hash_check" CHECK (("semantic_state_hash" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "image_map_revisions_source_script_content_hash_check" CHECK ((("source_script_content_hash" IS NULL) OR ("source_script_content_hash" ~ '^[0-9a-f]{64}$'::"text")))
);


ALTER TABLE "tongs"."image_map_revisions" OWNER TO "postgres";


COMMENT ON TABLE "tongs"."image_map_revisions" IS 'Immutable image-map documents with canonical script provenance and per-entry anchor assessments.';



COMMENT ON COLUMN "tongs"."image_map_revisions"."semantic_state_hash" IS 'Canonical semantic state hash used for no-change detection; excludes immutable revision identity.';



COMMENT ON COLUMN "tongs"."image_map_revisions"."immutable_revision_hash" IS 'Unique immutable revision identity including lineage, operation identity, and creation boundary.';



