    CONSTRAINT "pricing_discrepancies_discrepancy_type_check" CHECK (("discrepancy_type" = ANY (ARRAY['customer_ceiling_overrun'::"text", 'wholesale_ceiling_overrun'::"text"]))),
    CONSTRAINT "pricing_discrepancies_evidence_json_check" CHECK (("jsonb_typeof"("evidence_json") = 'object'::"text")),
    CONSTRAINT "pricing_discrepancies_quoted_ceiling_micros_check" CHECK (("quoted_ceiling_micros" >= 0))
);


ALTER TABLE "tongs"."pricing_discrepancies" OWNER TO "postgres";


