CREATE TABLE IF NOT EXISTS "tongs"."private_pricing_cost_components" (
    "pricing_revision_id" "uuid" NOT NULL,
    "ordinal" smallint NOT NULL,
    "component_code" "text" NOT NULL,
    "component_kind" "text" NOT NULL,
    "credential_funding" "text" NOT NULL,
    "provider_label" "text" NOT NULL,
    "success_ceiling_micros" bigint NOT NULL,
    "failure_ceiling_micros" bigint NOT NULL,
    "cost_policy_revision" "text" NOT NULL,
    "tail_policy" "text" NOT NULL,
    "tail_policy_details" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    CONSTRAINT "private_pricing_cost_components_check" CHECK ((("failure_ceiling_micros" >= 0) AND ("failure_ceiling_micros" <= "success_ceiling_micros"))),
    CONSTRAINT "private_pricing_cost_components_check1" CHECK ((("credential_funding" <> 'byo_customer'::"text") OR (("success_ceiling_micros" = 0) AND ("failure_ceiling_micros" = 0)))),
    CONSTRAINT "private_pricing_cost_components_check2" CHECK ((("tail_policy" <> 'included_until'::"text") OR (NULLIF(("tail_policy_details" ->> 'included_until'::"text"), ''::"text") IS NOT NULL))),
    CONSTRAINT "private_pricing_cost_components_component_code_check" CHECK ((("length"("btrim"("component_code")) >= 2) AND ("length"("btrim"("component_code")) <= 120))),
    CONSTRAINT "private_pricing_cost_components_component_kind_check" CHECK (("component_kind" = ANY (ARRAY['direct_provider'::"text", 'supporting_provider'::"text", 'compute'::"text", 'storage'::"text", 'bandwidth_egress'::"text", 'transactional_notification'::"text", 'payment_processing'::"text", 'retention_tail'::"text", 'contingency'::"text"]))),
    CONSTRAINT "private_pricing_cost_components_cost_policy_revision_check" CHECK ((("length"("btrim"("cost_policy_revision")) >= 1) AND ("length"("btrim"("cost_policy_revision")) <= 160))),
    CONSTRAINT "private_pricing_cost_components_credential_funding_check" CHECK (("credential_funding" = ANY (ARRAY['forge'::"text", 'byo_customer'::"text"]))),
    CONSTRAINT "private_pricing_cost_components_ordinal_check" CHECK (("ordinal" > 0)),
    CONSTRAINT "private_pricing_cost_components_provider_label_check" CHECK ((("length"("btrim"("provider_label")) >= 2) AND ("length"("btrim"("provider_label")) <= 120))),
    CONSTRAINT "private_pricing_cost_components_success_ceiling_micros_check" CHECK (("success_ceiling_micros" >= 0)),
    CONSTRAINT "private_pricing_cost_components_tail_policy_check" CHECK (("tail_policy" = ANY (ARRAY['none'::"text", 'included_until'::"text", 'plan_funded'::"text", 'recurring_metered'::"text"]))),
    CONSTRAINT "private_pricing_cost_components_tail_policy_details_check" CHECK (("jsonb_typeof"("tail_policy_details") = 'object'::"text"))
);


ALTER TABLE "tongs"."private_pricing_cost_components" OWNER TO "postgres";


