    CONSTRAINT "private_pricing_policies_policy_code_check" CHECK ((("length"("btrim"("policy_code")) >= 3) AND ("length"("btrim"("policy_code")) <= 120))),
    CONSTRAINT "private_pricing_policies_scope_kind_check" CHECK (("scope_kind" = ANY (ARRAY['default'::"text", 'provider'::"text", 'sku'::"text"])))
);


ALTER TABLE "tongs"."private_pricing_policies" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "tongs"."private_pricing_publications" (
    "id" "uuid" NOT NULL,
