    CONSTRAINT "private_pricing_publications_action_check" CHECK (("action" = ANY (ARRAY['published'::"text", 'withdrawn'::"text"]))),
    CONSTRAINT "private_pricing_publications_check" CHECK (((("action" = 'published'::"text") AND ("pricing_revision_id" IS NOT NULL)) OR (("action" = 'withdrawn'::"text") AND ("pricing_revision_id" IS NULL)))),
    CONSTRAINT "private_pricing_publications_publication_revision_check" CHECK (("publication_revision" > 0)),
    CONSTRAINT "private_pricing_publications_reason_check" CHECK ((NULLIF("btrim"("reason"), ''::"text") IS NOT NULL))
);


ALTER TABLE "tongs"."private_pricing_publications" OWNER TO "postgres";


COMMENT ON TABLE "tongs"."private_pricing_publications" IS 'Owner-only append-only publication pointer. Customer execution still requires independent paid-execution activation.';



