CREATE TABLE IF NOT EXISTS "tongs"."publication_attempts" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "publication_operation_id" "uuid" NOT NULL,
    "attempt_number" integer NOT NULL,
    "state" "text" NOT NULL,
    "side_effect_possible" boolean DEFAULT false NOT NULL,
    "credential_generation_id" "uuid",
    "adapter_id" "text",
    "adapter_version" "text",
    "provider_request_id" "text",
    "provider_upload_session_id" "text",
    "external_object_id" "text",
    "external_url" "text",
    "failure_code" "text",
    "failure_detail_json" "jsonb",
    "started_at" timestamp with time zone,
    "finished_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "publication_attempts_attempt_number_check" CHECK (("attempt_number" > 0)),
    CONSTRAINT "publication_attempts_check" CHECK ((("state" = ANY (ARRAY['succeeded'::"text", 'confirmed_failure'::"text", 'recoverable_failure'::"text", 'blocked'::"text", 'outcome_unknown'::"text"])) = ("finished_at" IS NOT NULL))),
    CONSTRAINT "publication_attempts_check1" CHECK (((NOT "side_effect_possible") OR ("state" = ANY (ARRAY['submitting'::"text", 'succeeded'::"text", 'confirmed_failure'::"text", 'outcome_unknown'::"text"])))),
    CONSTRAINT "publication_attempts_check2" CHECK ((("state" <> 'outcome_unknown'::"text") OR "side_effect_possible")),
    CONSTRAINT "publication_attempts_failure_detail_json_check" CHECK ((("failure_detail_json" IS NULL) OR ("jsonb_typeof"("failure_detail_json") = 'object'::"text"))),
    CONSTRAINT "publication_attempts_state_check" CHECK (("state" = ANY (ARRAY['reserved'::"text", 'preparing_execution'::"text", 'submitting'::"text", 'succeeded'::"text", 'confirmed_failure'::"text", 'recoverable_failure'::"text", 'blocked'::"text", 'outcome_unknown'::"text"])))
);


ALTER TABLE "tongs"."publication_attempts" OWNER TO "postgres";


COMMENT ON TABLE "tongs"."publication_attempts" IS 'Sequential execution attempts beneath one immutable publication operation; outcome_unknown forbids blind retry.';



CREATE TABLE IF NOT EXISTS "tongs"."publication_operations" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
