    CONSTRAINT "publication_operations_authority_fingerprint_check" CHECK (("authority_fingerprint" ~ '^[a-f0-9]{64}$'::"text")),
    CONSTRAINT "publication_operations_destination_capability_content_has_check" CHECK (("destination_capability_content_hash" ~ '^[a-f0-9]{64}$'::"text")),
    CONSTRAINT "publication_operations_destination_capability_revision_check" CHECK (("destination_capability_revision" > 0)),
    CONSTRAINT "publication_operations_manifest_content_hash_check" CHECK (("manifest_content_hash" ~ '^[a-f0-9]{64}$'::"text")),
    CONSTRAINT "publication_operations_publication_intent_content_hash_check" CHECK (("publication_intent_content_hash" ~ '^[a-f0-9]{64}$'::"text")),
    CONSTRAINT "publication_operations_publication_intent_snapshot_check" CHECK (("jsonb_typeof"("publication_intent_snapshot") = 'object'::"text")),
    CONSTRAINT "publication_operations_release_decision_content_hash_check" CHECK (("release_decision_content_hash" ~ '^[a-f0-9]{64}$'::"text")),
    CONSTRAINT "publication_operations_release_decision_revision_check" CHECK (("release_decision_revision" > 0))
);


ALTER TABLE "tongs"."publication_operations" OWNER TO "postgres";


COMMENT ON TABLE "tongs"."publication_operations" IS 'Immutable exact manifest, decision, destination, capability, and publication-intent authority.';



CREATE TABLE IF NOT EXISTS "tongs"."publication_receipts" (
