    CONSTRAINT "publication_receipts_normalized_provider_evidence_check" CHECK (("jsonb_typeof"("normalized_provider_evidence") = 'object'::"text")),
    CONSTRAINT "publication_receipts_outcome_check" CHECK (("outcome" = ANY (ARRAY['succeeded'::"text", 'confirmed_failure'::"text", 'recoverable_failure'::"text", 'blocked'::"text", 'outcome_unknown'::"text"])))
);


ALTER TABLE "tongs"."publication_receipts" OWNER TO "postgres";


COMMENT ON TABLE "tongs"."publication_receipts" IS 'Immutable evidence of intended publication authority and one terminal observed attempt outcome.';



