    CONSTRAINT "publication_reconciliation_events_evidence_json_check" CHECK (("jsonb_typeof"("evidence_json") = 'object'::"text"))
);


ALTER TABLE "tongs"."publication_reconciliation_events" OWNER TO "postgres";


