    CONSTRAINT "publishing_destination_capability_revi_observation_source_check" CHECK (("observation_source" = ANY (ARRAY['provider_api'::"text", 'verified_configuration'::"text"]))),
    CONSTRAINT "publishing_destination_capability_revis_capabilities_json_check" CHECK (("jsonb_typeof"("capabilities_json") = 'object'::"text")),
    CONSTRAINT "publishing_destination_capability_revisions_check" CHECK (((("revision" = 1) AND ("previous_revision_id" IS NULL)) OR (("revision" > 1) AND ("previous_revision_id" IS NOT NULL)))),
    CONSTRAINT "publishing_destination_capability_revisions_content_hash_check" CHECK (("content_hash" ~ '^[a-f0-9]{64}$'::"text")),
