    CONSTRAINT "publishing_executable_destinations_display_label_check" CHECK (("length"("btrim"("display_label")) > 0)),
    CONSTRAINT "publishing_executable_destinations_observation_revision_check" CHECK (("observation_revision" > 0)),
    CONSTRAINT "publishing_executable_destinations_state_check" CHECK (("state" = ANY (ARRAY['active'::"text", 'unavailable'::"text", 'ownership_changed'::"text", 'removed'::"text"])))
);


ALTER TABLE "tongs"."publishing_executable_destinations" OWNER TO "postgres";


