CREATE TABLE IF NOT EXISTS "tongs"."publishing_oauth_connection_attempts" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "connection_id" "uuid" NOT NULL,
    "owner_user_id" "uuid" NOT NULL,
    "provider" "text" NOT NULL,
    "state_hash" "text" NOT NULL,
    "encrypted_pkce_verifier" "text" NOT NULL,
    "encryption_key_version" "text" NOT NULL,
    "ciphertext_version" "text" NOT NULL,
    "expected_redirect_uri" "text" NOT NULL,
    "expires_at" timestamp with time zone NOT NULL,
    "consumed_at" timestamp with time zone,
    "state" "text" DEFAULT 'pending'::"text" NOT NULL,
    "failure_code" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "publishing_oauth_connection_attem_encrypted_pkce_verifier_check" CHECK (("length"("btrim"("encrypted_pkce_verifier")) > 0)),
    CONSTRAINT "publishing_oauth_connection_attemp_encryption_key_version_check" CHECK (("length"("btrim"("encryption_key_version")) > 0)),
    CONSTRAINT "publishing_oauth_connection_attempt_expected_redirect_uri_check" CHECK (("expected_redirect_uri" ~ '^https://'::"text")),
    CONSTRAINT "publishing_oauth_connection_attempts_check" CHECK (("expires_at" > "created_at")),
    CONSTRAINT "publishing_oauth_connection_attempts_check1" CHECK (((("state" = 'pending'::"text") AND ("consumed_at" IS NULL)) OR (("state" <> 'pending'::"text") AND ("consumed_at" IS NOT NULL)))),
    CONSTRAINT "publishing_oauth_connection_attempts_ciphertext_version_check" CHECK (("length"("btrim"("ciphertext_version")) > 0)),
    CONSTRAINT "publishing_oauth_connection_attempts_provider_check" CHECK (("provider" = 'google'::"text")),
    CONSTRAINT "publishing_oauth_connection_attempts_state_check" CHECK (("state" = ANY (ARRAY['pending'::"text", 'consumed'::"text", 'completed'::"text", 'failed'::"text", 'expired'::"text"]))),
    CONSTRAINT "publishing_oauth_connection_attempts_state_hash_check" CHECK (("state_hash" ~ '^[a-f0-9]{64}$'::"text"))
);


ALTER TABLE "tongs"."publishing_oauth_connection_attempts" OWNER TO "postgres";


COMMENT ON TABLE "tongs"."publishing_oauth_connection_attempts" IS 'Server-only, single-use OAuth state and PKCE evidence. It grants no workspace or destination authority.';



CREATE TABLE IF NOT EXISTS "tongs"."publishing_provider_accounts" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "connection_id" "uuid" NOT NULL,
    "owner_user_id" "uuid" NOT NULL,
    "provider" "text" NOT NULL,
    "external_account_id" "text" NOT NULL,
