    CONSTRAINT "reference_review_operation_attempts_check1" CHECK ((("terminal_outcome" = 'succeeded'::"text") = ("canonical_receipt_json" IS NOT NULL))),
    CONSTRAINT "reference_review_operation_attempts_check2" CHECK ((("terminal_outcome" <> 'failed'::"text") OR (("failure_code" IS NOT NULL) AND ("failure_message" IS NOT NULL)))),
    CONSTRAINT "reference_review_operation_attempts_check3" CHECK ((("parent_attempt_id" IS NULL) OR ("parent_attempt_id" <> "attempt_id"))),
    CONSTRAINT "reference_review_operation_attempts_intent_kind_check" CHECK (("intent_kind" = ANY (ARRAY['use_source'::"text", 'save_edits'::"text", 'replace'::"text", 'approve'::"text", 'skip'::"text"]))),
