    CONSTRAINT "reference_review_operation_attempts_operation_fingerprint_check" CHECK (("operation_fingerprint" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "reference_review_operation_attempts_terminal_outcome_check" CHECK (("terminal_outcome" = ANY (ARRAY['succeeded'::"text", 'failed'::"text"])))
);


