    "policy_revision_id" "uuid" NOT NULL,
    "capability_term_id" "uuid" NOT NULL,
    "operation_identity" "text" NOT NULL,
    "user_id" "uuid",
    "workspace_id" "uuid",
    "request_fingerprint" "text" NOT NULL,
    "model_or_sku" "text" NOT NULL,
    "funding_class" "text" NOT NULL,
    "funding_handle_hash" "text" NOT NULL,
    "provider_mode" "text" NOT NULL,
    "caller_class" "text" NOT NULL,
    "customer_funding_ceiling_micros" bigint NOT NULL,
    "supplier_exposure_ceiling_micros" bigint NOT NULL,
    "supporting_exposure_ceiling_micros" bigint NOT NULL,
    "tail_exposure_ceiling_micros" bigint NOT NULL,
    "unreconciled_exposure_ceiling_micros" bigint NOT NULL,
    "retry_exposure_ceiling_micros" bigint NOT NULL,
    "lease_expires_at" timestamp with time zone NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "funding_environment" "text" DEFAULT 'legacy_unverified'::"text" NOT NULL,
    CONSTRAINT "restricted_beta_exposure_hol_customer_funding_ceiling_mic_check" CHECK (("customer_funding_ceiling_micros" >= 0)),
    CONSTRAINT "restricted_beta_exposure_hol_retry_exposure_ceiling_micro_check" CHECK (("retry_exposure_ceiling_micros" >= 0)),
    CONSTRAINT "restricted_beta_exposure_hol_supplier_exposure_ceiling_mi_check" CHECK (("supplier_exposure_ceiling_micros" >= 0)),
    CONSTRAINT "restricted_beta_exposure_hol_supporting_exposure_ceiling__check" CHECK (("supporting_exposure_ceiling_micros" >= 0)),
    CONSTRAINT "restricted_beta_exposure_hol_tail_exposure_ceiling_micros_check" CHECK (("tail_exposure_ceiling_micros" >= 0)),
    CONSTRAINT "restricted_beta_exposure_hol_unreconciled_exposure_ceilin_check" CHECK (("unreconciled_exposure_ceiling_micros" >= 0)),
    CONSTRAINT "restricted_beta_exposure_holds_caller_class_check" CHECK (("caller_class" = ANY (ARRAY['interactive'::"text", 'background'::"text", 'retry'::"text", 'recovery'::"text"]))),
    CONSTRAINT "restricted_beta_exposure_holds_funding_class_check" CHECK (("funding_class" = ANY (ARRAY['verified_customer_deposit'::"text", 'economically_backed_allowance'::"text", 'owner_operating_budget'::"text", 'test_customer'::"text", 'byo'::"text"]))),
    CONSTRAINT "restricted_beta_exposure_holds_funding_environment_check" CHECK (("funding_environment" = ANY (ARRAY['test'::"text", 'live'::"text", 'owner_internal'::"text", 'legacy_unverified'::"text"]))),
    CONSTRAINT "restricted_beta_exposure_holds_funding_handle_hash_check" CHECK (("funding_handle_hash" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "restricted_beta_exposure_holds_operation_identity_check" CHECK ((("length"("btrim"("operation_identity")) >= 8) AND ("length"("btrim"("operation_identity")) <= 300))),
    CONSTRAINT "restricted_beta_exposure_holds_provider_mode_check" CHECK (("provider_mode" = ANY (ARRAY['real'::"text", 'simulated'::"text", 'byo'::"text"]))),
    CONSTRAINT "restricted_beta_exposure_holds_request_fingerprint_check" CHECK (("request_fingerprint" ~ '^[0-9a-f]{64}$'::"text"))
);

ALTER TABLE ONLY "tongs"."restricted_beta_exposure_holds" FORCE ROW LEVEL SECURITY;


ALTER TABLE "tongs"."restricted_beta_exposure_holds" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "tongs"."restricted_beta_policy_capabilities" (
    "id" "uuid" NOT NULL,
    "policy_revision_id" "uuid" NOT NULL,
    "capability_code" "text" NOT NULL,
    "admission_mode" "text" NOT NULL,
    "cost_evidence_revision_id" "uuid",
    "maximum_attempts" smallint,
    "maximum_concurrency" integer,
    "per_operation_supplier_ceiling_micros" bigint,
    "per_operation_supporting_ceiling_micros" bigint,
    "per_operation_tail_ceiling_micros" bigint,
    "permitted_callers_json" "jsonb" DEFAULT '["interactive"]'::"jsonb" NOT NULL,
    "exact_model_or_sku" "text",
    "notes" "text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "restricted_beta_policy_capab_per_operation_supplier_ceili_check" CHECK (("per_operation_supplier_ceiling_micros" >= 0)),
    CONSTRAINT "restricted_beta_policy_capab_per_operation_supporting_cei_check" CHECK (("per_operation_supporting_ceiling_micros" >= 0)),
    CONSTRAINT "restricted_beta_policy_capab_per_operation_tail_ceiling_m_check" CHECK (("per_operation_tail_ceiling_micros" >= 0)),
    CONSTRAINT "restricted_beta_policy_capabilitie_permitted_callers_json_check" CHECK (("jsonb_typeof"("permitted_callers_json") = 'array'::"text")),
    CONSTRAINT "restricted_beta_policy_capabilities_admission_mode_check" CHECK (("admission_mode" = ANY (ARRAY['covered'::"text", 'block'::"text", 'existing_enforced'::"text"]))),
    CONSTRAINT "restricted_beta_policy_capabilities_check" CHECK ((("admission_mode" = 'block'::"text") OR (("cost_evidence_revision_id" IS NOT NULL) AND ("maximum_attempts" IS NOT NULL) AND ("maximum_concurrency" IS NOT NULL) AND ("per_operation_supplier_ceiling_micros" IS NOT NULL) AND ("per_operation_supporting_ceiling_micros" IS NOT NULL) AND ("per_operation_tail_ceiling_micros" IS NOT NULL) AND (NULLIF("btrim"("exact_model_or_sku"), ''::"text") IS NOT NULL)))),
    CONSTRAINT "restricted_beta_policy_capabilities_maximum_attempts_check" CHECK ((("maximum_attempts" >= 1) AND ("maximum_attempts" <= 4))),
    CONSTRAINT "restricted_beta_policy_capabilities_maximum_concurrency_check" CHECK (("maximum_concurrency" > 0))
);

ALTER TABLE ONLY "tongs"."restricted_beta_policy_capabilities" FORCE ROW LEVEL SECURITY;


ALTER TABLE "tongs"."restricted_beta_policy_capabilities" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "tongs"."restricted_beta_policy_revisions" (
    "id" "uuid" NOT NULL,
    "environment" "text" NOT NULL,
    "revision" integer NOT NULL,
    "lifecycle_state" "text" NOT NULL,
    "aggregate_forge_exposure_limit_micros" bigint,
    "reserved_headroom_micros" bigint,
    "maximum_concurrency" integer,
    "rolling_window_seconds" integer,
    "evidence_max_age_seconds" integer,
    "allocation_policy_revision_id" "uuid",
    "tail_policy_revision_id" "uuid",
    "reason" "text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "restricted_beta_policy_revis_aggregate_forge_exposure_lim_check" CHECK (("aggregate_forge_exposure_limit_micros" > 0)),
    CONSTRAINT "restricted_beta_policy_revisions_check" CHECK ((("lifecycle_state" = 'draft'::"text") OR (("aggregate_forge_exposure_limit_micros" IS NOT NULL) AND ("reserved_headroom_micros" IS NOT NULL) AND ("maximum_concurrency" IS NOT NULL) AND ("rolling_window_seconds" IS NOT NULL) AND ("evidence_max_age_seconds" IS NOT NULL)))),
    CONSTRAINT "restricted_beta_policy_revisions_environment_check" CHECK (("environment" = ANY (ARRAY['test'::"text", 'production'::"text"]))),
    CONSTRAINT "restricted_beta_policy_revisions_evidence_max_age_seconds_check" CHECK (("evidence_max_age_seconds" > 0)),
    CONSTRAINT "restricted_beta_policy_revisions_lifecycle_state_check" CHECK (("lifecycle_state" = ANY (ARRAY['draft'::"text", 'active'::"text", 'halt_new'::"text", 'retired'::"text"]))),
    CONSTRAINT "restricted_beta_policy_revisions_maximum_concurrency_check" CHECK (("maximum_concurrency" > 0)),
    CONSTRAINT "restricted_beta_policy_revisions_reserved_headroom_micros_check" CHECK (("reserved_headroom_micros" >= 0)),
    CONSTRAINT "restricted_beta_policy_revisions_revision_check" CHECK (("revision" > 0)),
    CONSTRAINT "restricted_beta_policy_revisions_rolling_window_seconds_check" CHECK (("rolling_window_seconds" > 0))
);

ALTER TABLE ONLY "tongs"."restricted_beta_policy_revisions" FORCE ROW LEVEL SECURITY;


ALTER TABLE "tongs"."restricted_beta_policy_revisions" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "tongs"."restricted_beta_tail_policy_revisions" (
    "id" "uuid" NOT NULL,
    "revision" integer NOT NULL,
    "lifecycle_state" "text" NOT NULL,
    "first_period_days" integer NOT NULL,
    "first_period_storage_ceiling_bytes" bigint NOT NULL,
    "after_first_period_policy" "text" NOT NULL,
    "warning_threshold_basis_points" integer,
    "halt_threshold_basis_points" integer,
    "deletion_on_threshold" boolean DEFAULT false NOT NULL,
    "notes" "text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "funding_treatment_json" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    CONSTRAINT "restricted_beta_tail_policy__first_period_storage_ceiling_check" CHECK (("first_period_storage_ceiling_bytes" > 0)),
    CONSTRAINT "restricted_beta_tail_policy__warning_threshold_basis_poin_check" CHECK ((("warning_threshold_basis_points" >= 1) AND ("warning_threshold_basis_points" <= 10000))),
    CONSTRAINT "restricted_beta_tail_policy_r_halt_threshold_basis_points_check" CHECK ((("halt_threshold_basis_points" >= 1) AND ("halt_threshold_basis_points" <= 10000))),
    CONSTRAINT "restricted_beta_tail_policy_rev_after_first_period_policy_check" CHECK (("after_first_period_policy" = ANY (ARRAY['plan_funded'::"text", 'recurring_metered'::"text", 'unfunded_block'::"text"]))),
    CONSTRAINT "restricted_beta_tail_policy_revisi_funding_treatment_json_check" CHECK (("jsonb_typeof"("funding_treatment_json") = 'object'::"text")),
    CONSTRAINT "restricted_beta_tail_policy_revisio_deletion_on_threshold_check" CHECK (("deletion_on_threshold" = false)),
    CONSTRAINT "restricted_beta_tail_policy_revisions_first_period_days_check" CHECK (("first_period_days" > 0)),
    CONSTRAINT "restricted_beta_tail_policy_revisions_lifecycle_state_check" CHECK (("lifecycle_state" = ANY (ARRAY['draft'::"text", 'active'::"text", 'retired'::"text"]))),
    CONSTRAINT "restricted_beta_tail_policy_revisions_revision_check" CHECK (("revision" > 0))
);

ALTER TABLE ONLY "tongs"."restricted_beta_tail_policy_revisions" FORCE ROW LEVEL SECURITY;


ALTER TABLE "tongs"."restricted_beta_tail_policy_revisions" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "tongs"."runway_customer_test_authorizations" (
    "id" "uuid" NOT NULL,
    "user_id" "uuid" NOT NULL,
    "workspace_id" "uuid" NOT NULL,
    "financial_environment" "text" NOT NULL,
    "route_code" "text" NOT NULL,
    "provider" "text" NOT NULL,
    "model" "text" NOT NULL,
    "generation_mode" "text" NOT NULL,
    "duration_seconds" integer NOT NULL,
    "ratio" "text" NOT NULL,
    "output_count" integer NOT NULL,
    "reference_image_count" integer NOT NULL,
    "maximum_provider_attempts" integer NOT NULL,
    "pricing_revision_id" "uuid" NOT NULL,
    "operation_id" "text" NOT NULL,
    "operation_fingerprint" "text" NOT NULL,
    "maximum_operation_count" integer NOT NULL,
    "maximum_customer_charge_micros" bigint NOT NULL,
    "maximum_wholesale_exposure_micros" bigint NOT NULL,
    "maximum_concurrency" integer NOT NULL,
    "valid_from" timestamp with time zone NOT NULL,
    "valid_until" timestamp with time zone NOT NULL,
    "status" "text" NOT NULL,
    "reason" "text" NOT NULL,
    "created_by" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "maximum_quote_count" integer DEFAULT 2 NOT NULL,
    CONSTRAINT "runway_customer_test_authori_maximum_customer_charge_micr_check" CHECK (("maximum_customer_charge_micros" = 800000)),
    CONSTRAINT "runway_customer_test_authori_maximum_wholesale_exposure_m_check" CHECK (("maximum_wholesale_exposure_micros" = 600000)),
    CONSTRAINT "runway_customer_test_authorizat_maximum_provider_attempts_check" CHECK (("maximum_provider_attempts" = 1)),
    CONSTRAINT "runway_customer_test_authorizatio_maximum_operation_count_check" CHECK (("maximum_operation_count" = 1)),
    CONSTRAINT "runway_customer_test_authorizations_check" CHECK (("valid_until" > "valid_from")),
    CONSTRAINT "runway_customer_test_authorizations_duration_seconds_check" CHECK (("duration_seconds" = 5)),
    CONSTRAINT "runway_customer_test_authorizations_financial_environment_check" CHECK (("financial_environment" = 'test'::"text")),
    CONSTRAINT "runway_customer_test_authorizations_generation_mode_check" CHECK (("generation_mode" = 'text_to_video'::"text")),
    CONSTRAINT "runway_customer_test_authorizations_maximum_concurrency_check" CHECK (("maximum_concurrency" = 1)),
    CONSTRAINT "runway_customer_test_authorizations_maximum_quote_count_check" CHECK (("maximum_quote_count" = 2)),
    CONSTRAINT "runway_customer_test_authorizations_model_check" CHECK (("model" = 'gen4.5'::"text")),
    CONSTRAINT "runway_customer_test_authorizations_operation_fingerprint_check" CHECK (("operation_fingerprint" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "runway_customer_test_authorizations_output_count_check" CHECK (("output_count" = 1)),
    CONSTRAINT "runway_customer_test_authorizations_provider_check" CHECK (("provider" = 'runway'::"text")),
    CONSTRAINT "runway_customer_test_authorizations_ratio_check" CHECK (("ratio" = '1280:720'::"text")),
    CONSTRAINT "runway_customer_test_authorizations_reason_check" CHECK ((NULLIF("btrim"("reason"), ''::"text") IS NOT NULL)),
    CONSTRAINT "runway_customer_test_authorizations_reference_image_count_check" CHECK (("reference_image_count" = 0)),
    CONSTRAINT "runway_customer_test_authorizations_route_code_check" CHECK (("route_code" = 'tongs_broll_v2'::"text")),
    CONSTRAINT "runway_customer_test_authorizations_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'closed'::"text"])))
);

ALTER TABLE ONLY "tongs"."runway_customer_test_authorizations" FORCE ROW LEVEL SECURITY;


ALTER TABLE "tongs"."runway_customer_test_authorizations" OWNER TO "postgres";


COMMENT ON TABLE "tongs"."runway_customer_test_authorizations" IS 'Immutable exact-operation normal-customer Test Runway authority. It grants no Owner, BYO, reference-image, Seedance, or Live scope.';



