CREATE TABLE IF NOT EXISTS "tongs"."runway_execution_reconciliation_receipts" (
    "operation_id" "text" NOT NULL,
    "reservation_id" "uuid" NOT NULL,
    "provider_task_id" "text" NOT NULL,
    "direct_provider_estimated_micros" bigint NOT NULL,
    "direct_provider_actual_micros" bigint,
    "supporting_cost_status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "supporting_actual_micros" bigint,
    "settlement_result_json" "jsonb",
    "evidence_json" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "provider_completed_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "reconciled_at" timestamp with time zone,
    CONSTRAINT "runway_execution_reconciliat_direct_provider_actual_micro_check" CHECK ((("direct_provider_actual_micros" IS NULL) OR ("direct_provider_actual_micros" >= 0))),
    CONSTRAINT "runway_execution_reconciliat_direct_provider_estimated_mi_check" CHECK (("direct_provider_estimated_micros" >= 0)),
    CONSTRAINT "runway_execution_reconciliation__supporting_actual_micros_check" CHECK ((("supporting_actual_micros" IS NULL) OR ("supporting_actual_micros" >= 0))),
    CONSTRAINT "runway_execution_reconciliation_re_supporting_cost_status_check" CHECK (("supporting_cost_status" = ANY (ARRAY['pending'::"text", 'finalized'::"text"]))),
    CONSTRAINT "runway_execution_reconciliation_receipts_check" CHECK (((("supporting_cost_status" = 'pending'::"text") AND ("direct_provider_actual_micros" IS NULL) AND ("supporting_actual_micros" IS NULL) AND ("settlement_result_json" IS NULL) AND ("reconciled_at" IS NULL)) OR (("supporting_cost_status" = 'finalized'::"text") AND ("direct_provider_actual_micros" IS NOT NULL) AND ("supporting_actual_micros" IS NOT NULL) AND ("settlement_result_json" IS NOT NULL) AND ("reconciled_at" IS NOT NULL)))),
    CONSTRAINT "runway_execution_reconciliation_receipts_evidence_json_check" CHECK (("jsonb_typeof"("evidence_json") = 'object'::"text")),
    CONSTRAINT "runway_execution_reconciliation_receipts_provider_task_id_check" CHECK ((NULLIF("btrim"("provider_task_id"), ''::"text") IS NOT NULL))
);


ALTER TABLE "tongs"."runway_execution_reconciliation_receipts" OWNER TO "postgres";


COMMENT ON TABLE "tongs"."runway_execution_reconciliation_receipts" IS 'Direct Runway expense receipt retained until supporting costs are finalized and the shared reservation settles.';



CREATE TABLE IF NOT EXISTS "tongs"."runway_funding_bindings" (
    "operation_id" "text" NOT NULL,
    "operation_fingerprint" "text" NOT NULL,
    "reservation_id" "uuid" NOT NULL,
    "user_id" "uuid" NOT NULL,
    "workspace_id" "uuid" NOT NULL,
    "model" "text" NOT NULL,
    "duration_seconds" integer NOT NULL,
    "ratio" "text" NOT NULL,
    "direct_provider_ceiling_micros" bigint NOT NULL,
    "supporting_cost_ceiling_micros" bigint NOT NULL,
    "total_cost_ceiling_micros" bigint NOT NULL,
    "pricing_revision_id" "uuid" NOT NULL,
    "cost_stack_json" "jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "runway_funding_bindings_check" CHECK (("total_cost_ceiling_micros" = ("direct_provider_ceiling_micros" + "supporting_cost_ceiling_micros"))),
    CONSTRAINT "runway_funding_bindings_check1" CHECK (("direct_provider_ceiling_micros" = (("duration_seconds")::bigint * 120000))),
    CONSTRAINT "runway_funding_bindings_cost_stack_json_check" CHECK (("jsonb_typeof"("cost_stack_json") = 'array'::"text")),
    CONSTRAINT "runway_funding_bindings_direct_provider_ceiling_micros_check" CHECK (("direct_provider_ceiling_micros" > 0)),
    CONSTRAINT "runway_funding_bindings_duration_seconds_check" CHECK ((("duration_seconds" >= 2) AND ("duration_seconds" <= 10))),
    CONSTRAINT "runway_funding_bindings_model_check" CHECK (("model" = 'gen4.5'::"text")),
    CONSTRAINT "runway_funding_bindings_operation_fingerprint_check" CHECK (("operation_fingerprint" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "runway_funding_bindings_operation_id_check" CHECK ((("length"("btrim"("operation_id")) >= 8) AND ("length"("btrim"("operation_id")) <= 300))),
    CONSTRAINT "runway_funding_bindings_ratio_check" CHECK (("ratio" = ANY (ARRAY['1280:720'::"text", '720:1280'::"text"]))),
    CONSTRAINT "runway_funding_bindings_supporting_cost_ceiling_micros_check" CHECK (("supporting_cost_ceiling_micros" >= 0)),
    CONSTRAINT "runway_funding_bindings_total_cost_ceiling_micros_check" CHECK (("total_cost_ceiling_micros" > 0))
);


ALTER TABLE "tongs"."runway_funding_bindings" OWNER TO "postgres";


COMMENT ON TABLE "tongs"."runway_funding_bindings" IS 'Immutable binding between a canonical Runway operation and its full-cost shared funding reservation.';



