CREATE TABLE IF NOT EXISTS "tongs"."source_operation_receipts" (
    "operation_id" "text" NOT NULL,
    "operation_fingerprint" "text" NOT NULL,
    "operation_type" "text" NOT NULL,
    "workspace_id" "uuid" NOT NULL,
    "workpiece_id" "uuid",
    "source_id" "uuid",
    "link_id" "uuid",
    "normalized_inputs_json" "jsonb" NOT NULL,
    "state" "text" NOT NULL,
    "result_source_revision_id" "uuid",
    "result_link_revision_id" "uuid",
    "failure_code" "text",
    "failure_message" "text",
    "receipt_json" "jsonb",
    "created_by" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "source_operation_receipts_check" CHECK ((("state" <> 'committed'::"text") OR ("receipt_json" IS NOT NULL))),
    CONSTRAINT "source_operation_receipts_check1" CHECK ((("state" <> 'failed'::"text") OR ("failure_code" IS NOT NULL))),
    CONSTRAINT "source_operation_receipts_normalized_inputs_json_check" CHECK (("jsonb_typeof"("normalized_inputs_json") = 'object'::"text")),
    CONSTRAINT "source_operation_receipts_operation_fingerprint_check" CHECK (("operation_fingerprint" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "source_operation_receipts_operation_id_check" CHECK (("operation_id" ~ '^forge:source:[a-zA-Z0-9._:-]{8,180}$'::"text")),
    CONSTRAINT "source_operation_receipts_operation_type_check" CHECK (("operation_type" = ANY (ARRAY['source_revision'::"text", 'workpiece_link'::"text", 'legacy_adoption'::"text"]))),
