CREATE TABLE IF NOT EXISTS "tongs"."source_revisions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "source_id" "uuid" NOT NULL,
    "workspace_id" "uuid" NOT NULL,
    "revision" bigint NOT NULL,
    "previous_revision_id" "uuid",
    "previous_revision" bigint,
    "source_type" "text" NOT NULL,
    "title" "text" NOT NULL,
    "author_creator" "text",
    "publisher" "text",
    "published_at" timestamp with time zone,
    "canonical_url" "text",
    "document_identity" "text",
    "canonical_asset_revision_id" "uuid",
    "canonical_asset_content_hash" "text",
    "metadata_json" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "provenance_json" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "metadata_contract_version" "text" NOT NULL,
    "provenance_contract_version" "text" NOT NULL,
    "content_hash" "text" NOT NULL,
    "immutable_revision_hash" "text" NOT NULL,
    "created_by" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "source_revisions_canonical_asset_content_hash_check" CHECK ((("canonical_asset_content_hash" IS NULL) OR ("canonical_asset_content_hash" ~ '^[0-9a-f]{64}$'::"text"))),
    CONSTRAINT "source_revisions_check" CHECK ((("previous_revision_id" IS NULL) = ("previous_revision" IS NULL))),
    CONSTRAINT "source_revisions_check1" CHECK ((("canonical_asset_revision_id" IS NULL) = ("canonical_asset_content_hash" IS NULL))),
    CONSTRAINT "source_revisions_check2" CHECK ((("canonical_url" IS NOT NULL) OR ("document_identity" IS NOT NULL) OR ("canonical_asset_revision_id" IS NOT NULL))),
    CONSTRAINT "source_revisions_check3" CHECK (((("revision" = 1) AND ("previous_revision_id" IS NULL)) OR (("revision" > 1) AND ("previous_revision" = ("revision" - 1))))),
    CONSTRAINT "source_revisions_content_hash_check" CHECK (("content_hash" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "source_revisions_immutable_revision_hash_check" CHECK (("immutable_revision_hash" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "source_revisions_metadata_contract_version_check" CHECK (("length"("btrim"("metadata_contract_version")) > 0)),
    CONSTRAINT "source_revisions_metadata_json_check" CHECK (("jsonb_typeof"("metadata_json") = 'object'::"text")),
    CONSTRAINT "source_revisions_provenance_contract_version_check" CHECK (("length"("btrim"("provenance_contract_version")) > 0)),
    CONSTRAINT "source_revisions_provenance_json_check" CHECK (("jsonb_typeof"("provenance_json") = 'object'::"text")),
    CONSTRAINT "source_revisions_revision_check" CHECK (("revision" > 0)),
    CONSTRAINT "source_revisions_source_type_check" CHECK (("length"("btrim"("source_type")) > 0)),
    CONSTRAINT "source_revisions_title_check" CHECK (("length"("btrim"("title")) > 0))
);


ALTER TABLE "tongs"."source_revisions" OWNER TO "postgres";


