    "storage_bucket" "text" NOT NULL,
    "storage_key" "text" NOT NULL,
    "profile_id" "uuid" NOT NULL,
    "profile_revision_id" "uuid",
    "profile_revision" integer,
    "profile_content_hash" "text",
    "expected_binding_revision" integer NOT NULL,
    "previous_binding_id" "uuid",
    "previous_binding_revision" integer,
    "resulting_binding_id" "uuid",
    "resulting_binding_revision" integer,
    "prior_candidate_set_id" "uuid",
    "prior_candidate_set_revision" integer,
    "prior_candidate_count" integer DEFAULT 0 NOT NULL,
    "prior_candidate_content_hash" "text",
    "prior_thumbnail_count" integer DEFAULT 0 NOT NULL,
    "prior_thumbnail_identity_hash" "text" NOT NULL,
    "resolved_style_source" "text",
    "renderer_verified_logo_revision_id" "uuid",
    "renderer_verified_storage_bucket" "text",
    "renderer_verified_storage_key" "text",
    "receipt_json" "jsonb",
    "created_by" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "thumbnail_brand_setup_failure_shape" CHECK (((("failed_stage" IS NULL) AND ("failure_code" IS NULL) AND ("failure_message" IS NULL)) OR (("failed_stage" IS NOT NULL) AND ("failure_code" IS NOT NULL) AND ("failure_message" IS NOT NULL)))),
    CONSTRAINT "thumbnail_brand_setup_operat_prior_thumbnail_identity_has_check" CHECK (("prior_thumbnail_identity_hash" ~ '^[a-f0-9]{64}$'::"text")),
    CONSTRAINT "thumbnail_brand_setup_operation_expected_binding_revision_check" CHECK (("expected_binding_revision" >= 0)),
    CONSTRAINT "thumbnail_brand_setup_operations_failed_stage_check" CHECK ((("failed_stage" IS NULL) OR ("failed_stage" = ANY (ARRAY['asset_ready'::"text", 'profile_committed'::"text", 'binding_committed'::"text", 'verified'::"text"])))),
    CONSTRAINT "thumbnail_brand_setup_operations_logo_content_hash_check" CHECK ((("logo_content_hash" IS NULL) OR ("logo_content_hash" ~ '^[a-f0-9]{64}$'::"text"))),
    CONSTRAINT "thumbnail_brand_setup_operations_logo_role_check" CHECK (("logo_role" = ANY (ARRAY['transparent_logo'::"text", 'primary_logo'::"text", 'watermark_logo'::"text"]))),
    CONSTRAINT "thumbnail_brand_setup_operations_operation_fingerprint_check" CHECK (("operation_fingerprint" ~ '^[a-f0-9]{64}$'::"text")),
    CONSTRAINT "thumbnail_brand_setup_operations_profile_content_hash_check" CHECK ((("profile_content_hash" IS NULL) OR ("profile_content_hash" ~ '^[a-f0-9]{64}$'::"text"))),
    CONSTRAINT "thumbnail_brand_setup_operations_receipt_json_check" CHECK ((("receipt_json" IS NULL) OR ("jsonb_typeof"("receipt_json") = 'object'::"text"))),
    CONSTRAINT "thumbnail_brand_setup_operations_requested_rules_json_check" CHECK (("jsonb_typeof"("requested_rules_json") = 'object'::"text")),
    CONSTRAINT "thumbnail_brand_setup_operations_resolved_style_source_check" CHECK ((("resolved_style_source" IS NULL) OR ("resolved_style_source" = 'brand_profile'::"text"))),
    CONSTRAINT "thumbnail_brand_setup_operations_state_check" CHECK (("state" = ANY (ARRAY['pending'::"text", 'asset_ready'::"text", 'profile_committed'::"text", 'binding_committed'::"text", 'verified'::"text"]))),
    CONSTRAINT "thumbnail_brand_setup_stage_shape" CHECK (((("state" = 'pending'::"text") AND ("logo_content_hash" IS NULL) AND ("profile_revision_id" IS NULL) AND ("resulting_binding_id" IS NULL) AND ("receipt_json" IS NULL)) OR (("state" = 'asset_ready'::"text") AND ("logo_content_hash" IS NOT NULL) AND ("profile_revision_id" IS NULL) AND ("resulting_binding_id" IS NULL) AND ("receipt_json" IS NULL)) OR (("state" = 'profile_committed'::"text") AND ("logo_content_hash" IS NOT NULL) AND ("profile_revision_id" IS NOT NULL) AND ("profile_revision" IS NOT NULL) AND ("profile_content_hash" IS NOT NULL) AND ("resulting_binding_id" IS NULL) AND ("receipt_json" IS NULL)) OR (("state" = 'binding_committed'::"text") AND ("logo_content_hash" IS NOT NULL) AND ("profile_revision_id" IS NOT NULL) AND ("resulting_binding_id" IS NOT NULL) AND ("resulting_binding_revision" IS NOT NULL) AND ("receipt_json" IS NULL)) OR (("state" = 'verified'::"text") AND ("logo_content_hash" IS NOT NULL) AND ("profile_revision_id" IS NOT NULL) AND ("resulting_binding_id" IS NOT NULL) AND ("resolved_style_source" = 'brand_profile'::"text") AND ("renderer_verified_logo_revision_id" IS NOT NULL) AND ("renderer_verified_storage_bucket" IS NOT NULL) AND ("renderer_verified_storage_key" IS NOT NULL) AND ("receipt_json" IS NOT NULL) AND ("failed_stage" IS NULL))))
);


