CREATE OR REPLACE VIEW "tongs"."v_scripts_effective" WITH ("security_invoker"='true') AS
 WITH "latest_override" AS (
         SELECT DISTINCT ON ("o"."script_id") "o"."script_id",
            "o"."to_state",
            "o"."overridden_at"
           FROM "tongs"."script_state_overrides" "o"
          ORDER BY "o"."script_id", "o"."overridden_at" DESC
        ), "has_kept_take" AS (
         SELECT "t"."script_id",
            true AS "has_kept"
           FROM "tongs"."recording_takes" "t"
          WHERE ("t"."status" = 'kept'::"tongs"."take_status")
          GROUP BY "t"."script_id"
        ), "is_scheduled" AS (
         SELECT "ss"."script_id",
            true AS "scheduled"
           FROM "tongs"."session_scripts" "ss"
          GROUP BY "ss"."script_id"
        )
 SELECT "s"."id",
    "s"."origin_spark_id",
    "s"."title_working",
    "s"."body_anvil",
    "s"."base_state",
    "s"."relevance",
    "s"."revision",
    "s"."owner_user_id",
    "s"."created_at",
    "s"."updated_at",
        CASE
            WHEN ("lo"."to_state" IS NOT NULL) THEN "lo"."to_state"
            WHEN ("kt"."has_kept" IS TRUE) THEN 'recorded'::"tongs"."script_effective_state"
            WHEN ("sch"."scheduled" IS TRUE) THEN 'scheduled'::"tongs"."script_effective_state"
            WHEN ("s"."base_state" = 'ready'::"tongs"."script_base_state") THEN 'ready'::"tongs"."script_effective_state"
            ELSE 'warming'::"tongs"."script_effective_state"
        END AS "effective_state",
    "lo"."overridden_at" AS "effective_state_overridden_at"
   FROM ((("tongs"."scripts" "s"
     LEFT JOIN "latest_override" "lo" ON (("lo"."script_id" = "s"."id")))
     LEFT JOIN "has_kept_take" "kt" ON (("kt"."script_id" = "s"."id")))
     LEFT JOIN "is_scheduled" "sch" ON (("sch"."script_id" = "s"."id")));


ALTER VIEW "tongs"."v_scripts_effective" OWNER TO "postgres";


CREATE OR REPLACE VIEW "tongs"."v_scripts_ready_for_schedule" WITH ("security_invoker"='true') AS
 SELECT "id",
    "origin_spark_id",
    "title_working",
    "body_anvil",
    "base_state",
    "relevance",
    "revision",
    "owner_user_id",
    "created_at",
    "updated_at",
    "effective_state",
    "effective_state_overridden_at"
   FROM "tongs"."v_scripts_effective"
  WHERE ("effective_state" = ANY (ARRAY['ready'::"tongs"."script_effective_state", 'warming'::"tongs"."script_effective_state"]));


ALTER VIEW "tongs"."v_scripts_ready_for_schedule" OWNER TO "postgres";


