CREATE TABLE IF NOT EXISTS "tongs"."visual_narrative_interpretation_results" (
    "id" "uuid" NOT NULL,
    "operation_id" "text" NOT NULL,
    "reservation_id" "uuid",
    "user_id" "uuid" NOT NULL,
    "workspace_id" "uuid" NOT NULL,
    "workpiece_id" "uuid" NOT NULL,
    "request_fingerprint" "text" NOT NULL,
    "provider_body_sha256" "text" NOT NULL,
    "provider_request_id" "text",
    "model" "text" NOT NULL,
    "input_units" bigint NOT NULL,
    "output_units" bigint NOT NULL,
    "visual_brief_json" "jsonb" NOT NULL,
    "contracts_json" "jsonb" NOT NULL,
    "image_map_revision_id" "uuid" NOT NULL,
    "image_map_revision" bigint NOT NULL,
    "script_approval_id" "uuid" NOT NULL,
    "script_approval_revision" bigint NOT NULL,
    "creator_direction" "text" NOT NULL,
    "visual_style" "text",
    "synthesized_prompt" "text" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "owner_cost_attempt_id" "uuid",
    "customer_operation_id" "text" GENERATED ALWAYS AS (
CASE
    WHEN ("reservation_id" IS NOT NULL) THEN "operation_id"
    ELSE NULL::"text"
END) STORED,
    CONSTRAINT "visual_narrative_interpretation__script_approval_revision_check" CHECK (("script_approval_revision" > 0)),
    CONSTRAINT "visual_narrative_interpretation_resu_provider_body_sha256_check" CHECK (("provider_body_sha256" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "visual_narrative_interpretation_resul_request_fingerprint_check" CHECK (("request_fingerprint" ~ '^[0-9a-f]{64}$'::"text")),
    CONSTRAINT "visual_narrative_interpretation_result_image_map_revision_check" CHECK (("image_map_revision" > 0)),
    CONSTRAINT "visual_narrative_interpretation_result_synthesized_prompt_check" CHECK (("length"("btrim"("synthesized_prompt")) > 0)),
    CONSTRAINT "visual_narrative_interpretation_results_contracts_json_check" CHECK (("jsonb_typeof"("contracts_json") = 'object'::"text")),
    CONSTRAINT "visual_narrative_interpretation_results_creator_direction_check" CHECK (("length"("btrim"("creator_direction")) > 0)),
    CONSTRAINT "visual_narrative_interpretation_results_input_units_check" CHECK ((("input_units" >= 0) AND ("input_units" <= 4096))),
    CONSTRAINT "visual_narrative_interpretation_results_model_check" CHECK (("model" = 'gpt-5.6-luna'::"text")),
    CONSTRAINT "visual_narrative_interpretation_results_output_units_check" CHECK ((("output_units" >= 0) AND ("output_units" <= 1024))),
    CONSTRAINT "visual_narrative_interpretation_results_visual_brief_json_check" CHECK (("jsonb_typeof"("visual_brief_json") = 'object'::"text")),
    CONSTRAINT "visual_narrative_results_execution_authority_check" CHECK (("num_nonnulls"("reservation_id", "owner_cost_attempt_id") = 1))
);

